  ('kjemi-2', 'vg3', 'Kjemi 2', 'KJE01-02', 'https://www.udir.no/lk20/kje01-02/kompetansemaal-og-vurdering/kv533', '[{"nr":1,"tekst":"forstå og bruke kjemisk terminologi og fagspråk i faglig kommunikasjon"},{"nr":2,"tekst":"planlegge og gjennomføre forsøk, drøfte metode og tiltak for å redusere risiko og vurdere usikkerhet og feilkilder i egne og andres forsøk"},{"nr":3,"tekst":"gjøre rede for hvordan naturvitenskapelige modeller og teorier utvikles, og reflektere over hvordan samarbeid bidrar til kunnskapsutvikling i kjemi"},{"nr":4,"tekst":"utforske redoksreaksjoner og bruke beregninger til å vurdere sammenhenger mellom masse, ladning, spenning og energi i elektrokjemiske reaksjoner"},{"nr":5,"tekst":"utforske likevekter og bruke massevirkningsloven til å gjøre beregninger og forklare observasjoner"},{"nr":6,"tekst":"gjøre rede for entropibegrepet og bruke entropi og entalpi til å vurdere spontanitet og endringer i likevektsystemer"},{"nr":7,"tekst":"utforske og beregne pH i vannløsninger og drøfte betydningen av buffere for regulering av pH i naturlige og industrielle prosesser"},{"nr":8,"tekst":"utforske og gjøre beregninger av løseligheten til stoffer og gjøre vurderinger av løselighet i biologiske og industrielle prosesser"},{"nr":9,"tekst":"utforske katalyserte reaksjoner og gjøre rede for betydningen av katalysatorer i biologiske og industrielle prosesser"},{"nr":10,"tekst":"gjøre rede for reaksjonstypene addisjon, eliminasjon, substitusjon, hydrolyse og kondensasjon og bruke elektrostatiske krefter til å forklare noen enkle reaksjonsmekanismer"},{"nr":11,"tekst":"gjennomføre synteser og gjøre rede for faktorer som påvirker utbytte og renhet i synteser"},{"nr":12,"tekst":"gjøre rede for prinsipper for kromatografi og bruke kromatografi for å separere og analysere organiske stoffblandinger"},{"nr":13,"tekst":"beskrive oppbygningen til noen biologiske makromolekyler og vurdere hvordan ytre faktorer kan påvirke molekylenes struktur og egenskaper"},{"nr":14,"tekst":"gi eksempler på produksjon, gjenvinning, deponering og nedbryting av noen metaller og noen typer plast, og drøfte tiltak som er i samsvar med prinsipper for grønn kjemi"},{"nr":15,"tekst":"utforske en teoretisk eller praktisk problemstilling, og drøfte og presentere funn"}]'::jsonb, 4),
  ('fysikk-2', 'vg3', 'Fysikk 2', 'FYS01-02', 'https://www.udir.no/lk20/fys01-02/kompetansemaal-og-vurdering/kv467', '[{"nr":1,"tekst":"planlegge, gjennomføre og videreutvikle forsøk, og analysere data og beregne usikkerhet for å vurdere gyldigheten av funn"},{"nr":2,"tekst":"presentere sentrale elementer i ny viten i fysikk som er et resultat av internasjonalt forskningssamarbeid, og vurdere hvordan slikt samarbeid bidrar i kunnskapsutviklingen"},{"nr":3,"tekst":"bruke numeriske metoder og programmering til å utforske og modellere fysiske fenomener"},{"nr":4,"tekst":"utforske, beskrive og modellere bevegelse i to dimensjoner"},{"nr":5,"tekst":"gjøre rede for hvordan krefter kan forårsake krumlinjet bevegelse, og bruke dette i beregninger"},{"nr":6,"tekst":"beskrive elektriske og magnetiske felt og gjøre rede for krefter på objekter med masse og ladning i slike felt"},{"nr":7,"tekst":"gjøre rede for energibevaring i gravitasjonelle sentralfelt og bruke dette til å beregne bevegelse i slike felt"},{"nr":8,"tekst":"utforske ulike måter å indusere elektromotorisk spenning og strøm, og analysere resultatene"},{"nr":9,"tekst":"forklare hvordan induksjon kan inngå i bærekraftig energiproduksjon og vurdere anvendelser av induksjon i dagliglivet"},{"nr":10,"tekst":"beskrive de sentrale prinsippene i den spesielle og generelle relativitetsteorien og gjøre rede for hvordan disse har endret vår forståelse av tid, rom og felt"},{"nr":11,"tekst":"gjøre rede for hva som skiller kvanteobjekter fra klassiske objekter, og beskrive situasjoner der kvanteeffekter observeres"},{"nr":12,"tekst":"utforske og analysere en selvvalgt teoretisk eller praktisk problemstilling i fysikk, og presentere viktige prinsipper, sammenhenger og konsekvenser"}]'::jsonb, 5),
  ('biologi-2', 'vg3', 'Biologi 2', 'BIO01-02', 'https://www.udir.no/lk20/bio01-02/kompetansemaal-og-vurdering/kv539', '[{"nr":1,"tekst":"utforske ei biologisk problemstilling, analysere innsamla data, argumentere for val av metodar og drøfte resultat og funn"},{"nr":2,"tekst":"utforske faktorar som regulerer vekst i og storleiken på populasjonar, og drøfte interessekonfliktar rundt forvaltning av populasjonar"},{"nr":3,"tekst":"utforske og dokumentere artsmangfald gjennom feltarbeid, drøfte resultat og funn og vurdere korleis artane er tilpassa økosystemet dei lever i"},{"nr":4,"tekst":"gjere greie for energistraum og sentrale stoffkrinsløp"},{"nr":5,"tekst":"drøfte korleis menneskeleg aktivitet påverkar krinsløpa, og utforske tiltak for å vareta dei"},{"nr":6,"tekst":"utforske korleis enzym fungerer, og gjere greie for den rolla enzym speler i metabolske prosessar"},{"nr":7,"tekst":"samanlikne korleis energi blir omdanna gjennom fotosyntesen og celleandinga, og vurdere kva påverknad ulike faktorar har på energiomsetning"},{"nr":8,"tekst":"gjere greie for genetisk kode og regulering av genuttrykk, og beskrive korleis genteknologi kan brukast for å styre og endre genuttrykk"},{"nr":9,"tekst":"gjere greie for korleis eigenskapar blir arva, og utforske årsaker til genotypisk og fenotypisk variasjon i populasjonar"},{"nr":10,"tekst":"utforske korleis evolusjonære prosessar påverkar genlageret til populasjonar, og samanlikne ulike mekanismar for artsdanning"},{"nr":11,"tekst":"vurdere kommersiell bruk av genteknologi i medisin og matproduksjon, og drøfte etiske problemstillingar ved bruk av slik teknologi"}]'::jsonb, 6),
  ('geofag-2', 'vg3', 'Geofag 2', 'GFG01-03', 'https://www.udir.no/lk20/gfg01-03/kompetansemaal-og-vurdering/kv973', '[{"nr":1,"tekst":"gjøre rede for vekselvirkninger mellom de ulike jordsystemene, og hvordan disse kan påvirke havet, atmosfæren og kryosfæren"},{"nr":2,"tekst":"gjøre rede for strålingsbalanse, strålingsfordeling og strålingspådriv og bruke disse til å forstå den globale sirkulasjonen i atmosfæren"},{"nr":3,"tekst":"gjøre rede for konsekvensene av jordens rotasjon, tetthetsforskjeller og trykkforskjeller og hvordan de påvirker havet og atmosfæren"},{"nr":4,"tekst":"gjøre rede for hvordan ulike værsystemer oppstår og utvikler seg på global, regional og lokal skala, og tolke ulike værkart og værutvikling"},{"nr":5,"tekst":"gjøre rede for hvordan numeriske modeller i geofag bygges opp og videreutvikles, og beskrive hvordan modellene brukes innenfor værvarsling, havmodellering og klimaforskning"},{"nr":6,"tekst":"gjøre rede for klimasystemet på ulike skalaer i tid og rom og vurdere antropogen klimapåvirkning"},{"nr":7,"tekst":"gjøre rede for forskning på forhistorisk klima, og hvordan det bidrar til å lage prognoser for framtidens klima"},{"nr":8,"tekst":"drøfte konsekvenser av klimaendringer for enkeltmennesker, samfunn og økosystem, og vurdere bærekraftige løsninger for hvordan enkeltmennesker og samfunn kan redusere og tilpasse seg klimaendringer i nåtid og framtid"},{"nr":9,"tekst":"drøfte hvordan energiressurser fra hav og atmosfære kan utnyttes på en bærekraftig måte, både nasjonalt og globalt"},{"nr":10,"tekst":"gjennomføre geofaglig feltarbeid knyttet til havet, atmosfæren eller kryosfæren, bearbeide og tolke de innsamlede dataene og presentere resultatene"},{"nr":11,"tekst":"vurdere risiko ved naturfarer som følge av fenomener i atmosfæren, havet og kryosfæren og drøfte hvordan klimaendringer kan påvirke disse"}]'::jsonb, 7),
  ('matematikk-r2', 'vg3', 'Matematikk R2', 'MAT03-02', 'https://www.udir.no/lk20/mat03-02/kompetansemaal-og-vurdering/kv294', '[{"nr":1,"tekst":"utforske egenskaper ved ulike rekker og gjøre rede for praktiske anvendelser av egenskaper ved rekker"},{"nr":2,"tekst":"utforske rekursive sammenhenger ved å bruke programmering og presentere egne framgangsmåter"},{"nr":3,"tekst":"gjøre rede for integral som en grenseverdi av en følge av summer, og tolke betydningen av denne grenseverdien i ulike situasjoner"},{"nr":4,"tekst":"gjøre rede for analysens fundamentalteorem og gjøre rede for konsekvenser av teoremet"},{"nr":5,"tekst":"utvikle algoritmer for å beregne integraler numerisk, og bruke programmering til å utføre algoritmene"},{"nr":6,"tekst":"gi eksempler på ulike situasjoner som kan modelleres ved å bruke ulike matematiske funksjoner, og modellere og analysere slike situasjoner ved å bruke reelle datasett"},{"nr":7,"tekst":"anvende derivasjon og integrasjon til å analysere og tolke egne matematiske modeller av reelle datasett"},{"nr":8,"tekst":"analysere og tolke ulike funksjoner ved å bruke derivasjon og integrasjon, og anvende integrasjon til å beregne ulike mål av omdreiningslegemer"},{"nr":9,"tekst":"anvende parameterframstillinger til kurver og bruke parameterframstillinger til å løse naturvitenskapelige problemer inkludert problemer knyttet til fart og akselerasjon"},{"nr":10,"tekst":"utforske og forstå regneregler for vektorer i rommet, og bruke vektorer til å beregne ulike størrelser i rommet"},{"nr":11,"tekst":"utforske egenskaper ved radianer og trigonometriske funksjoner og identiteter og anvende disse egenskapene til å løse praktiske problemer"},{"nr":12,"tekst":"analysere og forstå matematiske bevis, forklare de bærende ideene i et matematisk bevis og utvikle egne bevis"}]'::jsonb, 8),
  ('matematikk-s2', 'vg3', 'Matematikk S2', 'MAT04-02', 'https://www.udir.no/lk20/mat04-02/kompetansemaal-og-vurdering/kv296', '[{"nr":1,"tekst":"utforske egenskaper ved ulike rekker og gjøre rede for praktiske anvendelser av egenskaper ved rekker"},{"nr":2,"tekst":"utforske rekursive sammenhenger ved å bruke programmering og presentere egne framgangsmåter"},{"nr":3,"tekst":"forstå definisjonen av det bestemte integralet og anvende integralet til å analysere funksjoner"},{"nr":4,"tekst":"gjøre rede for analysens fundamentalteorem og gjøre rede for konsekvenser av teoremet"},{"nr":5,"tekst":"analysere og tolke ulike funksjoner ved å bruke derivasjon og integrasjon"},{"nr":6,"tekst":"modellere og analysere eksponentiell og logistisk vekst i reelle datasett"},{"nr":7,"tekst":"forstå begrepene forventningsverdi, varians og standardavvik, og bruke disse størrelsene til å tolke stokastiske variabler"},{"nr":8,"tekst":"simulere utfall i, utforske og tolke ulike statistiske fordelinger, og gi eksempler på reelle anvendelser av disse fordelingene"},{"nr":9,"tekst":"finne grensekostnader og grenseinntekter i økonomiske modeller, og gjøre rede for betydningen av disse størrelsene"},{"nr":10,"tekst":"argumentere for sentralgrensesetningen og utforske og tolke praktiske situasjoner ved hjelp av normalfordelingen"},{"nr":11,"tekst":"gjennomføre hypotesetesting i reelle datasett og tolke resultatet"}]'::jsonb, 9),
  ('rettslare-2', 'vg3', 'Rettslære 2', 'RTL01-05', 'https://www.udir.no/lk20/rtl01-05/kompetansemaal-og-vurdering/kv890', '[{"nr":1,"tekst":"utforske og drøfte skiljet mellom rett og rettferd i ein rettsstat"},{"nr":2,"tekst":"utforske og bruke ulike rettskjelder for å løyse juridiske problemstillingar"},{"nr":3,"tekst":"identifisere partar, krav, rettsleg grunnlag og juridisk problemstilling, og gjennomføre juridisk drøfting for å komme fram til ein konklusjon"},{"nr":4,"tekst":"utforske og drøfte dagsaktuelle juridiske problemstillingar eller rettsspørsmål"},{"nr":5,"tekst":"utforske demokratiet si stilling i Noreg og Sápmi/Sábme/Sáepmie, og gjere greie for grunnleggjande menneskerettar som varetek dette"},{"nr":6,"tekst":"utforske rettsforholdet mellom individ og offentleg forvaltning og bruke sentrale reglar om saksbehandling"},{"nr":7,"tekst":"bruke sentrale reglar om personvern og utforske juridiske problemstillingar som oppstår i samband med bruk av informasjons- og kommunikasjonsteknologi"},{"nr":8,"tekst":"bruke grunnleggjande vilkår til å vurdere spørsmål om erstatning"},{"nr":9,"tekst":"utforske reaksjonssystemet og bruke straffleggingsvilkåra til å vurdere straff etter rettsreglar om seksuallovbrot, valdslovbrot og vinningslovbrot"},{"nr":10,"tekst":"utforske og drøfte dagsaktuelle juridiske rettsspørsmål som gjeld varetaking av miljøet"}]'::jsonb, 10),
  ('psykologi-2', 'vg3', 'Psykologi 2', 'PSY01-04', 'https://www.udir.no/lk20/psy01-04/kompetansemaal-og-vurdering/kv884', '[{"nr":1,"tekst":"finne og vurdere informasjon for å analysere faglige spørsmål og problemstillinger"},{"nr":2,"tekst":"planlegge, beskrive og gjennomføre en undersøkelse av en psykologisk problemstilling, analysere og drøfte resultater"},{"nr":3,"tekst":"sammenligne og anvende ulike vitenskapelige tilnærminger, teorier, perspektiver og metoder, og vurdere forskjellige forklaringer på psykologiske problemstillinger"},{"nr":4,"tekst":"drøfte hvordan sosial påvirkning og interaksjon i grupper kan påvirke holdninger, atferd og identitet"},{"nr":5,"tekst":"drøfte årsaker til utenforskap og reflektere over konsekvenser for individet"},{"nr":6,"tekst":"gjøre rede for faktorer som påvirker utviklingen av sosial kompetanse, og reflektere over betydningen av sosial kompetanse"},{"nr":7,"tekst":"gjøre rede for hvordan mellommenneskelige konflikter kan oppstå og utvikle seg, og drøfte hvordan verbal og ikke-verbal kommunikasjon kan bidra til både å utvikle og å løse konflikter"},{"nr":8,"tekst":"drøfte hvordan ulike former for kommunikasjon påvirker sosial samhandling og livskvalitet"},{"nr":9,"tekst":"reflektere over hvordan synet på psykisk helse og behandling av psykiske lidelser har endret seg og er i endring"},{"nr":10,"tekst":"drøfte begrepene normalitet og psykisk helse og reflektere over hva som skiller psykiske vansker og psykiske lidelser"},{"nr":11,"tekst":"utforske samspillet mellom biologiske, psykologiske og sosiale faktorer for utvikling av god psykisk helse, og drøfte forebygging og behandling av psykiske vansker og lidelser i lys av dette"}]'::jsonb, 11),
  ('sosialkunnskap', 'vg3', 'Sosialkunnskap', 'POS02-02', 'https://www.udir.no/lk20/pos02-02/kompetansemaal-og-vurdering/kv892', '[{"nr":1,"tekst":"finne og vurdere informasjon for å analysere faglige spørsmål og problemstillinger"},{"nr":2,"tekst":"vurdere ulike samfunnsvitenskapelige metoder og teorier og bruke disse til å utforske egne problemstillinger og gjennomføre undersøkelser"},{"nr":3,"tekst":"gjøre rede for ulike institusjoner, politisk styring, prinsipper og verdier i velferdsstaten og drøfte utfordringer ved velferdsstatens framtid og bærekraft"},{"nr":4,"tekst":"drøfte årsaker til sosial ulikhet, marginalisering og utenforskap og vurdere konsekvenser for individ og samfunn"},{"nr":5,"tekst":"gjøre rede for ulike perspektiver på sosialisering og drøfte hvordan sosialiseringen har endret seg over tid"},{"nr":6,"tekst":"utforske ulike perspektiver på kjønn og identitet og reflektere over holdninger til egen og andres identitet"},{"nr":7,"tekst":"utforske sammenhenger mellom velferdsforskjeller og sosiale problemer og drøfte konsekvenser for individ og samfunn"},{"nr":8,"tekst":"gjøre rede for ulike typer sosiale problemer og vurdere forebyggende tiltak"},{"nr":9,"tekst":"utforske inkludering på ulike nivåer i samfunnet og vurdere tiltak som kan bidra til inkludering i arbeidslivet og velferdssamfunnet"},{"nr":10,"tekst":"vurdere hvordan menneskerettighetene har påvirket den norske velferdsstaten, og drøfte hvordan menneskerettighetene ivaretas i Norge"},{"nr":11,"tekst":"gjøre rede for sentrale behov i barne- og ungdomsårene og vurdere sammenhengen mellom behovsdekning, velferd og livsmestring"},{"nr":12,"tekst":"gjøre rede for ulike former for vold og trakassering og drøfte konsekvenser av vold og trakassering på individ- og samfunnsnivå"},{"nr":13,"tekst":"vurdere hvordan ulike kriser kan håndteres på individ- og samfunnsnivå"}]'::jsonb, 12),
  ('markedsforing-og-ledelse-2', 'vg3', 'Markedsføring og ledelse 2', 'MFL01-04', 'https://www.udir.no/lk20/mfl01-04/kompetansemaal-og-vurdering/kv888', '[{"nr":1,"tekst":"velge og bruke kilder, markedsførings- og ledelsesteorier og modeller i arbeid med faglige spørsmål, emner og dagsaktuelle problemstillinger"},{"nr":2,"tekst":"utvikle og vurdere visjoner, forretningsideer og overordnede mål"},{"nr":3,"tekst":"drøfte og begrunne ulike faktorer som påvirker målgruppevalg"},{"nr":4,"tekst":"bruke situasjonsanalyse og bransjeanalyse og vurdere markedsstrategiske beslutninger"},{"nr":5,"tekst":"utvikle merkevarestrategier og vurdere posisjonering i merkevarebygging"},{"nr":6,"tekst":"utvikle distribusjonsstrategier og vurdere påvirkning av makt og avhengighet i en verdikjede"},{"nr":7,"tekst":"drøfte ulike faktorer som påvirker prissetting, og utvikle prisstrategier"},{"nr":8,"tekst":"vurdere og utvikle kommunikasjonsstrategier, utforske dagsaktuelle kommunikasjonskanaler og planlegge mediemiks"},{"nr":9,"tekst":"vurdere lederens rolle og funksjon i utviklingen av markedsstrategi og i internmarkedsføring"},{"nr":10,"tekst":"utvikle og begrunne helhetlige markedsstrategier og drøfte etisk bruk av konkurransemidler"},{"nr":11,"tekst":"vurdere hvordan virksomheter kan utvikle helhetlig markedsmiks, og utforske ulike metoder for å måle effekten av markedsføringstiltakene"},{"nr":12,"tekst":"drøfte virksomheters samfunnsansvar ut fra et etisk, lovmessig og forretningsmessig perspektiv, og vurdere dette opp mot virksomhetens omdømme"},{"nr":13,"tekst":"vurdere bærekraftige valg for virksomheter med tanke på sosiale, økonomiske og miljømessige forhold"}]'::jsonb, 13)
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-8:lesestrategier', 'norsk-8', 'lesestrategier', 'Lesestrategier', 'Hvordan du leser før, under og etter lesingen, og hvilke strategier som passer til skjønnlitteratur og sakprosa.', array[3, 1]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-8:lesestrategier', '## Hvorfor lesestrategier?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-8:lesestrategier', 'Lesestrategi', 'En bevisst måte å lese på for å forstå og huske bedre.', 0),
  ('norsk-8:lesestrategier', 'Formål med lesingen', 'Hvorfor du leser: for å oppleve, lære, finne informasjon eller vurdere.', 1),
  ('norsk-8:lesestrategier', 'Skumlese', 'Lese raskt over tittel, mellomtitler, bilder og uthevet tekst for å få overblikk.', 2),
  ('norsk-8:lesestrategier', 'Søkelese', 'Lete raskt etter en bestemt opplysning, for eksempel et årstall eller navn.', 3),
  ('norsk-8:lesestrategier', 'Nærlese', 'Lese nøye og grundig, ofte flere ganger, for å forstå detaljer.', 4),
  ('norsk-8:lesestrategier', 'Forkunnskaper', 'Det du vet fra før om et tema. Å aktivere dem gjør ny kunnskap lettere å forstå.', 5),
  ('norsk-8:lesestrategier', 'Førlesing', 'Det du gjør før du leser: skumleser, tenker over hva du vet og stiller spørsmål.', 6),
  ('norsk-8:lesestrategier', 'Oppsummere', 'Gjengi hovedinnholdet kort med egne ord.', 7),
  ('norsk-8:lesestrategier', 'Nøkkelord', 'De viktigste ordene i en tekst, som bærer hovedinnholdet.', 8),
  ('norsk-8:lesestrategier', 'Tankekart', 'En tegning som viser et tema i midten og hvordan underpunktene henger sammen.', 9),
  ('norsk-8:lesestrategier', 'Skjønnlitteratur', 'Oppdiktede tekster, som noveller, romaner og dikt.', 10),
  ('norsk-8:lesestrategier', 'Sakprosa', 'Tekster om virkeligheten, som fagtekster, artikler og nyheter.', 11),
  ('norsk-8:lesestrategier', 'Ingress', 'Innledningen i en artikkel, ofte i fet skrift, som oppsummerer det viktigste.', 12),
  ('norsk-8:lesestrategier', 'Sjekke forståelsen', 'Stoppe opp og spørre seg selv om man kan forklare det man nettopp har lest.', 13),
  ('norsk-8:lesestrategier', 'Reflektere over lesing', 'Tenke over hvilke strategier som fungerte, og hva du kan gjøre annerledes.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-8:lesestrategier', 'q01', 'flervalg', 'Hva gjør du når du skumleser?', array['Leser hvert ord nøye', 'Ser raskt over titler, bilder og uthevet tekst', 'Leser teksten høyt', 'Skriver av teksten']::text[], 1, 'Skumlesing gir et raskt overblikk før du leser grundig.', true, true, 0),
  ('norsk-8:lesestrategier', 'q02', 'flervalg', 'Du skal finne hvilket år en oppfinnelse ble gjort. Hvilken strategi passer best?', array['Søkelesing', 'Nærlesing', 'Tankekart', 'Høytlesing']::text[], 0, 'Når du leter etter en bestemt opplysning, søker du raskt gjennom teksten etter den.', true, true, 1),
  ('norsk-8:lesestrategier', 'q03', 'flervalg', 'Hvorfor er det lurt å aktivere forkunnskaper før du leser?', array['Fordi du slipper å lese hele teksten', 'Fordi det gjør teksten kortere', 'Fordi ny kunnskap blir lettere å forstå og huske når den kobles til det du kan', 'Fordi læreren krever det']::text[], 2, 'Hjernen husker bedre når ny informasjon kan knyttes til noe den allerede kjenner.', true, true, 2),
  ('norsk-8:lesestrategier', 'q04', 'flervalg', 'Hvilken tekst er sakprosa?', array['En novelle', 'Et eventyr', 'Et dikt', 'En fagartikkel om klimaendringer']::text[], 3, 'Sakprosa handler om virkeligheten. Novelle, eventyr og dikt er skjønnlitteratur.', true, true, 3),
  ('norsk-8:lesestrategier', 'q05', 'flervalg', 'Hva bør du understreke når du leser en fagtekst?', array['Hele setninger', 'Nøkkelord', 'Alle ord du kjenner', 'Ingenting']::text[], 1, 'Nøkkelord bærer hovedinnholdet. Understreker du alt, blir det ingen hjelp når du skal repetere.', true, true, 4),
  ('norsk-8:lesestrategier', 'q06', 'flervalg', 'Du har lest en side, men husker ingenting. Hva er et godt tiltak?', array['Lese videre raskere', 'Stoppe og oppsummere hvert avsnitt med egne ord', 'Hoppe over kapittelet', 'Lese siden baklengs']::text[], 1, 'Å oppsummere avsnitt for avsnitt tvinger deg til å bearbeide innholdet, og du merker med en gang hva du ikke har forstått.', true, true, 5),
  ('norsk-8:lesestrategier', 'q07', 'flervalg', 'Hva er en ingress?', array['Siste avsnitt i en novelle', 'En bildetekst', 'Innledningen i en artikkel som oppsummerer det viktigste', 'En fotnote']::text[], 2, 'Ingressen står etter overskriften, ofte i fet skrift, og gir et sammendrag av saken.', true, true, 6),
  ('norsk-8:lesestrategier', 'q08', 'flervalg', 'Hvilket spørsmål passer best når du leser skjønnlitteratur?', array['Hvorfor handler personen slik?', 'Hvem finansierte undersøkelsen?', 'Hvilket årstall står i tabellen?', 'Hva er kilden til tallene?']::text[], 0, 'I skjønnlitteratur er det ofte personenes motiver og tekstens tema som er interessant å tolke.', true, false, 7),
  ('norsk-8:lesestrategier', 'q09', 'flervalg', 'Hva er en typisk strategi etter lesingen?', array['Skumlese', 'Aktivere forkunnskaper', 'Se på bildene først', 'Lage et tankekart over innholdet']::text[], 3, 'Etter lesingen bearbeider du stoffet, for eksempel med tankekart eller sammendrag.', true, true, 8),
  ('norsk-8:lesestrategier', 'q10', 'flervalg', 'Hva betyr det å reflektere over egen lesing?', array['Å lese teksten en gang til', 'Å tenke over hvilke strategier som fungerer for deg og hvorfor', 'Å lese høyt for andre', 'Å skrive en bokanmeldelse']::text[], 1, 'Refleksjon over egen lesing handler om å bli bevisst hvordan du leser, slik at du kan velge bedre strategier.', true, false, 9),
  ('norsk-8:lesestrategier', 'm01', 'sant-usant', 'Du bør alltid lese alle tekster på samme måte.', array['Sant', 'Usant']::text[], 1, 'Strategien bør tilpasses formålet og teksttypen.', false, true, 10),
  ('norsk-8:lesestrategier', 'm02', 'sant-usant', 'En roman er et eksempel på skjønnlitteratur.', array['Sant', 'Usant']::text[], 0, 'Romaner er oppdiktede fortellinger og hører til skjønnlitteraturen.', false, true, 11),
  ('norsk-8:lesestrategier', 'm03', 'sant-usant', 'Å oppsummere med egne ord hjelper deg å huske det du har lest.', array['Sant', 'Usant']::text[], 0, 'Når du omformulerer innholdet, bearbeider du det og husker det bedre.', false, true, 12),
  ('norsk-8:lesestrategier', 'm04', 'sant-usant', 'Nærlesing betyr å lese raskt for å få overblikk.', array['Sant', 'Usant']::text[], 1, 'Det er skumlesing. Nærlesing er grundig lesing av detaljer.', false, true, 13),
  ('norsk-8:lesestrategier', 'm05', 'flervalg', 'Hvilken strategi hører hjemme før lesingen?', array['Skrive sammendrag', 'Lage tankekart over innholdet', 'Tolke budskapet', 'Se over titler og mellomtitler']::text[], 3, 'Å se over titler og mellomtitler er en førlesingsstrategi som gir overblikk.', false, true, 14),
  ('norsk-8:lesestrategier', 'm06', 'flervalg', 'Hva er viktig å vurdere når du leser sakprosa?', array['Hvem som står bak teksten', 'Hvilket rim diktet har', 'Hvem hovedpersonen er forelsket i', 'Hvilken farge omslaget har']::text[], 0, 'I sakprosa må du vurdere avsenderen og om teksten skiller fakta fra meninger.', false, true, 15),
  ('norsk-8:lesestrategier', 'm07', 'flervalg', 'Hva kan du gjøre med et ukjent ord?', array['Alltid hoppe over det', 'Slå det opp eller finne betydningen ut fra sammenhengen', 'Slutte å lese', 'Bytte det ut med et annet ord']::text[], 1, 'Ofte gir sammenhengen et hint. Er ordet viktig, bør du slå det opp.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-8:lesestrategier', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-8:lesestrategier', 's01', 'Du skal lese en novelle for å oppleve en fortelling, og senere lese et kapittel i en naturfagbok for å lære til en prøve. Forklar hvorfor du kan velge ulike lesestrategier i de to situasjonene.', 'Når du leser novella, kan du følge personene og handlingen for å oppleve fortellingen. I naturfagboka kan du lese nøye og oppsummere for å lære stoffet. Strategien bør passe til formålet og teksttypen.', array['Forklarer at strategivalget avhenger av formålet med lesingen og/eller teksttypen.', 'Viser med et relevant eksempel hvordan strategien kan være ulik i de to situasjonene.']::text[], 0),
  ('norsk-8:lesestrategier', 's02', 'Hva er forskjellen på å skumlese og å nærlese? Forklar når det kan være nyttig å bruke hver av strategiene.', 'Når du skumleser, får du raskt et overblikk ved å se på for eksempel titler og mellomtitler. Når du nærleser, går du grundig inn i teksten for å forstå detaljer, særlig når noe er vanskelig.', array['Forklarer at skumlesing gir et raskt overblikk, mens nærlesing er grundig.', 'Knytter strategiene til passende situasjoner eller formål.']::text[], 1),
  ('norsk-8:lesestrategier', 's03', 'Før du leser et fagkapittel, ser du overskriften «Dyr i kalde områder». Skriv et spørsmål du kan stille deg før lesingen, og forklar hvordan spørsmålet kan hjelpe deg.', 'Jeg kan spørre: «Hvordan klarer dyr å leve i kalde områder?» Spørsmålet gir meg noe bestemt å lete etter mens jeg leser.', array['Lager et relevant spørsmål om temaet i overskriften.', 'Forklarer at spørsmålet gir lesingen et fokus eller gjør det lettere å finne ut av noe.']::text[], 2),
  ('norsk-8:lesestrategier', 's04', 'Mens du leser en fagtekst, møter du et ord du ikke forstår. Forklar to måter du kan prøve å finne ut hva ordet betyr.', 'Jeg kan se på ordene rundt og prøve å forstå betydningen ut fra sammenhengen. Hvis det ikke er nok, kan jeg slå opp ordet.', array['Nevner å bruke sammenhengen rundt ordet for å finne betydningen.', 'Nevner å slå opp ordet dersom betydningen fortsatt er uklar.']::text[], 3),
  ('norsk-8:lesestrategier', 's05', 'Sammenlign hvordan du kan lese en novelle og en nyhetsartikkel. Hva kan du særlig legge merke til i hver teksttype?', 'I en novelle kan jeg følge med på personer, miljø og handling. I en nyhetsartikkel kan jeg se etter hovedpoenger, skille fakta fra meninger og vurdere hvem som står bak.', array['Nevner relevante trekk å følge med på i skjønnlitteratur, som personer, miljø eller handling.', 'Nevner relevante trekk ved sakprosa, som hovedpoenger, fakta og meninger eller hvem som står bak.']::text[], 4),
  ('norsk-8:lesestrategier', 's06', 'Etter å ha lest om et tema vil du vise hvordan flere underpunkter henger sammen. Forklar hvordan et tankekart kan hjelpe deg med dette.', 'Jeg kan skrive temaet i midten av tankekartet og plassere underpunktene rundt. Da blir det synlig hvordan underpunktene hører sammen med temaet og med hverandre.', array['Forklarer at temaet står i midten og underpunktene plasseres rundt.', 'Forklarer at tankekartet viser sammenhenger mellom temaet og underpunktene.']::text[], 5),
  ('norsk-8:lesestrategier', 's07', 'Du leser en artikkel om et tema i virkeligheten. Forklar hvordan du kan vurdere om artikkelen gir pålitelig informasjon.', 'Jeg kan undersøke hvem som står bak artikkelen, og skille mellom opplysninger som er fakta, og det som er meninger. Da vurderer jeg både informasjonen og avsenderen.', array['Nevner at man bør vurdere hvem som står bak teksten.', 'Nevner at man bør skille fakta fra meninger.']::text[], 6),
  ('norsk-8:lesestrategier', 's08', 'Når du leser en fagtekst, hvorfor er det ofte bedre å understreke nøkkelord enn hele setninger?', 'Nøkkelord bærer viktige deler av hovedinnholdet. Når jeg markerer dem i stedet for hele setninger, blir det lettere å få oversikt over det viktigste.', array['Forklarer at nøkkelord viser eller bærer viktige deler av hovedinnholdet.', 'Knytter markering av nøkkelord til å få oversikt over det viktigste.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-8:fortelling-og-novelle', 'norsk-8', 'fortelling-og-novelle', 'Fortelling og novelle', 'Kjennetegn ved novellen, oppbygning og spenningskurve, forteller og synsvinkel, og hvordan du analyserer og skriver fortellende tekster.', array[1, 13, 12]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-8:fortelling-og-novelle', '## Fortellende tekster
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-8:fortelling-og-novelle', 'Novelle', 'En kort skjønnlitterær fortelling med få personer, kort tid, brå start og ofte åpen slutt.', 0),
  ('norsk-8:fortelling-og-novelle', 'In medias res', 'At fortellingen starter midt i handlingen, uten lang innledning.', 1),
  ('norsk-8:fortelling-og-novelle', 'Vendepunkt', 'Øyeblikket der noe avgjørende endrer seg for hovedpersonen.', 2),
  ('norsk-8:fortelling-og-novelle', 'Åpen slutt', 'En slutt der ikke alt blir forklart, slik at leseren må tolke selv.', 3),
  ('norsk-8:fortelling-og-novelle', 'Spenningskurve', 'Innledning, konflikt, opptrapping, klimaks og avslutning.', 4),
  ('norsk-8:fortelling-og-novelle', 'Klimaks', 'Høydepunktet i handlingen, der spenningen er størst.', 5),
  ('norsk-8:fortelling-og-novelle', 'Tilbakeblikk', 'Når fortellingen hopper bakover i tid og viser noe som skjedde tidligere.', 6),
  ('norsk-8:fortelling-og-novelle', 'Frampek', 'Et hint om noe som skal skje senere i fortellingen.', 7),
  ('norsk-8:fortelling-og-novelle', 'Førstepersonsforteller', 'En person i fortellingen forteller selv, med «jeg».', 8),
  ('norsk-8:fortelling-og-novelle', 'Allvitende forteller', 'En tredjepersonsforteller som kan se inn i tankene til alle personene.', 9),
  ('norsk-8:fortelling-og-novelle', 'Personal forteller', 'En tredjepersonsforteller som følger én person tett og ser verden fra den personens ståsted.', 10),
  ('norsk-8:fortelling-og-novelle', 'Direkte karakteristikk', 'Fortelleren sier rett ut hvordan en person er.', 11),
  ('norsk-8:fortelling-og-novelle', 'Indirekte karakteristikk', 'Vi forstår hvordan en person er gjennom handlinger, replikker og tanker.', 12),
  ('norsk-8:fortelling-og-novelle', 'Tema', 'Det teksten handler om på et overordnet plan, som vennskap eller ensomhet.', 13),
  ('norsk-8:fortelling-og-novelle', 'Budskap', 'Det teksten vil si om temaet, altså tekstens «poeng».', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-8:fortelling-og-novelle', 'q01', 'flervalg', 'Hva er typisk for en novelle?', array['Mange personer og lang tidsperiode', 'Kort tekst, få personer og ofte brå start', 'Alltid lykkelig slutt', 'Rim og rytme']::text[], 1, 'Novellen er kort, har få personer, foregår over kort tid og starter gjerne midt i handlingen.', true, true, 0),
  ('norsk-8:fortelling-og-novelle', 'q02', 'flervalg', 'Hva betyr «in medias res»?', array['At teksten slutter brått', 'At teksten har en moral', 'At fortellingen starter midt i handlingen', 'At fortelleren er allvitende']::text[], 2, 'Uttrykket er latin og betyr «midt i tingene». Leseren kastes rett inn i handlingen.', true, true, 1),
  ('norsk-8:fortelling-og-novelle', 'q03', 'flervalg', '«Jeg løp så fort jeg kunne.» Hvilken forteller er dette?', array['Førstepersonsforteller', 'Allvitende forteller', 'Personal tredjepersonsforteller', 'Ingen forteller']::text[], 0, 'Fortelleren bruker «jeg» og er selv en person i handlingen.', true, true, 2),
  ('norsk-8:fortelling-og-novelle', 'q04', 'flervalg', 'Hva kalles høydepunktet i spenningskurven?', array['Innledning', 'Tilbakeblikk', 'Frampek', 'Klimaks']::text[], 3, 'Klimaks er stedet der spenningen er på topp, rett før handlingen løses eller vender.', true, true, 3),
  ('norsk-8:fortelling-og-novelle', 'q05', 'flervalg', 'Emma deler matpakken sin med en ny elev uten å si noe. Hva slags karakteristikk er dette?', array['Direkte', 'Indirekte', 'Allvitende', 'Åpen']::text[], 1, 'Vi forstår at Emma er omtenksom ut fra handlingen hennes, ikke fordi fortelleren sier det rett ut.', true, true, 4),
  ('norsk-8:fortelling-og-novelle', 'q06', 'flervalg', 'Hva er forskjellen på tema og budskap?', array['Tema er hva teksten handler om, budskap er hva den vil si om det', 'De betyr det samme', 'Tema er handlingen, budskap er slutten', 'Budskap er tittelen']::text[], 0, 'Temaet kan være vennskap. Budskapet kan være at ekte vennskap tåler uenighet.', true, true, 5),
  ('norsk-8:fortelling-og-novelle', 'q07', 'flervalg', 'Hva er et frampek?', array['Et hopp bakover i tid', 'Tekstens siste setning', 'Et hint om noe som skal skje senere', 'En beskrivelse av miljøet']::text[], 2, 'Frampek bygger forventning og spenning ved å antyde hva som kommer.', true, true, 6),
  ('norsk-8:fortelling-og-novelle', 'q08', 'flervalg', 'Hvorfor har mange noveller åpen slutt?', array['Fordi forfatteren gikk tom for ideer', 'Fordi noveller må være korte', 'Fordi det er en regel', 'For å la leseren tolke og tenke videre selv']::text[], 3, 'Den åpne slutten engasjerer leseren og gir rom for ulike tolkninger.', true, false, 7),
  ('norsk-8:fortelling-og-novelle', 'q09', 'flervalg', 'Hva kan miljøet i en fortelling brukes til?', array['Bare å fortelle hvor handlingen foregår', 'Å speile stemningen og personenes følelser', 'Å erstatte personene', 'Å gi fakta om geografi']::text[], 1, 'Været, årstiden og stedet kan forsterke stemningen, for eksempel mørke og regn i en trist scene.', true, false, 8),
  ('norsk-8:fortelling-og-novelle', 'q10', 'flervalg', 'Hva kjennetegner en allvitende forteller?', array['Fortelleren vet hva alle personene tenker og føler', 'Fortelleren er hovedpersonen', 'Fortelleren vet bare det én person vet', 'Fortelleren snakker til leseren som «du»']::text[], 0, 'Den allvitende fortelleren står utenfor handlingen og kan se inn i alle personene.', true, true, 9),
  ('norsk-8:fortelling-og-novelle', 'm01', 'sant-usant', 'En novelle er vanligvis lengre enn en roman.', array['Sant', 'Usant']::text[], 1, 'Novellen er en kort fortelling. Romanen er lengre og har gjerne flere personer og handlingstråder.', false, true, 10),
  ('norsk-8:fortelling-og-novelle', 'm02', 'sant-usant', 'Et tilbakeblikk viser noe som skjedde før handlingen i nåtid.', array['Sant', 'Usant']::text[], 0, 'Tilbakeblikk hopper bakover i tid og gir leseren bakgrunn.', false, true, 11),
  ('norsk-8:fortelling-og-novelle', 'm03', 'sant-usant', 'Synsvinkelen påvirker hvilke personer leseren får sympati med.', array['Sant', 'Usant']::text[], 0, 'Vi forstår ofte best den personen vi ser handlingen gjennom.', false, true, 12),
  ('norsk-8:fortelling-og-novelle', 'm04', 'sant-usant', '«Han var den snilleste i klassen» er indirekte karakteristikk.', array['Sant', 'Usant']::text[], 1, 'Fortelleren sier rett ut hvordan personen er. Det er direkte karakteristikk.', false, true, 13),
  ('norsk-8:fortelling-og-novelle', 'm05', 'flervalg', 'Hva kalles delen av spenningskurven der spenningen øker?', array['Innledning', 'Avslutning', 'Opptrapping', 'Vendepunkt']::text[], 2, 'I opptrappingen bygges spenningen opp mot klimaks.', false, true, 14),
  ('norsk-8:fortelling-og-novelle', 'm06', 'flervalg', 'Hvilket tema passer til en novelle om en gutt som blir holdt utenfor?', array['Utenforskap', 'Sjanger', 'Tredjepersonsforteller', 'Klimaks']::text[], 0, 'Temaet er det overordnede emnet teksten handler om, her utenforskap eller ensomhet.', false, true, 15),
  ('norsk-8:fortelling-og-novelle', 'm07', 'flervalg', 'Hva er et godt skrivetips for en novelle?', array['Forklar alt i detalj på slutten', 'Start med en lang presentasjon av alle personene', 'Unngå dialog', 'Vis følelser gjennom handling i stedet for å si dem rett ut']::text[], 3, '«Vis, ikke fortell» gjør teksten levende og lar leseren tolke.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-8:fortelling-og-novelle', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-8:fortelling-og-novelle', 's01', 'Hva er et vendepunkt i en fortelling, og hva skjer med hovedpersonen når det oppstår?', 'Et vendepunkt er et øyeblikk der noe avgjørende endrer seg for hovedpersonen. Etter vendepunktet kan handlingen eller hovedpersonens situasjon utvikle seg annerledes.', array['Forklarer at noe avgjørende skjer eller endrer seg.', 'Knytter endringen til hovedpersonen eller den videre handlingen.']::text[], 0),
  ('norsk-8:fortelling-og-novelle', 's02', 'Forklar forskjellen på et tilbakeblikk og et frampek i en fortelling.', 'Et tilbakeblikk viser noe som skjedde tidligere. Et frampek hinter om noe som skal skje senere.', array['Forklarer at tilbakeblikk går bakover i tid.', 'Forklarer at frampek antyder noe som kommer senere.']::text[], 1),
  ('norsk-8:fortelling-og-novelle', 's03', 'Hvordan er direkte og indirekte karakteristikk forskjellige? Ta med hva leseren får vite om personen på hver av måtene.', 'Ved direkte karakteristikk sier fortelleren rett ut hvordan personen er. Ved indirekte karakteristikk må leseren forstå det gjennom personens handlinger, replikker eller tanker.', array['Forklarer at direkte karakteristikk sier egenskaper rett ut.', 'Forklarer at indirekte karakteristikk viser egenskaper gjennom handlinger, replikker eller tanker.']::text[], 2),
  ('norsk-8:fortelling-og-novelle', 's04', 'En fortelling viser først hvem personene er og hvor handlingen skjer. Så oppstår en konflikt, og problemene blir gradvis større. Forklar hvordan denne opptrappingen kan gjøre fortellingen mer spennende.', 'Når problemene blir større, blir leseren mer spent på hva som vil skje. Opptrappingen bygger fram mot et høydepunkt i handlingen.', array['Knytter opptrappingen til at konflikten eller problemene blir større.', 'Forklarer at dette øker spenningen eller bygger fram mot et høydepunkt.']::text[], 3),
  ('norsk-8:fortelling-og-novelle', 's05', 'En tredjepersonsforteller følger én person tett og viser verden fra den personens ståsted. Hva slags forteller er dette, og hvordan påvirker det hva leseren får vite?', 'Det er en personal forteller. Leseren følger én person tett og får ikke nødvendigvis vite hva alle de andre tenker.', array['Identifiserer fortelleren som personal.', 'Forklarer at leserens innsyn er knyttet til personen fortelleren følger.']::text[], 4),
  ('norsk-8:fortelling-og-novelle', 's06', 'Vis hvordan en forfatter kan karakterisere en person indirekte. Finn på en kort handling eller replikk som røper en egenskap, og forklar hvilken egenskap leseren kan forstå.', 'En person kan for eksempel gi bort den siste brødskiven sin til noen som er sultne. Det viser indirekte at personen er omsorgsfull.', array['Gir en handling, replikk eller tanke som viser en egenskap uten å si den rett ut.', 'Forklarer hvilken egenskap leseren kan forstå ut fra eksempelet.']::text[], 5),
  ('norsk-8:fortelling-og-novelle', 's07', 'I en fortelling blir en person stadig holdt utenfor når andre er sammen, og personen føler seg alene. Hva kan være et passende tema for fortellingen? Forklar hvordan situasjonen peker mot temaet.', 'Et passende tema kan være ensomhet. Personen blir holdt utenfor og føler seg alene, så temaet handler om mer enn bare de konkrete hendelsene.', array['Foreslår et overordnet tema som ensomhet eller utenforskap.', 'Knytter temaet til at personen blir holdt utenfor eller føler seg alene.']::text[], 6),
  ('norsk-8:fortelling-og-novelle', 's08', 'Sett disse delene av spenningskurven i riktig rekkefølge: klimaks, innledning, avslutning, opptrapping og presentasjon av konflikten. Forklar kort hva opptrappingen gjør.', 'Rekkefølgen er innledning, presentasjon av konflikten, opptrapping, klimaks og avslutning. Opptrappingen gjør at spenningen øker fram mot klimaks.', array['Setter delene i riktig rekkefølge.', 'Forklarer at opptrappingen øker spenningen fram mot klimaks.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-8:sakprosa', 'norsk-8', 'sakprosa', 'Sakprosa og fagtekster', 'Hva sakprosa er, de vanligste sakprosasjangrene, hvordan en fagtekst er bygd opp, og hvordan du skriver informerende tekster.', array[1, 10]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-8:sakprosa', '## Hva er sakprosa?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-8:sakprosa', 'Sakprosa', 'Tekster om virkeligheten som skal informere, forklare, argumentere eller påvirke.', 0),
  ('norsk-8:sakprosa', 'Skjønnlitteratur', 'Oppdiktede tekster, som noveller, romaner og dikt.', 1),
  ('norsk-8:sakprosa', 'Nyhetsartikkel', 'Sakprosasjanger som informerer om noe nytt og viktig, med det viktigste først.', 2),
  ('norsk-8:sakprosa', 'Reportasje', 'Tar leseren med til et sted eller en hendelse med beskrivelser og intervjuer.', 3),
  ('norsk-8:sakprosa', 'Fagtekst', 'En tekst som forklarer et emne, for eksempel i lærebøker.', 4),
  ('norsk-8:sakprosa', 'Kåseri', 'En humoristisk og personlig tekst om et hverdagslig emne.', 5),
  ('norsk-8:sakprosa', 'Debattinnlegg', 'En tekst som argumenterer for en mening i en sak.', 6),
  ('norsk-8:sakprosa', 'Nyhetstrekanten', 'Oppbygning der det viktigste kommer først og detaljene til slutt.', 7),
  ('norsk-8:sakprosa', 'Hv-spørsmål', 'Hva, hvem, hvor, når, hvorfor og hvordan. Ingressen svarer ofte på dem.', 8),
  ('norsk-8:sakprosa', 'Temasetning', 'Setning, ofte først i avsnittet, som sier hva avsnittet handler om.', 9),
  ('norsk-8:sakprosa', 'Avsnitt', 'En del av teksten med én hovedtanke. Markeres med ny linje eller innrykk.', 10),
  ('norsk-8:sakprosa', 'Fagord', 'Ord som hører til et bestemt fag, og som bør forklares for leseren.', 11),
  ('norsk-8:sakprosa', 'Fakta', 'Opplysninger som kan sjekkes og bekreftes.', 12),
  ('norsk-8:sakprosa', 'Mening', 'Det noen synes eller mener. Kan ikke bevises som sant eller usant.', 13),
  ('norsk-8:sakprosa', 'Mottaker', 'Den teksten er skrevet for. Innhold og språk bør tilpasses mottakeren.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-8:sakprosa', 'q01', 'flervalg', 'Hva er sakprosa?', array['Oppdiktede fortellinger', 'Tekster som handler om virkeligheten', 'Bare tekster fra aviser', 'Dikt uten rim']::text[], 1, 'Sakprosa handler om virkelige forhold og kan være alt fra lærebøker til debattinnlegg.', true, true, 0),
  ('norsk-8:sakprosa', 'q02', 'flervalg', 'Hvordan er en nyhetsartikkel bygd opp?', array['Det viktigste kommer først', 'Det viktigste kommer til slutt', 'Den starter alltid med et sitat', 'Den har spenningskurve med klimaks']::text[], 0, 'Nyhetstrekanten gjør at leseren får hovedsaken med én gang, og kan lese videre for detaljer.', true, true, 1),
  ('norsk-8:sakprosa', 'q03', 'flervalg', 'Hvilken sjanger er humoristisk og personlig og handler ofte om noe hverdagslig?', array['Rapport', 'Nyhetsartikkel', 'Instruksjon', 'Kåseri']::text[], 3, 'Kåseriet er en lett og underholdende sjanger med personlig stil.', true, true, 2),
  ('norsk-8:sakprosa', 'q04', 'flervalg', 'Hva er en temasetning?', array['Siste setning i teksten', 'Overskriften', 'En setning som sier hva avsnittet handler om', 'Et sitat fra en kilde']::text[], 2, 'Temasetningen står ofte først i avsnittet og gir leseren avsnittets hovedtanke.', true, true, 3),
  ('norsk-8:sakprosa', 'q05', 'flervalg', 'Hvilket utsagn er en mening og ikke et faktum?', array['Oslo er hovedstaden i Norge', 'Skoledagen bør starte klokka ni', 'Vann koker ved 100 °C ved normalt lufttrykk', 'Norge har over fem millioner innbyggere']::text[], 1, 'At skoledagen bør starte senere, er noe man mener. De andre kan sjekkes.', true, true, 4),
  ('norsk-8:sakprosa', 'q06', 'flervalg', 'Hvilke spørsmål svarer ingressen i en nyhetsartikkel ofte på?', array['Hv-spørsmålene: hva, hvem, hvor, når, hvorfor, hvordan', 'Hvordan artikkelen slutter', 'Hva journalisten mener', 'Hvilke kilder som er brukt']::text[], 0, 'Ingressen gir en rask oppsummering av de viktigste opplysningene.', true, true, 5),
  ('norsk-8:sakprosa', 'q07', 'flervalg', 'Hva kjennetegner en reportasje?', array['Den er alltid kortest mulig', 'Den består bare av tall', 'Den tar leseren med til stedet med beskrivelser og intervjuer', 'Den er oppdiktet']::text[], 2, 'Reportasjen er levende sakprosa som lar leseren oppleve et sted eller en hendelse.', true, false, 6),
  ('norsk-8:sakprosa', 'q08', 'flervalg', 'Hva bør du tenke på først når du skal skrive en informerende tekst?', array['Hvor mange sider teksten skal være', 'Hvilke ord som rimer', 'Hvordan du kan skjule kildene', 'Hvem mottakeren er og hva de trenger å vite']::text[], 3, 'Innhold, fagord og språk må tilpasses den som skal lese teksten.', true, true, 7),
  ('norsk-8:sakprosa', 'q09', 'flervalg', 'Hvor mange hovedtanker bør et avsnitt ha?', array['Én', 'To', 'Så mange som mulig', 'Ingen']::text[], 0, 'Ett avsnitt, én hovedtanke. Det gjør teksten oversiktlig.', true, false, 8),
  ('norsk-8:sakprosa', 'q10', 'flervalg', 'Hvilken sjanger argumenterer for en mening?', array['Fagtekst', 'Debattinnlegg', 'Bruksanvisning', 'Leksikonartikkel']::text[], 1, 'Debattinnlegget skal overbevise leseren om et standpunkt.', true, true, 9),
  ('norsk-8:sakprosa', 'm01', 'sant-usant', 'En lærebok i naturfag er sakprosa.', array['Sant', 'Usant']::text[], 0, 'Lærebøker forklarer virkelige forhold og er typiske fagtekster.', false, true, 10),
  ('norsk-8:sakprosa', 'm02', 'sant-usant', 'I en nyhetsartikkel kommer de viktigste opplysningene til slutt.', array['Sant', 'Usant']::text[], 1, 'Nyhetsartikler har det viktigste først, etter nyhetstrekanten.', false, true, 11),
  ('norsk-8:sakprosa', 'm03', 'sant-usant', 'Sakprosa kan bruke fortellergrep, som å starte med en scene.', array['Sant', 'Usant']::text[], 0, 'Særlig reportasjer bruker skjønnlitterære grep for å gjøre teksten levende.', false, true, 12),
  ('norsk-8:sakprosa', 'm04', 'sant-usant', 'En mening kan sjekkes og bevises på samme måte som et faktum.', array['Sant', 'Usant']::text[], 1, 'Meninger handler om hva noen synes. Fakta kan kontrolleres.', false, true, 13),
  ('norsk-8:sakprosa', 'm05', 'flervalg', 'Hvilken tekst er en instruksjon?', array['En bruksanvisning til en kaffemaskin', 'Et dikt om høsten', 'Et leserbrev om bompenger', 'En novelle']::text[], 0, 'En instruksjon forklarer steg for steg hvordan man gjør noe.', false, true, 14),
  ('norsk-8:sakprosa', 'm06', 'flervalg', 'Hva bør en god avslutning i en fagtekst gjøre?', array['Introdusere et nytt emne', 'Oppsummere hovedpoengene', 'Gjenta innledningen ord for ord', 'Stille leseren et vanskelig spørsmål uten svar']::text[], 1, 'Avslutningen samler trådene og minner leseren om det viktigste.', false, true, 15),
  ('norsk-8:sakprosa', 'm07', 'flervalg', 'Hvorfor bør fagord forklares i en fagtekst?', array['For å gjøre teksten lengre', 'Fordi det er en regel i rettskrivingen', 'For at leseren skal forstå innholdet', 'For å unngå avsnitt']::text[], 2, 'Fagord er nødvendige for presisjon, men leseren må forstå dem for å få utbytte av teksten.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-8:sakprosa', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-8:sakprosa', 's01', 'En roman kan fortelle om oppdiktede hendelser, mens en læreboktekst forklarer et emne fra virkeligheten. Forklar forskjellen på skjønnlitteratur og sakprosa.', 'Skjønnlitteratur er oppdiktet, mens sakprosa handler om virkeligheten. Sakprosa kan for eksempel informere eller forklare.', array['Forklarer at skjønnlitteratur er oppdiktet, og at sakprosa handler om virkeligheten.']::text[], 0),
  ('norsk-8:sakprosa', 's02', 'En nyhetsartikkel har det viktigste først og mindre viktige detaljer lenger ned. Forklar hvorfor denne oppbygningen kan være nyttig for leseren.', 'Leseren får med seg hovedsaken tidlig. Hvis leseren må slutte å lese før artikkelen er ferdig, har hen likevel fått vite det viktigste.', array['Forklarer at leseren raskt får med seg hovedsaken, også hvis hen ikke leser hele artikkelen.']::text[], 1),
  ('norsk-8:sakprosa', 's03', 'En journalist besøker et sted der noe har skjedd, beskriver det som foregår og intervjuer personer som er der. Hvilken sakprosasjanger passer best, og hva i situasjonen viser det?', 'Dette passer best som en reportasje. Reportasjen tar leseren med til et sted eller en hendelse og kan bruke beskrivelser og intervjuer.', array['Velger reportasje og begrunner svaret med at teksten bruker beskrivelser og/eller intervjuer fra et sted eller en hendelse.']::text[], 2),
  ('norsk-8:sakprosa', 's04', 'Tenk deg at noen skriver: «Biblioteket ligger ved skolen» og «Biblioteket er det beste stedet i byen». Hvilken setning uttrykker en mening, og hvorfor?', '«Biblioteket er det beste stedet i byen» uttrykker en mening. Det er noe noen synes, og ikke en opplysning som kan bekreftes som sann eller usann.', array['Peker ut den andre setningen som en mening og forklarer at den uttrykker en vurdering eller noe noen synes.']::text[], 3),
  ('norsk-8:sakprosa', 's05', 'En fagtekst bruker et fagord som leserne kanskje ikke kjenner. Hva bør forfatteren gjøre med fagordet, og hvorfor?', 'Forfatteren bør forklare fagordet. Da kan leserne forstå innholdet selv om de ikke kjenner ordet fra før.', array['Får fram at fagordet bør forklares slik at leseren forstår teksten.']::text[], 4),
  ('norsk-8:sakprosa', 's06', 'Sammenlign formålet med en fagtekst og et debattinnlegg. Hva prøver hver av dem å gjøre?', 'En fagtekst forklarer et emne. Et debattinnlegg argumenterer for en mening i en sak.', array['Forklarer at en fagtekst skal forklare et emne.', 'Forklarer at et debattinnlegg argumenterer for en mening.']::text[], 5),
  ('norsk-8:sakprosa', 's07', 'I ett avsnitt i en fagtekst står det først om dyr i skogen og deretter om hvordan været påvirker planter. Forklar hvordan avsnittet kan forbedres, og hvilken rolle temasetningen kan ha.', 'Avsnittet kan deles i to, slik at hvert avsnitt handler om én hovedtanke. En temasetning kan stå først og fortelle hva avsnittet handler om.', array['Foreslår å samle én hovedtanke i hvert avsnitt, for eksempel ved å dele avsnittet.', 'Forklarer at temasetningen sier hva avsnittet handler om.']::text[], 6),
  ('norsk-8:sakprosa', 's08', 'En fagtekst skal ha en innledning, en hoveddel og en avslutning. Forklar hva disse delene bør gjøre, og hvilken rekkefølge de bør stå i.', 'Innledningen presenterer emnet, hoveddelen forklarer det i avsnitt, og avslutningen oppsummerer. De står i rekkefølgen innledning, hoveddel og avslutning.', array['Plasserer innledning, hoveddel og avslutning i riktig rekkefølge.', 'Forklarer hovedfunksjonen til delene: presentere emnet, forklare det og oppsummere.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-8:ordklasser', 'norsk-8', 'ordklasser', 'Ordklasser', 'De ti ordklassene i norsk skolegrammatikk, hvordan du kjenner dem igjen, og hvordan substantiv, verb og adjektiv bøyes.', array[12, 11]::int[], 3, 'utkast', array['Antall ordklasser varierer mellom framstillinger (ti, eventuelt med infinitivsmerke som egen klasse). Sjekk mot læreverket skolen bruker.']::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-8:ordklasser', '## Hvorfor ordklasser?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-8:ordklasser', 'Ordklasse', 'En gruppe ord med samme funksjon og bøyningsmåte, for eksempel substantiv eller verb.', 0),
  ('norsk-8:ordklasser', 'Substantiv', 'Navn på ting, personer, steder og begreper. Bøyes i kjønn, tall og bestemthet.', 1),
  ('norsk-8:ordklasser', 'Egennavn', 'Substantiv som er navn på en bestemt person eller et sted. Skrives med stor forbokstav.', 2),
  ('norsk-8:ordklasser', 'Verb', 'Ord for handling eller det som skjer. Bøyes i tid: kaste – kaster – kastet – har kastet.', 3),
  ('norsk-8:ordklasser', 'Infinitiv', 'Verbets grunnform, ofte med «å» foran: å løpe.', 4),
  ('norsk-8:ordklasser', 'Imperativ', 'Verbets bydeform: Løp! Kast!', 5),
  ('norsk-8:ordklasser', 'Adjektiv', 'Beskriver substantiv. Kan gradbøyes: stor – større – størst.', 6),
  ('norsk-8:ordklasser', 'Pronomen', 'Står i stedet for substantiv: jeg, du, han, hun, den, vi, dere, de.', 7),
  ('norsk-8:ordklasser', 'Determinativ', 'Bestemmer substantivet nærmere: min, denne, tre, alle, noen.', 8),
  ('norsk-8:ordklasser', 'Adverb', 'Sier noe om hvordan, hvor eller når: fort, her, i dag, ikke.', 9),
  ('norsk-8:ordklasser', 'Preposisjon', 'Viser forhold mellom ord, ofte sted eller tid: på, i, under, etter.', 10),
  ('norsk-8:ordklasser', 'Konjunksjon', 'Binder sammen likeverdige ord og setninger: og, men, eller, for, så.', 11),
  ('norsk-8:ordklasser', 'Subjunksjon', 'Innleder leddsetninger: at, fordi, hvis, når, som, om.', 12),
  ('norsk-8:ordklasser', 'Interjeksjon', 'Utrop og lydord: au, hei, uff, pang.', 13),
  ('norsk-8:ordklasser', 'Infinitivsmerke', '«å» foran verb i infinitiv. Regnes ofte som en egen liten ordklasse.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-8:ordklasser', 'q01', 'flervalg', 'Hvilken ordklasse er «glede» i setningen «Gleden var stor»?', array['Verb', 'Adjektiv', 'Substantiv', 'Adverb']::text[], 2, '«Gleden» er bestemt form av substantivet glede. Du kan si «en glede».', true, true, 0),
  ('norsk-8:ordklasser', 'q02', 'flervalg', 'Hva er preteritum av «kaste»?', array['kaster', 'kastet', 'har kastet', 'kast']::text[], 1, 'Preteritum er fortid: Jeg kastet ballen i går.', true, true, 1),
  ('norsk-8:ordklasser', 'q03', 'flervalg', 'Hvilket ord er en subjunksjon?', array['fordi', 'og', 'på', 'fort']::text[], 0, '«Fordi» innleder en leddsetning: … fordi det regnet. «Og» er konjunksjon.', true, true, 2),
  ('norsk-8:ordklasser', 'q04', 'flervalg', 'Hvilken ordklasse er «under» i «Katten sover under bordet»?', array['Adverb', 'Konjunksjon', 'Substantiv', 'Preposisjon']::text[], 3, '«Under» viser forholdet mellom katten og bordet, altså et stedsforhold.', true, true, 3),
  ('norsk-8:ordklasser', 'q05', 'flervalg', 'Hva er riktig gradbøying av «god»?', array['god – godere – godest', 'god – bedre – best', 'god – godt – gode', 'god – mer god – mest god']::text[], 1, '«God» har uregelrett gradbøying: god – bedre – best.', true, true, 4),
  ('norsk-8:ordklasser', 'q06', 'flervalg', 'Hvilket ord er et pronomen?', array['denne', 'min', 'hun', 'tre']::text[], 2, '«Hun» står i stedet for et substantiv. «Denne», «min» og «tre» er determinativer som står sammen med et substantiv.', true, true, 5),
  ('norsk-8:ordklasser', 'q07', 'flervalg', 'Hvilken ordklasse er «ikke»?', array['Adverb', 'Pronomen', 'Interjeksjon', 'Preposisjon']::text[], 0, '«Ikke» er et adverb som sier noe om verbet eller hele setningen.', true, false, 6),
  ('norsk-8:ordklasser', 'q08', 'flervalg', 'Hva er bestemt form flertall av «bil»?', array['biler', 'bilen', 'en bil', 'bilene']::text[], 3, 'en bil – bilen – biler – bilene. Bestemt flertall er «bilene».', true, true, 7),
  ('norsk-8:ordklasser', 'q09', 'flervalg', '«Kast ballen!» Hvilken form har verbet?', array['Infinitiv', 'Presens', 'Imperativ', 'Preteritum']::text[], 2, 'Imperativ er bydeformen, som brukes når vi gir beskjed eller ordre.', true, true, 8),
  ('norsk-8:ordklasser', 'q10', 'flervalg', 'Hvilket ord binder sammen to likeverdige setninger i «Jeg var sulten, men maten var ikke ferdig»?', array['men', 'var', 'ikke', 'maten']::text[], 0, '«Men» er en konjunksjon som binder sammen to hovedsetninger.', true, false, 9),
  ('norsk-8:ordklasser', 'm01', 'sant-usant', 'Et ord kan høre til ulike ordklasser avhengig av hvordan det brukes.', array['Sant', 'Usant']::text[], 0, '«Kast» er substantiv i «et godt kast», men verb i «kast ballen!».', false, true, 10),
  ('norsk-8:ordklasser', 'm02', 'sant-usant', 'Preposisjoner bøyes i tid.', array['Sant', 'Usant']::text[], 1, 'Preposisjoner er ubøyelige. Det er verbene som bøyes i tid.', false, true, 11),
  ('norsk-8:ordklasser', 'm03', 'sant-usant', '«Au!» er en interjeksjon.', array['Sant', 'Usant']::text[], 0, 'Utrop og lydord hører til ordklassen interjeksjon.', false, true, 12),
  ('norsk-8:ordklasser', 'm04', 'sant-usant', 'Egennavn skrives med liten forbokstav.', array['Sant', 'Usant']::text[], 1, 'Egennavn som Oslo og Maria skrives med stor forbokstav.', false, true, 13),
  ('norsk-8:ordklasser', 'm05', 'flervalg', 'Hvilket ord er et adjektiv?', array['løpe', 'grønn', 'raskt', 'under']::text[], 1, '«Grønn» beskriver et substantiv og kan bøyes: grønn – grønt – grønne.', false, true, 14),
  ('norsk-8:ordklasser', 'm06', 'flervalg', 'Hvilken ordklasse er «denne» i «denne boka»?', array['Pronomen', 'Adverb', 'Determinativ', 'Substantiv']::text[], 2, '«Denne» står sammen med substantivet og bestemmer hvilken bok det gjelder.', false, true, 15),
  ('norsk-8:ordklasser', 'm07', 'flervalg', 'Hva er presens perfektum av «skrive»?', array['skrev', 'skriver', 'skriv', 'har skrevet']::text[], 3, 'Presens perfektum består av «har» og perfektum partisipp: har skrevet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-8:ordklasser', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-8:ordklasser', 's01', 'Forklar hva en ordklasse forteller om et ord, og nevn én grunn til at det er nyttig å kjenne ordklassene.', 'Ordklassen forteller hvilken jobb ordet gjør, og hvordan det kan bøyes. Det er nyttig fordi ordklassene gjør det lettere å snakke om språk eller rette egne tekster.', array['Forklarer at ordklassen sier noe om ordets funksjon eller bøyning.', 'Nevner en relevant nytte, for eksempel å snakke om språk, rette tekster eller lære andre språk.']::text[], 0),
  ('norsk-8:ordklasser', 's02', 'I setningen «Eleven tegner et kart» er «eleven» og «kart» substantiv, mens «tegner» er verb. Forklar forskjellen på jobben substantivene og verbet gjør i setningen.', 'Substantivene navngir personen og tingen i setningen. Verbet forteller hva eleven gjør.', array['Forklarer at substantiv navngir personer, ting eller begreper.', 'Forklarer at verbet uttrykker handling eller det som skjer.']::text[], 1),
  ('norsk-8:ordklasser', 's03', 'Ordet «kast» brukes i «Et langt kast traff bakken» og «Kast ballen!». Forklar hvilken ordklasse ordet tilhører i hver setning, og hvordan du kan se forskjellen.', 'I «Et langt kast traff bakken» er «kast» et substantiv, fordi det er navnet på noe. I «Kast ballen!» er det et verb i imperativ, altså en bydeform.', array['Forklarer at «kast» er substantiv i den første setningen.', 'Forklarer at «kast» er verb i imperativ i den andre setningen.']::text[], 2),
  ('norsk-8:ordklasser', 's04', 'Forklar forskjellen på «Oslo» og «by» når det gjelder egennavn og stor forbokstav.', '«Oslo» er et egennavn fordi det er navnet på et bestemt sted, og det skrives med stor forbokstav. «By» er et vanlig substantiv, ikke et egennavn.', array['Forklarer at «Oslo» er navnet på et bestemt sted og derfor et egennavn.', 'Forklarer at egennavn skrives med stor forbokstav, og skiller «by» fra egennavn.']::text[], 3),
  ('norsk-8:ordklasser', 's05', 'I setningen «Den raske hunden løper», forklar hvorfor «raske» er et adjektiv. Nevn én måte du kan teste om et ord er et adjektiv på.', '«Raske» er et adjektiv fordi det beskriver substantivet «hunden». Et adjektiv kan for eksempel stå mellom «en» og et substantiv, som i «en rask hund».', array['Forklarer at «raske» beskriver substantivet «hunden».', 'Nevner en relevant adjektivtest, som plassering mellom «en» og et substantiv eller gradbøying.']::text[], 4),
  ('norsk-8:ordklasser', 's06', 'Sammenlign ordene «min» og «jeg» i setningene «Min bok ligger her» og «Jeg leser». Hvilken jobb gjør hvert ord?', '«Min» er et determinativ som bestemmer substantivet «bok» nærmere. «Jeg» er et pronomen som står i stedet for et substantiv.', array['Forklarer at «min» bestemmer substantivet nærmere.', 'Forklarer at «jeg» er et pronomen som står i stedet for et substantiv.']::text[], 5),
  ('norsk-8:ordklasser', 's07', 'Sammenlign «men» i «Jeg ville gå, men det regnet» og «fordi» i «Jeg ble hjemme fordi det regnet». Forklar hvilken type ord hvert av dem er, og hva de gjør.', '«Men» er en konjunksjon som binder sammen likeverdige setninger. «Fordi» er en subjunksjon som innleder leddsetningen «fordi det regnet».', array['Forklarer at «men» binder sammen likeverdige ord eller setninger.', 'Forklarer at «fordi» innleder en leddsetning.']::text[], 6),
  ('norsk-8:ordklasser', 's08', 'I uttrykket «å løpe» står «å» foran verbet. Forklar hvilken funksjon «å» har, og hvilken form «løpe» står i.', '«Å» er infinitivsmerket som står foran et verb i infinitiv. «Løpe» er verbets infinitiv, altså grunnform.', array['Forklarer at «å» er infinitivsmerket.', 'Forklarer at «løpe» står i infinitiv eller grunnform.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-8:rettskriving-og-tegnsetting', 'norsk-8', 'rettskriving-og-tegnsetting', 'Rettskriving og tegnsetting', 'De vanligste rettskrivingsfellene på bokmål – og/å, de/dem, dobbel konsonant og særskriving – og de viktigste kommareglene.', array[11]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-8:rettskriving-og-tegnsetting', '## Hvorfor rettskriving?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-8:rettskriving-og-tegnsetting', 'Å', 'Infinitivsmerke foran verb: Jeg liker å lese.', 0),
  ('norsk-8:rettskriving-og-tegnsetting', 'Og', 'Konjunksjon som binder sammen ord og setninger: brød og smør.', 1),
  ('norsk-8:rettskriving-og-tegnsetting', 'De', 'Subjektsform: De spiller fotball. Test: passer «vi»?', 2),
  ('norsk-8:rettskriving-og-tegnsetting', 'Dem', 'Objektsform og etter preposisjon: Jeg så dem. Test: passer «oss»?', 3),
  ('norsk-8:rettskriving-og-tegnsetting', 'Dobbel konsonant', 'Etter kort vokal skrives ofte dobbel konsonant: takk, katt, hopp.', 4),
  ('norsk-8:rettskriving-og-tegnsetting', 'Enkel konsonant', 'Etter lang vokal skrives enkel konsonant: tak, kat, hop.', 5),
  ('norsk-8:rettskriving-og-tegnsetting', 'Aldri dobbel m til slutt', 'Ord ender ikke på -mm: dum, rom, hvem.', 6),
  ('norsk-8:rettskriving-og-tegnsetting', 'Stum h', 'hv- og hj- i ord som hva, hvem, hjem og hjelp.', 7),
  ('norsk-8:rettskriving-og-tegnsetting', 'Særskriving', 'Feil der sammensatte ord deles i to. Riktig: fotballtrening, ikke fotball trening.', 8),
  ('norsk-8:rettskriving-og-tegnsetting', 'Liten forbokstav', 'Dager, måneder, språk og nasjonaliteter: mandag, mai, norsk, nordmann.', 9),
  ('norsk-8:rettskriving-og-tegnsetting', 'Komma mellom helsetninger', 'Foran og, men, eller, for, så når de binder to helsetninger: Det regnet, men vi gikk.', 10),
  ('norsk-8:rettskriving-og-tegnsetting', 'Komma etter leddsetning først', 'Når det regner, blir vi inne.', 11),
  ('norsk-8:rettskriving-og-tegnsetting', 'Innskutt leddsetning', 'Står midt i en helsetning og har komma på begge sider: Boka, som jeg fikk, var god.', 12),
  ('norsk-8:rettskriving-og-tegnsetting', 'Oppramsing', 'Komma mellom ledd, men ikke foran det siste «og»: epler, pærer og bananer.', 13),
  ('norsk-8:rettskriving-og-tegnsetting', 'Ikke komma foran «at»', 'Når at-setningen kommer etter hovedsetningen: Jeg tror at det blir fint.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-8:rettskriving-og-tegnsetting', 'q01', 'flervalg', 'Hvilken setning er riktig?', array['Jeg liker og svømme.', 'Jeg liker å svømme.', 'Jeg liker og å svømme.', 'Jeg liker svømme.']::text[], 1, '«Svømme» er et verb i infinitiv, og da skal det stå «å» foran.', true, true, 0),
  ('norsk-8:rettskriving-og-tegnsetting', 'q02', 'flervalg', 'Hvilken setning er riktig?', array['Jeg snakket med de i går.', 'Dem kom for sent.', 'Jeg snakket med dem i går.', 'De og dem betyr det samme.']::text[], 2, 'Etter preposisjonen «med» skal det være objektsformen «dem». Test: med oss, ikke med vi.', true, true, 1),
  ('norsk-8:rettskriving-og-tegnsetting', 'q03', 'flervalg', 'Hvilket ord er riktig stavet?', array['Takk for maten', 'Tak for maten', 'Takkk for maten', 'Tagg for maten']::text[], 0, 'Vokalen i «takk» er kort, så det skal være dobbel konsonant. «Tak» er det som er over huset.', true, true, 2),
  ('norsk-8:rettskriving-og-tegnsetting', 'q04', 'flervalg', 'Hvilket alternativ er skrevet riktig i ett ord?', array['ungdoms skole', 'fotball trening', 'røyk fritt', 'ungdomsskole']::text[], 3, 'Sammensatte ord skrives i ett ord på norsk. De andre er eksempler på særskriving.', true, true, 3),
  ('norsk-8:rettskriving-og-tegnsetting', 'q05', 'flervalg', 'Hvor skal kommaet stå? «Når vi kommer hjem skal vi spise.»', array['Etter «Når»', 'Etter «hjem»', 'Etter «vi»', 'Det skal ikke være komma']::text[], 1, 'Leddsetningen «Når vi kommer hjem» står først, og da skal det være komma etter den.', true, true, 4),
  ('norsk-8:rettskriving-og-tegnsetting', 'q06', 'flervalg', 'Hvilket ord skal ha liten forbokstav midt i en setning?', array['Oslo', 'Norge', 'Maria', 'januar']::text[], 3, 'Måneder skrives med liten forbokstav på norsk. Oslo, Norge og Maria er egennavn.', true, false, 5),
  ('norsk-8:rettskriving-og-tegnsetting', 'q07', 'flervalg', 'Hvilken setning har riktig komma?', array['Jeg kjøpte epler, pærer, og bananer.', 'Jeg kjøpte, epler pærer og bananer.', 'Jeg kjøpte epler, pærer og bananer.', 'Jeg kjøpte epler pærer, og bananer.']::text[], 2, 'Ved oppramsing skal det være komma mellom leddene, men ikke foran det siste «og».', true, true, 6),
  ('norsk-8:rettskriving-og-tegnsetting', 'q08', 'flervalg', 'Hvilken setning har riktig tegnsetting?', array['Jeg tror, at det blir fint.', 'Jeg tror at det blir fint.', 'Jeg, tror at det blir fint.', 'Jeg tror at, det blir fint.']::text[], 1, 'Det skal ikke være komma foran «at» når at-setningen kommer etter hovedsetningen.', true, true, 7),
  ('norsk-8:rettskriving-og-tegnsetting', 'q09', 'flervalg', 'Hva betyr skiltet «røyk fritt»?', array['At det er lov å røyke', 'At røyking er forbudt', 'At røyk er gratis', 'Ingenting']::text[], 0, 'Særskrivingen endrer betydningen: «røyk fritt» betyr «røyk så mye du vil». Riktig er «røykfritt».', true, false, 8),
  ('norsk-8:rettskriving-og-tegnsetting', 'q10', 'flervalg', 'Hvilken setning trenger komma?', array['Jeg vet at du kommer.', 'Hun sa hei.', 'Vi dro på tur og vi hadde det gøy.', 'Han løp fort.']::text[], 2, 'To helsetninger bundet sammen med «og» skal ha komma: Vi dro på tur, og vi hadde det gøy.', true, true, 9),
  ('norsk-8:rettskriving-og-tegnsetting', 'm01', 'sant-usant', 'Norsk skrives med stor forbokstav når det gjelder språket.', array['Sant', 'Usant']::text[], 1, 'Språk og nasjonaliteter skrives med liten forbokstav: norsk, engelsk, nordmann.', false, true, 10),
  ('norsk-8:rettskriving-og-tegnsetting', 'm02', 'sant-usant', '«Hvem» skrives med stum h.', array['Sant', 'Usant']::text[], 0, 'hv- i begynnelsen av ord som hva, hvem og hvor har stum h.', false, true, 11),
  ('norsk-8:rettskriving-og-tegnsetting', 'm03', 'sant-usant', '«Dum» skal skrives «dumm» fordi vokalen er kort.', array['Sant', 'Usant']::text[], 1, 'Ord ender ikke på dobbel m i norsk: dum, rom, hvem.', false, true, 12),
  ('norsk-8:rettskriving-og-tegnsetting', 'm04', 'sant-usant', 'En innskutt leddsetning skal ha komma på begge sider.', array['Sant', 'Usant']::text[], 0, 'Eksempel: Boka, som jeg fikk i gave, var spennende.', false, true, 13),
  ('norsk-8:rettskriving-og-tegnsetting', 'm05', 'flervalg', 'Hvilket ord mangler? «Jeg ga … boka.»', array['de', 'dem', 'dems', 'di']::text[], 1, 'Ordet er indirekte objekt: Jeg ga dem boka. Test: Jeg ga oss boka.', false, true, 14),
  ('norsk-8:rettskriving-og-tegnsetting', 'm06', 'flervalg', 'Hvilken skrivemåte er riktig?', array['gjest', 'jest', 'gest', 'hjest']::text[], 0, '«Gjest» skrives med stum g: gj-.', false, true, 15),
  ('norsk-8:rettskriving-og-tegnsetting', 'm07', 'flervalg', 'Hvor skal kommaet stå når du tiltaler noen?', array['Ola kom hit!', 'Ola, kom hit!', 'Ola kom, hit!', 'Ola, kom, hit!']::text[], 1, 'Det skal være komma etter tiltale: Ola, kom hit!', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-8:rettskriving-og-tegnsetting', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-8:rettskriving-og-tegnsetting', 's01', 'Forklar hvorfor riktig rettskriving og tegnsetting gjør en tekst bedre for leseren.', 'Riktig rettskriving og tegnsetting gjør teksten lettere å lese. Det viser også at skriveren tar leseren på alvor.', array['Forklarer at teksten blir lettere å lese.', 'Forklarer at riktig språk viser hensyn til leseren.']::text[], 0),
  ('norsk-8:rettskriving-og-tegnsetting', 's02', 'Forklar forskjellen på «å» og «og» i setningen «Jeg liker å lese og skrive».', '«Å» står foran verbet «lese» og er infinitivsmerke. «Og» binder sammen verbene «lese» og «skrive».', array['Forklarer at «å» står foran et verb i infinitiv.', 'Forklarer at «og» binder sammen ord eller setninger.']::text[], 1),
  ('norsk-8:rettskriving-og-tegnsetting', 's03', 'Fyll inn «de» eller «dem» i setningen, og forklar hvordan du kan kontrollere valget: «___ snakket med ___ etter kampen.»', 'De snakket med dem etter kampen. «De» passer fordi «vi» kan stå der, mens «dem» står etter preposisjonen «med» og kan byttes med «oss».', array['Bruker «de» som subjekt og «dem» etter «med».', 'Bruker eller forklarer vi/oss-testen riktig.']::text[], 2),
  ('norsk-8:rettskriving-og-tegnsetting', 's04', 'Sammenlign skrivemåten «tak» og «takk». Forklar hvordan vokallengden henger sammen med enkel eller dobbel konsonant.', 'I «tak» er vokalen lang, og derfor står det én k. I «takk» er vokalen kort, og derfor står det som regel dobbel k.', array['Knytter lang vokal til enkel konsonant i «tak».', 'Knytter kort vokal til dobbel konsonant i «takk».']::text[], 3),
  ('norsk-8:rettskriving-og-tegnsetting', 's05', 'Hva er stum h? Bruk «hva» og «hjelp» til å forklare hvor h-en står i ordene.', 'Stum h er en h som skrives, men ikke uttales. I «hva» står den først i bokstavkombinasjonen «hv», og i «hjelp» står den først i «hj».', array['Forklarer at stum h ikke uttales.', 'Viser at h står i «hv» i «hva» og «hj» i «hjelp».']::text[], 4),
  ('norsk-8:rettskriving-og-tegnsetting', 's06', 'Skriv «fotball trening» riktig, og forklar hvorfor ordene skal skrives slik på norsk.', 'Det skal skrives «fotballtrening». Sammensatte ord skrives i ett ord på norsk.', array['Skriver «fotballtrening» i ett ord.', 'Forklarer at sammensatte ord skrives sammen.']::text[], 5),
  ('norsk-8:rettskriving-og-tegnsetting', 's07', 'Skriv setningen riktig med store og små forbokstaver: «på mandag i mai møter jeg en nordmann som snakker norsk.» Forklar hvorfor «mandag», «mai», «nordmann» og «norsk» har liten forbokstav.', 'På mandag i mai møter jeg en nordmann som snakker norsk. Dager, måneder, språk og nasjonaliteter skrives med liten forbokstav.', array['Begynner setningen med stor forbokstav.', 'Forklarer at dag, måned, språk og nasjonalitet skrives med liten forbokstav.']::text[], 6),
  ('norsk-8:rettskriving-og-tegnsetting', 's08', 'Sett inn komma der det trengs i disse setningene, og forklar forskjellen: «Det regnet men vi gikk tur.» «Jeg tror at det blir fint.»', 'Det regnet, men vi gikk tur. Jeg tror at det blir fint. Den første setningen har to helsetninger bundet sammen med «men», mens det ikke skal stå komma foran «at» i den andre.', array['Setter komma foran «men» fordi det binder sammen to helsetninger.', 'Lar være å sette komma foran «at» i den andre setningen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-8:sammensatte-tekster', 'norsk-8', 'sammensatte-tekster', 'Sammensatte tekster', 'Tekster som kombinerer skrift, bilde, lyd og layout – hvordan de ulike uttrykksformene spiller sammen, og hvordan du lager og begrunner egne sammensatte tekster.', array[14, 6]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-8:sammensatte-tekster', '## Hva er en sammensatt tekst?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-8:sammensatte-tekster', 'Sammensatt tekst', 'En tekst som kombinerer flere uttrykksformer, som skrift, bilde, lyd og layout.', 0),
  ('norsk-8:sammensatte-tekster', 'Uttrykksform (modalitet)', 'En måte å formidle på: skrift, bilde, lyd, farge, bevegelse.', 1),
  ('norsk-8:sammensatte-tekster', 'Forsterke', 'Når bilde og tekst sier det samme og styrker budskapet.', 2),
  ('norsk-8:sammensatte-tekster', 'Utfylle', 'Når bilde og tekst gir hver sin del av informasjonen.', 3),
  ('norsk-8:sammensatte-tekster', 'Kontrast mellom bilde og tekst', 'Når bilde og tekst spiller mot hverandre, ofte for humor eller ironi.', 4),
  ('norsk-8:sammensatte-tekster', 'Nærbilde', 'Viser detaljer og følelser, for eksempel et ansikt.', 5),
  ('norsk-8:sammensatte-tekster', 'Totalbilde', 'Viser hele miljøet og sammenhengen.', 6),
  ('norsk-8:sammensatte-tekster', 'Froskeperspektiv', 'Motivet sett nedenfra. Får det til å virke stort og mektig.', 7),
  ('norsk-8:sammensatte-tekster', 'Fugleperspektiv', 'Motivet sett ovenfra. Får det til å virke lite eller sårbart.', 8),
  ('norsk-8:sammensatte-tekster', 'Blikkfang', 'Det som først fanger leserens oppmerksomhet.', 9),
  ('norsk-8:sammensatte-tekster', 'Layout', 'Hvordan tekst, bilder og luft er plassert på en side eller skjerm.', 10),
  ('norsk-8:sammensatte-tekster', 'Typografi', 'Valg av skrifttype, størrelse og stil.', 11),
  ('norsk-8:sammensatte-tekster', 'Slagord (slogan)', 'En kort, fengende setning i reklame som skal huskes.', 12),
  ('norsk-8:sammensatte-tekster', 'Komposisjon', 'Hvordan elementene i et bilde er plassert i forhold til hverandre.', 13),
  ('norsk-8:sammensatte-tekster', 'Begrunne valg', 'Forklare hvorfor du valgte bilder, farger og skrift, og hvordan de støtter budskapet.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-8:sammensatte-tekster', 'q01', 'flervalg', 'Hvilken tekst er en sammensatt tekst?', array['En reklameplakat med bilde og slagord', 'En lydløs tanke', 'En tom side', 'Et enkelt ord']::text[], 0, 'Reklameplakaten kombinerer bilde, skrift og layout, altså flere uttrykksformer.', true, true, 0),
  ('norsk-8:sammensatte-tekster', 'q02', 'flervalg', 'Et bilde er tatt nedenfra og får en person til å virke mektig. Hva kalles perspektivet?', array['Fugleperspektiv', 'Normalperspektiv', 'Froskeperspektiv', 'Nærbilde']::text[], 2, 'Froskeperspektiv er sett nedenfra og gir inntrykk av styrke og makt.', true, true, 1),
  ('norsk-8:sammensatte-tekster', 'q03', 'flervalg', 'Hva viser et nærbilde best?', array['Hele landskapet', 'Følelser og detaljer', 'Hvor mange personer som er til stede', 'Været']::text[], 1, 'Et nærbilde av et ansikt får fram følelser som ellers lett forsvinner.', true, true, 2),
  ('norsk-8:sammensatte-tekster', 'q04', 'flervalg', 'Bildet viser et øsende regnvær, mens teksten sier «Perfekt dag for piknik!». Hvordan spiller bilde og tekst sammen?', array['De forsterker hverandre', 'De utfyller hverandre', 'De er like', 'De står i kontrast og skaper ironi']::text[], 3, 'Bildet og teksten sier motsatte ting, og kontrasten skaper humor.', true, true, 3),
  ('norsk-8:sammensatte-tekster', 'q05', 'flervalg', 'Hva er layout?', array['Valg av farger i et maleri', 'Hvordan elementene er plassert på en side', 'Et reklameslagord', 'En type skrift']::text[], 1, 'Layout handler om plassering av tekst, bilder og luft, og styrer hvordan vi leser siden.', true, true, 4),
  ('norsk-8:sammensatte-tekster', 'q06', 'flervalg', 'Hva er typografi?', array['Valg av skrifttype, størrelse og stil', 'Et fotografi', 'En logo', 'En bildetekst']::text[], 0, 'Typografi er alt som har med utseendet til bokstavene å gjøre.', true, false, 5),
  ('norsk-8:sammensatte-tekster', 'q07', 'flervalg', 'Hvilken appellform bruker reklame ofte mest?', array['Logos', 'Etos', 'Patos', 'Ingen']::text[], 2, 'Reklame spiller ofte på følelser, som glede, lengsel eller frykt for å gå glipp av noe.', true, true, 6),
  ('norsk-8:sammensatte-tekster', 'q08', 'flervalg', 'Hva er et godt råd når du lager en lysbildepresentasjon?', array['Skriv hele manuset på lysbildene', 'Bruk så mange skrifttyper som mulig', 'Unngå bilder', 'Bruk lite tekst og bilder som støtter det du sier']::text[], 3, 'Lysbildene skal støtte det du sier, ikke erstatte det. For mye tekst gjør at publikum leser i stedet for å lytte.', true, true, 7),
  ('norsk-8:sammensatte-tekster', 'q09', 'flervalg', 'Hva kalles det som først fanger oppmerksomheten på en plakat?', array['Blikkfang', 'Slagord', 'Utsnitt', 'Kildehenvisning']::text[], 0, 'Blikkfanget kan være et stort bilde, en sterk farge eller en stor overskrift.', true, false, 8),
  ('norsk-8:sammensatte-tekster', 'q10', 'flervalg', 'Hvorfor bør du kunne begrunne valgene i en sammensatt tekst?', array['For å vise at du forstår hvordan valgene støtter budskapet', 'Fordi det gjør teksten lengre', 'Fordi bilder alltid er viktigst', 'For å slippe å oppgi kilder']::text[], 0, 'Begrunnelser viser at du har tenkt bevisst over formål, mottaker og virkemidler.', true, true, 9),
  ('norsk-8:sammensatte-tekster', 'm01', 'sant-usant', 'En tegneserie er en sammensatt tekst.', array['Sant', 'Usant']::text[], 0, 'Tegneserier kombinerer tegninger og skrift, ofte med snakkebobler og lydord.', false, true, 10),
  ('norsk-8:sammensatte-tekster', 'm02', 'sant-usant', 'Fugleperspektiv får motivet til å virke stort og mektig.', array['Sant', 'Usant']::text[], 1, 'Fugleperspektiv er sett ovenfra og får motivet til å virke lite. Froskeperspektiv gir inntrykk av makt.', false, true, 11),
  ('norsk-8:sammensatte-tekster', 'm03', 'sant-usant', 'Du bør oppgi kilder til bilder du bruker i en presentasjon.', array['Sant', 'Usant']::text[], 0, 'Bilder er andres åndsverk, og kildehenvisning viser hvor de kommer fra.', false, true, 12),
  ('norsk-8:sammensatte-tekster', 'm04', 'sant-usant', 'Valg av skrifttype har ingen betydning for hvordan en tekst oppfattes.', array['Sant', 'Usant']::text[], 1, 'Typografi påvirker stemningen. En leken skrift passer dårlig til en alvorlig nyhet.', false, true, 13),
  ('norsk-8:sammensatte-tekster', 'm05', 'flervalg', 'Hvilken farge forbindes ofte med ro?', array['Rødt', 'Oransje', 'Blått', 'Gult']::text[], 2, 'Kalde farger som blått forbindes ofte med ro, avstand eller tristhet.', false, true, 14),
  ('norsk-8:sammensatte-tekster', 'm06', 'flervalg', 'Hva gjør et totalbilde?', array['Viser et ansikt tett på', 'Viser hele miljøet og sammenhengen', 'Viser bare en detalj', 'Viser motivet ovenfra']::text[], 1, 'Totalbildet gir oversikt over stedet og situasjonen.', false, true, 15),
  ('norsk-8:sammensatte-tekster', 'm07', 'flervalg', 'Hva er et slagord?', array['En kort, fengende setning i reklame', 'En lang fagtekst', 'En bildetekst med kilde', 'En overskrift i en nyhetssak']::text[], 0, 'Slagordet skal være lett å huske og knytte seg til produktet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-8:sammensatte-tekster', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-8:sammensatte-tekster', 's01', 'Forklar forskjellen på at bilde og tekst forsterker hverandre, og at de utfyller hverandre.', 'De forsterker hverandre når de formidler det samme budskapet. De utfyller hverandre når bildet og teksten gir ulike deler av informasjonen.', array['Forklarer at forsterking betyr at bilde og tekst formidler det samme.', 'Forklarer at utfylling betyr at bilde og tekst gir ulik informasjon.']::text[], 0),
  ('norsk-8:sammensatte-tekster', 's02', 'Sammenlign fugleperspektiv og froskeperspektiv: Hvordan kan motivet virke i hvert av perspektivene?', 'I fugleperspektiv, der motivet ses ovenfra, kan det virke lite eller sårbart. I froskeperspektiv, der motivet ses nedenfra, kan det virke stort og mektig.', array['Knytter fugleperspektiv til at motivet kan virke lite eller sårbart.', 'Knytter froskeperspektiv til at motivet kan virke stort eller mektig.']::text[], 1),
  ('norsk-8:sammensatte-tekster', 's03', 'Du skal lage en plakat til en barnebursdag. Hvorfor passer en leken skrifttype bedre enn en slik skrifttype i en nyhetssak?', 'En leken skrifttype passer til den muntre stemningen i en barnebursdag. I en nyhetssak passer den dårligere fordi skrifttypen bør passe til innholdet og situasjonen.', array['Forklarer at den lekne skrifttypen passer til barnebursdagen eller stemningen der.', 'Viser at skrifttypen bør passe til innholdet, og at den derfor passer dårligere i en nyhetssak.']::text[], 2),
  ('norsk-8:sammensatte-tekster', 's04', 'En plakat har mange elementer, og det er vanskelig å se hva som er viktigst. Nevn ett grep med plassering, luft eller kontraster som kan gjøre hovedbudskapet lettere å legge merke til, og forklar virkningen.', 'Jeg kan bruke en stor overskrift og la det være luft rundt den. Da trekkes blikket mot overskriften først.', array['Foreslår et relevant grep med plassering, luft, størrelse eller kontraster.', 'Forklarer hvordan grepet styrer blikket mot det viktigste innholdet.']::text[], 3),
  ('norsk-8:sammensatte-tekster', 's05', 'Du lager en plakat for en skoleaktivitet. Beskriv et eksempel på hvordan bildet og teksten kan utfylle hverandre ved å gi ulik informasjon.', 'Teksten kan fortelle når og hvor aktiviteten skjer, mens bildet viser hva slags aktivitet det er. Da gir bildet og teksten hver sin del av informasjonen.', array['Gir bilde og tekst ulike oppgaver eller ulik informasjon.', 'Forklarer at delene sammen gir leseren mer informasjon.']::text[], 4),
  ('norsk-8:sammensatte-tekster', 's06', 'Du lager en presentasjon som skal gi et rolig inntrykk. Hvilke farger kan du velge, og hvilken virkning kan de ha?', 'Jeg kan velge kalde farger som blått. Slike farger kan gi et rolig inntrykk.', array['Velger kalde farger, for eksempel blått.', 'Knytter fargene til en rolig virkning.']::text[], 5),
  ('norsk-8:sammensatte-tekster', 's07', 'En reklame bruker et bilde som skal vekke glede hos dem som ser den. Forklar hvordan følelsen kan hjelpe reklamen med å nå målet sitt.', 'Glede kan få mottakeren til å føle seg positiv til det reklamen viser. Reklamen bruker følelsen for å få mottakeren til å kjøpe noe.', array['Forklarer at bildet skal vekke en følelse hos mottakeren.', 'Knytter følelsen til målet om å få mottakeren til å kjøpe noe.']::text[], 6),
  ('norsk-8:sammensatte-tekster', 's08', 'Du lager en presentasjon og bruker et bilde og noen opplysninger du har funnet. Hva bør du gjøre for å vise hvor bildet og opplysningene kommer fra?', 'Jeg bør oppgi kildene til både bildet og opplysningene. Da viser jeg hvor materialet kommer fra.', array['Nevner at kilden til bildet bør oppgis.', 'Nevner at kilden til opplysningene bør oppgis.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-8:nynorsk-grunnkurs', 'norsk-8', 'nynorsk-grunnkurs', 'Nynorsk: grunnkurs', 'De vanligste ordene og bøyningsmønstrene i nynorsk – pronomen, spørreord, substantiv og verb – for deg som har bokmål som hovedmål.', array[11, 1]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-8:nynorsk-grunnkurs', '## Sidemål
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-8:nynorsk-grunnkurs', 'eg', 'Nynorsk for «jeg».', 0),
  ('norsk-8:nynorsk-grunnkurs', 'ikkje', 'Nynorsk for «ikke».', 1),
  ('norsk-8:nynorsk-grunnkurs', 'ho', 'Nynorsk for «hun». Objektsform: henne (eller ho).', 2),
  ('norsk-8:nynorsk-grunnkurs', 'dei', 'Nynorsk for «de/dem» i tredje person flertall.', 3),
  ('norsk-8:nynorsk-grunnkurs', 'dykk', 'Nynorsk objektsform av «de» i andre person flertall (bokmål: dere).', 4),
  ('norsk-8:nynorsk-grunnkurs', 'kva, kven, kvar', 'Nynorsk for hva, hvem og hvor.', 5),
  ('norsk-8:nynorsk-grunnkurs', 'korleis og kvifor', 'Nynorsk for hvordan og hvorfor.', 6),
  ('norsk-8:nynorsk-grunnkurs', 'berre og mykje', 'Nynorsk for bare og mye.', 7),
  ('norsk-8:nynorsk-grunnkurs', 'ein, ei, eit', 'Ubestemte artikler i hankjønn, hokjønn og inkjekjønn.', 8),
  ('norsk-8:nynorsk-grunnkurs', 'Hankjønn', 'ein gut – guten – gutar – gutane', 9),
  ('norsk-8:nynorsk-grunnkurs', 'Hokjønn', 'ei jente – jenta – jenter – jentene', 10),
  ('norsk-8:nynorsk-grunnkurs', 'Inkjekjønn', 'eit hus – huset – hus – husa', 11),
  ('norsk-8:nynorsk-grunnkurs', 'a-verb', 'å kaste – kastar – kasta – har kasta', 12),
  ('norsk-8:nynorsk-grunnkurs', 'e-verb', 'å kjøpe – kjøper – kjøpte – har kjøpt', 13),
  ('norsk-8:nynorsk-grunnkurs', 'e- eller a-infinitiv', 'Du kan skrive «å kaste» eller «å kasta», men må være konsekvent.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-8:nynorsk-grunnkurs', 'q01', 'flervalg', 'Hva heter «jeg» på nynorsk?', array['je', 'eg', 'ek', 'jeg']::text[], 1, '«Eg» er nynorsk for «jeg».', true, true, 0),
  ('norsk-8:nynorsk-grunnkurs', 'q02', 'flervalg', 'Hva heter «hvordan» på nynorsk?', array['kvordan', 'korleis', 'kvifor', 'kven']::text[], 1, '«Korleis» betyr hvordan. «Kvifor» er hvorfor, og «kven» er hvem.', true, true, 1),
  ('norsk-8:nynorsk-grunnkurs', 'q03', 'flervalg', 'Hva er bestemt form flertall av «gut» på nynorsk?', array['gutene', 'gutar', 'gutane', 'gutter']::text[], 2, 'Hankjønn: ein gut – guten – gutar – gutane.', true, true, 2),
  ('norsk-8:nynorsk-grunnkurs', 'q04', 'flervalg', 'Hva er presens av a-verbet «å kaste» på nynorsk?', array['kastar', 'kaster', 'kasta', 'kast']::text[], 0, 'a-verb får -ar i presens: eg kastar.', true, true, 3),
  ('norsk-8:nynorsk-grunnkurs', 'q05', 'flervalg', 'Hva heter «hun» på nynorsk?', array['hu', 'hon', 'ho', 'hun']::text[], 2, '«Ho» er nynorsk for «hun».', true, true, 4),
  ('norsk-8:nynorsk-grunnkurs', 'q06', 'flervalg', 'Hva er bestemt form flertall av «hus» på nynorsk?', array['husene', 'husa', 'husane', 'hus']::text[], 1, 'Inkjekjønn: eit hus – huset – hus – husa.', true, true, 5),
  ('norsk-8:nynorsk-grunnkurs', 'q07', 'flervalg', 'Hvilken setning er skrevet på nynorsk?', array['Jeg vet ikke hva hun heter.', 'Eg veit ikkje kva ho heiter.', 'Eg vet ikke hva ho heter.', 'Jeg veit ikkje kva hun heiter.']::text[], 1, 'Alle ordene er på nynorsk: eg, veit, ikkje, kva, ho, heiter.', true, true, 6),
  ('norsk-8:nynorsk-grunnkurs', 'q08', 'flervalg', 'Hva er preteritum av e-verbet «å kjøpe»?', array['kjøpa', 'kjøpar', 'kjøpet', 'kjøpte']::text[], 3, 'e-verb: å kjøpe – kjøper – kjøpte – har kjøpt.', true, true, 7),
  ('norsk-8:nynorsk-grunnkurs', 'q09', 'flervalg', 'Hva betyr «dei» på nynorsk?', array['de/dem i tredje person flertall', 'deg', 'denne', 'det']::text[], 0, '«Dei» brukes både som subjekt og objekt: Dei kom. Eg såg dei.', true, false, 8),
  ('norsk-8:nynorsk-grunnkurs', 'q10', 'flervalg', 'Hva gjelder for valg av infinitivsending i nynorsk?', array['Du må alltid bruke -a', 'Du må alltid bruke -e', 'Du kan velge -e eller -a, men må være konsekvent', 'Du kan blande fritt']::text[], 2, 'Både e-infinitiv og a-infinitiv er tillatt, men du må holde deg til én i samme tekst.', true, false, 9),
  ('norsk-8:nynorsk-grunnkurs', 'm01', 'sant-usant', 'Bokmål og nynorsk er likestilte skriftspråk.', array['Sant', 'Usant']::text[], 0, 'Begge er offisielle skriftformer av norsk og er likestilte.', false, true, 10),
  ('norsk-8:nynorsk-grunnkurs', 'm02', 'sant-usant', '«Ikkje» er nynorsk for «ikke».', array['Sant', 'Usant']::text[], 0, 'Ikkje er den nynorske formen.', false, true, 11),
  ('norsk-8:nynorsk-grunnkurs', 'm03', 'sant-usant', 'Hokjønn kan sløyfes på nynorsk, slik som på bokmål.', array['Sant', 'Usant']::text[], 1, 'Nynorsk har alltid tre kjønn, og hokjønnsord får «ei» og -a i bestemt form.', false, true, 12),
  ('norsk-8:nynorsk-grunnkurs', 'm04', 'sant-usant', '«Kvifor» betyr hvorfor.', array['Sant', 'Usant']::text[], 0, 'Kvifor = hvorfor. Korleis = hvordan.', false, true, 13),
  ('norsk-8:nynorsk-grunnkurs', 'm05', 'flervalg', 'Hva heter «bare» på nynorsk?', array['bara', 'berre', 'bere', 'bære']::text[], 1, '«Berre» er nynorsk for bare.', false, true, 14),
  ('norsk-8:nynorsk-grunnkurs', 'm06', 'flervalg', 'Hvilken artikkel står foran hokjønnsordet «jente»?', array['ein', 'eit', 'ei', 'en']::text[], 2, 'Hokjønn har artikkelen «ei»: ei jente.', false, true, 15),
  ('norsk-8:nynorsk-grunnkurs', 'm07', 'flervalg', 'Hva er presens av «å skrive» på nynorsk?', array['skriv', 'skrivar', 'skriver', 'skreiv']::text[], 0, 'Sterke verb har ofte ingen ending i presens på nynorsk: eg skriv.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-8:nynorsk-grunnkurs', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-8:nynorsk-grunnkurs', 's01', 'Forklar forskjellen på hovedmål og sidemål. Ta også med hva alle elever skal lære fra 8. trinn.', 'Hovedmålet er skriftspråket du bruker mest, og sidemålet er det andre skriftspråket. Fra 8. trinn skal alle lære å skrive både bokmål og nynorsk.', array['Forklarer at hovedmålet er skriftspråket man bruker mest, og sidemålet er det andre.', 'Får fram at alle skal lære å skrive både bokmål og nynorsk fra 8. trinn.']::text[], 0),
  ('norsk-8:nynorsk-grunnkurs', 's02', 'Mange nynorske ord ligner på bokmålsord, men noen småord og bøyningsendinger skiller seg ut. Forklar hvorfor det er nyttig å lære nettopp disse formene.', 'Småord og bøyningsendinger er blant forskjellene man ofte møter. Når man lærer dem, har man kommet langt i å skrive nynorsk.', array['Får fram at småord og bøyningsendinger er viktige kjennetegn som skiller nynorsk fra bokmål.', 'Forklarer at det å lære disse formene hjelper en godt på vei med nynorsken.']::text[], 1),
  ('norsk-8:nynorsk-grunnkurs', 's03', 'En elev blander «dei» og «dykk». Forklar forskjellen på hvem pronomenene viser til, og hvilken form «dykk» er.', '«Dei» viser til personer i tredje person flertall. «Dykk» er objektsformen av «de» i andre person flertall, altså bokmålsformen «dere».', array['Forklarer at «dei» viser til tredje person flertall.', 'Forklarer at «dykk» er objektsform i andre person flertall.']::text[], 2),
  ('norsk-8:nynorsk-grunnkurs', 's04', 'Skriv substantivene «gut», «jente» og «hus» på nynorsk i ubestemt form, hver med riktig artikkel. Forklar hva artiklene viser.', 'Det heter ein gut, ei jente og eit hus. Artiklene viser hankjønn, hokjønn og inkjekjønn.', array['Bruker riktig artikkel til alle tre substantivene.', 'Knytter ein, ei og eit til henholdsvis hankjønn, hokjønn og inkjekjønn.']::text[], 3),
  ('norsk-8:nynorsk-grunnkurs', 's05', 'En elev skriver «Eg likar å kasta ball og å lese». Skriv setningen på nytt med konsekvent infinitivform, og forklar hva du endret.', 'Eg likar å kasta ball og å lesa. Jeg endret «å lese» til «å lesa», slik at begge infinitivene har a-infinitiv.', array['Skriver begge infinitivene konsekvent med samme type infinitiv, enten e-infinitiv eller a-infinitiv.', 'Forklarer at infinitivformene må være konsekvente i teksten.']::text[], 4),
  ('norsk-8:nynorsk-grunnkurs', 's06', 'Forklar hva som kjennetegner sterke verb, og bruk «å skrive» som eksempel ved å vise bøyningen.', 'Sterke verb skifter vokal når de bøyes. «Å skrive» bøyes skriv – skreiv – har skrive.', array['Forklarer at sterke verb skifter vokal.', 'Gir riktig bøyning av «å skrive».']::text[], 5),
  ('norsk-8:nynorsk-grunnkurs', 's07', 'Du er usikker på om et ord er riktig skrevet på nynorsk, og retteprogrammet foreslår en endring. Beskriv to ting du kan gjøre for å kontrollere teksten.', 'Jeg kan slå opp ordet i en nynorsk ordbok, for eksempel Nynorskordboka. Jeg kan også bruke nynorsk retteprogram og lese over selv.', array['Nevner å slå opp i en nynorsk ordbok eller å bruke nynorsk retteprogram.', 'Får fram at man bør lese over selv, også når man bruker retteprogram.']::text[], 6),
  ('norsk-8:nynorsk-grunnkurs', 's08', 'En elev skal skrive «hjemme», «spørre» og «kjærlighet» på nynorsk. Skriv nynorskformene, og forklar hvorfor det kan være lurt å lære slike egne former.', 'Formene er heime, spørje og kjærleik. Det er nyttig å lære dem fordi noen ord har egne nynorske former og ikke bør oversettes ord for ord fra bokmål.', array['Gir de nynorske formene heime, spørje og kjærleik.', 'Forklarer at noen ord har egne nynorske former, så ord-for-ord-oversettelse fra bokmål kan bli feil.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-8:potenser-og-kvadratrotter', 'matematikk-8', 'potenser-og-kvadratrotter', 'Potenser og kvadratrøtter', 'Hva en potens er, regnereglene for potenser, tall på standardform og hvordan du finner og anslår kvadratrøtter.', array[1]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-8:potenser-og-kvadratrotter', '## Hva er en potens?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-8:potenser-og-kvadratrotter', 'Potens', 'En kort skrivemåte for gjentatt multiplikasjon, for eksempel 2⁵ = 2 · 2 · 2 · 2 · 2.', 0),
  ('matematikk-8:potenser-og-kvadratrotter', 'Grunntall', 'Tallet som ganges med seg selv i en potens. I 4³ er grunntallet 4.', 1),
  ('matematikk-8:potenser-og-kvadratrotter', 'Eksponent', 'Det lille tallet oppe til høyre i en potens. Det viser hvor mange ganger grunntallet ganges med seg selv.', 2),
  ('matematikk-8:potenser-og-kvadratrotter', 'Kvadrattall', 'Et helt tall opphøyd i andre, for eksempel 1, 4, 9, 16, 25 og 36.', 3),
  ('matematikk-8:potenser-og-kvadratrotter', 'Kubikktall', 'Et helt tall opphøyd i tredje, for eksempel 8 = 2³ og 27 = 3³.', 4),
  ('matematikk-8:potenser-og-kvadratrotter', 'aᵐ · aⁿ', 'Ved multiplikasjon av potenser med samme grunntall legges eksponentene sammen: aᵐ · aⁿ = aᵐ⁺ⁿ.', 5),
  ('matematikk-8:potenser-og-kvadratrotter', 'aᵐ : aⁿ', 'Ved divisjon av potenser med samme grunntall trekkes eksponentene fra hverandre: aᵐ : aⁿ = aᵐ⁻ⁿ.', 6),
  ('matematikk-8:potenser-og-kvadratrotter', '(aᵐ)ⁿ', 'En potens opphøyd i en ny eksponent: eksponentene ganges. (2³)² = 2⁶.', 7),
  ('matematikk-8:potenser-og-kvadratrotter', 'a⁰', 'Alle tall unntatt 0 opphøyd i null er lik 1. For eksempel er 7⁰ = 1.', 8),
  ('matematikk-8:potenser-og-kvadratrotter', 'Tierpotens', 'En potens med grunntall 10. Eksponenten viser antall nuller: 10⁴ = 10 000.', 9),
  ('matematikk-8:potenser-og-kvadratrotter', 'Standardform', 'Et tall skrevet som a · 10ⁿ, der a er mellom 1 og 10. For eksempel er 350 000 = 3,5 · 10⁵.', 10),
  ('matematikk-8:potenser-og-kvadratrotter', 'Kvadratrot', 'Det positive tallet som ganget med seg selv gir tallet. √36 = 6 fordi 6 · 6 = 36.', 11),
  ('matematikk-8:potenser-og-kvadratrotter', '(−3)² og −3²', '(−3)² = 9 fordi parentesen tar med minustegnet. −3² = −9 fordi bare 3 opphøyes.', 12),
  ('matematikk-8:potenser-og-kvadratrotter', 'Anslå en kvadratrot', 'Finn de to nærmeste kvadrattallene. √50 ligger mellom 7 og 8 fordi 49 < 50 < 64.', 13),
  ('matematikk-8:potenser-og-kvadratrotter', 'Regnerekkefølge', 'Parenteser først, så potenser og røtter, så multiplikasjon og divisjon, og til slutt addisjon og subtraksjon.', 14),
  ('matematikk-8:potenser-og-kvadratrotter', 'Opphøye i andre', 'Å gange et tall med seg selv. Det motsatte er å ta kvadratroten.', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-8:potenser-og-kvadratrotter', 'q01', 'flervalg', 'Hva er 3⁴?', array['12', '81', '64', '27']::text[], 1, '3⁴ = 3 · 3 · 3 · 3 = 81. Svaret 12 får du hvis du ganger grunntallet med eksponenten, og det er en vanlig feil.', true, true, 0),
  ('matematikk-8:potenser-og-kvadratrotter', 'q02', 'flervalg', 'Hvilken potens er det samme som 5 · 5 · 5?', array['5³', '3⁵', '15', '5 · 3']::text[], 0, 'Grunntallet 5 ganges med seg selv tre ganger, så eksponenten er 3: 5 · 5 · 5 = 5³ = 125.', true, false, 1),
  ('matematikk-8:potenser-og-kvadratrotter', 'q03', 'flervalg', 'Forenkle 2³ · 2⁴.', array['2¹²', '4⁷', '2⁷', '2¹']::text[], 2, 'Potensene har samme grunntall, så eksponentene legges sammen: 3 + 4 = 7. Grunntallet endres ikke.', true, true, 2),
  ('matematikk-8:potenser-og-kvadratrotter', 'q04', 'flervalg', 'Hva er 10⁶?', array['60', '100 000', '10 000 000', '1 000 000']::text[], 3, 'Eksponenten 6 betyr seks nuller etter 1-tallet: 10⁶ = 1 000 000, altså én million.', true, true, 3),
  ('matematikk-8:potenser-og-kvadratrotter', 'q05', 'flervalg', 'Hva er √64?', array['32', '8', '16', '4']::text[], 1, '8 · 8 = 64, så kvadratroten av 64 er 8. Å halvere tallet (32) gir ikke kvadratroten.', true, true, 4),
  ('matematikk-8:potenser-og-kvadratrotter', 'q06', 'flervalg', 'Hva er 9⁰?', array['0', '9', '1', 'Det er ikke definert']::text[], 2, 'Alle tall unntatt 0 opphøyd i null er 1. Det følger av divisjonsregelen: 9² : 9² = 9⁰, og et tall delt på seg selv er 1.', true, false, 5),
  ('matematikk-8:potenser-og-kvadratrotter', 'q07', 'flervalg', 'Hva er −2⁴?', array['−16', '16', '−8', '8']::text[], 0, 'Uten parentes regnes potensen ut først: 2⁴ = 16. Deretter brukes minustegnet, så svaret er −16.', true, true, 6),
  ('matematikk-8:potenser-og-kvadratrotter', 'q08', 'flervalg', 'Hvordan skrives 4 700 000 på standardform?', array['47 · 10⁵', '4,7 · 10⁶', '0,47 · 10⁷', '4,7 · 10⁵']::text[], 1, 'På standardform skal tallet foran tierpotensen være mellom 1 og 10. Kommaet flyttes seks plasser: 4 700 000 = 4,7 · 10⁶.', true, true, 7),
  ('matematikk-8:potenser-og-kvadratrotter', 'q09', 'flervalg', 'Mellom hvilke to hele tall ligger √40?', array['4 og 5', '5 og 6', '6 og 7', '7 og 8']::text[], 2, 'De nærmeste kvadrattallene er 36 = 6² og 49 = 7². Siden 36 < 40 < 49, ligger √40 mellom 6 og 7.', true, true, 8),
  ('matematikk-8:potenser-og-kvadratrotter', 'q10', 'flervalg', 'Regn ut 2 + 3 · 4².', array['80', '196', '146', '50']::text[], 3, 'Potensen først: 4² = 16. Så multiplikasjonen: 3 · 16 = 48. Til slutt addisjonen: 2 + 48 = 50.', true, true, 9),
  ('matematikk-8:potenser-og-kvadratrotter', 'm01', 'sant-usant', '2⁵ er det samme som 2 · 5.', array['Sant', 'Usant']::text[], 1, '2⁵ betyr at 2 ganges med seg selv fem ganger: 2⁵ = 32. Men 2 · 5 = 10.', false, true, 10),
  ('matematikk-8:potenser-og-kvadratrotter', 'm02', 'sant-usant', '(−5)² = 25.', array['Sant', 'Usant']::text[], 0, 'Parentesen gjør at hele −5 opphøyes: (−5) · (−5) = 25, fordi minus ganger minus gir pluss.', false, true, 11),
  ('matematikk-8:potenser-og-kvadratrotter', 'm03', 'sant-usant', '√100 = 50.', array['Sant', 'Usant']::text[], 1, '√100 = 10 fordi 10 · 10 = 100. Kvadratroten er ikke det samme som halvparten.', false, true, 12),
  ('matematikk-8:potenser-og-kvadratrotter', 'm04', 'sant-usant', '7³ : 7 = 7².', array['Sant', 'Usant']::text[], 0, '7 er det samme som 7¹. Ved divisjon trekkes eksponentene fra hverandre: 3 − 1 = 2.', false, true, 13),
  ('matematikk-8:potenser-og-kvadratrotter', 'm05', 'flervalg', 'Forenkle (3²)³.', array['3⁵', '3⁶', '9⁵', '3⁸']::text[], 1, 'Når en potens opphøyes i en ny eksponent, ganges eksponentene: 2 · 3 = 6. Svaret er 3⁶.', false, true, 14),
  ('matematikk-8:potenser-og-kvadratrotter', 'm06', 'flervalg', 'Hvilket av tallene er et kvadrattall?', array['50', '60', '72', '81']::text[], 3, '81 = 9 · 9 = 9². Ingen av de andre tallene kan skrives som et helt tall ganget med seg selv.', false, true, 15),
  ('matematikk-8:potenser-og-kvadratrotter', 'm07', 'flervalg', 'Hva er 6,2 · 10³ skrevet som et vanlig tall?', array['6200', '620', '62 000', '6,2000']::text[], 0, 'Å gange med 10³ = 1000 flytter kommaet tre plasser mot høyre: 6,2 · 1000 = 6200.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-8:potenser-og-kvadratrotter', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-8:potenser-og-kvadratrotter', 's01', 'I potensen 4³, hva er grunntallet og hva er eksponenten? Forklar hva eksponenten forteller, og skriv potensen som gjentatt multiplikasjon.', 'Grunntallet er 4, og eksponenten er 3. Eksponenten forteller at 4 skal ganges med seg selv tre ganger: 4 · 4 · 4.', array['Identifiserer 4 som grunntallet og 3 som eksponenten.', 'Forklarer at eksponenten viser antall faktorer av grunntallet og skriver 4 · 4 · 4.']::text[], 0),
  ('matematikk-8:potenser-og-kvadratrotter', 's02', 'Regn ut 3² · 3³. Vis hvordan du bruker regneregelen for multiplikasjon av potenser med samme grunntall.', 'Når grunntallene er like, legger vi sammen eksponentene: 3² · 3³ = 3⁵ = 243.', array['Legger sammen eksponentene og får 3⁵.', 'Finner riktig svar, 243.']::text[], 1),
  ('matematikk-8:potenser-og-kvadratrotter', 's03', 'Regn ut 6⁴ : 6². Vis hvilket steg du bruker for å forenkle potensene før du finner svaret.', 'Ved divisjon av potenser med samme grunntall trekker vi eksponentene fra hverandre: 6⁴ : 6² = 6² = 36.', array['Trekker eksponentene fra hverandre og får 6².', 'Finner riktig svar, 36.']::text[], 2),
  ('matematikk-8:potenser-og-kvadratrotter', 's04', 'Sammenlign (−4)² og −4². Forklar hvorfor svarene blir ulike, og regn ut begge.', '(−4)² = 16 fordi minustegnet er med i parentesen og hele −4 ganges med seg selv. I −4² opphøyes bare 4 i andre før minustegnet brukes, så svaret er −16.', array['Får fram at parentesen gjør at minustegnet inngår i grunntallet i (−4)².', 'Oppgir riktig resultat for begge uttrykkene: 16 og −16.']::text[], 3),
  ('matematikk-8:potenser-og-kvadratrotter', 's05', 'Skriv 4 200 000 på standardform. Forklar kort hvorfor skrivemåten du velger, er standardform.', '4 200 000 = 4,2 · 10⁶. Tallet foran tierpotensen er mellom 1 og 10, så tallet er skrevet på standardform.', array['Skriver 4 200 000 som 4,2 · 10⁶.', 'Forklarer at tallet foran tierpotensen er mellom 1 og 10.']::text[], 4),
  ('matematikk-8:potenser-og-kvadratrotter', 's06', 'Et kvadratisk felt har areal 30. Mellom hvilke to hele tall ligger sidelengden? Begrunn svaret ved å bruke kvadrattall.', 'Sidelengden ligger mellom 5 og 6, fordi √30 ligger mellom √25 og √36. Siden 25 < 30 < 36, er 5 < √30 < 6.', array['Plasserer sidelengden mellom 5 og 6.', 'Begrunner med kvadrattallene 25 og 36, eller med at 25 < 30 < 36.']::text[], 5),
  ('matematikk-8:potenser-og-kvadratrotter', 's07', 'Forklar forskjellen på et kvadrattall og et kubikktall. Bruk 5² og 3³ til å vise hvordan de kan knyttes til areal og volum.', 'Et kvadrattall får vi når et helt tall opphøyes i andre, mens et kubikktall får vi når det opphøyes i tredje. 5² kan beskrive arealet av et kvadrat med side 5, og 3³ kan beskrive volumet av en terning med side 3.', array['Forklarer at kvadrattall betyr opphøyd i andre, og kubikktall opphøyd i tredje.', 'Knytter 5² til arealet av et kvadrat og 3³ til volumet av en terning.']::text[], 6),
  ('matematikk-8:potenser-og-kvadratrotter', 's08', 'Regn ut 2² + √36 · 2. Vis hvilken rekkefølge du bruker på potens, kvadratrot, multiplikasjon og addisjon.', 'Først regner vi ut potensen og kvadratroten: 2² = 4 og √36 = 6. Deretter regner vi multiplikasjonen før addisjonen: 4 + 6 · 2 = 4 + 12 = 16.', array['Finner 2² = 4 og √36 = 6.', 'Regner multiplikasjonen før addisjonen og får 16.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-8:regnestrategier', 'matematikk-8', 'regnestrategier', 'Regnestrategier og regneregler', 'Kommutativ, assosiativ og distributiv lov, og hvordan du bruker dem til smart hoderegning og ryddig skriftlig regning.', array[2]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-8:regnestrategier', '## Tre regneregler som gjør regning lettere
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-8:regnestrategier', 'Kommutativ lov', 'Rekkefølgen spiller ingen rolle ved addisjon og multiplikasjon: a + b = b + a og a · b = b · a.', 0),
  ('matematikk-8:regnestrategier', 'Assosiativ lov', 'Du kan velge hvilke tall du regner sammen først: (a + b) + c = a + (b + c), og tilsvarende for multiplikasjon.', 1),
  ('matematikk-8:regnestrategier', 'Distributiv lov', 'En faktor kan ganges inn i en parentes: a · (b + c) = a · b + a · c.', 2),
  ('matematikk-8:regnestrategier', 'Faktor', 'Et tall som ganges med et annet tall. I 6 · 7 er både 6 og 7 faktorer.', 3),
  ('matematikk-8:regnestrategier', 'Produkt', 'Svaret på en multiplikasjon. Produktet av 6 og 7 er 42.', 4),
  ('matematikk-8:regnestrategier', 'Sum', 'Svaret på en addisjon. Summen av 8 og 5 er 13.', 5),
  ('matematikk-8:regnestrategier', 'Differanse', 'Svaret på en subtraksjon. Differansen mellom 12 og 5 er 7.', 6),
  ('matematikk-8:regnestrategier', 'Kvotient', 'Svaret på en divisjon. Kvotienten av 20 og 4 er 5.', 7),
  ('matematikk-8:regnestrategier', 'Dele opp', 'Hoderegningsstrategi der tallene deles i tiere og enere: 36 + 47 = 30 + 40 + 6 + 7.', 8),
  ('matematikk-8:regnestrategier', 'Kompensere', 'Regne med et runt tall og justere etterpå: 99 · 6 = 100 · 6 − 6.', 9),
  ('matematikk-8:regnestrategier', 'Doble og halvere', 'Produktet endres ikke når én faktor dobles og den andre halveres: 16 · 25 = 8 · 50.', 10),
  ('matematikk-8:regnestrategier', 'Overslag', 'Et grovt anslag med runde tall for å sjekke om svaret er rimelig.', 11),
  ('matematikk-8:regnestrategier', 'Oppstilling', 'Skriftlig regning der sifrene står under hverandre etter plassverdi.', 12),
  ('matematikk-8:regnestrategier', 'Plassverdi', 'Verdien et siffer har ut fra plassen i tallet. I 352 står 5 for 5 tiere.', 13),
  ('matematikk-8:regnestrategier', 'Ikke kommutativ', 'Subtraksjon og divisjon: 10 − 4 ≠ 4 − 10 og 12 : 3 ≠ 3 : 12.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-8:regnestrategier', 'q01', 'flervalg', 'Hvilken regel viser at 6 · 9 = 9 · 6?', array['Den distributive loven', 'Den assosiative loven', 'Den kommutative loven', 'Regnerekkefølgen']::text[], 2, 'Den kommutative loven sier at faktorene kan bytte plass ved multiplikasjon uten at produktet endres.', true, true, 0),
  ('matematikk-8:regnestrategier', 'q02', 'flervalg', 'Hva er 5 · (8 + 2) skrevet med den distributive loven?', array['5 · 8 + 2', '5 · 8 + 5 · 2', '5 + 8 · 2', '5 · 8 · 2']::text[], 1, 'Faktoren 5 skal ganges med begge leddene i parentesen: 5 · 8 + 5 · 2 = 40 + 10 = 50.', true, true, 1),
  ('matematikk-8:regnestrategier', 'q03', 'flervalg', 'Hvilken strategi passer best for å regne 99 · 8 i hodet?', array['100 · 8 − 8', '99 · 10 − 2', '90 · 8 + 99', '9 · 9 · 8 − 1']::text[], 0, '99 er én mindre enn 100. Regn 100 · 8 = 800 og trekk fra én åtter: 800 − 8 = 792.', true, true, 2),
  ('matematikk-8:regnestrategier', 'q04', 'flervalg', 'Hva er 25 · 4 · 17?', array['425', '1017', '1360', '1700']::text[], 3, 'Bruk den kommutative og assosiative loven: 25 · 4 = 100, og 100 · 17 = 1700.', true, true, 3),
  ('matematikk-8:regnestrategier', 'q05', 'flervalg', 'Hvilken regneart er kommutativ?', array['Subtraksjon', 'Addisjon', 'Divisjon', 'Ingen av dem']::text[], 1, 'a + b = b + a gjelder alltid. For subtraksjon og divisjon gir det et annet svar om tallene bytter plass.', true, false, 4),
  ('matematikk-8:regnestrategier', 'q06', 'flervalg', 'Hva er 16 · 25 hvis du dobler og halverer?', array['8 · 50 = 400', '32 · 50 = 1600', '8 · 12,5 = 100', '4 · 25 = 100']::text[], 0, 'Halver 16 og doble 25: 8 · 50. Én gang til: 4 · 100 = 400. Produktet er det samme hele veien.', true, true, 5),
  ('matematikk-8:regnestrategier', 'q07', 'flervalg', 'Hva er 7 · 23?', array['141', '151', '161', '171']::text[], 2, 'Del opp: 7 · 20 + 7 · 3 = 140 + 21 = 161.', true, true, 6),
  ('matematikk-8:regnestrategier', 'q08', 'flervalg', 'Hvilket overslag passer best for 48 · 31?', array['50 · 30 = 1500', '40 · 30 = 1200', '50 · 40 = 2000', '48 · 3 = 144']::text[], 0, 'Rund 48 opp til 50 og 31 ned til 30. Det nøyaktige svaret er 1488, som ligger nær 1500.', true, false, 7),
  ('matematikk-8:regnestrategier', 'q09', 'flervalg', 'Hva er 17 + 38 + 62?', array['107', '127', '117', '137']::text[], 2, 'Bruk den assosiative loven og legg sammen 38 + 62 = 100 først. Så er 100 + 17 = 117.', true, true, 8),
  ('matematikk-8:regnestrategier', 'q10', 'flervalg', 'Hvilket uttrykk er lik 12 · 15?', array['12 · 10 + 5', '10 · 15 + 2', '12 · 10 + 12 · 5', '12 + 10 · 5']::text[], 2, '15 = 10 + 5, så 12 · 15 = 12 · 10 + 12 · 5 = 120 + 60 = 180. Begge leddene må ganges med 12.', true, true, 9),
  ('matematikk-8:regnestrategier', 'm01', 'sant-usant', '20 − 8 er det samme som 8 − 20.', array['Sant', 'Usant']::text[], 1, 'Subtraksjon er ikke kommutativ. 20 − 8 = 12, mens 8 − 20 = −12.', false, true, 10),
  ('matematikk-8:regnestrategier', 'm02', 'sant-usant', '(3 · 4) · 5 = 3 · (4 · 5).', array['Sant', 'Usant']::text[], 0, 'Den assosiative loven gjelder for multiplikasjon. Begge sider blir 60.', false, true, 11),
  ('matematikk-8:regnestrategier', 'm03', 'sant-usant', '4 · (10 + 3) = 4 · 10 + 3.', array['Sant', 'Usant']::text[], 1, 'Også 3-tallet må ganges med 4: 4 · 10 + 4 · 3 = 52. Høyre side gir bare 43.', false, true, 12),
  ('matematikk-8:regnestrategier', 'm04', 'sant-usant', 'Når du dobler én faktor og halverer den andre, blir produktet det samme.', array['Sant', 'Usant']::text[], 0, 'Å gange med 2 og dele på 2 opphever hverandre, så produktet endres ikke.', false, true, 13),
  ('matematikk-8:regnestrategier', 'm05', 'flervalg', 'Hva er 199 + 57?', array['246', '256', '266', '257']::text[], 1, 'Kompenser: 200 + 57 = 257, og trekk fra 1 fordi du la til 1 for mye: 256.', false, true, 14),
  ('matematikk-8:regnestrategier', 'm06', 'flervalg', 'Hva kalles svaret på en divisjon?', array['Produkt', 'Differanse', 'Sum', 'Kvotient']::text[], 3, 'Svaret på en divisjon kalles kvotient. Produkt er svaret på en multiplikasjon.', false, true, 15),
  ('matematikk-8:regnestrategier', 'm07', 'flervalg', 'Hva er 8 · 125?', array['1000', '800', '1250', '10 000']::text[], 0, '125 · 8 er et nyttig par å kunne: 125 · 2 = 250, 250 · 2 = 500 og 500 · 2 = 1000.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-8:regnestrategier', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-8:regnestrategier', 's01', 'Forklar forskjellen på den kommutative loven og den assosiative loven. Bruk gjerne et lite regneuttrykk for å vise hver regel.', 'Den kommutative loven lar oss bytte rekkefølge på tallene i addisjon og multiplikasjon. Den assosiative loven lar oss velge hvilke tall vi regner sammen først.', array['Forklarer at kommutativ lov handler om å bytte rekkefølge.', 'Forklarer at assosiativ lov handler om hvilke tall som regnes sammen først.']::text[], 0),
  ('matematikk-8:regnestrategier', 's02', 'Hvorfor kan vi ikke bytte om på tallene i en subtraksjon eller divisjon uten at svaret kan endre seg? Vis med ett eksempel.', 'Subtraksjon og divisjon er ikke kommutative, så rekkefølgen på tallene betyr noe. For eksempel er 10 − 4 = 6, mens 4 − 10 ikke er 6.', array['Forklarer at rekkefølgen betyr noe ved subtraksjon eller divisjon.', 'Gir et eksempel der ombytting gir et annet svar.']::text[], 1),
  ('matematikk-8:regnestrategier', 's03', 'Regn ut 38 + 46 ved å dele tallene opp i tiere og enere. Vis det viktigste steget.', '38 + 46 = 30 + 40 + 8 + 6 = 70 + 14 = 84.', array['Deler opp tallene i tiere og enere.', 'Får summen 84.']::text[], 2),
  ('matematikk-8:regnestrategier', 's04', 'Bruk strategien doble og halvere til å regne ut 18 · 5. Vis hvordan du endrer faktorene, og finn produktet.', 'Jeg halverer 18 til 9 og dobler 5 til 10. Da blir 9 · 10 = 90.', array['Halverer den ene faktoren og dobler den andre.', 'Får produktet 90.']::text[], 3),
  ('matematikk-8:regnestrategier', 's05', 'Bruk den distributive loven til å regne ut 6 · (20 + 3). Skriv uttrykket uten parentes og finn svaret.', '6 · (20 + 3) = 6 · 20 + 6 · 3 = 120 + 18 = 138.', array['Ganger 6 med både 20 og 3.', 'Får svaret 138.']::text[], 4),
  ('matematikk-8:regnestrategier', 's06', 'Regn ut 101 · 7 ved å kompensere: bruk et rundt tall og juster etterpå. Vis steget du bruker.', 'Jeg regner først 100 · 7 = 700 og legger til 7. Derfor er 101 · 7 = 707.', array['Bruker 100 · 7 som utgangspunkt.', 'Justerer med å legge til 7 og får 707.']::text[], 5),
  ('matematikk-8:regnestrategier', 's07', 'En elev får 899 som svar på 31 · 29. Bruk et overslag til å forklare hvorfor svaret virker rimelig.', '31 og 29 er nær 30, så et overslag er 30 · 30 = 900. Derfor virker 899 som et rimelig svar.', array['Runder tallene til omtrent 30 og 30.', 'Bruker overslaget 900 til å forklare at 899 er rimelig.']::text[], 6),
  ('matematikk-8:regnestrategier', 's08', 'Du skal stille opp 248 + 36. Hvilket siffer i 36 skal stå under 4-tallet i 248, og hvorfor?', '3-tallet skal stå under 4-tallet. Begge sifrene står på tierplassen, og sifre med samme plassverdi skal stå under hverandre.', array['Plasserer 3 under 4.', 'Forklarer at sifrene står under hverandre fordi begge har plassverdi tiere.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-8:faktorisering-og-brok', 'matematikk-8', 'faktorisering-og-brok', 'Faktorisering og brøk', 'Primtall, primtallsfaktorisering og hvordan du bruker faktorer til å forkorte, utvide og regne med brøker.', array[3]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-8:faktorisering-og-brok', '## Faktorer og primtall
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-8:faktorisering-og-brok', 'Faktorisere', 'Å skrive et tall eller uttrykk som et produkt av faktorer, for eksempel 12 = 3 · 4.', 0),
  ('matematikk-8:faktorisering-og-brok', 'Primtall', 'Et helt tall større enn 1 som bare er delelig med 1 og seg selv: 2, 3, 5, 7, 11, 13 …', 1),
  ('matematikk-8:faktorisering-og-brok', 'Sammensatt tall', 'Et helt tall større enn 1 som ikke er et primtall, for eksempel 4, 6, 9 og 15.', 2),
  ('matematikk-8:faktorisering-og-brok', 'Primtallsfaktorisering', 'Et tall skrevet som produkt av bare primtall. 60 = 2 · 2 · 3 · 5.', 3),
  ('matematikk-8:faktorisering-og-brok', 'Faktortre', 'En tegning der et tall deles i faktorer grein for grein, til alle greinene ender i primtall.', 4),
  ('matematikk-8:faktorisering-og-brok', 'Delelig med 3', 'Et tall er delelig med 3 når tverrsummen (summen av sifrene) er delelig med 3. 471: 4 + 7 + 1 = 12.', 5),
  ('matematikk-8:faktorisering-og-brok', 'Teller', 'Tallet over brøkstreken. Det viser hvor mange deler vi har.', 6),
  ('matematikk-8:faktorisering-og-brok', 'Nevner', 'Tallet under brøkstreken. Det viser hvor mange like deler helheten er delt i.', 7),
  ('matematikk-8:faktorisering-og-brok', 'Forkorte en brøk', 'Dele teller og nevner på samme tall. 18/24 = 3/4 når vi deler på 6.', 8),
  ('matematikk-8:faktorisering-og-brok', 'Utvide en brøk', 'Gange teller og nevner med samme tall. 2/3 = 8/12 når vi ganger med 4.', 9),
  ('matematikk-8:faktorisering-og-brok', 'Fullstendig forkortet', 'En brøk der teller og nevner ikke har noen felles faktor utenom 1.', 10),
  ('matematikk-8:faktorisering-og-brok', 'Fellesnevner', 'En nevner som alle brøkene i et regnestykke kan utvides til. Trengs ved addisjon og subtraksjon.', 11),
  ('matematikk-8:faktorisering-og-brok', 'Minste fellesnevner', 'Det minste tallet som alle nevnerne går opp i. For 6 og 8 er det 24.', 12),
  ('matematikk-8:faktorisering-og-brok', 'Gange brøker', 'Teller ganges med teller og nevner med nevner: 2/3 · 5/7 = 10/21.', 13),
  ('matematikk-8:faktorisering-og-brok', 'Dele med en brøk', 'Gang med den omvendte brøken: 3/4 : 1/2 = 3/4 · 2/1.', 14),
  ('matematikk-8:faktorisering-og-brok', 'Uekte brøk', 'En brøk der telleren er større enn nevneren, for eksempel 7/4 = 1 3/4.', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-8:faktorisering-og-brok', 'q01', 'flervalg', 'Hvilket av disse tallene er et primtall?', array['21', '27', '29', '33']::text[], 2, '29 kan bare deles på 1 og 29. 21 = 3 · 7, 27 = 3 · 9 og 33 = 3 · 11 er sammensatte tall.', true, true, 0),
  ('matematikk-8:faktorisering-og-brok', 'q02', 'flervalg', 'Hva er primtallsfaktoriseringen av 36?', array['4 · 9', '2 · 2 · 3 · 3', '6 · 6', '2 · 18']::text[], 1, 'Alle de andre svarene inneholder tall som ikke er primtall. 36 = 2 · 2 · 3 · 3 = 2² · 3².', true, true, 1),
  ('matematikk-8:faktorisering-og-brok', 'q03', 'flervalg', 'Er tallet 1 et primtall?', array['Nei, et primtall må være større enn 1', 'Ja, fordi det bare er delelig med seg selv', 'Ja, det er det minste primtallet', 'Det kommer an på sammenhengen']::text[], 0, 'Et primtall har nøyaktig to ulike faktorer: 1 og seg selv. Tallet 1 har bare én, og regnes derfor ikke som primtall.', true, false, 2),
  ('matematikk-8:faktorisering-og-brok', 'q04', 'flervalg', 'Forkort 18/24 fullstendig.', array['9/12', '6/8', '2/3', '3/4']::text[], 3, 'Største felles faktor for 18 og 24 er 6. 18 : 6 = 3 og 24 : 6 = 4, så brøken blir 3/4.', true, true, 3),
  ('matematikk-8:faktorisering-og-brok', 'q05', 'flervalg', 'Hvilket tall er delelig med 3?', array['412', '513', '701', '830']::text[], 1, 'Tverrsummen av 513 er 5 + 1 + 3 = 9, som er delelig med 3. Da er også 513 delelig med 3 (513 = 3 · 171).', true, true, 4),
  ('matematikk-8:faktorisering-og-brok', 'q06', 'flervalg', 'Hva er minste fellesnevner for 1/4 og 1/6?', array['10', '24', '12', '2']::text[], 2, '4 = 2 · 2 og 6 = 2 · 3. Fellesnevneren må inneholde 2 · 2 · 3 = 12. Både 4 og 6 går opp i 12.', true, true, 5),
  ('matematikk-8:faktorisering-og-brok', 'q07', 'flervalg', 'Hva er 1/6 + 3/8?', array['4/14', '13/24', '4/48', '1/2']::text[], 1, 'Fellesnevner 24: 1/6 = 4/24 og 3/8 = 9/24. Summen er 13/24. Tellere og nevnere kan ikke legges sammen hver for seg.', true, true, 6),
  ('matematikk-8:faktorisering-og-brok', 'q08', 'flervalg', 'Hva er 2/3 · 5/7?', array['10/21', '7/10', '10/7', '7/21']::text[], 0, 'Gang teller med teller og nevner med nevner: 2 · 5 = 10 og 3 · 7 = 21.', true, false, 7),
  ('matematikk-8:faktorisering-og-brok', 'q09', 'flervalg', 'Hva er 3/4 : 1/2?', array['3/8', '1/2', '3/4', '3/2']::text[], 3, 'Å dele på 1/2 er det samme som å gange med 2: 3/4 · 2 = 6/4 = 3/2.', true, true, 8),
  ('matematikk-8:faktorisering-og-brok', 'q10', 'flervalg', 'Hvilken brøk er lik 2/5?', array['4/15', '6/15', '5/2', '2/10']::text[], 1, 'Utvid 2/5 med 3: 2 · 3 = 6 og 5 · 3 = 15. Verdien er den samme, 6/15 = 2/5.', true, true, 9),
  ('matematikk-8:faktorisering-og-brok', 'm01', 'sant-usant', '2 er det eneste partallet som er et primtall.', array['Sant', 'Usant']::text[], 0, 'Alle andre partall er delelige med 2 og har derfor minst tre faktorer.', false, true, 10),
  ('matematikk-8:faktorisering-og-brok', 'm02', 'sant-usant', '1/3 + 1/4 = 2/7.', array['Sant', 'Usant']::text[], 1, 'Nevnerne kan ikke legges sammen. Med fellesnevner 12 blir det 4/12 + 3/12 = 7/12.', false, true, 11),
  ('matematikk-8:faktorisering-og-brok', 'm03', 'sant-usant', 'Når du utvider en brøk, blir verdien større.', array['Sant', 'Usant']::text[], 1, 'Teller og nevner ganges med det samme tallet, så verdien er uendret. 1/2 = 3/6.', false, true, 12),
  ('matematikk-8:faktorisering-og-brok', 'm04', 'sant-usant', 'Tallet 45 er delelig med både 3 og 5.', array['Sant', 'Usant']::text[], 0, 'Tverrsummen 4 + 5 = 9 er delelig med 3, og tallet slutter på 5. 45 = 3 · 3 · 5.', false, true, 13),
  ('matematikk-8:faktorisering-og-brok', 'm05', 'flervalg', 'Hva er primtallsfaktoriseringen av 84?', array['2 · 42', '4 · 21', '2 · 2 · 3 · 7', '2 · 3 · 14']::text[], 2, '84 : 2 = 42, 42 : 2 = 21, 21 : 3 = 7. Altså 84 = 2 · 2 · 3 · 7, og alle faktorene er primtall.', false, true, 14),
  ('matematikk-8:faktorisering-og-brok', 'm06', 'flervalg', 'Hva er 5/6 − 1/3?', array['4/3', '1/2', '4/6', '1/3']::text[], 1, '1/3 = 2/6. Da blir 5/6 − 2/6 = 3/6, som forkortes til 1/2.', false, true, 15),
  ('matematikk-8:faktorisering-og-brok', 'm07', 'flervalg', 'Hvilket tall er et sammensatt tall?', array['51', '53', '47', '43']::text[], 0, '51 = 3 · 17. Tverrsummen 5 + 1 = 6 avslører at 51 er delelig med 3. De andre er primtall.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-8:faktorisering-og-brok', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-8:faktorisering-og-brok', 's01', 'Forklar med egne ord hva det betyr å faktorisere et tall. Bruk 12 = 3 · 4 til å vise hva faktorene er.', 'Å faktorisere betyr å skrive et tall som et produkt av faktorer. I 12 = 3 · 4 er 3 og 4 faktorene.', array['Forklarer at faktorisering er å skrive et tall som et produkt.', 'Bruker 3 og 4 som faktorene i eksempelet.']::text[], 0),
  ('matematikk-8:faktorisering-og-brok', 's02', 'Et faktortre og gjentatt deling kan begge brukes til å primtallsfaktorisere et tall. Sammenlign hvordan de viser fram arbeidet.', 'I et faktortre deler man tallet i faktorer grein for grein til alle greinene ender i primtall. Ved gjentatt deling deler man på primtall så lenge det går. Begge metodene viser primtallsfaktoriseringen.', array['Beskriver hvordan et faktortre deler tallet grein for grein fram til primtall.', 'Forklarer at gjentatt deling bruker primtall, og at begge metodene gir en primtallsfaktorisering.']::text[], 1),
  ('matematikk-8:faktorisering-og-brok', 's03', 'Primtallsfaktoriser 60. Vis det viktigste steget i utregningen.', '60 : 2 = 30, 30 : 2 = 15 og 15 : 3 = 5. Derfor er 60 = 2 · 2 · 3 · 5.', array['Viser deling på primtall fram til 1 eller fram til primtallsfaktorene er funnet.', 'Skriver 60 som produktet 2 · 2 · 3 · 5.']::text[], 2),
  ('matematikk-8:faktorisering-og-brok', 's04', 'Regn ut 2/3 · 3/4. Vis hvordan du ganger tellerne og nevnerne, og forkort svaret hvis det går.', '2/3 · 3/4 = 6/12. Tellerne ganges med hverandre og nevnerne med hverandre, og 6/12 forkortes til 1/2.', array['Ganger teller med teller og nevner med nevner, slik at produktet blir 6/12.', 'Forkorter 6/12 riktig til 1/2.']::text[], 3),
  ('matematikk-8:faktorisering-og-brok', 's05', 'Brøken 2/3 utvides ved å gange teller og nevner med 4. Skriv den nye brøken, og forklar hvorfor verdien ikke endres.', 'Når vi ganger både teller og nevner med 4, får vi 8/12. Verdien endres ikke fordi teller og nevner er ganget med samme tall.', array['Finner den utvidede brøken 8/12.', 'Forklarer at brøkens verdi bevares når teller og nevner ganges med samme tall.']::text[], 4),
  ('matematikk-8:faktorisering-og-brok', 's06', 'Nevnerne i to brøker er 6 og 8. Forklar hvorfor 24 er den minste fellesnevneren.', '24 går opp i både 6 og 8, fordi 24 er delelig med begge nevnerne. Det er den minste fellesnevneren fordi faktorene som trengs for begge nevnerne, gir 2 · 2 · 2 · 3 = 24.', array['Viser at 24 er delelig med både 6 og 8.', 'Forklarer at den minste fellesnevneren må inneholde faktorene som trengs for begge nevnerne.']::text[], 5),
  ('matematikk-8:faktorisering-og-brok', 's07', 'I brøken 7/4 er telleren større enn nevneren. Forklar hva telleren og nevneren viser, og hvorfor 7/4 er en uekte brøk.', 'Telleren 7 viser hvor mange deler vi har, og nevneren 4 viser hvor mange like deler helheten er delt i. 7/4 er en uekte brøk fordi telleren er større enn nevneren.', array['Forklarer hva telleren og nevneren viser i brøken.', 'Knytter betegnelsen uekte brøk til at telleren er større enn nevneren.']::text[], 6),
  ('matematikk-8:faktorisering-og-brok', 's08', 'Vurder brøkene 2/3 og 8/12. Hvilken er fullstendig forkortet? Begrunn svaret ved å se på om teller og nevner har en felles faktor.', '2/3 er fullstendig forkortet fordi teller og nevner ikke har noen felles faktor utenom 1. 8/12 er ikke fullstendig forkortet, fordi 8 og 12 har den felles faktoren 4.', array['Velger 2/3 som den fullstendig forkortede brøken.', 'Begrunner valget med at 8 og 12 har en felles faktor, mens 2 og 3 ikke har det utenom 1.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-8:monstre-og-algebra', 'matematikk-8', 'monstre-og-algebra', 'Mønstre og algebraiske uttrykk', 'Hvordan du beskriver tallmønstre og figurmønstre med en formel, og hvordan du lager og forenkler uttrykk med variabler.', array[4, 5]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-8:monstre-og-algebra', '## Mønstre
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-8:monstre-og-algebra', 'Mønster', 'En følge av tall eller figurer som endrer seg etter en fast regel.', 0),
  ('matematikk-8:monstre-og-algebra', 'Tallfølge', 'Tall i en bestemt rekkefølge, for eksempel 3, 7, 11, 15, der hvert tall øker med 4.', 1),
  ('matematikk-8:monstre-og-algebra', 'Formel for et mønster', 'Et uttrykk som gir tallet på plass n. For 3, 7, 11, 15 er formelen 4n − 1.', 2),
  ('matematikk-8:monstre-og-algebra', 'Figurnummer n', 'Plassen i mønsteret. Vi setter inn n = 1, 2, 3 … i formelen.', 3),
  ('matematikk-8:monstre-og-algebra', 'Trekanttall', 'Tallene 1, 3, 6, 10, 15 …, som gir antall prikker i trekanter som vokser.', 4),
  ('matematikk-8:monstre-og-algebra', 'Variabel', 'En bokstav som står for et tall som kan variere, for eksempel x for antall kilometer.', 5),
  ('matematikk-8:monstre-og-algebra', 'Konstant', 'Et tall som ikke endrer seg i uttrykket, for eksempel en fast startpris.', 6),
  ('matematikk-8:monstre-og-algebra', 'Koeffisient', 'Tallet som står foran en variabel. I 15x er koeffisienten 15.', 7),
  ('matematikk-8:monstre-og-algebra', 'Algebraisk uttrykk', 'Et uttrykk med tall, variabler og regnetegn, for eksempel 15x + 60.', 8),
  ('matematikk-8:monstre-og-algebra', 'Ledd', 'Deler av et uttrykk som er skilt med pluss eller minus. 3x + 7 har to ledd.', 9),
  ('matematikk-8:monstre-og-algebra', 'Like ledd', 'Ledd med samme variabel i samme potens. 4a og 2a kan slås sammen til 6a.', 10),
  ('matematikk-8:monstre-og-algebra', '3x', 'Kort skrivemåte for 3 · x. Gangetegnet sløyfes mellom tall og variabel.', 11),
  ('matematikk-8:monstre-og-algebra', 'Gange ut en parentes', 'Gange faktoren med hvert ledd i parentesen: 3(x + 2) = 3x + 6.', 12),
  ('matematikk-8:monstre-og-algebra', 'Sette inn en verdi', 'Bytte variabelen med et tall og regne ut. 2x + 1 med x = 5 gir 11.', 13),
  ('matematikk-8:monstre-og-algebra', 'Generalisere', 'Beskrive en sammenheng som gjelder for alle tilfeller, ikke bare ett, ofte med en formel.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-8:monstre-og-algebra', 'q01', 'flervalg', 'Hva er neste tall i følgen 5, 9, 13, 17, …?', array['19', '20', '21', '22']::text[], 2, 'Hvert tall øker med 4, så neste tall er 17 + 4 = 21.', true, true, 0),
  ('matematikk-8:monstre-og-algebra', 'q02', 'flervalg', 'Hvilken formel passer til følgen 3, 7, 11, 15, …?', array['4n − 1', '3n + 4', 'n + 4', '4n + 3']::text[], 0, 'Følgen øker med 4, så formelen har 4n. For n = 1 skal svaret bli 3: 4 · 1 − 1 = 3. Sjekk n = 2: 4 · 2 − 1 = 7.', true, true, 1),
  ('matematikk-8:monstre-og-algebra', 'q03', 'flervalg', 'Hva er 5x + 3 når x = 4?', array['57', '23', '12', '20']::text[], 1, 'Sett inn 4 for x: 5 · 4 + 3 = 20 + 3 = 23. Svaret 57 får du hvis du skriver 5 og 4 ved siden av hverandre.', true, true, 2),
  ('matematikk-8:monstre-og-algebra', 'q04', 'flervalg', 'Forenkle 4a + 3b + 2a − b.', array['8ab', '6a + 3b', '6a + 2b', '7a + 2b']::text[], 2, 'Slå sammen like ledd: 4a + 2a = 6a og 3b − b = 2b. Ulike ledd kan ikke slås sammen.', true, true, 3),
  ('matematikk-8:monstre-og-algebra', 'q05', 'flervalg', 'En taxi koster 60 kr i start og 15 kr per km. Hvilket uttrykk gir prisen for x km?', array['60x + 15', '75x', '15 + 60 + x', '15x + 60']::text[], 3, 'Kilometerprisen ganges med antall kilometer (15x), og startprisen legges til én gang (60).', true, true, 4),
  ('matematikk-8:monstre-og-algebra', 'q06', 'flervalg', 'Hva er 3(x + 5) når parentesen er ganget ut?', array['3x + 15', '3x + 5', 'x + 15', '3x + 8']::text[], 0, '3 skal ganges med begge leddene: 3 · x + 3 · 5 = 3x + 15.', true, true, 5),
  ('matematikk-8:monstre-og-algebra', 'q07', 'flervalg', 'Hva er koeffisienten i leddet 7y?', array['y', '7', '7y', '1']::text[], 1, 'Koeffisienten er tallet foran variabelen. I 7y er den 7.', true, false, 6),
  ('matematikk-8:monstre-og-algebra', 'q08', 'flervalg', 'Hvilken formel gir kvadrattallene 1, 4, 9, 16, …?', array['2n', 'n + 3', 'n²', '3n − 2']::text[], 2, '1 = 1², 4 = 2², 9 = 3² og 16 = 4². Tallet på plass n er n · n = n².', true, true, 7),
  ('matematikk-8:monstre-og-algebra', 'q09', 'flervalg', 'Emma har 50 kr mer enn dobbelt så mye som Jonas, som har x kr. Hvor mye har Emma?', array['2(x + 50)', 'x + 50', '50x + 2', '2x + 50']::text[], 3, 'Dobbelt så mye som Jonas er 2x, og 50 kr mer blir 2x + 50. Uttrykket 2(x + 50) = 2x + 100 er for mye.', true, true, 8),
  ('matematikk-8:monstre-og-algebra', 'q10', 'flervalg', 'Hva er neste trekanttall etter 1, 3, 6, 10?', array['15', '14', '13', '16']::text[], 0, 'Økningen blir én større for hver figur: +2, +3, +4, og så +5. 10 + 5 = 15.', true, false, 9),
  ('matematikk-8:monstre-og-algebra', 'm01', 'sant-usant', '3a + 2b kan forenkles til 5ab.', array['Sant', 'Usant']::text[], 1, '3a og 2b er ulike ledd fordi variablene er forskjellige. Uttrykket kan ikke forenkles mer.', false, true, 10),
  ('matematikk-8:monstre-og-algebra', 'm02', 'sant-usant', 'I uttrykket 15x + 60 er 60 en konstant.', array['Sant', 'Usant']::text[], 0, '60 endrer seg ikke når x endrer seg. Det er derfor en konstant.', false, true, 11),
  ('matematikk-8:monstre-og-algebra', 'm03', 'sant-usant', 'Formelen 2n + 1 gir tallene 3, 5, 7, 9 for n = 1, 2, 3, 4.', array['Sant', 'Usant']::text[], 0, '2 · 1 + 1 = 3, 2 · 2 + 1 = 5, 2 · 3 + 1 = 7 og 2 · 4 + 1 = 9.', false, true, 12),
  ('matematikk-8:monstre-og-algebra', 'm04', 'sant-usant', 'x² betyr det samme som 2x.', array['Sant', 'Usant']::text[], 1, 'x² = x · x, mens 2x = x + x. Med x = 5 blir x² = 25 og 2x = 10.', false, true, 13),
  ('matematikk-8:monstre-og-algebra', 'm05', 'flervalg', 'Hvilket tall kommer på plass nummer 10 i følgen gitt ved 3n + 2?', array['30', '32', '35', '302']::text[], 1, 'Sett inn n = 10: 3 · 10 + 2 = 32.', false, true, 14),
  ('matematikk-8:monstre-og-algebra', 'm06', 'flervalg', 'Forenkle 2(x + 4) + 3x.', array['5x + 4', '5x + 8', '6x + 4', '2x + 11']::text[], 1, 'Gang ut parentesen: 2x + 8. Legg til 3x: 2x + 3x + 8 = 5x + 8.', false, true, 15),
  ('matematikk-8:monstre-og-algebra', 'm07', 'flervalg', 'Hva kalles et tall som står for en verdi som kan endre seg?', array['Variabel', 'Konstant', 'Koeffisient', 'Faktor']::text[], 0, 'En variabel kan ta ulike verdier. En konstant har alltid samme verdi.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-8:monstre-og-algebra', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-8:monstre-og-algebra', 's01', 'En taxi har en startpris på 60 kr og koster 15 kr per kilometer. I uttrykket 15x + 60 for prisen, hva står x, 15 og 60 for?', 'x står for antall kilometer. 15 er prisen per kilometer, og 60 er den faste startprisen.', array['Forklarer at x står for antall kilometer.', 'Skiller mellom prisen per kilometer og den faste startprisen.']::text[], 0),
  ('matematikk-8:monstre-og-algebra', 's02', 'Regn ut verdien av 2x + 1 når x = 5. Vis det viktigste regnetrinnet.', 'Jeg setter inn 5 for x: 2 · 5 + 1 = 11.', array['Setter inn 5 for x.', 'Kommer fram til svaret 11.']::text[], 1),
  ('matematikk-8:monstre-og-algebra', 's03', 'Formelen for tallfølgen 3, 7, 11, 15, … er 4n − 1. Regn ut tallet på plass n = 3, og vis det viktigste regnetrinnet.', 'Jeg setter inn 3 for n: 4 · 3 − 1 = 11. Tallet på tredje plass er 11.', array['Setter inn 3 for n i formelen.', 'Kommer fram til svaret 11.']::text[], 2),
  ('matematikk-8:monstre-og-algebra', 's04', 'Sammenlign leddene 4a og 2a med leddene 4a og 2b. Hvilke ledd kan slås sammen, og hvorfor?', '4a og 2a kan slås sammen fordi de har samme variabel i samme potens. 4a og 2b kan ikke slås sammen fordi variablene er ulike.', array['Forklarer at 4a og 2a kan slås sammen fordi de er like ledd.', 'Forklarer at 4a og 2b ikke kan slås sammen fordi de har ulike variabler.']::text[], 3),
  ('matematikk-8:monstre-og-algebra', 's05', 'Sammenlign kvadrattallene 1, 4, 9, 16 med trekanttallene 1, 3, 6, 10. Hva forteller hver tallfølge om mønsteret den beskriver?', 'Kvadrattallene kan skrives som n². Trekanttallene beskriver antall prikker i trekanter som vokser.', array['Knytter kvadrattallene til n².', 'Forklarer at trekanttallene er antall prikker i voksende trekanter.']::text[], 4),
  ('matematikk-8:monstre-og-algebra', 's06', 'Forklar hva 3x og x² betyr som multiplikasjon. Hva er forskjellen på skrivemåtene?', '3x betyr 3 · x, mens x² betyr x · x. I den første skrivemåten ganges x med 3; i den andre ganges x med seg selv.', array['Forklarer at 3x betyr 3 · x.', 'Forklarer at x² betyr x · x.']::text[], 5),
  ('matematikk-8:monstre-og-algebra', 's07', 'Hva betyr n i en formel for et mønster, og hvordan kan en slik formel brukes til å beskrive mønsteret generelt?', 'n står for figurnummeret eller plassen i mønsteret. Ved å sette inn et figurnummer i formelen finner vi tallet på den plassen, og formelen beskriver dermed en regel som gjelder for flere plasser.', array['Forklarer at n viser figurnummeret eller plassen i mønsteret.', 'Forklarer at formelen kan brukes til å finne tallet for ulike plasser i mønsteret.']::text[], 6),
  ('matematikk-8:monstre-og-algebra', 's08', 'Gang ut parentesen i 3(x + 2). Forklar kort hvordan du finner leddene utenfor parentesen.', '3(x + 2) = 3x + 6. Jeg ganger 3 med både x og 2.', array['Ganger 3 med begge leddene i parentesen.', 'Skriver riktig svar: 3x + 6.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-8:likninger', 'matematikk-8', 'likninger', 'Likninger', 'Hva en likning er, hvordan du løser den med balansemetoden, og hvordan du lager likninger til praktiske problemer og vurderer svaret.', array[6]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-8:likninger', '## Hva er en likning?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-8:likninger', 'Likning', 'Et utsagn der to uttrykk er like store og minst ett inneholder en ukjent, for eksempel 3x + 5 = 20.', 0),
  ('matematikk-8:likninger', 'Ukjent', 'Bokstaven i en likning som står for tallet vi skal finne, ofte x.', 1),
  ('matematikk-8:likninger', 'Løsning', 'Verdien av den ukjente som gjør at begge sidene av likningen blir like store.', 2),
  ('matematikk-8:likninger', 'Balansemetoden', 'Gjør alltid det samme på begge sider av likhetstegnet, slik at likningen holder seg i balanse.', 3),
  ('matematikk-8:likninger', 'Legge til / trekke fra', 'Samme tall kan legges til eller trekkes fra på begge sider uten at løsningen endres.', 4),
  ('matematikk-8:likninger', 'Gange / dele', 'Begge sider kan ganges eller deles med samme tall, men aldri deles på 0.', 5),
  ('matematikk-8:likninger', 'Flytte og bytte fortegn', 'Kortversjon av balansemetoden: +5 på én side blir −5 på den andre siden.', 6),
  ('matematikk-8:likninger', 'Samle ledd', 'Samle alle x-ledd på én side og alle tall på den andre før du løser videre.', 7),
  ('matematikk-8:likninger', 'Sette prøve', 'Sette løsningen inn i den opprinnelige likningen for å sjekke at begge sider blir like.', 8),
  ('matematikk-8:likninger', 'Venstre side (VS)', 'Uttrykket til venstre for likhetstegnet.', 9),
  ('matematikk-8:likninger', 'Høyre side (HS)', 'Uttrykket til høyre for likhetstegnet.', 10),
  ('matematikk-8:likninger', 'Likninger med brøk', 'Gang alle ledd med fellesnevneren for å bli kvitt nevnerne: x/2 + 3 = 7 gir x + 6 = 14.', 11),
  ('matematikk-8:likninger', 'Likninger med parentes', 'Gang ut parentesene først, så løs som vanlig: 2(x + 3) = 14 gir 2x + 6 = 14.', 12),
  ('matematikk-8:likninger', 'Modellere med likning', 'Oversette en tekstoppgave til en likning ved å la x stå for det ukjente tallet.', 13),
  ('matematikk-8:likninger', 'Vurdere løsningen', 'Sjekke om svaret gir mening i situasjonen, for eksempel at antall personer er et helt, positivt tall.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-8:likninger', 'q01', 'flervalg', 'Løs likningen x + 7 = 15.', array['x = 22', 'x = 8', 'x = 7', 'x = 15']::text[], 1, 'Trekk fra 7 på begge sider: x = 15 − 7 = 8. Prøve: 8 + 7 = 15.', true, true, 0),
  ('matematikk-8:likninger', 'q02', 'flervalg', 'Løs likningen 3x + 5 = 20.', array['x = 5', 'x = 25/3', 'x = 15', 'x = 8']::text[], 0, 'Trekk fra 5: 3x = 15. Del på 3: x = 5. Prøve: 3 · 5 + 5 = 20.', true, true, 1),
  ('matematikk-8:likninger', 'q03', 'flervalg', 'Hva er det første lurt å gjøre i likningen 4x − 3 = 21?', array['Dele begge sider på 4', 'Trekke fra 3 på begge sider', 'Legge til 3 på begge sider', 'Gange begge sider med 3']::text[], 2, 'Minus 3 fjernes ved å legge til 3 på begge sider: 4x = 24. Så deler du på 4 og får x = 6.', true, false, 2),
  ('matematikk-8:likninger', 'q04', 'flervalg', 'Løs likningen 5x − 4 = 2x + 11.', array['x = 3', 'x = 7/3', 'x = 15', 'x = 5']::text[], 3, 'Samle x-ledd: 5x − 2x = 3x. Samle tall: 11 + 4 = 15. Da er 3x = 15 og x = 5.', true, true, 3),
  ('matematikk-8:likninger', 'q05', 'flervalg', 'Løs likningen x/3 = 6.', array['x = 2', 'x = 18', 'x = 9', 'x = 3']::text[], 1, 'Gang begge sider med 3: x = 6 · 3 = 18. Prøve: 18/3 = 6.', true, true, 4),
  ('matematikk-8:likninger', 'q06', 'flervalg', 'Løs likningen 2(x + 3) = 14.', array['x = 4', 'x = 5,5', 'x = 8', 'x = 10']::text[], 0, 'Gang ut: 2x + 6 = 14. Trekk fra 6: 2x = 8. Del på 2: x = 4.', true, true, 5),
  ('matematikk-8:likninger', 'q07', 'flervalg', 'Hvilken likning passer? «Buss 1200 kr pluss 150 kr per elev, totalt 5250 kr.»', array['1200x + 150 = 5250', '150 + 1200 = 5250x', '150x + 1200 = 5250', '150x = 5250 + 1200']::text[], 2, 'Prisen per elev ganges med antall elever (150x), og bussen legges til én gang (1200). Summen skal bli 5250.', true, true, 6),
  ('matematikk-8:likninger', 'q08', 'flervalg', 'Du har løst en likning og fått x = 6. Hvordan setter du prøve?', array['Løser likningen på nytt med en annen metode', 'Setter x = 6 inn i den opprinnelige likningen og sjekker at sidene blir like', 'Ganger svaret med 2 og ser om det blir partall', 'Deler begge sider på 6']::text[], 1, 'En prøve betyr å sette løsningen inn i den opprinnelige likningen. Blir venstre og høyre side like, er løsningen riktig.', true, false, 7),
  ('matematikk-8:likninger', 'q09', 'flervalg', 'En likning om antall elever gir x = 26,4. Hva bør du tenke?', array['At det var 26,4 elever', 'At svaret skal rundes opp til 27 uten videre', 'At svaret skal rundes ned til 26 uten videre', 'At det trolig er en feil, fordi antall elever må være et helt tall']::text[], 3, 'Antall elever må være et helt, positivt tall. Et desimalsvar tyder på regnefeil eller feil i opplysningene, og bør sjekkes.', true, true, 8),
  ('matematikk-8:likninger', 'q10', 'flervalg', 'Løs likningen 7 − x = 2.', array['x = 5', 'x = −5', 'x = 9', 'x = −9']::text[], 0, 'Legg til x på begge sider: 7 = 2 + x. Trekk fra 2: x = 5. Prøve: 7 − 5 = 2.', true, true, 9),
  ('matematikk-8:likninger', 'm01', 'sant-usant', 'x = 4 er løsningen på likningen 2x + 1 = 9.', array['Sant', 'Usant']::text[], 0, 'Prøve: 2 · 4 + 1 = 9. Begge sider blir 9.', false, true, 10),
  ('matematikk-8:likninger', 'm02', 'sant-usant', 'Du kan dele begge sider av en likning på 0.', array['Sant', 'Usant']::text[], 1, 'Deling på 0 er ikke definert. Du kan gange og dele med alle andre tall.', false, true, 11),
  ('matematikk-8:likninger', 'm03', 'sant-usant', 'Å trekke fra 3 på begge sider gir samme resultat som å flytte +3 over og bytte fortegn.', array['Sant', 'Usant']::text[], 0, 'Å flytte og bytte fortegn er en kortversjon av balansemetoden.', false, true, 12),
  ('matematikk-8:likninger', 'm04', 'sant-usant', 'Likningen x + 3 = x + 5 har løsningen x = 2.', array['Sant', 'Usant']::text[], 1, 'Trekker du fra x på begge sider, får du 3 = 5, som aldri stemmer. Likningen har ingen løsning.', false, true, 13),
  ('matematikk-8:likninger', 'm05', 'flervalg', 'Løs likningen 6x = 42.', array['x = 36', 'x = 48', 'x = 7', 'x = 252']::text[], 2, 'Del begge sider på 6: x = 42 : 6 = 7.', false, true, 14),
  ('matematikk-8:likninger', 'm06', 'flervalg', 'Løs likningen x/4 + 2 = 5.', array['x = 28', 'x = 12', 'x = 3', 'x = 7']::text[], 1, 'Trekk fra 2: x/4 = 3. Gang med 4: x = 12. Prøve: 12/4 + 2 = 5.', false, true, 15),
  ('matematikk-8:likninger', 'm07', 'flervalg', 'Summen av et tall og det dobbelte av tallet er 36. Hvilket tall er det?', array['12', '18', '9', '6']::text[], 0, 'x + 2x = 36 gir 3x = 36 og x = 12. Prøve: 12 + 24 = 36.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-8:likninger', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-8:likninger', 's01', 'I likningen 3x + 5 = 20, forklar med egne ord hva det betyr at dette er en likning, og pek ut den ukjente.', 'En likning sier at uttrykket på venstre side er like stort som uttrykket på høyre side. x er den ukjente fordi verdien til x skal finnes.', array['Forklarer at de to sidene er like store.', 'Peker ut x som den ukjente verdien som skal finnes.']::text[], 0),
  ('matematikk-8:likninger', 's02', 'I likningen 4x + 2 = 18, forklar forskjellen på den ukjente og løsningen. Finn også løsningen.', 'x er den ukjente, altså tallet vi skal finne. Løsningen er x = 4, fordi 4 · 4 + 2 = 18.', array['Skiller mellom bokstaven som står for et ukjent tall, og verdien som gjør likningen sann.', 'Oppgir x = 4 som løsning.']::text[], 1),
  ('matematikk-8:likninger', 's03', 'En elev trekker fra 4 bare på venstre side i likningen 3x + 4 = 16. Forklar hvorfor dette ikke bevarer likheten, og hva eleven må gjøre i stedet.', 'Hvis eleven bare trekker fra 4 på venstre side, endres bare den siden, og sidene blir ikke lenger like. Eleven må trekke fra 4 på begge sider.', array['Forklarer at likheten ikke bevares når bare én side endres.', 'Sier at samme tall må trekkes fra på begge sider.']::text[], 2),
  ('matematikk-8:likninger', 's04', 'Løs likningen 5x − 4 = 2x + 20. Vis det viktigste steget før du finner x.', 'Trekk fra 2x på begge sider og legg til 4 på begge sider: 3x = 24. Del på 3, så x = 8.', array['Samler x-leddene på én side og tallene på den andre slik at 3x = 24.', 'Finner x = 8.']::text[], 3),
  ('matematikk-8:likninger', 's05', 'Løs likningen x/2 + 3 = 7. Vis hvordan du først blir kvitt 3, og finn deretter x.', 'Trekk fra 3 på begge sider: x/2 = 4. Gang begge sider med 2, så x = 8.', array['Får x/2 = 4 ved å trekke fra 3 på begge sider.', 'Finner x = 8 ved å gange begge sider med 2.']::text[], 4),
  ('matematikk-8:likninger', 's06', 'I likningen x + 5 = 20 kan noen si at «+5 flyttes over og blir −5». Forklar hvordan dette henger sammen med balansemetoden.', 'Å flytte +5 over som −5 er en kort måte å si at vi trekker fra 5 på begge sider. Da får vi x = 20 − 5 = 15.', array['Knytter fortegnsskiftet til at samme tall trekkes fra på begge sider.', 'Får x = 15.']::text[], 5),
  ('matematikk-8:likninger', 's07', 'En klassetur koster 1200 kr for bussen pluss 150 kr per elev, og totalprisen er 5250 kr. La x være antall elever. Finn x og vis det viktigste regnestykket.', 'Likningen blir 150x + 1200 = 5250. Da er 150x = 4050, og når vi deler på 150, får vi x = 27 elever.', array['Bruker en likning som viser bussprisen på 1200 kr og 150 kr per elev, med totalpris 5250 kr.', 'Finner at x = 27 elever.']::text[], 6),
  ('matematikk-8:likninger', 's08', 'En elev ganger ut 3(x + 2) som 3x + 2. Forklar feilen og skriv det riktige uttrykket uten parentes.', 'Eleven har bare ganget 3 med x, men 3 skal ganges med begge leddene i parentesen. Riktig uttrykk er 3x + 6.', array['Forklarer at 3 må ganges med både x og 2.', 'Skriver 3x + 6 som riktig uttrykk.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-8:ulikheter', 'matematikk-8', 'ulikheter', 'Ulikheter', 'Ulikhetstegnene, hvordan du løser ulikheter nesten som likninger, den viktige regelen om å snu tegnet, og hvordan du viser løsningen på tallinja.', array[7]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-8:ulikheter', '## Hva er en ulikhet?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-8:ulikheter', 'Ulikhet', 'Et utsagn som sammenligner to uttrykk med <, >, ≤ eller ≥ i stedet for =.', 0),
  ('matematikk-8:ulikheter', '<', 'Mindre enn. 3 < 7 betyr at 3 er mindre enn 7.', 1),
  ('matematikk-8:ulikheter', '>', 'Større enn. 10 > 4 betyr at 10 er større enn 4.', 2),
  ('matematikk-8:ulikheter', '≤', 'Mindre enn eller lik. x ≤ 5 betyr at x kan være 5 eller alt som er mindre.', 3),
  ('matematikk-8:ulikheter', '≥', 'Større enn eller lik. x ≥ −2 betyr at x kan være −2 eller alt som er større.', 4),
  ('matematikk-8:ulikheter', 'Huskeregel for tegnet', 'Den åpne siden av tegnet vender alltid mot det største tallet.', 5),
  ('matematikk-8:ulikheter', 'Løsningsmengde', 'Alle tallene som gjør ulikheten sann. For x > 2 er det alle tall større enn 2.', 6),
  ('matematikk-8:ulikheter', 'Snu tegnet', 'Når du ganger eller deler begge sider med et negativt tall, må ulikhetstegnet snus.', 7),
  ('matematikk-8:ulikheter', 'Hvorfor snu?', '2 < 5, men ganget med −1 blir det −2 og −5, og −2 > −5.', 8),
  ('matematikk-8:ulikheter', 'Åpen ring på tallinja', 'Tallet er ikke med i løsningen. Brukes ved < og >.', 9),
  ('matematikk-8:ulikheter', 'Fylt prikk på tallinja', 'Tallet er med i løsningen. Brukes ved ≤ og ≥.', 10),
  ('matematikk-8:ulikheter', 'Positiv koeffisient', 'Flytt x-leddet slik at tallet foran x blir positivt, så slipper du å snu tegnet.', 11),
  ('matematikk-8:ulikheter', 'Teste løsningen', 'Sett inn ett tall som skal være med og ett som ikke skal være med, og se om ulikheten stemmer.', 12),
  ('matematikk-8:ulikheter', 'Gyldig løsning', 'En løsning som gir mening i situasjonen, for eksempel et helt, positivt antall billetter.', 13),
  ('matematikk-8:ulikheter', 'Høyst og minst', '«Høyst 5» betyr x ≤ 5. «Minst 5» betyr x ≥ 5.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-8:ulikheter', 'q01', 'flervalg', 'Hva betyr x ≥ 3?', array['x er mindre enn 3', 'x er større enn eller lik 3', 'x er lik 3', 'x er større enn 3, men ikke lik 3']::text[], 1, 'Tegnet ≥ betyr større enn eller lik. 3 er altså med i løsningen.', true, true, 0),
  ('matematikk-8:ulikheter', 'q02', 'flervalg', 'Løs ulikheten x + 5 > 9.', array['x > 14', 'x < 4', 'x > 4', 'x = 4']::text[], 2, 'Trekk fra 5 på begge sider: x > 4. Tegnet endres ikke når du trekker fra et tall.', true, true, 1),
  ('matematikk-8:ulikheter', 'q03', 'flervalg', 'Løs ulikheten 2x + 3 < 11.', array['x < 4', 'x > 4', 'x < 7', 'x < 8']::text[], 0, 'Trekk fra 3: 2x < 8. Del på 2 (et positivt tall): x < 4.', true, true, 2),
  ('matematikk-8:ulikheter', 'q04', 'flervalg', 'Når må du snu ulikhetstegnet?', array['Når du legger til et negativt tall', 'Når du deler på et positivt tall', 'Når du trekker fra et tall', 'Når du ganger eller deler med et negativt tall']::text[], 3, 'Bare multiplikasjon og divisjon med negative tall snur rekkefølgen på tallene, og da må tegnet snus.', true, true, 3),
  ('matematikk-8:ulikheter', 'q05', 'flervalg', 'Løs ulikheten −3x ≤ 12.', array['x ≤ −4', 'x ≥ −4', 'x ≥ 4', 'x ≤ 4']::text[], 1, 'Del på −3 og snu tegnet: x ≥ −4. Test x = 0: −3 · 0 = 0 ≤ 12, stemmer.', true, true, 4),
  ('matematikk-8:ulikheter', 'q06', 'flervalg', 'Hvordan tegner du x < 2 på en tallinje?', array['Åpen ring på 2 og pil mot venstre', 'Fylt prikk på 2 og pil mot venstre', 'Åpen ring på 2 og pil mot høyre', 'Fylt prikk på 2 og pil mot høyre']::text[], 0, '2 er ikke med (<), så ringen er åpen. Tallene mindre enn 2 ligger til venstre.', true, false, 5),
  ('matematikk-8:ulikheter', 'q07', 'flervalg', 'Hvilket tall er en løsning av 4x − 1 > 7?', array['x = 0', 'x = 1', 'x = 2', 'x = 3']::text[], 3, '4x − 1 > 7 gir 4x > 8 og x > 2. Bare x = 3 er større enn 2. For x = 2 blir 4 · 2 − 1 = 7, som ikke er større enn 7.', true, true, 6),
  ('matematikk-8:ulikheter', 'q08', 'flervalg', 'Du har 200 kr, og en kinobillett koster 85 kr. Hvor mange billetter kan du høyst kjøpe?', array['3', '2', '2,35', '1']::text[], 1, '85x ≤ 200 gir x ≤ 2,35. Du kan bare kjøpe hele billetter, så svaret er høyst 2.', true, true, 7),
  ('matematikk-8:ulikheter', 'q09', 'flervalg', 'Hvilket utsagn er sant?', array['−7 > −2', '−3 < −5', '−1 > −4', '0 < −1']::text[], 2, 'På tallinja ligger −1 til høyre for −4, så −1 er størst. For negative tall er det nærmest null som er størst.', true, true, 8),
  ('matematikk-8:ulikheter', 'q10', 'flervalg', '«Du må være minst 15 år.» Hvilken ulikhet passer for alderen a?', array['a ≥ 15', 'a > 15', 'a ≤ 15', 'a < 15']::text[], 0, '«Minst 15» betyr 15 eller mer, altså a ≥ 15. Den som akkurat har fylt 15, er med.', true, false, 9),
  ('matematikk-8:ulikheter', 'm01', 'sant-usant', 'Løsningen på en ulikhet er ofte mange tall, ikke bare ett.', array['Sant', 'Usant']::text[], 0, 'x > 2 er oppfylt av alle tall større enn 2, for eksempel 2,1, 3 og 100.', false, true, 10),
  ('matematikk-8:ulikheter', 'm02', 'sant-usant', 'Når du deler begge sider på 5, må du snu ulikhetstegnet.', array['Sant', 'Usant']::text[], 1, '5 er positivt, så tegnet beholdes. Tegnet snus bare ved multiplikasjon eller divisjon med et negativt tall.', false, true, 11),
  ('matematikk-8:ulikheter', 'm03', 'sant-usant', '−10 < −3.', array['Sant', 'Usant']::text[], 0, '−10 ligger lenger til venstre på tallinja enn −3, og er derfor minst.', false, true, 12),
  ('matematikk-8:ulikheter', 'm04', 'sant-usant', 'x ≤ 6 tegnes med åpen ring på 6.', array['Sant', 'Usant']::text[], 1, 'Tegnet ≤ betyr at 6 er med i løsningen. Da brukes fylt prikk.', false, true, 13),
  ('matematikk-8:ulikheter', 'm05', 'flervalg', 'Løs ulikheten 5 − x > 2.', array['x > 3', 'x > −3', 'x < 3', 'x < −3']::text[], 2, 'Trekk fra 5: −x > −3. Gang med −1 og snu tegnet: x < 3. Test x = 0: 5 > 2, stemmer.', false, true, 14),
  ('matematikk-8:ulikheter', 'm06', 'flervalg', '«Høyst 30 elever» kan skrives som', array['e > 30', 'e ≥ 30', 'e < 30', 'e ≤ 30']::text[], 3, 'Høyst 30 betyr 30 eller færre, altså e ≤ 30.', false, true, 15),
  ('matematikk-8:ulikheter', 'm07', 'flervalg', 'Løs ulikheten 3x − 4 ≥ 2x + 1.', array['x ≥ 5', 'x ≥ −3', 'x ≤ 5', 'x ≥ 1']::text[], 0, 'Trekk fra 2x: x − 4 ≥ 1. Legg til 4: x ≥ 5.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-8:ulikheter', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-8:ulikheter', 's01', 'Forklar med egne ord hva en ulikhet er, og nevn hvordan den er forskjellig fra en likning.', 'En ulikhet sammenligner to uttrykk med tegnene <, >, ≤ eller ≥. En likning bruker likhetstegnet =.', array['Forklarer at en ulikhet sammenligner to uttrykk.', 'Skiller ulikhetstegnene fra likhetstegnet.']::text[], 0),
  ('matematikk-8:ulikheter', 's02', 'Hva betyr x ≤ 5? Forklar hvilke tall som kan være x, og om 5 er med.', 'x kan være 5 eller et hvilket som helst tall mindre enn 5. Tallet 5 er med fordi tegnet betyr «mindre enn eller lik».', array['Forklarer at x kan være 5 eller mindre enn 5.', 'Sier at 5 er med i løsningen.']::text[], 1),
  ('matematikk-8:ulikheter', 's03', 'Forklar hvorfor ulikhetstegnet må snus når begge sider ganges med −1. Bruk 2 < 5 i forklaringen.', 'Når 2 < 5 ganges med −1, får vi −2 og −5. Siden −2 er større enn −5, må tegnet snus til −2 > −5.', array['Viser at 2 < 5 blir til −2 og −5 når sidene ganges med −1.', 'Forklarer at −2 > −5, og derfor snus tegnet.']::text[], 2),
  ('matematikk-8:ulikheter', 's04', 'Løs ulikheten 3x − 2 ≥ 7. Vis det viktigste steget.', 'Legg til 2 på begge sider: 3x ≥ 9. Del på 3, så x ≥ 3.', array['Kommer fram til 3x ≥ 9 ved å legge til 2 på begge sider.', 'Får x ≥ 3.']::text[], 3),
  ('matematikk-8:ulikheter', 's05', 'Løs ulikheten −2x > 6. Vis det viktigste steget.', 'Del begge sider på −2 og snu ulikhetstegnet. Da får vi x < −3.', array['Viser at tegnet snus når det deles på −2.', 'Får x < −3.']::text[], 4),
  ('matematikk-8:ulikheter', 's06', 'Sammenlign åpen ring og fylt prikk på en tallinje. Forklar når tallet på ringen eller prikken er med i løsningen.', 'En åpen ring viser at tallet ikke er med, slik som ved < eller >. En fylt prikk viser at tallet er med, slik som ved ≤ eller ≥.', array['Forklarer at åpen ring betyr at tallet ikke er med.', 'Forklarer at fylt prikk betyr at tallet er med.']::text[], 5),
  ('matematikk-8:ulikheter', 's07', 'Ulikheten x ≥ −4 beskriver mulige verdier for x, men x er et antall billetter. Hvilke av verdiene kan være gyldige som antall, og hvorfor?', 'Som antall kan x være 0 eller et positivt helt tall. Negative verdier er ikke gyldige, selv om de oppfyller x ≥ −4.', array['Sier at antallet må være et helt tall som ikke er negativt.', 'Forklarer at negative tall ikke gir mening som antall billetter.']::text[], 6),
  ('matematikk-8:ulikheter', 's08', 'En regel sier at et antall x kan være høyst 5. Skriv en ulikhet som viser regelen, og forklar om 5 er tillatt.', 'Ulikheten er x ≤ 5. Tallet 5 er tillatt fordi «høyst 5» betyr 5 eller mindre.', array['Skriver x ≤ 5.', 'Forklarer at 5 er med i løsningen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-8:funksjoner', 'matematikk-8', 'funksjoner', 'Funksjoner', 'Hva en funksjon er, og hvordan samme sammenheng kan vises som situasjon, tabell, graf og uttrykk.', array[8, 9]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-8:funksjoner', '## Hva er en funksjon?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-8:funksjoner', 'Funksjon', 'En sammenheng der hver inngangsverdi (x) gir nøyaktig én utgangsverdi (y).', 0),
  ('matematikk-8:funksjoner', 'Uavhengig variabel', 'Verdien vi velger fritt, ofte x. Den står på x-aksen.', 1),
  ('matematikk-8:funksjoner', 'Avhengig variabel', 'Verdien som bestemmes av x, ofte y eller f(x). Den står på y-aksen.', 2),
  ('matematikk-8:funksjoner', 'f(x)', 'Skrivemåte for funksjonsverdien. f(3) er verdien når x = 3.', 3),
  ('matematikk-8:funksjoner', 'Funksjonsuttrykk', 'En formel som gir y ut fra x, for eksempel y = 2x + 100.', 4),
  ('matematikk-8:funksjoner', 'Verditabell', 'En tabell med utvalgte x-verdier og de tilhørende y-verdiene.', 5),
  ('matematikk-8:funksjoner', 'Graf', 'Tegningen av en funksjon i et koordinatsystem.', 6),
  ('matematikk-8:funksjoner', 'Koordinatsystem', 'To akser som står vinkelrett på hverandre: x-aksen vannrett og y-aksen loddrett.', 7),
  ('matematikk-8:funksjoner', 'Origo', 'Punktet (0, 0), der x-aksen og y-aksen krysser hverandre.', 8),
  ('matematikk-8:funksjoner', 'Koordinater (x, y)', 'Et punkts plassering: først x (sideveis), så y (opp eller ned).', 9),
  ('matematikk-8:funksjoner', 'Lineær funksjon', 'En funksjon med en rett linje som graf. Den endrer seg like mye for hver enhet i x.', 10),
  ('matematikk-8:funksjoner', 'Stigningstall', 'Hvor mye y endrer seg når x øker med 1. I y = 2x + 100 er det 2.', 11),
  ('matematikk-8:funksjoner', 'Konstantledd', 'Verdien av y når x = 0. Det er der grafen krysser y-aksen. I y = 2x + 100 er det 100.', 12),
  ('matematikk-8:funksjoner', 'Ikke-lineær funksjon', 'En funksjon med krum graf, for eksempel A = s², som vokser raskere og raskere.', 13),
  ('matematikk-8:funksjoner', 'Skala på aksene', 'Avstanden mellom tallene på aksene. En strukket skala kan få en endring til å se større ut enn den er.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-8:funksjoner', 'q01', 'flervalg', 'Hva er y når x = 5 i funksjonen y = 3x + 2?', array['10', '17', '15', '35']::text[], 1, 'Sett inn x = 5: 3 · 5 + 2 = 15 + 2 = 17.', true, true, 0),
  ('matematikk-8:funksjoner', 'q02', 'flervalg', 'Hva kalles punktet (0, 0) i et koordinatsystem?', array['Origo', 'Konstantleddet', 'Stigningstallet', 'Toppunktet']::text[], 0, 'Origo er punktet der x-aksen og y-aksen krysser hverandre, (0, 0).', true, true, 1),
  ('matematikk-8:funksjoner', 'q03', 'flervalg', 'Et abonnement koster 100 kr per måned pluss 2 kr per minutt. Hvilket uttrykk passer?', array['y = 100x + 2', 'y = 102x', 'y = 2x + 100', 'y = 2 + 100']::text[], 2, 'Minuttprisen ganges med antall minutter (2x), og den faste månedsprisen legges til (100).', true, true, 2),
  ('matematikk-8:funksjoner', 'q04', 'flervalg', 'Hva er stigningstallet i y = −4x + 7?', array['7', '4', 'x', '−4']::text[], 3, 'Stigningstallet er tallet foran x. Her er det −4, så y minker med 4 for hver gang x øker med 1.', true, true, 3),
  ('matematikk-8:funksjoner', 'q05', 'flervalg', 'Hvor krysser grafen til y = 2x + 5 y-aksen?', array['I (0, 5)', 'I (5, 0)', 'I (0, 2)', 'I (2, 5)']::text[], 0, 'På y-aksen er x = 0. Da er y = 2 · 0 + 5 = 5, så skjæringspunktet er (0, 5).', true, true, 4),
  ('matematikk-8:funksjoner', 'q06', 'flervalg', 'Hvilken tabell passer til y = x + 3?', array['x = 1, y = 3', 'x = 2, y = 5', 'x = 3, y = 3', 'x = 4, y = 12']::text[], 1, '2 + 3 = 5. Sjekk de andre: 1 + 3 = 4, 3 + 3 = 6 og 4 + 3 = 7.', true, false, 5),
  ('matematikk-8:funksjoner', 'q07', 'flervalg', 'Hvilken funksjon har en rett linje som graf?', array['A = s²', 'y = x · x', 'y = 5x − 1', 'y = 2ˣ']::text[], 2, 'y = 5x − 1 er lineær: y øker med 5 hver gang x øker med 1. De andre vokser raskere og raskere og gir krumme grafer.', true, true, 6),
  ('matematikk-8:funksjoner', 'q08', 'flervalg', 'I punktet (4, −2), hva er y-koordinaten?', array['4', '2', '−4', '−2']::text[], 3, 'Koordinatene skrives (x, y). Den andre verdien, −2, er y-koordinaten.', true, false, 7),
  ('matematikk-8:funksjoner', 'q09', 'flervalg', 'En graf over temperaturen i en kopp te synker raskt først og så langsommere. Hvordan ser grafen ut?', array['En rett linje som stiger', 'En krum linje som synker og flater ut', 'En vannrett linje', 'En rett linje som synker like mye hele tiden']::text[], 1, 'Endringen er ikke lik hele tiden, så grafen er krum. Den synker bratt først og blir flatere etter hvert.', true, true, 8),
  ('matematikk-8:funksjoner', 'q10', 'flervalg', 'Hvorfor starter grafen for abonnementsprisen i x = 0?', array['Fordi funksjonen ikke kan tegnes for negative tall', 'Fordi prisen er 0 der', 'Fordi antall minutter ikke kan være negativt', 'Fordi stigningstallet er positivt']::text[], 2, 'x står for antall minutter, og det gir ikke mening med negative minutter. Grafen tegnes derfor bare for x ≥ 0.', true, true, 9),
  ('matematikk-8:funksjoner', 'm01', 'sant-usant', 'I en funksjon kan én x-verdi gi to ulike y-verdier.', array['Sant', 'Usant']::text[], 1, 'I en funksjon gir hver x-verdi nøyaktig én y-verdi.', false, true, 10),
  ('matematikk-8:funksjoner', 'm02', 'sant-usant', 'Grafen til y = 3x + 1 er en rett linje.', array['Sant', 'Usant']::text[], 0, 'Funksjonen er lineær: y øker med 3 hver gang x øker med 1.', false, true, 11),
  ('matematikk-8:funksjoner', 'm03', 'sant-usant', 'Den uavhengige variabelen tegnes langs y-aksen.', array['Sant', 'Usant']::text[], 1, 'Den uavhengige variabelen, x, står langs den vannrette x-aksen.', false, true, 12),
  ('matematikk-8:funksjoner', 'm04', 'sant-usant', 'En strukket skala på y-aksen kan få en liten endring til å se stor ut.', array['Sant', 'Usant']::text[], 0, 'Derfor må du alltid sjekke tallene på aksene når du leser en graf.', false, true, 13),
  ('matematikk-8:funksjoner', 'm05', 'flervalg', 'Hva er f(2) når f(x) = x² + 1?', array['5', '3', '4', '9']::text[], 0, 'Sett inn x = 2: 2² + 1 = 4 + 1 = 5.', false, true, 14),
  ('matematikk-8:funksjoner', 'm06', 'flervalg', 'Hvilket punkt ligger på grafen til y = 2x − 1?', array['(1, 2)', '(2, 3)', '(3, 4)', '(0, 1)']::text[], 1, 'Med x = 2 blir y = 2 · 2 − 1 = 3. Punktet (2, 3) ligger derfor på grafen.', false, true, 15),
  ('matematikk-8:funksjoner', 'm07', 'flervalg', 'Et taxiselskap tar 50 kr + 12 kr per km. Hva er konstantleddet?', array['12', '62', '50', '600']::text[], 2, 'Konstantleddet er den faste delen som ikke avhenger av antall km, altså 50 kr.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-8:funksjoner', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-8:funksjoner', 's01', 'Hva må være sant om inngangsverdiene og utgangsverdiene for at en sammenheng skal være en funksjon?', 'Hver inngangsverdi må gi nøyaktig én utgangsverdi. Ulike inngangsverdier kan likevel gi samme utgangsverdi.', array['Sier at hver inngangsverdi har nøyaktig én utgangsverdi.', 'Skiller mellom én utgangsverdi per inngang og at utgangsverdiene må være ulike.']::text[], 0),
  ('matematikk-8:funksjoner', 's02', 'Arealet av et kvadrat er gitt ved A = s², der s er sidelengden. Hvilken variabel er uavhengig, hvilken er avhengig, og hvilken akse skal hver stå på i en graf?', 'Sidelengden s er den uavhengige variabelen og står på x-aksen. Arealet A er avhengig av s og står på y-aksen.', array['Identifiserer s som uavhengig og A som avhengig.', 'Plasserer s på x-aksen og A på y-aksen.']::text[], 1),
  ('matematikk-8:funksjoner', 's03', 'En funksjon er gitt ved f(x) = 2x + 100. Regn ut f(3), og vis det viktigste regnestykket.', 'f(3) = 2 · 3 + 100 = 106.', array['Setter x = 3 inn i uttrykket.', 'Får svaret 106.']::text[], 2),
  ('matematikk-8:funksjoner', 's04', 'Arealet av et kvadrat er A = s². Regn ut arealet når sidelengden s er 4, og vis det viktigste regnestykket.', 'A = 4² = 16. Arealet er 16 kvadratenheter.', array['Setter 4 inn for s og regner 4².', 'Får arealet 16.']::text[], 3),
  ('matematikk-8:funksjoner', 's05', 'Sammenlign grafene til den lineære funksjonen y = 2x + 100 og den ikke-lineære funksjonen A = s². Hvordan ser grafene ut, og hvordan endrer verdiene seg?', 'Grafen til y = 2x + 100 er en rett linje og øker like mye for hver enhet x øker. Grafen til A = s² er krum, og arealet vokser raskere og raskere.', array['Beskriver grafen til den lineære funksjonen som en rett linje med jevn endring.', 'Beskriver A = s² som krum og med økende vekst.']::text[], 4),
  ('matematikk-8:funksjoner', 's06', 'For abonnementet y = 2x + 100 viser verditabellen at x = 50 gir y = 200. Hva betyr dette i situasjonen, og hvordan kan verdiene vises på grafen?', 'Det betyr at abonnementet koster 200 kr når det brukes i 50 minutter. På grafen svarer det til punktet (50, 200).', array['Tolk­er x = 50 og y = 200 riktig i situasjonen.', 'Knytter verdiene til punktet (50, 200) på grafen.']::text[], 5),
  ('matematikk-8:funksjoner', 's07', 'En graf ser svært bratt ut. Hvorfor bør du undersøke skalaen på aksene før du bestemmer hvor stor endringen egentlig er?', 'En strukket skala på y-aksen kan få endringen til å se større ut enn den er. Derfor må du se på hvilke verdier og avstander aksene viser.', array['Forklarer at skalaen kan få endringen til å se større eller mindre ut.', 'Sier at tallene eller avstandene på aksene må undersøkes.']::text[], 6),
  ('matematikk-8:funksjoner', 's08', 'Beskriv hvordan du finner punktet (3, −2) i et koordinatsystem. Hvilken koordinat bruker du først, og hvilken vei går du for den andre?', 'Først går du 3 bortover langs x-aksen. Deretter går du 2 ned, fordi y-koordinaten er −2.', array['Bruker x-koordinaten først og beskriver bevegelsen 3 bortover.', 'Beskriver at den negative y-koordinaten betyr 2 ned.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-8:algoritmer-og-programmering', 'matematikk-8', 'algoritmer-og-programmering', 'Algoritmer og programmering', 'Hva en algoritme er, og hvordan du bruker variabler, løkker og betingelser til å lage, teste og forbedre programmer som løser matematiske oppgaver.', array[10]::int[], 7, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-8:algoritmer-og-programmering', '## Hva er en algoritme?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-8:algoritmer-og-programmering', 'Algoritme', 'En nøyaktig oppskrift som løser et problem steg for steg og stopper etter et endelig antall steg.', 0),
  ('matematikk-8:algoritmer-og-programmering', 'Program', 'En algoritme skrevet i et programmeringsspråk som en datamaskin kan utføre.', 1),
  ('matematikk-8:algoritmer-og-programmering', 'Variabel (i programmering)', 'Et navn som lagrer en verdi som kan endre seg, for eksempel sum = 0.', 2),
  ('matematikk-8:algoritmer-og-programmering', 'Sekvens', 'Kommandoene utføres én etter én i den rekkefølgen de står.', 3),
  ('matematikk-8:algoritmer-og-programmering', 'Løkke', 'En del av programmet som gjentas flere ganger.', 4),
  ('matematikk-8:algoritmer-og-programmering', 'for-løkke', 'En løkke som gjentas et bestemt antall ganger, for eksempel for hvert tall fra 1 til 100.', 5),
  ('matematikk-8:algoritmer-og-programmering', 'while-løkke', 'En løkke som gjentas så lenge en betingelse er sann.', 6),
  ('matematikk-8:algoritmer-og-programmering', 'Betingelse (if)', 'Lar programmet velge hva som skal skje ut fra om noe er sant eller usant.', 7),
  ('matematikk-8:algoritmer-og-programmering', '% (modulo)', 'Gir resten ved divisjon. 17 % 5 = 2. Et tall er partall hvis tall % 2 == 0.', 8),
  ('matematikk-8:algoritmer-og-programmering', 'print', 'Kommando i Python som skriver ut en verdi eller tekst på skjermen.', 9),
  ('matematikk-8:algoritmer-og-programmering', 'Flytskjema', 'En tegning av en algoritme med bokser for handlinger og valg, bundet sammen med piler.', 10),
  ('matematikk-8:algoritmer-og-programmering', 'Teste', 'Kjøre programmet med verdier der du kjenner svaret, for å se om det virker.', 11),
  ('matematikk-8:algoritmer-og-programmering', 'Feilsøke', 'Finne og rette feil i et program, for eksempel ved å skrive ut mellomverdier.', 12),
  ('matematikk-8:algoritmer-og-programmering', 'Evig løkke', 'En løkke der betingelsen aldri blir usann, slik at programmet aldri stopper.', 13),
  ('matematikk-8:algoritmer-og-programmering', 'Effektiv algoritme', 'En algoritme som bruker få steg. Summen 1 + … + n kan regnes direkte med n(n + 1)/2.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-8:algoritmer-og-programmering', 'q01', 'flervalg', 'Hva er en algoritme?', array['Et dataprogram som bare kan skrives i Python', 'En nøyaktig trinnvis oppskrift for å løse et problem', 'En type graf', 'Et matematisk bevis']::text[], 1, 'En algoritme er en steg-for-steg-oppskrift. Den kan skrives på papir, som flytskjema eller som et program.', true, true, 0),
  ('matematikk-8:algoritmer-og-programmering', 'q02', 'flervalg', 'Hvilken byggestein brukes til å gjenta kode mange ganger?', array['Variabel', 'Betingelse', 'print', 'Løkke']::text[], 3, 'En løkke gjentar kommandoene inni seg, enten et bestemt antall ganger (for) eller så lenge noe er sant (while).', true, true, 1),
  ('matematikk-8:algoritmer-og-programmering', 'q03', 'flervalg', 'Hva er 23 % 5 i Python?', array['3', '4', '4,6', '18']::text[], 0, '% gir resten ved divisjon. 23 = 4 · 5 + 3, så resten er 3.', true, true, 2),
  ('matematikk-8:algoritmer-og-programmering', 'q04', 'flervalg', 'Et program skal legge sammen tallene fra 1 til 100. Hva blir svaret?', array['100', '5000', '5050', '10 100']::text[], 2, 'Med formelen n(n + 1)/2: 100 · 101 / 2 = 5050. Et riktig program med løkke gir samme svar.', true, true, 3),
  ('matematikk-8:algoritmer-og-programmering', 'q05', 'flervalg', 'Hvilken betingelse sjekker om tallet t er et partall?', array['t % 2 == 1', 't / 2 == 0', 't % 2 == 0', 't == 2']::text[], 2, 'Et partall gir rest 0 ved deling på 2. Derfor bruker vi t % 2 == 0.', true, true, 4),
  ('matematikk-8:algoritmer-og-programmering', 'q06', 'flervalg', 'Hvorfor tester vi et program med tall der vi kjenner svaret?', array['For å se om programmet gir riktig resultat', 'For å gjøre programmet raskere', 'Fordi datamaskinen krever det', 'For å slippe å bruke variabler']::text[], 0, 'Kjenner du svaret på forhånd, kan du sammenligne og oppdage om programmet regner feil.', true, false, 5),
  ('matematikk-8:algoritmer-og-programmering', 'q07', 'flervalg', 'Hva kalles en løkke som aldri stopper?', array['En for-løkke', 'En evig løkke', 'En betingelse', 'En sekvens']::text[], 1, 'Hvis betingelsen i en while-løkke aldri blir usann, fortsetter løkka i det uendelige.', true, true, 6),
  ('matematikk-8:algoritmer-og-programmering', 'q08', 'flervalg', 'Hva gjør linjen sum = sum + n inne i en løkke?', array['Setter sum lik n', 'Sjekker om sum er lik n', 'Skriver ut summen', 'Legger n til den verdien sum allerede har']::text[], 3, 'Høyre side regnes ut først med den gamle verdien av sum. Resultatet lagres så som ny verdi i sum.', true, true, 7),
  ('matematikk-8:algoritmer-og-programmering', 'q09', 'flervalg', 'Hvilken metode er ofte nyttig når du feilsøker?', array['Slette hele programmet', 'Skrive ut verdien av variablene underveis', 'Bytte programmeringsspråk', 'Kjøre programmet raskere']::text[], 1, 'Ved å skrive ut mellomverdier ser du hvor programmet begynner å oppføre seg annerledes enn du venter.', true, false, 8),
  ('matematikk-8:algoritmer-og-programmering', 'q10', 'flervalg', 'Hva betyr det at en algoritme er forbedret?', array['Den har fått flere linjer', 'Den bruker flere variabler', 'Den gir samme riktige svar, men er for eksempel raskere eller gjelder flere tilfeller', 'Den gir et annet svar enn før']::text[], 2, 'En forbedret algoritme løser fortsatt problemet riktig, men mer effektivt, oversiktlig eller generelt.', true, true, 9),
  ('matematikk-8:algoritmer-og-programmering', 'm01', 'sant-usant', 'En algoritme må alltid skrives i et programmeringsspråk.', array['Sant', 'Usant']::text[], 1, 'En algoritme kan også skrives med vanlige ord, som punktliste eller som flytskjema.', false, true, 10),
  ('matematikk-8:algoritmer-og-programmering', 'm02', 'sant-usant', 'En for-løkke brukes ofte når vi vet hvor mange ganger noe skal gjentas.', array['Sant', 'Usant']::text[], 0, 'For-løkka går gjennom et bestemt område, for eksempel tallene fra 1 til 10.', false, true, 11),
  ('matematikk-8:algoritmer-og-programmering', 'm03', 'sant-usant', 'I Python har innrykk betydning for hvilke linjer som hører til en løkke.', array['Sant', 'Usant']::text[], 0, 'Linjer med innrykk under en for- eller if-setning hører til den. Feil innrykk gir feil oppførsel.', false, true, 12),
  ('matematikk-8:algoritmer-og-programmering', 'm04', 'sant-usant', '17 % 3 er lik 5.', array['Sant', 'Usant']::text[], 1, '% gir resten. 17 = 5 · 3 + 2, så 17 % 3 = 2. Tallet 5 er kvotienten, ikke resten.', false, true, 13),
  ('matematikk-8:algoritmer-og-programmering', 'm05', 'flervalg', 'Hva skrives ut? x = 3, så x = x · 2, så print(x)', array['3', '6', '5', '32']::text[], 1, 'x starter som 3. Linjen x = x · 2 gir x ny verdi 3 · 2 = 6, og det er dette som skrives ut.', false, true, 14),
  ('matematikk-8:algoritmer-og-programmering', 'm06', 'flervalg', 'Hvilken formel gir summen 1 + 2 + … + n direkte?', array['n²', '2n + 1', 'n(n + 1)/2', 'n + 100']::text[], 2, 'n(n + 1)/2 gir for eksempel 4 · 5 / 2 = 10 for n = 4, og 1 + 2 + 3 + 4 = 10.', false, true, 15),
  ('matematikk-8:algoritmer-og-programmering', 'm07', 'flervalg', 'Hva gjør en if-setning?', array['Gjentar kode', 'Lagrer en verdi', 'Skriver ut tekst', 'Lar programmet velge ut fra om noe er sant']::text[], 3, 'En if-setning sjekker en betingelse og utfører kode bare hvis betingelsen er sann.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-8:algoritmer-og-programmering', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-8:algoritmer-og-programmering', 's01', 'Hva er forskjellen på en algoritme og et program?', 'En algoritme er en nøyaktig oppskrift som løser et problem steg for steg. Et program er en algoritme skrevet i et programmeringsspråk som en datamaskin kan utføre.', array['Forklarer at en algoritme er en stegvis oppskrift for å løse et problem.', 'Forklarer at et program er skrevet i et språk datamaskinen kan utføre.']::text[], 0),
  ('matematikk-8:algoritmer-og-programmering', 's02', 'En variabel har verdien 2. Et program legger til 4 i variabelen tre ganger og skriver så ut verdien. Hva skrives ut, og hvordan finner du svaret?', 'Programmet skriver ut 14. Verdien starter på 2 og øker med 4 tre ganger: 2 + 4 + 4 + 4 = 14.', array['Oppgir at verdien som skrives ut, er 14.', 'Viser at 4 legges til startverdien tre ganger.']::text[], 1),
  ('matematikk-8:algoritmer-og-programmering', 's03', 'Sammenlign en for-løkke og en while-løkke. Når gjentas kommandoene i hver av dem?', 'En for-løkke gjentas et bestemt antall ganger. En while-løkke gjentas så lenge en betingelse er sann.', array['Forklarer at en for-løkke gjentas et bestemt antall ganger.', 'Forklarer at en while-løkke fortsetter mens betingelsen er sann.']::text[], 2),
  ('matematikk-8:algoritmer-og-programmering', 's04', 'Et program gjør dette i rekkefølge: Setter a til 5, legger 2 til a, skriver ut a og ganger deretter a med 2. Hvilket tall skriver programmet ut? Forklar hvilket steg som bestemmer svaret.', 'Programmet skriver ut 7. Før utskriften blir 2 lagt til 5, og multiplikasjonen skjer først etter at tallet er skrevet ut.', array['Oppgir at programmet skriver ut 7.', 'Tar hensyn til at kommandoene utføres i rekkefølge, slik at utskriften skjer før multiplikasjonen.']::text[], 3),
  ('matematikk-8:algoritmer-og-programmering', 's05', 'Et program bruker uttrykket 17 % 5. Hva blir verdien, og hva forteller den?', 'Verdien blir 2. Modulo gir resten når 17 deles på 5.', array['Oppgir at verdien er 2.', 'Forklarer at modulo gir resten ved divisjon.']::text[], 4),
  ('matematikk-8:algoritmer-og-programmering', 's06', 'Et program skriver ut «partall» hvis tall % 2 == 0, og ellers skriver det ut «oddetall». Hva skriver programmet ut for tallene 18 og 19, og hvorfor?', 'For 18 skriver programmet ut «partall», fordi 18 er delelig med 2 uten rest. For 19 skriver det ut «oddetall», fordi divisjonen med 2 gir en rest.', array['Oppgir riktig utskrift for både 18 og 19.', 'Knytter valget til om tallet er delelig med 2 uten rest.']::text[], 5),
  ('matematikk-8:algoritmer-og-programmering', 's07', 'I en while-løkke er betingelsen «n < 5», og n starter på 1. Inne i løkka skrives n ut, men verdien til n endres aldri. Hvorfor kan programmet fortsette for alltid, og hva kan endres for at det skal stoppe?', 'Programmet kan fortsette for alltid fordi n fortsatt er 1, så betingelsen n < 5 alltid er sann. Løkka må endre n slik at det til slutt blir 5 eller større.', array['Forklarer at betingelsen aldri blir usann fordi n ikke endres.', 'Foreslår at n endres slik at det til slutt ikke lenger er mindre enn 5.']::text[], 6),
  ('matematikk-8:algoritmer-og-programmering', 's08', 'Du skal finne summen 1 + 2 + 3 + 4 + 5 + 6. Bruk formelen n(n + 1)/2 til å regne ut summen, og vis det viktigste regnestykket.', 'Her er n = 6, så summen blir 6 · (6 + 1) / 2 = 6 · 7 / 2 = 21.', array['Setter n til 6 og bruker formelen n(n + 1)/2.', 'Oppgir at summen er 21.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-8:word-classes-and-sentences', 'engelsk-8', 'word-classes-and-sentences', 'Word classes and sentence structure', 'The main word classes in English, basic word order, and how knowing them helps you write clearer and more correct sentences.', array[8, 9]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-8:word-classes-and-sentences', '## Why grammar?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-8:word-classes-and-sentences', 'Noun', 'A word that names a person, place, thing or idea: teacher, Oslo, happiness.', 0),
  ('engelsk-8:word-classes-and-sentences', 'Verb', 'A word that shows an action or a state: run, think, be.', 1),
  ('engelsk-8:word-classes-and-sentences', 'Adjective', 'A word that describes a noun: a tall building. Does not change in the plural.', 2),
  ('engelsk-8:word-classes-and-sentences', 'Adverb', 'Describes a verb, adjective or sentence, often how, when or where. Many end in -ly.', 3),
  ('engelsk-8:word-classes-and-sentences', 'Pronoun', 'A word that replaces a noun: I, you, she, they, them.', 4),
  ('engelsk-8:word-classes-and-sentences', 'Preposition', 'Shows relation in place or time: in, on, at, under, after.', 5),
  ('engelsk-8:word-classes-and-sentences', 'Conjunction', 'Joins words and clauses: and, but, or, because.', 6),
  ('engelsk-8:word-classes-and-sentences', 'Determiner', 'Comes before a noun: a, the, this, my, some.', 7),
  ('engelsk-8:word-classes-and-sentences', 'a or an?', '“a” before a consonant sound, “an” before a vowel sound: an hour, a university.', 8),
  ('engelsk-8:word-classes-and-sentences', 'S-V-O', 'Subject – verb – object: basic English word order. Emma likes pizza.', 9),
  ('engelsk-8:word-classes-and-sentences', 'Time expression first', 'English keeps S-V: “Yesterday I went”, not “Yesterday went I”.', 10),
  ('engelsk-8:word-classes-and-sentences', 'do-support', 'Questions and negatives with most verbs use do/does/did: Do you like it?', 11),
  ('engelsk-8:word-classes-and-sentences', 'Clause', 'A group of words with a subject and a verb.', 12),
  ('engelsk-8:word-classes-and-sentences', 'Main clause', 'A clause that can stand alone as a sentence.', 13),
  ('engelsk-8:word-classes-and-sentences', 'Subordinate clause', 'A clause that cannot stand alone: because it was raining.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-8:word-classes-and-sentences', 'q01', 'flervalg', 'Which word is an adjective in “The old dog slept quietly”?', array['dog', 'old', 'slept', 'quietly']::text[], 1, '“Old” describes the noun “dog”. “Quietly” is an adverb describing how the dog slept.', true, true, 0),
  ('engelsk-8:word-classes-and-sentences', 'q02', 'flervalg', 'Which is correct?', array['a hour', 'an university', 'an hour', 'a apple']::text[], 2, '“Hour” starts with a vowel sound because the h is silent, so we use “an”.', true, true, 1),
  ('engelsk-8:word-classes-and-sentences', 'q03', 'flervalg', 'Which sentence has correct English word order?', array['Yesterday I went to the cinema.', 'Yesterday went I to the cinema.', 'Yesterday to the cinema I went.', 'I yesterday went to the cinema to.']::text[], 0, 'English keeps subject + verb even when the sentence starts with a time expression.', true, true, 2),
  ('engelsk-8:word-classes-and-sentences', 'q04', 'flervalg', 'What is the plural of “child”?', array['childs', 'childes', 'childrens', 'children']::text[], 3, '“Child” has an irregular plural: children.', true, true, 3),
  ('engelsk-8:word-classes-and-sentences', 'q05', 'flervalg', 'Which word is a conjunction?', array['under', 'because', 'quickly', 'they']::text[], 1, '“Because” joins a subordinate clause to a main clause.', true, true, 4),
  ('engelsk-8:word-classes-and-sentences', 'q06', 'flervalg', 'How do you make “She likes fish” negative?', array['She not likes fish.', 'She don''t like fish.', 'She doesn''t like fish.', 'She likes not fish.']::text[], 2, 'Most verbs need do-support in negatives. With he/she/it we use “does not” (doesn''t) + the base form.', true, true, 5),
  ('engelsk-8:word-classes-and-sentences', 'q07', 'flervalg', 'What is the subject in “My brother plays football”?', array['My brother', 'plays', 'football', 'plays football']::text[], 0, 'The subject is who does the action: my brother.', true, false, 6),
  ('engelsk-8:word-classes-and-sentences', 'q08', 'flervalg', 'Which is NOT a complete sentence?', array['I stayed at home.', 'It was raining.', 'Because it was raining.', 'I stayed at home because it was raining.']::text[], 2, '“Because it was raining” is a subordinate clause and cannot stand alone.', true, true, 7),
  ('engelsk-8:word-classes-and-sentences', 'q09', 'flervalg', 'Which word is an adverb?', array['beautiful', 'beauty', 'beautify', 'beautifully']::text[], 3, '“Beautifully” tells how something is done. Many adverbs are formed by adding -ly to an adjective.', true, false, 8),
  ('engelsk-8:word-classes-and-sentences', 'q10', 'flervalg', 'Which is correct?', array['They are tall buildings.', 'They are talls buildings.', 'They are tall buildingses.', 'They are talls building.']::text[], 0, 'English adjectives never take a plural ending. Only the noun changes: buildings.', true, true, 9),
  ('engelsk-8:word-classes-and-sentences', 'm01', 'sant-usant', 'English adjectives get an -s in the plural, like “bigs cars”.', array['Sant', 'Usant']::text[], 1, 'English adjectives never change for plural: big cars.', false, true, 10),
  ('engelsk-8:word-classes-and-sentences', 'm02', 'sant-usant', '“An” is used before words that start with a vowel sound.', array['Sant', 'Usant']::text[], 0, 'It is the sound, not the letter, that decides: an hour, a university.', false, true, 11),
  ('engelsk-8:word-classes-and-sentences', 'm03', 'sant-usant', 'A subordinate clause can stand alone as a full sentence.', array['Sant', 'Usant']::text[], 1, 'A subordinate clause needs a main clause to make a complete sentence.', false, true, 12),
  ('engelsk-8:word-classes-and-sentences', 'm04', 'sant-usant', '“Under” is a preposition.', array['Sant', 'Usant']::text[], 0, '“Under” shows a relation in place: under the table.', false, true, 13),
  ('engelsk-8:word-classes-and-sentences', 'm05', 'flervalg', 'Which question is correct?', array['Like you pizza?', 'Do you like pizza?', 'You like pizza do?', 'Does you like pizza?']::text[], 1, 'Questions with most verbs need “do” before the subject: Do you like pizza?', false, true, 14),
  ('engelsk-8:word-classes-and-sentences', 'm06', 'flervalg', 'Which word is a pronoun?', array['them', 'table', 'green', 'slowly']::text[], 0, '“Them” replaces a noun, for example “the students”.', false, true, 15),
  ('engelsk-8:word-classes-and-sentences', 'm07', 'flervalg', 'Which article is correct? “She is … engineer.”', array['a', 'the a', 'an', 'no article']::text[], 2, '“Engineer” starts with a vowel sound, so we use “an”. English also needs an article with jobs: She is an engineer.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-8:word-classes-and-sentences', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-8:word-classes-and-sentences', 's01', 'Explain the difference between a noun and a pronoun. Give an example where a pronoun replaces a noun, such as “teacher” being replaced by “she”.', 'A noun names a person, place, thing or idea. A pronoun replaces a noun: “The teacher is here. She is here.”', array['Explains that a noun names a person, place, thing or idea.', 'Explains that a pronoun replaces a noun, with an example that shows this.']::text[], 0),
  ('engelsk-8:word-classes-and-sentences', 's02', 'Change “a tall building” to the plural. Explain what happens to the adjective.', 'The plural is “tall buildings”. The adjective “tall” does not change in the plural.', array['Gives “tall buildings” as the plural form.', 'Explains that the adjective stays the same in the plural.']::text[], 1),
  ('engelsk-8:word-classes-and-sentences', 's03', 'Explain why both “an hour” and “a university” use the correct article.', '“An” comes before a vowel sound, and the h in “hour” is silent. “University” starts with a “you” sound, which is a consonant sound, so it takes “a”.', array['Connects “an” in “an hour” to the vowel sound at the start.', 'Connects “a” in “a university” to its starting consonant sound.']::text[], 2),
  ('engelsk-8:word-classes-and-sentences', 's04', 'Why is “Yesterday I went to the cinema” correct, while “Yesterday went I to the cinema” is not?', 'Even when a time expression comes first, English keeps the subject before the verb. In the correct sentence, “I” comes before “went”.', array['Explains that the subject stays before the verb after a time expression.', 'Uses the sentence to show that “I” must come before “went”.']::text[], 3),
  ('engelsk-8:word-classes-and-sentences', 's05', 'Turn “You like music.” into a question. Explain the job of the extra verb you add.', '“Do you like music?” The helping verb “do” is used to form the question.', array['Forms the question as “Do you like music?” or an equivalent correct question.', 'Explains that “do” is a helping verb used to form the question.']::text[], 4),
  ('engelsk-8:word-classes-and-sentences', 's06', 'Why can “because it was raining” not stand alone as a sentence? Add a main clause to make it a complex sentence.', 'It has a subject and a verb, but it is a subordinate clause and cannot stand alone. “I stayed at home because it was raining” is a complex sentence.', array['Explains that the clause is subordinate and cannot stand alone.', 'Adds a main clause that can stand alone and forms a complex sentence with the given clause.']::text[], 5),
  ('engelsk-8:word-classes-and-sentences', 's07', 'Compare the adjective in “a quiet room” with the adverb in “speaks quietly”. What does each word describe?', '“Quiet” is an adjective that describes the noun “room”. “Quietly” is an adverb that describes the verb “speaks”.', array['Explains that the adjective describes a noun.', 'Explains that the adverb describes a verb.']::text[], 6),
  ('engelsk-8:word-classes-and-sentences', 's08', 'Write one English sentence that contains a preposition showing place or time and a conjunction joining clauses. Name both words and explain what each one does.', '“The book is on the desk because I need it.” “On” is a preposition showing place, and “because” is a conjunction joining clauses.', array['Uses a preposition correctly to show a relation in place or time.', 'Uses a conjunction to join words or clauses and explains its role.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-8:verb-tenses', 'engelsk-8', 'verb-tenses', 'Verb tenses', 'Present simple and continuous, past simple, present perfect and the future – how they are formed, when to use them, and the most common irregular verbs.', array[9, 8]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-8:verb-tenses', '## Tense tells us when
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-8:verb-tenses', 'Present simple', 'Habits, routines and facts: I walk to school every day.', 0),
  ('engelsk-8:verb-tenses', 'Third person -s', 'He, she and it add -s in the present simple: she walks, he goes.', 1),
  ('engelsk-8:verb-tenses', 'Present continuous', 'am/is/are + -ing, for things happening now: I am reading.', 2),
  ('engelsk-8:verb-tenses', 'Past simple', 'Finished actions at a specific past time: I visited London last year.', 3),
  ('engelsk-8:verb-tenses', 'Regular past', 'Add -ed: play – played, walk – walked.', 4),
  ('engelsk-8:verb-tenses', 'Present perfect', 'have/has + past participle: I have visited London. Links past and present.', 5),
  ('engelsk-8:verb-tenses', 'Present perfect + since/for', 'I have lived here since 2020 / for five years.', 6),
  ('engelsk-8:verb-tenses', 'Not with finished time', 'Use past simple with “yesterday”: I saw him yesterday, not “have seen”.', 7),
  ('engelsk-8:verb-tenses', 'will', 'Predictions and quick decisions: It will rain. I''ll help you!', 8),
  ('engelsk-8:verb-tenses', 'be going to', 'Plans and things we can see coming: I''m going to study tonight.', 9),
  ('engelsk-8:verb-tenses', 'go – went – gone', 'Irregular verb.', 10),
  ('engelsk-8:verb-tenses', 'see – saw – seen', 'Irregular verb.', 11),
  ('engelsk-8:verb-tenses', 'buy – bought – bought', 'Irregular verb.', 12),
  ('engelsk-8:verb-tenses', 'write – wrote – written', 'Irregular verb.', 13),
  ('engelsk-8:verb-tenses', 'Stative verbs', 'Verbs like know, like and want are rarely used with -ing: I know, not “I am knowing”.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-8:verb-tenses', 'q01', 'flervalg', 'Choose the correct form: “She … to school every day.”', array['walk', 'walks', 'walking', 'is walk']::text[], 1, 'A daily routine uses the present simple, and “she” needs the third person -s: walks.', true, true, 0),
  ('engelsk-8:verb-tenses', 'q02', 'flervalg', 'Choose the correct form: “Be quiet! The baby …”', array['sleeps', 'slept', 'is sleeping', 'has slept']::text[], 2, 'Something happening right now uses the present continuous: is sleeping.', true, true, 1),
  ('engelsk-8:verb-tenses', 'q03', 'flervalg', 'What is the past simple of “go”?', array['goed', 'gone', 'going', 'went']::text[], 3, '“Go” is irregular: go – went – gone.', true, true, 2),
  ('engelsk-8:verb-tenses', 'q04', 'flervalg', 'Which sentence is correct?', array['I saw him yesterday.', 'I have seen him yesterday.', 'I have see him yesterday.', 'I seen him yesterday.']::text[], 0, '“Yesterday” is a finished time, so we need the past simple: I saw him yesterday.', true, true, 3),
  ('engelsk-8:verb-tenses', 'q05', 'flervalg', 'Choose the correct form: “We … here since 2020.”', array['live', 'lived', 'have lived', 'are live']::text[], 2, 'An action that started in the past and continues now, with “since”, uses the present perfect.', true, true, 4),
  ('engelsk-8:verb-tenses', 'q06', 'flervalg', 'Which future form fits best? “Look at those dark clouds! It … rain.”', array['is going to', 'rains', 'has rained', 'rained']::text[], 0, 'When we can see something coming, we use “be going to”.', true, true, 5),
  ('engelsk-8:verb-tenses', 'q07', 'flervalg', 'What is the past participle of “write”?', array['wrote', 'writed', 'written', 'writing']::text[], 2, 'write – wrote – written. The past participle is used with have/has: I have written.', true, true, 6),
  ('engelsk-8:verb-tenses', 'q08', 'flervalg', 'Which sentence is correct?', array['I am knowing the answer.', 'I know the answer.', 'I knowing the answer.', 'I am know the answer.']::text[], 1, '“Know” is a stative verb and is not normally used in the continuous form.', true, false, 7),
  ('engelsk-8:verb-tenses', 'q09', 'flervalg', 'What is the past simple of “buy”?', array['buyed', 'bought', 'brought', 'buy']::text[], 1, 'buy – bought – bought. Do not mix it up with bring – brought.', true, false, 8),
  ('engelsk-8:verb-tenses', 'q10', 'flervalg', 'Choose the correct form: “She has never … to Spain.”', array['be', 'was', 'went', 'been']::text[], 3, 'The present perfect uses has + past participle. The past participle of “be” is “been”.', true, true, 9),
  ('engelsk-8:verb-tenses', 'm01', 'sant-usant', '“He play football” is correct in the present simple.', array['Sant', 'Usant']::text[], 1, 'With “he”, the verb needs an -s: he plays.', false, true, 10),
  ('engelsk-8:verb-tenses', 'm02', 'sant-usant', 'The present perfect is formed with have/has + past participle.', array['Sant', 'Usant']::text[], 0, 'Example: I have finished my homework.', false, true, 11),
  ('engelsk-8:verb-tenses', 'm03', 'sant-usant', '“I''m going to” can be used about plans.', array['Sant', 'Usant']::text[], 0, 'Example: I''m going to visit my grandmother this weekend.', false, true, 12),
  ('engelsk-8:verb-tenses', 'm04', 'sant-usant', 'All English verbs form the past simple by adding -ed.', array['Sant', 'Usant']::text[], 1, 'Many common verbs are irregular: go – went, see – saw.', false, true, 13),
  ('engelsk-8:verb-tenses', 'm05', 'flervalg', 'What is the past simple of “think”?', array['thinked', 'thought', 'thank', 'thunk']::text[], 1, 'think – thought – thought.', false, true, 14),
  ('engelsk-8:verb-tenses', 'm06', 'flervalg', 'Choose the correct form: “I … my keys. I can''t find them anywhere.”', array['lose', 'am losing', 'have lost', 'lost yesterday']::text[], 2, 'The present perfect shows a past action with a result now: the keys are still lost.', false, true, 15),
  ('engelsk-8:verb-tenses', 'm07', 'flervalg', 'Choose the correct form: “Every summer we … to the mountains.”', array['go', 'are going now', 'gone', 'has gone']::text[], 0, '“Every summer” shows a habit, so we use the present simple.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-8:verb-tenses', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-8:verb-tenses', 's01', 'Compare “I read every evening” and “I am reading now.” Explain what each verb form tells us.', '“Read” is present simple and describes a habit. “Am reading” is present continuous and describes something happening now.', array['Explains that present simple is used for habits or routines.', 'Explains that present continuous is used for something happening now.']::text[], 0),
  ('engelsk-8:verb-tenses', 's02', 'Explain the difference between “He watches” and “They watch.” Which subjects get -s in the present simple?', 'In the present simple, the verb gets -s with he, she and it. “They” does not take -s, so we say “They watch.”', array['States that he, she and it take -s in the present simple.', 'Distinguishes this from subjects such as they, which do not take -s.']::text[], 1),
  ('engelsk-8:verb-tenses', 's03', 'Give the past simple forms of “walk” and “take.” Explain how the form of a regular verb differs from an irregular verb.', 'The past simple forms are “walked” and “took.” A regular verb adds -ed, while an irregular verb changes form and must be learned.', array['Gives “walked” and “took” as the correct past simple forms.', 'Explains that regular verbs add -ed but irregular verbs change form.']::text[], 2),
  ('engelsk-8:verb-tenses', 's04', 'Explain why “I visited London last year” uses past simple, while “I have visited London” uses present perfect.', '“Last year” is a finished time, so the sentence uses past simple. The present perfect does not state a finished time and connects the past to the present.', array['Connects past simple with a finished, stated time.', 'Explains that present perfect links the past to the present and is not used with a finished time.']::text[], 3),
  ('engelsk-8:verb-tenses', 's05', 'Someone started living in a place five years ago and still lives there. Write a present perfect sentence using “for,” and explain what “for” tells us.', '“I have lived here for five years.” “For five years” tells us how long the person has lived there, and the present perfect connects this past period to the present.', array['Uses have/has with a past participle in a sentence about something continuing to the present.', 'Explains that “for” gives the length of time.']::text[], 4),
  ('engelsk-8:verb-tenses', 's06', 'You decide right now to help someone. Another person has already planned to study tonight. Write a sentence for each situation using “will” and “be going to,” and explain why each form fits.', '“I’ll help you” uses will for a quick decision. “I’m going to study tonight” uses be going to for a plan.', array['Uses will for the decision made at that moment.', 'Uses be going to for the plan made earlier.']::text[], 5),
  ('engelsk-8:verb-tenses', 's07', 'A meeting is already arranged for six o’clock. Write a sentence using the present continuous to describe it, and explain why this tense is suitable.', '“We are meeting at six.” The present continuous can describe a fixed arrangement.', array['Writes a suitable present continuous sentence with am/is/are and a verb ending in -ing.', 'Explains that the tense is used for fixed arrangements.']::text[], 6),
  ('engelsk-8:verb-tenses', 's08', 'Correct “I am liking this song” and explain why the verb form needs to change.', '“I like this song.” “Like” is a stative verb and is rarely used in the present continuous.', array['Corrects the sentence to “I like this song.”', 'Explains that stative verbs such as “like” are rarely used with -ing.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-8:learning-strategies-and-vocabulary', 'engelsk-8', 'learning-strategies-and-vocabulary', 'Learning strategies and vocabulary', 'Smart ways to learn and remember English words, use dictionaries and digital tools wisely, and build a varied vocabulary with idioms and synonyms.', array[1, 2, 5]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-8:learning-strategies-and-vocabulary', '## Learning a language takes strategies
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-8:learning-strategies-and-vocabulary', 'Learning strategy', 'A conscious method that helps you understand, remember and use a language.', 0),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Context', 'The words and sentences around a word, which help you understand its meaning.', 1),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Spaced repetition', 'Repeating words with longer and longer gaps: after a day, a few days, a week.', 2),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Active vocabulary', 'Words you can use yourself when you speak and write.', 3),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Passive vocabulary', 'Words you understand when you read or hear them, but do not use yourself.', 4),
  ('engelsk-8:learning-strategies-and-vocabulary', 'English–English dictionary', 'A dictionary that explains English words in English.', 5),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Translation tool', 'Useful, but often translates word by word and can choose the wrong meaning.', 6),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Synonym', 'A word with a similar meaning: big – large – huge.', 7),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Antonym', 'A word with the opposite meaning: happy – sad.', 8),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Collocation', 'Words that naturally go together: heavy rain, make a mistake.', 9),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Idiom', 'An expression whose meaning is different from its individual words.', 10),
  ('engelsk-8:learning-strategies-and-vocabulary', 'It''s raining cats and dogs', 'It is raining heavily.', 11),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Piece of cake', 'Something very easy.', 12),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Break a leg', 'Good luck (often said before a performance).', 13),
  ('engelsk-8:learning-strategies-and-vocabulary', 'Overused words', 'Words like nice, good and said, which can be replaced by more precise words.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-8:learning-strategies-and-vocabulary', 'q01', 'flervalg', 'Why is it smart to learn words in context?', array['Because it is faster to write', 'Because words are easier to remember and use correctly in a sentence', 'Because lists are forbidden', 'Because context words are shorter']::text[], 1, 'In a sentence you see how the word is used, which helps you remember it and use it correctly.', true, true, 0),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q02', 'flervalg', 'What does “spaced repetition” mean?', array['Repeating words with longer and longer gaps', 'Repeating a word 100 times in a row', 'Writing words with spaces between the letters', 'Learning only new words']::text[], 0, 'Repeating words just before you forget them helps them stay in your long-term memory.', true, true, 1),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q03', 'flervalg', 'Which word is a synonym of “enormous”?', array['tiny', 'quick', 'huge', 'empty']::text[], 2, '“Huge” and “enormous” both mean very big. “Tiny” is an antonym.', true, true, 2),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q04', 'flervalg', 'What does the idiom “piece of cake” mean?', array['A dessert', 'A small part of something', 'A birthday', 'Something very easy']::text[], 3, '“The test was a piece of cake” means the test was very easy.', true, true, 3),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q05', 'flervalg', 'Which is a natural collocation?', array['make a mistake', 'do a mistake', 'take a mistake', 'create a mistake']::text[], 0, 'In English we “make” a mistake. Collocations must often be learned as fixed phrases.', true, true, 4),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q06', 'flervalg', 'What is a risk with translation tools?', array['They are always correct', 'They can translate word by word and choose the wrong meaning', 'They only work in Norwegian', 'They make texts shorter']::text[], 1, 'Translation tools can miss the context. Always check if the result sounds natural.', true, true, 5),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q07', 'flervalg', 'Which word could replace “said” to show that someone was angry?', array['whispered', 'mumbled', 'asked', 'shouted']::text[], 3, '“Shouted” shows volume and emotion, which makes the text more vivid.', true, false, 6),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q08', 'flervalg', 'What does “It''s raining cats and dogs” mean?', array['Animals are falling from the sky', 'It is raining heavily', 'It is a nice day', 'It has stopped raining']::text[], 1, 'This idiom means that it is raining very hard.', true, true, 7),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q09', 'flervalg', 'What is an antonym of “ancient”?', array['old', 'historic', 'modern', 'large']::text[], 2, '“Ancient” means very old, and “modern” is the opposite.', true, false, 8),
  ('engelsk-8:learning-strategies-and-vocabulary', 'q10', 'flervalg', 'Which mistake will a spell checker often NOT find?', array['“their” used instead of “there”', '“becuase” instead of “because”', '“teh” instead of “the”', '“freind” instead of “friend”']::text[], 0, '“Their” is a real word, so the spell checker does not react, even when it is used wrongly.', true, true, 9),
  ('engelsk-8:learning-strategies-and-vocabulary', 'm01', 'sant-usant', 'An idiom always means exactly what the words say.', array['Sant', 'Usant']::text[], 1, 'An idiom has a meaning that is different from the individual words.', false, true, 10),
  ('engelsk-8:learning-strategies-and-vocabulary', 'm02', 'sant-usant', 'Using new words when you speak helps you remember them.', array['Sant', 'Usant']::text[], 0, 'Words you use actively become part of your active vocabulary.', false, true, 11),
  ('engelsk-8:learning-strategies-and-vocabulary', 'm03', 'sant-usant', '“Heavy rain” is a common collocation in English.', array['Sant', 'Usant']::text[], 0, 'English speakers say “heavy rain”, not “strong rain”.', false, true, 12),
  ('engelsk-8:learning-strategies-and-vocabulary', 'm04', 'sant-usant', 'A translation tool is always right.', array['Sant', 'Usant']::text[], 1, 'Translation tools can misunderstand context and give unnatural or wrong results.', false, true, 13),
  ('engelsk-8:learning-strategies-and-vocabulary', 'm05', 'flervalg', 'What does “break a leg” usually mean?', array['Be careful', 'Good luck', 'Go home', 'Hurry up']::text[], 1, '“Break a leg” is said to wish someone good luck, especially before a performance.', false, true, 14),
  ('engelsk-8:learning-strategies-and-vocabulary', 'm06', 'flervalg', 'Which word is more precise than “good” in “The film was good”?', array['thing', 'fine', 'brilliant', 'ok']::text[], 2, '“Brilliant” gives a clearer picture of how good the film was.', false, true, 15),
  ('engelsk-8:learning-strategies-and-vocabulary', 'm07', 'flervalg', 'What should you do first when you meet an unknown word?', array['Try to guess its meaning from the context', 'Stop reading', 'Skip the whole paragraph', 'Translate the whole text']::text[], 0, 'The context often gives you a clue. Look the word up if it is important.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-8:learning-strategies-and-vocabulary', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-8:learning-strategies-and-vocabulary', 's01', 'Explain what a learning strategy is and how it helps someone learn a language.', 'A learning strategy is a method you choose to help you understand, remember or use a language. Trying different strategies can help you find what works best for you.', array['Explains that it is a conscious method for learning a language.', 'Explains how it supports understanding, remembering or using the language.']::text[], 0),
  ('engelsk-8:learning-strategies-and-vocabulary', 's02', 'Explain the difference between active and passive vocabulary.', 'Active vocabulary includes words you can use when you speak or write. Passive vocabulary includes words you understand when you read or hear them but do not use yourself.', array['Explains that active words are words you can use yourself.', 'Explains that passive words are understood but not used by you.']::text[], 1),
  ('engelsk-8:learning-strategies-and-vocabulary', 's03', 'You read: “The food was delicious; everyone enjoyed how tasty it was.” You do not know the word “delicious”. What can you work out from the sentence, and what can you do before looking the word up?', 'The sentence suggests that “delicious” means very tasty. I can use the surrounding words to guess its meaning before looking it up.', array['Uses the clues in the sentence to infer that “delicious” means tasty or very good to eat.', 'Explains that you should look at the surrounding words before looking the word up.']::text[], 2),
  ('engelsk-8:learning-strategies-and-vocabulary', 's04', 'You want to remember new English words throughout a week. Describe a flashcard plan that uses spaced repetition.', 'I would review the flashcards after a day, then after a few days, and then after a week. The gaps between reviews get longer each time.', array['Includes reviews after a day, a few days and a week.', 'Shows that the gaps between reviews become longer.']::text[], 3),
  ('engelsk-8:learning-strategies-and-vocabulary', 's05', 'What information can an English dictionary give you about a word besides its meaning? Name two kinds of information.', 'It can show how to pronounce the word and what word class it belongs to. It can also give example sentences.', array['Names two relevant kinds of information, such as pronunciation, word class or example sentences.']::text[], 4),
  ('engelsk-8:learning-strategies-and-vocabulary', 's06', 'Make this sentence more precise by replacing “good” with a better word: “The food was good.”', 'The food was delicious.', array['Replaces “good” with a more precise word that describes enjoyable-tasting food, such as “delicious”.']::text[], 5),
  ('engelsk-8:learning-strategies-and-vocabulary', 's07', 'A friend is going to perform on stage. Write an English expression you could say to wish them luck, and explain what it means.', 'I could say, “Break a leg!” It means “good luck”.', array['Uses “Break a leg” in the situation.', 'Explains that the expression means good luck.']::text[], 6),
  ('engelsk-8:learning-strategies-and-vocabulary', 's08', 'A suggested weekly goal for learning English is to learn ten new words. State this goal and explain one way you could check your progress.', 'My goal is to learn ten new words this week. I can check my progress by seeing how many of the words I have learned by the end of the week.', array['States the goal of learning ten new words in a week.', 'Describes checking progress against the goal.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-8:writing-narratives', 'engelsk-8', 'writing-narratives', 'Writing narratives', 'How to plan, write and revise a story in English: structure, point of view, dialogue, descriptive language and using feedback.', array[14, 15, 9]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-8:writing-narratives', '## What is a narrative?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-8:writing-narratives', 'Narrative', 'A text that tells a story, real or made up.', 0),
  ('engelsk-8:writing-narratives', 'Character', 'A person or creature in a story.', 1),
  ('engelsk-8:writing-narratives', 'Setting', 'Where and when a story takes place.', 2),
  ('engelsk-8:writing-narratives', 'Plot', 'What happens in the story; the sequence of events.', 3),
  ('engelsk-8:writing-narratives', 'Conflict', 'The problem or struggle that drives the story forward.', 4),
  ('engelsk-8:writing-narratives', 'Climax', 'The most exciting moment and turning point of the story.', 5),
  ('engelsk-8:writing-narratives', 'Resolution', 'The ending, where the problem is solved or the story is rounded off.', 6),
  ('engelsk-8:writing-narratives', 'In medias res', 'Starting a story in the middle of the action.', 7),
  ('engelsk-8:writing-narratives', 'First-person narrator', 'The story is told by a character using “I”.', 8),
  ('engelsk-8:writing-narratives', 'Third-person narrator', 'The story is told about “he”, “she” or “they”.', 9),
  ('engelsk-8:writing-narratives', 'Show, don''t tell', 'Show feelings through actions and details instead of naming them.', 10),
  ('engelsk-8:writing-narratives', 'Dialogue', 'Characters speaking. Use quotation marks and a new line for each speaker.', 11),
  ('engelsk-8:writing-narratives', 'Linking words', 'Words like first, suddenly, meanwhile, finally that create flow.', 12),
  ('engelsk-8:writing-narratives', 'Past tense in stories', 'Most stories are written in the past tense. Keep the same tense throughout.', 13),
  ('engelsk-8:writing-narratives', 'Revise', 'Improve a text after feedback: content, structure, language and spelling.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-8:writing-narratives', 'q01', 'flervalg', 'What is the setting of a story?', array['The main character', 'Where and when the story takes place', 'The ending', 'The title']::text[], 1, 'The setting tells the reader the place and time of the story.', true, true, 0),
  ('engelsk-8:writing-narratives', 'q02', 'flervalg', 'What is the climax of a story?', array['The first sentence', 'The list of characters', 'The most exciting moment and turning point', 'The author''s name']::text[], 2, 'The climax is where the tension is highest and something important changes.', true, true, 1),
  ('engelsk-8:writing-narratives', 'q03', 'flervalg', 'Which sentence “shows” rather than “tells”?', array['She was very nervous.', 'He was sad.', 'They were happy.', 'Her hands were shaking as she opened the letter.']::text[], 3, 'The shaking hands show that she is nervous, without naming the feeling.', true, true, 2),
  ('engelsk-8:writing-narratives', 'q04', 'flervalg', 'How is dialogue usually written in English?', array['With quotation marks and a new line for each speaker', 'In capital letters', 'Without any punctuation', 'In brackets']::text[], 0, 'Quotation marks show what is said, and a new line makes it clear who is speaking.', true, true, 3),
  ('engelsk-8:writing-narratives', 'q05', 'flervalg', 'What tense are most stories written in?', array['Present continuous', 'Past tense', 'Future tense', 'It does not matter, you can change often']::text[], 1, 'Most stories use the past tense, and it is important to stay in the same tense.', true, true, 4),
  ('engelsk-8:writing-narratives', 'q06', 'flervalg', 'What does a first-person narrator use?', array['“I”', '“he” or “she”', '“you”', '“they” only']::text[], 0, 'The first-person narrator is a character in the story who tells it as “I”.', true, false, 5),
  ('engelsk-8:writing-narratives', 'q07', 'flervalg', 'Which verb is more precise than “walked slowly”?', array['went', 'moved', 'crept', 'did']::text[], 2, '“Crept” tells the reader that the character moved slowly and quietly.', true, true, 6),
  ('engelsk-8:writing-narratives', 'q08', 'flervalg', 'What is the conflict in a story?', array['The title', 'The problem or struggle that drives the story', 'The setting', 'The last sentence']::text[], 1, 'Without a conflict, there is little to keep the reader interested.', true, true, 7),
  ('engelsk-8:writing-narratives', 'q09', 'flervalg', 'Which is a linking word that shows something unexpected?', array['finally', 'first', 'then', 'suddenly']::text[], 3, '“Suddenly” signals a surprising change in the story.', true, false, 8),
  ('engelsk-8:writing-narratives', 'q10', 'flervalg', 'What should you do with feedback on your story?', array['Ignore it', 'Use it to revise and improve the text', 'Delete the story', 'Only fix the title']::text[], 1, 'Feedback helps you see your text through a reader''s eyes, so you can make it better.', true, true, 9),
  ('engelsk-8:writing-narratives', 'm01', 'sant-usant', 'A story must always start at the very beginning of the events.', array['Sant', 'Usant']::text[], 1, 'Many stories start in the middle of the action to catch the reader''s attention.', false, true, 10),
  ('engelsk-8:writing-narratives', 'm02', 'sant-usant', 'You should start a new line when a new character speaks.', array['Sant', 'Usant']::text[], 0, 'This makes it clear who is speaking in a dialogue.', false, true, 11),
  ('engelsk-8:writing-narratives', 'm03', 'sant-usant', 'Using your senses in descriptions makes a story more vivid.', array['Sant', 'Usant']::text[], 0, 'Details about what characters see, hear and feel bring the story to life.', false, true, 12),
  ('engelsk-8:writing-narratives', 'm04', 'sant-usant', 'It is good style to switch between past and present tense often.', array['Sant', 'Usant']::text[], 1, 'Switching tense by accident confuses the reader. Stay in one tense.', false, true, 13),
  ('engelsk-8:writing-narratives', 'm05', 'flervalg', 'Which opening grabs the reader''s attention best?', array['This is a story about a boy.', 'The door slammed shut behind me, and the lights went out.', 'Once there was a day.', 'I will now tell a story.']::text[], 1, 'Starting in the middle of dramatic action makes the reader want to know more.', false, true, 14),
  ('engelsk-8:writing-narratives', 'm06', 'flervalg', 'What is the resolution of a story?', array['The beginning', 'The climax', 'The ending, where the problem is solved or rounded off', 'The dialogue']::text[], 2, 'The resolution ties up the story after the climax.', false, true, 15),
  ('engelsk-8:writing-narratives', 'm07', 'flervalg', 'Which verb could replace “said” when someone speaks very quietly?', array['whispered', 'yelled', 'screamed', 'shouted']::text[], 0, '“Whispered” tells the reader that the character speaks very quietly.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-8:writing-narratives', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-8:writing-narratives', 's01', 'Explain in your own words what makes a text a narrative. Can a narrative be real, made up, or both?', 'A narrative is a text that tells a story. It can be about something real or something made up.', array['Explains that a narrative tells a story.', 'States that a narrative can be real or made up.']::text[], 0),
  ('engelsk-8:writing-narratives', 's02', 'After a conflict appears in a story, what does the rising action do before the climax? Explain how it changes the story.', 'The rising action builds tension and moves the story towards the climax, the most exciting turning point.', array['Explains that the tension builds.', 'Connects the rising action to the climax or turning point.']::text[], 1),
  ('engelsk-8:writing-narratives', 's03', 'Compare a first-person narrator with a third-person narrator. Explain how each tells the story and what a third-person narrator can sometimes show.', 'A first-person narrator tells the story as “I”, while a third-person narrator tells it about “he”, “she” or “they”. A third-person narrator can sometimes show several characters’ thoughts.', array['Distinguishes between telling the story as “I” and telling it about “he”, “she” or “they”.', 'Explains that a third-person narrator can show several characters’ thoughts.']::text[], 2),
  ('engelsk-8:writing-narratives', 's04', 'Write one sentence that shows a character is afraid without using the word “afraid”. Use an action or a detail the character can sense.', 'Her hands were shaking, and she could hear her own heartbeat.', array['Uses a concrete action or sensory detail.', 'Makes it clear that the character is afraid without naming the feeling.']::text[], 3),
  ('engelsk-8:writing-narratives', 's05', 'A character is trying to open a locked door. Write an opening that starts in the middle of this action, before explaining who the character is or where they are.', 'I yanked the handle again, but the locked door would not move.', array['Begins during the action rather than with background information.', 'Makes the reader understand that the character is trying to open the door.']::text[], 4),
  ('engelsk-8:writing-narratives', 's06', 'Rewrite these events in the past tense, keeping the tense consistent: “I open the door. I hear a noise. I run outside.”', 'I opened the door, heard a noise, and ran outside.', array['Changes all the actions to past tense.', 'Keeps the tense consistent throughout.']::text[], 5),
  ('engelsk-8:writing-narratives', 's07', 'In a story, a character cannot find a key and is unable to open a door. At the end, the character finds the key and opens the door. Explain which part is the resolution and why.', 'The ending, where the character finds the key and opens the door, is the resolution. It solves the problem of being unable to open the door.', array['Identifies the ending as the resolution.', 'Explains that the problem is solved.']::text[], 6),
  ('engelsk-8:writing-narratives', 's08', 'A story has a character and a setting, but the reader cannot understand the order of events. What story element should the writer make clearer, and what does it include?', 'The writer should make the plot clearer. The plot is what happens in the story and the sequence of events.', array['Names the plot as the element to clarify.', 'Explains that it includes what happens and the sequence of events.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-8:english-around-the-world', 'engelsk-8', 'english-around-the-world', 'English around the world', 'Why English became a world language, where it is spoken, differences between British and American English, and the role English plays in Norway.', array[16, 4, 7]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-8:english-around-the-world', '## A global language
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-8:english-around-the-world', 'First language', 'The language a person learns first, as a child.', 0),
  ('engelsk-8:english-around-the-world', 'Second language', 'A language used in daily life in addition to the first language, often in the country one lives in.', 1),
  ('engelsk-8:english-around-the-world', 'Lingua franca', 'A shared language used between people with different first languages.', 2),
  ('engelsk-8:english-around-the-world', 'British Empire', 'The territories ruled by Britain from the 1600s to the 1900s, which spread English around the world.', 3),
  ('engelsk-8:english-around-the-world', 'Why English spread', 'The British Empire, and later the economic and cultural power of the USA.', 4),
  ('engelsk-8:english-around-the-world', 'Official language', 'A language with legal status in a country, like English in India and Nigeria.', 5),
  ('engelsk-8:english-around-the-world', 'Accent', 'The way people pronounce a language.', 6),
  ('engelsk-8:english-around-the-world', 'Dialect', 'A variety of a language with its own words, grammar and pronunciation.', 7),
  ('engelsk-8:english-around-the-world', 'colour / color', 'British and American spelling of the same word.', 8),
  ('engelsk-8:english-around-the-world', 'flat / apartment', 'British and American words for “leilighet”.', 9),
  ('engelsk-8:english-around-the-world', 'autumn / fall', 'British and American words for “høst”.', 10),
  ('engelsk-8:english-around-the-world', 'Be consistent', 'Stick to either British or American spelling in one text.', 11),
  ('engelsk-8:english-around-the-world', 'Domain loss', 'When a language, like Norwegian, is pushed aside by another language in an area such as research.', 12),
  ('engelsk-8:english-around-the-world', 'Loanword', 'A word borrowed from another language, like “weekend” in Norwegian.', 13),
  ('engelsk-8:english-around-the-world', 'eventually', 'False friend: means “til slutt”, not “eventuelt”.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-8:english-around-the-world', 'q01', 'flervalg', 'What is a lingua franca?', array['A French dialect', 'A shared language between people with different first languages', 'An old form of English', 'A type of accent']::text[], 1, 'English often works as a lingua franca, for example when a Norwegian and a Japanese person talk together.', true, true, 0),
  ('engelsk-8:english-around-the-world', 'q02', 'flervalg', 'Which historical development spread English to many continents?', array['The Viking Age', 'The Roman Empire', 'The British Empire', 'The Olympic Games']::text[], 2, 'The British Empire brought English to North America, Australia, Africa and Asia.', true, true, 1),
  ('engelsk-8:english-around-the-world', 'q03', 'flervalg', 'Which is the American spelling?', array['colour', 'centre', 'organise', 'color']::text[], 3, 'Americans write “color”, British English uses “colour”.', true, true, 2),
  ('engelsk-8:english-around-the-world', 'q04', 'flervalg', 'What is the British word for American “elevator”?', array['lift', 'stairs', 'flat', 'tube']::text[], 0, 'British English says “lift”, American English says “elevator”.', true, true, 3),
  ('engelsk-8:english-around-the-world', 'q05', 'flervalg', 'In which country is English an official language alongside many local languages?', array['Norway', 'India', 'Brazil', 'Japan']::text[], 1, 'India has English as one of its official languages, together with Hindi and many regional languages.', true, true, 4),
  ('engelsk-8:english-around-the-world', 'q06', 'flervalg', 'What does “eventually” mean?', array['eventuelt', 'kanskje', 'til slutt', 'straks']::text[], 2, '“Eventually” is a false friend. It means “til slutt” or “etter hvert”.', true, true, 5),
  ('engelsk-8:english-around-the-world', 'q07', 'flervalg', 'What is domain loss?', array['When a language is pushed aside by another language in an area like research or business', 'When you lose a website', 'When a dialect disappears', 'When you forget words']::text[], 0, 'Some fear that Norwegian may lose ground to English in areas like higher education and business.', true, true, 6),
  ('engelsk-8:english-around-the-world', 'q08', 'flervalg', 'Which of these is a loanword from English in Norwegian?', array['hus', 'skog', 'weekend', 'fjell']::text[], 2, '“Weekend” has been borrowed from English and is widely used in Norwegian.', true, false, 7),
  ('engelsk-8:english-around-the-world', 'q09', 'flervalg', 'Is British English more correct than American English?', array['Yes, always', 'Only in writing', 'Only in the UK', 'No, they are equally correct varieties']::text[], 3, 'Both are standard varieties. The important thing is to be consistent.', true, true, 8),
  ('engelsk-8:english-around-the-world', 'q10', 'flervalg', 'What is the American word for British “biscuit”?', array['cookie', 'candy', 'cracker', 'chip']::text[], 0, 'British “biscuit” is usually “cookie” in American English.', true, false, 9),
  ('engelsk-8:english-around-the-world', 'm01', 'sant-usant', 'English is an official language in Nigeria.', array['Sant', 'Usant']::text[], 0, 'English is the official language of Nigeria, where hundreds of other languages are also spoken.', false, true, 10),
  ('engelsk-8:english-around-the-world', 'm02', 'sant-usant', 'British and American English are two completely different languages.', array['Sant', 'Usant']::text[], 1, 'They are varieties of the same language, with some differences in spelling, words and pronunciation.', false, true, 11),
  ('engelsk-8:english-around-the-world', 'm03', 'sant-usant', '“Fall” is the American word for autumn.', array['Sant', 'Usant']::text[], 0, 'Americans usually say “fall”, British speakers “autumn”.', false, true, 12),
  ('engelsk-8:english-around-the-world', 'm04', 'sant-usant', 'You should mix British and American spelling in the same text.', array['Sant', 'Usant']::text[], 1, 'It is best to be consistent and choose one variety.', false, true, 13),
  ('engelsk-8:english-around-the-world', 'm05', 'flervalg', 'What is the British word for American “pants”?', array['shorts', 'trousers', 'jeans', 'socks']::text[], 1, 'British “trousers” are American “pants”. In British English, “pants” means underwear.', false, true, 14),
  ('engelsk-8:english-around-the-world', 'm06', 'flervalg', 'Which country became the leading economic and cultural power in the 1900s?', array['Canada', 'Australia', 'The United States', 'Ireland']::text[], 2, 'American films, music, business and technology spread English further in the 1900s.', false, true, 15),
  ('engelsk-8:english-around-the-world', 'm07', 'flervalg', 'What is an accent?', array['The way people pronounce a language', 'A spelling mistake', 'A type of grammar', 'A dictionary']::text[], 0, 'An accent is about pronunciation. People from different places have different accents.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-8:english-around-the-world', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-8:english-around-the-world', 's01', 'Nora learned Norwegian first as a child. She now lives in a country where she uses English every day in addition to Norwegian. Which is her first language, and which is her second language? Explain your answer.', 'Norwegian is Nora’s first language because she learned it first as a child. English is her second language because she uses it in daily life as well.', array['Identifies Norwegian as her first language because she learned it first.', 'Identifies English as her second language because she uses it in daily life in addition to Norwegian.']::text[], 0),
  ('engelsk-8:english-around-the-world', 's02', 'Britain ruled large parts of the world from the 1600s to the 1900s. Later, the United States became a leading economic and cultural power. Explain how these two developments helped English spread around the world.', 'The British Empire brought English to many parts of the world. Later, the United States helped make English more important through its economic and cultural influence.', array['Explains that British rule brought English to many parts of the world.', 'Explains that the United States’ economic and cultural influence later increased the importance of English.']::text[], 1),
  ('engelsk-8:english-around-the-world', 's03', 'English is the main language in the United Kingdom. In India, English has official status and is used alongside local languages. What is the difference between these two roles of English?', 'In the United Kingdom, English is the main language. In India, it has legal status as an official language but exists alongside local languages.', array['Explains that a main language is the primary language in a country.', 'Explains that an official language has legal status and can be used alongside local languages.']::text[], 2),
  ('engelsk-8:english-around-the-world', 's04', 'Two English speakers pronounce some words differently. Another English variety has its own words, grammar and pronunciation. Explain which description is about an accent and which is about a dialect.', 'Different ways of pronouncing words describe accents. A variety with its own words, grammar and pronunciation is a dialect.', array['Connects accent with differences in pronunciation.', 'Explains that a dialect can differ in words and grammar as well as pronunciation.']::text[], 3),
  ('engelsk-8:english-around-the-world', 's05', 'A student writes “colour, center, organise” in the same piece of writing. Explain what is inconsistent and give one way to fix it.', 'The student has mixed British and American spelling. They can make the spelling consistent by using either “colour, centre, organise” or “color, center, organize”.', array['Identifies that the student has mixed British and American spelling.', 'Gives a consistent British or American set of spellings.']::text[], 4),
  ('engelsk-8:english-around-the-world', 's06', 'In Norway, some people worry that English may push Norwegian aside in research or business. Knowing English can also give Norwegians chances to study, work and communicate internationally. Explain one concern and one benefit of using English in Norway.', 'One concern is that Norwegian could be pushed aside in areas such as research or business. One benefit is that English can help Norwegians study, work and communicate internationally.', array['Describes the concern that English may push Norwegian aside in an area such as research or business.', 'Describes an international opportunity that knowing English can give Norwegians.']::text[], 5),
  ('engelsk-8:english-around-the-world', 's07', 'A Norwegian speaker uses the word “streaming”, borrowed from English. Explain why “streaming” is a loanword and what it shows about Norwegian and English.', '“Streaming” is a loanword because Norwegian has borrowed the word from English. It shows that words can move from one language into another.', array['Explains that a loanword is borrowed from another language.', 'Connects “streaming” in Norwegian to English as its source.']::text[], 6),
  ('engelsk-8:english-around-the-world', 's08', 'Norwegian has words such as “hus” and “bok”, which are similar to the English words “house” and “book”. Explain how comparing words like these can help someone learn English.', 'A learner can use familiar Norwegian words to notice similarities with English words. Comparing them can help the learner learn English vocabulary.', array['Mentions that noticing similarities between known Norwegian words and English words can help learning.', 'Uses “hus/house” or “bok/book” as an example of a similar word pair.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-8:the-united-kingdom', 'engelsk-8', 'the-united-kingdom', 'The United Kingdom', 'The four nations of the UK, the difference between Great Britain and the UK, how the country is governed, and life and diversity in British society.', array[18, 16]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-8:the-united-kingdom', '## Four nations, one kingdom
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-8:the-united-kingdom', 'The United Kingdom (UK)', 'England, Scotland, Wales and Northern Ireland.', 0),
  ('engelsk-8:the-united-kingdom', 'Great Britain', 'The largest island: England, Scotland and Wales.', 1),
  ('engelsk-8:the-united-kingdom', 'British Isles', 'Geographical name for Great Britain, Ireland and the smaller islands around them.', 2),
  ('engelsk-8:the-united-kingdom', 'Republic of Ireland', 'An independent country, not part of the UK.', 3),
  ('engelsk-8:the-united-kingdom', 'Capitals', 'London (England and UK), Edinburgh (Scotland), Cardiff (Wales), Belfast (Northern Ireland).', 4),
  ('engelsk-8:the-united-kingdom', 'Constitutional monarchy', 'A system with a king or queen as head of state, but where elected politicians govern.', 5),
  ('engelsk-8:the-united-kingdom', 'Parliament', 'The UK''s law-making body, with the House of Commons and the House of Lords.', 6),
  ('engelsk-8:the-united-kingdom', 'House of Commons', 'The elected chamber of Parliament.', 7),
  ('engelsk-8:the-united-kingdom', 'Prime Minister', 'The head of government, usually the leader of the largest party in the House of Commons.', 8),
  ('engelsk-8:the-united-kingdom', 'Brexit', 'The UK leaving the EU after the referendum in 2016. The UK left in 2020.', 9),
  ('engelsk-8:the-united-kingdom', 'Referendum', 'A vote where all voters decide on a single question.', 10),
  ('engelsk-8:the-united-kingdom', 'Welsh', 'A Celtic language spoken by many in Wales.', 11),
  ('engelsk-8:the-united-kingdom', 'Union Jack', 'The UK flag, combining the crosses of England, Scotland and Ireland.', 12),
  ('engelsk-8:the-united-kingdom', 'Multicultural', 'A society with people from many different cultures and backgrounds.', 13),
  ('engelsk-8:the-united-kingdom', 'BBC', 'The British Broadcasting Corporation, the UK''s public broadcaster.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-8:the-united-kingdom', 'q01', 'flervalg', 'Which four nations make up the UK?', array['England, Scotland, Wales and Ireland', 'England, Scotland, Wales and Northern Ireland', 'England, Wales, Ireland and Iceland', 'England, Scotland, Ireland and Norway']::text[], 1, 'The UK consists of England, Scotland, Wales and Northern Ireland. The Republic of Ireland is a separate country.', true, true, 0),
  ('engelsk-8:the-united-kingdom', 'q02', 'flervalg', 'What is the capital of Scotland?', array['Glasgow', 'Cardiff', 'Edinburgh', 'Belfast']::text[], 2, 'Edinburgh is the capital of Scotland. Glasgow is the largest city.', true, true, 1),
  ('engelsk-8:the-united-kingdom', 'q03', 'flervalg', 'What is the difference between Great Britain and the UK?', array['They are exactly the same', 'Great Britain is bigger than the UK', 'The UK is only England', 'The UK also includes Northern Ireland']::text[], 3, 'Great Britain is the island with England, Scotland and Wales. The UK adds Northern Ireland.', true, true, 2),
  ('engelsk-8:the-united-kingdom', 'q04', 'flervalg', 'What is the elected chamber of the British Parliament called?', array['The House of Commons', 'The House of Lords', 'The Senate', 'Downing Street']::text[], 0, 'Members of the House of Commons are elected by the people.', true, true, 3),
  ('engelsk-8:the-united-kingdom', 'q05', 'flervalg', 'What does “Brexit” refer to?', array['A British sport', 'The UK leaving the European Union', 'A new British coin', 'The British royal family']::text[], 1, 'Brexit is short for “Britain exit”, the UK leaving the EU after the 2016 referendum.', true, true, 4),
  ('engelsk-8:the-united-kingdom', 'q06', 'flervalg', 'Which language is spoken by many people in Wales?', array['Gaelic', 'Cornish', 'Welsh', 'Scots']::text[], 2, 'Welsh is a Celtic language with official status in Wales.', true, true, 5),
  ('engelsk-8:the-united-kingdom', 'q07', 'flervalg', 'What type of government does the UK have?', array['A constitutional monarchy', 'A dictatorship', 'A republic with a president', 'An absolute monarchy']::text[], 0, 'The King is head of state, but Parliament and the government hold the political power.', true, true, 6),
  ('engelsk-8:the-united-kingdom', 'q08', 'flervalg', 'Who becomes Prime Minister in the UK?', array['The King''s oldest child', 'The mayor of London', 'The oldest member of Parliament', 'Usually the leader of the largest party in the House of Commons']::text[], 3, 'The Prime Minister is usually the leader of the party that can command a majority in the House of Commons.', true, true, 7),
  ('engelsk-8:the-united-kingdom', 'q09', 'flervalg', 'Which famous playwright was British?', array['Henrik Ibsen', 'William Shakespeare', 'Mark Twain', 'Astrid Lindgren']::text[], 1, 'William Shakespeare is one of the most famous writers in the English language.', true, false, 8),
  ('engelsk-8:the-united-kingdom', 'q10', 'flervalg', 'Why is the UK a multicultural society?', array['Because everyone has the same background', 'Because only English is spoken', 'Because people with roots in many countries live there', 'Because of the weather']::text[], 2, 'Immigration from former colonies and other countries has made the UK very diverse.', true, false, 9),
  ('engelsk-8:the-united-kingdom', 'm01', 'sant-usant', 'The Republic of Ireland is part of the UK.', array['Sant', 'Usant']::text[], 1, 'The Republic of Ireland is an independent country. Only Northern Ireland is part of the UK.', false, true, 10),
  ('engelsk-8:the-united-kingdom', 'm02', 'sant-usant', 'The King of the UK has little real political power.', array['Sant', 'Usant']::text[], 0, 'In a constitutional monarchy, elected politicians govern.', false, true, 11),
  ('engelsk-8:the-united-kingdom', 'm03', 'sant-usant', 'Cardiff is the capital of Wales.', array['Sant', 'Usant']::text[], 0, 'Cardiff is the capital and largest city of Wales.', false, true, 12),
  ('engelsk-8:the-united-kingdom', 'm04', 'sant-usant', 'Scotland has its own parliament that decides on some matters.', array['Sant', 'Usant']::text[], 0, 'The Scottish Parliament decides on issues like education and health.', false, true, 13),
  ('engelsk-8:the-united-kingdom', 'm05', 'flervalg', 'When did the UK leave the EU?', array['1973', '2016', '2020', '2008']::text[], 2, 'The referendum was in 2016, but the UK formally left the EU in 2020.', false, true, 14),
  ('engelsk-8:the-united-kingdom', 'm06', 'flervalg', 'What does the Union Jack combine?', array['The crosses of England, Scotland and Ireland', 'The colours of the EU', 'Symbols of London', 'The flags of all Commonwealth countries']::text[], 0, 'The flag combines the crosses of St George, St Andrew and St Patrick.', false, true, 15),
  ('engelsk-8:the-united-kingdom', 'm07', 'flervalg', 'What is the BBC?', array['A football club', 'The UK''s public broadcaster', 'A political party', 'A bank']::text[], 1, 'The British Broadcasting Corporation is a well-known public broadcaster.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-8:the-united-kingdom', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-8:the-united-kingdom', 's01', 'A student says, “The Republic of Ireland is part of the UK because it is in the British Isles.” Explain what is wrong with this statement.', 'The British Isles is a geographical name for Great Britain, Ireland and smaller islands. The Republic of Ireland is an independent country, so it is not part of the UK.', array['Explains that the British Isles is a geographical name, not the name of one country.', 'States that the Republic of Ireland is independent and not part of the UK.']::text[], 0),
  ('engelsk-8:the-united-kingdom', 's02', 'The King is head of state in the UK, while Parliament governs the country. Explain how these roles are different.', 'The King represents the state but has little real political power. Parliament is the body that governs the UK.', array['Explains that the King has little real political power.', 'Explains that Parliament governs the country.']::text[], 1),
  ('engelsk-8:the-united-kingdom', 's03', 'How can London be the capital of both England and the whole UK?', 'London is the capital of England and is also the capital of the UK. The UK includes England as well as Scotland, Wales and Northern Ireland.', array['States that London is the capital of England and the UK.', 'Shows that England is one of the four nations in the UK.']::text[], 2),
  ('engelsk-8:the-united-kingdom', 's04', 'Someone says, “I am Scottish, so I cannot also be British.” Explain why both identities can describe the same person.', 'A person can feel connected to Scotland and call themselves Scottish, while also being British because Scotland is part of the UK. People may identify with their own nation as well as Britain.', array['Explains that Scottish identity and British identity can both apply to one person.', 'Connects this to Scotland being part of the UK or to people feeling connected to both their nation and Britain.']::text[], 3),
  ('engelsk-8:the-united-kingdom', 's05', 'The Union Jack is the flag of the UK. Explain which crosses it combines and what that tells us about the flag.', 'The Union Jack combines the crosses of England, Scotland and Ireland. Its design brings together crosses linked to different parts of the UK.', array['Names the crosses of England, Scotland and Ireland.', 'Explains that the flag combines them in one design.']::text[], 4),
  ('engelsk-8:the-united-kingdom', 's06', 'A school in Birmingham has students whose families have roots in the Caribbean, Africa, South Asia and Europe. Give two examples of how this range of backgrounds may be reflected in city life.', 'A multicultural city may have a variety of food and music. Its different backgrounds may also be reflected in religion and language.', array['Gives two relevant examples, such as food, music, religion or language.', 'Connects the examples to people having different cultural backgrounds.']::text[], 5),
  ('engelsk-8:the-united-kingdom', 's07', 'A classmate says English is the only language used in the UK. Correct them by comparing English with other languages mentioned and where they are used.', 'English is the main language, but it is not the only language used. Many people speak Welsh in Wales, and Scottish Gaelic and Irish are also used.', array['States that English is the main language but not the only one used.', 'Names Welsh and where it is spoken, and mentions Scottish Gaelic or Irish.']::text[], 6),
  ('engelsk-8:the-united-kingdom', 's08', 'A question about education or health comes up in Scotland, Wales or Northern Ireland. Explain which bodies may make decisions about it and how this differs from decisions made in London.', 'Scotland, Wales and Northern Ireland have their own parliaments or assemblies that decide on matters such as education and health. The UK Parliament is in London and governs the whole UK.', array['Identifies the parliaments or assemblies in Scotland, Wales and Northern Ireland as bodies that may decide on these matters.', 'Distinguishes their role from the UK Parliament in London.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-8:online-communication', 'engelsk-fordypning-8', 'online-communication', 'Communicating online', 'How to adapt your English to purpose, receiver and situation in digital communication, how to write a good email, netiquette, and how online communication differs from face-to-face communication.', array[1, 5]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-8:online-communication', '## Communicating in a digital world
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-8:online-communication', 'Purpose', 'Why a text is written, for example to inform, ask or entertain.', 0),
  ('engelsk-fordypning-8:online-communication', 'Receiver', 'The person or group who reads or listens to a message.', 1),
  ('engelsk-fordypning-8:online-communication', 'Register', 'How formal or informal your language is.', 2),
  ('engelsk-fordypning-8:online-communication', 'Informal language', 'Relaxed language used with friends: contractions, slang and emojis.', 3),
  ('engelsk-fordypning-8:online-communication', 'Formal language', 'Polite, correct language used with teachers, employers and strangers.', 4),
  ('engelsk-fordypning-8:online-communication', 'Contraction', 'A short form of two words, like don''t (do not) or I''m (I am).', 5),
  ('engelsk-fordypning-8:online-communication', 'Subject line', 'A short line that tells the receiver what an email is about.', 6),
  ('engelsk-fordypning-8:online-communication', 'Greeting', 'How you start a letter or email, like “Dear Ms Smith,”.', 7),
  ('engelsk-fordypning-8:online-communication', 'Closing', 'How you end a formal email, like “Kind regards,” followed by your name.', 8),
  ('engelsk-fordypning-8:online-communication', 'Netiquette', 'Good manners online.', 9),
  ('engelsk-fordypning-8:online-communication', 'Asynchronous communication', 'Communication where people answer when it suits them, like email.', 10),
  ('engelsk-fordypning-8:online-communication', 'Synchronous communication', 'Communication in real time, like a video call or a live chat.', 11),
  ('engelsk-fordypning-8:online-communication', 'Non-verbal cues', 'Facial expressions, tone of voice and body language.', 12),
  ('engelsk-fordypning-8:online-communication', 'Direct communication', 'Saying exactly what you mean.', 13),
  ('engelsk-fordypning-8:online-communication', 'Indirect communication', 'Expressing yourself more carefully and politely, often with hints.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-8:online-communication', 'q01', 'flervalg', 'What does register mean?', array['The list of students in a class', 'How formal or informal your language is', 'A type of email', 'The subject line']::text[], 1, 'You choose your register depending on who you are talking to.', true, true, 0),
  ('engelsk-fordypning-8:online-communication', 'q02', 'flervalg', 'Which greeting fits a formal email to a teacher?', array['Hey dude!', 'Yo!', 'Sup', 'Dear Ms Smith,']::text[], 3, 'Formal emails start with a polite greeting and the person''s name.', true, true, 1),
  ('engelsk-fordypning-8:online-communication', 'q03', 'flervalg', 'What is netiquette?', array['Good manners online', 'A type of computer virus', 'A social media app', 'A formal letter']::text[], 0, 'The word combines “net” and “etiquette”.', true, true, 2),
  ('engelsk-fordypning-8:online-communication', 'q04', 'flervalg', 'Which is an example of informal language?', array['I would be grateful if you could reply.', 'Kind regards', 'lol brb, gonna grab food', 'Dear Sir or Madam']::text[], 2, 'Abbreviations and slang are typical of informal chat.', true, true, 3),
  ('engelsk-fordypning-8:online-communication', 'q05', 'flervalg', 'Why can jokes easily be misunderstood online?', array['Because the internet is slow', 'Because nobody reads them', 'Because tone of voice and body language are missing', 'Because jokes are not allowed']::text[], 2, 'Without non-verbal cues, irony can be taken seriously.', true, true, 4),
  ('engelsk-fordypning-8:online-communication', 'q06', 'flervalg', 'What is asynchronous communication?', array['Communication where people answer when it suits them, like email', 'A live video call', 'Talking face to face', 'A phone call']::text[], 0, 'The other options happen in real time.', true, true, 5),
  ('engelsk-fordypning-8:online-communication', 'q07', 'flervalg', 'Why should you avoid writing only in capital letters?', array['It is against the law', 'It uses more data', 'It is hard to type', 'It looks like shouting']::text[], 3, 'Capital letters are read as a raised voice online.', true, true, 6),
  ('engelsk-fordypning-8:online-communication', 'q08', 'flervalg', 'Which phrase is a polite way to ask for something in English?', array['Give me that.', 'Could you help me, please?', 'Do it now.', 'I want it.']::text[], 1, '“Could you” and “please” make a request polite.', true, true, 7),
  ('engelsk-fordypning-8:online-communication', 'q09', 'flervalg', 'Why should you think before you post?', array['Because messages can be saved and shared and last a long time', 'Because posting is expensive', 'Because only teachers can post', 'Because posts disappear immediately']::text[], 0, 'Screenshots can spread even if you delete a post.', true, false, 8),
  ('engelsk-fordypning-8:online-communication', 'q10', 'flervalg', 'What is the difference between direct and indirect communication?', array['Direct is written, indirect is spoken', 'Direct is formal, indirect is informal', 'There is no difference', 'Direct means saying exactly what you mean, indirect means being more careful and polite']::text[], 3, 'Cultures often differ in how direct people are.', true, false, 9),
  ('engelsk-fordypning-8:online-communication', 'm01', 'sant-usant', 'It is fine to use slang in a job application email.', array['Sant', 'Usant']::text[], 1, 'A job application should be written in formal language.', false, true, 10),
  ('engelsk-fordypning-8:online-communication', 'm02', 'sant-usant', 'Online, you have fewer non-verbal cues than face to face.', array['Sant', 'Usant']::text[], 0, 'Facial expressions and tone of voice are often missing.', false, true, 11),
  ('engelsk-fordypning-8:online-communication', 'm03', 'sant-usant', 'A good email should have a clear subject line.', array['Sant', 'Usant']::text[], 0, 'The subject line tells the receiver what the email is about.', false, true, 12),
  ('engelsk-fordypning-8:online-communication', 'm04', 'sant-usant', 'People always behave the same online as they do offline.', array['Sant', 'Usant']::text[], 1, 'Feeling anonymous can make people act differently.', false, true, 13),
  ('engelsk-fordypning-8:online-communication', 'm05', 'flervalg', 'Which closing fits a formal email?', array['Cya!', 'Kind regards,', 'XOXO', 'Later!']::text[], 1, '“Kind regards” and “Best wishes” are polite closings.', false, true, 14),
  ('engelsk-fordypning-8:online-communication', 'm06', 'flervalg', 'What is the purpose of a text?', array['Why the text is written', 'How long the text is', 'Who wrote the text', 'Where the text is published']::text[], 0, 'Purpose, receiver and situation decide how you write.', false, true, 15),
  ('engelsk-fordypning-8:online-communication', 'm07', 'flervalg', 'Which of these is a contraction?', array['do not', 'cannot', 'don''t', 'will not']::text[], 2, 'A contraction combines two words with an apostrophe.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-8:online-communication', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-8:online-communication', 's01', 'You need to tell your teacher that you will miss a lesson, and later tell a close friend the same news in a chat. Explain one way your language should differ in each message, and why.', 'I would use polite, formal language with my teacher because the receiver is a teacher. I could use more relaxed, informal language with my friend.', array['Explains that the message to the teacher should be formal or polite and the message to the friend can be informal.', 'Connects the choice of language to who will receive the message.']::text[], 0),
  ('engelsk-fordypning-8:online-communication', 's02', 'Rewrite this as a polite, formal request to your teacher: “hey, can u send me the homework? thx”', 'Could you please send me the homework? Thank you.', array['Uses polite wording to make the request.', 'Uses correct spelling and avoids slang or informal abbreviations.']::text[], 1),
  ('engelsk-fordypning-8:online-communication', 's03', 'Compare an email and a video call. Explain how the timing of replies differs in these two types of communication.', 'An email is asynchronous, so people can reply when it suits them. A video call is synchronous, so people communicate in real time.', array['Explains that email replies do not have to happen straight away.', 'Explains that a video call happens in real time.']::text[], 2),
  ('engelsk-fordypning-8:online-communication', 's04', 'Explain what a contraction is and give one example.', 'A contraction is a shortened form of two words. For example, “I''m” is short for “I am.”', array['Explains that a contraction is a short form made from two words.', 'Gives a correct example and its full form.']::text[], 3),
  ('engelsk-fordypning-8:online-communication', 's05', 'A friend sends you a photo of someone else and asks you to share it in a group chat. What should you do before sharing it, and why?', 'I should ask the person in the photo for permission first. Sharing someone’s picture without permission does not respect their privacy.', array['Says to get permission from the person in the photo before sharing it.', 'Explains that this protects the person’s privacy or respects their choice.']::text[], 4),
  ('engelsk-fordypning-8:online-communication', 's06', 'In a text chat, you cannot see the other person’s face or hear their voice. Name two non-verbal cues that are missing and explain one thing this can make harder.', 'Facial expressions and tone of voice are missing. This can make it harder to understand how someone feels or what they mean.', array['Names two relevant non-verbal cues, such as facial expressions, tone of voice or body language.', 'Explains that missing cues can make feelings or meaning harder to understand.']::text[], 5),
  ('engelsk-fordypning-8:online-communication', 's07', 'In an online school project, one student says exactly what they think, while another expresses ideas carefully and gives hints. Explain how recognising these different communication styles could help them work together.', 'One student is communicating directly, while the other is communicating indirectly. Recognising this can help them avoid misunderstandings and understand each other’s intentions.', array['Identifies the first style as direct and the second as indirect, or explains the difference accurately.', 'Explains how noticing the different styles can help avoid misunderstandings or improve understanding.']::text[], 6),
  ('engelsk-fordypning-8:online-communication', 's08', 'You are writing a formal email about a missed assignment. Why should you put only one main idea in each paragraph of the main message?', 'Putting one main idea in each paragraph makes the email easier to follow. The receiver can understand the message more clearly.', array['Explains that separate paragraphs organise the ideas.', 'Connects this organisation to making the email easier for the receiver to understand.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-8:presenting-your-interests', 'engelsk-fordypning-8', 'presenting-your-interests', 'Presenting your interests', 'How to plan, structure and give a presentation in English about a topic you choose yourself, with good visual aids and confident speaking.', array[9, 2]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-8:presenting-your-interests', '## Sharing what you care about
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-8:presenting-your-interests', 'Presentation', 'A talk where you share information about a topic with an audience.', 0),
  ('engelsk-fordypning-8:presenting-your-interests', 'Narrow a topic', 'Make a wide topic smaller and more specific.', 1),
  ('engelsk-fordypning-8:presenting-your-interests', 'Audience', 'The people who listen to or watch your presentation.', 2),
  ('engelsk-fordypning-8:presenting-your-interests', 'Purpose', 'What you want to achieve: inform, explain, tell a story or persuade.', 3),
  ('engelsk-fordypning-8:presenting-your-interests', 'Hook', 'An opening that catches the audience''s attention.', 4),
  ('engelsk-fordypning-8:presenting-your-interests', 'Main points', 'The two to four most important ideas in the main part.', 5),
  ('engelsk-fordypning-8:presenting-your-interests', 'Conclusion', 'The ending, where you sum up and leave the audience with something memorable.', 6),
  ('engelsk-fordypning-8:presenting-your-interests', 'Linking words', 'Words that guide the audience: first, however, finally, to sum up.', 7),
  ('engelsk-fordypning-8:presenting-your-interests', 'Visual aids', 'Slides, pictures, videos or objects that support your talk.', 8),
  ('engelsk-fordypning-8:presenting-your-interests', 'Key words', 'Short words on slides or cards instead of full sentences.', 9),
  ('engelsk-fordypning-8:presenting-your-interests', 'Cue cards', 'Small cards with key words that help you remember what to say.', 10),
  ('engelsk-fordypning-8:presenting-your-interests', 'Eye contact', 'Looking at your audience to connect with them.', 11),
  ('engelsk-fordypning-8:presenting-your-interests', 'Pace', 'How fast you speak. Not too fast, with pauses after important points.', 12),
  ('engelsk-fordypning-8:presenting-your-interests', 'Body language', 'How you use your posture, face and hands when you speak.', 13),
  ('engelsk-fordypning-8:presenting-your-interests', 'Q&A', 'Questions and answers, often at the end of a presentation.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-8:presenting-your-interests', 'q01', 'flervalg', 'Why should you narrow your topic?', array['To make it clearer and easier to cover well', 'To make the presentation longer', 'To avoid using sources', 'Because wide topics are not allowed']::text[], 0, 'A specific topic lets you go deeper in a short time.', true, true, 0),
  ('engelsk-fordypning-8:presenting-your-interests', 'q02', 'flervalg', 'What is a good way to start a presentation?', array['Reading your slides word for word', 'Saying “I don''t know much about this”', 'Asking a question or sharing a surprising fact', 'Showing the last slide first']::text[], 2, 'A hook makes the audience curious.', true, true, 1),
  ('engelsk-fordypning-8:presenting-your-interests', 'q03', 'flervalg', 'How many main points should a short presentation usually have?', array['One', 'Two to four', 'Ten or more', 'As many as possible']::text[], 1, 'A few well-explained points are easier to remember.', true, true, 2),
  ('engelsk-fordypning-8:presenting-your-interests', 'q04', 'flervalg', 'What should good slides have?', array['Long paragraphs', 'Tiny text', 'No pictures', 'Few words and large, readable text']::text[], 3, 'The audience should listen to you, not read long texts.', true, true, 3),
  ('engelsk-fordypning-8:presenting-your-interests', 'q05', 'flervalg', 'What are cue cards?', array['Tickets to a show', 'Small cards with key words to help you remember', 'Slides with pictures', 'A type of handout']::text[], 1, 'Cue cards help you speak freely instead of reading.', true, true, 4),
  ('engelsk-fordypning-8:presenting-your-interests', 'q06', 'flervalg', 'Which of these is a linking word?', array['Football', 'Slides', 'Audience', 'However']::text[], 3, '“However” shows a contrast between two ideas.', true, true, 5),
  ('engelsk-fordypning-8:presenting-your-interests', 'q07', 'flervalg', 'What should the conclusion do?', array['Sum up the main points and end with something memorable', 'Introduce a completely new topic', 'Apologise for the presentation', 'Only list your sources']::text[], 0, 'A strong ending helps the audience remember your message.', true, true, 6),
  ('engelsk-fordypning-8:presenting-your-interests', 'q08', 'flervalg', 'Why is eye contact important?', array['It makes you speak faster', 'It is required by law', 'It helps you connect with the audience', 'It makes the presentation shorter']::text[], 2, 'Looking at people makes them feel included.', true, true, 7),
  ('engelsk-fordypning-8:presenting-your-interests', 'q09', 'flervalg', 'What is the purpose of a persuasive presentation?', array['To tell a funny story', 'To list facts only', 'To describe a picture', 'To convince the audience of something']::text[], 3, 'Persuasive presentations use arguments to change opinions.', true, false, 8),
  ('engelsk-fordypning-8:presenting-your-interests', 'q10', 'flervalg', 'What should you think about when you consider your audience?', array['What they already know and what will interest them', 'What they are wearing', 'How tall they are', 'Nothing at all']::text[], 0, 'Adapting to your audience makes your presentation more engaging.', true, false, 9),
  ('engelsk-fordypning-8:presenting-your-interests', 'm01', 'sant-usant', 'Your slides should contain your whole manuscript.', array['Sant', 'Usant']::text[], 1, 'Slides should only have key words and pictures.', false, true, 10),
  ('engelsk-fordypning-8:presenting-your-interests', 'm02', 'sant-usant', 'Practising out loud helps you time your presentation.', array['Sant', 'Usant']::text[], 0, 'You also discover where you need to improve.', false, true, 11),
  ('engelsk-fordypning-8:presenting-your-interests', 'm03', 'sant-usant', 'A podcast can also be a way to present a topic.', array['Sant', 'Usant']::text[], 0, 'The same principles of structure and audience apply.', false, true, 12),
  ('engelsk-fordypning-8:presenting-your-interests', 'm04', 'sant-usant', 'You don''t need to show sources for pictures you use.', array['Sant', 'Usant']::text[], 1, 'Pictures are protected by copyright, so you must credit them.', false, true, 13),
  ('engelsk-fordypning-8:presenting-your-interests', 'm05', 'flervalg', 'Which linking words introduce the conclusion?', array['First', 'For example', 'To sum up', 'Another reason']::text[], 2, '“To sum up” signals that you are ending.', false, true, 14),
  ('engelsk-fordypning-8:presenting-your-interests', 'm06', 'flervalg', 'What does good pace mean?', array['Not too fast, with pauses after important points', 'As fast as possible', 'Very quietly', 'Without stopping at all']::text[], 0, 'Pauses give the audience time to think.', false, true, 15),
  ('engelsk-fordypning-8:presenting-your-interests', 'm07', 'flervalg', 'What is a hook?', array['The last slide', 'An opening that catches the audience''s attention', 'A type of cue card', 'A question at the end']::text[], 1, 'A good hook can be a question, a fact or a short story.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-8:presenting-your-interests', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-8:presenting-your-interests', 's01', 'Explain in your own words what a presentation is.', 'A presentation is a talk where someone shares information about a topic with an audience.', array['Explains that someone shares information about a topic.', 'Makes clear that there is an audience.']::text[], 0),
  ('engelsk-fordypning-8:presenting-your-interests', 's02', 'A student wants to present about football. Suggest a narrower topic and explain why it is easier to present than just “football”.', 'The student could present about why football is the world''s most popular sport. This is a smaller, more specific topic, so it is easier to cover well.', array['Suggests a specific topic about football.', 'Explains that a narrower topic is easier to cover well.']::text[], 1),
  ('engelsk-fordypning-8:presenting-your-interests', 's03', 'You want your classmates to learn information about a place you love, not to convince them to visit it. What is the purpose of your presentation? Explain your choice.', 'The purpose is to inform. The aim is to share information about the place, not to persuade the audience.', array['Identifies informing as the purpose.', 'Connects the purpose to sharing information rather than persuading.']::text[], 2),
  ('engelsk-fordypning-8:presenting-your-interests', 's04', 'Compare the role of visual aids with the role of the speaker in a presentation.', 'Visual aids such as slides or pictures support the speaker and can make the presentation clearer. The speaker should explain the topic instead of relying on the slides to do the talking.', array['Explains that visual aids support or clarify the presentation.', 'Makes clear that the speaker, not the visual aids, should do the talking.']::text[], 3),
  ('engelsk-fordypning-8:presenting-your-interests', 's05', 'A student''s slides are full of complete sentences. Give two changes that would make the slides better.', 'The student could replace the sentences with a few key words and use large, readable text. Relevant pictures with sources could also help.', array['Recommends using a few key words instead of full sentences.', 'Gives another suitable improvement, such as large readable text or relevant pictures with sources.']::text[], 4),
  ('engelsk-fordypning-8:presenting-your-interests', 's06', 'A speaker sometimes forgets what to say next. Explain how cue cards could help, and how they should be used.', 'Cue cards can help the speaker remember what to say. They should have key words, so the speaker can use them as reminders instead of reading a manuscript.', array['Explains that cue cards help the speaker remember what to say.', 'Says to use key words as reminders rather than read a manuscript.']::text[], 5),
  ('engelsk-fordypning-8:presenting-your-interests', 's07', 'A student is making a blog post instead of giving a talk. Name two presentation principles the student should still use.', 'The blog post should have a clear structure and be engaging for its audience. The student should also think about who the audience is.', array['Names a clear structure or an engaging presentation.', 'Names another suitable principle, such as considering the audience.']::text[], 6),
  ('engelsk-fordypning-8:presenting-your-interests', 's08', 'During a presentation, a speaker talks too fast and keeps looking down at their notes. Suggest two changes to improve the speaking.', 'The speaker should slow down, speak clearly and pause after important points. They should look at the audience to keep eye contact.', array['Suggests speaking more slowly or pausing after important points.', 'Suggests looking at the audience to keep eye contact.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-8:music-and-lyrics', 'engelsk-fordypning-8', 'music-and-lyrics', 'Music and lyrics', 'How to explore content, form and purpose in songs, the literary devices songwriters use, genres, and how music works in films, games and adverts.', array[4, 7]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-8:music-and-lyrics', '## Why study music?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-8:music-and-lyrics', 'Speaker', 'The voice or character who talks in the lyrics.', 0),
  ('engelsk-fordypning-8:music-and-lyrics', 'Theme', 'What a song is about on a deeper level, like love or identity.', 1),
  ('engelsk-fordypning-8:music-and-lyrics', 'Verse', 'The part of a song that tells the story and changes each time.', 2),
  ('engelsk-fordypning-8:music-and-lyrics', 'Chorus', 'The repeated part with the main message, often the catchiest.', 3),
  ('engelsk-fordypning-8:music-and-lyrics', 'Bridge', 'A contrasting part of a song, often near the end.', 4),
  ('engelsk-fordypning-8:music-and-lyrics', 'Rhyme', 'Words with the same ending sound, like night and light.', 5),
  ('engelsk-fordypning-8:music-and-lyrics', 'Rhythm', 'The beat and flow of words and music.', 6),
  ('engelsk-fordypning-8:music-and-lyrics', 'Repetition', 'Repeating words or lines to make them memorable.', 7),
  ('engelsk-fordypning-8:music-and-lyrics', 'Metaphor', 'Saying something is something else: “You are my sunshine”.', 8),
  ('engelsk-fordypning-8:music-and-lyrics', 'Simile', 'A comparison with like or as: “She runs like the wind”.', 9),
  ('engelsk-fordypning-8:music-and-lyrics', 'Alliteration', 'Repeating the first sound in several words.', 10),
  ('engelsk-fordypning-8:music-and-lyrics', 'Imagery', 'Words that create pictures in your mind.', 11),
  ('engelsk-fordypning-8:music-and-lyrics', 'Protest song', 'A song that criticises something in society.', 12),
  ('engelsk-fordypning-8:music-and-lyrics', 'Genre', 'A type of music with typical features, like pop, hip hop or country.', 13),
  ('engelsk-fordypning-8:music-and-lyrics', 'Music video', 'A video that adds pictures and often a story to a song.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-8:music-and-lyrics', 'q01', 'flervalg', 'What is the chorus of a song?', array['The first line', 'The instrumental part', 'The part that repeats the main message and is often the catchiest', 'The last word']::text[], 2, 'The chorus is usually what people remember and sing along to.', true, true, 0),
  ('engelsk-fordypning-8:music-and-lyrics', 'q02', 'flervalg', 'Which line contains a simile?', array['She runs like the wind', 'The city never sleeps', 'Big, bright balloons', 'I''m on top of the world']::text[], 0, 'A simile uses “like” or “as” to compare.', true, true, 1),
  ('engelsk-fordypning-8:music-and-lyrics', 'q03', 'flervalg', 'What is alliteration?', array['Words that rhyme at the end of lines', 'A comparison using like or as', 'A repeated chorus', 'Repeating the first sound in several words']::text[], 3, '“Big, bright balloons” is an example.', true, true, 2),
  ('engelsk-fordypning-8:music-and-lyrics', 'q04', 'flervalg', 'What is a protest song?', array['A song about love', 'A song that criticises something in society', 'A song for children', 'A song without lyrics']::text[], 1, 'Protest songs were important in the civil rights movement.', true, true, 3),
  ('engelsk-fordypning-8:music-and-lyrics', 'q05', 'flervalg', 'Why do songwriters use repetition?', array['To make lines memorable and emphasise the message', 'Because they run out of ideas', 'To make the song shorter', 'To avoid rhyme']::text[], 0, 'Repetition makes the message stick.', true, true, 4),
  ('engelsk-fordypning-8:music-and-lyrics', 'q06', 'flervalg', 'What is a metaphor?', array['A comparison with like or as', 'A song genre', 'Saying something is something else', 'A long verse']::text[], 2, '“You are my sunshine” describes a person as the sun.', true, true, 5),
  ('engelsk-fordypning-8:music-and-lyrics', 'q07', 'flervalg', 'Which genre is known for rhythm, rhyme and wordplay about life and society?', array['Country', 'Hip hop', 'Classical', 'Opera']::text[], 1, 'Hip hop lyrics often tell stories about everyday life and society.', true, true, 6),
  ('engelsk-fordypning-8:music-and-lyrics', 'q08', 'flervalg', 'What is the speaker in a song?', array['The loudspeaker', 'The producer', 'The person who buys the song', 'The voice or character that talks in the lyrics']::text[], 3, 'The speaker is not always the same as the singer.', true, true, 7),
  ('engelsk-fordypning-8:music-and-lyrics', 'q09', 'flervalg', 'How is music often used in films and games?', array['To replace the dialogue completely', 'To make the film shorter', 'To build mood and tension', 'To show the credits']::text[], 2, 'Music tells us how to feel about what we see.', true, false, 8),
  ('engelsk-fordypning-8:music-and-lyrics', 'q10', 'flervalg', 'What is the first step when analysing a song?', array['Listen several times and read the lyrics', 'Write your opinion', 'Look up the singer''s age', 'Count the words']::text[], 0, 'You need to know the song well before you can analyse it.', true, false, 9),
  ('engelsk-fordypning-8:music-and-lyrics', 'm01', 'sant-usant', 'Songs can be analysed as texts, just like poems.', array['Sant', 'Usant']::text[], 0, 'Songs have content, form and purpose.', false, true, 10),
  ('engelsk-fordypning-8:music-and-lyrics', 'm02', 'sant-usant', 'The bridge is always the first part of a song.', array['Sant', 'Usant']::text[], 1, 'The bridge usually comes near the end.', false, true, 11),
  ('engelsk-fordypning-8:music-and-lyrics', 'm03', 'sant-usant', '“Night” and “light” are an example of rhyme.', array['Sant', 'Usant']::text[], 0, 'They have the same ending sound.', false, true, 12),
  ('engelsk-fordypning-8:music-and-lyrics', 'm04', 'sant-usant', 'Music in adverts has no purpose.', array['Sant', 'Usant']::text[], 1, 'Music makes products memorable and creates feelings.', false, true, 13),
  ('engelsk-fordypning-8:music-and-lyrics', 'm05', 'flervalg', 'What does imagery mean?', array['Pictures in a music video', 'Words that create pictures in your mind', 'The album cover', 'A photo of the band']::text[], 1, 'Imagery appeals to our senses through words.', false, true, 14),
  ('engelsk-fordypning-8:music-and-lyrics', 'm06', 'flervalg', 'Which of these is a typical theme in songs?', array['Heartbreak', 'Tax law', 'Plumbing', 'Algebra']::text[], 0, 'Love and heartbreak are among the most common themes.', false, true, 15),
  ('engelsk-fordypning-8:music-and-lyrics', 'm07', 'flervalg', 'What does a music video add to a song?', array['More verses', 'A longer running time', 'Pictures and often a story', 'A new chorus']::text[], 2, 'The video can strengthen or change how we understand the song.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-8:music-and-lyrics', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-8:music-and-lyrics', 's01', 'Explain how a verse and a chorus are different parts of a song.', 'A verse tells the story and can change from one verse to another. A chorus repeats the song’s main message and is often the catchiest part.', array['Explains that verses tell the story and change.', 'Explains that the chorus repeats the main message.']::text[], 0),
  ('engelsk-fordypning-8:music-and-lyrics', 's02', 'A song has a contrasting section near the end. What is this section called, and how is it different from the other parts?', 'It is called a bridge. It contrasts with the other parts of the song and often comes near the end.', array['Identifies the section as a bridge.', 'Explains that it contrasts with other parts of the song.']::text[], 1),
  ('engelsk-fordypning-8:music-and-lyrics', 's03', 'Explain the difference between rhyme and rhythm in a song.', 'Rhyme is when words have the same ending sound, such as “night” and “light”. Rhythm is the beat and flow of the words and music.', array['Describes rhyme as words sharing an ending sound.', 'Describes rhythm as the beat or flow of words and music.']::text[], 2),
  ('engelsk-fordypning-8:music-and-lyrics', 's04', 'A lyric says, “The golden sun paints the quiet sea.” Explain how this line creates imagery and what it helps the listener imagine.', 'The words create a picture in the listener’s mind of a golden sun and a quiet sea. This is imagery because the words help the listener imagine a scene.', array['Explains that the words create a picture in the mind.', 'Identifies details of the scene the listener can imagine.']::text[], 3),
  ('engelsk-fordypning-8:music-and-lyrics', 's05', 'Compare pop and country music using one typical feature of each genre.', 'Pop often has catchy choruses, while country music is known for storytelling. These are typical features that can help describe the two genres.', array['Gives catchy choruses as a typical pop feature.', 'Gives storytelling as a typical country feature.']::text[], 4),
  ('engelsk-fordypning-8:music-and-lyrics', 's06', 'What does a music video add to a song, and how can it change the way the song is experienced?', 'A music video adds pictures and often a story to a song. These visuals give the listener more to see and follow while hearing the song.', array['Explains that a music video adds pictures.', 'Mentions that it often adds a story or helps the audience experience the song through visuals.']::text[], 5),
  ('engelsk-fordypning-8:music-and-lyrics', 's07', 'An advert uses a song to help people remember a product. Explain why music can be useful for this purpose.', 'Music in adverts can make products memorable. A song can help the advert and the product stay in people’s minds.', array['Connects music in adverts with making a product memorable.', 'Explains that the music can help people remember the advert or product.']::text[], 6),
  ('engelsk-fordypning-8:music-and-lyrics', 's08', 'A song is about someone growing up and has a chorus that repeats a message of hope. Name one content feature and one form feature an analyst could describe, and explain what each tells us.', 'The theme of growing up is a content feature, as it tells us what the song is about on a deeper level. The repeated chorus is a form feature that emphasises the message of hope.', array['Identifies a content feature, such as the theme of growing up.', 'Identifies a form feature, such as the repeated chorus, and explains its role in emphasising the message.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-8:feedback-and-revision', 'engelsk-fordypning-8', 'feedback-and-revision', 'Feedback and revision', 'The writing process, how to give and receive useful feedback, and how to revise and edit your own oral and written English texts.', array[3]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-8:feedback-and-revision', '## Writing is a process
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-8:feedback-and-revision', 'Writing process', 'The stages of writing: pre-writing, drafting, feedback, revising, editing and publishing.', 0),
  ('engelsk-fordypning-8:feedback-and-revision', 'Pre-writing', 'Brainstorming and planning before you start writing.', 1),
  ('engelsk-fordypning-8:feedback-and-revision', 'Draft', 'A first or early version of a text.', 2),
  ('engelsk-fordypning-8:feedback-and-revision', 'Feedback', 'Comments from a reader about what works and what can be improved.', 3),
  ('engelsk-fordypning-8:feedback-and-revision', 'Two stars and a wish', 'Feedback with two positive comments and one suggestion.', 4),
  ('engelsk-fordypning-8:feedback-and-revision', 'Revising', 'Making bigger changes to content, structure and language.', 5),
  ('engelsk-fordypning-8:feedback-and-revision', 'Editing', 'Correcting details like spelling, grammar and punctuation.', 6),
  ('engelsk-fordypning-8:feedback-and-revision', 'Proofreading', 'A final careful check for small mistakes.', 7),
  ('engelsk-fordypning-8:feedback-and-revision', 'Topic sentence', 'A sentence that presents the main idea of a paragraph.', 8),
  ('engelsk-fordypning-8:feedback-and-revision', 'Paragraph', 'A group of sentences about one main idea.', 9),
  ('engelsk-fordypning-8:feedback-and-revision', 'Synonym', 'A word with the same or similar meaning, like big and large.', 10),
  ('engelsk-fordypning-8:feedback-and-revision', 'Subject–verb agreement', 'The verb must match the subject: she goes, they go.', 11),
  ('engelsk-fordypning-8:feedback-and-revision', 'Their / there / they''re', 'Their = belonging to them, there = a place, they''re = they are.', 12),
  ('engelsk-fordypning-8:feedback-and-revision', 'Its / it''s', 'Its = belonging to it, it''s = it is.', 13),
  ('engelsk-fordypning-8:feedback-and-revision', 'Reading aloud', 'A good way to discover mistakes in your own text.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-8:feedback-and-revision', 'q01', 'flervalg', 'What happens in the drafting stage?', array['You publish your text', 'You correct spelling only', 'You brainstorm ideas', 'You write a first version']::text[], 3, 'In the draft, getting ideas down matters more than being perfect.', true, true, 0),
  ('engelsk-fordypning-8:feedback-and-revision', 'q02', 'flervalg', 'Which comment is the most useful feedback?', array['Good job!', 'Your introduction works well because you start with a question', 'I didn''t like it', 'Bad ending']::text[], 1, 'Specific feedback explains what works and why.', true, true, 1),
  ('engelsk-fordypning-8:feedback-and-revision', 'q03', 'flervalg', 'What is the difference between revising and editing?', array['Revising means bigger changes to content and structure, editing means checking details', 'They mean the same', 'Editing is done before writing', 'Revising is only about spelling']::text[], 0, 'Revise first, then edit the details.', true, true, 2),
  ('engelsk-fordypning-8:feedback-and-revision', 'q04', 'flervalg', 'What is “two stars and a wish”?', array['A grading system', 'A type of poem', 'Two positive comments and one suggestion', 'A way to start an essay']::text[], 2, 'The method keeps feedback both kind and useful.', true, true, 3),
  ('engelsk-fordypning-8:feedback-and-revision', 'q05', 'flervalg', 'Which sentence is correct?', array['She go to school every day.', 'She going to school every day.', 'She goes to school every day.', 'She gone to school every day.']::text[], 2, 'With he, she and it, the verb gets an -s in the present simple.', true, true, 4),
  ('engelsk-fordypning-8:feedback-and-revision', 'q06', 'flervalg', 'Which sentence uses “their” correctly?', array['Their going home.', 'Put it over their.', 'Their is a problem.', 'The students forgot their books.']::text[], 3, '“Their” shows that something belongs to them.', true, true, 5),
  ('engelsk-fordypning-8:feedback-and-revision', 'q07', 'flervalg', 'What is a topic sentence?', array['The title of a text', 'A sentence that presents the main idea of a paragraph', 'The last sentence of a text', 'A quotation']::text[], 1, 'It is often the first sentence of the paragraph.', true, true, 6),
  ('engelsk-fordypning-8:feedback-and-revision', 'q08', 'flervalg', 'Why is reading your text aloud useful?', array['It helps you discover mistakes', 'It makes the text longer', 'It replaces feedback', 'It is required by the teacher']::text[], 0, 'You often hear mistakes that you do not see.', true, true, 7),
  ('engelsk-fordypning-8:feedback-and-revision', 'q09', 'flervalg', 'How should you react to feedback?', array['Ignore it', 'Get angry', 'Delete your text', 'Listen carefully, ask questions and think about why the reader reacted that way']::text[], 3, 'Feedback is about the text, not about you as a person.', true, false, 8),
  ('engelsk-fordypning-8:feedback-and-revision', 'q10', 'flervalg', 'What should you remember when using AI tools to improve a text?', array['That AI is always right', 'That you must decide what to change and make sure the text is your own', 'That AI can write everything for you', 'That school rules don''t apply']::text[], 1, 'You are responsible for your own text.', true, false, 9),
  ('engelsk-fordypning-8:feedback-and-revision', 'm01', 'sant-usant', 'Good writers usually write a perfect text the first time.', array['Sant', 'Usant']::text[], 1, 'Most writers revise their texts several times.', false, true, 10),
  ('engelsk-fordypning-8:feedback-and-revision', 'm02', 'sant-usant', 'Spell checkers catch all mistakes.', array['Sant', 'Usant']::text[], 1, 'A spell checker will not notice if you write “there” instead of “their”.', false, true, 11),
  ('engelsk-fordypning-8:feedback-and-revision', 'm03', 'sant-usant', 'Feedback should focus on the text, not the person.', array['Sant', 'Usant']::text[], 0, 'This makes feedback easier to receive and use.', false, true, 12),
  ('engelsk-fordypning-8:feedback-and-revision', 'm04', 'sant-usant', 'The writing process can also be used for oral texts.', array['Sant', 'Usant']::text[], 0, 'Presentations and podcasts also improve with planning and feedback.', false, true, 13),
  ('engelsk-fordypning-8:feedback-and-revision', 'm05', 'flervalg', 'Which word is a synonym for “big”?', array['Small', 'Large', 'Quick', 'Old']::text[], 1, 'Synonyms help you avoid repeating the same word.', false, true, 14),
  ('engelsk-fordypning-8:feedback-and-revision', 'm06', 'flervalg', 'Which sentence uses the apostrophe correctly?', array['It''s a nice day.', 'Its a nice day.', 'Its'' a nice day.', 'It is'' a nice day.']::text[], 0, '“It''s” is short for “it is”.', false, true, 15),
  ('engelsk-fordypning-8:feedback-and-revision', 'm07', 'flervalg', 'Which of these words must start with a capital letter in English?', array['school', 'friend', 'Norwegian', 'apple']::text[], 2, 'Nationalities and languages always have a capital letter in English.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-8:feedback-and-revision', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-8:feedback-and-revision', 's01', 'A writer has several ideas for a text but has not decided how to arrange them. Explain how pre-writing can help the writer make the text easier to follow.', 'During pre-writing, the writer can brainstorm ideas and plan the structure. This helps arrange the ideas in a logical order before writing.', array['Forklarer at idémyldring eller planlegging skjer før skrivingen.', 'Knytter planleggingen til en tydelig eller logisk struktur.']::text[], 0),
  ('engelsk-fordypning-8:feedback-and-revision', 's02', 'Why might a writer write a first draft without stopping to correct every small mistake?', 'Writing freely helps the writer get the ideas down first. Small mistakes can be corrected later during editing.', array['Forklarer at førsteutkastet gir plass til å få fram ideene.', 'Nevner at småfeil kan rettes senere, for eksempel under editing.']::text[], 1),
  ('engelsk-fordypning-8:feedback-and-revision', 's03', 'A paragraph has sentences about three different main ideas, and none of the sentences introduces what the paragraph is about. Explain how the writer could improve it using paragraphs and topic sentences.', 'The writer could split the ideas into separate paragraphs, with one main idea in each. A topic sentence at the start of each paragraph could introduce that idea.', array['Foreslår å samle hver hovedidé i et eget avsnitt.', 'Forklarer at en topic sentence presenterer hovedideen i avsnittet.']::text[], 2),
  ('engelsk-fordypning-8:feedback-and-revision', 's04', 'A student writes this feedback: “You are a bad writer.” Rewrite it so it is kind, focuses on the text and gives a helpful suggestion. Use this situation: the text’s ending feels sudden.', 'The ending feels a bit sudden. Could you add a sentence that sums up your main point?', array['Kommentaren handler om teksten, ikke om personen.', 'Gir en vennlig og konkret forbedringsidé knyttet til den brå avslutningen.']::text[], 3),
  ('engelsk-fordypning-8:feedback-and-revision', 's05', 'These sentences are about a presentation: “I planned my presentation. I practised it. I asked someone for feedback.” Rewrite them using a linking word or phrase to show how the steps connect.', 'I planned my presentation, then practised it and asked someone for feedback.', array['Bruker et linking word eller en frase som knytter stegene sammen.', 'Beholder den logiske rekkefølgen i handlingene.']::text[], 4),
  ('engelsk-fordypning-8:feedback-and-revision', 's06', 'A student is preparing a podcast. Explain how the student can use the writing process to improve it before sharing the final version.', 'The student can plan the podcast, rehearse it and get feedback from someone. Then the student can make improvements before sharing it.', array['Nevner planlegging og øving eller rehearsal.', 'Nevner feedback og at studenten forbedrer podcasten før den deles.']::text[], 5),
  ('engelsk-fordypning-8:feedback-and-revision', 's07', 'Improve these sentences by replacing repeated words with a synonym or a more precise word: “The film was good. The film had good music.”', 'The film was enjoyable. It had catchy music.', array['Bytter ut minst ett gjentatt ord med et synonym eller et mer presist ord.', 'Beholder meningen om filmen og musikken.']::text[], 6),
  ('engelsk-fordypning-8:feedback-and-revision', 's08', 'A spell checker has checked a student’s final draft, but it may not catch every mistake. Explain what the student should do next and what kinds of errors to look for.', 'The student should proofread the draft carefully. They should check for small mistakes in spelling, grammar and punctuation.', array['Forklarer at studenten bør gjøre en grundig, siste kontroll (proofreading).', 'Nevner minst to typer detaljer som bør kontrolleres, som spelling, grammar eller punctuation.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-8:privacy-and-copyright', 'engelsk-fordypning-8', 'privacy-and-copyright', 'Privacy, copyright and your online identity', 'Your digital footprint and online identity, how to protect your own and others'' privacy, and how to use other people''s work fairly with copyright, Creative Commons and source lists.', array[11, 10]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-8:privacy-and-copyright', '## Your digital footprint
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-8:privacy-and-copyright', 'Digital footprint', 'The traces you leave online.', 0),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Active footprint', 'What you post yourself, like pictures, comments and likes.', 1),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Passive footprint', 'Data collected about you without you noticing, like your location.', 2),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Privacy', 'Your right to control information about yourself.', 3),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Personal data', 'Information that can identify you, like your name, photo or IP address.', 4),
  ('engelsk-fordypning-8:privacy-and-copyright', 'GDPR', 'EU privacy rules that also apply in Norway.', 5),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Privacy settings', 'Settings that decide who can see what you share.', 6),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Two-step verification', 'An extra security step, like a code sent to your phone.', 7),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Consent', 'A clear yes to something, like having your picture shared.', 8),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Online identity', 'The way you present yourself online.', 9),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Copyright', 'The creator''s right to decide how their work is used. Lasts until 70 years after death.', 10),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Creative Commons', 'Licences that let creators allow others to use their work on certain conditions.', 11),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Credit', 'Saying who made something and where it comes from.', 12),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Plagiarism', 'Using someone else''s words or ideas without saying where they come from.', 13),
  ('engelsk-fordypning-8:privacy-and-copyright', 'Source list', 'A list of the sources you have used, with author, title, website and date.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-8:privacy-and-copyright', 'q01', 'flervalg', 'What is a digital footprint?', array['A shoe print in the snow', 'The traces you leave online', 'A type of password', 'A computer virus']::text[], 1, 'Posts, likes and searches all become part of your footprint.', true, true, 0),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q02', 'flervalg', 'Which of these is personal data?', array['The weather forecast', 'A famous painting', 'Your phone number', 'A recipe']::text[], 2, 'Personal data can be linked to you as a person.', true, true, 1),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q03', 'flervalg', 'What does the GDPR give you the right to?', array['Free internet', 'Unlimited downloads', 'Use any picture online', 'Have your personal data deleted']::text[], 3, 'This is often called “the right to be forgotten”.', true, true, 2),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q04', 'flervalg', 'What should you do before posting a picture of a friend?', array['Ask for their consent', 'Add a filter', 'Tag everyone', 'Nothing']::text[], 0, 'Everyone has the right to decide over pictures of themselves.', true, true, 3),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q05', 'flervalg', 'How long does copyright last in Norway?', array['5 years', 'Until the work is posted online', 'Forever', 'Until 70 years after the creator''s death']::text[], 3, 'After that, the work becomes free for everyone to use.', true, true, 4),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q06', 'flervalg', 'What is plagiarism?', array['Using a spell checker', 'Using someone else''s words or ideas without saying where they come from', 'Writing a long text', 'Quoting with a source']::text[], 1, 'Plagiarism is a form of cheating.', true, true, 5),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q07', 'flervalg', 'What is a Creative Commons licence?', array['A ban on sharing', 'A password', 'A licence that allows others to use a work on certain conditions', 'A type of camera']::text[], 2, 'For example, you may have to credit the creator.', true, true, 6),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q08', 'flervalg', 'Why should you think before posting?', array['Because your digital footprint can be seen by others for a long time', 'Because posting costs money', 'Because nobody reads posts', 'Because posts disappear after one day']::text[], 0, 'Future schools and employers may see what you post.', true, true, 7),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q09', 'flervalg', 'Which is a good way to protect your privacy?', array['Sharing your password with friends', 'Using strong, different passwords and two-step verification', 'Posting your address', 'Using the same password everywhere']::text[], 1, 'Strong passwords make it harder for others to access your accounts.', true, false, 8),
  ('engelsk-fordypning-8:privacy-and-copyright', 'q10', 'flervalg', 'What is a passive digital footprint?', array['A photo you post', 'A comment you write', 'A like you give', 'Data collected about you, like your location']::text[], 3, 'Passive data is collected in the background.', true, false, 9),
  ('engelsk-fordypning-8:privacy-and-copyright', 'm01', 'sant-usant', 'An IP address can be personal data.', array['Sant', 'Usant']::text[], 0, 'It can be used to link online activity to you.', false, true, 10),
  ('engelsk-fordypning-8:privacy-and-copyright', 'm02', 'sant-usant', 'If a picture is on the internet, you can use it freely.', array['Sant', 'Usant']::text[], 1, 'Pictures online are still protected by copyright.', false, true, 11),
  ('engelsk-fordypning-8:privacy-and-copyright', 'm03', 'sant-usant', 'You should include a source list when you use sources.', array['Sant', 'Usant']::text[], 0, 'It shows where your information comes from.', false, true, 12),
  ('engelsk-fordypning-8:privacy-and-copyright', 'm04', 'sant-usant', 'Most people show a completely realistic picture of their lives online.', array['Sant', 'Usant']::text[], 1, 'Many people share mostly edited highlights.', false, true, 13),
  ('engelsk-fordypning-8:privacy-and-copyright', 'm05', 'flervalg', 'What does it mean to credit a source?', array['To pay for it', 'To say who made it and where it comes from', 'To delete it', 'To copy it']::text[], 1, 'Crediting is fair to the creator and honest to the reader.', false, true, 14),
  ('engelsk-fordypning-8:privacy-and-copyright', 'm06', 'flervalg', 'Which of these is protected by copyright?', array['A song someone wrote', 'The alphabet', 'The weather', 'A mathematical fact']::text[], 0, 'Copyright protects original creative works.', false, true, 15),
  ('engelsk-fordypning-8:privacy-and-copyright', 'm07', 'flervalg', 'What is your online identity?', array['Your passport', 'Your bank account', 'The way you present yourself online', 'Your home address']::text[], 2, 'Your posts, profile and comments build your online identity.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-8:privacy-and-copyright', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-8:privacy-and-copyright', 's01', 'Compare an active digital footprint with a passive digital footprint. Give one example of each.', 'An active footprint is something you post yourself, such as a comment. A passive footprint is data collected about you, such as your location.', array['Explains that an active footprint comes from things you do or post yourself.', 'Explains that a passive footprint is data collected about you, and gives a suitable example.']::text[], 0),
  ('engelsk-fordypning-8:privacy-and-copyright', 's02', 'How can the things you do online affect how other people see you in the future? Include who may see your digital footprint.', 'Friends, schools and future employers may see your digital footprint. What you post or do online can affect the impression they get of you.', array['Names at least one relevant audience, such as schools or future employers.', 'Connects the digital footprint to the impression those people may get.']::text[], 1),
  ('engelsk-fordypning-8:privacy-and-copyright', 's03', 'Sam wants only friends to see a photo he shares online. What should he check or change, and how would that help?', 'Sam should check his privacy settings and choose who can see the photo. These settings decide who can see what he shares.', array['Says to check or change the privacy settings.', 'Explains that the settings control who can see the photo or other shared content.']::text[], 2),
  ('engelsk-fordypning-8:privacy-and-copyright', 's04', 'Explain how two-step verification adds an extra security step when someone signs in.', 'After entering a password, the person must complete another step, such as entering a code sent to their phone. This makes signing in require more than just the password.', array['Explains that a second step is needed in addition to the password.', 'Gives a suitable example, such as a code sent to a phone.']::text[], 3),
  ('engelsk-fordypning-8:privacy-and-copyright', 's05', 'You use information from a website in a school assignment. What details should you put in your source list?', 'Include the author, the title, the website and the date you read it.', array['Includes the author and title.', 'Includes the website and the date the source was read.']::text[], 4),
  ('engelsk-fordypning-8:privacy-and-copyright', 's06', 'A classmate’s online profile shows edited photos and highlights. Explain why this may not show the whole of their life.', 'Many people show only the best sides of their lives online, using edited photos and highlights. Other people’s online lives may be edited too.', array['Explains that people may choose to show only the best sides of their lives.', 'Mentions that photos or other parts of an online profile may be edited.']::text[], 5),
  ('engelsk-fordypning-8:privacy-and-copyright', 's07', 'You want to use someone else’s photo in a project. Give two ways to do this while respecting copyright.', 'You could use a photo with a Creative Commons licence and follow its terms, or choose one from a free image library and follow the licence terms. You could also make your own photo.', array['Suggests using a Creative Commons photo or one from a free image library.', 'Says to follow the licence terms, or suggests creating an original photo instead.']::text[], 6),
  ('engelsk-fordypning-8:privacy-and-copyright', 's08', 'Explain the difference between copyright and plagiarism.', 'Copyright is the creator’s right to decide how their original work is used. Plagiarism is using someone else’s words or ideas without saying where they came from.', array['Explains that copyright concerns the creator’s control over how their work is used.', 'Explains that plagiarism is using another person’s words or ideas without naming the source.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-8:naturvitenskapelig-metode', 'naturfag-8', 'naturvitenskapelig-metode', 'Naturvitenskapelig metode', 'Hvordan naturforskere arbeider: problemstilling, hypotese, variabler, forsøk, datainnsamling, konklusjon – og hvordan du gjennomfører forsøk trygt.', array[1, 2, 4]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-8:naturvitenskapelig-metode', '## Hvordan vet vi det vi vet?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-8:naturvitenskapelig-metode', 'Naturvitenskapelig metode', 'Måten forskere undersøker naturen på: spørsmål, hypotese, forsøk, analyse og konklusjon.', 0),
  ('naturfag-8:naturvitenskapelig-metode', 'Observasjon', 'Noe du legger merke til med sansene eller måleinstrumenter.', 1),
  ('naturfag-8:naturvitenskapelig-metode', 'Hypotese', 'En mulig forklaring som kan testes med forsøk eller observasjoner.', 2),
  ('naturfag-8:naturvitenskapelig-metode', 'Uavhengig variabel', 'Det du selv endrer i et forsøk.', 3),
  ('naturfag-8:naturvitenskapelig-metode', 'Avhengig variabel', 'Det du måler for å se virkningen av endringen.', 4),
  ('naturfag-8:naturvitenskapelig-metode', 'Kontrollerte variabler', 'Faktorer som holdes like, slik at bare én ting endres om gangen.', 5),
  ('naturfag-8:naturvitenskapelig-metode', 'Kontrollgruppe', 'En gruppe som ikke utsettes for endringen, og som brukes til sammenligning.', 6),
  ('naturfag-8:naturvitenskapelig-metode', 'Data', 'Målinger og observasjoner som samles inn under et forsøk.', 7),
  ('naturfag-8:naturvitenskapelig-metode', 'Konklusjon', 'Svaret forsøket gir: støtter eller svekker resultatene hypotesen?', 8),
  ('naturfag-8:naturvitenskapelig-metode', 'Pålitelighet', 'Hvor mye vi kan stole på resultatene. Øker når forsøket gjentas og gir samme svar.', 9),
  ('naturfag-8:naturvitenskapelig-metode', 'Feilkilde', 'Noe som kan ha påvirket resultatet, som unøyaktig utstyr.', 10),
  ('naturfag-8:naturvitenskapelig-metode', 'Rapport', 'En beskrivelse av forsøket slik at andre kan kontrollere og gjenta det.', 11),
  ('naturfag-8:naturvitenskapelig-metode', 'Risikovurdering', 'Å tenke gjennom hva som kan gå galt i et forsøk, og hvordan det unngås.', 12),
  ('naturfag-8:naturvitenskapelig-metode', 'Faresymbol', 'Symbol på kjemikalier som viser farer, for eksempel brannfarlig eller etsende.', 13),
  ('naturfag-8:naturvitenskapelig-metode', 'Vernebriller', 'Beskytter øynene mot sprut og splinter under forsøk.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-8:naturvitenskapelig-metode', 'q01', 'flervalg', 'Hva er en hypotese?', array['Et bevist faktum', 'En mulig forklaring som kan testes', 'Resultatet av et forsøk', 'En tabell med data']::text[], 1, 'En hypotese er en foreløpig forklaring. Den testes med forsøk og kan vise seg å være feil.', true, true, 0),
  ('naturfag-8:naturvitenskapelig-metode', 'q02', 'flervalg', 'Du undersøker om mengden lys påvirker hvor mye en plante vokser. Hva er den uavhengige variabelen?', array['Hvor mye planten vokser', 'Mengden vann', 'Mengden lys', 'Typen jord']::text[], 2, 'Den uavhengige variabelen er det du selv endrer, her lysmengden.', true, true, 1),
  ('naturfag-8:naturvitenskapelig-metode', 'q03', 'flervalg', 'I samme forsøk, hva er den avhengige variabelen?', array['Hvor mye planten vokser', 'Mengden lys', 'Temperaturen', 'Potten']::text[], 0, 'Den avhengige variabelen er det du måler, altså veksten.', true, true, 2),
  ('naturfag-8:naturvitenskapelig-metode', 'q04', 'flervalg', 'Hvorfor skal du bare endre én ting om gangen i et forsøk?', array['For at forsøket skal gå raskere', 'Fordi det er billigere', 'Fordi det er en regel uten grunn', 'For å vite hva som forårsaket resultatet']::text[], 3, 'Endrer du flere ting samtidig, kan du ikke vite hvilken av dem som ga virkningen.', true, true, 3),
  ('naturfag-8:naturvitenskapelig-metode', 'q05', 'flervalg', 'Hva er en kontrollgruppe?', array['Gruppen som får mest behandling', 'En gruppe som ikke utsettes for endringen, og som brukes til sammenligning', 'Lærerens gruppe', 'Gruppen som skriver rapporten']::text[], 1, 'Kontrollgruppen viser hva som skjer uten endringen, slik at du kan se effekten.', true, true, 4),
  ('naturfag-8:naturvitenskapelig-metode', 'q06', 'flervalg', 'Hva gjør resultatene mer pålitelige?', array['Å gjenta forsøket flere ganger', 'Å bare gjøre forsøket én gang', 'Å endre mange variabler', 'Å gjette resultatet først']::text[], 0, 'Når gjentatte forsøk gir samme resultat, kan vi stole mer på det.', true, true, 5),
  ('naturfag-8:naturvitenskapelig-metode', 'q07', 'flervalg', 'Resultatet stemmer ikke med hypotesen. Hva bør du gjøre?', array['Endre dataene', 'Endre eller forkaste hypotesen og eventuelt teste på nytt', 'Skjule resultatet', 'Si at forsøket var feil uten å sjekke']::text[], 1, 'Data som ikke passer, er verdifulle. De viser at forklaringen må forbedres.', true, true, 6),
  ('naturfag-8:naturvitenskapelig-metode', 'q08', 'flervalg', 'Hva er en feilkilde?', array['En kjemikalieflaske', 'Hypotesen', 'Konklusjonen', 'Noe som kan ha påvirket resultatet, som unøyaktig måleutstyr']::text[], 3, 'Feilkilder bør drøftes i rapporten, fordi de påvirker hvor sikker konklusjonen er.', true, false, 7),
  ('naturfag-8:naturvitenskapelig-metode', 'q09', 'flervalg', 'Hva bør du gjøre før du starter et forsøk med kjemikalier?', array['Blande alt raskt', 'Gjøre en risikovurdering og ta på vernebriller', 'Smake på kjemikaliene', 'Ta av vernebrillene']::text[], 1, 'Risikovurdering og riktig verneutstyr forebygger skader.', true, true, 8),
  ('naturfag-8:naturvitenskapelig-metode', 'q10', 'flervalg', 'Hvorfor skal forsøket beskrives nøyaktig i en rapport?', array['For at andre skal kunne kontrollere og gjenta det', 'For at det skal bli langt', 'For å skjule feil', 'Fordi ingen skal lese den']::text[], 0, 'At andre kan gjenta forsøket og få samme resultat, er en grunnstein i naturvitenskapen.', true, false, 9),
  ('naturfag-8:naturvitenskapelig-metode', 'm01', 'sant-usant', 'En hypotese må alltid vise seg å være riktig.', array['Sant', 'Usant']::text[], 1, 'Hypoteser kan like gjerne vise seg å være feil. Det er også ny kunnskap.', false, true, 10),
  ('naturfag-8:naturvitenskapelig-metode', 'm02', 'sant-usant', 'Kontrollerte variabler skal holdes like gjennom hele forsøket.', array['Sant', 'Usant']::text[], 0, 'Da vet du at endringen i resultatet skyldes den uavhengige variabelen.', false, true, 11),
  ('naturfag-8:naturvitenskapelig-metode', 'm03', 'sant-usant', 'Alle målinger har en viss usikkerhet.', array['Sant', 'Usant']::text[], 0, 'Ingen måleinstrumenter er helt nøyaktige, og det bør tas med i vurderingen.', false, true, 12),
  ('naturfag-8:naturvitenskapelig-metode', 'm04', 'sant-usant', 'Det er greit å lukte tett innpå ukjente kjemikalier for å finne ut hva de er.', array['Sant', 'Usant']::text[], 1, 'Ukjente kjemikalier kan være farlige. Følg alltid sikkerhetsinstruksene.', false, true, 13),
  ('naturfag-8:naturvitenskapelig-metode', 'm05', 'flervalg', 'Hvilken påstand er en testbar hypotese?', array['Planter er fine', 'Planter vokser raskere i varme enn i kulde', 'Jeg liker planter', 'Planter er grønne fordi de er grønne']::text[], 1, 'Denne påstanden kan testes ved å måle vekst ved ulike temperaturer.', false, true, 14),
  ('naturfag-8:naturvitenskapelig-metode', 'm06', 'flervalg', 'Hvor bør du notere målingene underveis?', array['I hodet', 'Ingen steder', 'I en tabell', 'Bare i konklusjonen']::text[], 2, 'En tabell gir oversikt og gjør det lett å analysere dataene etterpå.', false, true, 15),
  ('naturfag-8:naturvitenskapelig-metode', 'm07', 'flervalg', 'Hva viser et faresymbol på en flaske?', array['Hvilken fare kjemikaliet utgjør', 'Prisen', 'Hvem som har laget flasken', 'Hvor mye som er igjen']::text[], 0, 'Faresymboler varsler om farer som brann, etsing eller giftighet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-8:naturvitenskapelig-metode', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-8:naturvitenskapelig-metode', 's01', 'En elev legger merke til at en plante i vinduskarmen visner. Eleven foreslår at planten får for mye sol. Hva er observasjonen, og hva er hypotesen?', 'Observasjonen er at planten visner. Hypotesen er at den visner fordi den får for mye sol.', array['Skiller mellom det eleven legger merke til, og den mulige forklaringen.', 'Kobler hypotesen til at planten får for mye sol.']::text[], 0),
  ('naturfag-8:naturvitenskapelig-metode', 's02', 'Hva gjør man i analysefasen med data fra et forsøk, og hvordan kan det hjelpe med å forstå resultatene?', 'Man sorterer dataene, lager gjerne diagrammer og ser etter mønstre. Mønstrene kan hjelpe med å tolke resultatene.', array['Beskriver at dataene sorteres eller vises i diagrammer.', 'Forklarer at man ser etter mønstre for å forstå resultatene.']::text[], 1),
  ('naturfag-8:naturvitenskapelig-metode', 's03', 'Forklar forskjellen på en hypotese og en konklusjon i et forsøk.', 'En hypotese er en mulig forklaring som kan testes. En konklusjon er svaret man kommer fram til etter å ha undersøkt resultatene.', array['Forklarer at hypotesen er en mulig forklaring før eller under forsøket.', 'Forklarer at konklusjonen bygger på resultatene.']::text[], 2),
  ('naturfag-8:naturvitenskapelig-metode', 's04', 'I et forsøk er en plantes høyde først 9 cm og senere 14 cm. Hvor mye har planten vokst? Vis det viktigste regnestykket.', 'Planten har vokst 5 cm. Regnestykket er 14 − 9 = 5.', array['Får fram at planten har vokst 5 cm.', 'Viser at startverdien trekkes fra den senere høyden.']::text[], 3),
  ('naturfag-8:naturvitenskapelig-metode', 's05', 'En elev måler veksten i tre potter: 2 cm, 4 cm og 3 cm. Hva er den gjennomsnittlige veksten? Vis det viktigste regnestykket.', 'Den gjennomsnittlige veksten er 3 cm. Regnestykket er (2 + 4 + 3) ÷ 3 = 3.', array['Får fram gjennomsnittet 3 cm.', 'Legger sammen målingene og deler summen på 3.']::text[], 4),
  ('naturfag-8:naturvitenskapelig-metode', 's06', 'Du vil undersøke om mengden lys påvirker hvor mye planter vokser. Nevn to forhold ved forsøket som bør holdes like for plantene, og forklar hvorfor.', 'Vannmengde og jord bør for eksempel være like for alle plantene. Da er det lettere å finne ut om forskjeller i vekst skyldes mengden lys.', array['Nevner to relevante forhold som bør holdes like, for eksempel vannmengde, jord eller temperatur.', 'Knytter dette til at man skal kunne undersøke virkningen av lys.']::text[], 5),
  ('naturfag-8:naturvitenskapelig-metode', 's07', 'Hvorfor bør en rapport om et forsøk ta med usikkerhet i målingene når man vurderer konklusjonen?', 'Målinger kan være usikre, så resultatene viser ikke alltid helt nøyaktig hva som skjedde. Derfor bør man vurdere hvor sikker konklusjonen er.', array['Forklarer at målinger kan ha usikkerhet.', 'Knytter usikkerheten til hvor sikkert man kan være på konklusjonen.']::text[], 6),
  ('naturfag-8:naturvitenskapelig-metode', 's08', 'Under et forsøk kan et kjemikalie sprute. Hva beskytter vernebriller mot, og når bør de brukes?', 'Vernebriller beskytter øynene mot sprut og splinter. De bør brukes under forsøk der øynene kan bli utsatt for slike farer.', array['Nevner at vernebriller beskytter øynene mot sprut eller splinter.', 'Forklarer at de brukes under forsøk der det er fare for at øynene utsettes.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-8:celler', 'naturfag-8', 'celler', 'Celler', 'Cellen som livets minste enhet, forskjellen på plante-, dyre- og bakterieceller, og hvordan cellenes oppbygning henger sammen med funksjonen.', array[14]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-8:celler', '## Livets byggesteiner
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-8:celler', 'Celle', 'Den minste enheten som kan leve selvstendig. Alle organismer er bygd av celler.', 0),
  ('naturfag-8:celler', 'Cellemembran', 'Tynn hinne rundt cellen som bestemmer hva som slipper inn og ut.', 1),
  ('naturfag-8:celler', 'Cytoplasma', 'Geléaktig væske i cellen der mange prosesser skjer.', 2),
  ('naturfag-8:celler', 'Cellekjerne', 'Inneholder DNA og styrer cellens aktiviteter.', 3),
  ('naturfag-8:celler', 'DNA', 'Arvestoffet, som inneholder oppskriften på cellen og organismen.', 4),
  ('naturfag-8:celler', 'Mitokondrie', 'Cellens «kraftverk», der energi frigjøres ved celleånding.', 5),
  ('naturfag-8:celler', 'Cellevegg', 'Stiv vegg utenfor membranen hos planter, sopp og bakterier.', 6),
  ('naturfag-8:celler', 'Kloroplast', 'Grønn cellebit i planteceller der fotosyntesen skjer.', 7),
  ('naturfag-8:celler', 'Klorofyll', 'Grønt stoff i kloroplastene som fanger opp lysenergi.', 8),
  ('naturfag-8:celler', 'Vakuole', 'Stort væskefylt rom i planteceller som lagrer vann.', 9),
  ('naturfag-8:celler', 'Prokaryot celle', 'Celle uten cellekjerne, som bakterier.', 10),
  ('naturfag-8:celler', 'Eukaryot celle', 'Celle med cellekjerne, som dyre-, plante- og soppceller.', 11),
  ('naturfag-8:celler', 'Spesialiserte celler', 'Celler med form og innhold tilpasset en bestemt oppgave.', 12),
  ('naturfag-8:celler', 'Vev', 'En gruppe like celler som samarbeider om en oppgave.', 13),
  ('naturfag-8:celler', 'Celle → vev → organ → organsystem', 'Organiseringen i flercellede organismer.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-8:celler', 'q01', 'flervalg', 'Hvilken del av cellen inneholder DNA?', array['Cellemembranen', 'Cellekjernen', 'Vakuolen', 'Celleveggen']::text[], 1, 'I eukaryote celler ligger DNA-et i cellekjernen.', true, true, 0),
  ('naturfag-8:celler', 'q02', 'flervalg', 'Hva finnes i planteceller, men ikke i dyreceller?', array['Cellemembran og cytoplasma', 'Mitokondrier', 'Cellevegg og kloroplaster', 'Cellekjerne']::text[], 2, 'Planteceller har cellevegg, kloroplaster og en stor vakuole i tillegg.', true, true, 1),
  ('naturfag-8:celler', 'q03', 'flervalg', 'Hvor skjer fotosyntesen?', array['I mitokondriene', 'I kloroplastene', 'I cellekjernen', 'I cellemembranen']::text[], 1, 'Kloroplastene inneholder klorofyll, som fanger lysenergien til fotosyntesen.', true, true, 2),
  ('naturfag-8:celler', 'q04', 'flervalg', 'Hva kjennetegner bakterieceller?', array['De har ikke cellekjerne', 'De har kloroplaster', 'De er større enn dyreceller', 'De har ikke cellemembran']::text[], 0, 'Bakterier er prokaryote. Arvestoffet ligger fritt i cytoplasmaet.', true, true, 3),
  ('naturfag-8:celler', 'q05', 'flervalg', 'Hva gjør mitokondriene?', array['Lagrer vann', 'Lager proteiner fra lys', 'Beskytter cellen', 'Frigjør energi fra næring ved celleånding']::text[], 3, 'Mitokondriene kalles ofte cellens kraftverk.', true, true, 4),
  ('naturfag-8:celler', 'q06', 'flervalg', 'Hvorfor er nerveceller lange og greinete?', array['For å lagre fett', 'For å sende signaler over lange avstander', 'For å fange lys', 'For å frakte oksygen']::text[], 1, 'Formen gjør det mulig å nå langt og koble seg til mange andre celler.', true, true, 5),
  ('naturfag-8:celler', 'q07', 'flervalg', 'Hva kalles en gruppe like celler som samarbeider?', array['Organ', 'Organisme', 'Vev', 'Organsystem']::text[], 2, 'Like celler danner vev, for eksempel muskelvev.', true, true, 6),
  ('naturfag-8:celler', 'q08', 'flervalg', 'Hva gjør cellemembranen?', array['Gir planten grønn farge', 'Inneholder arvestoffet', 'Frigjør energi', 'Holder cellen samlet og bestemmer hva som slipper inn og ut']::text[], 3, 'Membranen er en selektiv grense mellom cellen og omgivelsene.', true, false, 7),
  ('naturfag-8:celler', 'q09', 'flervalg', 'Hva er en eukaryot celle?', array['En celle med cellekjerne', 'En celle uten kjerne', 'En bakteriecelle', 'En død celle']::text[], 0, 'Dyre-, plante- og soppceller har kjerne og er eukaryote.', true, true, 8),
  ('naturfag-8:celler', 'q10', 'flervalg', 'Hvorfor har røde blodceller ingen kjerne?', array['Fordi de er døde', 'For å få plass til mer oksygen', 'Fordi de er bakterier', 'For å lage fotosyntese']::text[], 1, 'Uten kjerne har de mer plass til hemoglobin, som frakter oksygen.', true, false, 9),
  ('naturfag-8:celler', 'm01', 'sant-usant', 'Alle levende organismer er bygd opp av celler.', array['Sant', 'Usant']::text[], 0, 'Cellen er livets grunnleggende enhet.', false, true, 10),
  ('naturfag-8:celler', 'm02', 'sant-usant', 'Dyreceller har cellevegg.', array['Sant', 'Usant']::text[], 1, 'Dyreceller har bare cellemembran. Planter, sopp og bakterier har cellevegg.', false, true, 11),
  ('naturfag-8:celler', 'm03', 'sant-usant', 'Nye celler dannes ved at eksisterende celler deler seg.', array['Sant', 'Usant']::text[], 0, 'Celler oppstår fra andre celler gjennom celledeling.', false, true, 12),
  ('naturfag-8:celler', 'm04', 'sant-usant', 'Bakterier har cellekjerne.', array['Sant', 'Usant']::text[], 1, 'Bakterier er prokaryote og mangler cellekjerne.', false, true, 13),
  ('naturfag-8:celler', 'm05', 'flervalg', 'Hva gjør vakuolen i en plantecelle?', array['Lagrer vann og holder cellen spent', 'Lager energi', 'Inneholder DNA', 'Fanger lys']::text[], 0, 'Den store vakuolen fylles med vann og hjelper planten å stå oppreist.', false, true, 14),
  ('naturfag-8:celler', 'm06', 'flervalg', 'Hva kalles et hjerte, som består av flere typer vev?', array['En celle', 'Et organ', 'Et vev', 'En organisme']::text[], 1, 'Et organ består av ulike vev som samarbeider.', false, true, 15),
  ('naturfag-8:celler', 'm07', 'flervalg', 'Hvilket instrument trenger du for å se de fleste celler?', array['Kikkert', 'Termometer', 'Mikroskop', 'Vekt']::text[], 2, 'De fleste celler er for små til å ses uten mikroskop.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-8:celler', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-8:celler', 's01', 'Hva er DNA, og hva slags informasjon inneholder det?', 'DNA er arvestoffet. Det inneholder oppskriften på cellen og organismen.', array['Forklarer at DNA er arvestoff.', 'Nevner at DNA inneholder en oppskrift eller informasjon om cellen eller organismen.']::text[], 0),
  ('naturfag-8:celler', 's02', 'Beskriv rekkefølgen fra celler til organsystem, og forklar hvordan nivåene henger sammen.', 'Celler av samme type samarbeider og danner vev. Ulike vev danner organer, og organer som samarbeider, danner organsystemer.', array['Viser riktig rekkefølge: celle → vev → organ → organsystem.', 'Forklarer at celler, vev og organer samarbeider eller danner neste nivå.']::text[], 1),
  ('naturfag-8:celler', 's03', 'Sammenlign cellemembranen og celleveggen i en plantecelle. Hva er forskjellig med plasseringen og oppgaven deres?', 'Cellemembranen ligger rundt cellen og bestemmer hva som slipper inn og ut. Celleveggen ligger utenfor membranen og gir cellen stivhet og form.', array['Plasserer celleveggen utenfor cellemembranen.', 'Skiller mellom membranens rolle med å regulere hva som slipper inn og ut, og celleveggens rolle med å gi stivhet eller form.']::text[], 2),
  ('naturfag-8:celler', 's04', 'En plantecelle har mistet mye vann. Forklar hvordan det kan påvirke vakuolen og hvor spent cellen er.', 'Vakuolen lagrer vann og hjelper cellen med å holde seg spent. Når cellen mister mye vann, kan vakuolen inneholde mindre vann, og cellen blir mindre spent.', array['Nevner at vakuolen lagrer vann.', 'Knytter mindre vann i cellen eller vakuolen til at cellen blir mindre spent.']::text[], 3),
  ('naturfag-8:celler', 's05', 'Gi et eksempel på en spesialisert plantecelle, og forklar hvordan formen hjelper cellen med oppgaven sin.', 'En rothårcelle har lange utløpere som gir den stor overflate. Det hjelper cellen med å ta opp vann.', array['Nevner rothårcellen eller en annen spesialisert celle fra pensum.', 'Knytter cellens form til oppgaven, for eksempel at rothårcellens lange utløpere gir stor overflate for vannopptak.']::text[], 4),
  ('naturfag-8:celler', 's06', 'Forklar hvordan celledeling henger sammen med at nye celler blir til.', 'Nye celler dannes ved celledeling. De kommer fra celler som allerede finnes.', array['Forklarer at celledeling danner nye celler.', 'Får fram at nye celler kommer fra celler som allerede finnes.']::text[], 5),
  ('naturfag-8:celler', 's07', 'Nora teller 8 celler i ett synsfelt i mikroskopet og 7 i et annet. Hvor mange celler har hun telt til sammen? Vis regnestykket, og forklar hvorfor mikroskop er nyttig når hun undersøker celler.', 'Nora har telt 8 + 7 = 15 celler. Mikroskop er nyttig fordi de fleste celler er for små til å se med det blotte øye.', array['Regner riktig ut at 8 + 7 = 15.', 'Forklarer at mikroskop brukes fordi de fleste celler er for små til å se uten hjelp.']::text[], 6),
  ('naturfag-8:celler', 's08', 'En modell viser 14 celler. Seks er dyreceller, og resten er enten planteceller eller bakterieceller. Hvor mange celler er ikke dyreceller? Vis regnestykket, og nevn hvilke to celletyper de kan være.', '14 − 6 = 8 celler er ikke dyreceller. De kan være planteceller eller bakterieceller.', array['Regner riktig ut at 14 − 6 = 8.', 'Nevner planteceller og bakterieceller som de to mulige celletypene.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-8:fotosyntese-og-celleanding', 'naturfag-8', 'fotosyntese-og-celleanding', 'Fotosyntese, celleånding og karbonkretsløpet', 'Hvordan planter fanger solenergi og lager sukker, hvordan alle organismer frigjør energien igjen, og hvordan karbon går i kretsløp i naturen.', array[18]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-8:fotosyntese-og-celleanding', '## Energi til alt levende
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-8:fotosyntese-og-celleanding', 'Fotosyntese', 'Prosessen der planter bruker lysenergi til å lage glukose og oksygen av CO₂ og vann.', 0),
  ('naturfag-8:fotosyntese-og-celleanding', 'Fotosyntesens likning', '6CO₂ + 6H₂O + lysenergi → C₆H₁₂O₆ + 6O₂', 1),
  ('naturfag-8:fotosyntese-og-celleanding', 'Celleånding', 'Prosessen der glukose og oksygen gir energi, CO₂ og vann.', 2),
  ('naturfag-8:fotosyntese-og-celleanding', 'Celleåndingens likning', 'C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + energi', 3),
  ('naturfag-8:fotosyntese-og-celleanding', 'Glukose', 'Et sukker (C₆H₁₂O₆) som lagrer energi.', 4),
  ('naturfag-8:fotosyntese-og-celleanding', 'Kloroplast', 'Cellebiten der fotosyntesen skjer.', 5),
  ('naturfag-8:fotosyntese-og-celleanding', 'Mitokondrie', 'Cellebiten der celleåndingen skjer.', 6),
  ('naturfag-8:fotosyntese-og-celleanding', 'Klorofyll', 'Grønt stoff som fanger lysenergi.', 7),
  ('naturfag-8:fotosyntese-og-celleanding', 'Produsent', 'Organisme som lager sin egen næring ved fotosyntese, som planter og alger.', 8),
  ('naturfag-8:fotosyntese-og-celleanding', 'Karbonkretsløpet', 'Karbonets vandring mellom luft, levende organismer, jord og hav.', 9),
  ('naturfag-8:fotosyntese-og-celleanding', 'Nedbrytere', 'Sopp og bakterier som bryter ned døde organismer og frigjør næringsstoffer og CO₂.', 10),
  ('naturfag-8:fotosyntese-og-celleanding', 'Fossile brensler', 'Kull, olje og gass, dannet av rester etter planter og dyr for millioner av år siden.', 11),
  ('naturfag-8:fotosyntese-og-celleanding', 'Stivelse', 'Lagringsform for glukose i planter, for eksempel i poteter.', 12),
  ('naturfag-8:fotosyntese-og-celleanding', 'Planter om natta', 'Driver bare celleånding, fordi fotosyntesen trenger lys.', 13),
  ('naturfag-8:fotosyntese-og-celleanding', 'Fotosyntese og celleånding', 'Motsatte prosesser: produktene i den ene er utgangsstoffer i den andre.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-8:fotosyntese-og-celleanding', 'q01', 'flervalg', 'Hvilke stoffer trenger planten til fotosyntesen?', array['Oksygen og glukose', 'Karbondioksid og vann', 'Nitrogen og oksygen', 'Glukose og vann']::text[], 1, 'Planten bruker CO₂ fra lufta og vann fra jorda, og energi fra sollys.', true, true, 0),
  ('naturfag-8:fotosyntese-og-celleanding', 'q02', 'flervalg', 'Hva dannes i fotosyntesen?', array['Karbondioksid og vann', 'Oksygen og nitrogen', 'Glukose og oksygen', 'Bare energi']::text[], 2, 'Produktene er glukose, som lagrer energi, og oksygen, som slippes ut.', true, true, 1),
  ('naturfag-8:fotosyntese-og-celleanding', 'q03', 'flervalg', 'Hvor i cellen skjer celleåndingen?', array['I mitokondriene', 'I kloroplastene', 'I cellekjernen', 'I vakuolen']::text[], 0, 'Mitokondriene frigjør energi fra glukose ved celleånding.', true, true, 2),
  ('naturfag-8:fotosyntese-og-celleanding', 'q04', 'flervalg', 'Hvilke organismer driver med celleånding?', array['Bare dyr', 'Bare planter', 'Bare bakterier', 'Nesten alle organismer, både planter og dyr']::text[], 3, 'Alle celler trenger energi, så nesten alle organismer driver med celleånding.', true, true, 3),
  ('naturfag-8:fotosyntese-og-celleanding', 'q05', 'flervalg', 'Hvorfor kalles celleånding fotosyntesen «baklengs»?', array['Fordi den skjer om natta', 'Fordi utgangsstoffene i den ene er produktene i den andre', 'Fordi den går saktere', 'Fordi den skjer i røttene']::text[], 1, 'Fotosyntesen lager glukose og oksygen, som celleåndingen bruker til å lage CO₂ og vann.', true, true, 4),
  ('naturfag-8:fotosyntese-og-celleanding', 'q06', 'flervalg', 'Hva skjer i en plante om natta?', array['Bare fotosyntese', 'Ingenting', 'Bare celleånding', 'Planten dør']::text[], 2, 'Fotosyntesen trenger lys. Celleåndingen fortsetter hele døgnet.', true, true, 5),
  ('naturfag-8:fotosyntese-og-celleanding', 'q07', 'flervalg', 'Hvilken prosess tar CO₂ ut av atmosfæren?', array['Fotosyntese', 'Celleånding', 'Forbrenning', 'Nedbryting']::text[], 0, 'Fotosyntesen binder karbon fra CO₂ i planter og alger.', true, true, 6),
  ('naturfag-8:fotosyntese-og-celleanding', 'q08', 'flervalg', 'Hva er fossile brensler dannet av?', array['Vulkansk stein', 'Sand og vann', 'Luft', 'Rester etter planter og dyr som levde for millioner av år siden']::text[], 3, 'Kull, olje og gass er lagret karbon fra gamle organismer.', true, false, 7),
  ('naturfag-8:fotosyntese-og-celleanding', 'q09', 'flervalg', 'Hvilken rolle har nedbrytere i karbonkretsløpet?', array['De lager oksygen', 'De bryter ned døde organismer og frigjør CO₂', 'De binder karbon i stein', 'De driver med fotosyntese']::text[], 1, 'Sopp og bakterier bryter ned dødt materiale og slipper karbonet ut igjen.', true, false, 8),
  ('naturfag-8:fotosyntese-og-celleanding', 'q10', 'flervalg', 'Hvorfor forstyrrer bruk av fossile brensler karbonkretsløpet?', array['Fordi de frigjør karbon som har vært lagret i millioner av år, svært raskt', 'Fordi de lager oksygen', 'Fordi de fjerner CO₂', 'De påvirker ikke kretsløpet']::text[], 0, 'Utslippene øker CO₂-mengden i lufta raskere enn naturen klarer å binde den.', true, true, 9),
  ('naturfag-8:fotosyntese-og-celleanding', 'm01', 'sant-usant', 'Nesten all energi i levende organismer kommer opprinnelig fra sola.', array['Sant', 'Usant']::text[], 0, 'Solenergien fanges ved fotosyntese og går videre i næringskjedene.', false, true, 10),
  ('naturfag-8:fotosyntese-og-celleanding', 'm02', 'sant-usant', 'Dyr driver med fotosyntese.', array['Sant', 'Usant']::text[], 1, 'Dyr mangler kloroplaster. De får energi ved å spise andre organismer.', false, true, 11),
  ('naturfag-8:fotosyntese-og-celleanding', 'm03', 'sant-usant', 'Oksygenet vi puster inn, kommer i hovedsak fra fotosyntese.', array['Sant', 'Usant']::text[], 0, 'Planter og alger slipper ut oksygen når de lager glukose.', false, true, 12),
  ('naturfag-8:fotosyntese-og-celleanding', 'm04', 'sant-usant', 'Celleånding skjer bare om natta.', array['Sant', 'Usant']::text[], 1, 'Celleånding skjer hele tiden, dag og natt.', false, true, 13),
  ('naturfag-8:fotosyntese-og-celleanding', 'm05', 'flervalg', 'Hva er den kjemiske formelen for glukose?', array['CO₂', 'H₂O', 'C₆H₁₂O₆', 'O₂']::text[], 2, 'Glukose består av 6 karbonatomer, 12 hydrogenatomer og 6 oksygenatomer.', false, true, 14),
  ('naturfag-8:fotosyntese-og-celleanding', 'm06', 'flervalg', 'Hvilken form lagrer poteter energi i?', array['Stivelse', 'Oksygen', 'Protein', 'Vann']::text[], 0, 'Planter lagrer overskudd av glukose som stivelse.', false, true, 15),
  ('naturfag-8:fotosyntese-og-celleanding', 'm07', 'flervalg', 'Hva slipper celleåndingen ut?', array['Oksygen', 'Glukose', 'Karbondioksid og vann', 'Klorofyll']::text[], 2, 'Når glukose brytes ned med oksygen, dannes CO₂ og vann.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-8:fotosyntese-og-celleanding', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-8:fotosyntese-og-celleanding', 's01', 'Hva gjør klorofyll for planten under fotosyntesen, og hvordan hjelper det planten?', 'Klorofyll fanger lysenergi. Planten bruker denne energien i fotosyntesen til å lage glukose.', array['Forklarer at klorofyll fanger lysenergi.', 'Knytter lysenergien til at planten kan lage glukose ved fotosyntese.']::text[], 0),
  ('naturfag-8:fotosyntese-og-celleanding', 's02', 'En plante lager mer glukose enn den trenger med en gang. Hvordan kan planten lagre noe av glukosen, og hva er stivelse?', 'Planten kan gjøre glukose om til stivelse. Stivelse er en lagringsform for glukose i planter.', array['Forklarer at planten kan lagre glukose som stivelse.', 'Beskriver stivelse som en lagringsform for glukose.']::text[], 1),
  ('naturfag-8:fotosyntese-og-celleanding', 's03', 'Sammenlign fotosyntese og celleånding ved å forklare hva som skjer med energien, og hvor i cellen hver prosess foregår.', 'I fotosyntesen brukes lysenergi til å lage glukose, der energi lagres. Fotosyntesen skjer i kloroplastene, mens celleåndingen skjer i mitokondriene og frigjør energi fra glukose.', array['Forklarer at fotosyntesen lagrer energi i glukose, mens celleånding frigjør energi.', 'Plasserer fotosyntesen i kloroplastene og celleåndingen i mitokondriene.']::text[], 2),
  ('naturfag-8:fotosyntese-og-celleanding', 's04', 'Alger kan være produsenter. Forklar hvorfor, og hva en produsent lager selv.', 'Alger er produsenter fordi de kan bruke fotosyntese til å lage sin egen næring. De bruker lysenergi til å lage glukose.', array['Forklarer at en produsent lager sin egen næring ved fotosyntese.', 'Bruker alger som eksempel og knytter det til at de lager glukose.']::text[], 3),
  ('naturfag-8:fotosyntese-og-celleanding', 's05', 'Et dyr spiser en plante. Forklar hvordan karbon fra planten kan komme over i dyret og senere tilbake til lufta.', 'Dyret får karbon når det spiser planten. Når dyret driver celleånding, slippes karbon ut i lufta som CO₂.', array['Forklarer at karbon overføres til dyret når det spiser planten.', 'Forklarer at celleånding hos dyret slipper CO₂ ut i lufta.']::text[], 4),
  ('naturfag-8:fotosyntese-og-celleanding', 's06', 'Havet kan både ta opp og avgi CO₂. Forklar hvordan dette gjør at havet er en del av karbonkretsløpet.', 'Karbon kan flyttes mellom lufta og havet når havet tar opp eller avgir CO₂. Derfor inngår havet i karbonkretsløpet.', array['Beskriver at havet tar opp CO₂ fra lufta.', 'Beskriver at havet også kan avgi CO₂, slik at karbon flyttes mellom hav og luft.']::text[], 5),
  ('naturfag-8:fotosyntese-og-celleanding', 's07', 'I fotosyntesens likning dannes 6 O₂-molekyler for hvert glukosemolekyl. Hvor mange O₂-molekyler dannes når planten lager 2 glukosemolekyler? Vis det viktigste regnestykket.', 'Det dannes 12 O₂-molekyler. Regnestykket er 2 × 6 = 12.', array['Bruker forholdet 6 O₂-molekyler per glukosemolekyl.', 'Kommer fram til 12 O₂-molekyler.']::text[], 6),
  ('naturfag-8:fotosyntese-og-celleanding', 's08', 'I celleåndingens likning reagerer 6 O₂-molekyler med 1 glukosemolekyl. Hvor mange glukosemolekyler kan reagere med 12 O₂-molekyler? Vis det viktigste steget.', '12 O₂-molekyler kan reagere med 2 glukosemolekyler. Regnestykket er 12 ÷ 6 = 2.', array['Bruker forholdet 6 O₂-molekyler per glukosemolekyl.', 'Kommer fram til 2 glukosemolekyler.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-8:okosystemer', 'naturfag-8', 'okosystemer', 'Økosystemer', 'Biotiske og abiotiske faktorer, næringskjeder og næringsnett, energiflyt og kretsløp av stoffer i naturen.', array[15]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-8:okosystemer', '## Hva er et økosystem?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-8:okosystemer', 'Økosystem', 'Et område der organismer og omgivelsene påvirker hverandre, som en skog eller en innsjø.', 0),
  ('naturfag-8:okosystemer', 'Populasjon', 'Alle individer av samme art i et område.', 1),
  ('naturfag-8:okosystemer', 'Biotiske faktorer', 'Levende deler av økosystemet: planter, dyr, sopp og bakterier.', 2),
  ('naturfag-8:okosystemer', 'Abiotiske faktorer', 'Ikke-levende deler: lys, temperatur, vann, jord og næringsstoffer.', 3),
  ('naturfag-8:okosystemer', 'Produsent', 'Organisme som lager egen næring ved fotosyntese.', 4),
  ('naturfag-8:okosystemer', 'Konsument', 'Organisme som spiser andre organismer.', 5),
  ('naturfag-8:okosystemer', 'Primærkonsument', 'Planteeter, som spiser produsenter.', 6),
  ('naturfag-8:okosystemer', 'Rovdyr', 'Dyr som spiser andre dyr.', 7),
  ('naturfag-8:okosystemer', 'Nedbryter', 'Sopp, bakterier og smådyr som bryter ned døde organismer til næringsstoffer.', 8),
  ('naturfag-8:okosystemer', 'Næringskjede', 'Viser hvem som spiser hvem: gress → hare → rev.', 9),
  ('naturfag-8:okosystemer', 'Næringsnett', 'Mange sammenvevde næringskjeder.', 10),
  ('naturfag-8:okosystemer', 'Energiflyt', 'Energi går én vei fra sola via produsenter til konsumenter, og tapes som varme.', 11),
  ('naturfag-8:okosystemer', 'En tidel', 'Omtrent så mye av energien går videre til neste trinn i næringskjeden.', 12),
  ('naturfag-8:okosystemer', 'Kretsløp av materie', 'Stoffer som karbon, nitrogen og vann sirkulerer og brukes om igjen.', 13),
  ('naturfag-8:okosystemer', 'Fremmed art', 'En art som er innført til et område der den ikke hører naturlig hjemme.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-8:okosystemer', 'q01', 'flervalg', 'Hvilken er en abiotisk faktor?', array['Et tre', 'En elg', 'Temperatur', 'En sopp']::text[], 2, 'Temperatur er ikke-levende. Tre, elg og sopp er biotiske faktorer.', true, true, 0),
  ('naturfag-8:okosystemer', 'q02', 'flervalg', 'Hva er en produsent?', array['En organisme som lager egen næring ved fotosyntese', 'Et rovdyr', 'En nedbryter', 'En planteeter']::text[], 0, 'Planter og alger er produsenter og står nederst i næringskjeden.', true, true, 1),
  ('naturfag-8:okosystemer', 'q03', 'flervalg', 'I næringskjeden gress → hare → rev, hva er haren?', array['Produsent', 'Nedbryter', 'Rovdyr på toppen', 'Primærkonsument']::text[], 3, 'Haren spiser planter og er derfor planteeter, eller primærkonsument.', true, true, 2),
  ('naturfag-8:okosystemer', 'q04', 'flervalg', 'Hva gjør nedbryterne?', array['Lager oksygen', 'Bryter ned døde organismer til næringsstoffer', 'Spiser rovdyr', 'Fanger sollys']::text[], 1, 'Nedbryterne sørger for at næringsstoffene kommer tilbake i kretsløpet.', true, true, 3),
  ('naturfag-8:okosystemer', 'q05', 'flervalg', 'Hvorfor finnes det færre rovdyr enn planteetere?', array['Fordi rovdyr lever lenger', 'Fordi det bare går videre omtrent en tidel av energien til hvert nytt trinn', 'Fordi rovdyr ikke trenger mat', 'Fordi planteetere er større']::text[], 1, 'Energitapet på hvert trinn gjør at det er mindre energi tilgjengelig høyere opp.', true, true, 4),
  ('naturfag-8:okosystemer', 'q06', 'flervalg', 'Hva er forskjellen på energi og materie i et økosystem?', array['Begge går i kretsløp', 'Begge går én vei', 'Energi går én vei, materie går i kretsløp', 'Materie går én vei, energi går i kretsløp']::text[], 2, 'Energien kommer fra sola og tapes som varme, mens stoffene brukes om og om igjen.', true, true, 5),
  ('naturfag-8:okosystemer', 'q07', 'flervalg', 'Hva er et næringsnett?', array['Mange sammenvevde næringskjeder', 'Et fiskegarn', 'En liste over planter', 'Et kretsløp for vann']::text[], 0, 'De fleste dyr spiser og blir spist av flere arter, så kjedene henger sammen i et nett.', true, true, 6),
  ('naturfag-8:okosystemer', 'q08', 'flervalg', 'Hva kan skje hvis rovdyrene forsvinner fra et område?', array['Ingenting', 'Plantene forsvinner umiddelbart', 'Nedbryterne dør', 'Byttedyrene kan bli så mange at de spiser opp vegetasjonen']::text[], 3, 'Uten rovdyr kan byttedyrbestanden vokse kraftig og forstyrre balansen.', true, true, 7),
  ('naturfag-8:okosystemer', 'q09', 'flervalg', 'Hva er en populasjon?', array['Alle arter i en skog', 'Alle individer av samme art i et område', 'Alle abiotiske faktorer', 'Et helt kontinent']::text[], 1, 'For eksempel alle elgene i en bestemt skog.', true, false, 8),
  ('naturfag-8:okosystemer', 'q10', 'flervalg', 'Hvor kommer nesten all energi i et økosystem fra?', array['Sola', 'Jorda', 'Vannet', 'Nedbryterne']::text[], 0, 'Produsentene fanger solenergi, og den går videre gjennom næringskjedene.', true, false, 9),
  ('naturfag-8:okosystemer', 'm01', 'sant-usant', 'Meitemark er en nedbryter.', array['Sant', 'Usant']::text[], 0, 'Meitemark spiser dødt plantemateriale og bidrar til nedbrytingen.', false, true, 10),
  ('naturfag-8:okosystemer', 'm02', 'sant-usant', 'Energi går i kretsløp akkurat som karbon.', array['Sant', 'Usant']::text[], 1, 'Energi går én vei og tapes som varme. Stoffer som karbon går i kretsløp.', false, true, 11),
  ('naturfag-8:okosystemer', 'm03', 'sant-usant', 'Abiotiske faktorer avgjør hvilke organismer som kan leve et sted.', array['Sant', 'Usant']::text[], 0, 'Temperatur, lys og vann bestemmer levevilkårene.', false, true, 12),
  ('naturfag-8:okosystemer', 'm04', 'sant-usant', 'Næringskjeder har ofte 15–20 ledd.', array['Sant', 'Usant']::text[], 1, 'På grunn av energitapet har næringskjeder sjelden mer enn fire–fem ledd.', false, true, 13),
  ('naturfag-8:okosystemer', 'm05', 'flervalg', 'Hvilken organisme er en produsent?', array['Rev', 'Blåbærlyng', 'Hare', 'Sopp']::text[], 1, 'Blåbærlyng er en plante som driver fotosyntese.', false, true, 14),
  ('naturfag-8:okosystemer', 'm06', 'flervalg', 'Hva er et eksempel på en fremmed art i Norge?', array['Elg', 'Rev', 'Hagelupin', 'Bjørk']::text[], 2, 'Hagelupin er innført og sprer seg på bekostning av norske arter.', false, true, 15),
  ('naturfag-8:okosystemer', 'm07', 'flervalg', 'Hva kalles et dyr som spiser andre dyr?', array['Rovdyr', 'Produsent', 'Planteeter', 'Nedbryter']::text[], 0, 'Rovdyr, som rev og ulv, spiser andre dyr.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-8:okosystemer', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-8:okosystemer', 's01', 'Forklar hva som gjør en skog til et økosystem, og ikke bare en samling levende organismer.', 'En skog er et økosystem fordi organismene der påvirker hverandre og omgivelsene sine. Omgivelsene omfatter også ikke-levende ting som lys, vann og jord.', array['Forklarer at organismer påvirker hverandre og omgivelsene.', 'Får fram at omgivelsene også omfatter ikke-levende deler.']::text[], 0),
  ('naturfag-8:okosystemer', 's02', 'I et område lever flere harer av samme art, og det finnes også rever og planter. Forklar forskjellen på harepopulasjonen og samfunnet i området.', 'Harepopulasjonen er alle harene av samme art i området. Samfunnet er alle populasjonene der, altså harene, revene og plantene.', array['Beskriver harepopulasjonen som individer av samme art i området.', 'Forklarer at samfunnet omfatter alle populasjonene i området.']::text[], 1),
  ('naturfag-8:okosystemer', 's03', 'Et fjellområde er kaldt og vindfullt. Forklar hvordan disse forholdene kan påvirke hvilke planter som lever der, og hva slags faktorer kulde og vind er.', 'Kulde og vind kan gjøre at bare planter som tåler slike forhold, klarer å leve der. De er abiotiske faktorer fordi de ikke er levende.', array['Knytter kulde og vind til hvilke planter som kan klare seg.', 'Identifiserer forholdene som abiotiske, ikke-levende faktorer.']::text[], 2),
  ('naturfag-8:okosystemer', 's04', 'En fugl spiser både insekter og bær, og en rev kan spise fuglen. Forklar hvorfor dette passer bedre inn i et næringsnett enn i én enkel næringskjede.', 'Fuglen har flere matkilder, og den kan selv bli spist av et annet dyr. Flere slike sammenhenger vever næringskjeder sammen til et næringsnett.', array['Viser at fuglen inngår i flere spiseforhold.', 'Forklarer at slike sammenvevde forhold utgjør et næringsnett.']::text[], 3),
  ('naturfag-8:okosystemer', 's05', 'En art blir innført til et område der den ikke hører naturlig hjemme. Forklar hvorfor dette kan forstyrre balansen i økosystemet.', 'Arten kan påvirke organismene som allerede lever der, og dermed endre samspillet mellom dem. Derfor kan balansen i økosystemet bli forstyrret.', array['Forklarer at den innførte arten kan påvirke organismer eller samspill i området.', 'Knytter denne påvirkningen til at økosystemets balanse kan endres.']::text[], 4),
  ('naturfag-8:okosystemer', 's06', 'På ett trinn i en næringskjede er det 80 energienheter. Omtrent en tidel av energien går videre til neste trinn. Hvor mange energienheter går videre?', 'En tidel av 80 er 80 delt på 10, som er 8. Omtrent 8 energienheter går videre.', array['Viser eller beskriver at 80 deles på 10.', 'Svar: omtrent 8 energienheter.']::text[], 5),
  ('naturfag-8:okosystemer', 's07', 'En produsent har 100 energienheter. Omtrent en tidel går videre til konsumenten som spiser produsenten, og en tidel av dette går videre til neste konsument. Hvor mange energienheter når den neste konsumenten?', 'En tidel av 100 er 10, og en tidel av 10 er 1. Omtrent 1 energienhet når den neste konsumenten.', array['Viser at første overføring gir 10 energienheter.', 'Viser at neste overføring gir omtrent 1 energienhet.']::text[], 6),
  ('naturfag-8:okosystemer', 's08', 'Næringskjeder har sjelden mer enn fire–fem ledd. Forklar hvorfor det blir vanskelig å ha mange ledd når bare omtrent en tidel av energien går videre på hvert trinn.', 'På hvert trinn brukes mye energi til livsprosesser og forsvinner som varme, slik at bare omtrent en tidel går videre. Etter flere trinn er det derfor lite energi igjen til organismer høyere oppe i kjeden.', array['Forklarer at mesteparten av energien ikke går videre, men brukes eller forsvinner som varme.', 'Knytter den lille energimengden som går videre, til at det blir få ledd i næringskjeden.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-8:atomer-og-periodesystemet', 'naturfag-8', 'atomer-og-periodesystemet', 'Atomer og periodesystemet', 'Atomets oppbygning, grunnstoffer og kjemiske forbindelser, og hvordan periodesystemet ordner grunnstoffene etter egenskaper.', array[9, 3]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-8:atomer-og-periodesystemet', '## Alt er laget av atomer
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-8:atomer-og-periodesystemet', 'Atom', 'Den minste enheten av et grunnstoff. Består av kjerne og elektroner.', 0),
  ('naturfag-8:atomer-og-periodesystemet', 'Proton', 'Positivt ladd partikkel i atomkjernen.', 1),
  ('naturfag-8:atomer-og-periodesystemet', 'Nøytron', 'Nøytral partikkel i atomkjernen.', 2),
  ('naturfag-8:atomer-og-periodesystemet', 'Elektron', 'Negativt ladd partikkel som beveger seg i skall rundt kjernen.', 3),
  ('naturfag-8:atomer-og-periodesystemet', 'Atomnummer', 'Antall protoner i kjernen. Bestemmer hvilket grunnstoff atomet er.', 4),
  ('naturfag-8:atomer-og-periodesystemet', 'Grunnstoff', 'Et stoff som består av bare én type atomer, som gull eller oksygen.', 5),
  ('naturfag-8:atomer-og-periodesystemet', 'Kjemisk forbindelse', 'Stoff dannet av atomer fra ulike grunnstoffer, som vann (H₂O).', 6),
  ('naturfag-8:atomer-og-periodesystemet', 'Molekyl', 'En gruppe atomer som er bundet sammen, som H₂O eller CO₂.', 7),
  ('naturfag-8:atomer-og-periodesystemet', 'Periodesystemet', 'Oversikt over grunnstoffene ordnet etter atomnummer.', 8),
  ('naturfag-8:atomer-og-periodesystemet', 'Periode', 'En vannrett rad i periodesystemet. Viser antall elektronskall.', 9),
  ('naturfag-8:atomer-og-periodesystemet', 'Gruppe', 'En loddrett kolonne. Grunnstoffene har like mange elektroner i ytterste skall.', 10),
  ('naturfag-8:atomer-og-periodesystemet', 'Alkalimetaller', 'Gruppe 1: myke og svært reaktive metaller.', 11),
  ('naturfag-8:atomer-og-periodesystemet', 'Edelgasser', 'Gruppe 18: nesten ureaktive gasser med fullt ytterskall.', 12),
  ('naturfag-8:atomer-og-periodesystemet', 'Mendelejev', 'Russisk kjemiker som lagde et tidlig periodesystem i 1869.', 13),
  ('naturfag-8:atomer-og-periodesystemet', 'Atommodell', 'En forenklet framstilling av atomet som hjelper oss å forstå og forutsi.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-8:atomer-og-periodesystemet', 'q01', 'flervalg', 'Hvilken ladning har et proton?', array['Negativ', 'Positiv', 'Ingen', 'Det varierer']::text[], 1, 'Protoner er positive, elektroner negative og nøytroner nøytrale.', true, true, 0),
  ('naturfag-8:atomer-og-periodesystemet', 'q02', 'flervalg', 'Hva bestemmer hvilket grunnstoff et atom er?', array['Antall nøytroner', 'Antall elektronskall', 'Antall protoner', 'Størrelsen']::text[], 2, 'Atomnummeret, altså antall protoner, bestemmer grunnstoffet.', true, true, 1),
  ('naturfag-8:atomer-og-periodesystemet', 'q03', 'flervalg', 'Hva er vann, H₂O?', array['En kjemisk forbindelse', 'Et grunnstoff', 'Et atom', 'En edelgass']::text[], 0, 'Vann består av to grunnstoffer, hydrogen og oksygen, og er derfor en forbindelse.', true, true, 2),
  ('naturfag-8:atomer-og-periodesystemet', 'q04', 'flervalg', 'Hva kalles de loddrette kolonnene i periodesystemet?', array['Perioder', 'Skall', 'Rader', 'Grupper']::text[], 3, 'Kolonnene kalles grupper. De vannrette radene kalles perioder.', true, true, 3),
  ('naturfag-8:atomer-og-periodesystemet', 'q05', 'flervalg', 'Hvorfor reagerer edelgassene nesten ikke med andre stoffer?', array['Fordi de er metaller', 'Fordi de har fullt ytterste elektronskall', 'Fordi de er tunge', 'Fordi de er faste stoffer']::text[], 1, 'Et fullt ytterskall gjør atomene stabile, så de har lite behov for å reagere.', true, true, 4),
  ('naturfag-8:atomer-og-periodesystemet', 'q06', 'flervalg', 'Hvor står metallene i periodesystemet?', array['Bare helt til høyre', 'Bare øverst', 'Til venstre og i midten', 'Bare i gruppe 18']::text[], 2, 'De fleste grunnstoffene er metaller og står til venstre og i midten.', true, true, 5),
  ('naturfag-8:atomer-og-periodesystemet', 'q07', 'flervalg', 'Natrium og klor danner sammen et stoff. Hvilket?', array['Bordsalt', 'Vann', 'Karbondioksid', 'Sukker']::text[], 0, 'Natrium og klor danner natriumklorid, NaCl, som er bordsalt.', true, true, 6),
  ('naturfag-8:atomer-og-periodesystemet', 'q08', 'flervalg', 'Hvilken gruppe tilhører natrium og kalium?', array['Halogenene', 'Edelgassene', 'Overgangsmetallene', 'Alkalimetallene']::text[], 3, 'Natrium og kalium står i gruppe 1, alkalimetallene.', true, false, 7),
  ('naturfag-8:atomer-og-periodesystemet', 'q09', 'flervalg', 'Hvorfor er et atom elektrisk nøytralt?', array['Fordi det ikke har partikler med ladning', 'Fordi det har like mange elektroner som protoner', 'Fordi nøytronene nøytraliserer alt', 'Fordi det er lite']::text[], 1, 'Like mange positive protoner og negative elektroner opphever hverandres ladning.', true, true, 8),
  ('naturfag-8:atomer-og-periodesystemet', 'q10', 'flervalg', 'Hva gjorde Mendelejev spesielt?', array['Han oppdaget elektronet', 'Han lagde et periodesystem og lot plass til ukjente grunnstoffer', 'Han fant opp mikroskopet', 'Han delte atomet']::text[], 1, 'Mendelejev forutså grunnstoffer som senere ble oppdaget, noe som styrket systemet hans.', true, false, 9),
  ('naturfag-8:atomer-og-periodesystemet', 'm01', 'sant-usant', 'Nøytroner har negativ ladning.', array['Sant', 'Usant']::text[], 1, 'Nøytroner er nøytrale. Elektronene er negative.', false, true, 10),
  ('naturfag-8:atomer-og-periodesystemet', 'm02', 'sant-usant', 'Grunnstoffer i samme gruppe har ofte like kjemiske egenskaper.', array['Sant', 'Usant']::text[], 0, 'De har like mange elektroner i ytterste skall.', false, true, 11),
  ('naturfag-8:atomer-og-periodesystemet', 'm03', 'sant-usant', 'En kjemisk forbindelse har de samme egenskapene som grunnstoffene den er laget av.', array['Sant', 'Usant']::text[], 1, 'Forbindelser har nye egenskaper. Bordsalt er verken et reaktivt metall eller en giftig gass.', false, true, 12),
  ('naturfag-8:atomer-og-periodesystemet', 'm04', 'sant-usant', 'En atommodell er en forenkling av virkeligheten.', array['Sant', 'Usant']::text[], 0, 'Modeller hjelper oss å forstå, men viser ikke alt nøyaktig.', false, true, 13),
  ('naturfag-8:atomer-og-periodesystemet', 'm05', 'flervalg', 'Hva er atomnummeret til karbon?', array['12', '8', '6', '1']::text[], 2, 'Karbon har 6 protoner og derfor atomnummer 6.', false, true, 14),
  ('naturfag-8:atomer-og-periodesystemet', 'm06', 'flervalg', 'Hvilket grunnstoff er en edelgass?', array['Helium', 'Natrium', 'Klor', 'Jern']::text[], 0, 'Helium står i gruppe 18 sammen med de andre edelgassene.', false, true, 15),
  ('naturfag-8:atomer-og-periodesystemet', 'm07', 'flervalg', 'Hva forteller periodenummeret?', array['Antall protoner', 'Antall elektronskall', 'Om stoffet er fast', 'Atomets masse']::text[], 1, 'Atomer i periode 3 har for eksempel tre elektronskall.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-8:atomer-og-periodesystemet', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-8:atomer-og-periodesystemet', 's01', 'Hva er en atommodell, og hva hjelper den oss med?', 'En atommodell er en forenklet framstilling av et atom. Den hjelper oss å forstå og forutsi egenskapene til stoffer.', array['Forklarer at en atommodell er en forenklet framstilling av et atom.', 'Får fram at modellen hjelper oss å forstå eller forutsi egenskaper ved stoffer.']::text[], 0),
  ('naturfag-8:atomer-og-periodesystemet', 's02', 'Sammenlign et proton og et elektron ved å forklare hvor de finnes i atomet, og hvilken ladning de har.', 'Protonet er positivt ladd og finnes i atomkjernen. Elektronet er negativt ladd og beveger seg i skall rundt kjernen.', array['Plasserer protonet i kjernen og elektronet i skall rundt kjernen.', 'Oppgir at protonet er positivt ladd og elektronet negativt ladd.']::text[], 1),
  ('naturfag-8:atomer-og-periodesystemet', 's03', 'Et vannmolekyl, H₂O, består av 2 hydrogenatomer og 1 oksygenatom. Hvor mange hydrogenatomer, oksygenatomer og atomer totalt er det i 4 vannmolekyler? Vis regnestykket.', 'Det er 4 × 2 = 8 hydrogenatomer og 4 × 1 = 4 oksygenatomer. Til sammen blir det 8 + 4 = 12 atomer.', array['Finner 8 hydrogenatomer og 4 oksygenatomer ved å gange antallet i ett molekyl med 4.', 'Finner at det er 12 atomer totalt.']::text[], 2),
  ('naturfag-8:atomer-og-periodesystemet', 's04', 'Grunnstoffer i samme gruppe i periodesystemet ligner ofte hverandre kjemisk. Forklar hvordan elektronskallene deres henger sammen med dette.', 'Atomer i samme gruppe har like mange elektroner i det ytterste skallet. Derfor ligner de hverandre kjemisk.', array['Forklarer at atomer i samme gruppe har like mange elektroner i ytterste skall.', 'Knytter dette til at grunnstoffene ligner hverandre kjemisk.']::text[], 3),
  ('naturfag-8:atomer-og-periodesystemet', 's05', 'I CO₂ er karbonatomer og oksygenatomer bundet sammen. Forklar hvorfor CO₂ både er et molekyl og en kjemisk forbindelse.', 'CO₂ er et molekyl fordi det er en gruppe atomer som er bundet sammen. Det er en kjemisk forbindelse fordi det består av atomer fra ulike grunnstoffer.', array['Forklarer at CO₂ er et molekyl fordi atomer er bundet sammen.', 'Forklarer at CO₂ er en kjemisk forbindelse fordi det inneholder ulike typer atomer.']::text[], 4),
  ('naturfag-8:atomer-og-periodesystemet', 's06', 'Et grunnstoff står i periode 3 i periodesystemet. Hva forteller perioden om atomene til dette grunnstoffet?', 'Atomene har tre elektronskall, fordi periodetallet viser hvor mange elektronskall atomene har.', array['Knytter periodenummeret til antall elektronskall.', 'Svarar at atomene har tre elektronskall.']::text[], 5),
  ('naturfag-8:atomer-og-periodesystemet', 's07', 'Et karbonatom har 6 protoner, og et oksygenatom har 8 protoner. Hvor mange protoner har de til sammen, og hvor mange flere protoner har oksygenatomet enn karbonatomet? Vis regnestykkene.', 'Til sammen har de 6 + 8 = 14 protoner. Oksygenatomet har 8 − 6 = 2 flere protoner enn karbonatomet.', array['Regner ut at atomene har 14 protoner til sammen.', 'Regner ut at oksygenatomet har 2 flere protoner enn karbonatomet.']::text[], 6),
  ('naturfag-8:atomer-og-periodesystemet', 's08', 'Sammenlign alkalimetallene i gruppe 1 med halogenene i gruppe 17. Ta med hva slags stoffer de er, og minst én egenskap ved hver gruppe.', 'Alkalimetallene er myke og svært reaktive metaller. Halogenene er reaktive ikke-metaller som lett danner salter.', array['Beskriver alkalimetallene som myke, svært reaktive metaller.', 'Beskriver halogenene som reaktive ikke-metaller som lett danner salter.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-8:kjemiske-reaksjoner', 'naturfag-8', 'kjemiske-reaksjoner', 'Kjemiske reaksjoner og forbrenning', 'Hvordan du kjenner igjen en kjemisk reaksjon, loven om massebevaring, reaksjonslikninger og hva som skjer når noe brenner.', array[8, 4]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-8:kjemiske-reaksjoner', '## Fysisk eller kjemisk endring?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-8:kjemiske-reaksjoner', 'Fysisk endring', 'Stoffet endrer form, men er det samme stoffet, som når is smelter.', 0),
  ('naturfag-8:kjemiske-reaksjoner', 'Kjemisk reaksjon', 'Nye stoffer med nye egenskaper dannes ved at atomene omorganiseres.', 1),
  ('naturfag-8:kjemiske-reaksjoner', 'Tegn på kjemisk reaksjon', 'Gass, fargeendring, varme eller kulde, lys og bunnfall.', 2),
  ('naturfag-8:kjemiske-reaksjoner', 'Reaktanter', 'Stoffene man starter med i en reaksjon.', 3),
  ('naturfag-8:kjemiske-reaksjoner', 'Produkter', 'Stoffene som dannes i en reaksjon.', 4),
  ('naturfag-8:kjemiske-reaksjoner', 'Reaksjonslikning', 'Viser en reaksjon med formler: 2H₂ + O₂ → 2H₂O.', 5),
  ('naturfag-8:kjemiske-reaksjoner', 'Koeffisient', 'Tallet foran en formel i en reaksjonslikning.', 6),
  ('naturfag-8:kjemiske-reaksjoner', 'Loven om massebevaring', 'Massen av produktene er lik massen av reaktantene.', 7),
  ('naturfag-8:kjemiske-reaksjoner', 'Lavoisier', 'Fransk kjemiker som viste massebevaring på 1700-tallet.', 8),
  ('naturfag-8:kjemiske-reaksjoner', 'Balansert likning', 'Like mange atomer av hvert grunnstoff på begge sider av pilen.', 9),
  ('naturfag-8:kjemiske-reaksjoner', 'Forbrenning', 'Et stoff reagerer med oksygen og avgir varme og lys.', 10),
  ('naturfag-8:kjemiske-reaksjoner', 'Branntrekanten', 'Brensel, oksygen og høy nok temperatur. Fjernes én, slokner brannen.', 11),
  ('naturfag-8:kjemiske-reaksjoner', 'Fullstendig forbrenning', 'Gir CO₂ og vann når det er nok oksygen.', 12),
  ('naturfag-8:kjemiske-reaksjoner', 'Ufullstendig forbrenning', 'For lite oksygen. Kan gi sot og giftig karbonmonoksid (CO).', 13),
  ('naturfag-8:kjemiske-reaksjoner', 'Bunnfall', 'Et fast stoff som dannes i en væske ved en reaksjon.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-8:kjemiske-reaksjoner', 'q01', 'flervalg', 'Hvilken endring er en kjemisk reaksjon?', array['Is som smelter', 'Vann som koker', 'Et stearinlys som brenner', 'Sukker som løses i te']::text[], 2, 'Når stearinet brenner, dannes nye stoffer som CO₂ og vann.', true, true, 0),
  ('naturfag-8:kjemiske-reaksjoner', 'q02', 'flervalg', 'Hva sier loven om massebevaring?', array['Massen av produktene er lik massen av reaktantene', 'Massen øker i alle reaksjoner', 'Gasser har ingen masse', 'Massen forsvinner ved forbrenning']::text[], 0, 'Atomene omorganiseres, men ingen forsvinner eller oppstår.', true, true, 1),
  ('naturfag-8:kjemiske-reaksjoner', 'q03', 'flervalg', 'Hva kalles stoffene man starter med i en reaksjon?', array['Produkter', 'Koeffisienter', 'Katalysatorer', 'Reaktanter']::text[], 3, 'Reaktantene er utgangsstoffene. Produktene dannes i reaksjonen.', true, true, 2),
  ('naturfag-8:kjemiske-reaksjoner', 'q04', 'flervalg', 'Hvilke tre ting trengs for at noe skal brenne?', array['Vann, lys og luft', 'Brensel, oksygen og høy nok temperatur', 'Karbon, nitrogen og vann', 'Metall, salt og varme']::text[], 1, 'Dette er branntrekanten.', true, true, 3),
  ('naturfag-8:kjemiske-reaksjoner', 'q05', 'flervalg', 'Hvorfor slokner en brann når du legger et brannteppe over?', array['Fordi temperaturen øker', 'Fordi brenselet forsvinner', 'Fordi oksygentilførselen stoppes', 'Fordi teppet er vått']::text[], 2, 'Teppet kveler brannen ved å fjerne oksygenet fra branntrekanten.', true, true, 4),
  ('naturfag-8:kjemiske-reaksjoner', 'q06', 'flervalg', 'Hva dannes ved fullstendig forbrenning av stoffer med karbon og hydrogen?', array['Karbondioksid og vann', 'Oksygen og sukker', 'Karbonmonoksid og sot', 'Bare vann']::text[], 0, 'Med nok oksygen blir karbonet til CO₂ og hydrogenet til H₂O.', true, true, 5),
  ('naturfag-8:kjemiske-reaksjoner', 'q07', 'flervalg', 'Hvorfor er ufullstendig forbrenning farlig?', array['Den gir for mye oksygen', 'Den er for kald', 'Den gir ikke varme', 'Den kan danne den giftige gassen karbonmonoksid']::text[], 3, 'Karbonmonoksid er luktfritt og svært giftig, fordi det hindrer blodet i å frakte oksygen.', true, true, 6),
  ('naturfag-8:kjemiske-reaksjoner', 'q08', 'flervalg', 'Hvor mange oksygenatomer er det på hver side i 2H₂ + O₂ → 2H₂O?', array['Ett', 'To', 'Fire', 'Tre']::text[], 1, 'O₂ har to oksygenatomer, og 2H₂O har også to. Likningen er balansert.', true, true, 7),
  ('naturfag-8:kjemiske-reaksjoner', 'q09', 'flervalg', 'Hvilket er IKKE et tegn på kjemisk reaksjon?', array['Gassbobler dannes', 'Fargen endres', 'Et stoff endrer form fra fast til flytende', 'Det avgis lys']::text[], 2, 'Smelting er en fysisk endring. Stoffet er det samme.', true, false, 8),
  ('naturfag-8:kjemiske-reaksjoner', 'q10', 'flervalg', 'En fyrstikk brenner og ser lettere ut etterpå. Hvor ble massen av?', array['Den forsvant', 'Den gikk over i gasser som slapp ut i lufta', 'Den ble til energi', 'Den gikk inn i bordet']::text[], 1, 'Atomene finnes fortsatt, men i gasser som CO₂ og vanndamp.', true, false, 9),
  ('naturfag-8:kjemiske-reaksjoner', 'm01', 'sant-usant', 'I en kjemisk reaksjon kan atomer forsvinne.', array['Sant', 'Usant']::text[], 1, 'Atomene bevares. De bare kobles sammen på nye måter.', false, true, 10),
  ('naturfag-8:kjemiske-reaksjoner', 'm02', 'sant-usant', 'Vann kan slokke en brann fordi det senker temperaturen.', array['Sant', 'Usant']::text[], 0, 'Vann kjøler ned og fjerner dermed «høy nok temperatur» fra branntrekanten.', false, true, 11),
  ('naturfag-8:kjemiske-reaksjoner', 'm03', 'sant-usant', 'Karbonmonoksid er en ufarlig gass.', array['Sant', 'Usant']::text[], 1, 'Karbonmonoksid er svært giftig og kan ikke kjennes på lukt.', false, true, 12),
  ('naturfag-8:kjemiske-reaksjoner', 'm04', 'sant-usant', 'Et bunnfall er et tegn på at det har skjedd en kjemisk reaksjon.', array['Sant', 'Usant']::text[], 0, 'Når et fast stoff dannes i en væske, har det oppstått et nytt stoff.', false, true, 13),
  ('naturfag-8:kjemiske-reaksjoner', 'm05', 'flervalg', 'Hva kalles stoffene som dannes i en reaksjon?', array['Reaktanter', 'Koeffisienter', 'Produkter', 'Brensel']::text[], 2, 'Produktene står på høyre side av pilen.', false, true, 14),
  ('naturfag-8:kjemiske-reaksjoner', 'm06', 'flervalg', 'Hvilken gass trengs til forbrenning?', array['Oksygen', 'Nitrogen', 'Helium', 'Karbondioksid']::text[], 0, 'Forbrenning er en reaksjon med oksygen.', false, true, 15),
  ('naturfag-8:kjemiske-reaksjoner', 'm07', 'flervalg', 'Hvilken er en fysisk endring?', array['Rust på en sykkel', 'Brød som ristes svart', 'Vann som fryser til is', 'Ved som brenner']::text[], 2, 'Is er fortsatt vann, bare i fast form.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-8:kjemiske-reaksjoner', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-8:kjemiske-reaksjoner', 's01', 'Is smelter til vann, mens en fyrstikk brenner. Sammenlign hva som skjer med stoffene i de to situasjonene.', 'Når is smelter, er det fortsatt vann, bare i en annen form. Når en fyrstikk brenner, skjer en kjemisk reaksjon der det dannes nye stoffer.', array['Forklarer at smelting er en fysisk endring der stoffet er det samme.', 'Forklarer at brenning er en kjemisk reaksjon der nye stoffer dannes.']::text[], 0),
  ('naturfag-8:kjemiske-reaksjoner', 's02', 'Når to væsker blandes, begynner det å boble og fargen endrer seg. Forklar hvorfor dette er tegn på en kjemisk reaksjon, og hva som skjer med atomene.', 'Bobler og fargeendring er tegn på at det kan ha skjedd en kjemisk reaksjon. Da dannes nye stoffer ved at atomene omorganiseres.', array['Knytter bobler og/eller fargeendring til tegn på en kjemisk reaksjon.', 'Forklarer at atomene omorganiseres og nye stoffer dannes.']::text[], 1),
  ('naturfag-8:kjemiske-reaksjoner', 's03', 'Etter at to stoffer blandes i en væske, dannes det et fast stoff. Hva kalles det faste stoffet, og hva forteller dannelsen om reaksjonen?', 'Det faste stoffet kalles et bunnfall. Når det dannes et bunnfall i en væske, er det et tegn på en kjemisk reaksjon.', array['Kaller det faste stoffet et bunnfall.', 'Forklarer at dannelse av bunnfall er et tegn på en kjemisk reaksjon.']::text[], 2),
  ('naturfag-8:kjemiske-reaksjoner', 's04', 'I reaksjonslikningen 2H₂ + O₂ → 2H₂O: Hvor mange vannmolekyler dannes, og hvor mange hydrogenatomer er det til sammen i disse molekylene? Vis det viktigste regnestykket.', 'Koeffisienten 2 viser at det dannes 2 vannmolekyler. Hvert vannmolekyl har 2 hydrogenatomer, så 2 · 2 = 4 hydrogenatomer til sammen.', array['Bruker koeffisienten til å finne at det dannes 2 vannmolekyler.', 'Viser at 2 vannmolekyler inneholder 4 hydrogenatomer til sammen.']::text[], 3),
  ('naturfag-8:kjemiske-reaksjoner', 's05', 'I et lukket system reagerer stoffer med en samlet masse på 8 g og 3 g. Hva er den samlede massen av produktene? Vis det viktigste steget og forklar kort hvorfor.', 'Den samlede massen er 8 g + 3 g = 11 g. Massen er bevart i reaksjonen, så produktene har samme samlede masse som reaktantene.', array['Regner ut at massen er 11 g.', 'Knytter svaret til at massen bevares i en kjemisk reaksjon.']::text[], 4),
  ('naturfag-8:kjemiske-reaksjoner', 's06', 'I en kjemisk reaksjon kan atomer ikke forsvinne eller oppstå. Forklar hvorfor en reaksjonslikning må ha like mange atomer av hvert grunnstoff på begge sider av pilen.', 'Atomene blir bare omorganisert i reaksjonen. Derfor må det være like mange atomer av hvert grunnstoff før og etter reaksjonen, og likningen må være balansert.', array['Forklarer at atomene omorganiseres, men ikke forsvinner eller oppstår.', 'Knytter dette til at hvert grunnstoff må ha like mange atomer på begge sider av likningen.']::text[], 5),
  ('naturfag-8:kjemiske-reaksjoner', 's07', 'En brann slokner etter at den blir avkjølt med vann. Bruk branntrekanten til å forklare hvorfor avkjølingen kan slokke brannen.', 'Branntrekanten krever brensel, oksygen og høy nok temperatur. Vannet senker temperaturen, og når den blir for lav, slokner brannen.', array['Forklarer at branntrekanten krever høy nok temperatur.', 'Forklarer at vann senker temperaturen slik at brannen slokner.']::text[], 6),
  ('naturfag-8:kjemiske-reaksjoner', 's08', 'Forbrenning kan gi oss nyttige ting, men også ha ulemper. Nevn én nytte ved forbrenning og én ulempe ved forbrenning av fossile brensler.', 'Forbrenning kan gi oss varme, strøm eller drivstoff til transport. Forbrenning av fossile brensler slipper ut CO₂, som bidrar til global oppvarming, og kan også gi luftforurensning.', array['Nevner en nytte, for eksempel varme, strøm eller drivstoff til transport.', 'Nevner en ulempe, som CO₂-utslipp som bidrar til global oppvarming eller luftforurensning.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-8:platetektonikk', 'naturfag-8', 'platetektonikk', 'Platetektonikk og jordas utvikling', 'Jordas indre oppbygning, teorien om platetektonikk, hva som skjer ved plategrensene, og hvilke observasjoner som støtter teorien.', array[19, 3]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-8:platetektonikk', '## Jordas oppbygning
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-8:platetektonikk', 'Jordskorpa', 'Jordas tynne, harde ytterlag.', 0),
  ('naturfag-8:platetektonikk', 'Mantelen', 'Tykt lag med varm stein som beveger seg svært langsomt.', 1),
  ('naturfag-8:platetektonikk', 'Kjernen', 'Består mest av jern og nikkel. Ytre kjerne er flytende, indre kjerne fast.', 2),
  ('naturfag-8:platetektonikk', 'Litosfæren', 'Jordskorpa og den stive øverste delen av mantelen, delt i plater.', 3),
  ('naturfag-8:platetektonikk', 'Platetektonikk', 'Teorien om at litosfæreplatene beveger seg og former jordoverflaten.', 4),
  ('naturfag-8:platetektonikk', 'Konveksjonsstrømmer', 'Strømmer i mantelen der varm stein stiger og kald synker. Driver platene.', 5),
  ('naturfag-8:platetektonikk', 'Alfred Wegener', 'Tysk forsker som i 1912 foreslo teorien om kontinentaldrift.', 6),
  ('naturfag-8:platetektonikk', 'Pangea', 'Superkontinentet der alle kontinentene en gang var samlet.', 7),
  ('naturfag-8:platetektonikk', 'Divergerende grense', 'Platene beveger seg fra hverandre, og ny havbunn dannes.', 8),
  ('naturfag-8:platetektonikk', 'Konvergerende grense', 'Platene beveger seg mot hverandre. Gir fjellkjeder, dyphavsgroper og vulkaner.', 9),
  ('naturfag-8:platetektonikk', 'Transformgrense', 'Platene glir forbi hverandre sidelengs, som ved San Andreas-forkastningen.', 10),
  ('naturfag-8:platetektonikk', 'Subduksjon', 'En plate skyves ned under en annen plate.', 11),
  ('naturfag-8:platetektonikk', 'Midtatlanterhavsryggen', 'Divergerende plategrense i Atlanterhavet. Island ligger på den.', 12),
  ('naturfag-8:platetektonikk', 'Bevis for platetektonikk', 'Kystlinjer som passer, like fossiler, havbunnens alder, magnetiske striper og GPS.', 13),
  ('naturfag-8:platetektonikk', 'Platenes fart', 'Noen få centimeter i året, omtrent like raskt som negler vokser.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-8:platetektonikk', 'q01', 'flervalg', 'Hvilket lag i jorda er flytende?', array['Jordskorpa', 'Den ytre kjernen', 'Den indre kjernen', 'Litosfæren']::text[], 1, 'Den ytre kjernen er flytende jern og nikkel. Den indre kjernen er fast.', true, true, 0),
  ('naturfag-8:platetektonikk', 'q02', 'flervalg', 'Hvem foreslo teorien om kontinentaldrift i 1912?', array['Charles Darwin', 'Isaac Newton', 'Alfred Wegener', 'Dmitrij Mendelejev']::text[], 2, 'Alfred Wegener mente at kontinentene en gang hadde vært samlet i Pangea.', true, true, 1),
  ('naturfag-8:platetektonikk', 'q03', 'flervalg', 'Hva skjer ved en divergerende plategrense?', array['Platene beveger seg fra hverandre', 'Platene kolliderer', 'Platene glir forbi hverandre', 'Platene står stille']::text[], 0, 'Magma strømmer opp og danner ny havbunn, som ved Midtatlanterhavsryggen.', true, true, 2),
  ('naturfag-8:platetektonikk', 'q04', 'flervalg', 'Hvordan ble Himalaya dannet?', array['Av et vulkanutbrudd', 'Ved at platene gled fra hverandre', 'Av isbreer', 'Ved at to kontinentalplater kolliderte']::text[], 3, 'Kollisjonen mellom den indiske og den eurasiske platen presset opp fjellkjeden.', true, true, 3),
  ('naturfag-8:platetektonikk', 'q05', 'flervalg', 'Hvor fort beveger platene seg?', array['Flere meter i sekundet', 'Noen få centimeter i året', 'Flere kilometer i året', 'De beveger seg ikke']::text[], 1, 'Bevegelsen er omtrent like rask som negler vokser.', true, true, 4),
  ('naturfag-8:platetektonikk', 'q06', 'flervalg', 'Hvilken observasjon støtter platetektonikken?', array['At havet er salt', 'At fjell er høye', 'At samme fossiler finnes på kontinenter langt fra hverandre', 'At det er kaldt på Nordpolen']::text[], 2, 'Like fossiler og bergarter tyder på at kontinentene en gang lå sammen.', true, true, 5),
  ('naturfag-8:platetektonikk', 'q07', 'flervalg', 'Hvor finnes de fleste jordskjelv og vulkaner?', array['Langs plategrensene', 'Midt på platene', 'Bare i Norge', 'Bare i havet']::text[], 0, 'Det er ved plategrensene at platene støter mot, skiller seg fra eller glir forbi hverandre.', true, true, 6),
  ('naturfag-8:platetektonikk', 'q08', 'flervalg', 'Hvorfor har Norge få kraftige jordskjelv?', array['Fordi landet er kaldt', 'Fordi det ikke finnes plater under Norge', 'Fordi fjellene stopper dem', 'Fordi Norge ligger midt på en plate, langt fra grensene']::text[], 3, 'Norge ligger inne på den eurasiske platen, der det er lite bevegelse.', true, false, 7),
  ('naturfag-8:platetektonikk', 'q09', 'flervalg', 'Hva driver platebevegelsene?', array['Tidevannet', 'Konveksjonsstrømmer i mantelen', 'Vinden', 'Månens bevegelse']::text[], 1, 'Varm stein stiger og kaldere synker i mantelen, og dette drar med seg platene.', true, true, 8),
  ('naturfag-8:platetektonikk', 'q10', 'flervalg', 'Hvor på havbunnen er berggrunnen yngst?', array['Nær kontinentene', 'Nær midthavsryggene', 'På de dypeste stedene', 'Overalt like gammel']::text[], 1, 'Ny havbunn dannes ved ryggene og skyves utover, så den eldste ligger lengst unna.', true, false, 9),
  ('naturfag-8:platetektonikk', 'm01', 'sant-usant', 'Island ligger på en divergerende plategrense.', array['Sant', 'Usant']::text[], 0, 'Island ligger på Midtatlanterhavsryggen, der platene beveger seg fra hverandre.', false, true, 10),
  ('naturfag-8:platetektonikk', 'm02', 'sant-usant', 'Wegeners teori ble godtatt av alle med en gang.', array['Sant', 'Usant']::text[], 1, 'Mange avviste teorien fordi han ikke kunne forklare hva som drev bevegelsen.', false, true, 11),
  ('naturfag-8:platetektonikk', 'm03', 'sant-usant', 'San Andreas-forkastningen er et eksempel på en transformgrense.', array['Sant', 'Usant']::text[], 0, 'Der glir to plater sidelengs forbi hverandre.', false, true, 12),
  ('naturfag-8:platetektonikk', 'm04', 'sant-usant', 'Kontinentene ligger fast og har aldri beveget seg.', array['Sant', 'Usant']::text[], 1, 'Kontinentene beveger seg noen centimeter i året og har flyttet seg mye over millioner av år.', false, true, 13),
  ('naturfag-8:platetektonikk', 'm05', 'flervalg', 'Hva kalles det når en plate skyves ned under en annen?', array['Erosjon', 'Subduksjon', 'Konveksjon', 'Forvitring']::text[], 1, 'Subduksjon skjer ved konvergerende grenser og gir dyphavsgroper og vulkaner.', false, true, 14),
  ('naturfag-8:platetektonikk', 'm06', 'flervalg', 'Hva het superkontinentet der alle kontinentene var samlet?', array['Atlantis', 'Eurasia', 'Pangea', 'Gondwana-Norge']::text[], 2, 'Pangea betyr «hele jorda».', false, true, 15),
  ('naturfag-8:platetektonikk', 'm07', 'flervalg', 'Hvilken moderne teknologi viser at platene beveger seg i dag?', array['GPS-målinger', 'Termometre', 'Mikroskoper', 'Barometre']::text[], 0, 'Presise GPS-målinger viser at punkter på ulike plater flytter seg i forhold til hverandre.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-8:platetektonikk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-8:platetektonikk', 's01', 'Hva er litosfæren, og hvordan henger litosfæren sammen med platene?', 'Litosfæren består av jordskorpa og den stive øverste delen av mantelen. Den er delt opp i store plater.', array['Forklarer at litosfæren består av jordskorpa og den stive øverste delen av mantelen.', 'Forklarer at litosfæren er delt i plater.']::text[], 0),
  ('naturfag-8:platetektonikk', 's02', 'Sammenlign hva som kan skje når en havplate møter en annen plate, og når to kontinentalplater kolliderer.', 'Når en havplate møter en annen plate, kan havplata skyves ned under den andre. Det kan dannes dyphavsgroper og vulkaner. Når to kontinentalplater kolliderer, kan det presses opp en fjellkjede.', array['Beskriver at en havplate kan skyves ned under en annen plate, og knytter dette til dyphavsgroper eller vulkaner.', 'Beskriver at kollisjon mellom kontinentalplater kan presse opp fjellkjeder.']::text[], 1),
  ('naturfag-8:platetektonikk', 's03', 'To plater glir sidelengs forbi hverandre langs en plategrense. Hvilken type plategrense er dette, og hva kan bevegelsen føre til?', 'Dette er en transformgrense. Platene glir sidelengs forbi hverandre, og bevegelsen gir ofte jordskjelv.', array['Identifiserer plategrensen som en transformgrense og beskriver sideveis bevegelse.', 'Knytter denne typen plategrense til jordskjelv.']::text[], 2),
  ('naturfag-8:platetektonikk', 's04', 'Havbunnen er yngst ved midthavsryggene og blir eldre jo lenger unna den ligger. Hva forteller dette mønsteret om hvordan havbunnen dannes og beveger seg?', 'Ny havbunn dannes ved midthavsryggene når magma strømmer opp. Derfra beveger havbunnen seg utover på hver side av ryggen.', array['Forklarer at ny havbunn dannes ved midthavsrygger når magma strømmer opp.', 'Forklarer at havbunnen beveger seg bort fra ryggen.']::text[], 3),
  ('naturfag-8:platetektonikk', 's05', 'Alfred Wegener foreslo i 1912 at kontinentene hadde vært samlet i Pangea og drevet fra hverandre. Hvorfor avviste mange forskere ideen først, og hva bidro senere til at den ble godtatt?', 'Mange forskere avviste ideen fordi Wegener ikke kunne forklare hva som fikk kontinentene til å bevege seg. På 1960-tallet bidro nye undersøkelser av havbunnen til at teorien ble godtatt.', array['Forklarer at Wegener ikke kunne forklare hva som drev kontinentene.', 'Nevner at nye undersøkelser av havbunnen bidro til at teorien ble godtatt.']::text[], 4),
  ('naturfag-8:platetektonikk', 's06', 'Norge ligger midt på den eurasiske platen, langt fra plategrensene, men fjellene våre ble dannet i en stor kontinentkollisjon for over 400 millioner år siden. Forklar hvordan begge deler kan stemme.', 'Norge ligger nå langt fra plategrensene og har derfor få og svake jordskjelv. Fjellene ble likevel dannet i en stor kollisjon mellom kontinenter for over 400 millioner år siden.', array['Skiller mellom Norges plassering på platen i dag og tidligere platebevegelser.', 'Forklarer at fjellene ble dannet i en stor kollisjon mellom kontinenter.']::text[], 5),
  ('naturfag-8:platetektonikk', 's07', 'Wegener foreslo teorien om kontinentaldrift i 1912, og teorien ble godtatt på 1960-tallet. Regn fra 1960, starten av 1960-tallet: Hvor mange år gikk det fra 1912 til 1960? Vis det viktigste regnestykket.', 'Det gikk 48 år. Regnestykket er 1960 − 1912 = 48.', array['Får fram at det gikk 48 år.', 'Viser regnestykket 1960 − 1912, eller en tilsvarende utregning.']::text[], 6),
  ('naturfag-8:platetektonikk', 's08', 'Jorda beskrives med fire hovedlag: jordskorpa, mantelen, den ytre kjernen og den indre kjernen. Kjernen har to deler. Hvor mange av de fire lagene er ikke deler av kjernen? Vis regnestykket.', 'To av lagene er ikke deler av kjernen: jordskorpa og mantelen. Regnestykket er 4 − 2 = 2.', array['Får fram at to lag ikke er deler av kjernen.', 'Viser regnestykket 4 − 2 = 2, eller en tilsvarende utregning.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-8:metoder-og-kilder', 'samfunnsfag-8', 'metoder-og-kilder', 'Samfunnsfaglige metoder og kilder', 'Hvordan du undersøker samfunnet med spørreundersøkelser, intervjuer og kilder, hvordan du vurderer kildene, og hvordan algoritmer kan prege forståelsen vår.', array[1, 2]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-8:metoder-og-kilder', '## Å undersøke samfunnet
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-8:metoder-og-kilder', 'Problemstilling', 'Et spørsmål en undersøkelse skal gi svar på.', 0),
  ('samfunnsfag-8:metoder-og-kilder', 'Kvantitativ metode', 'Metode som gir tall, som en spørreundersøkelse med faste svaralternativer.', 1),
  ('samfunnsfag-8:metoder-og-kilder', 'Kvalitativ metode', 'Metode som gir dypere innsikt, som intervju og observasjon.', 2),
  ('samfunnsfag-8:metoder-og-kilder', 'Spørreundersøkelse', 'Mange svarer på de samme spørsmålene, ofte med faste alternativer.', 3),
  ('samfunnsfag-8:metoder-og-kilder', 'Intervju', 'Samtale med åpne spørsmål for å få fram tanker og erfaringer.', 4),
  ('samfunnsfag-8:metoder-og-kilder', 'Observasjon', 'Å se på og notere hva folk faktisk gjør.', 5),
  ('samfunnsfag-8:metoder-og-kilder', 'Gyldighet (validitet)', 'At undersøkelsen faktisk måler det den skal måle.', 6),
  ('samfunnsfag-8:metoder-og-kilder', 'Pålitelighet (reliabilitet)', 'At resultatene er nøyaktige og ville blitt de samme ved gjentakelse.', 7),
  ('samfunnsfag-8:metoder-og-kilder', 'Ledende spørsmål', 'Et spørsmål som styrer svaret, og som svekker undersøkelsen.', 8),
  ('samfunnsfag-8:metoder-og-kilder', 'Primærkilde', 'Kilde fra tiden eller hendelsen selv, som et brev eller fotografi.', 9),
  ('samfunnsfag-8:metoder-og-kilder', 'Sekundærkilde', 'Kilde skrevet senere med utgangspunkt i andre kilder, som en lærebok.', 10),
  ('samfunnsfag-8:metoder-og-kilder', 'Perspektiv', 'Ståstedet en kilde ser en sak fra.', 11),
  ('samfunnsfag-8:metoder-og-kilder', 'Algoritme', 'Et dataprogram som velger ut hva du får se på nett.', 12),
  ('samfunnsfag-8:metoder-og-kilder', 'Filterboble', 'Når du mest møter informasjon som bekrefter det du allerede tror.', 13),
  ('samfunnsfag-8:metoder-og-kilder', 'Mangel på kilder', 'Grupper som har etterlatt få kilder, får ofte mindre plass i historien.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-8:metoder-og-kilder', 'q01', 'flervalg', 'Hva er en kvantitativ metode?', array['En metode som gir tall som kan telles', 'Et dybdeintervju', 'En observasjon uten notater', 'Å lese en roman']::text[], 0, 'Spørreundersøkelser med faste alternativer gir tall som kan sammenlignes.', true, true, 0),
  ('samfunnsfag-8:metoder-og-kilder', 'q02', 'flervalg', 'Hvilken metode passer best for å forstå hvorfor ungdom velger som de gjør?', array['Å telle antall elever', 'Intervju med åpne spørsmål', 'Å lese statistikk alene', 'Å måle høyden deres']::text[], 1, 'Kvalitative metoder som intervju gir innsikt i tanker og begrunnelser.', true, true, 1),
  ('samfunnsfag-8:metoder-og-kilder', 'q03', 'flervalg', 'Hva er en primærkilde?', array['En lærebok om 1800-tallet', 'En nettside som oppsummerer historie', 'Et brev skrevet av en person i 1905', 'Et leksikon']::text[], 2, 'Primærkilder stammer fra tiden eller hendelsen selv.', true, true, 2),
  ('samfunnsfag-8:metoder-og-kilder', 'q04', 'flervalg', 'Hva betyr gyldighet i en undersøkelse?', array['At den er gratis', 'At mange svarer', 'At den er rask', 'At den måler det den skal måle']::text[], 3, 'Spør du om noe annet enn det du vil vite, blir resultatene lite gyldige.', true, true, 3),
  ('samfunnsfag-8:metoder-og-kilder', 'q05', 'flervalg', 'Hvilket spørsmål er ledende?', array['Hvor mange timer bruker du på mobilen?', 'Er du enig i at mobilbruk er skadelig?', 'Hvilke apper bruker du?', 'Når legger du deg?']::text[], 1, 'Formuleringen legger opp til at man skal svare ja.', true, true, 4),
  ('samfunnsfag-8:metoder-og-kilder', 'q06', 'flervalg', 'Hva er en filterboble?', array['Når du mest møter informasjon som bekrefter det du tror', 'En type spørreundersøkelse', 'En kilde fra middelalderen', 'Et digitalt verktøy for diagrammer']::text[], 0, 'Algoritmer viser deg innhold som ligner det du har likt før.', true, true, 5),
  ('samfunnsfag-8:metoder-og-kilder', 'q07', 'flervalg', 'Hvorfor vet vi mindre om hvordan fattige levde i gamle dager?', array['Fordi de ikke fantes', 'Fordi det var forbudt å skrive om dem', 'Fordi de har etterlatt få skriftlige kilder', 'Fordi historikere ikke er interessert']::text[], 2, 'Mangel på kilder gjør at noen gruppers historie er mindre kjent.', true, true, 6),
  ('samfunnsfag-8:metoder-og-kilder', 'q08', 'flervalg', 'Hva er en fordel med å kombinere kvantitative og kvalitative metoder?', array['Det tar kortere tid', 'Man får både oversikt og forklaring', 'Man trenger ingen problemstilling', 'Man slipper å vurdere kildene']::text[], 1, 'Tall viser hvor vanlig noe er, mens intervjuer forklarer hvorfor.', true, false, 7),
  ('samfunnsfag-8:metoder-og-kilder', 'q09', 'flervalg', 'Hvilket spørsmål hører til kildevurdering?', array['Hvem har laget kilden, og hvorfor?', 'Hvor mange sider er den?', 'Hvilken farge har den?', 'Hvor mye veier den?']::text[], 0, 'Avsender og formål sier mye om hvor pålitelig og nøytral kilden er.', true, true, 8),
  ('samfunnsfag-8:metoder-og-kilder', 'q10', 'flervalg', 'Hvordan kan du ta vare på personvernet i en spørreundersøkelse?', array['Be om fødselsnummer', 'Publisere navnene', 'Dele svarene på nett', 'Gjøre svarene anonyme']::text[], 3, 'Anonyme svar beskytter deltakerne og gir ofte ærligere svar.', true, false, 9),
  ('samfunnsfag-8:metoder-og-kilder', 'm01', 'sant-usant', 'En lærebok er en sekundærkilde.', array['Sant', 'Usant']::text[], 0, 'Læreboka er skrevet senere med utgangspunkt i andre kilder.', false, true, 10),
  ('samfunnsfag-8:metoder-og-kilder', 'm02', 'sant-usant', 'Et lite utvalg gir alltid svært pålitelige resultater.', array['Sant', 'Usant']::text[], 1, 'Få svar øker risikoen for tilfeldige og skjeve resultater.', false, true, 11),
  ('samfunnsfag-8:metoder-og-kilder', 'm03', 'sant-usant', 'Ulike kilder kan gi ulike perspektiver på samme hendelse.', array['Sant', 'Usant']::text[], 0, 'Derfor er det lurt å bruke flere kilder.', false, true, 12),
  ('samfunnsfag-8:metoder-og-kilder', 'm04', 'sant-usant', 'Algoritmer viser alle brukere nøyaktig det samme innholdet.', array['Sant', 'Usant']::text[], 1, 'Algoritmer tilpasser innholdet til den enkelte ut fra tidligere aktivitet.', false, true, 13),
  ('samfunnsfag-8:metoder-og-kilder', 'm05', 'flervalg', 'Hva kalles det å se på og notere hva folk faktisk gjør?', array['Spørreundersøkelse', 'Observasjon', 'Kildekritikk', 'Statistikk']::text[], 1, 'Observasjon er en kvalitativ metode.', false, true, 14),
  ('samfunnsfag-8:metoder-og-kilder', 'm06', 'flervalg', 'Hva er en problemstilling?', array['Et spørsmål undersøkelsen skal svare på', 'En konklusjon', 'En kildeliste', 'Et diagram']::text[], 0, 'Problemstillingen gir undersøkelsen retning.', false, true, 15),
  ('samfunnsfag-8:metoder-og-kilder', 'm07', 'flervalg', 'Hva er en ensrettet kilde?', array['En kilde med mange perspektiver', 'En kilde fra staten', 'En kilde som bare viser én side av en sak', 'En gammel kilde']::text[], 2, 'Ensrettede kilder kan gi et skjevt bilde av virkeligheten.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-8:metoder-og-kilder', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-8:metoder-og-kilder', 's01', 'En klasse vil undersøke hvilke fritidsaktiviteter elevene på skolen liker best. Skriv en tydelig problemstilling som undersøkelsen kan prøve å svare på.', 'En mulig problemstilling er: «Hvilke fritidsaktiviteter liker elevene på skolen best?»', array['Skriver et tydelig spørsmål som undersøkelsen skal finne svar på.', 'Spørsmålet handler om elevenes fritidsaktiviteter.']::text[], 0),
  ('samfunnsfag-8:metoder-og-kilder', 's02', 'En klasse vil finne ut både hvor mange elever som sykler til skolen, og hva som gjør at noen velger å sykle. Sammenlign hva en spørreundersøkelse med faste svaralternativer og et intervju med åpne spørsmål kan finne ut.', 'Spørreundersøkelsen kan vise hvor mange som sykler. Intervjuet kan gi dypere innsikt i hvorfor noen velger å sykle.', array['Forklarer at spørreundersøkelsen kan gi tall eller vise hvor vanlig noe er.', 'Forklarer at intervjuet kan få fram tanker eller grunner.']::text[], 1),
  ('samfunnsfag-8:metoder-og-kilder', 's03', 'Du vil undersøke om elever faktisk bruker søppelkassene til å sortere avfall. Beskriv hvordan du kan bruke observasjon til å undersøke dette.', 'Jeg kan se på hva elevene gjør når de kaster avfall, og notere om de bruker riktig søppelkasse. Da undersøker jeg handlingene deres direkte.', array['Beskriver at man ser på hva elevene faktisk gjør.', 'Beskriver at man noterer det man observerer, for eksempel hvilken søppelkasse som brukes.']::text[], 2),
  ('samfunnsfag-8:metoder-og-kilder', 's04', 'En klasse gjennomfører den samme spørreundersøkelsen to ganger, men får svært ulike resultater. Forklar hva dette kan si om undersøkelsens pålitelighet.', 'Pålitelighet handler om at resultatene er nøyaktige og ville blitt omtrent de samme hvis undersøkelsen ble gjentatt. Svært ulike resultater kan tyde på at undersøkelsen har lav pålitelighet.', array['Forklarer at pålitelighet handler om nøyaktige resultater som bør kunne gjentas.', 'Knytter de svært ulike resultatene til mulig lav pålitelighet.']::text[], 3),
  ('samfunnsfag-8:metoder-og-kilder', 's05', 'En lærebok skrevet i dag forteller om en hendelse fra fortiden og bygger på brev og andre kilder fra den tiden. Hva slags kilde er læreboka, og hvorfor?', 'Læreboka er en sekundærkilde. Den er skrevet senere og bygger på andre kilder fra hendelsen.', array['Klassifiserer læreboka som en sekundærkilde.', 'Forklarer at den er skrevet senere og bygger på andre kilder.']::text[], 4),
  ('samfunnsfag-8:metoder-og-kilder', 's06', 'To personer beskriver planene om flere sitteplasser i skolegården. En elevrådsrepresentant er opptatt av at elevene skal ha steder å sitte, mens en vaktmester er opptatt av at skolegården skal være lett å holde ren. Forklar hvorfor beskrivelsene kan vektlegge ulike ting, og hva det forteller om kildenes perspektiver.', 'De ser saken fra ulike ståsteder og er opptatt av forskjellige ting. Elevrådsrepresentanten legger vekt på elevenes behov, mens vaktmesteren legger vekt på renhold.', array['Forklarer at personene har ulike ståsteder eller interesser.', 'Knytter det ulike fokuset til hva hver person er opptatt av.']::text[], 5),
  ('samfunnsfag-8:metoder-og-kilder', 's07', 'Du klikker ofte på innlegg som støtter én bestemt mening om en sak. Etter hvert viser en sosial medieapp deg mest innlegg med lignende meninger. Forklar hvordan algoritmen kan påvirke hva du får se, og hva slags utfordring dette kan skape.', 'Algoritmen kan bruke det du har klikket på før til å velge lignende innlegg. Da kan du havne i en filterboble og få et skjevt bilde fordi du møter få andre meninger.', array['Forklarer at algoritmen velger innhold ut fra tidligere klikk eller aktivitet.', 'Forklarer at du dermed kan møte få andre meninger eller få et skjevt bilde.']::text[], 6),
  ('samfunnsfag-8:metoder-og-kilder', 's08', 'En klasse har samlet inn mange svar med faste svaralternativer i en spørreundersøkelse. Forklar hvordan et digitalt verktøy kan hjelpe klassen med å analysere og presentere svarene.', 'Et digitalt verktøy kan hjelpe klassen med å telle og organisere svarene. Klassen kan vise resultatene i et diagram.', array['Forklarer at verktøyet kan hjelpe med å telle eller organisere svarene.', 'Nevner at resultatene kan presenteres med et diagram.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-8:identitet-og-fellesskap', 'samfunnsfag-8', 'identitet-og-fellesskap', 'Identitet, sosialisering og fellesskap', 'Hvordan identitet og selvbilde formes i familie, venneflokk og på nett, hva sosialisering og normer er, og hvordan du kan håndtere press og sette grenser.', array[15, 13]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-8:identitet-og-fellesskap', '## Hva er identitet?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-8:identitet-og-fellesskap', 'Identitet', 'Hvem du er og opplever deg som, og hvordan andre ser deg.', 0),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Selvbilde', 'Hvordan du ser på deg selv.', 1),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Sosialisering', 'Prosessen der vi lærer normer, verdier og ferdigheter for å fungere i samfunnet.', 2),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Primærsosialisering', 'Sosialisering i de første leveårene, mest i familien.', 3),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Sekundærsosialisering', 'Senere sosialisering i skole, fritid, arbeidsliv og medier.', 4),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Sosialiseringsagent', 'Noen som påvirker sosialiseringen vår, som foreldre, venner og medier.', 5),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Norm', 'Uskrevet regel for hvordan man bør oppføre seg.', 6),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Sanksjon', 'Reaksjon på atferd: negativ ved normbrudd, positiv som belønning.', 7),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Rolle', 'Forventninger knyttet til en posisjon, som elev, venn eller søsken.', 8),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Primærgruppe', 'Liten og nær gruppe, som familie og nære venner.', 9),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Sekundærgruppe', 'Større og mer formell gruppe, som en skoleklasse eller et idrettslag.', 10),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Gruppepress', 'Press til å gjøre som de andre i en gruppe.', 11),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Influenser', 'Person med mange følgere på sosiale medier som påvirker holdninger og kjøp.', 12),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Egne grenser', 'Hva du vil og ikke vil være med på. Du har rett til å få dem respektert.', 13),
  ('samfunnsfag-8:identitet-og-fellesskap', 'Mangfold', 'At mennesker er ulike i identitet, levesett og kultur.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-8:identitet-og-fellesskap', 'q01', 'flervalg', 'Hva er sosialisering?', array['Å være sosial på fest', 'Prosessen der vi lærer normer, verdier og ferdigheter', 'Å bruke sosiale medier', 'Å bli med i en forening']::text[], 1, 'Gjennom sosialisering lærer vi hvordan vi skal fungere sammen med andre.', true, true, 0),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q02', 'flervalg', 'Hvor skjer primærsosialiseringen først og fremst?', array['I familien', 'På jobben', 'På sosiale medier', 'I politiske partier']::text[], 0, 'I de første leveårene er familien den viktigste sosialiseringsagenten.', true, true, 1),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q03', 'flervalg', 'Hva er en norm?', array['En skrevet lov', 'En straff', 'En uskrevet regel for hvordan man bør oppføre seg', 'En type gruppe']::text[], 2, 'Normer er forventninger som ofte ikke står skrevet noe sted.', true, true, 2),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q04', 'flervalg', 'Hva er et eksempel på en positiv sanksjon?', array['Et surt blikk', 'Å bli utestengt', 'Å få en bot', 'Å få ros']::text[], 3, 'Positive sanksjoner belønner atferd som er ønsket.', true, true, 3),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q05', 'flervalg', 'Hva er en primærgruppe?', array['Et stort idrettslag', 'En liten og nær gruppe, som familien', 'Et politisk parti', 'Alle elevene på skolen']::text[], 1, 'Primærgrupper er små og preget av nære relasjoner.', true, true, 4),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q06', 'flervalg', 'Hvorfor kan bilder på sosiale medier påvirke selvbildet negativt?', array['Fordi de ofte viser redigerte og urealistiske idealer', 'Fordi de er for små', 'Fordi de alltid er ekte', 'Det gjør de aldri']::text[], 0, 'Når vi sammenligner oss med redigerte bilder, kan vi føle at vi ikke strekker til.', true, true, 5),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q07', 'flervalg', 'Hva er gruppepress?', array['Å være leder i en gruppe', 'Et lagspill', 'Press til å gjøre som de andre, selv om man ikke vil', 'Å lage en gruppe på nett']::text[], 2, 'Gruppepress kan få oss til å gjøre ting vi egentlig ikke ønsker.', true, true, 6),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q08', 'flervalg', 'Hva kan du gjøre hvis du opplever press eller uønskede hendelser?', array['Holde det for deg selv', 'Gi etter for å unngå konflikt', 'Slette alle kontoer', 'Si nei og snakke med noen du stoler på']::text[], 3, 'Det er lov å si nei, og det hjelper å få støtte fra en voksen eller venn.', true, true, 7),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q09', 'flervalg', 'Hva betyr det at identiteten ikke er fast?', array['At den endrer seg gjennom livet', 'At man ikke har noen identitet', 'At man bytter navn ofte', 'At andre bestemmer den']::text[], 0, 'Nye erfaringer, venner og interesser gjør at identiteten utvikler seg.', true, false, 8),
  ('samfunnsfag-8:identitet-og-fellesskap', 'q10', 'flervalg', 'Hva er en sosialiseringsagent?', array['En hemmelig agent', 'Noen som påvirker sosialiseringen vår, som foreldre og venner', 'En politiker', 'En type lov']::text[], 1, 'Foreldre, lærere, venner, trenere og medier er sosialiseringsagenter.', true, false, 9),
  ('samfunnsfag-8:identitet-og-fellesskap', 'm01', 'sant-usant', 'Medier kan være en sosialiseringsagent.', array['Sant', 'Usant']::text[], 0, 'TV, spill og sosiale medier påvirker normer og verdier.', false, true, 10),
  ('samfunnsfag-8:identitet-og-fellesskap', 'm02', 'sant-usant', 'Man kan bare ha én rolle om gangen i livet.', array['Sant', 'Usant']::text[], 1, 'Vi har mange roller samtidig, som elev, venn, søsken og lagkamerat.', false, true, 11),
  ('samfunnsfag-8:identitet-og-fellesskap', 'm03', 'sant-usant', 'Du har rett til å ombestemme deg selv om du har sagt ja tidligere.', array['Sant', 'Usant']::text[], 0, 'Grensene dine gjelder hele tiden, og du kan endre mening.', false, true, 12),
  ('samfunnsfag-8:identitet-og-fellesskap', 'm04', 'sant-usant', 'Mangfold gir bare utfordringer og ingen muligheter.', array['Sant', 'Usant']::text[], 1, 'Mangfold kan også gi nye perspektiver, ideer og et rikere fellesskap.', false, true, 13),
  ('samfunnsfag-8:identitet-og-fellesskap', 'm05', 'flervalg', 'Hvilken er en sekundærgruppe?', array['Familien', 'Bestevennen din', 'Et idrettslag', 'Søsknene dine']::text[], 2, 'Idrettslaget er en større og mer formell gruppe.', false, true, 14),
  ('samfunnsfag-8:identitet-og-fellesskap', 'm06', 'flervalg', 'Hva er selvfølelse?', array['Hvor godt du liker deg selv', 'Hvor mange venner du har', 'Hvor gammel du er', 'Hvor du bor']::text[], 0, 'Selvfølelsen handler om verdien du opplever at du har.', false, true, 15),
  ('samfunnsfag-8:identitet-og-fellesskap', 'm07', 'flervalg', 'Hva er et eksempel på en negativ sanksjon?', array['Et klapp på skulderen', 'En premie', 'Et smil', 'Å bli ledd av']::text[], 3, 'Negative sanksjoner er reaksjoner på brudd på normer.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-8:identitet-og-fellesskap', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-8:identitet-og-fellesskap', 's01', 'Hva er forskjellen på selvbilde og selvfølelse? Forklar hva hvert begrep handler om.', 'Selvbildet er hvordan du ser på deg selv. Selvfølelsen handler om hvor godt du liker deg selv.', array['Skiller mellom hvordan man ser på seg selv og hvor godt man liker seg selv.']::text[], 0),
  ('samfunnsfag-8:identitet-og-fellesskap', 's02', 'Et barn lærer språk og vaner i familien i de første leveårene. Senere lærer barnet også i skolen og på fritidsaktiviteter. Sammenlign primær- og sekundærsosialisering.', 'Primærsosialisering skjer i de første leveårene, først og fremst i familien, der barnet blant annet lærer språk og vaner. Sekundærsosialisering skjer senere, for eksempel i skolen og på fritidsaktiviteter.', array['Forklarer at primærsosialisering skjer tidlig og særlig i familien.', 'Forklarer at sekundærsosialisering skjer senere, for eksempel i skole eller fritid.']::text[], 1),
  ('samfunnsfag-8:identitet-og-fellesskap', 's03', 'En person er elev på skolen og venn når hen er sammen med venner. Forklar hvordan forventningene til personen kan være forskjellige i disse to rollene.', 'Som elev forventes personen å følge forventningene som hører til skolen. Som venn kan andre forventninger gjelde, for eksempel hvordan man er sammen med venner.', array['Viser at roller er knyttet til ulike forventninger.', 'Gir en relevant forskjell mellom forventningene til en elev og en venn.']::text[], 2),
  ('samfunnsfag-8:identitet-og-fellesskap', 's04', 'Familie og nære venner er små, nære grupper. En skoleklasse eller et idrettslag er ofte større og mer formelle. Sammenlign primærgrupper og sekundærgrupper.', 'Primærgrupper er små og nære, som familie og nære venner. Sekundærgrupper er større og mer formelle, som en skoleklasse eller et idrettslag.', array['Forklarer at primærgrupper er små og nære.', 'Forklarer at sekundærgrupper er større og mer formelle.']::text[], 3),
  ('samfunnsfag-8:identitet-og-fellesskap', 's05', 'I en klasse avbryter flere elever den som snakker. Beskriv en norm som passer i situasjonen, og gi et eksempel på en reaksjon hvis normen brytes.', 'En norm kan være at man lar andre snakke ferdig. Hvis noen stadig avbryter, kan andre reagere med et surt blikk eller utestenge personen.', array['Beskriver en passende uskrevne regel om å la andre snakke ferdig.', 'Gir en mulig negativ sanksjon som reaksjon på normbruddet.']::text[], 4),
  ('samfunnsfag-8:identitet-og-fellesskap', 's06', 'En influenser viser fram et produkt på sosiale medier. Forklar hvordan influensere kan påvirke hva folk kjøper, og hvordan idealer for utseende eller livsstil kan brukes i reklame.', 'En influenser kan påvirke følgernes holdninger og kjøp. Reklame kan bruke idealer for utseende eller livsstil, selv om idealene ofte er redigerte og urealistiske, for å selge produkter.', array['Forklarer at influensere kan påvirke holdninger eller kjøp.', 'Knytter idealer for utseende eller livsstil til hvordan reklame forsøker å selge produkter.']::text[], 5),
  ('samfunnsfag-8:identitet-og-fellesskap', 's07', 'En venn vil at du skal dele et bilde på sosiale medier, men du ønsker ikke å dele det. Forklar hvordan du kan bruke egne grenser i situasjonen, og nevn én måte å få støtte på.', 'Jeg kan si nei, fordi jeg har rett til å bestemme hva jeg vil dele, og vennen bør respektere grensen min. Jeg kan snakke med en person jeg stoler på, for eksempel en forelder eller lærer.', array['Forklarer at personen kan si nei og bestemme hva hen vil dele.', 'Nevner en relevant person hen kan snakke med for å få støtte.']::text[], 6),
  ('samfunnsfag-8:identitet-og-fellesskap', 's08', 'Mennesker kan ha ulike identiteter, levesett og kulturuttrykk. Forklar én måte mangfold kan berike et fellesskap på, én utfordring det kan føre til, og hva som kan gjøre det lettere å leve sammen.', 'Mangfold kan gi fellesskapet nye perspektiver, men forskjeller kan også føre til misforståelser eller fordommer. Respekt og nysgjerrighet på andre gjør det lettere å leve sammen.', array['Forklarer en positiv side ved mangfold, som nye perspektiver.', 'Nevner en utfordring, som misforståelser eller fordommer, og knytter respekt eller nysgjerrighet til å leve sammen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-8:demokrati-og-politikk', 'samfunnsfag-8', 'demokrati-og-politikk', 'Demokrati og det politiske systemet', 'Hva demokrati er, hvordan makten er delt mellom Stortinget, regjeringen og domstolene, hvordan valg og partier fungerer, og hvilke aktører som har makt i samfunnet.', array[19, 16]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-8:demokrati-og-politikk', '## Hva er demokrati?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-8:demokrati-og-politikk', 'Demokrati', 'Folkestyre, der innbyggerne velger hvem som skal styre.', 0),
  ('samfunnsfag-8:demokrati-og-politikk', 'Representativt demokrati', 'Folket velger representanter som tar beslutninger på deres vegne.', 1),
  ('samfunnsfag-8:demokrati-og-politikk', 'Direkte demokrati', 'Folket stemmer selv over enkeltsaker, for eksempel i en folkeavstemning.', 2),
  ('samfunnsfag-8:demokrati-og-politikk', 'Maktfordeling', 'Makten er delt mellom lovgivende, utøvende og dømmende makt.', 3),
  ('samfunnsfag-8:demokrati-og-politikk', 'Stortinget', 'Den lovgivende makten med 169 representanter. Vedtar lover og statsbudsjett.', 4),
  ('samfunnsfag-8:demokrati-og-politikk', 'Regjeringen', 'Den utøvende makten, ledet av statsministeren.', 5),
  ('samfunnsfag-8:demokrati-og-politikk', 'Domstolene', 'Den dømmende makten, som avgjør saker etter lovene.', 6),
  ('samfunnsfag-8:demokrati-og-politikk', 'Grunnloven', 'Norges øverste lov, vedtatt i 1814.', 7),
  ('samfunnsfag-8:demokrati-og-politikk', 'Konstitusjonelt monarki', 'Kongen er statsoverhode, men makten er bundet av Grunnloven.', 8),
  ('samfunnsfag-8:demokrati-og-politikk', 'Parlamentarisme', 'Regjeringen må ha tillit fra Stortinget. Innført i Norge i 1884.', 9),
  ('samfunnsfag-8:demokrati-og-politikk', 'Mistillit', 'Når et flertall på Stortinget vedtar at regjeringen må gå av.', 10),
  ('samfunnsfag-8:demokrati-og-politikk', 'Stemmerett', 'Retten til å stemme ved valg, fra året du fyller 18.', 11),
  ('samfunnsfag-8:demokrati-og-politikk', 'Politisk parti', 'Organisasjon av folk med like verdier som stiller til valg.', 12),
  ('samfunnsfag-8:demokrati-og-politikk', 'Interesseorganisasjon', 'Organisasjon som prøver å påvirke politikken i saker medlemmene er opptatt av.', 13),
  ('samfunnsfag-8:demokrati-og-politikk', 'Den fjerde statsmakt', 'Mediene, som setter dagsorden og kontrollerer makthaverne.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-8:demokrati-og-politikk', 'q01', 'flervalg', 'Hva betyr demokrati?', array['Styre av de rike', 'Folkestyre', 'Styre av kongen', 'Styre av militæret']::text[], 1, 'Ordet kommer fra gresk og betyr at folket styrer.', true, true, 0),
  ('samfunnsfag-8:demokrati-og-politikk', 'q02', 'flervalg', 'Hvilken statsmakt vedtar lovene i Norge?', array['Regjeringen', 'Domstolene', 'Kongen', 'Stortinget']::text[], 3, 'Stortinget er den lovgivende makten.', true, true, 1),
  ('samfunnsfag-8:demokrati-og-politikk', 'q03', 'flervalg', 'Hvorfor er makten delt i tre?', array['For å hindre at noen får for mye makt', 'For å spare penger', 'Fordi det var enklest i 1814', 'For at kongen skal bestemme mest']::text[], 0, 'Statsmaktene kontrollerer hverandre, slik at makten ikke samles på én hånd.', true, true, 2),
  ('samfunnsfag-8:demokrati-og-politikk', 'q04', 'flervalg', 'Hva betyr parlamentarisme?', array['At kongen velger regjeringen fritt', 'At det er valg hvert år', 'At regjeringen må ha tillit fra Stortinget', 'At domstolene lager lover']::text[], 2, 'Mister regjeringen tilliten fra et flertall på Stortinget, må den gå av.', true, true, 3),
  ('samfunnsfag-8:demokrati-og-politikk', 'q05', 'flervalg', 'Hvor ofte er det stortingsvalg?', array['Hvert år', 'Hvert andre år', 'Hvert fjerde år', 'Hvert sjette år']::text[], 2, 'Kommunestyre- og fylkestingsvalg holdes to år etter stortingsvalget.', true, true, 4),
  ('samfunnsfag-8:demokrati-og-politikk', 'q06', 'flervalg', 'Hva er et representativt demokrati?', array['Folket velger representanter som tar beslutninger', 'Folket stemmer over alle saker', 'Én person bestemmer alt', 'Bare representanter har stemmerett']::text[], 0, 'Norge er et representativt demokrati der vi velger politikere til Stortinget og kommunestyrene.', true, true, 5),
  ('samfunnsfag-8:demokrati-og-politikk', 'q07', 'flervalg', 'Hvorfor kalles mediene den fjerde statsmakt?', array['Fordi de vedtar lover', 'Fordi de dømmer i rettssaker', 'Fordi de eies av staten', 'Fordi de setter dagsorden og kontrollerer makthaverne']::text[], 3, 'Mediene har stor påvirkning, selv om de ikke er en formell statsmakt.', true, true, 6),
  ('samfunnsfag-8:demokrati-og-politikk', 'q08', 'flervalg', 'Hva gjør en interesseorganisasjon?', array['Dømmer i saker', 'Prøver å påvirke politikken i saker medlemmene er opptatt av', 'Leder regjeringen', 'Teller stemmer ved valg']::text[], 1, 'Fagforeninger og miljøorganisasjoner er eksempler på interesseorganisasjoner.', true, true, 7),
  ('samfunnsfag-8:demokrati-og-politikk', 'q09', 'flervalg', 'Hvem er statsoverhode i Norge?', array['Kongen', 'Statsministeren', 'Stortingspresidenten', 'Lederen av Høyesterett']::text[], 0, 'Kongen er statsoverhode, men den politiske makten ligger hos Stortinget og regjeringen.', true, false, 8),
  ('samfunnsfag-8:demokrati-og-politikk', 'q10', 'flervalg', 'Hvordan kan en 14-åring påvirke politikken?', array['Ved å stemme ved stortingsvalget', 'Ved å bli statsråd', 'Det er ikke mulig', 'Gjennom elevråd, ungdomsråd og organisasjoner']::text[], 3, 'Ungdom kan påvirke på mange måter før de får stemmerett.', true, false, 9),
  ('samfunnsfag-8:demokrati-og-politikk', 'm01', 'sant-usant', 'Stortinget har 169 representanter.', array['Sant', 'Usant']::text[], 0, 'Representantene velges fra valgdistrikter over hele landet.', false, true, 10),
  ('samfunnsfag-8:demokrati-og-politikk', 'm02', 'sant-usant', 'Kongen har stor politisk makt i Norge i dag.', array['Sant', 'Usant']::text[], 1, 'Kongen er statsoverhode, men har en symbolsk og samlende rolle.', false, true, 11),
  ('samfunnsfag-8:demokrati-og-politikk', 'm03', 'sant-usant', 'Kommunestyre- og fylkestingsvalg holdes to år etter stortingsvalget.', array['Sant', 'Usant']::text[], 0, 'Derfor er det et valg i Norge annethvert år.', false, true, 12),
  ('samfunnsfag-8:demokrati-og-politikk', 'm04', 'sant-usant', 'I et demokrati trenger flertallet ikke å ta hensyn til mindretallet.', array['Sant', 'Usant']::text[], 1, 'Respekt for mindretallets rettigheter er et viktig kjennetegn ved demokrati.', false, true, 13),
  ('samfunnsfag-8:demokrati-og-politikk', 'm05', 'flervalg', 'Hvilken statsmakt er domstolene?', array['Den lovgivende', 'Den utøvende', 'Den dømmende', 'Den fjerde']::text[], 2, 'Domstolene avgjør saker etter lovene Stortinget har vedtatt.', false, true, 14),
  ('samfunnsfag-8:demokrati-og-politikk', 'm06', 'flervalg', 'Hva skjer hvis et flertall på Stortinget vedtar mistillit mot regjeringen?', array['Regjeringen må gå av', 'Kongen må abdisere', 'Stortinget oppløses', 'Ingenting']::text[], 0, 'Dette følger av parlamentarismen.', false, true, 15),
  ('samfunnsfag-8:demokrati-og-politikk', 'm07', 'flervalg', 'Hva er en folkeavstemning?', array['Et møte i Stortinget', 'At folket stemmer direkte over en enkeltsak', 'En meningsmåling', 'Et partimøte']::text[], 1, 'Norge har for eksempel hatt folkeavstemninger om EU-medlemskap i 1972 og 1994.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-8:demokrati-og-politikk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-8:demokrati-og-politikk', 's01', 'I ett tilfelle stemmer innbyggerne selv over en enkeltsak. I et annet velger de representanter som tar beslutninger på deres vegne. Forklar forskjellen mellom direkte og representativt demokrati.', 'I et direkte demokrati stemmer innbyggerne selv over enkeltsaker. I et representativt demokrati velger de representanter som tar beslutninger for dem.', array['Forklarer at innbyggerne selv stemmer over saker i direkte demokrati.', 'Forklarer at folket velger representanter i representativt demokrati.']::text[], 0),
  ('samfunnsfag-8:demokrati-og-politikk', 's02', 'Et flertall på Stortinget vedtar mistillit mot regjeringen. Hva må regjeringen gjøre, og hvordan henger dette sammen med parlamentarisme?', 'Regjeringen må gå av. Det henger sammen med parlamentarisme fordi regjeringen må ha tillit fra Stortinget for å kunne styre.', array['Sier at regjeringen må gå av etter et mistillitsvedtak.', 'Knytter dette til at regjeringen må ha Stortingets tillit.']::text[], 1),
  ('samfunnsfag-8:demokrati-og-politikk', 's03', 'Sammenlign synet på økonomi på høyre- og venstresiden i politikken.', 'Venstresiden ønsker gjerne mer økonomisk likhet og en større offentlig sektor. Høyresiden legger mer vekt på private løsninger og lavere skatter.', array['Beskriver venstresidens vekt på økonomisk likhet eller større offentlig sektor.', 'Beskriver høyresidens vekt på private løsninger eller lavere skatter.']::text[], 2),
  ('samfunnsfag-8:demokrati-og-politikk', 's04', 'Norge er et konstitusjonelt monarki, og kongen er statsoverhode. Hva betyr dette for kongens politiske makt?', 'Kongen er Norges statsoverhode, men har ingen politisk makt. Makten er bundet av Grunnloven.', array['Forklarer at kongen er statsoverhode.', 'Forklarer at kongen ikke har politisk makt, eller at makten er bundet av Grunnloven.']::text[], 3),
  ('samfunnsfag-8:demokrati-og-politikk', 's05', 'Lea fyller 18 år i løpet av valgåret. Hva betyr aldersregelen for stemmeretten hennes?', 'Hun har stemmerett ved valget fordi hun fyller 18 år i løpet av valgåret.', array['Sier at Lea har stemmerett.', 'Begrunner svaret med at hun fyller 18 år i løpet av valgåret.']::text[], 4),
  ('samfunnsfag-8:demokrati-og-politikk', 's06', 'Et land holder valg, men forbyr innbyggerne å kritisere lederne og begrenser frie medier. Forklar hvorfor valg alene ikke er nok for at landet skal være et fullt demokrati. Bruk to kjennetegn på demokrati i svaret.', 'Demokrati krever også blant annet ytringsfrihet og frie medier. Når innbyggerne ikke kan kritisere lederne og mediene ikke er frie, mangler landet viktige kjennetegn på demokrati.', array['Nevner ytringsfrihet eller muligheten til å kritisere makthaverne.', 'Nevner frie medier eller et annet relevant demokratisk kjennetegn som mangler.']::text[], 5),
  ('samfunnsfag-8:demokrati-og-politikk', 's07', 'En influenser støtter et politisk forslag i sosiale medier. Hva bør du undersøke før du vurderer utspillet, og hvorfor?', 'Du bør undersøke hvem som står bak utspillet, og hvilke interesser influenseren har. Det kan hjelpe deg med å vurdere hvorfor personen støtter forslaget.', array['Sier at man bør undersøke hvem som står bak utspillet.', 'Sier at man bør undersøke hvilke interesser personen har.']::text[], 6),
  ('samfunnsfag-8:demokrati-og-politikk', 's08', 'En ny lov skal vedtas, et politisk vedtak skal settes ut i livet, og en sak skal avgjøres etter lovene. Hvilken oppgave har Stortinget, regjeringen og domstolene i disse situasjonene?', 'Stortinget vedtar lover, regjeringen setter vedtak ut i livet, og domstolene avgjør saker etter lovene.', array['Knytter Stortinget til å vedta lover.', 'Knytter regjeringen til å sette vedtak ut i livet.', 'Knytter domstolene til å avgjøre saker etter lovene.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-8:lover-og-regler', 'samfunnsfag-8', 'lover-og-regler', 'Lover, regler og normer', 'Forskjellen på normer, regler og lover, hvordan rettsstaten fungerer, hvilke straffer som finnes, og hvilke konsekvenser lovbrudd kan få for den enkelte og for samfunnet.', array[18]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-8:lover-og-regler', '## Normer, regler og lover
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-8:lover-og-regler', 'Norm', 'Uskreven regel for hvordan vi bør oppføre oss.', 0),
  ('samfunnsfag-8:lover-og-regler', 'Regel', 'Skreven bestemmelse som gjelder et bestemt sted eller en aktivitet.', 1),
  ('samfunnsfag-8:lover-og-regler', 'Lov', 'Regel vedtatt av Stortinget som gjelder alle i landet.', 2),
  ('samfunnsfag-8:lover-og-regler', 'Straffeloven', 'Loven som sier hva som er straffbart, og hvilke straffer som kan gis.', 3),
  ('samfunnsfag-8:lover-og-regler', 'Rettsstat', 'Stat der alle er like for loven og saker avgjøres av uavhengige domstoler.', 4),
  ('samfunnsfag-8:lover-og-regler', 'Uskyldspresumpsjonen', 'Du er uskyldig til det motsatte er bevist.', 5),
  ('samfunnsfag-8:lover-og-regler', 'Domstolenes tre nivåer', 'Tingrett, lagmannsrett og Høyesterett.', 6),
  ('samfunnsfag-8:lover-og-regler', 'Kriminell lavalder', 'Alderen man kan straffes fra. I Norge er den 15 år.', 7),
  ('samfunnsfag-8:lover-og-regler', 'Samfunnsstraff', 'Straff der den dømte gjør samfunnsnyttig arbeid i stedet for å sitte i fengsel.', 8),
  ('samfunnsfag-8:lover-og-regler', 'Ungdomsstraff', 'Straffereaksjon for lovbrytere mellom 15 og 18 år med tett oppfølging.', 9),
  ('samfunnsfag-8:lover-og-regler', 'Konfliktråd', 'Tilbud der gjerningsperson og offer møtes for å løse saken.', 10),
  ('samfunnsfag-8:lover-og-regler', 'Allmennprevensjon', 'Straff skal avskrekke andre fra å begå lovbrudd.', 11),
  ('samfunnsfag-8:lover-og-regler', 'Individualprevensjon', 'Straff skal hindre at den dømte gjør det igjen.', 12),
  ('samfunnsfag-8:lover-og-regler', 'Politiattest', 'Dokument som viser om en person har begått visse lovbrudd. Kreves for noen jobber.', 13),
  ('samfunnsfag-8:lover-og-regler', 'Sosial sanksjon', 'Reaksjon fra andre på normbrudd, som utestenging.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-8:lover-og-regler', 'q01', 'flervalg', 'Hva er forskjellen på en norm og en lov?', array['Normer er uskrevne, lover er vedtatt av Stortinget', 'Det er ingen forskjell', 'Normer gjelder bare voksne', 'Lover er uskrevne']::text[], 0, 'Bare lovbrudd kan straffes av staten.', true, true, 0),
  ('samfunnsfag-8:lover-og-regler', 'q02', 'flervalg', 'Hva er den kriminelle lavalderen i Norge?', array['12 år', '15 år', '16 år', '18 år']::text[], 1, 'Barn under 15 år kan ikke straffes, men barnevernet kan gripe inn.', true, true, 1),
  ('samfunnsfag-8:lover-og-regler', 'q03', 'flervalg', 'Hva er konfliktrådet?', array['En domstol for voksne', 'Et fengsel for unge', 'Et tilbud der partene i en sak møtes for å finne en løsning', 'En komité på Stortinget']::text[], 2, 'I konfliktrådet kan gjerningspersonen gjøre opp for seg overfor den som er rammet.', true, true, 2),
  ('samfunnsfag-8:lover-og-regler', 'q04', 'flervalg', 'Hva betyr allmennprevensjon?', array['At straff skal gjøre offeret glad', 'At alle får samme straff', 'At straff hindrer den dømte i å gjøre det igjen', 'At straff skal avskrekke andre fra å begå lovbrudd']::text[], 3, 'Tanken er at synlige straffer gjør at færre bryter loven.', true, true, 3),
  ('samfunnsfag-8:lover-og-regler', 'q05', 'flervalg', 'Hva betyr det at alle er like for loven?', array['At alle får samme lønn', 'At lovene gjelder alle, uansett hvem de er', 'At alle er like sterke', 'At alle må være enige']::text[], 1, 'Også politikere, rike og kjente må følge loven.', true, true, 4),
  ('samfunnsfag-8:lover-og-regler', 'q06', 'flervalg', 'Hvilken domstol er den høyeste i Norge?', array['Høyesterett', 'Tingretten', 'Lagmannsretten', 'Konfliktrådet']::text[], 0, 'Høyesterett er siste instans, og dommene der kan ikke ankes.', true, true, 5),
  ('samfunnsfag-8:lover-og-regler', 'q07', 'flervalg', 'Hvorfor kan et lovbrudd i ungdommen få konsekvenser mange år senere?', array['Fordi det kan stå på politiattesten', 'Fordi man mister stemmeretten for alltid', 'Fordi man må flytte fra kommunen', 'Det kan det ikke']::text[], 0, 'Politiattest kreves blant annet for jobber med barn og unge.', true, false, 6),
  ('samfunnsfag-8:lover-og-regler', 'q08', 'flervalg', 'Hva er et eksempel på en regel som ikke er en lov?', array['Forbudet mot tyveri', 'Fartsgrensen', 'Skolens ordensreglement', 'Skatteplikten']::text[], 2, 'Ordensreglementet gjelder bare på skolen.', true, true, 7),
  ('samfunnsfag-8:lover-og-regler', 'q09', 'flervalg', 'Hvilket prinsipp hører til en rettsstat?', array['Politiet kan straffe uten rettssak', 'Man er uskyldig til det motsatte er bevist', 'Regjeringen dømmer i straffesaker', 'Lover gjelder bare for noen']::text[], 1, 'Det er påtalemyndigheten som må bevise skyld, ikke den tiltalte som må bevise uskyld.', true, true, 8),
  ('samfunnsfag-8:lover-og-regler', 'q10', 'flervalg', 'Hva er en konsekvens av kriminalitet for samfunnet?', array['Større trygghet', 'Lavere kostnader', 'Mer tillit', 'Utrygghet og store kostnader']::text[], 3, 'Kriminalitet koster samfunnet penger og svekker tilliten mellom folk.', true, false, 9),
  ('samfunnsfag-8:lover-og-regler', 'm01', 'sant-usant', 'Barn under 15 år kan ikke straffes i Norge.', array['Sant', 'Usant']::text[], 0, 'Barnevernet kan likevel gripe inn, og man kan måtte betale erstatning.', false, true, 10),
  ('samfunnsfag-8:lover-og-regler', 'm02', 'sant-usant', 'Grunnloven er den øverste loven i Norge.', array['Sant', 'Usant']::text[], 0, 'Andre lover kan ikke være i strid med Grunnloven.', false, true, 11),
  ('samfunnsfag-8:lover-og-regler', 'm03', 'sant-usant', 'Brudd på normer kan straffes med fengsel.', array['Sant', 'Usant']::text[], 1, 'Normbrudd gir sosiale sanksjoner. Bare lovbrudd kan straffes av staten.', false, true, 12),
  ('samfunnsfag-8:lover-og-regler', 'm04', 'sant-usant', 'Det er lov å dele nakenbilder av andre under 18 år hvis du selv er under 18.', array['Sant', 'Usant']::text[], 1, 'Deling av slike bilder er straffbart uansett alderen til den som deler.', false, true, 13),
  ('samfunnsfag-8:lover-og-regler', 'm05', 'flervalg', 'Hvem etterforsker lovbrudd?', array['Domstolene', 'Politiet', 'Stortinget', 'Konfliktrådet']::text[], 1, 'Politiet samler bevis, og påtalemyndigheten avgjør om det blir tiltale.', false, true, 14),
  ('samfunnsfag-8:lover-og-regler', 'm06', 'flervalg', 'Hva er målet med rehabilitering?', array['Å gjøre straffen hardere', 'Å skremme andre', 'Å hjelpe den dømte tilbake til et liv uten kriminalitet', 'Å gi offeret erstatning']::text[], 2, 'Norsk kriminalomsorg legger stor vekt på utdanning og arbeid under soning.', false, true, 15),
  ('samfunnsfag-8:lover-og-regler', 'm07', 'flervalg', 'Hvilken straffereaksjon er laget spesielt for lovbrytere mellom 15 og 18 år?', array['Ungdomsstraff', 'Forvaring', 'Livstidsfengsel', 'Bot']::text[], 0, 'Ungdomsstraff gjennomføres med tett oppfølging, ofte gjennom konfliktrådet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-8:lover-og-regler', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-8:lover-og-regler', 's01', 'Nevn to grunner til at samfunnet har lover, og forklar kort hvordan de kan bidra til et tryggere eller mer rettferdig samfunn.', 'Lover skal blant annet beskytte liv, helse, eiendom og rettigheter. De kan også skape trygghet og bidra til at konflikter løses rettferdig.', array['Nevner minst to formål med lover, for eksempel å beskytte rettigheter eller løse konflikter rettferdig.', 'Forklarer hvordan minst ett av formålene kan bidra til trygghet eller rettferdighet.']::text[], 0),
  ('samfunnsfag-8:lover-og-regler', 's02', 'En person blir mistenkt for et lovbrudd. Forklar hva politiet, påtalemyndigheten og domstolene har ansvar for i en slik sak.', 'Politiet etterforsker lovbruddet. Påtalemyndigheten bestemmer om personen skal tiltales, og domstolene avgjør saken.', array['Forklarer at politiet etterforsker lovbrudd.', 'Forklarer at påtalemyndigheten avgjør om noen skal tiltales, og at domstolene avgjør saken.']::text[], 1),
  ('samfunnsfag-8:lover-og-regler', 's03', 'En 14-åring gjør noe som er straffbart. Hva kan skje med 14-åringen, og hva kan ikke skje etter reglene om kriminell lavalder?', 'En 14-åring kan ikke straffes, fordi den kriminelle lavalderen er 15 år. Barnevernet kan likevel gripe inn, og 14-åringen kan måtte betale erstatning.', array['Får fram at en person under 15 år ikke kan straffes.', 'Nevner en mulig reaksjon eller følge, som at barnevernet kan gripe inn eller at personen kan måtte betale erstatning.']::text[], 2),
  ('samfunnsfag-8:lover-og-regler', 's04', 'Hva er samfunnsstraff, og hvordan skiller den seg fra fengsel?', 'Samfunnsstraff betyr at den dømte gjør samfunnsnyttig arbeid i stedet for å sitte i fengsel.', array['Forklarer at samfunnsstraff innebærer samfunnsnyttig arbeid i stedet for fengsel.']::text[], 3),
  ('samfunnsfag-8:lover-og-regler', 's05', 'Forklar forskjellen på individualprevensjon og rehabilitering som formål med straff.', 'Individualprevensjon skal hindre at den dømte begår nye lovbrudd. Rehabilitering skal hjelpe den dømte tilbake til et liv uten kriminalitet.', array['Forklarer at individualprevensjon skal hindre at den dømte gjør nye lovbrudd.', 'Forklarer at rehabilitering handler om å hjelpe den dømte til et liv uten kriminalitet.']::text[], 4),
  ('samfunnsfag-8:lover-og-regler', 's06', 'En 16-åring deler et nakenbilde av en person som er under 18 år. Forklar hvorfor det kan være straffbart selv om den som deler, også er under 18.', 'Deling av nakenbilder av personer under 18 år er straffbart. Det gjelder også når den som deler bildet, selv er under 18.', array['Får fram at deling av nakenbilder av personer under 18 år er straffbart.', 'Får fram at regelen også gjelder den som deler, selv om personen er under 18.']::text[], 5),
  ('samfunnsfag-8:lover-og-regler', 's07', 'En person sniker i køen, selv om det er en uskrevne regel at man venter på tur. Nevn en reaksjon personen kan få, og forklar hvorfor det er en sosial sanksjon.', 'Andre kan for eksempel utestenge personen eller gi personen et dårlig rykte. Det er en sosial sanksjon fordi reaksjonen kommer fra andre mennesker, ikke som straff fra staten.', array['Nevner en mulig reaksjon fra andre, som utestenging eller dårlig rykte.', 'Forklarer at reaksjonen kommer fra andre og ikke er straff fra staten.']::text[], 6),
  ('samfunnsfag-8:lover-og-regler', 's08', 'Normer kan endre seg, og noen ganger blir de til lover. Forklar denne sammenhengen med forbudet mot røyking på serveringssteder som eksempel.', 'Normer kan endre seg over tid, og noen ganger blir en norm gjort om til en lov. Forbudet mot røyking på serveringssteder er et eksempel på en slik lov.', array['Forklarer at normer kan endre seg og noen ganger bli til lover.', 'Bruker forbudet mot røyking på serveringssteder som eksempel.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-8:okonomi-og-forbruk', 'samfunnsfag-8', 'okonomi-og-forbruk', 'Arbeid, økonomi og forbruk', 'Hvordan arbeid, inntekt og forbruk påvirker den personlige økonomien, hvordan du lager et budsjett, hvilke rettigheter du har som forbruker, og forskjellen på levestandard og livskvalitet.', array[12]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-8:okonomi-og-forbruk', '## Arbeid og inntekt
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-8:okonomi-og-forbruk', 'Inntekt', 'Penger du får, for eksempel lønn, pensjon eller studiestøtte.', 0),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Bruttolønn', 'Lønn før skatt er trukket.', 1),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Nettolønn', 'Lønn etter at skatten er trukket, altså det du får utbetalt.', 2),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Skatt', 'Penger vi betaler til fellesskapet, som finansierer skoler, sykehus og veier.', 3),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Budsjett', 'Oversikt over forventede inntekter og utgifter.', 4),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Faste utgifter', 'Utgifter som kommer jevnlig, som husleie og mobilabonnement.', 5),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Variable utgifter', 'Utgifter som varierer, som mat, klær og fritid.', 6),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Buffer', 'Sparepenger til uforutsette utgifter.', 7),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Rente', 'Prisen du betaler for å låne penger.', 8),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Inkasso', 'Innkreving av ubetalte regninger, med ekstra gebyrer.', 9),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Inflasjon', 'At prisene stiger, slik at pengene er mindre verdt.', 10),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Angrerett', 'Rett til å angre et kjøp på nett innen 14 dager.', 11),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Reklamasjon', 'Å klage på en vare med feil, innen to eller fem år.', 12),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Levestandard', 'Materielle forhold, som inntekt, bolig og forbruk.', 13),
  ('samfunnsfag-8:okonomi-og-forbruk', 'Livskvalitet', 'Hvordan vi har det, som helse, relasjoner og trygghet.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-8:okonomi-og-forbruk', 'q01', 'flervalg', 'Hva er nettolønn?', array['Lønn før skatt', 'Lønn etter at skatten er trukket', 'Lønn for overtid', 'Lønn fra nettbutikker']::text[], 1, 'Nettolønnen er det som faktisk kommer inn på kontoen.', true, true, 0),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q02', 'flervalg', 'Hva er et budsjett?', array['En oversikt over forventede inntekter og utgifter', 'Et lån i banken', 'En type skatt', 'En kvittering']::text[], 0, 'Budsjettet hjelper deg å planlegge hva du har råd til.', true, true, 1),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q03', 'flervalg', 'Hvilken er en fast utgift?', array['Kinobillett', 'Godteri', 'Husleie', 'Ny jakke']::text[], 2, 'Husleie betales jevnlig og er omtrent like stor hver måned.', true, true, 2),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q04', 'flervalg', 'Hvorfor bør man være forsiktig med forbrukslån?', array['Fordi de er rentefrie', 'Fordi de bare gis til barn', 'Fordi de må betales tilbake samme dag', 'Fordi de ofte har høy rente']::text[], 3, 'Høy rente gjør at lånet kan bli svært dyrt over tid.', true, true, 3),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q05', 'flervalg', 'Hvor lenge har du som hovedregel angrerett når du handler på nett?', array['3 dager', '7 dager', '14 dager', '30 dager']::text[], 2, 'Angrefristen er 14 dager fra du mottok varen.', true, true, 4),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q06', 'flervalg', 'Hva er forskjellen på levestandard og livskvalitet?', array['Levestandard gjelder materielle forhold, livskvalitet gjelder hvordan vi har det', 'Det er det samme', 'Livskvalitet måles bare i penger', 'Levestandard handler om vennskap']::text[], 0, 'Man kan ha høy levestandard og likevel lav livskvalitet, og omvendt.', true, true, 5),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q07', 'flervalg', 'Hva må reklame på sosiale medier være?', array['Morsom', 'Tydelig merket som reklame', 'Gratis', 'Skrevet på engelsk']::text[], 1, 'Skjult reklame er ulovlig fordi den lurer forbrukerne.', true, true, 6),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q08', 'flervalg', 'Hva går skattepengene blant annet til?', array['Private feriereiser', 'Lønn til influensere', 'Reklame for butikker', 'Skoler, sykehus og veier']::text[], 3, 'Skatten finansierer fellesgoder som alle kan bruke.', true, true, 7),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q09', 'flervalg', 'Hva er en buffer i personlig økonomi?', array['Sparepenger til uforutsette utgifter', 'En type kredittkort', 'Et lån', 'En skatt']::text[], 0, 'Med en buffer slipper du å låne hvis noe uventet skjer.', true, false, 8),
  ('samfunnsfag-8:okonomi-og-forbruk', 'q10', 'flervalg', 'Hva kan du gjøre som 15-åring uten samtykke fra foresatte?', array['Ta opp et forbrukslån', 'Kjøpe bil på avbetaling', 'Bruke penger du har tjent selv', 'Inngå en boliglånsavtale']::text[], 2, 'Umyndige kan råde over penger de har tjent ved eget arbeid.', true, false, 9),
  ('samfunnsfag-8:okonomi-og-forbruk', 'm01', 'sant-usant', 'Arbeid gir bare penger og ingen andre goder.', array['Sant', 'Usant']::text[], 1, 'Arbeid gir også fellesskap, mestring og mening.', false, true, 10),
  ('samfunnsfag-8:okonomi-og-forbruk', 'm02', 'sant-usant', 'Når prisene stiger, får du mindre for de samme pengene.', array['Sant', 'Usant']::text[], 0, 'Dette kalles inflasjon.', false, true, 11),
  ('samfunnsfag-8:okonomi-og-forbruk', 'm03', 'sant-usant', 'Skjult reklame er lov på sosiale medier.', array['Sant', 'Usant']::text[], 1, 'Reklame skal være tydelig merket, også hos influensere.', false, true, 12),
  ('samfunnsfag-8:okonomi-og-forbruk', 'm04', 'sant-usant', 'Høyere inntekt betyr mest for dem som har lite fra før.', array['Sant', 'Usant']::text[], 0, 'Når grunnbehovene er dekket, blir andre ting viktigere for livskvaliteten.', false, true, 13),
  ('samfunnsfag-8:okonomi-og-forbruk', 'm05', 'flervalg', 'Hva er reklamasjon?', array['Å klage på en vare med feil eller mangel', 'Å returnere en vare du angrer på', 'Å lage reklame', 'Å betale med kort']::text[], 0, 'Reklamasjonsfristen er to år, eller fem år for ting som skal vare lenge.', false, true, 14),
  ('samfunnsfag-8:okonomi-og-forbruk', 'm06', 'flervalg', 'Hva kan skje hvis du ikke betaler en regning?', array['Regningen forsvinner', 'Du får penger tilbake', 'Beløpet blir mindre', 'Saken kan gå til inkasso med ekstra gebyrer']::text[], 3, 'Ubetalte regninger blir dyrere og kan gi betalingsanmerkning.', false, true, 15),
  ('samfunnsfag-8:okonomi-og-forbruk', 'm07', 'flervalg', 'Hva er et eksempel på bærekraftig forbruk?', array['Å kjøpe nye klær hver uke', 'Å reparere og kjøpe brukt', 'Å kaste ting som har gått i stykker', 'Å handle mest mulig på salg']::text[], 1, 'Å bruke ting lenger sparer både penger og ressurser.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-8:okonomi-og-forbruk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-8:okonomi-og-forbruk', 's01', 'En person får både lønn fra jobb og pensjon. Forklar hvorfor begge deler regnes som inntekt, og hva inntekt betyr.', 'Inntekt er penger man får. Lønn og pensjon er begge inntekt, selv om de kommer fra ulike kilder.', array['Forklarer at inntekt er penger man får.', 'Viser at inntekt kan komme fra ulike kilder, for eksempel arbeid og pensjon.']::text[], 0),
  ('samfunnsfag-8:okonomi-og-forbruk', 's02', 'Sammenlign faste og variable utgifter. Bruk husleie og mat som eksempler, og forklar hvilken type hver utgift er.', 'Husleie er en fast utgift fordi den kommer jevnlig og ofte er omtrent like stor hver gang. Mat er en variabel utgift fordi beløpet kan variere.', array['Forklarer at faste utgifter kommer jevnlig og er omtrent like store.', 'Forklarer at variable utgifter varierer, og plasserer husleie og mat i riktig kategori.']::text[], 1),
  ('samfunnsfag-8:okonomi-og-forbruk', 's03', 'Prisene på mat stiger, men en person har like mye penger som før. Forklar hvordan dette kan påvirke hva personen får kjøpt.', 'Når prisene stiger, får personen mindre for de samme pengene. Personen kan derfor kjøpe færre varer enn før.', array['Forklarer at stigende priser gjør at pengene blir mindre verdt.', 'Knytter dette til at man får kjøpt mindre for samme beløp.']::text[], 2),
  ('samfunnsfag-8:okonomi-og-forbruk', 's04', 'En person lar en regning være ubetalt. Forklar hva som kan skje hvis regningen går til inkasso, og nevn én mulig følge.', 'Inkasso betyr at den ubetalte regningen blir krevd inn. Det kan komme ekstra gebyrer, og personen kan få en betalingsanmerkning.', array['Forklarer at inkasso handler om innkreving av en ubetalt regning.', 'Nevner ekstra gebyrer eller betalingsanmerkning som en mulig følge.']::text[], 3),
  ('samfunnsfag-8:okonomi-og-forbruk', 's05', 'Nora kjøper en genser på nett og ombestemmer seg. En annen person kjøper en vare som viser seg å ha en feil. Hvilken rett passer i hvert tilfelle, og hvorfor?', 'Nora kan bruke angreretten fordi hun har ombestemt seg etter et nettkjøp. Personen med varen som har en feil, kan bruke reklamasjon for å klage på feilen.', array['Knytter angrerett til å angre på et nettkjøp.', 'Knytter reklamasjon til å klage på en vare med feil.']::text[], 4),
  ('samfunnsfag-8:okonomi-og-forbruk', 's06', 'En elev ser ofte videoer fra en influenser som viser fram bestemte merkeklær. Forklar hvordan dette kan påvirke hva eleven ønsker å kjøpe, og hvordan det kan føre til kjøpepress.', 'Influensere kan påvirke hva vi får lyst til å kjøpe. Hvis eleven opplever at bestemte merkeklær er viktige for å passe inn, kan det føre til kjøpepress.', array['Forklarer at influensere kan påvirke ønsker om å kjøpe varer.', 'Knytter påvirkningen til press om å kjøpe bestemte ting eller merker.']::text[], 5),
  ('samfunnsfag-8:okonomi-og-forbruk', 's07', 'Sekken til Amir har gått i stykker, men kan repareres. Forklar hvorfor det kan være bærekraftig å reparere den i stedet for å kjøpe en ny.', 'Ved å reparere sekken bruker Amir mindre ressurser og energi enn om han kjøper en ny. Det kan også være bra for lommeboka.', array['Forklarer at reparasjon kan redusere bruken av ressurser eller energi.', 'Nevner at reparasjon også kan spare penger.']::text[], 6),
  ('samfunnsfag-8:okonomi-og-forbruk', 's08', 'En familie får høyere inntekt etter at de allerede har råd til grunnleggende behov. Forklar hvorfor dette ikke nødvendigvis gir familien bedre livskvalitet.', 'Høyere inntekt kan gi høyere levestandard, men gir ikke automatisk bedre livskvalitet. Helse, venner, trygghet og mening har også betydning for hvordan familien har det.', array['Forklarer at høyere inntekt ikke automatisk betyr bedre livskvalitet.', 'Nevner en faktor som helse, relasjoner, trygghet eller mening som også påvirker livskvaliteten.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-8:befolkning-og-levekar', 'samfunnsfag-8', 'befolkning-og-levekar', 'Befolkning, bosetting og levekår', 'Hvordan politiske, geografiske og historiske forhold påvirker hvor folk bor, hvordan befolkningen utvikler seg, og hvilke levekår mennesker har i ulike deler av verden.', array[6]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-8:befolkning-og-levekar', '## Demografi
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-8:befolkning-og-levekar', 'Demografi', 'Læren om befolkningen: størrelse, alder, fødsler, dødsfall og flytting.', 0),
  ('samfunnsfag-8:befolkning-og-levekar', 'Befolkningsvekst', 'Fødte minus døde, pluss innvandring minus utvandring.', 1),
  ('samfunnsfag-8:befolkning-og-levekar', 'Fruktbarhetstall', 'Hvor mange barn hver kvinne i gjennomsnitt får.', 2),
  ('samfunnsfag-8:befolkning-og-levekar', 'Forventet levealder', 'Hvor mange år en nyfødt i gjennomsnitt kan forvente å leve.', 3),
  ('samfunnsfag-8:befolkning-og-levekar', 'Demografisk overgang', 'Modell for hvordan fødsels- og dødsrater endres når et land utvikler seg.', 4),
  ('samfunnsfag-8:befolkning-og-levekar', 'Fase 2 i overgangen', 'Dødsraten synker mens fødselsraten er høy, og befolkningen vokser raskt.', 5),
  ('samfunnsfag-8:befolkning-og-levekar', 'Befolkningspyramide', 'Diagram som viser hvor mange som er i hver aldersgruppe, fordelt på kjønn.', 6),
  ('samfunnsfag-8:befolkning-og-levekar', 'Bosettingsmønster', 'Hvordan befolkningen er fordelt i et område.', 7),
  ('samfunnsfag-8:befolkning-og-levekar', 'Urbanisering', 'At en økende andel av befolkningen bor i byer.', 8),
  ('samfunnsfag-8:befolkning-og-levekar', 'Sentralisering', 'Flytting fra distriktene til byer og tettsteder.', 9),
  ('samfunnsfag-8:befolkning-og-levekar', 'Levekår', 'Materielle og sosiale forhold som inntekt, bolig, helse og utdanning.', 10),
  ('samfunnsfag-8:befolkning-og-levekar', 'HDI', 'FNs indeks for menneskelig utvikling: levealder, utdanning og inntekt.', 11),
  ('samfunnsfag-8:befolkning-og-levekar', 'Skyvefaktor', 'Noe som får folk til å flytte fra et sted, som krig eller fattigdom.', 12),
  ('samfunnsfag-8:befolkning-og-levekar', 'Trekkfaktor', 'Noe som trekker folk til et sted, som arbeid eller trygghet.', 13),
  ('samfunnsfag-8:befolkning-og-levekar', 'Ettbarnspolitikken', 'Kinesisk politikk fra 1980 til 2015 som begrenset antall barn per familie.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-8:befolkning-og-levekar', 'q01', 'flervalg', 'Hva er demografi?', array['Læren om befolkningen', 'Læren om fjell og elver', 'Læren om demokrati', 'Læren om økonomi']::text[], 0, 'Demografi handler om befolkningens størrelse, sammensetning og endring.', true, true, 0),
  ('samfunnsfag-8:befolkning-og-levekar', 'q02', 'flervalg', 'Hva skjer i fase 2 i den demografiske overgangen?', array['Både fødselsraten og dødsraten er høye', 'Dødsraten synker, og befolkningen vokser raskt', 'Fødselsraten synker kraftig', 'Befolkningen går ned']::text[], 1, 'Bedre mat, rent vann og medisin gjør at færre dør, mens det fortsatt fødes mange.', true, true, 1),
  ('samfunnsfag-8:befolkning-og-levekar', 'q03', 'flervalg', 'Hva viser en befolkningspyramide med bred bunn?', array['En aldrende befolkning', 'At mange flytter ut', 'En befolkning med mange barn og unge', 'At levealderen er høy']::text[], 2, 'Bred bunn betyr at det fødes mange barn.', true, true, 2),
  ('samfunnsfag-8:befolkning-og-levekar', 'q04', 'flervalg', 'Hvorfor bor få mennesker i Sahara?', array['Fordi det er forbudt', 'Fordi det er for mange byer der', 'Fordi det er for kaldt', 'Fordi det er tørt og lite vann']::text[], 3, 'Tilgang på vann er en av de viktigste forutsetningene for bosetting.', true, true, 3),
  ('samfunnsfag-8:befolkning-og-levekar', 'q05', 'flervalg', 'Hva er urbanisering?', array['At en økende andel bor i byer', 'At byer blir mindre', 'At skogen vokser', 'At folk flytter til fjells']::text[], 0, 'Over halvparten av verdens befolkning bor nå i byer.', true, true, 4),
  ('samfunnsfag-8:befolkning-og-levekar', 'q06', 'flervalg', 'Hva måler HDI?', array['Bare inntekt', 'Levealder, utdanning og inntekt', 'Antall byer i et land', 'Hvor mange som stemmer ved valg']::text[], 1, 'HDI gir et bredere bilde av utvikling enn inntekt alene.', true, true, 5),
  ('samfunnsfag-8:befolkning-og-levekar', 'q07', 'flervalg', 'Hvorfor synker fødselsraten når et land utvikler seg?', array['Fordi det blir færre sykehus', 'Fordi alle flytter ut', 'Fordi kvinner får mer utdanning og tilgang til prevensjon', 'Fordi dødsraten øker']::text[], 2, 'Utdanning, arbeid og byliv gjør at mange velger å få færre barn.', true, true, 6),
  ('samfunnsfag-8:befolkning-og-levekar', 'q08', 'flervalg', 'Hva er et eksempel på en skyvefaktor for migrasjon?', array['Godt betalt arbeid i et annet land', 'Gode skoler i et annet land', 'Familie som bor i et annet land', 'Krig i hjemlandet']::text[], 3, 'Skyvefaktorer får folk til å forlate et sted.', true, true, 7),
  ('samfunnsfag-8:befolkning-og-levekar', 'q09', 'flervalg', 'Hvordan kan historiske forhold påvirke levekår i dag?', array['Kolonitiden kan ha gitt økonomier som bygger på eksport av råvarer', 'Historie påvirker aldri levekår', 'Bare klimaet betyr noe', 'Gamle kriger har ingen betydning']::text[], 0, 'Grenser og økonomiske strukturer fra kolonitiden preger fortsatt mange land.', true, false, 8),
  ('samfunnsfag-8:befolkning-og-levekar', 'q10', 'flervalg', 'Hva er sentralisering i Norge?', array['At folk flytter fra byer til bygder', 'At folk flytter fra distriktene til byer og tettsteder', 'At Oslo blir mindre', 'At alle kommuner slås sammen']::text[], 1, 'Mange flytter dit arbeidsplassene og utdanningstilbudene er.', true, false, 9),
  ('samfunnsfag-8:befolkning-og-levekar', 'm01', 'sant-usant', 'Verdens befolkning har passert 8 milliarder.', array['Sant', 'Usant']::text[], 0, 'Ifølge FN passerte vi 8 milliarder i 2022.', false, true, 10),
  ('samfunnsfag-8:befolkning-og-levekar', 'm02', 'sant-usant', 'De fleste mennesker i verden bor i ørken- og fjellområder.', array['Sant', 'Usant']::text[], 1, 'De fleste bor i lavland nær kyster og elver.', false, true, 11),
  ('samfunnsfag-8:befolkning-og-levekar', 'm03', 'sant-usant', 'Japan har en befolkningspyramide med svært bred bunn.', array['Sant', 'Usant']::text[], 1, 'Japan har få fødsler og en aldrende befolkning, så pyramiden er smal nederst.', false, true, 12),
  ('samfunnsfag-8:befolkning-og-levekar', 'm04', 'sant-usant', 'Et fruktbarhetstall på rundt 2,1 gir på sikt en stabil befolkning uten innvandring.', array['Sant', 'Usant']::text[], 0, 'Hver generasjon erstatter da seg selv.', false, true, 13),
  ('samfunnsfag-8:befolkning-og-levekar', 'm05', 'flervalg', 'Hvilken er en trekkfaktor?', array['Arbeidsløshet', 'Naturkatastrofe', 'Gode jobbmuligheter', 'Forfølgelse']::text[], 2, 'Trekkfaktorer gjør et sted attraktivt å flytte til.', false, true, 14),
  ('samfunnsfag-8:befolkning-og-levekar', 'm06', 'flervalg', 'Hva er forventet levealder?', array['Hvor mange år en nyfødt i gjennomsnitt kan forvente å leve', 'Alderen da man blir pensjonist', 'Den høyeste alderen i et land', 'Alderen da man får stemmerett']::text[], 0, 'Forventet levealder er et viktig mål på helse og levekår.', false, true, 15),
  ('samfunnsfag-8:befolkning-og-levekar', 'm07', 'flervalg', 'Hva var ettbarnspolitikken?', array['En norsk lov om barnetrygd', 'En regel i Kina som begrenset antall barn per familie', 'En FN-avtale om barns rettigheter', 'En skoleordning i Afrika']::text[], 1, 'Politikken varte fra 1980 til 2015 og har gitt Kina en raskt aldrende befolkning.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-8:befolkning-og-levekar', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-8:befolkning-og-levekar', 's01', 'Hva forteller fruktbarhetstallet, og hva forteller forventet levealder? Forklar forskjellen på de to målene.', 'Fruktbarhetstallet viser hvor mange barn hver kvinne får i gjennomsnitt. Forventet levealder viser hvor mange år en nyfødt i gjennomsnitt kan regne med å leve.', array['Forklarer at fruktbarhetstallet handler om antall barn per kvinne i gjennomsnitt.', 'Forklarer at forventet levealder handler om hvor lenge en nyfødt i gjennomsnitt kan leve.']::text[], 0),
  ('samfunnsfag-8:befolkning-og-levekar', 's02', 'Sammenlign fase 1 og fase 4 i den demografiske overgangen. Hvordan er fødselsraten og dødsraten i hver fase, og hvor mye vokser befolkningen?', 'I fase 1 er både fødselsraten og dødsraten høye, og befolkningen vokser lite. I fase 4 er begge ratene lave, og befolkningsveksten er også liten.', array['Beskriver at både fødselsraten og dødsraten er høye i fase 1, men lave i fase 4.', 'Får fram at befolkningen vokser lite i begge fasene.']::text[], 1),
  ('samfunnsfag-8:befolkning-og-levekar', 's03', 'I et land er det like mange fødte som døde. Samtidig flytter flere mennesker inn i landet enn ut av det. Forklar om befolkningen vokser, minker eller holder seg lik, og hvorfor.', 'Befolkningen vokser. Når like mange blir født som dør, går ikke folketallet opp eller ned av den grunn, men flere innflyttere enn utflyttere øker folketallet.', array['Konkluderer med at befolkningen vokser.', 'Forklarer at innvandringen er større enn utvandringen, mens fødsler og dødsfall går opp i opp.']::text[], 2),
  ('samfunnsfag-8:befolkning-og-levekar', 's04', 'I et land øker andelen av befolkningen som bor i byer. I Norge flytter mange fra distriktene til byer og tettsteder. Bruk begrepene urbanisering og sentralisering til å forklare hvilken beskrivelse som passer til hvert begrep.', 'Når en økende andel av befolkningen bor i byer, kalles det urbanisering. Når folk i Norge flytter fra distriktene til byer og tettsteder, kalles det sentralisering.', array['Knytter urbanisering til at en økende andel bor i byer.', 'Knytter sentralisering til flytting fra distriktene til byer og tettsteder.']::text[], 3),
  ('samfunnsfag-8:befolkning-og-levekar', 's05', 'Et område består av lavland ved en elv, med vann, godt klima og matjord. Et annet område er høyfjell. Hvilket område er det mest sannsynlig at flest mennesker vil bosette seg i? Begrunn svaret med forhold ved områdene.', 'Det er mest sannsynlig at flest vil bosette seg i lavlandet ved elven. Der er det tilgang til vann, godt klima og matjord, mens få mennesker bor i høyfjell.', array['Velger lavlandet ved elven som området det mest sannsynlig bor flest i.', 'Begrunner valget med relevante forhold, som tilgang til vann, godt klima eller matjord.']::text[], 4),
  ('samfunnsfag-8:befolkning-og-levekar', 's06', 'En oversikt viser at inntekten i et område har økt, men at helse og utdanning har blitt dårligere. Forklar hvorfor inntekt alene ikke gir et fullstendig bilde av levekårene der.', 'Levekår handler om flere materielle og sosiale forhold, ikke bare inntekt. Helse og utdanning er også viktige, så dårligere forhold på disse områdene påvirker levekårene selv om inntekten har økt.', array['Får fram at levekår omfatter flere forhold enn inntekt.', 'Bruker helse og utdanning som relevante sider ved levekårene i situasjonen.']::text[], 5),
  ('samfunnsfag-8:befolkning-og-levekar', 's07', 'En person flytter fra et sted på grunn av krig og reiser til et annet land der personen har familie og mulighet for arbeid. Forklar hva som er en skyvefaktor og hva som er en trekkfaktor i situasjonen.', 'Krigen er en skyvefaktor fordi den får personen til å flytte fra stedet. Familie og mulighet for arbeid er trekkfaktorer fordi de trekker personen til det nye landet.', array['Forklarer at krigen er en skyvefaktor som får personen til å flytte fra stedet.', 'Forklarer at familie eller arbeid er en trekkfaktor som trekker personen til det nye landet.']::text[], 6),
  ('samfunnsfag-8:befolkning-og-levekar', 's08', 'Kinas ettbarnspolitikk begrenset hvor mange barn hver familie kunne få. Forklar hvordan en slik politikk kan påvirke antallet fødsler og befolkningsveksten.', 'Når familier får færre barn, kan antallet fødsler bli lavere. Siden fødsler påvirker befolkningsveksten, kan en slik politikk endre hvordan befolkningen utvikler seg.', array['Forklarer at begrensningen kan føre til færre barn eller færre fødsler.', 'Knytter færre fødsler til en endring i befolkningsveksten eller befolkningens utvikling.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-8:digitale-spor-og-personvern', 'samfunnsfag-8', 'digitale-spor-og-personvern', 'Digitale spor, personvern og samfunnsdebatt', 'Hvilke digitale spor du legger igjen, hvilke rettigheter du har til personvern, sletting og opphavsrett, og hvordan digitale plattformer påvirker samfunnsdebatten.', array[14, 17]::int[], 6, 'sjekkes', array['Lov om aldersgrense for sosiale medier (fra 1. januar det året man fyller 16) var foreslått, men ikke vedtatt per september 2026. Oppdater temaet når Stortinget har behandlet loven.']::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-8:digitale-spor-og-personvern', '## Digitale spor
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Digitale spor', 'Informasjon du etterlater deg når du bruker internett.', 0),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Aktive spor', 'Det du selv legger ut, som bilder, kommentarer og likerklikk.', 1),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Passive spor', 'Data som samles inn uten at du merker det, som posisjon og søkehistorikk.', 2),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Informasjonskapsel (cookie)', 'Liten fil som nettsteder bruker til å huske og spore deg.', 3),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Personvern', 'Retten til privatliv og til å bestemme over opplysninger om deg selv.', 4),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Personopplysning', 'Opplysning som kan knyttes til deg, som navn, bilde eller IP-adresse.', 5),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'GDPR', 'Personvernforordningen, som gjelder i EU og EØS, også i Norge.', 6),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Rett til sletting', 'Retten til å få opplysninger om deg slettet, «retten til å bli glemt».', 7),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Datatilsynet', 'Myndigheten som passer på at personvernreglene følges i Norge.', 8),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Samtykke', 'Frivillig og tydelig ja til at noe kan skje, for eksempel at et bilde deles.', 9),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Opphavsrett', 'Skaperens rett til å bestemme over bruken av verket sitt, til 70 år etter død.', 10),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Creative Commons', 'Lisenser som lar skapere gi andre lov til å bruke verket på bestemte vilkår.', 11),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Ekkokammer', 'Nettmiljø der man mest møter meninger som ligner ens egne.', 12),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Polarisering', 'At meningene i debatten trekkes mot ytterpunktene.', 13),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'Hatefulle ytringer', 'Ytringer som truer eller håner noen for blant annet hudfarge, religion eller legning. Straffbart.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q01', 'flervalg', 'Hva er et passivt digitalt spor?', array['Et bilde du legger ut', 'En kommentar du skriver', 'Posisjonen din som samles inn uten at du merker det', 'Et innlegg du deler']::text[], 2, 'Passive spor samles inn i bakgrunnen mens du bruker nettet.', true, true, 0),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q02', 'flervalg', 'Hva er personopplysninger?', array['Bare passordet ditt', 'Opplysninger som kan knyttes til deg', 'Opplysninger om kjendiser', 'Nyheter om deg i avisen']::text[], 1, 'Navn, bilder, adresse og IP-adresse er eksempler på personopplysninger.', true, true, 1),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q03', 'flervalg', 'Hva betyr «retten til å bli glemt»?', array['At du kan be om å få slettet opplysninger om deg', 'At lærere ikke kan huske deg', 'At du kan slette andres innlegg', 'At internett sletter alt etter ett år']::text[], 0, 'Retten til sletting er en del av personvernforordningen.', true, true, 2),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q04', 'flervalg', 'Hvem passer på personvernet i Norge?', array['Politiet', 'Stortinget', 'Forbrukerrådet', 'Datatilsynet']::text[], 3, 'Datatilsynet kan gi pålegg og bøter til virksomheter som bryter reglene.', true, true, 3),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q05', 'flervalg', 'Hva bør du gjøre før du deler et bilde der en venn er hovedmotivet?', array['Redigere bildet', 'Spørre om lov', 'Ingenting', 'Legge på et filter']::text[], 1, 'Hovedregelen er at den som er avbildet, må samtykke.', true, true, 4),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q06', 'flervalg', 'Hva gir opphavsretten?', array['Rett til å bruke alle bilder på nett', 'Rett til å slette andres innlegg', 'Skaperen rett til å bestemme over bruken av verket', 'Staten rett til å sensurere']::text[], 2, 'Du trenger tillatelse for å bruke andres bilder, musikk og tekster.', true, true, 5),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q07', 'flervalg', 'Hvorfor samler selskaper inn data om deg?', array['For å lage en profil og vise målrettet reklame', 'For å hjelpe skolen', 'Fordi loven krever det', 'For å slette dem senere']::text[], 0, 'Data om deg er verdifulle fordi de gjør reklamen mer treffsikker.', true, true, 6),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q08', 'flervalg', 'Hvordan kan algoritmer påvirke samfunnsdebatten?', array['De gjør alle innlegg like lange', 'De fjerner alt politisk innhold', 'De viser bare nyheter fra staten', 'De kan fremheve innhold som vekker sterke følelser']::text[], 3, 'Engasjerende og polariserende innhold får ofte mer spredning.', true, true, 7),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q09', 'flervalg', 'Hva kan være en følge av hets i kommentarfelt?', array['At flere deltar i debatten', 'At noen trekker seg fra debatten', 'At debatten blir mer saklig', 'Ingen følger']::text[], 1, 'Hets kan gjøre at viktige stemmer forsvinner fra samfunnsdebatten.', true, false, 8),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'q10', 'flervalg', 'Hva er en Creative Commons-lisens?', array['En lisens som lar skapere gi andre lov til å bruke verket', 'Et forbud mot deling', 'Et førerkort for droner', 'En type passord']::text[], 0, 'Lisensen sier hva andre har lov til, for eksempel å dele med navn på skaperen.', true, false, 9),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'm01', 'sant-usant', 'Et skjermbilde kan gjøre at noe du har slettet, likevel spres videre.', array['Sant', 'Usant']::text[], 0, 'Det som er delt, kan kopieres før du rekker å slette det.', false, true, 10),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'm02', 'sant-usant', 'Ytringsfriheten betyr at du kan si hva som helst, også trusler.', array['Sant', 'Usant']::text[], 1, 'Trusler og hatefulle ytringer er straffbare.', false, true, 11),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'm03', 'sant-usant', 'IP-adressen din kan være en personopplysning.', array['Sant', 'Usant']::text[], 0, 'IP-adressen kan brukes til å knytte aktivitet på nett til deg.', false, true, 12),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'm04', 'sant-usant', 'Opphavsretten forsvinner når et bilde legges ut på internett.', array['Sant', 'Usant']::text[], 1, 'Skaperen har fortsatt opphavsretten, selv om bildet er lett å kopiere.', false, true, 13),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'm05', 'flervalg', 'Hva er et ekkokammer?', array['Et rom med god akustikk', 'Et nettmiljø der man mest møter meninger som ligner ens egne', 'En type søkemotor', 'Et lydopptak']::text[], 1, 'I ekkokamre blir egne meninger forsterket i stedet for utfordret.', false, true, 14),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'm06', 'flervalg', 'Hva er GDPR?', array['Personvernforordningen, som også gjelder i Norge', 'En norsk avis', 'En sosial medieplattform', 'Et bildeprogram']::text[], 0, 'GDPR gir alle i EU og EØS de samme grunnleggende personvernrettighetene.', false, true, 15),
  ('samfunnsfag-8:digitale-spor-og-personvern', 'm07', 'flervalg', 'Hvilken ytring er straffbar?', array['Kritikk av regjeringen', 'En sterk mening om skolemat', 'En hatefull ytring mot noen på grunn av hudfarge', 'En negativ anmeldelse av en film']::text[], 2, 'Straffeloven forbyr hatefulle ytringer mot grupper og enkeltpersoner.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-8:digitale-spor-og-personvern', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-8:digitale-spor-og-personvern', 's01', 'Nora legger ut et bilde og liker et innlegg. Samtidig registrerer et nettsted hva hun søker etter, hvilke sider hun besøker og hvor lenge hun ser på en video. Sammenlign de digitale sporene i disse to situasjonene.', 'Bildet og likerklikket er aktive spor fordi Nora selv legger dem ut. Søkene, sidene og videotiden er passive spor fordi nettstedet samler dem inn uten at hun nødvendigvis merker det.', array['Skiller mellom spor Nora selv legger ut og data som samles inn uten at hun merker det.', 'Plasserer eksemplene riktig som aktive eller passive spor.']::text[], 0),
  ('samfunnsfag-8:digitale-spor-og-personvern', 's02', 'En tjeneste har lagret en gammel adresse på deg, og adressen er feil. Hvilken rett etter GDPR kan du bruke, og hva kan du be tjenesten gjøre?', 'Du kan bruke retten til å få feil rettet. Du kan be tjenesten endre den gamle adressen til riktig adresse.', array['Kjenner igjen retten til å få feil opplysninger rettet.', 'Forklarer at tjenesten kan bes om å endre den uriktige opplysningen.']::text[], 1),
  ('samfunnsfag-8:digitale-spor-og-personvern', 's03', 'Du har sagt ja til at en app behandler opplysninger om deg, men ombestemmer deg. Hvilken rett etter GDPR kan du bruke da?', 'Du kan trekke tilbake samtykket ditt. Det betyr at du ikke lenger sier ja til at appen behandler opplysningene på grunnlag av samtykket.', array['Nevner retten til å trekke tilbake samtykke.', 'Viser at samtykket var et ja til behandling av opplysninger, og at det kan ombestemmes.']::text[], 2),
  ('samfunnsfag-8:digitale-spor-og-personvern', 's04', 'Du sletter et innlegg fra en nettside, men noen har tatt skjermbilde av det. Forklar hvorfor det ikke er sikkert at alle spor av innlegget forsvinner, og hva dette kan lære deg før du deler noe.', 'Andre kan ha kopiert innlegget eller tatt skjermbilde, så det kan fortsatt finnes selv om du sletter originalen. Derfor er det lurt å tenke gjennom hva du deler før du legger det ut.', array['Forklarer at kopier eller skjermbilder kan gjøre at innholdet fortsatt finnes etter sletting.', 'Knytter dette til å tenke før man deler.']::text[], 3),
  ('samfunnsfag-8:digitale-spor-og-personvern', 's05', 'Sosiale medier gjør det lett for mange å delta i en debatt og å samle folk raskt. Forklar denne fordelen, og beskriv én måte det korte, raske og visuelle formatet kan påvirke debatten på.', 'Digitale plattformer gjør det enkelt for mange å delta og mobilisere raskt. Fordi innlegg ofte er korte, raske og visuelle, kan debatten få en annen form enn en lengre samtale.', array['Forklarer at plattformer gjør det lettere å delta eller mobilisere mange raskt.', 'Knytter korte, raske eller visuelle innlegg til hvordan debatten formes.']::text[], 4),
  ('samfunnsfag-8:digitale-spor-og-personvern', 's06', 'I et ekkokammer møter folk mest meninger som ligner deres egne. Forklar hva dette kan gjøre med meningene i en samfunnsdebatt.', 'Når folk mest møter meninger som ligner deres egne, får de mindre møte med andre syn. Det kan bidra til polarisering, der meningene trekkes mot ytterpunktene.', array['Forklarer at man i et ekkokammer mest møter synspunkter som ligner ens egne.', 'Knytter dette til at debatten kan bli mer polarisert eller at meningene trekkes mot ytterpunktene.']::text[], 5),
  ('samfunnsfag-8:digitale-spor-og-personvern', 's07', 'Du vil bruke et bilde laget av noen andre i et innlegg du publiserer. Forklar hvorfor du ikke automatisk kan bruke bildet, og hvordan en Creative Commons-lisens kan gjøre bruk mulig.', 'Opphavsrett gir skaperen rett til å bestemme over bruken av bildet, så du kan ikke automatisk bruke det fritt. En Creative Commons-lisens kan gi lov til å bruke bildet på bestemte vilkår.', array['Forklarer at opphavsrett gir skaperen kontroll over bruken av bildet.', 'Forklarer at Creative Commons kan gi tillatelse til bruk på bestemte vilkår.']::text[], 6),
  ('samfunnsfag-8:digitale-spor-og-personvern', 's08', 'En elev skriver en trussel i et kommentarfelt og sier at ytringsfriheten betyr at hen kan skrive hva som helst på nett. Forklar hvorfor dette ikke stemmer.', 'Ytringsfriheten er viktig, men den har grenser. Trusler er straffbare også på nett, så ytringsfriheten betyr ikke at man kan true andre uten konsekvenser.', array['Forklarer at ytringsfriheten har grenser.', 'Nevner at trusler er straffbare også på nett.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-8:kristendommen', 'krle-8', 'kristendommen', 'Kristendommen', 'Jesus og Bibelen, sentrale trosideer og praksiser i kristendommen, de ulike kirkeretningene og hvor kristendommen er utbredt i dag.', array[1, 6]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-8:kristendommen', '## En verdensreligion
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
