  ('krle-8:kristendommen', 'Kristus', 'Betyr «den salvede». Kristne tror Jesus er Kristus og Guds sønn.', 1),
  ('krle-8:kristendommen', 'Bibelen', 'Kristendommens hellige skrift, med Det gamle og Det nye testamente.', 2),
  ('krle-8:kristendommen', 'Det nye testamente', 'Den delen av Bibelen som forteller om Jesus og de første kristne.', 3),
  ('krle-8:kristendommen', 'Evangelium', '«Godt budskap». De fire evangeliene forteller om Jesu liv.', 4),
  ('krle-8:kristendommen', 'Monoteisme', 'Troen på at det finnes én Gud.', 5),
  ('krle-8:kristendommen', 'Treenigheten', 'Gud er Fader, Sønn og Den hellige ånd – én Gud i tre personer.', 6),
  ('krle-8:kristendommen', 'Inkarnasjonen', 'Troen på at Gud ble menneske i Jesus.', 7),
  ('krle-8:kristendommen', 'Nåde', 'Guds tilgivelse og kjærlighet, som mennesket får uten å fortjene den.', 8),
  ('krle-8:kristendommen', 'Nestekjærlighet', 'Å elske og hjelpe andre mennesker som seg selv.', 9),
  ('krle-8:kristendommen', 'Sakrament', 'Hellig handling. Dåp og nattverd er sakramenter i de fleste kirker.', 10),
  ('krle-8:kristendommen', 'Påske', 'Høytiden for Jesu død og oppstandelse.', 11),
  ('krle-8:kristendommen', 'Pinse', 'Høytiden der Den hellige ånd kom til disiplene.', 12),
  ('krle-8:kristendommen', 'Reformasjonen', 'Bruddet med den katolske kirken som Martin Luther satte i gang i 1517.', 13),
  ('krle-8:kristendommen', 'Hovedretninger', 'Katolsk, ortodoks og protestantisk kristendom.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-8:kristendommen', 'q01', 'flervalg', 'Hva betyr «Kristus»?', array['Den salvede', 'Den hellige', 'Profeten', 'Kongen av Roma']::text[], 0, 'Tittelen viser til at kristne tror Jesus er den lovede frelseren.', true, true, 0),
  ('krle-8:kristendommen', 'q02', 'flervalg', 'Hva er treenigheten?', array['Tre ulike guder', 'Tre store høytider', 'At Gud er Fader, Sønn og Den hellige ånd – én Gud i tre personer', 'Tre kristne retninger']::text[], 2, 'Kristne tror på én Gud som viser seg på tre måter.', true, true, 1),
  ('krle-8:kristendommen', 'q03', 'flervalg', 'Hva feirer kristne i påsken?', array['Jesu fødsel', 'Jesu død og oppstandelse', 'At Den hellige ånd kom', 'At Jesus ble døpt']::text[], 1, 'Påsken er kirkeårets viktigste høytid.', true, true, 2),
  ('krle-8:kristendommen', 'q04', 'flervalg', 'Hvem satte i gang reformasjonen i 1517?', array['Paven', 'Paulus', 'Olav den hellige', 'Martin Luther']::text[], 3, 'Luther kritiserte blant annet salget av avlat i den katolske kirken.', true, true, 3),
  ('krle-8:kristendommen', 'q05', 'flervalg', 'Hvilke to sakramenter har de fleste kirker?', array['Konfirmasjon og bryllup', 'Bønn og faste', 'Dåp og nattverd', 'Jul og påske']::text[], 2, 'Den katolske og den ortodokse kirken har i tillegg flere sakramenter.', true, true, 4),
  ('krle-8:kristendommen', 'q06', 'flervalg', 'Hvilken kristen retning er størst i verden?', array['Den katolske kirke', 'Den ortodokse kirke', 'Den lutherske kirke', 'Pinsebevegelsen']::text[], 0, 'Rundt halvparten av verdens kristne er katolikker.', true, true, 5),
  ('krle-8:kristendommen', 'q07', 'flervalg', 'Hva forteller evangeliene om?', array['Skapelsen av verden', 'Moses og utgangen fra Egypt', 'Reformasjonen', 'Jesu liv, død og oppstandelse']::text[], 3, 'De fire evangeliene er Matteus, Markus, Lukas og Johannes.', true, true, 6),
  ('krle-8:kristendommen', 'q08', 'flervalg', 'Hvor bor flest kristne i dag?', array['I Nord-Europa', 'I Latin-Amerika og Afrika sør for Sahara', 'I Øst-Asia', 'I Midtøsten']::text[], 1, 'Tyngdepunktet i kristendommen har flyttet seg sørover.', true, true, 7),
  ('krle-8:kristendommen', 'q09', 'flervalg', 'Hva betyr inkarnasjonen?', array['At Gud ble menneske i Jesus', 'At man blir født på nytt i et annet liv', 'At Jesus sto opp fra de døde', 'At kirken ble grunnlagt']::text[], 0, 'Inkarnasjon betyr «å bli kjød», altså å bli menneske.', true, false, 8),
  ('krle-8:kristendommen', 'q10', 'flervalg', 'Hva feires i pinsen?', array['Jesu fødsel', 'At Jesus døde', 'At Den hellige ånd kom til disiplene', 'At kirkeåret begynner']::text[], 2, 'Pinsen regnes ofte som kirkens fødselsdag.', true, false, 9),
  ('krle-8:kristendommen', 'm01', 'sant-usant', 'Kristne deler Det gamle testamente med jødene.', array['Sant', 'Usant']::text[], 0, 'Jødene kaller de samme skriftene Tanak.', false, true, 10),
  ('krle-8:kristendommen', 'm02', 'sant-usant', 'Jesus vokste opp i Roma.', array['Sant', 'Usant']::text[], 1, 'Jesus var jøde og vokste opp i Galilea.', false, true, 11),
  ('krle-8:kristendommen', 'm03', 'sant-usant', 'Den norske kirke er luthersk.', array['Sant', 'Usant']::text[], 0, 'Norge ble luthersk etter reformasjonen i 1537.', false, true, 12),
  ('krle-8:kristendommen', 'm04', 'sant-usant', 'Den ortodokse kirke ledes av paven i Roma.', array['Sant', 'Usant']::text[], 1, 'Paven leder den katolske kirken. Den ortodokse kirken har egne patriarker.', false, true, 13),
  ('krle-8:kristendommen', 'm05', 'flervalg', 'Hva er monoteisme?', array['Troen på mange guder', 'Troen på én Gud', 'Troen på at det ikke finnes noen gud', 'Troen på gjenfødelse']::text[], 1, 'Kristendom, jødedom og islam er monoteistiske.', false, true, 14),
  ('krle-8:kristendommen', 'm06', 'flervalg', 'Hvilken bønn lærte Jesus disiplene ifølge Bibelen?', array['Fadervår', 'Trosbekjennelsen', 'Shahada', 'Shema']::text[], 0, 'Fadervår er den mest kjente kristne bønnen.', false, true, 15),
  ('krle-8:kristendommen', 'm07', 'flervalg', 'Hva betyr nestekjærlighet?', array['Å bare elske familien sin', 'Å gi penger til kirken', 'Å bry seg om og hjelpe andre mennesker', 'Å gå i kirken hver søndag']::text[], 2, 'Lignelsen om den barmhjertige samaritan er et kjent eksempel.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-8:kristendommen', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-8:kristendommen', 's01', 'Bibelen har to hoveddeler. Forklar hva Det gamle testamente og Det nye testamente inneholder.', 'Det gamle testamente er en del av Bibelen som kristne deler med jødene. Det nye testamente forteller om Jesus og de første kristne.', array['Skiller mellom innholdet i Det gamle og Det nye testamente.', 'Får fram at Det gamle testamente deles med jødene, eller at Det nye testamente handler om Jesus og de første kristne.']::text[], 0),
  ('krle-8:kristendommen', 's02', 'Forklar hva kristne mener med nåde, og hvordan nåde henger sammen med synd.', 'Kristne mener at mennesker er skilt fra Gud ved synd. Gjennom Guds nåde får de tilgivelse og kjærlighet uten å måtte fortjene det.', array['Forklarer at nåde er Guds tilgivelse eller kjærlighet som ikke må fortjenes.', 'Knytter nåde til at mennesker kan få tilgivelse for synd.']::text[], 1),
  ('krle-8:kristendommen', 's03', 'Paulus skrev brev som hjalp kristendommen med å spre seg. Forklar hvilken rolle brevene hans hadde for kristendommens utbredelse.', 'Brevene til Paulus hjalp kristendommen med å spre seg også blant mennesker som ikke var jøder.', array['Får fram at brevene bidro til at kristendommen spredte seg.', 'Nevner at spredningen også skjedde blant ikke-jøder.']::text[], 2),
  ('krle-8:kristendommen', 's04', 'Sammenlign Den katolske kirke og Den ortodokse kirke. Ta med én forskjell eller opplysning som skiller dem.', 'Den katolske kirke ledes av paven i Roma. Den ortodokse kirke er utbredt i Øst-Europa, og kirkene skilte lag i 1054.', array['Nevner at Den katolske kirke ledes av paven i Roma.', 'Gir en relevant opplysning om Den ortodokse kirke, for eksempel utbredelsen i Øst-Europa eller at kirkene skilte lag i 1054.']::text[], 3),
  ('krle-8:kristendommen', 's05', 'En elev ser at en medelev trenger hjelp med å bære bøker, og hjelper til. Forklar hvordan handlingen kan være et eksempel på nestekjærlighet.', 'Nestekjærlighet betyr å elske og hjelpe andre mennesker som seg selv. Eleven viser nestekjærlighet ved å hjelpe en medelev som trenger det.', array['Forklarer nestekjærlighet som å hjelpe eller vise omsorg for andre.', 'Knytter forklaringen tydelig til elevens handling i situasjonen.']::text[], 4),
  ('krle-8:kristendommen', 's06', 'Dåp og nattverd er sakramenter i de fleste kristne kirker. Forklar hva et sakrament er, og bruk dåp eller nattverd som eksempel.', 'Et sakrament er en hellig handling. Dåp er et eksempel på et sakrament i de fleste kristne kirker.', array['Forklarer at et sakrament er en hellig handling.', 'Knytter forklaringen til dåp eller nattverd som eksempel.']::text[], 5),
  ('krle-8:kristendommen', 's07', 'Kristne tror at mennesker kan få evig liv gjennom Jesu død og oppstandelse. Forklar hvordan dette henger sammen med frelse.', 'Frelse betyr at mennesker kan få evig liv. Kristne tror at dette er mulig gjennom Jesu død og oppstandelse.', array['Forklarer frelse som muligheten til å få evig liv.', 'Knytter frelsen til Jesu død og oppstandelse.']::text[], 6),
  ('krle-8:kristendommen', 's08', 'En person går på gudstjeneste på søndag, ber Fadervår og leser i Bibelen. Forklar hvordan minst to av disse handlingene er uttrykk for kristen praksis.', 'Kristne samles ofte til gudstjeneste på søndager. Bønn, særlig Fadervår, og lesing i Bibelen er også viktig kristen praksis.', array['Kjenner igjen minst to av handlingene som kristen praksis.', 'Beskriver handlingene riktig, for eksempel at kristne ofte samles til gudstjeneste på søndager eller at bønn og bibellesing er viktig.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-8:islam', 'krle-8', 'islam', 'Islam', 'Profeten Muhammad, Koranen og sunna, sentrale trosideer, de fem søylene, høytider og de ulike retningene i islam.', array[1, 6]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-8:islam', '## Islam i verden
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-8:islam', 'Islam', '«Underkastelse» eller «hengivelse» til Gud. Verdens nest største religion.', 0),
  ('krle-8:islam', 'Muslim', 'En som hengir seg til Gud og følger islam.', 1),
  ('krle-8:islam', 'Muhammad', 'Født i Mekka ca. 570. Regnes som den siste profeten i islam.', 2),
  ('krle-8:islam', 'Hijra', 'Muhammads utvandring fra Mekka til Medina i 622. Starten på den islamske tidsregningen.', 3),
  ('krle-8:islam', 'Koranen', 'Islams hellige skrift, som muslimer tror er Guds ord åpenbart på arabisk.', 4),
  ('krle-8:islam', 'Sura', 'Et kapittel i Koranen. Det finnes 114 suraer.', 5),
  ('krle-8:islam', 'Sunna og hadith', 'Muhammads eksempel og fortellingene om hva han sa og gjorde.', 6),
  ('krle-8:islam', 'Tawhid', 'Troen på Guds enhet – at det bare finnes én Gud.', 7),
  ('krle-8:islam', 'Shahada', 'Trosbekjennelsen: «Det finnes ingen gud utenom Gud, og Muhammad er Guds sendebud.»', 8),
  ('krle-8:islam', 'Salat', 'Bønn fem ganger om dagen, vendt mot Mekka.', 9),
  ('krle-8:islam', 'Zakat', 'Plikten til å gi en del av formuen til fattige.', 10),
  ('krle-8:islam', 'Sawm', 'Faste fra soloppgang til solnedgang i måneden ramadan.', 11),
  ('krle-8:islam', 'Hajj', 'Pilegrimsreisen til Mekka, en plikt for dem som har helse og råd.', 12),
  ('krle-8:islam', 'Sunni og sjia', 'Islams to hovedretninger. De skilte lag i striden om hvem som skulle lede etter Muhammad.', 13),
  ('krle-8:islam', 'Id al-fitr', 'Høytiden som avslutter fasten i ramadan.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-8:islam', 'q01', 'flervalg', 'Hva betyr ordet islam?', array['Fred på jorden', 'Den rette vei', 'Underkastelse eller hengivelse til Gud', 'Profetens lære']::text[], 2, 'En muslim er en som hengir seg til Gud.', true, true, 0),
  ('krle-8:islam', 'q02', 'flervalg', 'Hvor ble Muhammad født?', array['Mekka', 'Medina', 'Jerusalem', 'Kairo']::text[], 0, 'Mekka er i dag islams helligste by.', true, true, 1),
  ('krle-8:islam', 'q03', 'flervalg', 'Hva er hijra?', array['Pilegrimsreisen til Mekka', 'Fasten i ramadan', 'Bønnen fem ganger om dagen', 'Muhammads utvandring fra Mekka til Medina i 622']::text[], 3, 'Den islamske kalenderen teller år fra hijra.', true, true, 2),
  ('krle-8:islam', 'q04', 'flervalg', 'Hva er Koranen for muslimer?', array['En samling fortellinger om Muhammad', 'Guds ord slik det ble åpenbart for Muhammad', 'En lovbok skrevet av kalifene', 'En bønnebok for høytidene']::text[], 1, 'Fortellingene om Muhammad kalles hadith og er ikke en del av Koranen.', true, true, 3),
  ('krle-8:islam', 'q05', 'flervalg', 'Hvilken søyle handler om å gi til fattige?', array['Salat', 'Zakat', 'Hajj', 'Shahada']::text[], 1, 'Zakat er en fast andel av formuen som gis bort hvert år.', true, true, 4),
  ('krle-8:islam', 'q06', 'flervalg', 'I hvilken måned faster muslimer?', array['Muharram', 'Shawwal', 'Dhul-hijja', 'Ramadan']::text[], 3, 'Muslimer faster fra soloppgang til solnedgang i hele ramadan.', true, true, 5),
  ('krle-8:islam', 'q07', 'flervalg', 'Hva er tawhid?', array['Troen på Guds enhet', 'Den islamske kalenderen', 'En type moské', 'Et høytidsmåltid']::text[], 0, 'Tawhid er kjernen i islamsk tro.', true, true, 6),
  ('krle-8:islam', 'q08', 'flervalg', 'Hva var den opprinnelige uenigheten mellom sunni- og sjiamuslimer?', array['Hvilket språk Koranen skal leses på', 'Om man skal be tre eller fem ganger', 'Hvem som skulle lede muslimene etter Muhammad', 'Om det finnes én Gud']::text[], 2, 'Sjiamuslimene mente at Ali og etterkommerne hans skulle lede.', true, true, 7),
  ('krle-8:islam', 'q09', 'flervalg', 'Hvilket land har flest muslimer?', array['Saudi-Arabia', 'Egypt', 'Tyrkia', 'Indonesia']::text[], 3, 'De fleste muslimer bor i Asia, ikke i Midtøsten.', true, false, 8),
  ('krle-8:islam', 'q10', 'flervalg', 'Hvorfor kalles islam en abrahamittisk religion?', array['Fordi Abraham regnes som profet, slik som i jødedom og kristendom', 'Fordi Abraham skrev Koranen', 'Fordi Abraham var den siste profeten', 'Fordi Abraham grunnla Mekka']::text[], 0, 'De tre religionene har felles røtter og deler mange profeter.', true, false, 9),
  ('krle-8:islam', 'm01', 'sant-usant', 'Muslimer regner Jesus (Isa) som en profet.', array['Sant', 'Usant']::text[], 0, 'Jesus er en viktig profet i islam, men ikke Guds sønn.', false, true, 10),
  ('krle-8:islam', 'm02', 'sant-usant', 'De fleste muslimer i verden er arabere.', array['Sant', 'Usant']::text[], 1, 'Bare omtrent én av fem muslimer er araber.', false, true, 11),
  ('krle-8:islam', 'm03', 'sant-usant', 'Hajj er en plikt for alle muslimer som har helse og råd til det.', array['Sant', 'Usant']::text[], 0, 'Pilegrimsreisen skal gjøres minst én gang i livet.', false, true, 12),
  ('krle-8:islam', 'm04', 'sant-usant', 'Sjiamuslimer er i flertall i Saudi-Arabia.', array['Sant', 'Usant']::text[], 1, 'Saudi-Arabia har sunnimuslimsk flertall. Sjiamuslimer er i flertall i blant annet Iran og Irak.', false, true, 13),
  ('krle-8:islam', 'm05', 'flervalg', 'Hvilken høytid avslutter ramadan?', array['Id al-adha', 'Id al-fitr', 'Ashura', 'Mawlid']::text[], 1, 'Id al-fitr feires med bønn, gaver og festmåltider.', false, true, 14),
  ('krle-8:islam', 'm06', 'flervalg', 'Hva kalles den som leder bønnen i moskeen?', array['Imam', 'Kalif', 'Mufti', 'Sultan']::text[], 0, 'Imamen leder bønnen og holder ofte fredagspreken.', false, true, 15),
  ('krle-8:islam', 'm07', 'flervalg', 'Hva er sufisme?', array['En lovskole', 'En type moské', 'En tidsregning', 'En mystisk retning som søker nærhet til Gud']::text[], 3, 'Sufier bruker blant annet meditasjon, musikk og dans.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-8:islam', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-8:islam', 's01', 'Ifølge islamsk tradisjon, hvordan og når fikk Muhammad sin første åpenbaring?', 'Muhammad fikk den første åpenbaringen fra Gud gjennom engelen Jibril i år 610.', array['Får fram at åpenbaringen kom fra Gud gjennom Jibril.', 'Oppgir år 610.']::text[], 0),
  ('krle-8:islam', 's02', 'Forklar hvordan sunna og hadith henger sammen, og hvilken betydning de har for muslimer.', 'Sunna er Muhammads eksempel på hvordan man skal leve. Eksempelet er fortalt i hadith-samlingene og er en viktig rettesnor for muslimer.', array['Forklarer at sunna handler om Muhammads eksempel.', 'Forklarer at hadith forteller om eksempelet, eller at sunna er en rettesnor for hvordan muslimer skal leve.']::text[], 1),
  ('krle-8:islam', 's03', 'Sammenlign shahada og salat: Hva gjør en muslim i hver av disse to søylene?', 'I shahada sier muslimen trosbekjennelsen om Gud og Muhammad. Salat er bønn fem ganger om dagen, vendt mot Mekka.', array['Beskriver shahada som trosbekjennelsen om Gud og Muhammad.', 'Beskriver salat som bønn fem ganger om dagen vendt mot Mekka.']::text[], 2),
  ('krle-8:islam', 's04', 'Amina har ikke helse til å reise til Mekka. Forklar hva dette betyr for plikten hennes til å gjennomføre hajj.', 'Hajj er en plikt for muslimer som har helse og råd til å gjennomføre reisen. Siden Amina ikke har helse til det, er hun ikke forpliktet til å dra.', array['Får fram at hajj er en plikt bare for dem som har helse og råd.', 'Konkluderer med at Amina ikke er forpliktet til å dra når hun mangler helse til reisen.']::text[], 3),
  ('krle-8:islam', 's05', 'Forklar hvordan id al-fitr henger sammen med fasten i ramadan.', 'Id al-fitr er høytiden som avslutter ramadan. Den kommer etter perioden der muslimer faster fra soloppgang til solnedgang.', array['Får fram at id al-fitr markerer slutten på ramadan.', 'Knytter ramadan til fasten.']::text[], 4),
  ('krle-8:islam', 's06', 'Beskriv hvordan fredagsbønnen ofte foregår, og hvilken rolle imamen kan ha.', 'Muslimer samles i moskeen til fredagsbønn. Bønnen ledes ofte av en imam.', array['Får fram at muslimer samles i moskeen til fredagsbønn.', 'Får fram at imamen ofte leder bønnen.']::text[], 5),
  ('krle-8:islam', 's07', 'Hva kjennetegner sufisme, og hvordan henger denne retningen sammen med sunni og sjia?', 'Sufisme er en mystisk retning som søker nærhet til Gud gjennom blant annet meditasjon, musikk og dans. Den finnes både blant sunnimuslimer og sjiamuslimer.', array['Forklarer at sufisme søker nærhet til Gud, gjerne gjennom meditasjon, musikk eller dans.', 'Får fram at sufisme finnes både blant sunni- og sjiamuslimer.']::text[], 6),
  ('krle-8:islam', 's08', 'En elev tror at de fleste muslimer er arabere. Bruk opplysningene om andelen arabere og landet med flest muslimer til å rette på påstanden.', 'Bare omtrent én av fem muslimer er arabere, så de fleste muslimer er ikke arabere. Indonesia er landet med flest muslimer.', array['Får fram at bare omtrent én av fem muslimer er arabere.', 'Nevner Indonesia som landet med flest muslimer.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-8:jodedommen', 'krle-8', 'jodedommen', 'Jødedommen', 'Pakten med Gud, de hellige skriftene, tro og praksis, høytidene og de ulike retningene i jødedommen, og jødenes historie i verden og i Norge.', array[1, 6]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-8:jodedommen', '## Et folk og en religion
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-8:jodedommen', 'Jødedommen', 'Den eldste av de abrahamittiske religionene. Rundt 15 millioner jøder i verden.', 0),
  ('krle-8:jodedommen', 'Pakten', 'Avtalen mellom Gud og det jødiske folket, først inngått med Abraham.', 1),
  ('krle-8:jodedommen', 'Moses', 'Førte israelittene ut av Egypt og fikk loven på Sinai.', 2),
  ('krle-8:jodedommen', 'De ti bud', 'Grunnleggende regler for forholdet til Gud og til andre mennesker.', 3),
  ('krle-8:jodedommen', 'Tanak', 'Den hebraiske bibelen: Toraen, Profetene og Skriftene.', 4),
  ('krle-8:jodedommen', 'Toraen', 'De fem Mosebøkene, den viktigste delen av Tanak.', 5),
  ('krle-8:jodedommen', 'Talmud', 'Samling av rabbinernes tolkninger og diskusjoner av loven.', 6),
  ('krle-8:jodedommen', 'Shema', 'Den viktigste jødiske bønnen: «Hør, Israel! Herren er vår Gud, Herren er én.»', 7),
  ('krle-8:jodedommen', 'Sabbat', 'Ukens hviledag, fra fredag kveld til lørdag kveld.', 8),
  ('krle-8:jodedommen', 'Synagoge', 'Jødenes sted for bønn, lesing og undervisning.', 9),
  ('krle-8:jodedommen', 'Kosher', 'Mat som følger de jødiske matreglene.', 10),
  ('krle-8:jodedommen', 'Bar og bat mitsva', 'Overgangsrite der gutter (13) og jenter (12–13) blir religiøst myndige.', 11),
  ('krle-8:jodedommen', 'Pesach', 'Høytid til minne om utgangen fra Egypt.', 12),
  ('krle-8:jodedommen', 'Jom kippur', 'Forsoningsdagen, årets helligste dag, med faste og bønn.', 13),
  ('krle-8:jodedommen', 'Diaspora', 'At jødene har levd spredt over hele verden, særlig etter år 70.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-8:jodedommen', 'q01', 'flervalg', 'Hvem inngikk ifølge jødedommen den første pakten med Gud?', array['Moses', 'Abraham', 'David', 'Salomo']::text[], 1, 'Abraham regnes som stamfar for det jødiske folket.', true, true, 0),
  ('krle-8:jodedommen', 'q02', 'flervalg', 'Hva er Toraen?', array['En bønn', 'En høytid', 'En synagoge', 'De fem Mosebøkene']::text[], 3, 'Toraen er den viktigste delen av de hellige skriftene.', true, true, 1),
  ('krle-8:jodedommen', 'q03', 'flervalg', 'Når er sabbaten?', array['Fra fredag kveld til lørdag kveld', 'Hele søndagen', 'Fra fredag morgen til fredag kveld', 'Fra lørdag kveld til søndag kveld']::text[], 0, 'I jødisk tradisjon begynner døgnet ved solnedgang.', true, true, 2),
  ('krle-8:jodedommen', 'q04', 'flervalg', 'Hva minnes jødene under pesach?', array['Ødeleggelsen av tempelet', 'Opprettelsen av Israel', 'Utgangen fra Egypt', 'Skapelsen av verden']::text[], 2, 'Under pesachmåltidet fortelles historien om hvordan Gud befridde folket.', true, true, 3),
  ('krle-8:jodedommen', 'q05', 'flervalg', 'Hva er Talmud?', array['Den første Mosebok', 'En lysestake', 'Det jødiske nyttåret', 'En samling tolkninger og diskusjoner av loven']::text[], 3, 'Talmud viser hvordan loven kan forstås og brukes i hverdagen.', true, true, 4),
  ('krle-8:jodedommen', 'q06', 'flervalg', 'Hva betyr det at mat er kosher?', array['At den er økologisk', 'At den følger de jødiske matreglene', 'At den er laget i Israel', 'At den er vegetarisk']::text[], 1, 'Reglene gjelder blant annet hvilke dyr man kan spise, og at kjøtt og melk holdes adskilt.', true, true, 5),
  ('krle-8:jodedommen', 'q07', 'flervalg', 'Hva er diasporaen?', array['En jødisk høytid', 'Den jødiske kalenderen', 'At jødene har levd spredt over hele verden', 'Et jødisk skrift']::text[], 2, 'Etter år 70 bodde de fleste jøder utenfor Israel.', true, true, 6),
  ('krle-8:jodedommen', 'q08', 'flervalg', 'Hvordan begynner bønnen Shema?', array['«Hør, Israel! Herren er vår Gud, Herren er én»', '«Fader vår, du som er i himmelen»', '«Det finnes ingen gud utenom Gud»', '«Herren er min hyrde»']::text[], 0, 'Bønnen uttrykker troen på én Gud.', true, true, 7),
  ('krle-8:jodedommen', 'q09', 'flervalg', 'Hvilken retning mener at loven kan tolkes på nytt i hver tid?', array['Ortodoks jødedom', 'Reformjødedom', 'Hasidisme', 'Alle retninger']::text[], 1, 'Ortodokse jøder mener at loven ikke skal endres.', true, false, 8),
  ('krle-8:jodedommen', 'q10', 'flervalg', 'Hva er jom kippur?', array['Den jødiske lysfesten', 'Det jødiske nyttåret', 'Forsoningsdagen, årets helligste dag', 'Minnedagen for Holocaust']::text[], 2, 'På jom kippur faster man og ber om tilgivelse.', true, false, 9),
  ('krle-8:jodedommen', 'm01', 'sant-usant', 'De fleste jøder i verden bor i Israel og USA.', array['Sant', 'Usant']::text[], 0, 'Omtrent åtte av ti jøder bor i ett av disse to landene.', false, true, 10),
  ('krle-8:jodedommen', 'm02', 'sant-usant', 'Alle jøder er religiøse.', array['Sant', 'Usant']::text[], 1, 'Mange jøder er sekulære, men føler tilhørighet til folket og tradisjonene.', false, true, 11),
  ('krle-8:jodedommen', 'm03', 'sant-usant', 'Jøder var utestengt fra Norge i Grunnloven fram til 1851.', array['Sant', 'Usant']::text[], 0, 'Henrik Wergeland kjempet for å fjerne forbudet.', false, true, 12),
  ('krle-8:jodedommen', 'm04', 'sant-usant', 'Hanukka er en høytid om sommeren.', array['Sant', 'Usant']::text[], 1, 'Hanukka er en lysfest som feires i desember.', false, true, 13),
  ('krle-8:jodedommen', 'm05', 'flervalg', 'Hvor gammel er en gutt ved bar mitsva?', array['10 år', '13 år', '15 år', '18 år']::text[], 1, 'Fra da av regnes gutten som ansvarlig for å følge loven.', false, true, 14),
  ('krle-8:jodedommen', 'm06', 'flervalg', 'Hva kalles læreren og lederen i en synagoge?', array['Imam', 'Prest', 'Rabbiner', 'Munk']::text[], 2, 'Rabbiner betyr «min lærer».', false, true, 15),
  ('krle-8:jodedommen', 'm07', 'flervalg', 'Hva skjedde med tempelet i Jerusalem i år 70?', array['Det ble ødelagt av romerne', 'Det ble bygd', 'Det ble flyttet til Roma', 'Det ble solgt']::text[], 0, 'Klagemuren i Jerusalem er en rest av tempelområdet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-8:jodedommen', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-8:jodedommen', 's01', 'Jødisk tilhørighet kan handle både om religion og om å være del av et folk. Forklar hva disse to sidene ved å være jøde betyr.', 'Det kan bety at man følger jødisk religion, og at man tilhører et folk med felles historie og kultur. Noen jøder er ikke religiøse, men holder likevel på tradisjonene.', array['Forklarer både religiøs tilhørighet og tilhørighet til et folk med felles historie eller kultur.', 'Viser at man kan holde på jødiske tradisjoner uten å være religiøs.']::text[], 0),
  ('krle-8:jodedommen', 's02', 'Moses førte israelittene ut av slaveriet i Egypt og fikk loven fra Gud på Sinai. Forklar hvordan loven henger sammen med pakten mellom Gud og det jødiske folket.', 'Ifølge jødedommen fikk Moses loven fra Gud på Sinai. Å følge loven er å leve i pakten mellom Gud og det jødiske folket.', array['Knytter loven til Moses og Sinai.', 'Forklarer at det å følge loven er en måte å leve i pakten med Gud på.']::text[], 1),
  ('krle-8:jodedommen', 's03', 'Sammenlign ortodokse, konservative og reformjødiske retninger i synet på jødisk lov.', 'Ortodokse jøder følger loven strengt og mener den er gitt av Gud én gang for alle. Konservative følger mye av tradisjonen, men tilpasser den noe, mens reformjøder mener loven kan tolkes på nytt i hver tid.', array['Får fram at ortodokse følger loven strengt og ser den som gitt én gang for alle.', 'Skiller mellom konservatives tilpasning av tradisjonen og reformjøders syn på ny tolkning.']::text[], 2),
  ('krle-8:jodedommen', 's04', 'En familie serverer kjøtt og melk sammen i et måltid. Hva må familien endre for at måltidet skal følge de kosher-reglene som er beskrevet her?', 'Familien må holde kjøtt og melk adskilt. De kan for eksempel servere kjøtt uten melk i samme måltid.', array['Forklarer at kjøtt og melk ikke skal blandes eller serveres sammen.', 'Foreslår en endring som faktisk holder kjøtt og melk adskilt.']::text[], 3),
  ('krle-8:jodedommen', 's05', 'Miriam fyller 12 år. Hvilken overgangsrite kan hun markere, og hva betyr den?', 'Hun kan markere bat mitsva. Da blir hun religiøst myndig.', array['Identifiserer bat mitsva som riten for jenter.', 'Forklarer at riten markerer at hun blir religiøst myndig.']::text[], 4),
  ('krle-8:jodedommen', 's06', 'Hvorfor oppstod diasporaen, og hva betyr ordet i jødisk historie?', 'Etter at romerne ødela tempelet i Jerusalem i år 70, spredte jødene seg over hele verden. At jødene har levd spredt slik, kalles diasporaen.', array['Knytter spredningen til at romerne ødela tempelet i Jerusalem.', 'Forklarer diaspora som at jødene lever spredt over hele verden.']::text[], 5),
  ('krle-8:jodedommen', 's07', 'En ny elev spør hva man gjør i en synagoge, og hvem rabbineren er. Forklar begge deler.', 'I synagogen kan man be, lese og få undervisning. Rabbineren er lærer og leder.', array['Nevner bønn og minst én av aktivitetene lesing eller undervisning.', 'Forklarer at rabbineren har en rolle som lærer eller leder.']::text[], 6),
  ('krle-8:jodedommen', 's08', 'Sammenlign Rosh hashana og Hanukka. Hva markerer hver av høytidene?', 'Rosh hashana er det jødiske nyttåret. Hanukka er en lysfest i desember.', array['Knytter Rosh hashana til det jødiske nyttåret.', 'Knytter Hanukka til en lysfest i desember.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-8:livssynshumanisme', 'krle-8', 'livssynshumanisme', 'Livssynshumanisme og ikke-religiøse livssyn', 'Hva et livssyn er, sentrale ideer i livssynshumanismen og hvor de kommer fra, Human-Etisk Forbund og andre ikke-religiøse begreper som ateisme og agnostisisme.', array[3, 6]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-8:livssynshumanisme', '## Hva er et livssyn?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-8:livssynshumanisme', 'Livssyn', 'Grunnleggende oppfatning av mennesket, livet og hva som er rett og galt.', 0),
  ('krle-8:livssynshumanisme', 'Ikke-religiøst livssyn', 'Livssyn som ikke bygger på tro på gud eller guder.', 1),
  ('krle-8:livssynshumanisme', 'Livssynshumanisme', 'Livssyn som setter mennesket, fornuften og menneskeverdet i sentrum.', 2),
  ('krle-8:livssynshumanisme', 'Menneskeverd', 'At alle mennesker har like stor verdi.', 3),
  ('krle-8:livssynshumanisme', 'Den gylne regel', 'Gjør mot andre det du vil at de skal gjøre mot deg.', 4),
  ('krle-8:livssynshumanisme', 'Fornuft og vitenskap', 'Humanister mener kunnskap bør bygge på undersøkelser og kritisk tenkning.', 5),
  ('krle-8:livssynshumanisme', 'Human-Etisk Forbund', 'Norsk organisasjon for livssynshumanister, stiftet i 1956.', 6),
  ('krle-8:livssynshumanisme', 'Humanistisk konfirmasjon', 'Ikke-religiøs konfirmasjon, arrangert første gang i Norge i 1951.', 7),
  ('krle-8:livssynshumanisme', 'Humanistiske seremonier', 'Navnefest, konfirmasjon, vigsel og gravferd uten religiøst innhold.', 8),
  ('krle-8:livssynshumanisme', 'Protagoras', 'Gresk filosof som sa at «mennesket er alle tings mål».', 9),
  ('krle-8:livssynshumanisme', 'Opplysningstiden', '1700-tallet, da filosofer oppfordret folk til å bruke sin egen fornuft.', 10),
  ('krle-8:livssynshumanisme', 'Ateisme', 'Overbevisningen om at det ikke finnes noen gud.', 11),
  ('krle-8:livssynshumanisme', 'Agnostisisme', 'Synet at vi ikke kan vite om det finnes en gud.', 12),
  ('krle-8:livssynshumanisme', 'Sekularisering', 'At religion får mindre betydning i samfunnet og for den enkelte.', 13),
  ('krle-8:livssynshumanisme', 'Livssynsfrihet', 'Retten til å velge livssyn selv.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-8:livssynshumanisme', 'q01', 'flervalg', 'Hva er et livssyn?', array['En type religion', 'En politisk ideologi', 'En vitenskapelig teori', 'En grunnleggende oppfatning av mennesket, livet og hva som er rett og galt']::text[], 3, 'Både religioner og ikke-religiøse livssyn er livssyn.', true, true, 0),
  ('krle-8:livssynshumanisme', 'q02', 'flervalg', 'Hva står i sentrum i livssynshumanismen?', array['Mennesket', 'Gud', 'Naturen', 'Staten']::text[], 0, 'Humanister mener mennesker selv har ansvar for å skape et godt liv.', true, true, 1),
  ('krle-8:livssynshumanisme', 'q03', 'flervalg', 'Hva bygger humanister etikken sin på?', array['Hellige skrifter', 'Kongens befalinger', 'Empati, fornuft og konsekvenser for andre', 'Tradisjon alene']::text[], 2, 'Humanister mener at vi kan vite hva som er godt uten å vise til en gud.', true, true, 2),
  ('krle-8:livssynshumanisme', 'q04', 'flervalg', 'Når ble Human-Etisk Forbund stiftet?', array['1814', '1956', '1905', '2002']::text[], 1, 'Forbundet er i dag et av de største livssynssamfunnene i Norge.', true, true, 3),
  ('krle-8:livssynshumanisme', 'q05', 'flervalg', 'Hva er ateisme?', array['Overbevisningen om at det ikke finnes noen gud', 'Synet at man ikke kan vite om det finnes en gud', 'Troen på mange guder', 'Troen på gjenfødelse']::text[], 0, 'Det andre alternativet beskriver agnostisisme.', true, true, 4),
  ('krle-8:livssynshumanisme', 'q06', 'flervalg', 'Hva er agnostisisme?', array['Troen på én Gud', 'Troen på at alt er forutbestemt', 'Synet at vi ikke kan vite om det finnes en gud', 'Motstand mot all religion']::text[], 2, 'Ordet kommer fra gresk og betyr «uten kunnskap».', true, true, 5),
  ('krle-8:livssynshumanisme', 'q07', 'flervalg', 'Hvem sa at «mennesket er alle tings mål»?', array['Martin Luther', 'Charles Darwin', 'Buddha', 'Protagoras']::text[], 3, 'Protagoras levde i antikkens Hellas.', true, true, 6),
  ('krle-8:livssynshumanisme', 'q08', 'flervalg', 'Hva er sekularisering?', array['At flere blir religiøse', 'At religion får mindre betydning i samfunnet', 'At staten får en offisiell religion', 'At det bygges flere kirker']::text[], 1, 'I Norge har religion fått mindre betydning for mange de siste tiårene.', true, true, 7),
  ('krle-8:livssynshumanisme', 'q09', 'flervalg', 'Hvilken seremoni tilbyr Human-Etisk Forbund?', array['Dåp', 'Nattverd', 'Bar mitsva', 'Humanistisk konfirmasjon']::text[], 3, 'Forbundet tilbyr også navnefest, vigsel og gravferd.', true, false, 8),
  ('krle-8:livssynshumanisme', 'q10', 'flervalg', 'Hva mener humanister om livssynsfrihet?', array['At alle skal kunne velge livssyn selv, og at staten bør behandle alle livssyn likt', 'At alle bør bli humanister', 'At religion bør forbys', 'At staten skal bestemme livssyn']::text[], 0, 'Livssynsfrihet er også en menneskerettighet.', true, false, 9),
  ('krle-8:livssynshumanisme', 'm01', 'sant-usant', 'Livssynshumanister mener at kunnskap bør bygge på fornuft og vitenskap.', array['Sant', 'Usant']::text[], 0, 'Kritisk tenkning og vilje til å endre mening er sentrale verdier.', false, true, 10),
  ('krle-8:livssynshumanisme', 'm02', 'sant-usant', 'Livssynshumanisme er en religion med egne guder.', array['Sant', 'Usant']::text[], 1, 'Livssynshumanisme er et ikke-religiøst livssyn.', false, true, 11),
  ('krle-8:livssynshumanisme', 'm03', 'sant-usant', 'Humanistisk konfirmasjon ble arrangert første gang i Norge i 1951.', array['Sant', 'Usant']::text[], 0, 'Det var noen år før Human-Etisk Forbund ble stiftet.', false, true, 12),
  ('krle-8:livssynshumanisme', 'm04', 'sant-usant', 'Man må være medlem av en organisasjon for å ha et livssyn.', array['Sant', 'Usant']::text[], 1, 'Et livssyn kan være personlig og uavhengig av organisasjoner.', false, true, 13),
  ('krle-8:livssynshumanisme', 'm05', 'flervalg', 'Hva sier den gylne regel?', array['Gjør mot andre det du vil at de skal gjøre mot deg', 'Tenk alltid på deg selv først', 'Følg alltid loven', 'Gi bort alt du eier']::text[], 0, 'Varianter av regelen finnes i mange religioner og livssyn.', false, true, 14),
  ('krle-8:livssynshumanisme', 'm06', 'flervalg', 'I hvilken periode oppfordret filosofer folk til å bruke sin egen fornuft?', array['Vikingtiden', 'Middelalderen', 'Opplysningstiden', 'Steinalderen']::text[], 2, 'Opplysningstiden var på 1700-tallet.', false, true, 15),
  ('krle-8:livssynshumanisme', 'm07', 'flervalg', 'Hva mener de fleste humanister om livet etter døden?', array['At man blir gjenfødt', 'At vi bare har ett liv', 'At alle kommer til himmelen', 'At sjelen lever videre i naturen']::text[], 1, 'Derfor legger humanister vekt på å gjøre dette livet meningsfullt.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-8:livssynshumanisme', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-8:livssynshumanisme', 's01', 'Hvorfor mener livssynshumanister at vi bør være villige til å endre mening når vi får ny kunnskap?', 'Humanister mener at kunnskap bør bygge på undersøkelser, erfaring og kritisk tenkning. Ny kunnskap kan gi bedre grunn til å endre det vi tror.', array['Knytter kunnskap til undersøkelser, erfaring eller kritisk tenkning.', 'Forklarer at ny kunnskap kan gi grunn til å endre mening.']::text[], 0),
  ('krle-8:livssynshumanisme', 's02', 'Hva er forskjellen mellom ateisme og agnostisisme?', 'En ateist er overbevist om at det ikke finnes noen gud. En agnostiker mener at vi ikke kan vite om det finnes en gud.', array['Forklarer ateisme som en overbevisning om at det ikke finnes noen gud.', 'Forklarer agnostisisme som synet at vi ikke kan vite om det finnes en gud.']::text[], 1),
  ('krle-8:livssynshumanisme', 's03', 'En elev er ofte alene i friminuttene. Bruk den gylne regel til å forklare hva en medelev kan gjøre, og hvorfor det passer med regelen.', 'Medeleven kan invitere eleven til å være med, fordi en selv gjerne ville blitt invitert hvis en var alene. Det følger den gylne regel om å gjøre mot andre det en selv ønsker at de skal gjøre mot en.', array['Foreslår en handling som inkluderer eller støtter eleven.', 'Begrunner handlingen med at en selv ville ønsket tilsvarende behandling.']::text[], 2),
  ('krle-8:livssynshumanisme', 's04', 'En gruppe vil ikke la en elev være med fordi eleven har et annet livssyn. Hvordan kan tanken om menneskeverd brukes til å forklare hvorfor dette er urettferdig?', 'Menneskeverd betyr at alle mennesker har like stor verdi. Derfor bør eleven møtes med respekt og ikke holdes utenfor på grunn av livssynet sitt.', array['Forklarer at alle mennesker har like stor verdi.', 'Knytter dette til at eleven bør behandles med respekt eller ikke utestenges på grunn av livssynet.']::text[], 3),
  ('krle-8:livssynshumanisme', 's05', 'Mange humanister mener at vi bare har ett liv. Hvordan henger dette sammen med at det er viktig å gjøre livet meningsfullt?', 'Hvis vi bare har ett liv, mener mange humanister at det er viktig å bruke det godt og gjøre det meningsfullt. Dette livet får særlig betydning når det ikke ventes et nytt liv etterpå.', array['Får fram at mange humanister mener vi bare har ett liv.', 'Forklarer at dette gjør det viktig å gjøre livet meningsfullt eller bruke det godt.']::text[], 4),
  ('krle-8:livssynshumanisme', 's06', 'Under opplysningstiden oppfordret filosofer folk til å bruke sin egen fornuft. Forklar hvordan dette henger sammen med livssynshumanismens vekt på fornuft.', 'Opplysningstidens filosofer mente at folk skulle bruke sin egen fornuft i stedet for å godta autoriteter blindt. Dette passer med livssynshumanismen, som legger vekt på fornuft og kritisk tenkning.', array['Forklarer at folk ble oppfordret til å bruke egen fornuft framfor å godta autoriteter blindt.', 'Knytter dette til humanismens vekt på fornuft eller kritisk tenkning.']::text[], 5),
  ('krle-8:livssynshumanisme', 's07', 'Nora sier at hun ikke er religiøs, men hun er ikke medlem av noe livssynssamfunn. Forklar hvorfor hun likevel kan ha et livssyn.', 'Et livssyn er en grunnleggende oppfatning av mennesket, livet og hva som er rett og galt. Det kan være personlig og trenger ikke være knyttet til en organisasjon.', array['Forklarer at et livssyn handler om grunnleggende oppfatninger av mennesket, livet eller rett og galt.', 'Får fram at et livssyn kan være personlig og ikke krever medlemskap i en organisasjon.']::text[], 6),
  ('krle-8:livssynshumanisme', 's08', 'Sammenlign et religiøst og et ikke-religiøst livssyn: Hva bygger de på når det gjelder tro på guddommelige makter?', 'Et religiøst livssyn bygger på tro på noe guddommelig. Et ikke-religiøst livssyn bygger ikke på tro på gud eller guder, men på menneskelige erfaringer, fornuft og kunnskap.', array['Sier at religiøse livssyn bygger på tro på noe guddommelig.', 'Sier at ikke-religiøse livssyn ikke bygger på tro på gud eller guder.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-8:samisk-religion-og-urfolk', 'krle-8', 'samisk-religion-og-urfolk', 'Samisk religion og urfolks livssyn', 'Den førkristne samiske religionen, kristningen av samene, samisk religion og kultur i dag, og fellestrekk ved religionene til urfolk i andre deler av verden.', array[5]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-8:samisk-religion-og-urfolk', '## Samisk førkristen religion
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-8:samisk-religion-og-urfolk', 'Førkristen samisk religion', 'Samenes religion før kristningen, tett knyttet til naturen.', 0),
  ('krle-8:samisk-religion-og-urfolk', 'Besjelet natur', 'Troen på at dyr, planter, fjell og elver har sjel eller ånd.', 1),
  ('krle-8:samisk-religion-og-urfolk', 'Beaivi', 'Sola, en viktig makt i samisk religion.', 2),
  ('krle-8:samisk-religion-og-urfolk', 'Horagalles', 'Tordenguden i samisk religion.', 3),
  ('krle-8:samisk-religion-og-urfolk', 'Máttaráhkká', 'Urmoren, som sammen med døtrene hjalp ved fødsler og beskyttet hjemmet.', 4),
  ('krle-8:samisk-religion-og-urfolk', 'Sieidi', 'Hellig stein eller sted der det ble gitt offergaver.', 5),
  ('krle-8:samisk-religion-og-urfolk', 'Noaidi', 'Samisk religiøs spesialist som i transe kunne reise til åndeverdenen.', 6),
  ('krle-8:samisk-religion-og-urfolk', 'Goavddis', 'Runebommen, noaidens tromme med tegninger av guder, mennesker og dyr.', 7),
  ('krle-8:samisk-religion-og-urfolk', 'Joik', 'Samisk sangform som også hadde religiøs betydning.', 8),
  ('krle-8:samisk-religion-og-urfolk', 'Thomas von Westen', 'Prest som ledet misjonen blant samene fra 1716.', 9),
  ('krle-8:samisk-religion-og-urfolk', 'Læstadianismen', 'Kristen vekkelsesbevegelse fra 1800-tallet med sterk stilling blant samer og kvener.', 10),
  ('krle-8:samisk-religion-og-urfolk', 'Urfolk', 'Folk som bodde i et område før dagens statsgrenser. Rundt 476 millioner i verden.', 11),
  ('krle-8:samisk-religion-og-urfolk', 'Sjaman', 'Person som formidler mellom mennesker og åndeverdenen.', 12),
  ('krle-8:samisk-religion-og-urfolk', 'Drømmetiden', 'Aboriginernes fortellinger om hvordan forfedrene skapte verden og landskapet.', 13),
  ('krle-8:samisk-religion-og-urfolk', 'Muntlig tradisjon', 'Kunnskap som føres videre gjennom fortellinger, sang og ritualer.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-8:samisk-religion-og-urfolk', 'q01', 'flervalg', 'Hva er en sieidi?', array['En samisk tromme', 'En samisk sang', 'En hellig stein eller et hellig sted der man ga offergaver', 'En samisk prest']::text[], 2, 'Ved sieidien ofret man for å få god fangst eller beskyttelse.', true, true, 0),
  ('krle-8:samisk-religion-og-urfolk', 'q02', 'flervalg', 'Hva var en noaidi?', array['En reineier', 'En religiøs spesialist som kunne reise til åndeverdenen i transe', 'En misjonær', 'En samisk høvding']::text[], 1, 'Noaiden kunne helbrede, hjelpe og hente kunnskap fra åndeverdenen.', true, true, 1),
  ('krle-8:samisk-religion-og-urfolk', 'q03', 'flervalg', 'Hva betyr det at naturen var besjelet?', array['At dyr, planter og landskap hadde sjel eller ånd', 'At naturen var farlig', 'At naturen var skapt av mennesker', 'At bare mennesker hadde sjel']::text[], 0, 'Derfor måtte mennesket leve i balanse med naturen.', true, true, 2),
  ('krle-8:samisk-religion-og-urfolk', 'q04', 'flervalg', 'Hva skjedde med mange runebommer under misjonen?', array['De ble brukt i kirkene', 'De ble solgt til turister', 'De ble gitt til Sametinget', 'De ble tatt og brent']::text[], 3, 'Misjonærene så på runebommene som redskaper for hedensk religion.', true, true, 3),
  ('krle-8:samisk-religion-og-urfolk', 'q05', 'flervalg', 'Hvilken vekkelsesbevegelse fikk stor oppslutning blant samer på 1800-tallet?', array['Pinsebevegelsen', 'Haugianismen', 'Læstadianismen', 'Metodismen']::text[], 2, 'Bevegelsen er oppkalt etter presten Lars Levi Læstadius.', true, true, 4),
  ('krle-8:samisk-religion-og-urfolk', 'q06', 'flervalg', 'Hvem ledet misjonen blant samene fra 1716?', array['Thomas von Westen', 'Martin Luther', 'Lars Levi Læstadius', 'Hans Nielsen Hauge']::text[], 0, 'Han ble kalt «samenes apostel».', true, true, 5),
  ('krle-8:samisk-religion-og-urfolk', 'q07', 'flervalg', 'Hva er et vanlig trekk ved mange urfolksreligioner?', array['Én hellig bok', 'At alle har prester', 'Tro på at verden snart går under', 'At naturen er hellig og forfedrene viktige']::text[], 3, 'Urfolksreligioner er ofte tett knyttet til landet folket lever på.', true, true, 6),
  ('krle-8:samisk-religion-og-urfolk', 'q08', 'flervalg', 'Hva er Drømmetiden?', array['En samisk høytid', 'Aboriginernes fortellinger om hvordan forfedrene skapte landskapet', 'En indiansk dans', 'En type meditasjon']::text[], 1, 'Fortellingene knytter folket til bestemte steder i landskapet.', true, true, 7),
  ('krle-8:samisk-religion-og-urfolk', 'q09', 'flervalg', 'Hvordan ble joiken sett på under kristningen?', array['Som en del av gudstjenesten', 'Som et skolefag', 'Som syndig', 'Som nasjonalsang']::text[], 2, 'I dag er joiken igjen en viktig del av samisk kultur.', true, false, 8),
  ('krle-8:samisk-religion-og-urfolk', 'q10', 'flervalg', 'Hva gir FNs erklæring om urfolks rettigheter urfolk rett til?', array['Å praktisere og føre videre sine religiøse tradisjoner', 'Å slippe å betale skatt', 'Å ha egen hær', 'Å bestemme over alle land']::text[], 0, 'Erklæringen ble vedtatt i 2007.', true, false, 9),
  ('krle-8:samisk-religion-og-urfolk', 'm01', 'sant-usant', 'De fleste samer i dag er kristne.', array['Sant', 'Usant']::text[], 0, 'Samtidig har interessen for den førkristne tradisjonen økt.', false, true, 10),
  ('krle-8:samisk-religion-og-urfolk', 'm02', 'sant-usant', 'Kunnskapen om førkristen samisk religion bygger bare på samiske bøker fra middelalderen.', array['Sant', 'Usant']::text[], 1, 'Den bygger på muntlig tradisjon, arkeologi og kilder skrevet av misjonærer.', false, true, 11),
  ('krle-8:samisk-religion-og-urfolk', 'm03', 'sant-usant', 'Joik og samiske tradisjoner har fått en ny oppblomstring i vår tid.', array['Sant', 'Usant']::text[], 0, 'Dette er en del av en bredere samisk revitalisering.', false, true, 12),
  ('krle-8:samisk-religion-og-urfolk', 'm04', 'sant-usant', 'Urfolksreligioner føres som regel videre gjennom én hellig bok.', array['Sant', 'Usant']::text[], 1, 'De fleste urfolksreligioner bygger på muntlig tradisjon.', false, true, 13),
  ('krle-8:samisk-religion-og-urfolk', 'm05', 'flervalg', 'Hva er goavddis?', array['En hellig stein', 'En runebomme som noaiden brukte', 'En samisk kofte', 'En reinflokk']::text[], 1, 'Tegningene på trommen viste guder, mennesker og dyr.', false, true, 14),
  ('krle-8:samisk-religion-og-urfolk', 'm06', 'flervalg', 'Hvem var Máttaráhkká?', array['Tordenguden', 'Sola', 'Urmoren', 'En misjonær']::text[], 2, 'Hun og døtrene hennes var knyttet til fødsel og hjem.', false, true, 15),
  ('krle-8:samisk-religion-og-urfolk', 'm07', 'flervalg', 'Hva kalles en som formidler mellom mennesker og åndeverdenen i mange urfolksreligioner?', array['Sjaman', 'Rabbiner', 'Imam', 'Biskop']::text[], 0, 'Hos samene ble denne rollen kalt noaidi.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-8:samisk-religion-og-urfolk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-8:samisk-religion-og-urfolk', 's01', 'I førkristen samisk religion trodde man at dyr, planter, fjell og elver hadde sjel eller ånd. En person vil bruke naturen uten å tenke på hvordan det påvirker andre levende ting. Forklar hvordan dette skiller seg fra det samiske natursynet, og hvordan mennesker ifølge dette synet burde leve.', 'I det samiske natursynet hadde naturen sjel eller ånd, og mennesker måtte leve i balanse med den. Derfor skulle man vise respekt for andre levende ting og naturen.', array['Får fram at naturen ble sett på som besjelet, med sjel eller ånd.', 'Forklarer at mennesker burde leve i balanse med eller vise respekt for naturen.']::text[], 0),
  ('krle-8:samisk-religion-og-urfolk', 's02', 'Sammenlign Beaivi og Horagalles: Hvilken naturkraft var hver av dem knyttet til?', 'Beaivi var knyttet til sola, mens Horagalles var tordenguden.', array['Knytter Beaivi til sola.', 'Knytter Horagalles til torden.']::text[], 1),
  ('krle-8:samisk-religion-og-urfolk', 's03', 'En noaidi brukte en goavddis i religiøse sammenhenger. Forklar hva en goavddis var, og hva den kunne være dekorert med.', 'En goavddis var en runebomme, altså en tromme som noaidien brukte. Den hadde tegninger av guder, mennesker og dyr.', array['Forklarer at goavddis var en runebomme eller tromme brukt av en noaidi.', 'Nevner at den kunne ha tegninger av guder, mennesker og dyr.']::text[], 2),
  ('krle-8:samisk-religion-og-urfolk', 's04', 'Kunnskap om førkristen samisk religion bygger blant annet på muntlig tradisjon, arkeologi og skriftlige kilder fra misjonærer. Forklar hvorfor misjonærenes kilder bør leses kritisk.', 'Misjonærene så ofte den samiske religionen negativt. Derfor kan skildringene deres være farget av synet deres og ikke være nøytrale.', array['Får fram at misjonærene ofte hadde et negativt syn på religionen.', 'Forklarer at dette kan ha påvirket hvordan de beskrev den.']::text[], 3),
  ('krle-8:samisk-religion-og-urfolk', 's05', 'Førkristen samisk religion var tett knyttet til livet som jegere, fiskere og reindriftsutøvere. Forklar en sammenheng mellom disse levemåtene og religionens sterke tilknytning til naturen.', 'Jegere, fiskere og reindriftsutøvere var avhengige av naturen i hverdagen. I religionen ble naturen sett på som besjelet, og mennesker måtte leve i balanse med den.', array['Forklarer at disse levemåtene var avhengige av naturen.', 'Knytter religionens natursyn til at naturen ble sett på som besjelet eller at mennesker skulle leve i balanse med den.']::text[], 4),
  ('krle-8:samisk-religion-og-urfolk', 's06', 'En historiker finner en runebomme med tegninger av guder, mennesker og dyr. Forklar hvilken religiøs spesialist som brukte slike trommer, og hva vedkommende kunne gjøre i transe.', 'En noaidi brukte runebommen. I transe kunne noaiden reise til åndeverdenen for å hjelpe, helbrede eller få kunnskap.', array['Identifiserer noaidien som brukeren av runebommen.', 'Nevner at noaiden i transe kunne reise til åndeverdenen og få kunnskap, hjelpe eller helbrede.']::text[], 5),
  ('krle-8:samisk-religion-og-urfolk', 's07', 'I dag brukes joik igjen i stor grad, og kristendommen i Sápmi har blant annet gudstjenester og salmer på samisk. Forklar hvordan disse to eksemplene viser at samisk kultur og religion kommer til uttrykk i dag.', 'Joik, som også hadde religiøs betydning, brukes igjen. Samiske gudstjenester og salmer viser at kristendommen i Sápmi også har fått samiske uttrykk.', array['Forklarer at joik brukes igjen, og knytter den til samisk tradisjon eller religiøs betydning.', 'Forklarer at gudstjenester eller salmer på samisk er samiske uttrykk innenfor kristendommen.']::text[], 6),
  ('krle-8:samisk-religion-og-urfolk', 's08', 'Et urfolk lærer barn kunnskap gjennom fortellinger, sang og ritualer. Hva kalles denne måten å føre kunnskap videre på, og hvordan hjelper den med å bevare tradisjonene?', 'Dette kalles muntlig tradisjon. Fortellinger, sang og ritualer fører kunnskap videre mellom mennesker og generasjoner.', array['Kaller det muntlig tradisjon.', 'Forklarer at kunnskapen føres videre gjennom fortellinger, sang eller ritualer.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-8:etiske-teorier', 'krle-8', 'etiske-teorier', 'Etiske teorier og dilemmaer', 'Forskjellen på moral og etikk, konsekvensetikk, pliktetikk, dydsetikk og sinnelagsetikk, hvordan teoriene kan brukes på dilemmaer, og hvordan du håndterer uenighet.', array[11, 12]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-8:etiske-teorier', '## Etikk og moral
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-8:etiske-teorier', 'Moral', 'Oppfatninger om rett og galt, og hvordan vi faktisk handler.', 0),
  ('krle-8:etiske-teorier', 'Etikk', 'Systematisk tenkning om moral: hvorfor noe er rett eller galt.', 1),
  ('krle-8:etiske-teorier', 'Konsekvensetikk', 'Handlinger vurderes ut fra følgene de får.', 2),
  ('krle-8:etiske-teorier', 'Utilitarisme', 'Den rette handlingen gir størst mulig lykke for flest mulig.', 3),
  ('krle-8:etiske-teorier', 'Bentham og Mill', 'Engelske filosofer som utviklet utilitarismen.', 4),
  ('krle-8:etiske-teorier', 'Pliktetikk', 'Noen handlinger er rette eller gale i seg selv, uansett følger.', 5),
  ('krle-8:etiske-teorier', 'Immanuel Kant', 'Tysk filosof (1724–1804) kjent for pliktetikken og det kategoriske imperativ.', 6),
  ('krle-8:etiske-teorier', 'Det kategoriske imperativ', 'Handle bare slik at du kan ville at handlingen blir en allmenn lov.', 7),
  ('krle-8:etiske-teorier', 'Mål i seg selv', 'Kants idé om at mennesker aldri bare skal brukes som middel.', 8),
  ('krle-8:etiske-teorier', 'Dydsetikk', 'Etikk som spør hva slags menneske man vil være, og vektlegger gode karaktertrekk.', 9),
  ('krle-8:etiske-teorier', 'Aristoteles', 'Gresk filosof (384–322 f.Kr.) som grunnla dydsetikken.', 10),
  ('krle-8:etiske-teorier', 'Den gylne middelvei', 'En dyd ligger mellom to ytterpunkter, som mot mellom feighet og dumdristighet.', 11),
  ('krle-8:etiske-teorier', 'Sinnelagsetikk', 'Hensikten bak handlingen avgjør om den er god.', 12),
  ('krle-8:etiske-teorier', 'Etisk dilemma', 'Et valg mellom handlinger som alle har gode og dårlige sider.', 13),
  ('krle-8:etiske-teorier', 'Aktiv lytting', 'Å lytte for å forstå den andre, og vise at man har forstått.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-8:etiske-teorier', 'q01', 'flervalg', 'Hva er forskjellen på moral og etikk?', array['Det er ingen forskjell', 'Moral er oppfatninger om rett og galt, etikk er systematisk tenkning om moralen', 'Etikk gjelder bare religion', 'Moral er lover, etikk er regler']::text[], 1, 'Etikk kalles også moralfilosofi.', true, true, 0),
  ('krle-8:etiske-teorier', 'q02', 'flervalg', 'Hva sier utilitarismen?', array['At man alltid skal følge pliktene sine', 'At hensikten er det viktigste', 'At den rette handlingen gir størst mulig lykke for flest mulig', 'At man skal utvikle gode dyder']::text[], 2, 'Utilitarismen er den mest kjente formen for konsekvensetikk.', true, true, 1),
  ('krle-8:etiske-teorier', 'q03', 'flervalg', 'Hvem formulerte det kategoriske imperativ?', array['Immanuel Kant', 'Aristoteles', 'John Stuart Mill', 'Sokrates']::text[], 0, 'Kant er den mest kjente pliktetikeren.', true, true, 2),
  ('krle-8:etiske-teorier', 'q04', 'flervalg', 'Hva er en svakhet ved konsekvensetikk?', array['Den tar ikke hensyn til følger', 'Den er for enkel å bruke', 'Den handler bare om plikter', 'Den kan forsvare urett mot noen få hvis flertallet tjener på det']::text[], 3, 'Derfor mener kritikere at konsekvensetikken ikke verner godt nok om den enkelte.', true, true, 3),
  ('krle-8:etiske-teorier', 'q05', 'flervalg', 'Hva betyr det å behandle mennesker som et mål i seg selv?', array['Å konkurrere med dem', 'At mennesker har verdi i seg selv og ikke bare skal brukes', 'Å sette mål for dem', 'Å bruke dem for å nå egne mål']::text[], 1, 'Dette er en av Kants formuleringer av det kategoriske imperativ.', true, true, 4),
  ('krle-8:etiske-teorier', 'q06', 'flervalg', 'Hva spør dydsetikken først og fremst om?', array['Hva gir best resultat?', 'Hva sier loven?', 'Hva mener flertallet?', 'Hva slags menneske vil jeg være?']::text[], 3, 'Dydsetikken handler om karakter mer enn om enkelthandlinger.', true, true, 5),
  ('krle-8:etiske-teorier', 'q07', 'flervalg', 'Hva er den gylne middelvei hos Aristoteles?', array['En dyd som ligger mellom to ytterpunkter', 'En regel om å dele likt', 'En vei til lykke gjennom rikdom', 'En plikt til å si sannheten']::text[], 0, 'Mot ligger for eksempel mellom feighet og dumdristighet.', true, true, 6),
  ('krle-8:etiske-teorier', 'q08', 'flervalg', 'Hva legger sinnelagsetikken vekt på?', array['Resultatet', 'Loven', 'Hensikten bak handlingen', 'Flertallets mening']::text[], 2, 'En handling gjort i god mening regnes som god, selv om den går galt.', true, true, 7),
  ('krle-8:etiske-teorier', 'q09', 'flervalg', 'Hva er et etisk dilemma?', array['En enkel regel', 'Et valg mellom handlinger som alle har gode og dårlige sider', 'En lov', 'En etisk teori']::text[], 1, 'I et dilemma finnes det ingen løsning som er helt uten ulemper.', true, false, 8),
  ('krle-8:etiske-teorier', 'q10', 'flervalg', 'Hva er lurt når man er uenig i en etisk diskusjon?', array['Å avbryte den andre', 'Å angripe personen', 'Å gi seg med en gang', 'Å lytte aktivt og begrunne standpunktene sine']::text[], 3, 'Gode argumenter og respekt gjør det lettere å forstå hverandre.', true, false, 9),
  ('krle-8:etiske-teorier', 'm01', 'sant-usant', 'Kant mente at det aldri er riktig å lyve.', array['Sant', 'Usant']::text[], 0, 'Ifølge Kant kan ikke løgn bli en allmenn lov, uansett hva følgene blir.', false, true, 10),
  ('krle-8:etiske-teorier', 'm02', 'sant-usant', 'Konsekvensetikken vurderer handlinger bare ut fra hensikten.', array['Sant', 'Usant']::text[], 1, 'Det er sinnelagsetikken som vektlegger hensikten. Konsekvensetikken ser på følgene.', false, true, 11),
  ('krle-8:etiske-teorier', 'm03', 'sant-usant', 'Aristoteles mente at mot ligger mellom feighet og dumdristighet.', array['Sant', 'Usant']::text[], 0, 'Dette er et eksempel på den gylne middelvei.', false, true, 12),
  ('krle-8:etiske-teorier', 'm04', 'sant-usant', 'I en god diskusjon bør man angripe personen i stedet for saken.', array['Sant', 'Usant']::text[], 1, 'Personangrep gjør diskusjonen dårligere og hindrer at man forstår hverandre.', false, true, 13),
  ('krle-8:etiske-teorier', 'm05', 'flervalg', 'Hvilken teori spør «Hvilke følger får handlingen?»', array['Pliktetikk', 'Dydsetikk', 'Konsekvensetikk', 'Sinnelagsetikk']::text[], 2, 'Konsekvensetikken vurderer handlinger ut fra resultatet.', false, true, 14),
  ('krle-8:etiske-teorier', 'm06', 'flervalg', 'Hva er en dyd?', array['Et godt karaktertrekk, som mot eller ærlighet', 'En lov', 'En konsekvens', 'En plikt']::text[], 0, 'Ifølge Aristoteles utvikler vi dyder gjennom øvelse.', false, true, 15),
  ('krle-8:etiske-teorier', 'm07', 'flervalg', 'Hvilken etisk teori knyttes til Jeremy Bentham og John Stuart Mill?', array['Pliktetikk', 'Utilitarisme', 'Dydsetikk', 'Sinnelagsetikk']::text[], 1, 'Utilitarismen er en form for konsekvensetikk.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-8:etiske-teorier', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-8:etiske-teorier', 's01', 'En elev mener at det er galt å jukse, men jukser likevel på en prøve. Hva er elevens moralske oppfatning, og hva er elevens handling?', 'Elevens moralske oppfatning er at juks er galt. Handlingen er at eleven jukser, selv om det ikke stemmer med oppfatningen.', array['Skiller mellom oppfatningen om rett og galt og det eleven faktisk gjør.', 'Får fram at elevens handling ikke samsvarer med oppfatningen.']::text[], 0),
  ('krle-8:etiske-teorier', 's02', 'En avgjørelse kan gjøre situasjonen bedre for mange, men verre for én person. Hva er en styrke ved konsekvensetikken når man vurderer avgjørelsen?', 'Konsekvensetikken tar hensyn til hvordan handlingen påvirker alle som blir berørt. Det kan gjøre det lettere å se hvem som får det bedre eller verre.', array['Får fram at konsekvensetikken vurderer følgene av handlingen.', 'Viser at den tar hensyn til hvordan følgene påvirker flere enn bare den som tar avgjørelsen.']::text[], 1),
  ('krle-8:etiske-teorier', 's03', 'En elev vurderer å jukse på en lekse fordi det kan hjelpe eleven med å få en bedre vurdering. Hvordan kan det kategoriske imperativ brukes til å vurdere juksingen?', 'Eleven kan spørre om det ville vært greit dersom alle jukset når det passet dem. Hvis regelen ikke bør gjelde for alle, bør eleven ikke jukse.', array['Bruker tanken om at handlingen skal kunne bli en regel for alle.', 'Knytter denne testen til om eleven bør jukse.']::text[], 2),
  ('krle-8:etiske-teorier', 's04', 'Du har lovet å holde på en hemmelighet, men å holde løftet vil bety at du må si noe som ikke er sant. Hvorfor kan en pliktetiker synes dette valget er vanskelig?', 'Pliktetikken legger vekt på både å holde løfter og å si sannheten. Her kan pliktene komme i konflikt, slik at det er vanskelig å følge begge samtidig.', array['Nevner at å holde løfter og å si sannheten er plikter.', 'Forklarer at de to pliktene kan komme i konflikt.']::text[], 3),
  ('krle-8:etiske-teorier', 's05', 'En elev prøver å hjelpe en klassekamerat, men rådet gjør at klassekameraten får et dårligere resultat. Hvordan kan sinnelagsetikk og konsekvensetikk vurdere handlingen forskjellig?', 'Sinnelagsetikken vil legge vekt på at eleven prøvde å hjelpe. Konsekvensetikken vil legge vekt på at rådet førte til et dårligere resultat.', array['Knytter sinnelagsetikken til hensikten om å hjelpe.', 'Knytter konsekvensetikken til følgen, altså det dårligere resultatet.']::text[], 4),
  ('krle-8:etiske-teorier', 's06', 'Du får mulighet til å ta æren for et gruppearbeid, selv om flere har bidratt. Forklar hvordan dydsetikk kan hjelpe deg med å vurdere hva du bør gjøre.', 'Dydsetikken spør hva slags menneske du vil være. Du kan tenke på om et ærlig og rettferdig menneske ville tatt æren alene når flere hadde bidratt.', array['Knytter vurderingen til hva slags menneske man vil være eller hvilke dyder man vil vise.', 'Bruker en relevant dyd, som ærlighet eller rettferdighet, på situasjonen.']::text[], 5),
  ('krle-8:etiske-teorier', 's07', 'To elever er uenige om hva som er rett å gjøre. Beskriv én konkret måte den ene eleven kan vise aktiv lytting på, og forklar hva det viser.', 'Eleven kan gjenta med egne ord hva den andre mener, og spørre om det er forstått riktig. Det viser at eleven lytter for å forstå den andres perspektiv.', array['Beskriver en konkret handling som viser at eleven prøver å forstå den andre.', 'Forklarer at handlingen viser forståelse eller interesse for den andres perspektiv.']::text[], 6),
  ('krle-8:etiske-teorier', 's08', 'En person vurderer å bruke en annen elevs arbeid uten å spørre. Forklar hvordan konsekvensetikk og dydsetikk kan gi ulike spørsmål å tenke gjennom.', 'Konsekvensetikken vil spørre hvilke følger det får for dem som blir berørt. Dydsetikken vil spørre hva et ærlig og rettferdig menneske ville gjort.', array['Knytter konsekvensetikk til følgene for dem som blir berørt.', 'Knytter dydsetikk til hva slags menneske man vil være eller til en relevant dyd.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('tysk-8:hilsener-og-presentasjon', 'tysk-8', 'hilsener-og-presentasjon', 'Hilsener og presentasjon', 'Hvordan du hilser, presenterer deg selv og spør andre om navn, alder og bosted på tysk, når du bruker du og Sie, og de viktigste reglene for uttale og skrift.', array[2, 6]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('tysk-8:hilsener-og-presentasjon', '## Tysk i verden
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('tysk-8:hilsener-og-presentasjon', 'Hallo!', 'Hei!', 0),
  ('tysk-8:hilsener-og-presentasjon', 'Guten Morgen!', 'God morgen!', 1),
  ('tysk-8:hilsener-og-presentasjon', 'Guten Tag!', 'God dag! (litt formelt)', 2),
  ('tysk-8:hilsener-og-presentasjon', 'Tschüs!', 'Ha det! (uformelt)', 3),
  ('tysk-8:hilsener-og-presentasjon', 'Auf Wiedersehen!', 'Ha det bra! (formelt)', 4),
  ('tysk-8:hilsener-og-presentasjon', 'Wie heißt du?', 'Hva heter du?', 5),
  ('tysk-8:hilsener-og-presentasjon', 'Ich heiße …', 'Jeg heter …', 6),
  ('tysk-8:hilsener-og-presentasjon', 'Wie alt bist du?', 'Hvor gammel er du?', 7),
  ('tysk-8:hilsener-og-presentasjon', 'Woher kommst du?', 'Hvor kommer du fra?', 8),
  ('tysk-8:hilsener-og-presentasjon', 'Ich wohne in …', 'Jeg bor i …', 9),
  ('tysk-8:hilsener-og-presentasjon', 'Wie geht''s?', 'Hvordan går det?', 10),
  ('tysk-8:hilsener-og-presentasjon', 'du / Sie', 'du (uformelt) / De (høflig til voksne du ikke kjenner)', 11),
  ('tysk-8:hilsener-og-presentasjon', 'Danke', 'Takk', 12),
  ('tysk-8:hilsener-og-presentasjon', 'Bitte', 'Vær så snill / vær så god', 13),
  ('tysk-8:hilsener-og-presentasjon', 'Entschuldigung', 'Unnskyld', 14),
  ('tysk-8:hilsener-og-presentasjon', 'ß', 'Eszett, uttales som dobbel s, som i heißen.', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('tysk-8:hilsener-og-presentasjon', 'q01', 'flervalg', 'Hva betyr «Wie heißt du?»', array['Hvor bor du?', 'Hva heter du?', 'Hvor gammel er du?', 'Hvordan går det?']::text[], 1, 'Du svarer med «Ich heiße …».', true, true, 0),
  ('tysk-8:hilsener-og-presentasjon', 'q02', 'flervalg', 'Hvordan sier du «Jeg kommer fra Norge» på tysk?', array['Ich wohne in Norwegen.', 'Ich heiße Norwegen.', 'Ich bin Norwegen.', 'Ich komme aus Norwegen.']::text[], 3, '«aus» betyr «fra» når du forteller hvor du kommer fra.', true, true, 1),
  ('tysk-8:hilsener-og-presentasjon', 'q03', 'flervalg', 'Når bruker du «Sie» i stedet for «du»?', array['Til voksne du ikke kjenner, som en lærer eller ekspeditør', 'Til venner', 'Til søsken', 'Til kjæledyr']::text[], 0, '«Sie» er høflighetsformen.', true, true, 2),
  ('tysk-8:hilsener-og-presentasjon', 'q04', 'flervalg', 'Hvordan uttales «ei» i «drei»?', array['Som norsk «ei»', 'Som langt «i»', 'Som norsk «ai»', 'Som «åi»']::text[], 2, '«drei» uttales omtrent «drai».', true, true, 3),
  ('tysk-8:hilsener-og-presentasjon', 'q05', 'flervalg', 'Hvilken hilsen passer best når du sier ha det etter en formell samtale?', array['Hallo!', 'Tschüs!', 'Guten Morgen!', 'Auf Wiedersehen!']::text[], 3, '«Tschüs» er uformelt, «Auf Wiedersehen» er formelt.', true, true, 4),
  ('tysk-8:hilsener-og-presentasjon', 'q06', 'flervalg', 'Hvilke ord skrives alltid med stor forbokstav på tysk?', array['Verb', 'Substantiver', 'Adjektiver', 'Tallord']::text[], 1, 'Alle substantiver, som «der Hund» og «die Schule», har stor forbokstav.', true, true, 5),
  ('tysk-8:hilsener-og-presentasjon', 'q07', 'flervalg', 'Hva svarer du på «Wie geht''s?» hvis det går bra?', array['Gut, danke!', 'Ich heiße Ola.', 'Auf Wiedersehen!', 'Ich bin dreizehn.']::text[], 0, '«Gut, danke!» betyr «Bra, takk!».', true, true, 6),
  ('tysk-8:hilsener-og-presentasjon', 'q08', 'flervalg', 'Hvordan uttales «w» i «wo»?', array['Som engelsk «w»', 'Som «f»', 'Som norsk «v»', 'Den er stum']::text[], 2, '«wo» uttales omtrent «vo».', true, true, 7),
  ('tysk-8:hilsener-og-presentasjon', 'q09', 'flervalg', 'Hva betyr «Entschuldigung»?', array['Takk', 'Unnskyld', 'Vær så god', 'Ha det']::text[], 1, 'Ordet brukes når du vil be om unnskyldning eller få noens oppmerksomhet.', true, false, 8),
  ('tysk-8:hilsener-og-presentasjon', 'q10', 'flervalg', 'Hva er «ß»?', array['En omlyd', 'En stor S', 'Et spørsmålstegn', 'En bokstav som uttales som dobbel s']::text[], 3, 'Bokstaven kalles eszett, som i «Straße».', true, false, 9),
  ('tysk-8:hilsener-og-presentasjon', 'm01', 'sant-usant', '«Tschüs» er en uformell måte å si ha det på.', array['Sant', 'Usant']::text[], 0, 'Til venner sier du «Tschüs!».', false, true, 10),
  ('tysk-8:hilsener-og-presentasjon', 'm02', 'sant-usant', 'Tysk snakkes bare i Tyskland.', array['Sant', 'Usant']::text[], 1, 'Tysk er også offisielt språk i blant annet Østerrike og Sveits.', false, true, 11),
  ('tysk-8:hilsener-og-presentasjon', 'm03', 'sant-usant', 'Høflighetsformen «Sie» skrives alltid med stor S.', array['Sant', 'Usant']::text[], 0, 'Stor S skiller den fra «sie», som betyr «hun» eller «de».', false, true, 12),
  ('tysk-8:hilsener-og-presentasjon', 'm04', 'sant-usant', '«ie» i «vier» uttales som «i» og «e» hver for seg.', array['Sant', 'Usant']::text[], 1, '«ie» uttales som en lang i-lyd.', false, true, 13),
  ('tysk-8:hilsener-og-presentasjon', 'm05', 'flervalg', 'Hva betyr «Ich bin dreizehn Jahre alt»?', array['Jeg bor i Tyskland', 'Jeg er tretten år gammel', 'Jeg heter Dreizehn', 'Jeg har tretten søsken']::text[], 1, '«dreizehn» betyr tretten.', false, true, 14),
  ('tysk-8:hilsener-og-presentasjon', 'm06', 'flervalg', 'Hvordan uttales «z» i «zehn»?', array['ts', 's', 'som engelsk z', 'sj']::text[], 0, '«zehn» uttales omtrent «tsen».', false, true, 15),
  ('tysk-8:hilsener-og-presentasjon', 'm07', 'flervalg', 'Hvilket ord betyr «takk»?', array['Bitte', 'Ja', 'Danke', 'Hallo']::text[], 2, '«Danke schön» betyr «tusen takk».', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('tysk-8:hilsener-og-presentasjon', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('tysk-8:hilsener-og-presentasjon', 's01', 'Sammenlign de tyske hilsenene «Hallo!» og «Guten Tag!». Hva betyr de, og hvilken er litt mer formell?', '«Hallo!» betyr «hei», mens «Guten Tag!» betyr «god dag». «Guten Tag!» er litt mer formell.', array['Forklarer riktig hva begge hilsenene betyr.', 'Får fram at «Guten Tag!» er litt mer formell.']::text[], 0),
  ('tysk-8:hilsener-og-presentasjon', 's02', 'Du skal spørre en voksen du ikke kjenner, hva personen heter. Skriv spørsmålet på tysk med høflighetsformen, og forklar kort hvorfor du bruker den.', '«Wie heißen Sie?» Jeg bruker «Sie» fordi det er høflig når jeg snakker med en voksen jeg ikke kjenner.', array['Skriver et forståelig spørsmål med «Sie» med stor S.', 'Forklarer at «Sie» brukes høflig til voksne man ikke kjenner.']::text[], 1),
  ('tysk-8:hilsener-og-presentasjon', 's03', 'En person spør deg «Wie alt bist du?». Svar på tysk at du er tretten år gammel.', 'Ich bin dreizehn Jahre alt.', array['Svarer på tysk at man er tretten år gammel.']::text[], 2),
  ('tysk-8:hilsener-og-presentasjon', 's04', 'Skriv på tysk at du heter Nora og bor i Bergen.', 'Ich heiße Nora. Ich wohne in Bergen.', array['Skriver at man heter Nora med «Ich heiße Nora».', 'Skriver at man bor i Bergen med «Ich wohne in Bergen».']::text[], 3),
  ('tysk-8:hilsener-og-presentasjon', 's05', 'Forklar hvordan tysk og norsk henger sammen, og gi to eksempler på tyske og norske ord som ligner.', 'Tysk og norsk er i slekt, og derfor ligner noen ord. For eksempel betyr «Haus» hus og «Buch» bok.', array['Nevner at tysk og norsk er i slekt.', 'Gir to riktige par med lignende ord på tysk og norsk.']::text[], 4),
  ('tysk-8:hilsener-og-presentasjon', 's06', 'Forklar hvordan «ch» uttales i de tyske ordene «Buch» og «ich».', 'I «Buch» uttales «ch» som en hard lyd bak i halsen. I «ich» er lyden mykere, omtrent som «kj» i «kjøre».', array['Beskriver «ch» i «Buch» som en hard lyd bak i halsen.', 'Beskriver «ch» i «ich» som en mykere lyd, omtrent som «kj».']::text[], 5),
  ('tysk-8:hilsener-og-presentasjon', 's07', 'Du ber høflig om noe og vil takke etterpå. Skriv ett tysk ord du kan bruke når du ber, og ett tysk ord som betyr «takk».', 'Jeg kan si «Bitte» når jeg ber om noe, og «Danke» for å si takk.', array['Bruker «Bitte» som et høflig ord når man ber om noe.', 'Bruker «Danke» for å si takk.']::text[], 6),
  ('tysk-8:hilsener-og-presentasjon', 's08', 'Nevn de fire landene der tysk er offisielt språk, og ett annet land eller område der tysk også snakkes.', 'Tysk er offisielt språk i Tyskland, Østerrike, Sveits og Liechtenstein. Det snakkes også i deler av Belgia.', array['Nevner Tyskland, Østerrike, Sveits og Liechtenstein.', 'Nevner deler av Belgia, Luxembourg eller Italia som et annet sted der tysk snakkes.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('tysk-8:tall-og-tid', 'tysk-8', 'tall-og-tid', 'Tall, dager og klokka', 'Tallene på tysk, ukedager, måneder og årstider, hvordan du sier datoen og bursdagen din, og hvordan du spør om og sier hva klokka er.', array[6, 1]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('tysk-8:tall-og-tid', '## Tallene 0–20
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('tysk-8:tall-og-tid', 'zwölf', '12', 0),
  ('tysk-8:tall-og-tid', 'zwanzig', '20', 1),
  ('tysk-8:tall-og-tid', 'einundzwanzig', '21 – enerne kommer før tierne', 2),
  ('tysk-8:tall-og-tid', 'dreißig', '30 – skrives med ß', 3),
  ('tysk-8:tall-og-tid', 'hundert', '100', 4),
  ('tysk-8:tall-og-tid', 'Montag', 'mandag', 5),
  ('tysk-8:tall-og-tid', 'Mittwoch', 'onsdag', 6),
  ('tysk-8:tall-og-tid', 'Donnerstag', 'torsdag', 7),
  ('tysk-8:tall-og-tid', 'Samstag', 'lørdag', 8),
  ('tysk-8:tall-og-tid', 'der Frühling', 'våren', 9),
  ('tysk-8:tall-og-tid', 'der Herbst', 'høsten', 10),
  ('tysk-8:tall-og-tid', 'Wie spät ist es?', 'Hva er klokka?', 11),
  ('tysk-8:tall-og-tid', 'halb neun', 'halv ni (8.30)', 12),
  ('tysk-8:tall-og-tid', 'Viertel nach drei', 'kvart over tre', 13),
  ('tysk-8:tall-og-tid', 'Viertel vor vier', 'kvart på fire', 14),
  ('tysk-8:tall-og-tid', 'der Geburtstag', 'bursdagen', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('tysk-8:tall-og-tid', 'q01', 'flervalg', 'Hvordan skriver du 21 på tysk?', array['zwanzigeins', 'zweiundeins', 'einundzwanzig', 'zwanzig und eins']::text[], 2, 'Enerne kommer først: «en-og-tjue».', true, true, 0),
  ('tysk-8:tall-og-tid', 'q02', 'flervalg', 'Hva betyr «halb vier»?', array['Halv fire (3.30)', 'Halv tre (2.30)', 'Kvart over fire', 'Fire timer']::text[], 0, 'Som på norsk betyr «halb vier» en halv time før fire.', true, true, 1),
  ('tysk-8:tall-og-tid', 'q03', 'flervalg', 'Hvilken ukedag er «Mittwoch»?', array['Mandag', 'Tirsdag', 'Torsdag', 'Onsdag']::text[], 3, '«Mittwoch» betyr egentlig «midtuke».', true, true, 2),
  ('tysk-8:tall-og-tid', 'q04', 'flervalg', 'Hvordan spør du hva klokka er?', array['Wie alt bist du?', 'Wie spät ist es?', 'Wo wohnst du?', 'Wie geht''s?']::text[], 1, 'Du kan også si «Wie viel Uhr ist es?».', true, true, 3),
  ('tysk-8:tall-og-tid', 'q05', 'flervalg', 'Hvordan skrives tallet 30 på tysk?', array['dreizig', 'dreizehn', 'dreißig', 'dreisig']::text[], 2, '30 skrives med ß, i motsetning til de andre tierne som slutter på -zig.', true, true, 4),
  ('tysk-8:tall-og-tid', 'q06', 'flervalg', 'Hva betyr «Viertel vor vier»?', array['Kvart på fire', 'Kvart over fire', 'Halv fire', 'Fire og et kvarter']::text[], 0, '«vor» betyr «før» eller «på».', true, true, 5),
  ('tysk-8:tall-og-tid', 'q07', 'flervalg', 'Hvordan sier du «i mai» på tysk?', array['am Mai', 'um Mai', 'in Mai', 'im Mai']::text[], 3, 'Med måneder og årstider bruker du «im».', true, true, 6),
  ('tysk-8:tall-og-tid', 'q08', 'flervalg', 'Hvilket tall er «sechzig»?', array['16', '60', '6', '600']::text[], 1, '16 er «sechzehn», 60 er «sechzig».', true, true, 7),
  ('tysk-8:tall-og-tid', 'q09', 'flervalg', 'Hvordan sier du «på mandag»?', array['am Montag', 'im Montag', 'um Montag', 'in Montag']::text[], 0, 'Med ukedager bruker du «am».', true, false, 8),
  ('tysk-8:tall-og-tid', 'q10', 'flervalg', 'Hva heter høsten på tysk?', array['der Frühling', 'der Sommer', 'der Herbst', 'der Winter']::text[], 2, '«Herbst» ligner det engelske «harvest», innhøsting.', true, false, 9),
  ('tysk-8:tall-og-tid', 'm01', 'sant-usant', 'På tysk sier man enerne før tierne, som i «fünfundvierzig» (45).', array['Sant', 'Usant']::text[], 0, 'Slik telte man også på norsk før.', false, true, 10),
  ('tysk-8:tall-og-tid', 'm02', 'sant-usant', 'Månedsnavn skrives med liten forbokstav på tysk.', array['Sant', 'Usant']::text[], 1, 'Månedene er substantiver og skrives med stor forbokstav.', false, true, 11),
  ('tysk-8:tall-og-tid', 'm03', 'sant-usant', '«um acht Uhr» betyr klokka åtte.', array['Sant', 'Usant']::text[], 0, '«um» brukes når du sier når noe skjer.', false, true, 12),
  ('tysk-8:tall-og-tid', 'm04', 'sant-usant', '«zwölf» betyr tjue.', array['Sant', 'Usant']::text[], 1, '«zwölf» er 12. Tjue heter «zwanzig».', false, true, 13),
  ('tysk-8:tall-og-tid', 'm05', 'flervalg', 'Hva betyr «Ich habe am dritten März Geburtstag»?', array['Jeg er tre år gammel', 'Jeg har bursdag 3. mars', 'Jeg har tre bursdager', 'Det er tre dager til mars']::text[], 1, '«am dritten März» betyr «den tredje mars».', false, true, 14),
  ('tysk-8:tall-og-tid', 'm06', 'flervalg', 'Hvilket ord betyr «lørdag»?', array['Sonntag', 'Freitag', 'Samstag', 'Dienstag']::text[], 2, 'I Nord-Tyskland sier noen også «Sonnabend».', false, true, 15),
  ('tysk-8:tall-og-tid', 'm07', 'flervalg', 'Hva betyr «Viertel nach drei»?', array['Kvart over tre', 'Kvart på tre', 'Halv tre', 'Tre kvarter']::text[], 0, '«nach» betyr «etter» eller «over».', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('tysk-8:tall-og-tid', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('tysk-8:tall-og-tid', 's01', 'Skriv tallet 58 med tyske bokstaver. Forklar hvilken rekkefølge enerne og tierne kommer i, og hvordan tallet skrives.', '58 skrives achtundfünfzig. På tysk kommer enerne før tierne, og tallet skrives i ett ord.', array['Skriver achtundfünfzig riktig.', 'Forklarer at enerne kommer før tierne, og at tallet skrives i ett ord.']::text[], 0),
  ('tysk-8:tall-og-tid', 's02', 'Skriv 16 og 17 med tyske bokstaver. Forklar hva som er spesielt med skrivemåten deres.', '16 skrives sechzehn, og 17 skrives siebzehn. Begge formene er forkortet.', array['Skriver både sechzehn og siebzehn riktig.', 'Får fram at begge formene er forkortet.']::text[], 1),
  ('tysk-8:tall-og-tid', 's03', 'Sammenlign klokkeslettene 8.10 og 8.50. Skriv begge på tysk, og forklar hva nach og vor forteller om tidspunktet.', '8.10 er Es ist zehn nach acht, og 8.50 er Es ist zehn vor neun. Nach betyr at tiden er etter åtte, mens vor betyr at det er ti minutter igjen til ni.', array['Gir riktig tysk uttrykk for begge klokkeslettene.', 'Forklarer forskjellen mellom nach og vor med utgangspunkt i klokkeslettene.']::text[], 2),
  ('tysk-8:tall-og-tid', 's04', 'Skolen begynner klokka 8.30. Skriv en tysk setning om når skolen begynner, og bruk um.', 'Die Schule beginnt um halb neun.', array['Bruker um for å fortelle når noe skjer.', 'Skriver klokkeslettet 8.30 som halb neun.']::text[], 3),
  ('tysk-8:tall-og-tid', 's05', 'Du skal fortelle på tysk at du har bursdag 3. mars. Skriv en hel setning.', 'Ich habe am dritten März Geburtstag.', array['Får fram at bursdagen er 3. mars.', 'Bruker en forståelig tysk setning med am og Geburtstag.']::text[], 4),
  ('tysk-8:tall-og-tid', 's06', 'Skriv de tyske navnene på ukedagene fra mandag til søndag i riktig rekkefølge.', 'Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag, Sonntag.', array['Har med ukedagene i riktig rekkefølge.', 'Skriver ukedagsnavnene riktig eller med bare små skrivefeil.']::text[], 5),
  ('tysk-8:tall-og-tid', 's07', 'Forklar hvordan stor forbokstav brukes i tyske navn på årstider. Skriv to eksempler med artikkel.', 'Årstidene er substantiver på tysk og skrives derfor med stor forbokstav. Eksempler er der Sommer og der Winter.', array['Forklarer at årstidene er substantiver og derfor har stor forbokstav.', 'Gir to riktige eksempler på årstider med stor forbokstav.']::text[], 6),
  ('tysk-8:tall-og-tid', 's08', 'Nevn én måte å øve på tyske tall, og forklar hvordan den kan hjelpe deg med å lære.', 'Jeg kan skrive tallene med bokstaver. Det hjelper meg med å lære hvordan tallene staves på tysk.', array['Nevner en øvingsmåte fra temaet, for eksempel å skrive tall med bokstaver eller si et telefonnummer høyt.', 'Forklarer hvordan øvingsmåten hjelper med tall eller tysk rettskriving.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('tysk-8:familie-og-venner', 'tysk-8', 'familie-og-venner', 'Familie og venner', 'Ord for familie, venner og kjæledyr på tysk, hvordan du bruker mein og meine, ein, einen og kein, og hvordan du beskriver utseende og personlighet.', array[3, 5]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('tysk-8:familie-og-venner', '## Familien – die Familie
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('tysk-8:familie-og-venner', 'der Vater / die Mutter', 'faren / moren', 0),
  ('tysk-8:familie-og-venner', 'die Eltern', 'foreldrene', 1),
  ('tysk-8:familie-og-venner', 'der Bruder / die Schwester', 'broren / søsteren', 2),
  ('tysk-8:familie-og-venner', 'die Geschwister', 'søsknene', 3),
  ('tysk-8:familie-og-venner', 'die Großeltern', 'besteforeldrene', 4),
  ('tysk-8:familie-og-venner', 'der Onkel / die Tante', 'onkelen / tanten', 5),
  ('tysk-8:familie-og-venner', 'der Cousin / die Cousine', 'fetteren / kusinen', 6),
  ('tysk-8:familie-og-venner', 'das Haustier', 'kjæledyret', 7),
  ('tysk-8:familie-og-venner', 'mein / meine', 'min, mitt / min, mine – meine brukes ved hunkjønn og flertall', 8),
  ('tysk-8:familie-og-venner', 'Ich habe einen Bruder.', 'Jeg har en bror.', 9),
  ('tysk-8:familie-og-venner', 'Ich habe keine Geschwister.', 'Jeg har ingen søsken.', 10),
  ('tysk-8:familie-og-venner', 'nett', 'snill, hyggelig', 11),
  ('tysk-8:familie-og-venner', 'lustig', 'morsom', 12),
  ('tysk-8:familie-og-venner', 'schüchtern', 'sjenert', 13),
  ('tysk-8:familie-og-venner', 'Er hat blaue Augen.', 'Han har blå øyne.', 14),
  ('tysk-8:familie-og-venner', 'die Freundin', 'venninnen, eller kjæresten', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('tysk-8:familie-og-venner', 'q01', 'flervalg', 'Hva betyr «die Geschwister»?', array['Søsken', 'Søstre', 'Besteforeldre', 'Foreldre']::text[], 0, '«Geschwister» er brødre og søstre til sammen.', true, true, 0),
  ('tysk-8:familie-og-venner', 'q02', 'flervalg', 'Hva heter «foreldrene» på tysk?', array['die Großeltern', 'die Geschwister', 'die Kinder', 'die Eltern']::text[], 3, '«die Großeltern» er besteforeldrene.', true, true, 1),
  ('tysk-8:familie-og-venner', 'q03', 'flervalg', 'Hvilken form er riktig?', array['mein Mutter', 'meine Mutter', 'meinen Mutter', 'meines Mutter']::text[], 1, '«Mutter» er hunkjønn, derfor «meine».', true, true, 2),
  ('tysk-8:familie-og-venner', 'q04', 'flervalg', 'Hvordan sier du «Jeg har en bror»?', array['Ich habe ein Bruder.', 'Ich bin einen Bruder.', 'Ich habe einen Bruder.', 'Ich habe eine Bruder.']::text[], 2, 'Etter «haben» får hankjønnsord formen «einen».', true, true, 3),
  ('tysk-8:familie-og-venner', 'q05', 'flervalg', 'Hva betyr «Ich habe keine Geschwister»?', array['Jeg har mange søsken', 'Jeg har ingen søsken', 'Jeg har to søsken', 'Søsknene mine er snille']::text[], 1, '«kein/keine» betyr «ingen».', true, true, 4),
  ('tysk-8:familie-og-venner', 'q06', 'flervalg', 'Hva betyr «lustig»?', array['Lat', 'Trist', 'Høy', 'Morsom']::text[], 3, 'Ordet ligner norsk «lystig».', true, true, 5),
  ('tysk-8:familie-og-venner', 'q07', 'flervalg', 'Hvordan sier du «Hun har brune øyne»?', array['Sie hat braune Augen.', 'Sie ist braune Augen.', 'Sie hat braun Auge.', 'Er hat braune Augen.']::text[], 0, '«Sie» betyr «hun», og «Augen» er flertall av «Auge».', true, true, 6),
  ('tysk-8:familie-og-venner', 'q08', 'flervalg', 'Hva er «die Tante»?', array['Onkelen', 'Bestemoren', 'Tanten', 'Kusinen']::text[], 2, 'Onkelen heter «der Onkel».', true, true, 7),
  ('tysk-8:familie-og-venner', 'q09', 'flervalg', 'Hvilken artikkel har «Haustier» (kjæledyr)?', array['der', 'die', 'den', 'das']::text[], 3, 'Sammensatte ord får kjønnet til siste ledd, og «das Tier» (dyret) er intetkjønn.', true, false, 8),
  ('tysk-8:familie-og-venner', 'q10', 'flervalg', 'Hva betyr «Mein bester Freund heißt Jonas»?', array['Min bror heter Jonas', 'Min beste venn heter Jonas', 'Jonas er snill', 'Jonas bor her']::text[], 1, '«bester Freund» betyr beste venn.', true, false, 9),
  ('tysk-8:familie-og-venner', 'm01', 'sant-usant', '«der Opa» betyr bestefar.', array['Sant', 'Usant']::text[], 0, 'Bestemor heter «die Oma».', false, true, 10),
  ('tysk-8:familie-og-venner', 'm02', 'sant-usant', '«die Freundin» kan bety både venninne og kjæreste.', array['Sant', 'Usant']::text[], 0, 'Sammenhengen avgjør hva ordet betyr.', false, true, 11),
  ('tysk-8:familie-og-venner', 'm03', 'sant-usant', 'Etter «Ich habe» heter det «ein Hund».', array['Sant', 'Usant']::text[], 1, 'Det heter «Ich habe einen Hund», fordi hankjønnsord får formen «einen».', false, true, 12),
  ('tysk-8:familie-og-venner', 'm04', 'sant-usant', '«groß» betyr liten.', array['Sant', 'Usant']::text[], 1, '«groß» betyr stor eller høy. Liten heter «klein».', false, true, 13),
  ('tysk-8:familie-og-venner', 'm05', 'flervalg', 'Hva betyr «meine Eltern»?', array['Mine søsken', 'Mine besteforeldre', 'Mine foreldre', 'Mine venner']::text[], 2, '«Eltern» betyr foreldre.', false, true, 14),
  ('tysk-8:familie-og-venner', 'm06', 'flervalg', 'Hvilket ord betyr «snill» eller «hyggelig»?', array['nett', 'alt', 'klein', 'müde']::text[], 0, '«müde» betyr trøtt, og «alt» betyr gammel.', false, true, 15),
  ('tysk-8:familie-og-venner', 'm07', 'flervalg', 'Hvilken artikkel har «Mutter»?', array['der', 'die', 'das', 'den']::text[], 1, '«die Mutter» er hunkjønn.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('tysk-8:familie-og-venner', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('tysk-8:familie-og-venner', 's01', 'Forklar på norsk hva «die Großeltern» betyr, og hvem i familien det viser til.', '«Die Großeltern» betyr besteforeldrene, altså bestefaren og bestemoren.', array['Forklarer at ordet betyr besteforeldrene.', 'Knytter det til bestefar og bestemor.']::text[], 0),
  ('tysk-8:familie-og-venner', 's02', 'Hvorfor heter det «mein Vater», men «meine Mutter»? Forklar regelen med disse to ordene.', '«Vater» er hankjønn og får «mein». «Mutter» er hunkjønn og får «meine».', array['Kobler «mein» til hankjønn.', 'Kobler «meine» til hunkjønn.']::text[], 1),
  ('tysk-8:familie-og-venner', 's03', 'Forklar de to mulige betydningene av «der Freund» og «die Freundin».', '«Der Freund» kan bety en venn eller en kjæreste. «Die Freundin» kan bety en venninne eller en kjæreste.', array['Får fram at «der Freund» kan bety venn eller kjæreste.', 'Får fram at «die Freundin» kan bety venninne eller kjæreste.']::text[], 2),
  ('tysk-8:familie-og-venner', 's04', 'Du vil si på tysk: «Jeg har et kjæledyr.» Skriv setningen.', 'Ich habe ein Haustier.', array['Bruker «Ich habe».', 'Bruker «ein Haustier».']::text[], 3),
  ('tysk-8:familie-og-venner', 's05', 'Skriv på tysk om en gutt som er sjenert og har grønne øyne.', 'Er ist schüchtern und hat grüne Augen.', array['Beskriver gutten som «schüchtern».', 'Skriver at han har «grüne Augen».']::text[], 4),
  ('tysk-8:familie-og-venner', 's06', 'Forklar forskjellen mellom «der Cousin» og «der Onkel».', '«Der Cousin» betyr fetteren, mens «der Onkel» betyr onkelen.', array['Forklarer at «der Cousin» betyr fetteren.', 'Forklarer at «der Onkel» betyr onkelen.']::text[], 5),
  ('tysk-8:familie-og-venner', 's07', 'Du skal presentere foreldrene dine på tysk. Faren heter Lars og er morsom. Moren heter Ingrid og er sporty. Skriv setninger om dem.', 'Mein Vater heißt Lars. Er ist lustig. Meine Mutter heißt Ingrid. Sie ist sportlich.', array['Skriver at faren heter Lars, og beskriver ham som «lustig».', 'Skriver at moren heter Ingrid, og beskriver henne som «sportlich».']::text[], 6),
  ('tysk-8:familie-og-venner', 's08', 'Sammenlign «Ich habe einen Bruder» og «Ich habe eine Schwester». Hva er forskjellig i formen etter «habe», og hvorfor?', 'Det heter «einen Bruder», men «eine Schwester». «Bruder» er hankjønn og får formen «einen» etter «habe», mens «Schwester» er hunkjønn.', array['Viser at det heter «einen Bruder» og «eine Schwester».', 'Forklarer at forskjellen skyldes grammatisk kjønn, og at hankjønnsord får «einen» etter «habe».']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('tysk-8:skole-og-fritid', 'tysk-8', 'skole-og-fritid', 'Skole og fritid', 'Skolefag, meninger og fritidsaktiviteter på tysk, hvordan du bruker gern for å si hva du liker, ordstilling med verbet på andre plass, og hvordan skolen er i Tyskland.', array[2, 3]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('tysk-8:skole-og-fritid', '## Skolefag – die Schulfächer
