insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('spansk-8:land-og-kultur', 's01', 'Hva forteller uttrykket «las comunidades autónomas» om hvordan Spania er delt inn? Oppgi også hvor mange slike regioner landet har.', 'Uttrykket viser til Spanias autonome regioner. Landet er delt inn i 17 slike regioner.', array['Forklarer at uttrykket viser til regioner i Spania.', 'Oppgir at det er 17 regioner.']::text[], 0),
  ('spansk-8:land-og-kultur', 's02', 'Beskriv hvordan Spania ligger i forhold til Portugal, Frankrike og havområdene rundt landet.', 'Spania ligger på Den iberiske halvøy sammen med Portugal og har kyst mot Middelhavet og Atlanterhavet. Pyreneene skiller Spania fra Frankrike.', array['Plasserer Spania på Den iberiske halvøy sammen med Portugal.', 'Nevner kyst mot Middelhavet og Atlanterhavet.', 'Forklarer at Pyreneene skiller Spania fra Frankrike.']::text[], 1),
  ('spansk-8:land-og-kultur', 's03', 'Spansk kom til Amerika etter at Columbus kom dit i 1492. Forklar sammenhengen mellom dette og språkbruken i Mellom- og Sør-Amerika i dag.', 'Spansk kom til Amerika etter Columbus’ ankomst i 1492. I dag er spansk hovedspråket i de fleste land i Mellom- og Sør-Amerika.', array['Knytter spanskens ankomst til Columbus’ ankomst i 1492.', 'Nevner at spansk er hovedspråk i de fleste land i Mellom- og Sør-Amerika.']::text[], 2),
  ('spansk-8:land-og-kultur', 's04', 'Sammenlign hovedspråket i Brasil med hovedspråket i de fleste andre land i Mellom- og Sør-Amerika.', 'I Brasil snakker man portugisisk. I de fleste andre land i Mellom- og Sør-Amerika er spansk hovedspråket.', array['Nevner portugisisk som språket i Brasil.', 'Nevner spansk som hovedspråk i de fleste andre land i Mellom- og Sør-Amerika.']::text[], 3),
  ('spansk-8:land-og-kultur', 's05', 'Sammenlign las tapas og la paella. Hva kjennetegner hver av disse matrettene?', 'Las tapas er små retter som deles. La paella er en risrett fra Valencia.', array['Forklarer at tapas er små retter som deles.', 'Forklarer at paella er en risrett fra Valencia.']::text[], 4),
  ('spansk-8:land-og-kultur', 's06', 'En elev skal presentere et kjent kulturuttrykk fra Argentina. Hvilket uttrykk kan eleven velge, og hva knytter det til Argentina?', 'Eleven kan presentere tango. Tangoen kommer fra Argentina.', array['Velger tango.', 'Knytter tango til Argentina.']::text[], 5),
  ('spansk-8:land-og-kultur', 's07', 'Et museum vil vise fram en kjent kunstner fra Mexico. Hvem fra kunstverdenen kan museet presentere, og hvilken nasjonalitet har kunstneren?', 'Museet kan presentere Frida Kahlo. Hun var en meksikansk kunstner.', array['Navngir Frida Kahlo.', 'Oppgir at hun var fra Mexico eller var meksikansk.']::text[], 6),
  ('spansk-8:land-og-kultur', 's08', 'En besøkende er i byen Buñol i august og ser folk kaste tomater på hverandre. Hva heter tradisjonen, og hva skjer under den?', 'Tradisjonen heter La Tomatina. I august kaster folk i Buñol tomater på hverandre.', array['Navngir La Tomatina.', 'Beskriver at folk kaster tomater på hverandre i Buñol.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('arbeidslivsfag-8:arbeidsoppdrag-og-planlegging', 'arbeidslivsfag-8', 'arbeidsoppdrag-og-planlegging', 'Arbeidsoppdrag og planlegging', 'Hva arbeidslivsfag er, hvordan du finner behov for varer og tjenester, avklarer en bestilling med oppdragsgiveren, lager en arbeidsplan og dokumenterer arbeidet.', array[1, 2]::int[], 0, 'utkast', '{}'::text[], false, now())
