  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Kvalitetskrav', 'Krav som er avtalt med oppdragsgiveren.', 1),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Kvalitetskontroll', 'Å sjekke arbeidet underveis og til slutt.', 2),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Sjekkliste', 'Liste over punkter som skal kontrolleres.', 3),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Holdbarhet', 'Hvor lenge noe tåler bruk.', 4),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Levering', 'Å overlevere produktet til kunden til avtalt tid og sted.', 5),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Merking', 'Informasjon på produktet, for eksempel om innhold og allergener.', 6),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Allergener', 'Stoffer i mat som kan gi allergiske reaksjoner, som nøtter og melk.', 7),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Kundeservice', 'Måten man møter og hjelper kunden på.', 8),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Klage', 'Når kunden sier fra om at noe ikke er som det skal.', 9),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Reklamasjon', 'Forbrukerens rett til å klage på en vare med feil.', 10),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Kalkulasjon', 'Utregning av hva et produkt koster å lage, og hva prisen bør være.', 11),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Materialkostnader', 'Det materialene koster.', 12),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Fortjeneste', 'Det som blir igjen når kostnadene er trukket fra inntektene.', 13),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'Merverdiavgift (moms)', 'Avgift på de fleste varer og tjenester som går til staten.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q01', 'flervalg', 'Hva betyr kvalitet i et arbeidsoppdrag?', array['At produktet er dyrt', 'At produktet er stort', 'At produktet er laget raskt', 'At produktet oppfyller kravene som er avtalt']::text[], 3, 'Kvalitetskravene avtales med oppdragsgiveren.', true, true, 0),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q02', 'flervalg', 'Når bør kvalitetskontroll gjøres?', array['Bare når alt er ferdig', 'Underveis og til slutt', 'Aldri', 'Bare hvis kunden klager']::text[], 1, 'Feil som oppdages tidlig, er lettere å rette.', true, true, 1),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q03', 'flervalg', 'Hva bør mat merkes med?', array['Innhold og allergener', 'Navnet på kokken', 'Været', 'Hvor mange som har smakt']::text[], 0, 'Merking av allergener kan forhindre alvorlige reaksjoner.', true, true, 2),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q04', 'flervalg', 'Hvordan bør du håndtere en klage fra en kunde?', array['Bli sint', 'Ignorere den', 'Lytte, beklage og finne en løsning', 'Si at kunden tar feil']::text[], 2, 'God klagehåndtering kan gjøre kunden fornøyd igjen.', true, true, 3),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q05', 'flervalg', 'Hva er fortjeneste?', array['Det som blir igjen når kostnadene er trukket fra', 'Prisen på materialene', 'Lønnen til de ansatte', 'Momsen']::text[], 0, 'Fortjenesten kan brukes til å utvikle bedriften.', true, true, 4),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q06', 'flervalg', 'Hva er en sjekkliste?', array['En regning', 'En handleliste', 'En liste over punkter som skal kontrolleres', 'En kundeliste']::text[], 2, 'Sjekklisten gjør kontrollen systematisk.', true, true, 5),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q07', 'flervalg', 'Hva hører med i en priskalkulasjon?', array['Bare prisen konkurrentene tar', 'Bare fortjenesten', 'Ingenting', 'Materialkostnader, andre kostnader, arbeid og fortjeneste']::text[], 3, 'Prisen bør dekke alle kostnadene.', true, true, 6),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q08', 'flervalg', 'Hva er god kundeservice?', array['Å snakke mest mulig selv', 'Å hilse, lytte og være høflig og ærlig', 'Å ignorere spørsmål', 'Å selge så dyrt som mulig']::text[], 1, 'Fornøyde kunder kommer gjerne tilbake.', true, true, 7),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q09', 'flervalg', 'Hva er reklamasjon?', array['Å klage på en vare med feil eller mangel', 'Reklame for et produkt', 'En type kvittering', 'Et tilbud']::text[], 0, 'Forbrukere har rett til å reklamere på varer med feil.', true, false, 8),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'q10', 'flervalg', 'Hva bør en god plakat for et produkt fortelle?', array['Hvem som laget den', 'Hvor mye materialene kostet', 'Hvor lang tid det tok', 'Hva man tilbyr, hva det koster og hvordan man bestiller']::text[], 3, 'God markedsføring er tydelig og nyttig for kunden.', true, false, 9),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'm01', 'sant-usant', 'Levering til avtalt tid er en del av kvaliteten.', array['Sant', 'Usant']::text[], 0, 'Et godt produkt som kommer for sent, dekker ikke kundens behov.', false, true, 10),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'm02', 'sant-usant', 'Kunden har ingen rettigheter hvis en vare har feil.', array['Sant', 'Usant']::text[], 1, 'Forbrukere har rett til å reklamere.', false, true, 11),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'm03', 'sant-usant', 'Nøyaktige oppskrifter og tegninger bidrar til jevn kvalitet.', array['Sant', 'Usant']::text[], 0, 'Da blir produktene like hver gang.', false, true, 12),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'm04', 'sant-usant', 'Prisen på et produkt trenger ikke dekke kostnadene.', array['Sant', 'Usant']::text[], 1, 'Hvis prisen er for lav, taper bedriften penger.', false, true, 13),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'm05', 'flervalg', 'Hva er materialkostnader?', array['Det materialene koster', 'Lønnen', 'Fortjenesten', 'Momsen']::text[], 0, 'Materialkostnadene er ofte den største utgiften i små oppdrag.', false, true, 14),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'm06', 'flervalg', 'Hva er holdbarhet?', array['Hvor pent noe er', 'Hvor lenge noe tåler bruk', 'Hvor dyrt noe er', 'Hvor raskt noe lages']::text[], 1, 'God holdbarhet er også bra for miljøet.', false, true, 15),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 'm07', 'flervalg', 'Hva er moms?', array['En type rabatt', 'En del av lønna', 'En avgift på varer og tjenester som går til staten', 'En gave til kunden']::text[], 2, 'Moms står for merverdiavgift.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 's01', 'Hva betyr holdbarhet, og hvordan kan den påvirke kvaliteten på en vare?', 'Holdbarhet er hvor lenge en vare tåler bruk. En vare med god holdbarhet beholder kvaliteten over tid.', array['Forklarer at holdbarhet handler om hvor lenge noe tåler bruk.', 'Knytter holdbarhet til hvor godt varen holder seg over tid.']::text[], 0),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 's02', 'Hvorfor kan nøyaktige arbeidstegninger, oppskrifter eller mål gjøre at flere produkter får jevn kvalitet?', 'De gir tydelige instrukser å følge. Da blir produktene laget på en mer lik måte.', array['Forklarer at tydelige instrukser hjelper arbeidet å bli utført likt hver gang.', 'Knytter dette til at produktene får jevn eller lik kvalitet.']::text[], 1),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 's03', 'En gruppe kontrollerer produktene først når alt arbeidet er ferdig. Forklar hvorfor det også er nyttig å kontrollere arbeidet underveis.', 'Da kan gruppa oppdage feil tidligere og rette dem før produktene er ferdige og skal leveres.', array['Forklarer at feil kan oppdages tidligere ved kontroll underveis.', 'Forklarer at feil kan rettes før levering.']::text[], 2),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 's04', 'Hvorfor er det viktig å merke mat med allergener?', 'Allergener er stoffer i mat som kan gi allergiske reaksjoner. Merking hjelper kunden med å finne ut om maten inneholder slike stoffer.', array['Forklarer at allergener kan gi allergiske reaksjoner.', 'Forklarer at merking gir kunden informasjon om innholdet i maten.']::text[], 3),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 's05', 'En kunde har bestilt et bestemt antall produkter til et avtalt sted og tidspunkt. Hva bør du kontrollere før du leverer bestillingen?', 'Jeg bør kontrollere at antallet stemmer med bestillingen, og at levering skjer til avtalt tid og sted.', array['Nevner at antallet må kontrolleres mot bestillingen.', 'Nevner at avtalt tid og sted må følges.']::text[], 4),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 's06', 'En kunde spør hva en vare brukes til, og hva den koster. Hvordan kan du svare på en måte som gir god kundeservice?', 'Jeg bør gi tydelig informasjon om hva varen brukes til og hva den koster. Jeg bør være høflig og ærlig når jeg svarer.', array['Gir informasjon om både varen og prisen.', 'Forklarer at kunden bør møtes høflig og ærlig.']::text[], 5),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 's07', 'Hva er forskjellen på en klage og en reklamasjon?', 'En klage er når kunden sier fra om at noe ikke er som det skal. En reklamasjon er forbrukerens rett til å klage på en vare med feil.', array['Forklarer at en klage er en melding fra kunden om at noe ikke er som det skal.', 'Forklarer at reklamasjon er forbrukerens rett til å klage på en vare med feil.']::text[], 6),
  ('arbeidslivsfag-8:kvalitet-og-kundeservice', 's08', 'Når du setter pris på et produkt, hvorfor bør prisen både dekke kostnadene og være noe kundene er villige til å betale?', 'Hvis prisen ikke dekker kostnadene, får man ikke dekket det produktet koster å lage. Hvis kundene ikke vil betale prisen, kan det bli vanskelig å selge produktet.', array['Forklarer at prisen må dekke kostnadene ved å lage produktet.', 'Forklarer at prisen også må være akseptabel for kundene.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-9:lyrikk', 'norsk-9', 'lyrikk', 'Lyrikk og språklige virkemidler', 'Hva som kjennetegner dikt, de viktigste språklige virkemidlene som metafor, besjeling og rim, og hvordan du analyserer og tolker et dikt.', array[2, 6, 1]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-9:lyrikk', '## Hva er lyrikk?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-9:lyrikk', 'Lyrikk', 'Dikt. Tekster med fortettet språk, bilder og ofte rytme.', 0),
  ('norsk-9:lyrikk', 'Verselinje', 'En linje i et dikt.', 1),
  ('norsk-9:lyrikk', 'Strofe', 'En gruppe verselinjer, som et avsnitt i diktet.', 2),
  ('norsk-9:lyrikk', 'Det lyriske jeget', 'Den som «snakker» i diktet. Ikke nødvendigvis forfatteren.', 3),
  ('norsk-9:lyrikk', 'Enderim', 'Ord som rimer på slutten av verselinjene: sol – stol.', 4),
  ('norsk-9:lyrikk', 'Bokstavrim', 'Flere ord som begynner på samme lyd: store, stille stjerner.', 5),
  ('norsk-9:lyrikk', 'Lydmalende ord', 'Ord som ligner lyden de beskriver: plask, surr, knitre.', 6),
  ('norsk-9:lyrikk', 'Frie vers', 'Dikt uten fast rim eller rytme.', 7),
  ('norsk-9:lyrikk', 'Sammenligning', 'To ting sammenlignes med «som» eller «lik»: sterk som en bjørn.', 8),
  ('norsk-9:lyrikk', 'Metafor', 'Noe beskrives som noe annet, uten «som»: Livet er en reise.', 9),
  ('norsk-9:lyrikk', 'Besjeling', 'Ting, dyr eller natur får menneskelige egenskaper: Vinden hvisket.', 10),
  ('norsk-9:lyrikk', 'Symbol', 'Et konkret bilde som står for noe mer, som en due for fred.', 11),
  ('norsk-9:lyrikk', 'Kontrast', 'Motsetninger som settes opp mot hverandre, som lys og mørke.', 12),
  ('norsk-9:lyrikk', 'Haiku', 'Japansk diktform med tre linjer på 5, 7 og 5 stavelser.', 13),
  ('norsk-9:lyrikk', 'Effekt av virkemiddel', 'Hva virkemidlet gjør med diktet, for eksempel skaper stemning eller forsterker et tema.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-9:lyrikk', 'q01', 'flervalg', '«Vinden hvisket i trærne.» Hvilket virkemiddel er dette?', array['Sammenligning', 'Besjeling', 'Enderim', 'Bokstavrim']::text[], 1, 'Vinden får en menneskelig egenskap, å hviske. Det er besjeling.', true, true, 0),
  ('norsk-9:lyrikk', 'q02', 'flervalg', 'Hva er forskjellen på en metafor og en sammenligning?', array['Sammenligningen bruker «som» eller «lik», metaforen gjør det ikke', 'Metaforen rimer, sammenligningen ikke', 'De er det samme', 'Metaforen er alltid lengre']::text[], 0, '«Sterk som en bjørn» er sammenligning. «Han er en bjørn» er metafor.', true, true, 1),
  ('norsk-9:lyrikk', 'q03', 'flervalg', 'Hvor mange stavelser har en haiku til sammen?', array['14', '12', '17', '20']::text[], 2, 'En haiku har 5 + 7 + 5 = 17 stavelser.', true, true, 2),
  ('norsk-9:lyrikk', 'q04', 'flervalg', 'Hva kalles den som snakker i et dikt?', array['Forfatteren', 'Fortelleren', 'Hovedpersonen', 'Det lyriske jeget']::text[], 3, 'Det lyriske jeget er stemmen i diktet, og det kan være en helt annen enn forfatteren.', true, true, 3),
  ('norsk-9:lyrikk', 'q05', 'flervalg', '«Store, stille stjerner» er et eksempel på', array['enderim', 'bokstavrim', 'metafor', 'ironi']::text[], 1, 'Ordene begynner på samme lyd, s. Det kalles bokstavrim eller allitterasjon.', true, true, 4),
  ('norsk-9:lyrikk', 'q06', 'flervalg', 'Hva er frie vers?', array['Dikt som alle kan lese gratis', 'Dikt uten fast rim og rytme', 'Dikt med 14 linjer', 'Dikt skrevet på dialekt']::text[], 1, 'Frie vers er vanlig i moderne lyrikk og har ingen faste regler for rim og rytme.', true, false, 5),
  ('norsk-9:lyrikk', 'q07', 'flervalg', 'Hva er det viktigste å gjøre når du har funnet et virkemiddel i en analyse?', array['Tell hvor mange det er', 'Skriv det med store bokstaver', 'Forklar hvilken effekt det har', 'Bytt det ut med et annet ord']::text[], 2, 'En analyse blir god når du forklarer hva virkemidlet gjør med diktet, ikke bare at det finnes.', true, true, 6),
  ('norsk-9:lyrikk', 'q08', 'flervalg', 'En hvit due i et dikt står for fred. Hva kalles dette?', array['Symbol', 'Kontrast', 'Rim', 'Lydmaling']::text[], 0, 'Et symbol er et konkret bilde som peker mot noe større og abstrakt.', true, true, 7),
  ('norsk-9:lyrikk', 'q09', 'flervalg', 'Hvilket ord er lydmalende?', array['stille', 'hus', 'blå', 'plask']::text[], 3, '«Plask» ligner lyden av noe som faller i vann.', true, true, 8),
  ('norsk-9:lyrikk', 'q10', 'flervalg', 'Hvorfor kan det være nyttig å kjenne den historiske konteksten til et dikt?', array['Fordi dikt aldri kan forstås uten den', 'Fordi den kan forklare hvorfor diktet handler om det det gjør', 'Fordi alle gamle dikt handler om det samme', 'Fordi konteksten bestemmer rimmønsteret']::text[], 1, 'Tiden diktet ble skrevet i, kan gi bakgrunn for tema og bilder, selv om diktet også kan leses i lys av vår egen tid.', true, false, 9),
  ('norsk-9:lyrikk', 'm01', 'sant-usant', 'Det lyriske jeget er alltid forfatteren selv.', array['Sant', 'Usant']::text[], 1, 'Det lyriske jeget er stemmen i diktet og kan være en oppdiktet person.', false, true, 10),
  ('norsk-9:lyrikk', 'm02', 'sant-usant', '«Hun var rask som vinden» er en sammenligning.', array['Sant', 'Usant']::text[], 0, 'Ordet «som» viser at to ting sammenlignes.', false, true, 11),
  ('norsk-9:lyrikk', 'm03', 'sant-usant', 'Alle dikt må rime.', array['Sant', 'Usant']::text[], 1, 'Mange dikt, særlig moderne, er skrevet på frie vers uten rim.', false, true, 12),
  ('norsk-9:lyrikk', 'm04', 'sant-usant', 'En sonett har 14 linjer.', array['Sant', 'Usant']::text[], 0, 'Sonetten er en fast diktform med 14 verselinjer.', false, true, 13),
  ('norsk-9:lyrikk', 'm05', 'flervalg', '«Tiden er en tyv.» Hvilket virkemiddel er dette?', array['Sammenligning', 'Bokstavrim', 'Lydmaling', 'Metafor']::text[], 3, 'Tiden beskrives som en tyv uten «som». Det er en metafor for at tiden tar noe fra oss.', false, true, 14),
  ('norsk-9:lyrikk', 'm06', 'flervalg', 'Hva er en strofe?', array['En gruppe verselinjer', 'Et rimord', 'En diktsamling', 'Tittelen på et dikt']::text[], 0, 'En strofe er en samling verselinjer, omtrent som et avsnitt i prosa.', false, true, 15),
  ('norsk-9:lyrikk', 'm07', 'flervalg', 'Lys og mørke i samme dikt er et eksempel på', array['rim', 'kontrast', 'besjeling', 'haiku']::text[], 1, 'Motsetninger som settes opp mot hverandre, kalles kontrast.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-9:lyrikk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-9:lyrikk', 's01', 'Lyrikk bruker ofte fortettet språk. Forklar hva det betyr, og hvordan det gjør at et dikt kan uttrykke mye med få ord.', 'Fortettet språk betyr at mye mening er pakket inn i få ord. Derfor kan hvert ord bidra til bilder, stemning eller flere betydninger.', array['Forklarer at fortettet språk pakker mye mening inn i få ord.', 'Knytter det til at ord kan bidra til flere betydninger, bilder eller stemning.']::text[], 0),
  ('norsk-9:lyrikk', 's02', 'Se på oppsettet:
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-9:retorikk-og-argumentasjon', 'norsk-9', 'retorikk-og-argumentasjon', 'Retorikk og argumentasjon', 'Appellformene etos, patos og logos, retoriske virkemidler, saklig og usaklig argumentasjon, og hvordan du bygger opp en argumenterende tekst.', array[6, 9, 10]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-9:retorikk-og-argumentasjon', '## Hva er retorikk?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-9:retorikk-og-argumentasjon', 'Retorikk', 'Læren om å overbevise gjennom tale og skrift.', 0),
  ('norsk-9:retorikk-og-argumentasjon', 'Appellform', 'En måte å overbevise på: etos, patos eller logos.', 1),
  ('norsk-9:retorikk-og-argumentasjon', 'Etos', 'Overbevisning gjennom avsenderens troverdighet, kunnskap og karakter.', 2),
  ('norsk-9:retorikk-og-argumentasjon', 'Patos', 'Overbevisning gjennom følelser, som medfølelse eller frykt.', 3),
  ('norsk-9:retorikk-og-argumentasjon', 'Logos', 'Overbevisning gjennom fornuft: fakta, tall og logiske argumenter.', 4),
  ('norsk-9:retorikk-og-argumentasjon', 'Aristoteles', 'Gresk filosof som beskrev de tre appellformene i antikken.', 5),
  ('norsk-9:retorikk-og-argumentasjon', 'Retorisk spørsmål', 'Et spørsmål som ikke krever svar, men skal få mottakeren til å tenke.', 6),
  ('norsk-9:retorikk-og-argumentasjon', 'Tretall', 'Oppramsing av tre ting for å gi rytme og tyngde.', 7),
  ('norsk-9:retorikk-og-argumentasjon', 'Påstand (tese)', 'Standpunktet en argumenterende tekst forsvarer.', 8),
  ('norsk-9:retorikk-og-argumentasjon', 'Motargument', 'Et argument mot din påstand. Å imøtegå det styrker teksten.', 9),
  ('norsk-9:retorikk-og-argumentasjon', 'Personangrep', 'Usaklig grep der man angriper personen i stedet for argumentet.', 10),
  ('norsk-9:retorikk-og-argumentasjon', 'Stråmann', 'Å gjengi motpartens syn feil og så angripe den feilaktige versjonen.', 11),
  ('norsk-9:retorikk-og-argumentasjon', 'Svartmaling', 'Å beskrive konsekvensene av et forslag mye verre enn de er.', 12),
  ('norsk-9:retorikk-og-argumentasjon', 'Generalisering', 'Å trekke bastante konklusjoner ut fra ett eller få eksempler.', 13),
  ('norsk-9:retorikk-og-argumentasjon', 'Saklig argument', 'Et argument som handler om saken og kan begrunnes med fakta og fornuft.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-9:retorikk-og-argumentasjon', 'q01', 'flervalg', 'Hvilken appellform bruker en lege som viser til sin erfaring?', array['Patos', 'Logos', 'Etos', 'Ironi']::text[], 2, 'Legen bygger troverdighet gjennom fagkunnskap og erfaring. Det er etos.', true, true, 0),
  ('norsk-9:retorikk-og-argumentasjon', 'q02', 'flervalg', 'En reklame viser en trist hundevalp for å få folk til å gi penger. Hvilken appellform er det?', array['Patos', 'Logos', 'Etos', 'Stråmann']::text[], 0, 'Bildet vekker medfølelse, altså følelser. Det er patos.', true, true, 1),
  ('norsk-9:retorikk-og-argumentasjon', 'q03', 'flervalg', '«80 % av elevene sover under åtte timer, og forskning viser at søvnmangel svekker læringen.» Hvilken appellform er dette?', array['Etos', 'Patos', 'Personangrep', 'Logos']::text[], 3, 'Tall og forskning appellerer til fornuften, altså logos.', true, true, 2),
  ('norsk-9:retorikk-og-argumentasjon', 'q04', 'flervalg', 'Hva er et retorisk spørsmål?', array['Et spørsmål i en quiz', 'Et spørsmål som ikke krever svar, men skal få deg til å tenke', 'Et spørsmål læreren stiller', 'Et spørsmål uten spørsmålstegn']::text[], 1, 'Eksempel: «Vil vi virkelig at barna våre skal vokse opp i et forurenset land?»', true, true, 3),
  ('norsk-9:retorikk-og-argumentasjon', 'q05', 'flervalg', '«Du er jo bare 14 år, hva vet du om politikk?» Hva slags argument er dette?', array['Et saklig argument', 'Et personangrep', 'Logos', 'Et tretall']::text[], 1, 'Utsagnet angriper personens alder i stedet for å svare på det personen faktisk mener.', true, true, 4),
  ('norsk-9:retorikk-og-argumentasjon', 'q06', 'flervalg', 'Hva betyr det å bruke en stråmann?', array['Å gjengi motpartens syn feil og angripe den feilaktige versjonen', 'Å bruke et sterkt bilde', 'Å vise til en ekspert', 'Å gjenta et ord tre ganger']::text[], 0, 'Stråmannen er lettere å slå enn det motparten egentlig mente.', true, true, 5),
  ('norsk-9:retorikk-og-argumentasjon', 'q07', 'flervalg', 'Hvor bør påstanden stå i et debattinnlegg?', array['Bare i avslutningen', 'Den skal ikke stå der', 'Tydelig i innledningen, og gjerne gjentatt til slutt', 'I en fotnote']::text[], 2, 'Leseren skal vite tidlig hva du mener. Å gjenta påstanden til slutt gir teksten en tydelig ramme.', true, false, 6),
  ('norsk-9:retorikk-og-argumentasjon', 'q08', 'flervalg', 'Hvorfor kan det lønne seg å ta med motargumenter i en argumenterende tekst?', array['For å bytte side', 'For å gjøre teksten lengre', 'For å forvirre leseren', 'Fordi det viser at du kjenner saken, og styrker troverdigheten']::text[], 3, 'Når du imøtegår motargumenter, viser du at du har vurdert saken fra flere sider. Det styrker etos.', true, true, 7),
  ('norsk-9:retorikk-og-argumentasjon', 'q09', 'flervalg', 'Hvilket av disse er en generalisering?', array['«Min kusine ble mobbet på nett, så alle ungdommer blir mobbet på nett.»', '«Undersøkelsen viser at 12 % har opplevd nettmobbing.»', '«Nettmobbing er et problem for noen.»', '«Jeg mener skolen bør gjøre mer mot mobbing.»']::text[], 0, 'Konklusjonen om «alle» bygger på ett enkelt eksempel.', true, true, 8),
  ('norsk-9:retorikk-og-argumentasjon', 'q10', 'flervalg', 'Hvilken appellform handler om avsenderens troverdighet?', array['Logos', 'Patos', 'Etos', 'Kairos']::text[], 2, 'Etos er knyttet til hvem avsenderen er og om vi stoler på vedkommende.', true, false, 9),
  ('norsk-9:retorikk-og-argumentasjon', 'm01', 'sant-usant', 'Gode talere bruker ofte alle tre appellformene.', array['Sant', 'Usant']::text[], 0, 'En kombinasjon av troverdighet, følelser og fakta overbeviser flest.', false, true, 10),
  ('norsk-9:retorikk-og-argumentasjon', 'm02', 'sant-usant', 'Et personangrep er et saklig argument.', array['Sant', 'Usant']::text[], 1, 'Personangrep handler om personen, ikke saken, og er usaklig.', false, true, 11),
  ('norsk-9:retorikk-og-argumentasjon', 'm03', 'sant-usant', 'Logos bygger på fakta og logiske resonnementer.', array['Sant', 'Usant']::text[], 0, 'Logos appellerer til mottakerens fornuft.', false, true, 12),
  ('norsk-9:retorikk-og-argumentasjon', 'm04', 'sant-usant', 'Du må være ufin mot motparten for å vinne en diskusjon.', array['Sant', 'Usant']::text[], 1, 'Man kan være uenig i sak og likevel respektfull mot personen. Det styrker også troverdigheten.', false, true, 13),
  ('norsk-9:retorikk-og-argumentasjon', 'm05', 'flervalg', 'Hva kalles det når konsekvensene av et forslag beskrives mye verre enn de er?', array['Tretall', 'Svartmaling', 'Logos', 'Etos']::text[], 1, 'Svartmaling skaper frykt for motpartens forslag på et overdrevet grunnlag.', false, true, 14),
  ('norsk-9:retorikk-og-argumentasjon', 'm06', 'flervalg', 'Hvilket retorisk virkemiddel er dette: «Vi skal kjempe for fremtiden, for naturen og for hverandre»?', array['Stråmann', 'Personangrep', 'Tretall', 'Retorisk spørsmål']::text[], 2, 'Tre ledd ramses opp etter hverandre og gir rytme og tyngde.', false, true, 15),
  ('norsk-9:retorikk-og-argumentasjon', 'm07', 'flervalg', 'Hva hører typisk hjemme i avslutningen av et debattinnlegg?', array['En oppfordring og en gjentakelse av påstanden', 'Et nytt tema', 'Alle kildene i fulltekst', 'En novelle']::text[], 0, 'Avslutningen samler trådene og ber gjerne leseren om å handle eller tenke nytt.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-9:retorikk-og-argumentasjon', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-9:retorikk-og-argumentasjon', 's01', 'Forklar med egne ord hva retorikk er.', 'Retorikk er læren om hvordan vi kan overbevise andre gjennom tale og skrift.', array['Forklarer at retorikk handler om å overbevise.', 'Får fram at det kan skje gjennom tale eller skrift.']::text[], 0),
  ('norsk-9:retorikk-og-argumentasjon', 's02', 'Sammenlign etos og logos. Hva bruker avsenderen for å overbevise i hver av disse appellformene?', 'Etos overbeviser ved å vise at avsenderen er troverdig, for eksempel gjennom kunnskap eller erfaring. Logos overbeviser med fakta, eksempler eller logiske resonnementer.', array['Knytter etos til avsenderens troverdighet, kunnskap eller erfaring.', 'Knytter logos til fakta, eksempler eller logikk.']::text[], 1),
  ('norsk-9:retorikk-og-argumentasjon', 's03', 'Hvilken betydning hadde Aristoteles for retorikken, og hva kalles de tre måtene å overbevise på som han beskrev?', 'Aristoteles var en gresk filosof som beskrev tre appellformer. De kalles etos, patos og logos.', array['Får fram at Aristoteles beskrev de tre måtene å overbevise på.', 'Nevner appellformene etos, patos og logos.']::text[], 2),
  ('norsk-9:retorikk-og-argumentasjon', 's04', 'Du lager en kampanje for å få elever til å holde skolegården ryddig. Skriv en kort setning med direkte tiltale, og forklar hvilken virkning tiltalen kan ha.', 'Du kan hjelpe til med å holde skolegården ryddig. Ved å si «du» snakker kampanjen direkte til mottakeren og gjør budskapet mer personlig.', array['Bruker «du» eller «dere» i en setning om å holde skolegården ryddig.', 'Forklarer at direkte tiltale retter budskapet direkte mot mottakeren.']::text[], 3),
  ('norsk-9:retorikk-og-argumentasjon', 's05', 'Forklar hva som kjennetegner et tretall, og hvorfor det kan gjøre et budskap mer virkningsfullt.', 'Et tretall er en oppramsing av tre ting. Det kan gi budskapet rytme og tyngde.', array['Forklarer at tretall er en oppramsing av tre ting.', 'Får fram at det kan gi rytme eller tyngde.']::text[], 4),
  ('norsk-9:retorikk-og-argumentasjon', 's06', 'En elev sier: «Hvis vi tillater mobiler i friminuttet, kommer ingen til å følge med i timene igjen.» Hvilket usaklig grep bruker eleven, og hvorfor?', 'Eleven bruker svartmaling. Påstanden framstiller konsekvensen av å tillate mobiler mye verre enn det er grunnlag for.', array['Identifiserer svartmaling.', 'Forklarer at konsekvensen blir framstilt som mye verre eller mer omfattende.']::text[], 5),
  ('norsk-9:retorikk-og-argumentasjon', 's07', 'En medelev mener at friminuttene bør bli kortere. Hvordan kan du svare på en saklig måte uten å angripe personen?', 'Jeg kan først lytte til begrunnelsen og deretter svare på det medelevens argument faktisk handler om. Jeg bør begrunne mitt eget syn og holde en respektfull tone.', array['Viser at man bør lytte og svare på argumentet, ikke angripe personen.', 'Får fram at svaret bør være begrunnet eller ha en saklig tone.']::text[], 6),
  ('norsk-9:retorikk-og-argumentasjon', 's08', 'I argumentet «Skolen bør ha flere leseplasser i biblioteket, fordi elevene da får flere steder å lese»: Hva er påstanden, og hvilken funksjon har delen etter «fordi»?', 'Påstanden er at skolen bør ha flere leseplasser i biblioteket. Delen etter «fordi» er en begrunnelse for påstanden.', array['Peker ut at skolen bør ha flere leseplasser i biblioteket som påstand.', 'Forklarer at delen etter «fordi» begrunner påstanden.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-9:setningsledd', 'norsk-9', 'setningsledd', 'Setningsledd og setningstyper', 'Subjekt, verbal, objekt, predikativ og adverbial, forskjellen på helsetninger og leddsetninger, og hvordan setningsanalyse hjelper deg å skrive bedre.', array[12, 11]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-9:setningsledd', '## Ordklasser og setningsledd
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-9:setningsledd', 'Setningsledd', 'Ett eller flere ord som har en bestemt funksjon i setningen, som subjekt eller objekt.', 0),
  ('norsk-9:setningsledd', 'Verbal', 'Verbet eller verbene i setningen: Kari har spist.', 1),
  ('norsk-9:setningsledd', 'Subjekt', 'Den som gjør noe. Finnes ved å spørre «hvem/hva + verbal?».', 2),
  ('norsk-9:setningsledd', 'Direkte objekt', 'Den eller det handlingen rammer. «Hvem/hva + verbal + subjekt?»', 3),
  ('norsk-9:setningsledd', 'Indirekte objekt', 'Mottakeren: Kari ga broren en gave. Kan ofte få «til» foran.', 4),
  ('norsk-9:setningsledd', 'Predikativ', 'Sier noe om subjektet etter være, bli eller hete: Kari er trøtt.', 5),
  ('norsk-9:setningsledd', 'Adverbial', 'Forteller hvor, når, hvordan eller hvorfor: i går, på kjøkkenet.', 6),
  ('norsk-9:setningsledd', 'Helsetning', 'Har subjekt og verbal og kan stå alene: Det regnet.', 7),
  ('norsk-9:setningsledd', 'Leddsetning', 'Har subjekt og verbal, men kan ikke stå alene. Innledes ofte av en subjunksjon.', 8),
  ('norsk-9:setningsledd', 'Subjunksjon', 'Ord som innleder leddsetninger: at, fordi, når, hvis, som.', 9),
  ('norsk-9:setningsledd', 'Inversjon', 'Verbal før subjekt, for eksempel etter en leddsetning: … ble vi inne.', 10),
  ('norsk-9:setningsledd', 'Sideordning', 'To likeverdige setninger bundet med og, men, eller, for, så.', 11),
  ('norsk-9:setningsledd', 'Underordning', 'En leddsetning som er en del av en helsetning.', 12),
  ('norsk-9:setningsledd', 'Ufullstendig setning', 'En leddsetning som står alene som om den var en helsetning: «Fordi jeg var syk.»', 13),
  ('norsk-9:setningsledd', 'Finne verbalet først', 'Første steg i setningsanalyse. Så finner du subjektet ved å spørre hvem/hva.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-9:setningsledd', 'q01', 'flervalg', 'Hva er subjektet i «Hunden bet postbudet»?', array['bet', 'postbudet', 'Hunden', 'Hunden bet']::text[], 2, 'Hvem bet? Hunden. Den som gjør handlingen, er subjektet.', true, true, 0),
  ('norsk-9:setningsledd', 'q02', 'flervalg', 'Hva er det direkte objektet i «Kari spiste en brødskive»?', array['Kari', 'spiste', 'en brødskive', 'Det finnes ikke']::text[], 2, 'Hva spiste Kari? En brødskive. Det er det handlingen rammer.', true, true, 1),
  ('norsk-9:setningsledd', 'q03', 'flervalg', 'Hvilket ledd er «trøtt» i «Kari er trøtt»?', array['Direkte objekt', 'Predikativ', 'Adverbial', 'Subjekt']::text[], 1, '«Trøtt» sier noe om subjektet etter verbet «er». Det er predikativ.', true, true, 2),
  ('norsk-9:setningsledd', 'q04', 'flervalg', 'Hvilket ledd er «i går» i «Vi spilte fotball i går»?', array['Adverbial', 'Subjekt', 'Verbal', 'Indirekte objekt']::text[], 0, '«I går» svarer på når. Tid, sted, måte og årsak er adverbialer.', true, true, 3),
  ('norsk-9:setningsledd', 'q05', 'flervalg', 'Hva er det indirekte objektet i «Mor ga barna is»?', array['Mor', 'ga', 'is', 'barna']::text[], 3, 'Barna er mottakerne. Du kan si «ga is til barna».', true, true, 4),
  ('norsk-9:setningsledd', 'q06', 'flervalg', 'Hvilken av disse er en leddsetning?', array['Jeg var syk.', 'fordi jeg var syk', 'Kom hit!', 'Det regnet i går.']::text[], 1, '«Fordi jeg var syk» innledes av en subjunksjon og kan ikke stå alene som en fullstendig setning.', true, true, 5),
  ('norsk-9:setningsledd', 'q07', 'flervalg', 'Hva er inversjon?', array['At subjektet kommer før verbalet', 'At setningen mangler verbal', 'At verbalet kommer før subjektet', 'At setningen står i fortid']::text[], 2, 'Etter en leddsetning først bytter subjekt og verbal plass: Fordi det regnet, ble vi inne.', true, true, 6),
  ('norsk-9:setningsledd', 'q08', 'flervalg', 'Hva er verbalet i «Elevene har lest boka»?', array['Elevene', 'har lest', 'boka', 'lest boka']::text[], 1, 'Verbalet kan bestå av flere verb. Her er det «har lest».', true, false, 7),
  ('norsk-9:setningsledd', 'q09', 'flervalg', 'Hvorfor er setningsanalyse nyttig når du skriver?', array['Den hjelper deg å sette komma riktig og unngå ufullstendige setninger', 'Den gjør teksten lengre', 'Den erstatter rettskriving', 'Den er bare nyttig i matematikk']::text[], 0, 'Når du ser hvor helsetninger og leddsetninger begynner og slutter, blir tegnsettingen riktigere.', true, false, 8),
  ('norsk-9:setningsledd', 'q10', 'flervalg', 'Hvilken setning har to sideordnede helsetninger?', array['Jeg vet at du kommer.', 'Hvis det regner, blir vi inne.', 'Boka som ligger der, er min.', 'Det regnet, og vi ble våte.']::text[], 3, '«Det regnet» og «vi ble våte» kan begge stå alene og er bundet sammen med konjunksjonen «og».', true, true, 9),
  ('norsk-9:setningsledd', 'm01', 'sant-usant', 'En helsetning kan stå alene.', array['Sant', 'Usant']::text[], 0, 'Helsetninger har subjekt og verbal og gir mening alene.', false, true, 10),
  ('norsk-9:setningsledd', 'm02', 'sant-usant', 'Et setningsledd består alltid av ett ord.', array['Sant', 'Usant']::text[], 1, 'Et ledd kan bestå av flere ord, som «den gamle mannen» eller «har spist».', false, true, 11),
  ('norsk-9:setningsledd', 'm03', 'sant-usant', '«Ikke» regnes som adverbial i setningsanalysen.', array['Sant', 'Usant']::text[], 0, '«Ikke» sier noe om verbalet eller hele setningen og analyseres som adverbial.', false, true, 12),
  ('norsk-9:setningsledd', 'm04', 'sant-usant', '«Når jeg kommer hjem.» er en fullstendig setning.', array['Sant', 'Usant']::text[], 1, 'Dette er en leddsetning som mangler en helsetning, for eksempel «…, skal jeg spise.»', false, true, 13),
  ('norsk-9:setningsledd', 'm05', 'flervalg', 'Hvilket ledd er «Ali» i «Han heter Ali»?', array['Direkte objekt', 'Subjekt', 'Predikativ', 'Adverbial']::text[], 2, 'Etter verbet «heter» sier «Ali» noe om subjektet. Det er predikativ.', false, true, 14),
  ('norsk-9:setningsledd', 'm06', 'flervalg', 'Hvilket ord innleder en leddsetning?', array['hvis', 'og', 'men', 'eller']::text[], 0, '«Hvis» er en subjunksjon. «Og», «men» og «eller» er konjunksjoner.', false, true, 15),
  ('norsk-9:setningsledd', 'm07', 'flervalg', 'Hva er subjektet i «I morgen skal Emma reise»?', array['I morgen', 'skal reise', 'reise', 'Emma']::text[], 3, 'Hvem skal reise? Emma. Adverbialet står først, og derfor kommer verbalet før subjektet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-9:setningsledd', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-9:setningsledd', 's01', 'Forklar forskjellen på en ordklasse og et setningsledd. Bruk gjerne et eksempel for å vise forskjellen.', 'Ordklassen forteller hva slags ord det er, mens setningsleddet viser hvilken funksjon ordet eller ordene har i en bestemt setning. For eksempel kan «Kari» være et ord og samtidig være subjekt i en setning.', array['Skiller mellom hva slags ord det er og hvilken funksjon det har i setningen.', 'Viser at setningsledd kan være ett eller flere ord som hører sammen.']::text[], 0),
  ('norsk-9:setningsledd', 's02', 'I setningen «Kari har lagt boka på bordet» skal du finne verbalet og subjektet. Forklar kort hvorfor det er lurt å finne verbalet først.', 'Verbalet er «har lagt», og subjektet er «Kari». Når verbalet er funnet, kan vi spørre «hvem har lagt?» for å finne subjektet.', array['Finner «har lagt» som verbal og «Kari» som subjekt.', 'Forklarer at man finner subjektet ved å spørre hvem eller hva som gjør noe med verbalet.']::text[], 1),
  ('norsk-9:setningsledd', 's03', 'I setningen «Læreren sendte elevene en melding» er «elevene» og «en melding» ulike typer objekt. Finn begge og forklar forskjellen på hva de viser.', '«Elevene» er indirekte objekt fordi de er mottakerne, mens «en melding» er direkte objekt fordi det er det handlingen rammer eller det som blir sendt.', array['Identifiserer «elevene» som indirekte objekt og «en melding» som direkte objekt.', 'Forklarer forskjellen mellom mottaker og det handlingen rammer.']::text[], 2),
  ('norsk-9:setningsledd', 's04', 'Legg til et adverbial som forteller når i setningen «Elevene arbeidet». Skriv den nye setningen, og forklar hva adverbialet forteller.', 'Elevene arbeidet etter skolen. «Etter skolen» er et adverbial som forteller når de arbeidet.', array['Legger til et uttrykk som forteller når arbeidet skjedde.', 'Forklarer at uttrykket er et adverbial fordi det forteller når.']::text[], 3),
  ('norsk-9:setningsledd', 's05', 'I setningen «Døra ble åpen» skal du finne predikativet og forklare hva det sier noe om.', '«Åpen» er predikativ. Det sier noe om subjektet «døra» etter verbet «ble».', array['Finner «åpen» som predikativ.', 'Forklarer at predikativet sier noe om subjektet etter verbet «ble».']::text[], 4),
  ('norsk-9:setningsledd', 's06', 'Sammenlign setningene «Det regnet, og vi ble inne» og «Vi ble inne fordi det regnet». Forklar hvordan setningene er bundet sammen på ulike måter.', 'I den første setningen er to helsetninger sideordnet med konjunksjonen «og». I den andre er «fordi det regnet» en leddsetning som er underordnet helsetningen «Vi ble inne».', array['Forklarer at den første setningen har sideordning mellom to helsetninger.', 'Forklarer at den andre har en leddsetning som er underordnet en helsetning.']::text[], 5),
  ('norsk-9:setningsledd', 's07', 'Skriv om setningen slik at den blir riktig: «Når timen sluttet, elevene gikk ut.» Forklar hva som endres i ordstillingen etter leddsetningen.', 'Når timen sluttet, gikk elevene ut. Etter leddsetningen kommer verbalet «gikk» før subjektet «elevene»; det kalles inversjon.', array['Skriver helsetningen etter leddsetningen med verbal før subjekt, for eksempel «gikk elevene».', 'Forklarer at denne ordstillingen kalles inversjon.']::text[], 6),
  ('norsk-9:setningsledd', 's08', '«Fordi bussen var forsinket.» står alene som en setning. Skriv den om slik at den blir en fullstendig setning, og forklar hvorfor den opprinnelige setningen er ufullstendig.', 'Fordi bussen var forsinket, kom vi for sent. Den opprinnelige setningen er ufullstendig fordi leddsetningen «Fordi bussen var forsinket» ikke kan stå alene og mangler en helsetning.', array['Legger til en helsetning slik at setningen blir fullstendig.', 'Forklarer at den opprinnelige setningen bare er en leddsetning og ikke kan stå alene.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-9:tekstbinding', 'norsk-9', 'tekstbinding', 'Tekstbinding og tekststruktur', 'Hvordan du binder setninger og avsnitt sammen med bindeord, gjentakelser og henvisninger, og hvordan du bygger opp en tekst med rød tråd.', array[11, 12]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-9:tekstbinding', '## Rød tråd
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-9:tekstbinding', 'Rød tråd', 'At leseren kan følge sammenhengen i teksten fra start til slutt.', 0),
  ('norsk-9:tekstbinding', 'Tekstbinding', 'Det som knytter setninger og avsnitt sammen, som bindeord, pronomen og gjentakelser.', 1),
  ('norsk-9:tekstbinding', 'Bindeord (konnektiv)', 'Ord som viser forholdet mellom tanker: derfor, likevel, dessuten.', 2),
  ('norsk-9:tekstbinding', 'Tillegg', 'Bindeord som legger til: og, dessuten, i tillegg.', 3),
  ('norsk-9:tekstbinding', 'Motsetning', 'Bindeord som viser kontrast: men, likevel, derimot.', 4),
  ('norsk-9:tekstbinding', 'Årsak', 'Bindeord som forklarer hvorfor: fordi, siden, ettersom.', 5),
  ('norsk-9:tekstbinding', 'Følge', 'Bindeord som viser konsekvens: derfor, dermed, av den grunn.', 6),
  ('norsk-9:tekstbinding', 'Oppsummering', 'Bindeord som samler trådene: altså, kort sagt, alt i alt.', 7),
  ('norsk-9:tekstbinding', 'Pronomen som tekstbinding', 'Pronomen viser tilbake til noe som er nevnt: Ibsen … Han …', 8),
  ('norsk-9:tekstbinding', 'Synonym', 'Et ord med samme eller nesten samme betydning. Gir variasjon.', 9),
  ('norsk-9:tekstbinding', 'Uklar henvisning', 'Når det ikke går fram hvem et pronomen viser til.', 10),
  ('norsk-9:tekstbinding', 'Temasetning', 'Setningen som sier hva avsnittet handler om.', 11),
  ('norsk-9:tekstbinding', 'Kommentarsetning', 'Setninger i avsnittet som utdyper, forklarer eller gir eksempler.', 12),
  ('norsk-9:tekstbinding', 'Innledning – hoveddel – avslutning', 'Vanlig struktur i fagtekster og argumenterende tekster.', 13),
  ('norsk-9:tekstbinding', 'Bearbeide', 'Forbedre en tekst ved å se på innhold, struktur, bindeord og språk.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-9:tekstbinding', 'q01', 'flervalg', 'Hvilket bindeord uttrykker motsetning?', array['derfor', 'likevel', 'dessuten', 'først']::text[], 1, '«Likevel» viser at noe skjer til tross for det som er sagt før. Det er motsetning.', true, true, 0),
  ('norsk-9:tekstbinding', 'q02', 'flervalg', 'Hvilket bindeord passer? «Det var glatt ute. … kjørte bussen sakte.»', array['Derfor', 'Derimot', 'For eksempel', 'Dessuten']::text[], 0, 'Glatt føre er årsaken, og at bussen kjørte sakte er følgen. «Derfor» uttrykker følge.', true, true, 1),
  ('norsk-9:tekstbinding', 'q03', 'flervalg', 'Hva er en rød tråd i en tekst?', array['En tråd i tekstilfaget', 'At teksten har rød skrift', 'At leseren kan følge sammenhengen gjennom hele teksten', 'At teksten har mange avsnitt']::text[], 2, 'Rød tråd betyr at tankene henger logisk sammen fra start til slutt.', true, true, 2),
  ('norsk-9:tekstbinding', 'q04', 'flervalg', '«Ibsen skrev Et dukkehjem. Dramatikeren ble verdensberømt.» Hvordan er setningene bundet sammen?', array['Med et bindeord', 'Med tegnsetting', 'Med en temasetning', 'Med en omskrivning av Ibsen']::text[], 3, '«Dramatikeren» viser tilbake til Ibsen. Omskrivninger binder teksten uten å gjenta samme ord.', true, true, 3),
  ('norsk-9:tekstbinding', 'q05', 'flervalg', 'Hva er galt med «Lise sa til Maria at hun hadde vunnet»?', array['Setningen mangler verbal', 'Det er uklart hvem «hun» viser til', 'Det skal være komma før «at»', 'Ingenting']::text[], 1, '«Hun» kan vise til både Lise og Maria. Uklare henvisninger bør omskrives.', true, true, 4),
  ('norsk-9:tekstbinding', 'q06', 'flervalg', 'Hvor står temasetningen vanligvis?', array['Først i avsnittet', 'I overskriften', 'Sist i teksten', 'I en fotnote']::text[], 0, 'Temasetningen står ofte først og forteller leseren hva avsnittet skal handle om.', true, true, 5),
  ('norsk-9:tekstbinding', 'q07', 'flervalg', 'Hvilket bindeord uttrykker årsak?', array['altså', 'deretter', 'ettersom', 'derimot']::text[], 2, '«Ettersom» betyr omtrent det samme som «fordi» og forklarer årsaken.', true, true, 6),
  ('norsk-9:tekstbinding', 'q08', 'flervalg', 'Hva bør avslutningen av en fagtekst IKKE gjøre?', array['Oppsummere', 'Konkludere', 'Knytte tilbake til innledningen', 'Introdusere et helt nytt poeng']::text[], 3, 'Nye poenger hører hjemme i hoveddelen. Avslutningen skal samle trådene.', true, true, 7),
  ('norsk-9:tekstbinding', 'q09', 'flervalg', 'Hvorfor bør du variere bindeordene?', array['For at teksten ikke skal bli ensformig og for å vise presist hvordan tankene henger sammen', 'Fordi det er forbudt å bruke «og»', 'For å gjøre teksten kortere', 'For at leseren skal bli forvirret']::text[], 0, 'Mange «og så» gjør teksten monoton. Presise bindeord viser leseren tankegangen.', true, false, 8),
  ('norsk-9:tekstbinding', 'q10', 'flervalg', 'Hvilket bindeord innleder en oppsummering?', array['først', 'kort sagt', 'fordi', 'for eksempel']::text[], 1, '«Kort sagt» varsler at det kommer en oppsummering av det som er sagt.', true, false, 9),
  ('norsk-9:tekstbinding', 'm01', 'sant-usant', '«Dessuten» er et bindeord som uttrykker tillegg.', array['Sant', 'Usant']::text[], 0, '«Dessuten» legger til et nytt poeng i samme retning.', false, true, 10),
  ('norsk-9:tekstbinding', 'm02', 'sant-usant', 'Et avsnitt bør inneholde mange ulike hovedtanker.', array['Sant', 'Usant']::text[], 1, 'Et avsnitt bør samle én hovedtanke. Nye tanker får nye avsnitt.', false, true, 11),
  ('norsk-9:tekstbinding', 'm03', 'sant-usant', 'Å gjenta nøkkelord kan være en måte å binde teksten sammen på.', array['Sant', 'Usant']::text[], 0, 'Nøkkelord som går igjen, holder temaet samlet. Men varier gjerne med synonymer.', false, true, 12),
  ('norsk-9:tekstbinding', 'm04', 'sant-usant', '«Derfor» uttrykker motsetning.', array['Sant', 'Usant']::text[], 1, '«Derfor» uttrykker følge eller konsekvens.', false, true, 13),
  ('norsk-9:tekstbinding', 'm05', 'flervalg', 'Hvilket bindeord passer? «Mange liker sommeren. Jeg, …, foretrekker vinteren.»', array['derfor', 'altså', 'derimot', 'fordi']::text[], 2, 'Setningen står i motsetning til den forrige, og «derimot» markerer kontrasten.', false, true, 14),
  ('norsk-9:tekstbinding', 'm06', 'flervalg', 'Hva gjør du enklest for å avsløre hopp i tankegangen?', array['Leser teksten høyt', 'Teller ordene', 'Bytter skrifttype', 'Sletter avsnitt']::text[], 0, 'Når du leser høyt, hører du lettere hvor overgangene mangler.', false, true, 15),
  ('norsk-9:tekstbinding', 'm07', 'flervalg', 'Hva kalles setningene i et avsnitt som utdyper temasetningen?', array['Overskrifter', 'Kommentarsetninger', 'Leddsetninger', 'Ingresser']::text[], 1, 'Kommentarsetninger forklarer, begrunner og gir eksempler på det temasetningen sier.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-9:tekstbinding', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-9:tekstbinding', 's01', 'En tekst har mange bindeord, men leseren forstår ikke hvordan tankene henger sammen. Forklar hva som må til for at tekstbindingen skal være funksjonell.', 'Tekstbindingen er funksjonell når den viser hvordan tankene henger sammen, ikke bare når det står mange bindeord. Da kan leseren lettere følge tankegangen.', array['Forklarer at tekstbindingen må vise en meningsfull sammenheng mellom tanker.', 'Forklarer at sammenhengen hjelper leseren å følge tankegangen.']::text[], 0),
  ('norsk-9:tekstbinding', 's02', 'Forklar forskjellen på bindeord for årsak og bindeord for følge. Bruk «fordi» og «derfor» i et eksempel som viser den samme sammenhengen.', '«Fordi» viser årsaken, mens «derfor» viser følgen. Jeg ble hjemme fordi jeg var syk. Jeg var syk, derfor ble jeg hjemme.', array['Viser at årsaksbindeord forklarer hvorfor noe skjer, og at følgebindeord viser konsekvensen.', 'Bruker «fordi» og «derfor» riktig i en sammenheng der årsak og følge henger sammen.']::text[], 1),
  ('norsk-9:tekstbinding', 's03', 'Skriv to setninger der et pronomen viser tydelig tilbake til en person eller ting i den første setningen. Forklar hva pronomenet viser til, og hvordan det binder setningene sammen.', 'Læreren åpnet boka. Hun leste høyt. «Hun» viser tilbake til læreren og knytter setningene sammen.', array['Gir et tydelig eksempel der pronomenet viser tilbake til noe som allerede er nevnt.', 'Forklarer hvordan pronomenet knytter setningene sammen.']::text[], 2),
  ('norsk-9:tekstbinding', 's04', 'Les avsnittet: «Et avsnitt samler én hovedtanke. Det starter gjerne med en temasetning. Andre setninger kan utdype tanken.» Hvilken setning fungerer som temasetning, og hvilken fungerer som kommentarsetning? Forklar hvorfor.', 'Den første setningen fungerer som temasetning fordi den sier hva avsnittet handler om. Den andre og tredje setningen fungerer som kommentarsetninger fordi de utdyper dette.', array['Velger den første setningen som temasetning og forklarer at den presenterer hovedtanken.', 'Identifiserer de andre setningene som utdyping eller kommentar til hovedtanken.']::text[], 3),
  ('norsk-9:tekstbinding', 's05', 'En fagtekst kan ordne hoveddelen etter tid eller etter viktighet. Sammenlign disse to måtene å strukturere stoffet på, og forklar hvordan hver av dem kan skape en logisk rekkefølge.', 'Når stoffet ordnes etter tid, kommer hendelser eller punkter i tidsrekkefølge. Når det ordnes etter viktighet, plasseres punktene i en rekkefølge etter hvor viktige de er.', array['Forklarer at tidsrekkefølge organiserer stoffet etter når noe skjer.', 'Forklarer at rekkefølge etter viktighet organiserer stoffet ut fra hvor viktige punktene er.']::text[], 4),
  ('norsk-9:tekstbinding', 's06', 'En elev har skrevet: «Først presenterer innledningen temaet. Og så utdyper hoveddelen temaet. Og så oppsummerer avslutningen.» Skriv om bindeordene slik at rekkefølgen blir tydelig og språket mindre ensformig.', 'Først presenterer innledningen temaet. Deretter utdyper hoveddelen temaet. Til slutt oppsummerer avslutningen.', array['Bruker ulike tids- eller rekkefølgeord som viser hva som kommer først, videre og til slutt.', 'Beholder den logiske rekkefølgen mellom innledning, hoveddel og avslutning.']::text[], 5),
  ('norsk-9:tekstbinding', 's07', 'Når du leser en tekst høyt, merker du at tankegangen hopper brått mellom avsnittene. Hva bør du undersøke og forbedre når du bearbeider teksten?', 'Jeg bør undersøke om det går tydelig fram hvordan avsnittene henger sammen, og om bindeordene viser forbindelsen presist. Jeg kan endre tekstbindingen slik at overgangen mellom tankene blir lettere å følge.', array['Viser til at sammenhengen eller overgangen mellom avsnittene bør undersøkes.', 'Foreslår å forbedre tekstbindingen, for eksempel ved å bruke mer presise bindeord.']::text[], 6),
  ('norsk-9:tekstbinding', 's08', 'Sammenlign gjentakelse av nøkkelord med bruk av synonymer eller omskrivninger. Forklar hvordan begge deler kan bidra til at en tekst henger sammen.', 'Når et nøkkelord gjentas, holder det temaet samlet. Synonymer og omskrivninger kan vise til det samme temaet, men gir variasjon slik at man slipper å gjenta nøyaktig det samme ordet.', array['Forklarer at gjentakelse av nøkkelord holder temaet samlet.', 'Forklarer at synonymer eller omskrivninger gir variasjon samtidig som de viser til samme tema.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-9:kildebruk', 'norsk-9', 'kildebruk', 'Kildebruk og kildekritikk', 'Hvordan du vurderer om en kilde er pålitelig, hvordan du siterer og gjengir med egne ord, og hvordan du viser til kilder og unngår plagiat.', array[7]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-9:kildebruk', '## Hva er en kilde?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-9:kildebruk', 'Kilde', 'Der du henter informasjon fra, som en bok, nettside eller et intervju.', 0),
  ('norsk-9:kildebruk', 'Kildekritikk', 'Å vurdere hvor pålitelig en kilde er: hvem, hvorfor, når og hvor.', 1),
  ('norsk-9:kildebruk', 'Primærkilde', 'En original kilde, som en undersøkelse, et brev eller et intervju.', 2),
  ('norsk-9:kildebruk', 'Sekundærkilde', 'En kilde som bearbeider andre kilder, som en lærebok eller et leksikon.', 3),
  ('norsk-9:kildebruk', 'Sitat', 'Andres ord gjengitt nøyaktig, i anførselstegn «slik».', 4),
  ('norsk-9:kildebruk', 'Parafrase', 'Å gjengi andres tanker med egne ord. Trenger også kildehenvisning.', 5),
  ('norsk-9:kildebruk', 'Kildehenvisning', 'En henvisning i teksten som viser hvor en opplysning kommer fra.', 6),
  ('norsk-9:kildebruk', 'Kildeliste', 'En oversikt over alle kildene, bakerst i teksten.', 7),
  ('norsk-9:kildebruk', 'Nettkilde i kildelisten', 'Avsender, tittel, år, nettadresse og dato du leste den.', 8),
  ('norsk-9:kildebruk', 'Plagiat', 'Å presentere andres tekst eller ideer som sine egne. Regnes som fusk.', 9),
  ('norsk-9:kildebruk', 'Opphavsrett', 'Retten den som har laget et verk, har til å bestemme over bruken av det.', 10),
  ('norsk-9:kildebruk', 'Åpen lisens', 'En lisens som gir lov til å bruke et verk på visse vilkår, ofte med navngivelse.', 11),
  ('norsk-9:kildebruk', 'Avsender', 'Den som står bak en tekst. Påvirker hvor mye du kan stole på den.', 12),
  ('norsk-9:kildebruk', 'Sjekke mot andre kilder', 'Bekrefte viktige opplysninger i minst én uavhengig kilde til.', 13),
  ('norsk-9:kildebruk', 'KI-verktøy og kilder', 'KI kan finne på fakta og kilder. Oppgi bruken og kontroller opplysningene.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-9:kildebruk', 'q01', 'flervalg', 'Hva betyr kildekritikk?', array['Å kritisere forfatteren', 'Å vurdere hvor pålitelig en kilde er', 'Å bruke så få kilder som mulig', 'Å slette kilder man er uenig i']::text[], 1, 'Kildekritikk handler om å vurdere hvem som står bak, hvorfor, når og hvor noe er publisert.', true, true, 0),
  ('norsk-9:kildebruk', 'q02', 'flervalg', 'Hvilken kilde er en primærkilde?', array['En lærebok om andre verdenskrig', 'Et leksikon', 'En dagbok skrevet under andre verdenskrig', 'En nettside som oppsummerer bøker']::text[], 2, 'Dagboken er skrevet av en som opplevde hendelsene, og er derfor en original kilde.', true, true, 1),
  ('norsk-9:kildebruk', 'q03', 'flervalg', 'Hvordan markerer du et kort sitat i teksten?', array['Med kursiv uten henvisning', 'Med anførselstegn og kildehenvisning', 'Med store bokstaver', 'Det trenger ingen markering']::text[], 1, 'Sitatet settes i anførselstegn, og du viser til hvor det kommer fra.', true, true, 2),
  ('norsk-9:kildebruk', 'q04', 'flervalg', 'Hva er en parafrase?', array['Et langt sitat', 'En kildeliste', 'En gjengivelse av andres tanker med egne ord', 'En bildetekst']::text[], 2, 'En parafrase formulerer andres innhold med egne ord, men krever fortsatt kildehenvisning.', true, true, 3),
  ('norsk-9:kildebruk', 'q05', 'flervalg', 'Hva er plagiat?', array['Å presentere andres tekst eller ideer som sine egne', 'Å bruke mange kilder', 'Å sitere riktig', 'Å skrive en kildeliste']::text[], 0, 'Plagiat er uærlig fordi du tar æren for noe andre har laget.', true, true, 4),
  ('norsk-9:kildebruk', 'q06', 'flervalg', 'Hva bør du ta med når du oppgir en nettside i kildelisten?', array['Bare nettadressen', 'Bare tittelen', 'Bare datoen', 'Avsender, tittel, år, nettadresse og dato du leste den']::text[], 3, 'Nettsider kan endres, så datoen du leste er viktig i tillegg til avsender og adresse.', true, true, 5),
  ('norsk-9:kildebruk', 'q07', 'flervalg', 'Du finner en påstand på en ukjent blogg. Hva bør du gjøre?', array['Bruke den uten videre', 'Sjekke om påstanden stemmer med andre, pålitelige kilder', 'Skrive at den er sann', 'Kopiere hele bloggen']::text[], 1, 'Ukjente avsendere bør kontrolleres mot andre kilder før du bruker opplysningene.', true, false, 6),
  ('norsk-9:kildebruk', 'q08', 'flervalg', 'Trenger en parafrase kildehenvisning?', array['Nei, fordi du har brukt egne ord', 'Bare hvis den er lang', 'Bare i nettartikler', 'Ja, fordi ideen er hentet fra noen andre']::text[], 3, 'Selv om ordene er dine, er innholdet hentet fra en kilde, og det må leseren få vite.', true, true, 7),
  ('norsk-9:kildebruk', 'q09', 'flervalg', 'Hvorfor bør du være forsiktig med fakta fra KI-verktøy?', array['Fordi de alltid er for korte', 'Fordi de kan finne på fakta og kilder som ikke finnes', 'Fordi de bare svarer på engelsk', 'Fordi de er ulovlige']::text[], 1, 'KI-verktøy kan gi svar som høres riktige ut, men er feil. Kontroller opplysningene og oppgi bruken.', true, false, 8),
  ('norsk-9:kildebruk', 'q10', 'flervalg', 'Kan du bruke et hvilket som helst bilde fra nettet i en presentasjon?', array['Ja, alt på nettet er gratis', 'Ja, hvis bildet er pent', 'Nei, bilder er beskyttet av opphavsrett med mindre du har lov eller de har åpen lisens', 'Ja, hvis du endrer fargene']::text[], 2, 'Bilder er åndsverk. Bruk bilder med åpen lisens eller egne bilder, og oppgi alltid kilden.', true, true, 9),
  ('norsk-9:kildebruk', 'm01', 'sant-usant', 'En lærebok er en sekundærkilde.', array['Sant', 'Usant']::text[], 0, 'Læreboka bearbeider og oppsummerer andre kilder.', false, true, 10),
  ('norsk-9:kildebruk', 'm02', 'sant-usant', 'Du trenger ikke oppgi kilde hvis du skriver med egne ord.', array['Sant', 'Usant']::text[], 1, 'Innhold og ideer fra andre skal alltid ha kildehenvisning, også når de er omformulert.', false, true, 11),
  ('norsk-9:kildebruk', 'm03', 'sant-usant', 'Det er lurt å sjekke viktige opplysninger i mer enn én kilde.', array['Sant', 'Usant']::text[], 0, 'Når flere uavhengige kilder sier det samme, er opplysningen mer pålitelig.', false, true, 12),
  ('norsk-9:kildebruk', 'm04', 'sant-usant', 'En nettside som selger et produkt, er alltid en nøytral kilde om produktet.', array['Sant', 'Usant']::text[], 1, 'Avsenderen har interesse av å selge og kan derfor fremstille produktet positivt.', false, true, 13),
  ('norsk-9:kildebruk', 'm05', 'flervalg', 'Hvilket spørsmål er en del av kildekritikk?', array['Hvem har laget teksten?', 'Hvor lang er teksten?', 'Hvilken skrifttype er brukt?', 'Hvor mange bilder er det?']::text[], 0, 'Avsenderen sier mye om hvor pålitelig og nøytral en kilde er.', false, true, 14),
  ('norsk-9:kildebruk', 'm06', 'flervalg', 'Hvor står kildelisten vanligvis?', array['Først i teksten', 'I overskriften', 'Bakerst i teksten', 'Midt i hoveddelen']::text[], 2, 'Kildelisten samler alle kildene til slutt, slik at leseren kan finne dem.', false, true, 15),
  ('norsk-9:kildebruk', 'm07', 'flervalg', 'Når bør du bruke et sitat i stedet for en parafrase?', array['Alltid', 'Når ordlyden i seg selv er viktig', 'Når teksten er lang', 'Aldri']::text[], 1, 'Sitater passer når nøyaktig formulering betyr noe, for eksempel en berømt uttalelse.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-9:kildebruk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-9:kildebruk', 's01', 'En elev intervjuer et øyenvitne og bruker også en lærebok som omtaler det samme intervjuet. Sammenlign kildene, og forklar hvordan de skiller seg fra hverandre.', 'Intervjuet med øyenvitnet er en primærkilde fordi det er en original kilde. Læreboka er en sekundærkilde fordi den omtaler og bearbeider andre kilder.', array['Forklarer at intervjuet er en original kilde.', 'Forklarer at læreboka bearbeider eller omtaler andre kilder.']::text[], 0),
  ('norsk-9:kildebruk', 's02', 'En tekst om et produkt er laget av firmaet som selger produktet, og målet er å få folk til å kjøpe det. Forklar hvordan dette bør påvirke vurderingen av teksten som kilde.', 'Firmaet er avsenderen, og teksten er laget for å selge. Derfor bør leseren være oppmerksom på at teksten kan være vinklet, og vurdere hvem som står bak og hvorfor den er laget.', array['Får fram at avsenderen har en interesse i å selge produktet.', 'Knytter denne interessen til at innholdet bør vurderes kritisk, ikke bare godtas uten videre.']::text[], 1),
  ('norsk-9:kildebruk', 's03', 'En nettside ble laget for lenge siden, og du skal bruke opplysninger fra den i en fagtekst. Forklar hvorfor datoen kan ha betydning, og hva du bør undersøke.', 'Datoen er viktig fordi informasjonen kan ha blitt utdatert. Jeg bør undersøke når nettsiden sist ble oppdatert, og om opplysningene fortsatt stemmer.', array['Forklarer at eldre informasjon kan være utdatert eller ikke lenger riktig.', 'Får fram at dato eller oppdatering bør undersøkes.']::text[], 2),
  ('norsk-9:kildebruk', 's04', 'Forklar forskjellen på en kildehenvisning i teksten og en kildeliste bakerst i teksten.', 'En kildehenvisning viser i teksten hvor en opplysning kommer fra. Kildelista gir en oversikt over alle kildene som er brukt.', array['Forklarer at kildehenvisningen knytter en opplysning i teksten til kilden.', 'Forklarer at kildelista samler kildene som er brukt.']::text[], 3),
  ('norsk-9:kildebruk', 's05', 'Du finner et bilde på nettet som har en åpen lisens. Hva bør du undersøke og gjøre før du bruker bildet i en presentasjon?', 'Jeg bør undersøke vilkårene i lisensen, siden en åpen lisens gir lov til bruk på bestemte vilkår. Jeg må også oppgi hvem som har laget bildet.', array['Får fram at vilkårene for den åpne lisensen må følges.', 'Får fram at bildeskaperen skal oppgis.']::text[], 4),
  ('norsk-9:kildebruk', 's06', 'En elev har brukt et KI-verktøy som foreslo opplysninger og kilder til en fagtekst. Beskriv hva eleven bør gjøre før teksten leveres.', 'Eleven bør kontrollere at opplysningene stemmer, og at kildene faktisk finnes. Eleven bør også oppgi hvordan KI-verktøyet er brukt.', array['Får fram at opplysninger og foreslåtte kilder må kontrolleres.', 'Får fram at bruken av KI-verktøyet bør oppgis.']::text[], 5),
  ('norsk-9:kildebruk', 's07', 'To kilder gir ulike opplysninger om samme sak. Forklar hvordan det å sjekke en uavhengig kilde til kan hjelpe deg med å vurdere opplysningene.', 'En uavhengig kilde til kan bekrefte om en av opplysningene stemmer, eller vise at saken er usikker. Da får jeg et bedre grunnlag for å vurdere hvor pålitelig informasjonen er.', array['Forklarer at en uavhengig kilde kan bekrefte eller utfordre opplysningene.', 'Knytter sammenligningen til vurdering av hvor pålitelig informasjonen er.']::text[], 6),
  ('norsk-9:kildebruk', 's08', 'En elev bruker et bilde uten å undersøke om det er lov å bruke, men skriver navnet på den som laget bildet. Forklar hvorfor dette ikke nødvendigvis er nok.', 'Det er bra å oppgi hvem som laget bildet, men det gir ikke automatisk lov til å bruke det. Bildet er beskyttet av opphavsrett, så eleven må også ha tillatelse eller følge en åpen lisens.', array['Får fram at det å oppgi bildeskaperen ikke i seg selv gir tillatelse til bruk.', 'Nevner at bruk krever tillatelse eller må følge en åpen lisens.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-9:nabosprak', 'norsk-9', 'nabosprak', 'Nabospråk: svensk og dansk', 'Hva som er likt og ulikt i norsk, svensk og dansk, typiske kjennetegn ved skrift og uttale, og falske venner som kan skape misforståelser.', array[4]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-9:nabosprak', '## Skandinaviske språk
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-9:nabosprak', 'Nabospråk', 'Svensk og dansk, som ligger så nær norsk at vi stort sett forstår dem.', 0),
  ('norsk-9:nabosprak', 'Nordgermanske språk', 'Norsk, svensk, dansk, islandsk og færøysk. Alle kommer fra norrønt.', 1),
  ('norsk-9:nabosprak', 'ä og ö', 'Svenske bokstaver som tilsvarer norsk æ og ø.', 2),
  ('norsk-9:nabosprak', 'och og inte', 'Svensk for «og» og «ikke».', 3),
  ('norsk-9:nabosprak', 'flicka', 'Svensk for «jente».', 4),
  ('norsk-9:nabosprak', 'Bløte konsonanter', 'Dansk uttale der for eksempel d i «mad» uttales mykt.', 5),
  ('norsk-9:nabosprak', 'Stød', 'Et lite brudd i stemmen i dansk uttale som kan skille ord fra hverandre.', 6),
  ('norsk-9:nabosprak', 'halvtreds', 'Dansk for 50.', 7),
  ('norsk-9:nabosprak', 'Falske venner', 'Ord som ser like ut i to språk, men betyr noe forskjellig.', 8),
  ('norsk-9:nabosprak', 'rolig (svensk)', 'Betyr morsom.', 9),
  ('norsk-9:nabosprak', 'glass (svensk)', 'Betyr iskrem.', 10),
  ('norsk-9:nabosprak', 'semester (svensk)', 'Betyr ferie.', 11),
  ('norsk-9:nabosprak', 'frokost (dansk)', 'Betyr lunsj. Dansk «morgenmad» er frokost.', 12),
  ('norsk-9:nabosprak', 'grine (dansk)', 'Betyr å le.', 13),
  ('norsk-9:nabosprak', 'Bokmål og dansk', 'Bokmål har utviklet seg fra dansk skriftspråk, derfor er skriften ganske lik.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-9:nabosprak', 'q01', 'flervalg', 'Hva betyr det svenske ordet «rolig»?', array['Rolig', 'Morsom', 'Sint', 'Trøtt']::text[], 1, '«Rolig» på svensk betyr morsom. Det er en falsk venn.', true, true, 0),
  ('norsk-9:nabosprak', 'q02', 'flervalg', 'Hva betyr det svenske ordet «glass»?', array['Et drikkeglass', 'Et vindu', 'Iskrem', 'Is på vannet']::text[], 2, '«Glass» er svensk for iskrem. Et drikkeglass heter «glas».', true, true, 1),
  ('norsk-9:nabosprak', 'q03', 'flervalg', 'Hva betyr dansk «frokost»?', array['Lunsj', 'Frokost', 'Middag', 'Kveldsmat']::text[], 0, 'På dansk er «frokost» lunsj. Morgenmåltidet heter «morgenmad».', true, true, 2),
  ('norsk-9:nabosprak', 'q04', 'flervalg', 'Hvilke svenske bokstaver tilsvarer norsk æ og ø?', array['å og ø', 'ü og ö', 'æ og ø', 'ä og ö']::text[], 3, 'Svensk bruker ä og ö der norsk har æ og ø.', true, true, 3),
  ('norsk-9:nabosprak', 'q05', 'flervalg', 'Hvorfor ligner dansk skrift på bokmål?', array['Fordi dansk har lånt fra bokmål', 'Fordi bokmål har utviklet seg fra dansk skriftspråk', 'Fordi det er tilfeldig', 'Fordi dansk og bokmål er samme språk']::text[], 1, 'Norge brukte dansk skriftspråk i flere hundre år, og bokmål er en videreutvikling av det.', true, true, 4),
  ('norsk-9:nabosprak', 'q06', 'flervalg', 'Hva betyr svensk «inte»?', array['inne', 'inntil', 'ikke', 'inni']::text[], 2, '«Inte» er svensk for «ikke».', true, true, 5),
  ('norsk-9:nabosprak', 'q07', 'flervalg', 'Hva betyr dansk «halvtreds»?', array['50', '30', '25', '53']::text[], 0, 'Det danske tallsystemet er annerledes. «Halvtreds» betyr 50.', true, true, 6),
  ('norsk-9:nabosprak', 'q08', 'flervalg', 'Hva er falske venner?', array['Ord som ser like ut i to språk, men betyr noe annet', 'Ord som er helt like i alle språk', 'Venner som lyver', 'Lånord fra engelsk']::text[], 0, 'Falske venner kan skape misforståelser fordi vi tror vi forstår dem.', true, true, 7),
  ('norsk-9:nabosprak', 'q09', 'flervalg', 'Hva kjennetegner dansk uttale for mange nordmenn?', array['Den er lett fordi den er lik skriften', 'Den har bløte konsonanter og stød som gjør den vanskeligere', 'Den har ingen vokaler', 'Den er lik islandsk']::text[], 1, 'Bløte konsonanter og stød gjør at dansk kan være vanskeligere å forstå muntlig enn skriftlig.', true, false, 8),
  ('norsk-9:nabosprak', 'q10', 'flervalg', 'Hva betyr svensk «semester»?', array['Et skolehalvår', 'En eksamen', 'Et kurs', 'Ferie']::text[], 3, 'Svensk «semester» betyr ferie. Et skolehalvår heter «termin».', true, false, 9),
  ('norsk-9:nabosprak', 'm01', 'sant-usant', 'Norsk, svensk og dansk har utviklet seg fra norrønt.', array['Sant', 'Usant']::text[], 0, 'Alle de skandinaviske språkene har røtter i det norrøne språket.', false, true, 10),
  ('norsk-9:nabosprak', 'm02', 'sant-usant', 'Dansk «grine» betyr å gråte.', array['Sant', 'Usant']::text[], 1, 'Dansk «grine» betyr å le.', false, true, 11),
  ('norsk-9:nabosprak', 'm03', 'sant-usant', 'Svensk «kjol» betyr skjørt.', array['Sant', 'Usant']::text[], 0, '«Kjol» er en falsk venn: det betyr skjørt, ikke kjole.', false, true, 12),
  ('norsk-9:nabosprak', 'm04', 'sant-usant', 'Islandsk er like lett for nordmenn å forstå som svensk.', array['Sant', 'Usant']::text[], 1, 'Islandsk har holdt på mer av det gamle språket og er mye vanskeligere å forstå for nordmenn.', false, true, 13),
  ('norsk-9:nabosprak', 'm05', 'flervalg', 'Hva betyr svensk «och»?', array['også', 'eller', 'og', 'ok']::text[], 2, '«Och» er svensk for «og».', false, true, 14),
  ('norsk-9:nabosprak', 'm06', 'flervalg', 'Hvilket svensk ord betyr «jente»?', array['flicka', 'jente', 'pige', 'kvinde']::text[], 0, '«Flicka» er svensk for jente. «Pige» og «kvinde» er dansk, og «jente» er norsk.', false, true, 15),
  ('norsk-9:nabosprak', 'm07', 'flervalg', 'Hva betyr dansk «morgenmad»?', array['Lunsj', 'Frokost', 'Kveldsmat', 'Middag']::text[], 1, '«Morgenmad» er frokost på dansk.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-9:nabosprak', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-9:nabosprak', 's01', 'Norsk, svensk og dansk ligner hverandre, og folk kan ofte forstå hverandre selv om de snakker hvert sitt språk. Forklar hva denne forståelsen kalles, og hva som gjør den mulig.', 'Dette kalles nabospråkforståelse. Språkene ligner fordi de har utviklet seg fra det samme norrøne språket.', array['Forklarer at forståelsen mellom språkene kalles nabospråkforståelse.', 'Knytter forståelsen til at språkene ligner eller har utviklet seg fra samme språk.']::text[], 0),
  ('norsk-9:nabosprak', 's02', 'Dansk skrift ligner ofte på bokmål, mens dansk uttale kan være vanskeligere for nordmenn. Forklar hvorfor det er slik, og nevn ett trekk ved dansk uttale.', 'Bokmål har utviklet seg fra dansk skriftspråk, derfor ligner skriften. I dansk uttales mange konsonanter bløtt, eller språket har stød.', array['Forklarer likheten mellom dansk skrift og bokmål med bokmåls utvikling fra dansk skriftspråk.', 'Nevner et relevant uttaletrekk, som bløte konsonanter eller stød.']::text[], 1),
  ('norsk-9:nabosprak', 's03', 'En svensk venn sier: «Filmen var rolig.» Hva mener vennen, og hvorfor kan en norsk lytter lett misforstå setningen?', 'Vennen mener at filmen var morsom. En norsk lytter kan misforstå fordi svensk «rolig» ser ut som det norske ordet «rolig», men betyr noe annet.', array['Forklarer at svensk «rolig» betyr morsom.', 'Forklarer at ordet kan misforstås fordi det ligner et norsk ord med en annen betydning.']::text[], 2),
  ('norsk-9:nabosprak', 's04', 'På svensk kan «flicka» bety «jente», og svenske flertallsord kan ende på «-ar», «-er» eller «-or». Forklar hva disse opplysningene viser om svenske ord sammenlignet med norske.', 'Svensk har ord som ser annerledes ut enn norske ord, for eksempel «flicka» for «jente». Svenske flertallsord kan også ha andre endelser, som «-or» i «flickor».', array['Bruker «flicka» som eksempel på at svenske ord kan være ulike norske ord.', 'Forklarer at svenske flertallsendelser kan skille seg fra norske, gjerne med et eksempel.']::text[], 3),
  ('norsk-9:nabosprak', 's05', 'En norsk elev hører en dansk setning, men forstår ikke alle ordene. Forklar hvordan det kan hjelpe å se etter ord som ligner norsk og bruke sammenhengen rundt ordene.', 'Ord som ligner norsk, kan gi eleven hint om hva setningen handler om. Sammenhengen rundt ordene kan hjelpe eleven med å forstå betydningen selv om noen ord er ukjente.', array['Forklarer at ord som ligner norsk, kan gi ledetråder til betydningen.', 'Forklarer hvordan sammenhengen kan hjelpe når enkelte ord er ukjente.']::text[], 4),
  ('norsk-9:nabosprak', 's06', 'Hva er stød i dansk uttale, og hvilken rolle kan det ha for ord?', 'Stød er et lite brudd i stemmen i dansk uttale. Det kan skille ord fra hverandre.', array['Beskriver stød som et lite brudd i stemmen.', 'Forklarer at stød kan skille ord fra hverandre.']::text[], 5),
  ('norsk-9:nabosprak', 's07', 'Ordet «rar» brukes både på dansk og svensk, men betydningen kan overraske en norsktalende. Hva betyr ordet på dansk og svensk, og hvilken forskjell gjelder bruken?', 'På både dansk og svensk betyr «rar» snill eller søt. På dansk brukes det særlig om personer, mens det på svensk også kan brukes om ting.', array['Forklarer at «rar» betyr snill eller søt på både dansk og svensk.', 'Får fram forskjellen i bruk: særlig om personer på dansk, også om ting på svensk.']::text[], 6),
  ('norsk-9:nabosprak', 's08', 'Norsk, svensk, dansk, islandsk og færøysk er nordgermanske språk som kommer fra norrønt. Hvorfor er islandsk og færøysk vanskeligere for nordmenn å forstå enn svensk og dansk?', 'Islandsk og færøysk har holdt på mer av det gamle språket. Derfor er de vanskeligere for nordmenn å forstå enn svensk og dansk.', array['Forklarer at islandsk og færøysk har bevart mer av det gamle språket.', 'Knytter dette til at språkene er vanskeligere for nordmenn å forstå.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-9:ungdom-i-litteraturen', 'norsk-9', 'ungdom-i-litteraturen', 'Ungdom i tekster', 'Hvordan romaner, noveller, film og serier framstiller unges liv – temaer, perspektiv og virkemidler – og hvordan du kan reflektere over framstillingen.', array[5, 1, 2]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-9:ungdom-i-litteraturen', '## Unge i litteratur og film
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-9:ungdom-i-litteraturen', 'Ungdomslitteratur', 'Litteratur skrevet med unge lesere som målgruppe.', 0),
  ('norsk-9:ungdom-i-litteraturen', 'SKAM', 'NRK-serie (2015–2017) om ungdom i Oslo, kjent for realistisk skildring og bruk av sosiale medier.', 1),
  ('norsk-9:ungdom-i-litteraturen', 'Identitet', 'Hvem man er og opplever seg som. Et sentralt tema i tekster om unge.', 2),
  ('norsk-9:ungdom-i-litteraturen', 'Utenforskap', 'Å stå utenfor fellesskapet, for eksempel på grunn av mobbing.', 3),
  ('norsk-9:ungdom-i-litteraturen', 'Løsrivelse', 'Å bli selvstendig og finne sin egen vei, ofte i konflikt med foreldre.', 4),
  ('norsk-9:ungdom-i-litteraturen', 'Utviklingsfortelling', 'En fortelling der hovedpersonen forandrer seg gjennom en utfordring.', 5),
  ('norsk-9:ungdom-i-litteraturen', 'Førstepersonsperspektiv', 'Fortellingen fortelles av hovedpersonen selv, med «jeg».', 6),
  ('norsk-9:ungdom-i-litteraturen', 'Autentisitet', 'Inntrykket av at en tekst er ekte og troverdig.', 7),
  ('norsk-9:ungdom-i-litteraturen', 'Slang', 'Uformelle ord og uttrykk, ofte brukt av en bestemt gruppe, som ungdom.', 8),
  ('norsk-9:ungdom-i-litteraturen', 'Stereotypi', 'En forenklet og fastlåst framstilling av en gruppe mennesker.', 9),
  ('norsk-9:ungdom-i-litteraturen', 'Sammensatt person', 'En person i en tekst med både gode og dårlige sider, som virker menneskelig.', 10),
  ('norsk-9:ungdom-i-litteraturen', 'Representasjon', 'Hvilke grupper og erfaringer som er med i tekster, og hvordan de framstilles.', 11),
  ('norsk-9:ungdom-i-litteraturen', 'Historisk kontekst', 'Tiden og samfunnet teksten ble skrevet i.', 12),
  ('norsk-9:ungdom-i-litteraturen', 'Samtid', 'Vår egen tid.', 13),
  ('norsk-9:ungdom-i-litteraturen', 'Målgruppe', 'De en tekst er laget for.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-9:ungdom-i-litteraturen', 'q01', 'flervalg', 'Hva er en utviklingsfortelling?', array['En fortelling om teknologi', 'En fortelling der hovedpersonen forandrer seg gjennom en utfordring', 'En fortelling uten handling', 'En fagtekst om ungdom']::text[], 1, 'I en utviklingsfortelling har hovedpersonen lært noe eller endret seg når historien er slutt.', true, true, 0),
  ('norsk-9:ungdom-i-litteraturen', 'q02', 'flervalg', 'Hvorfor er mange ungdomsromaner skrevet i førsteperson?', array['For å gjøre dem kortere', 'Fordi det er påbudt', 'For at leseren skal komme tett på hovedpersonens tanker og følelser', 'For å skjule hovedpersonen']::text[], 2, 'Førsteperson gir nærhet og gjør det lettere å identifisere seg med hovedpersonen.', true, true, 1),
  ('norsk-9:ungdom-i-litteraturen', 'q03', 'flervalg', 'Hva er en stereotypi?', array['En forenklet og fastlåst framstilling av en gruppe', 'En sammensatt person', 'En type rim', 'En sann historie']::text[], 0, 'Stereotypier som «nerden» eller «den populære» gir et forenklet bilde av mennesker.', true, true, 2),
  ('norsk-9:ungdom-i-litteraturen', 'q04', 'flervalg', 'Hva betyr autentisitet i en tekst?', array['At teksten er lang', 'At teksten har mange bilder', 'At teksten er skrevet av en kjent forfatter', 'At teksten virker ekte og troverdig']::text[], 3, 'Et autentisk språk og troverdige situasjoner gjør at leseren tror på fortellingen.', true, true, 3),
  ('norsk-9:ungdom-i-litteraturen', 'q05', 'flervalg', 'Hvilket tema er typisk i tekster om unge?', array['Pensjon', 'Identitet og vennskap', 'Skattereglene', 'Gamle krigsminner']::text[], 1, 'Spørsmål om hvem man er, og hvem man hører til, går igjen i mange tekster om unge.', true, true, 4),
  ('norsk-9:ungdom-i-litteraturen', 'q06', 'flervalg', 'Hvilket spørsmål hjelper deg å vurdere hvordan unge framstilles?', array['Hvor mange sider har boka?', 'Hvilken farge har omslaget?', 'Er personene sammensatte eller stereotype?', 'Hvor mye kostet boka?']::text[], 2, 'Om personene virker menneskelige og nyanserte, sier mye om hvor troverdig framstillingen er.', true, true, 5),
  ('norsk-9:ungdom-i-litteraturen', 'q07', 'flervalg', 'Hva var spesielt med serien SKAM?', array['Den var en tegnefilm', 'Den brukte sosiale medier som en del av fortellingen', 'Den handlet om voksne', 'Den var på svensk']::text[], 1, 'Klipp, meldinger og innlegg ble publisert på nett i sanntid, som om personene fantes.', true, false, 6),
  ('norsk-9:ungdom-i-litteraturen', 'q08', 'flervalg', 'Hva kan en eldre tekst om ungdom fortelle oss?', array['Ingenting, fordi den er gammel', 'Bare hvordan man snakket før', 'Hvordan ungdom levde i en annen tid, og hva som er likt og ulikt i dag', 'Hvordan ungdom lever i dag']::text[], 2, 'Sammenligning med eldre tekster viser både det tidløse og det som har endret seg.', true, true, 7),
  ('norsk-9:ungdom-i-litteraturen', 'q09', 'flervalg', 'Hva betyr representasjon i litteratur?', array['Hvem og hvilke erfaringer som er med i tekstene, og hvordan de framstilles', 'At boka har mange kapitler', 'At forfatteren representerer et forlag', 'At teksten er oversatt']::text[], 0, 'Representasjon handler om hvem som får plass i fortellingene, og om ulike lesere kjenner seg igjen.', true, true, 8),
  ('norsk-9:ungdom-i-litteraturen', 'q10', 'flervalg', 'Hva bør du ha med når du skriver om hvordan en tekst framstiller unge?', array['Bare din egen mening', 'Bare et sammendrag av handlingen', 'Beskrivelse, konkrete eksempler og en refleksjon over framstillingen', 'Bare sitater']::text[], 2, 'En god tekst beskriver, viser til eksempler og reflekterer over hvorfor framstillingen er som den er.', true, false, 9),
  ('norsk-9:ungdom-i-litteraturen', 'm01', 'sant-usant', 'Bare bøker kan skildre unges liv, ikke film og serier.', array['Sant', 'Usant']::text[], 1, 'Film, serier, sanger og sosiale medier skildrer også ungdomstiden.', false, true, 10),
  ('norsk-9:ungdom-i-litteraturen', 'm02', 'sant-usant', 'Slang kan gjøre dialogen i en ungdomsroman mer troverdig.', array['Sant', 'Usant']::text[], 0, 'Språk som ligner ungdoms eget, kan gi autentisitet.', false, true, 11),
  ('norsk-9:ungdom-i-litteraturen', 'm03', 'sant-usant', 'En sammensatt person har bare gode egenskaper.', array['Sant', 'Usant']::text[], 1, 'En sammensatt person har både gode og dårlige sider, slik ekte mennesker har.', false, true, 12),
  ('norsk-9:ungdom-i-litteraturen', 'm04', 'sant-usant', 'Noen temaer, som forelskelse, går igjen i tekster om unge fra ulike tider.', array['Sant', 'Usant']::text[], 0, 'Tidløse temaer finnes i både gamle og nye tekster, selv om rammene endrer seg.', false, true, 13),
  ('norsk-9:ungdom-i-litteraturen', 'm05', 'flervalg', 'Hvilket begrep beskriver å bli selvstendig og finne sin egen vei?', array['Løsrivelse', 'Stereotypi', 'Autentisitet', 'Målgruppe']::text[], 0, 'Løsrivelse fra foreldre og barndom er et klassisk tema i tekster om unge.', false, true, 14),
  ('norsk-9:ungdom-i-litteraturen', 'm06', 'flervalg', 'Hva kalles de en tekst er laget for?', array['Avsender', 'Forteller', 'Målgruppe', 'Kontekst']::text[], 2, 'Ungdomslitteratur har unge lesere som målgruppe.', false, true, 15),
  ('norsk-9:ungdom-i-litteraturen', 'm07', 'flervalg', 'Hvorfor kan det være viktig å spørre hvem som har laget en tekst om unge?', array['Fordi voksne og unge kan ha ulikt blikk på ungdomstiden', 'Fordi bare unge kan skrive', 'Fordi det avgjør hvor lang teksten er', 'Det har ingen betydning']::text[], 0, 'Avsenderens ståsted kan farge framstillingen av ungdom.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-9:ungdom-i-litteraturen', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-9:ungdom-i-litteraturen', 's01', 'En bok handler om tenåringer, men er laget for voksne lesere. En annen bok handler ikke nødvendigvis om tenåringer, men er skrevet spesielt for unge lesere. Hvilken bok er ungdomslitteratur, og hvorfor?', 'Den andre boka er ungdomslitteratur fordi den er skrevet med unge lesere som målgruppe. Det avgjørende er hvem boka er laget for, ikke bare hvem den handler om.', array['Slår fast at boka laget for unge lesere er ungdomslitteratur.', 'Forklarer at målgruppen, ikke bare temaet eller personene, avgjør.']::text[], 0),
  ('norsk-9:ungdom-i-litteraturen', 's02', 'Samir vurderer om han skal kle seg slik han selv liker, eller slik vennegjengen forventer. Forklar hvordan dilemmaet kan handle om identitet.', 'Dilemmaet handler om identitet fordi Samir prøver å finne ut hvem han er og hvem han vil være. Han må vurdere egne ønsker opp mot forventningene fra andre.', array['Knytter identitet til hvem Samir er eller ønsker å være.', 'Viser hvordan forventningene fra vennegjengen står mot Samirs egne ønsker.']::text[], 1),
  ('norsk-9:ungdom-i-litteraturen', 's03', 'I én fortelling blir Lea holdt utenfor av klassekamerater som mobber henne. I en annen blir Amir uenig med foreldrene fordi han vil ta egne valg. Forklar hvilket tilfelle som viser utenforskap, og hvilket som viser løsrivelse.', 'Leas situasjon viser utenforskap fordi hun blir holdt utenfor fellesskapet. Amirs situasjon viser løsrivelse fordi han prøver å bli mer selvstendig og finne sin egen vei.', array['Knytter Leas situasjon til å stå utenfor fellesskapet.', 'Knytter Amirs situasjon til selvstendighet eller egne valg, gjerne i konflikt med foreldrene.']::text[], 2),
  ('norsk-9:ungdom-i-litteraturen', 's04', 'Når vi sammenligner fortellinger fra ulike tider, kan noen temaer gå igjen mens andre sider ved ungdomslivet endrer seg. Nevn én ting som kan gå igjen, og én ramme som kan endre seg.', 'Forelskelse kan være et tema i fortellinger fra ulike tider. Rammene kan endre seg, for eksempel når det gjelder teknologi, skole eller samfunnets forventninger.', array['Nevner et tema som kan gå igjen, for eksempel forelskelse eller løsrivelse.', 'Nevner en ramme som kan endre seg, for eksempel teknologi, skole eller samfunnets forventninger.']::text[], 3),
  ('norsk-9:ungdom-i-litteraturen', 's05', 'En roman bruker uformelle ord som er typiske for en bestemt gruppe ungdommer. Forklar hva slike ord kalles, og hva som gjør dem til slang.', 'Slike ord kalles slang. Det er uformelle ord og uttrykk som ofte brukes av en bestemt gruppe, for eksempel ungdom.', array['Forklarer at slang er uformelle ord eller uttrykk.', 'Får fram at slang ofte brukes av en bestemt gruppe.']::text[], 4),
  ('norsk-9:ungdom-i-litteraturen', 's06', 'En person i en fortelling blir først kalt «den populære». Etter hvert viser det seg at personen både liker å få oppmerksomhet, hjelper andre og gjør feil. Forklar hvorfor dette kan gjøre personen mer sammensatt enn en fast type.', 'Personen virker sammensatt fordi hen har flere sider, både gode og mindre gode. Hen passer derfor ikke bare inn i den forenklede rollen «den populære».', array['Viser at personen har flere ulike sider eller egenskaper.', 'Forklarer at dette gjør personen mer menneskelig og mindre fastlåst i én rolle.']::text[], 5),
  ('norsk-9:ungdom-i-litteraturen', 's07', 'En fortelling begynner slik: «Jeg gruer meg til å møte de andre etter skolen.» Hvilket perspektiv er brukt, og hva i setningen viser det?', 'Det er førstepersonsperspektiv. Fortellingen bruker «jeg», og den fortelles av personen som opplever situasjonen.', array['Identifiserer førstepersonsperspektiv.', 'Begrunner svaret med at fortelleren bruker «jeg» og forteller innenfra.']::text[], 6),
  ('norsk-9:ungdom-i-litteraturen', 's08', 'En ungdom føler press fordi hen tror at alle på sosiale medier må framstå som perfekte. Forklar hvilke temaer i fortellinger om unge denne situasjonen kan vise.', 'Situasjonen viser sosiale medier og forventninger om å være perfekt. Presset kan også knyttes til psykisk helse, for eksempel stress eller angst.', array['Knytter situasjonen til sosiale medier eller forventninger om å være perfekt.', 'Knytter presset til psykisk helse, for eksempel stress eller angst.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-9:sammensatte-maleenheter', 'matematikk-9', 'sammensatte-maleenheter', 'Sammensatte måleenheter', 'Fart, tetthet, pris per enhet og befolkningstetthet – enheter som består av to andre, og hvordan du regner og gjør om mellom dem.', array[1]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-9:sammensatte-maleenheter', '## Hva er en sammensatt måleenhet?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-9:sammensatte-maleenheter', 'Sammensatt måleenhet', 'En enhet laget av to andre enheter med «per» imellom, for eksempel km/h eller kr/kg.', 0),
  ('matematikk-9:sammensatte-maleenheter', '«Per»', 'Betyr delt på. 18 km/h betyr 18 km på hver time.', 1),
  ('matematikk-9:sammensatte-maleenheter', 'Fart', 'Strekning delt på tid: v = s / t.', 2),
  ('matematikk-9:sammensatte-maleenheter', 'Strekning fra fart', 's = v · t. 60 km/h i 1,5 h gir 90 km.', 3),
  ('matematikk-9:sammensatte-maleenheter', 'Tid fra fart', 't = s / v. 6 km med 5 km/h tar 1,2 h.', 4),
  ('matematikk-9:sammensatte-maleenheter', '1 m/s', 'Er lik 3,6 km/h.', 5),
  ('matematikk-9:sammensatte-maleenheter', 'm/s til km/h', 'Gang med 3,6. 20 m/s = 72 km/h.', 6),
  ('matematikk-9:sammensatte-maleenheter', 'km/h til m/s', 'Del på 3,6. 90 km/h = 25 m/s.', 7),
  ('matematikk-9:sammensatte-maleenheter', 'Minutter til timer', 'Del på 60. 45 min = 0,75 h og 12 min = 0,2 h.', 8),
  ('matematikk-9:sammensatte-maleenheter', 'Tetthet', 'Masse delt på volum, ofte i g/cm³.', 9),
  ('matematikk-9:sammensatte-maleenheter', 'Tettheten til vann', 'Omtrent 1 g/cm³. Stoffer med lavere tetthet flyter i vann.', 10),
  ('matematikk-9:sammensatte-maleenheter', 'Enhetspris', 'Pris delt på mengde, for eksempel kr/kg eller kr/L. Brukes til å sammenligne tilbud.', 11),
  ('matematikk-9:sammensatte-maleenheter', 'Befolkningstetthet', 'Antall innbyggere per km².', 12),
  ('matematikk-9:sammensatte-maleenheter', 'Kilowattime (kWh)', 'Enhet for energi: effekt i kilowatt ganget med tid i timer.', 13),
  ('matematikk-9:sammensatte-maleenheter', 'Enheter i utregningen', 'Skriv enhetene med når du regner, så ser du om svaret får riktig enhet.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-9:sammensatte-maleenheter', 'q01', 'flervalg', 'En syklist sykler 36 km på 2 timer. Hva er farten?', array['72 km/h', '18 km/h', '34 km/h', '38 km/h']::text[], 1, 'Fart = strekning / tid = 36 km / 2 h = 18 km/h.', true, true, 0),
  ('matematikk-9:sammensatte-maleenheter', 'q02', 'flervalg', 'Hva er 20 m/s i km/h?', array['72 km/h', '5,6 km/h', '200 km/h', '20 km/h']::text[], 0, 'Fra m/s til km/h ganger vi med 3,6: 20 · 3,6 = 72 km/h.', true, true, 1),
  ('matematikk-9:sammensatte-maleenheter', 'q03', 'flervalg', 'Hvor langt kjører en bil på 1,5 timer med farten 80 km/h?', array['53 km', '81,5 km', '120 km', '160 km']::text[], 2, 'Strekning = fart · tid = 80 km/h · 1,5 h = 120 km.', true, true, 2),
  ('matematikk-9:sammensatte-maleenheter', 'q04', 'flervalg', 'Hva er 45 minutter i timer?', array['0,45 h', '4,5 h', '0,57 h', '0,75 h']::text[], 3, 'Del på 60: 45 / 60 = 0,75 h. Å skrive 0,45 h er en vanlig feil.', true, true, 3),
  ('matematikk-9:sammensatte-maleenheter', 'q05', 'flervalg', 'En stein har masse 270 g og volum 100 cm³. Hva er tettheten?', array['2,7 g/cm³', '27 000 g/cm³', '0,37 g/cm³', '170 g/cm³']::text[], 0, 'Tetthet = masse / volum = 270 g / 100 cm³ = 2,7 g/cm³.', true, true, 4),
  ('matematikk-9:sammensatte-maleenheter', 'q06', 'flervalg', 'Hvilket tilbud er billigst per kilo?', array['500 g for 45 kr', '250 g for 25 kr', '750 g for 60 kr', '1 kg for 95 kr']::text[], 2, 'Enhetsprisene er 90, 100, 80 og 95 kr/kg. 750 g for 60 kr gir 60 / 0,75 = 80 kr/kg.', true, true, 5),
  ('matematikk-9:sammensatte-maleenheter', 'q07', 'flervalg', 'Hvor lang tid tar det å gå 6 km med farten 5 km/h?', array['30 min', '1 time og 12 minutter', '1 time og 2 minutter', '1 time og 20 minutter']::text[], 1, 't = s / v = 6 / 5 = 1,2 h. 0,2 h = 0,2 · 60 min = 12 min.', true, true, 6),
  ('matematikk-9:sammensatte-maleenheter', 'q08', 'flervalg', 'Hva er 90 km/h i m/s?', array['324 m/s', '90 m/s', '15 m/s', '25 m/s']::text[], 3, 'Fra km/h til m/s deler vi på 3,6: 90 / 3,6 = 25 m/s.', true, true, 7),
  ('matematikk-9:sammensatte-maleenheter', 'q09', 'flervalg', 'Hvilken enhet passer for befolkningstetthet?', array['Innbyggere per km²', 'km² per innbygger', 'Innbyggere · km', 'km/h']::text[], 0, 'Befolkningstetthet sier hvor mange som bor på hver kvadratkilometer: innbyggere per km².', true, false, 8),
  ('matematikk-9:sammensatte-maleenheter', 'q10', 'flervalg', 'En kloss har tetthet 0,6 g/cm³. Hva skjer når den legges i vann?', array['Den synker', 'Den flyter', 'Den løses opp', 'Det kan ikke avgjøres']::text[], 1, 'Tettheten er lavere enn vannets, som er omtrent 1 g/cm³. Da flyter klossen.', true, false, 9),
  ('matematikk-9:sammensatte-maleenheter', 'm01', 'sant-usant', '«Per» i en enhet betyr at vi skal gange.', array['Sant', 'Usant']::text[], 1, '«Per» betyr delt på. km/h betyr kilometer delt på timer.', false, true, 10),
  ('matematikk-9:sammensatte-maleenheter', 'm02', 'sant-usant', '1 m/s er raskere enn 3 km/h.', array['Sant', 'Usant']::text[], 0, '1 m/s = 3,6 km/h, som er litt mer enn 3 km/h.', false, true, 11),
  ('matematikk-9:sammensatte-maleenheter', 'm03', 'sant-usant', 'Den største pakken er alltid billigst per kilo.', array['Sant', 'Usant']::text[], 1, 'Ofte er det slik, men ikke alltid. Du må regne ut enhetsprisen for å være sikker.', false, true, 12),
  ('matematikk-9:sammensatte-maleenheter', 'm04', 'sant-usant', '12 minutter er 0,2 timer.', array['Sant', 'Usant']::text[], 0, '12 / 60 = 0,2. Altså er 12 minutter en femtedel av en time.', false, true, 13),
  ('matematikk-9:sammensatte-maleenheter', 'm05', 'flervalg', 'Et tog kjører 240 km på 3 timer. Hva er gjennomsnittsfarten?', array['720 km/h', '80 km/h', '60 km/h', '243 km/h']::text[], 1, '240 km / 3 h = 80 km/h.', false, true, 14),
  ('matematikk-9:sammensatte-maleenheter', 'm06', 'flervalg', 'En flaske med 1,5 L brus koster 30 kr. Hva er literprisen?', array['45 kr/L', '20 kr/L', '15 kr/L', '31,5 kr/L']::text[], 1, 'Enhetspris = pris / mengde = 30 kr / 1,5 L = 20 kr/L.', false, true, 15),
  ('matematikk-9:sammensatte-maleenheter', 'm07', 'flervalg', 'Hva er massen av 200 cm³ av et stoff med tetthet 2,5 g/cm³?', array['80 g', '202,5 g', '500 g', '50 g']::text[], 2, 'Masse = tetthet · volum = 2,5 g/cm³ · 200 cm³ = 500 g.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-9:sammensatte-maleenheter', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-9:sammensatte-maleenheter', 's01', 'Hva forteller en fart på 18 km/h? Forklar også hva ordet «per» betyr i denne enheten.', 'Det betyr at noe beveger seg 18 kilometer på én time. «Per» betyr delt på, altså kilometer delt på timer.', array['Forklarer at 18 km/h betyr 18 kilometer på én time.', 'Forklarer at «per» betyr delt på.']::text[], 0),
  ('matematikk-9:sammensatte-maleenheter', 's02', 'Vann har tetthet omtrent 1 g/cm³, mens jern har tetthet omtrent 7,9 g/cm³. Sammenlign tettheten og forklar hva tallene forteller om like store volum av stoffene.', 'Jern har større tetthet enn vann. Like store volum av jern og vann har derfor ulik masse, og jern har størst masse.', array['Slår fast at jern har større tetthet enn vann.', 'Knytter tetthet til masse per volum, slik at like store volum av jern har større masse.']::text[], 1),
  ('matematikk-9:sammensatte-maleenheter', 's03', 'To pakker kan ha ulik vekt og ulik pris. Forklar hvordan enhetspris gjør det mulig å sammenligne dem.', 'Enhetspris viser prisen for en bestemt mengde, for eksempel én kilo. Da kan pakkene sammenlignes på samme mengde selv om de har ulik vekt.', array['Forklarer at enhetspris er pris delt på mengde, for eksempel pris per kilo.', 'Forklarer at prisen for samme mengde gjør tilbud med ulik pakkestørrelse sammenlignbare.']::text[], 2),
  ('matematikk-9:sammensatte-maleenheter', 's04', 'En bil kjører med farten 60 km/h i 1,5 timer. Hvor langt kjører den? Vis det viktigste regnestykket med enhet.', 'Strekningen er fart ganger tid: 60 km/h · 1,5 h = 90 km.', array['Bruker strekning = fart · tid, med regnestykket 60 · 1,5.', 'Oppgir svaret som 90 km.']::text[], 3),
  ('matematikk-9:sammensatte-maleenheter', 's05', 'Gjør om 12 minutter til timer. Vis det viktigste regnestykket.', '12 minutter delt på 60 er 0,2 timer: 12 min / 60 = 0,2 h.', array['Deler 12 på 60 for å gjøre minutter om til timer.', 'Oppgir svaret som 0,2 timer.']::text[], 4),
  ('matematikk-9:sammensatte-maleenheter', 's06', 'Hvorfor er det lurt å skrive enhetene med i utregningen når du løser et problem med fart?', 'Enhetene gjør det lettere å se om svaret får riktig måleenhet. De kan også hjelpe deg med å oppdage om du har glemt å gjøre om en enhet.', array['Forklarer at enhetene hjelper med å kontrollere at svaret får riktig enhet.', 'Nevner at enhetene kan avdekke en glemt omgjøring.']::text[], 5),
  ('matematikk-9:sammensatte-maleenheter', 's07', 'Hva måler kilowattimer (kWh), og hvordan henger det sammen med effekt og tid?', 'Kilowattimer er en enhet for energi. Energi i kWh finner du ved å gange effekt i kilowatt med tid i timer.', array['Oppgir at kWh er en enhet for energi.', 'Forklarer at kWh henger sammen med effekt i kilowatt ganget med tid i timer.']::text[], 6),
  ('matematikk-9:sammensatte-maleenheter', 's08', 'Gjør om 5 m/s til km/h. Bruk at 1 m/s = 3,6 km/h, og vis regnestykket.', 'Fra m/s til km/h ganger vi med 3,6: 5 · 3,6 = 18. Farten er 18 km/h.', array['Ganger 5 med 3,6 for å gjøre om fra m/s til km/h.', 'Oppgir svaret som 18 km/h.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-9:formlikhet-og-kongruens', 'matematikk-9', 'formlikhet-og-kongruens', 'Formlikhet og kongruens', 'Egenskaper ved trekanter og firkanter, når to figurer er kongruente eller formlike, og hvordan du bruker formlikhet og målestokk til å finne ukjente lengder.', array[2, 3, 5]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-9:formlikhet-og-kongruens', '## Todimensjonale figurer
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-9:formlikhet-og-kongruens', 'Vinkelsum i trekant', 'Summen av vinklene i en trekant er alltid 180°.', 0),
  ('matematikk-9:formlikhet-og-kongruens', 'Vinkelsum i firkant', 'Summen av vinklene i en firkant er alltid 360°.', 1),
  ('matematikk-9:formlikhet-og-kongruens', 'Likebeint trekant', 'En trekant med to like lange sider. Vinklene ved grunnlinjen er like store.', 2),
  ('matematikk-9:formlikhet-og-kongruens', 'Likesidet trekant', 'En trekant der alle sidene er like lange og alle vinklene er 60°.', 3),
  ('matematikk-9:formlikhet-og-kongruens', 'Parallellogram', 'En firkant der begge par av motstående sider er parallelle.', 4),
  ('matematikk-9:formlikhet-og-kongruens', 'Trapes', 'En firkant med minst ett par parallelle sider.', 5),
  ('matematikk-9:formlikhet-og-kongruens', 'Rombe', 'En firkant der alle fire sider er like lange.', 6),
  ('matematikk-9:formlikhet-og-kongruens', 'Kongruente figurer', 'Figurer med nøyaktig samme form og størrelse. De dekker hverandre helt.', 7),
  ('matematikk-9:formlikhet-og-kongruens', 'SSS, SVS, VSV', 'Krav som gjør to trekanter kongruente: tre sider, to sider og vinkelen mellom, eller to vinkler og siden mellom.', 8),
  ('matematikk-9:formlikhet-og-kongruens', 'Formlike figurer', 'Figurer med samme form, men ulik størrelse. Vinklene er like og sidene har samme forhold.', 9),
  ('matematikk-9:formlikhet-og-kongruens', 'Formlike trekanter', 'To trekanter er formlike hvis to vinkler er parvis like store.', 10),
  ('matematikk-9:formlikhet-og-kongruens', 'Samsvarende sider', 'Sidene som ligger på samme plass i to formlike figurer, for eksempel motsatt av like vinkler.', 11),
  ('matematikk-9:formlikhet-og-kongruens', 'Forstørrelsesfaktor', 'Forholdet mellom samsvarende sider i formlike figurer.', 12),
  ('matematikk-9:formlikhet-og-kongruens', 'Målestokk 1 : 50 000', '1 cm på kartet er 50 000 cm = 500 m i virkeligheten.', 13),
  ('matematikk-9:formlikhet-og-kongruens', 'Areal ved forstørrelse', 'Ganges alle lengder med k, blir arealet k² ganger så stort.', 14),
  ('matematikk-9:formlikhet-og-kongruens', 'Skyggemetoden', 'Sollys gir formlike trekanter. Høyden av et tre kan finnes fra skyggen til en kjent pinne.', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-9:formlikhet-og-kongruens', 'q01', 'flervalg', 'To vinkler i en trekant er 50° og 70°. Hvor stor er den tredje?', array['50°', '70°', '60°', '120°']::text[], 2, 'Vinkelsummen er 180°: 180° − 50° − 70° = 60°.', true, true, 0),
  ('matematikk-9:formlikhet-og-kongruens', 'q02', 'flervalg', 'Hva betyr det at to figurer er kongruente?', array['De har samme form og samme størrelse', 'De har samme form, men ulik størrelse', 'De har samme areal, men ulik form', 'De har like mange sider']::text[], 0, 'Kongruente figurer er helt like og kan legges oppå hverandre, eventuelt etter speiling.', true, true, 1),
  ('matematikk-9:formlikhet-og-kongruens', 'q03', 'flervalg', 'Hva er nok for å vite at to trekanter er formlike?', array['At én side er lik', 'At arealet er likt', 'At to vinkler er parvis like store', 'At de er rettvinklede']::text[], 2, 'Er to vinkler like, blir også den tredje lik fordi summen er 180°. Da har trekantene samme form.', true, true, 2),
  ('matematikk-9:formlikhet-og-kongruens', 'q04', 'flervalg', 'Trekant ABC er formlik med DEF. AB = 4 cm, DE = 10 cm og BC = 6 cm. Hvor lang er EF?', array['12 cm', '15 cm', '2,4 cm', '16 cm']::text[], 1, 'Forstørrelsesfaktoren er 10/4 = 2,5. EF = 6 · 2,5 = 15 cm.', true, true, 3),
  ('matematikk-9:formlikhet-og-kongruens', 'q05', 'flervalg', 'En pinne på 2 m kaster en skygge på 3 m. Et tre kaster samtidig en skygge på 18 m. Hvor høyt er treet?', array['27 m', '9 m', '12 m', '36 m']::text[], 2, 'Forholdet høyde/skygge er det samme: 2/3 = h/18. Da er h = 2 · 18/3 = 12 m.', true, true, 4),
  ('matematikk-9:formlikhet-og-kongruens', 'q06', 'flervalg', 'Et kart har målestokk 1 : 50 000. Hvor langt er 4 cm på kartet i virkeligheten?', array['2 km', '200 m', '20 km', '12,5 km']::text[], 0, '4 cm · 50 000 = 200 000 cm = 2000 m = 2 km.', true, true, 5),
  ('matematikk-9:formlikhet-og-kongruens', 'q07', 'flervalg', 'Sidene i et kvadrat dobles. Hva skjer med arealet?', array['Det dobles', 'Det blir tre ganger så stort', 'Det blir åtte ganger så stort', 'Det blir fire ganger så stort']::text[], 3, 'Arealet ganges med k² = 2² = 4. Et kvadrat med side 3 har areal 9, med side 6 har det areal 36.', true, true, 6),
  ('matematikk-9:formlikhet-og-kongruens', 'q08', 'flervalg', 'Hvilken firkant har alle sider like lange, men ikke nødvendigvis rette vinkler?', array['Rektangel', 'Trapes', 'Parallellogram', 'Rombe']::text[], 3, 'En rombe har fire like lange sider. Hvis vinklene i tillegg er rette, er den et kvadrat.', true, false, 7),
  ('matematikk-9:formlikhet-og-kongruens', 'q09', 'flervalg', 'Hvilket krav gir IKKE sikker kongruens mellom to trekanter?', array['SSS', 'SVS', 'Tre like vinkler', 'VSV']::text[], 2, 'Tre like vinkler gir bare formlikhet. Trekantene kan ha samme form, men være forskjellig store.', true, true, 8),
  ('matematikk-9:formlikhet-og-kongruens', 'q10', 'flervalg', 'En modell av et hus er i målestokk 1 : 100. Huset er 12 m høyt. Hvor høy er modellen?', array['1,2 cm', '12 cm', '120 cm', '0,12 cm']::text[], 1, '12 m = 1200 cm. Del på 100: 1200 cm / 100 = 12 cm.', true, false, 9),
  ('matematikk-9:formlikhet-og-kongruens', 'm01', 'sant-usant', 'Alle kongruente figurer er også formlike.', array['Sant', 'Usant']::text[], 0, 'Kongruente figurer har samme form, og forstørrelsesfaktoren er 1.', false, true, 10),
  ('matematikk-9:formlikhet-og-kongruens', 'm02', 'sant-usant', 'Alle rektangler er formlike med hverandre.', array['Sant', 'Usant']::text[], 1, 'Vinklene er like, men forholdet mellom sidene kan være ulikt. Et 2 × 4-rektangel og et 3 × 3-kvadrat er ikke formlike.', false, true, 11),
  ('matematikk-9:formlikhet-og-kongruens', 'm03', 'sant-usant', 'Alle vinklene i en likesidet trekant er 60°.', array['Sant', 'Usant']::text[], 0, 'Vinklene er like store og summen er 180°, så hver vinkel er 180° / 3 = 60°.', false, true, 12),
  ('matematikk-9:formlikhet-og-kongruens', 'm04', 'sant-usant', 'Målestokk 1 : 100 betyr at 1 cm på tegningen er 100 m i virkeligheten.', array['Sant', 'Usant']::text[], 1, '1 cm på tegningen er 100 cm = 1 m i virkeligheten.', false, true, 13),
  ('matematikk-9:formlikhet-og-kongruens', 'm05', 'flervalg', 'Tre vinkler i en firkant er 90°, 90° og 100°. Hvor stor er den fjerde?', array['80°', '90°', '100°', '180°']::text[], 0, 'Vinkelsummen er 360°: 360° − 90° − 90° − 100° = 80°.', false, true, 14),
  ('matematikk-9:formlikhet-og-kongruens', 'm06', 'flervalg', 'En trekant har sidene 3, 4 og 5 cm. En formlik trekant har korteste side 9 cm. Hvor lang er lengste side?', array['11 cm', '15 cm', '12 cm', '25 cm']::text[], 1, 'Forstørrelsesfaktoren er 9/3 = 3. Lengste side blir 5 · 3 = 15 cm.', false, true, 15),
  ('matematikk-9:formlikhet-og-kongruens', 'm07', 'flervalg', 'Alle lengder i en figur ganges med 3. Hvor mange ganger større blir arealet?', array['3', '6', '27', '9']::text[], 3, 'Arealet ganges med 3² = 9.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-9:formlikhet-og-kongruens', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-9:formlikhet-og-kongruens', 's01', 'Sammenlign kongruente og formlike figurer. Hva må være likt i hvert tilfelle, og hva kan være forskjellig?', 'Kongruente figurer har samme form og størrelse, mens formlike figurer kan ha ulik størrelse. I begge tilfeller er samsvarende vinkler like, men hos formlike figurer har samsvarende sider samme forhold i stedet for nødvendigvis samme lengde.', array['Skiller mellom samme størrelse for kongruente figurer og mulig ulik størrelse for formlike figurer.', 'Får fram at samsvarende sider og vinkler oppfører seg ulikt i de to tilfellene.']::text[], 0),
  ('matematikk-9:formlikhet-og-kongruens', 's02', 'En likebeint trekant har en toppvinkel på 40°. Hvor stor er hver av vinklene ved grunnlinjen? Vis det viktigste regnestykket.', 'Vinklene ved grunnlinjen er like store. De blir hver (180° − 40°) / 2 = 70°.', array['Bruker at vinkelsummen i en trekant er 180° og at grunnlinjevinklene er like.', 'Finner at hver grunnlinjevinkel er 70°.']::text[], 1),
  ('matematikk-9:formlikhet-og-kongruens', 's03', 'Firkant A har begge par motstående sider parallelle. Firkant B har nøyaktig ett par parallelle sider. Hva kalles hver firkant, og hva er forskjellen på dem?', 'Firkant A er et parallellogram, og firkant B er et trapes. Parallellogrammet har to par parallelle sider, mens trapeset har ett par.', array['Kaller firkant A et parallellogram og firkant B et trapes.', 'Beskriver riktig hvor mange par parallelle sider hver har.']::text[], 2),
  ('matematikk-9:formlikhet-og-kongruens', 's04', 'I trekant ABC er vinkel A lik vinkel D i trekant DEF, vinkel B er lik vinkel E, og vinkel C er lik vinkel F. Hvilken side i trekant ABC samsvarer med side EF? Forklar hvordan du finner det.', 'Side EF samsvarer med side BC. Endepunktene E og F samsvarer med henholdsvis B og C fordi vinklene ved disse hjørnene er like.', array['Oppgir at BC samsvarer med EF.', 'Knytter samsvaret til hvilke hjørner eller vinkler som er like.']::text[], 3),
  ('matematikk-9:formlikhet-og-kongruens', 's05', 'Alle lengdene i en formlik figur blir ganget med 3. Hvor mange ganger så stort blir arealet? Forklar sammenhengen.', 'Arealet blir 3² = 9 ganger så stort. Når lengdene ganges med en faktor k, ganges arealet med k².', array['Finner at arealet blir 9 ganger så stort.', 'Begrunner svaret med at arealfaktoren er kvadratet av lengdefaktoren.']::text[], 4),
  ('matematikk-9:formlikhet-og-kongruens', 's06', 'I to trekanter er to sider like lange parvis, og vinkelen mellom disse sidene er også lik. Hvilket kongruenskrav beskriver dette, og hva kan du konkludere om trekantene?', 'Dette er SVS-kravet: to sider og vinkelen mellom dem er like. Derfor er trekantene kongruente.', array['Identifiserer SVS og forklarer at vinkelen er mellom de to sidene.', 'Konkluderer med at trekantene er kongruente.']::text[], 5),
  ('matematikk-9:formlikhet-og-kongruens', 's07', 'Tre vinkler i en firkant er 80°, 95° og 105°. Hvor stor er den fjerde vinkelen? Vis det viktigste regnestykket.', 'Vinkelsummen i en firkant er 360°. Den fjerde vinkelen er 360° − (80° + 95° + 105°) = 80°.', array['Bruker at vinkelsummen i en firkant er 360°.', 'Finner at den fjerde vinkelen er 80°.']::text[], 6),
  ('matematikk-9:formlikhet-og-kongruens', 's08', 'En trekant har én vinkel som er større enn 90°, og den har to like lange sider. Klassifiser trekanten etter vinklene og etter sidene. Forklar kort.', 'Trekanten er stumpvinklet fordi den har en vinkel større enn 90°. Den er likebeint fordi den har to like lange sider.', array['Klassifiserer trekanten som stumpvinklet.', 'Klassifiserer trekanten som likebeint og knytter det til de to like lange sidene.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-9:pytagoras', 'matematikk-9', 'pytagoras', 'Pytagoras'' setning', 'Sammenhengen mellom sidene i en rettvinklet trekant, hvordan du finner en ukjent side, og hvordan setningen brukes i praktiske situasjoner.', array[3, 4, 5]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-9:pytagoras', '## Den rettvinklede trekanten
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-9:pytagoras', 'Rettvinklet trekant', 'En trekant der én vinkel er 90°.', 0),
  ('matematikk-9:pytagoras', 'Katet', 'En av de to sidene som danner den rette vinkelen i en rettvinklet trekant.', 1),
  ('matematikk-9:pytagoras', 'Hypotenus', 'Den lengste siden i en rettvinklet trekant, rett overfor den rette vinkelen.', 2),
  ('matematikk-9:pytagoras', 'Pytagoras'' setning', 'a² + b² = c², der a og b er katetene og c er hypotenusen.', 3),
  ('matematikk-9:pytagoras', 'Finne hypotenusen', 'c = √(a² + b²). Katetene 6 og 8 gir c = √100 = 10.', 4),
  ('matematikk-9:pytagoras', 'Finne en katet', 'a = √(c² − b²). Hypotenus 13 og katet 5 gir a = √144 = 12.', 5),
  ('matematikk-9:pytagoras', 'Kvadrater på sidene', 'Arealene av kvadratene på katetene er til sammen like store som kvadratet på hypotenusen.', 6),
  ('matematikk-9:pytagoras', 'Pytagoreisk trippel', 'Tre hele tall som passer i a² + b² = c², for eksempel 3, 4, 5 og 5, 12, 13.', 7),
  ('matematikk-9:pytagoras', '3-4-5-regelen', 'Måler du 3 og 4 langs to vegger og avstanden er 5, er hjørnet rett.', 8),
  ('matematikk-9:pytagoras', 'Omvendt Pytagoras', 'Hvis a² + b² = c² for sidene i en trekant, er trekanten rettvinklet.', 9),
  ('matematikk-9:pytagoras', 'Stump vinkel', 'Hvis c² > a² + b², er vinkelen overfor c stump (over 90°).', 10),
  ('matematikk-9:pytagoras', 'Diagonal i rektangel', 'Deler rektangelet i to rettvinklede trekanter. d = √(l² + b²).', 11),
  ('matematikk-9:pytagoras', 'Avstand i koordinatsystem', 'Avstanden mellom to punkter er hypotenusen i en trekant med sidene Δx og Δy.', 12),
  ('matematikk-9:pytagoras', 'Kontroll av svar', 'Hypotenusen skal alltid være lengst. En katet må derfor bli kortere enn hypotenusen.', 13),
  ('matematikk-9:pytagoras', 'Skisse', 'Tegn trekanten, marker den rette vinkelen og finn hypotenusen før du regner.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-9:pytagoras', 'q01', 'flervalg', 'Hva kalles den lengste siden i en rettvinklet trekant?', array['Katet', 'Diagonal', 'Hypotenus', 'Grunnlinje']::text[], 2, 'Hypotenusen ligger rett overfor den rette vinkelen og er alltid den lengste siden.', true, true, 0),
  ('matematikk-9:pytagoras', 'q02', 'flervalg', 'Katetene er 6 cm og 8 cm. Hvor lang er hypotenusen?', array['14 cm', '10 cm', '48 cm', '100 cm']::text[], 1, 'c² = 36 + 64 = 100, og c = √100 = 10 cm. 100 er c², ikke c.', true, true, 1),
  ('matematikk-9:pytagoras', 'q03', 'flervalg', 'Hypotenusen er 13 cm og den ene kateten 5 cm. Hvor lang er den andre kateten?', array['12 cm', '8 cm', '13,9 cm', '18 cm']::text[], 0, 'a² = 13² − 5² = 169 − 25 = 144, så a = 12 cm.', true, true, 2),
  ('matematikk-9:pytagoras', 'q04', 'flervalg', 'Hvilke tall er en pytagoreisk trippel?', array['2, 3, 4', '4, 5, 6', '5, 12, 13', '6, 7, 8']::text[], 2, '5² + 12² = 25 + 144 = 169 = 13². De andre settene passer ikke.', true, false, 3),
  ('matematikk-9:pytagoras', 'q05', 'flervalg', 'En trekant har sidene 7, 24 og 25. Er den rettvinklet?', array['Nei, 7 + 24 er ikke 25', 'Det kan ikke avgjøres uten vinkelmåler', 'Nei, sidene er for ulike', 'Ja, fordi 7² + 24² = 25²']::text[], 3, '49 + 576 = 625 = 25². Når setningen stemmer, er trekanten rettvinklet.', true, true, 4),
  ('matematikk-9:pytagoras', 'q06', 'flervalg', 'En stige på 5 m står 3 m fra en vegg. Hvor høyt opp på veggen når den?', array['2 m', '4 m', '8 m', '5,8 m']::text[], 1, 'Stigen er hypotenusen. h² = 5² − 3² = 25 − 9 = 16, så h = 4 m.', true, true, 5),
  ('matematikk-9:pytagoras', 'q07', 'flervalg', 'Et rektangel er 9 cm langt og 12 cm bredt. Hvor lang er diagonalen?', array['21 cm', '10,5 cm', '15 cm', '225 cm']::text[], 2, 'Diagonalen er hypotenusen: d² = 81 + 144 = 225, og d = 15 cm.', true, true, 6),
  ('matematikk-9:pytagoras', 'q08', 'flervalg', 'Du finner en katet og får 15 cm, men hypotenusen er 13 cm. Hva har skjedd?', array['Du har lagt sammen i stedet for å trekke fra', 'Svaret er riktig', 'Trekanten er stumpvinklet', 'Du har glemt å ta kvadratroten']::text[], 0, 'En katet må være kortere enn hypotenusen. Et for stort svar tyder på at du la sammen kvadratene i stedet for å trekke fra.', true, false, 7),
  ('matematikk-9:pytagoras', 'q09', 'flervalg', 'Hva er avstanden mellom punktene (1, 1) og (4, 5)?', array['7', '3', '4', '5']::text[], 3, 'Δx = 3 og Δy = 4. Avstanden er √(3² + 4²) = √25 = 5.', true, true, 8),
  ('matematikk-9:pytagoras', 'q10', 'flervalg', 'En snekker måler 3 m og 4 m langs to vegger. Avstanden mellom merkene er 5,2 m. Hva betyr det?', array['Hjørnet er nøyaktig rett', 'Vinkelen er litt større enn 90°', 'Vinkelen er litt mindre enn 90°', 'Veggene er parallelle']::text[], 1, '5,2² = 27,04 er større enn 3² + 4² = 25. Da er vinkelen stump, altså litt over 90°.', true, true, 9),
  ('matematikk-9:pytagoras', 'm01', 'sant-usant', 'Pytagoras'' setning gjelder for alle trekanter.', array['Sant', 'Usant']::text[], 1, 'Setningen gjelder bare for rettvinklede trekanter.', false, true, 10),
  ('matematikk-9:pytagoras', 'm02', 'sant-usant', 'Hypotenusen ligger rett overfor den rette vinkelen.', array['Sant', 'Usant']::text[], 0, 'Det er derfor hypotenusen alltid er den lengste siden.', false, true, 11),
  ('matematikk-9:pytagoras', 'm03', 'sant-usant', '6, 8 og 10 er en pytagoreisk trippel.', array['Sant', 'Usant']::text[], 0, '36 + 64 = 100 = 10². Settet er 3, 4, 5 ganget med 2.', false, true, 12),
  ('matematikk-9:pytagoras', 'm04', 'sant-usant', 'I en rettvinklet trekant med kateter 1 og 1 er hypotenusen 2.', array['Sant', 'Usant']::text[], 1, 'c² = 1 + 1 = 2, så c = √2 ≈ 1,41.', false, true, 13),
  ('matematikk-9:pytagoras', 'm05', 'flervalg', 'En TV har bredde 80 cm og høyde 60 cm. Hvor lang er diagonalen?', array['140 cm', '100 cm', '70 cm', '120 cm']::text[], 1, 'd² = 80² + 60² = 6400 + 3600 = 10 000, og d = 100 cm.', false, true, 14),
  ('matematikk-9:pytagoras', 'm06', 'flervalg', 'Hypotenusen er 10 og én katet er 6. Hva er arealet av trekanten?', array['30', '60', '24', '48']::text[], 2, 'Den andre kateten er √(100 − 36) = 8. Arealet er 6 · 8 / 2 = 24.', false, true, 15),
  ('matematikk-9:pytagoras', 'm07', 'flervalg', 'Hvilken trekant er stumpvinklet?', array['3, 4, 6', '3, 4, 5', '5, 12, 13', '4, 4, 5']::text[], 0, '6² = 36 er større enn 3² + 4² = 25. Da er vinkelen overfor den lengste siden stump.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-9:pytagoras', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-9:pytagoras', 's01', 'Forklar hva en katet er, og hvordan du kjenner den igjen i en rettvinklet trekant.', 'En katet er en av de to sidene som danner den rette vinkelen. De to katetene møtes altså i 90°-vinkelen.', array['Forklarer at katetene danner den rette vinkelen.', 'Viser at det er de to sidene som møtes i 90°-vinkelen.']::text[], 0),
  ('matematikk-9:pytagoras', 's02', 'Forklar hvorfor du legger sammen kvadratene av katetene når du skal finne hypotenusen, men trekker fra når du skal finne en katet.', 'Pytagoras'' setning sier at a² + b² = c², så du legger sammen kvadratene av katetene for å finne c². Når c² og ett katetkvadrat er kjent, trekker du det kjente katetkvadratet fra c² for å finne det andre.', array['Knytter addisjon av katetkvadratene til å finne hypotenusen.', 'Forklarer at det kjente katetkvadratet trekkes fra hypotenusens kvadrat for å finne en katet.']::text[], 1),
  ('matematikk-9:pytagoras', 's03', 'Beskriv hva Pytagoras'' setning betyr når vi tegner et kvadrat på hver av sidene i en rettvinklet trekant.', 'Arealene av kvadratene på de to katetene til sammen er like stort som arealet av kvadratet på hypotenusen. Dette er den geometriske betydningen av a² + b² = c².', array['Sier at arealene av de to små kvadratene til sammen er like stort som arealet av kvadratet på hypotenusen.', 'Knytter forklaringen til katetene og hypotenusen.']::text[], 2),
  ('matematikk-9:pytagoras', 's04', 'En rettvinklet trekant har kateter på 9 cm og 12 cm. Finn hypotenusen, og vis det viktigste regnestykket.', 'c² = 9² + 12² = 81 + 144 = 225, så c = 15 cm.', array['Legger sammen kvadratene av katetene: 9² + 12² = 225.', 'Oppgir hypotenusen som 15 cm.']::text[], 3),
  ('matematikk-9:pytagoras', 's05', 'En rettvinklet trekant har hypotenus på 17 cm og én katet på 8 cm. Finn den andre kateten, og vis det viktigste regnestykket.', 'Den andre katetens kvadrat er 17² − 8² = 289 − 64 = 225. Kateten er derfor 15 cm.', array['Trekker det kjente katetkvadratet fra hypotenusens kvadrat.', 'Oppgir den andre kateten som 15 cm.']::text[], 4),
  ('matematikk-9:pytagoras', 's06', 'Vis hvordan du kan lage en ny pytagoreisk trippel ved å gange tallene 3, 4 og 5 med 2. Begrunn at den nye trippelen passer i Pytagoras'' setning.', 'Når hvert tall ganges med 2, får vi 6, 8 og 10. De passer i setningen fordi 6² + 8² = 36 + 64 = 100 = 10².', array['Finner den nye trippelen 6, 8, 10 ved å gange alle tallene med 2.', 'Viser at 6² + 8² = 10².']::text[], 5),
  ('matematikk-9:pytagoras', 's07', 'Sammenlign en trekant der c² = a² + b² med en der c² > a² + b². Hva forteller hver sammenheng om vinkelen overfor siden c?', 'Når c² = a² + b², er trekanten rettvinklet. Når c² > a² + b², er vinkelen overfor c stump, altså større enn 90°.', array['Knytter likhet mellom c² og a² + b² til en rett vinkel.', 'Knytter c² > a² + b² til en stump vinkel overfor c.']::text[], 6),
  ('matematikk-9:pytagoras', 's08', 'Forklar hvordan Pytagoras'' setning kan brukes til å finne avstanden mellom to punkter i et koordinatsystem.', 'Forskjellene i koordinatene gir sidelengdene Δx og Δy i en rettvinklet trekant. Avstanden mellom punktene er hypotenusen, som kan finnes med Pytagoras'' setning: d = √(Δx² + Δy²).', array['Forklarer at Δx og Δy er katetene i en rettvinklet trekant.', 'Forklarer at avstanden mellom punktene er hypotenusen og kan finnes med Pytagoras'' setning.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-9:overflate-og-volum', 'matematikk-9', 'overflate-og-volum', 'Overflate og volum', 'Formlene for volum og overflateareal av prismer, sylindre, pyramider, kjegler og kuler, og hvordan du gjør om mellom volumenheter.', array[6]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-9:overflate-og-volum', '## Tredimensjonale figurer
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-9:overflate-og-volum', 'Volum', 'Hvor mye plass en romfigur tar. Måles i cm³, dm³ eller m³.', 0),
  ('matematikk-9:overflate-og-volum', 'Overflateareal', 'Summen av arealet av alle flatene på en romfigur. Måles i cm² eller m².', 1),
  ('matematikk-9:overflate-og-volum', 'Utbretting', 'En romfigur brettet ut til en flat figur. Nyttig for å finne overflatearealet.', 2),
  ('matematikk-9:overflate-og-volum', 'Prisme', 'Romfigur med to like, parallelle grunnflater og rette sideflater. V = G · h.', 3),
  ('matematikk-9:overflate-og-volum', 'Rett firkantet prisme', 'Et prisme der alle flatene er rektangler. V = l · b · h.', 4),
  ('matematikk-9:overflate-og-volum', 'Sylinder', 'Romfigur med to sirkler som grunnflater. V = πr² · h.', 5),
  ('matematikk-9:overflate-og-volum', 'Overflate av sylinder', 'O = 2πr² + 2πrh: to sirkler pluss en sideflate med lengde lik omkretsen.', 6),
  ('matematikk-9:overflate-og-volum', 'Pyramide', 'Mangekant som grunnflate og sideflater som møtes i en topp. V = G · h / 3.', 7),
  ('matematikk-9:overflate-og-volum', 'Kjegle', 'Sirkel som grunnflate og en spiss topp. V = πr² · h / 3.', 8),
  ('matematikk-9:overflate-og-volum', 'Kule', 'V = 4πr³/3 og O = 4πr².', 9),
  ('matematikk-9:overflate-og-volum', 'Grunnflate (G)', 'Flaten figuren står på, som brukes i volumformlene.', 10),
  ('matematikk-9:overflate-og-volum', '1 L', '1 liter = 1 dm³ = 1000 cm³.', 11),
  ('matematikk-9:overflate-og-volum', '1 m³', '1 kubikkmeter = 1000 liter.', 12),
  ('matematikk-9:overflate-og-volum', 'Faktor mellom volumenheter', '1000 per steg, fordi lengde, bredde og høyde alle ganges med 10.', 13),
  ('matematikk-9:overflate-og-volum', 'En tredjedel', 'En pyramide eller kjegle har en tredjedel av volumet til et prisme eller en sylinder med samme G og h.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-9:overflate-og-volum', 'q01', 'flervalg', 'Hva er volumet av en eske som er 5 cm lang, 4 cm bred og 3 cm høy?', array['12 cm³', '60 cm³', '47 cm³', '94 cm³']::text[], 1, 'V = l · b · h = 5 · 4 · 3 = 60 cm³.', true, true, 0),
  ('matematikk-9:overflate-og-volum', 'q02', 'flervalg', 'Hvilken formel gir volumet av en sylinder?', array['2πr · h', 'πr² · h / 3', '4πr³/3', 'πr² · h']::text[], 3, 'Grunnflaten er en sirkel med areal πr². Den ganges med høyden: V = πr² · h.', true, true, 1),
  ('matematikk-9:overflate-og-volum', 'q03', 'flervalg', 'Hvor mange liter er 1 m³?', array['10 L', '100 L', '1000 L', '10 000 L']::text[], 2, '1 m³ = 1000 dm³, og 1 dm³ = 1 L. Altså er 1 m³ = 1000 L.', true, true, 2),
  ('matematikk-9:overflate-og-volum', 'q04', 'flervalg', 'En pyramide har grunnflate 36 cm² og høyde 10 cm. Hva er volumet?', array['120 cm³', '360 cm³', '180 cm³', '46 cm³']::text[], 0, 'V = G · h / 3 = 36 · 10 / 3 = 120 cm³.', true, true, 3),
  ('matematikk-9:overflate-og-volum', 'q05', 'flervalg', 'Hvor stor del av en sylinders volum har en kjegle med samme grunnflate og høyde?', array['Halvparten', 'En tredjedel', 'To tredjedeler', 'Like mye']::text[], 1, 'Kjeglen har volum πr²h/3, som er en tredjedel av sylinderens πr²h.', true, false, 4),
  ('matematikk-9:overflate-og-volum', 'q06', 'flervalg', 'En sylinder har radius 2 cm og høyde 5 cm. Hva er volumet? (Bruk π ≈ 3,14.)', array['31,4 cm³', '20 cm³', '62,8 cm³', '125,6 cm³']::text[], 2, 'V = πr²h = 3,14 · 4 · 5 = 62,8 cm³.', true, true, 5),
  ('matematikk-9:overflate-og-volum', 'q07', 'flervalg', 'Hva er overflatearealet av en terning med side 3 cm?', array['27 cm²', '54 cm²', '18 cm²', '36 cm²']::text[], 1, 'En terning har 6 kvadratiske flater med areal 3 · 3 = 9 cm². 6 · 9 = 54 cm². 27 cm³ er volumet.', true, true, 6),
  ('matematikk-9:overflate-og-volum', 'q08', 'flervalg', 'Du skal male utsiden av en kasse. Hva må du regne ut?', array['Volumet', 'Omkretsen', 'Overflatearealet', 'Diagonalen']::text[], 2, 'Maling dekker flater, så det er overflatearealet som bestemmer hvor mye maling som trengs.', true, false, 7),
  ('matematikk-9:overflate-og-volum', 'q09', 'flervalg', 'Hvor mange cm³ er 2,5 L?', array['250 cm³', '25 cm³', '25 000 cm³', '2500 cm³']::text[], 3, '1 L = 1000 cm³, så 2,5 L = 2500 cm³.', true, true, 8),
  ('matematikk-9:overflate-og-volum', 'q10', 'flervalg', 'Hvilken formel gir overflatearealet av en kule?', array['4πr²', 'πr²', '4πr³/3', '2πr']::text[], 0, 'Overflaten av en kule er O = 4πr², altså like stor som fire sirkler med samme radius.', true, true, 9),
  ('matematikk-9:overflate-og-volum', 'm01', 'sant-usant', '1 dm³ er det samme som 1 liter.', array['Sant', 'Usant']::text[], 0, 'En kube med side 1 dm = 10 cm rommer 1000 cm³, som er 1 liter.', false, true, 10),
  ('matematikk-9:overflate-og-volum', 'm02', 'sant-usant', '1 m² = 100 cm².', array['Sant', 'Usant']::text[], 1, '1 m² = 100 cm · 100 cm = 10 000 cm².', false, true, 11),
  ('matematikk-9:overflate-og-volum', 'm03', 'sant-usant', 'Volumet av et prisme er grunnflate ganger høyde.', array['Sant', 'Usant']::text[], 0, 'V = G · h gjelder for alle prismer, også sylindre.', false, true, 12),
  ('matematikk-9:overflate-og-volum', 'm04', 'sant-usant', 'En kjegle har halvparten så stort volum som en sylinder med samme grunnflate og høyde.', array['Sant', 'Usant']::text[], 1, 'Kjeglen har en tredjedel av sylinderens volum.', false, true, 13),
  ('matematikk-9:overflate-og-volum', 'm05', 'flervalg', 'Et basseng er 10 m langt, 5 m bredt og 2 m dypt. Hvor mange liter rommer det?', array['100 L', '10 000 L', '1000 L', '100 000 L']::text[], 3, 'V = 10 · 5 · 2 = 100 m³, og 100 m³ = 100 · 1000 L = 100 000 L.', false, true, 14),
  ('matematikk-9:overflate-og-volum', 'm06', 'flervalg', 'En kjegle har radius 3 cm og høyde 4 cm. Hva er volumet? (π ≈ 3,14)', array['37,68 cm³', '113,04 cm³', '12,56 cm³', '28,26 cm³']::text[], 0, 'V = πr²h/3 = 3,14 · 9 · 4 / 3 = 37,68 cm³.', false, true, 15),
  ('matematikk-9:overflate-og-volum', 'm07', 'flervalg', 'Hvor mange ganger større blir volumet av en terning når siden dobles?', array['2', '4', '8', '6']::text[], 2, 'Alle tre dimensjonene dobles: 2 · 2 · 2 = 8.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-9:overflate-og-volum', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-9:overflate-og-volum', 's01', 'Forklar forskjellen på volum og overflateareal for en romfigur. Ta med hvilken type enhet hver størrelse måles i.', 'Volum forteller hvor mye plass romfiguren tar, og måles i kubikkenheter som cm³. Overflateareal er summen av arealet av alle flatene og måles i kvadratenheter som cm².', array['Forklarer at volum handler om plassen figuren tar, mens overflateareal er summen av flatene.', 'Skiller mellom kubikkenheter for volum og kvadratenheter for overflateareal.']::text[], 0),
  ('matematikk-9:overflate-og-volum', 's02', 'Forklar hvordan en utbretting kan hjelpe deg med å finne overflatearealet til en romfigur.', 'Når romfiguren brettes ut, blir flatene synlige som en flat figur. Da kan du finne arealet av hver flate og legge arealene sammen.', array['Forklarer at utbrettingen viser flatene i en flat figur.', 'Forklarer at arealene av flatene legges sammen for å finne overflatearealet.']::text[], 1),
  ('matematikk-9:overflate-og-volum', 's03', 'Sammenlign et prisme og en pyramide. Beskriv hvordan grunnflatene og sideflatene deres er forskjellige.', 'Et prisme har to like, parallelle grunnflater og rette sideflater. En pyramide har én mangekant som grunnflate, og sideflatene møtes i en topp.', array['Beskriver prismets to like, parallelle grunnflater og rette sideflater.', 'Beskriver pyramidens grunnflate og at sideflatene møtes i en topp.']::text[], 2),
  ('matematikk-9:overflate-og-volum', 's04', 'Et prisme har grunnflateareal G og høyde h. Forklar hvorfor volumet blir G · h ved å tenke på lag som stables oppå hverandre.', 'Hvert lag har areal G, og lagene stables oppå hverandre gjennom høyden h. Antall lag ganger arealet av hvert lag gir volumet G · h.', array['Forklarer at hvert lag har grunnflateareal G.', 'Knytter lagene og høyden sammen med volumformelen V = G · h.']::text[], 3),
  ('matematikk-9:overflate-og-volum', 's05', 'En vanntank skal fylles, og du vil finne hvor mye vann den rommer. Forklar hvilken størrelse du må finne, og hvorfor.', 'Jeg må finne volumet, fordi volum forteller hvor mye plass tanken rommer. Volum kan for eksempel oppgis i liter eller kubikkenheter.', array['Velger volum som størrelsen som trengs for å finne hvor mye tanken rommer.', 'Forklarer at volum måles i liter eller kubikkenheter.']::text[], 4),
  ('matematikk-9:overflate-og-volum', 's06', 'En kule har radius 2 cm. Bruk O = 4πr² og π ≈ 3,14 til å regne ut overflatearealet.', 'O = 4 · 3,14 · 2² = 4 · 3,14 · 4 = 50,24 cm².', array['Setter radiusen inn i formelen og bruker 2² = 4.', 'Finner overflatearealet 50,24 cm².']::text[], 5),
  ('matematikk-9:overflate-og-volum', 's07', 'Hvor mange cm³ er 1 m³? Bruk at 1 m³ = 1000 L og 1 L = 1000 cm³ til å vise regnestykket.', '1 m³ = 1000 L, og 1000 L = 1000 · 1000 cm³. Derfor er 1 m³ = 1 000 000 cm³.', array['Bruker sammenhengen 1 m³ = 1000 L og 1 L = 1000 cm³.', 'Viser at 1000 · 1000 = 1 000 000 cm³.']::text[], 6),
  ('matematikk-9:overflate-og-volum', 's08', 'Hva forteller formelen O = 4πr² om overflaten til en kule sammenlignet med sirkler med samme radius?', 'Formelen forteller at overflaten til en kule er like stor som arealet av fire sirkler med samme radius.', array['Sier at kuleoverflaten tilsvarer arealet av fire sirkler.', 'Presiserer at sirklene har samme radius som kula.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-9:sentralmal-og-spredning', 'matematikk-9', 'sentralmal-og-spredning', 'Sentralmål og spredningsmål', 'Gjennomsnitt, median og typetall, variasjonsbredde og kvartiler, og hvordan du bruker dem til å beskrive et datasett.', array[8]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-9:sentralmal-og-spredning', '## Datasett
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-9:sentralmal-og-spredning', 'Datasett', 'En samling observasjoner eller måledata, for eksempel høyden til elevene i en klasse.', 0),
  ('matematikk-9:sentralmal-og-spredning', 'Frekvens', 'Hvor mange ganger en verdi forekommer i et datasett.', 1),
  ('matematikk-9:sentralmal-og-spredning', 'Relativ frekvens', 'Frekvensen delt på antall observasjoner, ofte oppgitt i prosent.', 2),
  ('matematikk-9:sentralmal-og-spredning', 'Sentralmål', 'Mål som beskriver det typiske i et datasett: gjennomsnitt, median og typetall.', 3),
  ('matematikk-9:sentralmal-og-spredning', 'Gjennomsnitt', 'Summen av alle verdiene delt på antall verdier.', 4),
  ('matematikk-9:sentralmal-og-spredning', 'Median', 'Den midterste verdien når dataene er sortert. Ved partall antall: snittet av de to midterste.', 5),
  ('matematikk-9:sentralmal-og-spredning', 'Typetall', 'Verdien som forekommer oftest i datasettet.', 6),
  ('matematikk-9:sentralmal-og-spredning', 'Ekstremverdi', 'En verdi som skiller seg mye ut fra resten. Påvirker gjennomsnittet mer enn medianen.', 7),
  ('matematikk-9:sentralmal-og-spredning', 'Spredningsmål', 'Mål som viser hvor mye dataene varierer: variasjonsbredde og kvartilbredde.', 8),
  ('matematikk-9:sentralmal-og-spredning', 'Variasjonsbredde', 'Største verdi minus minste verdi.', 9),
  ('matematikk-9:sentralmal-og-spredning', 'Nedre kvartil', 'Medianen av den nedre halvdelen av det sorterte datasettet.', 10),
  ('matematikk-9:sentralmal-og-spredning', 'Øvre kvartil', 'Medianen av den øvre halvdelen av det sorterte datasettet.', 11),
  ('matematikk-9:sentralmal-og-spredning', 'Kvartilbredde', 'Øvre kvartil minus nedre kvartil. Viser spredningen til de midterste 50 %.', 12),
  ('matematikk-9:sentralmal-og-spredning', 'Frekvenstabell', 'En tabell som viser hver verdi og hvor mange ganger den forekommer.', 13),
  ('matematikk-9:sentralmal-og-spredning', 'Velge sentralmål', 'Median ved ekstremverdier, typetall for kategorier, gjennomsnitt når dataene er jevne.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-9:sentralmal-og-spredning', 'q01', 'flervalg', 'Hva er gjennomsnittet av 4, 6, 7, 7 og 11?', array['6', '7', '7,5', '35']::text[], 1, 'Summen er 4 + 6 + 7 + 7 + 11 = 35. Del på 5 verdier: 35 / 5 = 7.', true, true, 0),
  ('matematikk-9:sentralmal-og-spredning', 'q02', 'flervalg', 'Hva er medianen av 2, 5, 8 og 10?', array['5', '8', '6,25', '6,5']::text[], 3, 'Det er fire verdier, så medianen er snittet av de to midterste: (5 + 8) / 2 = 6,5.', true, true, 1),
  ('matematikk-9:sentralmal-og-spredning', 'q03', 'flervalg', 'Hva er typetallet i 3, 5, 5, 6, 8, 8, 8, 9?', array['8', '5', '6,5', '9']::text[], 0, '8 forekommer tre ganger, oftere enn noen annen verdi.', true, true, 2),
  ('matematikk-9:sentralmal-og-spredning', 'q04', 'flervalg', 'Hva er variasjonsbredden i 12, 7, 19, 3, 15?', array['12', '19', '16', '3']::text[], 2, 'Største verdi er 19 og minste er 3. 19 − 3 = 16.', true, true, 3),
  ('matematikk-9:sentralmal-og-spredning', 'q05', 'flervalg', 'Ni personer tjener 40 000 kr og én tjener 400 000 kr i måneden. Hvilket sentralmål beskriver det typiske best?', array['Gjennomsnittet', 'Medianen', 'Variasjonsbredden', 'Summen']::text[], 1, 'Gjennomsnittet (76 000 kr) trekkes opp av én ekstremverdi. Medianen (40 000 kr) viser hva de fleste tjener.', true, true, 4),
  ('matematikk-9:sentralmal-og-spredning', 'q06', 'flervalg', 'Hva måler kvartilbredden?', array['Spredningen til de midterste 50 % av dataene', 'Forskjellen mellom største og minste verdi', 'Den vanligste verdien', 'Gjennomsnittet av kvartilene']::text[], 0, 'Kvartilbredden er øvre minus nedre kvartil, og viser spredningen i den midterste halvdelen av dataene.', true, false, 5),
  ('matematikk-9:sentralmal-og-spredning', 'q07', 'flervalg', '3 elever har 2 søsken og 5 elever har 1 søsken. Hva er gjennomsnittlig antall søsken?', array['1,5', '1,6', '1,4', '1,3']::text[], 2, '(3 · 2 + 5 · 1) / 8 = 11 / 8 ≈ 1,4.', true, true, 6),
  ('matematikk-9:sentralmal-og-spredning', 'q08', 'flervalg', 'Hvilket sentralmål passer for favorittfarge?', array['Gjennomsnitt', 'Median', 'Kvartilbredde', 'Typetall']::text[], 3, 'Farger kan ikke legges sammen eller sorteres etter størrelse. Da er typetallet det eneste meningsfulle sentralmålet.', true, true, 7),
  ('matematikk-9:sentralmal-og-spredning', 'q09', 'flervalg', 'Hva er nedre kvartil i 1, 3, 4, 6, 8, 9, 10, 12?', array['3', '3,5', '4', '7']::text[], 1, 'Nedre halvdel er 1, 3, 4, 6. Medianen av den er (3 + 4) / 2 = 3,5.', true, true, 8),
  ('matematikk-9:sentralmal-og-spredning', 'q10', 'flervalg', 'To klasser har samme gjennomsnitt på en prøve. Hva kan likevel være forskjellig?', array['Spredningen i resultatene', 'Summen av poengene hvis klassene er like store', 'Gjennomsnittet', 'Ingenting']::text[], 0, 'Samme gjennomsnitt kan skjule stor forskjell i spredning, for eksempel jevne resultater i én klasse og store forskjeller i den andre.', true, false, 9),
  ('matematikk-9:sentralmal-og-spredning', 'm01', 'sant-usant', 'Medianen påvirkes mindre av ekstremverdier enn gjennomsnittet.', array['Sant', 'Usant']::text[], 0, 'Medianen avhenger bare av plasseringen i det sorterte datasettet, ikke av hvor ekstrem den største verdien er.', false, true, 10),
  ('matematikk-9:sentralmal-og-spredning', 'm02', 'sant-usant', 'Et datasett kan ha mer enn ett typetall.', array['Sant', 'Usant']::text[], 0, 'Forekommer to verdier like ofte og oftest, har datasettet to typetall.', false, true, 11),
  ('matematikk-9:sentralmal-og-spredning', 'm03', 'sant-usant', 'Variasjonsbredden er største verdi pluss minste verdi.', array['Sant', 'Usant']::text[], 1, 'Variasjonsbredden er største verdi minus minste verdi.', false, true, 12),
  ('matematikk-9:sentralmal-og-spredning', 'm04', 'sant-usant', 'Gjennomsnittet må alltid være en av verdiene i datasettet.', array['Sant', 'Usant']::text[], 1, 'Gjennomsnittet av 1 og 2 er 1,5, som ikke er med i datasettet.', false, true, 13),
  ('matematikk-9:sentralmal-og-spredning', 'm05', 'flervalg', 'Hva er medianen av 9, 2, 7, 4, 5?', array['7', '4', '5', '5,4']::text[], 2, 'Sortert: 2, 4, 5, 7, 9. Den midterste verdien er 5.', false, true, 14),
  ('matematikk-9:sentralmal-og-spredning', 'm06', 'flervalg', 'Fem tall har gjennomsnitt 8. Hva er summen av tallene?', array['13', '40', '8', '1,6']::text[], 1, 'Gjennomsnitt = sum / antall, så sum = 8 · 5 = 40.', false, true, 15),
  ('matematikk-9:sentralmal-og-spredning', 'm07', 'flervalg', 'Hvilket mål forteller om dataene er samlet eller spredt?', array['Typetall', 'Median', 'Gjennomsnitt', 'Kvartilbredde']::text[], 3, 'Kvartilbredde er et spredningsmål. De tre andre er sentralmål.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-9:sentralmal-og-spredning', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-9:sentralmal-og-spredning', 's01', 'En elev registrerer antall minutter fire elever bruker på lekser: 10, 20, 20 og 30. Hva er datasettet, og hva er frekvensen til verdien 20?', 'Datasettet er 10, 20, 20 og 30 minutter. Frekvensen til 20 er 2, fordi verdien forekommer to ganger.', array['Beskriver datasettet som samlingen av de registrerte verdiene.', 'Oppgir at frekvensen til 20 er 2 fordi 20 forekommer to ganger.']::text[], 0),
  ('matematikk-9:sentralmal-og-spredning', 's02', 'I et datasett med 24 observasjoner har verdien 5 frekvens 6. Hva er den relative frekvensen til 5 i prosent, og hvordan finner du den?', 'Den relative frekvensen er 25 %. Jeg deler frekvensen 6 på antall observasjoner 24 og gjør svaret om til prosent.', array['Finner 25 %.', 'Viser at frekvensen deles på det totale antallet observasjoner.']::text[], 1),
  ('matematikk-9:sentralmal-og-spredning', 's03', 'I en gruppe har 4 elever 1 søsken, 2 elever har 3 søsken, og 2 elever har 5 søsken. Finn gjennomsnittlig antall søsken. Vis det viktigste regnetrinnet.', 'Gjennomsnittet er 2,5 søsken. Jeg regner (4 · 1 + 2 · 3 + 2 · 5) / 8 = 20 / 8 = 2,5.', array['Ganger hver verdi med frekvensen og summerer produktene.', 'Deler summen på 8 elever og får 2,5.']::text[], 2),
  ('matematikk-9:sentralmal-og-spredning', 's04', 'Finn kvartilbredden i datasettet 2, 4, 5, 7, 8, 10, 11, 13. Vis hvordan du finner nedre og øvre kvartil.', 'Nedre kvartil er medianen av 2, 4, 5, 7, altså 4,5. Øvre kvartil er medianen av 8, 10, 11, 13, altså 10,5, så kvartilbredden er 10,5 − 4,5 = 6.', array['Finner nedre kvartil 4,5 og øvre kvartil 10,5 ved å bruke medianene i hver halvdel.', 'Regner kvartilbredden som øvre kvartil minus nedre kvartil og får 6.']::text[], 3),
  ('matematikk-9:sentralmal-og-spredning', 's05', 'Et datasett har verdiene 3, 4, 4, 5 og 30. Forklar hvorfor medianen kan beskrive det typiske bedre enn gjennomsnittet i dette datasettet.', 'Verdien 30 er en ekstremverdi som trekker gjennomsnittet opp. Medianen er 4 og påvirkes mindre av denne verdien, så den viser bedre hva som er typisk her.', array['Forklarer at ekstremverdien 30 trekker gjennomsnittet opp.', 'Forklarer at medianen påvirkes mindre av ekstremverdien og derfor kan gi et bedre bilde av det typiske.']::text[], 4),
  ('matematikk-9:sentralmal-og-spredning', 's06', 'Hva er forskjellen på variasjonsbredde og kvartilbredde når de beskriver spredning i et datasett?', 'Variasjonsbredden er største verdi minus minste verdi. Kvartilbredden er øvre kvartil minus nedre kvartil og viser spredningen til de midterste 50 prosentene.', array['Forklarer at variasjonsbredden bygger på største og minste verdi.', 'Forklarer at kvartilbredden bygger på kvartilene og beskriver de midterste 50 prosentene.']::text[], 5),
  ('matematikk-9:sentralmal-og-spredning', 's07', 'I datasettet 2, 2, 4, 4, 7 forekommer to verdier like ofte. Hvilke verdier er typetall, og hvorfor kan et datasett ha mer enn ett typetall?', 'Typetallene er 2 og 4, fordi begge forekommer to ganger og oftere enn 7. Et datasett kan ha flere typetall når flere verdier forekommer like ofte og oftest.', array['Oppgir både 2 og 4 som typetall.', 'Forklarer at flere verdier kan være typetall når de deler høyeste frekvens.']::text[], 6),
  ('matematikk-9:sentralmal-og-spredning', 's08', 'Målingene i et datasett er 4, 5, 5, 6 og 7, og det er ingen ekstremverdier. Finn gjennomsnittet og variasjonsbredden, og forklar kort hva hvert mål forteller.', 'Gjennomsnittet er (4 + 5 + 5 + 6 + 7) / 5 = 5,4, og variasjonsbredden er 7 − 4 = 3. Gjennomsnittet beskriver et typisk nivå, mens variasjonsbredden viser avstanden mellom den største og minste målingen.', array['Finner gjennomsnittet 5,4 og variasjonsbredden 3.', 'Forklarer hva hvert mål sier om datasettet: typisk nivå og spredning fra minste til største verdi.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-9:statistikk-i-media', 'matematikk-9', 'statistikk-i-media', 'Statistikk i media', 'Diagramtyper, hvordan statistikk kan presenteres for å fremme et synspunkt, og hvordan du vurderer tall og grafer kritisk.', array[7, 9]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-9:statistikk-i-media', '## Diagrammer
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-9:statistikk-i-media', 'Stolpediagram', 'Sammenligner antall eller mengder i ulike kategorier med stolper.', 0),
  ('matematikk-9:statistikk-i-media', 'Linjediagram', 'Viser utvikling over tid med punkter som bindes sammen.', 1),
  ('matematikk-9:statistikk-i-media', 'Sektordiagram', 'Viser fordelingen av en helhet i prosent. Sektorene utgjør til sammen 360°.', 2),
  ('matematikk-9:statistikk-i-media', 'Histogram', 'Viser hvordan tallverdier fordeler seg i intervaller, uten mellomrom mellom søylene.', 3),
  ('matematikk-9:statistikk-i-media', 'Avkuttet akse', 'En y-akse som ikke starter på 0. Kan få små forskjeller til å se store ut.', 4),
  ('matematikk-9:statistikk-i-media', 'Absolutt endring', 'Endringen målt i antall, for eksempel en økning på 5 personer.', 5),
  ('matematikk-9:statistikk-i-media', 'Relativ endring', 'Endringen målt i prosent av startverdien. Fra 2 til 3 er en økning på 50 %.', 6),
  ('matematikk-9:statistikk-i-media', 'Populasjon', 'Hele gruppen en undersøkelse vil si noe om, for eksempel alle ungdommer i Norge.', 7),
  ('matematikk-9:statistikk-i-media', 'Utvalg', 'Den delen av populasjonen som faktisk blir spurt eller målt.', 8),
  ('matematikk-9:statistikk-i-media', 'Representativt utvalg', 'Et utvalg som ligner populasjonen, slik at resultatet kan overføres.', 9),
  ('matematikk-9:statistikk-i-media', 'Selvselektert utvalg', 'Når deltakerne selv velger å svare, som i nettavstemninger. Gir ofte skjeve resultater.', 10),
  ('matematikk-9:statistikk-i-media', 'Kildekritikk', 'Å vurdere hvem som står bak statistikken, og om de har interesse av et bestemt resultat.', 11),
  ('matematikk-9:statistikk-i-media', 'Utvalgte perioder', 'Å bare vise de årene som passer argumentet. Kan gi et skjevt bilde av utviklingen.', 12),
  ('matematikk-9:statistikk-i-media', 'Per innbygger', 'Å dele et tall på antall innbyggere gjør det mulig å sammenligne steder av ulik størrelse.', 13),
  ('matematikk-9:statistikk-i-media', '3D-diagram', 'Tredimensjonale effekter kan få deler av diagrammet til å se større ut enn de er.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-9:statistikk-i-media', 'q01', 'flervalg', 'Hvilket diagram passer best til å vise temperaturen hver måned gjennom et år?', array['Sektordiagram', 'Linjediagram', 'Histogram', 'Stolpediagram med kategorier']::text[], 1, 'Et linjediagram viser utvikling over tid og gjør det lett å se hvordan temperaturen stiger og synker.', true, true, 0),
  ('matematikk-9:statistikk-i-media', 'q02', 'flervalg', 'Hva må sektorene i et sektordiagram til sammen utgjøre?', array['180°', '100°', 'Antallet svar', '100 %, altså 360°']::text[], 3, 'Et sektordiagram viser en helhet. Alle sektorene til sammen blir 100 % av sirkelen, som er 360°.', true, true, 1),
  ('matematikk-9:statistikk-i-media', 'q03', 'flervalg', 'Y-aksen i et diagram starter på 95. Hva kan det føre til?', array['At små forskjeller ser store ut', 'At diagrammet blir mer nøyaktig', 'At dataene endres', 'At gjennomsnittet blir feil']::text[], 0, 'Når aksen er kuttet, blir forskjellene mellom stolpene overdrevet visuelt, selv om tallene er riktige.', true, true, 2),
  ('matematikk-9:statistikk-i-media', 'q04', 'flervalg', 'Antall ulykker økte fra 2 til 3. Hvor stor er den relative økningen?', array['1 %', '33 %', '50 %', '150 %']::text[], 2, 'Økningen er 1. Relativ økning = 1 / 2 = 0,5 = 50 %. Det høres mye ut, selv om det bare gjelder én ulykke.', true, true, 3),
  ('matematikk-9:statistikk-i-media', 'q05', 'flervalg', 'Hvorfor er en nettavstemning der alle kan stemme, lite pålitelig?', array['Fordi den har for mange svar', 'Fordi utvalget ikke er representativt', 'Fordi nettet regner feil', 'Fordi den bare gir prosent']::text[], 1, 'De som velger å svare, er ofte de som er mest engasjert i saken. Da ligner ikke utvalget befolkningen.', true, true, 4),
  ('matematikk-9:statistikk-i-media', 'q06', 'flervalg', 'Hva kalles hele gruppen en undersøkelse vil si noe om?', array['Utvalget', 'Frekvensen', 'Populasjonen', 'Medianen']::text[], 2, 'Populasjonen er hele gruppen, mens utvalget er de som faktisk blir spurt.', true, false, 5),
  ('matematikk-9:statistikk-i-media', 'q07', 'flervalg', 'En kommunes inntekter økte, men befolkningen økte mer. Hva kan da ha skjedd med inntektene per innbygger?', array['De må ha økt', 'De er uendret', 'Det kan ikke regnes ut', 'De kan ha gått ned']::text[], 3, 'Når befolkningen vokser raskere enn inntektene, blir det mindre per person. Begge påstandene kan være sanne samtidig.', true, true, 6),
  ('matematikk-9:statistikk-i-media', 'q08', 'flervalg', 'Hvilket diagram viser fordelingen av høyder i intervaller som 150–155 cm og 155–160 cm?', array['Histogram', 'Sektordiagram', 'Linjediagram', 'Punktdiagram over tid']::text[], 0, 'Et histogram viser hvor mange verdier som havner i hvert intervall av en tallskala.', true, false, 7),
  ('matematikk-9:statistikk-i-media', 'q09', 'flervalg', 'En undersøkelse om en brusmerkes smak er betalt av produsenten. Hva bør du tenke?', array['At den er ekstra pålitelig', 'At avsenderen kan ha interesse av et bestemt resultat', 'At den må være feil', 'At utvalget er stort']::text[], 1, 'Avsenderens interesser betyr ikke at tallene er feil, men du bør være ekstra kritisk til utvalg, spørsmål og presentasjon.', true, true, 8),
  ('matematikk-9:statistikk-i-media', 'q10', 'flervalg', 'Hvilket av disse er et eksempel på å bruke utvalgte perioder?', array['Å vise alle år fra 2000 til i dag', 'Å bruke et histogram', 'Å bare vise de tre årene der salget økte', 'Å oppgi både antall og prosent']::text[], 2, 'Å plukke ut bare de årene som passer argumentet, kan gi et helt annet inntrykk enn hele tidsserien.', true, true, 9),
  ('matematikk-9:statistikk-i-media', 'm01', 'sant-usant', 'Et diagram kan gi et skjevt inntrykk selv om alle tallene er riktige.', array['Sant', 'Usant']::text[], 0, 'Valg av skala, utsnitt og diagramtype påvirker hvordan tallene oppfattes.', false, true, 10),
  ('matematikk-9:statistikk-i-media', 'm02', 'sant-usant', 'Et stort utvalg er alltid representativt.', array['Sant', 'Usant']::text[], 1, 'Et stort utvalg kan fortsatt være skjevt, for eksempel hvis bare én gruppe har svart.', false, true, 11),
  ('matematikk-9:statistikk-i-media', 'm03', 'sant-usant', 'Et sektordiagram passer godt til å vise utvikling over mange år.', array['Sant', 'Usant']::text[], 1, 'Sektordiagram viser fordelingen av en helhet på ett tidspunkt. Utvikling over tid vises best med linjediagram.', false, true, 12),
  ('matematikk-9:statistikk-i-media', 'm04', 'sant-usant', 'En økning fra 10 til 15 er en relativ økning på 50 %.', array['Sant', 'Usant']::text[], 0, 'Økningen er 5, og 5 / 10 = 0,5 = 50 %.', false, true, 13),
  ('matematikk-9:statistikk-i-media', 'm05', 'flervalg', '30 % av 200 elever sykler til skolen. Hvor mange grader utgjør syklistene i et sektordiagram?', array['30°', '60°', '108°', '90°']::text[], 2, '30 % av 360° = 0,3 · 360° = 108°.', false, true, 14),
  ('matematikk-9:statistikk-i-media', 'm06', 'flervalg', 'Hvilket tall er best for å sammenligne kriminalitet i en storby og en liten kommune?', array['Antall lovbrudd per 1000 innbyggere', 'Totalt antall lovbrudd', 'Antall politifolk', 'Kommunens areal']::text[], 0, 'Et tall per innbygger tar hensyn til at storbyen har langt flere innbyggere.', false, true, 15),
  ('matematikk-9:statistikk-i-media', 'm07', 'flervalg', 'Hva er et representativt utvalg?', array['Et utvalg der alle har samme mening', 'Et utvalg som ligner populasjonen', 'Et utvalg med bare eksperter', 'Et utvalg som velger seg selv']::text[], 1, 'Et representativt utvalg har omtrent samme sammensetning som populasjonen, for eksempel når det gjelder alder og bosted.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-9:statistikk-i-media', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-9:statistikk-i-media', 's01', 'Forklar forskjellen på et stolpediagram og et histogram. Hvilken type data passer hvert diagram til?', 'Et stolpediagram sammenligner antall eller mengder i ulike kategorier. Et histogram viser hvordan tallverdier fordeler seg i intervaller, med søyler uten mellomrom.', array['Skiller mellom kategorier og tallverdier i intervaller.', 'Får fram at histogrammets søyler ikke har mellomrom.']::text[], 0),
  ('matematikk-9:statistikk-i-media', 's02', 'Et sektordiagram er laget i 3D. Forklar hvordan 3D-effekten kan påvirke inntrykket av diagrammet.', 'Perspektivet kan få noen sektorer til å se større ut enn de egentlig er. Derfor kan diagrammet gi et skjevt inntrykk av hvordan helheten er fordelt.', array['Nevner at perspektivet kan få deler til å se større ut enn de er.', 'Knytter dette til at diagrammet kan gi et skjevt inntrykk.']::text[], 1),
  ('matematikk-9:statistikk-i-media', 's03', 'En sektor i et sektordiagram viser 50 % av helheten. Hvor mange grader er sektoren? Vis det viktigste regnestykket.', '50 % av 360° er 180°. Sektoren er altså 180°.', array['Bruker at hele sektordiagrammet er 360°.', 'Viser eller beskriver regnestykket 0,5 · 360° = 180°.']::text[], 2),
  ('matematikk-9:statistikk-i-media', 's04', 'En verdi øker fra 96 til 98. Hva er den absolutte endringen? Vis det viktigste regnestykket.', 'Den absolutte endringen er 98 − 96 = 2. Verdien økte altså med 2.', array['Finner differansen mellom sluttverdien og startverdien.', 'Oppgir økningen som 2.']::text[], 3),
  ('matematikk-9:statistikk-i-media', 's05', 'En undersøkelse skal si noe om en stor populasjon. Forklar hva som kjennetegner et representativt utvalg, og hvorfor det er nyttig.', 'Et representativt utvalg ligner populasjonen det er hentet fra. Da er det lettere å overføre resultatet fra utvalget til hele populasjonen.', array['Forklarer at utvalget bør ligne populasjonen.', 'Knytter dette til at resultatene kan overføres til populasjonen.']::text[], 4),
  ('matematikk-9:statistikk-i-media', 's06', 'En undersøkelse med 20 svar brukes til å si noe om en hel befolkning. Forklar hvorfor resultatet kan være usikkert.', 'Et utvalg på 20 svar er lite og sier derfor lite om hele befolkningen. Resultatet trenger ikke å gjenspeile hva hele befolkningen mener eller gjør.', array['Får fram at 20 svar er et lite utvalg.', 'Forklarer at et lite utvalg kan gi et usikkert bilde av hele populasjonen.']::text[], 5),
  ('matematikk-9:statistikk-i-media', 's07', 'På en diagramakse står det tall med like store mellomrom, men tallforskjellene mellom merkene er ikke like store. Hva kalles dette, og hvordan kan det villede?', 'Dette er en ujevn skala. Den kan få forskjeller i dataene til å se større eller mindre ut enn de egentlig er.', array['Identifiserer at skalaen er ujevn.', 'Forklarer at dette kan gi et feilaktig inntrykk av størrelsen på forskjellene.']::text[], 6),
  ('matematikk-9:statistikk-i-media', 's08', 'En statistisk påstand brukes i en reklame, men det står ikke hvem som har laget statistikken. Nevn hva du bør undersøke ved kilden, og forklar hvorfor.', 'Jeg bør undersøke hvem som står bak statistikken, og hvorfor de har laget den. De kan ha interesse av at resultatet støtter et bestemt syn eller produkt.', array['Får fram at man bør undersøke hvem som står bak og hvorfor statistikken er laget.', 'Forklarer at kilden kan ha interesse av et bestemt resultat.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-9:sannsynlighet', 'matematikk-9', 'sannsynlighet', 'Sannsynlighet', 'Hva sannsynlighet er, gunstige og mulige utfall, relativ frekvens, og hvordan du regner på sannsynlighet i spill og statistikk.', array[10]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-9:sannsynlighet', '## Hva er sannsynlighet?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-9:sannsynlighet', 'Sannsynlighet', 'Et tall mellom 0 og 1 som sier hvor stor sjanse det er for at en hendelse skjer.', 0),
  ('matematikk-9:sannsynlighet', 'Tilfeldig forsøk', 'En handling der utfallet ikke er kjent på forhånd, for eksempel et terningkast.', 1),
  ('matematikk-9:sannsynlighet', 'Utfall', 'Ett mulig resultat av et forsøk, for eksempel at terningen viser 4.', 2),
  ('matematikk-9:sannsynlighet', 'Utfallsrom', 'Alle mulige utfall. For en terning: {1, 2, 3, 4, 5, 6}.', 3),
  ('matematikk-9:sannsynlighet', 'Hendelse', 'Ett eller flere utfall, for eksempel «partall» = {2, 4, 6}.', 4),
  ('matematikk-9:sannsynlighet', 'Gunstige / mulige', 'P = antall gunstige utfall / antall mulige utfall, når alle utfall er like sannsynlige.', 5),
  ('matematikk-9:sannsynlighet', 'Uniform modell', 'En sannsynlighetsmodell der alle utfallene har like stor sannsynlighet.', 6),
  ('matematikk-9:sannsynlighet', 'Umulig og sikker', 'P = 0 betyr umulig. P = 1 betyr sikker.', 7),
  ('matematikk-9:sannsynlighet', 'Komplementær hendelse', 'At hendelsen ikke skjer. P(ikke A) = 1 − P(A).', 8),
  ('matematikk-9:sannsynlighet', 'Relativ frekvens', 'Antall ganger en hendelse skjedde delt på antall forsøk.', 9),
  ('matematikk-9:sannsynlighet', 'De store talls lov', 'Med mange forsøk nærmer den relative frekvensen seg den egentlige sannsynligheten.', 10),
  ('matematikk-9:sannsynlighet', 'Valgtre', 'En tegning med greiner som viser alle utfall når flere forsøk gjøres etter hverandre.', 11),
  ('matematikk-9:sannsynlighet', 'Uavhengige forsøk', 'Forsøk der utfallet i det ene ikke påvirker det andre. Da kan sannsynlighetene ganges.', 12),
  ('matematikk-9:sannsynlighet', 'Rettferdig spill', 'Et spill der alle spillerne har like stor sjanse til å vinne.', 13),
  ('matematikk-9:sannsynlighet', 'Terningen har ingen hukommelse', 'Tidligere kast påvirker ikke neste. P(sekser) er alltid 1/6.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-9:sannsynlighet', 'q01', 'flervalg', 'Hva er sannsynligheten for å få et partall med én terning?', array['1/6', '1/3', '1/2', '2/3']::text[], 2, 'Partallene er 2, 4 og 6: 3 gunstige av 6 mulige. 3/6 = 1/2.', true, true, 0),
  ('matematikk-9:sannsynlighet', 'q02', 'flervalg', 'Hva betyr sannsynligheten 0?', array['At hendelsen er umulig', 'At hendelsen er sikker', 'At det er 50 % sjanse', 'At vi ikke vet']::text[], 0, 'Sannsynlighet 0 betyr at hendelsen aldri kan skje. 1 betyr at den er sikker.', true, false, 1),
  ('matematikk-9:sannsynlighet', 'q03', 'flervalg', 'Hva er sannsynligheten for å trekke et ess fra en vanlig kortstokk med 52 kort?', array['1/52', '1/4', '4/13', '1/13']::text[], 3, 'Det er 4 ess blant 52 kort: 4/52 = 1/13.', true, true, 2),
  ('matematikk-9:sannsynlighet', 'q04', 'flervalg', 'Sannsynligheten for regn i morgen er 0,3. Hva er sannsynligheten for at det ikke regner?', array['0,3', '0,7', '1,3', '0,03']::text[], 1, 'Komplementær hendelse: 1 − 0,3 = 0,7.', true, true, 3),
  ('matematikk-9:sannsynlighet', 'q05', 'flervalg', 'En tegnestift kastes 200 ganger og lander med spissen opp 130 ganger. Hva er den relative frekvensen?', array['0,65', '0,35', '1,3', '0,5']::text[], 0, 'Relativ frekvens = 130 / 200 = 0,65, altså 65 %.', true, true, 4),
  ('matematikk-9:sannsynlighet', 'q06', 'flervalg', 'Hvor mange mulige utfall er det når du kaster to terninger?', array['12', '6', '36', '18']::text[], 2, 'Hver terning har 6 utfall, og alle kombinasjoner er mulige: 6 · 6 = 36.', true, true, 5),
  ('matematikk-9:sannsynlighet', 'q07', 'flervalg', 'Hva er sannsynligheten for summen 7 med to terninger?', array['1/36', '7/36', '1/12', '1/6']::text[], 3, 'Summen 7 får du med (1,6), (2,5), (3,4), (4,3), (5,2) og (6,1): 6 av 36 = 1/6.', true, true, 6),
  ('matematikk-9:sannsynlighet', 'q08', 'flervalg', 'Du har kastet fem kast uten sekser. Hva er sannsynligheten for sekser i neste kast?', array['Større enn 1/6', '1/6', 'Mindre enn 1/6', '5/6']::text[], 1, 'Kastene er uavhengige. Terningen husker ikke tidligere kast, så sannsynligheten er fortsatt 1/6.', true, true, 7),
  ('matematikk-9:sannsynlighet', 'q09', 'flervalg', 'Hva sier de store talls lov?', array['At store tall er mer sannsynlige', 'At man alltid vinner til slutt', 'At relativ frekvens nærmer seg sannsynligheten når antall forsøk øker', 'At sannsynligheten blir større jo flere ganger man prøver']::text[], 2, 'Med få forsøk kan resultatet variere mye. Med mange forsøk stabiliserer den relative frekvensen seg rundt den egentlige sannsynligheten.', true, false, 8),
  ('matematikk-9:sannsynlighet', 'q10', 'flervalg', 'Hva er sannsynligheten for å få kron to ganger på rad med en mynt?', array['1/2', '1/3', '1/8', '1/4']::text[], 3, 'Kastene er uavhengige: 1/2 · 1/2 = 1/4. Utfallene er KK, KM, MK og MM, og bare ett er gunstig.', true, true, 9),
  ('matematikk-9:sannsynlighet', 'm01', 'sant-usant', 'En sannsynlighet kan være 1,2.', array['Sant', 'Usant']::text[], 1, 'Sannsynligheter ligger alltid mellom 0 og 1, eller mellom 0 % og 100 %.', false, true, 10),
  ('matematikk-9:sannsynlighet', 'm02', 'sant-usant', '25 % er det samme som sannsynligheten 1/4.', array['Sant', 'Usant']::text[], 0, '1/4 = 0,25 = 25 %.', false, true, 11),
  ('matematikk-9:sannsynlighet', 'm03', 'sant-usant', 'Med to terninger er summen 2 like sannsynlig som summen 7.', array['Sant', 'Usant']::text[], 1, 'Summen 2 kan bare komme som (1,1): 1/36. Summen 7 kan komme på 6 måter: 6/36.', false, true, 12),
  ('matematikk-9:sannsynlighet', 'm04', 'sant-usant', 'Relativ frekvens fra mange forsøk kan brukes som et anslag for sannsynligheten.', array['Sant', 'Usant']::text[], 0, 'Etter de store talls lov kommer relativ frekvens nær sannsynligheten når forsøkene er mange.', false, true, 13),
  ('matematikk-9:sannsynlighet', 'm05', 'flervalg', 'En pose har 3 røde og 7 blå kuler. Hva er sannsynligheten for å trekke en rød?', array['3/7', '3/10', '7/10', '1/3']::text[], 1, 'Det er 3 gunstige (røde) av 10 mulige kuler: 3/10.', false, true, 14),
  ('matematikk-9:sannsynlighet', 'm06', 'flervalg', '18 av 600 lyspærer er defekte. Hva er anslått sannsynlighet for en defekt pære?', array['18 %', '0,3 %', '6 %', '3 %']::text[], 3, '18 / 600 = 0,03 = 3 %.', false, true, 15),
  ('matematikk-9:sannsynlighet', 'm07', 'flervalg', 'Hva er sannsynligheten for to seksere med to terninger?', array['1/36', '2/6', '1/12', '1/6']::text[], 0, 'Terningene er uavhengige: 1/6 · 1/6 = 1/36.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-9:sannsynlighet', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-9:sannsynlighet', 's01', 'En vanlig terning kastes. Forklar forskjellen på ett utfall og en hendelse ved å bruke «terningen viser 4» og «terningen viser et tall større enn 4» som eksempler.', 'Et utfall er ett mulig resultat, for eksempel at terningen viser 4. En hendelse kan bestå av flere utfall; «større enn 4» består av utfallene 5 og 6.', array['Forklarer at et utfall er ett mulig resultat.', 'Forklarer at en hendelse kan bestå av ett eller flere utfall, og bruker eksemplet med 5 og 6.']::text[], 0),
  ('matematikk-9:sannsynlighet', 's02', 'En vanlig terning kastes én gang, og alle sidene er like sannsynlige. Hva er sannsynligheten for å få et tall mindre enn 3? Vis hvordan du finner svaret.', 'De gunstige utfallene er 1 og 2, altså 2 av 6 mulige utfall. Sannsynligheten er 2/6 = 1/3.', array['Finner de to gunstige utfallene blant de seks mulige.', 'Regner sannsynligheten som 2/6 = 1/3.']::text[], 1),
  ('matematikk-9:sannsynlighet', 's03', 'En vanlig terning kastes én gang. Finn sannsynligheten for ikke å få 1, og forklar kort hvilken regel du bruker.', 'Sannsynligheten for å få 1 er 1/6. Derfor er sannsynligheten for ikke å få 1 lik 1 − 1/6 = 5/6.', array['Bruker at sannsynligheten for den komplementære hendelsen er 1 minus sannsynligheten for å få 1.', 'Får svaret 5/6.']::text[], 2),
  ('matematikk-9:sannsynlighet', 's04', 'En knapp kastes 50 ganger og lander med forsiden opp 27 ganger. Hva er den relative frekvensen, og hva sier de store talls lov om resultatet hvis forsøket gjentas mange flere ganger?', 'Den relative frekvensen er 27/50 = 0,54, altså 54 %. Med mange flere forsøk vil den relative frekvensen nærme seg den egentlige sannsynligheten.', array['Regner den relative frekvensen som 27/50 = 54 %.', 'Forklarer at relativ frekvens med mange forsøk nærmer seg den egentlige sannsynligheten.']::text[], 3),
  ('matematikk-9:sannsynlighet', 's05', 'En vanlig terning kastes to ganger. Kastene er uavhengige. Hva er sannsynligheten for å få partall begge gangene? Vis det viktigste regnestykket.', 'Sannsynligheten for partall i ett kast er 3/6 = 1/2. Siden kastene er uavhengige, ganger vi sannsynlighetene: 1/2 · 1/2 = 1/4.', array['Bruker sannsynligheten 1/2 for partall i hvert kast.', 'Ganger sannsynlighetene og får 1/4.']::text[], 4),
  ('matematikk-9:sannsynlighet', 's06', 'En terning kastes to ganger. Forklar hvordan et valgtre kan hjelpe med å finne alle mulige utfall av de to kastene.', 'Valgtreet har greiner for mulige resultater ved hvert kast. Hver vei gjennom treet viser ett utfall for begge kastene, slik at alle kombinasjonene kan telles.', array['Forklarer at greinene viser mulige resultater ved hvert av de to kastene.', 'Forklarer at hver vei gjennom treet viser et mulig samlet utfall, slik at alle utfallene kan telles.']::text[], 5),
  ('matematikk-9:sannsynlighet', 's07', 'I et spill kaster to spillere hver sin vanlige terning. Spiller A vinner hvis terningen viser 1 eller 2, mens spiller B vinner hvis den viser 3, 4, 5 eller 6. Er spillet rettferdig? Begrunn svaret med sannsynligheten for at hver spiller vinner.', 'Spillet er ikke rettferdig. A har sannsynlighet 2/6 for å vinne, mens B har sannsynlighet 4/6, så spillerne har ikke like stor sjanse.', array['Finner sannsynligheten 2/6 for A og 4/6 for B.', 'Konkluderer med at spillet ikke er rettferdig fordi sannsynlighetene er ulike.']::text[], 6),
  ('matematikk-9:sannsynlighet', 's08', 'Sannsynligheten for en hendelse er 3/4. Skriv den som desimaltall og prosent, og forklar kort hva tallet sier om sjansen for at hendelsen skjer.', '3/4 = 0,75 = 75 %. Det betyr at sannsynligheten for at hendelsen skjer, er 75 %.', array['Gjør om 3/4 riktig til 0,75 og 75 %.', 'Forklarer at tallet uttrykker hvor stor sjanse hendelsen har for å skje.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-9:simulering', 'matematikk-9', 'simulering', 'Simulering med programmering', 'Hvordan du bruker tilfeldige tall og løkker i et program til å simulere tusenvis av forsøk og anslå sannsynligheter.', array[11]::int[], 7, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-9:simulering', '## Hva er en simulering?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-9:simulering', 'Simulering', 'En etterligning av et virkelig forsøk, ofte gjentatt mange ganger ved hjelp av en datamaskin.', 0),
  ('matematikk-9:simulering', 'random-modulen', 'Python-modul med funksjoner for tilfeldige tall. Hentes med import random.', 1),
  ('matematikk-9:simulering', 'randint(1, 6)', 'Gir et tilfeldig heltall fra og med 1 til og med 6, som et terningkast.', 2),
  ('matematikk-9:simulering', 'random()', 'Gir et tilfeldig desimaltall mellom 0 og 1.', 3),
  ('matematikk-9:simulering', 'random() < 0,3', 'Er sant i omtrent 30 % av tilfellene. Brukes til å simulere en hendelse med sannsynlighet 0,3.', 4),
  ('matematikk-9:simulering', 'Teller', 'En variabel som starter på 0 og økes med 1 hver gang hendelsen skjer.', 5),
  ('matematikk-9:simulering', 'Antall forsøk', 'Hvor mange ganger løkka gjentar forsøket, for eksempel 10 000.', 6),
  ('matematikk-9:simulering', 'Relativ frekvens i simulering', 'Telleren delt på antall forsøk.', 7),
  ('matematikk-9:simulering', 'Anslag', 'Et omtrentlig svar. En simulering gir et anslag, ikke et eksakt svar.', 8),
  ('matematikk-9:simulering', 'Variasjon mellom kjøringer', 'Hver kjøring gir litt ulikt svar. Variasjonen blir mindre med flere forsøk.', 9),
  ('matematikk-9:simulering', 'Teoretisk sannsynlighet', 'Sannsynligheten regnet ut med gunstige/mulige. Kan brukes til å sjekke simuleringen.', 10),
  ('matematikk-9:simulering', 'Bursdagsproblemet', 'Sannsynligheten for at to i en gruppe har samme bursdag. Egnet for simulering.', 11),
  ('matematikk-9:simulering', 'Simulere to terninger', 'Lag to tilfeldige tall i hver runde og sjekk for eksempel summen.', 12),
  ('matematikk-9:simulering', 'Feil grenser', 'Vanlig programfeil, for eksempel randint(0, 6), som gir sju mulige tall i stedet for seks.', 13),
  ('matematikk-9:simulering', 'Når simulere?', 'Når sannsynligheten er vanskelig å regne ut direkte, som i spill med mange regler.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-9:simulering', 'q01', 'flervalg', 'Hva er en simulering?', array['Et bevis for en formel', 'En etterligning av et forsøk, ofte gjentatt mange ganger med datamaskin', 'En tabell over alle utfall', 'Et diagram']::text[], 1, 'I en simulering etterligner vi et virkelig forsøk, for eksempel et terningkast, og gjentar det mange ganger.', true, true, 0),
  ('matematikk-9:simulering', 'q02', 'flervalg', 'Hvilke tall kan randint(1, 6) gi?', array['0, 1, 2, 3, 4, 5', 'Alle tall mellom 1 og 6, også desimaltall', '1, 2, 3, 4, 5, 6', 'Bare 1 og 6']::text[], 2, 'randint gir heltall fra og med den første til og med den siste grensen.', true, true, 1),
  ('matematikk-9:simulering', 'q03', 'flervalg', 'Hvorfor gjør vi mange forsøk i en simulering?', array['For at relativ frekvens skal komme nær sannsynligheten', 'For at programmet skal gå saktere', 'Fordi Python krever det', 'For å få et eksakt svar']::text[], 0, 'Etter de store talls lov blir den relative frekvensen mer stabil og nærmere sannsynligheten jo flere forsøk vi gjør.', true, true, 2),
  ('matematikk-9:simulering', 'q04', 'flervalg', 'En simulering gir 1712 seksere på 10 000 kast. Hva er den relative frekvensen?', array['1712', '0,01712', '17,12', '0,1712']::text[], 3, '1712 / 10 000 = 0,1712, som ligger nær den teoretiske sannsynligheten 1/6 ≈ 0,167.', true, true, 3),
  ('matematikk-9:simulering', 'q05', 'flervalg', 'Hva gjør vi med telleren hver gang hendelsen skjer?', array['Setter den til 0', 'Øker den med 1', 'Deler den på 2', 'Skriver den ut']::text[], 1, 'Telleren teller hvor mange ganger hendelsen har skjedd, så den økes med 1 hver gang.', true, true, 4),
  ('matematikk-9:simulering', 'q06', 'flervalg', 'Du kjører samme simulering to ganger og får 0,164 og 0,169. Hva er mest sannsynlig?', array['Programmet er feil', 'Datamaskinen er ødelagt', 'Det er vanlig variasjon mellom kjøringer', 'Sannsynligheten har endret seg']::text[], 2, 'Simuleringer gir tilfeldige resultater, så små forskjeller mellom kjøringer er helt normale.', true, false, 5),
  ('matematikk-9:simulering', 'q07', 'flervalg', 'Hvilken betingelse simulerer en hendelse med sannsynlighet 20 %?', array['random() < 0,2', 'random() > 0,2', 'randint(1, 20) == 1', 'random() == 0,2']::text[], 0, 'random() gir et tall mellom 0 og 1, og er mindre enn 0,2 i omtrent 20 % av tilfellene.', true, true, 6),
  ('matematikk-9:simulering', 'q08', 'flervalg', 'En simulering av summen 7 med to terninger gir 0,25. Den teoretiske sannsynligheten er 1/6. Hva bør du gjøre?', array['Stole på simuleringen', 'Sjekke programmet for feil', 'Senke antall forsøk', 'Endre den teoretiske verdien']::text[], 1, '0,25 er langt unna 1/6 ≈ 0,167. Med mange forsøk tyder et så stort avvik på en feil i programmet.', true, true, 7),
  ('matematikk-9:simulering', 'q09', 'flervalg', 'Hvilken feil gjør at en simulert terning kan vise 0?', array['Løkka er for kort', 'Telleren starter på 0', 'Antall forsøk er for lite', 'randint(0, 6) i stedet for randint(1, 6)']::text[], 3, 'randint(0, 6) gir sju mulige tall, 0 til 6. En terning skal bare gi 1 til 6.', true, true, 8),
  ('matematikk-9:simulering', 'q10', 'flervalg', 'Hvilket spørsmål egner seg best for simulering?', array['Hva er 7 · 8?', 'Hvor mange kast trengs i gjennomsnitt før du får en sekser?', 'Hva er arealet av et kvadrat?', 'Hva er medianen av tre tall?']::text[], 1, 'Antall kast før sekser er tilfeldig og varierer. En simulering med mange runder gir et godt anslag på gjennomsnittet.', true, false, 9),
  ('matematikk-9:simulering', 'm01', 'sant-usant', 'En simulering gir alltid nøyaktig samme svar hver gang den kjøres.', array['Sant', 'Usant']::text[], 1, 'Simuleringer bruker tilfeldige tall, så svaret varierer litt fra kjøring til kjøring.', false, true, 10),
  ('matematikk-9:simulering', 'm02', 'sant-usant', 'Med 100 000 forsøk varierer resultatet vanligvis mindre enn med 100 forsøk.', array['Sant', 'Usant']::text[], 0, 'Flere forsøk gir mer stabile relative frekvenser.', false, true, 11),
  ('matematikk-9:simulering', 'm03', 'sant-usant', 'random() kan brukes til å simulere en hendelse med sannsynlighet 0,5.', array['Sant', 'Usant']::text[], 0, 'Betingelsen random() < 0,5 er sann omtrent halvparten av gangene, som et myntkast.', false, true, 12),
  ('matematikk-9:simulering', 'm04', 'sant-usant', 'Simulering kan bare brukes når vi allerede kjenner sannsynligheten.', array['Sant', 'Usant']::text[], 1, 'Simulering er nettopp nyttig når sannsynligheten er vanskelig å regne ut direkte.', false, true, 13),
  ('matematikk-9:simulering', 'm05', 'flervalg', 'Et program teller 4950 kron på 10 000 myntkast. Hva er den relative frekvensen?', array['0,495', '4,95', '49,5', '0,0495']::text[], 0, '4950 / 10 000 = 0,495, nær den teoretiske verdien 0,5.', false, true, 14),
  ('matematikk-9:simulering', 'm06', 'flervalg', 'Hva må telleren settes til før løkka starter?', array['1', '10 000', '0', 'Et tilfeldig tall']::text[], 2, 'Telleren skal telle fra null, så den settes til 0 før forsøkene begynner.', false, true, 15),
  ('matematikk-9:simulering', 'm07', 'flervalg', 'Hvordan simulerer du to terningkast i én runde?', array['randint(2, 12)', 'Lag to tilfeldige tall med randint(1, 6)', 'randint(1, 6) · 2', 'random() · 12']::text[], 1, 'To uavhengige tall gir riktig fordeling. randint(2, 12) gir alle summer like sannsynlige, og det stemmer ikke for to terninger.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-9:simulering', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-9:simulering', 's01', 'Sammenlign `randint(1, 6)` og `random()` i Python. Hva slags tall gir hver av dem, og hvilken kan brukes når du vil simulere en hendelse med sannsynlighet 30 %?', '`randint(1, 6)` gir et tilfeldig heltall fra 1 til 6, mens `random()` gir et tilfeldig desimaltall mellom 0 og 1. For å simulere en hendelse med sannsynlighet 30 % kan du sjekke om `random() < 0,3`.', array['Forklarer forskjellen på heltallene fra `randint` og desimaltallet fra `random()`.', 'Knytter `random() < 0,3` til en hendelse med sannsynlighet 30 %.']::text[], 0),
  ('matematikk-9:simulering', 's02', 'Et terningspill har mange regler, og sannsynligheten for å vinne er vanskelig å regne ut direkte. Forklar hvorfor en simulering kan være nyttig i denne situasjonen.', 'En datamaskin kan gjenta spillet mange ganger raskt. Andelen ganger spilleren vinner, gir et anslag på hvor ofte spilleren vinner.', array['Forklarer at simuleringen gjentar spillet mange ganger.', 'Knytter andelen seire til et anslag på sannsynligheten for å vinne.']::text[], 1),
  ('matematikk-9:simulering', 's03', 'Beskriv hvordan du kan lage én runde av en simulering av bursdagsproblemet for en klasse på 25 elever. Forklar også hva du må telle når simuleringen gjentas mange ganger.', 'I én runde simulerer jeg en bursdag for hver av de 25 elevene og sjekker om minst to har samme bursdag. Jeg teller hvor mange runder som får en slik match, og deler på antall runder for å få relativ frekvens.', array['Beskriver at bursdager simuleres for elevene, og at en runde sjekker om noen deler bursdag.', 'Forklarer at antall runder med match telles og brukes til å finne relativ frekvens.']::text[], 2),
  ('matematikk-9:simulering', 's04', 'Du vil simulere en vanlig terning, men programmet bruker `randint(1, 5)`. Forklar hvorfor dette ikke simulerer en vanlig terning riktig, og hvilken kommando som bør brukes i stedet.', '`randint(1, 5)` kan bare gi tallene 1 til 5, så terningkastet 6 mangler. Bruk `randint(1, 6)` for å få alle de seks mulige terningkastene.', array['Forklarer at 6 ikke kan komme med `randint(1, 5)`.', 'Oppgir `randint(1, 6)` som riktig kommando for en vanlig terning.']::text[], 3),
  ('matematikk-9:simulering', 's05', 'Forklar hva det betyr at resultatet fra en simulering er et anslag, og ikke et eksakt svar.', 'Et anslag er et omtrentlig svar som simuleringen regner ut fra resultatene av mange forsøk. Det er ikke nødvendigvis nøyaktig lik den egentlige sannsynligheten.', array['Forklarer at anslaget er omtrentlig og bygger på simulerte forsøk.', 'Skiller anslaget fra den egentlige sannsynligheten eller et eksakt svar.']::text[], 4),
  ('matematikk-9:simulering', 's06', 'Du vil undersøke hvor mange kast det i gjennomsnitt tar før du får en sekser. Beskriv hva du gjør i én simulert runde, og hvordan du kan bruke mange runder til å finne et anslag.', 'I én runde kaster jeg en simulert terning gjentatte ganger fram til jeg får en sekser, og teller kastene. Jeg gjentar dette mange ganger og finner gjennomsnittet av antall kast i rundene.', array['Beskriver at kast gjentas fram til en sekser, og at kastene telles.', 'Forklarer at mange runders antall kast brukes til å finne et gjennomsnittlig anslag.']::text[], 5),
  ('matematikk-9:simulering', 's07', 'I en simulering skjedde en bestemt hendelse 18 ganger på 60 forsøk. Regn ut den relative frekvensen, og forklar kort hva tallet forteller.', 'Den relative frekvensen er 18 delt på 60, som er 0,3. Det betyr at hendelsen skjedde i 30 % av forsøkene i simuleringen.', array['Regner ut 18 ÷ 60 = 0,3.', 'Forklarer at tallet beskriver andelen forsøk der hendelsen skjedde.']::text[], 6),
  ('matematikk-9:simulering', 's08', 'Når summen av to terninger er 7, er den teoretiske sannsynligheten omtrent 1/6. I 600 simulerte runder, omtrent hvor mange ganger bør summen 7 komme hvis resultatet ligger nær den teoretiske sannsynligheten? Vis det viktigste regnestykket.', 'Jeg regner 600 · 1/6 = 100. Summen 7 bør derfor komme omtrent 100 ganger.', array['Bruker sannsynligheten 1/6 på de 600 rundene.', 'Får omtrent 100 ganger, med et relevant regnesteg.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-9:pronunciation', 'engelsk-9', 'pronunciation', 'Pronunciation', 'The English sounds Norwegians find hardest, silent letters, word stress and intonation, and how to practise pronunciation.', array[3, 4, 7]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-9:pronunciation', '## Why pronunciation matters
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-9:pronunciation', 'Voiceless th', 'The sound in think, three and month. Tongue between the teeth, no voice.', 0),
  ('engelsk-9:pronunciation', 'Voiced th', 'The sound in this, that and mother. Tongue between the teeth, with voice.', 1),
  ('engelsk-9:pronunciation', 'v', 'Top teeth on the lower lip: very, van, vest.', 2),
  ('engelsk-9:pronunciation', 'w', 'Rounded lips like a short “u”: we, west, wine.', 3),
  ('engelsk-9:pronunciation', 'z at the end', 'Plurals and verbs often end in a buzzing z-sound: dogs, is, was.', 4),
  ('engelsk-9:pronunciation', 'Silent k', 'know, knife, knee.', 5),
  ('engelsk-9:pronunciation', 'Silent w', 'write, wrong, who.', 6),
  ('engelsk-9:pronunciation', 'Silent b', 'climb, doubt, thumb.', 7),
  ('engelsk-9:pronunciation', 'Silent h', 'hour, honest, honour.', 8),
  ('engelsk-9:pronunciation', 'Word stress', 'One syllable is pronounced louder and longer: ho-TEL.', 9),
  ('engelsk-9:pronunciation', 'RE-cord / re-CORD', 'Noun with stress on the first syllable, verb on the second.', 10),
  ('engelsk-9:pronunciation', 'Intonation', 'The melody of speech. Usually falling in statements, often rising in yes/no questions.', 11),
  ('engelsk-9:pronunciation', 'Shadowing', 'Repeating what a speaker says right after them, to practise pronunciation.', 12),
  ('engelsk-9:pronunciation', 'Intelligibility', 'Being easy to understand. More important than sounding like a native speaker.', 13),
  ('engelsk-9:pronunciation', 'Minimal pair', 'Two words that differ in only one sound: vine – wine, ship – chip.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-9:pronunciation', 'q01', 'flervalg', 'Which word has a silent letter?', array['knife', 'kind', 'keep', 'kite']::text[], 0, 'The k in “knife” is silent.', true, true, 0),
  ('engelsk-9:pronunciation', 'q02', 'flervalg', 'How do you make the th-sound in “think”?', array['Like a t', 'With the tongue between the teeth', 'With rounded lips', 'Like an f']::text[], 1, 'The tongue tip goes between the teeth. Saying “tink” is a common mistake.', true, true, 1),
  ('engelsk-9:pronunciation', 'q03', 'flervalg', 'Which pair is a minimal pair for practising v and w?', array['vine – wine', 'very – vary', 'west – east', 'van – man']::text[], 0, '“Vine” and “wine” differ only in the first sound, v or w.', true, true, 2),
  ('engelsk-9:pronunciation', 'q04', 'flervalg', 'Where is the stress in the verb “record” (to record a song)?', array['RE-cord', 'Both syllables equally', 're-CORD', 'It has no stress']::text[], 2, 'As a verb, “record” is stressed on the second syllable. The noun is RE-cord.', true, true, 3),
  ('engelsk-9:pronunciation', 'q05', 'flervalg', 'Which word has a silent w?', array['water', 'write', 'west', 'wind']::text[], 1, 'In “write”, the w is not pronounced.', true, true, 4),
  ('engelsk-9:pronunciation', 'q06', 'flervalg', 'What usually happens with intonation in a yes/no question like “Are you coming?”', array['It goes down', 'It stays flat', 'It goes up at the end', 'It stops']::text[], 2, 'Yes/no questions often have rising intonation at the end.', true, true, 5),
  ('engelsk-9:pronunciation', 'q07', 'flervalg', 'What is most important in pronunciation?', array['Sounding exactly like the King', 'Speaking as fast as possible', 'Using only American accent', 'Being easy to understand']::text[], 3, 'Clear, intelligible pronunciation matters more than sounding like a native speaker.', true, false, 6),
  ('engelsk-9:pronunciation', 'q08', 'flervalg', 'Which word has a silent h?', array['hour', 'house', 'happy', 'hotel']::text[], 0, '“Hour” is pronounced like “our”. That is also why we say “an hour”.', true, true, 7),
  ('engelsk-9:pronunciation', 'q09', 'flervalg', 'What sound should the s in “dogs” have?', array['A sharp s', 'A buzzing z-sound', 'A sh-sound', 'It is silent']::text[], 1, 'After voiced sounds, the plural -s is pronounced like z: dogz.', true, true, 8),
  ('engelsk-9:pronunciation', 'q10', 'flervalg', 'What is shadowing?', array['Reading in the dark', 'Writing words many times', 'Repeating what a speaker says right after them', 'Translating to Norwegian']::text[], 2, 'Shadowing trains rhythm, stress and intonation by copying a speaker closely.', true, false, 9),
  ('engelsk-9:pronunciation', 'm01', 'sant-usant', 'The b in “climb” is pronounced.', array['Sant', 'Usant']::text[], 1, 'The b in “climb” is silent.', false, true, 10),
  ('engelsk-9:pronunciation', 'm02', 'sant-usant', 'There is only one correct English accent.', array['Sant', 'Usant']::text[], 1, 'There are many accents. Choose one model, but learn to understand many.', false, true, 11),
  ('engelsk-9:pronunciation', 'm03', 'sant-usant', 'The noun “present” (a gift) is stressed on the first syllable.', array['Sant', 'Usant']::text[], 0, 'PRE-sent (noun) and pre-SENT (verb).', false, true, 12),
  ('engelsk-9:pronunciation', 'm04', 'sant-usant', 'Saying “tree” instead of “three” can cause misunderstandings.', array['Sant', 'Usant']::text[], 0, 'The th-sound changes the meaning, so it is important to get it right.', false, true, 13),
  ('engelsk-9:pronunciation', 'm05', 'flervalg', 'Which word starts with a voiced th-sound?', array['think', 'three', 'this', 'thank']::text[], 2, '“This” has the voiced th. The others have the voiceless th.', false, true, 14),
  ('engelsk-9:pronunciation', 'm06', 'flervalg', 'In which word is the l silent?', array['walk', 'lamp', 'late', 'silk']::text[], 0, 'The l in “walk” is not pronounced.', false, true, 15),
  ('engelsk-9:pronunciation', 'm07', 'flervalg', 'How do you make the w-sound?', array['With the teeth on the lip', 'With rounded lips', 'With the tongue between the teeth', 'Through the nose']::text[], 1, 'The w is made with rounded lips, like a short “u”.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-9:pronunciation', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-9:pronunciation', 's01', 'What does intelligibility mean in pronunciation, and why is it a more important goal than sounding like a native speaker?', 'Intelligibility means being easy to understand. A speaker does not need a native accent if people can understand what they say.', array['Explains that intelligibility means being easy to understand.', 'Explains that sounding like a native speaker is not necessary if the speaker is understandable.']::text[], 0),
  ('engelsk-9:pronunciation', 's02', 'Compare the two English th-sounds in “think” and “this”. What is the same about how they are made, and what is different?', 'For both sounds, the tip of the tongue goes between the teeth. The sound in “think” is voiceless, while the sound in “this” is voiced.', array['Says the tongue tip goes between the teeth for both sounds.', 'Distinguishes the voiceless sound in “think” from the voiced sound in “this”.']::text[], 1),
  ('engelsk-9:pronunciation', 's03', 'Explain how your mouth is positioned differently when you say the v in “very” and the w in “we”.', 'For v, the top teeth touch the lower lip. For w, the lips are rounded, like a short “u” sound.', array['Describes the top teeth touching the lower lip for v.', 'Describes rounded lips for w.']::text[], 2),
  ('engelsk-9:pronunciation', 's04', 'In “knife” and “write”, one written letter is not pronounced in each word. Identify those letters and explain what this means when saying the words aloud.', 'The k in “knife” and the w in “write” are silent. You say the words without pronouncing those letters.', array['Identifies k as silent in “knife” and w as silent in “write”.', 'Explains that the silent letters are not pronounced aloud.']::text[], 3),
  ('engelsk-9:pronunciation', 's05', 'Compare “REcord” as a noun and “reCORD” as a verb. Where is the stress in each word, and how does the stress relate to the word’s use?', 'As a noun, the stress is on the first syllable: REcord. As a verb, it is on the second syllable: reCORD.', array['Places the noun’s stress on the first syllable.', 'Places the verb’s stress on the second syllable and connects the stress pattern to the word’s use.']::text[], 4),
  ('engelsk-9:pronunciation', 's06', 'British and American English can differ in the r-sound in “car” and in the pronunciation of words such as “tomato” and “schedule”. Why is it useful to understand different varieties, and what can a learner choose as a model?', 'Understanding different varieties helps you understand more English speakers. You can choose one variety as your own pronunciation model.', array['Explains that understanding varieties helps with understanding different English speakers.', 'Says a learner can choose one variety as a model.']::text[], 5),
  ('engelsk-9:pronunciation', 's07', 'When saying “bag” and “back”, what must happen to the final consonants, and why does this matter for understanding?', 'The final consonants must sound different: “bag” ends with a voiced sound, while “back” has a different final sound. If they sound the same, it may be harder to understand which word is meant.', array['States that the final consonants in “bag” and “back” must sound different.', 'Connects the difference to being able to understand which word is meant.']::text[], 6),
  ('engelsk-9:pronunciation', 's08', 'You are learning a new English word and want to pronounce it clearly. Explain how you could use an online dictionary and word stress to practise it.', 'I can use an online dictionary to listen to the word’s pronunciation. I can notice which syllable is stressed and practise saying the word with that stress.', array['Uses the dictionary to listen to the word’s pronunciation.', 'Explains that the learner should notice and practise the stressed syllable.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-9:common-grammar-mistakes', 'engelsk-9', 'common-grammar-mistakes', 'Common mistakes and false friends', 'The grammar mistakes Norwegian learners make most often – subject–verb agreement, much/many, it/there, the article – and false friends between Norwegian and English.', array[9, 7, 8]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-9:common-grammar-mistakes', '## Learning from mistakes
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-9:common-grammar-mistakes', 'Subject–verb agreement', 'The verb must match the subject: she plays, they play.', 0),
  ('engelsk-9:common-grammar-mistakes', 'There is / there are', 'The verb agrees with what follows: there is a cat, there are two cats.', 1),
  ('engelsk-9:common-grammar-mistakes', 'Everybody is', 'Everybody, nobody and each are singular.', 2),
  ('engelsk-9:common-grammar-mistakes', 'The police are', 'Police and people are plural in English.', 3),
  ('engelsk-9:common-grammar-mistakes', 'many', 'With countable nouns: many books, many people.', 4),
  ('engelsk-9:common-grammar-mistakes', 'much', 'With uncountable nouns: much water, much time.', 5),
  ('engelsk-9:common-grammar-mistakes', 'Uncountable nouns', 'information, advice, furniture, news, homework – no plural and no “a”.', 6),
  ('engelsk-9:common-grammar-mistakes', 'It or there?', 'There = something exists. It = something already mentioned, weather, time.', 7),
  ('engelsk-9:common-grammar-mistakes', 'She is a doctor', 'English uses a/an with jobs.', 8),
  ('engelsk-9:common-grammar-mistakes', 'good / well', 'Adjective and adverb: a good singer, she sings well.', 9),
  ('engelsk-9:common-grammar-mistakes', 'eventually', 'False friend: til slutt.', 10),
  ('engelsk-9:common-grammar-mistakes', 'actually', 'False friend: faktisk.', 11),
  ('engelsk-9:common-grammar-mistakes', 'sensible', 'False friend: fornuftig. (sensitive = sensibel)', 12),
  ('engelsk-9:common-grammar-mistakes', 'fabric', 'False friend: stoff. (factory = fabrikk)', 13),
  ('engelsk-9:common-grammar-mistakes', 'brave', 'False friend: modig. (well-behaved = brav)', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-9:common-grammar-mistakes', 'q01', 'flervalg', 'Choose the correct sentence.', array['She play the guitar.', 'She plays the guitar.', 'She playing the guitar.', 'She are playing the guitar.']::text[], 1, 'With “she” in the present simple, the verb needs -s: she plays.', true, true, 0),
  ('engelsk-9:common-grammar-mistakes', 'q02', 'flervalg', 'Choose the correct word: “There … two cars outside.”', array['is', 'be', 'are', 'am']::text[], 2, 'The verb agrees with “two cars”, which is plural: there are.', true, true, 1),
  ('engelsk-9:common-grammar-mistakes', 'q03', 'flervalg', 'Choose the correct word: “How … money do you have?”', array['much', 'many', 'few', 'a lot']::text[], 0, 'Money is uncountable, so we use “much”.', true, true, 2),
  ('engelsk-9:common-grammar-mistakes', 'q04', 'flervalg', 'Which sentence is correct?', array['Can you give me an advice?', 'Can you give me some advices?', 'Can you give me a advice?', 'Can you give me some advice?']::text[], 3, '“Advice” is uncountable in English. Say “some advice” or “a piece of advice”.', true, true, 3),
  ('engelsk-9:common-grammar-mistakes', 'q05', 'flervalg', 'Choose the correct word: “… is raining again.”', array['There', 'It', 'This', 'Here']::text[], 1, 'We use “it” about the weather: It is raining.', true, true, 4),
  ('engelsk-9:common-grammar-mistakes', 'q06', 'flervalg', 'What does “eventually” mean?', array['eventuelt', 'vanligvis', 'til slutt', 'straks']::text[], 2, '“Eventually” means “til slutt”. “Eventuelt” is “possibly” or “if necessary”.', true, true, 5),
  ('engelsk-9:common-grammar-mistakes', 'q07', 'flervalg', 'Which sentence is correct?', array['She is doctor.', 'She is a doctor.', 'She is the doctor for job.', 'She doctor is.']::text[], 1, 'English uses a/an before jobs: She is a doctor.', true, false, 6),
  ('engelsk-9:common-grammar-mistakes', 'q08', 'flervalg', 'Choose the correct word: “He drives very …”', array['careful', 'carefully', 'care', 'carefulness']::text[], 1, 'An adverb describes how he drives: carefully.', true, true, 7),
  ('engelsk-9:common-grammar-mistakes', 'q09', 'flervalg', 'What does “sensible” mean?', array['fornuftig', 'sensibel', 'følsom', 'sanselig']::text[], 0, '“Sensible” means “fornuftig”. “Sensibel” in Norwegian is “sensitive” in English.', true, false, 8),
  ('engelsk-9:common-grammar-mistakes', 'q10', 'flervalg', 'Choose the correct sentence.', array['Everybody are here.', 'Everybody were here now.', 'Everybody is here.', 'Everybody be here.']::text[], 2, '“Everybody” is grammatically singular: Everybody is here.', true, true, 9),
  ('engelsk-9:common-grammar-mistakes', 'm01', 'sant-usant', '“The news are good” is correct English.', array['Sant', 'Usant']::text[], 1, '“News” is uncountable and singular: The news is good.', false, true, 10),
  ('engelsk-9:common-grammar-mistakes', 'm02', 'sant-usant', '“Actually” means “faktisk”.', array['Sant', 'Usant']::text[], 0, '“Actually” is a false friend. “Aktuelt” is “relevant” or “current”.', false, true, 11),
  ('engelsk-9:common-grammar-mistakes', 'm03', 'sant-usant', '“Many” is used with uncountable nouns like water.', array['Sant', 'Usant']::text[], 1, '“Many” is for countable nouns. With water we use “much”.', false, true, 12),
  ('engelsk-9:common-grammar-mistakes', 'm04', 'sant-usant', '“There is a cat in the garden” uses “there” because the sentence says that something exists.', array['Sant', 'Usant']::text[], 0, '“There is/are” introduces something that exists or is present.', false, true, 13),
  ('engelsk-9:common-grammar-mistakes', 'm05', 'flervalg', 'What does “fabric” mean?', array['fabrikk', 'stoff', 'fabel', 'fasade']::text[], 1, '“Fabric” is cloth or material. A factory is “fabrikk”.', false, true, 14),
  ('engelsk-9:common-grammar-mistakes', 'm06', 'flervalg', 'Choose the correct word: “There were … people at the concert than last year.”', array['less', 'little', 'fewer', 'much']::text[], 2, '“People” is countable, so we use “fewer”.', false, true, 15),
  ('engelsk-9:common-grammar-mistakes', 'm07', 'flervalg', 'Which sentence uses “good” and “well” correctly?', array['She sings good.', 'She is a well singer.', 'She sings goodly.', 'She sings well.']::text[], 3, '“Well” is the adverb that describes how she sings.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-9:common-grammar-mistakes', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-9:common-grammar-mistakes', 's01', 'Norwegian and English are closely related, which can make English easier to learn. Why can this similarity also lead to mistakes?', 'Because the languages are similar, learners may translate directly from Norwegian. A direct translation can lead to typical mistakes in English.', array['Explains that the languages’ similarity can tempt learners to translate directly.', 'Connects direct translation with making mistakes in English.']::text[], 0),
  ('engelsk-9:common-grammar-mistakes', 's02', 'Complete the sentences and explain why the verbs are different: “Everybody ___ ready, but the police ___ coming.”', 'Everybody is ready, but the police are coming. Everybody is singular, while police is plural in English.', array['Uses “is” with “everybody” because it is singular.', 'Uses “are” with “police” because it is plural in English.']::text[], 1),
  ('engelsk-9:common-grammar-mistakes', 's03', 'Correct this sentence and explain the noun mistake: “I got an advice and two informations.”', 'I got a piece of advice and some information. “Advice” and “information” are uncountable nouns in English, so they do not take “a” or a plural ending.', array['Correctly uses “a piece of advice” or another correct form without “an advice”.', 'Uses “information” without a plural ending and recognises that it is uncountable.']::text[], 2),
  ('engelsk-9:common-grammar-mistakes', 's04', 'Correct both sentences and explain the article use: “She is doctor. We had a dinner.”', 'She is a doctor. We had dinner. English uses “a” with jobs but usually no article with meals.', array['Adds “a” before the job “doctor”.', 'Removes “a” before “dinner” and explains that meals usually have no article.']::text[], 3),
  ('engelsk-9:common-grammar-mistakes', 's05', 'A learner writes, “Actually, I might visit if I have time,” but means “possibly.” Explain what is wrong and replace “Actually” with the right word.', '“Actually” means “faktisk,” not “possibly.” The learner should write, “Possibly, I might visit if I have time.”', array['Explains that “actually” means “faktisk,” not “possibly”.', 'Replaces “Actually” with “Possibly” or another suitable way to express “possibly”.']::text[], 4),
  ('engelsk-9:common-grammar-mistakes', 's06', 'A learner means they work in a factory but writes, “I work in a fabric.” Correct the sentence and explain the difference between “fabric” and “factory.”', 'The correct sentence is, “I work in a factory.” “Fabric” means “stoff,” while “factory” means “fabrikk.”', array['Corrects “fabric” to “factory” in the sentence.', 'Distinguishes the meanings: fabric is stoff and factory is fabrikk.']::text[], 5),
  ('engelsk-9:common-grammar-mistakes', 's07', 'A Norwegian speaker thinks the English word “brave” means “brav.” Explain the mistake and say what “brave” means in English.', '“Brave” does not mean “brav”; it means “modig.” The similar-looking words have different meanings.', array['Gives the meaning of “brave” as “modig”.', 'Explains that it does not mean Norwegian “brav” (well-behaved).']::text[], 6),
  ('engelsk-9:common-grammar-mistakes', 's08', 'You have already introduced a cat by writing, “There is a cat in the garden.” Write a sentence saying that the cat is black, and explain why it starts with “it” or “there.”', 'It is black. Use “it” because the cat has already been mentioned.', array['Begins the sentence with “It” and says the cat is black.', 'Explains that “it” refers to something already mentioned.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-9:short-stories', 'engelsk-9', 'short-stories', 'Short stories and literary analysis', 'Key features of short stories, literary terms like theme, symbol and irony, and how to write a short analysis of a story in English.', array[11, 10]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-9:short-stories', '## What is a short story?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-9:short-stories', 'Short story', 'A short work of fiction with few characters, often one setting and a short time span.', 0),
  ('engelsk-9:short-stories', 'Protagonist', 'The main character in a story.', 1),
  ('engelsk-9:short-stories', 'Antagonist', 'A character or force that works against the protagonist.', 2),
  ('engelsk-9:short-stories', 'External conflict', 'A struggle between a character and another person, nature or society.', 3),
  ('engelsk-9:short-stories', 'Internal conflict', 'A struggle inside a character''s mind.', 4),
  ('engelsk-9:short-stories', 'Atmosphere', 'The mood or feeling of a story, often created by the setting.', 5),
  ('engelsk-9:short-stories', 'Theme', 'The main idea or message of a story, such as identity or friendship.', 6),
  ('engelsk-9:short-stories', 'Symbol', 'An object, place or colour that stands for something more.', 7),
  ('engelsk-9:short-stories', 'Foreshadowing', 'Hints about what will happen later in the story.', 8),
  ('engelsk-9:short-stories', 'Irony', 'When the opposite of what is expected happens, or words mean the opposite of what is said.', 9),
  ('engelsk-9:short-stories', 'Open ending', 'An ending that leaves questions unanswered.', 10),
  ('engelsk-9:short-stories', 'Indirect characterisation', 'We learn about a character through actions, words and thoughts.', 11),
  ('engelsk-9:short-stories', 'Round character', 'A complex character who changes during the story.', 12),
  ('engelsk-9:short-stories', 'Flat character', 'A simple character with few traits who does not develop.', 13),
  ('engelsk-9:short-stories', 'Present tense in analysis', 'Write about stories in the present tense: “The narrator feels lonely.”', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-9:short-stories', 'q01', 'flervalg', 'What is the protagonist?', array['The villain', 'The main character', 'The narrator''s friend', 'The setting']::text[], 1, 'The protagonist is the main character, the one the story is mostly about.', true, true, 0),
  ('engelsk-9:short-stories', 'q02', 'flervalg', 'A girl struggles to decide whether to tell the truth. What kind of conflict is this?', array['Internal conflict', 'External conflict with nature', 'External conflict with society', 'No conflict']::text[], 0, 'The struggle happens inside her mind, so it is an internal conflict.', true, true, 1),
  ('engelsk-9:short-stories', 'q03', 'flervalg', 'What is a theme?', array['The title', 'The place where the story happens', 'The main idea or message of the story', 'The first sentence']::text[], 2, 'The theme is what the story is really about on a deeper level, like loneliness or courage.', true, true, 2),
  ('engelsk-9:short-stories', 'q04', 'flervalg', 'A fire station burns down. What literary device is this an example of?', array['Foreshadowing', 'Symbol', 'Flat character', 'Irony']::text[], 3, 'It is the opposite of what we would expect, which is situational irony.', true, true, 3),
  ('engelsk-9:short-stories', 'q05', 'flervalg', 'Which tense should you use when writing an analysis of a story?', array['Present tense', 'Past tense', 'Future tense', 'Past perfect']::text[], 0, 'Literary analysis uses the present tense: “The narrator describes…”.', true, true, 4),
  ('engelsk-9:short-stories', 'q06', 'flervalg', 'What is foreshadowing?', array['A description of shadows', 'Hints about what will happen later', 'The ending of the story', 'A flashback']::text[], 1, 'Foreshadowing builds suspense by hinting at future events.', true, true, 5),
  ('engelsk-9:short-stories', 'q07', 'flervalg', 'What is indirect characterisation?', array['The narrator tells us what a character is like', 'We learn about a character through actions, words and thoughts', 'The character is not important', 'The character is described in a list']::text[], 1, 'Indirect characterisation lets the reader draw conclusions from what the character does and says.', true, false, 6),
  ('engelsk-9:short-stories', 'q08', 'flervalg', 'What should a good body paragraph in an analysis contain?', array['Only a long quotation', 'A retelling of the whole plot', 'A topic sentence, evidence from the text and your own explanation', 'Only your personal opinion']::text[], 2, 'A clear point, evidence and explanation show that your interpretation is based on the text.', true, true, 7),
  ('engelsk-9:short-stories', 'q09', 'flervalg', 'A character who changes and develops during the story is called', array['a flat character', 'a narrator', 'an antagonist', 'a round character']::text[], 3, 'Round characters are complex and often change, while flat characters stay the same.', true, true, 8),
  ('engelsk-9:short-stories', 'q10', 'flervalg', 'What is an open ending?', array['An ending that leaves questions unanswered', 'A happy ending', 'An ending where everyone dies', 'The first chapter']::text[], 0, 'An open ending invites the reader to think and interpret for themselves.', true, false, 9),
  ('engelsk-9:short-stories', 'm01', 'sant-usant', 'A good analysis retells the whole plot in detail.', array['Sant', 'Usant']::text[], 1, 'A short summary is enough. The analysis should explain how and why the story works.', false, true, 10),
  ('engelsk-9:short-stories', 'm02', 'sant-usant', 'The setting can help create atmosphere in a story.', array['Sant', 'Usant']::text[], 0, 'A dark, stormy night creates a very different mood from a sunny beach.', false, true, 11),
  ('engelsk-9:short-stories', 'm03', 'sant-usant', 'The antagonist is always a person.', array['Sant', 'Usant']::text[], 1, 'The antagonist can also be nature, society or another force.', false, true, 12),
  ('engelsk-9:short-stories', 'm04', 'sant-usant', 'Quotations can be used as evidence for your interpretation.', array['Sant', 'Usant']::text[], 0, 'Quotations show that your points are based on the text.', false, true, 13),
  ('engelsk-9:short-stories', 'm05', 'flervalg', 'A locked door appears several times in a story about a lonely boy. What might it be?', array['A symbol of isolation', 'An antagonist', 'The narrator', 'Foreshadowing of a party']::text[], 0, 'The locked door can stand for the boy being shut out or shutting others out.', false, true, 14),
  ('engelsk-9:short-stories', 'm06', 'flervalg', 'Which phrase is useful when you explain a quotation?', array['Once upon a time…', 'This suggests that…', 'The end.', 'Dear Sir or Madam,']::text[], 1, '“This suggests that…” helps you explain what the quotation shows.', false, true, 15),
  ('engelsk-9:short-stories', 'm07', 'flervalg', 'What is atmosphere?', array['The weather only', 'The title', 'The mood or feeling of a story', 'The main character''s name']::text[], 2, 'Atmosphere is the overall mood, created by setting, language and events.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-9:short-stories', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-9:short-stories', 's01', 'Explain what makes a work of fiction a short story. Include at least two typical features.', 'A short story is a brief work of fiction, often with few characters, one main setting and a limited time span. It can usually be read in one sitting.', array['Identifies it as a short work of fiction.', 'Includes at least two typical features, such as few characters, one main setting or a limited time span.']::text[], 0),
  ('engelsk-9:short-stories', 's02', 'Compare the protagonist and the antagonist in a story. What role does each have?', 'The protagonist is the main character. The antagonist is a character or force that works against the protagonist.', array['Identifies the protagonist as the main character.', 'Explains that the antagonist works against the protagonist.']::text[], 1),
  ('engelsk-9:short-stories', 's03', 'A character tries to cross a river during a storm, but the rising water blocks the way. Explain why this is an example of external conflict.', 'It is external conflict because the character struggles against nature. The problem comes from outside the character’s mind.', array['Identifies the struggle as being against nature or another outside force.', 'Explains that the conflict is external, not an inner struggle.']::text[], 2),
  ('engelsk-9:short-stories', 's04', 'A story takes place in a silent, empty school after dark. Explain how this setting could shape the atmosphere.', 'The setting could create an uneasy or lonely atmosphere. The darkness and emptiness make the school seem unsettling.', array['Names a suitable mood or feeling.', 'Connects that mood to details of the setting.']::text[], 3),
  ('engelsk-9:short-stories', 's05', 'Compare direct and indirect characterisation. How does the reader learn about a character in each type?', 'In direct characterisation, the narrator tells us what the character is like. In indirect characterisation, we learn from the character’s actions, words or thoughts, or from how others react to them.', array['Explains that direct characterisation tells the reader about the character.', 'Explains that indirect characterisation lets the reader infer traits from evidence such as actions, words or thoughts.']::text[], 4),
  ('engelsk-9:short-stories', 's06', 'In a story, a character keeps an old school badge because it reminds them of belonging to a group. Explain how the badge can work as a symbol.', 'The badge is a symbol because it stands for more than an object. It represents the character’s sense of belonging to the group.', array['Explains that the badge represents an idea or feeling beyond itself.', 'Connects its meaning to belonging to the group.']::text[], 5),
  ('engelsk-9:short-stories', 's07', 'Mia is afraid to speak at the start of a story, but becomes more confident after facing challenges. Ben is impatient throughout the story and does not change. Explain which character is round and which is flat, and why.', 'Mia is a round character because she is complex and changes. Ben is a flat character because he has few traits and does not develop.', array['Identifies Mia as round and connects this to her change or development.', 'Identifies Ben as flat and connects this to his lack of development.']::text[], 6),
  ('engelsk-9:short-stories', 's08', 'When analysing a story, a writer uses a quotation and then explains it. Explain why the explanation is important.', 'The quotation gives evidence for the writer’s interpretation. The explanation shows how that evidence supports the writer’s point.', array['Explains that a quotation provides evidence from the story.', 'Explains how the writer’s own explanation connects that evidence to an interpretation or point.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-9:formal-and-informal-writing', 'engelsk-9', 'formal-and-informal-writing', 'Formal and informal writing', 'How to adapt your English to purpose, receiver and situation – with rules for formal emails and letters, and the features of informal texts.', array[14, 5, 9]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-9:formal-and-informal-writing', '## Register
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-9:formal-and-informal-writing', 'Register', 'How formal or informal language is, adapted to the situation.', 0),
  ('engelsk-9:formal-and-informal-writing', 'Purpose, receiver, situation', 'Three questions that decide how formal a text should be.', 1),
  ('engelsk-9:formal-and-informal-writing', 'Contraction', 'A short form like I''m, don''t, can''t. Common in informal writing.', 2),
  ('engelsk-9:formal-and-informal-writing', 'Informal greeting', 'Hi, Hey, Hello Tom.', 3),
  ('engelsk-9:formal-and-informal-writing', 'Formal greeting, name known', 'Dear Mr Smith / Dear Ms Jones.', 4),
  ('engelsk-9:formal-and-informal-writing', 'Formal greeting, name unknown', 'Dear Sir or Madam.', 5),
  ('engelsk-9:formal-and-informal-writing', 'Yours sincerely', 'British formal ending after “Dear Mr Smith”.', 6),
  ('engelsk-9:formal-and-informal-writing', 'Yours faithfully', 'British formal ending after “Dear Sir or Madam”.', 7),
  ('engelsk-9:formal-and-informal-writing', 'Kind regards', 'A polite, common ending in emails.', 8),
  ('engelsk-9:formal-and-informal-writing', 'I would like to…', 'A polite formal phrase for saying what you want.', 9),
  ('engelsk-9:formal-and-informal-writing', 'I am writing to enquire about…', 'A formal opening for asking for information.', 10),
  ('engelsk-9:formal-and-informal-writing', 'I look forward to hearing from you.', 'A standard formal closing sentence.', 11),
  ('engelsk-9:formal-and-informal-writing', 'Application letter', 'A formal letter presenting yourself for a job or course.', 12),
  ('engelsk-9:formal-and-informal-writing', 'Letter of complaint', 'A formal letter that explains a problem and what you expect.', 13),
  ('engelsk-9:formal-and-informal-writing', 'Mixing registers', 'Using both formal and informal language in one text. Should be avoided.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-9:formal-and-informal-writing', 'q01', 'flervalg', 'Which greeting is best in an email to a company when you do not know the name?', array['Hey guys!', 'Dear Sir or Madam,', 'Hi there,', 'Yo,']::text[], 1, '“Dear Sir or Madam” is the standard formal greeting when you do not know the receiver''s name.', true, true, 0),
  ('engelsk-9:formal-and-informal-writing', 'q02', 'flervalg', 'Which sentence is formal?', array['I''m gonna need the info asap.', 'Send me the stuff!', 'Could you please send me more information?', 'Gimme the details.']::text[], 2, 'Polite phrases like “Could you please…” and no slang or contractions make it formal.', true, true, 1),
  ('engelsk-9:formal-and-informal-writing', 'q03', 'flervalg', 'In British English, which ending goes with “Dear Mr Smith”?', array['Yours sincerely', 'Yours faithfully', 'Love', 'See you']::text[], 0, 'When you know the name, the traditional British ending is “Yours sincerely”.', true, true, 2),
  ('engelsk-9:formal-and-informal-writing', 'q04', 'flervalg', 'What is a contraction?', array['A long word', 'A formal greeting', 'A type of letter', 'A short form like “don''t” or “I''m”']::text[], 3, 'Contractions combine two words. They are common in informal writing, but avoided in formal texts.', true, true, 3),
  ('engelsk-9:formal-and-informal-writing', 'q05', 'flervalg', 'Which phrase is a good formal opening?', array['What''s up?', 'I am writing to complain about the product I bought.', 'So, this thing broke.', 'Hey, just wanted to say…']::text[], 1, '“I am writing to…” clearly and politely states the purpose of a formal letter.', true, true, 4),
  ('engelsk-9:formal-and-informal-writing', 'q06', 'flervalg', 'What is register?', array['How formal or informal language is', 'A list of names', 'The length of a text', 'A spelling rule']::text[], 0, 'Register is about adapting language to purpose, receiver and situation.', true, true, 5),
  ('engelsk-9:formal-and-informal-writing', 'q07', 'flervalg', 'Which of these is a mistake in a formal letter?', array['Using full sentences', 'Using “I would like to”', 'Ending with “See ya!”', 'Stating the purpose early']::text[], 2, '“See ya!” is informal slang and does not fit in a formal letter.', true, true, 6),
  ('engelsk-9:formal-and-informal-writing', 'q08', 'flervalg', 'Which ending is common and polite in emails?', array['Bye bye', 'Kind regards', 'Later!', 'XOXO']::text[], 1, '“Kind regards” or “Best regards” are polite endings suitable for most emails.', true, false, 7),
  ('engelsk-9:formal-and-informal-writing', 'q09', 'flervalg', 'Which text is usually most informal?', array['A job application', 'A letter of complaint', 'An email to the principal', 'A text message to a friend']::text[], 3, 'Messages to friends are personal and informal.', true, false, 8),
  ('engelsk-9:formal-and-informal-writing', 'q10', 'flervalg', 'Which sentence closes a formal letter well?', array['I look forward to hearing from you.', 'Hope u reply soon!!', 'That''s it.', 'Whatever.']::text[], 0, '“I look forward to hearing from you” is a standard, polite formal closing.', true, true, 9),
  ('engelsk-9:formal-and-informal-writing', 'm01', 'sant-usant', 'Contractions like “can''t” are best avoided in formal letters.', array['Sant', 'Usant']::text[], 0, 'In formal writing we write the full forms: cannot, do not, I am.', false, true, 10),
  ('engelsk-9:formal-and-informal-writing', 'm02', 'sant-usant', '“Yours faithfully” is used when you know the receiver''s name.', array['Sant', 'Usant']::text[], 1, 'In British English, “Yours faithfully” goes with “Dear Sir or Madam”, when you do not know the name.', false, true, 11),
  ('engelsk-9:formal-and-informal-writing', 'm03', 'sant-usant', 'A blog post can be informal and personal.', array['Sant', 'Usant']::text[], 0, 'Many blog posts use a personal, informal style, but should still be clear.', false, true, 12),
  ('engelsk-9:formal-and-informal-writing', 'm04', 'sant-usant', 'Slang words make a job application more professional.', array['Sant', 'Usant']::text[], 1, 'Slang is informal and does not belong in a job application.', false, true, 13),
  ('engelsk-9:formal-and-informal-writing', 'm05', 'flervalg', 'Which phrase fits best in a letter of complaint?', array['This is totally lame!', 'I would be grateful if you could replace the product.', 'Fix it now or else!', 'Whatever, just refund it.']::text[], 1, 'A complaint should be polite but firm, and say clearly what you expect.', false, true, 14),
  ('engelsk-9:formal-and-informal-writing', 'm06', 'flervalg', 'What should you write to a teacher whose name is Anna Brown?', array['Hey Anna!', 'Yo teacher,', 'Dear Ms Brown,', 'Dear Sir or Madam,']::text[], 2, 'When you know the name, use “Dear” + title + surname.', false, true, 15),
  ('engelsk-9:formal-and-informal-writing', 'm07', 'flervalg', 'Which is an informal ending?', array['Take care!', 'Yours sincerely', 'Yours faithfully', 'Best regards']::text[], 0, '“Take care!” is friendly and informal.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-9:formal-and-informal-writing', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-9:formal-and-informal-writing', 's01', 'You are writing one message to a close friend and another to a company you do not know. Explain how the receivers and situations should affect the register you use.', 'A message to a close friend can be informal because you know the person well. A message to a company should be formal because it is an official situation with a receiver you do not know.', array['Explains why writing to a close friend suits an informal register.', 'Explains why writing to the company suits a formal register.']::text[], 0),
  ('engelsk-9:formal-and-informal-writing', 's02', 'Make this sentence suitable for a formal email by writing out the contractions: “I’m sorry, but I can’t send it today.” Explain why this change suits a formal email.', '“I am sorry, but I cannot send it today.” Formal writing usually avoids contractions, so the full forms are more suitable.', array['Changes both contractions to their full forms.', 'Explains that formal writing avoids contractions.']::text[], 1),
  ('engelsk-9:formal-and-informal-writing', 's03', 'Compare the purpose of an application letter with the purpose of a letter of complaint.', 'An application letter presents you and explains why you are suited for a job or course. A letter of complaint explains a problem and says what you expect to happen.', array['Explains that an application letter presents the writer and their suitability.', 'Explains that a complaint letter describes a problem and states an expectation.']::text[], 2),
  ('engelsk-9:formal-and-informal-writing', 's04', 'You need to write a letter to a company about a problem. Explain what information to include and how to make your expectation clear.', 'Explain the problem politely but firmly, giving the relevant details. Then clearly state what you expect the company to do next.', array['Says the letter should explain the problem and include relevant details.', 'Says it should state what the writer expects to happen.']::text[], 3),
  ('engelsk-9:formal-and-informal-writing', 's05', 'Compare a blog post with an article by describing the usual tone and organisation of each.', 'A blog post is often informal and personal, but it should still be clear and well organised. An article is usually more neutral and informative, and has a catchy headline.', array['Describes a blog post as often informal and personal while still clear or organised.', 'Describes an article as neutral and informative, or mentions its catchy headline.']::text[], 4),
  ('engelsk-9:formal-and-informal-writing', 's06', 'Write a short message to a close friend asking to meet. Include an informal greeting, a contraction and an informal ending. Explain why this register fits.', 'Hi! Do you want to meet later? I’m free after school. See you soon! This is informal because the receiver is a close friend.', array['Includes an informal greeting, a contraction and an informal ending.', 'Explains that an informal register fits because the message is for a close friend.']::text[], 5),
  ('engelsk-9:formal-and-informal-writing', 's07', 'Explain what an application letter should tell its reader about the writer and why.', 'An application letter should present the writer and explain why they are suited for the job or course. This helps the reader understand the writer’s reasons for applying.', array['Says the letter presents the writer.', 'Says it explains why the writer is suited for the job or course.']::text[], 6),
  ('engelsk-9:formal-and-informal-writing', 's08', 'You are revising an email for a formal receiver. Describe two things you should check to make sure the language stays formal throughout.', 'Check that the greeting and ending are formal, and replace slang with polite, precise words. Also check that the sentences are complete and well structured.', array['Names a relevant feature to check, such as the greeting, ending or vocabulary.', 'Names another relevant feature, such as avoiding slang or using complete, well-structured sentences.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-9:the-united-states', 'engelsk-9', 'the-united-states', 'The United States', 'How the USA is governed, key moments in American history, the civil rights movement, and diversity and ways of life in American society.', array[18, 17, 10]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-9:the-united-states', '## A large and varied country
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-9:the-united-states', '50 states', 'The USA consists of 50 states plus the capital, Washington, D.C.', 0),
  ('engelsk-9:the-united-states', 'Washington, D.C.', 'The capital of the USA, not part of any state.', 1),
  ('engelsk-9:the-united-states', 'Declaration of Independence', 'Declared the colonies'' independence from Britain in 1776.', 2),
  ('engelsk-9:the-united-states', 'Constitution', 'The basic law of the USA from 1787.', 3),
  ('engelsk-9:the-united-states', 'Civil War', 'War between the northern and southern states, 1861–1865, largely over slavery.', 4),
  ('engelsk-9:the-united-states', 'Segregation', 'Separation of people by race, for example in schools and on buses.', 5),
  ('engelsk-9:the-united-states', 'Civil rights movement', 'The struggle for equal rights for African Americans in the 1950s and 1960s.', 6),
  ('engelsk-9:the-united-states', 'Rosa Parks', 'Refused to give up her bus seat in 1955, a key moment in the civil rights movement.', 7),
  ('engelsk-9:the-united-states', 'Martin Luther King Jr.', 'Civil rights leader known for the “I Have a Dream” speech (1963).', 8),
  ('engelsk-9:the-united-states', 'Federal republic', 'A country where power is shared between a central government and states.', 9),
  ('engelsk-9:the-united-states', 'Checks and balances', 'The three branches of government control each other.', 10),
  ('engelsk-9:the-united-states', 'Congress', 'The Senate and the House of Representatives, which make federal laws.', 11),
  ('engelsk-9:the-united-states', 'Supreme Court', 'The highest court, which decides if laws follow the Constitution.', 12),
  ('engelsk-9:the-united-states', 'Melting pot / salad bowl', 'Two images of diversity: cultures blending together, or living side by side.', 13),
  ('engelsk-9:the-united-states', 'The American Dream', 'The idea that anyone can succeed through hard work.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-9:the-united-states', 'q01', 'flervalg', 'How many states does the USA have?', array['48', '52', '50', '13']::text[], 2, 'The USA has 50 states. The first thirteen were the original colonies.', true, true, 0),
  ('engelsk-9:the-united-states', 'q02', 'flervalg', 'What happened in 1776?', array['The Civil War ended', 'The colonies declared independence from Britain', 'Slavery was abolished', 'The first president was elected']::text[], 1, 'The Declaration of Independence was adopted on 4 July 1776.', true, true, 1),
  ('engelsk-9:the-united-states', 'q03', 'flervalg', 'What was the Civil War largely about?', array['Slavery', 'Independence from Britain', 'Oil', 'Taxes on tea']::text[], 0, 'The war between the North and the South (1861–1865) was largely about slavery.', true, true, 2),
  ('engelsk-9:the-united-states', 'q04', 'flervalg', 'Who gave the famous “I Have a Dream” speech?', array['Abraham Lincoln', 'Rosa Parks', 'Barack Obama', 'Martin Luther King Jr.']::text[], 3, 'Martin Luther King Jr. gave the speech in Washington in 1963.', true, true, 3),
  ('engelsk-9:the-united-states', 'q05', 'flervalg', 'Which body makes federal laws in the USA?', array['The Supreme Court', 'Congress', 'The President alone', 'The states']::text[], 1, 'Congress, consisting of the Senate and the House of Representatives, makes federal laws.', true, true, 4),
  ('engelsk-9:the-united-states', 'q06', 'flervalg', 'What does “checks and balances” mean?', array['The three branches of government control each other', 'The president decides everything', 'A way of paying taxes', 'A type of bank account']::text[], 0, 'The system prevents any one branch from getting too much power.', true, true, 5),
  ('engelsk-9:the-united-states', 'q07', 'flervalg', 'What was segregation?', array['A voting system', 'A type of school subject', 'Separation of people by race', 'A trade agreement']::text[], 2, 'Segregation meant separate schools, buses and public places for Black and white people, especially in the South.', true, true, 6),
  ('engelsk-9:the-united-states', 'q08', 'flervalg', 'What does the “salad bowl” image describe?', array['American food', 'Cultures blending completely into one', 'A political party', 'Cultures living side by side while keeping their identities']::text[], 3, 'In a salad bowl the ingredients are mixed, but each keeps its own character.', true, false, 7),
  ('engelsk-9:the-united-states', 'q09', 'flervalg', 'How often is the US President elected?', array['Every two years', 'Every four years', 'Every six years', 'For life']::text[], 1, 'Presidential elections are held every four years.', true, true, 8),
  ('engelsk-9:the-united-states', 'q10', 'flervalg', 'What is the American Dream?', array['The idea that anyone can succeed through hard work', 'A famous film', 'The national anthem', 'A law from 1787']::text[], 0, 'The American Dream is about opportunity and success, though many debate how real it is for everyone.', true, false, 9),
  ('engelsk-9:the-united-states', 'm01', 'sant-usant', 'Washington, D.C. is one of the 50 states.', array['Sant', 'Usant']::text[], 1, 'Washington, D.C. is a federal district and not part of any state.', false, true, 10),
  ('engelsk-9:the-united-states', 'm02', 'sant-usant', 'Rosa Parks refused to give up her seat on a bus in 1955.', array['Sant', 'Usant']::text[], 0, 'Her protest led to the Montgomery bus boycott.', false, true, 11),
  ('engelsk-9:the-united-states', 'm03', 'sant-usant', 'The states in the USA can make many of their own laws.', array['Sant', 'Usant']::text[], 0, 'In a federal system, states have their own laws on many issues.', false, true, 12),
  ('engelsk-9:the-united-states', 'm04', 'sant-usant', 'The USA has many political parties with equal power.', array['Sant', 'Usant']::text[], 1, 'American politics is dominated by two parties: the Democrats and the Republicans.', false, true, 13),
  ('engelsk-9:the-united-states', 'm05', 'flervalg', 'Which city is the biggest in the USA?', array['Washington, D.C.', 'Los Angeles', 'New York', 'Chicago']::text[], 2, 'New York is the largest city in the USA.', false, true, 14),
  ('engelsk-9:the-united-states', 'm06', 'flervalg', 'What does the Supreme Court do?', array['Leads the army', 'Decides whether laws follow the Constitution', 'Elects the president', 'Collects taxes']::text[], 1, 'The Supreme Court is the highest court and interprets the Constitution.', false, true, 15),
  ('engelsk-9:the-united-states', 'm07', 'flervalg', 'Who lived in North America before Europeans arrived?', array['Native American peoples', 'Nobody', 'The British', 'The Vikings only']::text[], 0, 'Many Native American peoples lived across the continent for thousands of years.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-9:the-united-states', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-9:the-united-states', 's01', 'Washington, D.C. is the capital of the USA, but it is not part of any state. Explain how this makes it different from a state such as California.', 'Washington, D.C. is the country''s capital, but it is not one of the 50 states. California is a state.', array['Explains that Washington, D.C. is the capital but is not a state.', 'Clearly distinguishes it from a state.']::text[], 0),
  ('engelsk-9:the-united-states', 's02', 'The Declaration of Independence was written in 1776, and the Constitution dates from 1787. Explain how their purposes are different.', 'The Declaration of Independence declared the colonies'' independence from Britain. The Constitution is the basic law that forms the basis of the American government.', array['Explains that the Declaration declared independence from Britain.', 'Explains that the Constitution is the basic law or basis of the government.']::text[], 1),
  ('engelsk-9:the-united-states', 's03', 'In a country, the central government shares power with states, and the states can make many of their own laws. Explain why this country could be called a federal republic.', 'It could be called a federal republic because power is shared between a central government and the states. The states also have the power to make many of their own laws.', array['Explains that power is shared between the central government and the states.', 'Connects the states'' ability to make laws with this shared power.']::text[], 2),
  ('engelsk-9:the-united-states', 's04', 'Slavery ended after the Civil War, but African Americans still faced discrimination, especially in the South. Explain why the civil rights movement was needed in the 1950s and 1960s, and what it fought for.', 'The movement was needed because African Americans still faced discrimination even after slavery ended. It fought for equal rights, using peaceful protests.', array['Explains that discrimination continued after slavery ended.', 'States that the movement fought for equal rights.']::text[], 3),
  ('engelsk-9:the-united-states', 's05', 'During the 1800s, the USA expanded westwards, often at the expense of Native Americans. Explain what this means for Native Americans.', 'As the country expanded westwards, Native Americans often lost out. The expansion happened at their expense.', array['Explains that westward expansion harmed Native Americans or happened at their expense.', 'Gives a clear implication of this, such as Native Americans losing out.']::text[], 4),
  ('engelsk-9:the-united-states', 's06', 'Imagine that people challenge a new law because they believe it goes against the Constitution. Which US institution decides whether the law follows the Constitution, and what does it decide?', 'The Supreme Court decides whether the law follows the Constitution. It considers whether the law is constitutional.', array['Identifies the Supreme Court.', 'Explains that it decides whether the law follows the Constitution.']::text[], 5),
  ('engelsk-9:the-united-states', 's07', 'A student claims that people in the USA have roots only in Europe. Correct this claim using two other regions people have come from, and explain what this shows about American society.', 'People have also come from Africa, Latin America and Asia. This shows that American society has diverse cultural backgrounds.', array['Names at least two other regions: Africa, Latin America or Asia.', 'Explains that this contributes to the USA''s cultural diversity.']::text[], 6),
  ('engelsk-9:the-united-states', 's08', 'The USA stretches from the Atlantic Ocean to the Pacific Ocean and also includes Alaska and Hawaii. Explain what these facts tell us about the country''s geographic extent.', 'The USA stretches across the country from the Atlantic to the Pacific. It also includes Alaska and Hawaii.', array['Identifies that the country stretches from the Atlantic to the Pacific.', 'Mentions that Alaska and Hawaii are also part of the USA.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-9:indigenous-peoples', 'engelsk-9', 'indigenous-peoples', 'Indigenous peoples', 'Indigenous peoples in the English-speaking world and in Norway – colonisation, assimilation, the fight for rights, and reconciliation today.', array[17, 18]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-9:indigenous-peoples', '## Who are indigenous peoples?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-9:indigenous-peoples', 'Indigenous peoples', 'Descendants of the people who lived in an area before colonisation or before today''s borders.', 0),
  ('engelsk-9:indigenous-peoples', 'First Nations', 'Indigenous peoples in Canada, alongside the Inuit and the Métis.', 1),
  ('engelsk-9:indigenous-peoples', 'Aboriginal and Torres Strait Islander peoples', 'The indigenous peoples of Australia.', 2),
  ('engelsk-9:indigenous-peoples', 'Māori', 'The indigenous people of New Zealand.', 3),
  ('engelsk-9:indigenous-peoples', 'Sámi', 'The indigenous people of Norway, Sweden, Finland and Russia.', 4),
  ('engelsk-9:indigenous-peoples', 'Colonisation', 'When a country takes control over another area and its people.', 5),
  ('engelsk-9:indigenous-peoples', 'Reservation', 'An area set aside for Native Americans, often after they lost their land.', 6),
  ('engelsk-9:indigenous-peoples', 'Assimilation', 'Forcing a minority to give up its culture and adopt the majority culture.', 7),
  ('engelsk-9:indigenous-peoples', 'Residential schools', 'Schools in Canada where indigenous children were forbidden to use their own languages.', 8),
  ('engelsk-9:indigenous-peoples', 'Stolen Generations', 'Aboriginal children taken from their families in Australia. Formal apology in 2008.', 9),
  ('engelsk-9:indigenous-peoples', 'Norwegianisation', 'Norwegian policy that pressured the Sámi and Kven to give up language and culture.', 10),
  ('engelsk-9:indigenous-peoples', 'Sámediggi', 'The Sámi Parliament in Norway, opened in 1989.', 11),
  ('engelsk-9:indigenous-peoples', 'Treaty of Waitangi', 'Agreement from 1840 between the British Crown and Māori chiefs.', 12),
  ('engelsk-9:indigenous-peoples', 'UN Declaration (2007)', 'The UN Declaration on the Rights of Indigenous Peoples.', 13),
  ('engelsk-9:indigenous-peoples', 'Reconciliation', 'Recognising past injustice and working for a fairer future.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-9:indigenous-peoples', 'q01', 'flervalg', 'What does “indigenous” mean?', array['Newly arrived', 'Descended from the original inhabitants of an area', 'Living in cities', 'Speaking English']::text[], 1, 'Indigenous peoples descend from those who lived in an area before colonisation or modern borders.', true, true, 0),
  ('engelsk-9:indigenous-peoples', 'q02', 'flervalg', 'Who are the Māori?', array['The indigenous people of Australia', 'The indigenous people of Canada', 'The indigenous people of New Zealand', 'A people in Scotland']::text[], 2, 'The Māori are the indigenous people of New Zealand.', true, true, 1),
  ('engelsk-9:indigenous-peoples', 'q03', 'flervalg', 'What is assimilation?', array['Forcing a minority to give up its culture and adopt the majority culture', 'Learning several languages', 'Moving to another country', 'Building new schools']::text[], 0, 'Assimilation policies tried to make indigenous peoples abandon their languages and traditions.', true, true, 2),
  ('engelsk-9:indigenous-peoples', 'q04', 'flervalg', 'What are the “Stolen Generations”?', array['Soldiers in the Civil War', 'British colonists', 'Sámi reindeer herders', 'Aboriginal children taken from their families in Australia']::text[], 3, 'For decades, many Aboriginal children were removed from their families. The government apologised in 2008.', true, true, 3),
  ('engelsk-9:indigenous-peoples', 'q05', 'flervalg', 'What was Norwegianisation?', array['A policy that pressured the Sámi and Kven to give up language and culture', 'A Norwegian sports event', 'A law about fishing', 'The Norwegian constitution']::text[], 0, 'Norwegianisation (fornorskning) lasted from the 1800s well into the 1900s.', true, true, 4),
  ('engelsk-9:indigenous-peoples', 'q06', 'flervalg', 'When did the Sámi Parliament in Norway open?', array['1814', '1905', '1989', '2023']::text[], 2, 'The Sámediggi opened in 1989.', true, true, 5),
  ('engelsk-9:indigenous-peoples', 'q07', 'flervalg', 'What were residential schools in Canada?', array['Holiday camps', 'Universities for indigenous leaders', 'Schools where indigenous children were forbidden to use their own languages', 'Schools only for adults']::text[], 2, 'The residential school system tried to separate children from their culture and language.', true, false, 6),
  ('engelsk-9:indigenous-peoples', 'q08', 'flervalg', 'What did the UN adopt in 2007?', array['A ban on reservations', 'The Declaration on the Rights of Indigenous Peoples', 'A new flag', 'The Treaty of Waitangi']::text[], 1, 'The declaration sets out rights to land, culture, language and self-determination.', true, true, 7),
  ('engelsk-9:indigenous-peoples', 'q09', 'flervalg', 'What is the Treaty of Waitangi?', array['A 1776 American document', 'A Canadian school law', 'A Sámi song', 'An 1840 agreement between the British Crown and Māori chiefs']::text[], 3, 'The treaty is still central to discussions about Māori rights in New Zealand.', true, false, 8),
  ('engelsk-9:indigenous-peoples', 'q10', 'flervalg', 'What does reconciliation mean in this context?', array['Recognising past injustice and working for a fairer future', 'Forgetting history', 'Moving people to new areas', 'Building more roads']::text[], 0, 'Reconciliation involves truth, recognition and concrete steps to improve the situation.', true, true, 9),
  ('engelsk-9:indigenous-peoples', 'm01', 'sant-usant', 'The Sámi live only in Norway.', array['Sant', 'Usant']::text[], 1, 'The Sámi live in Norway, Sweden, Finland and Russia.', false, true, 10),
  ('engelsk-9:indigenous-peoples', 'm02', 'sant-usant', 'Norway has also had a policy of assimilation towards indigenous people.', array['Sant', 'Usant']::text[], 0, 'The Norwegianisation policy pressured the Sámi and Kven to give up their languages.', false, true, 11),
  ('engelsk-9:indigenous-peoples', 'm03', 'sant-usant', 'Questions about indigenous land rights belong only to the past.', array['Sant', 'Usant']::text[], 1, 'Conflicts about land use, like wind power and reindeer herding, are still debated today.', false, true, 12),
  ('engelsk-9:indigenous-peoples', 'm04', 'sant-usant', 'Many indigenous peoples died from diseases brought by European settlers.', array['Sant', 'Usant']::text[], 0, 'Diseases like smallpox had devastating effects on populations without immunity.', false, true, 13),
  ('engelsk-9:indigenous-peoples', 'm05', 'flervalg', 'What did the Truth and Reconciliation Commission in Norway present in 2023?', array['A new flag', 'A report on injustice done to the Sámi and Kven/Norwegian Finns', 'A sports law', 'A new constitution']::text[], 1, 'The commission examined the consequences of Norwegianisation policy.', false, true, 14),
  ('engelsk-9:indigenous-peoples', 'm06', 'flervalg', 'What is a reservation in the USA?', array['A hotel booking', 'A national park', 'An area set aside for Native Americans', 'A military base']::text[], 2, 'Many Native Americans were moved to reservations after losing their lands.', false, true, 15),
  ('engelsk-9:indigenous-peoples', 'm07', 'flervalg', 'Which country made a formal apology to the Stolen Generations in 2008?', array['Australia', 'Canada', 'New Zealand', 'The USA']::text[], 0, 'The Australian government apologised in 2008.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-9:indigenous-peoples', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-9:indigenous-peoples', 's01', 'When Europeans colonised North America, Australia and New Zealand, indigenous peoples were harmed in several ways. Describe two different effects of colonisation on them.', 'Many indigenous peoples lost land or were forced away from their traditional areas. Many also died from diseases brought by settlers or were killed in wars.', array['Describes two distinct effects, such as land loss, forced removal, disease, deaths in war or broken treaties.']::text[], 0),
  ('engelsk-9:indigenous-peoples', 's02', 'Compare what happened to indigenous children in Canadian residential schools and to Aboriginal children in Australia.', 'In Canada, indigenous children were sent to residential schools where they were forbidden to speak their languages. In Australia, many Aboriginal children were taken from their families; they are known as the Stolen Generations.', array['Explains what happened to children in Canada, including the ban on their languages.', 'Explains that Aboriginal children in Australia were taken from their families.']::text[], 1),
  ('engelsk-9:indigenous-peoples', 's03', 'In Canada, indigenous children were forbidden to speak their languages at residential schools. In Norway, Sámi children were often not allowed to speak Sámi at school during Norwegianisation. What do these policies have in common, and what did they restrict?', 'Both policies restricted indigenous children from using their own languages at school. This put pressure on them to give up part of their culture.', array['Identifies that both policies restricted children’s use of their indigenous languages.', 'Connects the restrictions to pressure to give up language or culture.']::text[], 2),
  ('engelsk-9:indigenous-peoples', 's04', 'Today, the Sámi in Norway have the Sámediggi and Sámi languages have official status. Explain how these two facts relate to Sámi political representation and language rights.', 'The Sámediggi gives the Sámi their own parliament in Norway, while official status recognises Sámi languages. These are ways of supporting Sámi political representation and language rights.', array['Connects the Sámediggi to Sámi political representation.', 'Connects official language status to recognition or support for Sámi language rights.']::text[], 3),
  ('engelsk-9:indigenous-peoples', 's05', 'A student says that Inuit and Métis people are not Indigenous because the term “First Nations” is used for Indigenous peoples in Canada. Use what you know about Canada to correct the student.', 'First Nations, Inuit and Métis are all Indigenous peoples in Canada. First Nations is one group alongside the Inuit and the Métis.', array['States that Inuit and Métis are Indigenous peoples in Canada.', 'Clarifies that First Nations is not the only Indigenous group in Canada.']::text[], 4),
  ('engelsk-9:indigenous-peoples', 's06', 'A community’s language is being used less, but people begin learning it again, and its art and music gain new attention. Explain why this can be an example of cultural revival.', 'Learning the language again helps bring it back into use. New attention to the community’s art and music also shows renewed interest in its culture and traditions.', array['Explains that learning the language again helps renew or revive it.', 'Connects renewed attention to art or music with renewed interest in the community’s culture.']::text[], 5),
  ('engelsk-9:indigenous-peoples', 's07', 'A plan for wind power or mining could affect land used for reindeer herding. Explain why this could cause a conflict and what kind of rights are involved.', 'The project may compete with reindeer herding for the use of the land. The conflict concerns indigenous peoples’ rights to land and the use of their traditional areas.', array['Explains that development and reindeer herding may compete over land use.', 'Identifies indigenous peoples’ land rights as an issue.']::text[], 6),
  ('engelsk-9:indigenous-peoples', 's08', 'Compare the UN Declaration on the Rights of Indigenous Peoples with the Treaty of Waitangi. Who is connected to each one, and how are they different in scope?', 'The UN adopted the declaration on the rights of indigenous peoples in 2007, so it concerns indigenous peoples broadly. The Treaty of Waitangi is an agreement between the British Crown and Māori chiefs and is central to debates about Māori rights.', array['Identifies the UN Declaration as a declaration concerning the rights of indigenous peoples broadly.', 'Identifies the Treaty of Waitangi as an agreement between the British Crown and Māori chiefs.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-9:film-language', 'engelsk-fordypning-9', 'film-language', 'Film language', 'How films create meaning with camera shots, angles, sound, light and editing, how genres and narrative structure work, and how to write about a film.', array[4, 7]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-9:film-language', '## Film as a text
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-9:film-language', 'Establishing shot', 'A wide shot that shows where a scene takes place.', 0),
  ('engelsk-fordypning-9:film-language', 'Long shot', 'A shot showing a whole person and their surroundings.', 1),
  ('engelsk-fordypning-9:film-language', 'Medium shot', 'A shot showing a person from the waist up.', 2),
  ('engelsk-fordypning-9:film-language', 'Close-up', 'A shot of a face that shows emotions.', 3),
  ('engelsk-fordypning-9:film-language', 'Extreme close-up', 'A shot of a small detail, like an eye or a hand.', 4),
  ('engelsk-fordypning-9:film-language', 'Low angle', 'The camera looks up, making a character seem powerful.', 5),
  ('engelsk-fordypning-9:film-language', 'High angle', 'The camera looks down, making a character seem small or weak.', 6),
  ('engelsk-fordypning-9:film-language', 'Point-of-view shot', 'A shot that shows what a character sees.', 7),
  ('engelsk-fordypning-9:film-language', 'Diegetic sound', 'Sound the characters can hear, like dialogue or footsteps.', 8),
  ('engelsk-fordypning-9:film-language', 'Non-diegetic sound', 'Sound only the audience hears, like background music.', 9),
  ('engelsk-fordypning-9:film-language', 'Editing', 'How the shots are put together.', 10),
  ('engelsk-fordypning-9:film-language', 'Flashback', 'A scene that shows events from the past.', 11),
  ('engelsk-fordypning-9:film-language', 'Climax', 'The most exciting turning point of a story.', 12),
  ('engelsk-fordypning-9:film-language', 'Hero''s journey', 'A story pattern where the hero leaves home, faces challenges, changes and returns.', 13),
  ('engelsk-fordypning-9:film-language', 'Target audience', 'The group of people a film is made for.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-9:film-language', 'q01', 'flervalg', 'Which shot shows a character''s face and emotions?', array['Long shot', 'Extreme long shot', 'Close-up', 'Establishing shot']::text[], 2, 'Close-ups bring us near the character''s feelings.', true, true, 0),
  ('engelsk-fordypning-9:film-language', 'q02', 'flervalg', 'What effect does a low camera angle often have?', array['It makes the character seem powerful', 'It makes the character seem weak', 'It shows the landscape', 'It shows the past']::text[], 0, 'Looking up at someone makes them seem bigger and stronger.', true, true, 1),
  ('engelsk-fordypning-9:film-language', 'q03', 'flervalg', 'What is non-diegetic sound?', array['Dialogue between characters', 'Footsteps in the scene', 'A door slamming in the scene', 'Sound only the audience hears, like background music']::text[], 3, 'The characters cannot hear the background music.', true, true, 2),
  ('engelsk-fordypning-9:film-language', 'q04', 'flervalg', 'What do fast cuts usually create?', array['Calm', 'Speed and tension', 'Silence', 'A happy ending']::text[], 1, 'Fast cuts are common in action scenes.', true, true, 3),
  ('engelsk-fordypning-9:film-language', 'q05', 'flervalg', 'What is a flashback?', array['A camera angle', 'A type of light', 'The ending of a film', 'A scene showing events from the past']::text[], 3, 'Flashbacks can explain why characters act as they do.', true, true, 4),
  ('engelsk-fordypning-9:film-language', 'q06', 'flervalg', 'What is the climax of a story?', array['The introduction', 'The credits', 'The most exciting turning point', 'The first scene']::text[], 2, 'The conflict reaches its peak at the climax.', true, true, 5),
  ('engelsk-fordypning-9:film-language', 'q07', 'flervalg', 'What is an establishing shot?', array['A wide shot that shows where the story takes place', 'A close-up of a face', 'A shot of the credits', 'A sound effect']::text[], 0, 'It helps the audience understand the setting.', true, true, 6),
  ('engelsk-fordypning-9:film-language', 'q08', 'flervalg', 'What is the main purpose of a trailer?', array['To tell the whole story', 'To persuade people to watch the film', 'To show the credits', 'To replace the film']::text[], 1, 'A trailer is a form of advertising.', true, true, 7),
  ('engelsk-fordypning-9:film-language', 'q09', 'flervalg', 'Which genre often uses dark, shadowy lighting?', array['Romantic comedy', 'Animation for young children', 'Horror', 'Musical']::text[], 2, 'Darkness creates fear and uncertainty.', true, false, 8),
  ('engelsk-fordypning-9:film-language', 'q10', 'flervalg', 'What is the hero''s journey?', array['A pattern where the hero leaves home, faces challenges, changes and returns', 'A type of camera movement', 'A famous film studio', 'A film festival']::text[], 0, 'Many adventure and fantasy films follow this pattern.', true, false, 9),
  ('engelsk-fordypning-9:film-language', 'm01', 'sant-usant', 'A high camera angle can make a character seem small or weak.', array['Sant', 'Usant']::text[], 0, 'Looking down on someone makes them seem vulnerable.', false, true, 10),
  ('engelsk-fordypning-9:film-language', 'm02', 'sant-usant', 'Silence can never be used as an effect in films.', array['Sant', 'Usant']::text[], 1, 'Sudden silence can create strong tension.', false, true, 11),
  ('engelsk-fordypning-9:film-language', 'm03', 'sant-usant', 'Documentaries are films that mainly inform.', array['Sant', 'Usant']::text[], 0, 'Documentaries show real people and events.', false, true, 12),
  ('engelsk-fordypning-9:film-language', 'm04', 'sant-usant', 'All films are made for the same target audience.', array['Sant', 'Usant']::text[], 1, 'Films are made for different ages and interests.', false, true, 13),
  ('engelsk-fordypning-9:film-language', 'm05', 'flervalg', 'What is a point-of-view shot?', array['A shot from high above', 'A shot showing what a character sees', 'A shot of the audience', 'A shot with no sound']::text[], 1, 'It lets us see the world through the character''s eyes.', false, true, 14),
  ('engelsk-fordypning-9:film-language', 'm06', 'flervalg', 'Which of these is diegetic sound?', array['A character''s voice in a conversation', 'Background music added later', 'A narrator nobody in the film hears', 'The theme song over the credits']::text[], 0, 'The other characters in the scene can hear the voice.', false, true, 15),
  ('engelsk-fordypning-9:film-language', 'm07', 'flervalg', 'What does editing mean in film?', array['Writing the script', 'Choosing the actors', 'Putting the shots together', 'Selling tickets']::text[], 2, 'Editing decides the rhythm of a film.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-9:film-language', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-9:film-language', 's01', 'A film tells stories through pictures, sound and editing. Explain how this makes film more than just spoken or written words.', 'Pictures, sound and editing can all help tell the story and create meaning or feelings. Filmmakers choose how to use them carefully.', array['Explains that pictures, sound and editing help communicate the story.', 'Mentions that these choices can create meaning or feelings.']::text[], 0),
  ('engelsk-fordypning-9:film-language', 's02', 'Compare a long shot with a medium shot. What does each shot show?', 'A long shot shows a whole person and their surroundings. A medium shot shows a person from the waist up.', array['Describes what a long shot shows, including the person''s surroundings.', 'Describes that a medium shot shows a person from the waist up.']::text[], 1),
  ('engelsk-fordypning-9:film-language', 's03', 'The camera shows a scene from the exact viewpoint of a character. Name this type of shot and explain what the audience sees.', 'It is a point-of-view shot. The audience sees what the character sees.', array['Identifies the shot as a point-of-view shot.', 'Explains that the audience sees the scene from the character''s viewpoint.']::text[], 2),
  ('engelsk-fordypning-9:film-language', 's04', 'A camera is placed at a character''s eye level. What effect can this angle have on how the audience sees the character?', 'An eye-level angle feels neutral. It can make the audience feel that they meet the character as an equal.', array['Describes the angle as neutral.', 'Explains that it presents the character as an equal to the audience.']::text[], 3),
  ('engelsk-fordypning-9:film-language', 's05', 'A filmmaker wants a scene to feel calm. Explain how using slow cuts could help create this mood.', 'Slow cuts give a scene a calm feeling. The pace of the editing can affect the mood of the scene.', array['Links slow cuts with a calm mood or pace.', 'Explains that editing choices can affect the scene''s mood.']::text[], 4),
  ('engelsk-fordypning-9:film-language', 's06', 'In a typical narrative structure, what happens before the conflict, and what usually follows it?', 'The introduction presents the characters and setting before the conflict. Rising action usually follows the conflict.', array['Places the introduction of characters and setting before the conflict.', 'Places rising action after the conflict.']::text[], 5),
  ('engelsk-fordypning-9:film-language', 's07', 'Explain the difference between the purpose of a documentary and the purpose of a film trailer.', 'A documentary can be made to inform its audience. A trailer is made to persuade people to watch the film.', array['Explains that a documentary can inform.', 'Explains that a trailer aims to persuade people to watch the film.']::text[], 6),
  ('engelsk-fordypning-9:film-language', 's08', 'A student writes, “The film uses music and close-ups.” Explain what the student should add to make this a stronger film analysis.', 'The student should give examples of where the techniques are used and explain how they create meaning. This helps explain the effect of the filmmaker''s choices.', array['Says the student should give specific examples of the techniques in the film.', 'Says the student should explain how the techniques create meaning or an effect.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-9:storytelling-across-media', 'engelsk-fordypning-9', 'storytelling-across-media', 'Storytelling across media', 'How to present, tell and explain through different media, the elements of a good story, multimodal texts, and how to plan your own digital product.', array[2, 6]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-9:storytelling-across-media', '## Stories everywhere
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-9:storytelling-across-media', 'Medium', 'A way of communicating a story, like a book, film, podcast or game.', 0),
  ('engelsk-fordypning-9:storytelling-across-media', 'Narrate', 'To tell a story.', 1),
  ('engelsk-fordypning-9:storytelling-across-media', 'Protagonist', 'The main character, who usually wants something.', 2),
  ('engelsk-fordypning-9:storytelling-across-media', 'Setting', 'Where and when a story takes place.', 3),
  ('engelsk-fordypning-9:storytelling-across-media', 'Plot', 'What happens in a story.', 4),
  ('engelsk-fordypning-9:storytelling-across-media', 'Conflict', 'The main problem or struggle in a story.', 5),
  ('engelsk-fordypning-9:storytelling-across-media', 'First-person narrator', 'A narrator who tells the story as “I”.', 6),
  ('engelsk-fordypning-9:storytelling-across-media', 'Third-person narrator', 'A narrator who tells the story about “he”, “she” or “they”.', 7),
  ('engelsk-fordypning-9:storytelling-across-media', 'Show, don''t tell', 'Showing feelings through actions and details instead of naming them.', 8),
  ('engelsk-fordypning-9:storytelling-across-media', 'Multimodal text', 'A text that combines modes like words, pictures and sound.', 9),
  ('engelsk-fordypning-9:storytelling-across-media', 'Mode', 'A way of creating meaning: writing, speech, pictures, sound, movement or layout.', 10),
  ('engelsk-fordypning-9:storytelling-across-media', 'Layout', 'How colours, fonts and placement are arranged on a page or screen.', 11),
  ('engelsk-fordypning-9:storytelling-across-media', 'Panel and speech bubble', 'The frames in a comic and the bubbles that show what characters say.', 12),
  ('engelsk-fordypning-9:storytelling-across-media', 'Storyboard', 'A plan with sketches of what the audience will see and hear.', 13),
  ('engelsk-fordypning-9:storytelling-across-media', 'Hook', 'An opening that catches the audience''s attention.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-9:storytelling-across-media', 'q01', 'flervalg', 'What is a multimodal text?', array['A text with many chapters', 'A text that combines modes like words, pictures and sound', 'A text in many languages', 'A very long novel']::text[], 1, 'Comics and videos are typical multimodal texts.', true, true, 0),
  ('engelsk-fordypning-9:storytelling-across-media', 'q02', 'flervalg', 'Which sentence follows the “show, don''t tell” rule?', array['She was scared.', 'He was angry.', 'They were happy.', 'Her hands were shaking as she opened the door.']::text[], 3, 'The reader understands the fear from the details.', true, true, 1),
  ('engelsk-fordypning-9:storytelling-across-media', 'q03', 'flervalg', 'What is a protagonist?', array['The main character, who usually wants something', 'The villain', 'The narrator of a podcast', 'The setting']::text[], 0, 'The protagonist''s goal drives the story forward.', true, true, 2),
  ('engelsk-fordypning-9:storytelling-across-media', 'q04', 'flervalg', 'Which pronoun is typical of a first-person narrator?', array['She', 'They', 'I', 'He']::text[], 2, 'A first-person narrator tells the story from inside.', true, true, 3),
  ('engelsk-fordypning-9:storytelling-across-media', 'q05', 'flervalg', 'What is a storyboard?', array['A plan with sketches of what the audience will see and hear', 'A board game', 'A list of characters', 'The final version of a film']::text[], 0, 'Storyboards help you plan videos and comics.', true, true, 4),
  ('engelsk-fordypning-9:storytelling-across-media', 'q06', 'flervalg', 'What do podcasts mostly rely on?', array['Pictures', 'Panels', 'Layout', 'Voice, music and sound effects']::text[], 3, 'Podcasts create pictures in the listener''s mind through sound.', true, true, 5),
  ('engelsk-fordypning-9:storytelling-across-media', 'q07', 'flervalg', 'Why do short videos need a strong hook?', array['Because they are long', 'Because viewers decide in a few seconds whether to keep watching', 'Because they have no sound', 'Because they are for adults only']::text[], 1, 'Viewers scroll quickly past videos that do not grab them.', true, true, 6),
  ('engelsk-fordypning-9:storytelling-across-media', 'q08', 'flervalg', 'What is the setting of a story?', array['The main problem', 'The ending', 'Where and when the story takes place', 'The narrator']::text[], 2, 'The setting can also create mood.', true, true, 7),
  ('engelsk-fordypning-9:storytelling-across-media', 'q09', 'flervalg', 'What makes video games different from films as a storytelling medium?', array['They have no characters', 'The player can take part in the story and make choices', 'They have no sound', 'They are always shorter']::text[], 1, 'Interactivity is the special feature of games.', true, false, 8),
  ('engelsk-fordypning-9:storytelling-across-media', 'q10', 'flervalg', 'What does layout do in a multimodal text?', array['It adds music', 'It tells the plot', 'It records the voice', 'It guides the reader''s eye with colours, fonts and placement']::text[], 3, 'Good layout makes a text easy to read.', true, false, 9),
  ('engelsk-fordypning-9:storytelling-across-media', 'm01', 'sant-usant', 'The same story can be told in different media.', array['Sant', 'Usant']::text[], 0, 'Many books have been made into films, series and games.', false, true, 10),
  ('engelsk-fordypning-9:storytelling-across-media', 'm02', 'sant-usant', 'A comic is a multimodal text.', array['Sant', 'Usant']::text[], 0, 'It combines pictures, words and layout.', false, true, 11),
  ('engelsk-fordypning-9:storytelling-across-media', 'm03', 'sant-usant', 'Every story must be told in the first person.', array['Sant', 'Usant']::text[], 1, 'Stories can be told in the first or the third person.', false, true, 12),
  ('engelsk-fordypning-9:storytelling-across-media', 'm04', 'sant-usant', 'You can freely use any music you find online in your video.', array['Sant', 'Usant']::text[], 1, 'Most music is protected by copyright.', false, true, 13),
  ('engelsk-fordypning-9:storytelling-across-media', 'm05', 'flervalg', 'What is the conflict in a story?', array['The main problem or struggle', 'The title', 'The setting', 'The last page']::text[], 0, 'Without a conflict, there is little to drive the story.', false, true, 14),
  ('engelsk-fordypning-9:storytelling-across-media', 'm06', 'flervalg', 'What do comics use to show what characters say?', array['Captions only', 'Footnotes', 'Speech bubbles', 'Subtitles']::text[], 2, 'Thought bubbles show what characters think.', false, true, 15),
  ('engelsk-fordypning-9:storytelling-across-media', 'm07', 'flervalg', 'Which purpose fits a text that describes how something works?', array['Tell a story', 'Explain', 'Entertain only', 'Present a character']::text[], 1, 'Explaining texts answer how and why.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-9:storytelling-across-media', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-9:storytelling-across-media', 's01', 'Explain the difference between narrating a story and explaining how or why something happens.', 'To narrate is to tell a story about events. To explain is to show how or why something happens.', array['Explains that narrating tells a story or events.', 'Explains that explaining gives how or why something happens.']::text[], 0),
  ('engelsk-fordypning-9:storytelling-across-media', 's02', 'A protagonist wants to find a missing key, but it is locked inside a room. Explain how the protagonist’s goal and the conflict are connected.', 'The protagonist wants to find the key, which is the goal. The locked room is the conflict because it creates a problem that gets in the way.', array['Identifies finding the key as the protagonist’s goal.', 'Explains that the locked room is an obstacle or problem blocking the goal.']::text[], 1),
  ('engelsk-fordypning-9:storytelling-across-media', 's03', 'Compare how a comic and a podcast can tell a story. Name one technique used in each medium.', 'A comic uses panels, speech bubbles or captions to show the story. A podcast uses voice, music or sound effects to help listeners imagine it.', array['Names a relevant comic technique, such as panels, speech bubbles or captions.', 'Names a relevant podcast technique, such as voice, music or sound effects.']::text[], 2),
  ('engelsk-fordypning-9:storytelling-across-media', 's04', 'Rewrite “He was nervous” using “show, don’t tell”. Show his nervousness through an action or detail.', 'His fingers tapped the table as he waited for his name to be called.', array['Uses an action or detail instead of simply naming the feeling.', 'The action or detail clearly suggests nervousness.']::text[], 3),
  ('engelsk-fordypning-9:storytelling-across-media', 's05', 'In a comic, one panel shows a character reaching for a door handle, and the next shows the character inside the room. What can the reader imagine happened in the gap between the panels?', 'The reader can imagine the character opening the door and entering the room. The gap lets the reader fill in an event that is not shown.', array['Describes a plausible event between the two panels.', 'Explains that the reader imagines or fills in what is not shown.']::text[], 4),
  ('engelsk-fordypning-9:storytelling-across-media', 's06', 'A video scene shows a character walking alone through a dark place. Explain how a picture and music could work together to create a mood.', 'The dark picture can make the place look threatening, while tense music can make the scene feel frightening or suspenseful. Together they create a stronger mood.', array['Explains what the picture contributes to the mood or setting.', 'Explains how music contributes to the mood and how it works with the picture.']::text[], 5),
  ('engelsk-fordypning-9:storytelling-across-media', 's07', 'Compare a blog and a podcast as ways to tell a personal story. Give one feature of each that helps communicate the story.', 'A blog can use written text, pictures and links, often with a personal voice. A podcast can use a speaker’s voice, music or sound effects to communicate the story.', array['Gives a relevant blog feature, such as written text, pictures, links or a personal voice.', 'Gives a relevant podcast feature, such as voice, music or sound effects.']::text[], 6),
  ('engelsk-fordypning-9:storytelling-across-media', 's08', 'You are planning a digital story for younger students. What should you decide before creating it, and what could a storyboard help you plan?', 'First, decide the purpose and audience, then choose a medium that suits the story. A storyboard can plan what the audience will see and hear.', array['Mentions deciding the purpose and audience before creating the story.', 'Explains that a storyboard helps plan what the audience will see or hear.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-9:point-of-view-and-bias', 'engelsk-fordypning-9', 'point-of-view-and-bias', 'Point of view, sender and bias', 'How the sender and point of view shape a message, different types of narrators, bias, loaded words and framing, and how to tell fact from opinion.', array[8]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-9:point-of-view-and-bias', '## Who is behind the message?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Sender', 'The person or organisation behind a message.', 0),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Point of view', 'The position or perspective a message is told from.', 1),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Narrator', 'The voice that tells a story.', 2),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'First-person narrator', 'A narrator who is a character and tells the story as “I”.', 3),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Unreliable narrator', 'A narrator we cannot fully trust, who may misunderstand or lie.', 4),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Third-person limited', 'A narrator who follows one character closely.', 5),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Omniscient narrator', 'An all-knowing narrator who knows what everyone thinks and feels.', 6),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Target audience', 'The group a message is made for.', 7),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Bias', 'Presenting something in a one-sided or unfair way.', 8),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Loaded words', 'Words with strong positive or negative feelings.', 9),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Framing', 'How a story is presented, which affects how we understand it.', 10),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Fact', 'Something that can be checked and proved true or false.', 11),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Opinion', 'What someone thinks or feels about something.', 12),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Perspective', 'A way of seeing an issue, shaped by background and interests.', 13),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'Representation', 'How different groups are shown in texts and media.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q01', 'flervalg', 'What is bias?', array['Presenting something in a one-sided or unfair way', 'A type of narrator', 'A fact that can be checked', 'A news headline']::text[], 0, 'Bias can be both conscious and unconscious.', true, true, 0),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q02', 'flervalg', 'Which narrator knows what all the characters think and feel?', array['First-person narrator', 'Unreliable narrator', 'Omniscient narrator', 'Third-person limited narrator']::text[], 2, 'Omniscient means all-knowing.', true, true, 1),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q03', 'flervalg', 'Which sentence is an opinion?', array['London is the capital of the UK.', 'London is the best city in the world.', 'London has millions of inhabitants.', 'The Thames flows through London.']::text[], 1, '“The best” is a judgement that cannot be proved.', true, true, 2),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q04', 'flervalg', 'What are loaded words?', array['Very long words', 'Words from another language', 'Technical terms', 'Words with strong positive or negative feelings']::text[], 3, 'Loaded words try to influence how we feel.', true, true, 3),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q05', 'flervalg', 'What is framing?', array['Putting a picture in a frame', 'Writing a story in the first person', 'How a story is presented, which affects how we understand it', 'Checking facts']::text[], 2, 'The same facts can be framed in positive or negative ways.', true, true, 4),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q06', 'flervalg', 'Why can a first-person narrator be unreliable?', array['Because they can misunderstand or even lie', 'Because they know everything', 'Because they never speak', 'Because they are always the villain']::text[], 0, 'We only see the story through one person''s eyes.', true, true, 5),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q07', 'flervalg', 'Which question helps you think critically about a message?', array['How many words does it have?', 'What font is used?', 'Is it printed or digital?', 'What is included, and what is left out?']::text[], 3, 'What is missing can be as important as what is there.', true, true, 6),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q08', 'flervalg', 'Why should you look for different perspectives?', array['To make your text longer', 'To get a fuller and fairer picture', 'Because one source is always wrong', 'To confuse the reader']::text[], 1, 'Different voices show different sides of an issue.', true, true, 7),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q09', 'flervalg', 'What is a sender?', array['The person or organisation behind a message', 'The reader', 'The postman', 'The headline']::text[], 0, 'Knowing the sender helps you understand the purpose.', true, false, 8),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'q10', 'flervalg', 'Two headlines describe the same statistics very differently. What does this show?', array['That one of them is lying', 'That statistics are useless', 'That framing affects how we understand information', 'That headlines are always neutral']::text[], 2, 'Both headlines can be true, but they create different impressions.', true, false, 9),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'm01', 'sant-usant', 'Everyone has some bias.', array['Sant', 'Usant']::text[], 0, 'Our background and experiences shape how we see things.', false, true, 10),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'm02', 'sant-usant', 'A fact is something that cannot be checked.', array['Sant', 'Usant']::text[], 1, 'Facts can be checked and proved true or false.', false, true, 11),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'm03', 'sant-usant', 'Photos and camera angles can frame a news story.', array['Sant', 'Usant']::text[], 0, 'The choice of picture affects how we understand the story.', false, true, 12),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'm04', 'sant-usant', 'News articles never have a point of view.', array['Sant', 'Usant']::text[], 1, 'Choices about what to include always reflect a point of view.', false, true, 13),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'm05', 'flervalg', 'What does third-person limited mean?', array['The narrator follows one character closely', 'The narrator knows everything', 'The narrator is “I”', 'There is no narrator']::text[], 0, 'We know the thoughts of one character, but not the others.', false, true, 14),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'm06', 'flervalg', '“Freedom fighters” and “rebels” can describe the same group. What does this show?', array['Words are always neutral', 'Word choice can create different impressions', 'Both words mean soldiers', 'One word is a spelling mistake']::text[], 1, 'Loaded words reveal the sender''s point of view.', false, true, 15),
  ('engelsk-fordypning-9:point-of-view-and-bias', 'm07', 'flervalg', 'What is the target audience?', array['The sender', 'The purpose', 'The group a message is made for', 'The headline']::text[], 2, 'Messages are adapted to the audience they want to reach.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-9:point-of-view-and-bias', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-9:point-of-view-and-bias', 's01', 'Explain the difference between a sender and a narrator.', 'The sender is the person, organisation or company behind a message. The narrator is the voice that tells a story.', array['Explains that the sender is behind a message.', 'Explains that the narrator tells a story.']::text[], 0),
  ('engelsk-fordypning-9:point-of-view-and-bias', 's02', 'Compare a third-person limited narrator with an omniscient narrator. What does each narrator know?', 'A third-person limited narrator follows one character closely. An omniscient narrator knows what everyone thinks and feels.', array['Says that third-person limited follows one character closely.', 'Says that an omniscient narrator knows what everyone thinks and feels.']::text[], 1),
  ('engelsk-fordypning-9:point-of-view-and-bias', 's03', 'A company publishes an advert for its product that is made for teenagers. Identify the sender and the target audience, and explain a likely purpose of the advert.', 'The sender is the company, and the target audience is teenagers. The company likely wants to promote its product to them.', array['Identifies the company as the sender.', 'Identifies teenagers as the target audience and gives a suitable purpose, such as promoting the product.']::text[], 2),
  ('engelsk-fordypning-9:point-of-view-and-bias', 's04', 'Imagine two characters witness the same event, but each tells the story from their own point of view. Explain why their accounts might give different impressions of the event.', 'Each character may focus on different parts of the event and have different thoughts or feelings about it. This can make the same event seem different to the reader.', array['Explains that the characters may focus on different details or have different thoughts and feelings.', 'Connects these differences to the impressions readers get.']::text[], 3),
  ('engelsk-fordypning-9:point-of-view-and-bias', 's05', 'Two reports use different labels for the same group: one calls them “freedom fighters” and the other calls them “rebels”. Explain how the labels may affect the audience’s impression.', 'The labels have different positive or negative associations. They can lead the audience to view the group in different ways, even though both reports refer to the same group.', array['Recognises that the labels create different impressions or feelings.', 'Explains that this can influence how the audience views the group.']::text[], 4),
  ('engelsk-fordypning-9:point-of-view-and-bias', 's06', 'A news story uses a dramatic photo and puts some information before other information. Explain how these choices can affect the way readers understand the story.', 'The photo and the order of information can draw attention to certain details and create a particular impression. This is framing.', array['Explains that the photo or order of information shapes the impression readers get.', 'Connects the presentation choices to how readers understand the story.']::text[], 5),
  ('engelsk-fordypning-9:point-of-view-and-bias', 's07', 'Write one fact about London using the information that London is the capital of the UK. Then write one opinion about London and explain how the two statements differ.', 'London is the capital of the UK is a fact because it can be checked. Saying London is the best city in the world is an opinion because it expresses what someone thinks.', array['Gives the checkable fact that London is the capital of the UK.', 'Gives an opinion about London and explains that it expresses a personal view or feeling.']::text[], 6),
  ('engelsk-fordypning-9:point-of-view-and-bias', 's08', 'A media story often shows one group as leaders and another group only in one role. Explain what this shows about representation and how it may affect readers’ impressions of the groups.', 'Representation is how groups are shown in texts and media. Showing a group in only one role may give readers a limited impression of that group.', array['Explains that representation is how groups are shown.', 'Explains that showing a group in a narrow or repeated way can shape readers’ impressions.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-9:cultures-of-communication', 'engelsk-fordypning-9', 'cultures-of-communication', 'Cultures of communication', 'How culture shapes communication, direct and indirect styles, politeness and small talk, body language, online communities and different ways of thinking.', array[5, 1]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-9:cultures-of-communication', '## Communication is cultural
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-9:cultures-of-communication', 'Culture', 'The language, values, traditions and experiences a group shares.', 0),
  ('engelsk-fordypning-9:cultures-of-communication', 'Lingua franca', 'A shared language used by people with different first languages.', 1),
  ('engelsk-fordypning-9:cultures-of-communication', 'Direct communication', 'Saying exactly what you mean.', 2),
  ('engelsk-fordypning-9:cultures-of-communication', 'Indirect communication', 'Hinting and avoiding a direct no to protect relationships.', 3),
  ('engelsk-fordypning-9:cultures-of-communication', 'Small talk', 'Short, friendly conversation about everyday topics.', 4),
  ('engelsk-fordypning-9:cultures-of-communication', '“How are you?”', 'Usually a greeting. The expected answer is “Fine, thanks. And you?”', 5),
  ('engelsk-fordypning-9:cultures-of-communication', 'Politeness markers', 'Words like please, thank you, sorry and could you.', 6),
  ('engelsk-fordypning-9:cultures-of-communication', 'Body language', 'Gestures, facial expressions, posture and eye contact.', 7),
  ('engelsk-fordypning-9:cultures-of-communication', 'Personal space', 'The distance people like to keep between themselves and others.', 8),
  ('engelsk-fordypning-9:cultures-of-communication', 'Emojis', 'Small pictures that often replace body language online.', 9),
  ('engelsk-fordypning-9:cultures-of-communication', 'Online community', 'A group of people who meet and interact online.', 10),
  ('engelsk-fordypning-9:cultures-of-communication', 'Norms', 'Unwritten rules for how to behave in a group.', 11),
  ('engelsk-fordypning-9:cultures-of-communication', 'Toxic behaviour', 'Harassment and rude behaviour towards others, often online.', 12),
  ('engelsk-fordypning-9:cultures-of-communication', 'Individualism', 'A focus on the individual and personal freedom.', 13),
  ('engelsk-fordypning-9:cultures-of-communication', 'Collectivism', 'A focus on the group and on “us”.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-9:cultures-of-communication', 'q01', 'flervalg', 'What is a lingua franca?', array['A French dialect', 'A type of slang', 'An online community', 'A shared language used by people with different first languages']::text[], 3, 'English is the most widely used lingua franca today.', true, true, 0),
  ('engelsk-fordypning-9:cultures-of-communication', 'q02', 'flervalg', 'What might “That might be difficult” mean in an indirect culture?', array['Yes, definitely', 'No', 'I don''t understand', 'Let''s start now']::text[], 1, 'Indirect speakers often avoid saying no directly.', true, true, 1),
  ('engelsk-fordypning-9:cultures-of-communication', 'q03', 'flervalg', 'What is small talk?', array['A talk about a small topic in class', 'Speaking very quietly', 'Short, friendly conversation about everyday topics', 'An argument']::text[], 2, 'Small talk builds relationships.', true, true, 2),
  ('engelsk-fordypning-9:cultures-of-communication', 'q04', 'flervalg', 'How should you usually answer “How are you?” in English?', array['“Fine, thanks. And you?”', 'With a long story about your problems', 'By ignoring it', '“Why do you ask?”']::text[], 0, 'The question is usually a friendly greeting.', true, true, 3),
  ('engelsk-fordypning-9:cultures-of-communication', 'q05', 'flervalg', 'Why might Norwegians sometimes sound rude in English?', array['Because they speak too quietly', 'Because they sometimes skip polite words like please and could you', 'Because they use too much small talk', 'Because they are very indirect']::text[], 1, 'Norwegian is often more direct than English.', true, true, 4),
  ('engelsk-fordypning-9:cultures-of-communication', 'q06', 'flervalg', 'What is an online community?', array['A town with good internet', 'A news website', 'A single computer game', 'A group of people who meet and interact online']::text[], 3, 'Gaming clans and fan groups are examples.', true, true, 5),
  ('engelsk-fordypning-9:cultures-of-communication', 'q07', 'flervalg', 'What is toxic behaviour online?', array['Harassment and rude behaviour towards others', 'Sharing helpful tips', 'Winning a game', 'Using emojis']::text[], 0, 'Anonymity can make toxic behaviour more common.', true, true, 6),
  ('engelsk-fordypning-9:cultures-of-communication', 'q08', 'flervalg', 'What is collectivism?', array['A focus on the individual', 'Collecting things', 'A focus on the group and “us”', 'A political party']::text[], 2, 'In collectivist cultures, family and group needs often come first.', true, true, 7),
  ('engelsk-fordypning-9:cultures-of-communication', 'q09', 'flervalg', 'What can a thumbs-up mean in different cultures?', array['It means the same everywhere', 'It is always rude', 'It means stop', 'It is positive in many countries, but offensive in some']::text[], 3, 'Gestures do not always travel well between cultures.', true, false, 8),
  ('engelsk-fordypning-9:cultures-of-communication', 'q10', 'flervalg', 'What is a good way to avoid misunderstandings across cultures?', array['Always assume you are right', 'Ask if you are unsure what someone means', 'Rely on stereotypes', 'Avoid talking to people']::text[], 1, 'Asking shows interest and prevents mistakes.', true, false, 9),
  ('engelsk-fordypning-9:cultures-of-communication', 'm01', 'sant-usant', 'Everyone who speaks English communicates in exactly the same way.', array['Sant', 'Usant']::text[], 1, 'Culture shapes how people use English.', false, true, 10),
  ('engelsk-fordypning-9:cultures-of-communication', 'm02', 'sant-usant', 'Online communities often have their own norms and slang.', array['Sant', 'Usant']::text[], 0, 'New members learn these unwritten rules over time.', false, true, 11),
  ('engelsk-fordypning-9:cultures-of-communication', 'm03', 'sant-usant', 'Emojis can be understood differently by different people.', array['Sant', 'Usant']::text[], 0, 'The same emoji can be friendly to one person and sarcastic to another.', false, true, 12),
  ('engelsk-fordypning-9:cultures-of-communication', 'm04', 'sant-usant', 'Direct communication is always better than indirect communication.', array['Sant', 'Usant']::text[], 1, 'Both styles are normal in different cultures.', false, true, 13),
  ('engelsk-fordypning-9:cultures-of-communication', 'm05', 'flervalg', 'What is personal space?', array['Your bedroom', 'The distance people like to keep between themselves and others', 'Your online profile', 'A place in outer space']::text[], 1, 'The comfortable distance varies between cultures.', false, true, 14),
  ('engelsk-fordypning-9:cultures-of-communication', 'm06', 'flervalg', 'Which phrase is a polite way to disagree in British English?', array['You''re wrong.', 'No way!', 'I''m not sure that''s a good idea.', 'That''s stupid.']::text[], 2, 'Polite phrases soften disagreement.', false, true, 15),
  ('engelsk-fordypning-9:cultures-of-communication', 'm07', 'flervalg', 'What is a stereotype?', array['A simplified idea about a group of people', 'A type of music player', 'A friendly greeting', 'A cultural festival']::text[], 0, 'Stereotypes ignore that people are individuals.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-9:cultures-of-communication', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-9:cultures-of-communication', 's01', 'What is culture, and how can it shape the way people communicate?', 'Culture includes a group’s shared language, values, traditions and experiences. It can influence how people express themselves and understand others.', array['Explains that culture includes shared features such as language, values, traditions or experiences.', 'Connects culture to how people communicate or understand communication.']::text[], 0),
  ('engelsk-fordypning-9:cultures-of-communication', 's02', 'Compare direct and indirect communication. How does each style express disagreement?', 'In direct communication, people say exactly what they mean, so they may say clearly that they disagree. In indirect communication, people may hint at disagreement or avoid saying no to protect relationships.', array['Explains that direct communication states meaning clearly.', 'Explains that indirect communication hints or avoids a direct no, often to protect relationships.']::text[], 1),
  ('engelsk-fordypning-9:cultures-of-communication', 's03', 'You want a classmate to help you with homework. Write a polite request in English and explain what makes it polite.', 'Could you help me with my homework, please? “Could you” and “please” make the request sound more polite than a direct command.', array['Gives a clear request using a politeness marker such as “please” or “could you”.', 'Explains that the marker makes the request more polite or less direct.']::text[], 2),
  ('engelsk-fordypning-9:cultures-of-communication', 's04', 'In some cultures, long eye contact can show honesty, while in others it can seem rude. Explain why the same eye contact might be understood differently.', 'Eye contact is part of body language, and body language varies between cultures. People can therefore interpret the same gesture in different ways.', array['Identifies eye contact as body language or a non-verbal signal.', 'Explains that cultural differences can lead people to interpret it differently.']::text[], 3),
  ('engelsk-fordypning-9:cultures-of-communication', 's05', 'Emojis can replace body language in online messages, but their meaning can vary between people and cultures. Explain how this could lead to a misunderstanding.', 'A sender may use an emoji to show one meaning or feeling, while the receiver understands it differently. The message can then be misunderstood even though it includes an emoji.', array['Explains that people may understand the same emoji differently.', 'Connects this difference in meaning to a possible misunderstanding online.']::text[], 4),
  ('engelsk-fordypning-9:cultures-of-communication', 's06', 'A gaming clan has its own slang and unwritten rules. Explain what these rules are called and what they tell members.', 'The unwritten rules are called norms. They tell members how people are expected to behave in the group.', array['Identifies the unwritten rules as norms.', 'Explains that norms guide or describe how members should behave.']::text[], 5),
  ('engelsk-fordypning-9:cultures-of-communication', 's07', 'Online and offline communication can influence each other. Give one example of this and explain how the two are connected.', 'Slang from games or memes can spread into everyday speech. This shows that language used online can influence how people communicate offline.', array['Gives a relevant example, such as online slang spreading into everyday speech or an online friendship continuing offline.', 'Explains how the example connects online and offline communication.']::text[], 6),
  ('engelsk-fordypning-9:cultures-of-communication', 's08', 'One student thinks it is important to be punctual, while another is more relaxed about time. Explain how their different mindsets could cause a misunderstanding, and why neither view is automatically right or wrong.', 'They may expect different things about when someone should arrive, so one student could misunderstand the other’s behaviour. Different views about time are mindsets, and neither is automatically right or wrong.', array['Explains how different expectations about time could cause a misunderstanding.', 'Recognises that different mindsets are not automatically right or wrong.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-9:reliable-sources', 'engelsk-fordypning-9', 'reliable-sources', 'Reliable sources and honest use', 'How to evaluate and check sources, misinformation and disinformation, using AI critically, and how to quote, paraphrase and make a source list while respecting privacy and copyright.', array[11]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-9:reliable-sources', '## Why check your sources?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-9:reliable-sources', 'Reliable source', 'A source you can trust because of its expertise, evidence and purpose.', 0),
  ('engelsk-fordypning-9:reliable-sources', 'Misinformation', 'False information, often shared by people who believe it is true.', 1),
  ('engelsk-fordypning-9:reliable-sources', 'Disinformation', 'False information spread on purpose to deceive.', 2),
  ('engelsk-fordypning-9:reliable-sources', 'Sender', 'The person or organisation behind a source.', 3),
  ('engelsk-fordypning-9:reliable-sources', 'Up to date', 'Recent enough to still be correct.', 4),
  ('engelsk-fordypning-9:reliable-sources', 'Evidence', 'Facts, data and references that support a claim.', 5),
  ('engelsk-fordypning-9:reliable-sources', 'Lateral reading', 'Opening new tabs to see what other sources say about a topic and sender.', 6),
  ('engelsk-fordypning-9:reliable-sources', 'Reverse image search', 'Searching with a picture to find where else it has been published.', 7),
  ('engelsk-fordypning-9:reliable-sources', 'Fact-checking', 'Examining whether a claim is true.', 8),
  ('engelsk-fordypning-9:reliable-sources', 'AI that makes things up', 'AI chatbots can give wrong facts and invent sources.', 9),
  ('engelsk-fordypning-9:reliable-sources', 'Quote', 'Exact words from a source in quotation marks.', 10),
  ('engelsk-fordypning-9:reliable-sources', 'Paraphrase', 'Explaining an idea from a source in your own words.', 11),
  ('engelsk-fordypning-9:reliable-sources', 'Bibliography', 'A list of the sources you have used.', 12),
  ('engelsk-fordypning-9:reliable-sources', 'Plagiarism', 'Using someone''s words or ideas without giving credit.', 13),
  ('engelsk-fordypning-9:reliable-sources', 'Creative Commons', 'Licences that let creators allow others to use their work on certain conditions.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-9:reliable-sources', 'q01', 'flervalg', 'What is disinformation?', array['Information that is out of date', 'Information in another language', 'False information spread on purpose', 'Information from a university']::text[], 2, 'Disinformation is meant to deceive.', true, true, 0),
  ('engelsk-fordypning-9:reliable-sources', 'q02', 'flervalg', 'What is lateral reading?', array['Opening new tabs to see what other sources say about a topic and sender', 'Reading a text from right to left', 'Reading only headlines', 'Reading very fast']::text[], 0, 'Professional fact-checkers use this method.', true, true, 1),
  ('engelsk-fordypning-9:reliable-sources', 'q03', 'flervalg', 'What can a reverse image search reveal?', array['The photographer''s password', 'The price of the picture', 'How many people liked it', 'Whether a picture is old, edited or taken out of context']::text[], 3, 'Old pictures are often reused in fake news.', true, true, 2),
  ('engelsk-fordypning-9:reliable-sources', 'q04', 'flervalg', 'What is a paraphrase?', array['An exact quote', 'Explaining an idea in your own words', 'A list of sources', 'A picture']::text[], 1, 'You must still name the source when you paraphrase.', true, true, 3),
  ('engelsk-fordypning-9:reliable-sources', 'q05', 'flervalg', 'What should you remember about AI chatbots?', array['They are always correct', 'They never make mistakes about sources', 'They should replace all other sources', 'They can make things up and invent sources']::text[], 3, 'Always check important facts in reliable sources.', true, true, 4),
  ('engelsk-fordypning-9:reliable-sources', 'q06', 'flervalg', 'Why should you check when a source was published?', array['Old sources are always wrong', 'To know the author''s age', 'To make sure the information is still up to date', 'Because dates are required by law']::text[], 2, 'Facts like statistics can change over time.', true, true, 5),
  ('engelsk-fordypning-9:reliable-sources', 'q07', 'flervalg', 'How should you use Wikipedia?', array['As the only source', 'As a starting point, and check the references', 'Never', 'Only for pictures']::text[], 1, 'Anyone can edit Wikipedia, so check where the information comes from.', true, true, 6),
  ('engelsk-fordypning-9:reliable-sources', 'q08', 'flervalg', 'What should a source list include?', array['Author, title, website or publisher and dates', 'Only the website name', 'Only your opinion', 'Nothing']::text[], 0, 'The reader should be able to find the source.', true, true, 7),
  ('engelsk-fordypning-9:reliable-sources', 'q09', 'flervalg', 'Why should you be careful with content that makes you very angry?', array['Because anger is bad for you', 'Because it is always true', 'Because it may be designed to go viral', 'Because it is always old']::text[], 2, 'Strong emotions make people share without checking.', true, false, 8),
  ('engelsk-fordypning-9:reliable-sources', 'q10', 'flervalg', 'What must you do when you quote someone''s exact words?', array['Change some words', 'Hide the source', 'Translate them into Norwegian', 'Use quotation marks and name the source']::text[], 3, 'This shows clearly which words are not your own.', true, false, 9),
  ('engelsk-fordypning-9:reliable-sources', 'm01', 'sant-usant', 'All information on the internet is reliable.', array['Sant', 'Usant']::text[], 1, 'Anyone can publish online, so you must evaluate sources.', false, true, 10),
  ('engelsk-fordypning-9:reliable-sources', 'm02', 'sant-usant', 'Paraphrasing without naming the source can be plagiarism.', array['Sant', 'Usant']::text[], 0, 'The idea still belongs to someone else.', false, true, 11),
  ('engelsk-fordypning-9:reliable-sources', 'm03', 'sant-usant', 'A good source often gives evidence and references.', array['Sant', 'Usant']::text[], 0, 'References let you check where the information comes from.', false, true, 12),
  ('engelsk-fordypning-9:reliable-sources', 'm04', 'sant-usant', 'You can publish pictures of other people without asking them.', array['Sant', 'Usant']::text[], 1, 'You need consent to publish pictures of others.', false, true, 13),
  ('engelsk-fordypning-9:reliable-sources', 'm05', 'flervalg', 'What is misinformation?', array['A reliable news article', 'False information, often shared by people who believe it', 'An exact quote', 'A source list']::text[], 1, 'Misinformation is not necessarily spread on purpose.', false, true, 14),
  ('engelsk-fordypning-9:reliable-sources', 'm06', 'flervalg', 'Which question helps you evaluate a source?', array['Who made it, and why?', 'What colour is the website?', 'How many pictures does it have?', 'Is it long?']::text[], 0, 'The sender and purpose tell you a lot about reliability.', false, true, 15),
  ('engelsk-fordypning-9:reliable-sources', 'm07', 'flervalg', 'Which of these can you usually use in your project?', array['Any song from a streaming service', 'A photo from a stranger''s profile', 'A picture with a Creative Commons licence, following the terms', 'A clip from a new cinema film']::text[], 2, 'Creative Commons licences give permission on certain conditions.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-9:reliable-sources', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-9:reliable-sources', 's01', 'Explain in your own words what makes a source reliable.', 'A reliable source is one you can trust because the sender has relevant expertise, the source gives evidence, and its purpose is trustworthy.', array['Explains that a reliable source can be trusted.', 'Mentions relevant expertise, evidence and/or purpose as reasons for trust.']::text[], 0),
  ('engelsk-fordypning-9:reliable-sources', 's02', 'A university website gives evidence and names its experts. An anonymous blog makes the same claim but gives no evidence. Compare how reliable the two sources seem and explain why.', 'The university website seems more reliable because it identifies experts and gives evidence. The anonymous blog is harder to trust because its sender is unknown and it gives no evidence.', array['Says the university website seems more reliable, without claiming it must always be correct.', 'Uses the difference in expertise, sender or evidence to explain the comparison.']::text[], 1),
  ('engelsk-fordypning-9:reliable-sources', 's03', 'A website is trying to sell a product and makes a claim about it. Explain why the website’s purpose matters and what you should check before using the claim.', 'The website may present the claim to persuade people to buy the product. I should check what evidence it gives and compare the claim with other reliable sources.', array['Recognises that the purpose is to sell or persuade, which may affect how the claim is presented.', 'Says to check evidence and/or compare with other reliable sources.']::text[], 2),
  ('engelsk-fordypning-9:reliable-sources', 's04', 'Two reliable sources disagree about a claim you want to use in a presentation. Explain how you should decide what to include.', 'I should compare the evidence each source gives and check what other reliable sources say. I should not choose a claim just because it appears in one source.', array['Says to examine or compare the evidence behind the claims.', 'Says to check other reliable sources before deciding what to include.']::text[], 3),
  ('engelsk-fordypning-9:reliable-sources', 's05', 'A claim is spreading online, but you are not sure whether it is true. Explain how a fact-checking website could help you.', 'A fact-checking website examines whether a claim is true. It can help me check the claim before I share or use it.', array['Explains that fact-checking examines whether a claim is true.', 'Connects this check to deciding whether to use or share the claim.']::text[], 4),
  ('engelsk-fordypning-9:reliable-sources', 's06', 'You explain an idea from a website in your own words, but you do not name the website. Explain what is wrong and how to make your work honest.', 'This is plagiarism because I used someone else’s idea without giving credit. I should name the source even when I explain the idea in my own words.', array['Identifies using an idea without credit as plagiarism.', 'Says to name or credit the source, even when using your own words.']::text[], 5),
  ('engelsk-fordypning-9:reliable-sources', 's07', 'You want to post a picture of a friend online, but your friend has not agreed to it. What should you do, and why?', 'I should not post the picture without my friend’s consent. This respects their privacy.', array['Says not to publish the picture without consent.', 'Connects consent to respecting privacy.']::text[], 6),
  ('engelsk-fordypning-9:reliable-sources', 's08', 'You find a picture online and want to use it in a school presentation. Explain what you need to check and give one kind of picture you are allowed to use.', 'I need to check that I am allowed to use the picture. I can use my own picture or one with a Creative Commons licence, following its conditions.', array['Says to check that the picture is allowed to be used.', 'Gives an acceptable example, such as their own picture or one with a Creative Commons licence, and recognises that licence conditions apply.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-9:evolusjon', 'naturfag-9', 'evolusjon', 'Evolusjon', 'Hvordan Darwin og andre forskere kom fram til evolusjonsteorien, hvordan naturlig utvalg virker, og hvordan evolusjon forklarer det biologiske mangfoldet.', array[13, 5]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-9:evolusjon', '## Hva er evolusjon?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-9:evolusjon', 'Evolusjon', 'At arter endrer seg gradvis over mange generasjoner.', 0),
  ('naturfag-9:evolusjon', 'Charles Darwin', 'Britisk naturforsker som forklarte evolusjon med naturlig utvalg. Ga ut Artenes opprinnelse i 1859.', 1),
  ('naturfag-9:evolusjon', 'Alfred Russel Wallace', 'Kom uavhengig av Darwin fram til teorien om naturlig utvalg.', 2),
  ('naturfag-9:evolusjon', 'Lamarck', 'Mente at egenskaper man skaffer seg i livet, arves. Det stemmer ikke.', 3),
  ('naturfag-9:evolusjon', 'Galápagosfinkene', 'Finker med ulike nebb på ulike øyer, tilpasset ulik mat.', 4),
  ('naturfag-9:evolusjon', 'Naturlig utvalg', 'Individer med gunstige egenskaper overlever og får flere avkom.', 5),
  ('naturfag-9:evolusjon', 'Variasjon', 'At individer i en art er forskjellige.', 6),
  ('naturfag-9:evolusjon', 'Tilpasning', 'En egenskap som gjør en organisme bedre egnet til miljøet.', 7),
  ('naturfag-9:evolusjon', 'Gen', 'Et stykke DNA som styrer en egenskap.', 8),
  ('naturfag-9:evolusjon', 'Mutasjon', 'En tilfeldig endring i DNA-et.', 9),
  ('naturfag-9:evolusjon', 'Art', 'En gruppe organismer som kan få levedyktig avkom med hverandre.', 10),
  ('naturfag-9:evolusjon', 'Artsdannelse', 'Nye arter oppstår når grupper blir skilt og utvikler seg hver for seg.', 11),
  ('naturfag-9:evolusjon', 'Fossil', 'Rester eller avtrykk av organismer fra lenge siden, bevart i stein.', 12),
  ('naturfag-9:evolusjon', 'Homologe organer', 'Organer med samme grunnstruktur hos ulike arter, som arm, vinge og luffe.', 13),
  ('naturfag-9:evolusjon', 'Antibiotikaresistens', 'Bakterier som tåler antibiotika. Et eksempel på evolusjon i dag.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-9:evolusjon', 'q01', 'flervalg', 'Hva betyr evolusjon?', array['At et individ forandrer seg i løpet av livet', 'At arter endrer seg gradvis over mange generasjoner', 'At arter aldri endrer seg', 'At dyr lærer nye ting']::text[], 1, 'Evolusjon skjer i populasjoner over mange generasjoner, ikke hos enkeltindivider.', true, true, 0),
  ('naturfag-9:evolusjon', 'q02', 'flervalg', 'Hvilken bok ga Darwin ut i 1859?', array['Artenes opprinnelse', 'Sult', 'Principia', 'Et dukkehjem']::text[], 0, 'I Artenes opprinnelse presenterte Darwin teorien om naturlig utvalg.', true, true, 1),
  ('naturfag-9:evolusjon', 'q03', 'flervalg', 'Hva la Darwin merke til hos finkene på Galápagos?', array['At de var helt like', 'At de ikke kunne fly', 'At de hadde ulike nebb tilpasset ulik mat', 'At de levde i vann']::text[], 2, 'Nebbformene passet til maten på hver øy, noe som tydet på tilpasning.', true, true, 2),
  ('naturfag-9:evolusjon', 'q04', 'flervalg', 'Hva er naturlig utvalg?', array['At mennesker velger ut dyr', 'At alle individer overlever', 'At de sterkeste alltid vinner slåsskamper', 'At individer med gunstige egenskaper overlever og får flere avkom']::text[], 3, 'Egenskapene som gir flest levedyktige avkom, blir vanligere over tid.', true, true, 3),
  ('naturfag-9:evolusjon', 'q05', 'flervalg', 'Hva mente Lamarck som viste seg å være feil?', array['At arter kan endre seg', 'At egenskaper man skaffer seg i livet, går i arv', 'At fossiler finnes', 'At jorda er gammel']::text[], 1, 'En som trener muskler, får ikke barn med større muskler. Tillærte egenskaper arves ikke.', true, true, 4),
  ('naturfag-9:evolusjon', 'q06', 'flervalg', 'Hva er en mutasjon?', array['En tilfeldig endring i DNA', 'En ny art', 'Et fossil', 'En type celle']::text[], 0, 'Mutasjoner gir ny variasjon som naturlig utvalg kan virke på.', true, true, 5),
  ('naturfag-9:evolusjon', 'q07', 'flervalg', 'Hva er homologe organer?', array['Organer som har samme funksjon, men ulik bygning', 'Organer som bare finnes hos mennesker', 'Organer med samme grunnstruktur hos ulike arter', 'Organer som ikke lenger brukes']::text[], 2, 'Arm, vinge og luffe har samme benstruktur, noe som tyder på felles opphav.', true, true, 6),
  ('naturfag-9:evolusjon', 'q08', 'flervalg', 'Hvordan kan en ny art oppstå?', array['Ved at et individ bestemmer seg', 'Over én natt', 'Ved at dyr lærer nye triks', 'Ved at grupper blir skilt og utvikler seg hver for seg over lang tid']::text[], 3, 'Isolasjon gjør at gruppene utvikler seg ulikt til de ikke lenger kan få felles avkom.', true, false, 7),
  ('naturfag-9:evolusjon', 'q09', 'flervalg', 'Hvilket eksempel viser evolusjon i vår tid?', array['At barn blir høyere', 'At bakterier blir resistente mot antibiotika', 'At hunder lærer triks', 'At fjell eroderer']::text[], 1, 'Bakterier som tåler antibiotika, overlever og formerer seg, slik at resistensen sprer seg.', true, true, 8),
  ('naturfag-9:evolusjon', 'q10', 'flervalg', 'Hvem kom uavhengig av Darwin fram til teorien om naturlig utvalg?', array['Alfred Russel Wallace', 'Isaac Newton', 'Gregor Mendel', 'Alfred Wegener']::text[], 0, 'Wallace sendte Darwin et manuskript med de samme ideene, og de presenterte arbeidene sine sammen i 1858.', true, false, 9),
  ('naturfag-9:evolusjon', 'm01', 'sant-usant', 'Et enkelt individ kan utvikle seg til en ny art i løpet av livet sitt.', array['Sant', 'Usant']::text[], 1, 'Evolusjon skjer i populasjoner over mange generasjoner.', false, true, 10),
  ('naturfag-9:evolusjon', 'm02', 'sant-usant', 'Darwin visste ikke hvordan egenskaper ble arvet.', array['Sant', 'Usant']::text[], 0, 'Genetikken var ukjent for Darwin. Kunnskap om gener og DNA kom senere.', false, true, 11),
  ('naturfag-9:evolusjon', 'm03', 'sant-usant', 'De fleste mutasjoner gir store fordeler.', array['Sant', 'Usant']::text[], 1, 'De fleste mutasjoner er nøytrale eller skadelige. Bare noen få er gunstige.', false, true, 12),
  ('naturfag-9:evolusjon', 'm04', 'sant-usant', 'Nært beslektede arter har mer likt DNA enn fjernt beslektede arter.', array['Sant', 'Usant']::text[], 0, 'DNA-sammenligning bekrefter slektskapet mellom arter.', false, true, 13),
  ('naturfag-9:evolusjon', 'm05', 'flervalg', 'Hva kalles en egenskap som gjør en organisme bedre egnet til miljøet?', array['Mutasjon', 'Tilpasning', 'Fossil', 'Art']::text[], 1, 'En tilpasning øker sjansen for å overleve og få avkom.', false, true, 14),
  ('naturfag-9:evolusjon', 'm06', 'flervalg', 'Hva er et fossil?', array['En levende organisme', 'En type stein uten liv', 'Rester eller avtrykk av organismer fra lenge siden', 'En mutasjon']::text[], 2, 'Fossiler viser hvordan livet på jorda har vært og endret seg.', false, true, 15),
  ('naturfag-9:evolusjon', 'm07', 'flervalg', 'Hva gir variasjonen som naturlig utvalg virker på?', array['Mutasjoner og blanding av gener ved kjønnet formering', 'At dyr trener', 'Klimaet alene', 'Mat']::text[], 0, 'Nye genvarianter og nye kombinasjoner gir forskjeller mellom individer.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-9:evolusjon', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-9:evolusjon', 's01', 'Sammenlign hva Charles Darwin og Alfred Russel Wallace bidro med til forklaringen på evolusjon.', 'Darwin forklarte evolusjon med naturlig utvalg. Wallace kom uavhengig av Darwin fram til de samme ideene omtrent samtidig.', array['Beskriver Darwins forklaring med naturlig utvalg.', 'Får fram at Wallace kom uavhengig fram til de samme ideene.']::text[], 0),
  ('naturfag-9:evolusjon', 's02', 'Forklar hvorfor egenskaper som passer godt til miljøet, kan bli vanligere i en art over mange generasjoner.', 'Individer med slike egenskaper overlever oftere og får flere avkom. Hvis egenskapene arves, blir de vanligere i arten over generasjoner.', array['Knytter egenskapen til bedre overlevelse eller flere avkom.', 'Forklarer at egenskapen kan arves og derfor bli vanligere over generasjoner.']::text[], 1),
  ('naturfag-9:evolusjon', 's03', 'I en tenkt fugleart har noen individer nebb som passer bedre til maten som finnes i miljøet. Forklar hvordan nebbene kan endre seg i arten over mange generasjoner.', 'Fuglene med nebb som passer best til maten, kan overleve og få flere avkom. Hvis nebbegenskapen arves, blir den vanligere i arten over generasjoner.', array['Knytter nebb som passer til maten, til bedre overlevelse eller flere avkom.', 'Får fram at den arvelige egenskapen kan bli vanligere over generasjoner.']::text[], 2),
  ('naturfag-9:evolusjon', 's04', 'Sammenlign Lamarcks idé om arv med det vi i dag vet om hvordan egenskaper arves.', 'Lamarck mente at egenskaper man skaffer seg i løpet av livet, går i arv, men det stemmer ikke. I dag vet vi at egenskaper styres av gener i DNA.', array['Forklarer at Lamarck mente at egenskaper man skaffer seg i livet, arves.', 'Får fram at egenskaper styres av gener i DNA, og at Lamarcks idé var feil.']::text[], 3),
  ('naturfag-9:evolusjon', 's05', 'Hva kan fossiler fortelle oss om livet på jorda, og hva er et fossil?', 'Et fossil er rester eller avtrykk av organismer fra lenge siden, bevart i stein. Fossiler viser at livet har endret seg over tid.', array['Beskriver fossil som rester eller avtrykk av organismer fra lenge siden, bevart i stein.', 'Forklarer at fossiler viser endringer i livet over tid.']::text[], 4),
  ('naturfag-9:evolusjon', 's06', 'Armen til et menneske, vingen til en flaggermus og luffen til en hval har samme grunnleggende benstruktur. Hva kalles slike organer, og hva er felles ved dem?', 'De kalles homologe organer. De har samme grunnleggende struktur hos ulike arter.', array['Kaller organene homologe.', 'Får fram at de har samme grunnleggende struktur hos ulike arter.']::text[], 5),
  ('naturfag-9:evolusjon', 's07', 'Naturlig utvalg bygger på fire forhold: variasjon, arv, konkurranse og at individer med gunstige egenskaper får flere avkom. En elev har skrevet ned variasjon og arv. Hvor mange av de fire forholdene mangler? Vis regnestykket, og nevn forholdene som mangler.', 'Det mangler 2 forhold: konkurranse og at individer med gunstige egenskaper får flere avkom. Regnestykket er 4 − 2 = 2.', array['Viser regnestykket 4 − 2 = 2 eller tilsvarende.', 'Nevner både konkurranse og at individer med gunstige egenskaper får flere avkom.']::text[], 6),
  ('naturfag-9:evolusjon', 's08', 'Tre homologe organer som er nevnt, er menneskearmen, flaggermusvingen og hvalens luffe. Hvis du sammenligner organene to og to, hvor mange ulike par kan du lage? Vis kort hvordan du teller.', 'Det blir 3 ulike par: arm og vinge, arm og luffe, vinge og luffe.', array['Svarte 3 ulike par.', 'Viser tellingen ved å oppgi de tre parene eller en tilsvarende riktig utregning.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-9:biologisk-mangfold', 'naturfag-9', 'biologisk-mangfold', 'Biologisk mangfold og naturressurser', 'Hva biologisk mangfold er, hvorfor det er truet, dilemmaer knyttet til bruk av naturen, og hvordan samisk tradisjonell kunnskap kan bidra til bærekraftig forvaltning.', array[16, 17]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-9:biologisk-mangfold', '## Hva er biologisk mangfold?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-9:biologisk-mangfold', 'Biologisk mangfold', 'Variasjonen av liv: arter, genetisk variasjon og økosystemer.', 0),
  ('naturfag-9:biologisk-mangfold', 'Genetisk mangfold', 'Variasjonen innenfor en art, som gjør at arten kan tilpasse seg endringer.', 1),
  ('naturfag-9:biologisk-mangfold', 'Økosystemtjenester', 'Goder naturen gir oss, som mat, rent vann, pollinering og karbonlagring.', 2),
  ('naturfag-9:biologisk-mangfold', 'Pollinering', 'Overføring av pollen, ofte av insekter, som gjør at planter får frukt og frø.', 3),
  ('naturfag-9:biologisk-mangfold', 'Arealendringer', 'At natur bygges ned eller endres. Den største trusselen mot naturmangfoldet i Norge.', 4),
  ('naturfag-9:biologisk-mangfold', 'Overbeskatning', 'Å høste mer av en ressurs enn den tåler, som overfiske.', 5),
  ('naturfag-9:biologisk-mangfold', 'Rødlista', 'Oversikt over arter som står i fare for å dø ut. Lages av Artsdatabanken i Norge.', 6),
  ('naturfag-9:biologisk-mangfold', 'Fremmed art', 'En art som er spredt av mennesker til områder der den ikke hører hjemme.', 7),
  ('naturfag-9:biologisk-mangfold', 'Dilemma', 'En situasjon der ulike gode hensyn står mot hverandre.', 8),
  ('naturfag-9:biologisk-mangfold', 'Myr', 'Våtmark som lagrer mye karbon og demper flom.', 9),
  ('naturfag-9:biologisk-mangfold', 'Reindrift', 'Samisk næring med tamrein som flyttes mellom årstidsbeiter.', 10),
  ('naturfag-9:biologisk-mangfold', 'Tradisjonell kunnskap', 'Kunnskap om naturen utviklet og overlevert gjennom generasjoner.', 11),
  ('naturfag-9:biologisk-mangfold', 'Ikke ta mer enn naturen tåler', 'Prinsipp i tradisjonell samisk naturbruk.', 12),
  ('naturfag-9:biologisk-mangfold', 'Bærekraftig forvaltning', 'Å bruke naturen slik at også framtidige generasjoner kan dekke sine behov.', 13),
  ('naturfag-9:biologisk-mangfold', 'Verneområde', 'Område der naturen er beskyttet mot inngrep, som nasjonalparker.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-9:biologisk-mangfold', 'q01', 'flervalg', 'Hvilke tre nivåer omfatter biologisk mangfold?', array['Planter, dyr og sopp', 'Arter, genetisk variasjon og økosystemer', 'Land, luft og vann', 'Fjell, skog og hav']::text[], 1, 'Biologisk mangfold handler om artsmangfold, genetisk mangfold og mangfold av økosystemer.', true, true, 0),
  ('naturfag-9:biologisk-mangfold', 'q02', 'flervalg', 'Hva regnes som den største trusselen mot naturmangfoldet i Norge?', array['Vulkanutbrudd', 'Meteorer', 'Arealendringer', 'For mye regn']::text[], 2, 'Nedbygging av natur til veier, hytter og industri fjerner leveområder for mange arter.', true, true, 1),
  ('naturfag-9:biologisk-mangfold', 'q03', 'flervalg', 'Hva er en økosystemtjeneste?', array['Et gode naturen gir oss, som pollinering', 'En offentlig etat', 'En type skog', 'En turistbedrift']::text[], 0, 'Pollinering, rent vann og karbonlagring er eksempler på tjenester naturen gir.', true, true, 2),
  ('naturfag-9:biologisk-mangfold', 'q04', 'flervalg', 'Hva er Rødlista?', array['En liste over giftige planter', 'En liste over fremmede arter', 'En liste over nasjonalparker', 'En oversikt over arter som står i fare for å dø ut']::text[], 3, 'I Norge lager Artsdatabanken Rødlista.', true, true, 3),
  ('naturfag-9:biologisk-mangfold', 'q05', 'flervalg', 'Hvorfor er genetisk mangfold viktig?', array['Det gjør artene større', 'Det gjør at arten bedre kan tilpasse seg endringer', 'Det gir flere fargerike dyr', 'Det har ingen betydning']::text[], 1, 'Med stor variasjon er det større sjanse for at noen individer tåler nye forhold.', true, true, 4),
  ('naturfag-9:biologisk-mangfold', 'q06', 'flervalg', 'Hvilket er et dilemma knyttet til vindkraft?', array['Den gir fornybar energi, men kan ta store naturområder', 'Den forurenser med CO₂', 'Den virker bare om natta', 'Den er ulovlig']::text[], 0, 'Fornybar energi og naturvern er begge gode hensyn som kan stå mot hverandre.', true, true, 5),
  ('naturfag-9:biologisk-mangfold', 'q07', 'flervalg', 'Hvilket prinsipp står sentralt i tradisjonell samisk naturbruk?', array['Å ta mest mulig så raskt som mulig', 'Å bare bruke maskiner', 'Å ikke ta mer enn naturen tåler', 'Å unngå naturen']::text[], 2, 'Ressursene skal være der også for kommende generasjoner.', true, true, 6),
  ('naturfag-9:biologisk-mangfold', 'q08', 'flervalg', 'Hvordan kan samisk tradisjonell kunnskap bidra i dag?', array['Den erstatter all forskning', 'Den er ikke relevant', 'Den gjelder bare fortiden', 'Den kan utfylle forskning om for eksempel klima- og beiteendringer']::text[], 3, 'Erfaringsbasert kunnskap om snø, beite og vær gir verdifull informasjon om endringer i naturen.', true, true, 7),
  ('naturfag-9:biologisk-mangfold', 'q09', 'flervalg', 'Hva betyr overbeskatning?', array['For høye skatter', 'Å høste mer av en ressurs enn den tåler', 'Å verne for mye natur', 'Å plante for mange trær']::text[], 1, 'Overfiske er et eksempel: bestanden rekker ikke å fornye seg.', true, false, 8),
  ('naturfag-9:biologisk-mangfold', 'q10', 'flervalg', 'Hvorfor er myrer viktige?', array['De lagrer mye karbon og demper flom', 'De er gode byggetomter', 'De har ingen arter', 'De gir mye olje']::text[], 0, 'Myrer er viktige karbonlagre og holder på vann. Når de dreneres, slippes karbon ut.', true, false, 9),
  ('naturfag-9:biologisk-mangfold', 'm01', 'sant-usant', 'Arter forsvinner nå raskere enn det som er naturlig.', array['Sant', 'Usant']::text[], 0, 'Forskere mener menneskelig påvirkning har økt utryddelsestakten kraftig.', false, true, 10),
  ('naturfag-9:biologisk-mangfold', 'm02', 'sant-usant', 'Biologisk mangfold handler bare om hvor mange dyrearter som finnes.', array['Sant', 'Usant']::text[], 1, 'Det omfatter også planter, sopp, bakterier, genetisk variasjon og økosystemer.', false, true, 11),
  ('naturfag-9:biologisk-mangfold', 'm03', 'sant-usant', 'Et dilemma er en situasjon der ulike gode hensyn står mot hverandre.', array['Sant', 'Usant']::text[], 0, 'Derfor finnes det sjelden ett enkelt, riktig svar.', false, true, 12),
  ('naturfag-9:biologisk-mangfold', 'm04', 'sant-usant', 'Tradisjonell kunnskap er alltid ubrukelig i moderne forvaltning.', array['Sant', 'Usant']::text[], 1, 'Tradisjonell kunnskap kan utfylle naturvitenskapelige målinger.', false, true, 13),
  ('naturfag-9:biologisk-mangfold', 'm05', 'flervalg', 'Hva er et tiltak for bærekraftig forvaltning av fisk?', array['Fiskekvoter', 'Mer fiske', 'Dumping av avfall', 'Å tørke ut elver']::text[], 0, 'Kvoter begrenser fangsten slik at bestandene kan fornye seg.', false, true, 14),
  ('naturfag-9:biologisk-mangfold', 'm06', 'flervalg', 'Hvilken organisasjon lager Rødlista i Norge?', array['NRK', 'Artsdatabanken', 'Stortinget', 'Statens vegvesen']::text[], 1, 'Artsdatabanken vurderer risikoen for at arter dør ut.', false, true, 15),
  ('naturfag-9:biologisk-mangfold', 'm07', 'flervalg', 'Hva betyr bærekraftig bruk av naturen?', array['Å bruke opp ressursene raskt', 'Å aldri bruke naturen', 'Å dekke dagens behov uten å ødelegge for framtidige generasjoner', 'Å bare bygge i naturen']::text[], 2, 'Bærekraft handler om å tenke langsiktig.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-9:biologisk-mangfold', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-9:biologisk-mangfold', 's01', 'Forklar hva pollinering er, og hvordan det kan føre til at planter får frukt eller frø.', 'Pollinering er overføring av pollen, ofte ved hjelp av insekter. Det gjør at planter kan få frukt og frø.', array['Forklarer at pollinering er overføring av pollen.', 'Knytter pollinering til at planter får frukt eller frø.']::text[], 0),
  ('naturfag-9:biologisk-mangfold', 's02', 'Sammenlign arealendringer og overbeskatning som trusler mot naturen. Forklar hva som skjer i hvert tilfelle, og gi ett eksempel på hver.', 'Arealendringer betyr at natur bygges ned eller endres, for eksempel når myr bygges ut til hytter. Overbeskatning betyr at man høster mer av en ressurs enn den tåler, for eksempel ved overfiske.', array['Forklarer at arealendringer innebærer nedbygging eller endring av natur.', 'Forklarer at overbeskatning er for stort uttak, og gir et passende eksempel på truslene.']::text[], 1),
  ('naturfag-9:biologisk-mangfold', 's03', 'Insekter pollinerer avlinger. Forklar hvorfor dette er et eksempel på en økosystemtjeneste, og hva pollineringen kan hjelpe plantene med å lage.', 'Det er en økosystemtjeneste fordi naturen gir mennesker et gode. Pollineringen kan hjelpe avlingsplantene med å få frukt og frø.', array['Forklarer at økosystemtjenester er goder naturen gir oss.', 'Knytter pollinering til frukt eller frø.']::text[], 2),
  ('naturfag-9:biologisk-mangfold', 's04', 'En bygd ønsker å bygge nye hytter, men vil samtidig ta vare på naturen. Foreslå et tiltak fra bærekraftig forvaltning som kan passe, og forklar hvorfor det kan være et bedre valg for framtidige generasjoner.', 'Bygda kan bygge i områder som allerede er utbygd. Da kan behovet for hytter dekkes uten at nye naturområder bygges ned, og naturen kan også være tilgjengelig for framtidige generasjoner.', array['Foreslår å bygge i allerede utbygde områder eller et annet relevant tiltak for bærekraftig forvaltning.', 'Forklarer hvordan tiltaket kan ta vare på naturen for framtidige generasjoner.']::text[], 3),
  ('naturfag-9:biologisk-mangfold', 's05', 'Gruvedrift kan gi mineraler til teknologi og arbeidsplasser, men også forurense fjorder. Forklar hvorfor dette er et dilemma, og nevn hensyn som bør tas når saken vurderes.', 'Det er et dilemma fordi gruvedrift kan gi mineraler og arbeidsplasser, men samtidig skade naturen gjennom forurensning. Vurderingen bør ta hensyn til både mennesker, natur og framtidige generasjoner.', array['Får fram både en fordel og en mulig ulempe ved gruvedrift.', 'Nevner hensyn til mennesker, natur eller framtidige generasjoner.']::text[], 4),
  ('naturfag-9:biologisk-mangfold', 's06', 'Samiske ord for ulike typer snø og snøforhold kan gi kunnskap om naturen. Forklar hvordan slik kunnskap kan være nyttig for reindrift.', 'Kunnskap om snøforhold kan hjelpe reindriftsutøvere med å vurdere beite og ferdsel. Slik kunnskap er utviklet gjennom generasjoner og kan utfylle naturvitenskapelige målinger.', array['Knytter kunnskap om snø til vurdering av beite eller ferdsel for reindrift.', 'Får fram at kunnskapen er utviklet gjennom generasjoner eller kan utfylle målinger.']::text[], 5),
  ('naturfag-9:biologisk-mangfold', 's07', 'Naturen gir seks goder: mat, rent vann, ren luft, byggematerialer, medisiner og opplevelser. Myrer lagrer karbon og demper flom. Hvor mange goder og funksjoner er nevnt til sammen? Vis regnestykket.', 'Det er nevnt åtte til sammen: 6 + 2 = 8.', array['Viser at de to funksjonene til myra legges til de seks godene.', 'Kommer fram til 8.']::text[], 6),
  ('naturfag-9:biologisk-mangfold', 's08', 'Fem trusler er listet: arealendringer, overbeskatning, forurensning, klimaendringer og fremmede arter. Fire tiltak er listet: verneområder, fiskekvoter, restaurering av natur og bygging i allerede utbygde områder. Hvor mange flere trusler enn tiltak er listet? Vis regnestykket.', 'Det er én flere trussel enn tiltak: 5 − 4 = 1.', array['Regner ut forskjellen mellom fem trusler og fire tiltak.', 'Kommer fram til 1.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-9:energi', 'naturfag-9', 'energi', 'Energi: former, bevaring og kvalitet', 'Ulike energiformer, loven om energibevaring, energikvalitet og virkningsgrad, og hvordan energi omdannes, transporteres og lagres.', array[11]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-9:energi', '## Hva er energi?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-9:energi', 'Energi', 'Evnen til å utføre arbeid eller skape endring. Måles i joule (J).', 0),
  ('naturfag-9:energi', 'Kilowattime (kWh)', 'Enhet for energi. 1 kWh = 3,6 millioner joule.', 1),
  ('naturfag-9:energi', 'Effekt', 'Energi omdannet per sekund. Måles i watt (W).', 2),
  ('naturfag-9:energi', 'Bevegelsesenergi', 'Kinetisk energi – energien et legeme har fordi det beveger seg.', 3),
  ('naturfag-9:energi', 'Stillingsenergi', 'Potensiell energi – energi lagret fordi noe er høyt oppe.', 4),
  ('naturfag-9:energi', 'Kjemisk energi', 'Energi lagret i stoffer, som mat, ved og drivstoff.', 5),
  ('naturfag-9:energi', 'Strålingsenergi', 'Energi i lys og annen stråling, som fra sola.', 6),
  ('naturfag-9:energi', 'Loven om energibevaring', 'Energi kan ikke skapes eller forsvinne, bare omdannes.', 7),
  ('naturfag-9:energi', 'Energiomdanning i vannkraftverk', 'Stillingsenergi → bevegelsesenergi → elektrisk energi.', 8),
  ('naturfag-9:energi', 'Energikvalitet', 'Hvor nyttig energien er. Elektrisk energi har høy, lunken varme lav kvalitet.', 9),
  ('naturfag-9:energi', 'Virkningsgrad', 'Nyttig energi delt på tilført energi.', 10),
  ('naturfag-9:energi', 'LED-pære', 'Har høy virkningsgrad fordi det meste av energien blir lys.', 11),
  ('naturfag-9:energi', 'Glødepære', 'Har lav virkningsgrad fordi det meste blir varme.', 12),
  ('naturfag-9:energi', 'Energilagring', 'Vannmagasiner, batterier, drivstoff og varmtvannstanker.', 13),
  ('naturfag-9:energi', 'Å «bruke» energi', 'Å gjøre energi med høy kvalitet om til energi med lav kvalitet.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-9:energi', 'q01', 'flervalg', 'Hva sier loven om energibevaring?', array['Energi kan skapes av ingenting', 'Energi kan ikke skapes eller forsvinne, bare omdannes', 'Energi forsvinner når vi bruker den', 'Energi finnes bare i strøm']::text[], 1, 'Den totale mengden energi er konstant. Den bare skifter form.', true, true, 0),
  ('naturfag-9:energi', 'q02', 'flervalg', 'Hvilken energiform har vannet i et høyt fjellmagasin?', array['Bevegelsesenergi', 'Kjemisk energi', 'Stillingsenergi', 'Strålingsenergi']::text[], 2, 'Vannet har stillingsenergi, eller potensiell energi, fordi det ligger høyt.', true, true, 1),
  ('naturfag-9:energi', 'q03', 'flervalg', 'Hvilken energiform har høyest kvalitet?', array['Elektrisk energi', 'Lunkent vann', 'Varme i lufta i et rom', 'Varme fra en motor som er avkjølt']::text[], 0, 'Elektrisk energi kan lett gjøres om til mange andre former og har derfor høy kvalitet.', true, true, 2),
  ('naturfag-9:energi', 'q04', 'flervalg', 'En lyspære får 100 J og gir 20 J lys. Hva er virkningsgraden?', array['80 %', '5 %', '100 %', '20 %']::text[], 3, 'Virkningsgrad = nyttig / tilført = 20 / 100 = 0,20 = 20 %.', true, true, 3),
  ('naturfag-9:energi', 'q05', 'flervalg', 'Hva blir resten av energien i en glødepære til?', array['Den forsvinner', 'Varme', 'Kjemisk energi', 'Stillingsenergi']::text[], 1, 'Energien forsvinner ikke. Det meste blir til varme med lav kvalitet.', true, true, 4),
  ('naturfag-9:energi', 'q06', 'flervalg', 'En ovn på 2000 W står på i 3 timer. Hvor mye energi bruker den?', array['6 kWh', '2 kWh', '600 kWh', '0,6 kWh']::text[], 0, '2000 W = 2 kW. 2 kW · 3 h = 6 kWh.', true, true, 5),
  ('naturfag-9:energi', 'q07', 'flervalg', 'Hvilken energiomdanning skjer i et vannkraftverk?', array['Kjemisk → elektrisk', 'Strålingsenergi → varme', 'Stillingsenergi → bevegelsesenergi → elektrisk energi', 'Elektrisk → stillingsenergi']::text[], 2, 'Fallende vann driver turbinen, og generatoren lager strøm.', true, true, 6),
  ('naturfag-9:energi', 'q08', 'flervalg', 'Hva måles effekt i?', array['Joule', 'Kilowattimer', 'Newton', 'Watt']::text[], 3, 'Effekt er energi per tid og måles i watt. 1 W = 1 J per sekund.', true, true, 7),
  ('naturfag-9:energi', 'q09', 'flervalg', 'Hvorfor blir energilagring viktigere med mer sol- og vindkraft?', array['Fordi sol og vind varierer med vær og tid', 'Fordi sol og vind gir for mye kjemisk energi', 'Fordi batterier er gratis', 'Fordi sol og vind ikke gir strøm']::text[], 0, 'Energien må kunne lagres fra perioder med mye produksjon til perioder med lite.', true, false, 8),
  ('naturfag-9:energi', 'q10', 'flervalg', 'Hvilken energiform er lagret i mat?', array['Stillingsenergi', 'Kjemisk energi', 'Strålingsenergi', 'Kjerneenergi']::text[], 1, 'Maten inneholder kjemisk energi som kroppen frigjør ved celleånding.', true, false, 9),
  ('naturfag-9:energi', 'm01', 'sant-usant', 'Energi forsvinner når en bil bremser.', array['Sant', 'Usant']::text[], 1, 'Bevegelsesenergien blir til varme i bremsene. Den forsvinner ikke.', false, true, 10),
  ('naturfag-9:energi', 'm02', 'sant-usant', 'Varme ved lav temperatur har lav energikvalitet.', array['Sant', 'Usant']::text[], 0, 'Slik varme er spredt og vanskelig å gjøre om til noe nyttig.', false, true, 11),
  ('naturfag-9:energi', 'm03', 'sant-usant', 'En LED-pære har høyere virkningsgrad enn en glødepære.', array['Sant', 'Usant']::text[], 0, 'LED-pæra gjør mer av strømmen om til lys og mindre til varme.', false, true, 12),
  ('naturfag-9:energi', 'm04', 'sant-usant', '1 kWh er det samme som 1 joule.', array['Sant', 'Usant']::text[], 1, '1 kWh = 3,6 millioner joule.', false, true, 13),
  ('naturfag-9:energi', 'm05', 'flervalg', 'Hvilken energiform har en syklist i fart?', array['Kjerneenergi', 'Stillingsenergi', 'Bevegelsesenergi', 'Strålingsenergi']::text[], 2, 'Alt som beveger seg, har bevegelsesenergi (kinetisk energi).', false, true, 14),
  ('naturfag-9:energi', 'm06', 'flervalg', 'Hvor lagres energi i et batteri?', array['Som kjemisk energi', 'Som stillingsenergi', 'Som lys', 'Som lyd']::text[], 0, 'Batterier lagrer kjemisk energi som omdannes til elektrisk energi.', false, true, 15),
  ('naturfag-9:energi', 'm07', 'flervalg', 'Hva er virkningsgraden hvis 900 J av 1000 J blir nyttig energi?', array['10 %', '90 %', '9 %', '100 %']::text[], 1, '900 / 1000 = 0,90 = 90 %.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-9:energi', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-9:energi', 's01', 'Forklar hva energi er, og gi ett eksempel på en endring energi kan skape.', 'Energi er evnen til å utføre arbeid eller skape endring. For eksempel kan energi få noe til å bevege seg, bli varmere eller lyse.', array['Forklarer at energi kan utføre arbeid eller skape endring.', 'Gir et faglig passende eksempel på en endring energi kan skape.']::text[], 0),
  ('naturfag-9:energi', 's02', 'En ball ruller bortover gulvet, mens en bok ligger høyt på en hylle. Sammenlign energien de har, og forklar hvorfor de har disse energiformene.', 'Ballen har bevegelsesenergi fordi den beveger seg. Boka har stillingsenergi fordi den er høyt oppe.', array['Knytter bevegelsesenergi til at ballen beveger seg.', 'Knytter stillingsenergi til at boka er høyt oppe.']::text[], 1),
  ('naturfag-9:energi', 's03', 'En elektrisk motor får elektrisk energi, setter en gjenstand i bevegelse og avgir også varme. Forklar hva som skjer med energien.', 'Den elektriske energien omdannes til bevegelsesenergi og varmeenergi. Energien forsvinner ikke, men blir omdannet til andre former.', array['Beskriver at elektrisk energi omdannes til bevegelsesenergi og varme.', 'Forklarer at energien ikke forsvinner, men omdannes.']::text[], 2),
  ('naturfag-9:energi', 's04', 'Sammenlign elektrisk energi med varme ved lav temperatur. Hvorfor er den ene energiformen mer nyttig enn den andre?', 'Elektrisk energi har høy kvalitet fordi den lett kan omdannes til mange andre energiformer. Varme ved lav temperatur har lav kvalitet fordi den sprer seg og er vanskelig å bruke til noe.', array['Forklarer at elektrisk energi er lett å omdanne til mange former.', 'Forklarer at varme ved lav temperatur sprer seg og er vanskeligere å utnytte.']::text[], 3),
  ('naturfag-9:energi', 's05', 'Sammenlign virkningsgraden til en LED-pære og en gammeldags glødepære. Forklar hva som er forskjellen på hvor energien blir av.', 'LED-pæren har høy virkningsgrad fordi det meste av energien blir lys. Glødepæren har lav virkningsgrad fordi det meste blir varme.', array['Forklarer at det meste av energien i LED-pæren blir lys.', 'Forklarer at det meste av energien i glødepæren blir varme, og knytter dette til lav virkningsgrad.']::text[], 4),
  ('naturfag-9:energi', 's06', 'Gjør om 2 kWh til joule. Vis det viktigste regnetrinnet.', '2 kWh = 2 × 3,6 millioner J = 7,2 millioner J.', array['Bruker at 1 kWh er 3,6 millioner joule.', 'Får svaret 7,2 millioner joule.']::text[], 5),
  ('naturfag-9:energi', 's07', 'Et apparat omdanner 900 J energi på 3 sekunder. Hva er effekten i watt? Vis det viktigste regnetrinnet.', 'Effekt = energi per sekund, så 900 J ÷ 3 s = 300 W.', array['Deler energien på tiden.', 'Får svaret 300 W.']::text[], 6),
  ('naturfag-9:energi', 's08', 'Sammenlign hvordan energi lagres i et batteri og i et vannmagasin. Hvilken energiform er lagret i hvert av dem?', 'I et batteri er energi lagret som kjemisk energi. I et vannmagasin er energi lagret som stillingsenergi fordi vannet er høyt oppe.', array['Knytter batteriet til kjemisk energi.', 'Knytter vannmagasinet til stillingsenergi fordi vannet er høyt oppe.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-9:energi-og-miljo', 'naturfag-9', 'energi-og-miljo', 'Energiproduksjon og miljø', 'Fornybare og ikke-fornybare energikilder, hvordan de påvirker miljøet lokalt og globalt, og hvordan vi kan bruke energi smartere.', array[12, 11]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-9:energi-og-miljo', '## Energikilder
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-9:energi-og-miljo', 'Ikke-fornybar energikilde', 'Brukes opp og fornyes ikke i menneskelig tidsperspektiv: kull, olje, gass, uran.', 0),
  ('naturfag-9:energi-og-miljo', 'Fornybar energikilde', 'Fornyes hele tiden: vann, vind, sol, bioenergi, bølger og jordvarme.', 1),
  ('naturfag-9:energi-og-miljo', 'Fossile brensler', 'Kull, olje og gass. Gir CO₂-utslipp når de brennes.', 2),
  ('naturfag-9:energi-og-miljo', 'Vannkraft', 'Gir nesten all strømmen i Norge. Krever dammer og regulerte elver.', 3),
  ('naturfag-9:energi-og-miljo', 'Klimagass', 'Gass som forsterker drivhuseffekten, som CO₂ og metan.', 4),
  ('naturfag-9:energi-og-miljo', 'Global oppvarming', 'Økningen i jordas gjennomsnittstemperatur, forsterket av klimagassutslipp.', 5),
  ('naturfag-9:energi-og-miljo', 'Sur nedbør', 'Nedbør gjort sur av svovel- og nitrogenforbindelser fra forbrenning.', 6),
  ('naturfag-9:energi-og-miljo', 'Vindkraft – ulemper', 'Støy, synlige turbiner, arealbruk, fugler og reinbeite.', 7),
  ('naturfag-9:energi-og-miljo', 'Kjernekraft', 'Gir lite CO₂, men radioaktivt avfall som må lagres i svært lang tid.', 8),
  ('naturfag-9:energi-og-miljo', 'Bioenergi', 'Energi fra biologisk materiale, som ved og biogass.', 9),
  ('naturfag-9:energi-og-miljo', 'Energieffektivisering', 'Å få samme nytte med mindre energi.', 10),
  ('naturfag-9:energi-og-miljo', 'Varmepumpe', 'Henter varme fra luft, jord eller vann og gir mer varme enn strømmen den bruker.', 11),
  ('naturfag-9:energi-og-miljo', 'Elbil', 'Har høyere virkningsgrad enn bensinbil og ingen utslipp fra eksosrør.', 12),
  ('naturfag-9:energi-og-miljo', 'Hydrogen', 'Mulig energibærer for tungtransport og industri i framtida.', 13),
  ('naturfag-9:energi-og-miljo', 'Ingen energikilde uten kostnad', 'Alle energikilder har ulemper for miljøet, lokalt eller globalt.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-9:energi-og-miljo', 'q01', 'flervalg', 'Hvilken energikilde er fornybar?', array['Kull', 'Naturgass', 'Vindkraft', 'Olje']::text[], 2, 'Vinden fornyes hele tiden. Kull, olje og gass er fossile og brukes opp.', true, true, 0),
  ('naturfag-9:energi-og-miljo', 'q02', 'flervalg', 'Hvor kommer det meste av strømmen i Norge fra?', array['Vannkraft', 'Kullkraft', 'Kjernekraft', 'Solenergi']::text[], 0, 'Norge har mange fjell og mye nedbør, og nesten all strøm kommer fra vannkraft.', true, true, 1),
  ('naturfag-9:energi-og-miljo', 'q03', 'flervalg', 'Hvilken gass slippes ut når fossile brensler brennes, og forsterker drivhuseffekten?', array['Oksygen', 'Nitrogen', 'Helium', 'Karbondioksid']::text[], 3, 'CO₂ er den viktigste klimagassen fra menneskelig aktivitet.', true, true, 2),
  ('naturfag-9:energi-og-miljo', 'q04', 'flervalg', 'Hvilken er en lokal ulempe ved vannkraft?', array['Store CO₂-utslipp', 'Regulerte elver som kan skade fisk', 'Radioaktivt avfall', 'Sur nedbør']::text[], 1, 'Dammer og regulering endrer vannføringen og kan påvirke fisk som laks.', true, true, 3),
  ('naturfag-9:energi-og-miljo', 'q05', 'flervalg', 'Hva er den største ulempen med kjernekraft?', array['Store CO₂-utslipp', 'Den virker bare når det blåser', 'Radioaktivt avfall som må lagres i svært lang tid', 'Den gir sur nedbør']::text[], 2, 'Kjernekraft gir lite CO₂, men avfallet er farlig i tusenvis av år.', true, true, 4),
  ('naturfag-9:energi-og-miljo', 'q06', 'flervalg', 'Hva betyr energieffektivisering?', array['Å få samme nytte med mindre energi', 'Å bruke mer energi', 'Å bygge flere kraftverk', 'Å skru av alt strøm']::text[], 0, 'Eksempler er etterisolering, LED-lys og varmepumper.', true, true, 5),
  ('naturfag-9:energi-og-miljo', 'q07', 'flervalg', 'Hvilket er et argument mot vindkraft på land?', array['Den gir CO₂', 'Den bruker kull', 'Den er ikke fornybar', 'Den kan beslaglegge store naturområder og forstyrre dyreliv']::text[], 3, 'Store vindkraftanlegg kan påvirke natur, fugler og reinbeite.', true, true, 6),
  ('naturfag-9:energi-og-miljo', 'q08', 'flervalg', 'Hvorfor sparer en varmepumpe energi?', array['Den henter varme fra omgivelsene og gir mer varme enn strømmen den bruker', 'Den bruker ikke strøm', 'Den lager energi av ingenting', 'Den kjøler huset']::text[], 0, 'Varmepumpen flytter varme fra luft, jord eller vann inn i huset.', true, false, 7),
  ('naturfag-9:energi-og-miljo', 'q09', 'flervalg', 'Hva er sur nedbør forårsaket av?', array['CO₂ fra planter', 'Svovel- og nitrogenforbindelser fra forbrenning', 'Vanndamp', 'Solcellepaneler']::text[], 1, 'Utslipp fra forbrenning av kull og olje kan gjøre nedbøren sur.', true, false, 8),
  ('naturfag-9:energi-og-miljo', 'q10', 'flervalg', 'Finnes det en energikilde helt uten miljøkostnader?', array['Ja, vindkraft', 'Ja, vannkraft', 'Nei, alle har ulemper lokalt eller globalt', 'Ja, solenergi']::text[], 2, 'Alle energikilder har noen ulemper, så valgene handler om å veie fordeler og ulemper.', true, true, 9),
  ('naturfag-9:energi-og-miljo', 'm01', 'sant-usant', 'Mesteparten av energien i verden kommer fortsatt fra fossile brensler.', array['Sant', 'Usant']::text[], 0, 'Selv om fornybar energi vokser, dominerer fortsatt kull, olje og gass.', false, true, 10),
  ('naturfag-9:energi-og-miljo', 'm02', 'sant-usant', 'Solenergi har ingen miljøkostnader.', array['Sant', 'Usant']::text[], 1, 'Produksjon av solceller krever energi og mineraler, og solcelleparker tar areal.', false, true, 11),
  ('naturfag-9:energi-og-miljo', 'm03', 'sant-usant', 'Elbiler har høyere virkningsgrad enn bensinbiler.', array['Sant', 'Usant']::text[], 0, 'Elmotorer utnytter en mye større del av energien enn forbrenningsmotorer.', false, true, 12),
  ('naturfag-9:energi-og-miljo', 'm04', 'sant-usant', 'Uran er en fornybar energikilde.', array['Sant', 'Usant']::text[], 1, 'Uran brukes opp og fornyes ikke. Kjernekraft er derfor ikke fornybar.', false, true, 13),
  ('naturfag-9:energi-og-miljo', 'm05', 'flervalg', 'Hva er bioenergi?', array['Energi fra biologisk materiale, som ved og biogass', 'Energi fra kull', 'Energi fra atomkjerner', 'Energi fra vind']::text[], 0, 'Bioenergi kommer fra planter og annet organisk materiale.', false, true, 14),
  ('naturfag-9:energi-og-miljo', 'm06', 'flervalg', 'Hvilket tiltak er energieffektivisering?', array['Å bygge et nytt kullkraftverk', 'Å etterisolere et hus', 'Å kjøre mer bil', 'Å bruke glødepærer']::text[], 1, 'Bedre isolasjon gir samme varme med mindre energi.', false, true, 15),
  ('naturfag-9:energi-og-miljo', 'm07', 'flervalg', 'Hvilken energikilde kan utnytte varme dypt nede i jorda?', array['Tidevannskraft', 'Vindkraft', 'Jordvarme', 'Solenergi']::text[], 2, 'Jordvarme henter varme fra grunnen, ofte med varmepumpe.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-9:energi-og-miljo', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-9:energi-og-miljo', 's01', 'Forklar med egne ord hva en ikke-fornybar energikilde er, og gi ett eksempel.', 'En ikke-fornybar energikilde brukes opp og fornyes ikke i menneskelig tidsperspektiv. Kull er et eksempel.', array['Forklarer at energikilden brukes opp og ikke fornyes i menneskelig tidsperspektiv.', 'Gir et riktig eksempel, som kull, olje, naturgass eller uran.']::text[], 0),
  ('naturfag-9:energi-og-miljo', 's02', 'Forklar hvordan det å brenne kull, olje eller naturgass kan bidra til global oppvarming.', 'Når fossile brensler brennes, slippes CO₂ ut. CO₂ forsterker drivhuseffekten, noe som bidrar til global oppvarming.', array['Knytter forbrenning av fossile brensler til utslipp av CO₂.', 'Forklarer at CO₂ forsterker drivhuseffekten og bidrar til global oppvarming.']::text[], 1),
  ('naturfag-9:energi-og-miljo', 's03', 'Sammenlign én lokal miljøulempe ved vannkraft med én lokal miljøulempe ved vindkraft.', 'Vannkraft krever dammer og regulerte elver, som kan endre landskapet og skade fisk. Vindkraft kan gi støy eller forstyrre reinbeite.', array['Nevner en relevant lokal ulempe ved vannkraft, som endringer i landskap eller skade på fisk.', 'Nevner en relevant lokal ulempe ved vindkraft, som støy, arealbruk eller påvirkning på fugler eller reinbeite.']::text[], 2),
  ('naturfag-9:energi-og-miljo', 's04', 'En familie bytter fra bensinbil til elbil. Forklar to fordeler elbilen har når det gjelder energibruk og utslipp.', 'Elbiler har høyere virkningsgrad enn bensinbiler. De har heller ingen utslipp fra eksosrøret.', array['Forklarer at elbiler har høyere virkningsgrad enn bensinbiler.', 'Nevner at elbiler ikke har utslipp fra eksosrøret.']::text[], 3),
  ('naturfag-9:energi-og-miljo', 's05', 'En gård bruker ved som bioenergi. Forklar hvordan dette kan føre til en miljøulempe hvis skogen ikke drives bærekraftig.', 'Hvis skogen ikke drives bærekraftig, kan bruk av bioenergi føre til at det hogges for mye skog.', array['Knytter bioenergi fra ved til hogst av skog.', 'Forklarer at hogst kan bli en miljøulempe dersom den ikke er bærekraftig.']::text[], 4),
  ('naturfag-9:energi-og-miljo', 's06', 'Et land vil redusere klimagassutslippene ved å gå fra fossile brensler til fornybar energi. Nevn to løsninger landet trenger i framtidas energisystem, og si hva hydrogen kan brukes til.', 'Energisystemet trenger blant annet bedre energilagring og smartere strømnett. Hydrogen kan bli brukt i tungtransport eller industri.', array['Nevner to relevante løsninger, som mer strøm fra sol og vind, bedre energilagring eller smartere strømnett.', 'Nevner tungtransport eller industri som mulig bruksområde for hydrogen.']::text[], 5),
  ('naturfag-9:energi-og-miljo', 's07', 'I samme tidsrom bruker glødepærer 15 kWh, mens LED-lamper som gir samme nytte, bruker 6 kWh. Hvor mye energi spares ved å bytte til LED? Vis regnestykket, og forklar kort hvorfor dette er energieffektivisering.', 'Det spares 9 kWh: 15 − 6 = 9. Det er energieffektivisering fordi lampene gir samme nytte med mindre energi.', array['Viser regnestykket 15 − 6 og får svaret 9 kWh.', 'Forklarer at samme nytte oppnås med mindre energi.']::text[], 6),
  ('naturfag-9:energi-og-miljo', 's08', 'Et anlegg leverer 18 energienheter fra vindkraft og 27 fra vannkraft på én dag. Hvor mange energienheter kommer fra disse fornybare kildene til sammen? Vis regnestykket, og forklar kort hvorfor begge kildene regnes som fornybare.', 'Til sammen leverer de 45 energienheter: 18 + 27 = 45. Vind og vann regnes som fornybare fordi energikildene fornyes hele tiden.', array['Viser addisjonen 18 + 27 og får svaret 45 energienheter.', 'Forklarer at vind og vann regnes som fornybare energikilder.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-9:drivhuseffekten-og-klima', 'naturfag-9', 'drivhuseffekten-og-klima', 'Drivhuseffekten og klimaendringer', 'Den naturlige og den forsterkede drivhuseffekten, faktorer som påvirker jordas klima, og følgene av global oppvarming.', array[10, 5]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-9:drivhuseffekten-og-klima', '## Vær og klima
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-9:drivhuseffekten-og-klima', 'Vær', 'Forholdene i atmosfæren på et bestemt sted og tidspunkt.', 0),
  ('naturfag-9:drivhuseffekten-og-klima', 'Klima', 'Gjennomsnittsværet over lang tid, vanligvis 30 år.', 1),
  ('naturfag-9:drivhuseffekten-og-klima', 'Drivhuseffekten', 'Drivhusgasser holder på varmestråling fra jorda og gjør jorda varmere.', 2),
  ('naturfag-9:drivhuseffekten-og-klima', 'Uten drivhuseffekt', 'Jorda ville hatt en gjennomsnittstemperatur på rundt −18 °C i stedet for +15 °C.', 3),
  ('naturfag-9:drivhuseffekten-og-klima', 'Drivhusgasser', 'Vanndamp, karbondioksid (CO₂), metan (CH₄) og lystgass (N₂O).', 4),
  ('naturfag-9:drivhuseffekten-og-klima', 'Forsterket drivhuseffekt', 'Økt drivhuseffekt på grunn av menneskeskapte utslipp.', 5),
  ('naturfag-9:drivhuseffekten-og-klima', 'CO₂ i atmosfæren', 'Økt fra rundt 280 ppm før industrialiseringen til over 425 ppm i dag.', 6),
  ('naturfag-9:drivhuseffekten-og-klima', 'Albedo', 'Hvor mye sollys en flate reflekterer. Snø og is har høy albedo.', 7),
  ('naturfag-9:drivhuseffekten-og-klima', 'Tilbakekobling', 'En endring som forsterker eller demper seg selv, som når smeltende is gir mer oppvarming.', 8),
  ('naturfag-9:drivhuseffekten-og-klima', 'FNs klimapanel (IPCC)', 'Sammenstiller klimaforskningen og har konkludert med at mennesker er hovedårsaken til oppvarmingen.', 9),
  ('naturfag-9:drivhuseffekten-og-klima', 'Parisavtalen', 'Avtale fra 2015 om å begrense oppvarmingen til godt under 2 °C, helst 1,5 °C.', 10),
  ('naturfag-9:drivhuseffekten-og-klima', 'Havnivåstigning', 'Skyldes smeltende isbreer og at varmere havvann utvider seg.', 11),
  ('naturfag-9:drivhuseffekten-og-klima', 'Havforsuring', 'Havet blir surere når det tar opp CO₂.', 12),
  ('naturfag-9:drivhuseffekten-og-klima', 'Vulkanutbrudd og klima', 'Partikler fra store utbrudd kan kjøle ned klimaet i et par år.', 13),
  ('naturfag-9:drivhuseffekten-og-klima', 'Istider', 'Skyldes blant annet langsomme endringer i jordas bane og helning.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-9:drivhuseffekten-og-klima', 'q01', 'flervalg', 'Hva er forskjellen på vær og klima?', array['Det er det samme', 'Vær er hvordan det er nå, klima er gjennomsnittet over lang tid', 'Klima er været i morgen', 'Vær gjelder hele jorda, klima ett sted']::text[], 1, 'Klima er gjennomsnittsværet over rundt 30 år.', true, true, 0),
  ('naturfag-9:drivhuseffekten-og-klima', 'q02', 'flervalg', 'Hva ville gjennomsnittstemperaturen på jorda vært uten den naturlige drivhuseffekten?', array['Rundt −18 °C', 'Rundt +30 °C', 'Rundt 0 °C', 'Rundt +15 °C']::text[], 0, 'Drivhuseffekten hever temperaturen fra rundt −18 °C til rundt +15 °C.', true, true, 1),
  ('naturfag-9:drivhuseffekten-og-klima', 'q03', 'flervalg', 'Hvilken er en drivhusgass?', array['Oksygen', 'Nitrogen', 'Metan', 'Argon']::text[], 2, 'Metan er en kraftig drivhusgass. Oksygen og nitrogen er ikke drivhusgasser.', true, true, 2),
  ('naturfag-9:drivhuseffekten-og-klima', 'q04', 'flervalg', 'Hva er hovedårsaken til den forsterkede drivhuseffekten?', array['Flere vulkanutbrudd', 'At sola har blitt mye sterkere', 'Endringer i jordbanen', 'Menneskeskapte utslipp av drivhusgasser']::text[], 3, 'Forbrenning av fossile brensler og avskoging har økt mengden drivhusgasser.', true, true, 3),
  ('naturfag-9:drivhuseffekten-og-klima', 'q05', 'flervalg', 'Hvorfor forsterker smeltende is oppvarmingen?', array['Fordi isen er varm', 'Fordi mørkere hav og land tar opp mer sollys enn hvit is', 'Fordi isen slipper ut CO₂', 'Den forsterker ikke oppvarmingen']::text[], 1, 'Dette er en tilbakekobling via albedo: mindre is gir mer oppvarming, som gir enda mindre is.', true, true, 4),
  ('naturfag-9:drivhuseffekten-og-klima', 'q06', 'flervalg', 'Hva ble landene enige om i Parisavtalen?', array['Å begrense oppvarmingen til godt under 2 °C, helst 1,5 °C', 'Å stoppe all bilkjøring', 'Å øke oljeproduksjonen', 'Å flytte til Mars']::text[], 0, 'Parisavtalen fra 2015 setter målet for den globale temperaturøkningen.', true, true, 5),
  ('naturfag-9:drivhuseffekten-og-klima', 'q07', 'flervalg', 'Hvorfor stiger havnivået?', array['Fordi det regner mer', 'Fordi fisk tar mer plass', 'Fordi isbreer smelter og varmt havvann utvider seg', 'Fordi havbunnen stiger']::text[], 2, 'Både smeltevann fra is på land og termisk utvidelse av havvannet bidrar.', true, true, 6),
  ('naturfag-9:drivhuseffekten-og-klima', 'q08', 'flervalg', 'Hva kan et stort vulkanutbrudd gjøre med klimaet?', array['Gjøre det varmere i mange hundre år', 'Ingenting', 'Stoppe drivhuseffekten', 'Kjøle det ned i et par år']::text[], 3, 'Partikler i atmosfæren reflekterer sollys og gir en kortvarig nedkjøling.', true, false, 7),
  ('naturfag-9:drivhuseffekten-og-klima', 'q09', 'flervalg', 'Hva er FNs klimapanel (IPCC)?', array['En organisasjon som sammenstiller klimaforskningen', 'Et selskap som selger strøm', 'En norsk forskningsstasjon', 'En værmelding']::text[], 0, 'IPCC vurderer forskningen og gir rapporter om klimaendringer.', true, false, 8),
  ('naturfag-9:drivhuseffekten-og-klima', 'q10', 'flervalg', 'Hvorfor blir havet surere?', array['På grunn av plast', 'Fordi havet tar opp CO₂', 'På grunn av salt', 'Fordi det blir kaldere']::text[], 1, 'CO₂ løses i sjøvann og danner en svak syre. Det kalles havforsuring.', true, true, 9),
  ('naturfag-9:drivhuseffekten-og-klima', 'm01', 'sant-usant', 'Den naturlige drivhuseffekten er nødvendig for livet på jorda.', array['Sant', 'Usant']::text[], 0, 'Uten den ville jorda vært altfor kald.', false, true, 10),
  ('naturfag-9:drivhuseffekten-og-klima', 'm02', 'sant-usant', 'En kald vinter i Norge beviser at global oppvarming ikke skjer.', array['Sant', 'Usant']::text[], 1, 'Én vinter er vær. Klima handler om gjennomsnittet over mange år og hele kloden.', false, true, 11),
  ('naturfag-9:drivhuseffekten-og-klima', 'm03', 'sant-usant', 'Endringer i jordbanen har bidratt til istider.', array['Sant', 'Usant']::text[], 0, 'Langsomme endringer i banen og helningen påvirker hvor mye sollys som når jorda.', false, true, 12),
  ('naturfag-9:drivhuseffekten-og-klima', 'm04', 'sant-usant', 'Vanndamp er ikke en drivhusgass.', array['Sant', 'Usant']::text[], 1, 'Vanndamp er faktisk den drivhusgassen som bidrar mest til den naturlige drivhuseffekten.', false, true, 13),
  ('naturfag-9:drivhuseffekten-og-klima', 'm05', 'flervalg', 'Hva slags stråling holder drivhusgassene igjen?', array['Radiobølger', 'Varmestråling (infrarød)', 'Røntgenstråling', 'Lydbølger']::text[], 1, 'Jorda sender ut infrarød varmestråling, som drivhusgassene tar opp.', false, true, 14),
  ('naturfag-9:drivhuseffekten-og-klima', 'm06', 'flervalg', 'Hvor mye har jordas gjennomsnittstemperatur steget siden førindustriell tid?', array['Over 1 °C', 'Over 10 °C', '0 °C', 'Over 5 °C']::text[], 0, 'Oppvarmingen er allerede over 1 °C, og den fortsetter.', false, true, 15),
  ('naturfag-9:drivhuseffekten-og-klima', 'm07', 'flervalg', 'Hvilket tiltak reduserer utslippene av klimagasser?', array['Mer kullkraft', 'Hogst av regnskog', 'Overgang til fornybar energi', 'Drenering av myr']::text[], 2, 'Fornybar energi erstatter fossile brensler og gir lavere utslipp.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-9:drivhuseffekten-og-klima', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-9:drivhuseffekten-og-klima', 's01', 'Forklar hvordan sollys og drivhusgasser bidrar til at jordoverflaten blir varmere.', 'Sollys går gjennom atmosfæren og varmer jordoverflaten. Jorda sender energi ut igjen som varmestråling, og drivhusgasser tar opp noe av strålingen og sender den tilbake mot jorda.', array['Forklarer at sollys varmer jordoverflaten, som sender ut varmestråling.', 'Forklarer at drivhusgasser tar opp noe av varmestrålingen og sender den tilbake mot jorda.']::text[], 0),
  ('naturfag-9:drivhuseffekten-og-klima', 's02', 'Sammenlign hvordan vulkanutbrudd og endringer i jordas bane kan påvirke klimaet.', 'Partikler fra store vulkanutbrudd kan kjøle ned klimaet i et par år. Langsomme endringer i jordas bane og helning har bidratt til istider og mellomistider over hundretusenvis av år.', array['Får fram at partikler fra vulkanutbrudd kan gi kortvarig nedkjøling.', 'Får fram at langsomme endringer i jordas bane og helning har bidratt til istider og mellomistider.']::text[], 1),
  ('naturfag-9:drivhuseffekten-og-klima', 's03', 'Hva betyr albedo? Bruk snø eller is som eksempel på hvordan albedo påvirker hvor mye sollys en flate tar opp.', 'Albedo sier noe om hvor mye sollys en flate reflekterer. Snø og is har høy albedo og reflekterer mye sollys, slik at mindre sollys tas opp som varme.', array['Forklarer at albedo handler om hvor mye sollys en flate reflekterer.', 'Knytter snø eller is med høy albedo til at mye sollys reflekteres og mindre varme tas opp.']::text[], 2),
  ('naturfag-9:drivhuseffekten-og-klima', 's04', 'Hvilken rolle spiller havstrømmer for klimaet på ulike steder på jorda?', 'Havstrømmer frakter varme rundt på kloden. Derfor påvirker de hvordan varmen fordeles mellom ulike steder.', array['Forklarer at havstrømmer frakter varme.', 'Knytter varmetransporten til påvirkning på klimaet ulike steder.']::text[], 3),
  ('naturfag-9:drivhuseffekten-og-klima', 's05', 'Et land vil kutte utslippene sine for å bidra til målet i Parisavtalen. Beskriv én handling landet kan gjøre, og forklar hvordan den bidrar.', 'Landet kan gå over til fornybar energi i stedet for å brenne kull, olje og gass. Det bidrar til å kutte utslipp av drivhusgasser.', array['Nevner et relevant tiltak, som fornybar energi, energieffektivisering eller vern av skog og myr.', 'Forklarer at tiltaket bidrar til å kutte utslipp av drivhusgasser.']::text[], 4),
  ('naturfag-9:drivhuseffekten-og-klima', 's06', 'Sammenlign den naturlige drivhuseffekten med den forsterkede drivhuseffekten. Hva er felles, og hva fører til at effekten blir sterkere?', 'I begge tilfeller holder drivhusgasser på noe av varmestrålingen fra jorda. Den forsterkede drivhuseffekten oppstår når menneskeskapte utslipp øker mengden drivhusgasser, slik at mer varme holdes igjen.', array['Får fram at drivhusgasser holder på varmestråling fra jorda i begge tilfeller.', 'Forklarer at menneskeskapte utslipp øker mengden drivhusgasser og dermed forsterker effekten.']::text[], 5),
  ('naturfag-9:drivhuseffekten-og-klima', 's07', 'Den naturlige drivhuseffekten gir en gjennomsnittstemperatur på rundt +15 °C, mens temperaturen uten den ville vært rundt −18 °C. Hvor stor er forskjellen? Vis det viktigste regnestykket.', 'Forskjellen er 33 °C. Regnestykket er 15 − (−18) = 33.', array['Viser regnestykket 15 − (−18) eller et tilsvarende regnestykke.', 'Oppgir forskjellen som 33 °C.']::text[], 6),
  ('naturfag-9:drivhuseffekten-og-klima', 's08', 'Mengden CO₂ var rundt 280 ppm før industrialiseringen og er over 425 ppm i dag. Bruk 425 ppm som en avrundet verdi: Omtrent hvor mye har mengden økt? Vis det viktigste regnestykket.', 'Mengden har økt med omtrent 145 ppm. Regnestykket er 425 − 280 = 145.', array['Viser regnestykket 425 − 280.', 'Oppgir en økning på omtrent 145 ppm.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-9:sender-og-mottaker', 'naturfag-9', 'sender-og-mottaker', 'Teknologi: sender og mottaker', 'Hvordan teknologiske systemer overfører signaler fra en sender til en mottaker – med sensorer, mikrokontrollere, lys, lyd og radiobølger.', array[6, 7]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-9:sender-og-mottaker', '## Signaler overalt
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-9:sender-og-mottaker', 'Signal', 'Noe som bærer informasjon fra en sender til en mottaker, som lys, lyd eller radiobølger.', 0),
  ('naturfag-9:sender-og-mottaker', 'Sender', 'Delen som gjør informasjon om til et signal.', 1),
  ('naturfag-9:sender-og-mottaker', 'Mottaker', 'Delen som fanger opp signalet og gjør det om til noe nyttig.', 2),
  ('naturfag-9:sender-og-mottaker', 'Kanal', 'Det signalet går gjennom: luft, ledning, optisk fiber eller tomt rom.', 3),
  ('naturfag-9:sender-og-mottaker', 'Infrarødt lys', 'Usynlig lys som brukes i fjernkontroller.', 4),
  ('naturfag-9:sender-og-mottaker', 'Radiobølger', 'Elektromagnetiske bølger brukt i mobilnett, wifi, bluetooth og GPS.', 5),
  ('naturfag-9:sender-og-mottaker', 'Optisk fiber', 'Tynn glasstråd som leder lys og gir svært rask dataoverføring.', 6),
  ('naturfag-9:sender-og-mottaker', 'Analogt signal', 'Et signal som varierer jevnt og kontinuerlig.', 7),
  ('naturfag-9:sender-og-mottaker', 'Digitalt signal', 'Informasjon gjort om til ett-tall og null-tall.', 8),
  ('naturfag-9:sender-og-mottaker', 'Sensor', 'En komponent som måler noe i omgivelsene, som lys eller temperatur.', 9),
  ('naturfag-9:sender-og-mottaker', 'Mikrokontroller', 'En liten programmerbar datamaskin, som micro:bit eller Arduino.', 10),
  ('naturfag-9:sender-og-mottaker', 'Prototype', 'En tidlig, enkel versjon av et produkt som testes og forbedres.', 11),
  ('naturfag-9:sender-og-mottaker', 'Utviklingsprosess', 'Behov → plan → prototype → test → forbedring.', 12),
  ('naturfag-9:sender-og-mottaker', 'Ekkolodd', 'Sender lydbølger og måler ekkoet for å finne dybde eller fisk.', 13),
  ('naturfag-9:sender-og-mottaker', 'Støy', 'Uønskede forstyrrelser i et signal. Digitale signaler er mindre utsatt.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-9:sender-og-mottaker', 'q01', 'flervalg', 'Hva gjør senderen i et teknologisk system?', array['Fanger opp signalet', 'Gjør informasjon om til et signal', 'Lagrer strøm', 'Måler temperatur']::text[], 1, 'Senderen omformer informasjon til et signal som kan overføres.', true, true, 0),
  ('naturfag-9:sender-og-mottaker', 'q02', 'flervalg', 'Hva slags signal bruker en vanlig TV-fjernkontroll?', array['Infrarødt lys', 'Lyd', 'Røntgenstråler', 'Kabel']::text[], 0, 'Fjernkontrollen sender pulser av infrarødt lys som TV-en fanger opp.', true, true, 1),
  ('naturfag-9:sender-og-mottaker', 'q03', 'flervalg', 'Hvilken teknologi bruker radiobølger?', array['Optisk fiber', 'Fjernkontroll med infrarødt lys', 'Wifi og bluetooth', 'Et stetoskop']::text[], 2, 'Wifi, bluetooth, mobilnett og GPS bruker radiobølger.', true, true, 2),
  ('naturfag-9:sender-og-mottaker', 'q04', 'flervalg', 'Hva er et digitalt signal?', array['Et signal som varierer jevnt', 'Et lydsignal', 'Et signal i en fiber', 'Informasjon gjort om til ett-tall og null-tall']::text[], 3, 'Digitale signaler består av binære verdier og er mindre utsatt for støy.', true, true, 3),
  ('naturfag-9:sender-og-mottaker', 'q05', 'flervalg', 'Hva er en sensor?', array['En komponent som måler noe i omgivelsene', 'En høyttaler', 'En type batteri', 'Et program']::text[], 0, 'Sensorer kan måle for eksempel lys, temperatur, avstand og bevegelse.', true, true, 4),
  ('naturfag-9:sender-og-mottaker', 'q06', 'flervalg', 'Hva er en mikrokontroller?', array['Et lite mikroskop', 'En liten programmerbar datamaskin', 'En type lyspære', 'En radiostasjon']::text[], 1, 'Micro:bit og Arduino er eksempler på mikrokontrollere.', true, true, 5),
  ('naturfag-9:sender-og-mottaker', 'q07', 'flervalg', 'Hva sendes gjennom en optisk fiber?', array['Strøm', 'Vann', 'Lyd', 'Lys']::text[], 3, 'Optiske fibre leder lys og kan overføre enorme datamengder raskt.', true, false, 6),
  ('naturfag-9:sender-og-mottaker', 'q08', 'flervalg', 'Hva er en prototype?', array['Det ferdige produktet', 'En tidlig versjon som testes og forbedres', 'En type sensor', 'En reklame']::text[], 1, 'Prototyper gjør det mulig å teste ideer før man lager det endelige produktet.', true, true, 7),
  ('naturfag-9:sender-og-mottaker', 'q09', 'flervalg', 'I en dørlarm med to micro:biter, hva er senderen?', array['Micro:biten som piper', 'Døra', 'Micro:biten som oppdager at døra åpnes og sender signal', 'Batteriet']::text[], 2, 'Enheten som registrerer bevegelsen og sender signalet, er senderen.', true, true, 8),
  ('naturfag-9:sender-og-mottaker', 'q10', 'flervalg', 'Hvorfor er digitale signaler mindre utsatt for støy?', array['Fordi de bare har to verdier som er lette å skille fra hverandre', 'Fordi de er svakere', 'Fordi de går saktere', 'Fordi de bruker lyd']::text[], 0, 'Selv med litt støy er det lett å se om signalet er 0 eller 1.', true, false, 9),
  ('naturfag-9:sender-og-mottaker', 'm01', 'sant-usant', 'Radiobølger går med lysets fart.', array['Sant', 'Usant']::text[], 0, 'Radiobølger er elektromagnetiske bølger, som lys.', false, true, 10),
  ('naturfag-9:sender-og-mottaker', 'm02', 'sant-usant', 'Lyd kan sendes gjennom tomt rom (vakuum).', array['Sant', 'Usant']::text[], 1, 'Lyd trenger et stoff å bevege seg i, som luft eller vann.', false, true, 11),
  ('naturfag-9:sender-og-mottaker', 'm03', 'sant-usant', 'En fjernkontroll er både sender og mottaker.', array['Sant', 'Usant']::text[], 1, 'Fjernkontrollen er sender. TV-en er mottakeren.', false, true, 12),
  ('naturfag-9:sender-og-mottaker', 'm04', 'sant-usant', 'Å teste og forbedre er en viktig del av å lage et teknologisk system.', array['Sant', 'Usant']::text[], 0, 'Testing avslører svakheter som kan rettes i neste versjon.', false, true, 13),
  ('naturfag-9:sender-og-mottaker', 'm05', 'flervalg', 'Hvilken teknologi bruker lydbølger for å måle dybde?', array['GPS', 'Ekkolodd', 'Wifi', 'Optisk fiber']::text[], 1, 'Ekkoloddet sender lyd og måler hvor lang tid ekkoet bruker.', false, true, 14),
  ('naturfag-9:sender-og-mottaker', 'm06', 'flervalg', 'Hva kan en lyssensor brukes til?', array['Å måle hvor mye lys det er, for eksempel for å skru på gatelys', 'Å måle temperatur', 'Å lage lyd', 'Å veie ting']::text[], 0, 'Lyssensorer brukes blant annet i automatiske lys.', false, true, 15),
  ('naturfag-9:sender-og-mottaker', 'm07', 'flervalg', 'Hva er kanalen når to mobiler kommuniserer trådløst?', array['En kabel', 'Glassfiber', 'Lufta og rommet radiobølgene går gjennom', 'Batteriet']::text[], 2, 'Radiobølgene går gjennom lufta mellom mobilen og basestasjonen.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-9:sender-og-mottaker', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-9:sender-og-mottaker', 's01', 'En alarm piper, og en person hører den på den andre siden av rommet. Hva er signalet, og hva er kanalen? Forklar kort forskjellen på dem.', 'Signalet er lydbølgene som bærer informasjonen om at alarmen piper. Kanalen er lufta som lydbølgene går gjennom.', array['Skiller mellom lydbølgene som signal og lufta som kanal.']::text[], 0),
  ('naturfag-9:sender-og-mottaker', 's02', 'En dørsensor oppdager at en dør åpnes og sender et radiosignal gjennom lufta til en mottaker som piper. Forklar rekkefølgen fra døra åpnes til alarmen piper.', 'Sensoren oppdager at døra åpnes og sender informasjonen som et radiosignal. Signalet går gjennom lufta til mottakeren, som gjør det om til en pipelyd.', array['Forklarer at sensoren sender et signal når døra åpnes.', 'Forklarer at mottakeren tar imot signalet og lager pipelyden.']::text[], 1),
  ('naturfag-9:sender-og-mottaker', 's03', 'Sammenlign analoge og digitale signaler. Ta med hvordan de varierer, og én fordel digitale signaler har.', 'Et analogt signal varierer jevnt, mens et digitalt signal består av ett-tall og null-tall. Digitale signaler er mindre utsatt for støy og kan lett lagres og kopieres.', array['Forklarer forskjellen på hvordan analoge og digitale signaler er laget.', 'Nevner en faglig fordel med digitale signaler, som mindre støy eller enkel lagring og kopiering.']::text[], 2),
  ('naturfag-9:sender-og-mottaker', 's04', 'Du skal lage en lampe som slår seg på når det blir mørkt. Forklar hvilken rolle en sensor og en mikrokontroller kan ha i løsningen.', 'En lyssensor måler hvor mye lys det er. Mikrokontrolleren leser målingen og bestemmer at lampen skal slås på når det er mørkt.', array['Forklarer at sensoren måler lys i omgivelsene.', 'Forklarer at mikrokontrolleren bruker målingen til å styre lampen.']::text[], 3),
  ('naturfag-9:sender-og-mottaker', 's05', 'En gruppe har laget en prototype av en døralarm, men alarmen piper noen ganger uten at døra åpnes. Forklar hvordan gruppa kan bruke testing og forbedring for å gjøre alarmen bedre.', 'Gruppa kan teste når alarmen gir falsk alarm, og undersøke sensoren og programmet. Deretter kan de endre konstruksjonen eller programmet og teste på nytt.', array['Beskriver at gruppa tester for å finne ut når eller hvorfor falske alarmer oppstår.', 'Forklarer at de bruker resultatene til å gjøre en endring og teste igjen.']::text[], 4),
  ('naturfag-9:sender-og-mottaker', 's06', 'Et ekkolodd sender lydbølger og måler ekkoet. Forklar hvordan dette kan hjelpe med å finne dybde eller fisk.', 'Lydbølgene treffer noe og kommer tilbake som et ekko. Ved å måle ekkoet kan ekkoloddet finne dybde eller oppdage fisk.', array['Forklarer at lydbølger sendes ut og kommer tilbake som ekko.', 'Knytter målingen av ekkoet til å finne dybde eller fisk.']::text[], 5),
  ('naturfag-9:sender-og-mottaker', 's07', 'En døralarm sender ett radiosignal hver gang døra åpnes. Døra åpnes 3 ganger om morgenen og 4 ganger senere. Hvor mange radiosignaler sendes til sammen? Vis regnestykket.', 'Det sendes 3 + 4 = 7 radiosignaler.', array['Viser at antallet signaler finnes ved å legge sammen 3 og 4, og får 7.']::text[], 6),
  ('naturfag-9:sender-og-mottaker', 's08', 'I en test sender én micro:bit ett signal til hver av 3 mottakere. Den gjør dette 2 ganger. Hvor mange signalmottak blir det til sammen? Vis regnestykket.', 'Det blir 3 × 2 = 6 signalmottak.', array['Viser at antallet mottak finnes ved å regne 3 × 2, og får 6.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-9:programmering-i-naturfag', 'naturfag-9', 'programmering-i-naturfag', 'Programmering i naturfag', 'Hvordan programmering brukes til å samle inn måledata, lage simuleringer og modeller, og utforske naturfaglige fenomener.', array[7, 3, 1]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-9:programmering-i-naturfag', '## Hvorfor programmere i naturfag?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-9:programmering-i-naturfag', 'Simulering', 'Et program som etterligner en naturfaglig prosess etter bestemte regler.', 0),
  ('naturfag-9:programmering-i-naturfag', 'Modell', 'En forenklet beskrivelse av virkeligheten som simuleringer bygger på.', 1),
  ('naturfag-9:programmering-i-naturfag', 'Mikrokontroller', 'Liten programmerbar datamaskin, som micro:bit, som kan lese sensorer.', 2),
  ('naturfag-9:programmering-i-naturfag', 'Sensor', 'Måler noe i omgivelsene, som temperatur, lys eller bevegelse.', 3),
  ('naturfag-9:programmering-i-naturfag', 'Automatisk måling', 'Programmet tar målinger med faste mellomrom, uten at noen må lese av.', 4),
  ('naturfag-9:programmering-i-naturfag', 'Liste', 'Struktur i et program som lagrer mange verdier, for eksempel målinger.', 5),
  ('naturfag-9:programmering-i-naturfag', 'Tidssteg', 'Et lite tidsintervall som simuleringen regner ut ett og ett av, i en løkke.', 6),
  ('naturfag-9:programmering-i-naturfag', 'Populasjonsvekst', 'Økningen i antall individer, som kan simuleres med et program.', 7),
  ('naturfag-9:programmering-i-naturfag', 'Rovdyr–byttedyr-modell', 'Simulering av hvordan antall rovdyr og byttedyr påvirker hverandre.', 8),
  ('naturfag-9:programmering-i-naturfag', 'Halveringstid', 'Tiden det tar før halvparten av et radioaktivt stoff har brutt ned.', 9),
  ('naturfag-9:programmering-i-naturfag', 'Betingelse i måleprogram', 'For eksempel: hvis temperaturen er over 25 °C, skru på vifta.', 10),
  ('naturfag-9:programmering-i-naturfag', 'Tilfeldige tall', 'Brukes til å etterligne tilfeldige hendelser i simuleringer.', 11),
  ('naturfag-9:programmering-i-naturfag', 'Kontrollere sensoren', 'Sammenligne sensorens verdier med et kjent måleinstrument.', 12),
  ('naturfag-9:programmering-i-naturfag', 'Hva-om-spørsmål', 'Å endre én variabel i en simulering for å se hvordan systemet reagerer.', 13),
  ('naturfag-9:programmering-i-naturfag', 'Modellens begrensninger', 'Forenklingene gjør at modellen ikke stemmer helt med virkeligheten.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-9:programmering-i-naturfag', 'q01', 'flervalg', 'Hva er en simulering?', array['Et program som etterligner en prosess etter bestemte regler', 'Et vanlig forsøk på lab', 'En type sensor', 'Et regneark uten data']::text[], 0, 'Simuleringer lar oss utforske prosesser som er vanskelige å undersøke direkte.', true, true, 0),
  ('naturfag-9:programmering-i-naturfag', 'q02', 'flervalg', 'Hva er en fordel med automatisk måling med sensor?', array['Man trenger aldri å kontrollere resultatene', 'Den gir mange og jevne målinger over lang tid', 'Den er alltid helt nøyaktig', 'Den krever ingen strøm']::text[], 1, 'Programmet kan måle for eksempel hvert minutt i et helt døgn.', true, true, 1),
  ('naturfag-9:programmering-i-naturfag', 'q03', 'flervalg', 'Bakterier dobles hvert 20. minutt. Hvor mange blir én bakterie til etter 1 time?', array['3', '6', '8', '20']::text[], 2, 'På én time er det tre doblinger: 1 → 2 → 4 → 8.', true, true, 2),
  ('naturfag-9:programmering-i-naturfag', 'q04', 'flervalg', 'Hvorfor må vi sammenligne en simulering med virkelige data?', array['Fordi datamaskiner alltid regner feil', 'Fordi det er gøy', 'For å gjøre programmet raskere', 'Fordi simuleringen bygger på forenklinger som kan være feil']::text[], 3, 'En modell er bare så god som reglene og tallene den bygger på.', true, true, 3),
  ('naturfag-9:programmering-i-naturfag', 'q05', 'flervalg', 'Hva brukes en løkke til i en simulering?', array['Å gjenta beregningen for hvert tidssteg', 'Å lagre en enkelt verdi', 'Å koble til sensoren', 'Å skrive ut en tittel']::text[], 0, 'Løkka regner ut ett tidssteg om gangen, for eksempel ett minutt eller én generasjon.', true, true, 4),
  ('naturfag-9:programmering-i-naturfag', 'q06', 'flervalg', 'Et program skal skru på en vifte når det blir for varmt. Hva trengs?', array['Bare en løkke', 'Bare en liste', 'En betingelse, som «hvis temperaturen er over 25 °C»', 'Ingen programmering']::text[], 2, 'Betingelsen avgjør når vifta skal gå.', true, true, 5),
  ('naturfag-9:programmering-i-naturfag', 'q07', 'flervalg', 'Hvorfor kan tilfeldige tall være nyttige i simuleringer?', array['For å gjøre programmet feilfritt', 'For å etterligne tilfeldige hendelser, som radioaktivt henfall', 'For å erstatte alle målinger', 'De er aldri nyttige']::text[], 1, 'Mange prosesser i naturen har et tilfeldig element som kan etterlignes med tilfeldige tall.', true, false, 6),
  ('naturfag-9:programmering-i-naturfag', 'q08', 'flervalg', 'Hva gjør du når du kontrollerer en temperatursensor?', array['Sammenligner verdiene med et vanlig termometer', 'Sletter programmet', 'Bytter batteri', 'Legger den i fryseren for alltid']::text[], 0, 'Da ser du om sensoren viser riktige verdier.', true, true, 7),
  ('naturfag-9:programmering-i-naturfag', 'q09', 'flervalg', 'Hva er et hva-om-spørsmål i en simulering?', array['Et spørsmål om programmets navn', 'Å endre én variabel for å se hvordan systemet reagerer', 'Å slette data', 'Å skrive rapport']::text[], 1, 'Eksempel: Hva skjer med smittespredningen hvis flere er vaksinert?', true, false, 8),
  ('naturfag-9:programmering-i-naturfag', 'q10', 'flervalg', 'Hvilket fenomen egner seg godt for simulering fordi det tar lang tid i virkeligheten?', array['Å veie et eple', 'Å måle romtemperaturen nå', 'Radioaktiv nedbrytning over tusenvis av år', 'Å telle elevene i klassen']::text[], 2, 'Simuleringer kan vise prosesser som tar altfor lang tid å observere direkte.', true, true, 9),
  ('naturfag-9:programmering-i-naturfag', 'm01', 'sant-usant', 'En simulering gir alltid nøyaktig samme resultat som virkeligheten.', array['Sant', 'Usant']::text[], 1, 'Simuleringer bygger på forenklinger og kan avvike fra virkeligheten.', false, true, 10),
  ('naturfag-9:programmering-i-naturfag', 'm02', 'sant-usant', 'Værmeldinger bygger på dataprogrammer som simulerer atmosfæren.', array['Sant', 'Usant']::text[], 0, 'Meteorologer bruker store datamodeller for å beregne været.', false, true, 11),
  ('naturfag-9:programmering-i-naturfag', 'm03', 'sant-usant', 'Målinger fra en sensor kan lagres i en liste i programmet.', array['Sant', 'Usant']::text[], 0, 'Lister gjør det mulig å lagre og senere analysere mange målinger.', false, true, 12),
  ('naturfag-9:programmering-i-naturfag', 'm04', 'sant-usant', 'Man trenger aldri å vurdere om en sensor måler riktig.', array['Sant', 'Usant']::text[], 1, 'Sensorer kan være unøyaktige og bør kontrolleres.', false, true, 13),
  ('naturfag-9:programmering-i-naturfag', 'm05', 'flervalg', 'Hvor mye er igjen av et radioaktivt stoff etter to halveringstider?', array['Halvparten', 'En firedel', 'Ingenting', 'En tredel']::text[], 1, 'Etter én halveringstid er halvparten igjen, etter to er det en firedel.', false, true, 14),
  ('naturfag-9:programmering-i-naturfag', 'm06', 'flervalg', 'Hvilken byggestein lagrer størrelser som tid og temperatur i et program?', array['Variabler', 'Kommentarer', 'Tabeller på papir', 'Skrifttyper']::text[], 0, 'Variabler holder på verdiene programmet regner med.', false, true, 15),
  ('naturfag-9:programmering-i-naturfag', 'm07', 'flervalg', 'Hva er en modell i naturfag?', array['En person som poserer', 'En nøyaktig kopi av virkeligheten', 'En forenklet beskrivelse som hjelper oss å forstå og forutsi', 'Et forsøk']::text[], 2, 'Modeller forenkler virkeligheten slik at vi kan regne på den og forstå den.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-9:programmering-i-naturfag', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-9:programmering-i-naturfag', 's01', 'Forklar forskjellen mellom en modell og en simulering, og hvordan de henger sammen.', 'En modell er en forenklet beskrivelse av virkeligheten. En simulering er et program som bruker en modell til å etterligne en naturfaglig prosess etter bestemte regler.', array['Forklarer at en modell er en forenklet beskrivelse av virkeligheten.', 'Forklarer at en simulering er et program som bruker modellen til å etterligne en prosess.']::text[], 0),
  ('naturfag-9:programmering-i-naturfag', 's02', 'Du vil måle lysstyrken i et klasserom med en micro:bit. Forklar hva sensoren gjør, og hvilken oppgave micro:bit-en har.', 'Sensoren måler lysstyrken i klasserommet. Micro:bit-en leser av sensoren og kjører programmet som bruker målingen.', array['Forklarer at sensoren måler lysstyrken i omgivelsene.', 'Forklarer at micro:bit-en leser sensoren eller behandler målingen med programmet.']::text[], 1),
  ('naturfag-9:programmering-i-naturfag', 's03', 'Et program lagrer temperaturmålinger i en liste. Forklar hvordan lista kan brukes til å undersøke hvordan temperaturen endrer seg.', 'Lista kan lagre mange temperaturmålinger. Verdiene kan senere overføres til et regneark eller vises i en graf, slik at temperaturendringene blir lettere å se.', array['Forklarer at lista lagrer flere måleverdier.', 'Knytter bruk av verdiene til å vise eller undersøke endringer, for eksempel med en graf.']::text[], 2),
  ('naturfag-9:programmering-i-naturfag', 's04', 'Et program måler temperaturen én gang hvert minutt gjennom et døgn. Bruk at et døgn har 24 timer og en time har 60 minutter: Hvor mange målinger tar programmet? Vis det viktigste regnestykket.', 'Programmet tar 24 × 60 = 1440 målinger.', array['Bruker 24 timer og 60 minutter per time i utregningen.', 'Kommer fram til 1440 målinger.']::text[], 3),
  ('naturfag-9:programmering-i-naturfag', 's05', 'En simulering regner ett tidssteg for hvert 20. minutt. Hvor mange tidssteg regner den ut på én time? Vis det viktigste regnestykket.', 'Én time er 60 minutter, så 60 ÷ 20 = 3 tidssteg.', array['Bruker 60 minutter som lengden på én time og deler på 20.', 'Kommer fram til 3 tidssteg.']::text[], 4),
  ('naturfag-9:programmering-i-naturfag', 's06', 'Sammenlign en simulering av populasjonsvekst med en rovdyr–byttedyr-modell. Hva undersøker de hver for seg?', 'En simulering av populasjonsvekst undersøker hvordan antallet individer øker. En rovdyr–byttedyr-modell undersøker hvordan antallet rovdyr og byttedyr påvirker hverandre og svinger over tid.', array['Forklarer at populasjonsvekst handler om økning i antall individer.', 'Forklarer at rovdyr–byttedyr-modellen handler om hvordan antallet av de to påvirker hverandre.']::text[], 5),
  ('naturfag-9:programmering-i-naturfag', 's07', 'Forklar hva halveringstid betyr for mengden av et radioaktivt stoff.', 'Halveringstid er tiden det tar før halvparten av et radioaktivt stoff har brutt ned. Etter hver halveringstid er halvparten av mengden som var igjen, brutt ned.', array['Forklarer at halveringstid er tiden det tar før halvparten av stoffet brytes ned.', 'Viser at mengden blir halvert for hver halveringstid.']::text[], 6),
  ('naturfag-9:programmering-i-naturfag', 's08', 'En simulering av en naturfaglig prosess gir et annet resultat enn det som skjer i virkeligheten. Forklar hvordan modellens forenklinger kan være en årsak til forskjellen.', 'En modell forenkler virkeligheten, så den tar ikke nødvendigvis med alt som påvirker prosessen. Resultatet kan også avhenge av reglene og tallene som er lagt inn.', array['Knytter forskjellen til at modellen forenkler eller ikke beskriver hele virkeligheten.', 'Forklarer at reglene eller tallene modellen bygger på, påvirker resultatet.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-9:industrialisering-og-teknologi', 'samfunnsfag-9', 'industrialisering-og-teknologi', 'Industrialisering og teknologi', 'Hvordan den industrielle revolusjonen og senere teknologiske omveltninger har endret livet til enkeltmennesker, samfunnet og naturen, i verden og i Norge.', array[4]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-9:industrialisering-og-teknologi', '## Teknologi som endringsfaktor
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Den industrielle revolusjonen', 'Overgangen fra håndverk og jordbruk til fabrikkproduksjon, fra slutten av 1700-tallet.', 0),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Dampmaskinen', 'Maskin drevet av damp fra kullfyring. Forbedret av James Watt.', 1),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Fabrikk', 'Stor arbeidsplass der varer produseres med maskiner.', 2),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Urbanisering', 'At stadig flere flytter til og bor i byer.', 3),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Arbeiderklassen', 'Samfunnsgruppe som lever av å selge arbeidskraften sin, ofte i fabrikker.', 4),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Barnearbeid', 'At barn arbeider, vanlig i fabrikkene på 1800-tallet.', 5),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Luddittene', 'Engelske arbeidere som knuste maskiner i protest tidlig på 1800-tallet.', 6),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Hovedbanen', 'Norges første jernbane, mellom Christiania og Eidsvoll, åpnet i 1854.', 7),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Akerselva', 'Elv i Oslo der mange av de første norske fabrikkene lå.', 8),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Vannkraft', 'Elektrisitet fra fallende vann. Ga Norge et industrielt løft rundt 1900.', 9),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Norsk Hydro', 'Industriselskap grunnlagt i 1905, med fabrikker på Notodden og Rjukan.', 10),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Samlebånd', 'Produksjonsmetode der varen flyttes mellom arbeidere som gjør hver sin del.', 11),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Automatisering', 'At maskiner og datamaskiner gjør arbeid som mennesker gjorde før.', 12),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Digitalisering', 'At stadig mer av samfunnet foregår med digital teknologi.', 13),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'Fossile brensler', 'Kull, olje og gass. Gir klimagassutslipp når de brennes.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q01', 'flervalg', 'Hvor startet den industrielle revolusjonen?', array['Norge', 'Frankrike', 'Storbritannia', 'USA']::text[], 2, 'Storbritannia hadde kull, jern, kapital og arbeidskraft.', true, true, 0),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q02', 'flervalg', 'Hvilken oppfinnelse var sentral i den første industrielle revolusjonen?', array['Dampmaskinen', 'Datamaskinen', 'Telefonen', 'Flyet']::text[], 0, 'Dampmaskinen kunne drive fabrikker, tog og skip.', true, true, 1),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q03', 'flervalg', 'Hvorfor flyttet mange fra landsbygda til byene under industrialiseringen?', array['Fordi byene var renere', 'For å få arbeid i fabrikkene', 'Fordi jordbruk ble forbudt', 'Fordi boligene var gratis']::text[], 1, 'Fabrikkene trengte mange arbeidere.', true, true, 2),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q04', 'flervalg', 'Hvordan var arbeidsforholdene i de tidlige fabrikkene?', array['Korte dager og høy lønn', 'Barn fikk ikke jobbe', 'Trygge maskiner og ferie', 'Lange dager, lav lønn og farlige maskiner']::text[], 3, 'Det fantes få lover som beskyttet arbeiderne.', true, true, 3),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q05', 'flervalg', 'Hva ga Norge et stort industrielt løft rundt 1900?', array['Vannkraft og elektrisitet', 'Store kullgruver på Østlandet', 'Oljefunn', 'Datamaskiner']::text[], 0, 'Fossefallene ga billig strøm til kraftkrevende industri.', true, true, 4),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q06', 'flervalg', 'Når åpnet den første jernbanen i Norge?', array['1814', '1905', '1854', '1945']::text[], 2, 'Hovedbanen gikk mellom Christiania og Eidsvoll.', true, true, 5),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q07', 'flervalg', 'Hva er en negativ konsekvens for naturen av industrialiseringen?', array['Mer skog', 'Renere luft', 'Færre utslipp', 'Forurensning og økte klimagassutslipp']::text[], 3, 'Bruken av kull og olje har gitt store utslipp.', true, true, 6),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q08', 'flervalg', 'Hva betyr automatisering?', array['At folk jobber mer for hånd', 'At maskiner og datamaskiner gjør arbeid som mennesker gjorde før', 'At alle får egen bil', 'At fabrikker stenges']::text[], 1, 'Automatisering kan gjøre produksjonen billigere, men fjerne jobber.', true, true, 7),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q09', 'flervalg', 'Hvem var luddittene?', array['Oppfinnere av dampmaskinen', 'Fabrikkeiere', 'Arbeidere som knuste maskiner i protest', 'Norske politikere']::text[], 2, 'De var redde for at maskinene skulle ta arbeidet deres.', true, false, 8),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'q10', 'flervalg', 'Hvilket er et eksempel på den digitale revolusjonen?', array['Internett og smarttelefoner', 'Spinnemaskinen', 'Dampskipet', 'Hestevogna']::text[], 0, 'Digital teknologi har endret kommunikasjon, arbeid og fritid.', true, false, 9),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'm01', 'sant-usant', 'Samlebåndet gjorde det mulig å masseprodusere varer billigere.', array['Sant', 'Usant']::text[], 0, 'Hver arbeider gjorde en liten del, og produksjonen gikk mye raskere.', false, true, 10),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'm02', 'sant-usant', 'Teknologi har bare hatt positive konsekvenser for mennesker og natur.', array['Sant', 'Usant']::text[], 1, 'Teknologi har også gitt forurensning, farlig arbeid og tapte jobber.', false, true, 11),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'm03', 'sant-usant', 'Barnearbeid var vanlig i fabrikkene på 1800-tallet.', array['Sant', 'Usant']::text[], 0, 'Barn var billig arbeidskraft og jobbet ofte lange dager.', false, true, 12),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'm04', 'sant-usant', 'Norsk Hydro ble grunnlagt for å utvinne olje i Nordsjøen.', array['Sant', 'Usant']::text[], 1, 'Norsk Hydro ble grunnlagt i 1905 og brukte vannkraft til å lage kunstgjødsel.', false, true, 13),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'm05', 'flervalg', 'Hva brukte dampmaskinene som brensel?', array['Olje', 'Kull', 'Gass', 'Uran']::text[], 1, 'Derfor lå mange tidlige industriområder nær kullgruver.', false, true, 14),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'm06', 'flervalg', 'Hva er en mulig konsekvens av kunstig intelligens i arbeidslivet?', array['At noen yrker forsvinner og nye oppstår', 'At all teknologi stopper', 'At ingen trenger utdanning', 'At internett forsvinner']::text[], 0, 'Som tidligere teknologi endrer KI hvilke oppgaver mennesker gjør.', false, true, 15),
  ('samfunnsfag-9:industrialisering-og-teknologi', 'm07', 'flervalg', 'Hva kjennetegnet den andre industrielle revolusjonen rundt 1900?', array['Dampmaskin og tekstil', 'Internett og mobil', 'Hestekraft og vindmøller', 'Elektrisitet, olje og samlebånd']::text[], 3, 'Ny energi og nye produksjonsmetoder ga masseproduksjon.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-9:industrialisering-og-teknologi', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-9:industrialisering-og-teknologi', 's01', 'Hva menes med den industrielle revolusjonen? Forklar hva som endret seg i måten varer ble laget på.', 'Den industrielle revolusjonen var overgangen fra håndverk og jordbruk til fabrikkproduksjon. Maskiner gjorde det mulig å lage varer i fabrikker.', array['Forklarer overgangen fra håndverk og jordbruk til fabrikkproduksjon.', 'Får fram at maskiner og fabrikker endret produksjonen.']::text[], 0),
  ('samfunnsfag-9:industrialisering-og-teknologi', 's02', 'Dampmaskinen ble drevet av damp fra kullfyring. Forklar hvordan den gjorde det lettere å drive maskiner i fabrikker.', 'Kullfyring laget damp som kunne drive dampmaskinen. Dermed kunne maskiner drives med kull nesten hvor som helst.', array['Forklarer at kullfyring lager damp som driver maskinen.', 'Får fram at maskiner dermed kunne drives med kull nesten hvor som helst.']::text[], 1),
  ('samfunnsfag-9:industrialisering-og-teknologi', 's03', 'Sammenlign hvordan tekstiler ble laget før industrialiseringen, med hvordan de kunne lages etter at spinnemaskiner og vevstoler kom.', 'Før industrialiseringen ble varer laget for hånd. Spinnemaskiner og vevstoler gjorde det mulig å produsere tekstiler i store fabrikker.', array['Beskriver håndlaget produksjon før industrialiseringen.', 'Forklarer at maskinene gjorde stor tekstilproduksjon i fabrikker mulig.']::text[], 2),
  ('samfunnsfag-9:industrialisering-og-teknologi', 's04', 'Storbritannia hadde mye kull og jern, penger fra handel og kolonier, og en voksende befolkning som trengte arbeid. Forklar hvordan minst to av disse forholdene kunne hjelpe industrialiseringen.', 'Kull kunne brukes til å drive dampmaskiner, og jern var tilgjengelig til å lage maskiner. Penger fra handel og kolonier kunne brukes i industrien, mens en voksende befolkning ga tilgang på arbeidere.', array['Knytter kull eller jern til muligheter for maskiner og industri.', 'Forklarer hvordan penger fra handel og kolonier eller en voksende befolkning kunne støtte industrialiseringen.']::text[], 3),
  ('samfunnsfag-9:industrialisering-og-teknologi', 's05', 'Mange mennesker flyttet fra landsbygda til byene under industrialiseringen. Hva kalles denne utviklingen, og hvordan bodde mange av de nye byboerne?', 'Utviklingen kalles urbanisering. Mange bodde trangt og uhygienisk.', array['Identifiserer flytting og økt bosetting i byer som urbanisering.', 'Nevner at mange bodde trangt eller uhygienisk.']::text[], 4),
  ('samfunnsfag-9:industrialisering-og-teknologi', 's06', 'Hvordan gjorde jernbanen og dampskipet det enklere å frakte varer og mennesker?', 'Jernbanen og dampskipet gjorde transporten raskere og billigere. Dermed ble det enklere å flytte både varer og mennesker.', array['Forklarer at transporten ble raskere.', 'Forklarer at transporten ble billigere eller enklere for varer og mennesker.']::text[], 5),
  ('samfunnsfag-9:industrialisering-og-teknologi', 's07', 'På et samlebånd flyttes en vare mellom arbeidere som gjør hver sin del. Forklar hvordan denne måten å arbeide på kunne gjøre masseproduksjon billigere.', 'Hver arbeider gjør en del av arbeidet mens varen flyttes videre. Slik kunne mange varer produseres på en effektiv måte, noe som gjorde masseproduksjon billigere.', array['Forklarer at arbeiderne gjør hver sin del mens varen flyttes mellom dem.', 'Knytter arbeidsmåten til effektiv og billig masseproduksjon.']::text[], 6),
  ('samfunnsfag-9:industrialisering-og-teknologi', 's08', 'En fabrikk bruker kull, men vurderer å gå over til fornybar energi. Forklar hvordan dette kan påvirke utslippene og naturen.', 'Når kull brennes, slippes det ut klimagasser som bidrar til klimaendringer. Fornybar energi kan være en del av løsningen og redusere utslippene fra bruk av kull.', array['Forklarer at brenning av kull gir utslipp av klimagasser som bidrar til klimaendringer.', 'Får fram at fornybar energi kan bidra til å redusere miljøbelastningen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-9:kamp-for-endring', 'samfunnsfag-9', 'kamp-for-endring', 'Kamp for endring', 'Hvordan arbeidere, kvinner, urfolk og andre har kjempet for rettigheter og endringer i samfunnet, hvilke virkemidler de har brukt, og hvordan tid og sted har påvirket kampene.', array[5]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-9:kamp-for-endring', '## Mennesker skaper endring
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-9:kamp-for-endring', 'Arbeiderbevegelsen', 'Arbeidernes organisering i fagforeninger og partier for bedre kår.', 0),
  ('samfunnsfag-9:kamp-for-endring', 'Marcus Thrane', 'Samlet husmenn og arbeidere i Norges første arbeiderbevegelse rundt 1850.', 1),
  ('samfunnsfag-9:kamp-for-endring', 'LO', 'Landsorganisasjonen i Norge, paraplyorganisasjon for fagforeninger, stiftet i 1899.', 2),
  ('samfunnsfag-9:kamp-for-endring', 'Streik', 'At arbeidstakere legger ned arbeidet for å presse fram krav.', 3),
  ('samfunnsfag-9:kamp-for-endring', 'Åttetimersdagen', 'Lovfestet i Norge i 1919 etter krav fra arbeiderbevegelsen.', 4),
  ('samfunnsfag-9:kamp-for-endring', 'Hovedavtalen', 'Avtale fra 1935 om samarbeidet mellom arbeidsgivere og arbeidstakere.', 5),
  ('samfunnsfag-9:kamp-for-endring', 'Norsk Kvinnesaksforening', 'Stiftet i 1884 for å kjempe for kvinners rettigheter.', 6),
  ('samfunnsfag-9:kamp-for-endring', 'Kvinners stemmerett', 'Norske kvinner fikk allmenn stemmerett i 1913.', 7),
  ('samfunnsfag-9:kamp-for-endring', 'Borgerrettighetsbevegelsen', 'Kamp mot raseskille og for like rettigheter i USA på 1950- og 60-tallet.', 8),
  ('samfunnsfag-9:kamp-for-endring', 'Apartheid', 'System med raseskille i Sør-Afrika, avviklet tidlig på 1990-tallet.', 9),
  ('samfunnsfag-9:kamp-for-endring', 'Nelson Mandela', 'Satt 27 år i fengsel og ble Sør-Afrikas første svarte president i 1994.', 10),
  ('samfunnsfag-9:kamp-for-endring', 'Alta-saken', 'Protester 1979–1981 mot utbyggingen av Altaelva.', 11),
