insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('utdanningsvalg-9:utdanningssystemet', 'q01', 'flervalg', 'Hvor mange utdanningsprogram finnes det i videregående?', array['Ti', 'Femten', 'Fem', 'Tjue']::text[], 1, 'Fem studieforberedende og ti yrkesfaglige.', true, true, 0),
  ('utdanningsvalg-9:utdanningssystemet', 'q02', 'flervalg', 'Hvilket av disse er et studieforberedende utdanningsprogram?', array['Idrettsfag', 'Naturbruk', 'Elektro og datateknologi', 'Helse- og oppvekstfag']::text[], 0, 'De andre er yrkesfaglige program.', true, true, 1),
  ('utdanningsvalg-9:utdanningssystemet', 'q03', 'flervalg', 'Hva gir generell studiekompetanse?', array['Fagbrev alene', 'Ungdomsskolen', 'Rett til å søke universitet og høyskole', 'En lærlingplass']::text[], 2, 'Den får du etter et studieforberedende program eller påbygging.', true, true, 2),
  ('utdanningsvalg-9:utdanningssystemet', 'q04', 'flervalg', 'Hvor lang tid tar en bachelorgrad vanligvis?', array['Ett år', 'Fem år', 'Åtte år', 'Tre år']::text[], 3, 'En mastergrad tar vanligvis to år i tillegg.', true, true, 3),
  ('utdanningsvalg-9:utdanningssystemet', 'q05', 'flervalg', 'Hva er påbygging?', array['Et ekstra år etter yrkesfag som gir generell studiekompetanse', 'Å bygge et tilbygg på skolen', 'Et utdanningsprogram på ungdomsskolen', 'En type lærekontrakt']::text[], 0, 'Påbygging åpner veien til høyere utdanning.', true, true, 4),
  ('utdanningsvalg-9:utdanningssystemet', 'q06', 'flervalg', 'Hva er spesiell studiekompetanse?', array['Det samme som fagbrev', 'Krav om bestemte fag for å komme inn på enkelte studier', 'Karakterer fra ungdomsskolen', 'En bachelorgrad']::text[], 1, 'For eksempel krav til matematikk og fysikk for ingeniørstudier.', true, true, 5),
  ('utdanningsvalg-9:utdanningssystemet', 'q07', 'flervalg', 'Hvor finner du oversikt over utdanningsprogrammene i videregående?', array['Yr.no', 'Finn.no', 'Vilbli.no', 'Nrk.no']::text[], 2, 'Vilbli.no viser alle veier gjennom videregående.', true, true, 6),
  ('utdanningsvalg-9:utdanningssystemet', 'q08', 'flervalg', 'Hvor mange år er grunnskolen i Norge?', array['Sju', 'Tolv', 'Ni', 'Ti']::text[], 3, 'Barneskole 1.–7. og ungdomsskole 8.–10.', true, true, 7),
  ('utdanningsvalg-9:utdanningssystemet', 'q09', 'flervalg', 'Hvorfor bør du være kildekritisk når du leser om skoler og utdanninger?', array['Fordi informasjonen ofte er markedsføring', 'Fordi all informasjon er feil', 'Fordi rådgiveren sier det', 'Det er ikke nødvendig']::text[], 0, 'Sjekk flere kilder før du bestemmer deg.', true, false, 8),
  ('utdanningsvalg-9:utdanningssystemet', 'q10', 'flervalg', 'Hva er en fagskole?', array['En ungdomsskole', 'En barneskole', 'Høyere yrkesfaglig utdanning', 'Et universitet']::text[], 2, 'Fagskoler gir kortere, praktiske utdanninger.', true, false, 9),
  ('utdanningsvalg-9:utdanningssystemet', 'm01', 'sant-usant', 'Medier og kommunikasjon er et studieforberedende utdanningsprogram.', array['Sant', 'Usant']::text[], 0, 'Programmet ble studieforberedende med fagfornyelsen.', false, true, 10),
  ('utdanningsvalg-9:utdanningssystemet', 'm02', 'sant-usant', 'Med fagbrev er det umulig å bli ingeniør.', array['Sant', 'Usant']::text[], 1, 'Y-veien og påbygging gir muligheter videre.', false, true, 11),
  ('utdanningsvalg-9:utdanningssystemet', 'm03', 'sant-usant', 'På Vg2 og Vg3 spesialiserer man seg mer enn på Vg1.', array['Sant', 'Usant']::text[], 0, 'Da velger man programfag eller et bestemt yrkesfag.', false, true, 12),
  ('utdanningsvalg-9:utdanningssystemet', 'm04', 'sant-usant', 'Barnehage er obligatorisk i Norge.', array['Sant', 'Usant']::text[], 1, 'Barnehage er frivillig. Grunnskolen er obligatorisk.', false, true, 13),
  ('utdanningsvalg-9:utdanningssystemet', 'm05', 'flervalg', 'Hvor lenge varer en mastergrad vanligvis etter bachelor?', array['Ett år', 'Tre år', 'Fem år', 'To år']::text[], 3, 'Bachelor tre år pluss master to år er til sammen fem år.', false, true, 14),
  ('utdanningsvalg-9:utdanningssystemet', 'm06', 'flervalg', 'Hva er programfag?', array['Fag man velger for å fordype seg', 'Fag på ungdomsskolen', 'Fag som alle må ha', 'Fag på universitetet']::text[], 0, 'For eksempel fysikk eller rettslære på studiespesialisering.', false, true, 15),
  ('utdanningsvalg-9:utdanningssystemet', 'm07', 'flervalg', 'Hva betyr hospitering?', array['Å være på sykehus', 'Å besøke en skole eller arbeidsplass for å prøve den', 'Å ta en eksamen', 'Å søke jobb']::text[], 1, 'Hospitering gir et inntrykk av hvordan det er i praksis.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('utdanningsvalg-9:utdanningssystemet', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('utdanningsvalg-9:utdanningssystemet', 's01', 'De fleste yrkesfag følger 2 + 2-modellen. Forklar hva eleven gjør de to første årene, og hva som skjer de to neste årene.', 'Eleven går først to år på skole. Deretter er eleven lærling i en bedrift i to år.', array['Får med at de to første årene er på skole.', 'Får med at de to neste årene er som lærling i en bedrift.']::text[], 0),
  ('utdanningsvalg-9:utdanningssystemet', 's02', 'Sammenlign studieforberedende og yrkesfaglige utdanningsprogram når det gjelder hva slags kompetanse eller muligheter de gir etter videregående.', 'Et studieforberedende program varer i tre år og gir generell studiekompetanse. Yrkesfag kan gi fagbrev, svennebrev eller yrkeskompetanse.', array['Knytter studieforberedende program til generell studiekompetanse.', 'Knytter yrkesfag til fagbrev, svennebrev eller yrkeskompetanse.']::text[], 1),
  ('utdanningsvalg-9:utdanningssystemet', 's03', 'På Vg1 har elever på samme utdanningsprogram mye felles. Forklar hvordan opplæringen kan endre seg på Vg2 og Vg3.', 'På Vg2 og Vg3 spesialiserer elevene seg mer. De kan for eksempel velge programfag på studiespesialisering eller et bestemt fag på yrkesfag.', array['Forklarer at elevene spesialiserer seg mer på Vg2 og Vg3.', 'Gir et relevant eksempel, som valg av programfag eller et bestemt yrkesfag.']::text[], 2),
  ('utdanningsvalg-9:utdanningssystemet', 's04', 'Noah går yrkesfag, men ønsker senere å søke universitet eller høyskole. Forklar en vei han kan ta for å få generell studiekompetanse.', 'Noah kan ta påbygging etter yrkesfag. Påbygging gir generell studiekompetanse, som gir rett til å søke universitet og høyskole.', array['Foreslår påbygging etter yrkesfag.', 'Knytter generell studiekompetanse til retten til å søke universitet eller høyskole.']::text[], 3),
  ('utdanningsvalg-9:utdanningssystemet', 's05', 'Sara har fagbrev og vil bli ingeniør. Hvilken mulighet i utdanningssystemet kan hun undersøke, og hva åpner den for?', 'Sara kan undersøke Y-veien. Den gir personer med fagbrev mulighet til å bli ingeniør.', array['Nevner Y-veien.', 'Forklarer at den gir personer med fagbrev mulighet til å bli ingeniør.']::text[], 4),
  ('utdanningsvalg-9:utdanningssystemet', 's06', 'En elev vurderer en videregående skole og vil prøve ut hvordan det er å være der før hun bestemmer seg. Forklar hva hospitering er, og hvordan det kan hjelpe eleven.', 'Hospitering er å besøke en skole eller arbeidsplass for å prøve den. Eleven kan for eksempel besøke en videregående skole for å få et inntrykk av den.', array['Forklarer at hospitering innebærer å besøke en skole eller arbeidsplass for å prøve den.', 'Knytter besøket til at eleven kan få erfaring eller et inntrykk før hun velger.']::text[], 5),
  ('utdanningsvalg-9:utdanningssystemet', 's07', 'Forklar rekkefølgen fra bachelorgrad til ph.d., og hvor lang tid hvert av disse stegene vanligvis tar.', 'En bachelorgrad tar vanligvis tre år. Etter den kan man ta en mastergrad, som vanligvis tar to år, og deretter en ph.d., som vanligvis tar tre år etter mastergraden.', array['Plasserer mastergrad etter bachelorgrad og ph.d. etter mastergrad.', 'Oppgir vanlig varighet: bachelor tre år, master to år og ph.d. tre år etter master.']::text[], 6),
  ('utdanningsvalg-9:utdanningssystemet', 's08', 'Grunnskolen varer i ti år og er obligatorisk. Alle som har fullført grunnskolen, har rett til videregående opplæring. Forklar forskjellen på plikten til grunnskole og retten til videregående.', 'Barn har både rett og plikt til å gå på grunnskolen i ti år. Etter at grunnskolen er fullført, har man rett til videregående opplæring.', array['Forklarer at grunnskolen er obligatorisk, altså både en rett og en plikt.', 'Forklarer at retten til videregående gjelder etter fullført grunnskole.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'utdanningsvalg-9', 'arbeidslivet-i-endring', 'Arbeidslivet i endring', 'Næringer og sektorer i norsk arbeidsliv, hvordan konjunkturer påvirker jobbmulighetene, teknologi og kunstig intelligens, globalisering, det grønne skiftet og behovet for livslang læring.', array[4]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('utdanningsvalg-9:arbeidslivet-i-endring', '## Næringer
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Primærnæringer', 'Næringer som henter ressurser fra naturen: jordbruk, skogbruk og fiske.', 0),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Sekundærnæringer', 'Næringer som bearbeider råvarer: industri og bygg og anlegg.', 1),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Tertiærnæringer', 'Tjenesteytende næringer, som helse, handel og IT.', 2),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Offentlig sektor', 'Stat, fylker og kommuner, som skoler og sykehus.', 3),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Privat sektor', 'Bedrifter eid av private som skal tjene penger.', 4),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Konjunkturer', 'Svingninger i økonomien mellom gode og dårlige tider.', 5),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Høykonjunktur', 'Gode tider med høyt salg og lav arbeidsledighet.', 6),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Lavkonjunktur', 'Dårlige tider med lavere salg og økende arbeidsledighet.', 7),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Arbeidsledighet', 'At personer som ønsker å jobbe, ikke har arbeid.', 8),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Permittering', 'Midlertidig fritak fra arbeid når bedriften har for lite å gjøre.', 9),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Automatisering', 'At maskiner overtar oppgaver som mennesker gjorde før.', 10),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Kunstig intelligens (KI)', 'Teknologi som lar datamaskiner utføre oppgaver som krever en slags intelligens.', 11),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Globalisering', 'At landene knyttes tettere sammen gjennom handel og kommunikasjon.', 12),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Det grønne skiftet', 'Overgangen til et samfunn med lavere klimagassutslipp.', 13),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'Livslang læring', 'Å lære nye ting gjennom hele yrkeslivet.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q01', 'flervalg', 'Hvilken næring er fiske?', array['Sekundærnæring', 'Primærnæring', 'Tertiærnæring', 'Offentlig sektor']::text[], 1, 'Primærnæringer henter ressurser direkte fra naturen.', true, true, 0),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q02', 'flervalg', 'Hva kjennetegner en høykonjunktur?', array['Høy arbeidsledighet', 'Mange konkurser', 'Høyt salg og lav arbeidsledighet', 'At alle blir permittert']::text[], 2, 'I høykonjunktur trenger bedriftene flere ansatte.', true, true, 1),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q03', 'flervalg', 'Hvor jobber de fleste i Norge i dag?', array['I tjenesteytende næringer', 'I jordbruket', 'I fisket', 'I gruvedrift']::text[], 0, 'Helse, handel, skole og IT er eksempler.', true, true, 2),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q04', 'flervalg', 'Hva er automatisering?', array['At folk jobber mer', 'At bilene blir større', 'At bedrifter flytter til utlandet', 'At maskiner overtar oppgaver mennesker gjorde før']::text[], 3, 'Automatisering endrer mange yrker.', true, true, 3),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q05', 'flervalg', 'Hva er det grønne skiftet?', array['At alle maler husene grønne', 'Overgangen til et samfunn med lavere klimagassutslipp', 'En ny type skift på jobb', 'At man bare spiser grønnsaker']::text[], 1, 'Det grønne skiftet gir nye jobber innen blant annet fornybar energi.', true, true, 4),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q06', 'flervalg', 'Hva er et eksempel på offentlig sektor?', array['En frisørsalong', 'En dagligvarebutikk', 'Et sykehus', 'En restaurant']::text[], 2, 'Offentlig sektor drives av stat, fylker og kommuner.', true, true, 5),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q07', 'flervalg', 'Hvorfor bør du tenke langsiktig når du velger utdanning?', array['Fordi en utdanning tar flere år og konjunkturene endrer seg', 'Fordi arbeidslivet aldri endrer seg', 'Fordi alle jobber forsvinner', 'Det er ikke nødvendig']::text[], 0, 'Det som gjelder i dag, kan være annerledes når du er ferdig.', true, true, 6),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q08', 'flervalg', 'Hva er permittering?', array['At man får fast jobb', 'At man får lønnsøkning', 'At man blir forfremmet', 'Midlertidig fritak fra arbeid når bedriften har for lite å gjøre']::text[], 3, 'Permitteringer er vanlige i lavkonjunkturer.', true, true, 7),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q09', 'flervalg', 'Hva betyr globalisering for arbeidslivet?', array['At alle må flytte til utlandet', 'At norske bedrifter konkurrerer med bedrifter i hele verden', 'At handel stopper opp', 'At ingen jobber i Norge']::text[], 1, 'Noen jobber flyttes ut, mens andre oppstår.', true, false, 8),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'q10', 'flervalg', 'Hvilke egenskaper blir viktigere i framtidens arbeidsliv?', array['Å gjøre det samme hele livet', 'Å jobbe alene uten å samarbeide', 'Samarbeid, problemløsning og digitale ferdigheter', 'Å unngå ny teknologi']::text[], 2, 'Endringer krever evne til å lære og tilpasse seg.', true, false, 9),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'm01', 'sant-usant', 'Ny teknologi kan både fjerne gamle jobber og skape nye.', array['Sant', 'Usant']::text[], 0, 'Dataingeniør og droneoperatør er eksempler på nye yrker.', false, true, 10),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'm02', 'sant-usant', 'Industri er en primærnæring.', array['Sant', 'Usant']::text[], 1, 'Industri er en sekundærnæring.', false, true, 11),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'm03', 'sant-usant', 'I lavkonjunktur øker ofte arbeidsledigheten.', array['Sant', 'Usant']::text[], 0, 'Bedriftene selger mindre og trenger færre ansatte.', false, true, 12),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'm04', 'sant-usant', 'Etter at man er ferdig utdannet, trenger man aldri å lære noe nytt.', array['Sant', 'Usant']::text[], 1, 'Arbeidslivet endrer seg, så livslang læring er nødvendig.', false, true, 13),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'm05', 'flervalg', 'Hvilket yrke har endret seg på grunn av elbiler?', array['Bilmekaniker', 'Frisør', 'Baker', 'Barnehagelærer']::text[], 0, 'Bilmekanikere jobber nå mye med elektronikk og programvare.', false, true, 14),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'm06', 'flervalg', 'Hvilken sektor har ansvar for grunnskolen?', array['Privat sektor', 'Primærnæringen', 'Industrien', 'Offentlig sektor']::text[], 3, 'Kommunene driver grunnskolene.', false, true, 15),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 'm07', 'flervalg', 'Hvilket område gir nye jobber i det grønne skiftet?', array['Kullgruver', 'Fornybar energi', 'Engangsplast', 'Oljefyring']::text[], 1, 'Også gjenvinning og energieffektive bygg gir nye jobber.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('utdanningsvalg-9:arbeidslivet-i-endring', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('utdanningsvalg-9:arbeidslivet-i-endring', 's01', 'En gård dyrker korn, en fabrikk lager matvarer av råvarer, og et sykehus gir helsehjelp. Hvilken type næring hører hvert sted til? Forklar kort hva som skiller næringene.', 'Gården hører til primærnæringene, fabrikken til sekundærnæringene og sykehuset til tertiærnæringene. Primærnæringer henter ressurser fra naturen, sekundærnæringer bearbeider råvarer, og tertiærnæringer yter tjenester.', array['Plasserer gården, fabrikken og sykehuset riktig i hver sin næringstype.', 'Forklarer skillet mellom å hente ressurser fra naturen, bearbeide råvarer og yte tjenester.']::text[], 0),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 's02', 'En kommunal skole og et privat eid firma tilhører ulike sektorer. Sammenlign hvem som eier dem, og hva som kjennetegner formålet med det private firmaet.', 'Skolen tilhører offentlig sektor, som omfatter blant annet kommunene. Firmaet tilhører privat sektor fordi det eies privat, og det skal tjene penger.', array['Knytter offentlig sektor til stat, fylker eller kommuner og privat sektor til privat eierskap.', 'Får fram at private bedrifter skal tjene penger.']::text[], 1),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 's03', 'I en lavkonjunktur faller salget i mange bedrifter. Forklar hvordan dette kan påvirke ansatte og arbeidsledigheten.', 'Når bedriftene selger mindre, kan de få for lite å gjøre og permittere ansatte eller la noen miste jobben. Da kan arbeidsledigheten øke.', array['Knytter lavere salg til at bedrifter kan få mindre arbeid eller behov for færre ansatte.', 'Forklarer at permitteringer eller tap av jobb kan føre til økt arbeidsledighet.']::text[], 2),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 's04', 'Dataingeniør er et eksempel på et nytt yrke. En bilmekaniker som arbeider med elbiler og datamaskiner, har et yrke som har endret innhold. Forklar forskjellen mellom de to utviklingene.', 'Et nytt yrke oppstår, slik dataingeniør har gjort. Når bilmekanikerens arbeid endres, er det et eksisterende yrke som får nye oppgaver eller metoder.', array['Forklarer at det ene handler om at et nytt yrke oppstår.', 'Forklarer at det andre handler om at arbeidsinnholdet i et eksisterende yrke endres.']::text[], 3),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 's05', 'Et byggfirma vil bidra til lavere klimagassutslipp ved å bygge mer energieffektive bygg. En ansatt må lære nye metoder. Forklar hvordan dette henger sammen med det grønne skiftet.', 'Det grønne skiftet er overgangen til et samfunn med lavere klimagassutslipp. Energieffektive bygg kan bidra til denne overgangen, og derfor må ansatte i noen yrker lære nye metoder.', array['Knytter det grønne skiftet til lavere klimagassutslipp.', 'Forklarer at behovet for energieffektive bygg kan gjøre at ansatte må lære nye metoder.']::text[], 4),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 's06', 'En helsefagarbeider må lære å bruke velferdsteknologi som en del av jobben. Forklar hva livslang læring betyr, og hvorfor det er relevant for helsefagarbeideren.', 'Livslang læring betyr å lære nye ting gjennom hele yrkeslivet. Det er relevant fordi arbeidsoppgaver og metoder kan endres, slik at helsefagarbeideren må lære å bruke ny teknologi.', array['Forklarer at livslang læring er å lære nye ting gjennom hele yrkeslivet.', 'Knytter læringen til at yrker eller arbeidsmetoder endres, for eksempel bruk av velferdsteknologi.']::text[], 5),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 's07', 'Forklar med egne ord hva kunstig intelligens (KI) er, og hva slags oppgaver KI-teknologi lar datamaskiner utføre.', 'Kunstig intelligens er teknologi som gjør at datamaskiner kan utføre oppgaver som krever en slags intelligens. Det handler altså om mer enn at en maskin bare følger en enkel fysisk bevegelse.', array['Får fram at KI er teknologi som brukes i datamaskiner.', 'Forklarer at teknologien lar datamaskiner utføre oppgaver som krever en slags intelligens.']::text[], 6),
  ('utdanningsvalg-9:arbeidslivet-i-endring', 's08', 'En elev tror at framtidens arbeidsliv bare vil trenge folk med høyere utdanning. Bruk kunnskap om framtidens kompetanse til å rette påstanden: Hvilke to hovedgrupper arbeidstakere trengs, og hvilket område ventes å ha stort behov for arbeidskraft?', 'Arbeidslivet trenger både fagarbeidere og folk med høyere utdanning. Det ventes blant annet stort behov for arbeidskraft i helse og omsorg.', array['Nevner både fagarbeidere og personer med høyere utdanning.', 'Nevner helse og omsorg som et område med stort behov for arbeidskraft.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'utdanningsvalg-9', 'kjonn-og-karrierevalg', 'Kjønn og karrierevalg', 'Det kjønnsdelte arbeidsmarkedet i Norge, hvorfor jenter og gutter ofte velger ulikt, lønnsforskjeller og deltid, likestillingsloven og hvordan du kan ta valg uten å styres av stereotypier.', array[7]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('utdanningsvalg-9:kjonn-og-karrierevalg', '## Et kjønnsdelt arbeidsmarked
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Kjønnsdelt arbeidsmarked', 'At mange yrker domineres av ett kjønn.', 0),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Kjønnsstereotypi', 'Forestilling om hva som er typisk for jenter og gutter.', 1),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Rollemodell', 'En person andre ser opp til og lar seg inspirere av.', 2),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Utradisjonelt valg', 'Å velge et yrke der det er få av ens eget kjønn.', 3),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Likestilling', 'At kvinner og menn har like rettigheter, plikter og muligheter.', 4),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Lønnsforskjell', 'Forskjellen mellom gjennomsnittslønnen til kvinner og menn.', 5),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Deltid', 'Å jobbe mindre enn full stilling.', 6),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Likestillings- og diskrimineringsloven', 'Lov som forbyr diskriminering, blant annet på grunn av kjønn.', 7),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Likestillings- og diskrimineringsombudet', 'Offentlig organ som gir veiledning om diskriminering.', 8),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Diskrimineringsnemnda', 'Organ som behandler klager om diskriminering.', 9),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Aktivitetsplikt', 'Arbeidsgiveres plikt til å jobbe aktivt for likestilling.', 10),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Kjønnspoeng', 'Ekstra poeng til det underrepresenterte kjønnet ved opptak til enkelte studier.', 11),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Mangfold', 'At ulike mennesker med ulik bakgrunn jobber sammen.', 12),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Kvinnedominert yrke', 'Yrke der de fleste er kvinner, som sykepleier.', 13),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'Mannsdominert yrke', 'Yrke der de fleste er menn, som elektriker.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q01', 'flervalg', 'Hva betyr det at arbeidsmarkedet er kjønnsdelt?', array['At kvinner og menn jobber på ulike dager', 'At mange yrker domineres av ett kjønn', 'At lønna er lik for alle', 'At menn og kvinner ikke får jobbe sammen']::text[], 1, 'Norge har et av de mest kjønnsdelte arbeidsmarkedene i Europa, selv om landet regnes som likestilt.', true, true, 0),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q02', 'flervalg', 'Hvilket utdanningsprogram har flest jenter?', array['Elektro og datateknologi', 'Bygg- og anleggsteknikk', 'Teknologi- og industrifag', 'Helse- og oppvekstfag']::text[], 3, 'De tekniske programmene har flest gutter.', true, true, 1),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q03', 'flervalg', 'Hva er et utradisjonelt valg?', array['Å velge et yrke der det er få av ditt kjønn', 'Å velge det samme som foreldrene', 'Å ikke velge noe', 'Å velge den korteste utdanningen']::text[], 0, 'For eksempel en gutt som blir helsefagarbeider.', true, true, 2),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q04', 'flervalg', 'Hvilken lov forbyr diskriminering på grunn av kjønn?', array['Opplæringsloven', 'Ferieloven', 'Likestillings- og diskrimineringsloven', 'Vegtrafikkloven']::text[], 2, 'Loven gjelder blant annet ved ansettelse og lønn.', true, true, 3),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q05', 'flervalg', 'Hvorfor tjener kvinner i gjennomsnitt mindre enn menn?', array['Fordi de er dårligere', 'Blant annet fordi mange kvinnedominerte yrker har lavere lønn og flere kvinner jobber deltid', 'Fordi loven sier det', 'Det gjør de ikke']::text[], 1, 'Lønnsforskjellene har flere årsaker.', true, true, 4),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q06', 'flervalg', 'Hva er en kjønnsstereotypi?', array['En forestilling om hva som er typisk for jenter og gutter', 'En type musikkanlegg', 'En lov', 'Et yrke']::text[], 0, 'Stereotypier kan begrense valgene våre.', true, true, 5),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q07', 'flervalg', 'Hvordan kan rollemodeller påvirke yrkesvalg?', array['De har ingen betydning', 'De bestemmer valget for deg', 'De gjør det lettere å se for seg et yrke man ellers ikke ville vurdert', 'De gjør alle yrker like']::text[], 2, 'Det er lettere å velge noe når man ser at andre som ligner en, har gjort det.', true, true, 6),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q08', 'flervalg', 'Hvorfor er det et problem for samfunnet at arbeidsmarkedet er kjønnsdelt?', array['Det er ikke et problem', 'Det gir for mange arbeidere', 'Det gjør alle yrker like', 'Samfunnet går glipp av talenter og får mangel på arbeidskraft i noen yrker']::text[], 3, 'Det trengs for eksempel flere menn i helse og omsorg.', true, true, 7),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q09', 'flervalg', 'Hva er kjønnspoeng?', array['Ekstra poeng til det underrepresenterte kjønnet ved opptak til enkelte studier', 'Poeng i gym', 'Poeng for å være gutt', 'En karakter']::text[], 0, 'Tiltaket skal gi en jevnere kjønnsbalanse.', true, false, 8),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'q10', 'flervalg', 'Hva er et godt spørsmål å stille seg når man velger utdanning?', array['Hva velger alle vennene mine?', 'Hadde jeg valgt annerledes hvis jeg hadde vært av et annet kjønn?', 'Hva er mest populært på sosiale medier?', 'Hva er den korteste utdanningen?']::text[], 1, 'Spørsmålet kan avsløre om stereotypier styrer valget.', true, false, 9),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'm01', 'sant-usant', 'Flere kvinner enn menn jobber deltid i Norge.', array['Sant', 'Usant']::text[], 0, 'Deltid gir lavere inntekt og pensjon.', false, true, 10),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'm02', 'sant-usant', 'Det er lov å la være å ansette noen fordi de er kvinne.', array['Sant', 'Usant']::text[], 1, 'Likestillings- og diskrimineringsloven forbyr dette.', false, true, 11),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'm03', 'sant-usant', 'Det er nå flere kvinner enn menn i høyere utdanning i Norge.', array['Sant', 'Usant']::text[], 0, 'Kvinner er i flertall blant studentene.', false, true, 12),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'm04', 'sant-usant', 'Interesser er medfødte og påvirkes ikke av hva vi har fått prøve.', array['Sant', 'Usant']::text[], 1, 'Interesser formes også av erfaringer og forventninger.', false, true, 13),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'm05', 'flervalg', 'Hvem behandler klager om diskriminering?', array['Politiet', 'Rådgiveren', 'Diskrimineringsnemnda', 'Kommunestyret']::text[], 2, 'Ombudet gir veiledning, og nemnda behandler klager.', false, true, 14),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'm06', 'flervalg', 'Hvilket yrke er i dag mannsdominert?', array['Sykepleier', 'Elektriker', 'Barnehagelærer', 'Frisør']::text[], 1, 'De andre yrkene er kvinnedominerte.', false, true, 15),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 'm07', 'flervalg', 'Hva er en fordel med mangfold på arbeidsplassen?', array['Det gir ofte bedre løsninger og arbeidsmiljø', 'Det gir lavere lønn', 'Det gjør alle like', 'Det gir færre ansatte']::text[], 0, 'Ulike perspektiver kan gi bedre løsninger.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 's01', 'En arbeidstaker jobber mindre enn full stilling. Hva kalles det, og hvordan kan det påvirke inntekt og pensjon?', 'Det kalles deltid. Deltid kan gi lavere inntekt og pensjon.', array['Forklarer at deltid betyr å jobbe mindre enn full stilling.', 'Nevner at deltid kan gi lavere inntekt og pensjon.']::text[], 0),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 's02', 'En person vil først få veiledning om diskriminering og vurderer senere å klage. Hvilket organ gir veiledning, og hvilket behandler klager?', 'Likestillings- og diskrimineringsombudet gir veiledning. Diskrimineringsnemnda behandler klager.', array['Knytter veiledning til Likestillings- og diskrimineringsombudet.', 'Knytter behandling av klager til Diskrimineringsnemnda.']::text[], 1),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 's03', 'En elevs familie sier at teknologi passer best for gutter, og reklamer viser ofte menn i teknologiyrker. Forklar hvordan dette kan påvirke jenters utdannings- og yrkesvalg.', 'Forventninger fra familien og kjønnet framstilling i reklame kan få jenter til å tenke at teknologi ikke passer for dem. Da kan færre jenter vurdere teknologifag og teknologiyrker.', array['Forklarer at familieforventninger og/eller reklame kan påvirke hva jenter oppfatter som passende.', 'Knytter påvirkningen til at færre jenter kan vurdere teknologi.']::text[], 2),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 's04', 'En gutt vurderer helse og omsorg, men er redd for å bli den eneste gutten i klassen. Forklar hvordan denne frykten kan påvirke valget hans, og hvordan det å få prøve fagområdet kan påvirke interessene hans.', 'Frykten for å skille seg ut kan få ham til å velge bort helse og omsorg selv om han er interessert. Når han får prøve fagområdet, kan han oppdage interesser han ikke visste at han hadde.', array['Forklarer at frykten for å skille seg ut kan føre til at han velger bort fagområdet.', 'Forklarer at interesser også kan formes av hva man får prøve.']::text[], 3),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 's05', 'En mann velger å bli helsefagarbeider. Hvorfor kan det regnes som et utradisjonelt valg, og hvilken utfordring i arbeidslivet kan flere slike valg bidra til å møte?', 'Det er et utradisjonelt valg fordi det er få menn i helse og omsorg. Flere menn i slike yrker kan bidra til å møte mangelen på arbeidskraft.', array['Forklarer at valget er utradisjonelt fordi få menn jobber i helse og omsorg.', 'Knytter flere slike valg til behovet for arbeidskraft.']::text[], 4),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 's06', 'En elev mener at det er jevn kjønnsfordeling på alle utdanninger fordi det er flere kvinner enn menn i høyere utdanning. Bruk mønsteret på videregående til å forklare hvorfor påstanden ikke stemmer.', 'På videregående er det flest jenter på helse- og oppvekstfag, mens det er flest gutter på blant annet elektro og datateknologi. At det er flere kvinner enn menn i høyere utdanning, betyr derfor ikke at alle utdanningsvalg har jevn kjønnsfordeling.', array['Nevner at helse- og oppvekstfag har flest jenter, og at minst ett av de andre nevnte utdanningsprogrammene har flest gutter.', 'Forklarer at flere kvinner enn menn i høyere utdanning ikke betyr at alle utdanninger har jevn kjønnsfordeling.']::text[], 5),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 's07', 'Hva betyr mangfold på en arbeidsplass, og nevn én fordel mangfold kan gi?', 'Mangfold betyr at ulike mennesker med ulik bakgrunn jobber sammen. Det kan ofte gi bedre løsninger eller et bedre arbeidsmiljø.', array['Forklarer at mangfold innebærer at ulike mennesker med ulik bakgrunn jobber sammen.', 'Nevner bedre løsninger eller bedre arbeidsmiljø som en mulig fordel.']::text[], 6),
  ('utdanningsvalg-9:kjonn-og-karrierevalg', 's08', 'En arbeidsgiver mener at det er nok å la være å diskriminere, og at arbeidsgiveren ikke trenger å gjøre noe mer for likestilling. Rett påstanden ved å forklare aktivitetsplikten.', 'Aktivitetsplikt betyr at arbeidsgivere har plikt til å jobbe aktivt for likestilling. Det innebærer mer enn bare å la være å diskriminere.', array['Forklarer at arbeidsgivere har plikt til å jobbe aktivt for likestilling.', 'Får fram at plikten innebærer mer enn bare å unngå diskriminering.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-10:litteraturhistorie', 'norsk-10', 'litteraturhistorie', 'Litteraturhistorie i korte trekk', 'De store epokene i norsk litteratur – fra norrøn tid og folkediktning via romantikk og realisme til modernisme – og hvordan tekster henger sammen med tiden de ble skrevet i.', array[2, 1]::int[], 0, 'utkast', array['Årstallene for epokene er omtrentlige og varierer mellom læreverk.']::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-10:litteraturhistorie', '## Hvorfor litteraturhistorie?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-10:litteraturhistorie', 'Epoke', 'En periode i litteraturhistorien med felles trekk, som romantikken eller realismen.', 0),
  ('norsk-10:litteraturhistorie', 'Norrøn tid', 'Ca. 800–1350. Eddadikt, skaldedikt og sagaer.', 1),
  ('norsk-10:litteraturhistorie', 'Snorre Sturlason', 'Islandsk forfatter som skrev kongesagaene i Heimskringla på 1200-tallet.', 2),
  ('norsk-10:litteraturhistorie', 'Folkediktning', 'Muntlig overlevert diktning: eventyr, sagn, folkeviser og ordtak.', 3),
  ('norsk-10:litteraturhistorie', 'Asbjørnsen og Moe', 'Samlet og ga ut norske folkeeventyr fra 1841.', 4),
  ('norsk-10:litteraturhistorie', 'Romantikken', 'Ca. 1800–1850. Følelser, fantasi, natur og interesse for fortiden.', 5),
  ('norsk-10:litteraturhistorie', 'Nasjonalromantikk', 'Norsk romantikk som dyrket bondekultur, natur og det nasjonale.', 6),
  ('norsk-10:litteraturhistorie', 'Henrik Wergeland', 'Dikter i romantikken (1808–1845).', 7),
  ('norsk-10:litteraturhistorie', 'Realismen', 'Ca. 1870–1890. Skildret samfunnet som det var og satte problemer under debatt.', 8),
  ('norsk-10:litteraturhistorie', 'Det moderne gjennombrudd', 'Navn på overgangen til realismen, der litteraturen skulle debattere samfunnsproblemer.', 9),
  ('norsk-10:litteraturhistorie', 'Et dukkehjem', 'Skuespill av Henrik Ibsen fra 1879 om Nora, som bryter ut av ekteskapet.', 10),
  ('norsk-10:litteraturhistorie', 'Naturalismen', 'En enda mer usminket form for realisme. Amalie Skram er et norsk eksempel.', 11),
  ('norsk-10:litteraturhistorie', 'Nyromantikken', '1890-tallet. Vendte blikket mot sjelelivet, drømmer og det uforklarlige.', 12),
  ('norsk-10:litteraturhistorie', 'Sult', 'Roman av Knut Hamsun fra 1890 om en sulten forfatter i Kristiania.', 13),
  ('norsk-10:litteraturhistorie', 'Modernismen', '1900-tallet. Brudd med tradisjonelle former, frie vers og skildring av moderne liv.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-10:litteraturhistorie', 'q01', 'flervalg', 'Hvilken epoke satte følelser, natur og fortid i sentrum?', array['Realismen', 'Romantikken', 'Modernismen', 'Naturalismen']::text[], 1, 'Romantikerne dyrket følelser, fantasi og naturen, og var opptatt av fortiden.', true, true, 0),
  ('norsk-10:litteraturhistorie', 'q02', 'flervalg', 'Hvem skrev Et dukkehjem?', array['Knut Hamsun', 'Henrik Wergeland', 'Henrik Ibsen', 'Amalie Skram']::text[], 2, 'Henrik Ibsen skrev skuespillet i 1879, i realismens periode.', true, true, 1),
  ('norsk-10:litteraturhistorie', 'q03', 'flervalg', 'Hva ville realistene med litteraturen?', array['Skildre samfunnet som det var og sette problemer under debatt', 'Flykte fra virkeligheten til eventyrverdenen', 'Skrive bare om naturen', 'Bryte med alle regler for form']::text[], 0, 'Realistene tok opp problemer som kvinners stilling og dobbeltmoral.', true, true, 2),
  ('norsk-10:litteraturhistorie', 'q04', 'flervalg', 'Hva samlet Asbjørnsen og Moe?', array['Sagaer', 'Skuespill', 'Moderne dikt', 'Folkeeventyr']::text[], 3, 'De samlet eventyr som var fortalt muntlig, og ga dem ut fra 1841.', true, true, 3),
  ('norsk-10:litteraturhistorie', 'q05', 'flervalg', 'Hvilken roman av Knut Hamsun kom i 1890?', array['Sult', 'Et dukkehjem', 'Jord og jern', 'Heimskringla']::text[], 0, 'Sult skildrer en sulten forfatters indre liv og regnes som et viktig verk i nyromantikken.', true, true, 4),
  ('norsk-10:litteraturhistorie', 'q06', 'flervalg', 'Hva kjennetegner modernismen?', array['Faste rim og rytme', 'Folkeeventyr', 'Brudd med tradisjonelle former, blant annet frie vers', 'Kongesagaer']::text[], 2, 'Modernistene eksperimenterte med formen og skrev om det moderne livet.', true, true, 5),
  ('norsk-10:litteraturhistorie', 'q07', 'flervalg', 'Når omtrent var norrøn tid?', array['1800–1850', 'Ca. 800–1350', '1870–1890', '1900–2000']::text[], 1, 'Norrøn tid strekker seg omtrent fra vikingtiden til midten av 1300-tallet.', true, true, 6),
  ('norsk-10:litteraturhistorie', 'q08', 'flervalg', 'Hva er nasjonalromantikk?', array['En retning som dyrket det særegne norske, som bondekultur og natur', 'En kjærlighetsroman', 'Modernistisk lyrikk', 'En type krim']::text[], 0, 'Nasjonalromantikken knyttet romantikkens ideer til byggingen av en norsk nasjonal identitet.', true, false, 7),
  ('norsk-10:litteraturhistorie', 'q09', 'flervalg', 'Hvilken forfatter forbindes med naturalismen?', array['Henrik Wergeland', 'Snorre Sturlason', 'Rolf Jacobsen', 'Amalie Skram']::text[], 3, 'Amalie Skram skrev usminket om blant annet kvinners situasjon, i naturalismens stil.', true, false, 8),
  ('norsk-10:litteraturhistorie', 'q10', 'flervalg', 'Hvorfor er det nyttig å kjenne den historiske konteksten til en tekst?', array['Fordi den forklarer hvorfor teksten tar opp de temaene den gjør', 'Fordi alle tekster handler om historie', 'Fordi den bestemmer hvor lang teksten er', 'Den er ikke nyttig']::text[], 0, 'Tiden teksten ble skrevet i, preger temaer, verdier og form.', true, true, 9),
  ('norsk-10:litteraturhistorie', 'm01', 'sant-usant', 'Folkeeventyrene ble først fortalt muntlig før de ble skrevet ned.', array['Sant', 'Usant']::text[], 0, 'Eventyrene gikk i arv muntlig i generasjoner før Asbjørnsen og Moe samlet dem.', false, true, 10),
  ('norsk-10:litteraturhistorie', 'm02', 'sant-usant', 'Realismen kom før romantikken.', array['Sant', 'Usant']::text[], 1, 'Romantikken var ca. 1800–1850, realismen ca. 1870–1890.', false, true, 11),
  ('norsk-10:litteraturhistorie', 'm03', 'sant-usant', 'Det moderne gjennombrudd er et annet navn for overgangen til realismen.', array['Sant', 'Usant']::text[], 0, 'Begrepet beskriver at litteraturen begynte å debattere samfunnsproblemer.', false, true, 12),
  ('norsk-10:litteraturhistorie', 'm04', 'sant-usant', 'Modernistiske dikt har alltid fast rim og rytme.', array['Sant', 'Usant']::text[], 1, 'Modernistene skrev ofte på frie vers uten rim og fast rytme.', false, true, 13),
  ('norsk-10:litteraturhistorie', 'm05', 'flervalg', 'Hvilken epoke vendte blikket mot sjelelivet og drømmer på 1890-tallet?', array['Realismen', 'Nyromantikken', 'Norrøn tid', 'Folkediktningen']::text[], 1, 'Nyromantikken reagerte mot realismen og var opptatt av menneskets indre liv.', false, true, 14),
  ('norsk-10:litteraturhistorie', 'm06', 'flervalg', 'Hva handler Et dukkehjem om?', array['En sulten forfatter', 'Norrøne konger', 'Nora, som bryter ut av ekteskapet sitt', 'En reise til månen']::text[], 2, 'Nora oppdager at hun har levd som en «dukke» og forlater mann og barn.', false, true, 15),
  ('norsk-10:litteraturhistorie', 'm07', 'flervalg', 'Hvem skrev kongesagaene i Heimskringla?', array['Snorre Sturlason', 'Henrik Ibsen', 'Jørgen Moe', 'Knut Hamsun']::text[], 0, 'Snorre Sturlason skrev Heimskringla på Island på 1200-tallet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-10:litteraturhistorie', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-10:litteraturhistorie', 's01', 'En elev sier at sagaer og folkediktning er det samme fordi begge er gamle. Forklar én viktig forskjell mellom dem, og nevn typiske former fra hver.', 'Folkediktning ble overlevert muntlig gjennom generasjoner og omfatter blant annet eventyr og folkeviser. Norrøn litteratur omfatter blant annet sagaer, eddadikt og skaldedikt.', array['Forklarer at folkediktning ble overlevert muntlig.', 'Nevner relevante former fra folkediktningen og norrøn litteratur.']::text[], 0),
  ('norsk-10:litteraturhistorie', 's02', 'Hva var forskjellen på Snorre Sturlasons arbeid og arbeidet til Asbjørnsen og Moe?', 'Snorre Sturlason skrev kongesagaene i Heimskringla på 1200-tallet. Asbjørnsen og Moe samlet norske folkeeventyr og ga dem ut fra 1841.', array['Knytter Snorre til kongesagaene i Heimskringla.', 'Knytter Asbjørnsen og Moe til innsamling og utgivelse av folkeeventyr.']::text[], 1),
  ('norsk-10:litteraturhistorie', 's03', 'I skuespillet Et dukkehjem forlater Nora mann og barn. Forklar hvorfor dette kan knyttes til realismen.', 'Realistene ville skildre samfunnet slik det faktisk var og sette problemer under debatt. Noras brudd med ekteskapet tar opp spørsmål om kvinners rettigheter og samfunnets forventninger.', array['Knytter realismen til å skildre samfunnet slik det var eller til å debattere problemer.', 'Forklarer at Noras handling tar opp et samfunnsproblem, for eksempel kvinners rettigheter.']::text[], 2),
  ('norsk-10:litteraturhistorie', 's04', 'Sammenlign realismen og naturalismen. Hva har de til felles, og hva skiller naturalismen fra realismen?', 'Begge retningene skildrer samfunnet. Naturalismen er en enda mer usminket form for realisme.', array['Viser at naturalismen har en forbindelse til realismen.', 'Forklarer at naturalismen skildrer mer usminket enn realismen.']::text[], 3),
  ('norsk-10:litteraturhistorie', 's05', 'En roman følger en person som grubler over drømmer og opplevelser som virker uforklarlige. Hvilken litterær retning passer best, og hva ved retningen støtter svaret?', 'Nyromantikken passer best. Denne retningen vendte blikket mot sjelelivet, drømmer og det uforklarlige.', array['Identifiserer nyromantikken.', 'Knytter retningen til minst ett relevant trekk, som sjeleliv, drømmer eller det uforklarlige.']::text[], 4),
  ('norsk-10:litteraturhistorie', 's06', 'En diktsamling bruker frie vers uten rim eller fast rytme og skildrer teknologi og fremmedgjøring. Hvilken litterær retning passer best? Begrunn svaret med to trekk ved retningen.', 'Modernismen passer best. Modernistene brøt med tradisjonelle former, og tekstene kunne skildre teknologi og fremmedgjøring.', array['Identifiserer modernismen.', 'Nevner brudd med tradisjonelle former eller frie vers.', 'Nevner et relevant tema, som teknologi eller fremmedgjøring.']::text[], 5),
  ('norsk-10:litteraturhistorie', 's07', 'En norsk romantisk dikter skriver om fjell, bondekultur og folkediktning. Hvilket navn brukes på denne norske retningen, og hva ved eksempelet passer til den?', 'Retningen kalles nasjonalromantikk. Den dyrket blant annet bondekultur, natur og folkediktning.', array['Identifiserer nasjonalromantikken.', 'Knytter retningen til minst ett av trekkene i eksempelet: bondekultur, natur eller folkediktning.']::text[], 6),
  ('norsk-10:litteraturhistorie', 's08', 'En elev sammenligner en samtidsroman om teknologi med et eldre litterært verk. Hvilke to typer innsikt kan en slik sammenligning gi?', 'Sammenligningen kan vise hva som har endret seg mellom tidene, og hvilke temaer som fortsatt er viktige. Den kan dermed vise både historiske forskjeller og tidløse temaer.', array['Forklarer at sammenligningen kan vise hva som har endret seg.', 'Forklarer at den også kan vise temaer som er tidløse eller fortsatt viktige.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-10:romanen', 'norsk-10', 'romanen', 'Romanen og romananalyse', 'Hva som kjennetegner romanen, ulike romantyper, fortellerteknikk og komposisjon, og hvordan du skriver en god analyse av en roman eller et utdrag.', array[2, 1, 12]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-10:romanen', '## Hva er en roman?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-10:romanen', 'Roman', 'En lang skjønnlitterær fortelling på prosa, ofte med flere personer og handlingstråder.', 0),
  ('norsk-10:romanen', 'Handlingstråd', 'En av flere historier som går parallelt i en roman.', 1),
  ('norsk-10:romanen', 'Utviklingsroman', 'Følger hovedpersonen fra barndom eller ungdom mot voksenlivet.', 2),
  ('norsk-10:romanen', 'Samfunnsroman', 'Viser og kritiserer forhold i samfunnet.', 3),
  ('norsk-10:romanen', 'Historisk roman', 'Foregår i en tidligere tid, gjerne med virkelige hendelser i bakgrunnen.', 4),
  ('norsk-10:romanen', 'Selvbiografisk roman', 'Bygger på forfatterens eget liv, men er skjønnlitteratur.', 5),
  ('norsk-10:romanen', 'Komposisjon', 'Hvordan handlingen er satt sammen, for eksempel kronologisk eller med tilbakeblikk.', 6),
  ('norsk-10:romanen', 'Kronologisk', 'Handlingen fortelles i den rekkefølgen tingene skjer.', 7),
  ('norsk-10:romanen', 'Rammefortelling', 'En fortelling som rammer inn en annen fortelling.', 8),
  ('norsk-10:romanen', 'Indre monolog', 'Gjengir en persons tanker direkte, slik de farer gjennom hodet.', 9),
  ('norsk-10:romanen', 'Dialog', 'Replikkveksling mellom personer. Gjør scener levende.', 10),
  ('norsk-10:romanen', 'Fortellertempo', 'Hvor raskt tiden går i fortellingen: detaljerte scener eller store tidshopp.', 11),
  ('norsk-10:romanen', 'Utdrag', 'Et stykke av en lengre tekst. Må ses i sammenheng med helheten.', 12),
  ('norsk-10:romanen', 'Belegg', 'Sitater og eksempler fra teksten som støtter tolkningen din.', 13),
  ('norsk-10:romanen', 'Ikke gjenfortell alt', 'I en analyse skal handlingen oppsummeres kort. Vekten ligger på tolkning og virkemidler.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-10:romanen', 'q01', 'flervalg', 'Hva skiller en roman fra en novelle?', array['Romanen er alltid sann', 'Romanen er lengre og har ofte flere personer og handlingstråder', 'Romanen rimer', 'Romanen har ingen forteller']::text[], 1, 'Romanen gir plass til flere personer, miljøer og lengre tidsforløp enn novellen.', true, true, 0),
  ('norsk-10:romanen', 'q02', 'flervalg', 'En roman følger en jente fra hun er 10 til hun er 20 år. Hvilken romantype er dette mest sannsynlig?', array['Kriminalroman', 'Science fiction', 'Utviklingsroman', 'Rammefortelling']::text[], 2, 'Utviklingsromanen skildrer hvordan en person vokser opp og forandrer seg.', true, true, 1),
  ('norsk-10:romanen', 'q03', 'flervalg', 'Hva er indre monolog?', array['Personens tanker gjengitt direkte', 'En samtale mellom to personer', 'En beskrivelse av miljøet', 'Forfatterens forord']::text[], 0, 'Indre monolog gir leseren tilgang til tankestrømmen til en person.', true, true, 2),
  ('norsk-10:romanen', 'q04', 'flervalg', 'Hva betyr at en roman er fortalt kronologisk?', array['At den har mange tilbakeblikk', 'At den foregår i framtiden', 'At den har to fortellere', 'At handlingen kommer i den rekkefølgen den skjer']::text[], 3, 'Kronologisk betyr i tidsrekkefølge, fra begynnelse til slutt.', true, true, 3),
  ('norsk-10:romanen', 'q05', 'flervalg', 'Hva er det viktigste å unngå i en romananalyse?', array['Å bruke sitater', 'Å tolke temaet', 'Å gjenfortelle hele handlingen i detalj', 'Å nevne forfatteren']::text[], 2, 'En analyse skal tolke og forklare, ikke gjenfortelle. Handlingen oppsummeres kort.', true, true, 4),
  ('norsk-10:romanen', 'q06', 'flervalg', 'Hva er en rammefortelling?', array['En fortelling som rammer inn en annen fortelling', 'En fortelling med bilder', 'En fortelling uten slutt', 'En fortelling om et maleri']::text[], 0, 'For eksempel kan en gammel mann fortelle en historie fra ungdommen, og fortellingen hans er inni rammen.', true, true, 5),
  ('norsk-10:romanen', 'q07', 'flervalg', 'Hvorfor bruker man sitater i en analyse?', array['For å gjøre teksten lengre', 'Som belegg for tolkningen', 'Fordi man ikke har egne ord', 'For å gjenfortelle handlingen']::text[], 1, 'Sitater viser at tolkningen din bygger på teksten og ikke bare på synsing.', true, true, 6),
  ('norsk-10:romanen', 'q08', 'flervalg', 'Hva må du tenke på når du analyserer et utdrag?', array['At utdraget alltid er slutten', 'At utdraget ikke har noe med resten å gjøre', 'Å bare se på tittelen', 'Hvordan utdraget henger sammen med resten av romanen']::text[], 3, 'Utdraget får mye av betydningen sin fra helheten det er hentet fra.', true, true, 7),
  ('norsk-10:romanen', 'q09', 'flervalg', 'Hva kjennetegner en samfunnsroman?', array['Den foregår i verdensrommet', 'Den viser og kritiserer forhold i samfunnet', 'Den handler bare om kjærlighet', 'Den er alltid morsom']::text[], 1, 'Samfunnsromanen bruker fiksjonen til å belyse samfunnsproblemer.', true, false, 8),
  ('norsk-10:romanen', 'q10', 'flervalg', 'Hva betyr fortellertempo?', array['Hvor fort leseren leser', 'Hvor mange sider boka har', 'Hvor raskt tiden går i fortellingen', 'Hvor fort forfatteren skrev']::text[], 2, 'Noen hendelser skildres over mange sider, mens år kan passere på én setning.', true, false, 9),
  ('norsk-10:romanen', 'm01', 'sant-usant', 'En selvbiografisk roman er sakprosa.', array['Sant', 'Usant']::text[], 1, 'Selv om den bygger på forfatterens liv, er den en roman og regnes som skjønnlitteratur.', false, true, 10),
  ('norsk-10:romanen', 'm02', 'sant-usant', 'En roman kan veksle mellom flere synsvinkler.', array['Sant', 'Usant']::text[], 0, 'Mange romaner lar ulike personer fortelle i ulike kapitler.', false, true, 11),
  ('norsk-10:romanen', 'm03', 'sant-usant', 'I en analyse er det nok å finne virkemidler uten å forklare effekten.', array['Sant', 'Usant']::text[], 1, 'Effekten er det viktigste. Du må vise hva virkemidlet gjør med teksten.', false, true, 12),
  ('norsk-10:romanen', 'm04', 'sant-usant', 'En historisk roman kan ha virkelige hendelser som bakteppe.', array['Sant', 'Usant']::text[], 0, 'Historiske romaner blander fiksjon med virkelige hendelser og miljøer.', false, true, 13),
  ('norsk-10:romanen', 'm05', 'flervalg', 'Hva bør med i presentasjonen av verket i en analyse?', array['Forfatter, tittel, år og sjanger', 'Hele handlingen', 'Din favorittperson', 'Antall sider']::text[], 0, 'En kort presentasjon gir leseren de viktigste opplysningene om verket.', false, true, 14),
  ('norsk-10:romanen', 'm06', 'flervalg', 'Hva gjør dialog med en fortelling?', array['Gjør den kortere', 'Gjør scenene levende og viser personene gjennom det de sier', 'Fjerner spenningen', 'Erstatter fortelleren helt']::text[], 1, 'Gjennom replikkene kan leseren selv tolke hvordan personene er.', false, true, 15),
  ('norsk-10:romanen', 'm07', 'flervalg', 'Hva er et godt utgangspunkt for å sammenligne to romaner fra ulike tider?', array['Antall kapitler', 'Fargen på omslaget', 'Hvordan de framstiller et felles tema, som frihet eller familie', 'Hvilken som er lengst']::text[], 2, 'Et felles tema gjør det mulig å se likheter og forskjeller i syn og form.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-10:romanen', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-10:romanen', 's01', 'En roman veksler mellom historien om to søsken og historien om en nabo. Hva kalles hver av historiene, og hva gir det plass til når en roman har flere slike historier?', 'Hver av historiene kalles en handlingstråd. Flere handlingstråder gir plass til flere parallelle historier i romanen.', array['Forklarer at en handlingstråd er én av flere historier i en roman.', 'Får fram at flere handlingstråder lar flere historier gå parallelt.']::text[], 0),
  ('norsk-10:romanen', 's02', 'En roman bygger på forfatterens eget liv, men er skjønnlitterær. En annen foregår i en tidligere tid, med virkelige hendelser i bakgrunnen. Sammenlign hva slags romaner de er.', 'Den første er en selvbiografisk roman, fordi den bygger på forfatterens eget liv, men fortsatt er skjønnlitterær. Den andre er en historisk roman, fordi den foregår i en tidligere tid og har virkelige hendelser i bakgrunnen.', array['Knytter selvbiografisk roman til forfatterens eget liv og skjønnlitteratur.', 'Knytter historisk roman til en tidligere tid og gjerne virkelige hendelser i bakgrunnen.']::text[], 1),
  ('norsk-10:romanen', 's03', 'En roman begynner med at hovedpersonen kommer hjem. Senere forteller den om en hendelse fra barndommen som skjedde før hjemkomsten. Hva slags grep er dette, og hvordan påvirker det rekkefølgen handlingen fortelles i?', 'Dette er et tilbakeblikk. Fortellingen går tilbake til en tidligere hendelse i stedet for å fortelle alt i den rekkefølgen det skjedde.', array['Identifiserer grepet som et tilbakeblikk.', 'Forklarer at fortellingen går tilbake til noe som skjedde tidligere.']::text[], 2),
  ('norsk-10:romanen', 's04', 'To personer snakker sammen i en scene, og det de sier viser at den ene er usikker og den andre bestemt. Hvilket fortellergrep brukes, og hva kan det vise om personene?', 'Scenen bruker dialog, altså replikkveksling mellom personer. Det de sier, kan gjøre scenen levende og vise hvordan personene er.', array['Identifiserer replikkvekslingen som dialog.', 'Forklarer at det personene sier kan vise noe om dem.']::text[], 3),
  ('norsk-10:romanen', 's05', 'I en roman blir flere år oppsummert i én setning, mens ett kort øyeblikk beskrives svært detaljert. Hva viser dette om fortellertempoet?', 'Fortellertempoet varierer. Tiden går raskt når flere år oppsummeres, men saktere i den detaljerte scenen.', array['Forklarer at fortellertempoet varierer.', 'Skiller mellom rask oppsummering av lang tid og detaljert skildring av en scene.']::text[], 4),
  ('norsk-10:romanen', 's06', 'En roman undersøker og kritiserer urettferdige forhold i samfunnet. En annen bygger opp spenning rundt en forbrytelse som skal oppklares. Sammenlign romantypene.', 'Den første er en samfunnsroman, fordi den viser og kritiserer forhold i samfunnet. Den andre er en kriminalroman, fordi den bygger opp spenning rundt en forbrytelse som skal oppklares.', array['Knytter samfunnsroman til å vise og kritisere samfunnsforhold.', 'Knytter kriminalroman til spenning rundt en forbrytelse som skal oppklares.']::text[], 5),
  ('norsk-10:romanen', 's07', 'I en roman fortelles annethvert kapittel fra en forskjellig persons synsvinkel. Hvilket komposisjonsgrep bruker romanen, og hvordan er kapitlene ordnet?', 'Romanen veksler mellom flere synsvinkler. Synsvinklene skifter fra kapittel til kapittel.', array['Får fram at romanen veksler mellom flere synsvinkler.', 'Forklarer at synsvinklene skifter kapittel for kapittel.']::text[], 6),
  ('norsk-10:romanen', 's08', 'I begynnelsen av en roman unngår hovedpersonen ansvar. Senere tar personen ansvar for egne valg. Hva bør en analyse forklare om hovedpersonen?', 'Analysen bør beskrive hvordan hovedpersonen utvikler seg. Den kan sammenligne hvordan personen er i begynnelsen og senere i romanen.', array['Får fram at hovedpersonen utvikler seg.', 'Sammenligner personens egenskaper eller handlinger på ulike steder i romanen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-10:bokmal-og-nynorsk-historie', 'norsk-10', 'bokmal-og-nynorsk-historie', 'Bokmål, nynorsk og språkene i Norge', 'Hvorfor Norge har to skriftspråk, Ivar Aasen og Knud Knudsen, de viktigste årstallene i språkstriden, og hvilken status de offisielle språkene har i dag.', array[15]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-10:bokmal-og-nynorsk-historie', '## Fra norrønt til dansk
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-10:bokmal-og-nynorsk-historie', 'Norrønt', 'Skriftspråket i Norge i middelalderen.', 0),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Dansk skriftspråk i Norge', 'Ble det vanlige skriftspråket etter unionen med Danmark og ble brukt i om lag 400 år.', 1),
  ('norsk-10:bokmal-og-nynorsk-historie', '1814', 'Norge fikk egen grunnlov og ble en egen stat, i union med Sverige.', 2),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Ivar Aasen', 'Samlet dialekter og lagde landsmålet, grunnlaget for nynorsk.', 3),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Landsmål', 'Aasens skriftspråk bygd på norske dialekter. Grunnlaget for nynorsk.', 4),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Knud Knudsen', 'Ville fornorske dansk gradvis. Hans linje førte til riksmålet og bokmålet.', 5),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Riksmål', 'Fornorsket dansk skriftspråk. Grunnlaget for bokmål.', 6),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Jamstillingsvedtaket 1885', 'Stortinget likestilte landsmålet med det dansk-norske skriftspråket.', 7),
  ('norsk-10:bokmal-og-nynorsk-historie', '1929', 'Navnene bokmål og nynorsk ble vedtatt.', 8),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Samnorsk', 'Ideen om å slå sammen bokmål og nynorsk til ett språk. Senere oppgitt.', 9),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Språkloven', 'Lov i kraft fra 2022: norsk er hovedspråket, og bokmål og nynorsk er likestilte.', 10),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Samisk', 'Urfolksspråk i Norge, likestilt med norsk.', 11),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Nasjonale minoritetsspråk', 'Kvensk, romani, romanes og skogfinsk.', 12),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Hovedmål og sidemål', 'Hovedmålet er den målformen eleven bruker mest. Sidemålet er den andre.', 13),
  ('norsk-10:bokmal-og-nynorsk-historie', 'Rettskrivingsreformer', 'De siste store: bokmål i 2005 og nynorsk i 2012.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-10:bokmal-og-nynorsk-historie', 'q01', 'flervalg', 'Hvorfor skrev nordmenn dansk i flere hundre år?', array['Fordi Norge var i union med Danmark', 'Fordi norsk ikke fantes', 'Fordi dansk var lettere', 'Fordi kongen kom fra Sverige']::text[], 0, 'Under unionen med Danmark ble dansk det vanlige skriftspråket, mens folk snakket norske dialekter.', true, true, 0),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q02', 'flervalg', 'Hvem lagde landsmålet?', array['Knud Knudsen', 'Henrik Ibsen', 'Ivar Aasen', 'Henrik Wergeland']::text[], 2, 'Ivar Aasen bygde landsmålet på dialektene. Det er grunnlaget for nynorsk.', true, true, 1),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q03', 'flervalg', 'Hva ville Knud Knudsen?', array['Innføre svensk', 'Fornorske det danske skriftspråket gradvis', 'Lage et nytt språk fra dialektene', 'Gå tilbake til norrønt']::text[], 1, 'Knudsen ville gradvis gjøre dansk mer norsk. Det førte til riksmål og senere bokmål.', true, true, 2),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q04', 'flervalg', 'Hva skjedde i 1885?', array['Norge fikk grunnlov', 'Bokmål fikk navnet sitt', 'Samnorsk ble innført', 'Landsmålet ble likestilt med det dansk-norske skriftspråket']::text[], 3, 'Stortingets jamstillingsvedtak i 1885 ga landsmålet samme status som det offisielle skriftspråket.', true, true, 3),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q05', 'flervalg', 'Når fikk bokmål og nynorsk navnene sine?', array['1814', '1885', '1929', '2005']::text[], 2, 'I 1929 ble navnene bokmål og nynorsk vedtatt i stedet for riksmål og landsmål.', true, true, 4),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q06', 'flervalg', 'Hva var samnorsk?', array['Et samisk språk', 'Ideen om å slå sammen bokmål og nynorsk til ett språk', 'Et nordisk fellesspråk', 'En dialekt fra Nord-Norge']::text[], 1, 'Samnorsk var et mål i språkpolitikken i deler av 1900-tallet, men ble senere oppgitt.', true, false, 5),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q07', 'flervalg', 'Hva sier språkloven om bokmål og nynorsk?', array['At bokmål er viktigst', 'At nynorsk skal fases ut', 'At de er likestilte skriftspråk', 'At de skal slås sammen']::text[], 2, 'Språkloven fra 2022 slår fast at bokmål og nynorsk er likestilte skriftspråk.', true, true, 6),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q08', 'flervalg', 'Hvilken status har samisk i Norge?', array['Urfolksspråk, likestilt med norsk', 'Nasjonalt minoritetsspråk', 'Fremmedspråk', 'Dialekt']::text[], 0, 'Samisk er urfolksspråk og likestilt med norsk.', true, true, 7),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q09', 'flervalg', 'Hvilket språk er et nasjonalt minoritetsspråk i Norge?', array['Engelsk', 'Samisk', 'Polsk', 'Kvensk']::text[], 3, 'Kvensk, romani, romanes og skogfinsk er nasjonale minoritetsspråk. Samisk har status som urfolksspråk.', true, true, 8),
  ('norsk-10:bokmal-og-nynorsk-historie', 'q10', 'flervalg', 'Hva bygde Ivar Aasen landsmålet på?', array['Dansk skriftspråk', 'Norske dialekter, med blikk til norrønt', 'Svensk', 'Byfolkets talemål']::text[], 1, 'Aasen studerte dialekter over hele landet og brukte dem som grunnlag.', true, false, 9),
  ('norsk-10:bokmal-og-nynorsk-historie', 'm01', 'sant-usant', 'Nynorsk bygger på landsmålet til Ivar Aasen.', array['Sant', 'Usant']::text[], 0, 'Landsmålet fikk navnet nynorsk i 1929.', false, true, 10),
  ('norsk-10:bokmal-og-nynorsk-historie', 'm02', 'sant-usant', 'Bokmål bygger på det danske skriftspråket.', array['Sant', 'Usant']::text[], 0, 'Bokmål er en videreutvikling av dansk skriftspråk gjennom fornorsking.', false, true, 11),
  ('norsk-10:bokmal-og-nynorsk-historie', 'm03', 'sant-usant', 'Samnorsk er det offisielle skriftspråket i Norge i dag.', array['Sant', 'Usant']::text[], 1, 'Samnorsk ble aldri innført. Bokmål og nynorsk er de likestilte skriftspråkene.', false, true, 12),
  ('norsk-10:bokmal-og-nynorsk-historie', 'm04', 'sant-usant', 'De fleste elever i grunnskolen har nynorsk som hovedmål.', array['Sant', 'Usant']::text[], 1, 'Rundt en av ti elever har nynorsk som hovedmål. De fleste har bokmål.', false, true, 13),
  ('norsk-10:bokmal-og-nynorsk-historie', 'm05', 'flervalg', 'Hva var jamstillingsvedtaket?', array['Et vedtak om å likestille landsmålet med det dansk-norske skriftspråket', 'En lov om samisk', 'En reform av bokmål', 'Grunnloven av 1814']::text[], 0, 'Vedtaket i 1885 ga landsmålet offisiell status.', false, true, 14),
  ('norsk-10:bokmal-og-nynorsk-historie', 'm06', 'flervalg', 'Hvor bor det flest nynorskbrukere?', array['I Oslo', 'I Finnmark', 'På Vestlandet', 'I Trøndelag']::text[], 2, 'Nynorsk står sterkest på Vestlandet.', false, true, 15),
  ('norsk-10:bokmal-og-nynorsk-historie', 'm07', 'flervalg', 'Når trådte språkloven i kraft?', array['1885', '1929', '2005', '2022']::text[], 3, 'Språkloven trådte i kraft 1. januar 2022.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-10:bokmal-og-nynorsk-historie', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-10:bokmal-og-nynorsk-historie', 's01', 'I om lag fire hundre år skrev nordmenn dansk, men snakket norske dialekter. Forklar forskjellen mellom skriftspråket og talespråket i denne perioden.', 'Dansk var det vanlige skriftspråket, mens folk fortsatte å snakke norske dialekter. Skriftspråket og talespråket var altså ulike.', array['Får fram at dansk ble brukt skriftlig.', 'Får fram at nordmenn snakket norske dialekter.']::text[], 0),
  ('norsk-10:bokmal-og-nynorsk-historie', 's02', 'Ivar Aasen og Knud Knudsen ville utvikle et norsk skriftspråk på ulike måter. Sammenlign hva de bygde arbeidet sitt på, og hvilke målformer linjene deres førte til.', 'Aasen bygde landsmålet på norske dialekter, med blikk til norrønt, og det ble grunnlaget for nynorsk. Knudsen ville fornorske dansk gradvis, og linjen hans førte til riksmål og senere bokmål.', array['Skiller mellom Aasens arbeid med dialekter og Knudsens gradvise fornorsking av dansk.', 'Knytter Aasens linje til nynorsk og Knudsens linje til bokmål.']::text[], 1),
  ('norsk-10:bokmal-og-nynorsk-historie', 's03', 'Norge fikk egen grunnlov og ble en egen stat i 1814, men var fortsatt i union med Sverige. Forklar hvorfor dette kunne føre til diskusjon om hvilket skriftspråk Norge skulle ha.', 'Mange mente at et selvstendig folk også trengte et eget skriftspråk. Derfor vokste det fram ulike forslag til hvordan Norge kunne få et norsk skriftspråk.', array['Knytter Norges nye selvstendighet til ønsket om et eget skriftspråk.', 'Får fram at det vokste fram ulike løsninger.']::text[], 2),
  ('norsk-10:bokmal-og-nynorsk-historie', 's04', 'Et statlig organ lager alle skriftlige meldinger på bokmål. Hvilket krav må organet følge når det gjelder bokmål og nynorsk?', 'Statlige organer må bruke både bokmål og nynorsk. De kan derfor ikke bruke bare bokmål.', array['Får fram at statlige organer må bruke begge målformene.']::text[], 3),
  ('norsk-10:bokmal-og-nynorsk-historie', 's05', 'En elev sier at norsk tegnspråk er et av de nasjonale minoritetsspråkene. Rett opp påstanden ved å forklare hvilken status norsk tegnspråk har, og nevn språkene som regnes som nasjonale minoritetsspråk.', 'Norsk tegnspråk har en særskilt status. Kvensk, romani, romanes og skogfinsk er de nasjonale minoritetsspråkene.', array['Skiller norsk tegnspråks særskilte status fra kategorien nasjonale minoritetsspråk.', 'Nevner de nasjonale minoritetsspråkene.']::text[], 4),
  ('norsk-10:bokmal-og-nynorsk-historie', 's06', 'Mina bruker nynorsk mest på skolen og lærer også bokmål. Forklar hvilken målform som er hovedmålet hennes, og hvilken som er sidemålet.', 'Nynorsk er hovedmålet hennes fordi det er målformen hun bruker mest. Bokmål er sidemålet hennes.', array['Identifiserer nynorsk som hovedmål fordi Mina bruker det mest.', 'Identifiserer bokmål som sidemål.']::text[], 5),
  ('norsk-10:bokmal-og-nynorsk-historie', 's07', 'I 1938 kom en rettskrivingsreform som skulle føre bokmål og nynorsk nærmere hverandre. Forklar hva reformen prøvde å oppnå, og hva som senere skjedde med denne tanken.', 'Reformen skulle føre målformene sammen mot et felles språk kalt samnorsk. Tanken om samnorsk ble senere oppgitt.', array['Får fram at målet var å føre bokmål og nynorsk nærmere hverandre mot et felles språk.', 'Får fram at samnorsktanken senere ble oppgitt.']::text[], 6),
  ('norsk-10:bokmal-og-nynorsk-historie', 's08', 'En elev lager en tidslinje over rettskrivingsreformer. Hva skjedde med riksmålet i 1907, og når kom de siste store rettskrivingsreformene for bokmål og nynorsk?', 'Reformen i 1907 fornorsket riksmålet. De siste store rettskrivingsreformene kom for bokmål i 2005 og for nynorsk i 2012.', array['Får fram at 1907-reformen fornorsket riksmålet.', 'Oppgir 2005 for bokmål og 2012 for nynorsk.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-10:sprakvariasjon', 'norsk-10', 'sprakvariasjon', 'Språklig variasjon og dialekter', 'Dialekter, sosiolekter, etnolekter og multietnolekt, hvordan språket varierer med situasjon, og hvilke holdninger folk har til ulike måter å snakke på.', array[16]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-10:sprakvariasjon', '## Norge – et land med mange måter å snakke på
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-10:sprakvariasjon', 'Dialekt', 'En geografisk variant av et språk.', 0),
