insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-10:python-i-matematikk', 's01', 'Et program skal gjenta en handling flere ganger. Forklar forskjellen på hvordan en for-løkke og en while-løkke bestemmer om koden skal gjentas.', 'En for-løkke gjentar koden for hver verdi i en rekke. En while-løkke gjentar koden så lenge en betingelse er sann.', array['Forklarer at for-løkka gjentar for verdiene i en rekke.', 'Forklarer at while-løkka gjentar så lenge betingelsen er sann.']::text[], 0),
  ('matematikk-10:python-i-matematikk', 's02', 'Se på koden:
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-10:advanced-grammar', 'engelsk-10', 'advanced-grammar', 'Passive, conditionals and reported speech', 'Three grammar structures that make your English more flexible: the passive voice, conditional sentences with “if”, and reported speech.', array[8, 9, 15]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-10:advanced-grammar', '## The passive voice
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-10:advanced-grammar', 'Active voice', 'The subject does the action: The chef cooked the meal.', 0),
  ('engelsk-10:advanced-grammar', 'Passive voice', 'Focus on what the action is done to: The meal was cooked.', 1),
  ('engelsk-10:advanced-grammar', 'Forming the passive', 'be + past participle: is made, was built, has been sold.', 2),
  ('engelsk-10:advanced-grammar', 'When to use the passive', 'When the doer is unknown, unimportant or obvious; common in news and science.', 3),
  ('engelsk-10:advanced-grammar', 'Zero conditional', 'Always true: If you heat ice, it melts.', 4),
  ('engelsk-10:advanced-grammar', 'First conditional', 'Real future possibility: If it rains, we will stay inside.', 5),
  ('engelsk-10:advanced-grammar', 'Second conditional', 'Unreal now: If I had money, I would travel.', 6),
  ('engelsk-10:advanced-grammar', 'Third conditional', 'Unreal past: If she had studied, she would have passed.', 7),
  ('engelsk-10:advanced-grammar', 'No “would” in the if-clause', 'Say “If I had money”, not “If I would have money”.', 8),
  ('engelsk-10:advanced-grammar', 'If I were you', 'Formal form used with all persons in the second conditional.', 9),
  ('engelsk-10:advanced-grammar', 'Direct speech', 'Someone''s exact words in quotation marks: “I am tired.”', 10),
  ('engelsk-10:advanced-grammar', 'Reported speech', 'Retelling what someone said: She said she was tired.', 11),
  ('engelsk-10:advanced-grammar', 'Backshift', 'In reported speech, the verb moves one step back: will → would, is → was.', 12),
  ('engelsk-10:advanced-grammar', 'tomorrow → the next day', 'Time words change in reported speech.', 13),
  ('engelsk-10:advanced-grammar', 'Reported yes/no questions', 'Use if or whether: He asked if I liked football.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-10:advanced-grammar', 'q01', 'flervalg', 'Which sentence is passive?', array['The dog bit the man.', 'The man was bitten by the dog.', 'The man bit the sandwich.', 'The dog is biting.']::text[], 1, 'The passive uses be + past participle (was bitten), and the focus is on the man.', true, true, 0),
  ('engelsk-10:advanced-grammar', 'q02', 'flervalg', 'Make the sentence passive: “Someone stole my bike.”', array['My bike stole.', 'My bike has stealing.', 'My bike was stolen.', 'My bike is steal.']::text[], 2, 'was + past participle (stolen). We leave out “by someone” because it adds nothing.', true, true, 1),
  ('engelsk-10:advanced-grammar', 'q03', 'flervalg', 'Which conditional is this? “If it rains tomorrow, we will stay inside.”', array['First conditional', 'Zero conditional', 'Second conditional', 'Third conditional']::text[], 0, 'It describes a real possibility in the future: present + will.', true, true, 2),
  ('engelsk-10:advanced-grammar', 'q04', 'flervalg', 'Complete: “If I … a million kroner, I would buy a house.”', array['have', 'would have', 'will have', 'had']::text[], 3, 'The second conditional uses the past tense in the if-clause: If I had…', true, true, 3),
  ('engelsk-10:advanced-grammar', 'q05', 'flervalg', 'Complete: “If she … harder, she would have passed the test.”', array['studied', 'had studied', 'would study', 'studies']::text[], 1, 'The third conditional uses had + past participle in the if-clause.', true, true, 4),
  ('engelsk-10:advanced-grammar', 'q06', 'flervalg', 'Change to reported speech: She said, “I am tired.”', array['She said she was tired.', 'She said I am tired.', 'She said she is tiring.', 'She says she were tired.']::text[], 0, 'The pronoun changes (I → she) and the verb moves back (am → was).', true, true, 5),
  ('engelsk-10:advanced-grammar', 'q07', 'flervalg', 'Change to reported speech: He said, “I will call you.”', array['He said he will call me.', 'He said I call you.', 'He said he would call me.', 'He said he called you tomorrow.']::text[], 2, '“Will” becomes “would”, and the pronouns change to fit the new speaker.', true, true, 6),
  ('engelsk-10:advanced-grammar', 'q08', 'flervalg', 'How do you report the question “Do you like football?”', array['He asked do I like football.', 'He asked did I like football?', 'He asked that I like football.', 'He asked if I liked football.']::text[], 3, 'Reported yes/no questions use if/whether and normal statement word order.', true, true, 7),
  ('engelsk-10:advanced-grammar', 'q09', 'flervalg', 'Which zero conditional sentence is correct?', array['If you heat ice, it melts.', 'If you heated ice, it would melt yesterday.', 'If you will heat ice, it melts.', 'If you heat ice, it would melt.']::text[], 0, 'The zero conditional uses present + present for things that are always true.', true, false, 8),
  ('engelsk-10:advanced-grammar', 'q10', 'flervalg', 'When is the passive especially useful?', array['When you want to be informal', 'When the doer is unknown or unimportant', 'When you tell a joke', 'When you write dialogue']::text[], 1, '“The window was broken” works well when we do not know or care who broke it.', true, false, 9),
  ('engelsk-10:advanced-grammar', 'm01', 'sant-usant', '“If I would have time, I would help you” is correct.', array['Sant', 'Usant']::text[], 1, 'We do not use “would” in the if-clause. Correct: If I had time, I would help you.', false, true, 10),
  ('engelsk-10:advanced-grammar', 'm02', 'sant-usant', 'The passive is formed with a form of “be” and the past participle.', array['Sant', 'Usant']::text[], 0, 'Examples: is made, was built, has been sold.', false, true, 11),
  ('engelsk-10:advanced-grammar', 'm03', 'sant-usant', 'In reported speech, “can” often becomes “could”.', array['Sant', 'Usant']::text[], 0, 'Backshift: can → could, will → would.', false, true, 12),
  ('engelsk-10:advanced-grammar', 'm04', 'sant-usant', 'Passive sentences are always clearer than active sentences.', array['Sant', 'Usant']::text[], 1, 'Active sentences are usually clearer. Use the passive when there is a reason to.', false, true, 13),
  ('engelsk-10:advanced-grammar', 'm05', 'flervalg', 'Which sentence is the second conditional?', array['If I win, I will celebrate.', 'If I won, I would celebrate.', 'If I had won, I would have celebrated.', 'If you win, you celebrate.']::text[], 1, 'The second conditional: past in the if-clause + would.', false, true, 14),
  ('engelsk-10:advanced-grammar', 'm06', 'flervalg', 'Make passive: “They build new houses every year.”', array['New houses build every year.', 'New houses were building every year.', 'New houses are built every year.', 'New houses have build every year.']::text[], 2, 'Present passive: are + built.', false, true, 15),
  ('engelsk-10:advanced-grammar', 'm07', 'flervalg', 'Report: “Where do you live?” she asked.', array['She asked where I lived.', 'She asked where do I live.', 'She asked where did I live.', 'She asked if where I lived.']::text[], 0, 'The question word stays, the word order becomes a statement, and the verb moves back.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-10:advanced-grammar', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-10:advanced-grammar', 's01', 'Explain how the passive is formed. In “The meal was cooked,” identify the part that uses a form of “be” and the past participle.', 'The passive is formed with a form of “be” and a past participle. In the sentence, “was” is the form of “be” and “cooked” is the past participle.', array['States that the passive uses be + past participle.', 'Correctly identifies “was” and “cooked” in the sentence.']::text[], 0),
  ('engelsk-10:advanced-grammar', 's02', 'Compare the focus in these sentences: “The chef cooked the meal” and “The meal was cooked.” What does each sentence focus on?', 'The active sentence focuses on the chef, who does the action. The passive sentence focuses on the meal, which the action is done to.', array['Explains that the active sentence focuses on who does the action.', 'Explains that the passive sentence focuses on what the action is done to.']::text[], 1),
  ('engelsk-10:advanced-grammar', 's03', 'Compare these sentences: “If I finish my work, I will go home” and “If I had more time, I would travel.” Explain what kind of situation each conditional describes.', 'The first conditional describes a real possibility in the future. The second conditional describes an unreal or unlikely situation now.', array['Identifies the first sentence as a real future possibility.', 'Identifies the second sentence as unreal or unlikely now.']::text[], 2),
  ('engelsk-10:advanced-grammar', 's04', 'Give advice to a friend using the formal second conditional: “If I ___ you, I ___ take a break.” Fill in both gaps, then explain why “were” is used with “I” in this expression.', 'If I were you, I would take a break. “Were” is the formal form used in “If I were you” with all persons.', array['Uses “were” and “would” to complete the sentence.', 'Explains that the formal expression uses “were” with all persons.']::text[], 3),
  ('engelsk-10:advanced-grammar', 's05', 'They left late and missed the bus. Write a third conditional sentence explaining how leaving early could have changed what happened.', 'If they had left early, they would have caught the bus.', array['Uses “had” plus a past participle in the if-clause.', 'Uses “would have” plus a past participle in the main clause to describe an unreal past result.']::text[], 4),
  ('engelsk-10:advanced-grammar', 's06', 'Report this sentence from the listener’s point of view, using “me” for “you”: He said, “I can help you.”', 'He said that he could help me.', array['Changes “can” to “could.”', 'Changes “I” to “he” and “you” to “me.”']::text[], 5),
  ('engelsk-10:advanced-grammar', 's07', 'Report this question: She asked, “What do you do?” Use “I” for the person being asked.', 'She asked what I did.', array['Changes “do” to “did.”', 'Uses statement word order after “what,” without question word order.']::text[], 6),
  ('engelsk-10:advanced-grammar', 's08', 'Explain the difference between direct speech and reported speech. Include what happens to the verb when the reporting verb is in the past.', 'Direct speech gives someone’s exact words, usually in quotation marks. Reported speech retells what they said, and the verb usually moves one step back in time when the reporting verb is in the past.', array['Explains that direct speech gives the exact words and reported speech retells them.', 'Explains that the verb usually moves one step back in time after a past reporting verb.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-10:argumentative-writing', 'engelsk-10', 'argumentative-writing', 'Argumentative essays', 'How to write a clear argumentative essay in English: thesis statement, paragraph structure, evidence, counterarguments, linking words and revising.', array[14, 15, 5]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-10:argumentative-writing', '## What is an argumentative essay?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-10:argumentative-writing', 'Argumentative essay', 'An essay that takes a position and supports it with arguments and evidence.', 0),
  ('engelsk-10:argumentative-writing', 'Hook', 'An opening that catches the reader''s interest: a question, fact or example.', 1),
  ('engelsk-10:argumentative-writing', 'Thesis statement', 'One clear sentence in the introduction that states your position.', 2),
  ('engelsk-10:argumentative-writing', 'Body paragraph', 'A paragraph that presents one argument.', 3),
  ('engelsk-10:argumentative-writing', 'PEEL', 'Point, Evidence, Explanation, Link – a model for body paragraphs.', 4),
  ('engelsk-10:argumentative-writing', 'Topic sentence', 'The first sentence of a paragraph, stating its main point.', 5),
  ('engelsk-10:argumentative-writing', 'Evidence', 'Facts, examples, statistics or quotes that support a point.', 6),
  ('engelsk-10:argumentative-writing', 'Counterargument', 'An opposing view that you present fairly and then refute.', 7),
  ('engelsk-10:argumentative-writing', 'Refute', 'To show that an argument is wrong or weaker than yours.', 8),
  ('engelsk-10:argumentative-writing', 'Conclusion', 'Sums up the main points and restates the thesis without new arguments.', 9),
  ('engelsk-10:argumentative-writing', 'furthermore / moreover', 'Linking words for adding a point.', 10),
  ('engelsk-10:argumentative-writing', 'however / nevertheless', 'Linking words for contrast.', 11),
  ('engelsk-10:argumentative-writing', 'therefore / consequently', 'Linking words for cause and effect.', 12),
  ('engelsk-10:argumentative-writing', 'Hedging', 'Careful language like “may”, “suggest”, “it is likely that”.', 13),
  ('engelsk-10:argumentative-writing', 'Call to action', 'An ending that encourages the reader to do or think something.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-10:argumentative-writing', 'q01', 'flervalg', 'What is a thesis statement?', array['The title of the essay', 'One clear sentence that states your position', 'A list of sources', 'The last paragraph']::text[], 1, 'The thesis statement tells the reader exactly what you are going to argue.', true, true, 0),
  ('engelsk-10:argumentative-writing', 'q02', 'flervalg', 'What does the first “E” in PEEL stand for?', array['Evidence', 'Ending', 'Example sentence', 'Essay']::text[], 0, 'PEEL = Point, Evidence, Explanation, Link.', true, true, 1),
  ('engelsk-10:argumentative-writing', 'q03', 'flervalg', 'Why should you include a counterargument?', array['To change your opinion', 'To make the essay longer', 'To show that you have considered other views and can refute them', 'Because the teacher says so']::text[], 2, 'Answering a counterargument makes your own position more convincing.', true, true, 2),
  ('engelsk-10:argumentative-writing', 'q04', 'flervalg', 'Which linking word shows contrast?', array['furthermore', 'therefore', 'for example', 'however']::text[], 3, '“However” introduces a contrasting idea.', true, true, 3),
  ('engelsk-10:argumentative-writing', 'q05', 'flervalg', 'What should the conclusion NOT do?', array['Sum up the main points', 'Restate the thesis', 'Introduce new arguments', 'End with a final thought']::text[], 2, 'New arguments belong in the body paragraphs.', true, true, 4),
  ('engelsk-10:argumentative-writing', 'q06', 'flervalg', 'Which is the best hook for an essay about school phones?', array['This essay is about phones.', 'Did you know that many students check their phones over a hundred times a day?', 'Phones.', 'I will now write an essay.']::text[], 1, 'A question with a surprising fact catches the reader''s interest.', true, true, 5),
  ('engelsk-10:argumentative-writing', 'q07', 'flervalg', 'Which sentence is an example of hedging?', array['This proves everything.', 'Everybody knows this is true.', 'Studies suggest that this may improve concentration.', 'This is 100 % certain.']::text[], 2, '“Suggest” and “may” show careful, fair language.', true, true, 6),
  ('engelsk-10:argumentative-writing', 'q08', 'flervalg', 'What register is usually best for an argumentative essay?', array['Formal', 'Very informal with slang', 'Text-message style', 'Poetic']::text[], 0, 'Essays use formal language without slang and contractions.', true, false, 7),
  ('engelsk-10:argumentative-writing', 'q09', 'flervalg', 'How many main arguments should a body paragraph contain?', array['None', 'As many as possible', 'Three', 'One']::text[], 3, 'One argument per paragraph keeps the essay clear and organised.', true, true, 8),
  ('engelsk-10:argumentative-writing', 'q10', 'flervalg', 'Which phrase introduces a source?', array['Everybody knows that…', 'According to a report from…', 'I think maybe…', 'Whatever…']::text[], 1, '“According to…” shows where your information comes from.', true, false, 9),
  ('engelsk-10:argumentative-writing', 'm01', 'sant-usant', 'The thesis statement usually comes at the end of the introduction.', array['Sant', 'Usant']::text[], 0, 'The introduction leads up to the thesis, which tells the reader your position.', false, true, 10),
  ('engelsk-10:argumentative-writing', 'm02', 'sant-usant', 'Contractions like “don''t” are ideal in a formal essay.', array['Sant', 'Usant']::text[], 1, 'Formal essays use full forms: do not, cannot.', false, true, 11),
  ('engelsk-10:argumentative-writing', 'm03', 'sant-usant', '“Consequently” shows cause and effect.', array['Sant', 'Usant']::text[], 0, '“Consequently” means “as a result”.', false, true, 12),
  ('engelsk-10:argumentative-writing', 'm04', 'sant-usant', 'An argumentative essay only needs your opinion, not evidence.', array['Sant', 'Usant']::text[], 1, 'Evidence makes arguments convincing. Opinions alone are weak.', false, true, 13),
  ('engelsk-10:argumentative-writing', 'm05', 'flervalg', 'Which linking word adds a point?', array['however', 'moreover', 'although', 'nevertheless']::text[], 1, '“Moreover” adds another point in the same direction.', false, true, 14),
  ('engelsk-10:argumentative-writing', 'm06', 'flervalg', 'What does “refute” mean?', array['To agree completely', 'To repeat', 'To show that an argument is wrong or weaker', 'To summarise']::text[], 2, 'Refuting a counterargument strengthens your own position.', false, true, 15),
  ('engelsk-10:argumentative-writing', 'm07', 'flervalg', 'What is a call to action?', array['An ending that encourages the reader to do or think something', 'A phone call', 'A source', 'A topic sentence']::text[], 0, 'For example: “It is time for schools to act.”', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-10:argumentative-writing', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-10:argumentative-writing', 's01', 'In your own words, explain what makes an essay argumentative.', 'An argumentative essay takes a position on an issue and supports it with arguments and evidence to convince the reader.', array['Sier at essayet tar standpunkt i en sak.', 'Forklarer at standpunktet støttes med argumenter og bevis for å overbevise leseren.']::text[], 0),
  ('engelsk-10:argumentative-writing', 's02', 'Compare the purpose of a hook with the purpose of a topic sentence.', 'A hook catches the reader’s interest at the start of an essay. A topic sentence states the main point of a paragraph.', array['Forklarer at en hook skal fange leserens interesse.', 'Forklarer at en topic sentence forteller hva avsnittet handler om.']::text[], 1),
  ('engelsk-10:argumentative-writing', 's03', 'In PEEL, evidence and explanation are different parts. Explain what each one does in a body paragraph.', 'Evidence gives facts, examples, statistics or quotes to support a point. The explanation shows why that evidence supports the writer’s view.', array['Beskriver evidence som støtte for et poeng, for eksempel fakta eller eksempler.', 'Forklarer at explanation viser hvordan beviset støtter synspunktet.']::text[], 2),
  ('engelsk-10:argumentative-writing', 's04', 'A body paragraph states a point and gives evidence, but does not explain the connection between them. What should the writer add, and why?', 'The writer should add an explanation of how the evidence supports the point. This helps the reader understand why the evidence matters to the argument.', array['Foreslår å forklare sammenhengen mellom beviset og poenget.', 'Viser at forklaringen gjør det tydeligere hvorfor beviset støtter argumentet.']::text[], 3),
  ('engelsk-10:argumentative-writing', 's05', 'Name two forms that evidence can take in an argumentative essay, and explain how evidence helps an argument.', 'Evidence can be facts and examples. It supports a point and makes the argument stronger.', array['Nevner to gyldige former for evidence, som fakta, eksempler, statistikk eller sitater.', 'Forklarer at evidence støtter et poeng eller gjør argumentet sterkere.']::text[], 4),
  ('engelsk-10:argumentative-writing', 's06', 'Explain the difference between a counterargument and a refutation.', 'A counterargument presents an opposing view fairly. A refutation responds to that view and shows why it is wrong or weaker.', array['Forklarer at en counterargument presenterer et motsatt syn.', 'Forklarer at en refutation svarer på synet og viser hvorfor det er feil eller svakere.']::text[], 5),
  ('engelsk-10:argumentative-writing', 's07', 'A writer adds another supporting point and then explains a result caused by an earlier point. Which linking word fits each purpose: “moreover” or “therefore”? Explain your choices.', '“Moreover” fits when the writer adds another supporting point. “Therefore” fits when the writer shows a result or consequence.', array['Knytter moreover til å legge til et poeng.', 'Knytter therefore til resultat eller følge.']::text[], 6),
  ('engelsk-10:argumentative-writing', 's08', 'What is a call to action, and what is its purpose at the end of an argumentative essay?', 'A call to action is an ending that encourages the reader to do or think something. It gives the reader a clear final prompt.', array['Forklarer at en call to action oppfordrer leseren til å gjøre eller tenke noe.', 'Knytter den til avslutningen av essayet.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-10:sources-and-reliability', 'engelsk-10', 'sources-and-reliability', 'Sources and reliability', 'How to evaluate English-language sources, recognise fake news and bias, and quote, paraphrase and reference sources correctly in your own texts.', array[12, 13, 10]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-10:sources-and-reliability', '## Why evaluate sources?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-10:sources-and-reliability', 'Source-critical', 'Asking questions about a source before trusting and using it.', 0),
  ('engelsk-10:sources-and-reliability', 'Who, what, when, where, why', 'Five questions for evaluating a source.', 1),
  ('engelsk-10:sources-and-reliability', 'Purpose', 'Why a text was made: to inform, entertain, persuade or sell.', 2),
  ('engelsk-10:sources-and-reliability', 'Fake news', 'False information presented as real news.', 3),
  ('engelsk-10:sources-and-reliability', 'Bias', 'A one-sided presentation of information.', 4),
  ('engelsk-10:sources-and-reliability', 'Clickbait', 'Exaggerated headlines designed to make you click.', 5),
  ('engelsk-10:sources-and-reliability', 'Lateral reading', 'Checking what other sources say about a website or claim, in new tabs.', 6),
  ('engelsk-10:sources-and-reliability', 'Fact-checking', 'Checking whether a claim is true, often using specialised sites.', 7),
  ('engelsk-10:sources-and-reliability', 'Quoting', 'Using someone''s exact words in quotation marks, with a reference.', 8),
  ('engelsk-10:sources-and-reliability', 'Paraphrasing', 'Expressing someone''s ideas in your own words, still with a reference.', 9),
  ('engelsk-10:sources-and-reliability', 'Summarising', 'Giving the main points of a longer text briefly.', 10),
  ('engelsk-10:sources-and-reliability', 'Signal phrase', 'Words that introduce a source: According to…, As … argues…', 11),
  ('engelsk-10:sources-and-reliability', 'List of references', 'A list of all sources used, with author, title, date and URL.', 12),
  ('engelsk-10:sources-and-reliability', 'Plagiarism', 'Presenting someone else''s work or ideas as your own.', 13),
  ('engelsk-10:sources-and-reliability', 'AI and sources', 'AI tools can invent facts and sources. Always check and be open about your use.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-10:sources-and-reliability', 'q01', 'flervalg', 'Which question helps you find out if a source is current?', array['Who wrote it?', 'When was it published or updated?', 'Why was it written?', 'Where is it published?']::text[], 1, 'The date tells you whether the information might be outdated.', true, true, 0),
  ('engelsk-10:sources-and-reliability', 'q02', 'flervalg', 'What is bias?', array['A spelling mistake', 'A one-sided presentation of information', 'A reference list', 'A type of website']::text[], 1, 'A biased text may leave out information that does not support its view.', true, true, 1),
  ('engelsk-10:sources-and-reliability', 'q03', 'flervalg', 'Which is a warning sign of fake news?', array['A named expert author', 'Links to research', 'A shocking headline and no sources', 'A recent date']::text[], 2, 'Sensational headlines without sources are typical of fake news.', true, true, 2),
  ('engelsk-10:sources-and-reliability', 'q04', 'flervalg', 'What is paraphrasing?', array['Copying a text word for word', 'Writing a reference list', 'Deleting sources', 'Expressing someone''s ideas in your own words']::text[], 3, 'Paraphrasing uses your own words, but you must still give the source.', true, true, 3),
  ('engelsk-10:sources-and-reliability', 'q05', 'flervalg', 'What is lateral reading?', array['Checking what other sources say about a site or claim', 'Reading from left to right', 'Reading only the headline', 'Reading very slowly']::text[], 0, 'Fact-checkers often leave a site quickly to see what others say about it.', true, true, 4),
  ('engelsk-10:sources-and-reliability', 'q06', 'flervalg', 'Which is a signal phrase?', array['Once upon a time', 'According to the World Health Organization,', 'Yours sincerely', 'The end']::text[], 1, '“According to…” introduces a source in your text.', true, true, 5),
  ('engelsk-10:sources-and-reliability', 'q07', 'flervalg', 'What is plagiarism?', array['Using many sources', 'Quoting correctly', 'Presenting someone else''s work as your own', 'Writing a summary']::text[], 2, 'Plagiarism is a serious form of cheating.', true, true, 6),
  ('engelsk-10:sources-and-reliability', 'q08', 'flervalg', 'Why should you check facts from an AI chatbot?', array['Because AI is always right', 'Because AI only writes in Norwegian', 'Because it is forbidden to use AI', 'Because AI can produce convincing text that is wrong']::text[], 3, 'AI tools can make mistakes and even invent sources.', true, false, 7),
  ('engelsk-10:sources-and-reliability', 'q09', 'flervalg', 'What is clickbait?', array['A fishing tool', 'A headline designed to make you click, often exaggerated', 'A reliable news source', 'A type of reference']::text[], 1, 'Clickbait often promises more than the article delivers.', true, false, 8),
  ('engelsk-10:sources-and-reliability', 'q10', 'flervalg', 'What should a reference list include for a web page?', array['Only the URL', 'Only the title', 'Author, title, date and URL', 'Only your opinion of the page']::text[], 2, 'Enough information for the reader to find and check the source.', true, true, 9),
  ('engelsk-10:sources-and-reliability', 'm01', 'sant-usant', 'A text can be biased even if all the facts in it are true.', array['Sant', 'Usant']::text[], 0, 'Bias can come from what is left out or how facts are presented.', false, true, 10),
  ('engelsk-10:sources-and-reliability', 'm02', 'sant-usant', 'You do not need to give a source when you paraphrase.', array['Sant', 'Usant']::text[], 1, 'Paraphrased ideas still come from someone else and need a reference.', false, true, 11),
  ('engelsk-10:sources-and-reliability', 'm03', 'sant-usant', 'AI chatbots can invent sources that do not exist.', array['Sant', 'Usant']::text[], 0, 'This is why all facts and references from AI must be checked.', false, true, 12),
  ('engelsk-10:sources-and-reliability', 'm04', 'sant-usant', 'An anonymous blog is always as reliable as a research institution.', array['Sant', 'Usant']::text[], 1, 'Without a known author and sources, it is hard to judge reliability.', false, true, 13),
  ('engelsk-10:sources-and-reliability', 'm05', 'flervalg', 'What is the purpose of an advertisement?', array['To sell or persuade', 'To give neutral information', 'To report news', 'To entertain only']::text[], 0, 'Advertisements want you to buy something, so they present only the positive sides.', false, true, 14),
  ('engelsk-10:sources-and-reliability', 'm06', 'flervalg', 'Which source is usually most reliable for health information?', array['An anonymous forum post', 'A national health authority''s website', 'A product advertisement', 'A meme']::text[], 1, 'Official health authorities base their information on research and expert review.', false, true, 15),
  ('engelsk-10:sources-and-reliability', 'm07', 'flervalg', 'What does summarising mean?', array['Copying the whole text', 'Adding your own opinions only', 'Giving the main points of a text briefly', 'Translating a text']::text[], 2, 'A summary shortens a text to its key ideas.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-10:sources-and-reliability', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-10:sources-and-reliability', 's01', 'What does it mean to be source-critical, and why is this useful when you search for information?', 'Being source-critical means asking questions about a source before trusting and using it. This helps you avoid relying on false or misleading information.', array['Explains that source criticism involves checking or questioning a source before trusting it.', 'Explains that this can help avoid false or misleading information.']::text[], 0),
  ('engelsk-10:sources-and-reliability', 's02', 'Explain the difference between bias and fake news. Can a biased text still be true?', 'Bias is a one-sided presentation of information, while fake news is false information presented as real news. A biased text can still be true if it only includes facts that support one side.', array['Distinguishes one-sided presentation from false information presented as real news.', 'Explains that a biased text can be true, for example by leaving out facts that support another side.']::text[], 1),
  ('engelsk-10:sources-and-reliability', 's03', 'A company publishes a page praising one of its products. What is the likely purpose of the page, and what should you do before trusting its claims?', 'The likely purpose is to sell the product. Check the evidence for its claims and compare them with what other reliable sources say, rather than assuming the claims are true.', array['Identifies selling or persuading people to buy as the likely purpose.', 'Recommends checking evidence or comparing the claims with other reliable sources.']::text[], 2),
  ('engelsk-10:sources-and-reliability', 's04', 'You find a claim on a website you do not know. Describe how you could use lateral reading to check the claim.', 'Open new tabs and look for what other sources say about the website and the claim. You can also use a fact-checking site to check whether the claim is true.', array['Describes checking the website or claim using other sources in new tabs.', 'Mentions checking whether other reliable sources support the claim or using a fact-checking site.']::text[], 3),
  ('engelsk-10:sources-and-reliability', 's05', 'Compare quoting and paraphrasing. Explain what you do in each and what you must include in both cases.', 'When quoting, you use someone''s exact words in quotation marks. When paraphrasing, you express someone''s ideas in your own words. Both require a reference to the source.', array['Explains that a quote uses the source''s exact words, while a paraphrase uses your own words to express the idea.', 'States that both require a reference to the source.']::text[], 4),
  ('engelsk-10:sources-and-reliability', 's06', 'A long article explains several points, and you want to give a brief account of its main ideas. What kind of writing should you use, and how is it different from paraphrasing?', 'You should summarise the article by briefly giving its main points. Paraphrasing expresses a particular idea from a source in your own words rather than briefly covering the main points of a longer text.', array['Identifies summarising as briefly giving the main points of a longer text.', 'Distinguishes this from paraphrasing an idea in your own words.']::text[], 5),
  ('engelsk-10:sources-and-reliability', 's07', 'An AI chatbot gives you a fact and names a source for it. What should you do before using this information, and what should you be open about?', 'Check the fact using reliable sources and make sure the named source is real, because AI can invent facts and sources. Be open about how you used AI.', array['Says to verify the fact using reliable sources and recognises that the chatbot may invent information or sources.', 'Says to be open about how AI was used.']::text[], 6),
  ('engelsk-10:sources-and-reliability', 's08', 'You need to decide whether to use information from an unfamiliar website. Explain how the questions “Who?” and “Why?” can help you assess it.', '“Who?” helps you find out who wrote the information and whether the author or organisation is an expert. “Why?” helps you check whether the website gives evidence and sources, and whether other reliable sources agree.', array['Explains that “Who?” is about identifying the author or organisation and assessing their expertise.', 'Explains that “Why?” involves checking evidence or sources and comparing with reliable sources.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-10:oral-communication', 'engelsk-10', 'oral-communication', 'Oral communication', 'How to take part in discussions, ask follow-up questions, give presentations and use natural, idiomatic English when you speak.', array[6, 5, 3]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-10:oral-communication', '## Speaking with confidence
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-10:oral-communication', 'In my opinion…', 'A phrase for giving your opinion.', 0),
  ('engelsk-10:oral-communication', 'I see what you mean, but…', 'A polite way to disagree.', 1),
  ('engelsk-10:oral-communication', 'Sorry to interrupt, but…', 'A polite way to interrupt.', 2),
  ('engelsk-10:oral-communication', 'Could you give an example?', 'A phrase for asking for clarification.', 3),
  ('engelsk-10:oral-communication', 'Follow-up question', 'A question that builds on what someone just said: Why do you think so?', 4),
  ('engelsk-10:oral-communication', 'Open question', 'A question starting with why, how or what, which invites a longer answer.', 5),
  ('engelsk-10:oral-communication', 'Closed question', 'A question that can be answered with yes or no.', 6),
  ('engelsk-10:oral-communication', 'Signposting', 'Phrases that guide listeners: First… Moving on to… Finally…', 7),
  ('engelsk-10:oral-communication', 'Keyword notes', 'Short notes instead of a full script, so you can speak freely.', 8),
  ('engelsk-10:oral-communication', 'Fluency', 'Speaking smoothly without too many long pauses.', 9),
  ('engelsk-10:oral-communication', 'Fillers', 'Words like “well” and “let me think” that give you time to think.', 10),
  ('engelsk-10:oral-communication', 'I''m on the fence', 'I haven''t decided yet.', 11),
  ('engelsk-10:oral-communication', 'That makes sense', 'I understand and agree with the logic.', 12),
  ('engelsk-10:oral-communication', 'It''s up to you', 'You decide.', 13),
  ('engelsk-10:oral-communication', 'Intonation', 'The melody of speech. Varying it keeps listeners interested.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-10:oral-communication', 'q01', 'flervalg', 'Which phrase is a polite way to disagree?', array['You''re wrong!', 'I see what you mean, but I''m not sure I agree.', 'That''s stupid.', 'Whatever.']::text[], 1, 'Acknowledging the other person''s point before disagreeing keeps the discussion respectful.', true, true, 0),
  ('engelsk-10:oral-communication', 'q02', 'flervalg', 'Which is an open question?', array['Do you like football?', 'Is it raining?', 'Why do you think the law should change?', 'Are you ready?']::text[], 2, 'Open questions start with words like why, how and what, and invite longer answers.', true, true, 1),
  ('engelsk-10:oral-communication', 'q03', 'flervalg', 'What is signposting in a presentation?', array['Phrases that guide the audience through your talk', 'Drawing road signs', 'Holding up a poster', 'Reading the whole script']::text[], 0, 'Phrases like “Moving on to…” help the audience follow your structure.', true, true, 2),
  ('engelsk-10:oral-communication', 'q04', 'flervalg', 'What does “I''m on the fence” mean?', array['I''m sitting outside', 'I''m angry', 'I agree completely', 'I haven''t decided yet']::text[], 3, 'The idiom means you have not made up your mind.', true, true, 3),
  ('engelsk-10:oral-communication', 'q05', 'flervalg', 'Why are follow-up questions useful?', array['They end the conversation', 'They show you are listening and keep the conversation going', 'They change the topic', 'They are required by law']::text[], 1, 'Follow-up questions show interest and help the other person say more.', true, true, 4),
  ('engelsk-10:oral-communication', 'q06', 'flervalg', 'What is best to use as support during a presentation?', array['A full script you read word for word', 'No preparation', 'Short notes with keywords', 'Only your phone screen']::text[], 2, 'Keyword notes help you remember your points while still speaking freely to the audience.', true, true, 5),
  ('engelsk-10:oral-communication', 'q07', 'flervalg', 'Which phrase can you use to interrupt politely?', array['Stop talking!', 'Be quiet!', 'Sorry to interrupt, but can I add something?', 'Hey, listen to me!']::text[], 2, 'Apologising before interrupting is polite in English-speaking cultures.', true, true, 6),
  ('engelsk-10:oral-communication', 'q08', 'flervalg', 'What is fluency?', array['Speaking smoothly without too many long pauses', 'Having no accent', 'Speaking very fast', 'Using difficult words']::text[], 0, 'Fluency is about flow. You can be fluent and still have an accent.', true, false, 7),
  ('engelsk-10:oral-communication', 'q09', 'flervalg', 'What can you say to gain time when you need to think?', array['Nothing, just stop', 'Switch to Norwegian', 'Leave the room', 'Well, let me think…']::text[], 3, 'Fillers like “well, let me think” keep the conversation going in English.', true, true, 8),
  ('engelsk-10:oral-communication', 'q10', 'flervalg', 'What should the conclusion of a presentation include?', array['A completely new topic', 'A summary and a thank you, and an invitation for questions', 'Only a joke', 'Nothing']::text[], 1, 'The conclusion wraps up and gives the audience a chance to ask questions.', true, false, 9),
  ('engelsk-10:oral-communication', 'm01', 'sant-usant', 'You must speak without any accent to communicate well in English.', array['Sant', 'Usant']::text[], 1, 'Clarity matters more than accent. Many fluent speakers have an accent.', false, true, 10),
  ('engelsk-10:oral-communication', 'm02', 'sant-usant', '“That''s a good point” is a way of agreeing.', array['Sant', 'Usant']::text[], 0, 'It shows that you appreciate what the other person said.', false, true, 11),
  ('engelsk-10:oral-communication', 'm03', 'sant-usant', 'Slides should replace what you say in a presentation.', array['Sant', 'Usant']::text[], 1, 'Slides should support your talk, not replace it.', false, true, 12),
  ('engelsk-10:oral-communication', 'm04', 'sant-usant', '“To be honest” is an idiomatic expression.', array['Sant', 'Usant']::text[], 0, 'It is a common phrase used to introduce an honest opinion.', false, true, 13),
  ('engelsk-10:oral-communication', 'm05', 'flervalg', 'Which is a closed question?', array['How did you feel?', 'What happened next?', 'Did you like the film?', 'Why do you think so?']::text[], 2, '“Did you like the film?” can be answered with yes or no.', false, true, 14),
  ('engelsk-10:oral-communication', 'm06', 'flervalg', 'What does “It''s up to you” mean?', array['You decide', 'Go upstairs', 'It is your turn to pay', 'You are late']::text[], 0, '“It''s up to you” means the choice is yours.', false, true, 15),
  ('engelsk-10:oral-communication', 'm07', 'flervalg', 'Which phrase is signposting?', array['I''m on the fence.', 'Moving on to my second point…', 'Sorry to interrupt.', 'That makes sense.']::text[], 1, '“Moving on to…” tells the audience you are starting a new part.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-10:oral-communication', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-10:oral-communication', 's01', 'Some people understand English well but feel unsure when they speak. Explain why practice can help, and what the main goal of speaking English is.', 'Practice helps you feel more confident when speaking. The goal is not to speak perfectly, but to get your message across, listen to others and keep the conversation going.', array['Explains that practice can help with feeling unsure or speaking with confidence.', 'Explains that the aim is to communicate and take part in the conversation, not to be perfect.']::text[], 0),
  ('engelsk-10:oral-communication', 's02', 'Compare these questions: “Did you enjoy the presentation?” and “What did you think of the presentation?” Explain which is open and which is closed, and how the answers may differ.', '“Did you enjoy the presentation?” is closed because it can be answered yes or no. “What did you think of the presentation?” is open and invites a longer answer.', array['Identifies the yes-or-no question as closed and the other question as open.', 'Explains that an open question invites a longer answer than a closed question.']::text[], 1),
  ('engelsk-10:oral-communication', 's03', 'Your discussion partner says that only one person should speak in a group discussion. You disagree and think everyone should get a chance to speak. Write a polite response using “I see what you mean, but…”', 'I see what you mean, but I think everyone should get a chance to speak in a group discussion.', array['Uses “I see what you mean, but…” to disagree politely.', 'Clearly expresses the view that everyone should have a chance to speak.']::text[], 2),
  ('engelsk-10:oral-communication', 's04', 'Explain how the introduction, main part and conclusion each help give a presentation a clear structure.', 'The introduction greets the audience, presents the topic and says what the presentation will cover. The main part develops the main points with examples, and the conclusion sums up the presentation.', array['Explains the introduction’s role in introducing the topic and preparing the audience.', 'Explains that the main part develops points and that the conclusion sums things up.']::text[], 3),
  ('engelsk-10:oral-communication', 's05', 'You are preparing a presentation and have notes with only a few keywords. Explain why using these notes can be better than reading a full script.', 'Keyword notes help you speak more freely instead of reading every word. They remind you of your main ideas while allowing you to speak to the audience.', array['Explains that keyword notes remind the speaker of important ideas.', 'Explains that notes allow the speaker to speak more freely than a full script.']::text[], 4),
  ('engelsk-10:oral-communication', 's06', 'A speaker talks very quickly and uses the same tone throughout a presentation. Suggest two changes that would make the speech clearer or more interesting for the audience.', 'The speaker should slow down and pause between ideas. They could also vary their intonation so the speech does not sound monotonous.', array['Suggests speaking slowly or pausing between ideas to improve clarity.', 'Suggests varying intonation to make the speech less monotonous.']::text[], 5),
  ('engelsk-10:oral-communication', 's07', 'Explain how you might adapt your English when talking with friends and when speaking in a job interview.', 'With friends, you can use informal language. In a job interview, you should be more careful and polite.', array['Describes friends as a situation where informal language is suitable.', 'Describes a job interview as a situation where more careful and polite language is suitable.']::text[], 6),
  ('engelsk-10:oral-communication', 's08', 'Your friend asks who should choose what you do after school. Reply using “It’s up to you” and explain what your reply means.', 'It’s up to you. That means you can decide what we do after school.', array['Uses “It’s up to you” in a reply to the situation.', 'Explains that the friend is the one who gets to decide.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-10:youth-literature', 'engelsk-10', 'youth-literature', 'Young adult literature', 'What young adult fiction is, typical genres and themes, some well-known English-language novels, and how to read, interpret and write about a novel.', array[11, 10, 18]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-10:youth-literature', '## What is young adult fiction?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-10:youth-literature', 'Young adult fiction (YA)', 'Fiction written mainly for readers aged about 12–18, with teenage main characters.', 0),
  ('engelsk-10:youth-literature', 'Coming-of-age story', 'A story where the main character grows up and changes.', 1),
  ('engelsk-10:youth-literature', 'Bildungsroman', 'Another term for a coming-of-age novel.', 2),
  ('engelsk-10:youth-literature', 'Dystopian fiction', 'Stories about a frightening, oppressive future society.', 3),
  ('engelsk-10:youth-literature', 'Realistic fiction', 'Stories about everyday life that could really happen.', 4),
  ('engelsk-10:youth-literature', 'The Catcher in the Rye', 'Novel by J.D. Salinger (1951) about a teenager''s alienation.', 5),
  ('engelsk-10:youth-literature', 'The Outsiders', 'Novel by S.E. Hinton (1967) about rival gangs and loyalty.', 6),
  ('engelsk-10:youth-literature', 'The Hunger Games', 'Dystopian novel by Suzanne Collins (2008).', 7),
  ('engelsk-10:youth-literature', 'Wonder', 'Novel by R.J. Palacio (2012) about a boy with a facial difference starting school.', 8),
  ('engelsk-10:youth-literature', 'The Hate U Give', 'Novel by Angie Thomas (2017) about racism and police violence.', 9),
  ('engelsk-10:youth-literature', 'First-person voice', 'Common in YA; makes the reader feel close to the narrator.', 10),
  ('engelsk-10:youth-literature', 'Book review', 'A text that presents a book and gives the writer''s evaluation, without spoilers.', 11),
  ('engelsk-10:youth-literature', 'Spoiler', 'Information that reveals important plot twists or the ending.', 12),
  ('engelsk-10:youth-literature', 'Personal response', 'Your own reflection on what the book made you think or feel, and why.', 13),
  ('engelsk-10:youth-literature', 'Present tense', 'Used when writing about what happens in a story.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-10:youth-literature', 'q01', 'flervalg', 'What is young adult fiction?', array['Books only for adults', 'Fiction mainly for teenage readers, with teenage main characters', 'Non-fiction about youth', 'Picture books']::text[], 1, 'YA is aimed at readers of about 12–18, though many adults read it too.', true, true, 0),
  ('engelsk-10:youth-literature', 'q02', 'flervalg', 'What is a coming-of-age story?', array['A story about old people', 'A story where the main character grows up and changes', 'A story about time travel', 'A story without characters']::text[], 1, 'The main character matures through experiences and challenges.', true, true, 1),
  ('engelsk-10:youth-literature', 'q03', 'flervalg', 'What is dystopian fiction?', array['Stories about a perfect society', 'Love stories', 'Stories about a frightening, oppressive future society', 'Biographies']::text[], 2, 'Dystopias show societies with control, fear and injustice, like in The Hunger Games.', true, true, 2),
  ('engelsk-10:youth-literature', 'q04', 'flervalg', 'Who wrote The Hate U Give?', array['Angie Thomas', 'Suzanne Collins', 'J.D. Salinger', 'Mark Haddon']::text[], 0, 'Angie Thomas published the novel in 2017.', true, true, 3),
  ('engelsk-10:youth-literature', 'q05', 'flervalg', 'Why is the first-person voice common in YA?', array['It is required', 'It makes the reader feel close to the narrator', 'It makes the book shorter', 'It hides the main character']::text[], 1, 'The personal “I” lets readers experience the character''s thoughts and feelings directly.', true, true, 4),
  ('engelsk-10:youth-literature', 'q06', 'flervalg', 'What should a book review avoid?', array['The title', 'The author', 'The writer''s opinion', 'Spoilers that reveal the ending']::text[], 3, 'A review should make readers curious, not reveal the big surprises.', true, true, 5),
  ('engelsk-10:youth-literature', 'q07', 'flervalg', 'Which theme is common in YA literature?', array['Retirement', 'Tax law', 'Identity and belonging', 'Gardening techniques']::text[], 2, 'Questions about who you are and where you belong are central in many YA books.', true, true, 6),
  ('engelsk-10:youth-literature', 'q08', 'flervalg', 'What is S.E. Hinton known for?', array['Writing The Outsiders as a teenager', 'Writing Harry Potter', 'Writing The Hunger Games', 'Directing films']::text[], 0, 'Hinton wrote The Outsiders while she was still in high school; it was published in 1967.', true, false, 7),
  ('engelsk-10:youth-literature', 'q09', 'flervalg', 'Which tense should you use when you write about events in a novel?', array['Future tense', 'Past perfect', 'Present tense', 'Any tense, mixed']::text[], 2, 'Literary texts are discussed in the present tense: “The narrator describes…”.', true, true, 8),
  ('engelsk-10:youth-literature', 'q10', 'flervalg', 'What is a personal response?', array['A summary of the plot', 'Your own reflection on what the book made you think or feel', 'The author''s biography', 'A list of characters']::text[], 1, 'A personal response connects the book to your own thoughts and experiences.', true, false, 9),
  ('engelsk-10:youth-literature', 'm01', 'sant-usant', 'Only teenagers read young adult fiction.', array['Sant', 'Usant']::text[], 1, 'Many adults also read and enjoy YA books.', false, true, 10),
  ('engelsk-10:youth-literature', 'm02', 'sant-usant', 'The Hunger Games is an example of dystopian fiction.', array['Sant', 'Usant']::text[], 0, 'It shows an oppressive future society where teenagers must fight to survive.', false, true, 11),
  ('engelsk-10:youth-literature', 'm03', 'sant-usant', 'A good book review includes the writer''s evaluation of the book.', array['Sant', 'Usant']::text[], 0, 'A review tells the reader what you thought and why.', false, true, 12),
  ('engelsk-10:youth-literature', 'm04', 'sant-usant', 'The Catcher in the Rye was published in 2008.', array['Sant', 'Usant']::text[], 1, 'The Catcher in the Rye by J.D. Salinger was published in 1951.', false, true, 13),
  ('engelsk-10:youth-literature', 'm05', 'flervalg', 'Which novel is about a boy with a facial difference who starts school?', array['The Outsiders', 'Wonder', 'The Hunger Games', 'The Catcher in the Rye']::text[], 1, 'Wonder by R.J. Palacio follows Auggie as he starts school.', false, true, 14),
  ('engelsk-10:youth-literature', 'm06', 'flervalg', 'What is a spoiler?', array['A bad review', 'Information that reveals important plot twists or the ending', 'A book cover', 'A genre']::text[], 1, 'Spoilers ruin the surprise for readers who have not read the book.', false, true, 15),
  ('engelsk-10:youth-literature', 'm07', 'flervalg', 'What should you note while reading a novel?', array['Only the page numbers', 'Characters, setting, events and striking quotations', 'The price of the book', 'Nothing, just read']::text[], 1, 'Notes make it much easier to write about the novel afterwards.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-10:youth-literature', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-10:youth-literature', 's01', 'A teenager is trying to understand who they are and where they belong. They are also dealing with conflict at home while becoming more independent. Name two YA themes shown in this situation and explain how each one fits.', 'The situation shows identity, because the teenager is trying to understand who they are and where they belong. It also shows family conflict and becoming independent, because they are dealing with conflict at home while growing more independent.', array['Identifies identity and connects it to questions of who the teenager is or where they belong.', 'Identifies family conflict or becoming independent and connects it to the situation.']::text[], 0),
  ('engelsk-10:youth-literature', 's02', 'Compare the main situations in *The Catcher in the Rye* and *The Outsiders*. What is each novel about?', '*The Catcher in the Rye* is about a teenager who feels alienated from the adult world. *The Outsiders* is about rival gangs and loyalty.', array['Connects *The Catcher in the Rye* with a teenager’s alienation from the adult world.', 'Connects *The Outsiders* with rival gangs and loyalty.']::text[], 1),
  ('engelsk-10:youth-literature', 's03', 'A story follows a teenager through everyday events that could really happen. It has no magic or other worlds. Which genre best fits, and why is it a better fit than fantasy?', 'Realistic fiction fits best because the events could happen in everyday life. Fantasy often includes magic or other worlds, which are not part of this story.', array['Identifies realistic fiction and explains that the events could happen in everyday life.', 'Distinguishes it from fantasy by referring to magic or other worlds.']::text[], 2),
  ('engelsk-10:youth-literature', 's04', 'You want to show that a novel’s main character changes during the story. What reading notes would help you support this idea, and how would you use them?', 'I would use notes about the character and important events. Comparing how the character acts or thinks at different points can show how the events have changed them.', array['Uses notes about the character and/or important events as evidence.', 'Explains that comparing different points in the story can show the character’s change.']::text[], 3),
  ('engelsk-10:youth-literature', 's05', 'You are writing an analysis and want to discuss a novel’s language or themes. What could you include as evidence, and how would it help?', 'I could include quotations from the novel. They give evidence for what I say about the language or themes.', array['Identifies quotations from the novel as evidence.', 'Explains that quotations support a point about language or themes.']::text[], 4),
  ('engelsk-10:youth-literature', 's06', 'A student is choosing between writing a book review and an analysis. Explain how the focus of the plot summary differs in the two forms, and name one other element they can discuss.', 'A review gives a short summary without spoilers, while an analysis focuses on key events. Both can discuss characters, themes or language, using quotations.', array['Explains that a review’s summary avoids spoilers and an analysis focuses on key events.', 'Names a shared discussion element, such as characters, themes or language, or the use of quotations.']::text[], 5),
  ('engelsk-10:youth-literature', 's07', 'Compare the challenges faced by the main characters in *Wonder* and *The Hate U Give*.', 'In *Wonder*, a boy with a facial difference starts school. In *The Hate U Give*, a girl witnesses police violence and finds her voice.', array['Connects *Wonder* with a boy with a facial difference starting school.', 'Connects *The Hate U Give* with a girl witnessing police violence and finding her voice.']::text[], 6),
  ('engelsk-10:youth-literature', 's08', 'When writing about a novel in present tense, a writer can also connect it to the world around them. Choose either their own life or another book or film as a comparison, and explain what aspect of growing up they could compare.', 'A writer could compare the character’s experience of becoming independent with something from their own life. This can help them consider how the novel’s ideas about growing up relate to life outside the story.', array['Chooses a comparison with their own life or another book or film.', 'Explains how the comparison relates to growing up or an idea in the novel.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-10:film-music-and-media', 'engelsk-10', 'film-music-and-media', 'Film, music and media', 'How to explore and talk about English-language films, series, songs and games – with film techniques, song analysis and writing reviews.', array[19, 10, 14]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-10:film-music-and-media', '## Culture you already know
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-10:film-music-and-media', 'Cultural expression', 'Films, music, art, games and other creative works that express culture.', 0),
  ('engelsk-10:film-music-and-media', 'Genre', 'A category of film, music or literature: comedy, thriller, horror, documentary.', 1),
  ('engelsk-10:film-music-and-media', 'Close-up', 'A camera shot showing a face or detail up close, often to show emotion.', 2),
  ('engelsk-10:film-music-and-media', 'Long shot', 'A camera shot that shows the whole setting.', 3),
  ('engelsk-10:film-music-and-media', 'Point-of-view shot', 'Shows what a character sees.', 4),
  ('engelsk-10:film-music-and-media', 'Low angle', 'Camera looks up at a character, making them look powerful.', 5),
  ('engelsk-10:film-music-and-media', 'High angle', 'Camera looks down at a character, making them look small or weak.', 6),
  ('engelsk-10:film-music-and-media', 'Soundtrack', 'The music in a film, which creates mood and tension.', 7),
  ('engelsk-10:film-music-and-media', 'Editing', 'How shots are put together. Fast cuts create energy.', 8),
  ('engelsk-10:film-music-and-media', 'Lyrics', 'The words of a song.', 9),
  ('engelsk-10:film-music-and-media', 'Chorus', 'The repeated part of a song, often carrying its main message.', 10),
  ('engelsk-10:film-music-and-media', 'Protest song', 'A song that criticises injustice or supports a cause.', 11),
  ('engelsk-10:film-music-and-media', 'Review', 'A text that presents and evaluates a film, album, book or game.', 12),
  ('engelsk-10:film-music-and-media', 'Gripping / predictable', 'Adjectives for reviews: very exciting / easy to guess.', 13),
  ('engelsk-10:film-music-and-media', 'Rating', 'A score, like stars, given at the end of a review.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-10:film-music-and-media', 'q01', 'flervalg', 'What does a close-up usually show?', array['The whole landscape', 'A character''s emotions or an important detail', 'The credits', 'The audience']::text[], 1, 'Close-ups bring us near a face or object so we notice feelings and details.', true, true, 0),
  ('engelsk-10:film-music-and-media', 'q02', 'flervalg', 'What effect does a low camera angle often have?', array['The character looks powerful', 'The character looks weak', 'The scene looks funny', 'The scene becomes silent']::text[], 0, 'Looking up at someone makes them seem bigger and more powerful.', true, true, 1),
  ('engelsk-10:film-music-and-media', 'q03', 'flervalg', 'What is the chorus of a song?', array['The first line', 'The instruments', 'The repeated part that often carries the main message', 'The singer''s name']::text[], 2, 'The chorus is repeated, which makes its message stick.', true, true, 2),
  ('engelsk-10:film-music-and-media', 'q04', 'flervalg', 'What should a review include at the end?', array['A spoiler', 'A list of all actors', 'The whole plot', 'A conclusion with a recommendation']::text[], 3, 'Readers want to know whether you recommend the film, album or game.', true, true, 3),
  ('engelsk-10:film-music-and-media', 'q05', 'flervalg', 'What does the soundtrack do in a film?', array['Shows the setting', 'Creates mood and tension', 'Lists the actors', 'Translates the dialogue']::text[], 1, 'Music strongly affects how we feel during a scene.', true, true, 4),
  ('engelsk-10:film-music-and-media', 'q06', 'flervalg', 'Which adjective means “easy to guess” in a review?', array['predictable', 'breathtaking', 'gripping', 'moving']::text[], 0, 'A predictable plot has no surprises.', true, true, 5),
  ('engelsk-10:film-music-and-media', 'q07', 'flervalg', 'What is a protest song?', array['A love song', 'A song for children', 'A song that criticises injustice or supports a cause', 'A song without lyrics']::text[], 2, 'Protest songs have been important in movements for civil rights and peace.', true, false, 6),
  ('engelsk-10:film-music-and-media', 'q08', 'flervalg', 'Which shot shows the whole setting?', array['Close-up', 'Long shot', 'Point-of-view shot', 'Extreme close-up']::text[], 1, 'A long shot shows characters in their surroundings.', true, true, 7),
  ('engelsk-10:film-music-and-media', 'q09', 'flervalg', 'Why is context important when analysing a song?', array['It is not important', 'It tells you the song''s length', 'It changes the lyrics', 'It helps explain what the song is reacting to']::text[], 3, 'Knowing when and why a song was made can explain its message.', true, false, 8),
  ('engelsk-10:film-music-and-media', 'q10', 'flervalg', 'What can fast editing create in a film?', array['Calm and peace', 'Silence', 'Energy and tension', 'Longer scenes']::text[], 2, 'Quick cuts make action scenes feel intense and exciting.', true, true, 9),
  ('engelsk-10:film-music-and-media', 'm01', 'sant-usant', 'A high camera angle can make a character look small or weak.', array['Sant', 'Usant']::text[], 0, 'Looking down on a character makes them seem vulnerable.', false, true, 10),
  ('engelsk-10:film-music-and-media', 'm02', 'sant-usant', 'Songs can be analysed using some of the same terms as poems.', array['Sant', 'Usant']::text[], 0, 'Lyrics use metaphors, rhyme and repetition, just like poems.', false, true, 11),
  ('engelsk-10:film-music-and-media', 'm03', 'sant-usant', 'A review should reveal the ending of the film.', array['Sant', 'Usant']::text[], 1, 'Reviews avoid spoilers so that readers can enjoy the film themselves.', false, true, 12),
  ('engelsk-10:film-music-and-media', 'm04', 'sant-usant', 'English-language culture comes only from the USA and the UK.', array['Sant', 'Usant']::text[], 1, 'Many countries, like Nigeria, India, Ireland and Jamaica, produce English-language culture.', false, true, 13),
  ('engelsk-10:film-music-and-media', 'm05', 'flervalg', 'Which word could describe a film that made you cry?', array['moving', 'predictable', 'clichéd', 'boring']::text[], 0, '“Moving” means that it touched your emotions.', false, true, 14),
  ('engelsk-10:film-music-and-media', 'm06', 'flervalg', 'What is a point-of-view shot?', array['A shot of the audience', 'A shot showing what a character sees', 'A shot from above', 'A shot of the credits']::text[], 1, 'It lets the viewer see through a character''s eyes.', false, true, 15),
  ('engelsk-10:film-music-and-media', 'm07', 'flervalg', 'What makes many video games different from films as storytelling?', array['They have no characters', 'They never have music', 'The player can make choices that change the story', 'They are always silent']::text[], 2, 'Interactivity lets the player influence what happens.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-10:film-music-and-media', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-10:film-music-and-media', 's01', 'What is a cultural expression? Explain in your own words and give two examples of things that can be cultural expressions.', 'A cultural expression is a creative work that expresses culture. Films and music are two examples.', array['Explains that it is a creative work that expresses culture.', 'Gives two suitable examples, such as films, music, art or games.']::text[], 0),
  ('engelsk-10:film-music-and-media', 's02', 'In a film scene, the camera shows exactly what a character sees. What kind of camera shot is this, and what does the audience see through it?', 'It is a point-of-view shot. The audience sees the scene from the character’s point of view.', array['Identifies the shot as a point-of-view shot.', 'Explains that the audience sees what the character sees.']::text[], 1),
  ('engelsk-10:film-music-and-media', 's03', 'A filmmaker wants a happy mood in one scene and suspense in another. Explain how bright colours and dark lighting could help create these different moods.', 'Bright colours can create a happy mood. Dark lighting can create suspense.', array['Connects bright colours with a happy mood.', 'Connects dark lighting with suspense.']::text[], 2),
  ('engelsk-10:film-music-and-media', 's04', 'A song has lyrics about sadness, along with a slow tempo and soft instruments. Explain how the music can support the lyrics.', 'The slow tempo and soft instruments can help create a sad mood. This supports the feelings expressed in the lyrics.', array['Explains that features of the music, such as tempo or instruments, can create a mood.', 'Connects that mood to the feelings or meaning in the lyrics.']::text[], 3),
  ('engelsk-10:film-music-and-media', 's05', 'In a video game, the player can make choices that change the story. Explain how this makes the player part of the storytelling.', 'The player’s choices can affect what happens in the story. This means the player helps shape how the story develops.', array['States that the player’s choices can change the story.', 'Explains that the player therefore helps shape how it develops.']::text[], 4),
  ('engelsk-10:film-music-and-media', 's06', 'A reviewer says that the acting in a film works well and refers to a particular scene as an example. Explain what makes this an evaluation and why the example is useful.', 'Saying that the acting works well is an evaluation because it judges the film. The example helps explain why the reviewer has that opinion.', array['Identifies the statement about the acting as a judgement or evaluation.', 'Explains that the example supports or explains the judgement.']::text[], 5),
  ('engelsk-10:film-music-and-media', 's07', 'What could a student learn by exploring English-language films or music from Nigeria or Jamaica as well as from the USA and the UK?', 'They could discover that English-language culture comes from many countries. Exploring works from different places shows the variety of the English-speaking world.', array['States that English-language culture comes from many countries, not just the USA and the UK.', 'Explains that exploring different places shows the variety of the English-speaking world.']::text[], 6),
  ('engelsk-10:film-music-and-media', 's08', 'When analysing a YouTube channel, what should you consider about who made it, its audience and its purpose? Explain why these questions matter.', 'You should consider who made the channel, who it is for and why it was made. These questions can help you understand how it presents people and cultures.', array['Mentions the creator, intended audience and purpose.', 'Connects these questions to understanding how people or cultures are presented.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-10:australia-new-zealand-and-canada', 'engelsk-10', 'australia-new-zealand-and-canada', 'Australia, New Zealand and Canada', 'Three English-speaking countries with British roots – their geography, history, indigenous peoples, languages and multicultural societies.', array[18, 17, 16]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-10:australia-new-zealand-and-canada', '## Three former British colonies
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-10:australia-new-zealand-and-canada', 'Commonwealth', 'An association of countries mostly with historical ties to Britain.', 0),
  ('engelsk-10:australia-new-zealand-and-canada', 'Canberra', 'The capital of Australia.', 1),
  ('engelsk-10:australia-new-zealand-and-canada', 'Outback', 'The dry, sparsely populated interior of Australia.', 2),
  ('engelsk-10:australia-new-zealand-and-canada', '1901 (Australia)', 'The Australian colonies joined as the Commonwealth of Australia.', 3),
  ('engelsk-10:australia-new-zealand-and-canada', 'Aboriginal and Torres Strait Islander peoples', 'Australia''s indigenous peoples, with among the oldest continuous cultures in the world.', 4),
  ('engelsk-10:australia-new-zealand-and-canada', 'Wellington', 'The capital of New Zealand.', 5),
  ('engelsk-10:australia-new-zealand-and-canada', 'Auckland', 'The largest city in New Zealand.', 6),
  ('engelsk-10:australia-new-zealand-and-canada', 'Treaty of Waitangi', '1840 agreement between the British Crown and Māori chiefs.', 7),
  ('engelsk-10:australia-new-zealand-and-canada', 'Te reo Māori', 'The Māori language, an official language of New Zealand.', 8),
  ('engelsk-10:australia-new-zealand-and-canada', '1893 (New Zealand)', 'First country to give women the vote in national elections.', 9),
  ('engelsk-10:australia-new-zealand-and-canada', 'Ottawa', 'The capital of Canada.', 10),
  ('engelsk-10:australia-new-zealand-and-canada', 'Bilingual Canada', 'English and French are both official languages.', 11),
  ('engelsk-10:australia-new-zealand-and-canada', 'Quebec', 'Canadian province where French is the majority language.', 12),
  ('engelsk-10:australia-new-zealand-and-canada', 'First Nations, Inuit, Métis', 'The indigenous peoples of Canada.', 13),
  ('engelsk-10:australia-new-zealand-and-canada', 'Cultural mosaic', 'Canada''s image of cultures living side by side.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-10:australia-new-zealand-and-canada', 'q01', 'flervalg', 'What is the capital of Australia?', array['Sydney', 'Melbourne', 'Canberra', 'Perth']::text[], 2, 'Canberra is the capital. Sydney and Melbourne are the largest cities.', true, true, 0),
  ('engelsk-10:australia-new-zealand-and-canada', 'q02', 'flervalg', 'What is the capital of New Zealand?', array['Wellington', 'Auckland', 'Christchurch', 'Sydney']::text[], 0, 'Wellington is the capital. Auckland is the largest city.', true, true, 1),
  ('engelsk-10:australia-new-zealand-and-canada', 'q03', 'flervalg', 'Which two languages are official in Canada?', array['English and Spanish', 'English and Inuktitut only', 'French and German', 'English and French']::text[], 3, 'Canada is officially bilingual, with English and French.', true, true, 2),
  ('engelsk-10:australia-new-zealand-and-canada', 'q04', 'flervalg', 'What is the Commonwealth?', array['A British bank', 'An association of countries mostly with historical ties to Britain', 'The Australian parliament', 'A sports competition only']::text[], 1, 'The Commonwealth includes many former British colonies.', true, true, 3),
  ('engelsk-10:australia-new-zealand-and-canada', 'q05', 'flervalg', 'What was special about New Zealand in 1893?', array['It became independent', 'It became the first country to give women the vote in national elections', 'It joined the EU', 'It changed its capital']::text[], 1, 'New Zealand was the first self-governing country where women could vote in national elections.', true, true, 4),
  ('engelsk-10:australia-new-zealand-and-canada', 'q06', 'flervalg', 'In which Canadian province is French the majority language?', array['Ontario', 'British Columbia', 'Alberta', 'Quebec']::text[], 3, 'Most people in Quebec speak French as their first language.', true, true, 5),
  ('engelsk-10:australia-new-zealand-and-canada', 'q07', 'flervalg', 'What is the Treaty of Waitangi?', array['An 1840 agreement between the British Crown and Māori chiefs', 'Australia''s constitution', 'A Canadian peace treaty', 'A sports trophy']::text[], 0, 'It is regarded as New Zealand''s founding document.', true, true, 6),
  ('engelsk-10:australia-new-zealand-and-canada', 'q08', 'flervalg', 'What is the outback?', array['Canada''s northern islands', 'A New Zealand dance', 'The dry, sparsely populated interior of Australia', 'A British tradition']::text[], 2, 'Most Australians live along the coast, while the outback has few people.', true, false, 7),
  ('engelsk-10:australia-new-zealand-and-canada', 'q09', 'flervalg', 'Who are the indigenous peoples of Canada?', array['The Māori', 'First Nations, Inuit and Métis', 'The Sámi', 'Aboriginal Australians']::text[], 1, 'Canada recognises three groups of indigenous peoples.', true, true, 8),
  ('engelsk-10:australia-new-zealand-and-canada', 'q10', 'flervalg', 'What do Australia, New Zealand and Canada have in common?', array['They all have French as an official language', 'They were never colonised', 'They are all republics with presidents', 'They were British colonies and are now democracies in the Commonwealth']::text[], 3, 'All three share British colonial roots and parliamentary democracy.', true, false, 9),
  ('engelsk-10:australia-new-zealand-and-canada', 'm01', 'sant-usant', 'Sydney is the capital of Australia.', array['Sant', 'Usant']::text[], 1, 'Canberra is the capital. Sydney is the largest city.', false, true, 10),
  ('engelsk-10:australia-new-zealand-and-canada', 'm02', 'sant-usant', 'Te reo Māori is an official language of New Zealand.', array['Sant', 'Usant']::text[], 0, 'The Māori language has official status.', false, true, 11),
  ('engelsk-10:australia-new-zealand-and-canada', 'm03', 'sant-usant', 'Canada is the second largest country in the world by area.', array['Sant', 'Usant']::text[], 0, 'Only Russia is larger.', false, true, 12),
  ('engelsk-10:australia-new-zealand-and-canada', 'm04', 'sant-usant', 'Aboriginal Australians arrived in Australia after the British.', array['Sant', 'Usant']::text[], 1, 'They have lived there for tens of thousands of years.', false, true, 13),
  ('engelsk-10:australia-new-zealand-and-canada', 'm05', 'flervalg', 'What is the largest city in Canada?', array['Ottawa', 'Montreal', 'Toronto', 'Vancouver']::text[], 2, 'Toronto is the largest city. Ottawa is the capital.', false, true, 14),
  ('engelsk-10:australia-new-zealand-and-canada', 'm06', 'flervalg', 'What is the haka?', array['A Canadian food', 'A traditional Māori dance', 'An Australian animal', 'A type of boat']::text[], 1, 'The haka is a Māori ceremonial dance, known for example from rugby matches.', false, true, 15),
  ('engelsk-10:australia-new-zealand-and-canada', 'm07', 'flervalg', 'When did Canada become self-governing?', array['1867', '1776', '1901', '1945']::text[], 0, 'Canadian Confederation took place in 1867.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-10:australia-new-zealand-and-canada', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-10:australia-new-zealand-and-canada', 's01', 'A student says that the British monarch governs Australia, New Zealand and Canada because the monarch is their formal head of state. Explain what the student has misunderstood.', 'The monarch is the formal head of state, but does not govern these countries in practice. They are governed by their own elected parliaments and prime ministers.', array['Distinguishes the monarch’s formal role from who governs in practice.', 'Identifies elected parliaments and prime ministers as the ones who govern.']::text[], 0),
  ('engelsk-10:australia-new-zealand-and-canada', 's02', 'Most people in Australia live along the coast, while much of the interior is dry and sparsely populated. Explain how these two facts are connected.', 'Much of Australia’s interior, called the outback, is dry and has few people living there. This helps explain why most Australians live along the coast.', array['Connects the dry, sparsely populated interior with where most people live.', 'Identifies the outback as Australia’s interior.']::text[], 1),
  ('engelsk-10:australia-new-zealand-and-canada', 's03', 'Australia was made up of separate British colonies. Explain what happened to these colonies in 1901 and what the new country was called.', 'In 1901, the Australian colonies joined together. The new country was called the Commonwealth of Australia.', array['Explains that the colonies joined together.', 'Names the new country as the Commonwealth of Australia.']::text[], 2),
  ('engelsk-10:australia-new-zealand-and-canada', 's04', 'The Treaty of Waitangi is seen as New Zealand’s founding document, but its interpretation has been disputed. Explain how both of these things can be true.', 'The treaty was an agreement between the British Crown and Māori chiefs in 1840, which is why it is seen as a founding document. Its interpretation has been disputed, so people have not always agreed about what it means.', array['Explains the treaty’s importance as an agreement between the British Crown and Māori chiefs.', 'Notes that people have disagreed about how to interpret it.']::text[], 3),
  ('engelsk-10:australia-new-zealand-and-canada', 's05', 'A visitor sees the haka at a national event and learns that te reo Māori is an official language. Explain what these examples show about Māori culture in New Zealand.', 'They show that Māori culture is visible in New Zealand’s national life. The haka is a cultural example, and te reo Māori is an official language.', array['Explains that Māori culture is visible in national life.', 'Uses the haka or te reo Māori accurately as an example.']::text[], 4),
  ('engelsk-10:australia-new-zealand-and-canada', 's06', 'Canada describes itself as a cultural mosaic. Explain what this means about the different cultures in the country.', 'It means that different cultures live side by side in Canada. The image presents Canada as a country made up of many cultures.', array['Explains that different cultures live side by side.', 'Connects the idea to Canada’s cultural diversity.']::text[], 5),
  ('engelsk-10:australia-new-zealand-and-canada', 's07', 'A student says that Canada has thirteen provinces and became self-governing in 1867. Correct the student’s statement.', 'Canada has ten provinces and three territories, not thirteen provinces. It became a self-governing country in 1867.', array['Correctly states that Canada has ten provinces and three territories.', 'Keeps the statement that Canada became self-governing in 1867.']::text[], 6),
  ('engelsk-10:australia-new-zealand-and-canada', 's08', 'Colonisation in Australia led to loss of land and the tragedy of the Stolen Generations for Aboriginal and Torres Strait Islander peoples. Explain how this history connects to reconciliation today.', 'The loss of land and the Stolen Generations were injustices experienced by Aboriginal and Torres Strait Islander peoples. Reconciliation includes recognising Indigenous rights and languages.', array['Connects colonisation with loss of land or the Stolen Generations.', 'Links reconciliation with recognition of Indigenous rights or languages.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-10:video-games', 'engelsk-fordypning-10', 'video-games', 'Video games as texts', 'How video games tell stories and create worlds, how they are built, their purposes, gaming language, and debates about games and society.', array[4, 7]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-10:video-games', '## Games as texts
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-10:video-games', 'Interactivity', 'The player takes part and influences what happens.', 0),
  ('engelsk-fordypning-10:video-games', 'Narrative', 'The story told in a game, with characters, conflict and themes.', 1),
  ('engelsk-fordypning-10:video-games', 'Branching narrative', 'A story where the player''s choices lead to different endings.', 2),
  ('engelsk-fordypning-10:video-games', 'World-building', 'Creating a believable setting with its own history, rules and culture.', 3),
  ('engelsk-fordypning-10:video-games', 'RPG', 'Role-playing game, where you develop a character in a story world.', 4),
  ('engelsk-fordypning-10:video-games', 'Gameplay', 'The rules and actions the player can take.', 5),
  ('engelsk-fordypning-10:video-games', 'Game mechanics', 'The systems that make a game work, like points, levels and health.', 6),
  ('engelsk-fordypning-10:video-games', 'Perspective', 'How the player sees the game: first-person, third-person or top-down.', 7),
  ('engelsk-fordypning-10:video-games', 'Cutscene', 'A short film sequence in a game that tells the story.', 8),
  ('engelsk-fordypning-10:video-games', 'In-game purchases', 'Things you can buy with real money inside a game.', 9),
  ('engelsk-fordypning-10:video-games', 'Loot box', 'A random reward you can buy in a game, often compared to gambling.', 10),
  ('engelsk-fordypning-10:video-games', 'NPC', 'Non-player character, a character controlled by the game.', 11),
  ('engelsk-fordypning-10:video-games', 'Jargon', 'Special words used by a group, like GG, lag and respawn in gaming.', 12),
  ('engelsk-fordypning-10:video-games', 'Representation', 'How different groups are shown in games and other media.', 13),
  ('engelsk-fordypning-10:video-games', 'E-sports', 'Competitive gaming, often with big tournaments.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-10:video-games', 'q01', 'flervalg', 'What makes video games different from books and films?', array['They have no stories', 'Interactivity – the player takes part and influences what happens', 'They have no sound', 'They are always short']::text[], 1, 'The player is not just watching, but acting.', true, true, 0),
  ('engelsk-fordypning-10:video-games', 'q02', 'flervalg', 'What is a branching narrative?', array['A story about trees', 'A game without a story', 'A cutscene', 'A story where the player''s choices lead to different endings']::text[], 3, 'Branching narratives make choices meaningful.', true, true, 1),
  ('engelsk-fordypning-10:video-games', 'q03', 'flervalg', 'What is an NPC?', array['A non-player character controlled by the game', 'A new player', 'A type of weapon', 'A game genre']::text[], 0, 'Shopkeepers and enemies are often NPCs.', true, true, 2),
  ('engelsk-fordypning-10:video-games', 'q04', 'flervalg', 'What is world-building?', array['Building houses in a game', 'Playing online with friends', 'Creating a believable setting with its own history, rules and culture', 'Designing the menu']::text[], 2, 'A rich world makes the story more believable.', true, true, 3),
  ('engelsk-fordypning-10:video-games', 'q05', 'flervalg', 'What is a cutscene?', array['A mistake in the game', 'A level', 'A type of weapon', 'A short film sequence that tells the story']::text[], 3, 'During a cutscene, the player usually watches instead of playing.', true, true, 4),
  ('engelsk-fordypning-10:video-games', 'q06', 'flervalg', 'Why are loot boxes debated?', array['They are too cheap', 'They have been compared to gambling', 'They make games shorter', 'They improve graphics']::text[], 1, 'Players pay for random rewards without knowing what they will get.', true, true, 5),
  ('engelsk-fordypning-10:video-games', 'q07', 'flervalg', 'What are game mechanics?', array['The people who repair consoles', 'The story of a game', 'The systems that make the game work, like points, levels and health', 'The music']::text[], 2, 'Mechanics decide how the player interacts with the game.', true, true, 6),
  ('engelsk-fordypning-10:video-games', 'q08', 'flervalg', 'What purpose does an educational game have?', array['To teach', 'To sell weapons', 'To replace school', 'To make players angry']::text[], 0, 'Educational games are used in many schools.', true, true, 7),
  ('engelsk-fordypning-10:video-games', 'q09', 'flervalg', 'What does GG mean in gaming?', array['Get going', 'Great graphics', 'Game glitch', 'Good game']::text[], 3, 'Players often write GG at the end of a match.', true, false, 8),
  ('engelsk-fordypning-10:video-games', 'q10', 'flervalg', 'What is e-sports?', array['Sports on TV', 'Competitive gaming, often with big tournaments', 'Exercise games', 'Electronic sports equipment']::text[], 1, 'The best e-sports players are professionals.', true, false, 9),
  ('engelsk-fordypning-10:video-games', 'm01', 'sant-usant', 'Many young people practise English through online games.', array['Sant', 'Usant']::text[], 0, 'English is often the shared language in international games.', false, true, 10),
  ('engelsk-fordypning-10:video-games', 'm02', 'sant-usant', 'All games have exactly the same story for every player.', array['Sant', 'Usant']::text[], 1, 'In many games, the player''s choices change the story.', false, true, 11),
  ('engelsk-fordypning-10:video-games', 'm03', 'sant-usant', 'Sound and music in games can signal danger.', array['Sant', 'Usant']::text[], 0, 'Music often changes when an enemy is near.', false, true, 12),
  ('engelsk-fordypning-10:video-games', 'm04', 'sant-usant', 'Research clearly shows that all violent games make players violent.', array['Sant', 'Usant']::text[], 1, 'Research does not give a simple answer.', false, true, 13),
  ('engelsk-fordypning-10:video-games', 'm05', 'flervalg', 'What is gameplay?', array['The rules and actions the player can take', 'The game''s price', 'The box cover', 'The credits']::text[], 0, 'Gameplay is what you actually do in the game.', false, true, 14),
  ('engelsk-fordypning-10:video-games', 'm06', 'flervalg', 'Which genre lets the player develop a character in a story world?', array['Puzzle', 'Sports', 'Role-playing game (RPG)', 'Racing']::text[], 2, 'In RPGs, characters grow stronger through the story.', false, true, 15),
  ('engelsk-fordypning-10:video-games', 'm07', 'flervalg', 'What does representation in games mean?', array['How the game is sold', 'How different groups are shown', 'How fast the game runs', 'How many levels there are']::text[], 1, 'Representation affects how players see different groups.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-10:video-games', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-10:video-games', 's01', 'Some games tell the same story to every player, while in others the player’s choices can lead to different endings. Explain how these two kinds of stories differ and how the player’s choices matter in the second kind.', 'In a game with a fixed story, the main story stays the same for every player. In a branching narrative, choices can change how the story develops and lead to different endings.', array['Skiller mellom en fast historie og en historie som kan utvikle seg ulikt.', 'Forklarer at valgene i en branching narrative kan påvirke handlingen eller slutten.']::text[], 0),
  ('engelsk-fordypning-10:video-games', 's02', 'In a game, the player has health points. When the health is low, the player must avoid danger or find a way to recover. Explain how this game mechanic affects gameplay.', 'Health points are a game mechanic because they are part of the system that makes the game work. Low health can change the player’s actions, for example by making them avoid danger.', array['Forklarer at health points er en del av systemet eller reglene i spillet.', 'Knytter helsen til hvilke handlinger spilleren kan eller bør ta.']::text[], 1),
  ('engelsk-fordypning-10:video-games', 's03', 'A game uses music that becomes tense when danger is near and changes when the player succeeds. Explain how the sound helps shape the player’s experience.', 'The tense music creates an atmosphere of danger, and the change in music signals success. Sound helps the player understand what is happening and affects how the game feels.', array['Forklarer hvordan musikken skaper stemning eller atmosfære.', 'Forklarer at lyden signaliserer fare eller suksess for spilleren.']::text[], 2),
  ('engelsk-fordypning-10:video-games', 's04', 'In one game, the player sees the world through the character’s eyes. In another, the player sees the character from behind. Name the perspective used in each game and explain the difference.', 'The first game uses a first-person perspective, while the second uses a third-person perspective. In first person, the view is through the character’s eyes; in third person, the character is visible to the player.', array['Identifiserer første perspektiv som first-person og det andre som third-person.', 'Forklarer forskjellen i hva spilleren ser.']::text[], 3),
  ('engelsk-fordypning-10:video-games', 's05', 'A school uses one game to help students learn a subject and another game to practise operating a machine. Explain the purpose of each game and how the purposes differ.', 'The first is an educational game, designed to teach. The second is a simulator, designed to train someone to do something.', array['Knytter læringsspillet til det å undervise eller lære.', 'Knytter simulatoren til trening eller øving på en aktivitet.']::text[], 4),
  ('engelsk-fordypning-10:video-games', 's06', 'Players in an online game use English words such as “lag” and “respawn” in chat. Explain one way this could help young players learn English and one problem that can occur in game chat.', 'Using English with players from around the world can give young people practice with the language. Chat can also include toxic language, so games may have rules and ways to report players.', array['Forklarer hvordan kommunikasjon på engelsk i spill kan gi språkøving.', 'Nevner giftig eller sårende språk som et problem og knytter det til regler eller rapportering.']::text[], 5),
  ('engelsk-fordypning-10:video-games', 's07', 'In one free-to-play game, a player can buy a specific item with real money. In another, the player pays for a reward that is chosen at random. Explain how these purchases differ.', 'The first is an in-game purchase of a chosen item. The second is a loot box, which gives a random reward in exchange for payment.', array['Forklarer at den første betalingen gjelder en bestemt ting i spillet.', 'Forklarer at en loot box gir en tilfeldig belønning.']::text[], 6),
  ('engelsk-fordypning-10:video-games', 's08', 'A game shows people from different groups, but gives one group only negative roles. What aspect of games are you analysing, and what should you examine?', 'This is about representation: how different groups are shown in a game. You should examine how the game portrays each group, including whether their roles are limited or varied.', array['Identifiserer temaet som representation eller hvordan grupper framstilles.', 'Forklarer at analysen bør undersøke hvordan gruppene vises, for eksempel hvilke roller de får.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-10:creating-digital-products', 'engelsk-fordypning-10', 'creating-digital-products', 'Creating digital products', 'How to plan, create, edit and publish digital products in English that combine text, pictures, video and sound, from podcasts and videos to websites and infographics.', array[6, 2]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-10:creating-digital-products', '## Digital products
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-10:creating-digital-products', 'Digital product', 'Something created with digital tools that combines different media types.', 0),
  ('engelsk-fordypning-10:creating-digital-products', 'Media types', 'Text, pictures, video, sound, animation and interactive elements.', 1),
  ('engelsk-fordypning-10:creating-digital-products', 'Purpose', 'What you want to achieve: inform, explain, tell, persuade or entertain.', 2),
  ('engelsk-fordypning-10:creating-digital-products', 'Audience', 'The people your product is made for.', 3),
  ('engelsk-fordypning-10:creating-digital-products', 'Message', 'The main thing you want the audience to remember.', 4),
  ('engelsk-fordypning-10:creating-digital-products', 'Podcast', 'An audio programme, good for interviews, discussions and stories.', 5),
  ('engelsk-fordypning-10:creating-digital-products', 'Infographic', 'A visual presentation of facts and numbers.', 6),
  ('engelsk-fordypning-10:creating-digital-products', 'Digital story', 'A short personal story told with narration, pictures and music.', 7),
  ('engelsk-fordypning-10:creating-digital-products', 'Script', 'A written plan of what will be said and shown.', 8),
  ('engelsk-fordypning-10:creating-digital-products', 'Storyboard', 'Simple sketches of each scene or page.', 9),
  ('engelsk-fordypning-10:creating-digital-products', 'Captions', 'Text on screen that shows what is said.', 10),
  ('engelsk-fordypning-10:creating-digital-products', 'Consistent design', 'Using the same fonts, colours and style throughout.', 11),
  ('engelsk-fordypning-10:creating-digital-products', 'Accessibility', 'Making a product easy for as many people as possible to use.', 12),
  ('engelsk-fordypning-10:creating-digital-products', 'Editing', 'Cutting, arranging and improving recorded material.', 13),
  ('engelsk-fordypning-10:creating-digital-products', 'Consent', 'Permission from people who appear in your product.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-10:creating-digital-products', 'q01', 'flervalg', 'What is a digital product?', array['A product you buy online', 'A computer', 'Something you create with digital tools that combines media types', 'An app store']::text[], 2, 'Podcasts, videos and websites are examples.', true, true, 0),
  ('engelsk-fordypning-10:creating-digital-products', 'q02', 'flervalg', 'What should you decide before choosing tools?', array['Your purpose, audience and message', 'The price of the software', 'The colour of your laptop', 'The length of your name']::text[], 0, 'Purpose and audience decide which format fits best.', true, true, 1),
  ('engelsk-fordypning-10:creating-digital-products', 'q03', 'flervalg', 'Which format is best for presenting facts and numbers visually?', array['A podcast', 'A radio drama', 'A novel', 'An infographic']::text[], 3, 'Infographics use charts, icons and short texts.', true, true, 2),
  ('engelsk-fordypning-10:creating-digital-products', 'q04', 'flervalg', 'What is a storyboard?', array['A finished film', 'Simple sketches of each scene or page', 'A list of sources', 'A music track']::text[], 1, 'Storyboards help you plan before you record.', true, true, 3),
  ('engelsk-fordypning-10:creating-digital-products', 'q05', 'flervalg', 'Why should you add captions to a video?', array['To make it accessible to more people', 'To make it longer', 'Because music is not allowed', 'To hide mistakes']::text[], 0, 'Captions help people who cannot hear the sound or are watching without it.', true, true, 4),
  ('engelsk-fordypning-10:creating-digital-products', 'q06', 'flervalg', 'How should pictures and text work together?', array['They should repeat each other word for word', 'Text should always be larger than pictures', 'They should say something together and support each other', 'Pictures are not needed']::text[], 2, 'Each media type should add something.', true, true, 5),
  ('engelsk-fordypning-10:creating-digital-products', 'q07', 'flervalg', 'What is a good tip for recording sound?', array['Record in a noisy café', 'Hold the microphone far away', 'Use loud background music', 'Record in a quiet room with the microphone close']::text[], 3, 'Clear sound is essential in podcasts and videos.', true, true, 6),
  ('engelsk-fordypning-10:creating-digital-products', 'q08', 'flervalg', 'What must you get from people who appear in your video?', array['Money', 'Consent', 'Their passwords', 'Nothing']::text[], 1, 'Everyone has the right to decide over pictures and videos of themselves.', true, true, 7),
  ('engelsk-fordypning-10:creating-digital-products', 'q09', 'flervalg', 'What is a script?', array['A computer virus', 'A type of font', 'A written plan of what will be said and shown', 'A picture']::text[], 2, 'A script makes recording easier and more structured.', true, false, 8),
  ('engelsk-fordypning-10:creating-digital-products', 'q10', 'flervalg', 'Why should you test your product on someone from the target audience?', array['To get feedback and improve it before publishing', 'To finish faster', 'Because it is required by law', 'To avoid editing']::text[], 0, 'Feedback shows what works and what is unclear.', true, false, 9),
  ('engelsk-fordypning-10:creating-digital-products', 'm01', 'sant-usant', 'Music should be loud enough to drown out the speech.', array['Sant', 'Usant']::text[], 1, 'Music should support the speech, not compete with it.', false, true, 10),
  ('engelsk-fordypning-10:creating-digital-products', 'm02', 'sant-usant', 'A consistent design uses the same fonts, colours and style.', array['Sant', 'Usant']::text[], 0, 'Consistency makes a product look professional.', false, true, 11),
  ('engelsk-fordypning-10:creating-digital-products', 'm03', 'sant-usant', 'A podcast can be a digital product.', array['Sant', 'Usant']::text[], 0, 'Podcasts combine voice, music and sound effects.', false, true, 12),
  ('engelsk-fordypning-10:creating-digital-products', 'm04', 'sant-usant', 'You don''t need to credit sources in digital products.', array['Sant', 'Usant']::text[], 1, 'All sources and borrowed material must be credited.', false, true, 13),
  ('engelsk-fordypning-10:creating-digital-products', 'm05', 'flervalg', 'What is accessibility?', array['Making a product easy for as many people as possible to use', 'Making it expensive', 'Hiding it', 'Making it very long']::text[], 0, 'Good contrast, captions and clear sound improve accessibility.', false, true, 14),
  ('engelsk-fordypning-10:creating-digital-products', 'm06', 'flervalg', 'Which format suits interviews and discussions with sound?', array['An infographic', 'A podcast', 'A poster', 'A comic']::text[], 1, 'Podcasts are built around voices.', false, true, 15),
  ('engelsk-fordypning-10:creating-digital-products', 'm07', 'flervalg', 'What happens in the editing stage?', array['You choose your topic', 'You write the script', 'You cut away mistakes and adjust the sound', 'You find your audience']::text[], 2, 'Editing turns raw recordings into a finished product.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-10:creating-digital-products', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-10:creating-digital-products', 's01', 'A class is making a digital product for younger pupils. Explain the difference between its audience and its purpose, using this situation.', 'The audience is the younger pupils the product is made for. Its purpose is what the creators want to achieve, such as explaining something to them.', array['Identifies the audience as the people the product is made for.', 'Explains that the purpose is what the creators want to achieve.']::text[], 0),
  ('engelsk-fordypning-10:creating-digital-products', 's02', 'A student wants to make an interview about a school project. Compare how a podcast and a video could present the interview.', 'A podcast suits an interview because it uses sound. A video can also show the people, their actions and their emotions.', array['Explains that a podcast is well suited to an interview because it uses sound.', 'Describes something a video can show that a podcast cannot, such as people or their actions.']::text[], 1),
  ('engelsk-fordypning-10:creating-digital-products', 's03', 'When planning a short film, how do a script and a storyboard help in different ways?', 'A script plans what will be said and shown. A storyboard uses simple sketches to plan each scene.', array['Explains that a script plans what will be said and shown.', 'Explains that a storyboard sketches out the scenes.']::text[], 2),
  ('engelsk-fordypning-10:creating-digital-products', 's04', 'You want to tell a short personal story using narration, pictures and music. Explain why a digital story is a suitable format.', 'A digital story is suitable because it tells a short personal story using narration, pictures and music.', array['Identifies the format as suitable for a short personal story.', 'Explains that it combines narration, pictures and music.']::text[], 3),
  ('engelsk-fordypning-10:creating-digital-products', 's05', 'A website uses different fonts, colours and styles on every page. Suggest one design improvement and explain why it would help.', 'Use the same fonts, colours and style throughout the website. This creates a consistent design across its pages.', array['Recommends using the same fonts, colours or style throughout.', 'Connects this choice to keeping the design consistent.']::text[], 4),
  ('engelsk-fordypning-10:creating-digital-products', 's06', 'A video recording has mistakes, long pauses and music that is louder than the speech. Describe edits that would improve it.', 'Cut away the mistakes and long pauses, and adjust the sound level so the music does not drown out the speech.', array['Suggests cutting mistakes or long pauses.', 'Suggests adjusting the sound so the speech can be heard over the music.']::text[], 5),
  ('engelsk-fordypning-10:creating-digital-products', 's07', 'You plan to publish a video that shows a classmate and uses music made by someone else. What should you do about privacy and copyright?', 'Get the classmate’s consent before publishing the video. Use the music only if you have permission, and credit its source.', array['Says to get consent from the classmate who appears in the video.', 'Says to have permission to use the music and credit its source.']::text[], 6),
  ('engelsk-fordypning-10:creating-digital-products', 's08', 'You are filming a demonstration indoors, but the footage is shaky and dark. Name two filming choices that could improve the recording.', 'Hold the camera steadily or use a tripod. Use natural light to make the footage brighter.', array['Suggests steady hands or a tripod to reduce shaky footage.', 'Suggests using natural light to improve the lighting.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-10:language-in-the-media', 'engelsk-fordypning-10', 'language-in-the-media', 'Language in different media', 'How language and devices vary between news, social media, advertising, spoken media and formal writing, how to compare them, and differences between varieties of English.', array[7]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-10:language-in-the-media', '## Language changes with the medium
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-10:language-in-the-media', 'Medium', 'The channel used to communicate, like a newspaper, podcast or social media.', 0),
  ('engelsk-fordypning-10:language-in-the-media', 'Device', 'A language technique used for a particular effect.', 1),
  ('engelsk-fordypning-10:language-in-the-media', 'Inverted pyramid', 'A news structure with the most important information first.', 2),
  ('engelsk-fordypning-10:language-in-the-media', 'Headline', 'The short title of a news article.', 3),
  ('engelsk-fordypning-10:language-in-the-media', 'Tabloid', 'A newspaper with dramatic, emotional language and big headlines.', 4),
  ('engelsk-fordypning-10:language-in-the-media', 'Broadsheet', 'A newspaper with more serious, neutral language.', 5),
  ('engelsk-fordypning-10:language-in-the-media', 'Hashtag', 'A word or phrase with # that groups posts on social media.', 6),
  ('engelsk-fordypning-10:language-in-the-media', 'Engagement', 'Likes, comments and shares on social media.', 7),
  ('engelsk-fordypning-10:language-in-the-media', 'Imperative', 'A command, like “Buy now!”', 8),
  ('engelsk-fordypning-10:language-in-the-media', 'Slogan', 'A short, memorable phrase used in advertising.', 9),
  ('engelsk-fordypning-10:language-in-the-media', 'Direct address', 'Talking directly to the audience as “you”.', 10),
  ('engelsk-fordypning-10:language-in-the-media', 'Fillers', 'Words like um, like and you know in spoken language.', 11),
  ('engelsk-fordypning-10:language-in-the-media', 'Rhetorical question', 'A question asked for effect, not to get an answer.', 12),
  ('engelsk-fordypning-10:language-in-the-media', 'Rule of three', 'Listing three things for rhythm and effect.', 13),
  ('engelsk-fordypning-10:language-in-the-media', 'British and American English', 'Varieties with different spelling and words, like colour/color and flat/apartment.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-10:language-in-the-media', 'q01', 'flervalg', 'What is the inverted pyramid in news writing?', array['A type of headline', 'A picture layout', 'A way to end an article', 'Putting the most important information first']::text[], 3, 'Readers get the key facts even if they stop early.', true, true, 0),
  ('engelsk-fordypning-10:language-in-the-media', 'q02', 'flervalg', 'Which of these is an imperative?', array['The shoes are new.', 'Buy now!', 'Do you like it?', 'It was amazing.']::text[], 1, 'Imperatives tell the reader to do something.', true, true, 1),
  ('engelsk-fordypning-10:language-in-the-media', 'q03', 'flervalg', 'What is a slogan?', array['A long article', 'A news report', 'A short, memorable phrase used in advertising', 'A type of podcast']::text[], 2, 'Good slogans are easy to remember.', true, true, 2),
  ('engelsk-fordypning-10:language-in-the-media', 'q04', 'flervalg', 'Which is typical of language on social media?', array['Hashtags, emojis and abbreviations', 'Long, formal sentences', 'Footnotes', 'No pictures']::text[], 0, 'Social media language is short and informal.', true, true, 3),
  ('engelsk-fordypning-10:language-in-the-media', 'q05', 'flervalg', 'What is a rhetorical question?', array['A question in a quiz', 'A question asked for effect, not to get an answer', 'A question to the teacher', 'A question in an interview']::text[], 1, '“Who doesn''t love summer?” is an example.', true, true, 4),
  ('engelsk-fordypning-10:language-in-the-media', 'q06', 'flervalg', 'Which headline is typical of a tabloid newspaper?', array['Government publishes annual report', 'Interest rates unchanged', 'Minister attends meeting', 'SHOCK AS STAR''S SECRET REVEALED!']::text[], 3, 'Tabloids use dramatic, emotional language.', true, true, 5),
  ('engelsk-fordypning-10:language-in-the-media', 'q07', 'flervalg', 'Which word is American English?', array['Apartment', 'Flat', 'Lorry', 'Colour']::text[], 0, 'The British word is “flat”.', true, true, 6),
  ('engelsk-fordypning-10:language-in-the-media', 'q08', 'flervalg', 'What are fillers?', array['Headlines', 'Hashtags', 'Words like um, like and you know in speech', 'Adjectives in adverts']::text[], 2, 'Fillers make spoken language sound natural.', true, true, 7),
  ('engelsk-fordypning-10:language-in-the-media', 'q09', 'flervalg', 'Which features are typical of formal writing?', array['Slang and emojis', 'Abbreviations like idk', 'Short posts for engagement', 'Complete sentences, precise vocabulary and no slang']::text[], 3, 'Formal writing is used in reports, essays and applications.', true, false, 8),
  ('engelsk-fordypning-10:language-in-the-media', 'q10', 'flervalg', 'Why do adverts often use the word “you”?', array['Because it is required', 'To speak directly to the audience and involve them', 'To sound formal', 'To avoid saying the product''s name']::text[], 1, 'Direct address makes the reader feel personally involved.', true, false, 9),
  ('engelsk-fordypning-10:language-in-the-media', 'm01', 'sant-usant', 'News headlines often leave out small words.', array['Sant', 'Usant']::text[], 0, '“PM resigns after scandal” leaves out words like “the” and “has”.', false, true, 10),
  ('engelsk-fordypning-10:language-in-the-media', 'm02', 'sant-usant', 'Adverts usually use neutral, objective language.', array['Sant', 'Usant']::text[], 1, 'Adverts use positive and emotional language to sell.', false, true, 11),
  ('engelsk-fordypning-10:language-in-the-media', 'm03', 'sant-usant', 'British and American English can have different spelling.', array['Sant', 'Usant']::text[], 0, 'For example colour and color.', false, true, 12),
  ('engelsk-fordypning-10:language-in-the-media', 'm04', 'sant-usant', 'The same kind of language is used in all media.', array['Sant', 'Usant']::text[], 1, 'Language is adapted to each medium, purpose and audience.', false, true, 13),
  ('engelsk-fordypning-10:language-in-the-media', 'm05', 'flervalg', 'What is the rule of three?', array['Listing three things for rhythm and effect', 'Writing only three sentences', 'Using three pictures', 'Three rules for headlines']::text[], 0, '“Faster, stronger, better” is an example.', false, true, 14),
  ('engelsk-fordypning-10:language-in-the-media', 'm06', 'flervalg', 'Which word describes how formal or informal language is?', array['Headline', 'Register', 'Slogan', 'Hashtag']::text[], 1, 'We choose register based on the situation.', false, true, 15),
  ('engelsk-fordypning-10:language-in-the-media', 'm07', 'flervalg', 'What is engagement on social media?', array['A promise to marry', 'Followers you buy', 'Likes, comments and shares', 'A type of advert']::text[], 2, 'Many posts are written to get as much engagement as possible.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-10:language-in-the-media', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-10:language-in-the-media', 's01', 'A news article and a podcast discuss the same event. Compare one language feature you would expect in the news article with one you would expect in the podcast. Explain how each feature fits its medium.', 'A news article may put the most important information first, while a podcast may use fillers and a conversational tone. The article is written, but the podcast uses spoken language.', array['Gjør en relevant sammenligning mellom språk i en nyhetsartikkel og en podcast.', 'Knytter forskjellen til at det ene mediet er skriftlig og det andre muntlig.']::text[], 0),
  ('engelsk-fordypning-10:language-in-the-media', 's02', 'Compare the language of a tabloid newspaper with the language of a broadsheet newspaper.', 'A tabloid often uses dramatic, emotional language, while a broadsheet usually uses more serious and neutral language.', array['Beskriver tabloidens dramatiske eller følelsesladde språk.', 'Setter dette opp mot broadsheetens mer seriøse eller nøytrale språk.']::text[], 1),
  ('engelsk-fordypning-10:language-in-the-media', 's03', 'A student adds #SchoolGarden to a social media post. Explain what the hashtag does and how it can help people find related posts.', 'A hashtag is a word or phrase with # that groups social media posts. People can use it to find other posts about the school garden.', array['Forklarer at en hashtag grupperer innlegg om samme tema.', 'Forklarer at den kan gjøre relaterte innlegg lettere å finne.']::text[], 2),
  ('engelsk-fordypning-10:language-in-the-media', 's04', 'An advert for a snack says, “Crispy crackers create a cheerful crunch.” Identify one language device in the sentence and explain how it helps the advert.', 'The repeated “cr” sound is alliteration. It gives the phrase a catchy rhythm that may help people remember it.', array['Identifiserer allitterasjon eller positivt ladede adjektiv.', 'Forklarer hvordan språkbruken kan gjøre reklamen mer fengende eller minneverdig.']::text[], 3),
  ('engelsk-fordypning-10:language-in-the-media', 's05', 'In a speech about a cleaner park, a speaker asks, “Who wouldn’t want a cleaner park?” Explain what kind of question this is and what effect the speaker may want it to have.', 'It is a rhetorical question because the speaker is not expecting an answer. It can make the audience think about or agree with the idea of a cleaner park.', array['Forklarer at spørsmålet ikke først og fremst er ment å få et svar.', 'Beskriver en relevant effekt på publikum, for eksempel å få dem til å tenke eller støtte poenget.']::text[], 4),
  ('engelsk-fordypning-10:language-in-the-media', 's06', 'A speaker says, “We need courage, patience and teamwork.” Name the speech device used in the list and explain its effect.', 'The speaker uses the rule of three by listing three things. This can give the words rhythm and make the point more effective.', array['Identifiserer at listen består av tre ledd, altså regelen om tre.', 'Forklarer at dette kan skape rytme eller gi poenget større effekt.']::text[], 5),
  ('engelsk-fordypning-10:language-in-the-media', 's07', 'A student writes, “The colour of my new apartment is blue.” Rewrite the sentence consistently in British English or American English, and name the variety you chose.', 'In British English: “The colour of my new flat is blue.” I chose British English and used its spelling and vocabulary consistently.', array['Velger britisk eller amerikansk engelsk og oppgir hvilken variant.', 'Bruker både stavemåte og ordvalg som passer til den valgte varianten.']::text[], 6),
  ('engelsk-fordypning-10:language-in-the-media', 's08', 'An influencer tells a personal story in a social media post and then recommends a product. Explain how the post combines personal content with marketing.', 'The personal story is part of the post, while the product recommendation promotes something to the audience. The influencer combines personal content with marketing.', array['Forklarer at innlegget både deler en personlig historie og promoterer et produkt.', 'Knytter produktanbefalingen til markedsføring eller salg.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'engelsk-fordypning-10', 'persuasion-and-rhetoric', 'Persuasion and rhetoric', 'How senders persuade with ethos, pathos and logos, common persuasive techniques, when persuasion becomes manipulation, and how to be a critical receiver and a responsible persuader.', array[8]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-10:persuasion-and-rhetoric', '## The art of persuasion
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Persuade', 'To make someone believe or do something.', 0),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Rhetoric', 'The art of using language effectively to persuade.', 1),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Aristotle', 'Greek philosopher who described ethos, pathos and logos.', 2),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Ethos', 'An appeal to the sender''s credibility.', 3),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Pathos', 'An appeal to emotions.', 4),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Logos', 'An appeal to logic, facts and reasoning.', 5),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Hyperbole', 'Exaggeration for effect.', 6),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Bandwagon', 'The technique of saying that everyone is doing it, so you should too.', 7),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Testimonial', 'A recommendation from a famous person or satisfied customer.', 8),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Inclusive language', 'Words like we, us and together that make the audience feel included.', 9),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Fear appeal', 'Showing what bad things will happen if you don''t act.', 10),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Propaganda', 'One-sided information spread to control what people think.', 11),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Straw man', 'Twisting the other side''s argument and attacking that version.', 12),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Counterargument', 'An argument against your own view, which you should answer.', 13),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'Opinion piece', 'A text where the writer argues for a view on an issue.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q01', 'flervalg', 'What is rhetoric?', array['The art of using language effectively to persuade', 'A type of poem', 'A grammar rule', 'A news headline']::text[], 0, 'Rhetoric has been studied since ancient Greece.', true, true, 0),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q02', 'flervalg', 'Which appeal uses facts and statistics?', array['Ethos', 'Pathos', 'Logos', 'Bandwagon']::text[], 2, 'Logos appeals to reason.', true, true, 1),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q03', 'flervalg', '“As a doctor with 20 years of experience, I recommend …” Which appeal is this?', array['Pathos', 'Ethos', 'Logos', 'Hyperbole']::text[], 1, 'The sender''s expertise makes the message credible.', true, true, 2),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q04', 'flervalg', 'What is the bandwagon technique?', array['Using facts', 'Showing a doctor', 'Using a rhetorical question', 'Saying that everyone is doing it, so you should too']::text[], 3, 'It plays on our wish to fit in.', true, true, 3),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q05', 'flervalg', 'Which of these appeals mostly to emotions?', array['A table of statistics', 'A list of sources', 'A picture of a sad, hungry animal', 'A doctor''s title']::text[], 2, 'Pictures that make us feel pity are typical pathos.', true, true, 4),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q06', 'flervalg', 'What is propaganda?', array['One-sided information spread to control what people think', 'A balanced news report', 'A school essay', 'A scientific study']::text[], 0, 'Propaganda hides other perspectives.', true, true, 5),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q07', 'flervalg', 'What is a straw man argument?', array['A strong argument with facts', 'A question to the audience', 'A famous quotation', 'Twisting the other side''s argument and attacking that version']::text[], 3, 'It is easier to defeat a weaker version of an argument.', true, true, 6),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q08', 'flervalg', 'Why should you answer counterarguments in a persuasive text?', array['To make the text longer', 'To be more convincing', 'To confuse the reader', 'Because it is a grammar rule']::text[], 1, 'It shows that you have thought about other views.', true, true, 7),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q09', 'flervalg', 'Why is it important to know the sender of a persuasive message?', array['Because the sender''s interests shape the message', 'Because senders are always honest', 'To know their age', 'It is not important']::text[], 0, 'Ask what the sender gains.', true, false, 8),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'q10', 'flervalg', 'Which is an example of inclusive language?', array['You must obey.', 'They are wrong.', 'Together we can make a difference.', 'I know best.']::text[], 2, '“We” and “together” create a sense of community.', true, false, 9),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'm01', 'sant-usant', 'Persuasion is always manipulation.', array['Sant', 'Usant']::text[], 1, 'Honest persuasion is a normal part of democracy.', false, true, 10),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'm02', 'sant-usant', 'Aristotle described ethos, pathos and logos.', array['Sant', 'Usant']::text[], 0, 'His ideas are still used to analyse persuasion.', false, true, 11),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'm03', 'sant-usant', 'Strong arguments often combine ethos, pathos and logos.', array['Sant', 'Usant']::text[], 0, 'Credibility, feelings and facts support each other.', false, true, 12),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'm04', 'sant-usant', 'Misleading statistics always show numbers with full context.', array['Sant', 'Usant']::text[], 1, 'Statistics become misleading when context is left out.', false, true, 13),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'm05', 'flervalg', 'What is hyperbole?', array['A fact', 'A question', 'An exaggeration', 'A quotation']::text[], 2, '“The best phone ever made” is hyperbole.', false, true, 14),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'm06', 'flervalg', 'What is a testimonial?', array['A law', 'A recommendation from a famous person or satisfied customer', 'A news report', 'A rhetorical question']::text[], 1, 'Testimonials borrow credibility from others.', false, true, 15),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 'm07', 'flervalg', 'What should you do as a critical receiver?', array['Check claims in other sources', 'Believe the first source you find', 'Share without reading', 'Ignore facts']::text[], 0, 'Checking claims protects you from manipulation.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 's01', 'An advert calls a phone “the best phone ever made”. Which persuasive technique is used, and how might it affect the audience?', 'This is hyperbole because the advert exaggerates how good the phone is. The exaggerated claim is meant to make the phone seem exceptional and attract buyers.', array['Identifies the technique as hyperbole or exaggeration.', 'Explains that the exaggeration makes the phone sound unusually good or attracts the audience.']::text[], 0),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 's02', 'A speaker mentions their experience, tells an emotional story and gives facts with reasoning. Name the three appeals and explain why using them together can strengthen the argument.', 'The speaker uses ethos through experience, pathos through the emotional story and logos through facts and reasoning. Together, they can appeal to the audience’s trust, emotions and logic.', array['Correctly connects experience to ethos, the emotional story to pathos, and facts or reasoning to logos.', 'Explains that the appeals reach the audience in different ways.']::text[], 1),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 's03', 'A health organisation runs a campaign against sugary drinks, while a soft-drink company advertises them. Explain why the two senders might present the issue differently, and name one question a reader could ask to examine their perspectives.', 'Their purposes and interests may differ, so they may choose to emphasise different information. A reader could ask what each sender gains or which perspectives are missing.', array['Explains that the senders’ purposes, interests or points of view can shape the information they present.', 'Gives a relevant question about the sender’s gains, purpose or missing perspectives.']::text[], 2),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 's04', 'A message uses statistics but gives no context for the numbers. Explain why this could mislead readers and describe one way to check the claim.', 'Without context, statistics can give a misleading impression of what the numbers mean. Readers can check the claim in other sources and look for information that explains the numbers.', array['Explains that numbers without context can be misleading or difficult to interpret.', 'Suggests checking other sources or finding relevant context for the numbers.']::text[], 3),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 's05', 'A satisfied customer recommends a product. What persuasive technique is this, and how might the recommendation persuade someone?', 'This is a testimonial. A satisfied customer’s recommendation may persuade people by making the product seem trustworthy or appealing.', array['Identifies the recommendation as a testimonial.', 'Explains how a customer’s recommendation could make the audience more likely to trust or want the product.']::text[], 4),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 's06', 'A campaign uses the words “we”, “us” and “together”. Name the technique and explain how these words might affect the audience.', 'This is inclusive language. It can make the audience feel included and part of a group working together.', array['Identifies the technique as inclusive language.', 'Explains that the words can create a feeling of inclusion or togetherness.']::text[], 5),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 's07', 'A group shares only information that supports its view because it wants to control what people think. Explain why this is propaganda and describe one thing a reader can do to assess the message.', 'It is propaganda because it is one-sided information intended to control what people think. A reader can check the claims in other sources.', array['Explains that the information is one-sided and intended to influence or control what people think.', 'Suggests checking the claims in other sources or looking for other perspectives.']::text[], 6),
  ('engelsk-fordypning-10:persuasion-and-rhetoric', 's08', 'A campaign warns that bad things will happen if people do not act. Name the persuasive technique and explain how it tries to influence the audience.', 'This is a fear appeal. It uses fear about what may happen to encourage people to act.', array['Identifies the technique as a fear appeal.', 'Explains that it uses fear about possible consequences to encourage action.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('engelsk-fordypning-10:self-presentation-online', 'engelsk-fordypning-10', 'self-presentation-online', 'Self-presentation online', 'Your different roles in the media, curated lives and influencers, how you present yourself and others online, algorithms, and how to reflect critically on your own online behaviour.', array[10, 5]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('engelsk-fordypning-10:self-presentation-online', '## You on the internet
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('engelsk-fordypning-10:self-presentation-online', 'Online identity', 'The way you present yourself online.', 0),
  ('engelsk-fordypning-10:self-presentation-online', 'Consumer', 'Someone who reads, watches and scrolls.', 1),
  ('engelsk-fordypning-10:self-presentation-online', 'Participant', 'Someone who likes, comments and shares.', 2),
  ('engelsk-fordypning-10:self-presentation-online', 'Creator', 'Someone who posts their own pictures, videos and texts.', 3),
  ('engelsk-fordypning-10:self-presentation-online', 'Bystander', 'Someone who sees something happen, like bullying, without acting.', 4),
  ('engelsk-fordypning-10:self-presentation-online', 'Curate', 'To choose carefully what to show.', 5),
  ('engelsk-fordypning-10:self-presentation-online', 'Filter', 'An effect that changes how a picture or video looks.', 6),
  ('engelsk-fordypning-10:self-presentation-online', 'Unrealistic ideals', 'Images of how people should look or live that are hard or impossible to reach.', 7),
  ('engelsk-fordypning-10:self-presentation-online', 'Self-esteem', 'How much you value and like yourself.', 8),
  ('engelsk-fordypning-10:self-presentation-online', 'Influencer', 'Someone who earns money by promoting products and lifestyles online.', 9),
  ('engelsk-fordypning-10:self-presentation-online', 'Sponsored content', 'Paid advertising that must be clearly marked.', 10),
  ('engelsk-fordypning-10:self-presentation-online', 'Consent', 'Permission, for example to post a picture of someone.', 11),
  ('engelsk-fordypning-10:self-presentation-online', 'Stereotype', 'A simplified idea about a group of people.', 12),
  ('engelsk-fordypning-10:self-presentation-online', 'Filter bubble', 'When you mostly see content that matches what you already like and think.', 13),
  ('engelsk-fordypning-10:self-presentation-online', 'Cyberbullying', 'Bullying through digital channels.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('engelsk-fordypning-10:self-presentation-online', 'q01', 'flervalg', 'What does it mean to curate your profile?', array['To delete it', 'To make it private', 'To choose carefully what to show', 'To post everything']::text[], 2, 'Most people share highlights rather than everyday life.', true, true, 0),
  ('engelsk-fordypning-10:self-presentation-online', 'q02', 'flervalg', 'What is a bystander online?', array['Someone who creates content', 'An influencer', 'A moderator', 'Someone who sees something happen, like bullying, without acting']::text[], 3, 'Bystanders can help by reporting or supporting the victim.', true, true, 1),
  ('engelsk-fordypning-10:self-presentation-online', 'q03', 'flervalg', 'Why can edited images affect self-esteem?', array['Because comparing yourself with unrealistic ideals can make you feel you are not good enough', 'Because they are always ugly', 'Because they are illegal', 'Because they are too small']::text[], 0, 'Edited pictures show a reality that does not exist.', true, true, 2),
  ('engelsk-fordypning-10:self-presentation-online', 'q04', 'flervalg', 'What must sponsored content be?', array['Funny', 'Clearly marked as advertising', 'Written in English', 'Free']::text[], 1, 'Hidden advertising misleads the audience.', true, true, 3),
  ('engelsk-fordypning-10:self-presentation-online', 'q05', 'flervalg', 'What decides what appears in your feed?', array['Your teacher', 'The government', 'Chance only', 'Algorithms based on what you have clicked on']::text[], 3, 'Algorithms learn from your behaviour.', true, true, 4),
  ('engelsk-fordypning-10:self-presentation-online', 'q06', 'flervalg', 'What should you do before posting a video of a friend?', array['Ask for their consent', 'Add music', 'Tag strangers', 'Nothing']::text[], 0, 'Everyone has the right to decide over pictures of themselves.', true, true, 5),
  ('engelsk-fordypning-10:self-presentation-online', 'q07', 'flervalg', 'What is an influencer?', array['A news journalist', 'A politician', 'Someone who earns money by promoting products and lifestyles online', 'A computer program']::text[], 2, 'Influencers can have large audiences, especially among young people.', true, true, 6),
  ('engelsk-fordypning-10:self-presentation-online', 'q08', 'flervalg', 'What is a filter bubble?', array['A soap bubble', 'When you mostly see content that matches what you already like and think', 'A photo filter', 'A privacy setting']::text[], 1, 'Filter bubbles can limit the perspectives you meet.', true, true, 7),
  ('engelsk-fordypning-10:self-presentation-online', 'q09', 'flervalg', 'Which question helps you reflect on your own posts?', array['How many likes can I get?', 'Which filter is best?', 'Should I post more often?', 'Would I be comfortable if a future employer saw this?']::text[], 3, 'What you post can stay online for a long time.', true, false, 8),
  ('engelsk-fordypning-10:self-presentation-online', 'q10', 'flervalg', 'How can you make your feed healthier?', array['Follow different accounts, mute some and take breaks', 'Scroll even more', 'Follow only influencers', 'Turn off all privacy settings']::text[], 0, 'You can influence what the algorithm shows you.', true, false, 9),
  ('engelsk-fordypning-10:self-presentation-online', 'm01', 'sant-usant', 'What you see on social media is often a performance, not the whole truth.', array['Sant', 'Usant']::text[], 0, 'Most people share carefully chosen moments.', false, true, 10),
  ('engelsk-fordypning-10:self-presentation-online', 'm02', 'sant-usant', 'A like or share has no effect on how content spreads.', array['Sant', 'Usant']::text[], 1, 'Likes and shares tell the algorithm to show content to more people.', false, true, 11),
  ('engelsk-fordypning-10:self-presentation-online', 'm03', 'sant-usant', 'Some people feel more confident online than offline.', array['Sant', 'Usant']::text[], 0, 'Online spaces can let people explore interests and identities.', false, true, 12),
  ('engelsk-fordypning-10:self-presentation-online', 'm04', 'sant-usant', 'Influencer posts are always spontaneous and unplanned.', array['Sant', 'Usant']::text[], 1, 'Much influencer content is carefully planned and sometimes paid for.', false, true, 13),
  ('engelsk-fordypning-10:self-presentation-online', 'm05', 'flervalg', 'What is cyberbullying?', array['A computer virus', 'Bullying through digital channels', 'A video game', 'A type of filter']::text[], 1, 'Cyberbullying can follow people everywhere through their phones.', false, true, 14),
  ('engelsk-fordypning-10:self-presentation-online', 'm06', 'flervalg', 'Which role are you in when you post your own videos?', array['Consumer', 'Bystander', 'Creator', 'Moderator']::text[], 2, 'As a creator, you are responsible for what you publish.', false, true, 15),
  ('engelsk-fordypning-10:self-presentation-online', 'm07', 'flervalg', 'How can stereotypes online affect real life?', array['They can shape how people see groups in real life', 'They have no effect', 'They only affect games', 'They make everyone equal']::text[], 0, 'Repeated images influence our attitudes.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('engelsk-fordypning-10:self-presentation-online', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('engelsk-fordypning-10:self-presentation-online', 's01', 'Explain what an online identity is and give one example of something that can shape it.', 'An online identity is the way you present yourself online. For example, the pictures or posts you choose to share can shape how others see you.', array['Explains that online identity is how someone presents themselves online.', 'Gives a relevant example of something that can shape it.']::text[], 0),
  ('engelsk-fordypning-10:self-presentation-online', 's02', 'Compare a consumer and a creator on social media. Give one example of what each might do.', 'A consumer reads, watches or scrolls through content, while a creator makes and posts their own content. For example, someone might watch a video as a consumer and post their own video as a creator.', array['Explains the difference between taking in content and making or posting it.', 'Gives a relevant example for both roles.']::text[], 1),
  ('engelsk-fordypning-10:self-presentation-online', 's03', 'Explain why liking or sharing a post can be a responsibility, not just a small action.', 'A like or share can help content spread quickly. This can be positive, but it can also spread harmful content, so people should think about what they support or pass on.', array['Explains that likes or shares can help content spread.', 'Recognises that the spread can have good or harmful effects.']::text[], 2),
  ('engelsk-fordypning-10:self-presentation-online', 's04', 'An influencer posts about a product in a personal, casual-looking video. The post is paid for, but it is not clearly marked as advertising. What is important about this post, and what should a viewer consider?', 'Because the post is paid for, it is sponsored content and should be clearly marked as advertising. A viewer should consider whether it is an advert and why the influencer is showing the product.', array['Identifies that paid promotion is sponsored content and must be clearly marked as advertising.', 'Explains that viewers should question the purpose of the post or why the product is being shown.']::text[], 3),
  ('engelsk-fordypning-10:self-presentation-online', 's05', 'Explain how a stereotype about a group online could affect how people see that group in real life.', 'A stereotype is a simplified idea about a group. If people see that idea repeated online, it can affect how they think about members of the group in real life.', array['Explains that a stereotype is a simplified idea about a group.', 'Describes how online portrayals can influence people’s views of the group in real life.']::text[], 4),
  ('engelsk-fordypning-10:self-presentation-online', 's06', 'Maya feels more confident sharing her interests online, and this later helps her talk about them in real life. Explain how this shows a connection between online and real-life identity.', 'Maya’s online identity affects her real-life identity because feeling confident online helps her talk about her interests in person. Online and real-life identities can influence each other.', array['Explains that confidence or exploration online can affect someone in real life.', 'Recognises that online and real-life identities influence each other.']::text[], 5),
  ('engelsk-fordypning-10:self-presentation-online', 's07', 'Someone sees a classmate being bullied through messages online but does not act. What role does this person have, and what makes the situation an example of cyberbullying?', 'The person is a bystander because they see something happen without acting. It is cyberbullying because the bullying is happening through digital messages.', array['Identifies the person as a bystander because they witness the bullying without acting.', 'Connects cyberbullying to bullying through digital channels.']::text[], 6),
  ('engelsk-fordypning-10:self-presentation-online', 's08', 'A photo effect changes the colours and appearance of a picture. Explain how this is different from a filter bubble.', 'A filter is an effect that changes how a picture or video looks. A filter bubble is when someone mostly sees online content that matches what they already like and think.', array['Explains that a filter changes the appearance of a picture or video.', 'Explains that a filter bubble affects the kind of content someone mostly sees.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-10:nervesystemet-og-hormoner', 'naturfag-10', 'nervesystemet-og-hormoner', 'Nervesystemet og hormonsystemet', 'Kroppens to signalsystemer – hvordan nerver og hormoner sender beskjeder, hvordan de skiller seg fra hverandre, og hvordan de samarbeider.', array[21]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-10:nervesystemet-og-hormoner', '## To signalsystemer
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-10:nervesystemet-og-hormoner', 'Sentralnervesystemet', 'Hjernen og ryggmargen.', 0),
  ('naturfag-10:nervesystemet-og-hormoner', 'Perifere nervesystem', 'Nervene som går ut i kroppen til muskler, hud og organer.', 1),
  ('naturfag-10:nervesystemet-og-hormoner', 'Nervecelle (nevron)', 'Celle som leder elektriske signaler.', 2),
  ('naturfag-10:nervesystemet-og-hormoner', 'Synapse', 'Den lille spalten mellom to nerveceller der signalstoffer overfører beskjeden.', 3),
  ('naturfag-10:nervesystemet-og-hormoner', 'Signalstoff (nevrotransmitter)', 'Kjemisk stoff som overfører signaler i synapsen, som dopamin og serotonin.', 4),
  ('naturfag-10:nervesystemet-og-hormoner', 'Sanseceller', 'Celler som registrerer inntrykk som lys, lyd, trykk og smak.', 5),
  ('naturfag-10:nervesystemet-og-hormoner', 'Refleks', 'En rask, automatisk reaksjon der signalet går via ryggmargen uten at hjernen bestemmer.', 6),
  ('naturfag-10:nervesystemet-og-hormoner', 'Hormon', 'Kjemisk signalstoff som lages i kjertler og fraktes med blodet.', 7),
  ('naturfag-10:nervesystemet-og-hormoner', 'Reseptor', 'Mottaker på cellen som bare passer til bestemte signalstoffer eller hormoner.', 8),
  ('naturfag-10:nervesystemet-og-hormoner', 'Hypofysen', 'Kjertel i hjernen som styrer mange andre kjertler.', 9),
  ('naturfag-10:nervesystemet-og-hormoner', 'Insulin', 'Hormon fra bukspyttkjertelen som senker blodsukkeret.', 10),
  ('naturfag-10:nervesystemet-og-hormoner', 'Adrenalin', 'Hormon fra binyrene som gjør kroppen klar til kamp eller flukt.', 11),
  ('naturfag-10:nervesystemet-og-hormoner', 'Østrogen og testosteron', 'Kjønnshormoner som styrer puberteten.', 12),
  ('naturfag-10:nervesystemet-og-hormoner', 'Nerve vs. hormon', 'Nerver: raskt, presist, kortvarig. Hormoner: langsommere, hele kroppen, langvarig.', 13),
  ('naturfag-10:nervesystemet-og-hormoner', 'Tilbakekobling', 'Regulering der en endring stopper sin egen årsak, som insulin og blodsukker.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-10:nervesystemet-og-hormoner', 'q01', 'flervalg', 'Hva består sentralnervesystemet av?', array['Hjernen og ryggmargen', 'Alle nervene i armene', 'Hjertet og lungene', 'Kjertlene']::text[], 0, 'Sentralnervesystemet er hjernen og ryggmargen. Resten av nervene er det perifere nervesystemet.', true, true, 0),
  ('naturfag-10:nervesystemet-og-hormoner', 'q02', 'flervalg', 'Hva skjer i en synapse?', array['Blodet renses', 'Signalstoffer overfører beskjeden fra én nervecelle til den neste', 'Det lages hormoner', 'Muskler trekker seg sammen']::text[], 1, 'Den elektriske impulsen gjør at signalstoffer skilles ut og fester seg til neste celle.', true, true, 1),
  ('naturfag-10:nervesystemet-og-hormoner', 'q03', 'flervalg', 'Hvorfor trekker du hånda raskt bort fra en varm kokeplate?', array['Fordi hjernen tenker seg om', 'Fordi hormoner virker raskt', 'På grunn av en refleks via ryggmargen', 'Fordi huden er kald']::text[], 2, 'Refleksen går via ryggmargen, som sender signal direkte til musklene.', true, true, 2),
  ('naturfag-10:nervesystemet-og-hormoner', 'q04', 'flervalg', 'Hvordan fraktes hormoner rundt i kroppen?', array['Gjennom nervene', 'Gjennom luftveiene', 'Gjennom lymfen alene', 'Med blodet']::text[], 3, 'Hormoner skilles ut fra kjertler og fraktes med blodet til hele kroppen.', true, true, 3),
  ('naturfag-10:nervesystemet-og-hormoner', 'q05', 'flervalg', 'Hvilket hormon senker blodsukkeret?', array['Adrenalin', 'Insulin', 'Testosteron', 'Veksthormon']::text[], 1, 'Insulin fra bukspyttkjertelen hjelper cellene å ta opp sukker fra blodet.', true, true, 4),
  ('naturfag-10:nervesystemet-og-hormoner', 'q06', 'flervalg', 'Hva gjør adrenalin?', array['Gjør kroppen klar til kamp eller flukt', 'Senker pulsen', 'Får oss til å sove', 'Styrer fordøyelsen']::text[], 0, 'Adrenalin øker puls og pust og gir musklene mer energi ved fare.', true, true, 5),
  ('naturfag-10:nervesystemet-og-hormoner', 'q07', 'flervalg', 'Hvilken påstand stemmer om hormonsystemet sammenlignet med nervesystemet?', array['Hormoner virker raskere', 'Hormoner går bare til ett bestemt sted', 'Hormoner virker langsommere, men ofte lenger', 'Hormoner er elektriske signaler']::text[], 2, 'Hormoner sprer seg med blodet og kan ha virkning i timer, måneder eller år.', true, true, 6),
  ('naturfag-10:nervesystemet-og-hormoner', 'q08', 'flervalg', 'Hvilken kjertel styrer mange av de andre kjertlene?', array['Binyrene', 'Skjoldbruskkjertelen', 'Bukspyttkjertelen', 'Hypofysen']::text[], 3, 'Hypofysen i hjernen kalles ofte en overordnet kjertel.', true, false, 7),
  ('naturfag-10:nervesystemet-og-hormoner', 'q09', 'flervalg', 'Hvorfor reagerer bare noen celler på et bestemt hormon?', array['Fordi bare de har riktige reseptorer', 'Fordi hormonet ikke når de andre', 'Fordi de andre cellene er døde', 'Fordi hormonet er for stort']::text[], 0, 'Hormonet passer som en nøkkel i en lås, og bare celler med riktig reseptor reagerer.', true, true, 8),
  ('naturfag-10:nervesystemet-og-hormoner', 'q10', 'flervalg', 'Hvilke hormoner styrer puberteten?', array['Insulin og glukagon', 'Østrogen og testosteron', 'Adrenalin og dopamin', 'Serotonin og melatonin']::text[], 1, 'Kjønnshormonene østrogen og testosteron gir kroppsendringene i puberteten.', true, false, 9),
  ('naturfag-10:nervesystemet-og-hormoner', 'm01', 'sant-usant', 'Nervesignaler går mye raskere enn hormonsignaler.', array['Sant', 'Usant']::text[], 0, 'Nervesignaler når fram på brøkdeler av et sekund.', false, true, 10),
  ('naturfag-10:nervesystemet-og-hormoner', 'm02', 'sant-usant', 'Dopamin og serotonin er eksempler på signalstoffer i hjernen.', array['Sant', 'Usant']::text[], 0, 'De overfører signaler mellom nerveceller.', false, true, 11),
  ('naturfag-10:nervesystemet-og-hormoner', 'm03', 'sant-usant', 'Ved en refleks bestemmer hjernen først hva som skal skje.', array['Sant', 'Usant']::text[], 1, 'Refleksen går via ryggmargen. Hjernen får beskjed etterpå.', false, true, 12),
  ('naturfag-10:nervesystemet-og-hormoner', 'm04', 'sant-usant', 'Hormoner påvirker alle celler i kroppen likt.', array['Sant', 'Usant']::text[], 1, 'Bare celler med riktige reseptorer reagerer på et bestemt hormon.', false, true, 13),
  ('naturfag-10:nervesystemet-og-hormoner', 'm05', 'flervalg', 'Hvilken kjertel lager adrenalin?', array['Hypofysen', 'Binyrene', 'Bukspyttkjertelen', 'Skjoldbruskkjertelen']::text[], 1, 'Binyrene sitter på toppen av nyrene og lager adrenalin.', false, true, 14),
  ('naturfag-10:nervesystemet-og-hormoner', 'm06', 'flervalg', 'Hva registrerer sansecellene i huden?', array['Lys', 'Lyd', 'Smak', 'Trykk, temperatur og smerte']::text[], 3, 'Huden har sanseceller for berøring, trykk, varme, kulde og smerte.', false, true, 15),
  ('naturfag-10:nervesystemet-og-hormoner', 'm07', 'flervalg', 'Hva skjer med insulinutskillingen når blodsukkeret faller?', array['Den stopper', 'Den øker kraftig', 'Den blir til adrenalin', 'Ingenting']::text[], 0, 'Dette er tilbakekobling: Lavt blodsukker stopper utskillingen av insulin.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-10:nervesystemet-og-hormoner', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-10:nervesystemet-og-hormoner', 's01', 'En nervecelle tar imot et signal og sender det videre. Forklar hvordan de korte og lange utløperne bidrar til dette.', 'De korte utløperne tar imot signaler. Den lange utløperen sender signalet videre som en elektrisk impuls.', array['Forklarer at de korte utløperne tar imot signaler.', 'Forklarer at den lange utløperen leder signalet videre som en elektrisk impuls.']::text[], 0),
  ('naturfag-10:nervesystemet-og-hormoner', 's02', 'Et signal går fra huden mot ryggmargen og hjernen, og en beskjed sendes derfra til en muskel. Hvilke deler av signalveien hører til sentralnervesystemet, og hvilke hører til det perifere nervesystemet? Forklar kort hva delene gjør.', 'Ryggmargen og hjernen hører til sentralnervesystemet, der informasjon bearbeides. Nervene mellom huden, sentralnervesystemet og muskelen hører til det perifere nervesystemet og fører signaler gjennom kroppen.', array['Plasserer hjernen og ryggmargen i sentralnervesystemet og knytter dette til bearbeiding av informasjon.', 'Forklarer at nervene ut i kroppen hører til det perifere nervesystemet og fører signaler til eller fra kroppen.']::text[], 1),
  ('naturfag-10:nervesystemet-og-hormoner', 's03', 'Du lukter mat. Forklar hva sansecellene gjør, og hvor de sender informasjonen videre.', 'Sanseceller i nesen registrerer lukten og sender signaler til hjernen. Hjernen bearbeider informasjonen.', array['Forklarer at sanseceller registrerer inntrykket av lukt.', 'Forklarer at signaler sendes til hjernen for bearbeiding.']::text[], 2),
  ('naturfag-10:nervesystemet-og-hormoner', 's04', 'En person opplever fare. Forklar hvordan nervesystemet og hormonsystemet kan samarbeide, fra faresignalet til adrenalinets virkning.', 'Nervesystemet sender beskjed til binyrene, som skiller ut adrenalin. Adrenalinet gjør kroppen klar til kamp eller flukt.', array['Får fram at nervesystemet gir beskjed til binyrene, som skiller ut adrenalin.', 'Forklarer at adrenalin gjør kroppen klar til kamp eller flukt.']::text[], 3),
  ('naturfag-10:nervesystemet-og-hormoner', 's05', 'Etter et måltid stiger blodsukkeret. Forklar hvordan insulin og tilbakekobling bidrar til å regulere blodsukkeret, også når det begynner å falle igjen.', 'Når blodsukkeret stiger, skilles det ut insulin, som senker blodsukkeret. Når blodsukkeret faller igjen, stopper utskillingen av insulin.', array['Forklarer at økt blodsukker fører til utskilling av insulin, som senker blodsukkeret.', 'Forklarer at utskillingen av insulin stopper når blodsukkeret faller igjen.']::text[], 4),
  ('naturfag-10:nervesystemet-og-hormoner', 's06', 'En kjertel påvirker stoffskiftet. Hvilken kjertel er det, og hva er dens rolle?', 'Det er skjoldbruskkjertelen. Den påvirker stoffskiftet.', array['Identifiserer skjoldbruskkjertelen.', 'Knytter kjertelen til påvirkning av stoffskiftet.']::text[], 5),
  ('naturfag-10:nervesystemet-og-hormoner', 's07', 'I en regneoppgave varer en nervesignalvirkning i 2 sekunder, og en hormonvirkning varer i 1 time. Hvor mange sekunder lengre varer hormonvirkningen? Vis det viktigste regnestykket.', 'Én time er 3600 sekunder. Forskjellen er 3600 − 2 = 3598 sekunder.', array['Gjør om 1 time til 3600 sekunder.', 'Regner ut forskjellen, 3598 sekunder.']::text[], 6),
  ('naturfag-10:nervesystemet-og-hormoner', 's08', 'I en modell registreres 4 nerveimpulser hvert sekund i 3 sekunder. Hvor mange nerveimpulser registreres totalt? Vis regnestykket.', '4 · 3 = 12. Det registreres 12 nerveimpulser.', array['Multipliserer 4 nerveimpulser per sekund med 3 sekunder.', 'Oppgir 12 nerveimpulser som svar.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-10:rus-legemidler-og-miljogifter', 'naturfag-10', 'rus-legemidler-og-miljogifter', 'Rusmidler, legemidler, miljøgifter og doping', 'Hvordan ulike stoffer påvirker kroppens signalsystemer – fra rusmidler og legemidler til miljøgifter og doping – og hvorfor unge hjerner er ekstra sårbare.', array[21]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-10:rus-legemidler-og-miljogifter', '## Stoffer som påvirker signalsystemene
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Rusmiddel', 'Stoff som påvirker hjernen og endrer tanker, følelser og atferd.', 0),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Belønningssystemet', 'Del av hjernen som gir velvære via dopamin. Påvirkes av mange rusmidler.', 1),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Alkohol', 'Demper sentralnervesystemet og svekker dømmekraft og reaksjonsevne.', 2),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Nikotin', 'Sterkt avhengighetsskapende stoff i snus, sigaretter og e-sigaretter.', 3),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Toleranse', 'At man trenger mer av et stoff for å få samme effekt.', 4),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Avhengighet', 'Sterk trang til et stoff, og vansker med å slutte.', 5),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Abstinenser', 'Ubehagelige symptomer når man slutter med et stoff man er avhengig av.', 6),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Hjernens utvikling', 'Hjernen utvikles til man er rundt 25 år, og unge er derfor ekstra sårbare.', 7),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Legemiddel', 'Stoff som brukes til å forebygge, lindre eller kurere sykdom.', 8),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Antibiotika', 'Legemidler som virker mot bakterier, men ikke mot virus.', 9),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Bivirkning', 'Uønsket virkning av et legemiddel.', 10),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Miljøgift', 'Giftig stoff som brytes langsomt ned og hoper seg opp i organismer.', 11),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Biomagnifisering', 'Miljøgifter hoper seg opp oppover i næringskjeden.', 12),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Hormonforstyrrende stoffer', 'Stoffer som ligner kroppens hormoner og kan påvirke vekst og forplantning.', 13),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'Anabole steroider', 'Dopingmiddel som ligner testosteron. Øker muskler, men gir alvorlige bivirkninger.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q01', 'flervalg', 'Hvilket signalstoff er sentralt i hjernens belønningssystem?', array['Insulin', 'Dopamin', 'Adrenalin', 'Østrogen']::text[], 1, 'Mange rusmidler øker utskillingen av dopamin, som gir følelse av velvære.', true, true, 0),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q02', 'flervalg', 'Hva betyr toleranse?', array['At man tåler alt', 'At man ikke blir påvirket', 'At man trenger mer av stoffet for å få samme effekt', 'At man slutter lett']::text[], 2, 'Kroppen venner seg til stoffet, og effekten blir svakere.', true, true, 1),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q03', 'flervalg', 'Hvorfor er unge ekstra sårbare for rusmidler?', array['Fordi hjernen fortsatt utvikler seg', 'Fordi de veier mindre enn voksne', 'Fordi de har mindre blod', 'De er ikke mer sårbare']::text[], 0, 'Hjernen utvikles til rundt 25 års alder, og rusmidler kan påvirke utviklingen.', true, true, 2),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q04', 'flervalg', 'Hva virker antibiotika mot?', array['Virus', 'Sopp og virus', 'Alle sykdommer', 'Bakterier']::text[], 3, 'Antibiotika virker ikke mot virus som gir forkjølelse og influensa.', true, true, 3),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q05', 'flervalg', 'Hva er en miljøgift?', array['Et giftig stoff som brytes langsomt ned og hoper seg opp i organismer', 'Alt som lukter vondt', 'Et vanlig næringsstoff', 'Et legemiddel']::text[], 0, 'Eksempler er kvikksølv, PCB og PFAS.', true, true, 4),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q06', 'flervalg', 'Hva er biomagnifisering?', array['At miljøgifter forsvinner i naturen', 'At dyr blir større', 'At miljøgifter hoper seg opp oppover i næringskjeden', 'At planter vokser raskere']::text[], 2, 'Rovdyr på toppen av næringskjeden får derfor de høyeste konsentrasjonene.', true, true, 5),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q07', 'flervalg', 'Hvilke dyr får typisk høyest konsentrasjon av miljøgifter?', array['Planteplankton', 'Små krepsdyr', 'Gress', 'Rovdyr på toppen av næringskjeden, som isbjørn']::text[], 3, 'De spiser mange byttedyr som hver inneholder litt miljøgift.', true, false, 6),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q08', 'flervalg', 'Hva gjør EPO som dopingmiddel?', array['Gir større muskler', 'Øker produksjonen av røde blodceller', 'Senker pulsen', 'Gjør deg søvnig']::text[], 1, 'Flere røde blodceller gir bedre oksygentransport, men tykkere blod og økt risiko for blodpropp.', true, true, 7),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q09', 'flervalg', 'Hvordan virker alkohol på sentralnervesystemet?', array['Det demper det', 'Det stimulerer det kraftig', 'Det har ingen virkning', 'Det reparerer nerveceller']::text[], 0, 'Alkohol demper signaloverføringen og svekker dømmekraft og reaksjonsevne.', true, false, 8),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'q10', 'flervalg', 'Hva er abstinenser?', array['En type vitamin', 'Et dopingmiddel', 'Ubehagelige symptomer når man slutter med et stoff man er avhengig av', 'En bivirkning av antibiotika']::text[], 2, 'Abstinenser er et tegn på at kroppen har vent seg til stoffet.', true, true, 9),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'm01', 'sant-usant', 'Nikotin er avhengighetsskapende.', array['Sant', 'Usant']::text[], 0, 'Nikotin gir raskt avhengighet, også gjennom snus og e-sigaretter.', false, true, 10),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'm02', 'sant-usant', 'Antibiotika hjelper mot forkjølelse.', array['Sant', 'Usant']::text[], 1, 'Forkjølelse skyldes virus, og antibiotika virker bare mot bakterier.', false, true, 11),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'm03', 'sant-usant', 'Alle legemidler kan ha bivirkninger.', array['Sant', 'Usant']::text[], 0, 'Derfor er det viktig å bruke legemidler riktig og følge legens råd.', false, true, 12),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'm04', 'sant-usant', 'Miljøgifter brytes raskt ned i naturen.', array['Sant', 'Usant']::text[], 1, 'Miljøgifter brytes langsomt ned og hoper seg derfor opp.', false, true, 13),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'm05', 'flervalg', 'Hvilket stoff ligner testosteron og brukes som doping?', array['EPO', 'Insulin', 'Anabole steroider', 'Koffein']::text[], 2, 'Anabole steroider øker muskelmassen, men gir mange alvorlige bivirkninger.', false, true, 14),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'm06', 'flervalg', 'Hvorfor gir Mattilsynet kostråd om store rovfisk?', array['Fordi de kan inneholde mye miljøgifter', 'Fordi de er dyre', 'Fordi de smaker dårlig', 'Fordi de er fredet']::text[], 0, 'Store rovfisk står høyt i næringskjeden og kan ha opphopning av for eksempel kvikksølv.', false, true, 15),
  ('naturfag-10:rus-legemidler-og-miljogifter', 'm07', 'flervalg', 'Hva er et eksempel på et tungmetall som er en miljøgift?', array['Kalsium', 'Kvikksølv', 'Oksygen', 'Natrium']::text[], 1, 'Kvikksølv er giftig og hoper seg opp i næringskjeden.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-10:rus-legemidler-og-miljogifter', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-10:rus-legemidler-og-miljogifter', 's01', 'Stoffer kan påvirke kroppens signalsystemer på flere måter. Forklar to ulike måter et stoff kan gjøre dette på.', 'Et stoff kan etterligne kroppens egne signalstoffer eller hormoner, blokkere reseptorer eller endre hvor mye signalstoff som skilles ut.', array['Forklarer to ulike måter stoffer kan påvirke signalsystemene på.']::text[], 0),
  ('naturfag-10:rus-legemidler-og-miljogifter', 's02', 'Sammenlign hvordan alkohol og cannabis kan påvirke evner eller funksjoner hos en person.', 'Alkohol kan svekke dømmekraft, reaksjonsevne og koordinasjon. Cannabis kan svekke hukommelse, konsentrasjon og læring.', array['Nevner en riktig påvirkning av alkohol.', 'Nevner en riktig påvirkning av cannabis.']::text[], 1),
  ('naturfag-10:rus-legemidler-og-miljogifter', 's03', 'En person har en sykdom som skyldes et virus, og spør om antibiotika kan kurere den. Forklar hvorfor antibiotika ikke virker mot sykdommen.', 'Antibiotika virker mot bakterier, ikke virus. Derfor kan det ikke kurere en sykdom som skyldes et virus.', array['Forklarer at antibiotika virker mot bakterier, men ikke virus.']::text[], 2),
  ('naturfag-10:rus-legemidler-og-miljogifter', 's04', 'Et stoff ligner kroppens egne hormoner. Forklar hvorfor stoffet kan være hormonforstyrrende, og nevn én type utvikling det kan påvirke.', 'Stoffet kan påvirke kroppen fordi det ligner hormonene. Hormonforstyrrende stoffer kan blant annet påvirke vekst, forplantning eller utvikling.', array['Knytter likheten med kroppens hormoner til at stoffet kan påvirke kroppen.', 'Nevner en mulig påvirkning på vekst, forplantning eller utvikling.']::text[], 3),
  ('naturfag-10:rus-legemidler-og-miljogifter', 's05', 'En idrettsutøver bruker anabole steroider for å få større muskler. Forklar hvorfor dette regnes som doping, og nevn én mulig helseskade.', 'Anabole steroider brukes her for å prestere bedre i idrett og regnes derfor som doping. De kan øke muskelmassen, men blant annet gi hjerteproblemer, humørsvingninger eller hormonforstyrrelser.', array['Forklarer at bruk av stoffet for å prestere bedre i idrett er doping.', 'Nevner en mulig alvorlig bivirkning av anabole steroider.']::text[], 4),
  ('naturfag-10:rus-legemidler-og-miljogifter', 's06', 'Hjernen utvikles til man er rundt 25 år. Omtrent hvor mange år er det fra en person fyller 16 år til hjernen er ferdig utviklet? Vis regnestykket.', 'Det er omtrent 9 år. Regnestykket er 25 − 16 = 9.', array['Viser regnestykket 25 − 16.', 'Oppgir omtrent 9 år.']::text[], 5),
  ('naturfag-10:rus-legemidler-og-miljogifter', 's07', 'I en tenkt regnemodell er konsentrasjonen av en miljøgift 4 enheter hos små organismer. Hos en rovfisk settes konsentrasjonen til tre ganger så mye. Hvor mange enheter er det hos rovfisken? Vis regnestykket.', 'Det er 12 enheter. Regnestykket er 4 × 3 = 12.', array['Viser regnestykket 4 × 3.', 'Oppgir 12 enheter.']::text[], 6),
  ('naturfag-10:rus-legemidler-og-miljogifter', 's08', 'Alle legemidler kan ha bivirkninger, og feil bruk kan være farlig. Forklar hvorfor mange legemidler må skrives ut på resept av lege.', 'Resept fra lege bidrar til at legemidler brukes riktig, siden feil bruk kan være farlig og legemidler kan gi bivirkninger.', array['Knytter resept til at feil bruk av legemidler kan være farlig.', 'Nevner at legemidler kan ha bivirkninger.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-10:immunforsvar-og-vaksiner', 'naturfag-10', 'immunforsvar-og-vaksiner', 'Immunforsvaret og vaksiner', 'Kroppens forsvar mot sykdomsfremkallende mikroorganismer, hvordan antistoffer og hukommelsesceller virker, og hvorfor vaksiner er viktige for folkehelsen.', array[22]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-10:immunforsvar-og-vaksiner', '## Sykdomsfremkallende mikroorganismer
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-10:immunforsvar-og-vaksiner', 'Patogen', 'Mikroorganisme som kan gi sykdom, som enkelte bakterier og virus.', 0),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Bakterie', 'Levende encellet organisme som kan formere seg selv.', 1),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Virus', 'Svært liten smittepartikkel som må inn i kroppens celler for å formere seg.', 2),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Første forsvarslinje', 'Hud, slimhinner, flimmerhår, magesyre, tårer og spytt.', 3),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Betennelse', 'Rødme, varme og hevelse når kroppen bekjemper mikrober i et område.', 4),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Eteceller (fagocytter)', 'Hvite blodceller som spiser opp mikrober.', 5),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Antigen', 'Kjennetegn på overflaten av et smittestoff.', 6),
  ('naturfag-10:immunforsvar-og-vaksiner', 'B-celler', 'Hvite blodceller som lager antistoffer.', 7),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Antistoff', 'Protein som passer til et bestemt antigen og uskadeliggjør smittestoffet.', 8),
  ('naturfag-10:immunforsvar-og-vaksiner', 'T-celler', 'Hvite blodceller som styrer forsvaret og dreper virusinfiserte celler.', 9),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Hukommelsesceller', 'Celler som husker smittestoffet og gir rask reaksjon neste gang.', 10),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Immun', 'Beskyttet mot en sykdom fordi kroppen husker smittestoffet.', 11),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Vaksine', 'Lærer immunforsvaret å kjenne igjen et smittestoff uten at man blir syk.', 12),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Flokkimmunitet', 'Når mange nok er vaksinert, sprer smitten seg dårlig, og også uvaksinerte beskyttes.', 13),
  ('naturfag-10:immunforsvar-og-vaksiner', 'Kopper', 'Sykdom som er erklært utryddet (1980) takket være vaksinasjon.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-10:immunforsvar-og-vaksiner', 'q01', 'flervalg', 'Hva er forskjellen på bakterier og virus?', array['Det finnes ingen forskjell', 'Bakterier er levende celler, virus må inn i celler for å formere seg', 'Virus er større enn bakterier', 'Bakterier kan bare leve i vann']::text[], 1, 'Virus mangler egne celleprosesser og bruker kroppens celler til å lage nye virus.', true, true, 0),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q02', 'flervalg', 'Hvilken er en del av kroppens første forsvarslinje?', array['Huden', 'Antistoffer', 'Hukommelsesceller', 'T-celler']::text[], 0, 'Huden hindrer smittestoffer i å komme inn i kroppen.', true, true, 1),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q03', 'flervalg', 'Hva lager B-cellene?', array['Hormoner', 'Magesyre', 'Antistoffer', 'Røde blodceller']::text[], 2, 'Antistoffene passer til antigenene på et bestemt smittestoff.', true, true, 2),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q04', 'flervalg', 'Hvorfor blir du sjelden syk av samme sykdom to ganger?', array['Fordi smittestoffet dør ut', 'Fordi du får feber', 'Fordi huden blir tykkere', 'Fordi hukommelsesceller gjør at kroppen reagerer raskt neste gang']::text[], 3, 'Hukommelsescellene gjenkjenner smittestoffet og setter raskt i gang forsvaret.', true, true, 3),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q05', 'flervalg', 'Hvordan virker en vaksine?', array['Den lærer immunforsvaret å kjenne igjen et smittestoff uten at du blir syk', 'Den dreper alle bakterier i kroppen', 'Den erstatter immunforsvaret', 'Den virker som antibiotika']::text[], 0, 'Vaksinen gir kroppen antistoffer og hukommelsesceller mot smittestoffet.', true, true, 4),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q06', 'flervalg', 'Hva er flokkimmunitet?', array['At dyr er immune', 'At bare voksne er beskyttet', 'At smitte sprer seg dårlig når mange er immune, slik at også uvaksinerte beskyttes', 'At man blir immun av å være i en gruppe']::text[], 2, 'Når få kan bli smittet, finner smittestoffet få nye verter.', true, true, 5),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q07', 'flervalg', 'Hva gjør eteceller?', array['Lager antistoffer', 'Spiser opp mikrober', 'Frakter oksygen', 'Lager hormoner']::text[], 1, 'Eteceller (fagocytter) er hvite blodceller som omslutter og bryter ned mikrober.', true, true, 6),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q08', 'flervalg', 'Hvilken sykdom er erklært utryddet takket være vaksiner?', array['Influensa', 'Forkjølelse', 'Meslinger', 'Kopper']::text[], 3, 'WHO erklærte kopper utryddet i 1980.', true, false, 7),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q09', 'flervalg', 'Hva er et antigen?', array['Et kjennetegn på overflaten av et smittestoff', 'En type vaksine', 'Et legemiddel', 'En hvit blodcelle']::text[], 0, 'Immunforsvaret kjenner igjen smittestoffer på antigenene deres.', true, false, 8),
  ('naturfag-10:immunforsvar-og-vaksiner', 'q10', 'flervalg', 'Hva kan skje hvis vaksinasjonsdekningen synker?', array['Ingenting', 'Sykdommene blir farligere for vaksinerte', 'Sykdommer som har vært sjeldne, kan komme tilbake', 'Alle blir immune automatisk']::text[], 2, 'Flokkimmuniteten svekkes, og smitte kan spre seg igjen, som ved meslingutbrudd.', true, true, 9),
  ('naturfag-10:immunforsvar-og-vaksiner', 'm01', 'sant-usant', 'Alle bakterier er farlige.', array['Sant', 'Usant']::text[], 1, 'De fleste bakterier er ufarlige, og mange er nyttige, for eksempel i tarmen.', false, true, 10),
  ('naturfag-10:immunforsvar-og-vaksiner', 'm02', 'sant-usant', 'Et antistoff passer bare til et bestemt antigen.', array['Sant', 'Usant']::text[], 0, 'Antistoffer er spesifikke, som en nøkkel som passer i én lås.', false, true, 11),
  ('naturfag-10:immunforsvar-og-vaksiner', 'm03', 'sant-usant', 'Feber kan hjelpe kroppen å bekjempe infeksjoner.', array['Sant', 'Usant']::text[], 0, 'Mange mikrober trives dårligere ved høyere temperatur.', false, true, 12),
  ('naturfag-10:immunforsvar-og-vaksiner', 'm04', 'sant-usant', 'Barnevaksinasjonsprogrammet i Norge koster penger for familiene.', array['Sant', 'Usant']::text[], 1, 'Vaksinene i barnevaksinasjonsprogrammet er gratis.', false, true, 13),
  ('naturfag-10:immunforsvar-og-vaksiner', 'm05', 'flervalg', 'Hva slags vaksine gir cellene en oppskrift på et ufarlig protein fra viruset?', array['mRNA-vaksine', 'Antibiotika', 'Levende bakterier', 'Serum']::text[], 0, 'mRNA-vaksiner får cellene til å lage et protein som immunforsvaret lærer å kjenne igjen.', false, true, 14),
  ('naturfag-10:immunforsvar-og-vaksiner', 'm06', 'flervalg', 'Hvilke celler dreper kroppsceller som er infisert av virus?', array['Røde blodceller', 'Noen typer T-celler', 'Nerveceller', 'Hudceller']::text[], 1, 'Såkalte drepe-T-celler fjerner infiserte celler.', false, true, 15),
  ('naturfag-10:immunforsvar-og-vaksiner', 'm07', 'flervalg', 'Hva er tegn på betennelse?', array['Kulde og blekhet', 'Kløe og nysing alltid', 'Rødme, varme og hevelse', 'Nummenhet']::text[], 2, 'Mer blod strømmer til området for å bekjempe smittestoffene.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-10:immunforsvar-og-vaksiner', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-10:immunforsvar-og-vaksiner', 's01', 'Hva betyr det at en mikroorganisme er et patogen? Forklar hva den kan gjøre, og nevn hvilke typer mikroorganismer som kan være patogener.', 'Et patogen er en mikroorganisme som kan gi sykdom. Enkelte bakterier og virus er patogener.', array['Forklarer at et patogen kan gi sykdom.', 'Nevner bakterier og/eller virus som mulige patogener.']::text[], 0),
  ('naturfag-10:immunforsvar-og-vaksiner', 's02', 'Når et smittestoff kommer inn gjennom et sår, kan området bli rødt, varmt og hovent. Forklar hvorfor disse tegnene oppstår.', 'Kroppen starter en betennelse for å bekjempe mikrobene. Mer blod strømmer til området, og det gjør det rødt, varmt og hovent.', array['Knytter tegnene til en betennelse som oppstår når kroppen bekjemper mikrober.', 'Forklarer at økt blodtilstrømning gjør området rødt og varmt, og bidrar til hevelsen.']::text[], 1),
  ('naturfag-10:immunforsvar-og-vaksiner', 's03', 'Sammenlign kroppens første forsvarslinje med det spesifikke immunforsvaret. Forklar hva hver av dem gjør.', 'Den første forsvarslinjen, som hud og slimhinner, hindrer smittestoffer i å komme inn. Det spesifikke immunforsvaret reagerer mot bestemte smittestoffer som har bestemte antigener.', array['Forklarer at første forsvarslinje hindrer smittestoffer i å komme inn.', 'Forklarer at det spesifikke immunforsvaret retter seg mot bestemte smittestoffer.']::text[], 2),
  ('naturfag-10:immunforsvar-og-vaksiner', 's04', 'Antistoffer passer til bestemte antigener på smittestoffer. Forklar hvordan denne tilpasningen hjelper kroppen med å bekjempe smittestoffet.', 'Når et antistoff binder seg til antigenet det passer til, kan smittestoffet bli uskadeliggjort. Antistoffet kan også merke smittestoffet slik at eteceller lettere kan spise det opp.', array['Forklarer at antistoffet binder seg til et antigen det passer til.', 'Forklarer at bindingen kan uskadeliggjøre eller merke smittestoffet for eteceller.']::text[], 3),
  ('naturfag-10:immunforsvar-og-vaksiner', 's05', 'En kroppscelle er infisert av et virus. Hvilken type hvit blodcelle kan drepe den infiserte cellen, og hva er en annen oppgave denne celletypen har i immunforsvaret?', 'T-celler kan drepe kroppsceller som er infisert av virus. De hjelper også til med å styre immunforsvaret.', array['Identifiserer T-celler som celler som kan drepe virusinfiserte kroppsceller.', 'Nevner at T-celler også hjelper til med å styre immunforsvaret.']::text[], 4),
  ('naturfag-10:immunforsvar-og-vaksiner', 's06', 'Mikrober kommer inn i kroppen sammen med mat. Forklar hvordan magesyren kan bidra til kroppens første forsvar.', 'Magesyren dreper mange mikrober som kommer inn med maten. Dermed hindrer den noen smittestoffer i å fortsette inn i kroppen.', array['Forklarer at magesyre dreper mange mikrober i maten.', 'Knytter dette til at kroppens første forsvar hindrer smittestoffer i å komme videre inn.']::text[], 5),
  ('naturfag-10:immunforsvar-og-vaksiner', 's07', 'I en tenkt gruppe er 20 personer med, og 15 av dem er vaksinert. Hvor stor prosentandel av gruppen er vaksinert? Vis det viktigste regnestykket.', '15 av 20 er 15 ÷ 20 = 0,75, altså 75 prosent.', array['Viser en riktig utregning av 15 delt på 20 eller tilsvarende.', 'Oppgir svaret 75 prosent.']::text[], 6),
  ('naturfag-10:immunforsvar-og-vaksiner', 's08', 'I en annen tenkt gruppe er 7 personer vaksinert og 5 personer ikke vaksinert. Hvor mange personer er det i gruppen til sammen? Vis regnestykket.', 'Det er 7 + 5 = 12 personer i gruppen.', array['Legger sammen antallet vaksinerte og uvaksinerte.', 'Oppgir riktig total, 12 personer.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'naturfag-10', 'seksuell-og-reproduktiv-helse', 'Seksuell og reproduktiv helse', 'Puberteten, forplantning og menstruasjonssyklusen, prevensjon og seksuelt overførbare infeksjoner – og samtykke, grenser og mangfold.', array[20]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-10:seksuell-og-reproduktiv-helse', '## Hva er seksuell og reproduktiv helse?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Seksuell helse', 'Å ha det godt med egen kropp og seksualitet, ta trygge valg og bli respektert.', 0),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Reproduktiv helse', 'Å kunne velge om og når man vil få barn, og beskytte seg mot sykdom.', 1),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Pubertet', 'Perioden der kroppen utvikles til en voksen kropp, styrt av kjønnshormoner.', 2),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Eggløsning', 'Når et modent egg slippes ut fra eggstokken, omtrent én gang i måneden.', 3),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Befruktning', 'Når en sædcelle og et egg smelter sammen.', 4),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Menstruasjon', 'Livmorslimhinnen støtes ut når egget ikke er befruktet.', 5),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Menstruasjonssyklus', 'Ofte rundt 28 dager, men varierer, særlig de første årene.', 6),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Prevensjon', 'Metoder som hindrer graviditet.', 7),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Kondom', 'Beskytter både mot graviditet og mot seksuelt overførbare infeksjoner.', 8),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Hormonell prevensjon', 'P-piller, p-stav og hormonspiral hindrer blant annet eggløsning.', 9),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'SOI', 'Seksuelt overførbare infeksjoner, som klamydia, gonoré, herpes, HPV og hiv.', 10),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Klamydia', 'En av de vanligste SOI blant unge. Gir ofte ingen symptomer.', 11),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'HPV-vaksine', 'Vaksine mot humant papillomavirus, del av barnevaksinasjonsprogrammet.', 12),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Samtykke', 'At alle involverte frivillig sier ja, og kan ombestemme seg når som helst.', 13),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'Seksuell lavalder', '16 år i Norge.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q01', 'flervalg', 'Hvilke hormoner styrer puberteten?', array['Insulin og glukagon', 'Østrogen og testosteron', 'Adrenalin og kortisol', 'Dopamin og serotonin']::text[], 1, 'Kjønnshormonene gir kroppsendringene i puberteten.', true, true, 0),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q02', 'flervalg', 'Hva er eggløsning?', array['Når et modent egg slippes ut fra eggstokken', 'Når fosteret blir født', 'Når menstruasjonen starter', 'Når sædceller dannes']::text[], 0, 'Eggløsningen skjer omtrent én gang i måneden.', true, true, 1),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q03', 'flervalg', 'Hvilken prevensjonsmetode beskytter også mot seksuelt overførbare infeksjoner?', array['P-piller', 'P-stav', 'Kondom', 'Hormonspiral']::text[], 2, 'Kondomet hindrer kontakt med kroppsvæsker og beskytter derfor også mot SOI.', true, true, 2),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q04', 'flervalg', 'Hvorfor er klamydia lett å overse?', array['Den gir alltid høy feber', 'Den smitter ikke', 'Den varer bare én dag', 'Den gir ofte ingen symptomer']::text[], 3, 'Mange merker ingenting, derfor er testing viktig.', true, true, 3),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q05', 'flervalg', 'Hva betyr samtykke?', array['At alle involverte frivillig sier ja og kan ombestemme seg', 'At man har sagt ja én gang for alltid', 'At foreldrene har sagt ja', 'At man ikke har sagt nei']::text[], 0, 'Samtykke må være frivillig og kan trekkes tilbake når som helst.', true, true, 4),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q06', 'flervalg', 'Hva er den seksuelle lavalderen i Norge?', array['14 år', '15 år', '16 år', '18 år']::text[], 2, 'Den seksuelle lavalderen i Norge er 16 år.', true, true, 5),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q07', 'flervalg', 'Hva skjer hvis egget ikke blir befruktet?', array['Det utvikler seg likevel til et foster', 'Livmorslimhinnen støtes ut som menstruasjon', 'Egget blir i eggstokken for alltid', 'Det dannes nye sædceller']::text[], 1, 'Slimhinnen som ble bygd opp, trengs ikke og støtes ut.', true, true, 6),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q08', 'flervalg', 'Hvilken SOI finnes det vaksine mot i barnevaksinasjonsprogrammet?', array['Klamydia', 'Gonoré', 'Herpes', 'HPV']::text[], 3, 'HPV-vaksinen beskytter blant annet mot livmorhalskreft.', true, true, 7),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q09', 'flervalg', 'Hvor kan unge få gratis veiledning om prevensjon og seksuell helse?', array['Helsestasjon for ungdom', 'Bare hos privatlege mot betaling', 'Ingen steder', 'I butikken']::text[], 0, 'Helsestasjon for ungdom tilbyr gratis og konfidensiell hjelp.', true, false, 8),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'q10', 'flervalg', 'Er det lovlig å dele nakenbilder av andre uten samtykke?', array['Ja, hvis bildet ble sendt til deg', 'Ja, hvis det er en venn', 'Nei, det er ulovlig', 'Ja, hvis man er over 16']::text[], 2, 'Deling av slike bilder uten samtykke er straffbart og kan skade den som blir utsatt for det.', true, false, 9),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'm01', 'sant-usant', 'Puberteten starter på samme alder for alle.', array['Sant', 'Usant']::text[], 1, 'Puberteten starter på ulike tidspunkter, og det er helt normalt.', false, true, 10),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'm02', 'sant-usant', 'P-piller beskytter mot seksuelt overførbare infeksjoner.', array['Sant', 'Usant']::text[], 1, 'P-piller hindrer graviditet, men beskytter ikke mot SOI. Kondom gjør det.', false, true, 11),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'm03', 'sant-usant', 'Man kan ombestemme seg selv om man har sagt ja tidligere.', array['Sant', 'Usant']::text[], 0, 'Samtykke kan trekkes tilbake når som helst.', false, true, 12),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'm04', 'sant-usant', 'Mange seksuelt overførbare infeksjoner kan behandles.', array['Sant', 'Usant']::text[], 0, 'For eksempel kan klamydia behandles med antibiotika. Derfor er testing viktig.', false, true, 13),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'm05', 'flervalg', 'Hva er seksuell orientering?', array['Hvilket kjønn man er født med', 'Hvem man forelsker seg i og tiltrekkes av', 'Hvor gammel man er', 'Hvilken prevensjon man bruker']::text[], 1, 'Seksuell orientering handler om tiltrekning og forelskelse.', false, true, 14),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'm06', 'flervalg', 'Hvor lang er en menstruasjonssyklus ofte?', array['7 dager', '14 dager', 'Rundt 28 dager', '60 dager']::text[], 2, 'Rundt 28 dager er vanlig, men syklusen varierer mye.', false, true, 15),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 'm07', 'flervalg', 'Hva kan klamydia føre til hvis den ikke behandles?', array['Bedre immunforsvar', 'Nedsatt fruktbarhet', 'Ingenting', 'Høyere blodsukker']::text[], 1, 'Ubehandlet klamydia kan gi betennelser som skader fruktbarheten.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-10:seksuell-og-reproduktiv-helse', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-10:seksuell-og-reproduktiv-helse', 's01', 'Forklar med egne ord hva reproduktiv helse handler om.', 'Reproduktiv helse handler om å kunne velge om og når man vil få barn, og om å beskytte seg mot sykdom.', array['Får fram at det handler om muligheten til å velge om og når man vil få barn.', 'Får fram at beskyttelse mot sykdom også inngår.']::text[], 0),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 's02', 'En menstruasjonssyklus varer ofte rundt 28 dager, men kan variere, særlig de første årene. Forklar hvorfor det ikke er riktig å forvente at alle har en syklus på nøyaktig 28 dager.', '28 dager er en vanlig omtrentlig lengde, ikke en fast lengde for alle. Syklusen varierer fra person til person og særlig de første årene.', array['Forklarer at 28 dager er omtrentligt, ikke en nøyaktig regel for alle.', 'Nevner at syklusen varierer, særlig de første årene.']::text[], 1),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 's03', 'Sammenlign hvordan kondom og hormonell prevensjon kan hindre graviditet. Ta også med én forskjell mellom dem når det gjelder beskyttelse mot SOI.', 'Kondom hindrer sædceller i å nå egget, mens hormonell prevensjon blant annet kan hindre eggløsning. Kondom beskytter også mot SOI, mens hormonell prevensjon ikke gjør det.', array['Beskriver en riktig måte kondom kan hindre graviditet på og en riktig måte hormonell prevensjon kan virke på.', 'Får fram at kondom også beskytter mot SOI.']::text[], 2),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 's04', 'En syklus varer ofte rundt 28 dager. Regn ut hvor mange dager to sykluser blir til sammen hvis hver av dem varer 28 dager. Vis regnestykket.', '28 + 28 = 56. To sykluser på 28 dager blir til sammen 56 dager.', array['Viser et riktig regnestykke, for eksempel 28 + 28.', 'Oppgir svaret 56 dager.']::text[], 3),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 's05', 'En person har sagt ja til seksuell aktivitet, men ombestemmer seg underveis. Forklar hva de andre involverte skal gjøre, og hvorfor.', 'De andre skal stoppe, fordi samtykke kan trekkes tilbake når som helst. All seksuell aktivitet skal være frivillig.', array['Får fram at aktiviteten skal stoppe når personen ombestemmer seg.', 'Begrunner dette med at samtykke kan trekkes tilbake og at aktiviteten skal være frivillig.']::text[], 4),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 's06', 'Tenk deg en periode på 28 dager som deles i fire like lange deler. Hvor mange dager er det i hver del? Vis regnestykket.', '28 ÷ 4 = 7. Hver del er 7 dager.', array['Viser at 28 deles på 4.', 'Oppgir svaret 7 dager.']::text[], 5),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 's07', 'En person kan ha klamydia uten å merke symptomer. Forklar hvorfor testing likevel er viktig, og hva ubehandlet klamydia kan føre til.', 'Testing er viktig fordi klamydia ofte ikke gir symptomer, og smitten ellers kan bli oversett. Ubehandlet klamydia kan føre til nedsatt fruktbarhet.', array['Får fram at klamydia ofte ikke gir symptomer, slik at smitte kan bli oversett.', 'Nevner at ubehandlet klamydia kan føre til nedsatt fruktbarhet.']::text[], 6),
  ('naturfag-10:seksuell-og-reproduktiv-helse', 's08', 'Forklar forskjellen på seksuell orientering og kjønnsidentitet. Ta med hvordan kunnskap og respekt for mangfold kan bidra til god seksuell helse.', 'Seksuell orientering handler om hvem man forelsker seg i og tiltrekkes av, mens kjønnsidentitet handler om hvilket kjønn man opplever seg som. Kunnskap og respekt for forskjeller bidrar til at alle kan ha god seksuell helse.', array['Skiller mellom hvem man forelsker seg i eller tiltrekkes av, og hvilket kjønn man opplever seg som.', 'Får fram at kunnskap og respekt for mangfold bidrar til god seksuell helse.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-10:modeller-i-naturfag', 'naturfag-10', 'modeller-i-naturfag', 'Modeller i naturfag', 'Hva modeller er, ulike typer modeller, hvordan de brukes til å forklare og forutsi, og hvorfor alle modeller har styrker og begrensninger.', array[3, 2]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-10:modeller-i-naturfag', '## Hvorfor modeller?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-10:modeller-i-naturfag', 'Modell', 'En forenklet framstilling av virkeligheten som hjelper oss å forklare og forutsi.', 0),
  ('naturfag-10:modeller-i-naturfag', 'Fysisk modell', 'En modell man kan ta på, som en globus eller en molekylmodell.', 1),
  ('naturfag-10:modeller-i-naturfag', 'Begrepsmodell', 'En modell som beskriver sammenhenger med ord og begreper, som partikkelmodellen.', 2),
  ('naturfag-10:modeller-i-naturfag', 'Matematisk modell', 'En modell som bruker formler, som s = v · t.', 3),
  ('naturfag-10:modeller-i-naturfag', 'Datamodell', 'Et dataprogram som simulerer et komplekst system, som klimaet.', 4),
  ('naturfag-10:modeller-i-naturfag', 'Forutsi', 'Bruke en modell til å si hva som vil skje.', 5),
  ('naturfag-10:modeller-i-naturfag', 'Modellens styrker', 'Gjør noe komplisert forståelig og gir mulighet for forutsigelser.', 6),
  ('naturfag-10:modeller-i-naturfag', 'Modellens begrensninger', 'Det modellen ikke viser eller forenkler bort.', 7),
  ('naturfag-10:modeller-i-naturfag', 'Partikkelmodellen', 'Stoffer består av partikler som ligger tett i faste stoffer og beveger seg fritt i gasser.', 8),
  ('naturfag-10:modeller-i-naturfag', 'Dalton', 'Så atomer som små, udelelige kuler (tidlig 1800-tall).', 9),
  ('naturfag-10:modeller-i-naturfag', 'Thomson', 'Oppdaget elektronet i 1897. «Rosinbollemodellen».', 10),
  ('naturfag-10:modeller-i-naturfag', 'Rutherford', 'Viste i 1911 at atomet har en liten, tett kjerne.', 11),
  ('naturfag-10:modeller-i-naturfag', 'Bohr', 'Plasserte elektronene i bestemte skall rundt kjernen (1913).', 12),
  ('naturfag-10:modeller-i-naturfag', 'Modeller endres', 'Når nye observasjoner ikke passer, forbedres eller erstattes modellen.', 13),
  ('naturfag-10:modeller-i-naturfag', 'Globus', 'Viser jordas form og kontinenter, men ikke høyder eller at jorda er litt flattrykt.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-10:modeller-i-naturfag', 'q01', 'flervalg', 'Hva er en modell i naturfag?', array['En eksakt kopi av virkeligheten', 'En forenklet framstilling som hjelper oss å forklare og forutsi', 'En person som viser klær', 'Et forsøk på lab']::text[], 1, 'Modeller forenkler for å gjøre noe forståelig og for å kunne forutsi.', true, true, 0),
  ('naturfag-10:modeller-i-naturfag', 'q02', 'flervalg', 'Hvilken er en matematisk modell?', array['En globus', 'En tegning av en celle', 'Formelen s = v · t', 'En kulemodell av vann']::text[], 2, 'Matematiske modeller beskriver sammenhenger med formler.', true, true, 1),
  ('naturfag-10:modeller-i-naturfag', 'q03', 'flervalg', 'Hva er en begrensning ved en globus?', array['Den viser ikke høyden på fjellene', 'Den viser ikke kontinentene', 'Den er ikke rund', 'Den viser ikke havene']::text[], 0, 'Globusen forenkler bort blant annet høydeforskjeller.', true, true, 2),
  ('naturfag-10:modeller-i-naturfag', 'q04', 'flervalg', 'Hvem oppdaget at atomet har en liten, tett kjerne?', array['John Dalton', 'J.J. Thomson', 'Niels Bohr', 'Ernest Rutherford']::text[], 3, 'Rutherfords forsøk i 1911 viste at det meste av atomet er tomrom rundt en liten kjerne.', true, true, 3),
  ('naturfag-10:modeller-i-naturfag', 'q05', 'flervalg', 'Hvorfor endres modeller over tid?', array['Fordi forskere liker å forandre ting', 'Fordi nye observasjoner ikke passer med den gamle modellen', 'Fordi gamle modeller blir slitt', 'De endres aldri']::text[], 1, 'Når en modell ikke kan forklare nye observasjoner, må den forbedres eller erstattes.', true, true, 4),
  ('naturfag-10:modeller-i-naturfag', 'q06', 'flervalg', 'Hva slags modell er en værmelding basert på?', array['En fysisk modell', 'En tegning', 'En datamodell som simulerer atmosfæren', 'En begrepsmodell uten tall']::text[], 2, 'Meteorologer bruker store datamodeller som regner på atmosfæren.', true, true, 5),
  ('naturfag-10:modeller-i-naturfag', 'q07', 'flervalg', 'Hvem plasserte elektronene i bestemte skall rundt kjernen?', array['Niels Bohr', 'John Dalton', 'Isaac Newton', 'Charles Darwin']::text[], 0, 'Bohrs modell fra 1913 forklarte blant annet lysspektre fra atomer.', true, false, 6),
  ('naturfag-10:modeller-i-naturfag', 'q08', 'flervalg', 'Hva bør du alltid spørre om når du bruker en modell?', array['Hvem har laget den?', 'Hvor mye koster den?', 'Hvor stor er den?', 'Hva viser den godt, og hva viser den ikke?']::text[], 3, 'Da blir du bevisst både styrkene og begrensningene.', true, true, 7),
  ('naturfag-10:modeller-i-naturfag', 'q09', 'flervalg', 'Hva beskriver partikkelmodellen?', array['Hvordan stoffer består av partikler som oppfører seg ulikt i faste stoffer, væsker og gasser', 'Hvordan planeter går rundt sola', 'Hvordan celler deler seg', 'Hvordan vær oppstår']::text[], 0, 'Partikkelmodellen forklarer blant annet smelting, fordamping og trykk.', true, false, 8),
  ('naturfag-10:modeller-i-naturfag', 'q10', 'flervalg', 'Hva så Thomson for seg etter at han oppdaget elektronet?', array['Atomet som en udelelig kule', 'Atomet som en positiv masse med elektroner i, som rosiner i en kake', 'Elektroner i skall', 'En tett kjerne med tomrom rundt']::text[], 1, 'Thomsons modell kalles ofte rosinbollemodellen.', true, true, 9),
  ('naturfag-10:modeller-i-naturfag', 'm01', 'sant-usant', 'En god modell viser alt nøyaktig slik det er i virkeligheten.', array['Sant', 'Usant']::text[], 1, 'Alle modeller forenkler. En god modell er nyttig for formålet.', false, true, 10),
  ('naturfag-10:modeller-i-naturfag', 'm02', 'sant-usant', 'Dagens atommodell er den samme som Daltons.', array['Sant', 'Usant']::text[], 1, 'Atommodellen har blitt endret mange ganger siden Dalton.', false, true, 11),
  ('naturfag-10:modeller-i-naturfag', 'm03', 'sant-usant', 'En næringskjede er en form for modell.', array['Sant', 'Usant']::text[], 0, 'Den forenkler sammenhengene i et økosystem.', false, true, 12),
  ('naturfag-10:modeller-i-naturfag', 'm04', 'sant-usant', 'Modeller kan brukes til å forutsi hva som vil skje.', array['Sant', 'Usant']::text[], 0, 'Klimamodeller og værmeldinger er eksempler.', false, true, 13),
  ('naturfag-10:modeller-i-naturfag', 'm05', 'flervalg', 'Hvilken modell er en fysisk modell?', array['s = v · t', 'En kulemodell av et molekyl', 'En begrepsdefinisjon', 'Et regneark']::text[], 1, 'Fysiske modeller kan tas og føles på.', false, true, 14),
  ('naturfag-10:modeller-i-naturfag', 'm06', 'flervalg', 'Hva er en begrensning ved en tegning av et atom med elektroner i sirkelbaner?', array['Elektronene beveger seg ikke egentlig i slike baner', 'Den viser ikke kjernen', 'Den er for stor', 'Den har ingen begrensninger']::text[], 0, 'Modellen er nyttig, men dagens kvantemekaniske modell viser at elektronene ikke har faste baner.', false, true, 15),
  ('naturfag-10:modeller-i-naturfag', 'm07', 'flervalg', 'Når oppdaget Thomson elektronet?', array['1803', '1911', '1897', '1913']::text[], 2, 'J.J. Thomson oppdaget elektronet i 1897.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-10:modeller-i-naturfag', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-10:modeller-i-naturfag', 's01', 'Atomer er for små til at vi kan se dem direkte. Forklar hvordan en modell likevel kan hjelpe oss med å forstå atomer og med å forutsi noe om dem.', 'En modell gir en forenklet framstilling av atomene, slik at vi kan forstå dem selv om vi ikke ser dem direkte. Den kan også hjelpe oss med å forklare observasjoner og forutsi hva som vil skje.', array['Forklarer at modellen gjør noe vi ikke kan se direkte, lettere å forstå.', 'Får fram at modeller kan brukes til å forklare observasjoner eller forutsi.']::text[], 0),
  ('naturfag-10:modeller-i-naturfag', 's02', 'Sammenlign en fysisk modell med en begrepsmodell. Gi ett eksempel på hver type, og forklar forskjellen på hvordan de framstiller noe.', 'En globus er en fysisk modell som vi kan ta på, mens partikkelmodellen er en begrepsmodell som beskriver sammenhenger med ord og begreper. Den fysiske modellen er en konkret gjenstand, mens begrepsmodellen forklarer hvordan noe henger sammen.', array['Gir et passende eksempel på en fysisk modell og en begrepsmodell.', 'Forklarer forskjellen mellom en modell som kan tas på, og en som beskriver sammenhenger med begreper.']::text[], 1),
  ('naturfag-10:modeller-i-naturfag', 's03', 'Du skal lage en modell av en celle. Forklar hva du må velge når du bestemmer hva som skal være med, og hvordan det å utelate noe både kan være nyttig og begrensende.', 'Jeg må velge hvilke deler eller sammenhenger som er viktige å vise, og hva som kan utelates. Det gjør modellen enklere å forstå, men den viser ikke alle sider ved cellen.', array['Forklarer at man velger hva som er viktig å ta med, og hva som kan utelates.', 'Får fram både at forenklingen gjør modellen lettere å forstå, og at noe informasjon dermed mangler.']::text[], 2),
  ('naturfag-10:modeller-i-naturfag', 's04', 'En tegning viser elektroner i sirkelbaner rundt atomkjernen. Forklar hva en slik tegning kan hjelpe oss med å forstå, og hvorfor den ikke viser elektronene helt slik de beveger seg.', 'Tegningen kan hjelpe oss med å forstå skallene i atomet og sammenhengen med periodesystemet. Men elektronene beveger seg ikke egentlig i bestemte sirkelbaner slik tegningen viser.', array['Nevner at tegningen kan hjelpe med å forstå skall eller periodesystemet.', 'Forklarer at elektronene ikke egentlig beveger seg i sirkelbaner slik tegningen viser.']::text[], 3),
  ('naturfag-10:modeller-i-naturfag', 's05', 'Sammenlign Daltons atommodell med dagens kvantemekaniske modell. Hva er én viktig forskjell på hvordan de beskriver atomet?', 'Dalton så for seg atomet som en liten, udelelig kule. I dagens kvantemekaniske modell har elektronene ikke bestemte baner rundt kjernen.', array['Beskriver Daltons atom som en liten, udelelig kule.', 'Får fram at elektronene i den kvantemekaniske modellen ikke har bestemte baner.']::text[], 4),
  ('naturfag-10:modeller-i-naturfag', 's06', 'Bruk partikkelmodellen til å sammenligne et fast stoff med en gass. Hva sier modellen om hvor partiklene er, og hvordan de beveger seg?', 'I et fast stoff ligger partiklene tett. I en gass beveger partiklene seg fritt.', array['Forklarer at partiklene ligger tett i faste stoffer.', 'Forklarer at partiklene beveger seg fritt i gasser.']::text[], 5),
  ('naturfag-10:modeller-i-naturfag', 's07', 'En matematisk modell for strekning er s = v · t, der v er fart og t er tid. Hvis farten er uendret og tiden blir dobbelt så stor, hvordan endres strekningen? Vis det viktigste steget.', 'Strekningen blir dobbelt så stor. Siden s = v · t og v er uendret, gir dobbelt så stor t dobbelt så stor verdi av s.', array['Svarar at strekningen blir dobbelt så stor.', 'Begrunner det med at v er uendret og at s beregnes som v · t.']::text[], 6),
  ('naturfag-10:modeller-i-naturfag', 's08', 'I modellen s = v · t er strekningen s fast. Hvis farten v blir dobbelt så stor, hvordan må tiden t endres? Vis det viktigste steget.', 'Tiden må bli halvparten så stor. Når strekningen er fast i s = v · t, må en dobling av v balanseres av at t halveres.', array['Svarar at tiden må halveres.', 'Begrunner svaret med sammenhengen s = v · t og at strekningen er fast.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('naturfag-10:forskning-og-kunnskap', 'naturfag-10', 'forskning-og-kunnskap', 'Forskning og ny kunnskap', 'Hvordan ny naturvitenskapelig kunnskap blir til gjennom samarbeid, fagfellevurdering og kritisk testing, med eksempler på dagsaktuell forskning.', array[5, 2]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('naturfag-10:forskning-og-kunnskap', '## Kunnskap som stadig testes
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('naturfag-10:forskning-og-kunnskap', 'Fagfellevurdering', 'Andre eksperter vurderer en forskningsartikkel før den publiseres.', 0),
  ('naturfag-10:forskning-og-kunnskap', 'Replikasjon', 'Å gjenta et forsøk for å se om man får samme resultat.', 1),
  ('naturfag-10:forskning-og-kunnskap', 'Konsensus', 'Bred enighet blant forskere, basert på mange uavhengige undersøkelser.', 2),
  ('naturfag-10:forskning-og-kunnskap', 'Vitenskapelig tidsskrift', 'Publikasjon der forskningsresultater gjøres kjent for andre forskere.', 3),
  ('naturfag-10:forskning-og-kunnskap', 'Korrelasjon', 'At to ting varierer sammen.', 4),
  ('naturfag-10:forskning-og-kunnskap', 'Årsakssammenheng', 'At én ting faktisk forårsaker en annen.', 5),
  ('naturfag-10:forskning-og-kunnskap', 'Korrelasjon ≠ årsak', 'Is-salg og drukninger øker samtidig fordi begge skyldes varmt vær.', 6),
  ('naturfag-10:forskning-og-kunnskap', 'Interessekonflikt', 'Når forskeren eller finansieringskilden kan tjene på et bestemt resultat.', 7),
  ('naturfag-10:forskning-og-kunnskap', 'mRNA-vaksiner', 'Vaksiner som gir cellene oppskrift på et virusprotein. Nobelpris i medisin 2023.', 8),
  ('naturfag-10:forskning-og-kunnskap', 'CRISPR', 'Metode for presis genredigering. Nobelpris i kjemi 2020.', 9),
  ('naturfag-10:forskning-og-kunnskap', 'James Webb-teleskopet', 'Romteleskop skutt opp i 2021 som studerer de tidligste galaksene.', 10),
  ('naturfag-10:forskning-og-kunnskap', 'CERN', 'Stort europeisk forskningssenter for partikkelfysikk med forskere fra mange land.', 11),
  ('naturfag-10:forskning-og-kunnskap', 'Kritisk tilnærming', 'Å vurdere metoder, data og konklusjoner nøye, også sine egne.', 12),
  ('naturfag-10:forskning-og-kunnskap', 'Kunnskap i endring', 'At forskere endrer syn ved nye data er en styrke ved naturvitenskapen.', 13),
  ('naturfag-10:forskning-og-kunnskap', 'Utvalgsstørrelse', 'Store og gode utvalg gir sikrere konklusjoner enn få forsøk.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('naturfag-10:forskning-og-kunnskap', 'q01', 'flervalg', 'Hva er fagfellevurdering?', array['At venner leser artikkelen', 'At andre eksperter vurderer forskningen før den publiseres', 'At journalister skriver om forskningen', 'At forskeren vurderer seg selv']::text[], 1, 'Fagfeller ser etter svakheter i metode, analyse og konklusjoner.', true, true, 0),
  ('naturfag-10:forskning-og-kunnskap', 'q02', 'flervalg', 'Hvorfor er replikasjon viktig?', array['Fordi det gjør forskningen dyrere', 'Fordi det viser om resultatet holder når andre gjentar forsøket', 'Fordi det er påbudt ved lov', 'Fordi resultater ellers forsvinner']::text[], 1, 'Resultater som kan gjentas av uavhengige forskere, er mer pålitelige.', true, true, 1),
  ('naturfag-10:forskning-og-kunnskap', 'q03', 'flervalg', 'Salg av is og antall drukninger øker om sommeren. Hva kan vi konkludere?', array['At is forårsaker drukning', 'At drukning gjør folk sultne på is', 'At begge trolig skyldes en tredje faktor, som varmt vær', 'At tallene er feil']::text[], 2, 'Korrelasjon er ikke årsak. Varmt vær får flere til både å kjøpe is og å bade.', true, true, 2),
  ('naturfag-10:forskning-og-kunnskap', 'q04', 'flervalg', 'Hva er konsensus i forskning?', array['At én forsker har bestemt noe', 'At alle forsøk gir samme tall', 'En avstemning blant politikere', 'Bred enighet basert på mange uavhengige undersøkelser']::text[], 3, 'Konsensus bygger på samlet evidens fra mange studier.', true, true, 3),
  ('naturfag-10:forskning-og-kunnskap', 'q05', 'flervalg', 'Hvilken metode for genredigering fikk Nobelprisen i kjemi i 2020?', array['CRISPR', 'mRNA', 'PCR', 'Kloning']::text[], 0, 'CRISPR gjør det mulig å endre gener svært presist.', true, true, 4),
  ('naturfag-10:forskning-og-kunnskap', 'q06', 'flervalg', 'Hva fikk Nobelprisen i medisin i 2023?', array['Oppdagelsen av penicillin', 'Forskningen bak mRNA-vaksiner', 'Kartleggingen av menneskets DNA', 'CRISPR']::text[], 1, 'Forskningen gjorde det mulig å utvikle mRNA-vaksiner, blant annet mot covid-19.', true, true, 5),
  ('naturfag-10:forskning-og-kunnskap', 'q07', 'flervalg', 'Hva er en interessekonflikt i forskning?', array['Når forskere er uenige', 'Når forskningen er kjedelig', 'Når noen kan tjene på et bestemt resultat', 'Når forsøket mislykkes']::text[], 2, 'Interessekonflikter bør oppgis, fordi de kan påvirke hvordan forskningen gjøres eller presenteres.', true, true, 6),
  ('naturfag-10:forskning-og-kunnskap', 'q08', 'flervalg', 'Er det en svakhet at forskere endrer mening når nye data kommer?', array['Ja, det viser at forskning ikke kan stoles på', 'Ja, forskere bør aldri endre mening', 'Det har ingen betydning', 'Nei, det er en styrke at kunnskapen forbedres']::text[], 3, 'Naturvitenskapen er selvkorrigerende: bedre data gir bedre kunnskap.', true, true, 7),
  ('naturfag-10:forskning-og-kunnskap', 'q09', 'flervalg', 'Hva studerer James Webb-romteleskopet blant annet?', array['De tidligste galaksene', 'Jordas indre', 'Bakterier i havet', 'Været i Norge']::text[], 0, 'Teleskopet ser infrarødt lys fra svært fjerne og gamle galakser.', true, false, 8),
  ('naturfag-10:forskning-og-kunnskap', 'q10', 'flervalg', 'Hvorfor gir et stort utvalg sikrere svar?', array['Fordi det ser bedre ut', 'Fordi tilfeldigheter jevner seg ut når det er mange observasjoner', 'Fordi det er billigere', 'Det gir ikke sikrere svar']::text[], 1, 'Med få observasjoner kan tilfeldigheter gi et misvisende resultat.', true, false, 9),
  ('naturfag-10:forskning-og-kunnskap', 'm01', 'sant-usant', 'Moderne forskning skjer ofte i store internasjonale team.', array['Sant', 'Usant']::text[], 0, 'Store prosjekter krever samarbeid mellom mange forskere og land.', false, true, 10),
  ('naturfag-10:forskning-og-kunnskap', 'm02', 'sant-usant', 'At to ting henger sammen, beviser at den ene forårsaker den andre.', array['Sant', 'Usant']::text[], 1, 'Korrelasjon er ikke det samme som årsak.', false, true, 11),
  ('naturfag-10:forskning-og-kunnskap', 'm03', 'sant-usant', 'CRISPR reiser også etiske spørsmål.', array['Sant', 'Usant']::text[], 0, 'Muligheten til å endre gener, også hos mennesker, gir viktige etiske diskusjoner.', false, true, 12),
  ('naturfag-10:forskning-og-kunnskap', 'm04', 'sant-usant', 'Et enkelt forsøk er nok til å endre konsensus i forskningen.', array['Sant', 'Usant']::text[], 1, 'Konsensus bygger på mange undersøkelser, og ett avvikende resultat må gjentas og testes.', false, true, 13),
  ('naturfag-10:forskning-og-kunnskap', 'm05', 'flervalg', 'Hvor publiseres forskningsresultater vanligvis?', array['I vitenskapelige tidsskrifter', 'Bare på sosiale medier', 'I reklame', 'De publiseres ikke']::text[], 0, 'Tidsskriftene sørger for fagfellevurdering og gjør funnene tilgjengelige.', false, true, 14),
  ('naturfag-10:forskning-og-kunnskap', 'm06', 'flervalg', 'Når ble James Webb-teleskopet skutt opp?', array['1990', '2021', '2009', '2015']::text[], 1, 'Teleskopet ble skutt opp i desember 2021.', false, true, 15),
  ('naturfag-10:forskning-og-kunnskap', 'm07', 'flervalg', 'Hva er CERN?', array['Et norsk universitet', 'En vaksine', 'Et stort europeisk forskningssenter for partikkelfysikk', 'Et romteleskop']::text[], 2, 'Ved CERN samarbeider forskere fra hele verden om å forstå materiens minste byggesteiner.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('naturfag-10:forskning-og-kunnskap', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('naturfag-10:forskning-og-kunnskap', 's01', 'Naturvitenskapelig kunnskap kan bli endret når forskere får nye data. Forklar hvordan kunnskapen likevel kan være pålitelig.', 'Kunnskapen bygger på observasjoner og forsøk, og andre forskere kan kontrollere den kritisk. Nye data kan føre til at ideer forbedres eller forkastes.', array['Knytter pålitelighet til observasjoner og forsøk.', 'Forklarer at andre kan kontrollere funn, eller at ny kunnskap kan føre til at ideer endres.']::text[], 0),
  ('naturfag-10:forskning-og-kunnskap', 's02', 'Forskningsresultater publiseres ofte i vitenskapelige tidsskrifter. Forklar hvordan publisering kan hjelpe forskningen videre.', 'Når resultater blir publisert, kan andre forskere lese dem og bygge videre på dem. Slik kan kunnskapen utvikles gjennom videre forskning.', array['Forklarer at publisering gjør resultater tilgjengelige for andre forskere.', 'Forklarer at andre kan bruke resultatene som grunnlag for videre forskning.']::text[], 1),
  ('naturfag-10:forskning-og-kunnskap', 's03', 'Sammenlign resultatet fra én undersøkelse med vitenskapelig konsensus. Hva gjør konsensus til noe mer enn ett enkelt forskningsresultat?', 'Konsensus er bred enighet blant forskere som bygger på mange uavhengige undersøkelser. Ett enkelt resultat kommer bare fra én undersøkelse og gir ikke alene slik bred enighet.', array['Får fram at konsensus bygger på mange uavhengige undersøkelser.', 'Skiller bred enighet fra resultatet av én enkelt undersøkelse.']::text[], 2),
  ('naturfag-10:forskning-og-kunnskap', 's04', 'Et firma betaler for en undersøkelse av et produkt firmaet selger. Hva bør andre være oppmerksomme på når de vurderer resultatene, og hvorfor?', 'Det kan være en interessekonflikt fordi firmaet kan tjene på et bestemt resultat. Derfor bør metoder, data og konklusjoner vurderes kritisk, uten at resultatet automatisk avvises.', array['Ser at firmaets økonomiske interesse kan påvirke eller være relevant for resultatet.', 'Foreslår kritisk vurdering av undersøkelsen, ikke automatisk godkjenning eller avvisning.']::text[], 3),
  ('naturfag-10:forskning-og-kunnskap', 's05', 'Sammenlign mRNA-vaksiner og CRISPR ut fra hva de brukes til eller gjør.', 'mRNA-vaksiner gir cellene en oppskrift på et virusprotein. CRISPR er en metode for å redigere gener svært presist.', array['Forklarer at mRNA-vaksiner gir cellene en oppskrift på et virusprotein.', 'Forklarer at CRISPR brukes til presis genredigering.']::text[], 4),
  ('naturfag-10:forskning-og-kunnskap', 's06', 'CERN er et stort europeisk forskningssenter for partikkelfysikk med forskere fra mange land. Hva viser dette eksempelet om hvordan moderne forskning ofte organiseres?', 'Eksempelet viser at moderne forskning ofte foregår i store samarbeid på tvers av land. Store forskningsprosjekter kan samle mange forskere.', array['Får fram at forskning kan organiseres som samarbeid mellom forskere fra flere land.', 'Knytter eksempelet til store forskningsprosjekter eller store forskerteam.']::text[], 5),
  ('naturfag-10:forskning-og-kunnskap', 's07', 'Nobelprisen i kjemi for CRISPR kom i 2020, og Nobelprisen i medisin for forskningen bak mRNA-vaksiner kom i 2023. Hvor mange år skiller årstallene? Vis det viktigste regnestykket.', 'Det skiller 3 år. Regnestykket er 2023 − 2020 = 3.', array['Viser eller beskriver subtraksjonen 2023 − 2020.', 'Oppgir 3 år.']::text[], 6),
  ('naturfag-10:forskning-og-kunnskap', 's08', 'James Webb-romteleskopet ble skutt opp i 2021. Nobelprisen i medisin for forskningen bak mRNA-vaksiner ble delt ut i 2023. Hvor mange år skiller årstallene? Vis det viktigste regnestykket.', 'Det skiller 2 år. Regnestykket er 2023 − 2021 = 2.', array['Viser eller beskriver subtraksjonen 2023 − 2021.', 'Oppgir 2 år.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-10:den-kalde-krigen', 'samfunnsfag-10', 'den-kalde-krigen', 'Den kalde krigen', 'Årsakene til og forløpet av konflikten mellom USA og Sovjetunionen 1947–1991, hvordan Europa ble delt, Norges rolle, og hvordan den kalde krigen tok slutt.', array[7]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-10:den-kalde-krigen', '## En kald krig
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-10:den-kalde-krigen', 'Den kalde krigen', 'Konflikten mellom USA og Sovjetunionen fra slutten av 1940-tallet til 1991.', 0),
  ('samfunnsfag-10:den-kalde-krigen', 'Supermakt', 'Stat med så stor militær, økonomisk og politisk makt at den påvirker hele verden.', 1),
  ('samfunnsfag-10:den-kalde-krigen', 'Kapitalisme', 'Økonomisk system med privat eierskap der markedet styrer.', 2),
  ('samfunnsfag-10:den-kalde-krigen', 'Kommunisme', 'Ideologi der staten eier produksjonen og ett parti styrer.', 3),
  ('samfunnsfag-10:den-kalde-krigen', 'Jernteppet', 'Churchills bilde på grensen som delte Europa i øst og vest.', 4),
  ('samfunnsfag-10:den-kalde-krigen', 'Marshallplanen', 'Amerikansk økonomisk hjelp til gjenoppbyggingen av Vest-Europa etter krigen.', 5),
  ('samfunnsfag-10:den-kalde-krigen', 'NATO', 'Forsvarsallianse dannet i 1949 med USA i spissen. Norge var med fra start.', 6),
  ('samfunnsfag-10:den-kalde-krigen', 'Warszawapakten', 'Militærallianse fra 1955 mellom Sovjetunionen og landene i Øst-Europa.', 7),
  ('samfunnsfag-10:den-kalde-krigen', 'Berlinmuren', 'Muren som delte Berlin fra 1961 til 1989.', 8),
  ('samfunnsfag-10:den-kalde-krigen', 'Terrorbalansen', 'Begge supermaktene hadde så mange atomvåpen at en krig ville ødelegge begge.', 9),
  ('samfunnsfag-10:den-kalde-krigen', 'Stedfortrederkrig', 'Krig der supermaktene støtter hver sin side i et annet land.', 10),
  ('samfunnsfag-10:den-kalde-krigen', 'Cubakrisen', 'Krisen i 1962 der verden var nær atomkrig på grunn av sovjetiske raketter på Cuba.', 11),
  ('samfunnsfag-10:den-kalde-krigen', 'Romkappløpet', 'Konkurransen om romfart. Sputnik i 1957 og månelandingen i 1969.', 12),
  ('samfunnsfag-10:den-kalde-krigen', 'Basepolitikken', 'Norges politikk om ingen faste utenlandske baser eller atomvåpen i fredstid.', 13),
  ('samfunnsfag-10:den-kalde-krigen', 'Gorbatsjov', 'Sovjetisk leder fra 1985 som innførte reformene glasnost og perestrojka.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-10:den-kalde-krigen', 'q01', 'flervalg', 'Hvilke to supermakter sto mot hverandre under den kalde krigen?', array['USA og Sovjetunionen', 'Storbritannia og Frankrike', 'Kina og Japan', 'Tyskland og Italia']::text[], 0, 'De to supermaktene hadde svært ulike ideologier.', true, true, 0),
  ('samfunnsfag-10:den-kalde-krigen', 'q02', 'flervalg', 'Hvorfor kalles krigen «kald»?', array['Fordi den foregikk om vinteren', 'Fordi supermaktene aldri kriget direkte mot hverandre', 'Fordi den foregikk i Arktis', 'Fordi ingen døde']::text[], 1, 'Konflikten foregikk gjennom våpenkappløp, propaganda og stedfortrederkriger.', true, true, 1),
  ('samfunnsfag-10:den-kalde-krigen', 'q03', 'flervalg', 'Hva var Marshallplanen?', array['En sovjetisk militærplan', 'En plan for månelanding', 'Amerikansk økonomisk hjelp til gjenoppbyggingen av Europa', 'En fredsavtale med Japan']::text[], 2, 'Hjelpen skulle også hindre at kommunismen fikk fotfeste i Vest-Europa.', true, true, 2),
  ('samfunnsfag-10:den-kalde-krigen', 'q04', 'flervalg', 'Når ble Berlinmuren bygd?', array['1945', '1949', '1989', '1961']::text[], 3, 'Muren skulle hindre østtyskere i å flykte til Vest-Berlin.', true, true, 3),
  ('samfunnsfag-10:den-kalde-krigen', 'q05', 'flervalg', 'Hva var Cubakrisen i 1962?', array['En krise der verden var nær atomkrig på grunn av sovjetiske raketter på Cuba', 'En økonomisk krise på Cuba', 'En borgerkrig i Latin-Amerika', 'En orkan']::text[], 0, 'Krisen ble løst gjennom forhandlinger, og Sovjetunionen trakk rakettene tilbake.', true, true, 4),
  ('samfunnsfag-10:den-kalde-krigen', 'q06', 'flervalg', 'Hva er en stedfortrederkrig?', array['En krig mellom to supermakter direkte', 'En krig der supermaktene støtter hver sin side i en konflikt i et annet land', 'En handelskrig', 'En krig uten våpen']::text[], 1, 'Koreakrigen og Vietnamkrigen er eksempler.', true, true, 5),
  ('samfunnsfag-10:den-kalde-krigen', 'q07', 'flervalg', 'Hvilken militærallianse ble Norge med i i 1949?', array['Warszawapakten', 'EU', 'NATO', 'FN']::text[], 2, 'Norge var et av de tolv landene som grunnla NATO.', true, true, 6),
  ('samfunnsfag-10:den-kalde-krigen', 'q08', 'flervalg', 'Hva var terrorbalansen?', array['At begge supermaktene hadde så mange atomvåpen at en krig ville ødelegge begge', 'At ingen hadde atomvåpen', 'At terrorister styrte verden', 'At Europa var nøytralt']::text[], 0, 'Frykten for gjensidig ødeleggelse kan ha hindret en direkte krig.', true, true, 7),
  ('samfunnsfag-10:den-kalde-krigen', 'q09', 'flervalg', 'Hva skjedde 9. november 1989?', array['Sovjetunionen ble oppløst', 'Cubakrisen startet', 'NATO ble dannet', 'Berlinmuren falt']::text[], 3, 'Murens fall ble et symbol på slutten av den kalde krigen.', true, false, 8),
  ('samfunnsfag-10:den-kalde-krigen', 'q10', 'flervalg', 'Hvilken sovjetisk leder innførte reformene glasnost og perestrojka?', array['Stalin', 'Khrusjtsjov', 'Gorbatsjov', 'Putin']::text[], 2, 'Reformene ga mer åpenhet, men bidro også til at Sovjetunionen gikk i oppløsning.', true, false, 9),
  ('samfunnsfag-10:den-kalde-krigen', 'm01', 'sant-usant', 'Sovjetunionen ble oppløst i 1991.', array['Sant', 'Usant']::text[], 0, 'Sovjetunionen ble delt i 15 selvstendige stater, blant dem Russland og Ukraina.', false, true, 10),
  ('samfunnsfag-10:den-kalde-krigen', 'm02', 'sant-usant', 'Norge tillot faste utenlandske militærbaser i fredstid under den kalde krigen.', array['Sant', 'Usant']::text[], 1, 'Basepolitikken sa nei til faste utenlandske baser i fredstid.', false, true, 11),
  ('samfunnsfag-10:den-kalde-krigen', 'm03', 'sant-usant', 'Romkappløpet var en del av rivaliseringen mellom supermaktene.', array['Sant', 'Usant']::text[], 0, 'Teknologiske seire ble brukt som bevis på at eget system var best.', false, true, 12),
  ('samfunnsfag-10:den-kalde-krigen', 'm04', 'sant-usant', 'Tyskland var samlet under hele den kalde krigen.', array['Sant', 'Usant']::text[], 1, 'Tyskland var delt fra 1949 til 1990.', false, true, 13),
  ('samfunnsfag-10:den-kalde-krigen', 'm05', 'flervalg', 'Hva kalte Churchill grensen mellom øst og vest i Europa?', array['Berlinmuren', 'Jernteppet', 'Den kalde fronten', 'Østgrensen']::text[], 1, 'Uttrykket ble kjent etter en tale i 1946.', false, true, 14),
  ('samfunnsfag-10:den-kalde-krigen', 'm06', 'flervalg', 'Hvilken allianse ledet Sovjetunionen?', array['Warszawapakten', 'NATO', 'EU', 'Folkeforbundet']::text[], 0, 'Warszawapakten ble oppløst i 1991.', false, true, 15),
  ('samfunnsfag-10:den-kalde-krigen', 'm07', 'flervalg', 'Hva var en konsekvens av at den kalde krigen tok slutt?', array['Berlinmuren ble bygd', 'Europa ble delt', 'Mange land i Øst-Europa ble demokratier', 'Koreakrigen startet']::text[], 2, 'Flere av landene ble senere med i både NATO og EU.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-10:den-kalde-krigen', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-10:den-kalde-krigen', 's01', 'Sammenlign kapitalisme og kommunisme slik de ble praktisert i USA og Sovjetunionen. Ta med hvem som eide og styrte produksjonen, og hvordan økonomien ble styrt.', 'I USA var økonomien kapitalistisk: privat eierskap og markedet styrte. I Sovjetunionen eide og styrte staten produksjonen, og landet hadde planøkonomi og ettpartistyre.', array['Forklarer at kapitalisme bygger på privat eierskap og at markedet styrer.', 'Forklarer at kommunisme i Sovjetunionen innebar statlig eierskap og styring av produksjonen.']::text[], 0),
  ('samfunnsfag-10:den-kalde-krigen', 's02', 'USA og Sovjetunionen var allierte under andre verdenskrig, men ble rivaler etter krigen. Forklar to forhold som bidro til at mistilliten mellom dem vokste.', 'Landene hadde svært ulike ideologier og økonomiske systemer. Mistilliten økte også da Sovjetunionen fikk kontroll over Øst-Europa.', array['Nevner de store forskjellene mellom landenes ideologier eller politiske og økonomiske systemer.', 'Forklarer at Sovjetunionens kontroll over Øst-Europa bidro til økt mistillit.']::text[], 1),
  ('samfunnsfag-10:den-kalde-krigen', 's03', 'Hva mente Churchill med bildet «jernteppet»? Forklar hva det skilte mellom i Europa.', 'Jernteppet var et bilde på delingen av Europa i en østlig og en vestlig del. Sovjetunionen hadde kontroll over Øst-Europa, mens Vest-Europa lå på den andre siden av skillet.', array['Forklarer at jernteppet var et bilde på et skille mellom øst og vest i Europa.', 'Knytter delingen til Sovjetunionens kontroll over Øst-Europa.']::text[], 2),
  ('samfunnsfag-10:den-kalde-krigen', 's04', 'Sammenlign NATO og Warszawapakten. Hvilke land eller makter sto i spissen for hver allianse, og når ble de dannet?', 'NATO ble dannet i 1949 med USA i spissen, og Norge var med fra starten. Warszawapakten ble dannet i 1955 av Sovjetunionen og landene i Øst-Europa.', array['Plasserer NATO på USAs side og Warszawapakten på Sovjetunionens og Øst-Europas side.', 'Oppgir riktig dannelsesår for begge alliansene.']::text[], 3),
  ('samfunnsfag-10:den-kalde-krigen', 's05', 'Norge grenser til Sovjetunionen i nord. En politiker foreslår å ha faste utenlandske militærbaser og atomvåpen i Norge også i fredstid. Hvordan ville basepolitikken ha stilt seg til forslaget, og hva var målet med politikken?', 'Basepolitikken sa nei til faste utenlandske militærbaser og atomvåpen i Norge i fredstid. Målet var å redusere spenningen i nord.', array['Forklarer at basepolitikken ikke tillot faste utenlandske baser eller atomvåpen i fredstid.', 'Knytter politikken til ønsket om å redusere spenningen i nord.']::text[], 4),
  ('samfunnsfag-10:den-kalde-krigen', 's06', 'Gi ett konkret eksempel på romkappløpet, og forklar hvordan eksempelet viser konkurranse mellom supermaktene.', 'Sovjetunionen sendte opp Sputnik i 1957, mens USA senere landet på månen i 1969. Begge forsøkte å oppnå store resultater innen romfart og vise sin styrke.', array['Nevner et riktig eksempel: Sputnik i 1957 eller USAs månelanding i 1969.', 'Forklarer at eksempelet viser konkurranse mellom USA og Sovjetunionen om romfart eller teknologi.']::text[], 5),
  ('samfunnsfag-10:den-kalde-krigen', 's07', 'Begge supermaktene hadde mange atomvåpen. Forklar hvordan dette kunne hindre USA og Sovjetunionen i å gå til direkte krig mot hverandre.', 'Hvis en atomkrig brøt ut, ville begge supermaktene bli ødelagt. Frykten for dette gjorde at de kunne la være å angripe hverandre direkte.', array['Forklarer at en atomkrig ville ødelegge begge supermaktene.', 'Knytter denne faren til at begge kunne bli avskrekket fra å starte en direkte krig.']::text[], 6),
  ('samfunnsfag-10:den-kalde-krigen', 's08', 'Nevn to følger av at den kalde krigen tok slutt for landene i Øst-Europa eller for maktforholdet i verden.', 'Mange land i Øst-Europa ble demokratier, og flere ble med i NATO og EU. USA sto igjen som verdens eneste supermakt.', array['Nevner at mange land i Øst-Europa ble demokratier, eller at flere ble med i NATO eller EU.', 'Nevner at USA sto igjen som eneste supermakt.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-10:konflikter-i-var-tid', 'samfunnsfag-10', 'konflikter-i-var-tid', 'Konflikter i vår tid', 'Hvordan du analyserer en konflikt, vanlige årsaker til væpnede konflikter, eksempler fra vår tid, konsekvensene for mennesker og verden, og hvordan konflikter kan løses.', array[7]::int[], 1, 'utkast', '{}'::text[], false, now())
