  ('samfunnsfag-10:konflikter-i-var-tid', '## Hva er en konflikt?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-10:konflikter-i-var-tid', 'Konflikt', 'Uenighet mellom parter med motstridende mål eller interesser.', 0),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Borgerkrig', 'Væpnet konflikt mellom grupper inne i ett land.', 1),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Mellomstatlig krig', 'Krig mellom to eller flere stater.', 2),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Konfliktanalyse', 'Systematisk undersøkelse av årsaker, aktører, interesser, konsekvenser og løsninger.', 3),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Aktør', 'En part som deltar i eller påvirker en konflikt.', 4),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Langsiktig årsak', 'Dypere forhold som bygger opp en konflikt over tid.', 5),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Utløsende årsak', 'Hendelsen som setter i gang en konflikt.', 6),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Kolonigrenser', 'Grenser trukket av kolonimakter uten hensyn til folkegruppene.', 7),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Annektering', 'Å innlemme et område i sin egen stat, ofte med makt, som Russland gjorde med Krim i 2014.', 8),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Fullskala invasjon', 'Russlands angrep på hele Ukraina fra 24. februar 2022.', 9),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Oslo-avtalen', 'Avtale fra 1993 mellom Israel og PLO som skulle lede til fred.', 10),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Flyktning', 'Person som har flyktet fra hjemlandet på grunn av forfølgelse eller krig.', 11),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Mekling', 'En nøytral tredjepart hjelper partene å finne en løsning.', 12),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Sikkerhetsrådet', 'FNs viktigste organ for fred og sikkerhet, med 5 faste og 10 valgte medlemmer.', 13),
  ('samfunnsfag-10:konflikter-i-var-tid', 'Vetorett', 'Retten de fem faste medlemmene i Sikkerhetsrådet har til å stoppe et vedtak.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-10:konflikter-i-var-tid', 'q01', 'flervalg', 'Hva er den vanligste typen væpnet konflikt i dag?', array['Kriger mellom stormakter', 'Borgerkriger inne i ett land', 'Kriger om kolonier', 'Verdenskriger']::text[], 1, 'Mange borgerkriger får likevel innblanding fra andre land.', true, true, 0),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q02', 'flervalg', 'Hvilket spørsmål hører til en konfliktanalyse?', array['Hvem er partene, og hva vil de oppnå?', 'Hvilken farge har flaggene?', 'Hvor mange innbyggere har hovedstaden?', 'Hva heter nasjonalsangen?']::text[], 0, 'Aktører og interesser er sentrale for å forstå en konflikt.', true, true, 1),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q03', 'flervalg', 'Hvordan kan kolonitiden være en årsak til konflikter i dag?', array['Kolonimaktene bygde for mange skoler', 'Koloniene fikk for mye makt', 'Kolonimaktene trakk grenser uten hensyn til folkegruppene', 'Kolonitiden har ingen betydning']::text[], 2, 'Grupper som ble delt eller tvunget sammen, har ofte havnet i konflikt.', true, true, 2),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q04', 'flervalg', 'Når gikk Russland til fullskala invasjon av Ukraina?', array['2014', '1991', '2008', '2022']::text[], 3, 'Invasjonen startet 24. februar 2022, åtte år etter annekteringen av Krim.', true, true, 3),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q05', 'flervalg', 'Hva er mekling?', array['At en nøytral tredjepart hjelper partene å finne en løsning', 'At én part vinner krigen', 'At FN sender soldater', 'At et land innfører sanksjoner']::text[], 0, 'Norge har ofte hatt rollen som mekler.', true, true, 4),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q06', 'flervalg', 'Hva var Oslo-avtalen fra 1993?', array['En handelsavtale mellom Norge og EU', 'En avtale mellom Israel og PLO som skulle føre til fred', 'En avtale om NATO-medlemskap', 'En klimaavtale']::text[], 1, 'Avtalen ga palestinerne begrenset selvstyre, men den endelige fredsavtalen kom aldri.', true, true, 5),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q07', 'flervalg', 'Hvorfor er det ofte vanskelig for FNs sikkerhetsråd å gripe inn?', array['Fordi FN ikke har penger', 'Fordi Sikkerhetsrådet bare møtes hvert tiende år', 'Fordi Norge har vetorett', 'Fordi de fem faste medlemmene har vetorett']::text[], 3, 'USA, Russland, Kina, Storbritannia og Frankrike kan hver for seg stoppe et vedtak.', true, true, 6),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q08', 'flervalg', 'Hvordan kan en krig i ett land påvirke resten av verden?', array['Den kan gi høyere mat- og energipriser og flere flyktninger', 'Den påvirker aldri andre land', 'Den gjør alt billigere', 'Den gir mindre spenning mellom stormakter']::text[], 0, 'Krigen i Ukraina ga for eksempel høyere priser på korn og energi i mange land.', true, true, 7),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q09', 'flervalg', 'Hva er en utløsende årsak?', array['Den dypeste grunnen til en konflikt', 'Konsekvensen av en krig', 'Hendelsen som setter i gang en konflikt', 'En fredsavtale']::text[], 2, 'Utløsende årsaker virker sammen med langsiktige årsaker.', true, false, 8),
  ('samfunnsfag-10:konflikter-i-var-tid', 'q10', 'flervalg', 'Hvordan kan klimaendringer bidra til konflikter?', array['Ved å gi mer regn overalt', 'Ved å forsterke kampen om vann og dyrkbar jord', 'Ved å stoppe all krig', 'Klima har ingen betydning']::text[], 1, 'Tørke og knapphet kan skape spenninger mellom grupper.', true, false, 9),
  ('samfunnsfag-10:konflikter-i-var-tid', 'm01', 'sant-usant', 'Alle konflikter blir voldelige.', array['Sant', 'Usant']::text[], 1, 'De fleste konflikter løses uten vold, for eksempel gjennom forhandlinger.', false, true, 10),
  ('samfunnsfag-10:konflikter-i-var-tid', 'm02', 'sant-usant', 'Russland annekterte Krim i 2014.', array['Sant', 'Usant']::text[], 0, 'Annekteringen ble ikke anerkjent av de fleste land i verden.', false, true, 11),
  ('samfunnsfag-10:konflikter-i-var-tid', 'm03', 'sant-usant', 'Norge har vært mekler i fredsprosesser i andre land.', array['Sant', 'Usant']::text[], 0, 'Blant annet i Colombia, Sri Lanka og mellom Israel og palestinerne.', false, true, 12),
  ('samfunnsfag-10:konflikter-i-var-tid', 'm04', 'sant-usant', 'Konflikter har som regel bare én årsak.', array['Sant', 'Usant']::text[], 1, 'Som regel virker flere årsaker sammen.', false, true, 13),
  ('samfunnsfag-10:konflikter-i-var-tid', 'm05', 'flervalg', 'Hvem har vetorett i FNs sikkerhetsråd?', array['Alle FNs medlemsland', 'Bare USA', 'De fem faste medlemmene', 'Generalsekretæren']::text[], 2, 'USA, Russland, Kina, Storbritannia og Frankrike.', false, true, 14),
  ('samfunnsfag-10:konflikter-i-var-tid', 'm06', 'flervalg', 'Hva betyr å annektere et område?', array['Å innlemme et område i sin egen stat, ofte med makt', 'Å gi et område selvstendighet', 'Å handle med et område', 'Å sende nødhjelp til et område']::text[], 0, 'Annektering med makt er i strid med folkeretten.', false, true, 15),
  ('samfunnsfag-10:konflikter-i-var-tid', 'm07', 'flervalg', 'Hvilken konflikt startet med at regimet slo ned på fredelige protester i 2011?', array['Koreakrigen', 'Borgerkrigen i Syria', 'Krigen i Ukraina', 'Vietnamkrigen']::text[], 1, 'Protestene var en del av den arabiske våren.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-10:konflikter-i-var-tid', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-10:konflikter-i-var-tid', 's01', 'Hva gjør en uenighet til en konflikt, og hvorfor fører ikke alle konflikter til krig?', 'En konflikt er en uenighet der partene har mål eller interesser som står mot hverandre. Konflikten blir ikke nødvendigvis voldelig, og derfor fører ikke alle konflikter til krig.', array['Forklarer at partene har motstridende mål eller interesser.', 'Skiller mellom konflikt og vold eller krig.']::text[], 0),
  ('samfunnsfag-10:konflikter-i-var-tid', 's02', 'Forklar forskjellen mellom en borgerkrig og en mellomstatlig krig.', 'En borgerkrig er en væpnet konflikt mellom grupper inne i ett land. En mellomstatlig krig er en krig mellom to eller flere stater.', array['Plasserer borgerkrig mellom grupper i ett land.', 'Forklarer at mellomstatlig krig er mellom stater.']::text[], 1),
  ('samfunnsfag-10:konflikter-i-var-tid', 's03', 'Hvordan kan fattigdom og ulikhet gjøre det lettere for væpnede grupper å få nye medlemmer?', 'Fattigdom og ulikhet kan gjøre folk mer utsatt for å bli rekruttert til væpnede grupper. Slike forhold kan derfor bidra til at en konflikt vokser.', array['Knytter fattigdom eller ulikhet til at det blir lettere å rekruttere til væpnede grupper.']::text[], 2),
  ('samfunnsfag-10:konflikter-i-var-tid', 's04', 'Russland innlemmet Krim i sin egen stat i 2014. Forklar hvorfor dette kalles annektering.', 'Annektering betyr å innlemme et område i sin egen stat, ofte med makt. Russlands handling på Krim i 2014 er et eksempel på dette.', array['Forklarer at annektering er å innlemme et område i sin egen stat.', 'Knytter forklaringen til Russlands handling på Krim.']::text[], 3),
  ('samfunnsfag-10:konflikter-i-var-tid', 's05', 'I et land konkurrerer grupper om vann og jord, og klimaendringer gjør ressursene knappere. Forklar hvordan klimaendringene kan forsterke konflikten, og hva slags årsak kampen om vann og jord er.', 'Når vann og jord blir knappere, kan konkurransen om disse ressursene bli sterkere og forsterke konflikten. Kampen om vann og jord er en kamp om ressurser.', array['Forklarer at mindre tilgang på vann eller jord kan øke konkurransen mellom gruppene.', 'Identifiserer kampen som en konflikt om ressurser.']::text[], 4),
  ('samfunnsfag-10:konflikter-i-var-tid', 's06', 'En stat støtter en væpnet gruppe i en konflikt, men deltar ikke selv i kampene. Forklar hvorfor staten likevel kan regnes som en aktør.', 'En aktør er en part som deltar i eller påvirker en konflikt. Staten kan derfor regnes som en aktør fordi støtten dens påvirker konflikten.', array['Forklarer at en aktør kan påvirke en konflikt uten å delta direkte i kampene.']::text[], 5),
  ('samfunnsfag-10:konflikter-i-var-tid', 's07', 'En person flykter fra hjemlandet sitt på grunn av krig. Forklar hvorfor personen kan kalles flyktning.', 'En flyktning er en person som har flyktet fra hjemlandet sitt på grunn av forfølgelse eller krig. Personen i situasjonen kan derfor kalles flyktning.', array['Knytter begrepet flyktning til at personen har forlatt hjemlandet på grunn av krig eller forfølgelse.']::text[], 6),
  ('samfunnsfag-10:konflikter-i-var-tid', 's08', 'Når vi undersøker om en konflikt kunne vært hindret, kan vi spørre hva som ville skjedd hvis forutsetningene hadde vært annerledes. Hva kan slike spørsmål hjelpe oss med, og hvorfor gir de ikke et sikkert svar?', 'Slike spørsmål kan hjelpe oss å forstå hvilke forhold som bidro til konflikten og om andre forutsetninger kunne ha forebygget vold. De gir ikke et sikkert svar fordi vi ikke kan vite sikkert hva som ville skjedd.', array['Forklarer at spørsmålene kan gi bedre forståelse av årsakene eller mulige måter å forebygge konflikt på.', 'Får fram at man ikke kan vite sikkert hva som ville skjedd under andre forutsetninger.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-10:terror-og-ekstremisme', 'samfunnsfag-10', 'terror-og-ekstremisme', 'Terror og ekstremisme', 'Hva terror, ekstremisme og radikalisering er, eksempler på terrorangrep, årsaker og konsekvenser, og hvordan ekstreme holdninger og handlinger kan forebygges.', array[8]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-10:terror-og-ekstremisme', '## Hva er terror?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-10:terror-og-ekstremisme', 'Terror', 'Vold eller trusler mot sivile for å skape frykt og oppnå politiske, religiøse eller ideologiske mål.', 0),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Ekstremisme', 'Holdninger som godtar bruk av vold for å nå et mål.', 1),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Radikalisering', 'Prosessen der en person gradvis får ekstreme holdninger.', 2),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Høyreekstremisme', 'Ekstremisme preget av rasisme og fremmedfiendtlighet.', 3),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Islamistisk ekstremisme', 'Voldelig ekstremisme som vil innføre en bestemt tolkning av islam, for eksempel al-Qaida og IS.', 4),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Venstreekstremisme', 'Voldelig ekstremisme rettet mot kapitalisme og det man ser som undertrykkende stater.', 5),
  ('samfunnsfag-10:terror-og-ekstremisme', '11. september 2001', 'Al-Qaidas angrep i USA der nesten 3000 mennesker ble drept.', 6),
  ('samfunnsfag-10:terror-og-ekstremisme', '22. juli 2011', 'Høyreekstreme terrorangrep mot Regjeringskvartalet og Utøya. 77 ble drept.', 7),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Konspirasjonsteori', 'Forestilling om at hemmelige grupper i skjul styrer hendelser, uten godt bevis.', 8),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Utenforskap', 'Å føle seg utenfor fellesskapet, for eksempel i skole, arbeid eller vennegjeng.', 9),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Ekkokammer', 'Miljø der man mest møter meninger som bekrefter ens egne.', 10),
  ('samfunnsfag-10:terror-og-ekstremisme', 'PST', 'Politiets sikkerhetstjeneste, som blant annet skal avdekke og forebygge terror.', 11),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Propaganda', 'Ensidig informasjon som skal påvirke holdninger og handlinger.', 12),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Sikkerhet mot frihet', 'Avveiningen mellom å beskytte samfunnet og å bevare personvern og frihet.', 13),
  ('samfunnsfag-10:terror-og-ekstremisme', 'Forebygging', 'Tiltak som hindrer at noen blir radikalisert eller utfører vold.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-10:terror-og-ekstremisme', 'q01', 'flervalg', 'Hva er terror?', array['Vold eller trusler mot sivile for å skape frykt og oppnå politiske mål', 'All kriminalitet', 'Krig mellom to land', 'En demonstrasjon']::text[], 0, 'Terror retter seg mot sivile og skal påvirke mange flere enn dem som rammes.', true, true, 0),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q02', 'flervalg', 'Når blir radikale meninger til ekstremisme?', array['Når man er uenig med regjeringen', 'Når man godtar bruk av vold for å nå målet', 'Når man skriver leserinnlegg', 'Når man demonstrerer']::text[], 1, 'Radikale meninger er lov i et demokrati, men ikke å bruke vold.', true, true, 1),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q03', 'flervalg', 'Hvor mange ble drept i terrorangrepene 22. juli 2011?', array['12', '35', '77', '3000']::text[], 2, 'Åtte ble drept i Regjeringskvartalet og 69 på Utøya.', true, true, 2),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q04', 'flervalg', 'Hva er radikalisering?', array['Å bli medlem av et parti', 'Å endre mening etter en debatt', 'Å flytte til et annet land', 'Prosessen der en person gradvis får ekstreme holdninger']::text[], 3, 'Radikalisering skjer som regel over tid og har flere årsaker.', true, true, 3),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q05', 'flervalg', 'Hvordan kan internett bidra til radikalisering?', array['Algoritmer og ekkokamre kan forsterke ekstreme budskap', 'Internett gjør alle mer tolerante', 'Internett stopper all propaganda', 'Det kan det ikke']::text[], 0, 'Ekstreme miljøer på nett kan gi fellesskap og normalisere voldelige ideer.', true, true, 4),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q06', 'flervalg', 'Hva skjedde 11. september 2001?', array['Berlinmuren falt', 'Al-Qaida kapret fly og angrep mål i USA', 'Terrorangrepet på Utøya', 'Terrorangrepet under Pride i Oslo']::text[], 1, 'Angrepene fikk store følger for internasjonal politikk.', true, true, 5),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q07', 'flervalg', 'Hvilken avveining må samfunnet gjøre etter terrorangrep?', array['Mellom sport og kultur', 'Mellom skatt og lønn', 'Mellom by og land', 'Mellom sikkerhet og frihet og personvern']::text[], 3, 'Mer overvåking kan gi tryggere samfunn, men også begrense friheten.', true, true, 6),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q08', 'flervalg', 'Hva er et tiltak for å forebygge ekstremisme?', array['Å utestenge dem som er annerledes', 'Inkludering og gode fellesskap', 'Å spre konspirasjonsteorier', 'Å unngå å snakke om vanskelige temaer']::text[], 1, 'Tilhørighet gjør det mindre fristende å søke fellesskap i ekstreme miljøer.', true, true, 7),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q09', 'flervalg', 'Hva bør du gjøre hvis en venn begynner å uttrykke støtte til vold?', array['Ignorere det', 'Le av det', 'Si ifra og snakke med en voksen du stoler på', 'Dele innleggene videre']::text[], 2, 'Tidlig hjelp kan hindre at noen blir radikalisert.', true, false, 8),
  ('samfunnsfag-10:terror-og-ekstremisme', 'q10', 'flervalg', 'Hvilken etat har et særlig ansvar for å avdekke terrorplaner i Norge?', array['NAV', 'Datatilsynet', 'Skatteetaten', 'PST']::text[], 3, 'Politiets sikkerhetstjeneste jobber med å forebygge og avdekke terror.', true, false, 9),
  ('samfunnsfag-10:terror-og-ekstremisme', 'm01', 'sant-usant', 'Det er lov å ha radikale meninger i et demokrati.', array['Sant', 'Usant']::text[], 0, 'Grensen går ved vold, trusler og hatefulle ytringer.', false, true, 10),
  ('samfunnsfag-10:terror-og-ekstremisme', 'm02', 'sant-usant', 'Terror utføres bare av én bestemt religiøs gruppe.', array['Sant', 'Usant']::text[], 1, 'Terror har blitt utført av mange ulike grupper og ideologier.', false, true, 11),
  ('samfunnsfag-10:terror-og-ekstremisme', 'm03', 'sant-usant', 'Etter 22. juli samlet mange seg i rosetog for å vise samhold.', array['Sant', 'Usant']::text[], 0, 'Rosetogene ble et symbol på svaret mot terroren.', false, true, 12),
  ('samfunnsfag-10:terror-og-ekstremisme', 'm04', 'sant-usant', 'Mer overvåking har aldri noen ulemper.', array['Sant', 'Usant']::text[], 1, 'Overvåking kan gå ut over personvernet og friheten til alle.', false, true, 13),
  ('samfunnsfag-10:terror-og-ekstremisme', 'm05', 'flervalg', 'Hva er en konspirasjonsteori?', array['En vitenskapelig bevist teori', 'En forestilling om at hemmelige grupper i skjul styrer hendelser, uten godt bevis', 'En type nyhetsartikkel', 'En lov']::text[], 1, 'Konspirasjonsteorier brukes ofte til å skape fiendebilder.', false, true, 14),
  ('samfunnsfag-10:terror-og-ekstremisme', 'm06', 'flervalg', 'Hva er utenforskap?', array['Å føle seg utenfor fellesskapet', 'Å bo i utlandet', 'Å være på ferie', 'Å være medlem i mange klubber']::text[], 0, 'Utenforskap kan gjøre noen mer sårbare for ekstreme miljøer.', false, true, 15),
  ('samfunnsfag-10:terror-og-ekstremisme', 'm07', 'flervalg', 'Hvor skjedde terrorangrepet mot to moskeer i 2019, der 51 ble drept?', array['Oslo', 'Paris', 'Christchurch', 'London']::text[], 2, 'Angrepet i Christchurch på New Zealand ble utført av en høyreekstremist.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-10:terror-og-ekstremisme', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-10:terror-og-ekstremisme', 's01', 'En gruppe bruker vold for å få et område løsrevet fra landet og gjort til en egen stat. Hvilken form for terror er dette, og hva er målet med den?', 'Dette er separatistisk terror. Målet er å skille ut et område og gjøre det til en egen stat.', array['Identifiserer det som separatistisk terror.', 'Forklarer at målet er å skille ut et område som egen stat.']::text[], 0),
  ('samfunnsfag-10:terror-og-ekstremisme', 's02', 'Sammenlign høyreekstremisme og islamistisk ekstremisme. Hva kjennetegner hver av disse formene?', 'Høyreekstremisme er ofte preget av rasisme, fremmedfiendtlighet og en idé om at eget folk er truet. Islamistisk ekstremisme bruker vold for å innføre en bestemt tolkning av islam.', array['Knytter høyreekstremisme til rasisme eller fremmedfiendtlighet.', 'Forklarer at islamistisk ekstremisme vil innføre en bestemt tolkning av islam med vold.']::text[], 1),
  ('samfunnsfag-10:terror-og-ekstremisme', 's03', 'Hvorfor ønsker terrorister ofte at en voldshandling skal få stor oppmerksomhet, også blant mennesker som ikke blir direkte rammet?', 'Terrorister vil skape frykt og påvirke flere enn dem som rammes direkte. Stor oppmerksomhet kan bidra til at handlingen påvirker samfunnet og støtter terroristens mål.', array['Forklarer at terrorister ønsker å skape frykt eller påvirke flere enn de direkte rammede.', 'Knytter oppmerksomheten til terroristenes mål.']::text[], 2),
  ('samfunnsfag-10:terror-og-ekstremisme', 's04', 'En person følger nettmiljøer der innleggene stort sett bekrefter meningene personen allerede har. Hva kalles et slikt miljø, og hvordan kan det påvirke personen?', 'Et slikt miljø kalles et ekkokammer. Personen møter mest meninger som bekrefter egne, og budskap kan derfor bli forsterket.', array['Identifiserer miljøet som et ekkokammer.', 'Forklarer at ensidige, bekreftende meninger kan forsterke budskap eller holdninger.']::text[], 3),
  ('samfunnsfag-10:terror-og-ekstremisme', 's05', 'Forklar forskjellen mellom propaganda og en konspirasjonsteori.', 'Propaganda er ensidig informasjon som skal påvirke holdninger og handlinger. En konspirasjonsteori er en forestilling om at hemmelige grupper styrer hendelser i skjul, uten godt bevis.', array['Forklarer at propaganda er ensidig informasjon ment å påvirke.', 'Forklarer at en konspirasjonsteori handler om hemmelig styring uten godt bevis.']::text[], 4),
  ('samfunnsfag-10:terror-og-ekstremisme', 's06', 'Hvordan kan utenforskap og et ønske om identitet eller fellesskap gjøre en person mer sårbar for radikalisering?', 'En person som føler seg utenfor, kan søke etter mening og et fellesskap. Kontakt med ekstreme miljøer kan da bidra til at personen gradvis får ekstreme holdninger.', array['Knytter utenforskap til søken etter mening, identitet eller fellesskap.', 'Forklarer at kontakt med ekstreme miljøer kan bidra til at holdningene utvikler seg i ekstrem retning.']::text[], 5),
  ('samfunnsfag-10:terror-og-ekstremisme', 's07', 'Terror kan ramme mennesker som ikke er fysisk skadet i selve angrepet. Nevn og forklar to mulige følger for dem eller samfunnet rundt.', 'Overlevende og pårørende kan få traumer, og terror kan skape frykt og mistillit i samfunnet. Den kan også føre til at hele grupper blir mistenkeliggjort.', array['Nevner og forklarer to følger, for eksempel traumer, frykt, mistillit eller mistenkeliggjøring av grupper.']::text[], 6),
  ('samfunnsfag-10:terror-og-ekstremisme', 's08', 'Etter terrorangrepene 22. juli samlet mange seg i rosetog. Hva viste denne reaksjonen om hvordan mennesker kan møte terror?', 'Rosetogene viste samhold og støtte til demokratiet. Mennesker møtte terroren ved å stå sammen i stedet for å la frykten splitte samfunnet.', array['Forklarer at rosetogene viste samhold.', 'Knytter reaksjonen til støtte for demokratiet eller motstand mot at terroren skulle splitte samfunnet.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-10:berekraftig-utvikling', 'samfunnsfag-10', 'berekraftig-utvikling', 'Bærekraftig utvikling', 'Hva bærekraftig utvikling betyr, hvordan den miljømessige, økonomiske og sosiale dimensjonen påvirker hverandre, og hvilke tiltak som kan gi mer bærekraftige samfunn.', array[11]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-10:berekraftig-utvikling', '## Hva er bærekraftig utvikling?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-10:berekraftig-utvikling', 'Bærekraftig utvikling', 'Utvikling som dekker dagens behov uten å ødelegge mulighetene for kommende generasjoner.', 0),
  ('samfunnsfag-10:berekraftig-utvikling', 'Brundtland-kommisjonen', 'FN-kommisjon som i 1987 la fram rapporten «Vår felles framtid».', 1),
  ('samfunnsfag-10:berekraftig-utvikling', 'Miljømessig dimensjon', 'At naturen tåler det vi gjør: klima, naturmangfold, rent vann og ren luft.', 2),
  ('samfunnsfag-10:berekraftig-utvikling', 'Økonomisk dimensjon', 'En økonomi som gir arbeid, inntekt og velferd over tid uten rovdrift.', 3),
  ('samfunnsfag-10:berekraftig-utvikling', 'Sosial dimensjon', 'Rettferdig fordeling og tilgang til mat, helse, utdanning og trygghet.', 4),
  ('samfunnsfag-10:berekraftig-utvikling', 'FNs bærekraftsmål', '17 mål vedtatt i 2015 som skal nås innen 2030.', 5),
  ('samfunnsfag-10:berekraftig-utvikling', 'Parisavtalen', 'Klimaavtale fra 2015: oppvarmingen skal holdes godt under 2 °C, helst 1,5 °C.', 6),
  ('samfunnsfag-10:berekraftig-utvikling', 'Naturmangfold', 'Variasjonen av arter, gener og økosystemer.', 7),
  ('samfunnsfag-10:berekraftig-utvikling', 'Fornybar energi', 'Energi fra kilder som ikke tar slutt, som vann, vind og sol.', 8),
  ('samfunnsfag-10:berekraftig-utvikling', 'Rovdrift', 'At ressurser brukes raskere enn de fornyes.', 9),
  ('samfunnsfag-10:berekraftig-utvikling', 'Sirkulær økonomi', 'Ressursene holdes i kretsløp gjennom gjenbruk og resirkulering.', 10),
  ('samfunnsfag-10:berekraftig-utvikling', 'Klimagass', 'Gass som forsterker drivhuseffekten, som CO₂ og metan.', 11),
  ('samfunnsfag-10:berekraftig-utvikling', 'Avgift', 'Et virkemiddel staten kan bruke for å gjøre miljøskadelige varer dyrere.', 12),
  ('samfunnsfag-10:berekraftig-utvikling', 'Dilemma', 'Et valg mellom to hensyn som begge er viktige.', 13),
  ('samfunnsfag-10:berekraftig-utvikling', 'Kommende generasjoner', 'De som skal leve etter oss, og som bærekraft skal ta hensyn til.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-10:berekraftig-utvikling', 'q01', 'flervalg', 'Hvem la fram definisjonen av bærekraftig utvikling i 1987?', array['FNs sikkerhetsråd', 'Brundtland-kommisjonen', 'EU', 'NATO']::text[], 1, 'Kommisjonen ble ledet av Gro Harlem Brundtland.', true, true, 0),
  ('samfunnsfag-10:berekraftig-utvikling', 'q02', 'flervalg', 'Hvilke tre dimensjoner har bærekraftig utvikling?', array['Miljømessig, økonomisk og sosial', 'Politisk, militær og religiøs', 'Lokal, nasjonal og global', 'Fortid, nåtid og framtid']::text[], 0, 'Alle tre må ivaretas for at utviklingen skal være bærekraftig.', true, true, 1),
  ('samfunnsfag-10:berekraftig-utvikling', 'q03', 'flervalg', 'Hvor mange bærekraftsmål vedtok FN i 2015?', array['5', '10', '17', '30']::text[], 2, 'Målene gjelder alle land og skal etter planen nås innen 2030.', true, true, 2),
  ('samfunnsfag-10:berekraftig-utvikling', 'q04', 'flervalg', 'Hva er målet i Parisavtalen?', array['Å stoppe all bilkjøring', 'Å øke oljeproduksjonen', 'At alle land skal bli med i EU', 'Å begrense oppvarmingen til godt under 2 °C, helst 1,5 °C']::text[], 3, 'Landene skal kutte klimagassutslipp for å nå målet.', true, true, 3),
  ('samfunnsfag-10:berekraftig-utvikling', 'q05', 'flervalg', 'Hvordan kan fattigdom påvirke miljøet?', array['Fattige mennesker kan bli tvunget til å hogge skog for å overleve', 'Fattigdom gir alltid renere natur', 'Fattigdom har ingen sammenheng med miljø', 'Fattigdom gir mindre avfall overalt']::text[], 0, 'Her påvirker den sosiale dimensjonen den miljømessige.', true, true, 4),
  ('samfunnsfag-10:berekraftig-utvikling', 'q06', 'flervalg', 'Hva er sirkulær økonomi?', array['At pengene går i ring mellom bankene', 'At ressursene holdes i kretsløp gjennom gjenbruk og resirkulering', 'At alle varer lages av plast', 'At man bare handler lokalt']::text[], 1, 'Målet er at minst mulig blir til avfall.', true, true, 5),
  ('samfunnsfag-10:berekraftig-utvikling', 'q07', 'flervalg', 'Hvilket tiltak kan en kommune gjøre for mer bærekraft?', array['Legge ned bussrutene', 'Bygge flere motorveier inn til sentrum', 'Øke antall parkeringsplasser', 'Satse på kollektivtransport og sykkelveier']::text[], 3, 'Det gjør det lettere for innbyggerne å reise uten bil.', true, true, 6),
  ('samfunnsfag-10:berekraftig-utvikling', 'q08', 'flervalg', 'Hvorfor kan det å avvikle oljeindustrien være et dilemma?', array['Fordi det gir mer utslipp', 'Fordi det kan redusere utslipp, men gi tap av arbeidsplasser og inntekter', 'Fordi olje er fornybar', 'Det er ikke noe dilemma']::text[], 1, 'Miljøhensyn og økonomiske hensyn trekker i hver sin retning.', true, true, 7),
  ('samfunnsfag-10:berekraftig-utvikling', 'q09', 'flervalg', 'Hva betyr det at klimaendringer har en sosial dimensjon?', array['At de ofte rammer de fattigste hardest', 'At de bare påvirker naturen', 'At de er gode for økonomien', 'At de bare skjer i rike land']::text[], 0, 'De fattigste har minst ressurser til å tilpasse seg tørke og flom.', true, false, 8),
  ('samfunnsfag-10:berekraftig-utvikling', 'q10', 'flervalg', 'Hva kan du som enkeltperson gjøre for mer bærekraft?', array['Kjøpe mer og kaste oftere', 'Kjøre bil korte strekninger', 'Reparere, gjenbruke og reise kollektivt', 'Kaste avfall usortert']::text[], 2, 'Mange små valg til sammen kan utgjøre en forskjell.', true, false, 9),
  ('samfunnsfag-10:berekraftig-utvikling', 'm01', 'sant-usant', 'Bærekraftig utvikling handler bare om miljø.', array['Sant', 'Usant']::text[], 1, 'Den handler også om økonomi og sosiale forhold.', false, true, 10),
  ('samfunnsfag-10:berekraftig-utvikling', 'm02', 'sant-usant', 'FNs bærekraftsmål skal etter planen nås innen 2030.', array['Sant', 'Usant']::text[], 0, 'Målene ble vedtatt i 2015 med en frist på 15 år.', false, true, 11),
  ('samfunnsfag-10:berekraftig-utvikling', 'm03', 'sant-usant', 'De aller fleste nye personbiler som selges i Norge, er elbiler.', array['Sant', 'Usant']::text[], 0, 'Avgiftsfordeler har gjort elbiler svært populære i Norge.', false, true, 12),
  ('samfunnsfag-10:berekraftig-utvikling', 'm04', 'sant-usant', 'Miljøtiltak kan aldri komme i konflikt med økonomiske hensyn.', array['Sant', 'Usant']::text[], 1, 'Tiltak for miljøet kan for eksempel koste arbeidsplasser eller penger.', false, true, 13),
  ('samfunnsfag-10:berekraftig-utvikling', 'm05', 'flervalg', 'Hva er fornybar energi?', array['Energi fra kilder som ikke tar slutt, som vann, vind og sol', 'Energi fra kull og olje', 'Energi som bare kan brukes én gang', 'Energi fra naturgass']::text[], 0, 'Fornybar energi gir lite klimagassutslipp i bruk.', false, true, 14),
  ('samfunnsfag-10:berekraftig-utvikling', 'm06', 'flervalg', 'Hva betyr rovdrift?', array['At man sparer ressurser', 'At man planter trær', 'At ressurser brukes raskere enn de fornyes', 'At man resirkulerer']::text[], 2, 'Overfiske er et eksempel på rovdrift.', false, true, 15),
  ('samfunnsfag-10:berekraftig-utvikling', 'm07', 'flervalg', 'Hva handler den sosiale dimensjonen om?', array['Bare om sosiale medier', 'Rettferdig fordeling, helse, utdanning og trygghet', 'Bare om økonomisk vekst', 'Bare om dyreliv']::text[], 1, 'Et bærekraftig samfunn må være rettferdig for alle.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-10:berekraftig-utvikling', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-10:berekraftig-utvikling', 's01', 'Forklar hva bærekraftig utvikling betyr, og hvorfor definisjonen også tar hensyn til kommende generasjoner.', 'Bærekraftig utvikling dekker behovene vi har i dag uten å ødelegge mulighetene for at kommende generasjoner får dekket sine behov. Vi må derfor unngå å bruke opp jordas ressurser eller skade naturen så mye at de som kommer etter oss får det vanskeligere.', array['Forklarer at dagens behov skal dekkes.', 'Forklarer at framtidige generasjoners muligheter ikke skal ødelegges.']::text[], 0),
  ('samfunnsfag-10:berekraftig-utvikling', 's02', 'Naturmangfold handler om variasjon i naturen. Forklar hva denne variasjonen omfatter.', 'Naturmangfold er variasjon av arter, gener og økosystemer. Det handler altså både om ulike levende arter og variasjon innen arter og naturmiljøer.', array['Får fram at begrepet handler om variasjon i naturen.', 'Nevner minst to av nivåene arter, gener og økosystemer.']::text[], 1),
  ('samfunnsfag-10:berekraftig-utvikling', 's03', 'FN vedtok 17 bærekraftsmål i 2015, som skal nås innen 2030. Parisavtalen ble også vedtatt i 2015 og handler om global oppvarming. Sammenlign hva disse to internasjonale tiltakene retter seg mot.', 'Bærekraftsmålene dekker mange temaer, blant annet fattigdom, helse, utdanning og natur. Parisavtalen retter seg spesielt mot klima og skal begrense den globale oppvarmingen til godt under 2 °C, helst 1,5 °C.', array['Forklarer at bærekraftsmålene dekker flere samfunns- og miljøtemaer.', 'Forklarer at Parisavtalen er rettet mot å begrense global oppvarming.']::text[], 2),
  ('samfunnsfag-10:berekraftig-utvikling', 's04', 'Et selskap gir folk arbeid og inntekt over tid, men bruker naturressurser raskere enn de fornyes. Forklar hvordan dette både støtter og utfordrer økonomisk bærekraft.', 'Arbeid og inntekt over tid støtter den økonomiske dimensjonen. Men når ressursene brukes raskere enn de fornyes, er det rovdrift, og økonomien bygger da ikke på en bærekraftig bruk av ressursene.', array['Knytter arbeid og inntekt over tid til økonomisk bærekraft.', 'Forklarer at ressursbruk raskere enn fornyelse er rovdrift og ikke bærekraftig.']::text[], 3),
  ('samfunnsfag-10:berekraftig-utvikling', 's05', 'Staten vil bruke en avgift på en miljøskadelig vare. Forklar hvordan avgiften kan brukes som et virkemiddel for mer bærekraftig utvikling.', 'Avgiften kan gjøre den miljøskadelige varen dyrere. Staten kan bruke dette som et virkemiddel for å påvirke hva som kjøpes.', array['Forklarer at avgiften kan gjøre varen dyrere.', 'Knytter prisendringen til avgiften som et virkemiddel staten kan bruke.']::text[], 4),
  ('samfunnsfag-10:berekraftig-utvikling', 's06', 'En skole har pulter som fortsatt kan brukes, noen som trenger reparasjon, og deler fra ødelagte pulter som kan resirkuleres. Beskriv en løsning som følger prinsippet om sirkulær økonomi, og forklar hvorfor.', 'Skolen kan beholde pultene som fortsatt virker, reparere dem som trenger det og resirkulere brukbare deler fra de ødelagte. Da holdes ressursene i kretsløp i stedet for at alt blir avfall.', array['Foreslår gjenbruk eller reparasjon av pulter som fortsatt kan brukes.', 'Forklarer at ressurser holdes i kretsløp og ikke bare blir avfall.']::text[], 5),
  ('samfunnsfag-10:berekraftig-utvikling', 's07', 'Et tiltak skal gi flere mennesker tilgang til utdanning, men krever at naturressurser brukes raskere enn de fornyes. Forklar hvilke bærekraftsdimensjoner som berøres, og hva som må vurderes før tiltaket velges.', 'Bedre tilgang til utdanning berører den sosiale dimensjonen. Ressursbruken berører den miljømessige dimensjonen og kan være rovdrift, så tiltaket må vurderes ut fra alle tre dimensjonene før det velges.', array['Knytter tilgang til utdanning til den sosiale dimensjonen.', 'Knytter ressursbruk raskere enn fornyelse til miljømessig bærekraft eller rovdrift.', 'Får fram at tiltaket bør vurderes ut fra alle tre dimensjonene.']::text[], 6),
  ('samfunnsfag-10:berekraftig-utvikling', 's08', 'Vann, vind og sol er energikilder som ikke tar slutt. Forklar hvorfor de regnes som fornybar energi, og hvordan dette skiller seg fra rovdrift.', 'Vann, vind og sol regnes som fornybar energi fordi kildene ikke tar slutt. Rovdrift er derimot å bruke ressurser raskere enn de fornyes.', array['Forklarer at fornybare energikilder ikke tar slutt.', 'Forklarer at rovdrift betyr å bruke ressurser raskere enn de fornyes.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-10:velferdsstaten', 'samfunnsfag-10', 'velferdsstaten', 'Velferdsstaten og det politiske systemet', 'Kjennetegn ved den norske velferdsstaten og den nordiske modellen, hvem som har ansvar for hva, hvordan velferden finansieres, og hvilke utfordringer den står overfor.', array[19]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-10:velferdsstaten', '## Hva er en velferdsstat?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-10:velferdsstaten', 'Velferdsstat', 'Samfunn der staten tar stort ansvar for innbyggernes trygghet, helse og utdanning.', 0),
  ('samfunnsfag-10:velferdsstaten', 'Folketrygden', 'Innført i 1967. Gir blant annet pensjon, sykepenger og uføretrygd.', 1),
  ('samfunnsfag-10:velferdsstaten', 'Den nordiske modellen', 'Universelle ordninger, høy skatt, trepartssamarbeid, høy tillit og små forskjeller.', 2),
  ('samfunnsfag-10:velferdsstaten', 'Universell ordning', 'Velferdsordning som gjelder alle, uansett inntekt.', 3),
  ('samfunnsfag-10:velferdsstaten', 'Trepartssamarbeid', 'Samarbeid mellom staten, arbeidsgiverne og arbeidstakerne.', 4),
  ('samfunnsfag-10:velferdsstaten', 'Egenandel', 'Den delen av prisen du selv betaler for en offentlig tjeneste.', 5),
  ('samfunnsfag-10:velferdsstaten', 'Barnetrygd', 'Månedlig støtte til alle som har barn under 18 år.', 6),
  ('samfunnsfag-10:velferdsstaten', 'Dagpenger', 'Økonomisk støtte når du er arbeidsløs.', 7),
  ('samfunnsfag-10:velferdsstaten', 'Sykepenger', 'Erstatter lønnen når du er syk og ikke kan jobbe.', 8),
  ('samfunnsfag-10:velferdsstaten', 'NAV', 'Arbeids- og velferdsforvaltningen, som forvalter mange velferdsordninger.', 9),
  ('samfunnsfag-10:velferdsstaten', 'Kommunens oppgaver', 'Blant annet barnehage, grunnskole, fastlege og sykehjem.', 10),
  ('samfunnsfag-10:velferdsstaten', 'Fylkeskommunens oppgaver', 'Blant annet videregående skole, kollektivtransport og fylkesveier.', 11),
  ('samfunnsfag-10:velferdsstaten', 'Oljefondet', 'Statens pensjonsfond utland, der statens olje- og gassinntekter spares.', 12),
  ('samfunnsfag-10:velferdsstaten', 'Handlingsregelen', 'Staten skal over tid bare bruke omtrent den forventede avkastningen av oljefondet.', 13),
  ('samfunnsfag-10:velferdsstaten', 'Eldrebølgen', 'At andelen eldre øker, slik at det blir færre i arbeid per pensjonist.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-10:velferdsstaten', 'q01', 'flervalg', 'Hva er en velferdsstat?', array['Et samfunn der staten tar stort ansvar for innbyggernes trygghet og velferd', 'En stat uten skatter', 'En stat der alle er rike', 'En stat styrt av kongen']::text[], 0, 'Staten sørger blant annet for utdanning, helse og økonomisk trygghet.', true, true, 0),
  ('samfunnsfag-10:velferdsstaten', 'q02', 'flervalg', 'Hva betyr det at en velferdsordning er universell?', array['At den bare gjelder fattige', 'At den gjelder alle, uansett inntekt', 'At den gjelder hele verden', 'At den er frivillig']::text[], 1, 'Barnetrygd og gratis skole er eksempler på universelle ordninger.', true, true, 1),
  ('samfunnsfag-10:velferdsstaten', 'q03', 'flervalg', 'Hvilket forvaltningsnivå har ansvaret for videregående skole?', array['Kommunen', 'Staten', 'Fylkeskommunen', 'NAV']::text[], 2, 'Fylkeskommunen har også ansvar for kollektivtransport og fylkesveier.', true, true, 2),
  ('samfunnsfag-10:velferdsstaten', 'q04', 'flervalg', 'Hva er trepartssamarbeidet?', array['Samarbeid mellom tre politiske partier', 'Samarbeid mellom Norge, Sverige og Danmark', 'Samarbeid mellom tre kommuner', 'Samarbeid mellom staten, arbeidsgiverne og arbeidstakerne']::text[], 3, 'Samarbeidet er et viktig kjennetegn ved den nordiske modellen.', true, true, 3),
  ('samfunnsfag-10:velferdsstaten', 'q05', 'flervalg', 'Hva er eldrebølgen?', array['At det blir flere eldre per person i arbeid', 'At eldre flytter til utlandet', 'At pensjonsalderen senkes', 'At det blir færre eldre']::text[], 0, 'Vi lever lenger, og store årskull går av med pensjon.', true, true, 4),
  ('samfunnsfag-10:velferdsstaten', 'q06', 'flervalg', 'Hva sier handlingsregelen?', array['At all oljeformuen skal brukes med en gang', 'At staten over tid bare skal bruke omtrent den forventede avkastningen av oljefondet', 'At oljen skal selges til Sverige', 'At skatten skal fjernes']::text[], 1, 'Slik skal også framtidige generasjoner få glede av oljeinntektene.', true, true, 5),
  ('samfunnsfag-10:velferdsstaten', 'q07', 'flervalg', 'Hvem har ansvaret for fastlege og sykehjem?', array['Staten', 'Fylkeskommunen', 'Private bedrifter', 'Kommunen']::text[], 3, 'Kommunen har ansvar for de fleste nære tjenestene til innbyggerne.', true, true, 6),
  ('samfunnsfag-10:velferdsstaten', 'q08', 'flervalg', 'Hvordan finansieres velferdsstaten først og fremst?', array['Gjennom skatter og avgifter', 'Gjennom lotteri', 'Gjennom lån fra andre land', 'Gjennom frivillige gaver']::text[], 0, 'Oljefondet bidrar også, men skatter og avgifter er den viktigste kilden.', true, true, 7),
  ('samfunnsfag-10:velferdsstaten', 'q09', 'flervalg', 'Hva er dagpenger?', array['Penger du får hver dag på skolen', 'Lommepenger fra foreldre', 'Økonomisk støtte når du er arbeidsløs', 'Lønn for overtid']::text[], 2, 'Dagpenger skal gi trygghet mens man søker ny jobb.', true, false, 8),
  ('samfunnsfag-10:velferdsstaten', 'q10', 'flervalg', 'Hvilken utfordring handler om unge som står utenfor både arbeid og utdanning?', array['Eldrebølgen', 'Utenforskap', 'Sentralisering', 'Inflasjon']::text[], 1, 'Utenforskap er kostbart for samfunnet og vanskelig for den enkelte.', true, false, 9),
  ('samfunnsfag-10:velferdsstaten', 'm01', 'sant-usant', 'Folketrygden ble innført i 1967.', array['Sant', 'Usant']::text[], 0, 'Folketrygden samlet flere trygdeordninger i én.', false, true, 10),
  ('samfunnsfag-10:velferdsstaten', 'm02', 'sant-usant', 'I Norge må alle betale full pris for sykehusbehandling.', array['Sant', 'Usant']::text[], 1, 'Sykehusbehandling er i hovedsak gratis, og egenandelene har et tak.', false, true, 11),
  ('samfunnsfag-10:velferdsstaten', 'm03', 'sant-usant', 'Den nordiske modellen kjennetegnes av høy tillit og relativt små forskjeller.', array['Sant', 'Usant']::text[], 0, 'Tillit gjør det lettere å samarbeide og å kreve inn skatt.', false, true, 12),
  ('samfunnsfag-10:velferdsstaten', 'm04', 'sant-usant', 'Alle politiske partier er enige om hvordan velferdsstaten skal utvikles.', array['Sant', 'Usant']::text[], 1, 'Partiene er uenige om blant annet skatt, privatisering og hvor mye staten skal gjøre.', false, true, 13),
  ('samfunnsfag-10:velferdsstaten', 'm05', 'flervalg', 'Hvilken etat forvalter mange av velferdsordningene, som dagpenger og pensjon?', array['Skatteetaten', 'NAV', 'Politiet', 'Datatilsynet']::text[], 1, 'NAV ble opprettet i 2006.', false, true, 14),
  ('samfunnsfag-10:velferdsstaten', 'm06', 'flervalg', 'Hva er en egenandel?', array['Den delen av prisen du selv betaler for en offentlig tjeneste', 'En skatt på eiendom', 'En del av lønnen', 'En type trygd']::text[], 0, 'Du betaler for eksempel en egenandel hos fastlegen.', false, true, 15),
  ('samfunnsfag-10:velferdsstaten', 'm07', 'flervalg', 'Hvorfor gir eldrebølgen utfordringer for velferdsstaten?', array['Eldre betaler mer skatt enn andre', 'Det blir færre sykehjem', 'Utgiftene til pensjon og omsorg øker, mens det blir færre i arbeid per pensjonist', 'Eldre trenger ikke helsetjenester']::text[], 2, 'Færre skal betale for velferden til flere.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-10:velferdsstaten', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-10:velferdsstaten', 's01', 'Folketrygden ble innført i 1967. Forklar hva folketrygden bidrar med, og nevn to typer økonomisk støtte den kan gi.', 'Folketrygden er en del av velferdsordningene i Norge. Den kan blant annet gi pensjon, sykepenger og uføretrygd.', array['Forklarer at folketrygden gir økonomisk støtte eller trygghet.', 'Nevner minst to av disse: pensjon, sykepenger eller uføretrygd.']::text[], 0),
  ('samfunnsfag-10:velferdsstaten', 's02', 'Gratis offentlig skole og helsetjenester er velferdsgoder. Forklar hvordan skatter bidrar til at slike tjenester kan tilbys.', 'Skatter er med på å finansiere fellesskapet og velferdstjenestene. Derfor kan det offentlige tilby blant annet skole og helsetjenester.', array['Knytter skatter til finansiering av offentlige tjenester eller fellesskapet.', 'Bruker skole eller helsetjenester som eksempel på en tjeneste skattene bidrar til å finansiere.']::text[], 1),
  ('samfunnsfag-10:velferdsstaten', 's03', 'Sykepenger og dagpenger er begge velferdsordninger. Forklar forskjellen på hvem som kan få dem, og hvorfor.', 'Sykepenger erstatter lønn når du er syk og ikke kan jobbe. Dagpenger er økonomisk støtte når du er arbeidsløs.', array['Forklarer at sykepenger gjelder når sykdom hindrer en i å jobbe.', 'Forklarer at dagpenger gjelder ved arbeidsløshet.']::text[], 2),
  ('samfunnsfag-10:velferdsstaten', 's04', 'En person mister jobben og trenger økonomisk støtte mens hen er arbeidsløs. Hvilken støtteordning kan være aktuell, og hvilken rolle kan NAV ha?', 'Dagpenger kan være aktuell støtte når personen er arbeidsløs. NAV forvalter mange velferdsordninger, blant annet ordninger som gir økonomisk støtte.', array['Nevner dagpenger som støtte ved arbeidsløshet.', 'Forklarer at NAV forvalter mange velferdsordninger.']::text[], 3),
  ('samfunnsfag-10:velferdsstaten', 's05', 'To familier med ulik inntekt har begge barn under 18 år. Bruk barnetrygd til å forklare hva som gjør en ordning universell.', 'Begge familiene kan få barnetrygd fordi den gis til alle som har barn under 18 år. En universell ordning gjelder uansett inntekt.', array['Forklarer at barnetrygd gjelder for familier med barn under 18 år, uavhengig av inntekt.', 'Knytter dette til at universelle ordninger gjelder alle, uansett inntekt.']::text[], 4),
  ('samfunnsfag-10:velferdsstaten', 's06', 'En person trenger hjemmetjeneste, og en annen skal studere ved et offentlig universitet. Hvilket forvaltningsnivå har ansvar for hver av disse tjenestene?', 'Kommunen har ansvar for hjemmetjenester. Staten har ansvar for universiteter.', array['Plasserer hjemmetjenester hos kommunen.', 'Plasserer universiteter hos staten.']::text[], 5),
  ('samfunnsfag-10:velferdsstaten', 's07', 'Flere eldre og færre personer i arbeid per pensjonist kan påvirke velferdsstaten. Forklar hvordan dette kan føre til større utgifter.', 'Når andelen eldre øker, blir det færre i arbeid per pensjonist. Det kan gi større utgifter til pensjon og omsorg.', array['Knytter flere eldre til at det blir færre i arbeid per pensjonist.', 'Nevner økte utgifter til pensjon eller omsorg.']::text[], 6),
  ('samfunnsfag-10:velferdsstaten', 's08', 'Noen partier ønsker mer offentlig ansvar og høyere skatt, mens andre ønsker mer privat konkurranse og lavere skatt. Forklar forskjellen mellom disse retningene.', 'Den ene retningen vil at det offentlige skal ta mer ansvar og at skattene skal være høyere. Den andre vil ha mer privat konkurranse og lavere skatter.', array['Beskriver retningen med mer offentlig ansvar og høyere skatt.', 'Beskriver retningen med mer privat konkurranse og lavere skatt.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-10:mangfold-og-fordommer', 'samfunnsfag-10', 'mangfold-og-fordommer', 'Mangfold, fordommer og framstillinger', 'Likheter og ulikheter i identitet, levesett og kultur, muligheter og utfordringer ved mangfold, og hvordan framstillinger av fortiden og av grupper påvirker holdninger og handlinger.', array[13, 3]::int[], 5, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-10:mangfold-og-fordommer', '## Identitet, levesett og kultur
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-10:mangfold-og-fordommer', 'Kultur', 'Kunnskap, verdier, normer, tradisjoner og språk som en gruppe deler.', 0),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Kulturuttrykk', 'Måter kulturen vises på, som musikk, mat, klær, kunst og høytider.', 1),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Mangfold', 'At mennesker i et samfunn er ulike i blant annet kultur, religion og identitet.', 2),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Majoritet', 'Den største gruppen i et samfunn.', 3),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Minoritet', 'En mindre gruppe som skiller seg fra majoriteten, for eksempel i språk eller religion.', 4),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Etnosentrisme', 'Å bedømme andre kulturer ut fra ens egen og se på sin egen som best.', 5),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Kulturrelativisme', 'Å forstå en kultur ut fra dens egne forutsetninger.', 6),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Stereotypi', 'Forenklet bilde av en gruppe.', 7),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Fordom', 'Negativ holdning til en gruppe uten god kunnskap.', 8),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Diskriminering', 'Å behandle noen dårligere på grunn av hvem de er. Forbudt ved lov.', 9),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Rasisme', 'Ideen om at noen er mindre verdt på grunn av hudfarge eller etnisk bakgrunn.', 10),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Integrering', 'Minoriteter deltar i samfunnet og kan samtidig beholde sin kultur.', 11),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Assimilering', 'Minoriteten må gi opp sin kultur og bli lik majoriteten.', 12),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Segregering', 'At grupper lever atskilt fra hverandre.', 13),
  ('samfunnsfag-10:mangfold-og-fordommer', 'Faren ved én enkelt historie', 'Adichies advarsel om at én fortelling om en gruppe gir et forenklet bilde.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-10:mangfold-og-fordommer', 'q01', 'flervalg', 'Hva er etnosentrisme?', array['Å bedømme andre kulturer ut fra ens egen og se på sin egen som best', 'Å lære mange språk', 'Å reise mye', 'Å forstå andre kulturer ut fra deres egne forutsetninger']::text[], 0, 'Det siste alternativet beskriver kulturrelativisme.', true, true, 0),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q02', 'flervalg', 'Hva er forskjellen på en fordom og diskriminering?', array['Det er ingen forskjell', 'En fordom er en holdning, diskriminering er en handling', 'Diskriminering er en holdning, en fordom er en handling', 'Fordommer er alltid positive']::text[], 1, 'Når fordommer påvirker hvordan vi behandler andre, blir det diskriminering.', true, true, 1),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q03', 'flervalg', 'Hva betyr integrering?', array['At minoriteten må gi opp sin kultur', 'At grupper lever atskilt', 'At minoriteter deltar i samfunnet og samtidig kan beholde sin kultur', 'At alle må flytte']::text[], 2, 'Integrering skiller seg fra assimilering, der man må gi opp sin kultur.', true, true, 2),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q04', 'flervalg', 'Hva er et eksempel på kulturuttrykk?', array['En lov', 'Et politisk parti', 'En type skatt', 'Musikk, mat, klær eller høytider']::text[], 3, 'Kulturuttrykk er måter kulturen vises på.', true, true, 3),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q05', 'flervalg', 'Hva er en stereotypi?', array['Et forenklet bilde av en gruppe', 'En type musikk', 'En vitenskapelig undersøkelse', 'Et lydanlegg']::text[], 0, 'Stereotypier overser at mennesker i en gruppe er forskjellige.', true, true, 4),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q06', 'flervalg', 'Hvordan kan framstillinger i nyhetene påvirke holdninger?', array['De påvirker ikke holdninger', 'Ensidig dekning av en gruppe kan forsterke fordommer', 'De gjør alltid folk mer tolerante', 'De bestemmer lovene direkte']::text[], 1, 'Hvis vi mest hører negative historier om en gruppe, kan bildet bli skjevt.', true, true, 5),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q07', 'flervalg', 'Hva var fornorskingen av samer og kvener et eksempel på?', array['Integrering', 'Segregering', 'Assimilering', 'Kulturrelativisme']::text[], 2, 'Minoritetene skulle gi opp språk og kultur og bli «norske».', true, true, 6),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q08', 'flervalg', 'Hva er en mulighet ved mangfold?', array['Flere misforståelser', 'Mindre kontakt med verden', 'Mer diskriminering', 'Nye perspektiver og ideer']::text[], 3, 'Ulike erfaringer kan gi nye løsninger og et rikere samfunn.', true, true, 7),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q09', 'flervalg', 'Hva mener Adichie med «faren ved én enkelt historie»?', array['At bare én fortelling om en gruppe gir et forenklet bilde', 'At historie er et farlig fag', 'At man bare skal lese én bok', 'At alle historier er løgn']::text[], 0, 'Flere fortellinger gir et mer sammensatt og riktig bilde.', true, false, 8),
  ('samfunnsfag-10:mangfold-og-fordommer', 'q10', 'flervalg', 'Hvilken utfordring kan en ekstrem kulturrelativisme føre med seg?', array['At man ikke lærer om andre', 'At man godtar brudd på menneskerettighetene', 'At man blir etnosentrisk', 'At man ikke reiser']::text[], 1, 'Menneskerettighetene gjelder alle, uansett kultur.', true, false, 9),
  ('samfunnsfag-10:mangfold-og-fordommer', 'm01', 'sant-usant', 'Kultur er noe som aldri endrer seg.', array['Sant', 'Usant']::text[], 1, 'Kultur endrer seg hele tiden gjennom kontakt med andre og nye ideer.', false, true, 10),
  ('samfunnsfag-10:mangfold-og-fordommer', 'm02', 'sant-usant', 'Omtrent én av fem innbyggere i Norge er innvandrer eller født i Norge med innvandrerforeldre.', array['Sant', 'Usant']::text[], 0, 'Andelen har økt mye siden 1970-tallet.', false, true, 11),
  ('samfunnsfag-10:mangfold-og-fordommer', 'm03', 'sant-usant', 'Nazistisk propaganda framstilte jøder negativt for å skape støtte til forfølgelsen.', array['Sant', 'Usant']::text[], 0, 'Propagandaen avhumaniserte jøder og gjorde forfølgelsen lettere å godta.', false, true, 12),
  ('samfunnsfag-10:mangfold-og-fordommer', 'm04', 'sant-usant', 'Det er lov å avvise en jobbsøker på grunn av hudfarge.', array['Sant', 'Usant']::text[], 1, 'Diskriminering på grunn av etnisitet er forbudt etter likestillings- og diskrimineringsloven.', false, true, 13),
  ('samfunnsfag-10:mangfold-og-fordommer', 'm05', 'flervalg', 'Hva er segregering?', array['At grupper lever atskilt fra hverandre', 'At alle blir like', 'At man lærer et nytt språk', 'At man flytter til byen']::text[], 0, 'Segregering kan skje gjennom lover eller gjennom bosettingsmønstre.', false, true, 14),
  ('samfunnsfag-10:mangfold-og-fordommer', 'm06', 'flervalg', 'Hva er rasisme?', array['Kritikk av politikere', 'Ideen om at noen er mindre verdt på grunn av hudfarge eller etnisk bakgrunn', 'Interesse for andre kulturer', 'Et sportsbegrep']::text[], 1, 'Rasisme bryter med prinsippet om at alle mennesker er likeverdige.', false, true, 15),
  ('samfunnsfag-10:mangfold-og-fordommer', 'm07', 'flervalg', 'Hvilket spørsmål er nyttig når du vurderer en framstilling av en gruppe?', array['Hvor lang er teksten?', 'Hvilken skrifttype er brukt?', 'Hvem forteller, og hvem mangler?', 'Hvor mange bilder har den?']::text[], 2, 'Avsender og manglende stemmer sier mye om hvilket bilde som skapes.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-10:mangfold-og-fordommer', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-10:mangfold-og-fordommer', 's01', 'En gruppe deler språk, normer og tradisjoner. Medlemmene viser noe av dette gjennom musikk, mat og klær. Forklar forskjellen på kultur og kulturuttrykk.', 'Kultur er kunnskap, verdier, normer, tradisjoner og språk som en gruppe deler. Kulturuttrykk er måter kulturen blir synlig på, for eksempel gjennom musikk, mat og klær.', array['Forklarer at kultur er noe en gruppe deler, som kunnskap, normer eller tradisjoner.', 'Forklarer at kulturuttrykk er måter kulturen vises på.']::text[], 0),
  ('samfunnsfag-10:mangfold-og-fordommer', 's02', 'I ett samfunn deltar en minoritet i skole og arbeidsliv, samtidig som gruppen kan beholde sin kultur. I et annet samfunn må minoriteten gi opp sin kultur og bli lik majoriteten. Sammenlign hva de to samfunnene legger opp til.', 'Det første legger opp til integrering: minoriteten deltar i samfunnet og kan beholde kulturen sin. Det andre legger opp til assimilering, der minoriteten må bli lik majoriteten.', array['Knytter deltakelse kombinert med å beholde egen kultur til integrering.', 'Knytter kravet om å gi opp egen kultur og bli lik majoriteten til assimilering.']::text[], 1),
  ('samfunnsfag-10:mangfold-og-fordommer', 's03', 'I en by lever to grupper atskilt fra hverandre og har lite kontakt. Hvilket begrep beskriver dette, og hva kjennetegner det?', 'Dette er segregering. Det kjennetegnes ved at grupper lever atskilt fra hverandre.', array['Identifiserer situasjonen som segregering.', 'Forklarer at grupper lever atskilt fra hverandre.']::text[], 2),
  ('samfunnsfag-10:mangfold-og-fordommer', 's04', 'En person får avslag på en boligsøknad fordi personen har en bestemt etnisk bakgrunn. Hvilket begrep beskriver behandlingen, og hvorfor passer begrepet?', 'Dette er diskriminering fordi personen blir behandlet dårligere på grunn av hvem personen er. Diskriminering er forbudt ved lov.', array['Identifiserer behandlingen som diskriminering.', 'Forklarer at personen behandles dårligere på grunn av etnisk bakgrunn eller hvem personen er.']::text[], 3),
  ('samfunnsfag-10:mangfold-og-fordommer', 's05', 'Nazistisk propaganda framstilte jøder som farlige. Forklar hvordan denne framstillingen kunne få alvorlige følger for jøder.', 'Framstillingen kunne skape eller styrke negative holdninger til jøder. Nazistisk propaganda bidro til Holocaust.', array['Forklarer at framstillingen kunne påvirke holdninger ved å framstille jøder negativt eller som farlige.', 'Knytter propagandaen til at den bidro til Holocaust.']::text[], 4),
  ('samfunnsfag-10:mangfold-og-fordommer', 's06', 'I et samfunn er gruppe A den største gruppen, mens gruppe B er mindre og skiller seg fra den største gruppen gjennom språket sitt. Hva kalles gruppe A og gruppe B? Begrunn svaret.', 'Gruppe A er majoriteten fordi den er den største gruppen. Gruppe B er en minoritet fordi den er mindre og skiller seg fra majoriteten gjennom språket sitt.', array['Identifiserer den største gruppen som majoriteten.', 'Identifiserer den mindre gruppen som minoritet og knytter det til at den skiller seg fra majoriteten.']::text[], 5),
  ('samfunnsfag-10:mangfold-og-fordommer', 's07', 'En person prøver å forstå en skikk ved å undersøke hva den betyr for menneskene i kulturen, i stedet for å vurdere den ut fra sine egne vaner. Hvilket begrep beskriver denne tilnærmingen, og hva går den ut på?', 'Dette er kulturrelativisme. Det betyr å forsøke å forstå en kultur ut fra dens egne forutsetninger.', array['Identifiserer tilnærmingen som kulturrelativisme.', 'Forklarer at man prøver å forstå kulturen ut fra dens egne forutsetninger.']::text[], 6),
  ('samfunnsfag-10:mangfold-og-fordommer', 's08', 'Minnesmerker, filmer og bøker løfter fram noen historier om fortiden mer enn andre. Forklar hvordan dette kan påvirke hvem folk ser på som helter og ofre.', 'Når noen historier løftes fram, påvirker det hvordan folk forstår fortiden. Det kan gjøre at bestemte personer eller grupper blir sett på som helter eller ofre, mens andre historier får mindre plass.', array['Forklarer at hvilke historier som løftes fram, påvirker hvordan folk forstår fortiden.', 'Knytter dette til hvem som blir oppfattet som helter eller ofre.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsfag-10:makt-og-medier', 'samfunnsfag-10', 'makt-og-medier', 'Makt, medier og digital debatt', 'Hvem som har makt i samfunnet i dag og hvordan de argumenterer, hvordan mediene og digitale plattformer former samfunnsdebatten, og hvordan du vurderer kilder kritisk.', array[16, 17, 2]::int[], 6, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('samfunnsfag-10:makt-og-medier', '## Hva er makt?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('samfunnsfag-10:makt-og-medier', 'Makt', 'Evnen til å få andre til å gjøre noe eller påvirke utviklingen i samfunnet.', 0),
  ('samfunnsfag-10:makt-og-medier', 'Politisk makt', 'Makt til å vedta lover og budsjetter.', 1),
  ('samfunnsfag-10:makt-og-medier', 'Økonomisk makt', 'Makt gjennom eierskap, investeringer og arbeidsplasser.', 2),
  ('samfunnsfag-10:makt-og-medier', 'Mediemakt', 'Makt til å bestemme hva folk får vite om, og hvordan det framstilles.', 3),
  ('samfunnsfag-10:makt-og-medier', 'Lobbyisme', 'Å prøve å påvirke politikere på vegne av bedrifter eller organisasjoner.', 4),
  ('samfunnsfag-10:makt-og-medier', 'Etos', 'Appell til avsenderens troverdighet.', 5),
  ('samfunnsfag-10:makt-og-medier', 'Patos', 'Appell til følelser.', 6),
  ('samfunnsfag-10:makt-og-medier', 'Logos', 'Appell til fornuft, fakta og logikk.', 7),
  ('samfunnsfag-10:makt-og-medier', 'Redaktørstyrte medier', 'Medier med en ansvarlig redaktør som følger presseetiske regler.', 8),
  ('samfunnsfag-10:makt-og-medier', 'Vær Varsom-plakaten', 'Presseetiske regler for norske medier.', 9),
  ('samfunnsfag-10:makt-og-medier', 'PFU', 'Pressens Faglige Utvalg, som behandler klager på medier.', 10),
  ('samfunnsfag-10:makt-og-medier', 'Dagsorden', 'Hvilke saker som får oppmerksomhet i samfunnet.', 11),
  ('samfunnsfag-10:makt-og-medier', 'Desinformasjon', 'Bevisst falsk eller villedende informasjon.', 12),
  ('samfunnsfag-10:makt-og-medier', 'Deepfake', 'KI-laget bilde eller video som ser ekte ut.', 13),
  ('samfunnsfag-10:makt-og-medier', 'Faktasjekk', 'Å undersøke om en påstand stemmer, for eksempel med Faktisk.no.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsfag-10:makt-og-medier', 'q01', 'flervalg', 'Hva er makt?', array['Evnen til å påvirke andre eller utviklingen i samfunnet', 'Å ha mange venner', 'Å være fysisk sterk', 'Å ha mye fritid']::text[], 0, 'Makt kan være politisk, økonomisk, kunnskapsbasert eller knyttet til medier.', true, true, 0),
  ('samfunnsfag-10:makt-og-medier', 'q02', 'flervalg', 'Hva gjør en lobbyist?', array['Dømmer i rettssaker', 'Prøver å påvirke politikere på vegne av bedrifter eller organisasjoner', 'Skriver nyheter', 'Teller stemmer']::text[], 1, 'Lobbyisme er lovlig, men åpenhet om hvem som påvirker, er viktig i et demokrati.', true, true, 1),
  ('samfunnsfag-10:makt-og-medier', 'q03', 'flervalg', 'Hvilken appellform bygger på følelser?', array['Etos', 'Logos', 'Patos', 'Ingen av dem']::text[], 2, 'Patos spiller for eksempel på medfølelse, frykt eller sinne.', true, true, 2),
  ('samfunnsfag-10:makt-og-medier', 'q04', 'flervalg', 'Hvorfor har internasjonale teknologiselskaper stor makt?', array['Fordi de vedtar norske lover', 'Fordi de eier alle aviser', 'Fordi de styrer domstolene', 'Fordi algoritmene deres bestemmer hva milliarder ser']::text[], 3, 'Algoritmene påvirker hvilke nyheter og meninger vi møter.', true, true, 3),
  ('samfunnsfag-10:makt-og-medier', 'q05', 'flervalg', 'Hva er Vær Varsom-plakaten?', array['Presseetiske regler for redaktørstyrte medier', 'En trafikkregel', 'En lov om sosiale medier', 'En plakat i klasserommet']::text[], 0, 'Reglene handler blant annet om kildebruk, personvern og retten til å svare på kritikk.', true, true, 4),
  ('samfunnsfag-10:makt-og-medier', 'q06', 'flervalg', 'Hvordan kan algoritmer påvirke formen på samfunnsdebatten?', array['De gjør innleggene lengre og roligere', 'De belønner engasjement og kan fremme spisse utspill', 'De fjerner alle meninger', 'De har ingen påvirkning']::text[], 1, 'Innlegg som vekker sterke følelser, får ofte mest spredning.', true, true, 5),
  ('samfunnsfag-10:makt-og-medier', 'q07', 'flervalg', 'Hva er en deepfake?', array['En falsk nyhetsavis', 'En type datavirus', 'Et KI-laget bilde eller en video som ser ekte ut', 'En hemmelig chat']::text[], 2, 'Deepfakes kan brukes til å spre desinformasjon.', true, true, 6),
  ('samfunnsfag-10:makt-og-medier', 'q08', 'flervalg', 'Hva betyr det at mediene setter dagsorden?', array['At de bestemmer lovene', 'At de lager timeplaner', 'At de velger politikere', 'At de påvirker hvilke saker folk snakker om']::text[], 3, 'Det mediene skriver mye om, blir ofte det politikerne må svare på.', true, true, 7),
  ('samfunnsfag-10:makt-og-medier', 'q09', 'flervalg', 'Hvilket spørsmål er viktig når du vurderer et politisk utspill?', array['Hvem er avsenderen, og hvilke interesser har de?', 'Hvor mange liker innlegget?', 'Hvilken farge har logoen?', 'Hvor lang er teksten?']::text[], 0, 'Interessene til avsenderen kan påvirke hvilke argumenter som brukes.', true, false, 8),
  ('samfunnsfag-10:makt-og-medier', 'q10', 'flervalg', 'Hva er en ensrettet kilde?', array['En kilde med mange perspektiver', 'En kilde som bare viser én side av en sak', 'En offentlig statistikk', 'En kilde som er oppdatert']::text[], 1, 'Ensrettede kilder bør suppleres med andre kilder.', true, false, 9),
  ('samfunnsfag-10:makt-og-medier', 'm01', 'sant-usant', 'Regler vedtatt i EU kan få betydning i Norge gjennom EØS-avtalen.', array['Sant', 'Usant']::text[], 0, 'Norge er ikke medlem av EU, men må ta inn mange EU-regler gjennom EØS.', false, true, 10),
  ('samfunnsfag-10:makt-og-medier', 'm02', 'sant-usant', 'Alt som deles på sosiale medier, følger presseetiske regler.', array['Sant', 'Usant']::text[], 1, 'Bare redaktørstyrte medier er bundet av Vær Varsom-plakaten.', false, true, 11),
  ('samfunnsfag-10:makt-og-medier', 'm03', 'sant-usant', 'Mangel på kilder kan gi et skjevt bilde av en sak.', array['Sant', 'Usant']::text[], 0, 'Stemmer som mangler, kan gjøre at bildet blir ufullstendig.', false, true, 12),
  ('samfunnsfag-10:makt-og-medier', 'm04', 'sant-usant', 'Et argument som bygger på følelser, kalles logos.', array['Sant', 'Usant']::text[], 1, 'Følelsesargumenter kalles patos. Logos bygger på fornuft og fakta.', false, true, 13),
  ('samfunnsfag-10:makt-og-medier', 'm05', 'flervalg', 'Hvor kan du klage hvis en avis bryter god presseskikk?', array['Pressens Faglige Utvalg (PFU)', 'Datatilsynet', 'Stortinget', 'NAV']::text[], 0, 'PFU vurderer om mediene har fulgt Vær Varsom-plakaten.', false, true, 14),
  ('samfunnsfag-10:makt-og-medier', 'm06', 'flervalg', 'Hva er desinformasjon?', array['Korrekte nyheter', 'Bevisst falsk eller villedende informasjon', 'Reklame', 'Statistikk']::text[], 1, 'Desinformasjon spres med vilje for å villede.', false, true, 15),
  ('samfunnsfag-10:makt-og-medier', 'm07', 'flervalg', 'Hva er etos?', array['Et argument basert på statistikk', 'Et argument som spiller på frykt', 'Troverdigheten til avsenderen', 'En type kilde']::text[], 2, 'Vi lytter gjerne mer til en avsender vi opplever som troverdig og kunnskapsrik.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsfag-10:makt-og-medier', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsfag-10:makt-og-medier', 's01', 'Sammenlign politisk makt og økonomisk makt. Forklar hva hver type makt går ut på, og gi ett eksempel på hver.', 'Politisk makt er makt til å vedta lover og budsjetter, slik Stortinget har. Økonomisk makt kommer blant annet fra eierskap, investeringer og arbeidsplasser, slik næringslivet kan ha.', array['Forklarer at politisk makt handler om å vedta lover eller budsjetter.', 'Forklarer at økonomisk makt bygger på eierskap, investeringer eller arbeidsplasser.']::text[], 0),
  ('samfunnsfag-10:makt-og-medier', 's02', 'En debattant sier at hun har lang erfaring som ekspert på et tema. En annen viser til forskning og fakta som støtter synet sitt. Hvilken appellform bruker hver av dem, og hva skiller appellformene?', 'Den første bruker etos, fordi hun viser til troverdigheten sin. Den andre bruker logos, fordi hun støtter synet sitt med forskning og fakta.', array['Knytter etos til troverdighet eller avsenderens kunnskap.', 'Knytter logos til fornuft, fakta eller forskning.']::text[], 1),
  ('samfunnsfag-10:makt-og-medier', 's03', 'Hva kjennetegner redaktørstyrte medier sammenlignet med innlegg som hvem som helst kan publisere på sosiale medier?', 'Redaktørstyrte medier har en ansvarlig redaktør og følger presseetiske regler. På sosiale medier kan alle delta og publisere innhold.', array['Forklarer at redaktørstyrte medier har en ansvarlig redaktør.', 'Forklarer at slike medier følger presseetiske regler, i motsetning til at alle kan publisere på sosiale medier.']::text[], 2),
  ('samfunnsfag-10:makt-og-medier', 's04', 'En plattform bruker algoritmer som løfter fram innhold som skaper mye engasjement. Forklar hvordan dette kan føre til at spisse og polariserende utspill får stor spredning.', 'Algoritmene belønner innhold som skaper engasjement. Spisse og polariserende utspill kan skape mye engasjement og blir derfor lettere løftet fram og spredd.', array['Forklarer at algoritmer prioriterer innhold som skaper engasjement.', 'Knytter dette til at polariserende eller spisse utspill kan få større spredning.']::text[], 3),
  ('samfunnsfag-10:makt-og-medier', 's05', 'Du finner et innlegg med en påstand, men innlegget viser ikke til kilder. Beskriv hvordan du kan undersøke om påstanden stemmer.', 'Jeg kan undersøke hvem som står bak innlegget, og hvorfor det ble laget. Deretter kan jeg sammenligne med flere kilder eller bruke en faktasjekk-tjeneste som Faktisk.no.', array['Foreslår å undersøke hvem som står bak kilden, når eller hvorfor den ble laget.', 'Foreslår å sammenligne med flere kilder eller bruke en faktasjekk-tjeneste.']::text[], 4),
  ('samfunnsfag-10:makt-og-medier', 's06', 'En leser mener at en avis har brutt presseetiske regler. Forklar hvilken rolle Vær Varsom-plakaten og PFU har i en slik sak.', 'Vær Varsom-plakaten inneholder presseetiske regler for norske medier. PFU behandler klager på medier, for eksempel en klage på en avis.', array['Forklarer at Vær Varsom-plakaten er presseetiske regler for norske medier.', 'Forklarer at PFU behandler klager på medier.']::text[], 5),
  ('samfunnsfag-10:makt-og-medier', 's07', 'Regler som er vedtatt i EU, kan også få betydning i Norge gjennom EØS-avtalen. Forklar hva dette sier om hvordan beslutninger utenfor Norge kan påvirke landet.', 'Gjennom EØS-avtalen får regler vedtatt i EU også betydning i Norge. Dermed kan beslutninger som tas utenfor Norge, påvirke hvilke regler som gjelder her.', array['Knytter EØS-avtalen til at EU-regler får betydning i Norge.', 'Forklarer at beslutninger utenfor Norge dermed kan påvirke landet.']::text[], 6),
  ('samfunnsfag-10:makt-og-medier', 's08', 'En person ser mest innlegg fra folk som mener det samme som personen selv. Hva kalles dette, og hvordan kan det påvirke hvilke syn personen møter i samfunnsdebatten?', 'Dette kan være en filterboble. Personen møter mest synspunkter hen allerede er enig i, og får dermed mindre kontakt med andre meninger.', array['Identifiserer situasjonen som en filterboble.', 'Forklarer at personen i mindre grad møter synspunkter som utfordrer egne meninger.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-10:sikhisme-og-andre-tradisjoner', 'krle-10', 'sikhisme-og-andre-tradisjoner', 'Sikhisme og andre religiøse tradisjoner', 'Sikhismens guruer, tro og praksis, og sentrale trekk ved daoisme, konfutsianisme, shinto og bahá''í.', array[1]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-10:sikhisme-og-andre-tradisjoner', '## Sikhismen
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Sikhisme', 'Monoteistisk religion fra Punjab i India med rundt 25–30 millioner tilhengere.', 0),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Guru Nanak', 'Sikhismens grunnlegger (1469–1539).', 1),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Guru Gobind Singh', 'Den tiende guruen, som grunnla Khalsa i 1699.', 2),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Khalsa', 'Fellesskapet av innviede sikher.', 3),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Guru Granth Sahib', 'Sikhismens hellige skrift, som regnes som evig guru.', 4),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Waheguru', 'Et vanlig navn på Gud i sikhismen.', 5),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Gurdwara', 'Sikhenes gudshus.', 6),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Langar', 'Gratis kjøkken i gurdwaraen der alle får mat, uansett bakgrunn.', 7),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Det gylne tempel', 'Sikhismens mest kjente gudshus, i Amritsar.', 8),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'De fem K-ene', 'Kjennetegn innviede sikher bærer, blant annet uklipt hår og stålarmbånd.', 9),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Singh og Kaur', 'Navn for sikhmenn («løve») og sikhkvinner («prinsesse»).', 10),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Dao', '«Veien», den naturlige orden i alt i daoismen.', 11),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Yin og yang', 'To motsatte krefter som hører sammen og må være i balanse.', 12),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Shinto', 'Japansk religion om kami, ånder og guddommelige krefter i naturen og hos forfedrene.', 13),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'Bahá''í', 'Religion fra 1800-tallets Persia som vektlegger én Gud og menneskehetens enhet.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q01', 'flervalg', 'Hvem grunnla sikhismen?', array['Guru Gobind Singh', 'Bahá''u''lláh', 'Guru Nanak', 'Laozi']::text[], 2, 'Guru Nanak levde fra 1469 til 1539.', true, true, 0),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q02', 'flervalg', 'Hva er langar?', array['Et gratis kjøkken i gurdwaraen der alle får mat', 'En hellig bok', 'En turban', 'En høytid']::text[], 0, 'Langar er et uttrykk for likeverd og deling.', true, true, 1),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q03', 'flervalg', 'Hva er Guru Granth Sahib?', array['Den første guruen', 'Et tempel i Amritsar', 'Et seremonielt sverd', 'Sikhismens hellige skrift, som regnes som evig guru']::text[], 3, 'Etter den tiende guruen har skriften vært sikhenes guru.', true, true, 2),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q04', 'flervalg', 'Hva mente guruene om kastesystemet?', array['At det var gitt av Gud', 'At det skulle avvises fordi alle er likeverdige', 'At det bare gjaldt i Punjab', 'At det var nødvendig']::text[], 1, 'Likeverd er et grunnleggende prinsipp i sikhismen.', true, true, 3),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q05', 'flervalg', 'Hva er de fem K-ene?', array['Fem hellige byer', 'Fem guruer', 'Fem daglige bønner', 'Fem kjennetegn som innviede sikher bærer']::text[], 3, 'Blant dem er uklipt hår, en kam og et stålarmbånd.', true, true, 4),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q06', 'flervalg', 'Hva betyr Dao i daoismen?', array['Kraften', 'Guden', 'Veien, den naturlige orden i alt', 'Himmelen']::text[], 2, 'Daoister søker å leve i harmoni med dao.', true, true, 5),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q07', 'flervalg', 'Hva er kami i shinto?', array['Ånder og guddommelige krefter i naturen, forfedrene og hellige steder', 'En munk', 'En hellig bok', 'En port']::text[], 0, 'Kami kan finnes i fjell, trær, elver og forfedre.', true, true, 6),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q08', 'flervalg', 'Hva legger bahá''í vekt på?', array['At bare én religion er sann', 'At det finnes én Gud, og at religionene har samme kilde', 'At det finnes mange guder', 'At naturen er hellig']::text[], 1, 'Bahá''í vektlegger også menneskehetens enhet.', true, true, 7),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q09', 'flervalg', 'Hvor ligger Det gylne tempel?', array['Delhi', 'Lahore', 'Amritsar', 'Varanasi']::text[], 2, 'Tempelet i Amritsar besøkes av mange tusen mennesker hver dag.', true, false, 8),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'q10', 'flervalg', 'Hvilken tradisjon legger vekt på respekt for foreldre og et harmonisk samfunn?', array['Shinto', 'Sikhisme', 'Bahá''í', 'Konfutsianisme']::text[], 3, 'Konfutsianismen har preget kinesisk kultur i over 2000 år.', true, false, 9),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'm01', 'sant-usant', 'Sikhismen er monoteistisk.', array['Sant', 'Usant']::text[], 0, 'Sikher tror på én Gud, ofte kalt Waheguru.', false, true, 10),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'm02', 'sant-usant', 'Bare sikher får spise i langar.', array['Sant', 'Usant']::text[], 1, 'Alle er velkomne, uansett religion og bakgrunn.', false, true, 11),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'm03', 'sant-usant', 'Mange japanere kombinerer shinto og buddhisme.', array['Sant', 'Usant']::text[], 0, 'Shinto brukes ofte ved fødsel og bryllup, buddhisme ved død og gravferd.', false, true, 12),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'm04', 'sant-usant', 'Sikhismen er over 3000 år gammel.', array['Sant', 'Usant']::text[], 1, 'Sikhismen oppsto på 1400- og 1500-tallet.', false, true, 13),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'm05', 'flervalg', 'Hva betyr navnet Singh?', array['Løve', 'Prinsesse', 'Lærer', 'Elev']::text[], 0, 'Kvinner får navnet Kaur, som betyr «prinsesse».', false, true, 14),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'm06', 'flervalg', 'Hva er yin og yang?', array['To guruer', 'To motsatte krefter som hører sammen og må være i balanse', 'To japanske helligdommer', 'To hellige bøker']::text[], 1, 'For eksempel lys og mørke, varmt og kaldt.', false, true, 15),
  ('krle-10:sikhisme-og-andre-tradisjoner', 'm07', 'flervalg', 'Hva heter sikhenes gudshus?', array['Moské', 'Synagoge', 'Pagode', 'Gurdwara']::text[], 3, 'Gurdwara betyr «guruens dør».', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-10:sikhisme-og-andre-tradisjoner', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-10:sikhisme-og-andre-tradisjoner', 's01', 'Sikhismen kalles monoteistisk. Forklar hva dette betyr, og si hva Gud i sikhismen kalles.', 'Monoteistisk betyr at religionen tror på én Gud. I sikhismen kalles Gud ofte Waheguru.', array['Forklarer at monoteisme betyr tro på én Gud.', 'Oppgir Waheguru som et vanlig navn på Gud i sikhismen.']::text[], 0),
  ('krle-10:sikhisme-og-andre-tradisjoner', 's02', 'Guru Gobind Singh bestemte at Guru Granth Sahib skulle være guru for alltid. Forklar hva dette betydde for sikhismen etter den tiende guruen.', 'Guru Granth Sahib skulle være den evige guruen. Dermed fortsatte den hellige skriften å ha rollen som guru etter at rekken av menneskelige guruer var over.', array['Får fram at Guru Granth Sahib skulle være guru for alltid.', 'Forklarer at skriften dermed hadde en vedvarende gururolle etter den tiende guruen.']::text[], 1),
  ('krle-10:sikhisme-og-andre-tradisjoner', 's03', 'En sikh ønsker å følge pliktene med å meditere over Guds navn, arbeide ærlig og dele med andre. Gi to konkrete handlinger som passer til to av pliktene, og forklar hvilke plikter handlingene viser.', 'Personen kan sette av tid til å meditere over Guds navn og dele mat eller andre ressurser med noen. Dette viser pliktene med å meditere og å dele med andre.', array['Gir minst to handlinger som passer til ulike plikter.', 'Knytter handlingene riktig til meditasjon, ærlig arbeid eller det å dele.']::text[], 2),
  ('krle-10:sikhisme-og-andre-tradisjoner', 's04', 'Sammenlign sikhismen og bahá''í når det gjelder troen på Gud. Nevn også én annen viktig tanke som bahá''í legger vekt på.', 'Både sikhismen og bahá''í er monoteistiske og tror på én Gud. Bahá''í legger også vekt på at alle religioner har samme kilde, og at menneskeheten er én.', array['Sier at begge tradisjonene tror på én Gud.', 'Nevner en annen sentral tanke i bahá''í, som at religionene har samme kilde eller at menneskeheten er én.']::text[], 3),
  ('krle-10:sikhisme-og-andre-tradisjoner', 's05', 'Sammenlign hva daoisme og konfutsianisme særlig legger vekt på i måten mennesker bør leve på.', 'Daoismen legger vekt på å leve i harmoni med naturen og finne balanse. Konfutsianismen legger særlig vekt på respekt for foreldre og eldre, gode relasjoner og et harmonisk samfunn.', array['Beskriver daoismens vekt på harmoni med naturen eller balanse.', 'Beskriver konfutsianismens vekt på respekt, gode relasjoner eller et harmonisk samfunn.']::text[], 4),
  ('krle-10:sikhisme-og-andre-tradisjoner', 's06', 'En person besøker et hellig sted i naturen fordi stedet forbindes med åndelige krefter. Forklar hvordan dette passer med shinto.', 'I shinto finnes kami, ånder og guddommelige krefter i naturen og på hellige steder. Derfor passer det med shinto å knytte åndelige krefter til et sted i naturen.', array['Knytter situasjonen til shintos tro på kami eller guddommelige krefter.', 'Får fram at slike krefter kan forbindes med naturen eller hellige steder.']::text[], 5),
  ('krle-10:sikhisme-og-andre-tradisjoner', 's07', 'I daoismen hører yin og yang sammen selv om de er motsatte krefter. Forklar hva dette innebærer for balansen mellom dem.', 'Yin og yang er motsatte krefter som likevel hører sammen. De må være i balanse.', array['Får fram at yin og yang er motsatte, men hører sammen.', 'Forklarer at de må være i balanse.']::text[], 6),
  ('krle-10:sikhisme-og-andre-tradisjoner', 's08', 'Sikhmenn får ofte navnet Singh, og sikhkvinner får ofte navnet Kaur. Forklar hva navnene betyr, og hva de skulle vise om kaste.', 'Singh betyr «løve», og Kaur betyr «prinsesse». Navnene skulle vise at kaste ikke betyr noe.', array['Oppgir betydningen av Singh og Kaur riktig.', 'Forklarer at navnene skulle uttrykke at kaste ikke betyr noe.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-10:kjonn-og-seksualitet', 'krle-10', 'kjonn-og-seksualitet', 'Kjønn og seksualitet i religioner og livssyn', 'Ulike syn på kjønnsroller, seksualitet og likekjønnet samliv i kristendom, islam, jødedom, hinduisme og livssynshumanisme, og hva norsk lov sier.', array[8]::int[], 1, 'sjekkes', array['Sensitivt tema – bør gjennomgås av lærer for balanse og presisjon i beskrivelsen av de ulike religionenes syn. Fakta sjekket i september 2026.']::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-10:kjonn-og-seksualitet', '## Et omstridt tema
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-10:kjonn-og-seksualitet', 'Kjønnsroller', 'Forventninger til hvordan kvinner og menn skal oppføre seg og hva de skal gjøre.', 0),
  ('krle-10:kjonn-og-seksualitet', 'Tolkning', 'Hvordan hellige tekster forstås. Ulike tolkninger gir ulike syn på kjønn og seksualitet.', 1),
  ('krle-10:kjonn-og-seksualitet', 'Ingrid Bjerkås', 'Den norske kirkes første kvinnelige prest, ordinert i 1961.', 2),
  ('krle-10:kjonn-og-seksualitet', 'Rosemarie Köhn', 'Den norske kirkes første kvinnelige biskop, fra 1993.', 3),
  ('krle-10:kjonn-og-seksualitet', 'Mannlige prester', 'Den katolske og den ortodokse kirken har bare menn som prester.', 4),
  ('krle-10:kjonn-og-seksualitet', 'Muslimsk feminisme', 'Muslimer som tolker Koranen på nye måter og krever større likestilling.', 5),
  ('krle-10:kjonn-og-seksualitet', 'Kvinnelige rabbinere', 'Finnes i reformjødedommen, men ikke i ortodoks jødedom.', 6),
  ('krle-10:kjonn-og-seksualitet', 'Likestilling', 'At kjønn ikke skal avgjøre rettigheter og muligheter.', 7),
  ('krle-10:kjonn-og-seksualitet', 'Samtykke', 'Et frivillig og tydelig ja.', 8),
  ('krle-10:kjonn-og-seksualitet', 'Likekjønnet vigsel', 'Den norske kirke vedtok i 2016 at likekjønnede par kan vies i kirken.', 9),
  ('krle-10:kjonn-og-seksualitet', 'Katolsk syn på homofili', 'Legningen er ikke synd, men homofilt samliv regnes som synd.', 10),
  ('krle-10:kjonn-og-seksualitet', 'Tredje kjønn', 'Gammel tradisjon i Sør-Asia med en egen kjønnskategori ved siden av mann og kvinne.', 11),
  ('krle-10:kjonn-og-seksualitet', 'Kjønnsnøytral ekteskapslov', 'Siden 2009 kan to av samme kjønn gifte seg i Norge.', 12),
  ('krle-10:kjonn-og-seksualitet', 'Unntak for trossamfunn', 'Trossamfunn kan selv bestemme hvem de vier, og hvem som kan være religiøse ledere.', 13),
  ('krle-10:kjonn-og-seksualitet', 'Mangfold innad', 'At troende i samme religion kan ha svært ulike syn.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-10:kjonn-og-seksualitet', 'q01', 'flervalg', 'Hva handler uenigheten om kjønn og seksualitet i religioner ofte om?', array['Hvilke høytider man feirer', 'Hvordan hellige tekster skal tolkes', 'Hvilket språk man ber på', 'Hvor gudshusene ligger']::text[], 1, 'Samme tekst kan tolkes svært ulikt av ulike troende.', true, true, 0),
  ('krle-10:kjonn-og-seksualitet', 'q02', 'flervalg', 'Når fikk Den norske kirke sin første kvinnelige prest?', array['1814', '1913', '1993', '1961']::text[], 3, 'Ingrid Bjerkås ble ordinert i 1961.', true, true, 1),
  ('krle-10:kjonn-og-seksualitet', 'q03', 'flervalg', 'Hvilken kirke har bare mannlige prester?', array['Den katolske kirke', 'Den norske kirke', 'Alle lutherske kirker', 'Ingen kirker']::text[], 0, 'Også den ortodokse kirken har bare mannlige prester.', true, true, 2),
  ('krle-10:kjonn-og-seksualitet', 'q04', 'flervalg', 'Hva vedtok Den norske kirke i 2016?', array['At kvinner kan bli prester', 'At kirken skal skilles fra staten', 'At likekjønnede par kan vies i kirken', 'At prevensjon er forbudt']::text[], 2, 'Vedtaket ble gjort av Kirkemøtet.', true, true, 3),
  ('krle-10:kjonn-og-seksualitet', 'q05', 'flervalg', 'Hva lærer Den katolske kirke om homofili?', array['At homofil legning ikke er synd, men at homofilt samliv er det', 'At alt er tillatt', 'At homofile ikke kan være katolikker', 'At homofile par kan vies i kirken']::text[], 0, 'Kirken skiller mellom legning og handling.', true, true, 4),
  ('krle-10:kjonn-og-seksualitet', 'q06', 'flervalg', 'Hva mener livssynshumanister om kjønn?', array['At menn skal lede', 'At kvinner skal være hjemme', 'At kjønn avgjør hvilke yrker man kan ha', 'At det skal være full likestilling']::text[], 3, 'Humanister bygger på menneskeverd og menneskerettigheter.', true, true, 5),
  ('krle-10:kjonn-og-seksualitet', 'q07', 'flervalg', 'Hvor finnes en gammel tradisjon med et tredje kjønn?', array['I Den katolske kirke', 'I Sør-Asia', 'I ortodoks jødedom', 'I Skandinavia']::text[], 1, 'Tradisjonen har også plass i hinduistiske fortellinger.', true, true, 6),
  ('krle-10:kjonn-og-seksualitet', 'q08', 'flervalg', 'Hvordan har ekteskapsloven vært siden 2009?', array['Bare for mann og kvinne', 'Bare for kristne', 'Kjønnsnøytral', 'Avskaffet']::text[], 2, 'To av samme kjønn kan gifte seg i Norge.', true, true, 7),
  ('krle-10:kjonn-og-seksualitet', 'q09', 'flervalg', 'Hvilken rett har trossamfunn i Norge?', array['Å sette norsk lov til side', 'Å straffe medlemmene sine', 'Å bestemme hvem som blir statsminister', 'Å bestemme hvem de vil vie, og hvem som kan være religiøse ledere']::text[], 3, 'Dette er et unntak fra diskrimineringsloven for religiøse spørsmål.', true, false, 8),
  ('krle-10:kjonn-og-seksualitet', 'q10', 'flervalg', 'Hvorfor er det viktig å huske mangfoldet innenfor hver religion?', array['Fordi troende i samme religion kan mene svært ulike ting', 'Fordi alle religioner er like', 'Fordi religioner aldri endrer seg', 'Fordi bare lederne har meninger']::text[], 0, 'Det hindrer at vi generaliserer om alle troende.', true, false, 9),
  ('krle-10:kjonn-og-seksualitet', 'm01', 'sant-usant', 'Rosemarie Köhn ble Den norske kirkes første kvinnelige biskop i 1993.', array['Sant', 'Usant']::text[], 0, 'Hun ble biskop i Hamar.', false, true, 10),
  ('krle-10:kjonn-og-seksualitet', 'm02', 'sant-usant', 'Alle muslimer har nøyaktig samme syn på kvinners rolle.', array['Sant', 'Usant']::text[], 1, 'Det finnes stort mangfold av syn blant muslimer.', false, true, 11),
  ('krle-10:kjonn-og-seksualitet', 'm03', 'sant-usant', 'Reformjødedommen har kvinnelige rabbinere.', array['Sant', 'Usant']::text[], 0, 'Ortodoks jødedom har bare mannlige rabbinere.', false, true, 12),
  ('krle-10:kjonn-og-seksualitet', 'm04', 'sant-usant', 'Norske lover gjelder ikke for medlemmer av trossamfunn.', array['Sant', 'Usant']::text[], 1, 'Norske lover gjelder for alle, men trossamfunn har visse unntak i religiøse spørsmål.', false, true, 13),
  ('krle-10:kjonn-og-seksualitet', 'm05', 'flervalg', 'Hva åpnet paven for i 2023?', array['At kvinner kan bli prester', 'At prester kan velsigne likekjønnede par', 'At likekjønnede par kan vies', 'At prester kan gifte seg']::text[], 1, 'Velsignelse er ikke det samme som vigsel, og ordningen er omstridt i kirken.', false, true, 14),
  ('krle-10:kjonn-og-seksualitet', 'm06', 'flervalg', 'Hva er samtykke?', array['Et frivillig og tydelig ja', 'En religiøs regel', 'En type ekteskap', 'Et løfte i kirken']::text[], 0, 'Samtykke er grunnleggende for all seksuell kontakt.', false, true, 15),
  ('krle-10:kjonn-og-seksualitet', 'm07', 'flervalg', 'Hva sier norsk lov om diskriminering på grunn av seksuell orientering?', array['At det er lov i alle sammenhenger', 'At det er lov for arbeidsgivere', 'At det er forbudt', 'At det bare er forbudt i skolen']::text[], 2, 'Likestillings- og diskrimineringsloven forbyr slik diskriminering.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-10:kjonn-og-seksualitet', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-10:kjonn-og-seksualitet', 's01', 'Hva betyr «kjønnsroller»? Forklar hva slike roller sier om kvinner og menn.', 'Kjønnsroller er forventninger til hvordan kvinner og menn skal oppføre seg, og hva de skal gjøre. Tradisjonelt har menn ofte ledet, mens kvinner har hatt ansvar for hjem og barn.', array['Forklarer at kjønnsroller er forventninger knyttet til kjønn.', 'Viser hva forventningene kan handle om, for eksempel oppførsel, oppgaver eller ansvar.']::text[], 0),
  ('krle-10:kjonn-og-seksualitet', 's02', 'To troende i samme religion kan mene forskjellig om kjønn og seksualitet. Forklar hvordan ulike måter å forstå hellige tekster på og ulik vekt på tradisjon, fornuft eller menneskerettigheter kan føre til uenighet.', 'Troende kan tolke de samme hellige tekstene på ulike måter. De kan også legge ulik vekt på tradisjon, fornuft og menneskerettigheter, og derfor komme til forskjellige syn.', array['Forklarer at ulike tolkninger av hellige tekster kan gi ulike syn.', 'Knytter uenigheten til at tradisjon, fornuft eller menneskerettigheter kan vektlegges ulikt.']::text[], 1),
  ('krle-10:kjonn-og-seksualitet', 's03', 'Sammenlign hvem som kan være rabbiner i ortodoks jødedom og reformjødedom.', 'I ortodoks jødedom er rabbinerne menn. I reformjødedommen finnes det også kvinnelige rabbinere.', array['Får fram at ortodoks jødedom har mannlige rabbinere.', 'Får fram at reformjødedommen har kvinnelige rabbinere.']::text[], 2),
  ('krle-10:kjonn-og-seksualitet', 's04', 'Sammenlign synet på seksualitet i mange religiøse tradisjoner med synet til retninger og enkeltpersoner som mener at samliv er et privat ansvar.', 'I mange religiøse tradisjoner blir ekteskap mellom mann og kvinne sett på som den rette rammen for seksualitet. Andre retninger og enkeltpersoner mener at samliv er et privat ansvar, der gjensidig respekt og samtykke er viktigst.', array['Beskriver synet om at ekteskap mellom mann og kvinne er den rette rammen for seksualitet.', 'Forklarer at andre legger vekt på privat ansvar, gjensidig respekt og samtykke.']::text[], 3),
  ('krle-10:kjonn-og-seksualitet', 's05', 'En person sier ja til sex fordi partneren presser på, selv om personen egentlig ikke vil. Bruk begrepet samtykke til å forklare hvorfor dette ikke er et frivillig ja.', 'Samtykke er et frivillig og tydelig ja. Når personen sier ja på grunn av press og egentlig ikke vil, er det ikke et frivillig samtykke.', array['Forklarer at samtykke må være frivillig.', 'Knytter presset og personens egentlige ønske til hvorfor situasjonen ikke viser samtykke.']::text[], 4),
  ('krle-10:kjonn-og-seksualitet', 's06', 'Et likekjønnet par spør en katolsk prest om å vie dem i en egen seremoni. Forklar hva presten kan tilby ifølge Den katolske kirkes regler om velsignelse, og hva presten ikke kan gjøre.', 'Presten kan gi paret en kort og uformell velsignelse, men ikke vie dem. Velsignelsen skal ikke være en egen seremoni eller gjøres til et ritual.', array['Skiller mellom at paret kan få en velsignelse og at presten ikke kan vie dem.', 'Får fram at velsignelsen skal være kort og uformell, ikke en egen seremoni eller et ritual.']::text[], 5),
  ('krle-10:kjonn-og-seksualitet', 's07', 'To personer av samme kjønn vil gifte seg i Norge, men et trossamfunn sier at det ikke vil vie dem. Forklar hvordan dette kan være mulig etter norske regler.', 'Norsk ekteskapslov gir to personer av samme kjønn rett til å gifte seg. Samtidig kan trossamfunn selv bestemme hvem de vil vie, så paret kan gifte seg uten å bli viet av akkurat dette trossamfunnet.', array['Forklarer at norsk lov åpner for ekteskap mellom to av samme kjønn.', 'Forklarer at trossamfunn selv kan bestemme hvem de vier.']::text[], 6),
  ('krle-10:kjonn-og-seksualitet', 's08', 'Mange muslimer mener at kvinner og menn er likeverdige, men har ulike roller. Forklar hvordan muslimske feminister utfordrer eller endrer dette synet.', 'Muslimske feminister tolker Koranen på nye måter og krever større likestilling. Dermed kan de utfordre synet om at kvinner og menn skal ha ulike roller.', array['Får fram at muslimske feminister tolker Koranen på nye måter.', 'Forklarer at de krever større likestilling eller utfordrer ulike kjønnsroller.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-10:eksistensielle-sporsmal', 'krle-10', 'eksistensielle-sporsmal', 'Eksistensielle spørsmål', 'De store spørsmålene om mening, frihet, lidelse og død, svar fra religioner, livssyn og eksistensialistiske filosofer, og hva det vil si å vokse opp i et mangfoldig og globalt samfunn.', array[13]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-10:eksistensielle-sporsmal', '## Hva er eksistensielle spørsmål?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-10:eksistensielle-sporsmal', 'Eksistensielle spørsmål', 'De store spørsmålene om mening, frihet, lidelse og død.', 0),
  ('krle-10:eksistensielle-sporsmal', 'Kristent svar', 'Mennesket er skapt og elsket av Gud, med håp om evig liv.', 1),
  ('krle-10:eksistensielle-sporsmal', 'Islamsk svar', 'Livet er en prøve fra Gud, og dommens dag avgjør det som skjer etter døden.', 2),
  ('krle-10:eksistensielle-sporsmal', 'Moksha og nirvana', 'Frigjøring fra gjenfødelsene i hinduisme og buddhisme.', 3),
  ('krle-10:eksistensielle-sporsmal', 'Humanistisk svar', 'Vi har ett liv og skaper mening selv, blant annet gjennom relasjoner.', 4),
  ('krle-10:eksistensielle-sporsmal', 'Eksistensialisme', 'Filosofisk retning om menneskets frihet, valg og ansvar.', 5),
  ('krle-10:eksistensielle-sporsmal', 'Søren Kierkegaard', 'Dansk filosof (1813–1855) som skrev om valg, ansvar og angst.', 6),
  ('krle-10:eksistensielle-sporsmal', 'Jean-Paul Sartre', 'Fransk filosof som mente at mennesket er «dømt til å være fritt».', 7),
  ('krle-10:eksistensielle-sporsmal', '«Eksistensen går forut for essensen»', 'Vi er ikke født med en ferdig mening, men skaper oss selv gjennom valg.', 8),
  ('krle-10:eksistensielle-sporsmal', 'Det absurde', 'Camus'' begrep om at vi søker mening i en verden som ikke gir klare svar.', 9),
  ('krle-10:eksistensielle-sporsmal', 'Identitet i et mangfoldig samfunn', 'Mange vokser opp med flere kulturer og kan høre til flere steder.', 10),
  ('krle-10:eksistensielle-sporsmal', 'Framtidsangst', 'Uro for framtiden, for eksempel på grunn av krig eller klimaendringer.', 11),
  ('krle-10:eksistensielle-sporsmal', 'Livskrise', 'Vanskelig periode, for eksempel etter sorg, tap eller sykdom.', 12),
  ('krle-10:eksistensielle-sporsmal', 'Alarmtelefonen for barn og unge', 'Gratis hjelpetelefon: 116 111.', 13),
  ('krle-10:eksistensielle-sporsmal', 'Mental Helses hjelpetelefon', 'Gratis hjelpetelefon for alle som trenger noen å snakke med: 116 123.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-10:eksistensielle-sporsmal', 'q01', 'flervalg', 'Hva er et eksistensielt spørsmål?', array['Hva er klokka?', 'Hva koster en bussbillett?', 'Hva er meningen med livet?', 'Hvilken dag er det i dag?']::text[], 2, 'Eksistensielle spørsmål handler om de store sidene ved det å være menneske.', true, true, 0),
  ('krle-10:eksistensielle-sporsmal', 'q02', 'flervalg', 'Hva sa Sartre om menneskets frihet?', array['At vi er «dømt til å være frie»', 'At alt er forutbestemt', 'At bare Gud er fri', 'At frihet ikke finnes']::text[], 0, 'Ifølge Sartre kan vi ikke unngå å velge, og vi har ansvar for valgene våre.', true, true, 1),
  ('krle-10:eksistensielle-sporsmal', 'q03', 'flervalg', 'Hvordan svarer livssynshumanismen på spørsmålet om meningen med livet?', array['At meningen er gitt av Gud', 'At vi selv skaper mening, for eksempel gjennom relasjoner og å hjelpe andre', 'At livet ikke har noen mening', 'At meningen er å bli gjenfødt']::text[], 1, 'Humanister mener at mening skapes av mennesker.', true, true, 2),
  ('krle-10:eksistensielle-sporsmal', 'q04', 'flervalg', 'Hvem var Søren Kierkegaard?', array['En norsk prest', 'En tysk fysiker', 'En fransk forfatter', 'En dansk filosof som skrev om valg, ansvar og angst']::text[], 3, 'Kierkegaard regnes som en forløper for eksistensialismen.', true, true, 3),
  ('krle-10:eksistensielle-sporsmal', 'q05', 'flervalg', 'Hva betyr «eksistensen går forut for essensen»?', array['At Gud skapte alt', 'At vi ikke er født med en ferdig mening, men skaper oss selv gjennom valg', 'At alt er bestemt på forhånd', 'At bare essensen betyr noe']::text[], 1, 'Først finnes vi, så blir vi den vi er gjennom det vi gjør.', true, true, 4),
  ('krle-10:eksistensielle-sporsmal', 'q06', 'flervalg', 'Hvordan ser islam på livet?', array['Som en drøm', 'Som en tilfeldighet', 'Som en prøve fra Gud', 'Som ett av mange liv i samsara']::text[], 2, 'Hvordan man lever, har betydning på dommens dag.', true, true, 5),
  ('krle-10:eksistensielle-sporsmal', 'q07', 'flervalg', 'Hva mente Albert Camus med det absurde?', array['At livet bare er morsomt', 'At vi ikke bør bry oss om noe', 'At Gud styrer alt', 'At vi søker mening i en verden som ikke gir klare svar']::text[], 3, 'Camus mente vi likevel kan leve fullt og engasjert.', true, true, 6),
  ('krle-10:eksistensielle-sporsmal', 'q08', 'flervalg', 'Hvilken utfordring kan sosiale medier gi?', array['Sammenligning og følelsen av å ikke være god nok', 'At man lærer for mye', 'At man får for lite fritid', 'Ingen utfordringer']::text[], 0, 'Det man ser på sosiale medier, er ofte et redigert bilde av livet.', true, true, 7),
  ('krle-10:eksistensielle-sporsmal', 'q09', 'flervalg', 'Hva kan du gjøre hvis du går gjennom en livskrise?', array['Holde alt for deg selv', 'Unngå alle andre', 'Snakke med noen du stoler på eller ringe en hjelpetelefon', 'Late som ingenting']::text[], 2, 'Det hjelper ofte å dele tankene med noen.', true, false, 8),
  ('krle-10:eksistensielle-sporsmal', 'q10', 'flervalg', 'Hva er målet i hinduisme og buddhisme?', array['Å bli rik', 'Frigjøring fra gjenfødelsene, moksha eller nirvana', 'Å leve evig på jorda', 'Å få mange barn']::text[], 1, 'Begge religionene ser livet som en del av et kretsløp.', true, false, 9),
  ('krle-10:eksistensielle-sporsmal', 'm01', 'sant-usant', 'Eksistensielle spørsmål har ett riktig fasitsvar.', array['Sant', 'Usant']::text[], 1, 'Religioner, livssyn og enkeltmennesker svarer ulikt.', false, true, 10),
  ('krle-10:eksistensielle-sporsmal', 'm02', 'sant-usant', 'Mange som vokser opp med flere kulturer, kan oppleve å høre til flere steder.', array['Sant', 'Usant']::text[], 0, 'Det kan være både en styrke og en utfordring.', false, true, 11),
  ('krle-10:eksistensielle-sporsmal', 'm03', 'sant-usant', 'Klimaendringer kan gi både framtidsangst og engasjement.', array['Sant', 'Usant']::text[], 0, 'Mange unge engasjerer seg for klimaet.', false, true, 12),
  ('krle-10:eksistensielle-sporsmal', 'm04', 'sant-usant', 'Det er uvanlig å tenke på døden og meningen med livet i ungdomstiden.', array['Sant', 'Usant']::text[], 1, 'Ungdomstiden er en periode der mange tenker mye over slike spørsmål.', false, true, 13),
  ('krle-10:eksistensielle-sporsmal', 'm05', 'flervalg', 'Hvilket nummer har Alarmtelefonen for barn og unge?', array['112', '116 111', '113', '110']::text[], 1, 'Telefonen er gratis og åpen for barn og unge som trenger hjelp.', false, true, 14),
  ('krle-10:eksistensielle-sporsmal', 'm06', 'flervalg', 'Hva er et kristent svar på hva som skjer etter døden?', array['Håp om evig liv', 'Gjenfødelse som dyr', 'At ingenting skjer', 'At man blir en ånd i naturen']::text[], 0, 'Håpet bygger på troen på Jesu oppstandelse.', false, true, 15),
  ('krle-10:eksistensielle-sporsmal', 'm07', 'flervalg', 'Hva mente Kierkegaard at friheten til å velge kan skape?', array['Bare glede', 'Kjedsomhet', 'Angst', 'Rikdom']::text[], 2, 'Når vi selv må velge, kjenner vi på ansvaret.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-10:eksistensielle-sporsmal', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-10:eksistensielle-sporsmal', 's01', 'En kristen og en muslim blir spurt om hva som skjer etter døden. Forklar en viktig forskjell mellom svarene deres.', 'Kristne har håp om evig liv. I islam avgjør dommens dag hva som skjer etter døden.', array['Får fram kristendommens håp om evig liv.', 'Får fram at dommens dag avgjør hva som skjer etter døden i islam.']::text[], 0),
  ('krle-10:eksistensielle-sporsmal', 's02', 'Kierkegaard mente at mennesket må velge selv og ta ansvar for livet sitt. Forklar hvordan denne friheten kan føre til angst.', 'Når vi må velge selv, må vi også ta ansvar for valgene og livet vårt. Det ansvaret og friheten kan skape angst.', array['Knytter angsten til at mennesket selv må velge.', 'Får fram at mennesket må ta ansvar for livet eller valgene sine.']::text[], 1),
  ('krle-10:eksistensielle-sporsmal', 's03', 'En person leter etter mening, men opplever at verden ikke gir klare svar. Bruk Camus’ begrep «det absurde» til å forklare situasjonen, og si hvordan Camus mente personen likevel kan leve.', 'Det absurde handler om at vi søker mening i en verden som ikke gir klare svar. Camus mente at vi likevel kan leve fullt og engasjert.', array['Forklarer motsetningen mellom å søke mening og ikke få klare svar.', 'Får fram at Camus mente vi likevel kan leve fullt og engasjert.']::text[], 2),
  ('krle-10:eksistensielle-sporsmal', 's04', 'Samir vokser opp med flere kulturer og språk og føler at han hører til flere steder. Forklar hvordan situasjonen hans viser noe ved identitet i et mangfoldig samfunn.', 'I et mangfoldig samfunn kan mennesker vokse opp med flere kulturer eller språk. De kan derfor føle tilhørighet til flere steder.', array['Får fram at flere kulturer eller språk kan prege identiteten.', 'Forklarer at en person kan oppleve tilhørighet til flere steder.']::text[], 3),
  ('krle-10:eksistensielle-sporsmal', 's05', 'En elev er urolig for klimaendringer, men begynner også å engasjere seg. Forklar sammenhengen mellom bekymringen og engasjementet.', 'Bekymring for globale utfordringer som klimaendringer kan føre til framtidsangst. Den samme uroen kan også føre til engasjement.', array['Knytter uro for klimaendringer til framtidsangst.', 'Får fram at uro for globale utfordringer også kan føre til engasjement.']::text[], 4),
  ('krle-10:eksistensielle-sporsmal', 's06', 'Etter et tap begynner en person å gruble mer over meningen med livet og døden. Forklar hvorfor eksistensielle spørsmål kan bli sterkere i en slik periode.', 'Et tap kan være en livskrise. I vanskelige perioder kan eksistensielle spørsmål bli ekstra sterke.', array['Kjenner igjen tap som en mulig livskrise.', 'Forklarer at slike vanskelige perioder kan gjøre eksistensielle spørsmål sterkere.']::text[], 5),
  ('krle-10:eksistensielle-sporsmal', 's07', 'To personer med ulike livssyn snakker sammen om hva som gir livet mening. Forklar hvordan det å lytte til hverandres svar kan være nyttig.', 'Når vi lytter til mennesker med andre livssyn, kan vi få nye perspektiver. Det kan hjelpe oss å forstå at mennesker kan finne mening på ulike måter.', array['Får fram at samtalen kan gi nye perspektiver.', 'Får fram at mennesker kan finne mening på ulike måter.']::text[], 6),
  ('krle-10:eksistensielle-sporsmal', 's08', 'Unge kan ha mange muligheter, men også press om å lykkes på skolen, se bra ut og ha venner. Forklar hvordan dette viser både frihet og press i ungdomslivet.', 'Mange muligheter gir unge frihet til å velge. Samtidig kan forventninger om å lykkes på ulike områder skape press.', array['Knytter mange muligheter til frihet eller valgmuligheter.', 'Forklarer at forventninger på flere områder kan skape press.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-10:etikk-og-kommunikasjon', 'krle-10', 'etikk-og-kommunikasjon', 'Etikk, kommunikasjon og uenighet', 'Etiske problemstillinger knyttet til sannhet, hemmeligheter og digital kommunikasjon, og hvordan du kan håndtere uenighet og kjenne igjen usaklige teknikker.', array[14, 12]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-10:etikk-og-kommunikasjon', '## Kommunikasjon og etikk
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-10:etikk-og-kommunikasjon', 'Etisk problemstilling', 'Et spørsmål om hva som er rett og galt å gjøre.', 0),
  ('krle-10:etikk-og-kommunikasjon', 'Hvit løgn', 'En liten løgn for å skåne noen.', 1),
  ('krle-10:etikk-og-kommunikasjon', 'Fortrolighet', 'Når noen forteller deg noe i tillit om at du ikke sprer det videre.', 2),
  ('krle-10:etikk-og-kommunikasjon', 'Nettmobbing', 'Gjentatt plaging, utestenging eller hets via digitale kanaler.', 3),
  ('krle-10:etikk-og-kommunikasjon', 'Samtykke til deling', 'Du må spørre før du deler bilder der andre er hovedmotivet.', 4),
  ('krle-10:etikk-og-kommunikasjon', 'Ryktespredning', 'Å spre påstander om andre som kan være usanne eller sårende.', 5),
  ('krle-10:etikk-og-kommunikasjon', 'Anonymitet', 'Å ytre seg uten navn. Kan beskytte varslere, men gjøre hets lettere.', 6),
  ('krle-10:etikk-og-kommunikasjon', 'Ytringsfrihet og ansvar', 'Retten til å si sin mening, sammen med ansvaret for hvordan ordene påvirker andre.', 7),
  ('krle-10:etikk-og-kommunikasjon', 'Meningsbrytning', 'At ulike meninger møtes og prøves mot hverandre.', 8),
  ('krle-10:etikk-og-kommunikasjon', 'Dialog og debatt', 'Dialog handler om å forstå, debatt ofte om å vinne.', 9),
  ('krle-10:etikk-og-kommunikasjon', 'Perspektivtaking', 'Å prøve å forstå hvordan den andre tenker og opplever en sak.', 10),
  ('krle-10:etikk-og-kommunikasjon', 'Jeg-budskap', 'Å si hvordan man selv opplever noe, i stedet for å anklage.', 11),
  ('krle-10:etikk-og-kommunikasjon', 'Personangrep', 'Å angripe personen i stedet for argumentet.', 12),
  ('krle-10:etikk-og-kommunikasjon', 'Stråmann', 'Å forvrenge motpartens syn og så angripe den forvrengte versjonen.', 13),
  ('krle-10:etikk-og-kommunikasjon', 'Hersketeknikk', 'Måte å undertrykke andre på, som å overse eller latterliggjøre. Gjort kjent av Berit Ås.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-10:etikk-og-kommunikasjon', 'q01', 'flervalg', 'Hva er en hvit løgn?', array['En løgn som skader mange', 'En løgn i retten', 'En løgn på nett', 'En liten løgn for å skåne noen']::text[], 3, 'Etiske teorier vurderer hvite løgner ulikt.', true, true, 0),
  ('krle-10:etikk-og-kommunikasjon', 'q02', 'flervalg', 'Hvordan vil en pliktetiker som Kant se på å lyve?', array['At det er greit hvis det gir gode følger', 'At det alltid er galt', 'At det er opp til hver enkelt', 'At det bare er galt på nett']::text[], 1, 'Kant mente at plikten til å si sannheten gjelder uansett følger.', true, true, 1),
  ('krle-10:etikk-og-kommunikasjon', 'q03', 'flervalg', 'Når kan det være riktig å bryte et løfte om å holde noe hemmelig?', array['Når hemmeligheten er kjedelig', 'Når du er sint på vennen', 'Når en venn blir utsatt for vold eller kan komme til å skade seg selv', 'Aldri']::text[], 2, 'Plikten til å hjelpe kan veie tyngre enn løftet om å tie.', true, true, 2),
  ('krle-10:etikk-og-kommunikasjon', 'q04', 'flervalg', 'Hvorfor kan terskelen for sårende kommentarer være lavere på nett?', array['Fordi vi ikke ser ansiktet og reaksjonen til mottakeren', 'Fordi alle er anonyme', 'Fordi det er lov', 'Fordi ingen leser det']::text[], 0, 'Avstanden gjør det lettere å glemme at det er et menneske på den andre siden.', true, true, 3),
  ('krle-10:etikk-og-kommunikasjon', 'q05', 'flervalg', 'Hva er forskjellen på dialog og debatt?', array['Det er ingen forskjell', 'Debatt er alltid bedre', 'Dialog handler om å forstå, debatt ofte om å vinne', 'Dialog er bare skriftlig']::text[], 2, 'Begge formene kan være nyttige i ulike situasjoner.', true, true, 4),
  ('krle-10:etikk-og-kommunikasjon', 'q06', 'flervalg', 'Hva er et stråmannsargument?', array['Et argument med mange fakta', 'Et argument om landbruk', 'Et spørsmål til motparten', 'Å forvrenge motpartens syn og så angripe det']::text[], 3, 'Det er lettere å angripe en forenklet versjon av det motparten mener.', true, true, 5),
  ('krle-10:etikk-og-kommunikasjon', 'q07', 'flervalg', 'Hva er et jeg-budskap?', array['Å snakke bare om seg selv', 'Å si hvordan man selv opplever noe, i stedet for å anklage', 'Å skrive dagbok', 'Å alltid ta ordet først']::text[], 1, 'Jeg-budskap gjør det lettere for den andre å lytte uten å gå i forsvar.', true, true, 6),
  ('krle-10:etikk-og-kommunikasjon', 'q08', 'flervalg', 'Hvem gjorde begrepet hersketeknikker kjent i Norge?', array['Berit Ås', 'Henrik Ibsen', 'Gro Harlem Brundtland', 'Sigrid Undset']::text[], 0, 'Hun beskrev fem hersketeknikker, blant annet usynliggjøring og latterliggjøring.', true, true, 7),
  ('krle-10:etikk-og-kommunikasjon', 'q09', 'flervalg', 'Hva er en etisk utfordring ved anonymitet på nett?', array['At ingen kan skrive', 'At det blir for mange innlegg', 'At alle blir mer høflige', 'At det kan gjøre det lettere å hetse andre']::text[], 3, 'Anonymitet kan likevel være viktig for varslere.', true, false, 8),
  ('krle-10:etikk-og-kommunikasjon', 'q10', 'flervalg', 'Hva sier den gylne regel om kommunikasjon?', array['Si alltid det du vil', 'Snakk til andre slik du selv vil bli snakket til', 'Svar aldri på meldinger', 'Del alt du ser']::text[], 1, 'Regelen passer like godt på nett som ansikt til ansikt.', true, false, 9),
  ('krle-10:etikk-og-kommunikasjon', 'm01', 'sant-usant', 'Ytringsfrihet betyr at man ikke har noe ansvar for det man sier.', array['Sant', 'Usant']::text[], 1, 'Med friheten følger ansvar, og noen ytringer er forbudt, som trusler.', false, true, 10),
  ('krle-10:etikk-og-kommunikasjon', 'm02', 'sant-usant', 'Latterliggjøring kan være en hersketeknikk.', array['Sant', 'Usant']::text[], 0, 'Latterliggjøring gjør at andre ikke blir tatt på alvor.', false, true, 11),
  ('krle-10:etikk-og-kommunikasjon', 'm03', 'sant-usant', 'Du trenger samtykke før du deler bilder der andre er hovedmotivet.', array['Sant', 'Usant']::text[], 0, 'Hovedregelen er at den som er avbildet, må spørres.', false, true, 12),
  ('krle-10:etikk-og-kommunikasjon', 'm04', 'sant-usant', 'Humor kan aldri være krenkende.', array['Sant', 'Usant']::text[], 1, 'Det som er morsomt for én, kan såre en annen.', false, true, 13),
  ('krle-10:etikk-og-kommunikasjon', 'm05', 'flervalg', 'Hva er perspektivtaking?', array['Å ta bilder fra ulike vinkler', 'Å prøve å forstå hvordan den andre tenker og opplever saken', 'Å alltid være enig', 'Å bytte mening ofte']::text[], 1, 'Perspektivtaking gjør det lettere å håndtere uenighet.', false, true, 14),
  ('krle-10:etikk-og-kommunikasjon', 'm06', 'flervalg', 'Hva er et personangrep i en diskusjon?', array['Å angripe personen i stedet for argumentet', 'Å gi ros', 'Å stille spørsmål', 'Å vise til fakta']::text[], 0, 'Personangrep svarer ikke på saken.', false, true, 15),
  ('krle-10:etikk-og-kommunikasjon', 'm07', 'flervalg', 'Hva er meningsbrytning?', array['At man slutter å snakke sammen', 'At alle mener det samme', 'At ulike meninger møtes og prøves mot hverandre', 'At man bryter et løfte']::text[], 2, 'Meningsbrytning er en viktig del av demokratiet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-10:etikk-og-kommunikasjon', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-10:etikk-og-kommunikasjon', 's01', 'Forklar hvordan ærlighet kan bidra til tillit mellom mennesker, og hvorfor det også betyr noe hvordan man sier sannheten.', 'Ærlighet gjør det lettere å stole på hverandre. Samtidig kan måten sannheten blir sagt på, påvirke om den andre blir såret eller føler seg respektert.', array['Forklarer at ærlighet kan bygge eller bevare tillit.', 'Forklarer at måten sannheten uttrykkes på kan påvirke den andre.']::text[], 0),
  ('krle-10:etikk-og-kommunikasjon', 's02', 'Du vil dele et bilde på sosiale medier der en medelev er hovedmotivet. Hva må du gjøre først, og hvorfor?', 'Du må spørre medelevens samtykke før du deler bildet. Personen bør få bestemme om bildet av dem skal deles.', array['Sier at man må spørre om samtykke før bildet deles.', 'Forklarer at personen på bildet skal få bestemme over delingen.']::text[], 1),
  ('krle-10:etikk-og-kommunikasjon', 's03', 'En elev blir utestengt og plaget flere ganger i en gruppechat. Forklar hvorfor dette kan kalles nettmobbing.', 'Det kan kalles nettmobbing fordi plagingen eller utestengingen skjer gjentatte ganger gjennom en digital kanal. Det er ikke bare en enkelt ubehagelig kommentar.', array['Får fram at handlingene skjer gjentatte ganger.', 'Får fram at plaging eller utestenging skjer via en digital kanal.']::text[], 2),
  ('krle-10:etikk-og-kommunikasjon', 's04', 'Forklar hvorfor det er viktig at ulike meninger møtes i et demokrati, og nevn én måte å håndtere uenighet på en god måte.', 'Når ulike meninger prøves mot hverandre, kan folk få fram flere syn på en sak. Uenigheten bør håndteres med saklige argumenter og ved å unngå personangrep.', array['Forklarer at ulike meninger som møtes og prøves mot hverandre, er viktig i et demokrati.', 'Nevner en god måte å håndtere uenighet på, for eksempel saklige argumenter eller å skille sak fra person.']::text[], 3),
  ('krle-10:etikk-og-kommunikasjon', 's05', 'Du vil legge ut en kritisk kommentar om en beslutning på skolen. Forklar hvordan både ytringsfrihet og ansvar gjelder i denne situasjonen.', 'Ytringsfriheten gir deg rett til å si hva du mener om beslutningen. Samtidig har du ansvar for hvordan ordene dine påvirker andre, så kritikken bør ikke brukes til å såre eller hetse noen.', array['Får fram at ytringsfrihet gir rett til å uttrykke en mening.', 'Får fram at man også har ansvar for hvordan ordene påvirker andre.']::text[], 4),
  ('krle-10:etikk-og-kommunikasjon', 's06', 'I en diskusjon om en regel sier en elev: «Du er så dum at du ikke skjønner hvorfor regelen er nødvendig.» Forklar hva som er usaklig med dette, og skriv om kritikken slik at den retter seg mot saken.', 'Utsagnet er et personangrep fordi det angriper eleven i stedet for argumentet. En saklig kritikk kan for eksempel være: «Jeg mener regelen ikke er nødvendig fordi den ikke løser problemet.»', array['Forklarer at utsagnet angriper personen, ikke argumentet eller saken.', 'Gir en omskriving som kritiserer regelen eller argumentet uten å angripe personen.']::text[], 5),
  ('krle-10:etikk-og-kommunikasjon', 's07', 'En elev sprer en påstand om en medelev uten å vite om den er sann. Forklar hvorfor dette kan være skadelig, og hva eleven heller bør gjøre.', 'Påstanden kan være ryktespredning og kan såre eller skade medeleven, særlig hvis den er usann. Eleven bør la være å spre den videre og undersøke om den stemmer før noe sies videre.', array['Forklarer at påstanden kan være usann eller sårende og skade personen det gjelder.', 'Foreslår å ikke spre påstanden videre, for eksempel å undersøke om den stemmer først.']::text[], 6),
  ('krle-10:etikk-og-kommunikasjon', 's08', 'To elever er uenige om en sak, og begge føler at den andre ikke forstår dem. Beskriv hva den ene kan gjøre for å prøve å forstå den andres syn, og hvorfor det kan hjelpe.', 'Eleven kan lytte aktivt og prøve å se saken fra den andres perspektiv ved å spørre hvorfor den andre mener dette. Da kan de bedre forstå hverandres opplevelser og snakke videre om uenigheten.', array['Foreslår aktiv lytting eller å prøve å forstå den andres perspektiv.', 'Forklarer at dette kan gi bedre forståelse av den andres syn eller opplevelse.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('krle-10:filosofi-og-aktuell-etikk', 'krle-10', 'filosofi-og-aktuell-etikk', 'Filosofer og aktuelle etiske spørsmål', 'Etiske ideer fra filosofer fra antikken til i dag, og hvordan ideene kan brukes til å drøfte aktuelle spørsmål om dyr, kunstig intelligens og klima.', array[11]::int[], 4, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('krle-10:filosofi-og-aktuell-etikk', '## Filosofer og de store spørsmålene
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('krle-10:filosofi-og-aktuell-etikk', 'Sokrates', 'Gresk filosof som stilte spørsmål for å få folk til å tenke selv.', 0),
  ('krle-10:filosofi-og-aktuell-etikk', '«Et uransaket liv er ikke verdt å leve»', 'Sokrates'' tanke om at vi må tenke over hvordan vi lever.', 1),
  ('krle-10:filosofi-og-aktuell-etikk', 'Platon', 'Sokrates'' elev, som mente det finnes et evig og uforanderlig gode.', 2),
  ('krle-10:filosofi-og-aktuell-etikk', 'Aristoteles og lykke', 'Målet med livet er et godt og meningsfullt liv, nådd gjennom dyder.', 3),
  ('krle-10:filosofi-og-aktuell-etikk', 'Epikur', 'Mente at lykke er fravær av smerte og uro.', 4),
  ('krle-10:filosofi-og-aktuell-etikk', 'Kant og menneskeverd', 'Mennesker skal behandles som mål i seg selv, aldri bare som middel.', 5),
  ('krle-10:filosofi-og-aktuell-etikk', 'Skadeprinsippet', 'Mills prinsipp: Friheten bør bare begrenses for å hindre skade på andre.', 6),
  ('krle-10:filosofi-og-aktuell-etikk', 'Hannah Arendt', 'Filosof som skrev om ondskapens banalitet etter Eichmann-rettssaken.', 7),
  ('krle-10:filosofi-og-aktuell-etikk', 'Ondskapens banalitet', 'At vanlige mennesker kan gjøre store forbrytelser ved å slutte å tenke selv.', 8),
  ('krle-10:filosofi-og-aktuell-etikk', 'K.E. Løgstrup', 'Dansk filosof som skrev om den etiske fordring.', 9),
  ('krle-10:filosofi-og-aktuell-etikk', 'Den etiske fordring', 'Vi har alltid noe av et annet menneskes liv i våre hender.', 10),
  ('krle-10:filosofi-og-aktuell-etikk', 'Peter Singer', 'Filosof som mener dyrs lidelse teller, og at rike har plikt til å hjelpe fattige.', 11),
  ('krle-10:filosofi-og-aktuell-etikk', 'Dyreetikk', 'Spørsmål om hvordan vi bør behandle dyr.', 12),
  ('krle-10:filosofi-og-aktuell-etikk', 'KI-etikk', 'Spørsmål om ansvar, personvern og menneskeverd ved bruk av kunstig intelligens.', 13),
  ('krle-10:filosofi-og-aktuell-etikk', 'Å drøfte', 'Å veie argumenter fra flere sider og komme fram til en begrunnet konklusjon.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('krle-10:filosofi-og-aktuell-etikk', 'q01', 'flervalg', 'Hvordan arbeidet Sokrates?', array['Han stilte spørsmål for å få folk til å tenke selv', 'Han skrev mange bøker', 'Han var konge i Athen', 'Han bygde templer']::text[], 0, 'Det vi vet om Sokrates, kommer i stor grad fra eleven Platon.', true, true, 0),
  ('krle-10:filosofi-og-aktuell-etikk', 'q02', 'flervalg', 'Hva sier Mills skadeprinsipp?', array['At man alltid skal si sannheten', 'At dyr har samme verdi som mennesker', 'At lykke er fravær av smerte', 'At staten bare bør begrense friheten for å hindre skade på andre']::text[], 3, 'Prinsippet brukes ofte i debatter om forbud og frihet.', true, true, 1),
  ('krle-10:filosofi-og-aktuell-etikk', 'q03', 'flervalg', 'Hva mente Hannah Arendt med ondskapens banalitet?', array['At onde mennesker er sjeldne', 'At ondskap alltid er lett å oppdage', 'At vanlige mennesker kan gjøre store forbrytelser ved å slutte å tenke selv', 'At ondskap er morsomt']::text[], 2, 'Arendt mente Eichmann ikke var et monster, men en byråkrat som fulgte ordre.', true, true, 2),
  ('krle-10:filosofi-og-aktuell-etikk', 'q04', 'flervalg', 'Hva er den etiske fordring hos Løgstrup?', array['At man alltid må følge loven', 'At vi alltid har noe av et annet menneskes liv i våre hender', 'At man skal søke egen lykke', 'At dyr er viktigere enn mennesker']::text[], 1, 'Møtet med et annet menneske gir oss ansvar.', true, true, 3),
  ('krle-10:filosofi-og-aktuell-etikk', 'q05', 'flervalg', 'Hva mente Epikur at lykke er?', array['Rikdom og makt', 'Å vinne diskusjoner', 'Å leve i kloster', 'Fravær av smerte og uro']::text[], 3, 'Epikur anbefalte vennskap og enkle gleder.', true, true, 4),
  ('krle-10:filosofi-og-aktuell-etikk', 'q06', 'flervalg', 'Hvilken filosof mener at dyrs lidelse må telle like mye som menneskers lignende lidelse?', array['Peter Singer', 'Immanuel Kant', 'Platon', 'Sokrates']::text[], 0, 'Singer er en av de mest kjente dyreetikerne.', true, true, 5),
  ('krle-10:filosofi-og-aktuell-etikk', 'q07', 'flervalg', 'Hva betyr det å drøfte et spørsmål?', array['Å gi et kort svar', 'Å gjenta det læreren sier', 'Å veie argumenter fra flere sider og komme fram til en begrunnet konklusjon', 'Å bare si sin egen mening']::text[], 2, 'Drøfting krever at man tar motargumenter på alvor.', true, true, 6),
  ('krle-10:filosofi-og-aktuell-etikk', 'q08', 'flervalg', 'Hvilken etisk utfordring knyttes til kunstig intelligens?', array['At den ikke kan regne', 'Hvem som har ansvaret når den gjør feil', 'At den er for treg', 'At den bare virker på engelsk']::text[], 1, 'Ansvar er vanskelig å plassere når en maskin tar avgjørelser.', true, true, 7),
  ('krle-10:filosofi-og-aktuell-etikk', 'q09', 'flervalg', 'Hvordan kan Kants ideer brukes i debatten om KI?', array['Til å si at KI alltid er god', 'Til å si at KI skal bestemme alt', 'Til å si at menneskeverd ikke betyr noe', 'Til å kreve at mennesker aldri bare behandles som data']::text[], 3, 'Kants tanke om menneskeverd kan brukes som et krav til teknologien.', true, false, 8),
  ('krle-10:filosofi-og-aktuell-etikk', 'q10', 'flervalg', 'Hva mente Aristoteles er målet med livet?', array['Rikdom', 'Makt', 'Lykke i betydningen et godt og meningsfullt liv', 'Å klare seg uten andre']::text[], 2, 'Aristoteles mente vi når lykke ved å utvikle gode dyder.', true, false, 9),
  ('krle-10:filosofi-og-aktuell-etikk', 'm01', 'sant-usant', 'Sokrates mente at det er bedre å lide urett enn å gjøre urett.', array['Sant', 'Usant']::text[], 0, 'Tanken er kjent fra Platons dialoger.', false, true, 10),
  ('krle-10:filosofi-og-aktuell-etikk', 'm02', 'sant-usant', 'Filosofiske ideer gir fasitsvar på alle aktuelle etiske spørsmål.', array['Sant', 'Usant']::text[], 1, 'Ideene gir verktøy for å tenke, men ikke ferdige svar.', false, true, 11),
  ('krle-10:filosofi-og-aktuell-etikk', 'm03', 'sant-usant', 'Hannah Arendt fulgte rettssaken mot Adolf Eichmann.', array['Sant', 'Usant']::text[], 0, 'Rettssaken ble holdt i Jerusalem i 1961.', false, true, 12),
  ('krle-10:filosofi-og-aktuell-etikk', 'm04', 'sant-usant', 'Løgstrup mente at vi ikke har ansvar for andre mennesker.', array['Sant', 'Usant']::text[], 1, 'Løgstrup mente tvert imot at møtet med den andre gir oss ansvar.', false, true, 13),
  ('krle-10:filosofi-og-aktuell-etikk', 'm05', 'flervalg', 'Hvem var elev av Sokrates?', array['Kant', 'Platon', 'Mill', 'Singer']::text[], 1, 'Platon skrev ned mange samtaler med Sokrates.', false, true, 14),
  ('krle-10:filosofi-og-aktuell-etikk', 'm06', 'flervalg', 'Hvilket argument kan brukes for å spise mindre kjøtt?', array['At det reduserer dyrs lidelse og klimagassutslipp', 'At kjøtt er dyrt', 'At dyr ikke kan føle smerte', 'At det er påbudt']::text[], 0, 'Både dyreetikk og klimahensyn trekkes inn i debatten.', false, true, 15),
  ('krle-10:filosofi-og-aktuell-etikk', 'm07', 'flervalg', 'Hvilken tanke kan brukes for å argumentere for at vi har ansvar for framtidige generasjoner?', array['At bare de som lever nå, teller', 'At klimaet ikke påvirker mennesker', 'At følgene for alle som berøres, må tas med', 'At framtiden ikke kan påvirkes']::text[], 2, 'Konsekvensetikken tar hensyn til alle som påvirkes av en handling.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('krle-10:filosofi-og-aktuell-etikk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('krle-10:filosofi-og-aktuell-etikk', 's01', 'Platon mente at det finnes et evig og uforanderlig gode, og at et rettferdig samfunn bør ledes av kloke mennesker. Forklar hvorfor Platon kan mene at kloke ledere er viktige for rettferdigheten.', 'Platon kan mene at kloke ledere forstår det gode og derfor kan styre samfunnet i en rettferdig retning.', array['Knytter klokskap til forståelse av det gode.', 'Forklarer at dette kan hjelpe lederne å styre rettferdig.']::text[], 0),
  ('krle-10:filosofi-og-aktuell-etikk', 's02', 'Sokrates mente at «et uransaket liv ikke er verdt å leve». En elev har såret en venn og lurer på om hen bør si unnskyld. Forklar hvordan Sokrates’ tanke kan hjelpe eleven med valget.', 'Eleven bør tenke gjennom hva hen gjorde, og vurdere om handlingen var rett. Å undersøke egne valg kan hjelpe eleven med å ta ansvar og bestemme seg for om hen bør si unnskyld.', array['Viser at eleven bør undersøke eller tenke gjennom egne handlinger.', 'Knytter dette til å ta et gjennomtenkt valg om unnskyldning.']::text[], 1),
  ('krle-10:filosofi-og-aktuell-etikk', 's03', 'Sammenlign Aristoteles’ og Epikurs syn på lykke. Hva er én viktig forskjell mellom synene deres?', 'Aristoteles mente at lykke er et godt og meningsfullt liv som nås ved å utvikle dyder. Epikur mente at lykke er fravær av smerte og uro, og la vekt på blant annet vennskap, enkle gleder og måtehold.', array['Beskriver Aristoteles’ lykke som et godt og meningsfullt liv knyttet til dyder.', 'Beskriver Epikurs lykke som fravær av smerte og uro, eller trekker fram hans vekt på enkle gleder og måtehold.']::text[], 2),
  ('krle-10:filosofi-og-aktuell-etikk', 's04', 'En elev bruker en medelevs arbeid i et gruppeprosjekt uten å spørre, bare for selv å få en bedre vurdering. Hvordan kan Kant sitt syn på menneskeverd brukes til å forklare hva som er galt, og hva eleven heller bør gjøre?', 'Kant ville mene at eleven behandler medelevens arbeid som et middel for egen vinning, ikke som et menneske med egne rettigheter. Eleven bør spørre om lov og respektere medelevens valg.', array['Forklarer at medelevens arbeid eller person blir brukt bare for elevens egen fordel.', 'Foreslår å respektere medelevens valg, for eksempel ved å spørre først.']::text[], 3),
  ('krle-10:filosofi-og-aktuell-etikk', 's05', 'En person har god råd og vurderer å gi noe av pengene sine til mennesker som er fattige. Hvilken plikt ville Peter Singer mene at personen har, og hvorfor?', 'Singer mener at rike mennesker har plikt til å hjelpe fattige. Personen bør derfor bruke noe av det hen har til å hjelpe mennesker som trenger det.', array['Får fram at Singer mener rike har plikt til å hjelpe fattige.', 'Knytter plikten til at andre mennesker trenger hjelp.']::text[], 4),
  ('krle-10:filosofi-og-aktuell-etikk', 's06', 'Noen mener at mennesker har større verdi enn dyr, men at vi likevel bør behandle dyr godt. Forklar hvordan disse to synspunktene kan henge sammen.', 'Man kan mene at mennesker har større verdi enn dyr, samtidig som dyr kan lide og derfor fortjener god behandling. Menneskers større verdi betyr ikke at det er greit å påføre dyr unødvendig lidelse.', array['Skiller mellom å mene at mennesker har større verdi og å mene at dyr fortjener god behandling.', 'Forklarer at dyr likevel kan lide eller at mennesker derfor har ansvar for hvordan de behandles.']::text[], 5),
  ('krle-10:filosofi-og-aktuell-etikk', 's07', 'Forklar hvordan både Løgstrups etiske fordring og hensynet til konsekvensene for alle som berøres, kan brukes som argument for å kutte utslipp i dag av hensyn til framtidige generasjoner.', 'Løgstrups etiske fordring handler om at vi har ansvar fordi noe av andres liv er i våre hender. Framtidige generasjoner blir berørt av utslipp, og derfor kan både ansvar for andre og hensynet til konsekvensene støtte at vi kutter utslipp nå.', array['Knytter Løgstrups etiske fordring til ansvar for andre mennesker.', 'Forklarer at framtidige generasjoner blir berørt av utslipp, slik at konsekvensene gir grunn til å kutte dem.']::text[], 6),
  ('krle-10:filosofi-og-aktuell-etikk', 's08', 'En person følger en ordre om å skade andre uten å tenke over hva handlingen innebærer. Forklar hvordan Hannah Arendts idé om ondskapens banalitet passer til situasjonen, og hva personen burde gjøre i stedet.', 'Situasjonen passer med Arendts idé fordi vanlige mennesker kan gjøre store forbrytelser når de slutter å tenke selv og bare følger ordre. Personen burde tenke selv og vurdere handlingen før hen følger ordren.', array['Knytter situasjonen til at mennesker kan gjøre alvorlig skade ved å slutte å tenke selv og bare følge ordre.', 'Foreslår at personen tenker selv eller vurderer handlingens konsekvenser før hen handler.']::text[], 7);
