insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('spansk-10:miljo-og-samfunn', 'q01', 'flervalg', 'Hva betyr «el medio ambiente»?', array['Verden', 'Byen', 'Miljøet', 'Været']::text[], 2, 'Verden heter «el mundo».', true, true, 0),
  ('spansk-10:miljo-og-samfunn', 'q02', 'flervalg', 'Hva er «la sequía»?', array['Tørke', 'Flom', 'Snø', 'Storm']::text[], 0, '«seco» betyr tørr.', true, true, 1),
  ('spansk-10:miljo-og-samfunn', 'q03', 'flervalg', 'Hvilken fornybar energikilde er Spania blant Europas ledende land på?', array['Kull', 'Olje', 'Atomkraft', 'Solenergi']::text[], 3, 'Spania har svært mange soldager.', true, true, 2),
  ('spansk-10:miljo-og-samfunn', 'q04', 'flervalg', 'Hva betyr «reciclar»?', array['Å sykle', 'Å gjenvinne', 'Å kaste', 'Å kjøpe']::text[], 1, 'Å sykle heter «montar en bici».', true, true, 3),
  ('spansk-10:miljo-og-samfunn', 'q05', 'flervalg', 'Hva er «la deforestación» i Amazonas?', array['Planting av trær', 'En ny nasjonalpark', 'Et turistområde', 'Avskoging, at regnskogen hogges ned']::text[], 3, 'Avskoging truer både dyreliv, urfolk og klimaet.', true, true, 4),
  ('spansk-10:miljo-og-samfunn', 'q06', 'flervalg', 'Hva betyr «Deberíamos usar más el transporte público»?', array['Vi bruker aldri kollektivtransport', 'Kollektivtransport er dyrt', 'Vi burde bruke kollektivtransport mer', 'Vi må kjøre bil']::text[], 2, '«deberíamos» betyr vi burde.', true, true, 5),
  ('spansk-10:miljo-og-samfunn', 'q07', 'flervalg', 'Når fikk Spania sin demokratiske grunnlov etter Franco-diktaturet?', array['1978', '1939', '1992', '2004']::text[], 0, 'Franco døde i 1975, og overgangen til demokrati fulgte.', true, true, 6),
  ('spansk-10:miljo-og-samfunn', 'q08', 'flervalg', 'Hva betyr «Estoy en contra de …»?', array['Jeg er for …', 'Jeg er mot …', 'Jeg vet ikke om …', 'Jeg liker …']::text[], 1, '«a favor de» betyr for.', true, true, 7),
  ('spansk-10:miljo-og-samfunn', 'q09', 'flervalg', 'Hva er et stort miljøproblem i Spania om sommeren?', array['Snøskred', 'Isbreer', 'Orkaner', 'Skogbranner og tørke']::text[], 3, 'Varme somre med lite regn øker faren for branner.', true, false, 8),
  ('spansk-10:miljo-og-samfunn', 'q10', 'flervalg', 'Hva betyr «el transporte público»?', array['Kollektivtransport', 'Privatbil', 'Fly', 'Sykkel']::text[], 0, '«público» betyr offentlig.', true, false, 9),
  ('spansk-10:miljo-og-samfunn', 'm01', 'sant-usant', 'I Spania sorteres avfall i fargede containere på gata.', array['Sant', 'Usant']::text[], 0, 'Gul for emballasje, blå for papir og grønn for glass.', false, true, 10),
  ('spansk-10:miljo-og-samfunn', 'm02', 'sant-usant', 'Spania har vært et diktatur siden 1978.', array['Sant', 'Usant']::text[], 1, 'Spania har vært et demokrati siden slutten av 1970-tallet.', false, true, 11),
  ('spansk-10:miljo-og-samfunn', 'm03', 'sant-usant', 'Amazonas-regnskogen strekker seg gjennom flere land i Sør-Amerika.', array['Sant', 'Usant']::text[], 0, 'Blant annet Brasil, Peru, Colombia og Bolivia.', false, true, 12),
  ('spansk-10:miljo-og-samfunn', 'm04', 'sant-usant', '«la basura» betyr gjenvinning.', array['Sant', 'Usant']::text[], 1, '«la basura» betyr søppel.', false, true, 13),
  ('spansk-10:miljo-og-samfunn', 'm05', 'flervalg', 'Hva betyr «ahorrar agua»?', array['Å spare vann', 'Å selge vann', 'Å drikke vann', 'Å rense vann']::text[], 0, '«ahorrar» betyr å spare.', false, true, 14),
  ('spansk-10:miljo-og-samfunn', 'm06', 'flervalg', 'Hvem styrte Spania som diktator fra 1939 til 1975?', array['Kong Felipe', 'Francisco Franco', 'Pablo Picasso', 'Simón Bolívar']::text[], 1, 'Franco kom til makten etter den spanske borgerkrigen.', false, true, 15),
  ('spansk-10:miljo-og-samfunn', 'm07', 'flervalg', 'Hva betyr «Es importante reciclar»?', array['Gjenvinning er dyrt', 'Jeg liker ikke å gjenvinne', 'Det er viktig å gjenvinne', 'Man kan ikke gjenvinne']::text[], 2, '«Es importante» + infinitiv betyr det er viktig å …', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('spansk-10:miljo-og-samfunn', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('spansk-10:miljo-og-samfunn', 's01', 'Svar på spansk: Hvilken farge har containeren for plast- og metallemballasje, og hvilken farge har containeren for papir og papp?', 'Los envases de plástico y metal van al contenedor amarillo. El papel y el cartón van al contenedor azul.', array['Knytter plast- og metallemballasje til den gule containeren.', 'Knytter papir og papp til den blå containeren.']::text[], 0),
  ('spansk-10:miljo-og-samfunn', 's02', 'I Spania regner det lite, og tørke er et problem. Forklar på spansk hvorfor det er viktig å spare vann.', 'Es importante ahorrar agua porque en España llueve poco y hay sequía.', array['Forklarer at lite regn eller tørke gjør vann viktig å spare.']::text[], 1),
  ('spansk-10:miljo-og-samfunn', 's03', 'Svar på spansk: Sammenlign satsingen på solenergi og vindkraft i Spania. Ta med hva landet har mye av, og hva det satser på.', 'España tiene mucho sol y es uno de los países líderes de Europa en energía solar. También apuesta por la energía eólica.', array['Nevner at Spania har mye sol og er ledende i Europa på solenergi.', 'Nevner at Spania også satser på vindkraft.']::text[], 2),
  ('spansk-10:miljo-og-samfunn', 's04', 'Avskoging truer Amazonas-regnskogen. Forklar på spansk hva den truer, og hvem eller hva som blir berørt.', 'La deforestación amenaza la selva amazónica. Pone en peligro a los animales, a los pueblos indígenas y al clima.', array['Nevner at avskoging truer dyrelivet.', 'Nevner at den også truer urfolk eller klimaet.']::text[], 3),
  ('spansk-10:miljo-og-samfunn', 's05', 'Galápagosøyene ligger i Ecuador og har et unikt dyreliv. Forklar på spansk hvilken egenskap ved øyene som gjør beskyttelse viktig.', 'Las islas Galápagos tienen una fauna única. Por eso están estrictamente protegidas.', array['Får fram at Galápagosøyene har et unikt dyreliv.', 'Knytter det unike dyrelivet til at øyene er strengt vernet.']::text[], 4),
  ('spansk-10:miljo-og-samfunn', 's06', 'Sammenlign Spanias styre under Franco med styret etter hans død. Svar på spansk, og ta med hva slags styre landet har i dag.', 'España fue una dictadura bajo Franco de 1939 a 1975. Después de su muerte, el país se convirtió en una democracia y hoy es una monarquía constitucional.', array['Beskriver Spania under Franco som et diktatur fra 1939 til 1975.', 'Forklarer at landet ble et demokrati etter Francos død og er et konstitusjonelt monarki i dag.']::text[], 5),
  ('spansk-10:miljo-og-samfunn', 's07', 'En spansk storby har utfordringer med forurensning. Byen bygger ut kollektivtransport og sykkelveier. Skriv på spansk én anbefaling som passer til situasjonen, og knytt den til tiltakene byen bygger ut.', 'Deberíamos usar más el transporte público. También podemos ir en bicicleta por las vías para bicicletas.', array['Anbefaler å bruke kollektivtransport mer eller sykle.', 'Knytter anbefalingen til minst ett av tiltakene byen bygger ut.']::text[], 6),
  ('spansk-10:miljo-og-samfunn', 's08', 'Mange land i Latin-Amerika har store økonomiske forskjeller, og mange flytter til USA eller Spania for å finne arbeid. Forklar dette med egne ord på spansk.', 'En muchos países de América Latina hay grandes diferencias económicas. Muchas personas se mudan a Estados Unidos o España para buscar trabajo.', array['Nevner de store økonomiske forskjellene i mange land i Latin-Amerika.', 'Nevner at mange flytter til USA eller Spania for å finne arbeid.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('arbeidslivsfag-10:prosjektstyring', 'arbeidslivsfag-10', 'prosjektstyring', 'Prosjektstyring', 'Hvordan større arbeidsoppdrag gjennomføres som prosjekter: prosjektmål, faser, milepæler, Gantt-diagram, ressurser, budsjett og regnskap, statusmøter og sluttrapport.', array[2, 8]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('arbeidslivsfag-10:prosjektstyring', '## Hva er et prosjekt?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('arbeidslivsfag-10:prosjektstyring', 'Prosjekt', 'Arbeidsoppgave med tydelig mål, start og slutt, budsjett og team.', 0),
  ('arbeidslivsfag-10:prosjektstyring', 'SMART-mål', 'Mål som er spesifikt, målbart, akseptert, realistisk og tidsbestemt.', 1),
  ('arbeidslivsfag-10:prosjektstyring', 'Idéfasen', 'Fasen der man finner behov og idé og avklarer bestillingen.', 2),
  ('arbeidslivsfag-10:prosjektstyring', 'Planleggingsfasen', 'Fasen der man lager mål, planer, budsjett og risikovurdering.', 3),
  ('arbeidslivsfag-10:prosjektstyring', 'Gjennomføringsfasen', 'Fasen der arbeidet utføres og framdriften følges opp.', 4),
  ('arbeidslivsfag-10:prosjektstyring', 'Avslutningsfasen', 'Fasen der man leverer, evaluerer og skriver sluttrapport.', 5),
  ('arbeidslivsfag-10:prosjektstyring', 'Gantt-diagram', 'Tidsplan der oppgavene vises som stolper langs en tidslinje.', 6),
  ('arbeidslivsfag-10:prosjektstyring', 'Milepæl', 'Viktig delmål i et prosjekt.', 7),
  ('arbeidslivsfag-10:prosjektstyring', 'Ressurser', 'Det prosjektet trenger: personer, tid, penger, materialer og verktøy.', 8),
  ('arbeidslivsfag-10:prosjektstyring', 'Prosjektleder', 'Person som har ansvar for å lede prosjektet og holde oversikt.', 9),
  ('arbeidslivsfag-10:prosjektstyring', 'Budsjett', 'Plan for forventede inntekter og utgifter, laget før prosjektet.', 10),
  ('arbeidslivsfag-10:prosjektstyring', 'Regnskap', 'Oversikt over faktiske inntekter og utgifter.', 11),
  ('arbeidslivsfag-10:prosjektstyring', 'Statusmøte', 'Møte der teamet går gjennom hva som er gjort og hva som gjenstår.', 12),
  ('arbeidslivsfag-10:prosjektstyring', 'Prototyp', 'Første utkast av et produkt som testes før endelig produksjon.', 13),
  ('arbeidslivsfag-10:prosjektstyring', 'Sluttrapport', 'Rapport om mål, gjennomføring, resultat, økonomi og erfaringer.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('arbeidslivsfag-10:prosjektstyring', 'q01', 'flervalg', 'Hva kjennetegner et prosjekt?', array['Det varer for alltid', 'Det har et tydelig mål, en start og en slutt', 'Det har ingen budsjett', 'Det gjøres alltid alene']::text[], 1, 'Prosjekter er avgrensede oppgaver.', true, true, 0),
  ('arbeidslivsfag-10:prosjektstyring', 'q02', 'flervalg', 'Hva står T-en i SMART for?', array['Teknisk', 'Trygt', 'Tidsbestemt', 'Tydelig']::text[], 2, 'Et godt mål har en frist.', true, true, 1),
  ('arbeidslivsfag-10:prosjektstyring', 'q03', 'flervalg', 'Hva viser et Gantt-diagram?', array['Oppgavene som stolper langs en tidslinje', 'Hvor mye penger prosjektet tjente', 'Hvem som er sjef', 'En tegning av produktet']::text[], 0, 'Gantt-diagrammet gir oversikt over tidsplanen.', true, true, 2),
  ('arbeidslivsfag-10:prosjektstyring', 'q04', 'flervalg', 'Hva er forskjellen på budsjett og regnskap?', array['Det er det samme', 'Regnskapet lages før prosjektet', 'Budsjettet viser hva som faktisk ble brukt', 'Budsjettet er en plan, regnskapet viser hva som faktisk skjedde']::text[], 3, 'Ved å sammenligne dem ser man om prosjektet holdt seg innenfor rammene.', true, true, 3),
  ('arbeidslivsfag-10:prosjektstyring', 'q05', 'flervalg', 'Hva er en milepæl?', array['Et viktig delmål i prosjektet', 'En stein ved veien', 'Prosjektets budsjett', 'En type verktøy']::text[], 0, 'Milepæler gjør det lett å se om prosjektet er i rute.', true, true, 4),
  ('arbeidslivsfag-10:prosjektstyring', 'q06', 'flervalg', 'I hvilken fase lages risikovurderingen?', array['Avslutningsfasen', 'Planleggingsfasen', 'Etter leveringen', 'Den lages aldri']::text[], 1, 'Risikoen må vurderes før arbeidet starter.', true, true, 5),
  ('arbeidslivsfag-10:prosjektstyring', 'q07', 'flervalg', 'Hva gjør man på et statusmøte?', array['Feirer at prosjektet er ferdig', 'Velger ny prosjektleder', 'Går gjennom hva som er gjort, hva som gjenstår og om det er problemer', 'Deler ut lønn']::text[], 2, 'Statusmøter gjør det mulig å justere planen i tide.', true, true, 6),
  ('arbeidslivsfag-10:prosjektstyring', 'q08', 'flervalg', 'Hva bør en sluttrapport inneholde?', array['Mål, gjennomføring, resultat, økonomi og erfaringer', 'Bare bilder', 'Bare navnene på deltakerne', 'Bare budsjettet']::text[], 0, 'Erfaringene gjør neste prosjekt bedre.', true, true, 7),
  ('arbeidslivsfag-10:prosjektstyring', 'q09', 'flervalg', 'Prosjektet ligger an til å bli forsinket. Hva er et godt tiltak?', array['Late som ingenting', 'Justere planen og eventuelt avtale ny frist med oppdragsgiveren', 'Slutte i prosjektet', 'Skylde på andre']::text[], 1, 'Tidlig beskjed og justering gir bedre resultat.', true, false, 8),
  ('arbeidslivsfag-10:prosjektstyring', 'q10', 'flervalg', 'Hvilket av disse er et SMART mål?', array['Vi skal lage noe fint', 'Vi skal jobbe mye', 'Vi skal gjøre vårt beste', 'Vi skal lage ti fuglekasser og levere dem til barnehagen innen 1. mai']::text[], 3, 'Målet er spesifikt, målbart og tidsbestemt.', true, false, 9),
  ('arbeidslivsfag-10:prosjektstyring', 'm01', 'sant-usant', 'Noen oppgaver i et prosjekt må gjøres i en bestemt rekkefølge.', array['Sant', 'Usant']::text[], 0, 'Man må for eksempel kjøpe materialer før man kan bygge.', false, true, 10),
  ('arbeidslivsfag-10:prosjektstyring', 'm02', 'sant-usant', 'Evaluering er unødvendig når prosjektet er levert.', array['Sant', 'Usant']::text[], 1, 'Evalueringen gir erfaringer til neste prosjekt.', false, true, 11),
  ('arbeidslivsfag-10:prosjektstyring', 'm03', 'sant-usant', 'En prototyp testes før endelig produksjon.', array['Sant', 'Usant']::text[], 0, 'Da kan feil rettes før man lager mange eksemplarer.', false, true, 12),
  ('arbeidslivsfag-10:prosjektstyring', 'm04', 'sant-usant', 'Tid er ikke en ressurs i et prosjekt.', array['Sant', 'Usant']::text[], 1, 'Tid er en av de viktigste ressursene.', false, true, 13),
  ('arbeidslivsfag-10:prosjektstyring', 'm05', 'flervalg', 'Hva står M-en i SMART for?', array['Morsomt', 'Moderne', 'Mulig', 'Målbart']::text[], 3, 'Man må kunne sjekke om målet er nådd.', false, true, 14),
  ('arbeidslivsfag-10:prosjektstyring', 'm06', 'flervalg', 'Hvem har ansvar for å fordele ressursene i et prosjekt?', array['Kunden', 'Prosjektlederen', 'Leverandøren', 'Ingen']::text[], 1, 'Prosjektlederen holder oversikten.', false, true, 15),
  ('arbeidslivsfag-10:prosjektstyring', 'm07', 'flervalg', 'Hva skjer i avslutningsfasen?', array['Man finner en idé', 'Man lager budsjett', 'Man leverer, evaluerer og skriver sluttrapport', 'Man kjøper materialer']::text[], 2, 'Avslutningen er like viktig som starten.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('arbeidslivsfag-10:prosjektstyring', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('arbeidslivsfag-10:prosjektstyring', 's01', 'Et team skal arrangere et julemarked. Først finner de ut hva som trengs og avklarer bestillingen. Deretter lager de mål, arbeidsplan, tidsplan og budsjett. Forklar forskjellen på arbeidet i idéfasen og planleggingsfasen.', 'I idéfasen finner teamet behovet og idéen og avklarer bestillingen. I planleggingsfasen lager de blant annet mål, planer og budsjett for hvordan prosjektet skal gjennomføres.', array['Beskriver idéfasen som å finne behov eller idé og avklare bestillingen.', 'Beskriver planleggingsfasen som å lage mål eller planer for arbeidet.']::text[], 0),
  ('arbeidslivsfag-10:prosjektstyring', 's02', 'Et prosjektmål er «Vi skal lage noe fint». Forklar hvorfor det er vanskelig å vite om målet er nådd, og nevn to SMART-egenskaper som kan gjøre målet tydeligere.', 'Målet sier ikke tydelig hva som skal lages, eller hvordan man kan sjekke om det er ferdig. Det kan bli tydeligere hvis det er spesifikt og målbart, for eksempel ved at det sier hva som skal lages og hvor mange.', array['Forklarer at målet er uklart eller vanskelig å kontrollere om er nådd.', 'Nevner og forklarer minst to relevante SMART-egenskaper.']::text[], 1),
  ('arbeidslivsfag-10:prosjektstyring', 's03', 'Et team bruker et Gantt-diagram for å planlegge et prosjekt. Noen oppgaver må gjøres etter hverandre, mens andre kan gjøres samtidig. Forklar hvordan diagrammet kan hjelpe teamet med dette.', 'Stolpene langs tidslinjen viser når oppgavene skal utføres. Teamet kan bruke planen til å se hvilke oppgaver som må komme i rekkefølge, og hvilke som kan foregå samtidig.', array['Forklarer at stolpene viser oppgavene langs en tidslinje og når de skal skje.', 'Knytter planen til rekkefølge eller oppgaver som kan utføres samtidig.']::text[], 2),
  ('arbeidslivsfag-10:prosjektstyring', 's04', 'Et team har laget en plan for å bygge en gapahuk. Nå begynner de å utføre arbeidet og følge med på om det går framover som planlagt. Hvilken prosjektfase er de i, og hvorfor følger de med på framdriften i denne fasen?', 'De er i gjennomføringsfasen. Da utfører teamet arbeidet og følger med på framdriften for å se hvordan prosjektet ligger an.', array['Identifiserer gjennomføringsfasen.', 'Forklarer at arbeidet utføres og at framdriften følges opp i denne fasen.']::text[], 3),
  ('arbeidslivsfag-10:prosjektstyring', 's05', 'Flere oppgaver i et prosjekt trenger den samme sagen, og den kan bare brukes til én oppgave om gangen. Forklar hva prosjektlederen bør gjøre med ressursene for å hjelpe teamet med å få arbeidet gjennomført.', 'Prosjektlederen bør planlegge når sagen skal brukes til de ulike oppgavene, slik at bruken ikke kolliderer. Prosjektlederen må fordele ressursene og holde oversikt over dem.', array['Forklarer at bruken av sagen må fordeles eller planlegges slik at oppgavene ikke kolliderer.', 'Viser at prosjektlederen har ansvar for å fordele ressurser eller holde oversikt.']::text[], 4),
  ('arbeidslivsfag-10:prosjektstyring', 's06', 'Et team lager først en prototyp av et produkt og tester den før de lager den endelige versjonen. Forklar hva prototypen er, og hvorfor teamet tester den først.', 'En prototyp er det første utkastet av produktet. Teamet tester den før endelig produksjon for å undersøke produktet og vurdere hva som bør gjøres videre.', array['Forklarer at en prototyp er et første utkast av produktet.', 'Forklarer at den testes før produktet lages ferdig.']::text[], 5),
  ('arbeidslivsfag-10:prosjektstyring', 's07', 'Et prosjekt er ferdig, og teamet snakker om hva som fungerte i samarbeidet og hva de ville gjort annerledes. Forklar hvordan slike erfaringer kan være nyttige i et senere prosjekt.', 'Teamet kan bruke erfaringene til å forstå hva som fungerte godt, og hva som kan forbedres. Da kan de planlegge og samarbeide bedre i et senere prosjekt.', array['Knytter evalueringen til å finne ut hva som fungerte eller kunne vært gjort annerledes.', 'Forklarer at erfaringene kan brukes til å forbedre et senere prosjekt.']::text[], 6),
  ('arbeidslivsfag-10:prosjektstyring', 's08', 'Et team lager fuglekasser. Foreslå en milepæl som viser at en viktig del av arbeidet er nådd, og forklar hvorfor den passer som milepæl.', '«Den første fuglekassen er ferdig montert» kan være en milepæl. Den viser at en viktig del av arbeidet er nådd før teamet går videre med resten.', array['Foreslår en konkret viktig del av arbeidet som kan sjekkes, for eksempel at en første fuglekasse er ferdig.', 'Forklarer at milepælen viser at et viktig delmål eller en del av arbeidet er nådd.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('arbeidslivsfag-10:rettigheter-og-plikter-i-arbeidslivet', 'arbeidslivsfag-10', 'rettigheter-og-plikter-i-arbeidslivet', 'Rettigheter og plikter i arbeidslivet', 'Arbeidsavtale, lønn og skatt, feriepenger, arbeidstid, regler for unge arbeidstakere, plikter som arbeidstaker, svart arbeid, fagforeninger og den norske modellen.', array[7]::int[], 1, 'utkast', '{}'::text[], false, now())
