  ('fransk-vg1:historie', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('fransk-vg1:historie', 's01', 'Før 1789 hadde adelen og kirken store privilegier, mens folket betalte skatt og slet med høye matpriser. Forklar hvordan stormingen av Bastillen kunne uttrykke motstand mot dette samfunnet.', 'Bastillen var et symbol på kongens makt. Da folket stormet fengselet, viste de motstand mot makten og det urettferdige samfunnet.', array['Forklarer at Bastillen symboliserte kongens makt.', 'Knytter stormingen til motstand mot maktforholdene eller ulikhetene i samfunnet.']::text[], 0),
  ('fransk-vg1:historie', 's02', 'Sammenlign rettighetene til folket før revolusjonen med prinsippet i menneskerettighetserklæringen fra 1789.', 'Før revolusjonen hadde adelen og kirken store privilegier, mens folket betalte skatt. Erklæringen slo fast at alle mennesker fødes frie og like i rettigheter.', array['Beskriver privilegiene eller ulikhetene før revolusjonen.', 'Forklarer at erklæringen slo fast at alle fødes frie og like i rettigheter.']::text[], 1),
  ('fransk-vg1:historie', 's03', 'Napoleon ble beseiret ved Waterloo, men betydningen hans var ikke bare knyttet til erobringene hans. Forklar én måte han fikk betydning for andre land på.', 'Napoleon innførte Code civil, en lovbok som påvirket lovgivningen i mange land.', array['Nevner Code civil som Napoleons lovbok.', 'Forklarer at lovboken påvirket lovgivningen i mange land.']::text[], 2),
  ('fransk-vg1:historie', 's04', 'Fransk snakkes i mange land i Afrika. Forklar sammenhengen mellom dette og Frankrikes kolonihistorie.', 'Frankrike bygde et stort kolonirike i Afrika, Asia og Karibia. Kolonihistorien er en viktig årsak til at fransk fortsatt snakkes i Afrika.', array['Knytter fransk språk i Afrika til Frankrikes kolonisering eller kolonirike.', 'Forklarer at kolonihistorien fortsatt preger forholdet mellom Frankrike og mange land, eller at den bidrar til at fransk snakkes der.']::text[], 3),
  ('fransk-vg1:historie', 's05', 'I setningen «La Bastille a été prise le 14 juillet 1789» blir Bastillen utsatt for en handling. Forklar hvilke deler av verbformen som viser passiv, og hva passivformen forteller om Bastillen.', 'Passiv dannes med en form av être og et partisipp, her a été prise. Passivformen viser at Bastillen blir tatt, altså at den mottar handlingen.', array['Forklarer at passiv dannes med être og partisipp.', 'Forklarer at Bastillen er den som blir utsatt for handlingen.']::text[], 4),
  ('fransk-vg1:historie', 's06', 'Under den tyske okkupasjonen var Vichy-regimet og la Résistance ulike. Forklar forskjellen mellom dem, og ta med hvilken rolle Charles de Gaulle hadde.', 'Vichy-regimet, som var tyskvennlig, styrte Sør-Frankrike, mens motstandsbevegelsen kjempet mot okkupantene. Charles de Gaulle ledet De frie franske styrkene fra London.', array['Skiller mellom Vichy-regimet, som styrte Sør-Frankrike og var tyskvennlig, og motstandsbevegelsen, som kjempet mot okkupantene.', 'Nevner at de Gaulle ledet De frie franske styrkene fra London.']::text[], 5),
  ('fransk-vg1:historie', 's07', 'I en historisk fortelling møter du uttrykket «il eut». Forklar hva det betyr, og hvilken verbform det er.', '«Il eut» betyr «han hadde». Det er passé simple, en verbform som ofte brukes i historiske tekster.', array['Gir betydningen «han hadde».', 'Kjenner igjen passé simple som verbformen, eller forklarer at den ofte brukes i historiske tekster.']::text[], 6),
  ('fransk-vg1:historie', 's08', 'Etter andre verdenskrig ble forsoning mellom Frankrike og Tyskland viktig for europeisk samarbeid. Forklar hvordan dette henger sammen med EU.', 'Forsoningen mellom Frankrike og Tyskland ble grunnlaget for europeisk samarbeid. Frankrike var med på å grunnlegge det som i dag er EU gjennom Roma-traktaten i 1957.', array['Forklarer at forsoningen mellom Frankrike og Tyskland la grunnlag for europeisk samarbeid.', 'Knytter Frankrikes rolle i grunnleggelsen av EU til Roma-traktaten.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('fransk-vg1:kunst-og-kultur', 'fransk-vg1', 'kunst-og-kultur', 'Litteratur, kunst, musikk og film', 'Kjente kunstnere og verk fra den fransktalende verden – Molière, Victor Hugo, Den lille prinsen, impresjonismen, chanson, Stromae, tegneserier og fransk film – og hvordan du bruker conditionnel til ønsker og hypotetiske situasjoner.', array[9, 3]::int[], 5, 'utkast', '{}'::text[], false, now())
