  ('spansk-vg1:fortelle-om-opplevelser', 'el verano pasado', 'i fjor sommer', 13),
  ('spansk-vg1:fortelle-om-opplevelser', 'Hacía sol.', 'Det var sol.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('spansk-vg1:fortelle-om-opplevelser', 'q01', 'flervalg', 'Hvilken tid brukes om vaner i fortiden?', array['Indefinido', 'Imperfecto', 'Futuro', 'Presens']::text[], 1, 'Iba a la playa todos los veranos.', true, true, 0),
  ('spansk-vg1:fortelle-om-opplevelser', 'q02', 'flervalg', 'Hva er indefinido av «tener» i jeg-form?', array['tuve', 'tení', 'tenía', 'tengo']::text[], 0, 'tener er uregelmessig: tuve.', true, true, 1),
  ('spansk-vg1:fortelle-om-opplevelser', 'q03', 'flervalg', 'Velg riktig kombinasjon: «___ sol cuando ___ a llover.»', array['Hizo – empezaba', 'Hace – empieza', 'Hacía – empezó', 'Hará – empezará']::text[], 2, 'Bakgrunn i imperfecto, hendelse i indefinido.', true, true, 2),
  ('spansk-vg1:fortelle-om-opplevelser', 'q04', 'flervalg', 'Hva er imperfecto av «ir» i jeg-form?', array['fui', 'iré', 'voy', 'iba']::text[], 3, 'ir er uregelmessig i imperfecto: iba.', true, true, 3),
  ('spansk-vg1:fortelle-om-opplevelser', 'q05', 'flervalg', 'Hva kan «fui» bety?', array['jeg var eller jeg dro', 'jeg hadde', 'jeg gjorde', 'jeg kom']::text[], 0, 'ser og ir har samme former i indefinido.', true, true, 4),
  ('spansk-vg1:fortelle-om-opplevelser', 'q06', 'flervalg', 'Hva er indefinido av «hacer» i han-form?', array['hació', 'hizo', 'hice', 'hacía']::text[], 1, 'hacer: hice, hiciste, hizo.', true, true, 5),
  ('spansk-vg1:fortelle-om-opplevelser', 'q07', 'flervalg', 'Hva uttrykker «había salido»?', array['Noe som skjer nå', 'En vane i fortiden', 'Noe som skjedde før noe annet i fortiden', 'Noe i framtiden']::text[], 2, 'Pluskvamperfektum.', true, true, 6),
  ('spansk-vg1:fortelle-om-opplevelser', 'q08', 'flervalg', 'Hva betyr «de repente»?', array['til slutt', 'først', 'etterpå', 'plutselig']::text[], 3, 'De repente, empezó a llover.', true, true, 7),
  ('spansk-vg1:fortelle-om-opplevelser', 'q09', 'flervalg', 'Hva er indefinido av «hablar» i jeg-form?', array['hablé', 'hablaba', 'hablo', 'hablaré']::text[], 0, 'Regelmessig -ar-verb: hablé.', true, false, 8),
  ('spansk-vg1:fortelle-om-opplevelser', 'q10', 'flervalg', 'Hva betyr «hace dos años»?', array['om to år', 'for to år siden', 'i to år', 'hvert annet år']::text[], 1, 'hace + tid = for … siden.', true, false, 9),
  ('spansk-vg1:fortelle-om-opplevelser', 'm01', 'sant-usant', 'Bare tre verb er uregelmessige i imperfecto.', array['Sant', 'Usant']::text[], 0, 'ser, ir og ver.', false, true, 10),
  ('spansk-vg1:fortelle-om-opplevelser', 'm02', 'sant-usant', 'En plutselig hendelse står vanligvis i imperfecto.', array['Sant', 'Usant']::text[], 1, 'Plutselige hendelser står i indefinido.', false, true, 11),
  ('spansk-vg1:fortelle-om-opplevelser', 'm03', 'sant-usant', '«estuve» er indefinido av «estar».', array['Sant', 'Usant']::text[], 0, 'Estuve en Madrid dos semanas.', false, true, 12),
  ('spansk-vg1:fortelle-om-opplevelser', 'm04', 'sant-usant', 'Imperfecto av «comer» er «comaba».', array['Sant', 'Usant']::text[], 1, '-er-verb får -ía: comía.', false, true, 13),
  ('spansk-vg1:fortelle-om-opplevelser', 'm05', 'flervalg', 'Hva betyr «Cuando era pequeño, jugaba al fútbol»?', array['Da jeg var liten, spilte jeg fotball.', 'Jeg spilte fotball i går.', 'Jeg skal spille fotball.', 'Jeg har aldri spilt fotball.']::text[], 0, 'Imperfecto om vaner.', false, true, 14),
  ('spansk-vg1:fortelle-om-opplevelser', 'm06', 'flervalg', 'Hva er indefinido av «decir» i jeg-form?', array['decí', 'dije', 'decía', 'diré']::text[], 1, 'decir er uregelmessig: dije.', false, true, 15),
  ('spansk-vg1:fortelle-om-opplevelser', 'm07', 'flervalg', 'Hvordan sier du «i fjor sommer»?', array['el verano próximo', 'este verano', 'el verano pasado', 'en verano']::text[], 2, 'pasado = forrige.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('spansk-vg1:fortelle-om-opplevelser', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('spansk-vg1:fortelle-om-opplevelser', 's01', 'Forklar på spansk forskjellen mellom pretérito imperfecto og pretérito indefinido i en fortelling. Si hva slags informasjon hver tid vanligvis gir.', 'El imperfecto describe el fondo, las situaciones, los hábitos o los estados. El indefinido cuenta acciones terminadas y acontecimientos.', array['Forklarer at imperfecto beskriver bakgrunn, vaner, situasjoner eller tilstander.', 'Forklarer at indefinido forteller om avsluttede handlinger eller hendelser.']::text[], 0),
  ('spansk-vg1:fortelle-om-opplevelser', 's02', 'Du vil fortelle at toget dro før dere kom fram. Skriv dette på spansk med «Cuando llegamos...» og pretérito pluscuamperfecto av «salir».', 'Cuando llegamos, el tren ya había salido.', array['Bruker «había salido» om det som skjedde først.', 'Får fram at dere kom fram etter at toget hadde gått.']::text[], 1),
  ('spansk-vg1:fortelle-om-opplevelser', 's03', 'Lag en kort fortelling på spansk ut fra disse opplysningene: Det var lørdag og varmt. Dere dro på konsert. Du så favorittsangeren din og var nervøs. Dagen var uforglemmelig. Bruk «primero», «después» og «al final».', 'Primero, era sábado y hacía calor. Después, fuimos al concierto y vi a mi cantante favorito; estaba muy nerviosa. Al final, fue un día inolvidable.', array['Bruker «primero», «después» og «al final» til å vise rekkefølge.', 'Bruker imperfecto til bakgrunn eller følelse og indefinido til avsluttede hendelser.']::text[], 2),
  ('spansk-vg1:fortelle-om-opplevelser', 's04', 'Skriv én spansk setning med «nosotros» og «hablar» i imperfecto, og én med «ellos» og «vivir» i imperfecto. Bruk riktig verbform.', 'Nosotros hablábamos. Ellos vivían.', array['Bruker «hablábamos» med «nosotros».', 'Bruker «vivían» med «ellos».']::text[], 3),
  ('spansk-vg1:fortelle-om-opplevelser', 's05', 'På spansk finnes det tre uregelmessige verb i pretérito imperfecto. Nevn infinitivene, og skriv jeg-formen i imperfecto for hvert verb.', 'Los tres verbos irregulares son ser, ir y ver. Sus formas son era, iba y veía.', array['Nevner ser, ir og ver som de tre uregelmessige verbene.', 'Knytter formene era, iba og veía til riktig verb.']::text[], 4),
  ('spansk-vg1:fortelle-om-opplevelser', 's06', 'Forklar på norsk forskjellen mellom tidsuttrykkene «el verano pasado» og «al final». Hva forteller hvert uttrykk leseren?', '«El verano pasado» forteller når noe skjedde: i fjor sommer. «Al final» viser at noe skjer eller oppsummeres til slutt i en fortelling.', array['Forklarer at «el verano pasado» plasserer noe i tid, i fjor sommer.', 'Forklarer at «al final» viser til slutten av en hendelsesrekke eller fortelling.']::text[], 5),
  ('spansk-vg1:fortelle-om-opplevelser', 's07', 'Skriv én spansk setning som forteller at du i går hadde tid og var på stranda. Bruk «ayer», «tener» og «estar» i indefinido.', 'Ayer tuve tiempo y estuve en la playa.', array['Bruker «tuve» som indefinido av «tener» i jeg-form.', 'Bruker «estuve» som indefinido av «estar» i jeg-form.']::text[], 6),
  ('spansk-vg1:fortelle-om-opplevelser', 's08', 'Sammenlign tú-formene av «hablar» og «comer» i indefinido. Skriv begge formene og forklar kort hva endelsene viser.', 'Las formas son «hablaste» y «comiste». Las dos están en indefinido y tienen terminaciones diferentes: «-aste» y «-iste».', array['Skriver «hablaste» og «comiste» riktig.', 'Forklarer at begge formene er indefinido, men har ulike endelser.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('spansk-vg1:samfunn-og-aktuelle-saker', 'spansk-vg1', 'samfunn-og-aktuelle-saker', 'Samfunn i Spania og Latin-Amerika', 'Den spansktalende verden, Spanias regioner og språk, mangfold, ulikhet og migrasjon i Latin-Amerika – og hvordan du uttrykker meninger og ønsker på spansk, blant annet med en første innføring i subjuntivo.', array[4, 5, 8]::int[], 3, 'utkast', '{}'::text[], false, now())
