insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('kinesisk-vg1:kultur-og-hoytider', 'q01', 'flervalg', 'Hva er hovedstaden i Kina?', array['Shanghai', 'Beijing', 'Hongkong', 'Taipei']::text[], 1, 'Shanghai er den største byen.', true, true, 0),
  ('kinesisk-vg1:kultur-og-hoytider', 'q02', 'flervalg', 'Hva får barn ofte i gave til kinesisk nyttår?', array['Røde konvolutter med penger', 'Julestrømper', 'Påskeegg', 'Blomster']::text[], 0, '红包 hóngbāo.', true, true, 1),
  ('kinesisk-vg1:kultur-og-hoytider', 'q03', 'flervalg', 'Hva spiser man under midthøstfestivalen?', array['Dumplings', 'Nudler', 'Månekaker', 'Ris med fisk']::text[], 2, '月饼 yuèbing.', true, true, 2),
  ('kinesisk-vg1:kultur-og-hoytider', 'q04', 'flervalg', 'Hvor mange dyr har den kinesiske dyrekretsen?', array['7', '10', '24', '12']::text[], 3, 'Ett dyr for hvert år i en tolvårssyklus.', true, true, 3),
  ('kinesisk-vg1:kultur-og-hoytider', 'q05', 'flervalg', 'Hvilken farge regnes som lykkens farge i Kina?', array['Rød', 'Hvit', 'Svart', 'Blå']::text[], 0, 'Rødt brukes mye under høytider.', true, true, 4),
  ('kinesisk-vg1:kultur-og-hoytider', 'q06', 'flervalg', 'Hva er 书法 shūfǎ?', array['Kinesisk opera', 'Kalligrafi', 'Kampsport', 'Te-seremoni']::text[], 1, 'Kunsten å skrive tegn vakkert med pensel.', true, true, 5),
  ('kinesisk-vg1:kultur-og-hoytider', 'q07', 'flervalg', 'Hvorfor er det uhøflig å stikke spisepinnene loddrett ned i risen?', array['Fordi pinnene kan knekke', 'Fordi det er slurvete', 'Fordi det minner om røkelse ved begravelser', 'Fordi det er for høflig']::text[], 2, 'Det forbindes med død.', true, true, 6),
  ('kinesisk-vg1:kultur-og-hoytider', 'q08', 'flervalg', 'Når feires vårfestivalen?', array['1. januar', 'I juli', 'I desember', 'Mellom slutten av januar og midten av februar']::text[], 3, 'Datoen følger månekalenderen.', true, true, 7),
  ('kinesisk-vg1:kultur-og-hoytider', 'q09', 'flervalg', 'Hva heter Asias lengste elv?', array['Chang Jiang (Yangtze)', 'Huang He', 'Mekong', 'Ganges']::text[], 0, 'Chang Jiang renner gjennom Kina.', true, false, 8),
  ('kinesisk-vg1:kultur-og-hoytider', 'q10', 'flervalg', 'Hva betyr 新年快乐？', array['God jul!', 'Godt nytt år!', 'Gratulerer med dagen!', 'God morgen!']::text[], 1, 'Xīnnián kuàilè!', true, false, 9),
  ('kinesisk-vg1:kultur-og-hoytider', 'm01', 'sant-usant', 'Kina har rundt 1,4 milliarder innbyggere.', array['Sant', 'Usant']::text[], 0, 'Kina er et av verdens mest folkerike land.', false, true, 10),
  ('kinesisk-vg1:kultur-og-hoytider', 'm02', 'sant-usant', 'Vårfestivalen feires alltid 1. januar.', array['Sant', 'Usant']::text[], 1, 'Datoen følger månekalenderen.', false, true, 11),
  ('kinesisk-vg1:kultur-og-hoytider', 'm03', 'sant-usant', 'I Nord-Kina spiser man mye hvete, som nudler og dumplings.', array['Sant', 'Usant']::text[], 0, 'I sør spiser man mer ris.', false, true, 12),
  ('kinesisk-vg1:kultur-og-hoytider', 'm04', 'sant-usant', 'Mandarin snakkes bare i Kina.', array['Sant', 'Usant']::text[], 1, 'Mandarin snakkes også i Taiwan og Singapore.', false, true, 13),
  ('kinesisk-vg1:kultur-og-hoytider', 'm05', 'flervalg', 'Hva er 端午节?', array['Midthøstfestivalen', 'Dragebåtfestivalen', 'Vårfestivalen', 'Nasjonaldagen']::text[], 1, 'Duānwǔjié feires med båtløp.', false, true, 14),
  ('kinesisk-vg1:kultur-og-hoytider', 'm06', 'flervalg', 'Hva er 长城?', array['Den kinesiske mur', 'En elv', 'Et fjell', 'En by']::text[], 0, 'Chángchéng – «den lange muren».', false, true, 15),
  ('kinesisk-vg1:kultur-og-hoytider', 'm07', 'flervalg', 'Hva har jul i Norge og vårfestivalen i Kina til felles?', array['De feires samme dato', 'Begge feires med røde konvolutter', 'Begge handler om å samles med familien og spise tradisjonsmat', 'Ingenting']::text[], 2, 'Familie og tradisjonsmat står sentralt i begge.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('kinesisk-vg1:kultur-og-hoytider', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('kinesisk-vg1:kultur-og-hoytider', 's01', 'Beskriv en forskjell mellom landskapet i vest og øst i Kina.', 'I vest finnes store fjellområder, blant annet Himalaya og Tibet-platået. I øst ligger tett befolkede sletter.', array['Nevner fjellområder i vest, gjerne Himalaya eller Tibet-platået.', 'Nevner at øst har tett befolkede sletter.']::text[], 0),
  ('kinesisk-vg1:kultur-og-hoytider', 's02', 'Under 春节 Chūnjié reiser svært mange mennesker hjem. Forklar hvorfor de reiser, og hva dette viser om høytiden.', 'Mange reiser hjem for å være sammen med familien. Det viser at familiefellesskap er en viktig del av vårfestivalen.', array['Forklarer at folk reiser hjem for å samles med familien.', 'Knytter reisen til vårfestivalens betydning som en viktig familiehøytid.']::text[], 1),
  ('kinesisk-vg1:kultur-og-hoytider', 's03', 'Du spiser et kinesisk måltid der flere deler rettene rundt bordet. Hvilket redskap bruker man vanligvis, og hvordan serveres maten?', 'Man bruker 筷子 kuàizi, altså spisepinner. Rett­ene deles ofte av alle rundt bordet.', array['Nevner spisepinner som redskap.', 'Forklarer at rettene ofte deles rundt bordet.']::text[], 2),
  ('kinesisk-vg1:kultur-og-hoytider', 's04', 'Sammenlign 中秋节 Zhōngqiūjié og 端午节 Duānwǔjié ved å beskrive en aktivitet som kjennetegner hver av dem.', 'Under midthøstfestivalen samles familien, ser på månen og spiser månekaker. Dragebåtfestivalen kjennetegnes av kappløp i lange båter formet som drager.', array['Knytter midthøstfestivalen til månen, familiesamling eller månekaker.', 'Knytter dragebåtfestivalen til kappløp i drageformede båter.']::text[], 3),
  ('kinesisk-vg1:kultur-og-hoytider', 's05', 'En person vil prøve mat som er typisk for både Sør-Kina og Nord-Kina. Hvilken mat kan personen prøve i hver region?', 'I Sør-Kina kan personen prøve retter med ris. I Nord-Kina er hvete vanlig, for eksempel i nudler og dumplings.', array['Knytter ris til Sør-Kina.', 'Knytter hvete, nudler eller dumplings til Nord-Kina.']::text[], 4),
  ('kinesisk-vg1:kultur-og-hoytider', 's06', 'En besøkende ser en forestilling med sang, akrobatikk og fargerike masker. Hvilken kinesisk kunstform er det sannsynligvis, og hvilke trekk viser det?', 'Det er sannsynligvis 京剧 jīngjù, altså Beijing-opera. Sang, akrobatikk og fargerike masker er typiske trekk ved denne kunstformen.', array['Identifiserer kunstformen som Beijing-opera.', 'Nevner relevante kjennetegn, som sang, akrobatikk eller fargerike masker.']::text[], 5),
  ('kinesisk-vg1:kultur-og-hoytider', 's07', 'Hva menes med at dyret i fødselsåret kan si noe om en persons personlighet?', 'I den kinesiske dyrekretsen er hvert år knyttet til ett av tolv dyr. Mange mener at dyret som hører til fødselsåret, sier noe om personens personlighet.', array['Forklarer at et dyr er knyttet til fødselsåret.', 'Forklarer at mange mener dette dyret sier noe om personligheten.']::text[], 6),
  ('kinesisk-vg1:kultur-og-hoytider', 's08', 'Sammenlign jul i Norge og 春节 Chūnjié i Kina. Nevn én likhet ved feiringen og én forskjell knyttet til familier.', 'Begge høytidene handler om å samles med familien og spise tradisjonsmat. I Kina bor flere generasjoner ofte tettere sammen, mens mange nordmenn bor langt fra besteforeldrene.', array['Nevner en likhet: familiesamling eller tradisjonsmat.', 'Nevner forskjellen i hvor tett flere generasjoner ofte bor sammen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-vg2:norron-litteratur', 'norsk-vg2', 'norron-litteratur', 'Norrøn litteratur', 'Eddadikt, skaldedikt, islendingesagaer og kongesagaer: hvordan norrøne tekster er bygd opp, hvilke verdier de uttrykker – ære, hevn og skjebne – og hvordan de kan sammenlignes med tekster fra nyere tid.', array[1]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-vg2:norron-litteratur', '## Den norrøne perioden
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('norsk-vg2:norron-litteratur', 'Norrøn tid', 'Omtrent 800–1350.', 0),
  ('norsk-vg2:norron-litteratur', 'Eddadikt', 'Anonyme dikt om guder og helter.', 1),
  ('norsk-vg2:norron-litteratur', 'Voluspå', 'Eddadikt om verdens skapelse og undergang.', 2),
  ('norsk-vg2:norron-litteratur', 'Ragnarok', 'Verdens undergang i norrøn mytologi.', 3),
  ('norsk-vg2:norron-litteratur', 'Håvamål', 'Eddadikt med leveregler om vennskap, måtehold og ettermæle.', 4),
  ('norsk-vg2:norron-litteratur', 'Ettermæle', 'Det andre sier om deg etter at du er død.', 5),
  ('norsk-vg2:norron-litteratur', 'Skald', 'Dikter ved kongens hoff.', 6),
  ('norsk-vg2:norron-litteratur', 'Kenning', 'Omskrivning, som «havets hest» for skip.', 7),
  ('norsk-vg2:norron-litteratur', 'Islendingesagaer', 'Sagaer skrevet på 1200-tallet om islandske ætter omkring 900–1050.', 8),
  ('norsk-vg2:norron-litteratur', 'Njåls saga', 'En av de mest kjente islendingesagaene.', 9),
  ('norsk-vg2:norron-litteratur', 'Lakonisk replikk', 'Kort, underdrevet utsagn – typisk i sagaene.', 10),
  ('norsk-vg2:norron-litteratur', 'Ære og hevn', 'Sentrale verdier i sagasamfunnet.', 11),
  ('norsk-vg2:norron-litteratur', 'Snorre Sturlason', 'Skrev Heimskringla, sagaene om de norske kongene.', 12),
  ('norsk-vg2:norron-litteratur', 'Heimskringla', 'Kongesagaene, som fikk stor betydning for norsk nasjonal identitet.', 13),
  ('norsk-vg2:norron-litteratur', 'Frampek i sagaene', 'Drømmer og varsler som peker fram mot det som skal skje.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-vg2:norron-litteratur', 'q01', 'flervalg', 'Hva handler Voluspå om?', array['Leveregler', 'Verdens skapelse og undergang', 'De norske kongene', 'Kjærlighet']::text[], 1, 'Den forteller også om en ny verden etter Ragnarok.', true, true, 0),
  ('norsk-vg2:norron-litteratur', 'q02', 'flervalg', 'Hva er Håvamål?', array['En samling leveregler', 'En kongesaga', 'En islendingesaga', 'Et skaldedikt til en konge']::text[], 0, 'Den handler om vennskap, gjestfrihet og ettermæle.', true, true, 1),
  ('norsk-vg2:norron-litteratur', 'q03', 'flervalg', 'Hva er en kenning?', array['En type saga', 'En norrøn gud', 'En omskrivning, som «havets hest» for skip', 'En regel for rim']::text[], 2, 'Kenninger er typiske for skaldedikt.', true, true, 2),
  ('norsk-vg2:norron-litteratur', 'q04', 'flervalg', 'Hvem skrev Heimskringla?', array['Egil Skallagrimsson', 'Njål', 'Henrik Wergeland', 'Snorre Sturlason']::text[], 3, 'Heimskringla er sagaene om de norske kongene.', true, true, 3),
  ('norsk-vg2:norron-litteratur', 'q05', 'flervalg', 'Hvordan skildres personene vanligvis i islendingesagaene?', array['Indirekte, gjennom handlinger og replikker', 'Med lange beskrivelser av følelser', 'Gjennom indre monolog', 'Gjennom fortellerens kommentarer']::text[], 0, 'Stilen er saklig og kortfattet.', true, true, 4),
  ('norsk-vg2:norron-litteratur', 'q06', 'flervalg', 'Hvorfor var ære og hevn så viktig i sagasamfunnet?', array['Fordi kongen krevde det', 'Fordi det ikke fantes stat og politi, og ætta måtte beskytte seg selv', 'Fordi kirken bestemte det', 'Fordi det var en sport']::text[], 1, 'En fornærmelse mot én var en fornærmelse mot hele ætta.', true, true, 5),
  ('norsk-vg2:norron-litteratur', 'q07', 'flervalg', 'Når ble de fleste islendingesagaene skrevet ned?', array['På 800-tallet', 'På 1800-tallet', 'På 1200-tallet', 'På 1500-tallet']::text[], 2, 'De handler om hendelser rundt 900–1050.', true, true, 6),
  ('norsk-vg2:norron-litteratur', 'q08', 'flervalg', 'Hva er ettermæle?', array['En gravstein', 'En type dikt', 'Et arveoppgjør', 'Det andre sier om deg etter at du er død']::text[], 3, 'Ifølge Håvamål dør aldri et godt ettermæle.', true, true, 7),
  ('norsk-vg2:norron-litteratur', 'q09', 'flervalg', 'Hvilken funksjon har drømmer og varsler i sagaene?', array['De peker fram mot det som skal skje', 'De er bare pynt', 'De avslutter sagaen', 'De forklarer ordene']::text[], 0, 'Det uttrykker skjebnetro.', true, false, 8),
  ('norsk-vg2:norron-litteratur', 'q10', 'flervalg', 'Hvilken moderne sjanger minner sagastilen ofte om?', array['Romantiske dikt', 'Krimlitteratur og minimalistisk prosa', 'Eventyr', 'Reiseskildringer']::text[], 1, 'Saklig stil og korte replikker.', true, false, 9),
  ('norsk-vg2:norron-litteratur', 'm01', 'sant-usant', 'Mye av den norrøne litteraturen ble skrevet ned på Island.', array['Sant', 'Usant']::text[], 0, 'Særlig på 1200-tallet.', false, true, 10),
  ('norsk-vg2:norron-litteratur', 'm02', 'sant-usant', 'Fortelleren i sagaene kommenterer ofte personenes følelser.', array['Sant', 'Usant']::text[], 1, 'Stilen er saklig, og fortelleren kommenterer sjelden.', false, true, 11),
  ('norsk-vg2:norron-litteratur', 'm03', 'sant-usant', 'Eddadiktene er anonyme.', array['Sant', 'Usant']::text[], 0, 'Vi vet ikke hvem som diktet dem.', false, true, 12),
  ('norsk-vg2:norron-litteratur', 'm04', 'sant-usant', 'Heimskringla handler om islandske bønder.', array['Sant', 'Usant']::text[], 1, 'Heimskringla handler om de norske kongene.', false, true, 13),
  ('norsk-vg2:norron-litteratur', 'm05', 'flervalg', 'Hvilken av disse er en islendingesaga?', array['Heimskringla', 'Njåls saga', 'Voluspå', 'Håvamål']::text[], 1, 'Egils saga og Laksdøla saga er andre eksempler.', false, true, 14),
  ('norsk-vg2:norron-litteratur', 'm06', 'flervalg', 'Hva er en lakonisk replikk?', array['En kort, underdrevet replikk', 'En lang tale', 'Et dikt', 'Et spørsmål']::text[], 0, 'Typisk for sagastilen.', false, true, 15),
  ('norsk-vg2:norron-litteratur', 'm07', 'flervalg', 'Hvorfor fikk Heimskringla stor betydning på 1800-tallet?', array['Fordi den var ny', 'Fordi den var skrevet på dansk', 'Fordi den styrket norsk nasjonal identitet', 'Fordi den handlet om Danmark']::text[], 2, 'Den viste at Norge hadde en stor fortid som eget kongerike.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-vg2:norron-litteratur', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-vg2:norron-litteratur', 's01', 'Norrøn tid regnes omtrent fra 800 til 1350. Hvilket språk ble snakket i Norge og på Island i denne perioden?', 'Språket var norrønt, som ble snakket både i Norge og på Island.', array['Slår fast at språket var norrønt.', 'Knytter språket til både Norge og Island.']::text[], 0),
  ('norsk-vg2:norron-litteratur', 's02', 'Mye norrøn litteratur ble skrevet ned på Island på 1200-tallet, men tekstene bygger ofte på eldre muntlig tradisjon. Forklar hvordan dette henger sammen.', 'Fortellingene kunne bli overlevert muntlig før de ble skrevet ned. Derfor kan en tekst være skrevet på 1200-tallet, selv om innholdet bygger på eldre fortellinger.', array['Skiller mellom tidspunktet tekstene ble skrevet ned og den eldre muntlige overleveringen.', 'Forklarer at muntlig tradisjon kan ha blitt bevart fram til nedskrivingen.']::text[], 1),
  ('norsk-vg2:norron-litteratur', 's03', 'Sammenlign eddadikt og skaldedikt: Hva handler de typisk om, og hvem laget dem?', 'Eddadiktene er anonyme dikt om guder og helter. Skaldedikt ble laget av skalder ved kongens hoff og hyllet ofte konger og krigere.', array['Beskriver eddadikt som anonyme dikt om guder og helter.', 'Beskriver skaldene som hoffdiktere som ofte hyllet konger og krigere.']::text[], 2),
  ('norsk-vg2:norron-litteratur', 's04', 'En dikter ved kongens hoff hyller en kriger og bruker uttrykket «sverdenes regn». Hva kalles dikteren, og hva viser uttrykket til?', 'Dikteren er en skald. «Sverdenes regn» er en kenning som viser til kamp.', array['Identifiserer dikteren som en skald.', 'Forklarer at uttrykket er en omskrivning for kamp.']::text[], 3),
  ('norsk-vg2:norron-litteratur', 's05', 'Islendingesagaene ble skrevet på 1200-tallet, men handler om hendelser på Island omkring 900–1050. Forklar forskjellen mellom disse tidspunktene.', '1200-tallet viser til når sagaene ble skrevet. Tidsrommet 900–1050 viser til når hendelsene de forteller om, skal ha funnet sted.', array['Skiller mellom tidspunktet sagaene ble skrevet og tiden handlingen foregår.', 'Knytter tidsrommet 900–1050 til hendelsene på Island.']::text[], 4),
  ('norsk-vg2:norron-litteratur', 's06', 'Heimskringla forteller om norske konger fra sagntiden til 1177. Hvilken betydning fikk verket for norsk nasjonal identitet, og når var denne betydningen særlig stor?', 'Heimskringla fikk stor betydning for norsk nasjonal identitet, særlig på 1800-tallet.', array['Forklarer at Heimskringla fikk betydning for norsk nasjonal identitet.', 'Nevner at betydningen var særlig stor på 1800-tallet.']::text[], 5),
  ('norsk-vg2:norron-litteratur', 's07', 'En saga forteller hendelsene i kronologisk rekkefølge, men lar også en drøm varsle noe som skjer senere. Forklar hvilken funksjon kronologien og drømmen har.', 'Kronologien gjør at hendelsene blir fortalt i tidsrekkefølge. Drømmen fungerer som et frampek fordi den varsler noe som skal skje senere.', array['Forklarer at kronologisk komposisjon forteller hendelsene i tidsrekkefølge.', 'Forklarer at drømmen peker fram mot en senere hendelse.']::text[], 6),
  ('norsk-vg2:norron-litteratur', 's08', 'En moderne fantasyfilm bruker figurer og motiver fra norrøn mytologi. Hva viser dette om hvordan norrøn mytologi brukes i dag?', 'Det viser at norrøn mytologi fortsatt inspirerer moderne kultur. Figurer og motiver fra mytologien brukes også i fantasyfilmer, spill og andre fantasyverk.', array['Knytter filmens figurer eller motiver til norrøn mytologi.', 'Forklarer at norrøne motiver fortsatt brukes i moderne fantasy eller populærkultur.']::text[], 7);
