  ('norsk-vg2:romantikken', 'Nasjonalromantikken', '1840- og 1850-tallet – norsk bondekultur som den ekte nasjonale kulturen.', 8),
  ('norsk-vg2:romantikken', 'Asbjørnsen og Moe', 'Samlet Norske Folkeeventyr fra 1841.', 9),
