  ('historie-vg2:demokrati-for-og-na', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-vg2:demokrati-for-og-na', 's01', 'I Athen møttes borgerne i folkeforsamlingen, ekklesia. Forklar hva de kunne gjøre der, og nevn to typer saker de avgjorde.', 'Borgerne kunne møte, tale og stemme over saker selv. De avgjorde blant annet lover og spørsmål om krig og fred.', array['Får fram at borgerne selv kunne delta og stemme, ikke bare velge representanter.', 'Nevner minst én sakstype folkeforsamlingen avgjorde, for eksempel lover eller krig og fred.']::text[], 0),
  ('historie-vg2:demokrati-for-og-na', 's02', 'Rådet boulé besto av 500 loddtrukne borgere. Forklar hvilken oppgave rådet hadde, og hvordan arbeidet hang sammen med folkeforsamlingen.', 'Boulé forberedte sakene som skulle behandles i folkeforsamlingen. Folkeforsamlingen kunne deretter stemme over sakene.', array['Forklarer at boulé forberedte saker for folkeforsamlingen.', 'Får fram at folkeforsamlingen behandlet eller stemte over sakene.']::text[], 1),
  ('historie-vg2:demokrati-for-og-na', 's03', 'I Athen ble mange offentlige verv fordelt ved loddtrekning. Forklar hvorfor athenerne kunne mene at denne metoden var demokratisk.', 'Loddtrekning ble sett på som demokratisk fordi alle borgere hadde lik sjanse til å få et verv. Dermed ble vervene ikke bare fordelt gjennom valg.', array['Forklarer at loddtrekning ga borgerne lik sjanse til å få verv.']::text[], 2),
  ('historie-vg2:demokrati-for-og-na', 's04', 'Borgerne i Athen kunne stemme over om noen skulle forvises i ti år. Forklar hvilket problem dette tiltaket skulle forebygge, og hvordan det kunne bidra til det.', 'Tiltaket skulle hindre at noen fikk for mye makt. Ved å forvise en person kunne borgerne begrense personens mulighet til å samle makt i byen.', array['Får fram at målet var å hindre at noen fikk for mye makt.', 'Knytter forvisningen til at personen ble fjernet fra byen i en periode.']::text[], 3),
  ('historie-vg2:demokrati-for-og-na', 's05', 'Athen omtales som et demokrati, selv om bare et mindretall hadde politiske rettigheter. Forklar hvordan begrenset borgerskap og slavearbeid henger sammen med hvem som kunne delta i politikken.', 'Politiske rettigheter var forbeholdt frie menn med athenske foreldre, så store grupper var utestengt. Slaver utførte mye av arbeidet, mens borgerne kunne delta i politikken.', array['Får fram at bare en begrenset gruppe hadde politiske rettigheter, og at blant andre kvinner, slaver og metøker var utestengt.', 'Forklarer at slaver utførte mye av arbeidet i Athen.']::text[], 4),
  ('historie-vg2:demokrati-for-og-na', 's06', 'En elev hevder at Perikles innførte demokratiet i Athen i 508/507 f.Kr. Rett opp påstanden ved å forklare rollene til Kleisthenes og Perikles.', 'Det var Kleisthenes som innførte demokratiske reformer i Athen i 508/507 f.Kr. Perikles var en ledende politiker i perioden da demokratiet var på sitt mest utviklede på 400-tallet f.Kr.', array['Knytter Kleisthenes til de demokratiske reformene i 508/507 f.Kr.', 'Forklarer Perikles’ rolle på 400-tallet f.Kr., da demokratiet var på sitt mest utviklede.']::text[], 5),
  ('historie-vg2:demokrati-for-og-na', 's07', 'En regjering vil straffe en person uten å følge gjeldende lover. Bruk begrepet rettsstat til å forklare hvorfor dette er problematisk.', 'I en rettsstat er myndighetene bundet av lover. Regjeringen må derfor følge lovene når den handler overfor personer.', array['Forklarer at myndighetene er bundet av lover.', 'Knytter dette til at regjeringen ikke kan handle uten å følge lovene.']::text[], 6),
  ('historie-vg2:demokrati-for-og-na', 's08', 'En kommune velger innbyggere ved loddtrekning til et borgerpanel som skal gi råd i en vanskelig sak. I Athen stemte borgerne selv over saker i folkeforsamlingen. Forklar én likhet og én forskjell mellom de to måtene å delta på.', 'Begge ordningene bruker loddtrekning for å få innbyggere med i politiske saker. I Athen stemte borgerne selv i folkeforsamlingen, mens borgerpanelet gir råd.', array['Nevner loddtrekning som en likhet mellom borgerpanelet og en athensk demokratisk praksis.', 'Skiller mellom at folkeforsamlingen stemte over saker, mens borgerpanelet gir råd.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-vg2:kommunikasjon-og-kulturmoter', 'historie-vg2', 'kommunikasjon-og-kulturmoter', 'Kommunikasjon og kulturmøter', 'Hvordan skrift, boktrykk, telegraf, radio, TV og internett har endret menneskers liv, og hvordan kulturmøter – fra vikingtiden og koloniseringen til migrasjonen i vår tid – har preget mennesker i Norge og verden.', array[9]::int[], 6, 'utkast', '{}'::text[], false, now())
