insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('historie-vg2:religion-og-makt', 'q01', 'flervalg', 'Hva skjedde på Stiklestad i 1030?', array['Reformasjonen startet', 'Olav Haraldsson falt i slaget', 'Nidarosdomen ble ferdig', 'Norge ble kristnet på én dag']::text[], 1, 'Han ble senere dyrket som Olav den hellige.', true, true, 0),
  ('historie-vg2:religion-og-makt', 'q02', 'flervalg', 'Hva kritiserte Martin Luther i 1517?', array['Kirkens handel med avlat', 'Kongens skatter', 'Vitenskapen', 'Islam']::text[], 0, 'Protesten førte til reformasjonen.', true, true, 1),
  ('historie-vg2:religion-og-makt', 'q03', 'flervalg', 'Hva skjedde med kirken i Danmark-Norge etter reformasjonen i 1537?', array['Den ble uavhengig av staten', 'Paven fikk mer makt', 'Kongen overtok kirkens eiendom og ble dens overhode', 'Kirken ble avskaffet']::text[], 2, 'Kirken ble en statskirke.', true, true, 2),
  ('historie-vg2:religion-og-makt', 'q04', 'flervalg', 'Hvor i Norge var hekseprosessene særlig omfattende?', array['Oslo', 'Bergen', 'Trøndelag', 'Finnmark']::text[], 3, 'Steilneset minnested i Vardø minner om ofrene.', true, true, 3),
  ('historie-vg2:religion-og-makt', 'q05', 'flervalg', 'Når ble jødeparagrafen opphevet?', array['1851', '1814', '1964', '2012']::text[], 0, 'Wergeland kjempet for opphevelsen.', true, true, 4),
  ('historie-vg2:religion-og-makt', 'q06', 'flervalg', 'Hva er sekularisering?', array['At religionen får mer makt', 'At religionen får mindre betydning i samfunnet', 'At kirken blir statskirke', 'At man bygger flere kirker']::text[], 1, 'Færre går i kirken i Norge i dag.', true, true, 5),
  ('historie-vg2:religion-og-makt', 'q07', 'flervalg', 'Hva slo Grunnloven fra 1814 fast om religion?', array['Full religionsfrihet', 'At staten ikke skulle ha religion', 'At den evangelisk-lutherske religionen var statens religion', 'At alle religioner var likestilte']::text[], 2, 'Jøder, jesuitter og munkeordener ble utestengt.', true, true, 6),
  ('historie-vg2:religion-og-makt', 'q08', 'flervalg', 'Hvordan har religion blitt brukt til å skape skiller mellom «oss» og «de andre»?', array['Gjennom felles bønn', 'Gjennom veldedighet', 'Gjennom fredsarbeid', 'Gjennom korstog, antisemittisme og rettferdiggjøring av undertrykkelse']::text[], 3, 'Religion har også inspirert fellesskap og fredsarbeid.', true, true, 7),
  ('historie-vg2:religion-og-makt', 'q09', 'flervalg', 'Når ble religionsfrihet tatt inn i Grunnloven?', array['1964', '1814', '1851', '2017']::text[], 0, 'Dissenterloven kom allerede i 1845.', true, false, 8),
  ('historie-vg2:religion-og-makt', 'q10', 'flervalg', 'Hvilken religiøs leder ledet borgerrettighetsbevegelsen i USA?', array['Martin Luther', 'Martin Luther King Jr.', 'Paven', 'Olav den hellige']::text[], 1, 'Han var baptistprest.', true, false, 9),
  ('historie-vg2:religion-og-makt', 'm01', 'sant-usant', 'Kongene brukte kristningen til å styrke kongemakten.', array['Sant', 'Usant']::text[], 0, 'Kirken og kongen samarbeidet om makten.', false, true, 10),
  ('historie-vg2:religion-og-makt', 'm02', 'sant-usant', 'Den norske kirke har vært fullstendig atskilt fra staten siden 1814.', array['Sant', 'Usant']::text[], 1, 'Den ble gradvis skilt fra staten i 2012 og 2017.', false, true, 11),
  ('historie-vg2:religion-og-makt', 'm03', 'sant-usant', 'Mange av dem som ble henrettet for trolldom i Finnmark, var kvinner.', array['Sant', 'Usant']::text[], 0, 'Også mange samer ble rammet.', false, true, 12),
  ('historie-vg2:religion-og-makt', 'm04', 'sant-usant', 'Norge er i dag mindre religiøst mangfoldig enn før.', array['Sant', 'Usant']::text[], 1, 'Norge har blitt mer religiøst mangfoldig.', false, true, 13),
  ('historie-vg2:religion-og-makt', 'm05', 'flervalg', 'Når begynte korstogene?', array['1030', '1096', '1517', '1618']::text[], 1, 'Korstogene var rettet mot muslimer i Midtøsten.', false, true, 14),
  ('historie-vg2:religion-og-makt', 'm06', 'flervalg', 'Hva ga dissenterloven fra 1845?', array['Andre kristne trossamfunn rett til å drive virksomhet', 'Jøder adgang til riket', 'Full religionsfrihet', 'Paven makt i Norge']::text[], 0, 'Det var et første steg mot religionsfrihet.', false, true, 15),
  ('historie-vg2:religion-og-makt', 'm07', 'flervalg', 'Når fikk Nidaros eget erkebispesete?', array['800-årene', '1030', '1150-årene', '1537']::text[], 2, 'Nidaros ble sentrum for kirken i Norge.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-vg2:religion-og-makt', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-vg2:religion-og-makt', 's01', 'Kristendommen kom til Norge gjennom kontakt med Europa i vikingtiden. Olav Tryggvason og Olav Haraldsson brukte kristningen til å samle riket. Forklar hvordan kristningen også kunne styrke kongemakten.', 'Når flere i riket fulgte den samme religionen, kunne det bidra til å samle riket. Kongene kunne dermed bruke kristendommen til å styrke sin egen makt.', array['Forklarer at kristendommen kunne bidra til å samle riket.', 'Knytter samlingen til at kongenes makt ble styrket.']::text[], 0),
  ('historie-vg2:religion-og-makt', 's02', 'I middelalderen eide kirken mye jord, krevde tiende og drev skoler og sykehus. Paven hadde også stor makt. Forklar hvordan kirken både kunne støtte kongen og komme i konflikt med ham.', 'Kirken kunne legitimere kongemakten og dermed støtte kongen. Samtidig hadde kirken og paven stor egen makt, så kirken kunne utfordre kongen om hvem som skulle bestemme.', array['Forklarer hvordan kirken kunne støtte kongen ved å legitimere makten hans.', 'Forklarer at kirkens egen makt kunne føre til konflikt om hvem som skulle ha det siste ordet.']::text[], 1),
  ('historie-vg2:religion-og-makt', 's03', 'Nidaros i Trondheim var et pilegrimssted og fikk erkebispesete i 1150-årene. Steilneset minnested i Vardø minnes ofrene for hekseprosessene. Forklar hva de to stedene forteller om ulike sider ved religionens historie i Norge.', 'Nidaros viser at kristendommen fikk viktige religiøse sentre og tiltrakk seg pilegrimer. Steilneset minner om forfølgelsen av mennesker som ble anklaget for trolldom.', array['Knytter Nidaros til pilegrimsferd eller kirkens institusjoner.', 'Knytter Steilneset til ofrene for hekseprosessene eller religiøs forfølgelse.']::text[], 2),
  ('historie-vg2:religion-og-makt', 's04', 'I 1814 var jøder, jesuitter og munkeordener utestengt fra Norge. Dissenterloven i 1845 ga andre kristne trossamfunn rett til å drive virksomhet, jødeparagrafen ble opphevet i 1851, og religionsfrihet kom inn i Grunnloven i 1964. Den norske kirke ble gradvis skilt fra staten i 2012 og 2017. Forklar hovedtrekkene i denne utviklingen.', 'Utviklingen gikk fra religiøse utestengelser til større rettigheter for ulike trosretninger og religionsfrihet. Senere ble også båndet mellom staten og Den norske kirke gradvis svekket.', array['Beskriver en utvikling fra utestengelse til større religiøse rettigheter eller religionsfrihet.', 'Får fram at Den norske kirke gradvis ble skilt fra staten.']::text[], 3),
  ('historie-vg2:religion-og-makt', 's05', 'Trettiårskrigen var en religionskrig i Europa fra 1618 til 1648. På 1600-tallet ble mennesker i Norge anklaget for trolldom i hekseprosessene, særlig i Finnmark, der mange kvinner og samer ble henrettet. Forklar én likhet og én forskjell mellom disse to historiske hendelsene.', 'Begge hendelsene viser at religion kunne være knyttet til vold og forfølgelse. Trettiårskrigen var en krig i Europa, mens hekseprosessene var rettssaker mot mennesker anklaget for trolldom, særlig i Finnmark.', array['Peker på at begge hendelsene var knyttet til religion og vold eller forfølgelse.', 'Skiller mellom krig i Europa og rettssaker om trolldom i Norge.']::text[], 4),
  ('historie-vg2:religion-og-makt', 's06', 'I et samfunn får kirken mindre betydning i skolen, politikken og hverdagen, og færre går i kirken. Samtidig blir det flere muslimer, katolikker og andre religiøse grupper. Forklar hvilke deler av situasjonen som viser sekularisering, og hvilke som viser større religiøst mangfold.', 'At kirken får mindre betydning og færre går i kirken, viser sekularisering. At flere ulike religiøse grupper er til stede, viser at samfunnet blir mer religiøst mangfoldig.', array['Knytter mindre kirkelig betydning eller færre kirkegjengere til sekularisering.', 'Knytter flere ulike religiøse grupper til større religiøst mangfold.']::text[], 5),
  ('historie-vg2:religion-og-makt', 's07', 'Religion har inspirert arbeid for fred og rettferdighet. Martin Luther King Jr., som var prest, ledet borgerrettighetsbevegelsen i USA. Forklar hvordan dette eksemplet viser at religion kan påvirke samfunnet på en positiv måte.', 'Eksemplet viser at religion kan inspirere mennesker til å arbeide for rettferdighet og endring i samfunnet. Martin Luther King Jr. brukte sin rolle som prest i ledelsen av borgerrettighetsbevegelsen.', array['Forklarer at religion kan inspirere kamp for rettferdighet eller samfunnsendring.', 'Knytter forklaringen til Martin Luther King Jr. og borgerrettighetsbevegelsen.']::text[], 6),
  ('historie-vg2:religion-og-makt', 's08', 'Antisemittisme betyr hat og fordommer mot jøder. Forklar hvordan Holocaust viser at antisemittisme kan få alvorlige følger.', 'Holocaust viser at hat og fordommer mot jøder kunne føre til omfattende forfølgelse og drap. Det er et alvorlig eksempel på følgene av antisemittisme.', array['Knytter Holocaust til forfølgelse eller drap på jøder.', 'Forklarer at dette viser alvorlige følger av hat eller fordommer mot jøder.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
