insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-2p:indeks-og-reallonn', 's01', 'Forklar hva et basisår er, og hvordan indeksen viser en endring sammenlignet med dette året.', 'Basisåret er året indeksen sammenlignes med, og det settes til 100. Indekstallet viser hvordan nivået har endret seg siden basisåret.', array['Forklarer at basisåret er sammenligningsåret og har indeksverdi 100.', 'Forklarer at indeksen viser endring sammenlignet med basisåret.']::text[], 0),
  ('matematikk-2p:indeks-og-reallonn', 's02', 'Hva måler konsumprisindeksen (KPI), og hva mener vi med inflasjon?', 'KPI måler hvordan prisene på varer og tjenester husholdningene kjøper, endrer seg. Inflasjon betyr at prisene stiger.', array['Får fram at KPI måler prisutviklingen for varer og tjenester husholdningene kjøper.', 'Forklarer at inflasjon er prisstigning.']::text[], 1),
  ('matematikk-2p:indeks-og-reallonn', 's03', 'En vare følger prisutviklingen og koster 250 kr når KPI er 125. Hva kostet varen da KPI var 100? Vis det viktigste regnestykket.', 'Prisen ved KPI 100 var 250 · 100/125 = 200 kr.', array['Bruker forholdet mellom pris og indeks riktig, for eksempel 250 · 100/125.', 'Oppgir 200 kr.']::text[], 2),
  ('matematikk-2p:indeks-og-reallonn', 's04', 'En person får utbetalt 28 000 kr etter at 30 % av bruttolønnen er trukket i skatt. Hva var bruttolønnen? Vis det viktigste regnestykket.', 'Etter et trekk på 30 % er 70 % av lønnen igjen. Bruttolønnen var derfor 28 000/0,70 = 40 000 kr.', array['Forstår at utbetalingen er 70 % av bruttolønnen.', 'Regner ut og oppgir bruttolønnen 40 000 kr.']::text[], 3),
  ('matematikk-2p:indeks-og-reallonn', 's05', 'En person får høyere lønn i kroner enn før. Hvilken opplysning om prisene trenger du for å avgjøre om personen også har fått større kjøpekraft? Forklar hvordan du bruker opplysningen.', 'Vi må vite hvor mye prisene har steget. Hvis lønnen har økt mer enn prisene, har reallønnen og kjøpekraften økt; hvis prisene har steget mer, har kjøpekraften gått ned.', array['Sammenligner lønnsøkningen med prisstigningen.', 'Knytter utfallet til endring i reallønn eller kjøpekraft.']::text[], 4),
  ('matematikk-2p:indeks-og-reallonn', 's06', 'En lønn står oppført som 500 000 kr, mens reallønnen er 400 000 kr i basisårets kroner. Forklar hvorfor beløpene er ulike.', '500 000 kr er den nominelle lønnen, altså beløpet i kroner. Reallønnen justerer dette beløpet for prisstigning, slik at den viser verdien målt i basisårets kroner.', array['Forklarer at nominell lønn er beløpet i kroner.', 'Forklarer at reallønn er justert for prisstigning og uttrykker kjøpekraft i basisårets kroner.']::text[], 5),
  ('matematikk-2p:indeks-og-reallonn', 's07', 'En husleiekontrakt sier at husleien kan justeres etter KPI. Forklar hvordan KPI kan brukes til å vurdere en slik justering.', 'Endringen i KPI viser hvordan prisene har utviklet seg. Ved å sammenligne KPI-verdiene kan man finne hvor mye husleien skal justeres i tråd med prisutviklingen.', array['Forklarer at endringen i KPI viser prisutviklingen.', 'Knytter sammenligning av KPI-verdier til hvor mye husleien justeres.']::text[], 6),
  ('matematikk-2p:indeks-og-reallonn', 's08', 'Forklar forskjellen på trinnskatt og prosenttrekk.', 'Trinnskatt innebærer at skatten øker med høyere inntekt. Prosenttrekk betyr at en fast prosent av lønnen trekkes i skatt.', array['Forklarer at trinnskatten øker når inntekten blir høyere.', 'Forklarer at prosenttrekk er en fast prosent av lønnen.']::text[], 7);
