  ('tysk-vg2:miljo-og-barekraft', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('tysk-vg2:miljo-og-barekraft', 's01', 'Erkläre auf Deutsch, was „umweltfreundlich“ bedeutet. Nenne auch ein Beispiel mit „recyceln“.', 'Umweltfreundlich bedeutet, dass etwas die Umwelt schont. Ein Beispiel ist, dass viele Flaschen recycelt werden.', array['Erklärt, dass umweltfreundlich etwas bezeichnet, das die Umwelt schont.', 'Nutzt Recycling als passendes Beispiel.']::text[], 0),
  ('tysk-vg2:miljo-og-barekraft', 's02', 'Erkläre auf Deutsch, was die Energiewende in Deutschland bedeutet. Nenne auch, was nach der Schließung der letzten Kernkraftwerke 2023 weiterhin genutzt wird.', 'Die Energiewende ist der Übergang von Kernkraft und Kohle zu erneuerbarer Energie. Die letzten Kernkraftwerke wurden 2023 geschlossen, aber Kohle wird weiterhin genutzt.', array['Beschreibt den Übergang von Kernkraft und Kohle zu erneuerbarer Energie.', 'Nennt sowohl die Schließung der letzten Kernkraftwerke 2023 als auch die weitere Nutzung von Kohle.']::text[], 1),
  ('tysk-vg2:miljo-og-barekraft', 's03', 'Jemand sagt: „Seit die letzten Kernkraftwerke in Deutschland geschlossen wurden, wird dort keine Kohle mehr genutzt.“ Korrigiere diese Aussage auf Deutsch mit den passenden Fakten.', 'Die letzten Kernkraftwerke wurden 2023 geschlossen. Kohle wird in Deutschland aber weiterhin genutzt.', array['Unterscheidet die Schließung der Kernkraftwerke von der Nutzung der Kohle.', 'Stellt klar, dass Kohle weiterhin genutzt wird.']::text[], 2),
  ('tysk-vg2:miljo-og-barekraft', 's04', 'Vergleiche auf Deutsch die Energieversorgung Norwegens und Deutschlands. Nenne für jedes Land die passenden Energiequellen und eine weitere wichtige Besonderheit.', 'Norwegen erhält fast seinen ganzen Strom aus Wasserkraft, ist aber ein großer Öl- und Gasexporteur. Deutschland hat viel Kohle genutzt und viel Wind- und Solarenergie ausgebaut.', array['Nennt Norwegens Wasserkraft und seine Rolle als Öl- und Gasexporteur.', 'Nennt Deutschlands Kohlenutzung und den Ausbau von Wind- und Solarenergie.']::text[], 3),
  ('tysk-vg2:miljo-og-barekraft', 's05', 'Erkläre auf Deutsch, warum man Passiv in den Sätzen „Der Müll wird getrennt“ und „Viele Flaschen werden recycelt“ verwenden kann. Was steht dabei im Mittelpunkt?', 'Im Passiv ist die Handlung wichtiger als die Person, die sie ausführt. In den Beispielen stehen das Sortieren des Mülls und das Recyceln der Flaschen im Mittelpunkt.', array['Erklärt, dass die Handlung wichtiger ist als die handelnde Person.', 'Bezieht die Erklärung passend auf die Handlungen in den Beispielen.']::text[], 4),
  ('tysk-vg2:miljo-og-barekraft', 's06', 'In einem Umweltprojekt soll das Ziel „CO₂ soll reduziert werden“ genannt werden. Formuliere diesen Gedanken auf Deutsch als Passivsatz mit einem Modalverb.', 'CO₂ soll reduziert werden.', array['Verwendet einen passenden Passivsatz mit „soll“.', 'Setzt das Partizip vor das abschließende „werden“.']::text[], 5),
  ('tysk-vg2:miljo-og-barekraft', 's07', 'Eine Austauschschülerin möchte wissen, welche zwei Umweltpraktiken zum Alltag in Deutschland gehören. Nenne sie auf Deutsch.', 'Mülltrennung und Pfand gehören in Deutschland zum Alltag.', array['Nennt Mülltrennung als Teil des Alltags in Deutschland.', 'Nennt Pfand ebenfalls als Teil des Alltags in Deutschland.']::text[], 6),
  ('tysk-vg2:miljo-og-barekraft', 's08', 'Formuliere auf Deutsch eine kurze Stellungnahme mit „Ich bin der Meinung, dass …“. Begründe die Position, dass Deutschland den Übergang zu erneuerbarer Energie fortsetzen sollte, mit einem passenden Fakt über die Energieversorgung des Landes.', 'Ich bin der Meinung, dass Deutschland den Übergang zu erneuerbarer Energie fortsetzen sollte, weil dort weiterhin Kohle genutzt wird.', array['Verwendet „Ich bin der Meinung, dass …“ passend.', 'Begründet die Position mit dem Fakt, dass Kohle in Deutschland weiterhin genutzt wird.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('tysk-vg2:teknologi-og-digitalt-liv', 'tysk-vg2', 'teknologi-og-digitalt-liv', 'Teknologi og digitalt liv', 'Hvordan du snakker om sosiale medier, skjermtid, kunstig intelligens og personvern på tysk, forstår tydelig tale om aktuelle saker, og bruker infinitiv med zu, um … zu og ohne … zu.', array[1, 2, 6]::int[], 1, 'utkast', '{}'::text[], false, now())
