  ('tysk-vg2:teknologi-og-digitalt-liv', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('tysk-vg2:teknologi-og-digitalt-liv', 's01', 'Erkläre auf Deutsch, was mit *Bildschirmzeit* gemeint ist.', 'Die Bildschirmzeit ist die Zeit, die man vor einem Bildschirm verbringt.', array['Erklärt, dass es um die Zeit vor einem Bildschirm geht.']::text[], 0),
  ('tysk-vg2:teknologi-og-digitalt-liv', 's02', 'Eine Nachricht im Internet klingt überraschend. Erkläre auf Deutsch, warum man kritisch sein sollte, bevor man sie teilt.', 'Man sollte kritisch sein, weil es viele Falschmeldungen gibt. Wenn man eine Nachricht teilt, ohne sie zu prüfen, kann man eine Falschmeldung weiterverbreiten.', array['Verknüpft kritisches Denken mit der Gefahr von Falschmeldungen.', 'Erklärt, dass unkritisches Teilen eine Falschmeldung weiterverbreiten kann.']::text[], 1),
  ('tysk-vg2:teknologi-og-digitalt-liv', 's03', 'Vergleiche auf Deutsch einen Vorteil und einen Nachteil des digitalen Lebens. Erkläre kurz, warum das eine ein Vorteil und das andere ein Nachteil ist.', 'Ein Vorteil ist, dass man schnell Informationen finden kann. Ein Nachteil ist, dass viele Menschen zu viel Zeit vor dem Bildschirm verbringen.', array['Nennt einen passenden Vorteil aus dem Stoff.', 'Nennt einen passenden Nachteil aus dem Stoff.']::text[], 2),
  ('tysk-vg2:teknologi-og-digitalt-liv', 's04', 'Gib auf Deutsch ein konkretes Beispiel dafür, wie künstliche Intelligenz beim Lernen helfen kann, und erkläre, warum das ein Vorteil ist.', 'Eine Schülerin kann künstliche Intelligenz nutzen, um beim Lernen Hilfe zu bekommen. Das ist ein Vorteil, weil KI beim Lernen helfen kann.', array['Gibt ein Beispiel für KI als Lernhilfe.', 'Erklärt, warum die Lernhilfe ein Vorteil ist.']::text[], 3),
  ('tysk-vg2:teknologi-og-digitalt-liv', 's05', 'Du benutzt dein Handy, um schnell Informationen zu finden. Schreibe auf Deutsch einen Satz mit *um … zu*, der das ausdrückt.', 'Ich benutze mein Handy, um schnell Informationen zu finden.', array['Drückt aus, dass das Handy zum schnellen Finden von Informationen benutzt wird.', 'Verwendet *um … zu* passend mit dem Infinitiv am Satzende.']::text[], 4),
  ('tysk-vg2:teknologi-og-digitalt-liv', 's06', 'Nina möchte Informationen finden, aber sie postet stattdessen in sozialen Medien. Formuliere den Gegensatz auf Deutsch mit *statt … zu*.', 'Nina postet in den sozialen Medien, statt Informationen zu suchen.', array['Drückt den Gegensatz zwischen Posten und Informationen suchen aus.', 'Verwendet *statt … zu* passend.']::text[], 5),
  ('tysk-vg2:teknologi-og-digitalt-liv', 's07', 'Ein Mitschüler behauptet, dass DSGVO und GDPR zwei verschiedene Regeln sind. Erkläre ihm auf Deutsch, was die Verbindung zwischen diesen Begriffen ist.', 'Die DSGVO ist die Datenschutz-Grundverordnung in Deutschland. Sie ist dasselbe wie die GDPR.', array['Erklärt, dass DSGVO für Datenschutz-Grundverordnung steht.', 'Stellt klar, dass DSGVO und GDPR dasselbe sind.']::text[], 6),
  ('tysk-vg2:teknologi-og-digitalt-liv', 's08', 'Du beendest eine Präsentation über digitale Vorteile und Nachteile. Schreibe einen passenden deutschen Schlusssatz mit *Abschließend* und nenne darin einen Vorteil oder Nachteil aus dem Stoff.', 'Abschließend kann man sagen, dass soziale Medien helfen, mit Freunden in Kontakt zu bleiben.', array['Verwendet *Abschließend* als Einleitung zum Schluss.', 'Nennt einen passenden Vorteil oder Nachteil des digitalen Lebens.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
