insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('tysk-vg2:ungdomskultur', 'q01', 'flervalg', 'Hva er «ein Verein»?', array['En venn', 'En forening eller et lag', 'En skole', 'En festival']::text[], 1, 'Ich bin Mitglied in einem Sportverein.', true, true, 0),
  ('tysk-vg2:ungdomskultur', 'q02', 'flervalg', 'Velg riktig: «Das ist ein ___ Buch.»', array['gutes', 'guter', 'gute', 'guten']::text[], 0, 'Intetkjønn etter ein i nominativ: gutes.', true, true, 1),
  ('tysk-vg2:ungdomskultur', 'q03', 'flervalg', 'Velg riktig: «Ich sehe den ___ Film.»', array['gute', 'guter', 'guten', 'gutes']::text[], 2, 'Akkusativ hankjønn etter den: guten.', true, true, 2),
  ('tysk-vg2:ungdomskultur', 'q04', 'flervalg', 'Velg riktig: «Der Film ist ___.»', array['guter', 'gute', 'guten', 'gut']::text[], 3, 'Etter verbet får adjektivet ingen endelse.', true, true, 3),
  ('tysk-vg2:ungdomskultur', 'q05', 'flervalg', 'Hva er en tandempartner?', array['En som vil lære ditt språk mens du lærer hans eller hennes', 'En sykkelpartner', 'En lærer', 'En klassekamerat']::text[], 0, 'Dere hjelper hverandre.', true, true, 4),
  ('tysk-vg2:ungdomskultur', 'q06', 'flervalg', 'Velg riktig: «Ich trinke ___ Kaffee.»', array['gute', 'guten', 'gut', 'gutes']::text[], 1, 'Uten artikkel, akkusativ hankjønn: guten Kaffee.', true, true, 5),
  ('tysk-vg2:ungdomskultur', 'q07', 'flervalg', 'Hva er Bundesliga?', array['Det tyske parlamentet', 'En musikkfestival', 'Den øverste fotballigaen i Tyskland', 'En skoletype']::text[], 2, 'En av verdens sterkeste ligaer.', true, true, 6),
  ('tysk-vg2:ungdomskultur', 'q08', 'flervalg', 'Hvorfor bør du bruke oversettelsesverktøy kritisk?', array['Fordi de er forbudt', 'Fordi de alltid er feil', 'Fordi de er dyre', 'Fordi de kan gi feil, og du lærer mer ved å sjekke']::text[], 3, 'Sjekk alltid resultatet.', true, true, 7),
  ('tysk-vg2:ungdomskultur', 'q09', 'flervalg', 'Velg riktig: «Das ist eine ___ Idee.»', array['gute', 'guter', 'gutes', 'guten']::text[], 0, 'Hunkjønn etter eine: gute.', true, false, 8),
  ('tysk-vg2:ungdomskultur', 'q10', 'flervalg', 'Hva betyr «in meiner Freizeit»?', array['i ferien min', 'på fritiden min', 'i helgen min', 'på skolen min']::text[], 1, 'die Freizeit = fritiden.', true, false, 9),
  ('tysk-vg2:ungdomskultur', 'm01', 'sant-usant', 'Tysk ungdomsspråk låner mye fra engelsk.', array['Sant', 'Usant']::text[], 0, 'Som norsk ungdomsspråk.', false, true, 10),
  ('tysk-vg2:ungdomskultur', 'm02', 'sant-usant', 'Etter bestemt artikkel i dativ får adjektivet endelsen -e.', array['Sant', 'Usant']::text[], 1, 'I dativ er endelsen -en: dem guten Film.', false, true, 11),
  ('tysk-vg2:ungdomskultur', 'm03', 'sant-usant', 'Å repetere litt hver dag er en god strategi for å lære ord.', array['Sant', 'Usant']::text[], 0, 'Jevnlig repetisjon gir bedre hukommelse.', false, true, 12),
  ('tysk-vg2:ungdomskultur', 'm04', 'sant-usant', 'Adjektiver etter verbet «sein» får alltid endelse på tysk.', array['Sant', 'Usant']::text[], 1, 'Der Film ist gut – ingen endelse.', false, true, 13),
  ('tysk-vg2:ungdomskultur', 'm05', 'flervalg', 'Velg riktig: «Ich höre ___ Musik.» (god, uten artikkel)', array['guter', 'gute', 'gutes', 'guten']::text[], 1, 'Hunkjønn uten artikkel i akkusativ: gute.', false, true, 14),
  ('tysk-vg2:ungdomskultur', 'm06', 'flervalg', 'Hva betyr «Ich bin Mitglied in einem Sportverein»?', array['Jeg er medlem i et idrettslag.', 'Jeg trener alene.', 'Jeg ser på sport.', 'Jeg er trener.']::text[], 0, 'Mitglied = medlem.', false, true, 15),
  ('tysk-vg2:ungdomskultur', 'm07', 'flervalg', 'Velg riktig: «mit dem ___ Freund»', array['gute', 'guter', 'guten', 'gutes']::text[], 2, 'mit tar dativ: dem guten Freund.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('tysk-vg2:ungdomskultur', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('tysk-vg2:ungdomskultur', 's01', 'Hvilke tre forhold bestemmer endelsen til et tysk adjektiv når det står foran et substantiv? Forklar kort.', 'Endelsen avhenger av artikkelen, substantivets kjønn og kasus. Derfor kan samme adjektiv få ulike endelser i ulike uttrykk.', array['Nevner artikkelen som en faktor.', 'Nevner både kjønn og kasus som faktorer.']::text[], 0),
  ('tysk-vg2:ungdomskultur', 's02', 'Skriv to tyske uttrykk med ordet «Buch»: I det ene skal adjektivet stå foran substantivet med bestemt artikkel, og i det andre skal adjektivet stå etter verbet «sein». Forklar hva som skjer med adjektivendelsen.', 'Das gute Buch. Das Buch ist gut. Foran substantivet får adjektivet endelse, mens det etter «ist» ikke får endelse.', array['Gir et korrekt uttrykk med adjektivet foran substantivet, for eksempel «das gute Buch».', 'Gir et korrekt uttrykk med adjektivet etter «ist» uten endelse, og viser forståelse for forskjellen.']::text[], 1),
  ('tysk-vg2:ungdomskultur', 's03', 'Sammenlign en Verein og en festival som deler av fritidskulturen i Tyskland. Ta med én konkret opplysning om hver.', 'En Verein er en forening, for eksempel et idrettslag eller en musikkforening. Festivaler som Rock am Ring samler mange unge hver sommer.', array['Forklarer at en Verein er en forening eller et lag, gjerne innen idrett eller musikk.', 'Forteller at festivaler som Rock am Ring samler mange unge hver sommer.']::text[], 2),
  ('tysk-vg2:ungdomskultur', 's04', 'Forklar hvordan engelsk henger sammen med tysk ungdomsspråk, og ta med én opplysning om «Jugendwort des Jahres».', 'Tysk ungdomsspråk låner mange ord fra engelsk og endrer seg raskt. Hvert år kåres et «Jugendwort des Jahres», altså årets ungdomsord.', array['Forklarer at ungdomsspråket låner mye fra engelsk eller endrer seg raskt.', 'Nevner at årets ungdomsord kåres hvert år.']::text[], 3),
  ('tysk-vg2:ungdomskultur', 's05', 'Du vil bli bedre til å forstå muntlig tysk og huske nye ord. Velg én strategi for hvert mål, og forklar kort hvordan strategiene passer.', 'Jeg kan lytte til tysk musikk eller podkaster for å øve på å forstå tysk. Jeg kan bruke flashcards og repetere litt hver dag for å huske nye ord.', array['Foreslår en relevant lyttestrategi, som tysk musikk eller podkaster.', 'Foreslår ordlister eller flashcards med regelmessig repetisjon for å lære ord.']::text[], 4),
  ('tysk-vg2:ungdomskultur', 's06', 'Du møter de tyske ordene «Haus», «Buch» og «trinken». Forklar hvordan kunnskap i norsk eller engelsk kan hjelpe deg med å forstå minst to av ordene.', 'Jeg kan bruke ord jeg kjenner fra norsk eller engelsk, fordi mange ord ligner. «Haus» ligner på «house», og «Buch» ligner på «book».', array['Bruker minst to av ordene som eksempler på ord som ligner ord fra norsk eller engelsk.', 'Forklarer at slike likheter kan hjelpe med å forstå tyske ord.']::text[], 5),
  ('tysk-vg2:ungdomskultur', 's07', 'Skriv på tysk at du på fritiden spiller håndball og møter vennene dine. Legg også til at du er medlem i et idrettslag.', 'In meiner Freizeit spiele ich Handball und treffe meine Freunde. Ich bin Mitglied in einem Sportverein.', array['Formidler på tysk at personen spiller håndball og møter venner på fritiden.', 'Formidler på tysk at personen er medlem i et idrettslag.']::text[], 6),
  ('tysk-vg2:ungdomskultur', 's08', 'Beskriv hvordan fotball og tysk rap eller pop inngår i fritidskulturen i Tyskland. Ta med én konkret opplysning om hver.', 'Fotball er den største sporten i Tyskland, og Bundesliga er en av verdens sterkeste ligaer. Tysk rap og pop er svært populært, og mange artister synger på tysk.', array['Nevner at fotball er den største sporten, eller at Bundesliga er en av verdens sterkeste ligaer.', 'Nevner at tysk rap eller pop er svært populært, eller at mange artister synger på tysk.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('fransk-vg2:miljo-og-barekraft', 'fransk-vg2', 'miljo-og-barekraft', 'Klima, miljø og bærekraft', 'Hvordan du snakker og skriver om klima og miljø på fransk, franske miljødebatter – Parisavtalen, kjernekraft og borgerpanelet for klima – og hvordan du uttrykker krav og ønsker med subjonctif etter il faut que.', array[4, 5, 8]::int[], 0, 'utkast', '{}'::text[], false, now())
