insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('fransk-vg2:migrasjon-og-mangfold', 'q01', 'flervalg', 'Hvilke land hører til Maghreb?', array['Senegal, Mali og Niger', 'Algerie, Marokko og Tunisia', 'Belgia, Sveits og Luxembourg', 'Egypt, Libya og Sudan']::text[], 1, 'Mange innvandrere i Frankrike har bakgrunn derfra.', true, true, 0),
  ('fransk-vg2:migrasjon-og-mangfold', 'q02', 'flervalg', 'Hva er «les banlieues»?', array['Forstedene rundt storbyene', 'Bankene', 'Landsbygda', 'Sentrum av Paris']::text[], 0, 'Mange med innvandrerbakgrunn bor der.', true, true, 1),
  ('fransk-vg2:migrasjon-og-mangfold', 'q03', 'flervalg', 'Gjør om til indirekte tale: «Je suis fatigué», il a dit → Il a dit qu''il …', array['est fatigué', 'sera fatigué', 'était fatigué', 'soit fatigué']::text[], 2, 'Presens blir imparfait.', true, true, 2),
  ('fransk-vg2:migrasjon-og-mangfold', 'q04', 'flervalg', 'Gjør om: «Je viendrai», elle a dit → Elle a dit qu''elle …', array['viendra', 'vient', 'venait', 'viendrait']::text[], 3, 'Futur blir conditionnel.', true, true, 3),
  ('fransk-vg2:migrasjon-og-mangfold', 'q05', 'flervalg', 'Hvilken fotballspiller har foreldre fra Algerie?', array['Zinedine Zidane', 'Lionel Messi', 'Erling Haaland', 'Cristiano Ronaldo']::text[], 0, 'Han var en av stjernene på VM-laget i 1998.', true, true, 4),
  ('fransk-vg2:migrasjon-og-mangfold', 'q06', 'flervalg', 'Hva betyr «se sentir chez soi»?', array['reise hjem', 'føle seg hjemme', 'bo alene', 'savne hjemmet']::text[], 1, 'chez soi = hjemme.', true, true, 5),
  ('fransk-vg2:migrasjon-og-mangfold', 'q07', 'flervalg', 'Hva skjer med tiden etter «il dit que» (presens)?', array['Presens blir imparfait', 'Presens blir futur', 'Tiden endres ikke', 'Presens blir subjonctif']::text[], 2, 'Bare når innledningen står i fortid, endres tiden.', true, true, 6),
  ('fransk-vg2:migrasjon-og-mangfold', 'q08', 'flervalg', 'Hvorfor kommer mange innvandrere i Frankrike fra land der fransk er et viktig språk?', array['På grunn av turisme', 'På grunn av EU', 'På grunn av fotball', 'På grunn av kolonihistorien']::text[], 3, 'Frankrike hadde store kolonier i Afrika.', true, true, 7),
  ('fransk-vg2:migrasjon-og-mangfold', 'q09', 'flervalg', 'Gjør om: «J''ai mangé», il a dit → Il a dit qu''il …', array['avait mangé', 'a mangé', 'mangeait', 'mangera']::text[], 0, 'Passé composé blir plus-que-parfait.', true, false, 8),
  ('fransk-vg2:migrasjon-og-mangfold', 'q10', 'flervalg', 'Hva betyr «la diversité»?', array['forskjellen', 'mangfoldet', 'avgjørelsen', 'diskusjonen']::text[], 1, 'la diversité culturelle = kulturelt mangfold.', true, false, 9),
  ('fransk-vg2:migrasjon-og-mangfold', 'm01', 'sant-usant', 'Den franske staten registrerer ikke innbyggernes etnisitet.', array['Sant', 'Usant']::text[], 0, 'Det henger sammen med den republikanske tradisjonen.', false, true, 10),
  ('fransk-vg2:migrasjon-og-mangfold', 'm02', 'sant-usant', 'I indirekte tale etter «il a dit que» blir futur til futur.', array['Sant', 'Usant']::text[], 1, 'Futur blir conditionnel.', false, true, 11),
  ('fransk-vg2:migrasjon-og-mangfold', 'm03', 'sant-usant', 'Forstedene er kjent for kreativitet innen rap og dans.', array['Sant', 'Usant']::text[], 0, 'Mange kjente artister kommer derfra.', false, true, 12),
  ('fransk-vg2:migrasjon-og-mangfold', 'm04', 'sant-usant', '«la discrimination» betyr mangfoldet.', array['Sant', 'Usant']::text[], 1, 'la discrimination betyr diskrimineringen. Mangfold heter la diversité.', false, true, 13),
  ('fransk-vg2:migrasjon-og-mangfold', 'm05', 'flervalg', 'Gjør om: «Je t''aime», il a dit → Il a dit qu''il …', array['l''aimait', 't''aime', 'm''aimait', 'l''aime']::text[], 0, 'Både pronomen og tid endres.', false, true, 14),
  ('fransk-vg2:migrasjon-og-mangfold', 'm06', 'flervalg', 'Hva betyr «enrichir la société»?', array['gjøre samfunnet rikere i penger', 'berike samfunnet', 'forandre samfunnet', 'splitte samfunnet']::text[], 1, 'enrichir = berike.', false, true, 15),
  ('fransk-vg2:migrasjon-og-mangfold', 'm07', 'flervalg', 'Hvilket år var det store opptøyer i franske forsteder?', array['1789', '1968', '2005', '2015']::text[], 2, 'Opptøyene spredte seg til mange byer.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('fransk-vg2:migrasjon-og-mangfold', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('fransk-vg2:migrasjon-og-mangfold', 's01', 'Compare l’immigration venue d’Europe du Sud et celle venue du Maghreb en France. Donne une différence précise concernant le contexte ou la période.', 'Des personnes sont venues de pays d’Europe du Sud comme l’Italie, l’Espagne et le Portugal. L’immigration du Maghreb a été particulièrement importante après la Seconde Guerre mondiale, lorsque la France avait besoin de main-d’œuvre.', array['Identifie l’Europe du Sud et le Maghreb comme des régions d’origine.', 'Indique que l’immigration du Maghreb a été particulièrement importante après la Seconde Guerre mondiale, quand la France avait besoin de travailleurs.']::text[], 0),
  ('fransk-vg2:migrasjon-og-mangfold', 's02', 'Explique pourquoi les banlieues françaises peuvent être décrites à la fois comme des lieux de difficultés et de créativité.', 'Beaucoup de personnes y connaissent le chômage et la discrimination. Mais les banlieues sont aussi des lieux de créativité, notamment dans le rap, la danse et le football.', array['Mentionne des difficultés comme le chômage ou la discrimination.', 'Présente aussi une forme de créativité, par exemple le rap, la danse ou le football.']::text[], 1),
  ('fransk-vg2:migrasjon-og-mangfold', 's03', 'Présente les deux points de vue sur la laïcité en France : pourquoi certaines personnes la défendent-elles, et pourquoi d’autres la critiquent-elles ?', 'La laïcité signifie que l’État est neutre sur le plan religieux, ce qui peut garantir l’égalité. D’autres pensent qu’elle rend plus difficile la discussion sur la discrimination ou l’expression de l’identité religieuse.', array['Explique que la laïcité correspond à la neutralité religieuse de l’État et peut être considérée comme une garantie d’égalité.', 'Présente la critique liée à la difficulté de parler de discrimination ou d’exprimer son identité religieuse.']::text[], 2),
  ('fransk-vg2:migrasjon-og-mangfold', 's04', 'Compare les origines familiales de Zinedine Zidane et de Kylian Mbappé.', 'Les parents de Zinedine Zidane viennent d’Algérie. Kylian Mbappé a des racines au Cameroun et en Algérie.', array['Associe les parents de Zidane à l’Algérie.', 'Indique que Mbappé a des racines au Cameroun et en Algérie.']::text[], 3),
  ('fransk-vg2:migrasjon-og-mangfold', 's05', 'Une personne veut que l’État français enregistre l’origine ethnique de chaque citoyen. Explique comment la tradition républicaine française se rapporte à cette idée.', 'Dans la tradition républicaine française, tous les citoyens doivent être égaux. L’État ne relève donc pas l’origine ethnique des citoyens.', array['Explique que le modèle républicain met l’accent sur l’égalité entre les citoyens.', 'Indique que l’État ne relève pas l’origine ethnique.']::text[], 4),
  ('fransk-vg2:migrasjon-og-mangfold', 's06', 'Une personne parle français et une autre langue, et elle dit qu’elle se sent chez elle en France. Explique ce que cette situation montre sur le bilinguisme et l’appartenance.', 'Cette personne est bilingue, car elle parle deux langues. Elle se sent chez elle en France, ce qui exprime un sentiment d’appartenance.', array['Explique que parler deux langues correspond au bilinguisme.', 'Relie le fait de se sentir chez soi à un sentiment d’appartenance.']::text[], 5),
  ('fransk-vg2:migrasjon-og-mangfold', 's07', 'Paul a dit : « Je t’aime. » Rapporte ses paroles au discours indirect en commençant par « Paul a dit que… ».', 'Paul a dit qu’il l’aimait.', array['Utilise « aimait » à l’imparfait après « a dit que ».', 'Remplace les pronoms de la phrase directe par « il » et « l’ ».']::text[], 6),
  ('fransk-vg2:migrasjon-og-mangfold', 's08', 'Dans les banlieues françaises, certaines personnes connaissent le chômage et la discrimination, mais on y trouve aussi de la créativité dans le rap, la danse et le football. Explique comment ces faits illustrent l’idée que l’immigration peut enrichir la société alors que l’intégration peut être difficile.', 'La créativité dans le rap, la danse et le football montre que l’immigration peut enrichir la société. Le chômage et la discrimination vécus dans les banlieues montrent que l’intégration peut aussi être difficile.', array['Relie une forme de créativité des banlieues à l’idée que l’immigration enrichit la société.', 'Relie le chômage ou la discrimination à des difficultés d’intégration.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('fransk-vg2:studier-og-arbeid-i-utlandet', 'fransk-vg2', 'studier-og-arbeid-i-utlandet', 'Studier og arbeid i fransktalende land', 'Muligheter for å studere og jobbe i Frankrike, Belgia, Sveits og Québec – Erasmus+, au pair og sommerjobb – formell søknad og intervju på fransk, og hvordan du snakker om det som kunne ha skjedd med plus-que-parfait og conditionnel passé.', array[2, 3, 5]::int[], 3, 'utkast', '{}'::text[], false, now())
