insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('spansk-vg2:litteratur', 'q01', 'flervalg', 'Hva pålegger Bernarda døtrene sine i «La casa de Bernarda Alba»?', array['Å gifte seg', 'Åtte års sorg innestengt i huset', 'Å flytte til Madrid', 'Å bli nonner']::text[], 1, 'Stykket handler om undertrykkelse og ære.', true, true, 0),
  ('spansk-vg2:litteratur', 'q02', 'flervalg', 'Hvem var den første latinamerikanske forfatteren som fikk Nobelprisen i litteratur?', array['Gabriela Mistral', 'Pablo Neruda', 'Julio Cortázar', 'García Lorca']::text[], 0, 'Hun fikk prisen i 1945.', true, true, 1),
  ('spansk-vg2:litteratur', 'q03', 'flervalg', 'Hva skjer i «Continuidad de los parques»?', array['En mann reiser til en park', 'To elskende gifter seg', 'Leseren av en roman viser seg å være offeret i romanen', 'En gutt mister sin hund']::text[], 2, 'Fortellingen leker med fiksjon og virkelighet.', true, true, 2),
  ('spansk-vg2:litteratur', 'q04', 'flervalg', 'Hva er magisk realisme?', array['Fantasy med drager', 'Realistiske krimromaner', 'Dikt om magikere', 'Overnaturlige hendelser beskrevet som en naturlig del av hverdagen']::text[], 3, 'Særlig knyttet til Latin-Amerika.', true, true, 3),
  ('spansk-vg2:litteratur', 'q05', 'flervalg', 'Hva betyr «el qué dirán»?', array['Hva folk sier – frykten for sladder', 'Hva som skjer i morgen', 'Hva læreren sier', 'Hva vi skal si']::text[], 0, 'Et sentralt tema i Bernarda Alba.', true, true, 4),
  ('spansk-vg2:litteratur', 'q06', 'flervalg', 'Hvordan døde García Lorca?', array['Av sykdom i eksil', 'Han ble drept tidlig i borgerkrigen', 'I en ulykke i New York', 'Av alderdom']::text[], 1, 'Han ble drept av nasjonalistene i 1936.', true, true, 5),
  ('spansk-vg2:litteratur', 'q07', 'flervalg', 'Hva betyr «la trama»?', array['tragedien', 'trærne', 'handlingen', 'temaet']::text[], 2, 'la trama de la novela = romanens handling.', true, true, 6),
  ('spansk-vg2:litteratur', 'q08', 'flervalg', 'Hvilket land kom Julio Cortázar fra?', array['Spania', 'Chile', 'Mexico', 'Argentina']::text[], 3, 'Han er kjent for sine cuentos.', true, true, 7),
  ('spansk-vg2:litteratur', 'q09', 'flervalg', 'Hvordan sier du «Teksten handler om ensomhet»?', array['El texto trata de la soledad.', 'El texto es soledad.', 'La soledad trata el texto.', 'El texto hace soledad.']::text[], 0, 'tratar de = handle om.', true, false, 8),
  ('spansk-vg2:litteratur', 'q10', 'flervalg', 'Hvilken verbtid brukes ofte for bakgrunn i en fortelling?', array['Indefinido', 'Imperfecto', 'Futuro', 'Imperativ']::text[], 1, 'Indefinido brukes for handlinger.', true, false, 9),
  ('spansk-vg2:litteratur', 'm01', 'sant-usant', 'García Lorca var fra Andalucía.', array['Sant', 'Usant']::text[], 0, 'Andalucía preger mange av diktene hans.', false, true, 10),
  ('spansk-vg2:litteratur', 'm02', 'sant-usant', 'Gabriela Mistral var fra Argentina.', array['Sant', 'Usant']::text[], 1, 'Hun var fra Chile.', false, true, 11),
  ('spansk-vg2:litteratur', 'm03', 'sant-usant', 'Korte tekster åpner seg ofte ved andre gangs lesing.', array['Sant', 'Usant']::text[], 0, 'Detaljer man overså første gang, blir tydelige.', false, true, 12),
  ('spansk-vg2:litteratur', 'm04', 'sant-usant', '«La casa de Bernarda Alba» er en lykkelig komedie.', array['Sant', 'Usant']::text[], 1, 'Det er et tragisk drama om undertrykkelse.', false, true, 13),
  ('spansk-vg2:litteratur', 'm05', 'flervalg', 'Hva betyr «el cuento»?', array['regnskapet', 'den korte fortellingen', 'kontoen', 'hjørnet']::text[], 1, 'Cortázar er kjent for cuentos.', false, true, 14),
  ('spansk-vg2:litteratur', 'm06', 'flervalg', 'Hva betyr «Me identifico con la protagonista»?', array['Jeg kjenner meg igjen i hovedpersonen.', 'Jeg liker ikke hovedpersonen.', 'Jeg er hovedpersonen.', 'Jeg har møtt hovedpersonen.']::text[], 0, 'identificarse con = kjenne seg igjen i.', false, true, 15),
  ('spansk-vg2:litteratur', 'm07', 'flervalg', 'Hvilken forfatter forbindes særlig med magisk realisme?', array['Cervantes', 'García Lorca', 'Gabriel García Márquez', 'Gabriela Mistral']::text[], 2, 'Hundre års ensomhet er et hovedverk.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('spansk-vg2:litteratur', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('spansk-vg2:litteratur', 's01', 'I *Romancero gitano* bruker Federico García Lorca folkelige former og sterke bilder knyttet til Andalucía, døden og lidenskap. Forklar hvordan disse trekkene preger diktsamlingen.', 'Lorca kombinerer folkelige uttrykksformer med sterke bilder. Bildene knytter diktene til Andalucía og temaer som døden og lidenskap.', array['Forklarer at diktsamlingen bruker folkelige former og sterke bilder.', 'Knytter bildene til Andalucía og minst ett av temaene døden eller lidenskap.']::text[], 0),
  ('spansk-vg2:litteratur', 's02', 'I *La casa de Bernarda Alba* sperrer Bernarda døtrene sine inne og holder dem i sorg etter farens død. Forklar hvordan situasjonen kan knyttes både til undertrykkelse og til *el qué dirán*.', 'Døtrene blir fratatt friheten sin, noe som viser undertrykkelse. *El qué dirán* handler om frykten for hva folk vil si, og denne frykten knyttes til ære og sosial kontroll.', array['Forklarer at døtrene mangler frihet eller blir undertrykt.', 'Knytter *el qué dirán* til frykt for sladder eller hva andre mener.']::text[], 1),
  ('spansk-vg2:litteratur', 's03', 'Federico García Lorca var fra Andalucía og skrev *Romancero gitano*, med bilder av Andalucía, døden og lidenskap. Gabriela Mistral var fra Chile og skrev dikt om kjærlighet, barn, sorg og natur i Latin-Amerika. Sammenlign forfatterskapene ved å nevne én forskjell i hva diktene deres forbindes med.', 'Lorca knyttes blant annet til bilder av Andalucía, døden og lidenskap. Mistrals dikt forbindes med temaer som kjærlighet, barn, sorg og natur i Latin-Amerika.', array['Nevner en relevant forskjell mellom temaene eller bildene hos Lorca og Mistral.', 'Knytter opplysningene til riktig forfatter.']::text[], 2),
  ('spansk-vg2:litteratur', 's04', 'I en fortelling blir et vanlig objekt brukt slik at det står for en større idé eller betydning. Hvilket analysebegrep på spansk passer, og hvorfor?', 'Begrepet er *el símbolo*. Objektet fungerer som et symbol fordi det står for noe mer enn seg selv.', array['Bruker begrepet *el símbolo*.', 'Forklarer at objektet representerer eller viser til en større betydning.']::text[], 3),
  ('spansk-vg2:litteratur', 's05', 'I Cortázars *Continuidad de los parques* leser en mann en roman om et planlagt drap, og leseren forstår til slutt at mannen selv er offeret. Forklar hvordan dette gjør forholdet mellom fiksjon og virkelighet til et viktig trekk ved fortellingen.', 'Fortellingen lar handlingen i romanen mannen leser gripe inn i situasjonen hans. Dermed blir skillet mellom fiksjonen og virkeligheten i fortellingen uklart.', array['Forklarer at handlingen i romanen knyttes til mannen som leser.', 'Viser at dette gjør grensen mellom fiksjon og virkelighet uklar.']::text[], 4),
  ('spansk-vg2:litteratur', 's06', 'Du analyserer en spansk fortelling. Først beskrives et hus og stemningen der; senere fortelles det at en person åpner en dør. Hvilken verbtid passer best til bakgrunnen, og hvilken passer best til den avsluttede handlingen? Forklar kort hvorfor.', 'Imperfecto passer til beskrivelsen av huset og stemningen, fordi det er bakgrunn. Indefinido passer til at personen åpner døren, fordi det er en handling i fortellingen.', array['Velger imperfecto til bakgrunnsbeskrivelsen.', 'Velger indefinido til den avsluttede handlingen og forklarer forskjellen.']::text[], 5),
  ('spansk-vg2:litteratur', 's07', 'I *Continuidad de los parques* følger leseren en mann som sitter og leser en roman, og mannen viser seg til slutt å være offeret i romanen. Hvem er *el protagonista* i denne fortellingen, og hva betyr begrepet?', '*El protagonista* betyr hovedpersonen. I denne fortellingen er mannen som leser romanen hovedpersonen.', array['Forklarer at *el protagonista* betyr hovedpersonen.', 'Identifiserer mannen som leser som hovedpersonen.']::text[], 6),
  ('spansk-vg2:litteratur', 's08', 'Du leser en kort spansk fortelling og forstår ikke alle ordene. Beskriv to lesestrategier du kan bruke, og forklar hvordan hver av dem kan hjelpe deg.', 'Jeg kan se etter ord som ligner på norsk eller engelsk, og gjette betydningen ut fra sammenhengen. Jeg kan også lese teksten på nytt, siden detaljer i korte tekster kan bli tydeligere ved andre gangs lesing.', array['Nevner to strategier fra lesestrategiene, for eksempel å se etter ordlikheter, gjette ut fra sammenhengen eller lese på nytt.', 'Forklarer hvordan strategiene kan hjelpe med å forstå teksten.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('spansk-vg2:ungdomskultur', 'spansk-vg2', 'ungdomskultur', 'Ungdomskultur, fester og språklæring', 'Ungdomskultur og fester i den spansktalende verden – fotball, musikk, San Fermín, La Tomatina og Día de Muertos – slang fra Spania og Latin-Amerika, forskjellen på por og para, og strategier for å lære spansk videre.', array[1, 2, 7]::int[], 5, 'utkast', '{}'::text[], false, now())
