  ('spansk-vg2:ungdomskultur', 'q01', 'flervalg', 'Hvor arrangeres San Fermín?', array['Valencia', 'Pamplona', 'Buñol', 'Sevilla']::text[], 1, 'Oksene løper gjennom gatene.', true, true, 0),
  ('spansk-vg2:ungdomskultur', 'q02', 'flervalg', 'Hva er Día de Muertos?', array['En mexicansk tradisjon der de døde minnes', 'En skrekkfilm', 'En fotballkamp', 'En spansk nasjonaldag']::text[], 0, 'Feires 1.–2. november.', true, true, 1),
  ('spansk-vg2:ungdomskultur', 'q03', 'flervalg', 'Velg riktig: «Este regalo es ___ ti.»', array['por', 'a', 'para', 'de']::text[], 2, 'Mottaker: para.', true, true, 2),
  ('spansk-vg2:ungdomskultur', 'q04', 'flervalg', 'Velg riktig: «Gracias ___ todo.»', array['para', 'a', 'con', 'por']::text[], 3, 'gracias por.', true, true, 3),
  ('spansk-vg2:ungdomskultur', 'q05', 'flervalg', 'Hva betyr «vale» i Spania?', array['ok', 'farvel', 'dal', 'verdi']::text[], 0, '¿Quedamos a las ocho? – ¡Vale!', true, true, 4),
  ('spansk-vg2:ungdomskultur', 'q06', 'flervalg', 'Velg riktig: «Estudio ___ aprender.»', array['por', 'para', 'de', 'en']::text[], 1, 'Formål: para.', true, true, 5),
  ('spansk-vg2:ungdomskultur', 'q07', 'flervalg', 'Hva er El Clásico?', array['En musikkfestival', 'En gammel bil', 'Kampen mellom Real Madrid og FC Barcelona', 'En dans']::text[], 2, 'Følges over hele verden.', true, true, 6),
  ('spansk-vg2:ungdomskultur', 'q08', 'flervalg', 'Velg riktig: «___ la lluvia, no salimos.»', array['Para', 'Con', 'A', 'Por']::text[], 3, 'Årsak: por.', true, true, 7),
  ('spansk-vg2:ungdomskultur', 'q09', 'flervalg', 'Hvilket ord betyr «kult» i Mexico?', array['chido', 'guay', 'vale', 'tío']::text[], 0, 'Guay er vanlig i Spania.', true, false, 8),
  ('spansk-vg2:ungdomskultur', 'q10', 'flervalg', 'Hva betyr «Los fines de semana quedo con mis amigos»?', array['I helgene blir jeg hjemme.', 'I helgene møter jeg vennene mine.', 'I helgene ringer jeg vennene mine.', 'I helgene jobber jeg.']::text[], 1, 'quedar con = møte (avtale med).', true, false, 9),
  ('spansk-vg2:ungdomskultur', 'm01', 'sant-usant', 'La Tomatina er en tomatkrig i Buñol.', array['Sant', 'Usant']::text[], 0, 'Den arrangeres i august.', false, true, 10),
  ('spansk-vg2:ungdomskultur', 'm02', 'sant-usant', '«para» brukes for å uttrykke årsak.', array['Sant', 'Usant']::text[], 1, 'Årsak uttrykkes med por.', false, true, 11),
  ('spansk-vg2:ungdomskultur', 'm03', 'sant-usant', 'Slang varierer mellom Spania og landene i Latin-Amerika.', array['Sant', 'Usant']::text[], 0, 'Guay i Spania, chido i Mexico, chévere i Colombia.', false, true, 12),
  ('spansk-vg2:ungdomskultur', 'm04', 'sant-usant', 'Día de Muertos er en trist dag uten musikk.', array['Sant', 'Usant']::text[], 1, 'Dagen feires med blomster, altere og musikk.', false, true, 13),
  ('spansk-vg2:ungdomskultur', 'm05', 'flervalg', 'Velg riktig: «Paseamos ___ el parque.»', array['para', 'por', 'a', 'de']::text[], 1, 'Gjennom et sted: por.', false, true, 14),
  ('spansk-vg2:ungdomskultur', 'm06', 'flervalg', 'Velg riktig: «Los deberes son ___ el lunes.»', array['para', 'por', 'en', 'a']::text[], 0, 'Frist: para.', false, true, 15),
  ('spansk-vg2:ungdomskultur', 'm07', 'flervalg', 'Hvilken artist kommer fra Puerto Rico?', array['Rosalía', 'Shakira', 'Bad Bunny', 'Enrique Iglesias']::text[], 2, 'Rosalía er fra Spania og Shakira fra Colombia.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('spansk-vg2:ungdomskultur', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('spansk-vg2:ungdomskultur', 's01', 'Sammenlign Las Fallas og La Tomatina: Hvor arrangeres de, når skjer de, og hva er typisk for hver fest?', 'Las Fallas arrangeres i Valencia i mars, og store figurer brennes til slutt. La Tomatina arrangeres i Buñol i august og er en stor tomatkrig.', array['Plasserer Las Fallas i Valencia i mars og nevner at figurer brennes.', 'Plasserer La Tomatina i Buñol i august og beskriver den som en tomatkrig.']::text[], 0),
  ('spansk-vg2:ungdomskultur', 's02', 'Día de Muertos i Mexico er en tradisjon for å minnes de døde. Nevn to konkrete ting som brukes under feiringen, og forklar hvordan de passer til formålet.', 'Altere og blomster brukes for å minnes de døde. Sukkerhodeskaller og musikk er også elementer i feiringen.', array['Nevner minst to av elementene: altere, blomster, sukkerhodeskaller eller musikk.', 'Knytter elementene til at de døde minnes.']::text[], 1),
  ('spansk-vg2:ungdomskultur', 's03', 'En venn i Venezuela sier «¡Qué chévere!» om en fest, mens en venn i Spania sier «¡Mola!». Forklar hva uttrykkene har til felles, og hvor de brukes.', 'Begge uttrykkene betyr «kult». «Chévere» brukes blant annet i Venezuela, mens «mola» brukes i Spania.', array['Forklarer at begge uttrykkene betyr «kult».', 'Knytter «chévere» til Venezuela eller andre land som Colombia, og «mola» til Spania.']::text[], 2),
  ('spansk-vg2:ungdomskultur', 's04', 'Forklar forskjellen på «por» og «para» i setningene «Estudio por la mañana» og «Los deberes son para el lunes». Hva uttrykker hvert ord her?', '«Por» viser til tidspunktet eller tidsrommet, altså om morgenen. «Para» viser her til en frist: leksene skal være klare til mandag.', array['Forklarer at «por» brukes om tid eller tidsrom i den første setningen.', 'Forklarer at «para» uttrykker frist i den andre setningen.']::text[], 3),
  ('spansk-vg2:ungdomskultur', 's05', 'En klassekamerat tror at Bad Bunny er fra Spania, og at Rosalía er fra Puerto Rico. Rett opp misforståelsen ved å oppgi hvor hver artist kommer fra.', 'Bad Bunny kommer fra Puerto Rico. Rosalía kommer fra Spania.', array['Plasserer Bad Bunny i Puerto Rico.', 'Plasserer Rosalía i Spania.']::text[], 4),
  ('spansk-vg2:ungdomskultur', 's06', 'Du vil bli bedre til å forstå muntlig spansk. Foreslå to læringsstrategier fra pensum som passer til dette målet, og forklar kort hvordan de kan hjelpe.', 'Jeg kan lytte til spansk musikk eller podkaster for å høre språket brukt muntlig. Jeg kan også se serier med spansk teksting og følge med på ordene mens jeg lytter.', array['Foreslår lytting til spansk musikk eller podkaster.', 'Foreslår serier med spansk teksting og knytter strategiene til å øve på å forstå spansk.']::text[], 5),
  ('spansk-vg2:ungdomskultur', 's07', 'Du lærer spansk og finner en språkpartner som snakker spansk og ønsker å lære norsk eller engelsk. Forklar hvordan et intercambio kan være nyttig for begge.', 'Du kan øve på spansk sammen med språkpartneren. Partneren kan samtidig øve på norsk eller engelsk sammen med deg.', array['Forklarer at eleven får øve på spansk med en spansktalende partner.', 'Forklarer at partneren kan få øve på norsk eller engelsk.']::text[], 6),
  ('spansk-vg2:ungdomskultur', 's08', 'Du besøker venner i Spania og foreslår å starte kvelden klokka 20. Mange unge der går ut sent, og kvelden starter ofte etter klokka 22. Forklar hvordan forslaget ditt kan oppfattes i lys av denne vanen.', 'Forslaget om å starte klokka 20 kan oppfattes som tidlig. Mange unge i Spania starter kvelden først etter klokka 22.', array['Forklarer at klokka 20 er tidligere enn det som ofte er vanlig.', 'Oppgir at kvelden ofte starter etter klokka 22.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('kinesisk-vg2:mat-og-restaurant', 'kinesisk-vg2', 'mat-og-restaurant', 'Mat og restaurant', 'Hvordan du bestiller mat, snakker om smak og betaler på restaurant i Kina, forskjellen på 想 og 要, spørsmål med 还是, og regionale kjøkken som sichuanmat, dim sum og Peking-and.', array[2, 3, 8]::int[], 0, 'utkast', '{}'::text[], false, now())
