insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('geofag-1:vannets-kretslop', 'q01', 'flervalg', 'Hvor mye av vannet på jorda er ferskvann?', array['Omtrent 50 %', 'Omtrent 2,5 %', 'Omtrent 25 %', 'Omtrent 97,5 %']::text[], 1, 'Resten er saltvann i havet.', true, true, 0),
  ('geofag-1:vannets-kretslop', 'q02', 'flervalg', 'Hvor finnes mesteparten av ferskvannet?', array['I isbreer og snø', 'I elver', 'I innsjøer', 'I atmosfæren']::text[], 0, 'Nesten 70 % av ferskvannet.', true, true, 1),
  ('geofag-1:vannets-kretslop', 'q03', 'flervalg', 'Hva er evapotranspirasjon?', array['Nedbør og avrenning', 'Vann som siver ned', 'Fordampning pluss transpirasjon fra planter', 'Kondensasjon i skyer']::text[], 2, 'Vannet går tilbake til atmosfæren.', true, true, 2),
  ('geofag-1:vannets-kretslop', 'q04', 'flervalg', 'Hva er et nedbørfelt?', array['Et område med mye regn', 'En innsjø', 'Et grunnvannsmagasin', 'Området som drenerer til et punkt i en elv']::text[], 3, 'Grensene går langs vannskillene.', true, true, 3),
  ('geofag-1:vannets-kretslop', 'q05', 'flervalg', 'Hva står A for i vannbalanselikningen N = F + A + ΔM?', array['Avrenning', 'Atmosfære', 'Akvifer', 'Areal']::text[], 0, 'N er nedbør, F fordampning.', true, true, 4),
  ('geofag-1:vannets-kretslop', 'q06', 'flervalg', 'Hvorfor får byer oftere overvannsflom?', array['Det regner mer i byer', 'Tette flater hindrer infiltrasjon', 'Byer ligger alltid lavt', 'Grunnvannet er høyere']::text[], 1, 'Regnet renner raskt av.', true, true, 5),
  ('geofag-1:vannets-kretslop', 'q07', 'flervalg', 'Hvilket materiale gir en god akvifer?', array['Leire', 'Massivt granitt uten sprekker', 'Sand og grus', 'Asfalt']::text[], 2, 'God porøsitet og permeabilitet.', true, true, 6),
  ('geofag-1:vannets-kretslop', 'q08', 'flervalg', 'Hvordan påvirker klimaendringer vannets kretsløp i Norge?', array['Mindre nedbør og flere breer', 'Ingen endring', 'Mer snø i lavlandet', 'Mer nedbør, kraftigere regnskyll og krympende breer']::text[], 3, 'Flommene endrer tidspunkt.', true, true, 7),
  ('geofag-1:vannets-kretslop', 'q09', 'flervalg', 'Omtrent hvor lenge blir et vannmolekyl i atmosfæren?', array['Omtrent ti dager', 'Ett år', 'Hundre år', 'Tusen år']::text[], 0, 'Grunnvann og is kan lagre vann mye lenger.', true, false, 8),
  ('geofag-1:vannets-kretslop', 'q10', 'flervalg', 'Hva er et regnbed?', array['En type seng', 'En blågrønn løsning der regnvann får infiltrere', 'En demning', 'En type akvifer']::text[], 1, 'Det demper overvann i byer.', true, false, 9),
  ('geofag-1:vannets-kretslop', 'm01', 'sant-usant', 'Vannets kretsløp drives av solenergi og tyngdekraft.', array['Sant', 'Usant']::text[], 0, 'Sola fordamper vann, tyngdekraften får det til å renne.', false, true, 10),
  ('geofag-1:vannets-kretslop', 'm02', 'sant-usant', 'Leire slipper vann lett gjennom.', array['Sant', 'Usant']::text[], 1, 'Leire har lav permeabilitet.', false, true, 11),
  ('geofag-1:vannets-kretslop', 'm03', 'sant-usant', 'Vassdragsregulering jevner ut vannføringen i elvene.', array['Sant', 'Usant']::text[], 0, 'Vann lagres i magasiner og slippes ut ved behov.', false, true, 12),
  ('geofag-1:vannets-kretslop', 'm04', 'sant-usant', 'Avskoging gir langsommere avrenning.', array['Sant', 'Usant']::text[], 1, 'Avskoging gir raskere avrenning og mer erosjon.', false, true, 13),
  ('geofag-1:vannets-kretslop', 'm05', 'flervalg', 'Hva er tredje trinn i tretrinnsstrategien for overvann?', array['Infiltrere', 'Sikre trygge flomveier for de største mengdene', 'Fordampe', 'Pumpe ut alt vann']::text[], 1, 'Først infiltrere, så fordrøye, så flomveier.', false, true, 14),
  ('geofag-1:vannets-kretslop', 'm06', 'flervalg', 'Hva er et vannskille?', array['Grensen mellom to nedbørfelt', 'En demning', 'Et grunnvannsspeil', 'En elvemunning']::text[], 0, 'Går langs de høyeste punktene.', false, true, 15),
  ('geofag-1:vannets-kretslop', 'm07', 'flervalg', 'Hva kalles vann som siver ned til grunnvannet?', array['Kondensasjon', 'Transpirasjon', 'Perkolasjon', 'Avrenning']::text[], 2, 'Etter infiltrasjonen i jorda.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('geofag-1:vannets-kretslop', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('geofag-1:vannets-kretslop', 's01', 'Etter nedbør siver noe vann ned i jorda, og noe av dette beveger seg videre ned til grunnvannet. Forklar forskjellen på infiltrasjon og perkolasjon.', 'Infiltrasjon er når vann siver ned i jorda. Perkolasjon er når vannet siver videre ned mot grunnvannet.', array['Skiller mellom at vann først siver ned i jorda og deretter videre mot grunnvannet.']::text[], 0),
  ('geofag-1:vannets-kretslop', 's02', 'En by har mange asfaltflater og tak. Forklar hvordan dette kan føre til overvannsflom når det regner.', 'Asfalt og tak hindrer vann i å infiltrere i jorda. Derfor renner regnet raskere av på overflaten, og det kan oppstå overvannsflom.', array['Forklarer at tette flater hindrer infiltrasjon.', 'Knytter dette til raskere avrenning og fare for overvannsflom.']::text[], 1),
  ('geofag-1:vannets-kretslop', 's03', 'En akvifer er et grunnvannsmagasin som vi kan hente vann fra. Sammenlign sand og grus med leire som materiale i en akvifer.', 'Sand og grus slipper vann lett gjennom og kan derfor gi gode akviferer. Leire kan holde mye vann, men slipper det nesten ikke gjennom.', array['Forklarer at sand og grus har god permeabilitet og egner seg godt som akvifer.', 'Får fram at leire slipper vann svært dårlig gjennom, selv om den holder mye vann.']::text[], 2),
  ('geofag-1:vannets-kretslop', 's04', 'Rundt 2,5 % av alt vann på jorda er ferskvann, og nesten 70 % av ferskvannet er bundet i isbreer og snø. Omtrent hvor stor prosentandel av alt vann på jorda er da bundet i isbreer og snø? Vis det viktigste regnestykket.', 'Omtrent 1,75 % av alt vannet er bundet i isbreer og snø. Regnestykket er 0,70 × 2,5 % = 1,75 %.', array['Bruker 70 % av 2,5 % i regnestykket.', 'Kommer fram til omtrent 1,75 % av alt vannet.']::text[], 3),
  ('geofag-1:vannets-kretslop', 's05', 'Vannbalanselikningen for et nedbørfelt er N = F + A + ΔM, der N er nedbør, F er fordampning, A er avrenning og ΔM er endring i magasin. Over flere år er ΔM nær null. Hva forteller likningen da om forholdet mellom nedbør, fordampning og avrenning?', 'Når ΔM er nær null, er nedbøren omtrent lik summen av fordampning og avrenning: N ≈ F + A.', array['Bruker at ΔM er nær null til å forenkle likningen til N ≈ F + A.', 'Forklarer at nedbøren omtrent fordeles mellom fordampning og avrenning.']::text[], 4),
  ('geofag-1:vannets-kretslop', 's06', 'Et høydedrag ligger mellom to elver som renner hver sin vei. Forklar hva vannskillet er her, og hvordan det påvirker hvor vannet fra regn renner.', 'Høydedraget utgjør vannskillet, altså grensen mellom to nedbørfelt. Regn på hver side drenerer mot hvert sitt nedbørfelt og dermed mot ulike elver.', array['Identifiserer høydedraget som grensen mellom nedbørfeltene.', 'Forklarer at vann på hver side drenerer mot ulike elver.']::text[], 5),
  ('geofag-1:vannets-kretslop', 's07', 'Omtrent 97,5 % av vannet på jorda er saltvann, mens rundt 2,5 % er ferskvann. Omtrent hvor mange ganger så mye saltvann som ferskvann er det? Vis det viktigste regnestykket.', 'Det er omtrent 39 ganger så mye saltvann som ferskvann. Regnestykket er 97,5 ÷ 2,5 = 39.', array['Deler andelen saltvann på andelen ferskvann.', 'Kommer fram til omtrent 39 ganger så mye saltvann.']::text[], 6),
  ('geofag-1:vannets-kretslop', 's08', 'Sammenlign hvor lenge et vannmolekyl kan være i atmosfæren, med hvor lenge det kan være i et dypt grunnvannsmagasin eller en isbre. Hva sier dette om oppholdstid?', 'Et vannmolekyl kan være i atmosfæren i omtrent ti dager, men i dype grunnvannsmagasiner eller isbreer i tusenvis av år. Oppholdstid er hvor lenge vannet blir i et magasin.', array['Sammenligner omtrent ti dager i atmosfæren med tusenvis av år i dypt grunnvann eller isbreer.', 'Forklarer at oppholdstid er hvor lenge vannet blir i et magasin.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('geofag-1:ferskvannsressurser', 'geofag-1', 'ferskvannsressurser', 'Ferskvann som ressurs', 'Hvordan ferskvann brukes til drikkevann, jordbruk, industri og energi i Norge og verden, hvorfor vannmangel og konflikter oppstår, og hva bærekraftig vannforvaltning innebærer.', array[8]::int[], 7, 'utkast', '{}'::text[], false, now())
