  ('geofag-1:geologiske-ressurser', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('geofag-1:geologiske-ressurser', 's01', 'Varme væsker kan sirkulere i sprekker i berggrunnen. Forklar hvordan slike hydrotermale løsninger kan danne metallforekomster.', 'De varme væskene beveger seg gjennom sprekker og feller ut metaller når forholdene endres. Metallene kan dermed samle seg i ganger i berggrunnen.', array['Forklarer at varme væsker sirkulerer i sprekker.', 'Forklarer at væskene feller ut metaller, som samles i ganger.']::text[], 0),
  ('geofag-1:geologiske-ressurser', 's02', 'Sammenlign dagbrudd med utvinning i en gruve under jorda.', 'Et dagbrudd er et åpent brudd på overflaten, mens en gruve under jorda henter ut malm eller mineraler fra dypet.', array['Beskriver dagbrudd som utvinning i et åpent brudd på overflaten.', 'Skiller dette fra utvinning i en gruve under jorda.']::text[], 1),
  ('geofag-1:geologiske-ressurser', 's03', 'Et geologisk kart og prøver av bekkesand tyder på at det kan finnes en metallforekomst i dypet. Hvilken metode kan brukes for å bekrefte hva som finnes der, og hva viser prøven?', 'Man kan bore og ta opp en kjerneprøve. Den viser hvilke bergarter og mineraler som finnes i dypet.', array['Foreslår boring for å undersøke forekomsten.', 'Forklarer at kjerneprøven viser hva som finnes i dypet.']::text[], 2),
  ('geofag-1:geologiske-ressurser', 's04', 'Forklar hvordan olje og gass kan bli fanget i en geologisk felle.', 'Olje og gass vandrer oppover og samles i en porøs reservoarbergart. En tett takbergart hindrer dem i å lekke videre opp, slik at de blir fanget.', array['Forklarer at olje og gass vandrer oppover og samles i en porøs reservoarbergart.', 'Forklarer at en tett takbergart hindrer lekkasje og bidrar til at de fanges.']::text[], 3),
  ('geofag-1:geologiske-ressurser', 's05', 'Sammenlign seismikk med geokjemiske analyser som metoder for å undersøke mulige geologiske ressurser.', 'Seismikk bruker lydbølger som reflekteres fra lag i undergrunnen. Geokjemiske analyser undersøker prøver av for eksempel stein, jord eller bekkesand.', array['Forklarer at seismikk bruker lydbølger til å kartlegge lag i undergrunnen.', 'Forklarer at geokjemiske analyser undersøker materiale som stein, jord eller bekkesand.']::text[], 4),
  ('geofag-1:geologiske-ressurser', 's06', 'Et lokalsamfunn vurderer gruvedrift. Forklar én fordel og én mulig ulempe ved utvinningen, og nevn ett tiltak som kan gjøre den mer bærekraftig.', 'Gruvedrift kan gi arbeidsplasser og råstoffer, men kan også føre til naturinngrep eller konflikt med for eksempel reindrift og friluftsliv. God arealplanlegging eller strenge miljøkrav kan gjøre utvinningen mer bærekraftig.', array['Nevner en relevant fordel, som arbeidsplasser, inntekter eller råstoffer.', 'Nevner en relevant ulempe, som naturinngrep eller konflikt med andre interesser.', 'Nevner et relevant tiltak, som arealplanlegging, miljøkrav eller at berørte interesser blir hørt.']::text[], 5),
  ('geofag-1:geologiske-ressurser', 's07', 'Oljevinduet går fra omtrent 60 °C til 120 °C. Hvor stor er temperaturforskjellen mellom grensene? Vis det viktigste regnestykket.', 'Temperaturforskjellen er 60 °C. Regnestykket er 120 − 60 = 60.', array['Regner ut forskjellen ved å trekke den nedre grensen fra den øvre.', 'Oppgir 60 °C.']::text[], 6),
  ('geofag-1:geologiske-ressurser', 's08', 'Oljevinduet går fra omtrent 60 °C til 120 °C. Hvor mange ganger så høy er den øvre temperaturgrensen som den nedre? Vis det viktigste regnestykket.', 'Den øvre grensen er 2 ganger så høy som den nedre. Regnestykket er 120 ÷ 60 = 2.', array['Deler den øvre temperaturgrensen på den nedre.', 'Oppgir at den øvre grensen er 2 ganger så høy.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('geofag-1:naturfarer', 'geofag-1', 'naturfarer', 'Naturfarer, risiko og modellering', 'Skred, flom, jordskjelv, vulkanutbrudd og tsunamier – hvordan de oppstår, hvordan vi vurderer risiko med kart og modeller, og hvordan samfunnet kan forebygge og tilpasse seg.', array[10, 11]::int[], 9, 'utkast', '{}'::text[], false, now())
