insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('teknologi-og-forskningslare-1:kravspesifikasjon-og-arbeidstegninger', 's01', 'En prototype testes mot produktets krav. Forklar hvordan et konkret og målbart krav gjør det lettere å vurdere testresultatet.', 'Et konkret, målbart krav kan kontrolleres med en test. Da blir det tydelig om kravet er oppfylt eller ikke.', array['Forklarer at kravet kan kontrolleres eller måles i en test.', 'Knytter testresultatet til om kravet er oppfylt.']::text[], 0),
  ('teknologi-og-forskningslare-1:kravspesifikasjon-og-arbeidstegninger', 's02', 'Forklar forskjellen mellom et funksjonelt og et ikke-funksjonelt krav. Gi ett eksempel på hvert fra et produkt som har en vifte.', 'Et funksjonelt krav beskriver hva produktet skal gjøre, for eksempel at viften starter automatisk over en bestemt temperatur. Et ikke-funksjonelt krav beskriver en egenskap, for eksempel hvor mye produktet kan koste.', array['Skiller mellom hva produktet gjør og en egenskap ved produktet.', 'Gir et eksempel på hvert krav som passer til forklaringen.']::text[], 1),
  ('teknologi-og-forskningslare-1:kravspesifikasjon-og-arbeidstegninger', 's03', 'En gruppe lager en kravspesifikasjon med både må-krav og bør-krav. Forklar hvordan skillet kan hjelpe gruppen når den velger mellom to produktløsninger.', 'Må-krav må være oppfylt, så en løsning som ikke oppfyller dem, passer ikke. Bør-krav er ønskelige, og gruppen kan bruke dem til å sammenligne løsninger som oppfyller må-kravene.', array['Forklarer at må-krav er nødvendige å oppfylle.', 'Forklarer at bør-krav er ønskelige og kan brukes til å vurdere eller sammenligne løsninger.']::text[], 2),
  ('teknologi-og-forskningslare-1:kravspesifikasjon-og-arbeidstegninger', 's04', 'Du lager en arbeidstegning som en annen person skal bruke til å lage produktet. Forklar hvorfor både flere projeksjoner og mål er nyttige for den som skal lage det.', 'Projeksjonene viser produktet fra ulike retninger, slik at formen blir lettere å forstå. Målene viser størrelsene nøyaktig, slik at produktet kan lages i riktig størrelse.', array['Forklarer at projeksjonene viser produktet fra ulike retninger og gir informasjon om formen.', 'Forklarer at målene angir nøyaktige størrelser for produksjonen.']::text[], 3),
  ('teknologi-og-forskningslare-1:kravspesifikasjon-og-arbeidstegninger', 's05', 'På en arbeidstegning i målestokk 1 : 2 er en del 35 mm lang. Hvor lang er delen i virkeligheten? Vis det viktigste regnestykket.', 'Målestokk 1 : 2 betyr at tegningen er halvparten så stor som virkeligheten. 35 mm · 2 = 70 mm, så delen er 70 mm lang i virkeligheten.', array['Bruker at virkelig størrelse er dobbelt så stor som tegningen.', 'Regner riktig til 70 mm.']::text[], 4),
  ('teknologi-og-forskningslare-1:kravspesifikasjon-og-arbeidstegninger', 's06', 'Et produkt skal koste under 300 kr i materialer. To deler koster 120 kr og 95 kr. Alle beløp er hele kroner. Hvor mye kan en tredje del koste mest uten at kravet brytes? Vis regnestykket.', 'De to første delene koster 120 + 95 = 215 kr. Siden totalen må være under 300 kr, kan den tredje delen koste mest 84 kr: 215 + 84 = 299 kr.', array['Regner ut at de to delene til sammen koster 215 kr.', 'Tar hensyn til at kostnaden må være under 300 kr, og finner 84 kr som største mulige kostnad.']::text[], 5),
  ('teknologi-og-forskningslare-1:kravspesifikasjon-og-arbeidstegninger', 's07', 'Du vil undersøke om formen og størrelsen på et produkt passer før du lager teknikken i det. Hvilken type prototype passer best, og hva kan du bruke den til å undersøke?', 'En skissemodell i papp eller skum passer best. Den kan brukes til å undersøke produktets form og størrelse før teknikken lages.', array['Velger en skissemodell.', 'Knytter skissemodellen til testing av form og størrelse.']::text[], 6),
  ('teknologi-og-forskningslare-1:kravspesifikasjon-og-arbeidstegninger', 's08', 'Under et produktutviklingsprosjekt skriver gruppen ned valg, problemer, løsninger og testresultater i en logg. Forklar hvordan loggen kan være nyttig når produktet skal vurderes eller forbedres senere.', 'Loggen gjør det mulig å etterprøve hva gruppen har gjort og hvorfor. Den gir også informasjon som kan brukes når produktet skal forbedres senere.', array['Forklarer at loggen dokumenterer arbeidet slik at det kan etterprøves.', 'Forklarer at informasjonen kan brukes i senere forbedring.']::text[], 7);
