insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('teknologi-og-forskningslare-1:sensorer-og-signaler', 's01', 'En temperatursensor er koblet til en mikrokontroller. Forklar hva sensoren gjør med temperaturen, og hvordan mikrokontrolleren kan bruke signalet.', 'Sensoren gjør temperaturen om til et elektrisk signal. Mikrokontrolleren kan lese signalet og bruke det til å finne temperaturen.', array['Forklarer at sensoren gjør en fysisk størrelse om til et elektrisk signal.', 'Forklarer at mikrokontrolleren kan lese eller bruke signalet.']::text[], 0),
  ('teknologi-og-forskningslare-1:sensorer-og-signaler', 's02', 'Sammenlign en TMP36 med en digital temperatursensor når det gjelder signalet de sender.', 'En TMP36 gir en analog spenning som varierer med temperaturen. En digital temperatursensor sender et ferdig tall over en databuss.', array['Beskriver TMP36-signalet som analog spenning som varierer med temperaturen.', 'Beskriver at den digitale sensoren sender et ferdig tall over en databuss.']::text[], 1),
  ('teknologi-og-forskningslare-1:sensorer-og-signaler', 's03', 'En AD-omformer med flere bit brukes til å lese spenninger innenfor det samme måleområdet. Forklar hvorfor flere bit gir finere oppløsning.', 'Flere bit gjør at spenningene kan deles inn i flere ulike verdier. Da blir endringen mellom verdiene mindre, slik at mindre spenningsendringer kan registreres.', array['Knytter flere bit til flere mulige verdier innenfor samme måleområde.', 'Forklarer at mindre trinn gjør det mulig å registrere mindre endringer.']::text[], 2),
  ('teknologi-og-forskningslare-1:sensorer-og-signaler', 's04', 'En TMP36 følger formelen T = (U − 0,5) · 100. Hvilken temperatur svarer en spenning på 0,8 V til? Vis det viktigste regnetrinnet.', 'T = (0,8 − 0,5) · 100 = 30 °C. Temperaturen er altså 30 °C.', array['Setter 0,8 V inn i formelen og viser at 0,8 − 0,5 = 0,3.', 'Får fram svaret 30 °C.']::text[], 3),
  ('teknologi-og-forskningslare-1:sensorer-og-signaler', 's05', 'En 10-biters AD-omformer bruker formelen U = verdi · 5,0 / 1023. Omtrent hvilken spenning svarer verdien 204 til? Vis det viktigste regnetrinnet.', 'U = 204 · 5,0 / 1023, som er omtrent 1,0 V. Verdien 204 svarer altså til omtrent 1 V.', array['Bruker verdien 204 i formelen for å finne spenningen.', 'Oppgir omtrent 1,0 V.']::text[], 4),
  ('teknologi-og-forskningslare-1:sensorer-og-signaler', 's06', 'En LDR skal brukes til å registrere om et rom blir lysere. Den er koblet sammen med en fast motstand i en spenningsdeler. Forklar hvordan lysendringen kan bli et signal som en mikrokontroller kan lese.', 'Når rommet blir lysere, får LDR-en lavere resistans. I spenningsdeleren fører dette til at spenningen endrer seg, og mikrokontrolleren kan lese spenningsendringen.', array['Forklarer at LDR-ens resistans blir lavere når det blir lysere.', 'Knytter spenningsdeleren til en spenningsendring som mikrokontrolleren kan lese.']::text[], 5),
  ('teknologi-og-forskningslare-1:sensorer-og-signaler', 's07', 'Du skal registrere at en varm person beveger seg inn i et rom. Forklar hvorfor en PIR-sensor passer til oppgaven, og hva et akselerometer i stedet måler.', 'En PIR-sensor passer fordi den oppdager varme kropper som beveger seg. Et akselerometer måler akselerasjon i tre retninger og kan for eksempel registrere helning eller rystelser.', array['Forklarer at PIR-sensoren oppdager varme kropper i bevegelse.', 'Forklarer at akselerometeret måler akselerasjon i tre retninger.']::text[], 6),
  ('teknologi-og-forskningslare-1:sensorer-og-signaler', 's08', 'En temperatursensor viser usikre målinger. Beskriv hvordan du kan kalibrere den ved hjelp av en kjent temperatur, og hvorfor dette kan hjelpe.', 'Sammenlign sensorens måling med en kjent referanse, for eksempel isvann ved 0 °C, og juster sensoren. Da kan målingene bli mer nøyaktige.', array['Beskriver sammenligning med en kjent temperatur som referanse.', 'Beskriver at sensoren justeres ut fra sammenligningen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('teknologi-og-forskningslare-1:produkt-som-samler-data', 'teknologi-og-forskningslare-1', 'produkt-som-samler-data', 'Et produkt som samler inn data', 'Hvordan du designer og lager en datalogger med mikrokontroller og sensorer – valg av sensor, målefrekvens, tidsstempel og lagring – og hvordan du bearbeider og presenterer funnene fra dine egne data.', array[4]::int[], 3, 'utkast', '{}'::text[], false, now())
