  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 's01', 'Hva menes med måleusikkerhet, og hva bør man gjøre med den når man måler?', 'Måleusikkerhet er et anslag på hvor mye en måling kan avvike fra den sanne verdien. Den bør anslås og reduseres der det er mulig, ikke overses.', array['Forklarer at måleusikkerhet handler om mulig avvik fra den sanne verdien.', 'Får fram at usikkerheten bør anslås og eventuelt reduseres.']::text[], 0),
  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 's02', 'Sammenlign tilfeldige og systematiske feil. Hva skjer med hver type når man gjentar målingen mange ganger?', 'Tilfeldige feil varierer fra måling til måling og gjør målingene spredt, men kan jevne seg ut over mange målinger. Systematiske feil gir samme skjevhet hver gang og forsvinner ikke ved å måle flere ganger.', array['Beskriver at tilfeldige feil varierer og kan jevnes ut over mange målinger.', 'Beskriver at systematiske feil gir en vedvarende skjevhet som ikke forsvinner ved gjentakelse.']::text[], 1),
  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 's03', 'En elev måler en lengde fem ganger og får 8 cm, 7 cm, 9 cm, 6 cm og 8 cm. Hva er variasjonsbredden? Vis det viktigste regnestykket.', 'Variasjonsbredden er 3 cm. Den største verdien minus den minste er 9 cm − 6 cm = 3 cm.', array['Finner største og minste måling og trekker den minste fra den største.', 'Oppgir 3 cm.']::text[], 2),
  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 's04', 'Fem målinger er 6, 2, 5, 3 og 20. Hva er medianen? Vis det viktigste steget.', 'Sortert fra minst til størst blir målingene 2, 3, 5, 6 og 20. Medianen er den midterste verdien, altså 5.', array['Viser eller beskriver at målingene sorteres etter størrelse.', 'Oppgir den midterste verdien, 5.']::text[], 3),
  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 's05', 'Hva forteller standardavviket om en gruppe målinger, og hvilken regnearkfunksjon kan brukes til å regne det ut?', 'Standardavviket sier noe om hvor mye målingene typisk avviker fra gjennomsnittet. I et regneark kan funksjonen STDAV brukes til å regne det ut.', array['Forklarer at standardavvik beskriver det typiske avviket fra gjennomsnittet.', 'Oppgir STDAV som regnearkfunksjon.']::text[], 4),
  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 's06', 'Du har målinger av to variabler og vil vise hvordan de henger sammen, før du finner en linje eller kurve som passer best til punktene. Hvilken type graf og hvilken analyse kan du bruke?', 'Et punktdiagram viser sammenhengen mellom de to variablene. Regresjon kan brukes til å finne en linje eller kurve som passer best til punktene.', array['Velger punktdiagram for å vise sammenhengen mellom to variabler.', 'Forklarer at regresjon finner en linje eller kurve som passer best.']::text[], 5),
  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 's07', 'I et punktdiagram øker målt temperatur ofte når sensorens spenning øker. Hva kan du si om sammenhengen, og hva kan du ikke slå fast ut fra dette alene?', 'Målingene viser en korrelasjon mellom spenning og temperatur. De viser ikke alene at økt spenning er årsaken til økt temperatur.', array['Beskriver at mønsteret viser en korrelasjon eller sammenheng.', 'Får fram at korrelasjon alene ikke beviser årsakssammenheng.']::text[], 6),
  ('teknologi-og-forskningslare-1:dataanalyse-og-usikkerhet', 's08', 'Et sensorsignal varierer på grunn av støy. Forklar hvordan et glidende gjennomsnitt kan hjelpe med å vise signalet tydeligere.', 'Et glidende gjennomsnitt er et enkelt filter som jevner ut tilfeldige variasjoner i signalet. Det gjør støyen mindre framtredende.', array['Forklarer at glidende gjennomsnitt brukes som et filter.', 'Får fram at filteret jevner ut støy eller tilfeldige variasjoner.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
