insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('sosiologi-og-sosialantropologi:makt', 'q01', 'flervalg', 'Hvordan definerte Max Weber makt?', array['Evnen til å tjene penger', 'Sjansen til å få gjennomført sin vilje, også mot motstand', 'Retten til å stemme', 'Å være populær']::text[], 1, 'En klassisk definisjon.', true, true, 0),
  ('sosiologi-og-sosialantropologi:makt', 'q02', 'flervalg', 'Hvilken autoritet bygger på lover og regler?', array['Legal-rasjonell', 'Tradisjonell', 'Karismatisk', 'Ideologisk']::text[], 0, 'Typisk for moderne demokratier.', true, true, 1),
  ('sosiologi-og-sosialantropologi:makt', 'q03', 'flervalg', 'Hva er skjult makt ifølge Lukes?', array['Makt i en avstemning', 'Makt gjennom vold', 'Makten til å bestemme hva som kommer på dagsordenen', 'Makt over naturen']::text[], 2, 'Noen saker blir aldri diskutert.', true, true, 2),
  ('sosiologi-og-sosialantropologi:makt', 'q04', 'flervalg', 'Hva mente Foucault med disiplinmakt?', array['Straff med pisk', 'Makt bare hos kongen', 'Makt gjennom penger', 'Makt som virker gjennom overvåking og normalisering']::text[], 3, 'Vi retter oss etter normer fordi vi kan bli observert.', true, true, 3),
  ('sosiologi-og-sosialantropologi:makt', 'q05', 'flervalg', 'Hva er kulturell kapital hos Bourdieu?', array['Utdanning, kunnskap, språk og smak', 'Penger', 'Venner', 'Eiendom']::text[], 0, 'Kan gi fordeler i skole og arbeidsliv.', true, true, 4),
  ('sosiologi-og-sosialantropologi:makt', 'q06', 'flervalg', 'Hva er karismatisk autoritet?', array['Autoritet basert på lover', 'Autoritet basert på lederens personlige egenskaper', 'Autoritet basert på tradisjon', 'Autoritet basert på rikdom']::text[], 1, 'Evnen til å inspirere.', true, true, 5),
  ('sosiologi-og-sosialantropologi:makt', 'q07', 'flervalg', 'Hva er ideologisk makt?', array['Makt i en synlig konflikt', 'Makt over dagsordenen', 'Makten til å forme hva folk ønsker og tenker', 'Makt gjennom militæret']::text[], 2, 'Lukes'' tredje dimensjon.', true, true, 6),
  ('sosiologi-og-sosialantropologi:makt', 'q08', 'flervalg', 'Hvordan kan grupper med lite formell makt påvirke samfunnet?', array['De kan ikke påvirke', 'Bare ved å bli rike', 'Bare gjennom kongen', 'Gjennom demonstrasjoner, streik, boikott og sosiale medier']::text[], 3, 'Makt nedenfra.', true, true, 7),
  ('sosiologi-og-sosialantropologi:makt', 'q09', 'flervalg', 'Hva er mediemakt?', array['Makten til å sette dagsorden og vinkle saker', 'Makten til å vedta lover', 'Makten til å dømme', 'Makten til å kreve skatt']::text[], 0, 'Også plattformenes algoritmer.', true, false, 8),
  ('sosiologi-og-sosialantropologi:makt', 'q10', 'flervalg', 'Hvordan kan makt virke gjennom strukturer?', array['Bare gjennom bevisste beslutninger', 'Gjennom lover, økonomi og normer som gir noen fordeler uten at noen aktivt bestemmer det', 'Bare gjennom vold', 'Den kan ikke det']::text[], 1, 'Makt er ikke bare aktørers bevisste valg.', true, false, 9),
  ('sosiologi-og-sosialantropologi:makt', 'm01', 'sant-usant', 'Makt finnes også i familier og vennegjenger.', array['Sant', 'Usant']::text[], 0, 'Makt finnes i alle sosiale relasjoner.', false, true, 10),
  ('sosiologi-og-sosialantropologi:makt', 'm02', 'sant-usant', 'All makt er synlig og lett å oppdage.', array['Sant', 'Usant']::text[], 1, 'Skjult og ideologisk makt er vanskelig å se.', false, true, 11),
  ('sosiologi-og-sosialantropologi:makt', 'm03', 'sant-usant', 'Bourdieu mente at kapital kan bidra til å reprodusere ulikhet.', array['Sant', 'Usant']::text[], 0, 'De med mye kapital definerer hva som gir status.', false, true, 12),
  ('sosiologi-og-sosialantropologi:makt', 'm04', 'sant-usant', 'Foucault mente at makt bare utøves av staten.', array['Sant', 'Usant']::text[], 1, 'Han mente makt finnes i relasjoner overalt.', false, true, 13),
  ('sosiologi-og-sosialantropologi:makt', 'm05', 'flervalg', 'Hvilken kapitalform er et stort nettverk av kontakter?', array['Økonomisk kapital', 'Sosial kapital', 'Kulturell kapital', 'Symbolsk kapital']::text[], 1, 'Nettverk kan gi jobb og muligheter.', false, true, 14),
  ('sosiologi-og-sosialantropologi:makt', 'm06', 'flervalg', 'Hva er et eksempel på tradisjonell autoritet?', array['En konge som arver tronen', 'En valgt ordfører', 'En populær influenser', 'En dommer']::text[], 0, 'Bygger på skikk og vane.', false, true, 15),
  ('sosiologi-og-sosialantropologi:makt', 'm07', 'flervalg', 'Hvilket bilde brukte Foucault om disiplinmakt?', array['Pyramiden', 'Tårnet i Babel', 'Panoptikon', 'Labyrinten']::text[], 2, 'Fangene vet aldri om de blir sett.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('sosiologi-og-sosialantropologi:makt', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('sosiologi-og-sosialantropologi:makt', 's01', 'En konge arver rollen sin etter en skikk som har vært fulgt lenge. En annen leder får støtte fordi folk blir inspirert av personlighet og evner. Sammenlign hvilken type autoritet de to lederne har, og hva autoriteten bygger på.', 'Kongen har tradisjonell autoritet, som bygger på skikk og vane. Den andre lederen har karismatisk autoritet, som bygger på lederens personlige egenskaper og evne til å inspirere.', array['Knytter tradisjonell autoritet til skikk og vane.', 'Knytter karismatisk autoritet til lederens personlige egenskaper eller evne til å inspirere.']::text[], 0),
  ('sosiologi-og-sosialantropologi:makt', 's02', 'I et elevråd stemmer elevene over et forslag, og flertallet vinner. Før møtet har ledelsen bestemt at et annet forslag ikke skal tas opp til diskusjon. Forklar hvilken type makt som vises i avstemningen, og hvilken type makt som vises når et forslag holdes utenfor dagsordenen.', 'Avstemningen viser åpen makt, fordi det er en synlig konflikt der vi kan se hvem som vinner. Å holde et forslag utenfor dagsordenen viser skjult makt, fordi noen bestemmer hva som får bli diskutert.', array['Knytter den synlige avstemningen til åpen makt.', 'Knytter det å stenge et forslag ute fra diskusjonen til skjult makt og kontroll over dagsordenen.']::text[], 1),
  ('sosiologi-og-sosialantropologi:makt', 's03', 'Nora får hjelp til å finne en jobb fordi familien hennes kjenner mange i bransjen. Amir får jobb fordi han har penger til å kjøpe seg utstyr som kreves. Hvilke typer kapital viser de to eksemplene, og hva er forskjellen?', 'Noras nettverk viser sosial kapital, mens Amirs penger viser økonomisk kapital. Sosial kapital handler om nettverk og kontakter, mens økonomisk kapital handler om penger og eiendom.', array['Identifiserer Noras nettverk som sosial kapital.', 'Identifiserer Amirs penger som økonomisk kapital og forklarer forskjellen mellom typene.']::text[], 2),
  ('sosiologi-og-sosialantropologi:makt', 's04', 'En gruppe med mye status får gjennomslag for at deres smak og måte å oppføre seg på blir sett på som den riktige. Forklar hvordan dette kan bidra til å reprodusere ulikhet.', 'Gruppen kan bruke sin symbolske kapital, som anseelse og status, til å påvirke hva som regnes som god smak og riktig oppførsel. Når gruppens normer får høy verdi, kan fordelene deres bli videreført og ulikheten opprettholdes.', array['Forklarer at status eller anseelse kan gi innflytelse over hva som regnes som god smak eller riktig oppførsel.', 'Knytter dette til at fordeler videreføres og ulikhet opprettholdes.']::text[], 3),
  ('sosiologi-og-sosialantropologi:makt', 's05', 'Et stort selskap prøver å påvirke hvilke regler som blir vedtatt, mens en fagforening organiserer arbeidstakere for å fremme interessene deres. Hvilke former for makt er dette eksempler på, og hva skiller dem?', 'Selskapets forsøk på å påvirke regler handler om økonomisk makt, som blant annet kan ligge hos store selskaper og eiere. Fagforeningen bruker organisasjonsmakt ved å samle medlemmer i en interesseorganisasjon.', array['Knytter selskapet til økonomisk makt.', 'Knytter fagforeningen til organisasjonsmakt og forklarer at den handler om organisering av interesser.']::text[], 4),
  ('sosiologi-og-sosialantropologi:makt', 's06', 'En gruppe protesterer åpent og uten vold ved å bryte en lov for å påvirke en politisk beslutning. Forklar hvorfor dette kan kalles sivil ulydighet.', 'Det kan kalles sivil ulydighet fordi gruppen åpent og ikkevoldelig bryter en lov for å påvirke samfunnet eller en beslutning. Lovbruddet brukes som en protestform.', array['Får fram at lovbruddet skjer åpent og ikkevoldelig.', 'Forklarer at lovbruddet brukes for å påvirke.']::text[], 5),
  ('sosiologi-og-sosialantropologi:makt', 's07', 'I et fengsel vet fangene aldri om de blir observert. Forklar hvordan denne usikkerheten kan føre til at fangene selv tilpasser oppførselen sin, og knytt det til begrepet panoptikon.', 'Når fangene ikke vet om de blir sett, kan de rette seg etter reglene fordi de tror at de kan bli observert og vurdert. Panoptikon er bildet på et fengsel der fangene aldri vet om de blir sett.', array['Forklarer at usikkerheten om overvåking kan få fangene til å kontrollere eller tilpasse egen oppførsel.', 'Knytter situasjonen til panoptikon.']::text[], 6),
  ('sosiologi-og-sosialantropologi:makt', 's08', 'En plattformalgoritme gjør at noen temaer blir mye mer synlige enn andre i brukernes strømmer. Forklar hvordan dette kan påvirke hva folk snakker om, og hvilken form for makt dette er.', 'Når algoritmen gir noen temaer mer synlighet, kan den påvirke hvilke saker folk legger merke til og diskuterer. Dette er mediemakt fordi plattformer kan være med på å sette dagsorden.', array['Forklarer at ulik synlighet kan påvirke hvilke saker folk legger merke til eller diskuterer.', 'Knytter dette til mediemakt og dagsorden.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('sosiologi-og-sosialantropologi:medier-og-samhandling', 'sosiologi-og-sosialantropologi', 'medier-og-samhandling', 'Medier, kommunikasjon og samhandling', 'Hvordan ny teknologi har endret medier, kommunikasjon og samhandling – fra massemedier til sosiale medier, nettverkssamfunnet, selvpresentasjon, parasosiale relasjoner, algoritmer og ekkokamre.', array[8]::int[], 7, 'utkast', '{}'::text[], false, now())
