insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q01', 'flervalg', 'Hva er marginalisering?', array['At noen blir rike', 'En prosess der personer skyves ut i utkanten og får mindre tilgang til goder', 'At noen flytter', 'En type sykdom']::text[], 1, 'Tilgang til arbeid, utdanning og innflytelse.', true, true, 0),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q02', 'flervalg', 'Hva står NEET for?', array['Unge som verken er i arbeid, utdanning eller opplæring', 'En type utdanning', 'Et NAV-tiltak', 'En diagnose']::text[], 0, 'En utsatt gruppe.', true, true, 1),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q03', 'flervalg', 'Hva har forskning vist om søkere med utenlandskklingende navn?', array['De får flere intervjuer', 'Det er ingen forskjell', 'De blir i gjennomsnitt kalt inn til færre intervjuer', 'De søker ikke jobb']::text[], 2, 'Selv med like kvalifikasjoner.', true, true, 2),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q04', 'flervalg', 'Hva er en ond sirkel i sammenheng med utenforskap?', array['En sosial aktivitet', 'En type tiltak', 'Et vennskap', 'At årsaker forsterker hverandre']::text[], 3, 'For eksempel helse, frafall og lav inntekt.', true, true, 3),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q05', 'flervalg', 'Hva er Individuell jobbstøtte (IPS)?', array['Hjelp til ordinært arbeid med tett oppfølging for personer med psykiske lidelser', 'En type sosialhjelp', 'En skole', 'En skatteordning']::text[], 0, 'Arbeid som del av behandlingen.', true, true, 4),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q06', 'flervalg', 'Hvilken er en årsak til utenforskap på samfunnsnivå?', array['Personlige interesser', 'Høye krav til kompetanse i arbeidsmarkedet', 'Hobbyer', 'Høyde']::text[], 1, 'Færre jobber uten utdanning.', true, true, 5),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q07', 'flervalg', 'Hvorfor er frafall fra videregående en risiko?', array['Det gir høyere lønn', 'Det har ingen betydning', 'Det øker risikoen for å stå utenfor arbeidslivet', 'Det gir flere venner']::text[], 2, 'Utdanning er viktig for arbeid.', true, true, 6),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q08', 'flervalg', 'Hva er en konsekvens av utenforskap for samfunnet?', array['Mer arbeidskraft', 'Lavere velferdsutgifter', 'Høyere tillit', 'Tapt arbeidskraft og økte velferdsutgifter']::text[], 3, 'Og svekket samhold.', true, true, 7),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q09', 'flervalg', 'Hva er stigma?', array['Negative fordommer knyttet til en egenskap eller gruppe', 'En medisin', 'En type skatt', 'En utdanning']::text[], 0, 'For eksempel mot psykisk sykdom.', true, false, 8),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'q10', 'flervalg', 'Hva er et strukturelt tiltak mot diskriminering?', array['Å be den diskriminerte endre navn', 'Lovverk og anonyme søknader', 'Å ignorere problemet', 'Individuell trening']::text[], 1, 'Endrer rammene, ikke bare individet.', true, false, 9),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'm01', 'sant-usant', 'Man kan oppleve sosialt utenforskap selv om man har jobb.', array['Sant', 'Usant']::text[], 0, 'For eksempel ensomhet.', false, true, 10),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'm02', 'sant-usant', 'Utenforskap skyldes bare individuelle valg.', array['Sant', 'Usant']::text[], 1, 'Også samfunnsforhold spiller inn.', false, true, 11),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'm03', 'sant-usant', 'Frivillige organisasjoner kan bidra til inkludering.', array['Sant', 'Usant']::text[], 0, 'De gir fellesskap og nettverk.', false, true, 12),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'm04', 'sant-usant', 'Diskriminering i arbeidslivet er ikke dokumentert i Norge.', array['Sant', 'Usant']::text[], 1, 'Forskning har dokumentert det.', false, true, 13),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'm05', 'flervalg', 'Hvilket tiltak retter seg mot strukturene?', array['Samtale med én elev', 'Lover mot diskriminering', 'Personlig trening', 'Et motivasjonskurs']::text[], 1, 'Endrer samfunnets rammer.', false, true, 14),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'm06', 'flervalg', 'Hvilken etat har hovedansvar for arbeidsrettede tiltak i Norge?', array['NAV', 'Skatteetaten', 'Politiet', 'Datatilsynet']::text[], 0, 'Arbeids- og velferdsforvaltningen.', false, true, 15),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 'm07', 'flervalg', 'Hva bør du vurdere når du drøfter tiltak mot utenforskap?', array['Bare prisen', 'Bare hvem som foreslo tiltaket', 'Om tiltakene når dem som trenger dem og gir varig endring', 'Bare hvor raskt de virker']::text[], 2, 'Og om de retter seg mot individ eller struktur.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 's01', 'En person har jobb, men føler seg ensom og mangler nære sosiale nettverk. Forklar hvordan personen likevel kan oppleve utenforskap.', 'Personen kan oppleve sosialt utenforskap fordi hen mangler tilhørighet og kontakt med andre, selv om hen deltar i arbeidslivet. Utenforskap kan altså handle om sosiale fellesskap, ikke bare jobb eller skole.', array['Forklarer at ensomhet eller mangel på nettverk kan føre til sosialt utenforskap selv om personen har jobb.']::text[], 0),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 's02', 'En arbeidssøker har få kontakter som kan hjelpe med å finne jobb. Forklar hvordan et lite nettverk kan øke risikoen for å stå utenfor arbeidslivet.', 'Et lite nettverk kan gjøre det vanskeligere å få kontakter som åpner dører til arbeid. Dermed kan personen få svakere tilknytning til arbeidslivet.', array['Knytter nettverk til kontakter eller muligheter som kan hjelpe en person inn i arbeid.', 'Forklarer hvordan færre slike muligheter kan øke risikoen for utenforskap.']::text[], 1),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 's03', 'En person har psykiske plager, samtidig som arbeidsmarkedet stiller høye krav til kompetanse. Forklar forskjellen på disse to mulige årsakene til utenforskap.', 'Psykiske plager er en årsak på individnivå fordi de handler om personens helse. Høye kompetansekrav er en årsak på samfunnsnivå fordi de handler om kravene i arbeidsmarkedet.', array['Plasserer psykiske plager som en årsak på individnivå og forklarer at det handler om helse.', 'Plasserer høye kompetansekrav som en årsak på samfunnsnivå og knytter dem til arbeidsmarkedet.']::text[], 2),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 's04', 'En idrettsklubb tilbyr gratis trening, men noen deltakere får ikke være med på aktivitetene og blir ikke regnet som en del av gruppa. Forklar hva klubben må gjøre for at tilbudet skal være inkluderende.', 'Klubben må sørge for at alle kan delta på like vilkår, ikke bare tilby gratis trening. Deltakerne må også bli anerkjent som en del av fellesskapet.', array['Forklarer at inkludering krever reell mulighet til å delta på like vilkår.', 'Får fram at deltakerne også må anerkjennes som en del av fellesskapet.']::text[], 3),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 's05', 'En person står utenfor både skole og arbeidsliv. Beskriv to mulige konsekvenser dette kan få for personen selv.', 'Personen kan få dårligere økonomi og oppleve ensomhet. Utenforskap kan også svekke helsen, livskvaliteten eller følelsen av mestring.', array['Nevner minst to mulige konsekvenser for individet, som dårligere økonomi, helse, livskvalitet, ensomhet eller tap av mestring.']::text[], 4),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 's06', 'En elev står i fare for ikke å fullføre videregående. Foreslå et tiltak skolen kan sette inn tidlig, og forklar hvordan det kan forebygge frafall.', 'Skolen kan følge opp eleven tidlig og tilby et alternativt opplæringsløp. Slik hjelp kan gjøre det lettere for eleven å fortsette og fullføre videregående.', array['Foreslår tidlig oppfølging eller et alternativt løp i skolen.', 'Forklarer hvordan tiltaket kan bidra til at eleven fortsetter eller fullfører opplæringen.']::text[], 5),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 's07', 'En frivillig organisasjon tilbyr et rimelig kulturtilbud der mennesker kan møtes og delta sammen. Forklar hvordan dette kan bidra til inkludering.', 'Tilbudet kan gi mennesker en arena der de deltar i et fellesskap og møter andre. Rimelig deltakelse kan gjøre det lettere for flere å være med.', array['Knytter organisasjonen eller tilbudet til fellesskap og mulighet for å delta sammen med andre.', 'Forklarer hvordan lav eller rimelig pris kan gjøre deltakelse mulig for flere.']::text[], 6),
  ('sosiologi-og-sosialantropologi:marginalisering-og-inkludering', 's08', 'En familie har lav inntekt og strever med å skaffe eller beholde en egnet bolig. Nevn to økonomiske eller boligretta tiltak fra hjelpeordningene, og forklar kort hvordan de kan være relevante.', 'Familien kan for eksempel søke om bostøtte og sosialhjelp. Slike økonomiske tiltak kan avhjelpe familiens økonomiske vansker, mens startlån også kan være aktuelt i forbindelse med bolig.', array['Nevner to relevante tiltak fra sosialhjelp, bostøtte og startlån.', 'Knytter minst ett av tiltakene til familiens økonomiske vansker eller boligsituasjon.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('sosiologi-og-sosialantropologi:urfolk', 'sosiologi-og-sosialantropologi', 'urfolk', 'Urfolk – mangfold og rettigheter', 'Hva som kjennetegner urfolk, mangfoldet i urfolks kulturer og samfunnsliv i verden, samenes historie og rettigheter i Norge, og aktuelle spørsmål om land, språk, selvbestemmelse og forsoning.', array[10]::int[], 9, 'utkast', '{}'::text[], false, now())
