insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-og-filosofi-1:kilder-og-historisk-kunnskap', 's01', 'Fortiden kan ikke undersøkes direkte i dag. Forklar hvordan kilder gjør det mulig for historikere å lage kunnskap om fortiden, og hvorfor framstillingen deres er en tolkning.', 'Kilder er bevarte spor og fortellinger fra fortiden som historikere kan undersøke. Historikeren tolker og setter sammen opplysningene til en fortelling, så fortellingen er ikke selve fortiden.', array['Forklarer at kilder gir tilgang til spor eller fortellinger fra fortiden.', 'Forklarer at historikeren tolker kildene for å lage en historisk fortelling.']::text[], 0),
  ('historie-og-filosofi-1:kilder-og-historisk-kunnskap', 's02', 'En historiker undersøker et intervju med en person som selv opplevde hendelsen intervjuet handler om. Forklar hvorfor intervjuet er en førstehåndskilde, og hvordan det ville vært annerledes dersom personen bare hadde hørt om hendelsen fra andre.', 'Intervjuet er en førstehåndskilde fordi personen selv opplevde hendelsen. Hvis personen bare hadde hørt om den fra andre, ville kilden vært en annenhåndskilde.', array['Knytter førstehåndskilde til at personen selv opplevde hendelsen.', 'Skiller dette fra en annenhåndskilde som bygger på andres erfaringer eller opplysninger.']::text[], 1),
  ('historie-og-filosofi-1:kilder-og-historisk-kunnskap', 's03', 'En historiker bruker en gammel lov og et verktøy som er funnet av arkeologer. Sammenlign kildetypene, og forklar hva som gjør at de hører til hver sin type.', 'Loven er en skriftlig kilde fordi den består av tekst. Verktøyet er en materiell kilde fordi det er en gjenstand fra fortiden.', array['Identifiserer loven som en skriftlig kilde.', 'Identifiserer verktøyet som en materiell kilde og knytter det til at det er en gjenstand.']::text[], 2),
  ('historie-og-filosofi-1:kilder-og-historisk-kunnskap', 's04', 'En historiker undersøker pollen og årringer for å lære om klimaet i fortiden. Forklar hvorfor dette er naturvitenskapelige spor, og hva de kan bidra med kunnskap om.', 'Pollen og årringer er naturvitenskapelige spor som er bevart fra fortiden. De kan gi kunnskap om hvordan klimaet var.', array['Identifiserer pollen og årringer som naturvitenskapelige spor.', 'Forklarer at slike spor kan fortelle om klima i fortiden.']::text[], 3),
  ('historie-og-filosofi-1:kilder-og-historisk-kunnskap', 's05', 'En historiker finner en påstand i en gammel kilde. Beskriv to undersøkelser historikeren kan gjøre for å vurdere hvor troverdig påstanden er.', 'Historikeren kan undersøke hvem som laget kilden, og hvorfor, og vurdere om opphavspersonen hadde en tendens. Historikeren kan også sammenligne påstanden med andre kilder og undersøke om de er uavhengige.', array['Nevner en relevant undersøkelse av opphavsperson, hensikt, tendens, tid, sted eller nærhet til hendelsen.', 'Nevner sammenligning med andre kilder eller en annen relevant kildekritisk undersøkelse.']::text[], 4),
  ('historie-og-filosofi-1:kilder-og-historisk-kunnskap', 's06', 'Beskriv hvordan en historiker går fra et spørsmål om fortiden til en historisk fortelling. Ta med de viktigste stegene i arbeidet.', 'Historikeren formulerer en problemstilling, finner og vurderer kilder, og tolker og setter sammen opplysningene. Deretter lager historikeren en fortelling som forklarer problemstillingen.', array['Får med at historikeren formulerer en problemstilling og finner eller vurderer kilder.', 'Får med at opplysningene tolkes og settes sammen til en forklarende fortelling.']::text[], 5),
  ('historie-og-filosofi-1:kilder-og-historisk-kunnskap', 's07', 'En historiker undersøker en bygning fra fortiden. Forklar hvilken type kilde bygningen er, og hvorfor den kan brukes som kilde selv om den ikke inneholder skriftlig informasjon.', 'Bygningen er en materiell kilde fordi den er en fysisk gjenstand eller konstruksjon fra fortiden. Den kan gi spor om fortiden selv om den ikke inneholder skriftlig informasjon.', array['Identifiserer bygningen som en materiell kilde.', 'Forklarer at fysiske spor fra fortiden kan gi kunnskap uten å være skriftlige.']::text[], 6),
  ('historie-og-filosofi-1:kilder-og-historisk-kunnskap', 's08', 'En propagandaplakat fra andre verdenskrig brukes til å undersøke både hvordan krigen gikk, og hvordan myndighetene ønsket å påvirke folk. Forklar hvorfor plakaten er mer nyttig til det ene spørsmålet enn til det andre.', 'Plakaten er en dårlig beretning om hvordan krigen gikk, fordi den skulle påvirke folk. Den er en god levning fordi den viser hvordan myndighetene ønsket å påvirke befolkningen.', array['Forklarer at plakaten ikke er særlig pålitelig som beretning om hvordan krigen gikk.', 'Forklarer at plakaten er nyttig som levning fordi den viser myndighetenes ønskede påvirkning.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-og-filosofi-1:antikkens-demokrati-og-makt', 'historie-og-filosofi-1', 'antikkens-demokrati-og-makt', 'Makt, frihet og demokrati i antikken', 'Bystatene i Hellas, det athenske demokratiet og hvem som fikk delta, Platons og Aristoteles'' syn på styreformer, og den romerske republikken og keiserdømmet – med refleksjon over hva makt, frihet og demokrati betydde da og nå.', array[4]::int[], 2, 'utkast', '{}'::text[], false, now())
