insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-og-filosofi-1:metafysikk-og-erkjennelsesteori', 's01', 'Mina tror at en mynt landet på kron etter et myntkast, og hun gjetter riktig. Hvorfor er det ikke nok til at hun har kunnskap om at mynten landet på kron?', 'Selv om oppfatningen hennes er sann, har hun bare gjettet og mangler gode grunner for den. Derfor oppfyller ikke oppfatningen kravet om å være begrunnet.', array['Forklarer at en sann oppfatning ikke er nok når den bygger på en ren gjetning.', 'Får fram at kunnskap krever gode grunner eller begrunnelse.']::text[], 0),
  ('historie-og-filosofi-1:metafysikk-og-erkjennelsesteori', 's02', 'En materialist mener at bevisstheten skyldes prosesser i hjernen. Hva er likevel et vanskelig spørsmål for materialismen når vi tenker på opplevelser som smerte eller smaken av sjokolade?', 'Materialismen forklarer bevisstheten som et resultat av fysiske prosesser i hjernen. Et vanskelig spørsmål er hvordan slike prosesser kan gi opphav til den subjektive opplevelsen av smerte eller smak.', array['Knytter bevisstheten til fysiske prosesser i hjernen.', 'Forklarer spørsmålet om hvordan fysiske prosesser kan gi opphav til subjektive opplevelser.']::text[], 1),
  ('historie-og-filosofi-1:metafysikk-og-erkjennelsesteori', 's03', 'Ifølge determinismen er alt som skjer, bestemt av tidligere årsaker. Forklar hvorfor dette kan gjøre det vanskelig å si at mennesker velger fritt.', 'Hvis handlingene våre er bestemt av tidligere årsaker, kan det virke som om vi ikke kunne valgt annerledes. Da blir det vanskelig å forklare hvordan valgene våre kan være frie.', array['Knytter handlinger eller valg til tidligere årsaker.', 'Forklarer at det kan svekke ideen om at vi kunne valgt annerledes eller valgt fritt.']::text[], 2),
  ('historie-og-filosofi-1:metafysikk-og-erkjennelsesteori', 's04', 'En person hjelper en venn fordi hun selv ønsker det, og ingen tvinger henne. Selv om handlingen er bestemt av tidligere årsaker, hvordan kan en kompatibilist forklare at hun likevel handler fritt?', 'En kompatibilist kan si at handlingen er fri fordi hun handler ut fra egne ønsker og ikke blir utsatt for ytre tvang. Fri vilje kan dermed forenes med at handlinger har årsaker.', array['Viser til at hun handler ut fra egne ønsker.', 'Viser til fravær av ytre tvang og knytter dette til at fri vilje kan forenes med determinisme.']::text[], 3),
  ('historie-og-filosofi-1:metafysikk-og-erkjennelsesteori', 's05', 'Sammenlign rasjonalismen og empirismen: Hva regner hver retning som den viktigste kilden til kunnskap?', 'Rasjonalismen regner fornuften som den sikreste kilden til kunnskap. Empirismen legger vekt på erfaring og sansene som kilden til kunnskap.', array['Plasserer fornuften som den viktigste eller sikreste kunnskapskilden for rasjonalismen.', 'Plasserer erfaring eller sansene som kunnskapskilden for empirismen.']::text[], 4),
  ('historie-og-filosofi-1:metafysikk-og-erkjennelsesteori', 's06', 'Du ser en kopp falle ned fra et bord og knuse. Hvordan kan Kant forklare at kunnskap om en slik hendelse krever både sanseerfaring og måter sinnet ordner erfaringen på?', 'Sansene gir oss erfaringen av koppen som faller og knuses. Fornuftens former, som tid og årsak, hjelper sinnet med å ordne erfaringen slik at vi kan forstå hendelsen som en sammenheng.', array['Forklarer at kunnskap krever sanseerfaring.', 'Forklarer at sinnet ordner erfaringen ved hjelp av former som tid eller årsak.']::text[], 5),
  ('historie-og-filosofi-1:metafysikk-og-erkjennelsesteori', 's07', 'Descartes tvilte metodisk på alt som kunne være usikkert. Hva var hensikten med denne tvilen, og hvordan ville han gå videre når han hadde funnet noe sikkert?', 'Hensikten var å finne et utgangspunkt han kunne vite helt sikkert. Derfra ville han bruke fornuften til å bygge opp mer kunnskap, slik man gjør i matematikken.', array['Forklarer at tvilen skulle hjelpe ham med å finne noe helt sikkert.', 'Får fram at han ville bygge videre på dette med fornuften.']::text[], 6),
  ('historie-og-filosofi-1:metafysikk-og-erkjennelsesteori', 's08', 'Ifølge Hume ser vi ikke selve årsakssammenhengen, men bare at én ting følger etter en annen. Når en ball treffer en annen og den andre begynner å rulle, hva kan vi observere direkte, og hva kan vi ikke observere direkte?', 'Vi kan observere at den første ballen treffer den andre, og at den andre begynner å rulle etterpå. Selve årsakssammenhengen mellom hendelsene kan vi ikke observere direkte.', array['Skiller mellom hendelsene vi kan observere, som at den ene følger etter den andre.', 'Får fram at selve årsakssammenhengen ikke kan observeres direkte.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-og-filosofi-1:etikk', 'historie-og-filosofi-1', 'etikk', 'Etiske teorier', 'De store etiske teoriene – dydsetikk, pliktetikk, konsekvensetikk og kontraktsetikk – med Aristoteles, Kant, Bentham og Mill, og hvordan du bruker dem til å drøfte etiske dilemmaer.', array[5]::int[], 7, 'utkast', '{}'::text[], false, now())
