  ('historie-og-filosofi-1:etikk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-og-filosofi-1:etikk', 's01', 'Hva betyr eudaimonia i Aristoteles’ dydsetikk, og hvordan henger det sammen med dydene?', 'Eudaimonia er et godt og blomstrende liv. Ifølge Aristoteles oppnår vi det ved å utvikle gode karaktertrekk, altså dyder.', array['Forklarer eudaimonia som et godt og blomstrende liv.', 'Knytter dette livet til utvikling av dyder.']::text[], 0),
  ('historie-og-filosofi-1:etikk', 's02', 'Gavmildhet ligger ifølge dydsetikken mellom gjerrighet og ødselhet. Forklar hvordan dette viser ideen om den gylne middelvei.', 'Den gylne middelvei betyr at en dyd ofte ligger mellom to ytterpunkter. Gavmildhet er verken å holde for mye tilbake eller å gi bort på en ødsel måte.', array['Forklarer at dyden ligger mellom to ytterpunkter.', 'Viser hvordan gavmildhet skiller seg fra både gjerrighet og ødselhet.']::text[], 1),
  ('historie-og-filosofi-1:etikk', 's03', 'En person vil hjelpe en venn, men er usikker på hva som er riktig å gjøre i situasjonen. Forklar hvilken rolle praktisk klokskap kan ha.', 'Praktisk klokskap hjelper personen med å vurdere hva som er riktig i akkurat denne situasjonen. Den handler om å bruke dømmekraft, ikke bare å kjenne til dyder generelt.', array['Forklarer at praktisk klokskap handler om å se hva som er riktig i en konkret situasjon.', 'Knytter klokskapen til vurdering eller dømmekraft i situasjonen.']::text[], 2),
  ('historie-og-filosofi-1:etikk', 's04', 'Sammenlign hva pliktetikken og konsekvensetikken legger vekt på når de vurderer om en handling er riktig.', 'Pliktetikken vurderer om handlingen er riktig eller gal i seg selv, uavhengig av konsekvensene. Konsekvensetikken vurderer om handlingen gir de beste konsekvensene.', array['Forklarer at pliktetikken legger vekt på plikter eller handlingens riktighet i seg selv.', 'Forklarer at konsekvensetikken legger vekt på resultatene av handlingen.']::text[], 3),
  ('historie-og-filosofi-1:etikk', 's05', 'John Rawls foreslo at vi skulle velge regler bak et «uvitenhetens slør». Forklar hva man ikke vet da, og hvordan dette kan bidra til rettferdige regler.', 'Bak uvitenhetens slør vet man ikke hvem man selv blir. Da må man velge regler uten å vite hvilken posisjon man selv får, noe som kan bidra til at reglene blir rettferdige.', array['Får fram at man ikke vet hvem man selv blir eller hvilken posisjon man får.', 'Forklarer at dette kan gjøre regelvalget mer rettferdig fordi man ikke kan tilpasse reglene til egen posisjon.']::text[], 4),
  ('historie-og-filosofi-1:etikk', 's06', 'Hvorfor mente Jeremy Bentham at dyrs lidelse også teller når vi vurderer handlingers konsekvenser?', 'Bentham mente at utilitarismen skal fremme størst mulig lykke og ta hensyn til glede og smerte. Derfor teller også lidelsen dyr opplever.', array['Knytter vurderingen til glede, smerte eller lykke.', 'Forklarer at dyrs lidelse må tas med i vurderingen.']::text[], 5),
  ('historie-og-filosofi-1:etikk', 's07', 'Hvorfor kan det være vanskelig å avgjøre på forhånd hvilken handling som gir de beste konsekvensene?', 'Det kan være vanskelig fordi konsekvensene av en handling er vanskelige å forutsi. Derfor kan vi være usikre på hvilken handling som faktisk gir det beste resultatet.', array['Får fram at konsekvenser kan være vanskelige å forutsi.', 'Knytter usikkerheten til vansker med å vite hvilken handling som gir best resultat.']::text[], 6),
  ('historie-og-filosofi-1:etikk', 's08', 'Når et etisk dilemma blir drøftet, hva bør en god drøfting inneholde for å ende i en begrunnet konklusjon?', 'En god drøfting presenterer dilemmaet, bruker flere etiske teorier og vurderer styrker og svakheter ved dem. Deretter kommer den fram til en begrunnet konklusjon.', array['Får fram at dilemmaet og flere etiske teorier bør presenteres.', 'Viser at teoriene bør vurderes, for eksempel ved å ta opp styrker og svakheter.', 'Knytter vurderingen til en begrunnet konklusjon.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-og-filosofi-1:religion-filosofi-og-makt', 'historie-og-filosofi-1', 'religion-filosofi-og-makt', 'Religion, filosofi og makt', 'Hvordan religion og filosofi gjennom historien både har legitimert og utfordret makt og samfunnsstrukturer – fra gudekonger og kirkens makt til reformasjonen, opplysningstiden og moderne frigjøringsbevegelser – og hvordan de har formet synet på sannhet og virkelighet.', array[6]::int[], 8, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('historie-og-filosofi-1:religion-filosofi-og-makt', '## Religion som legitimering av makt
