insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('politikk-og-menneskerettigheter:det-norske-politiske-systemet', 's01', 'Forklar hvordan den lovgivende, utøvende og dømmende makten er fordelt mellom Stortinget, regjeringen og domstolene.', 'Stortinget har den lovgivende makten, regjeringen den utøvende makten og domstolene den dømmende makten.', array['Plasserer lovgivende makt hos Stortinget og utøvende makt hos regjeringen.', 'Plasserer dømmende makt hos domstolene.']::text[], 0),
  ('politikk-og-menneskerettigheter:det-norske-politiske-systemet', 's02', 'Et lovforslag fra regjeringen skal behandles på Stortinget. Forklar hva komiteene gjør med saken, og hvor den blir avgjort.', 'Komiteene behandler saken før den går videre til plenum. Stortinget avgjør saken i plenum.', array['Får fram at komiteene behandler saken før den avgjøres.', 'Får fram at saken avgjøres i plenum.']::text[], 1),
  ('politikk-og-menneskerettigheter:det-norske-politiske-systemet', 's03', 'Sammenlign regjeringens og Stortingets roller i arbeidet med statsbudsjettet.', 'Regjeringen fremmer forslag til statsbudsjett. Stortinget vedtar budsjettet og bestemmer dermed statens inntekter og utgifter.', array['Får fram at regjeringen fremmer budsjettforslaget.', 'Får fram at Stortinget vedtar budsjettet, som gjelder statens inntekter og utgifter.']::text[], 2),
  ('politikk-og-menneskerettigheter:det-norske-politiske-systemet', 's04', 'En person vil undersøke om statens penger er brukt riktig. Hvilket organ har ansvar for å kontrollere dette, og hva går kontrollen ut på?', 'Riksrevisjonen kontrollerer om statens penger brukes riktig.', array['Identifiserer Riksrevisjonen.', 'Forklarer at organet kontrollerer bruken av statens penger.']::text[], 3),
  ('politikk-og-menneskerettigheter:det-norske-politiske-systemet', 's05', 'Forklar forskjellen mellom kongens rolle som statsoverhode i praksis og kongens formelle rolle når regjeringen fatter vedtak.', 'Kongen har i praksis en symbolsk rolle. Formelt fattes regjeringens vedtak i statsråd med kongen.', array['Får fram at kongens rolle i praksis er symbolsk.', 'Får fram at regjeringens vedtak formelt fattes i statsråd med kongen.']::text[], 4),
  ('politikk-og-menneskerettigheter:det-norske-politiske-systemet', 's06', 'En kommune planlegger en barnehage, mens fylkeskommunen arbeider med kollektivtransport. Hvilket nivå har ansvar for hver av oppgavene?', 'Kommunen har ansvar for barnehager. Fylkeskommunen har ansvar for kollektivtransport.', array['Plasserer barnehagen hos kommunen.', 'Plasserer kollektivtransport hos fylkeskommunen.']::text[], 5),
  ('politikk-og-menneskerettigheter:det-norske-politiske-systemet', 's07', 'Sammenlign hvor ofte kommune- og fylkestingsvalg holdes med hvor ofte stortingsvalg holdes. Hvordan er valgene forskjøvet i tid?', 'Begge valgene holdes hvert fjerde år. Kommune- og fylkestingsvalgene ligger to år forskjøvet fra stortingsvalget.', array['Får fram at begge valgtypene holdes hvert fjerde år.', 'Får fram at kommune- og fylkestingsvalgene er forskjøvet med to år fra stortingsvalget.']::text[], 6),
  ('politikk-og-menneskerettigheter:det-norske-politiske-systemet', 's08', 'En kommune får både rammetilskudd og øremerkede midler fra staten. Forklar hvordan kommunen kan bruke disse pengene på ulike måter.', 'Kommunen fordeler selv rammetilskuddet. Øremerkede midler er knyttet til bestemte formål.', array['Får fram at kommunen selv fordeler rammetilskuddet.', 'Får fram at øremerkede midler er satt av til bestemte formål.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('politikk-og-menneskerettigheter:makt-konfliktlinjer-og-kanaler', 'politikk-og-menneskerettigheter', 'makt-konfliktlinjer-og-kanaler', 'Makt, konfliktlinjer og kanaler for innflytelse', 'Hvem som har makt i Norge, konfliktdimensjonene som former partiene, og de ulike kanalene for politisk innflytelse – parlamentarisk, korporativ, aksjon, media og rettslig – med eksempler fra praktisk politikk.', array[5]::int[], 3, 'utkast', '{}'::text[], false, now())
