insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q01', 'flervalg', 'Hvor stor er sperregrensen for utjevningsmandater?', array['2 %', '4 %', '5 %', '10 %']::text[], 1, 'Partier under 4 % kan likevel vinne distriktsmandater.', true, true, 0),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q02', 'flervalg', 'Hva er formålet med utjevningsmandater?', array['Å gjøre resultatet mer rettferdig nasjonalt', 'Å gi flere mandater til store partier', 'Å gi kongen mandater', 'Å redusere antall partier']::text[], 0, 'Ett per valgdistrikt.', true, true, 1),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q03', 'flervalg', 'Hva er saksstemming?', array['Å stemme som foreldrene', 'Å stemme etter klasse', 'Å stemme ut fra politikken i viktige saker', 'Å stemme tilfeldig']::text[], 2, 'For eksempel klima eller skatt.', true, true, 2),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q04', 'flervalg', 'Hva er retrospektiv stemmegivning?', array['Å stemme på det nyeste partiet', 'Å stemme etter framtidige løfter', 'Å stemme blankt', 'Å belønne eller straffe regjeringen for hvordan det har gått']::text[], 3, 'Ser bakover.', true, true, 3),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q05', 'flervalg', 'Hvor stor er feilmarginen omtrent i en meningsmåling med 1000 personer?', array['±3 prosentpoeng', '±0,1 prosentpoeng', '±15 prosentpoeng', 'Ingen feilmargin']::text[], 0, 'Små endringer kan være tilfeldige.', true, true, 4),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q06', 'flervalg', 'Hva har skjedd med klassestemmegivningen de siste tiårene?', array['Den har blitt sterkere', 'Den har blitt svakere', 'Den er uendret', 'Den er forbudt']::text[], 1, 'Flere bytter parti.', true, true, 5),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q07', 'flervalg', 'Hvilke grupper har ofte lavere valgdeltakelse?', array['Eldre med høy utdanning', 'Pensjonister', 'Unge og personer med lav utdanning og inntekt', 'Politikere']::text[], 2, 'Gir skjev representasjon.', true, true, 6),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q08', 'flervalg', 'Hvorfor er lav valgdeltakelse et problem?', array['Det gjør valg dyrere', 'Det gir flere partier', 'Det gjør valget kortere', 'Det kan svekke legitimiteten og gi skjev representasjon']::text[], 3, 'Politikere lytter mest til velgerne.', true, true, 7),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q09', 'flervalg', 'Hva er partiidentifikasjon?', array['Varig tilhørighet til et parti', 'Et medlemskort', 'Et valgprogram', 'En meningsmåling']::text[], 0, 'Ofte formet gjennom familien.', true, false, 8),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'q10', 'flervalg', 'Hvorfor får distrikter med spredt bosetting flere mandater per innbygger?', array['Fordi de har flere partier', 'Fordi også areal teller i fordelingen', 'Fordi byene ikke stemmer', 'Fordi kongen bestemmer det']::text[], 1, 'Et distriktshensyn i valgordningen.', true, false, 9),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'm01', 'sant-usant', 'Mange velgere bestemmer seg sent i valgkampen.', array['Sant', 'Usant']::text[], 0, 'Valgkampen har derfor stor betydning.', false, true, 10),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'm02', 'sant-usant', 'En endring på ett prosentpoeng fra én meningsmåling til neste er alltid en reell endring.', array['Sant', 'Usant']::text[], 1, 'Den kan skyldes tilfeldig variasjon.', false, true, 11),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'm03', 'sant-usant', 'Partimedlemskap har gått ned over tid.', array['Sant', 'Usant']::text[], 0, 'Mange engasjerer seg heller i saker.', false, true, 12),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'm04', 'sant-usant', 'Et parti under sperregrensen kan aldri komme inn på Stortinget.', array['Sant', 'Usant']::text[], 1, 'Det kan vinne distriktsmandater.', false, true, 13),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'm05', 'flervalg', 'Hvor mange distriktsmandater er det ved stortingsvalg?', array['19', '150', '169', '100']::text[], 1, 'I tillegg kommer 19 utjevningsmandater.', false, true, 14),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'm06', 'flervalg', 'Hvilken metode gir innsikt i hvorfor noen lar være å stemme?', array['Kvalitative intervjuer', 'Valgresultatet alene', 'Mandatfordelingen', 'Sperregrensen']::text[], 0, 'Gir dybdekunnskap.', false, true, 15),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 'm07', 'flervalg', 'Hvilket tiltak er diskutert for å øke valgdeltakelsen blant unge?', array['Høyere stemmerettsalder', 'Færre valglokaler', 'Stemmerett for 16-åringer', 'Avskaffe skolevalg']::text[], 2, 'Prøvd ut i enkelte kommuner.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 's01', 'Norge bruker forholdstallsvalg ved stortingsvalg. Forklar hva det betyr for hvordan partiene får mandater.', 'Ved forholdstallsvalg får partiene mandater omtrent i forhold til hvor mange stemmer de får. Partier med større andel av stemmene får vanligvis en større andel av mandatene.', array['Forklarer at mandatene fordeles omtrent i forhold til stemmetallet.', 'Viser sammenhengen mellom andel stemmer og andel mandater.']::text[], 0),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 's02', 'Ved stortingsvalg fordeles 150 distriktsmandater i valgdistriktene, mens 19 utjevningsmandater fordeles – ett per valgdistrikt. Sammenlign hva disse to mandattypene er til for.', 'Distriktsmandatene fordeles i valgdistriktene. Utjevningsmandatene skal gjøre valgresultatet mer rettferdig på nasjonalt nivå.', array['Beskriver distriktsmandatene som mandater fordelt i valgdistriktene.', 'Forklarer at utjevningsmandatene skal jevne ut resultatet nasjonalt.']::text[], 1),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 's03', 'Før stemte arbeidere oftest på Arbeiderpartiet. Forklar hvordan dette kan brukes som eksempel på en sosiologisk forklaring på velgeratferd.', 'En sosiologisk forklaring knytter stemmegivning til sosial bakgrunn, for eksempel yrke eller klasse. At arbeidere oftest stemte på Arbeiderpartiet, viser en sammenheng mellom yrkes- eller klassebakgrunn og partivalg.', array['Knytter sosiologiske forklaringer til sosial bakgrunn, som yrke eller klasse.', 'Bruker eksempelet med arbeidere og Arbeiderpartiet til å vise en slik sammenheng.']::text[], 2),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 's04', 'En forsker vil undersøke både hva folk stemte, og hvorfor de stemte slik, etter et valg. Forklar hvordan en valgundersøkelse kan brukes til dette.', 'Forskeren spør et representativt utvalg om hva de stemte og hvorfor. Svarene kan brukes til å undersøke velgernes stemmegivning og begrunnelser.', array['Beskriver valgundersøkelsen som en spørreundersøkelse etter valget.', 'Får fram at et representativt utvalg blir spurt både om hva de stemte og hvorfor.']::text[], 3),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 's05', 'En meningsmåling med omtrent 1000 personer viser en liten endring for et stort parti sammenlignet med en tidligere måling. Feilmarginen er omtrent ±3 prosentpoeng. Forklar hvorfor endringen ikke nødvendigvis betyr at partiets oppslutning faktisk har endret seg.', 'Endringen kan skyldes tilfeldig variasjon i utvalget. Når feilmarginen er omtrent ±3 prosentpoeng, kan en liten forskjell mellom målingene ligge innenfor feilmarginen.', array['Forklarer at små endringer kan skyldes tilfeldig variasjon.', 'Knytter dette til feilmarginen på omtrent ±3 prosentpoeng.']::text[], 4),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 's06', 'En velger stemmer på ett parti ved et valg og på et annet parti ved neste valg. Hva kalles dette, og hva viser det om velgerens stemmegivning over tid?', 'Dette kalles velgervandring. Det viser at velgeren har byttet parti fra ett valg til det neste.', array['Identifiserer dette som velgervandring.', 'Forklarer at velgeren bytter parti fra valg til valg.']::text[], 5),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 's07', 'En ungdom skriver politiske ytringer i sosiale medier og deltar i en underskriftskampanje, men er ikke medlem av et parti. Beskriv hvilke former for politisk deltakelse dette er, og hvordan de skiller seg fra partimedlemskap.', 'Politiske ytringer i sosiale medier og underskriftskampanjer er former for politisk deltakelse. De gjør det mulig å engasjere seg politisk uten å være medlem av et parti.', array['Identifiserer både politiske ytringer i sosiale medier og underskriftskampanjer som deltakelsesformer.', 'Forklarer at politisk deltakelse også kan skje uten partimedlemskap.']::text[], 6),
  ('politikk-og-menneskerettigheter:valg-og-velgeratferd', 's08', 'En forsker vil finne ut hvorfor noen personer ikke stemmer ved valg. Hvilken metode kan gi innsikt i dette, og hva kan metoden bidra med?', 'Kvalitative intervjuer kan gi innsikt i hvorfor folk ikke stemmer. Intervjuene kan få fram personenes egne grunner og erfaringer.', array['Foreslår kvalitative intervjuer.', 'Forklarer at metoden kan gi innsikt i hvorfor folk ikke stemmer.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('politikk-og-menneskerettigheter:barekraft-og-fordeling', 'politikk-og-menneskerettigheter', 'barekraft-og-fordeling', 'Bærekraft og fordeling i politikken', 'Dagsaktuelle problemstillinger om bærekraft og fordeling – klimapolitikk, olje og energi, ulikhet i Norge og globalt, fordeling mellom generasjoner og hvordan partiene ser på avveiningene.', array[7]::int[], 5, 'utkast', '{}'::text[], false, now())
