insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('politikk-og-menneskerettigheter:urfolk-og-minoriteter', 's01', 'Hva skiller urfolk fra nasjonale minoriteter? Bruk samene og én nasjonal minoritet i Norge som eksempler.', 'Urfolk nedstammer fra folk som bodde i et område før dagens statsgrenser ble trukket, og har bevart egen kultur og egne institusjoner. Samene er urfolk i Norge, mens for eksempel jøder er en nasjonal minoritet med lang tilknytning til landet.', array['Forklarer at urfolk har tilknytning til området fra før dagens statsgrenser og har bevart egen kultur og egne institusjoner.', 'Bruker samene som eksempel på urfolk og en nasjonal minoritet som eksempel på en gruppe med lang tilknytning til landet.']::text[], 0),
  ('politikk-og-menneskerettigheter:urfolk-og-minoriteter', 's02', 'Sammenlign ILO-konvensjon 169 med FNs urfolkserklæring når det gjelder hvilke rettigheter de slår fast for urfolk.', 'ILO-konvensjon 169 gir urfolk rett til konsultasjon og deltakelse i saker som berører dem, og rett til land og ressurser. FNs urfolkserklæring fra 2007 slår fast retten til selvbestemmelse.', array['Knytter ILO-konvensjon 169 til konsultasjon og deltakelse og/eller rett til land og ressurser.', 'Knytter FNs urfolkserklæring til retten til selvbestemmelse.']::text[], 1),
  ('politikk-og-menneskerettigheter:urfolk-og-minoriteter', 's03', 'Sametinget er samenes folkevalgte organ og gir råd til staten, men har begrenset beslutningsmyndighet. Forklar hva dette forteller om Sametingets politiske innflytelse.', 'Sametinget gir samene en folkevalgt kanal for å påvirke saker, blant annet om språk og kultur. Sametinget har likevel ikke myndighet til å bestemme i alle saker, så den politiske innflytelsen er begrenset.', array['Forklarer at Sametinget gir samene representasjon og mulighet til å påvirke saker.', 'Får fram at Sametingets begrensede beslutningsmyndighet gjør at innflytelsen ikke innebærer full beslutningsmakt.']::text[], 2),
  ('politikk-og-menneskerettigheter:urfolk-og-minoriteter', 's04', 'En kommune planlegger et tiltak som kan påvirke samiske interesser direkte. Hva må kommunen gjøre før den tar en beslutning, og hva er hensikten med det?', 'Kommunen må konsultere samiske interesser før den tar beslutningen. Hensikten er at de berørte samiske interessene skal bli hørt i en sak som kan påvirke dem direkte.', array['Sier at kommunen må konsultere samiske interesser før beslutningen tas.', 'Forklarer at konsultasjonen skal gjøre det mulig for berørte samiske interesser å bli hørt.']::text[], 3),
  ('politikk-og-menneskerettigheter:urfolk-og-minoriteter', 's05', 'I Fosen-saken tok det lang tid før staten og reindriftssamene kom fram til løsninger etter Høyesteretts avgjørelse. Forklar sammenhengen mellom dette og protestene i 2023, og nevn hva avtalene innebar.', 'Den lange tiden det tok å komme fram til løsninger førte til store protester i 2023. Avtalene innebar at vindturbinene blir stående, mens reindrifta får kompensasjon og nye vinterbeiter.', array['Knytter den lange tiden før løsninger til de store protestene i 2023.', 'Nevner at turbinene blir stående, og at reindrifta får kompensasjon og nye vinterbeiter.']::text[], 4),
  ('politikk-og-menneskerettigheter:urfolk-og-minoriteter', 's06', 'Finnmarkseiendommen og Sametinget er begge knyttet til samiske forhold, men har ulike roller. Forklar forskjellen mellom dem.', 'Finnmarkseiendommen eier grunnen i Finnmark etter finnmarksloven fra 2005 og styres av Sametinget og Finnmark fylkeskommune. Sametinget er samenes folkevalgte organ, som blant annet har ansvar for samisk språk og kultur og gir råd til staten.', array['Forklarer at Finnmarkseiendommen eier grunnen i Finnmark og styres av Sametinget sammen med Finnmark fylkeskommune.', 'Skiller dette fra Sametingets rolle som samenes folkevalgte organ med ansvar for blant annet språk og kultur.']::text[], 5),
  ('politikk-og-menneskerettigheter:urfolk-og-minoriteter', 's07', 'Flere samiske språk og kvensk er truet. Forklar hva språkrevitalisering betyr, og hvorfor det er relevant for disse språkene.', 'Språkrevitalisering er arbeid for å styrke et språk. Det er relevant fordi flere samiske språk og kvensk er truet og derfor trenger tiltak for å styrkes.', array['Forklarer at språkrevitalisering handler om å styrke et språk.', 'Knytter behovet for revitalisering til at flere samiske språk og kvensk er truet.']::text[], 6),
  ('politikk-og-menneskerettigheter:urfolk-og-minoriteter', 's08', 'Forklar ett argument for og ett argument mot særrettigheter for urfolk og minoriteter. Vis også hvilken demokratisk utfordring debatten handler om.', 'Et argument for særrettigheter er at de kan rette opp historisk urett og bidra til at små kulturer overlever. Et argument mot er at særrettigheter kan skape nye skiller. Debatten handler om hvordan flertallsstyre kan sikre at mindretall blir hørt og ikke overkjørt.', array['Gir et relevant argument for særrettigheter, som å rette opp historisk urett eller sikre små kulturers overlevelse.', 'Gir et relevant argument mot, som at særrettigheter kan skape nye skiller eller bryte med ønsket om like rettigheter.', 'Knytter debatten til hvordan mindretall skal bli hørt og beskyttet i et demokrati med flertallsstyre.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('politikk-og-menneskerettigheter:menneskerettigheter-demokrati-og-velferd', 'politikk-og-menneskerettigheter', 'menneskerettigheter-demokrati-og-velferd', 'Menneskerettigheter, demokrati og velferdsstat', 'Hva menneskerettigheter er og hvordan de utviklet seg, sivile og politiske mot økonomiske, sosiale og kulturelle rettigheter, hvordan de er gjennomført i norsk rett – og hvilken betydning de har for demokratiet og velferdsstaten.', array[9]::int[], 7, 'utkast', '{}'::text[], false, now())
