insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q01', 'flervalg', 'Hva er UPR?', array['En domstol', 'En gjennomgang der alle FN-land vurderes jevnlig av de andre', 'En hjelpeorganisasjon', 'En traktat']::text[], 1, 'Universell periodisk gjennomgang.', true, true, 0),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q02', 'flervalg', 'Hvor ligger Den europeiske menneskerettsdomstolen?', array['Strasbourg', 'Genève', 'Haag', 'Brussel']::text[], 0, 'Den hører til Europarådet.', true, true, 1),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q03', 'flervalg', 'Hva kjennetegner overstatlig myndighet?', array['At statene alltid har vetorett', 'At bare stormakter bestemmer', 'At et organ kan fatte vedtak som binder statene', 'At statene bestemmer alt selv']::text[], 2, 'For eksempel EMD.', true, true, 2),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q04', 'flervalg', 'Hvilke saker har Norge tapt flere av i EMD?', array['Fiskerisaker', 'Oljesaker', 'Skattesaker', 'Barnevernssaker']::text[], 3, 'Om retten til familieliv.', true, true, 3),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q05', 'flervalg', 'Hva gjør FNs traktatorganer?', array['Overvåker konvensjonene gjennom rapporter og anbefalinger', 'Straffer statsledere', 'Vedtar lover i Norge', 'Leder FNs hær']::text[], 0, 'For eksempel FNs barnekomité.', true, true, 4),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q06', 'flervalg', 'Er EMDs dommer bindende for statene?', array['Nei, bare anbefalinger', 'Ja', 'Bare for EU-land', 'Bare for stormakter']::text[], 1, 'Overstatlig myndighet.', true, true, 5),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q07', 'flervalg', 'Hva er NIM?', array['En FN-domstol', 'En frivillig organisasjon', 'Norges institusjon for menneskerettigheter', 'Et politisk parti']::text[], 2, 'Overvåker og gir råd.', true, true, 6),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q08', 'flervalg', 'Hva kjennetegner mellomstatlig samarbeid?', array['At et organ fatter bindende vedtak', 'At statene gir fra seg all makt', 'At det ikke finnes avtaler', 'At statene samarbeider, men beholder vetorett']::text[], 3, 'Som i FN.', true, true, 7),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q09', 'flervalg', 'Hvilken rolle har organisasjoner som Amnesty?', array['Dokumentere brudd og legge press på regjeringer', 'Dømme i straffesaker', 'Vedta lover', 'Lede FN']::text[], 0, 'Gjennom rapporter og kampanjer.', true, false, 8),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'q10', 'flervalg', 'Hva er et argument mot overstatlige organer?', array['At de gir sterkere vern', 'At de flytter makt bort fra nasjonale folkevalgte', 'At de beskytter mindretall', 'At de er billige']::text[], 1, 'Spenning mellom rettigheter og demokrati.', true, false, 9),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'm01', 'sant-usant', 'Man må som hovedregel prøve saken i nasjonale domstoler før man klager til EMD.', array['Sant', 'Usant']::text[], 0, 'Nasjonale rettsmidler må brukes først.', false, true, 10),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'm02', 'sant-usant', 'FNs menneskerettighetsråd kan avsi bindende dommer mot stater.', array['Sant', 'Usant']::text[], 1, 'FN-systemet bygger mest på dialog og press.', false, true, 11),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'm03', 'sant-usant', 'Norge er bundet av mye EU-rett gjennom EØS-avtalen.', array['Sant', 'Usant']::text[], 0, 'Selv om Norge ikke er EU-medlem.', false, true, 12),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'm04', 'sant-usant', 'Menneskerettsforkjempere er trygge i alle land.', array['Sant', 'Usant']::text[], 1, 'I mange land blir de forfulgt.', false, true, 13),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'm05', 'flervalg', 'Hvilket organ behandler klager på den norske forvaltningen?', array['EMD', 'Sivilombudet', 'ICC', 'UPR']::text[], 1, 'Nasjonal klageordning.', false, true, 14),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'm06', 'flervalg', 'Hvor mange medlemsland har FNs menneskerettighetsråd?', array['47', '15', '193', '5']::text[], 0, 'Valgt av FNs generalforsamling.', false, true, 15),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 'm07', 'flervalg', 'Hvilken institusjon kan straffe statsledere for krigsforbrytelser?', array['Sivilombudet', 'FNs barnekomité', 'ICC', 'Europarådet']::text[], 2, 'Den internasjonale straffedomstolen.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 's01', 'FN-systemet bruker dialog, rapportering og offentlig press, og avgjørelsene er i hovedsak ikke juridisk bindende. EMDs dommer er bindende for statene. Forklar en viktig forskjell mellom hvordan FN-systemet og EMD kan påvirke statene.', 'FN-systemet påvirker særlig gjennom anbefalinger og offentlig press, mens EMD kan avsi dommer som statene er juridisk bundet av.', array['Forklarer at FN i hovedsak bruker dialog, anbefalinger eller offentlig press, ikke bindende avgjørelser.', 'Forklarer at EMDs dommer er bindende for statene.']::text[], 0),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 's02', 'En person mener at staten har krenket rettighetene sine etter Den europeiske menneskerettskonvensjonen. Personen har først prøvd saken i nasjonale domstoler. Hvilket organ kan personen klage til, og hva kan organet gjøre?', 'Personen kan klage til Den europeiske menneskerettsdomstolen (EMD). EMD behandler klager fra enkeltpersoner og kan avsi dommer som er bindende for staten.', array['Identifiserer EMD som organet personen kan klage til etter å ha prøvd saken nasjonalt.', 'Forklarer at EMD behandler individklager om statlige krenkelser, og/eller at dommene er bindende.']::text[], 1),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 's03', 'Sammenlign EMD og Den internasjonale straffedomstolen (ICC) ut fra hvem de kan rette avgjørelser mot, og hva slags saker de behandler.', 'EMD behandler klager fra enkeltpersoner som mener en stat har krenket rettighetene deres. ICC kan straffe enkeltpersoner, også statsledere, for de alvorligste forbrytelsene, som folkemord og krigsforbrytelser.', array['Skiller mellom EMD-saker om staters ansvar for menneskerettighetsbrudd og ICC-saker mot enkeltpersoner.', 'Knytter ICC til alvorlige forbrytelser, for eksempel folkemord eller krigsforbrytelser.']::text[], 2),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 's04', 'En person vil klage på hvordan en offentlig etat har behandlet saken deres. Samtidig ønsker en stortingsrepresentant råd om menneskerettighetssituasjonen i Norge. Hvilke to nasjonale institusjoner passer til disse oppgavene, og hva gjør de?', 'Sivilombudet behandler klager på forvaltningen. NIM overvåker menneskerettighetene i Norge og gir råd til Stortinget og regjeringen.', array['Knytter klagen på den offentlige etaten til Sivilombudet og dets arbeid med klager på forvaltningen.', 'Knytter rådet om menneskerettighetssituasjonen til NIMs overvåking og rådgivning.']::text[], 3),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 's05', 'Norge tapte flere saker om barnevern i EMD. Domstolen mente at myndighetene ikke hadde tatt nok hensyn til familiens rett til familieliv. Forklar hvilken følge dommene fikk for norsk praksis.', 'Dommene førte til endringer i norsk barnevernspraksis. De viste at myndighetene måtte ta tilstrekkelig hensyn til familiens rett til familieliv.', array['Nevner at dommene førte til endringer i norsk barnevernspraksis.', 'Knytter sakene til at familiens rett til familieliv ikke var godt nok ivaretatt.']::text[], 4),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 's06', 'En stat bestemmer som hovedregel selv innenfor sine grenser, men har også godtatt at EMD kan fatte bindende dommer. Forklar hvordan dette viser en spenning mellom suverenitet og overstatlig myndighet.', 'Suverenitet betyr at staten bestemmer selv innenfor egne grenser. Når EMD kan fatte bindende dommer, har staten samtidig gitt et organ myndighet til å treffe avgjørelser den må følge.', array['Forklarer suverenitet som statens rett til å bestemme selv innenfor egne grenser.', 'Forklarer at bindende EMD-dommer innebærer at et organ utenfor staten kan fatte avgjørelser staten må følge.']::text[], 5),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 's07', 'Noen traktatorganer mottar jevnlige rapporter fra stater, og noen kan også behandle individklager. Forklar forskjellen på hvem som sender inn en rapport, og hvem som sender inn en individklage.', 'Det er staten som sender jevnlige rapporter til traktatorganet om konvensjonen. En individklage sendes av en enkeltperson som mener at rettighetene deres er krenket.', array['Forklarer at staten sender rapporter til traktatorganet.', 'Forklarer at en individklage kommer fra en enkeltperson som mener rettighetene er krenket.']::text[], 6),
  ('politikk-og-menneskerettigheter:handhevelse-av-menneskerettigheter', 's08', 'Frivillige organisasjoner dokumenterer menneskerettsbrudd og driver kampanjer, mens journalister og varslere kan avsløre overgrep. I mange land blir menneskerettsforkjempere forfulgt. Forklar hvordan slik forfølgelse kan gjøre det vanskeligere å følge med på og reagere på menneskerettsbrudd.', 'Når menneskerettsforkjempere blir forfulgt, kan det bli vanskeligere å dokumentere og avsløre overgrep. Da blir det også vanskeligere for organisasjoner og medier å rette oppmerksomhet mot bruddene og legge press på regjeringer.', array['Knytter forfølgelse til at dokumentasjon eller avsløring av overgrep blir vanskeligere.', 'Forklarer at dette kan svekke oppmerksomhet eller press på myndighetene.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('politikk-og-menneskerettigheter:krig-fred-og-internasjonal-politikk', 'politikk-og-menneskerettigheter', 'krig-fred-og-internasjonal-politikk', 'Krig, fred og internasjonalt samarbeid', 'Hvordan det internasjonale systemet håndterer krig og fred, sikkerhet og samarbeid – FNs sikkerhetsråd, kollektiv sikkerhet og kollektivt forsvar i NATO, fredsbevaring, sanksjoner og mekling – og hvordan du analyserer en konflikt statsvitenskapelig.', array[13, 4]::int[], 10, 'utkast', '{}'::text[], false, now())
