  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 's01', 'Hva var landskapslovene, og hvordan ble de vedtatt?', 'Landskapslovene var middelalderlover, blant annet Gulatingsloven og Frostatingsloven. De ble vedtatt på ting der frie menn møttes.', array['Forklarer at dette var lover fra middelalderen, gjerne med et eksempel.', 'Får fram at lovene ble vedtatt på ting der frie menn møttes.']::text[], 0),
  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 's02', 'Sammenlign hvordan landskapslovene og Christian 5.s Norske Lov ble til. Hva er en viktig forskjell?', 'Landskapslovene ble vedtatt på ting der frie menn møttes. Christian 5.s Norske Lov samlet lovene under eneveldet i 1687.', array['Beskriver at landskapslovene ble vedtatt på ting der frie menn møttes.', 'Beskriver at Christian 5.s Norske Lov samlet lovene under eneveldet.']::text[], 1),
  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 's03', 'En elev sier at dødsstraff ble avskaffet i Norge i 1902, og derfor ikke kunne brukes etter det året. Forklar hva eleven har misforstått.', 'Dødsstraff ble avskaffet i fredstid i 1902, men ble brukt i landssvikoppgjøret etter andre verdenskrig. Den ble helt avskaffet i 1979.', array['Skiller mellom avskaffelsen i fredstid i 1902 og at dødsstraff fortsatt ble brukt i landssvikoppgjøret.', 'Får fram at dødsstraff først ble helt avskaffet i 1979.']::text[], 2),
  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 's04', 'Bedrifter og staten kan samle inn data om mennesker. Forklar hvorfor dette kan bli et juridisk spørsmål når samfunnet endrer seg.', 'Nye forhold kan skape spørsmål som lovene må ta stilling til. Når bedrifter eller staten samler inn data, blir det for eksempel et spørsmål hvor mye de kan samle inn uten å krenke personvernet.', array['Forklarer at nye samfunnsforhold kan føre til nye juridiske spørsmål.', 'Knytter eksempelet til spørsmålet om hvor mye data bedrifter eller staten kan samle inn, eller til personvern.']::text[], 3),
  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 's05', 'En juridisk drøfting beskriver først hva som er gjeldende rett, og vurderer deretter hva retten bør være. Hvilket begrep passer til hver del?', 'Det som er gjeldende rett, er de lege lata. Det som bør være gjeldende rett, er de lege ferenda.', array['Knytter de lege lata til det som er gjeldende rett.', 'Knytter de lege ferenda til det som bør være gjeldende rett.']::text[], 4),
  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 's06', 'I Fosen-saken kom Høyesterett i 2021 fram til at vindkraftverk krenket reindriftssamenes rettigheter. Forklar hvorfor saken er et eksempel på en aktuell problemstilling om urfolksrett.', 'Saken handler om hvordan vindkraftverk påvirket reindriftssamenes rettigheter. Høyesteretts konklusjon om at rettighetene var krenket, gjør saken til et juridisk spørsmål om urfolksrett.', array['Knytter saken til reindriftssamenes rettigheter og vindkraftverkene.', 'Får fram at Høyesterett kom fram til at rettighetene var krenket.']::text[], 5),
  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 's07', 'En part i en juridisk sak publiserer et innlegg med påstander som støtter partens egen interesse. Forklar hvordan du bør undersøke påstandene før du bruker dem som kilder.', 'Vær kildekritisk fordi parten kan ha egeninteresse i saken. Kontroller juridiske opplysninger mot lover og dommer i Lovdata, og bruk gjerne redaktørstyrte medier eller fagartikler for å undersøke debatten.', array['Får fram at partens egeninteresse gjør det viktig å være kildekritisk.', 'Nevner relevante kilder å kontrollere opplysningene mot, for eksempel Lovdata for lover og dommer eller redaktørstyrte medier og fagartikler.']::text[], 6),
  ('rettslare-1:aktuelle-og-rettshistoriske-saker', 's08', 'Du skal drøfte en sak om oljeboring og Grunnlovens miljøparagraf. Beskriv hva du bør undersøke og vurdere før du kommer med en begrunnet konklusjon.', 'Jeg bør finne gjeldende rett, blant annet relevante lover, dommer og menneskerettigheter, og ta med hensyn og argumenter som taler for ulike løsninger. Deretter bør jeg vurdere argumentene og begrunne konklusjonen.', array['Får fram at drøftingen må undersøke relevant gjeldende rett, som lover eller dommer.', 'Får fram at ulike hensyn eller argumenter må vurderes før en begrunnet konklusjon.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('psykologi-1:psykologiske-perspektiver', 'psykologi-1', 'psykologiske-perspektiver', 'Psykologiske perspektiver', 'Hva psykologi er, og de viktigste perspektivene – biologisk, psykodynamisk, atferdsorientert, kognitivt, humanistisk og sosiokulturelt – og hvordan de gir ulike forklaringer på det samme fenomenet.', array[1, 2]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('psykologi-1:psykologiske-perspektiver', '## Hva er psykologi?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('psykologi-1:psykologiske-perspektiver', 'Psykologi', 'Den vitenskapelige studien av tanker, følelser og atferd.', 0),
  ('psykologi-1:psykologiske-perspektiver', 'Wilhelm Wundt', 'Åpnet det første psykologiske laboratoriet i Leipzig i 1879.', 1),
  ('psykologi-1:psykologiske-perspektiver', 'Perspektiv', 'En måte å se på mennesket på, med egne spørsmål og metoder.', 2),
  ('psykologi-1:psykologiske-perspektiver', 'Biologisk perspektiv', 'Forklarer atferd ut fra hjernen, nervesystemet, hormoner og gener.', 3),
  ('psykologi-1:psykologiske-perspektiver', 'Psykodynamisk perspektiv', 'Freuds tradisjon: ubevisste krefter og barndomserfaringer styrer oss.', 4),
  ('psykologi-1:psykologiske-perspektiver', 'Id, ego og superego', 'Freuds tredeling av personligheten: drifter, virkelighetssans og samvittighet.', 5),
  ('psykologi-1:psykologiske-perspektiver', 'Forsvarsmekanisme', 'Ubevisst strategi for å beskytte seg mot angst, for eksempel fortrengning.', 6),
  ('psykologi-1:psykologiske-perspektiver', 'Behaviorisme', 'Atferdsperspektivet: studerer observerbar atferd som læres fra miljøet.', 7),
  ('psykologi-1:psykologiske-perspektiver', 'Kognitivt perspektiv', 'Studerer tankeprosesser som hukommelse, persepsjon og problemløsning.', 8),
  ('psykologi-1:psykologiske-perspektiver', 'Humanistisk perspektiv', 'Vektlegger fri vilje, egenverd og selvrealisering.', 9),
  ('psykologi-1:psykologiske-perspektiver', 'Selvrealisering', 'Å utvikle seg til sitt fulle potensial.', 10),
  ('psykologi-1:psykologiske-perspektiver', 'Sosiokulturelt perspektiv', 'Viser hvordan kultur og sosiale relasjoner former oss.', 11),
  ('psykologi-1:psykologiske-perspektiver', 'Biopsykososial modell', 'Samler biologiske, psykologiske og sosiale faktorer i én forklaring.', 12),
  ('psykologi-1:psykologiske-perspektiver', 'Reduksjonisme', 'Å forklare et sammensatt fenomen med én enkel årsak.', 13),
  ('psykologi-1:psykologiske-perspektiver', 'Carl Rogers', 'Humanistisk psykolog som vektla egenverd og ubetinget aksept.', 14),
  ('psykologi-1:psykologiske-perspektiver', 'Lev Vygotskij', 'Mente at vi lærer og utvikler oss gjennom samhandling med andre.', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('psykologi-1:psykologiske-perspektiver', 'q01', 'flervalg', 'Hva studerer psykologien?', array['Bare hjernen', 'Tanker, følelser og atferd', 'Bare psykiske lidelser', 'Bare dyr']::text[], 1, 'Fra nerveceller til grupper.', true, true, 0),
  ('psykologi-1:psykologiske-perspektiver', 'q02', 'flervalg', 'Hvilket perspektiv legger vekt på ubevisste krefter og barndommen?', array['Det psykodynamiske', 'Det kognitive', 'Det humanistiske', 'Atferdsperspektivet']::text[], 0, 'Stammer fra Sigmund Freud.', true, true, 1),
  ('psykologi-1:psykologiske-perspektiver', 'q03', 'flervalg', 'Hva mente behavioristene at psykologien skulle studere?', array['Drømmer', 'Følelser', 'Observerbar atferd', 'Sjelen']::text[], 2, 'Det som kan observeres og måles.', true, true, 2),
  ('psykologi-1:psykologiske-perspektiver', 'q04', 'flervalg', 'Hvilket perspektiv sammenligner hjernen med en informasjonsbehandler?', array['Det humanistiske', 'Det psykodynamiske', 'Det sosiokulturelle', 'Det kognitive']::text[], 3, 'Studerer tankeprosesser.', true, true, 3),
  ('psykologi-1:psykologiske-perspektiver', 'q05', 'flervalg', 'Hvem er knyttet til det humanistiske perspektivet?', array['Maslow og Rogers', 'Freud og Jung', 'Watson og Skinner', 'Pavlov og Thorndike']::text[], 0, 'De vektla egenverd og selvrealisering.', true, true, 4),
  ('psykologi-1:psykologiske-perspektiver', 'q06', 'flervalg', 'Hva er den biopsykososiale modellen?', array['En modell av hjernen', 'En samlet forklaring med biologiske, psykologiske og sosiale faktorer', 'En test av intelligens', 'En teori om drømmer']::text[], 1, 'Gir en mer helhetlig forklaring.', true, true, 5),
  ('psykologi-1:psykologiske-perspektiver', 'q07', 'flervalg', 'En elev tenker «alle vil synes jeg er dum» før et foredrag. Hvilket perspektiv legger mest vekt på dette?', array['Det biologiske', 'Atferdsperspektivet', 'Det kognitive', 'Det psykodynamiske']::text[], 2, 'Tolkninger og tanker påvirker følelser.', true, true, 6),
  ('psykologi-1:psykologiske-perspektiver', 'q08', 'flervalg', 'Hva betyr det at en forklaring er reduksjonistisk?', array['At den er for lang', 'At den bygger på mange studier', 'At den tar hensyn til kultur', 'At den forenkler et sammensatt fenomen til én årsak']::text[], 3, 'Et vanlig kritikkpunkt.', true, true, 7),
  ('psykologi-1:psykologiske-perspektiver', 'q09', 'flervalg', 'Hvilken kritikk rettes ofte mot Freuds teorier?', array['At de er vanskelige å teste', 'At de bare handler om dyr', 'At de overser barndommen', 'At de bygger på hjernescanning']::text[], 0, 'Ubevisste prosesser er vanskelige å måle.', true, false, 8),
  ('psykologi-1:psykologiske-perspektiver', 'q10', 'flervalg', 'Hva la Vygotskij vekt på?', array['Belønning og straff', 'Læring gjennom samhandling med andre', 'Ubevisste drifter', 'Gener']::text[], 1, 'Et sosiokulturelt syn på læring.', true, false, 9),
  ('psykologi-1:psykologiske-perspektiver', 'm01', 'sant-usant', 'Psykologien ble et eget vitenskapelig fag på slutten av 1800-tallet.', array['Sant', 'Usant']::text[], 0, 'Wundt åpnet laboratoriet i Leipzig i 1879.', false, true, 10),
  ('psykologi-1:psykologiske-perspektiver', 'm02', 'sant-usant', 'Perspektivene i psykologien utelukker hverandre, så bare ett kan være riktig.', array['Sant', 'Usant']::text[], 1, 'De utfyller hverandre og kan kombineres.', false, true, 11),
  ('psykologi-1:psykologiske-perspektiver', 'm03', 'sant-usant', 'Behaviorismen er kritisert for å overse tanker og følelser.', array['Sant', 'Usant']::text[], 0, 'Den studerte bare observerbar atferd.', false, true, 12),
  ('psykologi-1:psykologiske-perspektiver', 'm04', 'sant-usant', 'Superego er Freuds betegnelse på de primitive driftene.', array['Sant', 'Usant']::text[], 1, 'Driftene er id, superego er samvittigheten.', false, true, 13),
  ('psykologi-1:psykologiske-perspektiver', 'm05', 'flervalg', 'Hvilket perspektiv vil forklare angst med aktivitet i amygdala?', array['Det humanistiske', 'Det biologiske', 'Det sosiokulturelle', 'Det psykodynamiske']::text[], 1, 'Hjernen og stresshormonene.', false, true, 14),
  ('psykologi-1:psykologiske-perspektiver', 'm06', 'flervalg', 'Hva er fortrengning?', array['En forsvarsmekanisme', 'En læringsstrategi', 'En hjernedel', 'En forskningsmetode']::text[], 0, 'Ubehagelige minner skyves ut av bevisstheten.', false, true, 15),
  ('psykologi-1:psykologiske-perspektiver', 'm07', 'flervalg', 'Hvilket perspektiv legger størst vekt på kultur og gruppe?', array['Det kognitive', 'Det biologiske', 'Det sosiokulturelle', 'Atferdsperspektivet']::text[], 2, 'Mennesket formes av sine sosiale omgivelser.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('psykologi-1:psykologiske-perspektiver', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('psykologi-1:psykologiske-perspektiver', 's01', 'Forklar hva id, ego og superego står for i Freuds tredeling av personligheten, og hvordan de skiller seg fra hverandre.', 'Id står for driftene, ego for virkelighetssansen og superego for samvittigheten. De viser ulike sider ved personligheten i Freuds teori.', array['Knytter id til drifter og ego til virkelighetssans.', 'Knytter superego til samvittighet.']::text[], 0),
  ('psykologi-1:psykologiske-perspektiver', 's02', 'Hvorfor regnes Wilhelm Wundts åpning av et psykologisk laboratorium i Leipzig i 1879 som et vendepunkt for psykologien?', 'Da Wundt åpnet laboratoriet i Leipzig i 1879, ble psykologien et eget vitenskapelig fag. Før dette hørte spørsmål om sjelen og tenkningen til filosofien.', array['Får fram at psykologien ble et eget vitenskapelig fag.', 'Nevner at slike spørsmål tidligere hørte til filosofien.']::text[], 1),
  ('psykologi-1:psykologiske-perspektiver', 's03', 'En elev får ros etter å ha deltatt i timen, og begynner etter hvert å delta oftere. Forklar hvordan en behaviorist kan forstå denne endringen.', 'En behaviorist vil forklare deltakelsen som atferd som er lært gjennom samspill med miljøet. Ros fungerer som en belønning som kan gjøre at eleven deltar oftere.', array['Forklarer endringen som lært atferd påvirket av miljøet.', 'Knytter rosen til belønning og økt deltakelse.']::text[], 2),
  ('psykologi-1:psykologiske-perspektiver', 's04', 'En elev tolker en nøytral kommentar fra læreren som kritikk og slutter å stille spørsmål. Bruk det kognitive perspektivet til å forklare hvordan tolkningen kan påvirke elevens følelser og atferd.', 'Det kognitive perspektivet legger vekt på at måten eleven tolker kommentaren på, kan påvirke følelsene og atferden. Når eleven tolker kommentaren som kritikk, kan det bidra til at eleven blir utrygg og slutter å stille spørsmål.', array['Får fram at tolkning eller tankeprosesser påvirker følelser og atferd.', 'Knytter elevens tolkning av kommentaren til at eleven slutter å stille spørsmål.']::text[], 3),
  ('psykologi-1:psykologiske-perspektiver', 's05', 'En elev lærer en ny ferdighet mens hen arbeider sammen med andre. Forklar hvordan behaviorismen og det sosiokulturelle perspektivet kan gi ulike forklaringer på læringen.', 'Behaviorismen kan forklare læringen med at atferd læres gjennom samspill med miljøet, blant annet gjennom belønning og straff. Det sosiokulturelle perspektivet legger vekt på at eleven lærer gjennom samhandling med andre.', array['Knytter behaviorismen til lært atferd og påvirkning fra miljøet.', 'Knytter det sosiokulturelle perspektivet til læring gjennom samhandling med andre.']::text[], 4),
  ('psykologi-1:psykologiske-perspektiver', 's06', 'Jon velger selv et mål han ønsker å utvikle seg mot. Forklar hvordan en humanistisk psykolog kan forstå betydningen av dette målet.', 'Det humanistiske perspektivet vektlegger fri vilje og egenverd. Å arbeide mot målet kan forstås som selvrealisering, altså å utvikle seg til sitt fulle potensial.', array['Knytter perspektivet til fri vilje eller egenverd.', 'Forklarer målet som en del av selvrealisering eller utvikling av eget potensial.']::text[], 5),
  ('psykologi-1:psykologiske-perspektiver', 's07', 'Forklar hvordan fortrengning kan fungere som en forsvarsmekanisme.', 'Fortrengning er en ubevisst strategi der en person holder ubehagelige tanker eller erfaringer utenfor bevisstheten. Den kan beskytte personen mot angst.', array['Får fram at fortrengning er ubevisst.', 'Forklarer at den kan beskytte mot angst.']::text[], 6),
  ('psykologi-1:psykologiske-perspektiver', 's08', 'En forklaring hevder at en elevs lave deltakelse bare skyldes genene. Vurder forklaringen ved å bruke begrepet reduksjonisme og den biopsykososiale modellen.', 'Forklaringen er reduksjonistisk fordi den forklarer et sammensatt fenomen med én årsak. Den biopsykososiale modellen ville også tatt med psykologiske og sosiale faktorer, i tillegg til biologiske faktorer som gener.', array['Forklarer at én årsak alene gjør forklaringen reduksjonistisk.', 'Får fram at den biopsykososiale modellen samler biologiske, psykologiske og sosiale faktorer.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('psykologi-1:forskningsmetoder', 'psykologi-1', 'forskningsmetoder', 'Forskningsmetoder og kildebruk i psykologi', 'Hvordan psykologer forsker – eksperimenter, korrelasjonsstudier, observasjon, intervju, spørreskjema og kasusstudier – hva reliabilitet, validitet og etikk betyr, og hvordan du finner og vurderer psykologisk informasjon.', array[1, 2]::int[], 1, 'utkast', '{}'::text[], false, now())
