insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q01', 'flervalg', 'Hva er etterspørsel?', array['En følelse av at noe mangler', 'Et ønske kunden har kjøpekraft til å gjennomføre', 'Et produkt', 'En reklame']::text[], 1, 'Behov og ønsker blir etterspørsel når kunden kan betale.', true, true, 0),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q02', 'flervalg', 'Hva kjennetegner markedsorientering?', array['Kundenes behov er utgangspunktet', 'Fokus på billig produksjon', 'Aggressivt salg', 'Bare kvalitet']::text[], 0, 'Virksomheten starter med kunden.', true, true, 1),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q03', 'flervalg', 'Hva står de fire P-ene for?', array['Plan, pris, personale og profitt', 'Produkt, profil, pris og presse', 'Produkt, pris, plass og påvirkning', 'Pris, prosess, plass og personale']::text[], 2, 'Markedsføringsmiksen.', true, true, 2),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q04', 'flervalg', 'Hvilke P-er kommer i tillegg for tjenester?', array['Profitt, plan og presse', 'Pris og produkt', 'Promotering og plassering', 'Personale, prosess og fysiske omgivelser']::text[], 3, 'Sju P-er.', true, true, 3),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q05', 'flervalg', 'Hva er relasjonsmarkedsføring?', array['Å bygge langsiktige forhold til kundene', 'Å selge mest mulig på kort tid', 'Å bare reklamere på TV', 'Å senke prisene']::text[], 0, 'Det er ofte billigere å beholde en kunde enn å skaffe en ny.', true, true, 4),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q06', 'flervalg', 'Hvilken oppgave er en klassisk lederoppgave?', array['Å produsere varene selv', 'Å planlegge, organisere, lede og kontrollere', 'Å selge i kassen', 'Å designe logoen']::text[], 1, 'Fire klassiske lederoppgaver.', true, true, 5),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q07', 'flervalg', 'Hva er det første steget i en markedsplan?', array['Kontroll', 'Budsjett', 'Situasjonsanalyse', 'Reklame']::text[], 2, 'Hvor står vi?', true, true, 6),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q08', 'flervalg', 'Hvorfor bør du være kritisk til en virksomhets egne pressemeldinger?', array['De er alltid feil', 'De er for korte', 'De er ulovlige', 'Virksomheten har egeninteresse i å vise seg fram']::text[], 3, 'Sjekk mot flere kilder.', true, true, 7),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q09', 'flervalg', 'Hva kjennetegner samfunnsorientering?', array['Hensyn også til samfunn og miljø på lang sikt', 'Fokus bare på profitt', 'Fokus på produksjon', 'Aggressivt salg']::text[], 0, 'Den nyeste orienteringen.', true, false, 8),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'q10', 'flervalg', 'Hva er en modell i markedsføring?', array['En person i reklame', 'En forenkling som hjelper oss å strukturere en analyse', 'Et produkt', 'En lov']::text[], 1, 'Modeller har også svakheter.', true, false, 9),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'm01', 'sant-usant', 'Markedsføring er mer enn reklame.', array['Sant', 'Usant']::text[], 0, 'Det handler om å skape og levere verdi.', false, true, 10),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'm02', 'sant-usant', 'Produksjonsorientering passer best når tilbudet er mye større enn etterspørselen.', array['Sant', 'Usant']::text[], 1, 'Den oppstod når etterspørselen var større enn tilbudet.', false, true, 11),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'm03', 'sant-usant', 'Modeller som de fire P-ene er forenklinger av virkeligheten.', array['Sant', 'Usant']::text[], 0, 'De hjelper oss å strukturere en analyse.', false, true, 12),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'm04', 'sant-usant', 'Det er alltid billigere å skaffe en ny kunde enn å beholde en gammel.', array['Sant', 'Usant']::text[], 1, 'Det er ofte omvendt.', false, true, 13),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'm05', 'flervalg', 'Hvilken P handler om distribusjon?', array['Påvirkning', 'Plass', 'Pris', 'Produkt']::text[], 1, 'Hvor og hvordan kunden får tak i produktet.', false, true, 14),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'm06', 'flervalg', 'Hvilken kilde gir offisiell statistikk?', array['SSB', 'En influencer', 'En reklameplakat', 'Et nettforum']::text[], 0, 'Statistisk sentralbyrå.', false, true, 15),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 'm07', 'flervalg', 'Hva er et behov?', array['Et bestemt merke', 'Et ønske med kjøpekraft', 'En følelse av at noe mangler', 'En pris']::text[], 2, 'For eksempel sult.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 's01', 'En kunde kjenner at hen er sulten, får lyst på en burger, men har ikke penger til å kjøpe den. Hva er behovet, hva er ønsket, og hvorfor er dette ikke etterspørsel?', 'Sulten er behovet, og burgeren er ønsket. Det er ikke etterspørsel fordi kunden ikke har kjøpekraft til å gjennomføre kjøpet.', array['Skiller mellom behovet (at noe mangler) og ønsket (den konkrete formen behovet tar).', 'Forklarer at ønsket ikke er etterspørsel fordi kunden mangler kjøpekraft.']::text[], 0),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 's02', 'En virksomhet bruker penger på reklame, men undersøker ikke hva kundene trenger og vurderer ikke hvordan tilbudet skal gi dem verdi. Forklar hvorfor virksomheten ikke dekker hele markedsføringsarbeidet.', 'Markedsføring er mer enn reklame. Virksomheten må også forstå kundene og skape og levere verdi til dem, i tillegg til å kommunisere verdien.', array['Forklarer at markedsføring omfatter mer enn kommunikasjon eller reklame.', 'Nevner at virksomheten må forstå kundene og skape eller levere verdi til dem.']::text[], 1),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 's03', 'Sammenlign produksjonsorientering og salgsorientering. Hva fokuserer virksomheten på i hver orientering, og hvilken markedssituasjon forbindes de med?', 'Ved produksjonsorientering er etterspørselen større enn tilbudet, og virksomheten fokuserer på effektiv og billig produksjon. Ved salgsorientering er tilbudet stort, og virksomheten satser på aggressivt salg.', array['Knytter produksjonsorientering til stor etterspørsel sammenlignet med tilbudet og effektiv, billig produksjon.', 'Knytter salgsorientering til stort tilbud og aggressivt salg.']::text[], 2),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 's04', 'En kjede skal lansere en ny bærekraftig produktserie. Foreslå ett tiltak for hver av de fire P-ene: produkt, pris, plass og påvirkning.', 'Kjeden kan tilby produkter med bærekraftige egenskaper, velge en pris, bestemme hvor produktene skal selges og kommunisere lanseringen til kundene. Tiltakene viser hva kjeden tilbyr, hva det koster, hvor kundene får tak i det, og hvordan det kommuniseres.', array['Gir et relevant tiltak for produkt og pris.', 'Gir et relevant tiltak for plass og påvirkning.']::text[], 3),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 's05', 'En leder setter mål for en arbeidsgruppe og bestemmer deretter hvem som skal gjøre de ulike oppgavene. Hvilken lederoppgave beskrives i hver del, og hva skiller dem?', 'Å sette mål er planlegging. Å fordele oppgaver er organisering: planlegging handler om mål og strategier, mens organisering handler om fordeling av oppgaver og ressurser.', array['Identifiserer målsetting som planlegging.', 'Identifiserer oppgavefordeling som organisering og skiller mellom hva de innebærer.']::text[], 4),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 's06', 'I en markedsplan er mål og strategi fastsatt, og virksomheten har valgt konkurransemidler. Hva kommer deretter, og hva skal virksomheten undersøke i kontrollfasen?', 'Etter valg av konkurransemidler kommer gjennomføring og budsjett. I kontrollfasen undersøker virksomheten om den nådde målene.', array['Plasserer gjennomføring og budsjett etter konkurransemidlene.', 'Forklarer at kontroll handler om å undersøke om målene ble nådd.']::text[], 5),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 's07', 'En elev bruker en modell som eneste grunnlag for å analysere en virksomhet. Forklar hvorfor dette kan gi et ufullstendig bilde, og hva eleven bør gjøre med modellens svakheter.', 'En modell er en forenkling og passer ikke alltid perfekt til situasjonen. Eleven bør derfor vurdere modellens svakheter i stedet for å behandle analysen som et fullstendig bilde.', array['Forklarer at modeller forenkler og derfor ikke alltid passer perfekt.', 'Sier at modellens svakheter bør vurderes.']::text[], 6),
  ('markedsforing-og-ledelse-1:markedsforing-og-teorier', 's08', 'En butikk ønsker å beholde flere av kundene sine. Foreslå ett tiltak innen relasjonsmarkedsføring, og forklar hvorfor det passer med målet.', 'Butikken kan for eksempel bruke god service, en kundeklubb eller dialog med kundene for å bygge langsiktige forhold. Det passer fordi relasjonsmarkedsføring handler om å beholde og utvikle forholdet til kunder, og det er ofte billigere å beholde en kunde enn å skaffe en ny.', array['Foreslår et relevant tiltak, som god service, kundeklubb eller dialog.', 'Knytter tiltaket til langsiktige kundeforhold eller til at det ofte er billigere å beholde kunder enn å skaffe nye.']::text[], 7);
