  ('markedsforing-og-ledelse-1:forbrukeratferd', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-1:forbrukeratferd', 's01', 'Forklar hva forbrukeratferd handler om, fra kunden begynner å velge et produkt til kunden kvitter seg med det.', 'Forbrukeratferd handler om hvordan mennesker velger, kjøper og bruker varer og tjenester, og hvordan de kvitter seg med dem.', array['Får fram at forbrukeratferd omfatter flere deler av kundens forhold til varer eller tjenester, ikke bare selve kjøpet.', 'Nevner både kjøp eller bruk og det å kvitte seg med produktet.']::text[], 0),
  ('markedsforing-og-ledelse-1:forbrukeratferd', 's02', 'Sammenlign et rutinekjøp, som å kjøpe melk, med et omfattende kjøp, som å kjøpe en bil. Hvordan skiller de seg i engasjement og informasjonssøk?', 'Ved et rutinekjøp er engasjementet lite, og kunden søker vanligvis lite informasjon. Bilkjøpet er dyrt og viktig, så kunden har høyt engasjement og søker mye informasjon.', array['Beskriver rutinekjøp som et kjøp med lite engasjement og lite informasjonssøk.', 'Beskriver omfattende problemløsning som et viktig kjøp med høyt engasjement og mye informasjonssøk.']::text[], 1),
  ('markedsforing-og-ledelse-1:forbrukeratferd', 's03', 'En kunde har bestemt seg for å kjøpe en mobil. Kunden sammenligner nå pris, kvalitet, merke og egenskaper hos flere mobiler. Hvilket trinn i kjøpsprosessen er kunden i, og hva gjør kunden i dette trinnet?', 'Kunden er i trinnet vurdering av alternativer. Kunden veier egenskaper ved de ulike mobilene opp mot hverandre før kjøpsbeslutningen.', array['Identifiserer vurdering av alternativer som trinnet.', 'Forklarer at kunden sammenligner eller veier ulike egenskaper ved alternativene.']::text[], 2),
  ('markedsforing-og-ledelse-1:forbrukeratferd', 's04', 'En butikk plasserer en vare godt synlig ved inngangen. Forklar hvordan dette kan påvirke kundens valg ved hjelp av begrepet persepsjon.', 'Persepsjon handler om hvordan vi legger merke til og tolker informasjon. Den synlige plasseringen kan gjøre at kunden legger merke til varen og vurderer den som et alternativ.', array['Forklarer persepsjon som det å legge merke til og tolke informasjon.', 'Knytter den synlige plasseringen til at kunden lettere legger merke til varen eller påvirkes i vurderingen.']::text[], 3),
  ('markedsforing-og-ledelse-1:forbrukeratferd', 's05', 'En kunde har hatt gode erfaringer med et merke og velger det igjen. Hvilken psykologisk faktor forklarer hvordan erfaringer kan føre til lojalitet? Forklar sammenhengen.', 'Læring kan forklare dette. Erfaringer med et merke kan gjøre kunden lojal mot det og føre til at kunden velger det igjen.', array['Identifiserer læring som den relevante psykologiske faktoren.', 'Forklarer at erfaringer kan gjøre kunden lojal mot et merke eller påvirke framtidige valg.']::text[], 4),
  ('markedsforing-og-ledelse-1:forbrukeratferd', 's06', 'En student og en småbarnsfamilie vurderer hva de trenger å kjøpe. Forklar hvordan livsfase kan føre til at de har ulike behov og kjøper ulike ting.', 'Livsfase handler om hvor i livet man er. En student og en småbarnsfamilie kan derfor ha ulike behov, noe som påvirker hva de kjøper.', array['Forklarer at livsfase er hvor i livet en person eller familie befinner seg.', 'Knytter ulike livsfaser til ulike behov og dermed ulike kjøp.']::text[], 5),
  ('markedsforing-og-ledelse-1:forbrukeratferd', 's07', 'En nettbutikk viser en kunde anbefalinger som en algoritme har valgt ut. Forklar hvordan slike anbefalinger kan påvirke kundens kjøpsvalg.', 'Anbefalinger fra algoritmer kan påvirke hvilke produkter kunden legger merke til og vurderer. Det kan dermed påvirke hva kunden velger å kjøpe.', array['Får fram at algoritmeanbefalinger kan påvirke kunden.', 'Forklarer at påvirkningen kan skje ved at kunden legger merke til eller vurderer bestemte produkter.']::text[], 6),
  ('markedsforing-og-ledelse-1:forbrukeratferd', 's08', 'En gruppe gamere har egne verdier og en egen stil, og medlemmene velger produkter som passer til dette. Forklar hvorfor gruppen kan kalles en subkultur, og hvordan den kan påvirke medlemmenes kjøp.', 'Gruppen kan kalles en subkultur fordi den har egne verdier og en egen stil innenfor en større kultur. Dette kan påvirke hvilke produkter medlemmene velger.', array['Forklarer at en subkultur er en gruppe innenfor en kultur med egne verdier eller stil.', 'Knytter gruppetilhørigheten til medlemmenes produktvalg.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
