  ('markedsforing-og-ledelse-1:markedskommunikasjon', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-1:markedskommunikasjon', 's01', 'Forklar hva markedskommunikasjon er, og hva virksomheten ønsker å oppnå gjennom den.', 'Markedskommunikasjon er kommunikasjon virksomheten har med markedet for å påvirke kundene. Den skal informere, overbevise og minne kundene på produktene.', array['Forklarer at markedskommunikasjon er virksomhetens kommunikasjon eller påvirkning rettet mot markedet.', 'Får fram at den skal informere, overbevise og/eller minne kundene på produktene.']::text[], 0),
  ('markedsforing-og-ledelse-1:markedskommunikasjon', 's02', 'En bedrift publiserer et innlegg om et produkt i sosiale medier. Mulige kunder ser innlegget, og noen kommenterer. Pek ut avsender, kanal, mottaker og respons i situasjonen.', 'Bedriften er avsender, og innlegget er budskapet som sendes gjennom sosiale medier som kanal. De mulige kundene er mottakere, og kommentarene deres er respons.', array['Identifiserer bedriften som avsender, sosiale medier som kanal og kundene som mottakere.', 'Forklarer at kommentarene er mottakernes respons.']::text[], 1),
  ('markedsforing-og-ledelse-1:markedskommunikasjon', 's03', 'Forklar forskjellen på målene kjennskap, holdning og handling i markedskommunikasjon. Hva skal kunden vite, like eller gjøre ved hvert mål?', 'Kjennskap betyr at kunden skal vite om produktet, mens holdning betyr at kunden skal like det. Handling betyr at kunden skal kjøpe produktet eller gjøre noe annet.', array['Skiller mellom kjennskap som å vite om produktet og holdning som å like det.', 'Forklarer handling som å kjøpe produktet eller gjøre noe annet.']::text[], 2),
  ('markedsforing-og-ledelse-1:markedskommunikasjon', 's04', 'Sammenlign reklame og personlig salg ut fra hvor mange de kan nå, og hvor godt kommunikasjonen kan tilpasses den enkelte kunden.', 'Reklame er betalt kommunikasjon i medier som kan nå mange, men gir liten mulighet for dialog. Personlig salg skjer ansikt til ansikt eller på telefon og kan tilpasses kunden.', array['Får fram at reklame kan nå mange, men gir liten mulighet for dialog.', 'Får fram at personlig salg kan tilpasses den enkelte kunden.']::text[], 3),
  ('markedsforing-og-ledelse-1:markedskommunikasjon', 's05', 'En virksomhet vil bruke en rasjonell appell i en annonse. Gi ett eksempel på hva annonsen kan framheve, og forklar hvorfor dette er en rasjonell appell.', 'Annonsen kan framheve produktets pris. Det er en rasjonell appell fordi budskapet bygger på fakta.', array['Gir et eksempel på fakta annonsen kan framheve, for eksempel pris, egenskaper eller kvalitet.', 'Begrunner at dette er rasjonelt fordi budskapet bygger på fakta.']::text[], 4),
  ('markedsforing-og-ledelse-1:markedskommunikasjon', 's06', 'En produsent gir forhandlere rabatter og lager samtidig annonser som skal få forbrukere til å etterspørre produktet. Forklar hvilken strategi hvert tiltak viser, og hvem tiltakene er rettet mot.', 'Rabattene til forhandlerne er en push-strategi, fordi kommunikasjonen rettes mot forhandlerne. Annonsene rettet mot forbrukerne er en pull-strategi, fordi de skal skape etterspørsel hos forbrukerne.', array['Knytter rabattene til forhandlerne til push og forklarer at strategien retter seg mot forhandlere.', 'Knytter annonsene til forbrukerne til pull og forklarer at strategien skal skape etterspørsel.']::text[], 5),
  ('markedsforing-og-ledelse-1:markedskommunikasjon', 's07', 'En virksomhet støtter et kulturarrangement og får logoen sin synlig der. Forklar hvorfor dette er sponsing, og hva virksomheten får igjen for støtten.', 'Dette er sponsing fordi virksomheten støtter kultur mot å få synlighet. Synligheten kan bidra til et positivt image for virksomheten.', array['Forklarer at sponsing innebærer støtte til idrett, kultur eller frivillighet i bytte mot synlighet.', 'Får fram at støtten og synligheten kan bidra til et positivt image.']::text[], 6),
  ('markedsforing-og-ledelse-1:markedskommunikasjon', 's08', 'En virksomhet vil gjøre et produktbudskap lettere å huske. Forklar hvordan historiefortelling kan hjelpe, og hva historiefortelling betyr i denne sammenhengen.', 'Historiefortelling betyr å formidle budskapet gjennom en fortelling. Det kan gjøre budskapet lettere for kundene å huske.', array['Forklarer at historiefortelling formidler budskapet gjennom en fortelling.', 'Knytter historiefortelling til at budskapet blir lettere å huske.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('markedsforing-og-ledelse-1:mediemiks-og-innhold', 'markedsforing-og-ledelse-1', 'mediemiks-og-innhold', 'Mediemiks og innhold', 'Hvordan virksomheter planlegger mediemiks: betalte, eide og fortjente medier, styrker og svakheter ved ulike kanaler, begreper som dekning, frekvens og tusenkontaktpris, medieplanen – og hvordan du lager innhold tilpasset ulike kanaler.', array[10]::int[], 9, 'utkast', '{}'::text[], false, now())
