insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('entreprenorskap-og-bedriftsutvikling-1:innovasjonsprosesser', 's01', 'En kafé lanserer en ny suppe på menyen og innfører en ny måte å tilberede bestillingene på. Forklar hvilken endring som er produktinnovasjon, og hvilken som er prosessinnovasjon.', 'Den nye suppen er en produktinnovasjon fordi det er en ny vare. Den nye måten å tilberede bestillingene på er en prosessinnovasjon fordi det er en ny måte å produsere eller levere på.', array['Knytter den nye suppen til en ny vare eller et nytt produkt.', 'Knytter den nye tilberedningsmåten til en ny måte å produsere eller levere på.']::text[], 0),
  ('entreprenorskap-og-bedriftsutvikling-1:innovasjonsprosesser', 's02', 'En sykkelprodusent gjør små forbedringer på en eksisterende modell. En annen bedrift utvikler en løsning som skaper et helt nytt marked. Sammenlign hvilken type innovasjon de to endringene er.', 'Forbedringene på sykkelen er inkrementell innovasjon fordi de er små og gradvise. Løsningen som skaper et helt nytt marked, er radikal innovasjon fordi den innebærer en stor endring.', array['Klassifiserer små, gradvise forbedringer som inkrementell innovasjon.', 'Klassifiserer endringen som skaper et helt nytt marked, som radikal innovasjon.']::text[], 1),
  ('entreprenorskap-og-bedriftsutvikling-1:innovasjonsprosesser', 's03', 'Elever opplever lange køer i skolekantina. Forklar hvordan de kan bruke empati og definere-stegene i designtenkning for å forstå hva de bør løse.', 'I empati-steget kan de observere elevene eller intervjue dem for å forstå opplevelsen deres. Deretter formulerer de det egentlige problemet, for eksempel hva som skaper køene.', array['Beskriver at empati handler om å forstå brukerne gjennom observasjon eller intervjuer.', 'Beskriver at definere-steget handler om å formulere det egentlige problemet.']::text[], 2),
  ('entreprenorskap-og-bedriftsutvikling-1:innovasjonsprosesser', 's04', 'En elevgruppe lager en enkel pappmodell av en ny selvbetjeningsløsning. Forklar hva modellen kan brukes til, og hva gruppen kan lære av å la brukere prøve den.', 'Pappmodellen er en prototyp som gjør det mulig å prøve en enkel versjon av løsningen. Når brukere tester den, kan gruppen få ny innsikt og forbedre løsningen eller gå tilbake til tidligere steg.', array['Forklarer at en prototyp er en enkel modell som kan prøves ut.', 'Forklarer at brukertesting gir læring eller innsikt som kan brukes til å forbedre løsningen.']::text[], 3),
  ('entreprenorskap-og-bedriftsutvikling-1:innovasjonsprosesser', 's05', 'En gründer er usikker på om kunder vil bestille en ny tjeneste for matlevering. Beskriv hvordan gründeren kan bruke bygg, mål og lær for å teste antakelsen, og hva hen bør gjøre hvis testen viser at antakelsen er feil.', 'Gründeren kan bygge en enkel versjon av tjenesten som kan gi læring, måle hvordan kundene reagerer og lære av resultatet. Hvis antakelsen viser seg å være feil, bør gründeren justere tilbudet eller endre retning.', array['Beskriver en rask og enkel test av antakelsen, for eksempel med en enkel versjon av tjenesten.', 'Knytter måling til kundenes faktiske reaksjoner.', 'Beskriver justering eller endret retning hvis testen viser at antakelsen er feil.']::text[], 4),
  ('entreprenorskap-og-bedriftsutvikling-1:innovasjonsprosesser', 's06', 'En møbelbutikk begynner å selge gjennom direktesendte produktvisninger på nettet i tillegg til den vanlige butikken. Forklar hvilken type innovasjon dette er, og hvorfor.', 'Dette er en markedsinnovasjon fordi butikken tar i bruk en ny måte å nå kunder og selge produktene på. Selve møblene trenger ikke å være nye eller forbedret.', array['Identifiserer endringen som markedsinnovasjon.', 'Forklarer at endringen gjelder en ny måte å selge til eller nå kunder på.']::text[], 5),
  ('entreprenorskap-og-bedriftsutvikling-1:innovasjonsprosesser', 's07', 'En oppstartsbedrift skal diskutere en hemmelig idé med en mulig samarbeidspartner. Hvilken avtale kan bedriften bruke for å beskytte informasjonen, og hva innebærer avtalen?', 'Bedriften kan bruke en taushetserklæring. Det er en avtale om at den fortrolige informasjonen ikke skal deles med andre.', array['Foreslår en taushetserklæring.', 'Forklarer at avtalen innebærer at fortrolig informasjon ikke skal deles.']::text[], 6),
  ('entreprenorskap-og-bedriftsutvikling-1:innovasjonsprosesser', 's08', 'Mange innovasjoner mislykkes før de lykkes. Forklar hvorfor det kan være nyttig for en virksomhet å ha en kultur der ansatte får prøve, feile og lære.', 'Når ansatte får prøve og feile, kan virksomheten lære av det som ikke fungerer og forbedre løsningene sine. Det støtter innovasjon fordi mange innovasjoner mislykkes underveis.', array['Knytter det å prøve og feile til læring eller forbedring.', 'Forklarer at læring underveis støtter innovasjon, som ofte innebærer at noe ikke lykkes.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('entreprenorskap-og-bedriftsutvikling-1:forretningsmodeller-og-barekraft', 'entreprenorskap-og-bedriftsutvikling-1', 'forretningsmodeller-og-barekraft', 'Forretningsmodeller og bærekraft', 'Hva en forretningsmodell er, de ni byggeklossene i forretningsmodellkanvaset, vanlige typer forretningsmodeller som abonnement, plattform og gratisversjon med betalte tillegg – og hvordan du vurderer en forretningsmodell opp mot bærekraftig utvikling.', array[4]::int[], 3, 'utkast', '{}'::text[], false, now())
