  ('samfunnsokonomi-1:penge-og-finanspolitikk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsokonomi-1:penge-og-finanspolitikk', 's01', 'Hva skal stabiliseringspolitikken bidra til, og hvilke mål prøver den å nå?', 'Stabiliseringspolitikken skal dempe svingningene mellom høy og lav økonomisk aktivitet. Den skal bidra til lav og stabil prisstigning, høy sysselsetting og jevn vekst.', array['Forklarer at politikken skal dempe konjunktursvingningene.', 'Nevner de sentrale målene: stabil prisstigning, høy sysselsetting og jevn vekst.']::text[], 0),
  ('samfunnsokonomi-1:penge-og-finanspolitikk', 's02', 'Sammenlign en høykonjunktur og en lavkonjunktur ved å beskrive produksjon, arbeidsledighet og press på priser eller lønninger.', 'I en høykonjunktur er produksjonen høy, arbeidsledigheten lav og det er ofte press på lønninger og priser. I en lavkonjunktur er produksjonen lavere, arbeidsledigheten øker og bedriftene har ledig kapasitet.', array['Skiller mellom høy produksjon og lav produksjon.', 'Sammenligner arbeidsledigheten riktig og beskriver pris- og lønnspress eller ledig kapasitet.']::text[], 1),
  ('samfunnsokonomi-1:penge-og-finanspolitikk', 's03', 'Hva er forskjellen på pengepolitikk og finanspolitikk når det gjelder hvem som styrer dem, og hvilke virkemidler de bruker?', 'Norges Bank styrer pengepolitikken og bruker særlig styringsrenten. Regjeringen og Stortinget styrer finanspolitikken gjennom statsbudsjettets utgifter, skatter og avgifter.', array['Knytter pengepolitikken til Norges Bank og styringsrenten.', 'Knytter finanspolitikken til regjeringen og Stortinget og virkemidler i statsbudsjettet.']::text[], 2),
  ('samfunnsokonomi-1:penge-og-finanspolitikk', 's04', 'Det er lav produksjon og arbeidsledigheten øker. Beskriv ett pengepolitisk tiltak Norges Bank kan bruke, og forklar hvordan det kan øke etterspørselen.', 'Norges Bank kan sette ned styringsrenten. Da blir det billigere å låne, og konsumet og investeringene kan øke, slik at etterspørselen blir større.', array['Foreslår lavere styringsrente som et tiltak i lavkonjunktur.', 'Forklarer at lavere rente kan øke konsum eller investeringer og dermed etterspørselen.']::text[], 3),
  ('samfunnsokonomi-1:penge-og-finanspolitikk', 's05', 'Forklar hvordan dagpenger og skatteinntekter kan virke automatisk stabiliserende når økonomien går inn i en lavkonjunktur.', 'Når flere blir arbeidsledige, øker utgiftene til dagpenger. Samtidig faller skatteinntektene når folk tjener mindre, og dette bidrar til å holde etterspørselen oppe uten nye vedtak.', array['Forklarer at utgiftene til dagpenger øker i lavkonjunktur.', 'Forklarer at skatteinntektene faller når inntektene går ned, og at dette støtter etterspørselen automatisk.']::text[], 4),
  ('samfunnsokonomi-1:penge-og-finanspolitikk', 's06', 'Bruk handlingsregelen til å forklare hvordan statens bruk av oljepenger kan tilpasses både dårlige og gode økonomiske tider.', 'Over tid skal staten bruke om lag den forventede realavkastningen av oljefondet. I dårlige tider kan den bruke mer, mens den i gode tider bør bruke mindre.', array['Beskriver regelen om å bruke om lag forventet realavkastning over tid.', 'Forklarer at staten kan bruke mer i dårlige tider og bør bruke mindre i gode tider.']::text[], 5),
  ('samfunnsokonomi-1:penge-og-finanspolitikk', 's07', 'Regjeringen øker offentlige utgifter kraftig mens etterspørselen allerede er høy. Forklar hvorfor Norges Bank da kan komme til å sette renten høyere enn ellers.', 'Økte offentlige utgifter gjør finanspolitikken ekspansiv og øker etterspørselen. For å dempe presset på økonomien og prisstigningen kan Norges Bank sette renten høyere enn den ellers ville gjort.', array['Forklarer at økte offentlige utgifter øker etterspørselen.', 'Knytter høyere rente til å dempe etterspørselen eller prispresset.']::text[], 6),
  ('samfunnsokonomi-1:penge-og-finanspolitikk', 's08', 'Norges Bank setter opp renten for å dempe prisveksten, men virkningen kommer først etter en tid. Forklar hvorfor dette tidsetterslepet gjør det krevende å styre økonomien.', 'Når renteendringen virker, kan den økonomiske situasjonen ha endret seg siden beslutningen ble tatt. Derfor kan tiltaket komme sent i forhold til konjunkturen og være vanskelig å tilpasse nøyaktig.', array['Forklarer at virkningen kommer etter at tiltaket er satt inn.', 'Beskriver at økonomien kan ha endret seg før virkningen kommer, slik at tiltaket blir vanskelig å treffe riktig med.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('samfunnsokonomi-1:finansmarkeder', 'samfunnsokonomi-1', 'finansmarkeder', 'Finansmarkeder', 'Hva finansmarkedene er – bank, aksjer, obligasjoner og valuta – hvilke oppgaver de har i økonomien, hvilke muligheter de gir for vekst, og hvilke utfordringer som bobler, gjeld og finanskriser skaper – og hvordan markedene reguleres.', array[9]::int[], 9, 'utkast', '{}'::text[], false, now())
