insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q01', 'flervalg', 'Hva er et komparativt fortrinn?', array['Å produsere alt billigst', 'Å ha lavest alternativkostnad for en vare', 'Å ha mest olje', 'Å ha høyest toll']::text[], 1, 'Beskrevet av David Ricardo.', true, true, 0),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q02', 'flervalg', 'Hvorfor kan handel lønne seg selv om ett land er best på alt?', array['Fordi land har ulike alternativkostnader', 'Fordi handel alltid er gratis', 'Fordi toll gir inntekter', 'Det kan det ikke']::text[], 0, 'Begge kan få mer ved å spesialisere seg.', true, true, 1),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q03', 'flervalg', 'Hva er Norges viktigste eksportvarer?', array['Biler og klær', 'Kaffe og bananer', 'Olje, gass, fisk og metaller', 'Elektronikk og maskiner']::text[], 2, 'Naturressurser er viktige.', true, true, 2),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q04', 'flervalg', 'Hva er toll?', array['En subsidie', 'En kvote', 'En frihandelsavtale', 'En skatt på importerte varer']::text[], 3, 'En handelshindring.', true, true, 3),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q05', 'flervalg', 'Hva gir EØS-avtalen Norge?', array['Tilgang til EUs indre marked', 'Medlemskap i EU', 'Egen valuta i EU', 'Fritak fra alle EU-regler']::text[], 0, 'Fri flyt av varer, tjenester, kapital og personer.', true, true, 4),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q06', 'flervalg', 'Hva er en ulempe med handelshindringer for forbrukerne?', array['Lavere priser', 'Høyere priser', 'Mer utvalg', 'Mer konkurranse']::text[], 1, 'Men de kan beskytte arbeidsplasser.', true, true, 5),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q07', 'flervalg', 'Hva er stordriftsfordeler?', array['Høyere kostnader ved stor produksjon', 'Fordeler ved å være liten', 'Lavere kostnader per enhet ved stor produksjon', 'Høyere toll']::text[], 2, 'Et verdensmarked gjør stor skala mulig.', true, true, 6),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q08', 'flervalg', 'Hva viste pandemien om globale verdikjeder?', array['At de er helt trygge', 'At handel ikke betyr noe', 'At transport er gratis', 'At mangel på én komponent kan stanse produksjon verden over']::text[], 3, 'Verdikjedene er sårbare.', true, true, 7),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q09', 'flervalg', 'Hva gjør WTO?', array['Lager regler for handel mellom land', 'Styrer Norges rente', 'Eier oljefondet', 'Bestemmer valutakursene']::text[], 0, 'Skal redusere handelshindringer.', true, false, 8),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'q10', 'flervalg', 'Hva er en mulighet ved globalisering?', array['Mer utflytting av arbeidsplasser', 'Raskere spredning av teknologi og mindre fattigdom', 'Sårbare verdikjeder', 'Mer skatteplanlegging']::text[], 1, 'Mange land har fått høyere velstand.', true, false, 9),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'm01', 'sant-usant', 'Norge er en liten, åpen økonomi med mye handel.', array['Sant', 'Usant']::text[], 0, 'Handel er svært viktig for Norge.', false, true, 10),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'm02', 'sant-usant', 'EØS-avtalen gjør Norge til medlem av EU.', array['Sant', 'Usant']::text[], 1, 'Den gir tilgang til det indre markedet uten medlemskap.', false, true, 11),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'm03', 'sant-usant', 'Konkurranse fra utlandet kan gjøre bedrifter mer effektive.', array['Sant', 'Usant']::text[], 0, 'De må forbedre seg for å overleve.', false, true, 12),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'm04', 'sant-usant', 'Globalisering har bare positive virkninger.', array['Sant', 'Usant']::text[], 1, 'Den gir også utfordringer som ulikhet og sårbare verdikjeder.', false, true, 13),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'm05', 'flervalg', 'Hvilken norsk næring er beskyttet av toll?', array['Oljenæringen', 'Landbruket', 'Fiskeoppdrett', 'IT']::text[], 1, 'For å sikre norsk matproduksjon.', false, true, 14),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'm06', 'flervalg', 'Hva er proteksjonisme?', array['Å beskytte egne næringer mot utenlandsk konkurranse', 'Å fjerne all toll', 'Å øke eksporten', 'Å innføre felles valuta']::text[], 0, 'For eksempel med toll og kvoter.', false, true, 15),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 'm07', 'flervalg', 'Hvorfor vil flere land produsere mer selv i dag?', array['For å øke importen', 'For å redusere eksporten', 'Av hensyn til sikkerhet og selvforsyning', 'For å få lavere lønn']::text[], 2, 'En motstrøm mot globaliseringen.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 's01', 'Norge har olje, gass, fisk og vannkraft, men kan ikke dyrke bananer og kaffe. Forklar hvordan forskjeller i ressurser kan føre til handel mellom land, med Norge som eksempel.', 'Land kan selge varer de har gode ressurser til å produsere, og kjøpe varer de ikke kan produsere selv. Norge kan for eksempel eksportere olje og fisk og importere varer som bananer og kaffe.', array['Knytter handel til at land har ulike ressurser eller produksjonsmuligheter.', 'Bruker Norge som eksempel på varer landet kan eksportere og varer det må importere.']::text[], 0),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 's02', 'Sammenlign absolutt fortrinn og komparativt fortrinn. Hva er forskjellen på hva de måler?', 'Absolutt fortrinn betyr at et land kan produsere en vare billigere enn andre land. Komparativt fortrinn handler om hvilket land som gir opp minst av andre varer for å produsere den aktuelle varen.', array['Forklarer at absolutt fortrinn handler om å produsere billigere enn andre.', 'Forklarer at komparativt fortrinn handler om lavest alternativkostnad, altså å gi opp minst av andre varer.']::text[], 1),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 's03', 'Tenk deg at en norsk butikk selger både varer fra Norge og importerte klær eller elektronikk. Forklar hvordan importen kan være en fordel for forbrukerne.', 'Import gjør at forbrukerne kan velge mellom varer fra flere land. Det gir større utvalg enn dersom de bare kunne kjøpe varer produsert i Norge.', array['Forklarer at import gir tilgang til varer fra flere land.', 'Knytter dette til større utvalg for forbrukerne.']::text[], 2),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 's04', 'Norge selger blant annet olje og gass, fisk og metaller til utlandet, og kjøper blant annet biler, maskiner, klær og elektronikk fra andre land. Forklar hvorfor Norge kan beskrives som en åpen økonomi.', 'Norge er en åpen økonomi fordi landet har mye handel med utlandet. Det både eksporterer varer og importerer varer.', array['Forklarer at en åpen økonomi har mye handel med utlandet.', 'Bruker både eksport og import som tegn på slik handel.']::text[], 3),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 's05', 'Et land setter en øvre grense for hvor mye klær som kan importeres, for å skjerme egne produsenter. Hva slags handelshindring er dette, og hvordan kan den påvirke markedet?', 'Dette er en importkvote, fordi landet begrenser hvor mye som kan importeres. Kvoten kan beskytte egne produsenter mot utenlandsk konkurranse, men kan også bidra til høyere priser for forbrukerne.', array['Identifiserer grensen for importmengden som en importkvote.', 'Forklarer at kvoten kan beskytte egne produsenter mot utenlandsk konkurranse.']::text[], 4),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 's06', 'Sammenlign rollene til WTO og EFTA i internasjonal handel.', 'WTO lager regler for handel mellom de fleste land i verden og skal bidra til å redusere handelshindringer. EFTA er en frihandelsorganisasjon som Norge bruker til å ha frihandelsavtaler med en rekke andre land.', array['Beskriver WTOs rolle med regler for internasjonal handel og å redusere handelshindringer.', 'Beskriver EFTA som en organisasjon Norge har frihandelsavtaler gjennom.']::text[], 5),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 's07', 'Et norsk foretak investerer i produksjon i et annet land og bruker teknologi fra utlandet. Forklar hvorfor dette er et eksempel på økonomisk globalisering.', 'Dette er økonomisk globalisering fordi økonomier i ulike land blir tettere knyttet sammen. Investeringer og teknologi på tvers av landegrenser er måter slik sammenkobling skjer på.', array['Forklarer at økonomisk globalisering innebærer at landenes økonomier knyttes tettere sammen.', 'Knytter investeringer eller teknologi på tvers av land til denne sammenkoblingen.']::text[], 6),
  ('samfunnsokonomi-1:internasjonal-handel-og-globalisering', 's08', 'Et land innfører nye tollsatser og vil produsere mer selv av hensyn til sikkerhet. Forklar hvordan dette kan knyttes til proteksjonisme og selvforsyning.', 'Tollsatser kan beskytte landets egne næringer mot utenlandsk konkurranse, og er derfor et uttrykk for proteksjonisme. Å produsere mer selv for å dekke egne behov handler om selvforsyning.', array['Knytter tollsatser til å beskytte egne næringer mot utenlandsk konkurranse.', 'Forklarer selvforsyning som å produsere det landet trenger selv.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-vg3:realismen', 'norsk-vg3', 'realismen', 'Realismen og det moderne gjennombruddet', 'Realismen i norsk litteratur fra 1850 til 1890: det moderne gjennombruddet, problemlitteraturen og de fire store – Ibsen, Bjørnson, Kielland og Lie – og Camilla Collett, med vekt på hvordan tekstene framstiller menneske og samfunn.', array[1, 2]::int[], 0, 'utkast', '{}'::text[], false, now())
