insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-vg3:naturalismen-og-nyromantikken', 's01', 'Émile Zola ville skrive romaner nesten som vitenskapelige eksperimenter. Forklar hvordan denne ideen passer med naturalismens syn på hva som former mennesket.', 'Romanen kan undersøke hvordan arv, miljø og drifter påvirker mennesket. Dette passer med naturalismens syn på at mennesket har liten fri vilje.', array['Knytter eksperimentideen til å undersøke eller skildre mennesket.', 'Forklarer at arv, miljø og drifter former mennesket og begrenser fri vilje.']::text[], 0),
  ('norsk-vg3:naturalismen-og-nyromantikken', 's02', 'Sammenlign Amalie Skrams Constance Ring og Hellemyrsfolket. Hva skildrer hvert verk, og hva har de til felles?', 'Constance Ring skildrer en kvinne som er fanget i et ulykkelig ekteskap, mens Hellemyrsfolket følger en slekt gjennom flere generasjoner og viser hvordan fattigdom og arv fører nedover. Begge verkene skildrer menneskers liv under vanskelige vilkår.', array['Skiller mellom handlingen eller motivet i de to verkene.', 'Får fram en relevant likhet, for eksempel at begge skildrer menneskers vanskelige livsvilkår.']::text[], 1),
  ('norsk-vg3:naturalismen-og-nyromantikken', 's03', 'Tenk deg en roman der en person formes av arv, fattigdom og drifter. Fortelleren skildrer sykdom og fattigdom detaljert og nøkternt, og slutten er pessimistisk. Forklar hvilke trekk som gjør romanen naturalistisk.', 'Romanen er naturalistisk fordi mennesket framstilles som styrt av arv, miljø og drifter. Den detaljerte, nøkterne skildringen og den pessimistiske slutten er også typiske naturalistiske trekk.', array['Knytter menneskets situasjon til arv, miljø eller drifter.', 'Identifiserer minst ett av stiltrekkene: detaljert/naken skildring, objektiv forteller eller pessimistisk slutt.']::text[], 2),
  ('norsk-vg3:naturalismen-og-nyromantikken', 's04', 'Sammenlign naturalismen og nyromantikken når det gjelder hva de retter oppmerksomheten mot, og hvordan mennesket blir framstilt.', 'Naturalismen retter oppmerksomheten mot samfunnet og det ytre, og framstiller mennesket som styrt av arv og miljø. Nyromantikken fokuserer på sjelen og det indre, og framstiller mennesket som sammensatt og gåtefullt.', array['Skiller mellom retningenes fokus på det ytre/samfunnet og det indre/sjelen.', 'Skiller mellom naturalismens menneskesyn og nyromantikkens menneskesyn.']::text[], 3),
  ('norsk-vg3:naturalismen-og-nyromantikken', 's05', 'På 1890-tallet reagerte mange forfattere mot realismen og naturalismen. Forklar hva de mente disse retningene ga et for begrenset bilde av, og hva de derfor ville utforske.', 'De mente at realismen og naturalismen ga et for ytre og mekanisk bilde av mennesket. Derfor ville de utforske sjelelivet, blant annet det indre, ubevisste og uforklarlige.', array['Forklarer kritikken av det ytre eller mekaniske menneskebildet.', 'Nevner utforskingen av sjelelivet eller det indre og ubevisste.']::text[], 4),
  ('norsk-vg3:naturalismen-og-nyromantikken', 's06', 'I nyromantikken kunne naturen speile sjelen, og forfatterne brukte symboler i stedet for direkte samfunnskritikk. Forklar hva et symbol kan bidra med i en slik tekst.', 'Et symbol er et konkret bilde som står for noe mer. I en nyromantisk tekst kan det uttrykke en følelse eller en side ved sjelen indirekte, i stedet for å kritisere samfunnet direkte.', array['Forklarer at et symbol har en betydning utover det konkrete bildet.', 'Knytter symbolbruken til å uttrykke indre liv eller følelser indirekte.']::text[], 5),
  ('norsk-vg3:naturalismen-og-nyromantikken', 's07', 'Knut Hamsun mente at litteraturen burde skildre sjelens små, uforklarlige bevegelser. Forklar hvordan innholdet og fortellemåten i Sult passer med dette synet.', 'Sult skildrer den unge forfatteren innenfra, med skiftende stemninger, galskap og stolthet. Slik viser romanen skiftninger i det indre livet framfor bare å beskrive ytre forhold.', array['Viser til at romanen skildrer hovedpersonen innenfra eller fokuserer på det indre.', 'Knytter skiftende stemninger, galskap eller stolthet til sjelens bevegelser.']::text[], 6),
  ('norsk-vg3:naturalismen-og-nyromantikken', 's08', 'Hans Jæger og Kristiania-bohemen utfordret normene i samtiden. Forklar hva de protesterte mot, og hvilken livsform eller holdning de krevde større frihet til.', 'Kristiania-bohemen protesterte mot borgerlig moral og krevde fri kjærlighet. De utfordret dermed de rådende normene for hvordan mennesker skulle leve og elske.', array['Nevner protesten mot borgerlig moral.', 'Nevner kravet om fri kjærlighet.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-vg3:mellomkrigstiden', 'norsk-vg3', 'mellomkrigstiden', 'Litteratur fra 1900 til 1945', 'Norsk litteratur i første halvdel av 1900-tallet: nyrealismen med Sigrid Undset og Olav Duun, psykologisk realisme hos Cora Sandel og Aksel Sandemose, arbeiderlitteratur, tidlig modernisme og den politiske lyrikken i møte med fascismen og krigen.', array[1, 2]::int[], 2, 'utkast', '{}'::text[], false, now())
