  ('norsk-vg3:mellomkrigstiden', 'm04', 'sant-usant', 'Nordahl Grieg overlevde krigen.', array['Sant', 'Usant']::text[], 1, 'Han døde som krigskorrespondent i 1943.', false, true, 13),
  ('norsk-vg3:mellomkrigstiden', 'm05', 'flervalg', 'Hva heter Rolf Jacobsens debutsamling?', array['Haugtussa', 'Jord og jern', 'Sult', 'Juvikfolke']::text[], 1, 'Fra 1933.', false, true, 14),
  ('norsk-vg3:mellomkrigstiden', 'm06', 'flervalg', 'Hvilket tema står sentralt hos Undset og Duun?', array['Moral, ansvar og tro', 'Teknologi', 'Reklame', 'Romfart']::text[], 0, 'Store romanverk om menneskelig utvikling.', false, true, 15),
  ('norsk-vg3:mellomkrigstiden', 'm07', 'flervalg', 'Når ble Norge selvstendig?', array['1814', '1884', '1905', '1945']::text[], 2, 'Unionen med Sverige ble oppløst.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-vg3:mellomkrigstiden', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-vg3:mellomkrigstiden', 's01', 'Hva kjennetegner nyrealismen, og hvilken type verk skrev mange nyrealistiske forfattere?', 'Nyrealismen var en tilbakevending til en realistisk fortellemåte etter nyromantikken. Mange forfattere skrev store romanverk.', array['Forklarer at nyrealismen vendte tilbake til en realistisk fortellemåte.', 'Nevner at mange skrev store romanverk.']::text[], 0),
  ('norsk-vg3:mellomkrigstiden', 's02', 'Sammenlign Kristin Lavransdatter og Juvikfolke ut fra hva slags fortellinger de er, og hva de skildrer.', 'Kristin Lavransdatter er en trilogi fra middelalderen om en kvinne som velger kjærligheten mot farens vilje og må leve med konsekvensene. Juvikfolke følger en slekt i Trøndelag gjennom flere hundre år og viser hvordan mennesket kan vokse fra makt til godhet.', array['Beskriver Kristin Lavransdatter som en middelaldertrilogi om en kvinnes valg og konsekvensene av dem.', 'Beskriver Juvikfolke som en slektsserie over flere hundre år med utviklingen fra makt til godhet.']::text[], 1),
  ('norsk-vg3:mellomkrigstiden', 's03', 'Arbeiderbevegelsen vokste fram samtidig som industrialiseringen endret arbeidslivet. Forklar hvordan arbeiderlitteraturen knyttet seg til denne utviklingen.', 'Arbeiderlitteraturen kom med arbeiderbevegelsen og ble skrevet om og for arbeiderne. Den skildret blant annet klasseforskjeller, harde arbeidsforhold og solidaritet.', array['Knytter arbeiderlitteraturens framvekst til arbeiderbevegelsen og arbeidernes liv.', 'Nevner hvordan litteraturen tok opp sosiale forhold som klasseforskjeller eller harde arbeidsforhold, gjerne også solidaritet.']::text[], 2),
  ('norsk-vg3:mellomkrigstiden', 's04', 'En diktsamling bruker frie vers og skildrer teknologi, byer og maskiner. Hvilken retning innen norsk lyrikk passer dette med, og hvilken forfatter er knyttet til den? Begrunn svaret.', 'Dette passer med tidlig modernistisk lyrikk. Rolf Jacobsen regnes som en pioner for denne lyrikken, og han skrev frie vers om blant annet teknologi, byer og maskiner.', array['Kjenner igjen tidlig modernisme eller modernistisk lyrikk.', 'Knytter trekkene til Rolf Jacobsen og begrunner svaret med frie vers eller motiver som teknologi, byer og maskiner.']::text[], 3),
  ('norsk-vg3:mellomkrigstiden', 's05', 'Sammenlign hvordan Cora Sandel og Aksel Sandemose skildrer individets kamp for frihet i et trangt miljø.', 'Sandel skildrer en ung kvinne som kjemper for å bli forfatter og frigjøre seg i en tid da kvinner hadde få muligheter. Sandemose viser hvordan et lite samfunn kan knuse den som skiller seg ut.', array['Knytter Sandels skildring til en kvinnes kamp for å bli forfatter og frigjøre seg.', 'Knytter Sandemoses skildring til et lite samfunn som motarbeider den som skiller seg ut.']::text[], 4),
  ('norsk-vg3:mellomkrigstiden', 's06', 'I et lite samfunn blir en person stadig holdt tilbake når hen prøver å skille seg ut. Bruk begrepet Janteloven til å forklare hva som skjer med personen.', 'Situasjonen uttrykker Janteloven: den som skiller seg ut, blir møtt med budskapet om at hen ikke skal tro at hen er noe. Slike regler kan begrense personens frihet og mulighet til å utvikle seg.', array['Forklarer at Janteloven handler om at et lite samfunn holder tilbake den som skiller seg ut.', 'Viser hvordan dette kan begrense individets frihet eller mulighet til å utvikle seg.']::text[], 5),
  ('norsk-vg3:mellomkrigstiden', 's07', 'Under okkupasjonen ble dikt spredt i hemmelighet. Forklar hvordan dette kunne gjøre lyrikk til en del av motstandskampen.', 'Politisk engasjerte dikt kunne uttrykke motstand mot fascisme og krig. Når diktene ble spredt i hemmelighet under okkupasjonen, ble de en del av motstandskampen.', array['Knytter diktene til politisk motstand mot fascisme eller krig.', 'Forklarer at hemmelig spredning under okkupasjonen gjorde diktene til en del av motstandskampen.']::text[], 6),
  ('norsk-vg3:mellomkrigstiden', 's08', 'Sammenlign hva som står i sentrum hos Hamsun på den ene siden og arbeiderdikterne og de politiske lyrikerne på den andre.', 'Hos Hamsun blir naturen og jorda et motbilde til det moderne samfunnet. Arbeiderdikterne og de politiske lyrikerne retter oppmerksomheten mot samfunnet og urett.', array['Forklarer at Hamsun framhever naturen og jorda som et motbilde til det moderne.', 'Forklarer at arbeiderdikterne og de politiske lyrikerne retter søkelyset mot samfunnet og urett.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-vg3:modernismen-etter-1945', 'norsk-vg3', 'modernismen-etter-1945', 'Modernismen og litteraturen 1945–1980', 'Modernismens kjennetegn og gjennombrudd i norsk litteratur etter andre verdenskrig: lyrikkmodernismen og tungetaledebatten, Tarjei Vesaas'' symbolske prosa, Olav H. Hauge, Jens Bjørneboe, Profil-generasjonen og den politiske og feministiske litteraturen på 1970-tallet.', array[1, 2]::int[], 3, 'utkast', '{}'::text[], false, now())
