insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q01', 'flervalg', 'Hva undersøker en retorisk analyse?', array['Rim og rytme', 'Hvordan en tekst prøver å overbevise, og om den lykkes', 'Bare fakta i teksten', 'Forfatterens liv']::text[], 1, 'Brukes på sakprosa.', true, true, 0),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q02', 'flervalg', 'Hva er etos?', array['Appell gjennom avsenderens troverdighet', 'Appell til følelser', 'Appell til fornuften', 'Rett timing']::text[], 0, 'Kompetanse, erfaring og velvilje.', true, true, 1),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q03', 'flervalg', 'Hva er kairos?', array['En argumentasjonsfeil', 'Et språklig bilde', 'Rett tidspunkt og tilpasning til situasjonen', 'En sjanger']::text[], 2, 'Timing.', true, true, 2),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q04', 'flervalg', 'Hva er en hjemmel?', array['Hovedpåstanden', 'Et sitat', 'Konklusjonen', 'Den uuttalte forutsetningen som knytter belegg og påstand']::text[], 3, 'Ofte underforstått.', true, true, 3),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q05', 'flervalg', 'En debattant angriper motpartens utseende i stedet for argumentene. Hva kalles dette?', array['Personangrep', 'Stråmann', 'Falsk dilemma', 'Glidebane']::text[], 0, 'Angriper personen, ikke saken.', true, true, 4),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q06', 'flervalg', '«Enten er du for full frihet, eller så vil du ha diktatur.» Hvilken feil er dette?', array['Stråmann', 'Falsk dilemma', 'Personangrep', 'Autoritetsargument']::text[], 1, 'Det finnes flere alternativer.', true, true, 5),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q07', 'flervalg', 'Hvilken appellform bruker statistikk og fakta?', array['Etos', 'Patos', 'Logos', 'Kairos']::text[], 2, 'Appell til fornuften.', true, true, 6),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q08', 'flervalg', 'Hva bør vurderingen i en retorisk analyse handle om?', array['Om du er enig i saken', 'Hvor lang teksten er', 'Hvem som betalte avisen', 'Om teksten er overbevisende for målgruppen']::text[], 3, 'Skill mellom egen mening og tekstens retorikk.', true, true, 7),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q09', 'flervalg', 'Hva er et glidebaneargument?', array['Å påstå at ett steg uunngåelig fører til katastrofe', 'Å angripe personen', 'Å gjenta et ord', 'Å bruke statistikk']::text[], 0, 'En vanlig argumentasjonsfeil.', true, false, 8),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'q10', 'flervalg', 'Hvorfor kan en tekst bruke vi-form?', array['For å virke upersonlig', 'For å skape fellesskap med leseren', 'For å skjule avsenderen', 'Fordi det er et krav i sakprosa']::text[], 1, 'Et språklig virkemiddel.', true, false, 9),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'm01', 'sant-usant', 'Du kan være uenig i en påstand og likevel mene at teksten er retorisk sterk.', array['Sant', 'Usant']::text[], 0, 'Skill mellom mening og analyse.', false, true, 10),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'm02', 'sant-usant', 'Patos betyr appell gjennom avsenderens troverdighet.', array['Sant', 'Usant']::text[], 1, 'Patos er appell til følelser.', false, true, 11),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'm03', 'sant-usant', 'Sakprosa kan også tolkes, for eksempel ut fra verdier og menneskesyn.', array['Sant', 'Usant']::text[], 0, 'Hva sies – og hva sies ikke?', false, true, 12),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'm04', 'sant-usant', 'Hjemmelen står alltid tydelig i teksten.', array['Sant', 'Usant']::text[], 1, 'Den er ofte uuttalt.', false, true, 13),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'm05', 'flervalg', 'Hva er en stråmann?', array['Å angripe personen', 'Å angripe en forvrengt versjon av motpartens syn', 'Å bruke statistikk', 'Å gjenta et poeng']::text[], 1, 'En vanlig argumentasjonsfeil.', false, true, 14),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'm06', 'flervalg', 'Hvilket virkemiddel er et tretall?', array['«Vi trenger mot, vilje og handling»', '«Er det rettferdig?»', '«Han er en løve»', '«Vi»']::text[], 0, 'Tre ledd gir rytme og tyngde.', false, true, 15),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 'm07', 'flervalg', 'Hva hører til den retoriske situasjonen?', array['Rim og rytme', 'Antall avsnitt', 'Avsender, mottaker, formål og kontekst', 'Skrifttypen']::text[], 2, 'Første steg i analysen.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 's01', 'Når du analyserer en kronikk, undersøker du blant annet hvem avsenderen og mottakeren er. Forklar hvordan kunnskap om avsenderen eller mottakeren kan hjelpe deg med å forstå hvordan kronikken prøver å påvirke.', 'Kunnskap om avsenderens rolle og troverdighet kan forklare hvorfor mottakeren vil stole på teksten. Kunnskap om mottakeren kan vise hvordan teksten tilpasser argumentene sine til det målgruppen vet eller mener fra før.', array['Forklarer hvordan en opplysning om avsenderen kan påvirke tekstens troverdighet eller virkning.', 'Forklarer hvordan teksten kan tilpasses mottakerens kunnskap eller meninger.']::text[], 0),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 's02', 'Én tekst bruker en personlig fortelling som skal vekke medfølelse. En annen bruker fakta og logiske argumenter. Sammenlign hvilken appellform tekstene bruker, og hvordan de prøver å påvirke leseren.', 'Fortellingen bruker patos ved å appellere til leserens følelser. Faktaene og de logiske argumentene bruker logos ved å appellere til leserens fornuft.', array['Knytter den personlige fortellingen til patos og følelsesappell.', 'Knytter fakta og logiske argumenter til logos og fornuftsappell.']::text[], 1),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 's03', 'En skribent skriver: «Kommunen bør lage flere møteplasser for ungdom, fordi ungdom trenger steder å møtes.» Hva er hovedpåstanden, og hva er belegget?', 'Hovedpåstanden er at kommunen bør lage flere møteplasser for ungdom. Belegget er at ungdom trenger steder å møtes.', array['Identifiserer hva skribenten vil at leseren skal mene, som hovedpåstanden.', 'Identifiserer begrunnelsen som støtter påstanden, som belegget.']::text[], 2),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 's04', 'En debattant snakker med to personer som misliker et forslag, og konkluderer med at alle innbyggerne er imot det. Hvilken argumentasjonsfeil gjør debattanten, og hvorfor?', 'Dette er en generalisering ut fra få eksempler. To personers mening gir ikke grunnlag for å konkludere med hva alle innbyggerne mener.', array['Identifiserer generalisering ut fra få eksempler.', 'Forklarer at grunnlaget er for lite til å trekke en konklusjon om alle.']::text[], 3),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 's05', 'Kommunestyret skal snart avgjøre en sak. En organisasjon publiserer et innlegg om saken rett før avgjørelsen. Forklar hvorfor tidspunktet kan gi teksten god kairos, og hva teksten også må passe til for å treffe situasjonen.', 'Tidspunktet kan gi god kairos fordi innlegget kommer mens saken er aktuell og før avgjørelsen. Innholdet må også passe til saken og situasjonen det skal påvirke.', array['Knytter kairos til at tidspunktet passer fordi saken er aktuell eller avgjørelsen nærmer seg.', 'Forklarer at teksten også må passe til den konkrete saken eller situasjonen.']::text[], 4),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 's06', 'Sammenlign assosiasjonene i uttrykkene «et modig tiltak» og «et risikabelt eksperiment». Hvordan kan ordvalget påvirke leserens syn på det samme forslaget?', '«Et modig tiltak» har positive konnotasjoner og kan få forslaget til å virke handlekraftig. «Et risikabelt eksperiment» har mer negative konnotasjoner og kan få det til å virke uforsvarlig eller usikkert.', array['Forklarer at «modig tiltak» vekker positive assosiasjoner.', 'Forklarer at «risikabelt eksperiment» vekker negative assosiasjoner, og knytter ordvalget til hvordan forslaget framstår.']::text[], 5),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 's07', 'En taler sier: «Hvor lenge skal vi godta at stemmen vår ikke blir hørt?» Forklar hvorfor dette kan være et retorisk spørsmål, og hvilken virkning det kan ha på tilhørerne.', 'Spørsmålet er retorisk fordi det ikke først og fremst ber om et konkret svar. Det kan understreke frustrasjon og få tilhørerne til å reflektere eller føle seg engasjert.', array['Forklarer at spørsmålet ikke er ment å få et konkret svar.', 'Beskriver en relevant virkning, for eksempel at det understreker et poeng eller engasjerer tilhørerne.']::text[], 6),
  ('norsk-vg3:retorisk-analyse-av-sakprosa', 's08', 'Du er uenig i hovedpåstanden i en tekst, men mener at teksten likevel er retorisk sterk. Forklar hvordan disse vurderingene kan henge sammen.', 'Du kan være uenig i hva teksten vil at du skal mene, men likevel vurdere at den argumenterer godt og bruker virkemidler som kan overbevise målgruppen. Din egen mening om saken er ikke det samme som en vurdering av hvordan teksten argumenterer.', array['Skiller mellom egen enighet i saken og vurdering av tekstens argumentasjon.', 'Forklarer at teksten kan være overbevisende eller retorisk sterk selv om leseren er uenig i påstanden.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-vg3:sammensatte-tekster', 'norsk-vg3', 'sammensatte-tekster', 'Sammensatte tekster i ulike medier', 'Hvordan du analyserer uttrykksformene i sammensatte tekster – skrift, bilde, lyd og bevegelse – og vurderer samspillet mellom dem i reklame, film, nyhetsartikler, sosiale medier, tegneserier og dataspill.', array[5]::int[], 8, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-vg3:sammensatte-tekster', '## Hva er en sammensatt tekst?
