  ('norsk-vg3:sammensatte-tekster', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-vg3:sammensatte-tekster', 's01', 'Hva betyr gyldne snitt i bildekomposisjon?', 'Gyldne snitt er et komposisjonsprinsipp der motivet plasseres utenfor midten av bildet.', array['Forklarer at det handler om plasseringen av motivet.', 'Får fram at motivet plasseres utenfor midten.']::text[], 0),
  ('norsk-vg3:sammensatte-tekster', 's02', 'Sammenlign fugleperspektiv og froskeperspektiv. Hvordan er bildene tatt, og hvordan kan motivet virke i hvert av dem?', 'Fugleperspektiv er tatt ovenfra og kan få motivet til å virke lite eller sårbart. Froskeperspektiv er tatt nedenfra og kan få motivet til å virke mektig.', array['Knytter fugleperspektiv til fotografering ovenfra og at motivet kan virke lite eller sårbart.', 'Knytter froskeperspektiv til fotografering nedenfra og at motivet kan virke mektig.']::text[], 1),
  ('norsk-vg3:sammensatte-tekster', 's03', 'I én sammensatt tekst uttrykker bilde og skrift det samme budskapet. I en annen gir skriften informasjon som ikke kommer fram i bildet. Forklar hva slags samspill de to tekstene har.', 'Når bilde og skrift uttrykker det samme, er samspillet forsterkende. Når skriften gir mer informasjon enn bildet, er samspillet utdypende.', array['Identifiserer det første eksempelet som forsterkende samspill.', 'Identifiserer det andre eksempelet som utdypende samspill og forklarer at én uttrykksform gir mer informasjon.']::text[], 2),
  ('norsk-vg3:sammensatte-tekster', 's04', 'Hva er et klipp i film, og hvordan kan klipping bidra til å fortelle eller skape stemning?', 'Et klipp er overgangen mellom to bilder eller scener. Valg av klipp kan bidra til å fortelle historien og skape stemning.', array['Forklarer at klipp er en overgang mellom bilder eller scener.', 'Nevner at klipping kan bidra til fortelling eller stemning.']::text[], 3),
  ('norsk-vg3:sammensatte-tekster', 's05', 'Et bilde viser en person som ser rett mot den som ser på bildet. Hvilken virkning kan dette blikket ha?', 'Når personen ser rett mot oss, kan blikket skape kontakt mellom personen i bildet og den som ser på det.', array['Knytter blikket rett mot betrakteren til at det skaper kontakt.']::text[], 4),
  ('norsk-vg3:sammensatte-tekster', 's06', 'En organisasjon legger ut et innlegg på sosiale medier for å få ungdom til å delta på et arrangement. Pek ut avsender, mottaker, formål og kanal i kommunikasjonssituasjonen.', 'Avsenderen er organisasjonen, mottakerne er ungdom, formålet er å få dem til å delta på arrangementet, og kanalen er sosiale medier.', array['Identifiserer organisasjonen som avsender og ungdom som mottakere.', 'Identifiserer formålet som å få ungdom til å delta på arrangementet.', 'Identifiserer sosiale medier som kanal.']::text[], 5),
  ('norsk-vg3:sammensatte-tekster', 's07', 'En reklame publiseres i sosiale medier uten at det kommer fram at innlegget er reklame. Hva må gjøres med innlegget?', 'Innlegget må merkes som reklame, siden reklame i sosiale medier skal være merket.', array['Sier at innlegget må merkes som reklame.']::text[], 6),
  ('norsk-vg3:sammensatte-tekster', 's08', 'Sammenlign hvilke uttrykksformer som typisk brukes i tegneserier og i film.', 'Tegneserier kombinerer ruter, snakkebobler og tegnestil. Film bruker blant annet klipp, musikk, lys og kameravinkler til å fortelle og skape stemning.', array['Nevner ruter, snakkebobler eller tegnestil som typiske uttrykksformer i tegneserier.', 'Nevner uttrykksformer som klipp, musikk, lys eller kameravinkler i film.', 'Får fram en relevant forskjell mellom mediene.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-vg3:fagartikkel-og-kildebruk', 'norsk-vg3', 'fagartikkel-og-kildebruk', 'Fagartikkel, kildebruk og språklige formkrav', 'Hvordan du orienterer deg i faglitteratur, vurderer kilder kritisk og skriver en fagartikkel som greier ut og drøfter et norskfaglig emne – med etterrettelig kildebruk, presist og nyansert språk og riktig rettskriving på hovedmål og sidemål.', array[9, 8]::int[], 9, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-vg3:fagartikkel-og-kildebruk', '## Hva er en fagartikkel?
