  ('norsk-vg3:muntlig-fordypning', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('norsk-vg3:muntlig-fordypning', 's01', 'Sammenlign en utforskende samtale og en diskusjon. Hva er forskjellen på målet deltakerne har, og hvordan de forholder seg til ulike synspunkter?', 'I en utforskende samtale tenker deltakerne sammen for å forstå noe bedre, og de kan endre mening underveis. I en diskusjon argumenterer de for ulike standpunkter og bør møte andres synspunkter med respekt.', array['Skiller mellom å undersøke noe sammen og å argumentere for standpunkter.', 'Får fram hvordan deltakerne forholder seg til andres syn eller egne meninger.']::text[], 0),
  ('norsk-vg3:muntlig-fordypning', 's02', 'I en utforskende samtale sier en medelev noe du vil undersøke videre. Skriv et svar som viser aktiv lytting og inviterer medelevens til å utdype tanken.', 'Du kan vise at du har fått med deg poenget, og stille et åpent oppfølgingsspørsmål. For eksempel: «Du mener altså at dette er viktig. Hva får deg til å tenke det?»', array['Viser at svaret tar utgangspunkt i det medeleven nettopp sa.', 'Stiller et åpent spørsmål som kan føre samtalen videre.']::text[], 1),
  ('norsk-vg3:muntlig-fordypning', 's03', 'Forklar hvorfor det er nyttig å avgrense et emne og formulere en problemstilling før du lager en muntlig presentasjon.', 'En avgrensning gjør emnet mer håndterlig, slik at du kan gå grundig inn i det. Problemstillingen gir presentasjonen en tydelig retning og viser hva den skal svare på.', array['Forklarer at avgrensning snevrer inn et bredt emne til noe håndterlig.', 'Forklarer at problemstillingen styrer hva presentasjonen skal undersøke eller svare på.']::text[], 2),
  ('norsk-vg3:muntlig-fordypning', 's04', 'Du skal fordype deg i hvordan kvinners frihet framstilles i «Et dukkehjem» og «Amtmandens Døttre». Hvilke typer kilder bør du arbeide med, og hvordan kan de hjelpe deg med å utvikle hovedpoengene dine?', 'Jeg bør lese primærtekstene grundig og også bruke faglitteratur og kontekst. Eksempler og sitater fra tekstene kan støtte hovedpoengene, mens faglitteratur og kontekst kan gi et bredere grunnlag for fordypningen.', array['Nevner primærtekstene og faglitteratur eller kontekst som relevante kilder.', 'Knytter arbeidet med kildene til å utvikle eller støtte hovedpoeng, for eksempel med eksempler eller sitater.']::text[], 3),
  ('norsk-vg3:muntlig-fordypning', 's05', 'En presentasjon har flere viktige poeng i hoveddelen. Forklar hvordan du kan ordne dem og binde dem sammen slik at publikum lettere følger resonnementet.', 'Poengene bør komme i en logisk rekkefølge og støttes med eksempler og fagbegreper. Overganger kan vise hvordan ett poeng henger sammen med det neste.', array['Får fram at poengene bør ordnes logisk.', 'Forklarer hvordan eksempler, fagbegreper eller overganger bidrar til å utvikle eller binde sammen poengene.']::text[], 4),
  ('norsk-vg3:muntlig-fordypning', 's06', 'En elev snakker svært fort og ser mest ned på notatene sine under framføringen. Foreslå to endringer i stemmebruk eller kroppsspråk som kan gjøre framføringen tydeligere.', 'Eleven kan senke tempoet og bruke pauser, slik at publikum får bedre tid til å følge med. Eleven kan også løfte blikket for å få blikkontakt med publikum.', array['Foreslår minst én relevant endring i stemmebruk, som å variere tempo eller bruke pauser.', 'Foreslår minst én relevant endring i kroppsspråk, som blikkontakt eller en stødig holdning.']::text[], 5),
  ('norsk-vg3:muntlig-fordypning', 's07', 'Du har fått en tidsramme for en presentasjon. Forklar hvordan øving på forhånd kan hjelpe deg med å holde deg innenfor den.', 'Når jeg øver på forhånd, kan jeg undersøke om innholdet passer innenfor tidsrammen. Da kan jeg justere framføringen før jeg skal presentere.', array['Knytter øving til å kontrollere om presentasjonen passer innenfor tidsrammen.', 'Får fram at øving gjør det mulig å justere framføringen på forhånd.']::text[], 6),
  ('norsk-vg3:muntlig-fordypning', 's08', 'Forklar hvilken funksjon avslutningen har i en muntlig presentasjon, og hvordan den bør knyttes til problemstillingen.', 'Avslutningen bør oppsummere de viktigste poengene og gi et svar eller en refleksjon. Den bør vise hvordan poengene samlet sett svarer på problemstillingen.', array['Nevner at avslutningen oppsummerer hovedpoeng og gir et svar eller en refleksjon.', 'Knytter avslutningen tydelig til problemstillingen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('norsk-vg3:talesprak-i-endring', 'norsk-vg3', 'talesprak-i-endring', 'Talespråk i endring', 'Hvordan talespråket i Norge endrer seg i dag – dialektutjevning og regionalisering, sosiolekter, multietnolektisk ungdomsspråk, påvirkning fra engelsk og nye medier – og sammenhengen mellom språk, kultur og identitet.', array[10]::int[], 11, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('norsk-vg3:talesprak-i-endring', '## Talespråket i Norge
