  ('historie-vg3:historisk-metode-og-framstillinger', 'Muntlige kilder', 'Intervjuer og fortellinger fra øyenvitner.', 13),
  ('historie-vg3:historisk-metode-og-framstillinger', 'Alternativ forklaring', 'En annen mulig tolkning av kildene.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('historie-vg3:historisk-metode-og-framstillinger', 'q01', 'flervalg', 'Hvilken problemstilling er best?', array['Hva er utvandring?', 'Hvorfor utvandret så mange fra Vestlandet på 1880-tallet?', 'Utvandring', 'Når var 1880?']::text[], 1, 'Åpen og avgrenset.', true, true, 0),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q02', 'flervalg', 'Hva er en primærkilde?', array['En kilde fra den tiden som undersøkes', 'En moderne historiebok', 'En dokumentar', 'Et leksikon']::text[], 0, 'For eksempel et brev.', true, true, 1),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q03', 'flervalg', 'Hva betyr det å bruke en kilde som levning?', array['Å se hva den forteller om en hendelse', 'Å kaste den', 'Å se hva den avslører om tiden og menneskene som laget den', 'Å bare lese tittelen']::text[], 2, 'En propagandaplakat er en god levning.', true, true, 2),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q04', 'flervalg', 'Hva er tendens i en kilde?', array['At den er gammel', 'At den er kort', 'At den er muntlig', 'At den har interesse i å framstille noe på en bestemt måte']::text[], 3, 'Viktig i kildekritikken.', true, true, 3),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q05', 'flervalg', 'Hvordan ble 1814 framstilt i 1800-tallets nasjonale historieskrivning?', array['Som en heroisk gjenfødelse av Norge', 'Som en katastrofe', 'Som uviktig', 'Som en svensk seier']::text[], 0, 'Senere historikere har nyansert bildet.', true, true, 4),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q06', 'flervalg', 'Hva ble 1492 lenge omtalt som i europeiske framstillinger?', array['Erobringen', 'Oppdagelsen av Amerika', 'Starten på undertrykkelse', 'En handelsreise']::text[], 1, 'Urfolkenes perspektiv er annerledes.', true, true, 5),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q07', 'flervalg', 'Hva preger en historisk framstilling?', array['Bare kildene', 'Ingenting', 'Opphavspersonens ståsted og kontekst', 'Bare lengden']::text[], 2, 'Også formålet.', true, true, 6),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q08', 'flervalg', 'Betyr ulike framstillinger at alt er like sant?', array['Ja, alt er like sant', 'Ja, historie er bare meninger', 'Nei, historie kan ikke vites', 'Nei, noen bygger på bedre kilder og argumenter']::text[], 3, 'Kvaliteten på begrunnelsen varierer.', true, true, 7),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q09', 'flervalg', 'Hvordan bør du formulere en usikker slutning?', array['«Kildene tyder på at …»', '«Det er helt sikkert at …»', '«Alle vet at …»', '«Det er umulig at …»']::text[], 0, 'Vær ærlig om usikkerhet.', true, false, 8),
  ('historie-vg3:historisk-metode-og-framstillinger', 'q10', 'flervalg', 'Hva ble jøder utsatt for i Grunnloven av 1814?', array['De fikk stemmerett', 'De ble utestengt fra riket', 'De ble statsråder', 'De fikk egne skoler']::text[], 1, 'Paragraf 2.', true, false, 9),
  ('historie-vg3:historisk-metode-og-framstillinger', 'm01', 'sant-usant', 'Gjenstander kan være historiske kilder.', array['Sant', 'Usant']::text[], 0, 'Materielle kilder.', false, true, 10),
  ('historie-vg3:historisk-metode-og-framstillinger', 'm02', 'sant-usant', 'En god problemstilling spør bare «hva».', array['Sant', 'Usant']::text[], 1, 'Hvorfor, hvordan og i hvilken grad gir mer.', false, true, 11),
  ('historie-vg3:historisk-metode-og-framstillinger', 'm03', 'sant-usant', 'To framstillinger kan være enige om fakta, men vektlegge ulikt.', array['Sant', 'Usant']::text[], 0, 'Derfor må de sammenlignes.', false, true, 12),
  ('historie-vg3:historisk-metode-og-framstillinger', 'm04', 'sant-usant', 'Sekundærkilder er alltid mindre verdifulle enn primærkilder.', array['Sant', 'Usant']::text[], 1, 'Gode framstillinger samler og tolker mange kilder.', false, true, 13),
  ('historie-vg3:historisk-metode-og-framstillinger', 'm05', 'flervalg', 'Hva spør du om når du vurderer nærhet i en kilde?', array['Hvor lang kilden er', 'Om opphavspersonen var til stede', 'Hvilken farge papiret har', 'Hvem som eier kilden i dag']::text[], 1, 'Førstehånds eller andrehånds.', false, true, 14),
  ('historie-vg3:historisk-metode-og-framstillinger', 'm06', 'flervalg', 'Hva er en sekundærkilde?', array['En historiebok skrevet senere', 'Et brev fra 1880', 'En dagbok fra krigen', 'En lov fra 1814']::text[], 0, 'En framstilling.', false, true, 15),
  ('historie-vg3:historisk-metode-og-framstillinger', 'm07', 'flervalg', 'Hvorfor kan to historikere framstille samme hendelse ulikt?', array['Fordi den ene lyver alltid', 'Fordi fortiden endrer seg', 'Fordi de har ulikt ståsted, ulike kilder og ulik kontekst', 'Fordi de har lest samme bok']::text[], 2, 'Framstillinger preges av mange faktorer.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-vg3:historisk-metode-og-framstillinger', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-vg3:historisk-metode-og-framstillinger', 's01', 'En undersøkelse skal handle om hvorfor mange utvandret fra Vestlandet på 1880-tallet. Lag en problemstilling som både er åpen og avgrenset, og forklar kort hvordan den oppfyller begge krav.', '«Hvorfor utvandret mange fra Vestlandet på 1880-tallet?» er en åpen og avgrenset problemstilling. Den spør etter en forklaring og avgrenser undersøkelsen til et sted, en gruppe og en tidsperiode.', array['Problemstillingen spør åpent etter en forklaring, for eksempel med «hvorfor» eller «hvordan».', 'Den avgrenser undersøkelsen til Vestlandet, utvandring og 1880-tallet.']::text[], 0),
  ('historie-vg3:historisk-metode-og-framstillinger', 's02', 'En historiker bruker et gammelt verktøy fra tiden som undersøkes, og et intervju med et øyenvitne. Forklar hvilken form for kilde hvert av dem er.', 'Verktøyet er en materiell kilde, mens intervjuet er en muntlig kilde. Verktøyet er en gjenstand, og intervjuet er en fortelling fra et øyenvitne.', array['Identifiserer verktøyet som en materiell kilde.', 'Identifiserer intervjuet med øyenvitnet som en muntlig kilde.']::text[], 1),
  ('historie-vg3:historisk-metode-og-framstillinger', 's03', 'En historiker vil bruke en avisartikkel som kilde til en hendelse. Nevn viktige spørsmål historikeren bør undersøke om artikkelens opphav og formål, og forklar hvorfor det er nyttig å sammenligne den med andre kilder.', 'Historikeren bør undersøke hvem som laget artikkelen, når og hvor den ble laget, og hvorfor og for hvem den ble skrevet. Sammenligning med andre kilder kan vise om opplysningene samsvarer eller bør vurderes med større usikkerhet.', array['Tar opp hvem som laget artikkelen og når eller hvor den ble laget.', 'Tar opp formålet eller målgruppen og forklarer at sammenligning kan prøve om opplysningene samsvarer med andre kilder.']::text[], 2),
  ('historie-vg3:historisk-metode-og-framstillinger', 's04', 'En historiker finner en propagandaplakat fra et regime. Forklar hvorfor plakaten kan være en dårlig kilde til hvordan virkeligheten faktisk var, men en god kilde til regimets tenkemåte.', 'Som beretning kan plakaten være svak fordi propaganda kan framstille virkeligheten på en bestemt måte. Som levning kan den være nyttig fordi den viser hvordan regimet ønsket å tenke eller framstille saker.', array['Forklarer at plakaten som beretning ikke nødvendigvis gir et pålitelig bilde av virkeligheten.', 'Forklarer at plakaten som levning kan vise regimets tenkemåte eller hvordan det ønsket å framstille noe.']::text[], 3),
  ('historie-vg3:historisk-metode-og-framstillinger', 's05', 'En historiker finner én kilde som støtter en bestemt forklaring på en hendelse. Forklar hvorfor historikeren bør ta forbehold når hen trekker en slutning, og hvilken rolle en alternativ forklaring kan ha.', 'Én kilde gir ikke nødvendigvis et sikkert grunnlag, så historikeren bør uttrykke usikkerhet og begrunne slutningen i kildene. En alternativ forklaring kan vise at de samme opplysningene også kan tolkes på en annen måte.', array['Knytter forbehold til usikkerhet eller til at slutningen må begrunnes i kildene.', 'Forklarer at en alternativ forklaring er en annen mulig tolkning av kildene.']::text[], 4),
  ('historie-vg3:historisk-metode-og-framstillinger', 's06', 'En framstilling fra 1800-tallet beskrev 1814 som en heroisk gjenfødelse av Norge. Senere framstillinger har lagt mer vekt på stormaktspolitikk og tilfeldigheter, og nyere framstillinger har også løftet fram at jøder var utestengt og at mange ikke hadde stemmerett. Forklar hvordan endringer i spørsmålene historikere stiller, eller i perspektivene de bruker, kan føre til slike ulike vektlegginger.', 'Framstillinger påvirkes av hvilke spørsmål som er viktige i tiden de blir laget, og av opphavspersonenes ståsted og kildene de bruker. Når historikere undersøker andre sider ved 1814, kan de derfor legge mindre vekt på den heroiske fortellingen og mer vekt på stormaktspolitikk, tilfeldigheter og hvem som ble utestengt fra rettigheter.', array['Knytter forskjeller i framstilling til endrede spørsmål, ståsteder eller tilgjengelige kilder.', 'Bruker forskjellene i eksempelet til å vise hvordan vektleggingen av 1814 har endret seg.']::text[], 5),
  ('historie-vg3:historisk-metode-og-framstillinger', 's07', 'I europeiske framstillinger ble 1492 lenge omtalt som «oppdagelsen» av Amerika. Fra urfolkenes perspektiv var det starten på erobring, sykdom og undertrykkelse. Sammenlign perspektivene og forklar hvorfor samme hendelse kan få ulik betydning i ulike framstillinger.', 'Det europeiske perspektivet framhever 1492 som en oppdagelse, mens urfolkenes perspektiv framhever erobring, sykdom og undertrykkelse. Ulikt ståsted og ulike erfaringer gjør at framstillingene gir hendelsen forskjellig betydning.', array['Sammenligner hva det europeiske perspektivet og urfolkenes perspektiv vektlegger.', 'Forklarer forskjellen med ståsted eller ulike erfaringer.']::text[], 6),
  ('historie-vg3:historisk-metode-og-framstillinger', 's08', 'En dokumentar blir laget lenge etter en hendelse av noen som har studert kildene. Dokumentaren bruker dagbøker skrevet på den tiden hendelsen skjedde. Forklar hvorfor dokumentaren er en sekundærkilde, mens dagbøkene er primærkilder.', 'Dokumentaren er en sekundærkilde fordi den er laget senere av noen som har studert kildene. Dagbøkene er primærkilder fordi de er fra tiden som undersøkes.', array['Forklarer at dokumentaren er laget senere og bygger på studier av kilder.', 'Forklarer at dagbøkene er primærkilder fordi de stammer fra tiden som undersøkes.']::text[], 7);
