  ('historie-vg3:personer-og-handlingsrom', 'q06', 'flervalg', 'Hva er kollaborasjon?', array['Motstand', 'Samarbeid med okkupanten', 'Flukt', 'Nøytralitet']::text[], 1, 'For eksempel medlemskap i NS.', true, true, 5),
  ('historie-vg3:personer-og-handlingsrom', 'q07', 'flervalg', 'Hvorfor bør vi unngå å være etterpåkloke når vi vurderer valg?', array['Fordi valg ikke har konsekvenser', 'Fordi alle valgte riktig', 'Fordi personene ikke visste hvordan det ville gå', 'Fordi historien er ferdig']::text[], 2, 'Handlingene må forstås i samtiden.', true, true, 6),
  ('historie-vg3:personer-og-handlingsrom', 'q08', 'flervalg', 'Hva er kontrafaktisk tenkning?', array['Å sjekke fakta', 'Å lese kilder', 'Å skrive biografier', 'Å spørre «hva om?»']::text[], 3, 'Viser betydningen av valg og tilfeldigheter.', true, true, 7),
  ('historie-vg3:personer-og-handlingsrom', 'q09', 'flervalg', 'Hvilke grupper hadde ofte minst handlingsrom?', array['Kvinner, fattige og minoriteter', 'Rike menn med makt', 'Konger', 'Statsråder']::text[], 0, 'Strukturer begrenset valgene.', true, false, 8),
  ('historie-vg3:personer-og-handlingsrom', 'q10', 'flervalg', 'Hva er en gråsone under okkupasjonen?', array['Et område med tåke', 'En situasjon der det er uklart hva som er rett og galt', 'En militær sone', 'Et fengsel']::text[], 1, 'For eksempel å jobbe for tyskerne for å forsørge familien.', true, false, 9),
  ('historie-vg3:personer-og-handlingsrom', 'm01', 'sant-usant', 'De fleste nordmenn tilpasset seg og prøvde å klare seg under okkupasjonen.', array['Sant', 'Usant']::text[], 0, 'Motstand og kollaborasjon var mindretall.', false, true, 10),
  ('historie-vg3:personer-og-handlingsrom', 'm02', 'sant-usant', 'Strukturer spiller ingen rolle for enkeltmenneskers valg.', array['Sant', 'Usant']::text[], 1, 'De begrenser og muliggjør handling.', false, true, 11),
  ('historie-vg3:personer-og-handlingsrom', 'm03', 'sant-usant', 'En persons ettermæle kan endre seg over tid.', array['Sant', 'Usant']::text[], 0, 'Nye tider stiller nye spørsmål.', false, true, 12),
  ('historie-vg3:personer-og-handlingsrom', 'm04', 'sant-usant', 'Kontrafaktiske spørsmål kan besvares med full sikkerhet.', array['Sant', 'Usant']::text[], 1, 'De kan ikke besvares sikkert.', false, true, 13),
  ('historie-vg3:personer-og-handlingsrom', 'm05', 'flervalg', 'Hva var Nasjonal Samling?', array['En motstandsgruppe', 'Et norsk nazistparti', 'En fagforening', 'Et samisk parti']::text[], 1, 'Ledet av Vidkun Quisling.', false, true, 14),
  ('historie-vg3:personer-og-handlingsrom', 'm06', 'flervalg', 'Hva er et eksempel på motstand under okkupasjonen?', array['Illegale aviser', 'Medlemskap i NS', 'Å jobbe for okkupantene', 'Å angi naboer']::text[], 0, 'Også sabotasje og flyktninghjelp.', false, true, 15),
  ('historie-vg3:personer-og-handlingsrom', 'm07', 'flervalg', 'Hvor lenge satt Mandela i fengsel?', array['2 år', '10 år', '27 år', '50 år']::text[], 2, 'Han ble løslatt i 1990.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-vg3:personer-og-handlingsrom', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-vg3:personer-og-handlingsrom', 's01', 'Under okkupasjonen av Norge kunne folk gjøre motstand, tilpasse seg eller samarbeide med okkupantene. Forklar forskjellen på en aktør og en struktur ved å bruke denne situasjonen som eksempel.', 'Menneskene som valgte hvordan de skulle handle, var aktører. Okkupasjonen og det politiske systemet var strukturer som kunne begrense eller påvirke valgene deres.', array['Forklarer at aktører er personer eller grupper som handler og tar valg.', 'Forklarer at strukturer påvirker valgene ved å begrense eller muliggjøre handling.']::text[], 0),
  ('historie-vg3:personer-og-handlingsrom', 's02', 'Elsa Laula Renberg var en sørsamisk kvinne tidlig på 1900-tallet. Fornorskingspolitikken og tidens kjønnsroller begrenset handlingsrommet hennes, men hun tok initiativ til det første samiske landsmøtet i Trondheim i 1917. Forklar hvordan både begrensninger og egne handlinger preget handlingsrommet hennes.', 'Fornorskingspolitikken og kjønnsrollene begrenset hvilke muligheter Elsa Laula Renberg hadde. Likevel handlet hun ved å organisere samer og ta initiativ til landsmøtet i 1917, og utfordret dermed begrensningene.', array['Knytter begrensningene til fornorskingspolitikken og/eller kjønnsrollene.', 'Forklarer hvordan hun selv handlet og utfordret begrensningene.']::text[], 1),
  ('historie-vg3:personer-og-handlingsrom', 's03', 'Under okkupasjonen av Norge kunne folk gjøre motstand eller tilpasse seg. Forklar forskjellen mellom disse valgene, og gi ett eksempel på hver.', 'Motstand var aktiv eller passiv kamp mot okkupanten, for eksempel å nekte å melde seg inn i nazistenes lærersamband. Tilpasning var å leve videre og prøve å klare seg i hverdagen.', array['Skiller mellom kamp mot okkupanten og det å forsøke å klare seg i hverdagen.', 'Gir et passende eksempel på både motstand og tilpasning.']::text[], 2),
  ('historie-vg3:personer-og-handlingsrom', 's04', 'En person arbeider på et anlegg for tyskerne under okkupasjonen fordi familien trenger inntekten. Forklar hvorfor situasjonen kan regnes som en gråsone, og hva den viser om personens handlingsrom.', 'Situasjonen er en gråsone fordi arbeidet kan framstå som samarbeid med okkupanten, samtidig som personen prøver å forsørge familien. Det viser at valgene kunne være begrenset av livssituasjonen.', array['Forklarer konflikten mellom å arbeide for okkupanten og å forsørge familien.', 'Knytter situasjonen til uklare grenser mellom rett og galt eller til begrenset handlingsrom.']::text[], 3),
  ('historie-vg3:personer-og-handlingsrom', 's05', 'Under en okkupasjon nekter en person bevisst å følge en regel for å protestere, og gjør det uten vold. Forklar hva slags handling dette er, og hvorfor den regnes som motstand.', 'Dette er sivil ulydighet: Personen bryter bevisst en regel i protest, uten å bruke vold. Det regnes som motstand fordi handlingen er rettet mot okkupantens makt eller politikk.', array['Identifiserer handlingen som sivil ulydighet og forklarer at regelbruddet er bevisst og skjer i protest uten vold.', 'Forklarer at handlingen er motstand mot okkupanten.']::text[], 4),
  ('historie-vg3:personer-og-handlingsrom', 's06', 'Sammenlign Elsa Laula Renberg og Nelson Mandela ut fra hvilke begrensninger de møtte, og hva de gjorde for å påvirke samfunnet.', 'Elsa Laula Renberg ble begrenset av fornorskingspolitikken og kjønnsrollene, men organiserte samer og tok initiativ til et landsmøte. Mandela kjempet mot apartheid og satt i fengsel i 27 år før han ble Sør-Afrikas første demokratisk valgte president i 1994.', array['Beskriver en relevant begrensning eller motstand for hver av personene.', 'Sammenligner hvordan de handlet for å påvirke samfunnet.']::text[], 5),
  ('historie-vg3:personer-og-handlingsrom', 's07', 'En person samarbeider med okkupanten fordi hen er redd for konsekvensene av å si nei. Hvilke forhold bør en historiker undersøke før personen vurderes, og hvorfor?', 'Historikeren bør undersøke om personen hadde et reelt valg, hvilke verdier eller hvilken frykt som påvirket valget, og hvilke konsekvenser det fikk for andre. Da kan valget vurderes ut fra situasjonen personen faktisk sto i, ikke med etterpåklokskap.', array['Tar opp personens reelle valgmuligheter og/eller hva som påvirket valget.', 'Vurderer konsekvensene for andre og knytter vurderingen til å unngå etterpåklokskap.']::text[], 6),
  ('historie-vg3:personer-og-handlingsrom', 's08', 'En historisk person kan bli framstilt på ulike måter lenge etter at personen levde. Forklar hva ettermæle betyr, og hvorfor det er en annen historisk undersøkelse enn å finne ut hvilke valg personen tok.', 'Ettermæle handler om hvordan en person blir husket og framstilt senere, og hvorfor framstillingen har blitt slik. Det skiller seg fra å undersøke personens valg mens hen levde, fordi det handler om senere tiders syn på personen.', array['Forklarer at ettermæle gjelder hvordan personen huskes eller framstilles senere.', 'Skiller dette fra personens egne valg og handlinger mens hen levde.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-vg3:brudd-og-kontinuitet', 'historie-vg3', 'brudd-og-kontinuitet', 'Brudd, kontinuitet og historisk betydning', 'Hvordan historikere deler inn fortiden i perioder, hva brudd og kontinuitet er, hvordan du drøfter i hvilken grad en periode var preget av endring eller videreføring – og hvilke kriterier som gjør en hendelse historisk betydningsfull.', array[6]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('historie-vg3:brudd-og-kontinuitet', '## Brudd og kontinuitet
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
