insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('historie-vg3:teknologiske-omveltninger', 'q01', 'flervalg', 'Hvor startet den industrielle revolusjonen?', array['I Norge', 'I Storbritannia', 'I USA', 'I Kina']::text[], 1, 'På 1700-tallet.', true, true, 0),
  ('historie-vg3:teknologiske-omveltninger', 'q02', 'flervalg', 'Hvilken bransje var først ute med fabrikker?', array['Tekstilindustrien', 'Bilindustrien', 'Dataindustrien', 'Oljeindustrien']::text[], 0, 'Dampdrevne vevstoler.', true, true, 1),
  ('historie-vg3:teknologiske-omveltninger', 'q03', 'flervalg', 'Hva ga grunnlag for kraftkrevende industri i Norge?', array['Kull', 'Olje', 'Vannkraft', 'Atomkraft']::text[], 2, 'For eksempel Norsk Hydro.', true, true, 2),
  ('historie-vg3:teknologiske-omveltninger', 'q04', 'flervalg', 'Hva gjorde samlebåndet mulig?', array['Håndverk', 'Hjemmeproduksjon', 'Barnearbeid', 'Masseproduksjon']::text[], 3, 'Kjent fra Fords bilfabrikk.', true, true, 3),
  ('historie-vg3:teknologiske-omveltninger', 'q05', 'flervalg', 'Hvem var maskinstormerne?', array['Arbeidere som ødela maskiner som tok jobbene deres', 'Oppfinnere', 'Fabrikkeiere', 'Politikere']::text[], 0, 'Uttrykk for frykt for arbeidsløshet.', true, true, 4),
  ('historie-vg3:teknologiske-omveltninger', 'q06', 'flervalg', 'Hvordan bidro husholdningsmaskiner til endring?', array['De økte husarbeidet', 'De gjorde at flere kvinner kunne ta lønnsarbeid', 'De skapte arbeidsløshet i fabrikkene', 'De forbød kvinner å jobbe']::text[], 1, 'Lettere husarbeid.', true, true, 5),
  ('historie-vg3:teknologiske-omveltninger', 'q07', 'flervalg', 'Hva viste atombomben i 1945?', array['At krig var over for alltid', 'At teknologi alltid er positiv', 'At teknologi også kunne utslette menneskeheten', 'At fremskritt er umulig']::text[], 2, 'Endret forventningene til framtiden.', true, true, 6),
  ('historie-vg3:teknologiske-omveltninger', 'q08', 'flervalg', 'Hva er en utfordring ved den digitale revolusjonen?', array['For lite informasjon', 'For langsom kommunikasjon', 'Færre nyheter', 'Personvern og desinformasjon']::text[], 3, 'Også overvåking og skjermtid.', true, true, 7),
  ('historie-vg3:teknologiske-omveltninger', 'q09', 'flervalg', 'Hvilken langsiktig følge har industrialiseringen for miljøet?', array['Klimaendringer', 'Mindre forurensning', 'Flere skoger', 'Kaldere klima']::text[], 0, 'Økt bruk av kull, olje og gass.', true, false, 8),
  ('historie-vg3:teknologiske-omveltninger', 'q10', 'flervalg', 'Hvilken oppfinnelse fikk James Watt æren for å forbedre?', array['Telefonen', 'Dampmaskinen', 'Datamaskinen', 'Bilen']::text[], 1, 'Viktig for den industrielle revolusjonen.', true, false, 9),
  ('historie-vg3:teknologiske-omveltninger', 'm01', 'sant-usant', 'I Norge kom industrialiseringen senere enn i Storbritannia.', array['Sant', 'Usant']::text[], 0, 'Fra midten av 1800-tallet.', false, true, 10),
  ('historie-vg3:teknologiske-omveltninger', 'm02', 'sant-usant', 'Teknologiske omveltninger har bare skapt optimisme.', array['Sant', 'Usant']::text[], 1, 'De har også skapt frykt.', false, true, 11),
  ('historie-vg3:teknologiske-omveltninger', 'm03', 'sant-usant', 'Klokka og fabrikkfløyta fikk større betydning i industrisamfunnet.', array['Sant', 'Usant']::text[], 0, 'Tid ble viktigere.', false, true, 12),
  ('historie-vg3:teknologiske-omveltninger', 'm04', 'sant-usant', 'Den digitale revolusjonen har ikke endret arbeidslivet.', array['Sant', 'Usant']::text[], 1, 'Nesten alle yrker er endret.', false, true, 13),
  ('historie-vg3:teknologiske-omveltninger', 'm05', 'flervalg', 'Når ble Norsk Hydro grunnlagt?', array['1814', '1905', '1945', '1969']::text[], 1, 'Samme år som unionsoppløsningen.', false, true, 14),
  ('historie-vg3:teknologiske-omveltninger', 'm06', 'flervalg', 'Hva kjennetegnet arbeidsforholdene i tidlig industri?', array['Lange arbeidsdager og barnearbeid', 'Korte dager og høy lønn', 'Hjemmekontor', 'Fire dagers arbeidsuke']::text[], 0, 'Arbeiderbevegelsen kjempet for bedre kår.', false, true, 15),
  ('historie-vg3:teknologiske-omveltninger', 'm07', 'flervalg', 'Hvilket spørsmål bør du stille når du vurderer en teknologisk omveltning?', array['Hvor stor maskinen var', 'Hvem som oppfant den alene', 'Hvem som tjente og tapte på endringene', 'Hvilken farge den hadde']::text[], 2, 'Teknologi former samfunnet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-vg3:teknologiske-omveltninger', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-vg3:teknologiske-omveltninger', 's01', 'Under den industrielle revolusjonen flyttet mange fra landsbygda til byer der fabrikkene lå. Forklar begrepet urbanisering, og forklar sammenhengen mellom fabrikkene og flyttingen til byene.', 'Urbanisering betyr at folk flytter fra landet til byene. Da fabrikkene samlet arbeidsplasser i byene, flyttet mange dit for å få arbeid.', array['Forklarer at urbanisering er flytting fra landet til byene.', 'Knytter flyttingen til at fabrikkene samlet arbeidsplasser i byene.']::text[], 0),
  ('historie-vg3:teknologiske-omveltninger', 's02', 'Sammenlign den industrielle revolusjonen med den andre industrielle revolusjonen. Hva kjennetegnet maskinbruken i den første, og hvilke nye teknologier kjennetegnet den andre?', 'Den industrielle revolusjonen bygde på maskiner drevet av dampmaskinen, og produksjonen flyttet til fabrikker. Den andre industrielle revolusjonen var kjennetegnet av blant annet elektrisitet, forbrenningsmotoren og kjemisk industri.', array['Knytter den industrielle revolusjonen til dampmaskiner og fabrikkproduksjon.', 'Nevner sentrale teknologier fra den andre industrielle revolusjonen, som elektrisitet, forbrenningsmotor eller kjemisk industri.']::text[], 1),
  ('historie-vg3:teknologiske-omveltninger', 's03', 'Før industrialiseringen foregikk mye produksjon i hjemmet og på gården. Forklar hvordan produksjonen ble endret da fabrikkene tok over, og hvordan dette påvirket arbeidernes hverdag.', 'Produksjonen ble flyttet fra hjem og gårder til fabrikker, der maskiner ble brukt. Arbeidsdagen ble styrt mer av klokka og fabrikkfløyta, og mange arbeidere hadde lange arbeidsdager.', array['Forklarer at produksjonen flyttet fra hjem og gårder til fabrikker med maskiner.', 'Beskriver en relevant endring i arbeidernes hverdag, for eksempel lange arbeidsdager eller at klokka styrte arbeidsdagen.']::text[], 2),
  ('historie-vg3:teknologiske-omveltninger', 's04', 'I Norge ga vannkraft grunnlag for kraftkrevende industri. Norsk Hydro ble grunnlagt i 1905. Forklar hvordan vannkraft kunne bidra til at slik industri vokste fram, og bruk Norsk Hydro som eksempel.', 'Vannkraft ga energi til kraftkrevende industri og gjorde det mulig for slik industri å vokse i Norge. Norsk Hydro, grunnlagt i 1905, er et eksempel på en industribedrift som bygde på vannkraft.', array['Forklarer at vannkraft ga energi som kraftkrevende industri trengte.', 'Bruker Norsk Hydro som et relevant eksempel og får fram at selskapet ble grunnlagt i 1905.']::text[], 3),
  ('historie-vg3:teknologiske-omveltninger', 's05', 'På en arbeidsplass blir et dataprogram satt til å utføre oppgaver som ansatte tidligere gjorde. Forklar begrepet automatisering, og beskriv én mulig følge av automatisering for arbeidslivet.', 'Automatisering betyr at maskiner eller programmer overtar arbeid mennesker tidligere gjorde. Noen jobber kan forsvinne, samtidig som det kan oppstå nye jobber.', array['Forklarer at automatisering innebærer at maskiner eller programmer overtar menneskers arbeidsoppgaver.', 'Beskriver en relevant følge for arbeidslivet, som at jobber forsvinner eller nye jobber oppstår.']::text[], 4),
  ('historie-vg3:teknologiske-omveltninger', 's06', 'På 1800-tallet viste verdensutstillingene stolt fram nye oppfinnelser. Samtidig ødela enkelte arbeidere i England maskiner de mente tok jobbene deres. Forklar hva dette viser om ulike forventninger til teknologiske endringer.', 'Verdensutstillingene uttrykte tro på at teknologi ville føre til fremskritt og et bedre liv. Arbeiderne som ødela maskiner, viste frykt for at teknologien skulle ta fra dem arbeidet.', array['Knytter verdensutstillingene til optimisme eller tro på teknologisk fremskritt.', 'Knytter ødeleggelsen av maskiner til frykt for tap av arbeid.']::text[], 5),
  ('historie-vg3:teknologiske-omveltninger', 's07', 'Industrialiseringen ga økt velstand, men førte også til større bruk av kull, olje og gass. Forklar hvordan dette kunne gi både fordeler for mennesker og langsiktige problemer for natur og miljø.', 'Bruken av teknologi og fossile energikilder bidro til økt velstand. Samtidig førte økt bruk av kull, olje og gass til forurensning og klimaendringer, og fornybar energi kan være en del av løsningen.', array['Forklarer en fordel ved industrialiseringen, som økt velstand.', 'Knytter bruk av kull, olje eller gass til forurensning eller klimaendringer.']::text[], 6),
  ('historie-vg3:teknologiske-omveltninger', 's08', 'En konto på nettet finner på falske nyheter med vilje og sprer dem videre. Forklar hvorfor dette er desinformasjon, og hvordan slik spredning kan påvirke nyheter eller debatter.', 'Dette er desinformasjon fordi informasjonen er falsk og spres bevisst. Når slike påstander spres raskt gjennom digitale medier, kan de påvirke hva folk tror på og hvordan de deltar i debatter.', array['Forklarer at desinformasjon er falsk informasjon som spres med vilje.', 'Beskriver en mulig virkning på nyheter, hva folk tror på eller samfunnsdebatt.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-vg3:migrasjon-og-kulturmoter', 'historie-vg3', 'migrasjon-og-kulturmoter', 'Migrasjon og kulturmøter', 'Årsaker til at mennesker har migrert – push- og pull-faktorer, emigrasjonen fra Norge til Amerika, arbeidsinnvandring og flyktninger – og kulturmøtene sett fra perspektivene til dem som kom, og dem som tok imot.', array[9]::int[], 6, 'utkast', '{}'::text[], false, now())
