  ('historie-vg3:nasjonal-identitet', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-vg3:nasjonal-identitet', 's01', 'Forklar hva en nasjon er, og hvorfor en nasjon kan sies å være bygd framfor bare å være født.', 'En nasjon er et fellesskap der mennesker opplever tilhørighet gjennom blant annet historie, språk og kultur. Nasjoner bygges gjennom fortellinger, symboler og andre uttrykk som skaper en følelse av fellesskap.', array['Forklarer at nasjoner bygger på opplevd tilhørighet gjennom flere felles kjennetegn.', 'Forklarer at nasjonal tilhørighet blir skapt eller styrket, ikke bare oppstår av seg selv.']::text[], 0),
  ('historie-vg3:nasjonal-identitet', 's02', 'Etter 1814 hadde Norge fått egen grunnlov, men manglet en tydelig nasjonal identitet. Forklar hvorfor dette førte til at kunstnere og forskere lette etter det «ekte norske».', 'Grunnloven ga Norge en egen politisk ramme, men sa ikke alene hva som skulle gjøre landet til et eget nasjonalt fellesskap. Kunstnere og forskere lette derfor etter historie, språk og kultur som kunne uttrykke det norske.', array['Knytter letingen etter det norske til behovet for en tydelig nasjonal identitet etter 1814.', 'Forklarer at historie, språk eller kultur kunne brukes til å uttrykke norsk tilhørighet.']::text[], 1),
  ('historie-vg3:nasjonal-identitet', 's03', 'Sammenlign arbeidet til Asbjørnsen og Moe med arbeidet til Ivar Aasen. Hva samlet de inn, og hvordan bidro arbeidet deres til norsk kultur?', 'Asbjørnsen og Moe samlet folkeeventyr, mens Ivar Aasen samlet dialekter og laget landsmålet, dagens nynorsk. Begge bidro til å løfte fram kulturuttrykk som ble knyttet til Norge.', array['Skiller riktig mellom folkeeventyrene til Asbjørnsen og Moe og dialektarbeidet til Aasen.', 'Forklarer hvordan arbeidet deres bidro til å løfte fram norsk kultur eller identitet.']::text[], 2),
  ('historie-vg3:nasjonal-identitet', 's04', 'Forklar hvordan barnetog, flagg og taler på 17. mai kan skape fellesskap mellom mennesker.', 'Når mennesker deltar i de samme ritualene og bruker felles symboler, kan de oppleve at de hører sammen. 17. mai-feiringen gjør dette gjennom blant annet barnetog, flagg og taler.', array['Forklarer at felles ritualer eller symboler kan gi mennesker en opplevelse av tilhørighet.', 'Knytter forklaringen til minst ett element ved 17. mai-feiringen.']::text[], 3),
  ('historie-vg3:nasjonal-identitet', 's05', 'Et museum viser Tidemand og Gudes maleri «Brudeferden i Hardanger» som et bilde på Norge. Forklar hva slags Norge bildet formidler, og hvorfor det kan beskrives som idealisert.', 'Bildet framstiller bonden og naturen som sentrale uttrykk for det norske. Det er idealisert fordi det viser et ønsket eller opphøyd bilde av Norge, ikke nødvendigvis hele virkeligheten.', array['Knytter bildet til bonden og naturen som uttrykk for det norske.', 'Forklarer at idealiseringen innebærer at bildet framstiller et utvalgt eller opphøyd bilde av Norge.']::text[], 4),
  ('historie-vg3:nasjonal-identitet', 's06', 'Forklar hvordan ideen om «ett folk, ett språk og én kultur» kunne ramme samer. Ta med to konkrete følger av fornorskingspolitikken.', 'Ideen om ett språk og én kultur gjorde at samisk språk og kultur ble presset tilbake. Samisk språk ble fortrengt i skolen, og mange samiske barn ble sendt på internatskoler borte fra familien.', array['Knytter fornorskingspolitikken til press om å tilpasse seg norsk språk eller kultur.', 'Nevner to relevante følger for samer, for eksempel at samisk ble fortrengt i skolen og at barn ble sendt på internatskoler.']::text[], 5),
  ('historie-vg3:nasjonal-identitet', 's07', 'Sammenlign hvordan fornorskingspolitikken rammet samer med hvordan romanifolket ble utsatt for tvangsassimilering. Vis én forskjell mellom erfaringene deres.', 'Samer ble blant annet utsatt for at samisk språk ble fortrengt i skolen, og mange barn måtte bo på internatskoler. Romanifolket ble utsatt for tvangsassimilering, blant annet ved at barn ble tatt fra foreldrene og mange ble tvangssterilisert.', array['Beskriver en relevant følge av fornorskingspolitikken for samer.', 'Beskriver en relevant følge av tvangsassimileringen av romanifolket og viser en forskjell mellom gruppenes erfaringer.']::text[], 6),
  ('historie-vg3:nasjonal-identitet', 's08', 'Etter oljefunnene fra 1969 ble fortellingen om Norge som et rikt, likestilt og fredelig land viktig. Forklar hvordan denne fortellingen henger sammen med selvbildet som oljenasjon, fredsnasjon og velferdsstat.', 'Oljefunnene bidro til en fortelling om Norge som et rikt land, mens fredsnasjonen og velferdsstaten ble sentrale deler av selvbildet. Fortellingen knytter dermed velstand sammen med likestilling, fred og velferd.', array['Knytter oljefunnene til fortellingen om Norge som et rikt land.', 'Forklarer at fredsnasjonen og velferdsstaten er deler av Norges nasjonale selvbilde.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-vg3:myndiggjoring-og-frigjoring', 'historie-vg3', 'myndiggjoring-og-frigjoring', 'Myndiggjøring og frigjøring i norsk og samisk historie', 'Hvordan arbeidere, kvinner, samer, skeive og mennesker med funksjonsnedsettelser har kjempet for rettigheter og frigjøring i Norge – og hvordan kampene samtidig har utvidet og fordypet demokratiet.', array[15]::int[], 11, 'utkast', '{}'::text[], false, now())
