insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q01', 'flervalg', 'Hva krevde Thrane-bevegelsen?', array['Kongens makt', 'Allmenn stemmerett og bedre kår for arbeidere og husmenn', 'Samisk selvstyre', 'Union med Sverige']::text[], 1, 'Marcus Thrane ble fengslet.', true, true, 0),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q02', 'flervalg', 'Når ble parlamentarismen innført i Norge?', array['1884', '1814', '1905', '1913']::text[], 0, 'Regjeringen må ha Stortingets tillit.', true, true, 1),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q03', 'flervalg', 'Når fikk kvinner allmenn stemmerett ved stortingsvalg?', array['1898', '1884', '1913', '1978']::text[], 2, 'Menn fikk det i 1898.', true, true, 2),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q04', 'flervalg', 'Hva satte Alta-saken på dagsordenen?', array['Kvinners stemmerett', 'Arbeidstiden', 'Homofiles rettigheter', 'Samiske rettigheter']::text[], 3, 'Et vendepunkt, selv om kraftverket ble bygd.', true, true, 3),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q05', 'flervalg', 'Når ble Sametinget opprettet?', array['1989', '1917', '1968', '2005']::text[], 0, 'Samenes folkevalgte organ.', true, true, 4),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q06', 'flervalg', 'Hva skjedde i 1972?', array['Kvinner fikk stemmerett', 'Sex mellom menn ble avkriminalisert', 'Sametinget ble opprettet', 'LO ble stiftet']::text[], 1, 'Senere kom vern mot diskriminering og ekteskapslov.', true, true, 5),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q07', 'flervalg', 'Hvem tok initiativ til det første samiske landsmøtet i 1917?', array['Gina Krog', 'Marcus Thrane', 'Elsa Laula Renberg', 'Gro Harlem Brundtland']::text[], 2, '6. februar er samefolkets dag.', true, true, 6),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q08', 'flervalg', 'Hva gjorde ansvarsreformen tidlig på 1990-tallet?', array['Innførte stemmerett for kvinner', 'Opprettet Sametinget', 'Innførte 8-timersdagen', 'La ned institusjoner og ga kommunene ansvaret for utviklingshemmede']::text[], 3, 'Flere fikk bo i egne hjem.', true, true, 7),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q09', 'flervalg', 'Hvordan har frigjøringskampene bidratt til demokratiet?', array['Ved å gi flere stemmerett, innflytelse og vern mot diskriminering', 'Ved å fjerne valg', 'Ved å gi kongen mer makt', 'De har ikke bidratt']::text[], 0, 'Demokratiet er blitt bredere.', true, false, 8),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'q10', 'flervalg', 'Når kom den felles ekteskapsloven?', array['1993', '2009', '1981', '1972']::text[], 1, 'Gir likekjønnede par rett til å gifte seg.', true, false, 9),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'm01', 'sant-usant', 'Grunnloven fikk en egen sameparagraf i 1988.', array['Sant', 'Usant']::text[], 0, 'Staten skal legge forholdene til rette for samisk språk, kultur og samfunnsliv.', false, true, 10),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'm02', 'sant-usant', 'Thrane-bevegelsen fikk gjennomslag for allmenn stemmerett i 1851.', array['Sant', 'Usant']::text[], 1, 'Bevegelsen ble slått ned.', false, true, 11),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'm03', 'sant-usant', 'Loven om selvbestemt abort kom i 1978.', array['Sant', 'Usant']::text[], 0, 'Samme år som likestillingsloven.', false, true, 12),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'm04', 'sant-usant', 'Demokratiet er ferdig utviklet og endrer seg ikke.', array['Sant', 'Usant']::text[], 1, 'Det utvikles når nye grupper krever å bli hørt.', false, true, 13),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'm05', 'flervalg', 'Når ble Det norske Arbeiderparti stiftet?', array['1848', '1887', '1899', '1919']::text[], 1, 'LO kom i 1899.', false, true, 14),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'm06', 'flervalg', 'Hvilket land ratifiserte først ILO-konvensjonen om urfolks rettigheter?', array['Norge', 'Sverige', 'Finland', 'Danmark']::text[], 0, 'I 1990.', false, true, 15),
  ('historie-vg3:myndiggjoring-og-frigjoring', 'm07', 'flervalg', 'Hva kjennetegnet regjeringen Brundtland dannet i 1986?', array['Bare menn', 'Bare samer', 'Nesten halvparten var kvinner', 'Den hadde ingen statsråder']::text[], 2, 'Kalt «kvinneregjeringen».', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-vg3:myndiggjoring-og-frigjoring', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-vg3:myndiggjoring-og-frigjoring', 's01', 'Forklar med egne ord hva myndiggjøring betyr, og hvordan det skiller seg fra frigjøring.', 'Myndiggjøring betyr at mennesker får makt over eget liv og mulighet til å påvirke samfunnet. Frigjøring handler om å bli fri fra undertrykkelse og diskriminering.', array['Forklarer at myndiggjøring handler om makt over eget liv og innflytelse.', 'Forklarer at frigjøring handler om å bli fri fra undertrykkelse eller diskriminering.']::text[], 0),
  ('historie-vg3:myndiggjoring-og-frigjoring', 's02', 'Arbeiderpartiet ble stiftet i 1887 og LO i 1899. Forklar hvordan slike organisasjoner kunne hjelpe arbeidere med å få større innflytelse.', 'Når arbeidere organiserte seg i partier og organisasjoner, kunne de stå sammen om krav og få en tydeligere stemme i samfunnet. Organisering kunne dermed bidra til politisk innflytelse og bedre rettigheter.', array['Forklarer at organisering samler arbeidere om felles krav eller interesser.', 'Knytter organisering til større innflytelse eller en sterkere stemme i samfunnet.']::text[], 1),
  ('historie-vg3:myndiggjoring-og-frigjoring', 's03', 'Parlamentarismen ble innført i Norge i 1884. Forklar hvordan regelen om at regjeringen må ha Stortingets tillit påvirker forholdet mellom regjeringen og de folkevalgte.', 'Regjeringen er avhengig av at Stortinget har tillit til den. Det gir Stortinget innflytelse over regjeringen og knytter regjeringens makt til de folkevalgte.', array['Forklarer at regjeringen må ha støtte eller tillit fra Stortinget.', 'Viser at dette gir Stortinget innflytelse over regjeringen.']::text[], 2),
  ('historie-vg3:myndiggjoring-og-frigjoring', 's04', 'Allmenn stemmerett for menn kom i 1898, og kvinner fikk allmenn stemmerett ved stortingsvalg i 1913. Sammenlign hva disse endringene betydde for hvem som kunne delta i valg, og forklar hvordan de gjorde demokratiet bredere.', 'Først fikk menn allmenn stemmerett, og senere fikk også kvinner denne retten ved stortingsvalg. Dermed kunne flere grupper delta politisk gjennom valg, og demokratiet ble bredere.', array['Får fram at menn fikk allmenn stemmerett før kvinner.', 'Forklarer at kvinners stemmerett utvidet hvem som kunne delta i valg og dermed gjorde demokratiet bredere.']::text[], 3),
  ('historie-vg3:myndiggjoring-og-frigjoring', 's05', 'I Alta-saken protesterte samer mot utbyggingen av Alta-vassdraget, og kraftverket ble likevel bygd. Forklar hvorfor saken likevel ble et vendepunkt.', 'Protestene, blant annet sultestreiken utenfor Stortinget, satte samiske rettigheter på dagsordenen. Derfor ble saken et vendepunkt selv om kraftverket ble bygd.', array['Knytter protestene til at samiske rettigheter fikk større oppmerksomhet eller kom på dagsordenen.', 'Får fram at saken ble et vendepunkt selv om utbyggingen ble gjennomført.']::text[], 4),
  ('historie-vg3:myndiggjoring-og-frigjoring', 's06', 'Sametinget ble opprettet i 1989, og Norge ratifiserte ILO-konvensjonen om urfolks rettigheter i 1990. Forklar hvordan disse to tiltakene på ulike måter kunne styrke samenes rettigheter.', 'Sametinget ga samene et folkevalgt organ. ILO-konvensjonen var et internasjonalt vern for urfolks rettigheter som Norge sluttet seg til ved å ratifisere den.', array['Forklarer at Sametinget gir samene et folkevalgt organ eller en politisk stemme.', 'Forklarer at ratifiseringen innebar at Norge sluttet seg til en konvensjon om urfolks rettigheter.']::text[], 5),
  ('historie-vg3:myndiggjoring-og-frigjoring', 's07', 'Beskriv hvordan rettighetene til homofile ble utvidet fra 1972 til 1993. Ta med minst to ulike typer rettighetsendringer.', 'Sex mellom menn ble avkriminalisert i 1972, og homofile fikk vern mot diskriminering i 1981. Partnerskapsloven i 1993 ga likekjønnede par rett til registrert partnerskap.', array['Nevner at sex mellom menn ble avkriminalisert eller at homofile fikk vern mot diskriminering.', 'Nevner at partnerskapsloven ga likekjønnede par rett til registrert partnerskap.']::text[], 6),
  ('historie-vg3:myndiggjoring-og-frigjoring', 's08', 'En kommune planlegger et offentlig bygg med trapper ved inngangen og uten en alternativ inngang. Bruk begrepene universell utforming og like muligheter til å forklare hvorfor dette kan hindre personer med funksjonsnedsettelser i å delta på lik linje med andre.', 'Når inngangen bare har trapper, kan noen personer med funksjonsnedsettelser få problemer med å komme inn. Universell utforming handler om å utforme omgivelsene slik at flere kan bruke dem, og det støtter like muligheter til å delta.', array['Forklarer at manglende alternativ til trappene kan stenge noen ute eller begrense deltakelsen deres.', 'Knytter universell utforming til at flere skal kunne bruke bygget og delta på like vilkår.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-vg3:velferdsstaten', 'historie-vg3', 'velferdsstaten', 'Velferdsutviklingen i Norge på 1900-tallet', 'Hvordan den norske velferdsstaten vokste fram – fra fattigvesenet og de første trygdene via kriseforliket i 1935 til gjenreisningen, folketrygden i 1967 og utbyggingen av skole, helse og barnehager – og hvilke konsekvenser utviklingen har hatt for menneskers liv.', array[16]::int[], 12, 'utkast', '{}'::text[], false, now())
