insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('historie-vg3:velferdsstaten', 'q01', 'flervalg', 'Hva var det viktigste sikkerhetsnettet før velferdsstaten?', array['Folketrygden', 'Familien, arbeidsgiveren og fattigvesenet', 'NAV', 'Barnetrygden']::text[], 1, 'Hjelpen var ofte nedverdigende.', true, true, 0),
  ('historie-vg3:velferdsstaten', 'q02', 'flervalg', 'Hvilken trygd kom i 1894?', array['Ulykkestrygd for fabrikkarbeidere', 'Folketrygden', 'Barnetrygden', 'Alderstrygden']::text[], 0, 'Den første sosialforsikringen.', true, true, 1),
  ('historie-vg3:velferdsstaten', 'q03', 'flervalg', 'Hva var kriseforliket i 1935?', array['En fredsavtale', 'En avtale mellom LO og NHO', 'En avtale mellom Arbeiderpartiet og Bondepartiet', 'En handelsavtale med Sverige']::text[], 2, 'Arbeiderpartiet dannet deretter regjering.', true, true, 2),
  ('historie-vg3:velferdsstaten', 'q04', 'flervalg', 'Når kom folketrygden?', array['1936', '1946', '1978', '1967']::text[], 3, 'Én trygd for alle.', true, true, 3),
  ('historie-vg3:velferdsstaten', 'q05', 'flervalg', 'Hva betyr at ytelsene er universelle?', array['At de gjelder alle', 'At de bare gjelder de fattigste', 'At de gjelder hele verden', 'At de er private']::text[], 0, 'Kjennetegn ved den norske modellen.', true, true, 4),
  ('historie-vg3:velferdsstaten', 'q06', 'flervalg', 'Hvordan bidro barnehageutbyggingen til endring?', array['Færre kvinner tok lønnsarbeid', 'Flere kvinner kunne ta lønnsarbeid', 'Skolen ble kortere', 'Pensjonene ble lavere']::text[], 1, 'Viktig for likestillingen.', true, true, 5),
  ('historie-vg3:velferdsstaten', 'q07', 'flervalg', 'Hvem ledet Arbeiderpartiet under gjenreisningen?', array['Gro Harlem Brundtland', 'Christian Michelsen', 'Einar Gerhardsen', 'Marcus Thrane']::text[], 2, 'Statsminister i mange år etter krigen.', true, true, 6),
  ('historie-vg3:velferdsstaten', 'q08', 'flervalg', 'Hva er en utfordring for velferdsstaten i framtiden?', array['For mange unge', 'For lave skatter alltid', 'For mange barnehager', 'Eldrebølgen og lavere oljeinntekter']::text[], 3, 'Gjør det dyrere å finansiere velferden.', true, true, 7),
  ('historie-vg3:velferdsstaten', 'q09', 'flervalg', 'Hva la Hovedavtalen i 1935 grunnlaget for?', array['Samarbeid i arbeidslivet', 'Folketrygden', 'Barnetrygden', 'Niårig skole']::text[], 0, 'Mellom LO og arbeidsgiverne.', true, false, 8),
  ('historie-vg3:velferdsstaten', 'q10', 'flervalg', 'Hvordan har velferdsstaten påvirket sosial mobilitet?', array['Den har redusert den', 'Flere har fått utdanning uavhengig av foreldrenes økonomi', 'Den har ingen betydning', 'Bare de rike har fått utdanning']::text[], 1, 'For eksempel gjennom Lånekassen.', true, false, 9),
  ('historie-vg3:velferdsstaten', 'm01', 'sant-usant', 'Mottakere av fattighjelp kunne i en periode miste stemmeretten.', array['Sant', 'Usant']::text[], 0, 'Hjelpen var nedverdigende.', false, true, 10),
  ('historie-vg3:velferdsstaten', 'm02', 'sant-usant', 'De første trygdene gjaldt alle innbyggere.', array['Sant', 'Usant']::text[], 1, 'De var begrensede og gjaldt bare noen grupper.', false, true, 11),
  ('historie-vg3:velferdsstaten', 'm03', 'sant-usant', 'Høye skatter finansierer den norske velferdsmodellen.', array['Sant', 'Usant']::text[], 0, 'Et kjennetegn ved modellen.', false, true, 12),
  ('historie-vg3:velferdsstaten', 'm04', 'sant-usant', 'Velferdsstaten ble bygd opp av ett parti alene uten kompromisser.', array['Sant', 'Usant']::text[], 1, 'Den bygger på kompromisser og brede avtaler.', false, true, 13),
  ('historie-vg3:velferdsstaten', 'm05', 'flervalg', 'Når ble barnetrygden innført?', array['1936', '1946', '1967', '1978']::text[], 1, 'Rett etter krigen.', false, true, 14),
  ('historie-vg3:velferdsstaten', 'm06', 'flervalg', 'Hva er en kritikk mot velferdsstaten?', array['Byråkrati og mindre valgfrihet', 'For lite trygghet', 'For lave skatter', 'For få skoler']::text[], 0, 'Også høye kostnader.', false, true, 15),
  ('historie-vg3:velferdsstaten', 'm07', 'flervalg', 'Hva har gjort det mulig å bygge ut velferden etter 1970-tallet?', array['Bare krigsskadeserstatning', 'Bare lån fra utlandet', 'Økonomisk vekst og oljeinntekter', 'Salg av kolonier']::text[], 2, 'Sammen med politiske kompromisser.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-vg3:velferdsstaten', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-vg3:velferdsstaten', 's01', 'Før velferdsstaten kunne fattigvesenet gi offentlig hjelp til fattige, men hjelpen kunne være nedverdigende og mottakerne kunne miste stemmeretten en periode. Sammenlign dette med universelle ytelser i velferdsstaten.', 'Fattigvesenet hjalp mennesker som var fattige, og hjelpen kunne føre til tap av verdighet og stemmerett. Universelle ytelser gjelder alle, ikke bare de fattigste.', array['Forklarer at fattigvesenet var hjelp rettet mot fattige, og at hjelpen kunne ha negative følger for mottakerne.', 'Forklarer at universelle ytelser gjelder alle, ikke bare de fattigste.']::text[], 0),
  ('historie-vg3:velferdsstaten', 's02', 'Industrialiseringen førte til de første sosialforsikringene i Norge. Forklar hva en sosialforsikring skulle sikre mot, og hvordan dette hang sammen med behovet for trygghet ved inntektstap.', 'En sosialforsikring er en trygd som sikrer mot tap av inntekt. Den ga økonomisk trygghet dersom noen for eksempel ble syke eller utsatt for en ulykke.', array['Forklarer at sosialforsikring sikrer mot inntektstap.', 'Knytter ordningen til økonomisk trygghet ved en situasjon som sykdom eller ulykke.']::text[], 1),
  ('historie-vg3:velferdsstaten', 's03', 'En lavtlønnet person blir syk i Norge i 1909. Hvilken trygd kunne gi personen støtte, og hvilken begrensning hadde de tidlige trygdeordningene?', 'Syketrygden, som kom i 1909, kunne gi støtte ved sykdom til lavtlønte. De tidlige trygdene var begrensede og gjaldt bare bestemte grupper.', array['Identifiserer syketrygden som ordningen ved sykdom for lavtlønte.', 'Forklarer at tidlige trygder bare gjaldt bestemte grupper.']::text[], 2),
  ('historie-vg3:velferdsstaten', 's04', 'Etter krigen ble utdanning bygget ut, blant annet gjennom Statens lånekasse for utdanning fra 1947 og niårig skole fra slutten av 1960-tallet. Forklar hvordan slike tiltak kunne gi flere mulighet til å få utdanning uavhengig av foreldrenes økonomi.', 'Lånekassen kunne gjøre det lettere å finansiere utdanning, og niårig skole ga flere en lengre skolegang. Slik kunne flere få utdanning og mulighet til et annet liv enn foreldrene sine.', array['Knytter minst ett av tiltakene til at flere fikk tilgang til eller kunne finansiere utdanning.', 'Forklarer sammenhengen mellom utdanning og muligheten til å få et annet liv enn foreldrene.']::text[], 3),
  ('historie-vg3:velferdsstaten', 's05', 'To avtaler ble inngått i 1935: Kriseforliket mellom Arbeiderpartiet og Bondepartiet, og Hovedavtalen mellom LO og arbeidsgiverne. Sammenlign hvem som inngikk avtalene, og hva slags samarbeid de la til rette for.', 'Kriseforliket var en politisk avtale mellom Arbeiderpartiet og Bondepartiet, og etter den dannet Arbeiderpartiet regjering. Hovedavtalen var mellom LO og arbeidsgiverne og la grunnlaget for samarbeid i arbeidslivet.', array['Skiller riktig mellom partene i kriseforliket og partene i Hovedavtalen.', 'Forklarer at kriseforliket var politisk, mens Hovedavtalen la grunnlag for samarbeid i arbeidslivet.']::text[], 4),
  ('historie-vg3:velferdsstaten', 's06', 'I den norske modellen samarbeider arbeidsgivere, arbeidstakere og staten. Bruk en arbeidslivssituasjon der disse tre partene møtes, og forklar hvorfor samarbeidet kalles trepartssamarbeid.', 'Hvis arbeidsgivere, arbeidstakere og staten samarbeider om spørsmål i arbeidslivet, er alle de tre partene med. Derfor kalles det trepartssamarbeid.', array['Identifiserer arbeidsgivere, arbeidstakere og staten som de tre partene.', 'Forklarer at betegnelsen viser til samarbeid mellom nettopp disse tre partene.']::text[], 5),
  ('historie-vg3:velferdsstaten', 's07', 'Den norske modellen bruker høye skatter til å finansiere offentlige tjenester. Forklar både hvordan skattene bidrar til velferd, og hvorfor høye skatter samtidig kan bli kritisert.', 'Skatteinntektene kan finansiere offentlige tjenester som skoler, sykehus og eldreomsorg. Høye skatter kan kritiseres fordi de innebærer en stor kostnad for innbyggerne.', array['Forklarer at skatter finansierer offentlige velferdstjenester.', 'Forklarer at skattenivået også kan oppfattes som en belastning eller kritiseres.']::text[], 6),
  ('historie-vg3:velferdsstaten', 's08', 'Folketrygden gir blant annet pensjoner og andre ytelser, mens skoler og sykehus er offentlige tjenester. Forklar forskjellen mellom en trygdeytelse og en offentlig tjeneste, og gi ett eksempel på hver.', 'En trygdeytelse er økonomisk støtte, for eksempel alderspensjon. En offentlig tjeneste er et tilbud det offentlige driver, for eksempel skole eller sykehus.', array['Forklarer at en trygdeytelse er økonomisk støtte, og gir et relevant eksempel.', 'Forklarer at en offentlig tjeneste er et tilbud det offentlige driver, og gir et relevant eksempel.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-vg3:menneske-natur-og-ressurser', 'historie-vg3', 'menneske-natur-og-ressurser', 'Mennesket, naturen og ressursene i historien', 'Hvordan mennesker har forholdt seg til naturen og forvaltet ressurser – fra fangst og jordbruk via industrialisering, hvalfangst og oljealder til naturvernbevegelsen og klimapolitikken – og hvordan historiske erfaringer kan brukes i samtaler om bærekraftige løsninger.', array[17]::int[], 13, 'utkast', '{}'::text[], false, now())
