  ('religion-og-etikk:jodedommen', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('religion-og-etikk:jodedommen', 's01', 'Forklar hva pakten betyr i jødedommen, og knytt den til Abraham.', 'Pakten er forholdet mellom Gud og det jødiske folket. Ifølge jødisk tradisjon inngikk Gud denne pakten med Abraham.', array['Forklarer at pakten er et forhold mellom Gud og det jødiske folket.', 'Knytter pakten til Abraham.']::text[], 0),
  ('religion-og-etikk:jodedommen', 's02', 'Sammenlign Toraen og Tanakh med tanke på hva de inneholder, og forklar hvordan de henger sammen.', 'Toraen består av de fem Mosebøkene. Tanakh er hele den hebraiske bibelen og omfatter Toraen, Profetene og Skriftene, så Toraen er en del av Tanakh.', array['Forklarer at Toraen er de fem Mosebøkene.', 'Forklarer at Tanakh også omfatter Profetene og Skriftene, og at Toraen inngår i Tanakh.']::text[], 1),
  ('religion-og-etikk:jodedommen', 's03', 'En person følger ikke religiøse regler, men omtaler seg likevel som jødisk. Forklar hvordan dette kan henge sammen med at jødedommen både er en religion og et folk.', 'Jødisk identitet kan være knyttet til et folk og en felles historie, ikke bare til religiøs tro eller praksis. Derfor kan også sekulære personer føle seg jødiske.', array['Forklarer at jødisk identitet også handler om folk og felles historie.', 'Knytter dette til at sekulære jøder fortsatt kan føle seg jødiske.']::text[], 2),
  ('religion-og-etikk:jodedommen', 's04', 'Du skal servere et måltid som følger kosher-reglene. Det serveres både kjøtt og melk. Hva må du passe på, og hvorfor?', 'Kjøtt og melk skal ikke blandes i et kosher måltid. Derfor må de serveres hver for seg.', array['Slår fast at kjøtt og melk ikke skal blandes.', 'Bruker regelen til å forklare at maten må holdes atskilt.']::text[], 3),
  ('religion-og-etikk:jodedommen', 's05', 'En besøkende vil delta i bønn og lære om jødisk tro. Forklar hvor personen kan gå, og hvilken rolle en rabbiner har der.', 'Personen kan gå til en synagoge, som brukes til bønn, lesning og undervisning. En rabbiner er en jødisk lærer og leder.', array['Identifiserer synagogen som et sted for bønn og læring.', 'Forklarer rabbinerens rolle som lærer eller leder.']::text[], 4),
  ('religion-og-etikk:jodedommen', 's06', 'Sammenlign sabbat og jom kippur med tanke på hva slags dag de er, og hva som kjennetegner dem.', 'Sabbaten er en hviledag fra fredag kveld til lørdag kveld og minner om skapelsen. Jom kippur er forsoningsdagen, som kjennetegnes av faste og bønn.', array['Forklarer sabbaten som hviledag og knytter den til skapelsen.', 'Forklarer jom kippur som forsoningsdag med faste og bønn.']::text[], 5),
  ('religion-og-etikk:jodedommen', 's07', 'Sammenlign ortodoks jødedom og reformjødedom: Hvordan forholder de seg ulikt til religiøs lov og tradisjon?', 'Ortodoks jødedom følger loven strengt og ser den som uforanderlig. Reformjødedom tilpasser tradisjonen til moderne tid, for eksempel ved å ha kvinnelige rabbinere.', array['Forklarer at ortodoks jødedom følger loven strengt og ser den som uforanderlig.', 'Forklarer at reformjødedom tilpasser tradisjonen til moderne tid.']::text[], 6),
  ('religion-og-etikk:jodedommen', 's08', 'Grunnloven fra 1814 stengte jøder ute fra Norge, og forbudet ble opphevet i 1851. Forklar hvilken endring dette innebar for jøders adgang til riket, og hvilken rolle Henrik Wergeland hadde.', 'I 1814 var jøder utestengt fra riket, mens de etter opphevelsen i 1851 kunne komme inn. Henrik Wergeland arbeidet for å få opphevet forbudet.', array['Forklarer endringen fra utestengelse til at forbudet ble opphevet.', 'Knytter Henrik Wergelands innsats til arbeidet for å oppheve forbudet.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('religion-og-etikk:hinduisme-buddhisme-og-ostlige-tradisjoner', 'religion-og-etikk', 'hinduisme-buddhisme-og-ostlige-tradisjoner', 'Hinduisme, buddhisme og andre østlige tradisjoner', 'Sentrale trekk ved hinduisme og buddhisme – samsara, karma og moksha, de fire edle sannhetene og den åttedelte veien – kort om sikhisme, konfutsianisme og daoisme, og en sammenligning av østlige og vestlige religiøse tradisjoner.', array[1]::int[], 4, 'utkast', '{}'::text[], false, now())
