  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 's01', 'Hva kjennetegner humanismen som livssyn, utover at den ikke bygger på guder eller det overnaturlige?', 'Humanismen setter mennesket, fornuften og menneskeverdet i sentrum. Den legger vekt på menneskers frihet og ansvar.', array['Får fram at mennesket står i sentrum.', 'Knytter humanismen til fornuft eller menneskeverd.']::text[], 0),
  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 's02', 'Hvordan passer synet på evolusjon sammen med humanistenes syn på mennesket?', 'Humanister ser mennesket som en del av naturen, som har utviklet seg gjennom evolusjon. Mennesket forstås dermed ikke som løsrevet fra naturen.', array['Får fram at mennesket er en del av naturen.', 'Knytter menneskets utvikling til evolusjon.']::text[], 1),
  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 's03', 'Sammenlign hva som var særlig sentralt for filosofer i antikken, med hva som ble sentralt i opplysningstiden.', 'I antikken satte filosofer som Sokrates og Protagoras mennesket og fornuften i sentrum. I opplysningstiden ble også vitenskap og menneskerettigheter viktige, og mange filosofer kritiserte kirkens makt.', array['Får fram mennesket og fornuften som sentralt i antikken.', 'Får fram vitenskap, menneskerettigheter eller kritikk av kirkens makt som sentralt i opplysningstiden.']::text[], 2),
  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 's04', 'En elev vurderer å dele et bilde av en medelev uten å spørre først. Hvordan kan humanistisk etikk brukes til å vurdere valget?', 'En humanistisk vurdering ser på konsekvensene for den som blir berørt, og tar hensyn til empati og menneskeverd. Eleven har ansvar for egne valg og bør vurdere om delingen kan skade den andre.', array['Viser at konsekvensene for den berørte personen bør vurderes.', 'Knytter vurderingen til empati, menneskeverd eller ansvar for egne valg.']::text[], 3),
  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 's05', 'Human-Etisk Forbund arbeider for et livssynsnøytralt samfunn. Hva betyr det, og hvordan henger det sammen med forbundets kritikk av kirkens særstilling?', 'Et livssynsnøytralt samfunn behandler ulike livssyn likt. Derfor har Human-Etisk Forbund vært kritisk til at kirken har hatt en særstilling.', array['Forklarer at ulike livssyn skal behandles likt.', 'Knytter dette til kritikken av kirkens særstilling.']::text[], 4),
  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 's06', 'En person forteller at hen er ateist eller agnostiker. Hvorfor forteller ikke dette alene hvilket livssyn personen har?', 'Ateisme og agnostisisme er standpunkter om Gud, men ikke hele livssyn i seg selv. De sier derfor ikke alene hva personen mener om for eksempel mennesket, moral eller meningen med livet.', array['Får fram at ateisme og agnostisisme er standpunkter om Gud.', 'Forklarer at standpunktene ikke alene dekker et helt livssyn.']::text[], 5),
  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 's07', 'Hva innebærer menneskeverd i humanismen, og hva betyr det for hvordan mennesker bør vurderes?', 'Menneskeverd betyr at alle mennesker har samme ukrenkelige verdi. I humanismen skal ikke menneskers verdi gjøres avhengig av hvem de er eller hvilket livssyn de har.', array['Får fram at alle mennesker har samme verdi.', 'Får fram at verdien er ukrenkelig eller ikke avhenger av bestemte kjennetegn.']::text[], 6),
  ('religion-og-etikk:humanisme-og-sekulare-livssyn', 's08', 'Hva mener humanister når de sier at mennesket selv må skape meningen med livet?', 'Humanister mener at meningen med livet ikke er gitt på forhånd, men at mennesker selv må skape den. Det innebærer at mennesker kan finne eller forme mening gjennom egne valg og liv.', array['Får fram at mennesker selv skaper meningen med livet.', 'Skiller dette fra en mening som er gitt på forhånd.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'religion-og-etikk', 'religion-i-historiske-endringsprosesser', 'Religion i historiske endringsprosesser', 'Hvordan religion har vært med på å forme – og blitt formet av – historiske endringer globalt og i Norge: kristningen, reformasjonen, misjon og kolonialisme, sekularisering, religion i frigjøringsbevegelser og politiske revolusjoner, og utviklingen fra statskirke til livssynsåpent samfunn.', array[2]::int[], 6, 'utkast', '{}'::text[], false, now())
