insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q01', 'flervalg', 'Hvilken rolle spilte kristendommen i middelalderens Norge?', array['Den svekket kongemakten', 'Den styrket kongemakten og ga nye lover', 'Den hadde ingen betydning', 'Den førte til demokrati']::text[], 1, 'Knyttet Norge til den europeiske kirken.', true, true, 0),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q02', 'flervalg', 'Når ble lutherdommen innført i Norge?', array['1537', '1030', '1814', '1905']::text[], 0, 'Av den dansk-norske kongen.', true, true, 1),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q03', 'flervalg', 'Hva protesterte Luther mot?', array['Bibelen på folkespråket', 'Salmer', 'Avlatshandelen og pavens makt', 'Nattverden']::text[], 2, 'Startet reformasjonen.', true, true, 2),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q04', 'flervalg', 'Hva skjedde i Iran i 1979?', array['Landet ble sekulært', 'Landet ble kristent', 'Landet ble en koloni', 'Landet ble en islamsk republikk']::text[], 3, 'Religion som politisk kraft.', true, true, 3),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q05', 'flervalg', 'Hva bygde Martin Luther King borgerrettighetskampen på?', array['Kristen tro og ikkevold', 'Vold', 'Kommunisme', 'Nasjonalisme']::text[], 0, 'Religion som frigjørende kraft.', true, true, 4),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q06', 'flervalg', 'Hva skjedde med statskirkeordningen i 2012?', array['Den ble innført', 'Den ble avviklet i Grunnloven', 'Den ble utvidet', 'Den ble flyttet til Sverige']::text[], 1, 'Kirken ble eget rettssubjekt i 2017.', true, true, 5),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q07', 'flervalg', 'Hva var en positiv side ved reformasjonen?', array['Religionskriger', 'Mer avlat', 'Bibler og salmer på folkespråket og økt leseferdighet', 'Større pavemakt']::text[], 2, 'Folk kunne lese selv.', true, true, 6),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q08', 'flervalg', 'Hva er frigjøringsteologi?', array['Teologi om kongemakt', 'Teologi om misjon i Norge', 'Teologi om avlat', 'Teologi om rettferdighet for de fattige']::text[], 3, 'Fra Latin-Amerika.', true, true, 7),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q09', 'flervalg', 'Hva betyr religionens tilbakekomst?', array['At religion igjen får større plass i offentligheten', 'At religioner forsvinner', 'At kirker rives', 'At alle blir ateister']::text[], 0, 'En motstrøm til sekulariseringen.', true, false, 8),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'q10', 'flervalg', 'Hva tillot dissenterloven fra 1845?', array['Islam', 'Andre kristne trossamfunn', 'Ateisme', 'Jødedom']::text[], 1, 'Jøder fikk adgang i 1851.', true, false, 9),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'm01', 'sant-usant', 'Misjonen bygde skoler og sykehus, men var ofte knyttet til kolonimakten.', array['Sant', 'Usant']::text[], 0, 'En tvetydig historie.', false, true, 10),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'm02', 'sant-usant', 'Religion har bare vært en kilde til konflikt i historien.', array['Sant', 'Usant']::text[], 1, 'Den har også vært en kraft for frigjøring.', false, true, 11),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'm03', 'sant-usant', 'Den norske kirke ble et eget rettssubjekt i 2017.', array['Sant', 'Usant']::text[], 0, 'Etter at statskirken ble avviklet.', false, true, 12),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'm04', 'sant-usant', 'Kristningen av Norge skjedde helt uten bruk av makt.', array['Sant', 'Usant']::text[], 1, 'Kongene brukte ofte makt.', false, true, 13),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'm05', 'flervalg', 'Hvem kjempet mot apartheid i Sør-Afrika ut fra kristen tro?', array['Martin Luther', 'Desmond Tutu', 'Olav Tryggvason', 'Paulus']::text[], 1, 'Erkebiskop i Sør-Afrika.', false, true, 14),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'm06', 'flervalg', 'Hvilket spørsmål er nyttig når du drøfter religionens rolle i en endring?', array['Var religionen årsak, redskap eller følge?', 'Hvor mange kirker finnes?', 'Hvilken farge hadde kirkene?', 'Hvor gammel var kongen?']::text[], 0, 'Og hvem brukte religionen.', false, true, 15),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 'm07', 'flervalg', 'Hvor bor de fleste kristne i dag?', array['I Norden', 'I Vest-Europa', 'I det globale sør', 'I Midtøsten']::text[], 2, 'Tyngdepunktet har flyttet seg.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 's01', 'Norge ble kristnet på 900- og 1000-tallet. Forklar hvordan kristningen både kunne styrke kongemakten og knytte Norge til Europa.', 'Kristendommen styrket kongemakten ved å gi nye lover. Den knyttet også Norge til den europeiske kirken.', array['Forklarer at kristendommen styrket kongemakten, for eksempel gjennom nye lover.', 'Forklarer at kristningen knyttet Norge til den europeiske kirken.']::text[], 0),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 's02', 'I Norge ble lutherdommen innført av den dansk-norske kongen i 1537, og kongen ble kirkens overhode. Forklar hvordan dette endret forholdet mellom politisk og religiøs makt.', 'Kongen fikk ikke bare politisk makt, men også øverste myndighet over kirken. Reformasjonen førte dermed til at kirkens ledelse i Norge ble knyttet til kongemakten.', array['Får fram at kongen ble kirkens overhode.', 'Forklarer at den religiøse myndigheten dermed ble samlet hos eller knyttet til den politiske makten.']::text[], 1),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 's03', 'Europeiske misjonærer bygde skoler og sykehus i koloniene, men misjonen var ofte knyttet til kolonimakten og til ideen om europeisk overlegenhet. Forklar hvorfor misjon kunne oppfattes både som hjelp og som en del av kolonial undertrykking.', 'Skoler og sykehus kunne gi mennesker viktige tilbud. Samtidig kunne misjonen støtte kolonimakten og formidle en idé om at europeisk kultur var overlegen.', array['Viser hvordan skoler eller sykehus kunne være til hjelp.', 'Forklarer hvordan tilknytningen til kolonimakten eller ideen om europeisk overlegenhet kunne bidra til undertrykking.']::text[], 2),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 's04', 'En kirkegruppe i Latin-Amerika viser til Bibelen for å kreve rettferdighet for fattige. Hvilket begrep passer på denne måten å tolke Bibelen på, og hvordan brukes religion i situasjonen?', 'Dette er frigjøringsteologi, som tolker Bibelen som et budskap om rettferdighet for de fattige. Religion brukes som grunnlag for å kreve sosial endring.', array['Identifiserer frigjøringsteologi.', 'Forklarer at religion eller bibeltolkning brukes til å fremme rettferdighet for fattige.']::text[], 3),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 's05', 'I 1979 ble Iran en islamsk republikk styrt av religiøse ledere. Forklar hva dette viser om forholdet mellom religion og politikk i moderne tid.', 'Det viser at religion kan være en sterk politisk kraft også i moderne tid. I Iran fikk religiøse ledere en styrende rolle i en islamsk republikk.', array['Får fram at religion kan ha stor politisk betydning også i moderne tid.', 'Knytter dette til at Iran ble styrt som en islamsk republikk av religiøse ledere.']::text[], 4),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 's06', 'I Vest-Europa har religion fått mindre betydning i offentligheten og i manges liv. Samtidig har pinsebevegelsen, politisk islam og hindunasjonalisme vokst fram som motstrømmer andre steder. Forklar forskjellen mellom sekularisering og religionens tilbakekomst, og bruk et eksempel på hver.', 'Sekularisering betyr at religion får mindre betydning i samfunnet, slik det har skjedd i Vest-Europa. Religionens tilbakekomst viser til at religion igjen får større plass i offentligheten, for eksempel gjennom veksten i pinsebevegelsen.', array['Forklarer sekularisering som mindre betydning for religion i samfunnet.', 'Forklarer religionens tilbakekomst som økt plass for religion i offentligheten, med et relevant eksempel.']::text[], 5),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 's07', 'I 1814 gjorde Grunnloven den evangelisk-lutherske religionen til statens religion. Dissenterloven i 1845 tillot andre kristne trossamfunn, og i 2012 ble statskirkeordningen avviklet i Grunnloven. Forklar hvordan disse endringene viser en utvikling i forholdet mellom stat og religion i Norge.', 'Utviklingen gikk fra at én religion var statens religion, til at andre kristne trossamfunn fikk lov til å eksistere. Avviklingen av statskirkeordningen markerte et videre skille mellom staten og kirken.', array['Beskriver overgangen fra evangelisk-luthersk statsreligion til at andre kristne trossamfunn ble tillatt.', 'Forklarer at avviklingen av statskirkeordningen markerte en endring i forholdet mellom stat og kirke.']::text[], 6),
  ('religion-og-etikk:religion-i-historiske-endringsprosesser', 's08', 'Sammenlign religionens rolle i Martin Luther Kings borgerrettighetskamp i USA med religionens rolle i Iran etter revolusjonen i 1979. Hva ble religion brukt til i de to tilfellene?', 'Martin Luther King bygde borgerrettighetsbevegelsen på kristen tro og ikkevold. I Iran ble landet en islamsk republikk styrt av religiøse ledere, slik at religion var knyttet til politisk styre.', array['Forklarer at King brukte kristen tro og ikkevold som grunnlag for borgerrettighetskampen.', 'Forklarer at religion i Iran var knyttet til styringen av landet gjennom religiøse ledere.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('religion-og-etikk:samisk-religion-og-urfolksperspektiv', 'religion-og-etikk', 'samisk-religion-og-urfolksperspektiv', 'Religion og livssyn i majoritets-, minoritets- og urfolksperspektiv', 'Religion og livssyn i Norge sett fra majoritetens, minoritetenes og urfolkets perspektiv – med vekt på førkristen samisk religion, noaiden og joiken, kristningen og læstadianismen, fornorskingen gjennom kirken og samisk religiøs revitalisering i dag.', array[3]::int[], 7, 'utkast', '{}'::text[], false, now())
