insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q01', 'flervalg', 'Hva betyr menneskeverd?', array['At noen mennesker er mer verdt enn andre', 'At alle mennesker har ukrenkelig og lik verdi', 'At verdien avhenger av nytte', 'At bare friske har verdi']::text[], 1, 'Grunnlaget for menneskerettighetene.', true, true, 0),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q02', 'flervalg', 'Hva er et antroposentrisk natursyn?', array['Mennesket i sentrum – naturen har verdi fordi vi trenger den', 'Alt levende har egenverdi', 'Økosystemer har egenverdi', 'Naturen har ingen verdi']::text[], 0, 'Motsatsen er bio- og økosentrisk.', true, true, 1),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q03', 'flervalg', 'Hvem grunnla dypøkologien?', array['Peter Singer', 'Immanuel Kant', 'Arne Næss', 'K.E. Løgstrup']::text[], 2, 'Norsk filosof.', true, true, 2),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q04', 'flervalg', 'Hva er artsdiskriminering?', array['Diskriminering av minoriteter', 'Å frede arter', 'Å dyrke planter', 'Å behandle dyr dårligere bare fordi de ikke er mennesker']::text[], 3, 'Peter Singers begrep.', true, true, 3),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q05', 'flervalg', 'Hvilken bekymring knyttes til fosterdiagnostikk?', array['At det kan føre til sortering av mennesker', 'At det er for billig', 'At ingen bruker det', 'At det gir for lite informasjon']::text[], 0, 'Veies mot kvinners selvbestemmelse.', true, true, 4),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q06', 'flervalg', 'Hva er CRISPR?', array['Et våpen', 'En teknologi for genredigering', 'En type KI', 'En klimaavtale']::text[], 1, 'Kan kanskje kurere arvelige sykdommer.', true, true, 5),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q07', 'flervalg', 'Hvilket etisk spørsmål reiser autonome våpen?', array['Om de er dyre', 'Om de er raske', 'Om maskiner skal kunne ta beslutninger om liv og død', 'Om de er lovlige å selge']::text[], 2, 'Ansvar og menneskeverd.', true, true, 6),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q08', 'flervalg', 'Hva sier føre var-prinsippet?', array['At vi alltid skal ta risiko', 'At teknologi alltid er trygg', 'At vi skal vente på bevis før vi handler', 'At vi bør være forsiktige når konsekvensene er usikre og alvorlige']::text[], 3, 'Viktig i miljø- og teknologietikk.', true, true, 7),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q09', 'flervalg', 'Hva er et økosentrisk natursyn?', array['Økosystemer og hele naturen har egenverdi', 'Mennesket i sentrum', 'Bare dyr har verdi', 'Naturen er en ressurs']::text[], 0, 'Det bredeste perspektivet.', true, false, 8),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'q10', 'flervalg', 'Hvilken konflikt kan vindkraft skape?', array['Med klimamål', 'Med natur og urfolksrettigheter', 'Med fornybar energi', 'Ingen konflikt']::text[], 1, 'Grønn teknologi har også etiske sider.', true, false, 9),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'm01', 'sant-usant', 'Menneskeverdet gjelder uavhengig av helse og evner.', array['Sant', 'Usant']::text[], 0, 'Det er ukrenkelig og likt.', false, true, 10),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'm02', 'sant-usant', 'Et biosentrisk syn mener at bare mennesker har egenverdi.', array['Sant', 'Usant']::text[], 1, 'Alt levende har egenverdi.', false, true, 11),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'm03', 'sant-usant', 'Genendringer som arves videre, er særlig etisk omstridte.', array['Sant', 'Usant']::text[], 0, 'De påvirker framtidige generasjoner.', false, true, 12),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'm04', 'sant-usant', 'Etiske spørsmål om teknologi kan løses med én enkel regel.', array['Sant', 'Usant']::text[], 1, 'Flere teorier og verdier må veies.', false, true, 13),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'm05', 'flervalg', 'Hva mente Peter Singer ga dyr moralsk betydning?', array['Intelligens', 'Evnen til å lide', 'Nytte for mennesker', 'Størrelse']::text[], 1, 'Utilitaristisk begrunnelse.', false, true, 14),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'm06', 'flervalg', 'Hvilket spørsmål reiser roboter i omsorg?', array['Om de kan erstatte menneskelig kontakt', 'Om de er vakre', 'Om de er norske', 'Om de er små']::text[], 0, 'Menneskeverd i omsorg.', false, true, 15),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 'm07', 'flervalg', 'Hvordan begrunner Kant menneskeverdet?', array['Med nytte', 'Med styrke', 'Med menneskets fornuft og autonomi', 'Med rikdom']::text[], 2, 'Mennesket er mål i seg selv.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 's01', 'Sammenlign et biosentrisk og et økosentrisk syn på naturens egenverdi.', 'Et biosentrisk syn gir alt levende, som dyr og planter, egenverdi. Et økosentrisk syn gir egenverdi til økosystemer og hele naturen.', array['Forklarer at biosentrismen gjelder alt levende.', 'Forklarer at økosentrismen gjelder økosystemer eller hele naturen.']::text[], 0),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 's02', 'Sammenlign hvordan kristendommen og Kant begrunner menneskets verdi.', 'Kristendommen begrunner menneskets verdi med at mennesket er skapt i Guds bilde. Kant knytter verdien til menneskets fornuft og autonomi.', array['Knytter kristen begrunnelse til at mennesket er skapt i Guds bilde.', 'Knytter Kants begrunnelse til fornuft og autonomi.']::text[], 1),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 's03', 'Hva innebærer dypøkologi for hvordan mennesker bør leve i forhold til naturen?', 'Dypøkologi bygger på at alt liv har verdi i seg selv. Derfor bør mennesker leve enklere og i harmoni med naturen.', array['Får fram at alt liv har egenverdi.', 'Knytter dette til enklere liv eller harmoni med naturen.']::text[], 2),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 's04', 'Genredigering kan brukes til å forsøke å kurere arvelige sykdommer. Hvorfor blir det etisk mer komplisert hvis endringene kan arves av nye generasjoner?', 'Arvelige endringer påvirker også framtidige generasjoner, som ikke selv kan velge endringene. Det reiser spørsmål om designerbabyer og om mennesker går for langt ved å gripe inn i livet.', array['Forklarer at endringene kan føres videre til nye generasjoner.', 'Knytter dette til bekymring for designerbabyer eller spørsmålet om å «leke Gud».']::text[], 3),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 's05', 'En algoritme avslår søknader og viser seg å diskriminere enkelte grupper. Hva er etisk problematisk med dette, og hvilket ansvarsspørsmål oppstår?', 'Algoritmen kan behandle mennesker urettferdig gjennom diskriminering. Det oppstår også et spørsmål om hvem som har ansvaret når algoritmen gjør feil eller diskriminerer.', array['Peker på at automatiserte beslutninger kan diskriminere eller gjøre feil.', 'Får fram spørsmålet om hvem som har ansvaret.']::text[], 4),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 's06', 'En omsorgstjeneste bruker roboter til å gi brukerne selskap. Forklar hvilken etisk bekymring dette kan reise.', 'En robot kan kanskje hjelpe i omsorgen, men den kan ikke nødvendigvis erstatte menneskelig kontakt. Bekymringen er at teknologien skal gå på bekostning av kontakt mellom mennesker.', array['Får fram at robotbruk kan påvirke eller erstatte menneskelig kontakt.', 'Forklarer hvorfor dette er en etisk bekymring i omsorgen.']::text[], 5),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 's07', 'Et vindkraftverk kan gi fornybar energi, men påvirke naturen og urfolksrettigheter. Forklar hvordan konsekvensetikk og pliktetikk kan belyse beslutningen om å bygge det.', 'Konsekvensetikken vurderer resultatene, som energien fra vindkraftverket opp mot skadene på naturen. Pliktetikken spør om det finnes grenser eller rettigheter, som urfolksrettigheter, som ikke bør krenkes.', array['Viser at konsekvensetikk vurderer resultatene eller følgene.', 'Viser at pliktetikk vurderer grenser eller plikter, for eksempel respekt for urfolksrettigheter.']::text[], 6),
  ('religion-og-etikk:menneskeverd-natur-og-teknologi', 's08', 'Forklar både hvordan teknologi har bidratt til problemer for naturen, og hvordan ny teknologi kan bidra til å løse noen av dem.', 'Teknologi har gitt velstand, men også bidratt til klimaendringer, forurensning og tap av arter. Fornybar energi og karbonfangst er eksempler på teknologi som kan være del av løsningen.', array['Nevner minst én negativ miljøfølge av teknologi.', 'Nevner fornybar energi eller karbonfangst som en mulig del av løsningen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'religion-og-etikk', 'fordommer-rasisme-og-diskriminering', 'Fordommer, rasisme og diskriminering', 'Hva gruppebaserte fordommer, stereotypier, rasisme og diskriminering er, ulike former som antisemittisme, muslimhat og antisamisk rasisme, hvordan fordommer oppstår og forsterkes – og hva lovverket og hver enkelt kan gjøre for å motarbeide dem.', array[13]::int[], 15, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', '## Begreper
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Stereotypi', 'Forenklet bilde av en gruppe.', 0),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Fordom', 'Negativ holdning til en person fordi hen tilhører en gruppe.', 1),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Gruppebaserte fordommer', 'Fordommer basert på etnisitet, religion, kjønn, seksualitet eller funksjonsevne.', 2),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Diskriminering', 'At noen behandles dårligere på grunn av gruppetilhørighet.', 3),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Rasisme', 'Forestillingen om at grupper av mennesker har ulik verdi.', 4),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Biologisk rasisme', 'Påstand om at menneskeraser finnes og har ulik verdi.', 5),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Kulturell rasisme', 'Påstand om at noen kulturer eller religioner er mindreverdige.', 6),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Strukturell rasisme', 'Systemer og regler som rammer noen grupper.', 7),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Antisemittisme', 'Fordommer og hat mot jøder.', 8),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Muslimhat', 'Fordommer og hat mot muslimer.', 9),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Antisamisk rasisme', 'Nedvurdering og hets av samer.', 10),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Inngruppe og utgruppe', 'Vi og dem – egen gruppe ses som bedre.', 11),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Syndebukk', 'En gruppe som får skylden for problemer.', 12),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Indirekte diskriminering', 'En tilsynelatende nøytral regel rammer noen grupper hardere.', 13),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Likestillings- og diskrimineringsloven', 'Lov som forbyr diskriminering på mange grunnlag.', 14),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'Hatkriminalitet', 'Straffbare handlinger motivert av hat mot en gruppe.', 15);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q01', 'flervalg', 'Hva er en fordom?', array['Kunnskap om en gruppe', 'En negativ holdning til en person fordi hen tilhører en gruppe', 'En lov', 'En type forskning']::text[], 1, 'Uten at man kjenner personen.', true, true, 0),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q02', 'flervalg', 'Hva er kulturell rasisme?', array['Påstand om at noen kulturer eller religioner er mindreverdige', 'Påstand om ulike raser', 'Lovverk mot rasisme', 'Kulturutveksling']::text[], 0, 'En nyere form for rasisme.', true, true, 1),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q03', 'flervalg', 'Hva er antisemittisme?', array['Hat mot muslimer', 'Hat mot samer', 'Fordommer og hat mot jøder', 'Kritikk av religion']::text[], 2, 'Drivkraften bak holocaust.', true, true, 2),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q04', 'flervalg', 'Hva er indirekte diskriminering?', array['Bevisst avvisning', 'Trakassering', 'Hets på nett', 'En tilsynelatende nøytral regel som rammer noen grupper hardere']::text[], 3, 'For eksempel et forbud mot hodeplagg.', true, true, 3),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q05', 'flervalg', 'Hva sier forskningen om menneskeraser?', array['At det ikke finnes egne menneskeraser', 'At det finnes fem raser', 'At raser har ulik intelligens', 'At raser har ulik verdi']::text[], 0, 'Biologisk rasisme er avvist.', true, true, 4),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q06', 'flervalg', 'Hva er en syndebukk?', array['En type dyr', 'En gruppe som får skylden for problemer', 'En lov', 'En type ytring']::text[], 1, 'Minoriteter rammes ofte i krisetider.', true, true, 5),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q07', 'flervalg', 'Hvilken lov forbyr diskriminering på grunn av religion og etnisitet?', array['Arbeidsmiljøloven alene', 'Arveloven', 'Likestillings- og diskrimineringsloven', 'Barneloven']::text[], 2, 'Også kjønn og seksuell orientering.', true, true, 6),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q08', 'flervalg', 'Hva kan redusere fordommer?', array['Mindre kontakt', 'Konspirasjonsteorier', 'Å dele hets', 'Kunnskap og kontakt på tvers av grupper']::text[], 3, 'Fordommer trives der vi har lite kjennskap.', true, true, 7),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q09', 'flervalg', 'En person blir ikke kalt inn til intervju på grunn av navnet. Hva slags diskriminering er det?', array['Direkte', 'Indirekte', 'Strukturell alene', 'Positiv']::text[], 0, 'Bevisst avvisning.', true, false, 8),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'q10', 'flervalg', 'Hva er forskjellen på kritikk av ideer og hat mot mennesker?', array['Ingen forskjell', 'Kritikk retter seg mot ideer, hat rammer mennesker som gruppe', 'Hat er alltid lovlig', 'Kritikk er alltid ulovlig']::text[], 1, 'Viktig skille.', true, false, 9),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'm01', 'sant-usant', 'De fleste mennesker har noen fordommer.', array['Sant', 'Usant']::text[], 0, 'Det viktige er å bli bevisst dem.', false, true, 10),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'm02', 'sant-usant', 'Hatefulle ytringer er fullt ut lovlige i Norge.', array['Sant', 'Usant']::text[], 1, 'Straffeloven forbyr hatefulle ytringer.', false, true, 11),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'm03', 'sant-usant', 'Strukturell rasisme kan finnes selv om ingen har ment å diskriminere.', array['Sant', 'Usant']::text[], 0, 'Systemer og regler kan ramme noen grupper.', false, true, 12),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'm04', 'sant-usant', 'Antisemittisme forsvant etter andre verdenskrig.', array['Sant', 'Usant']::text[], 1, 'Den finnes fortsatt.', false, true, 13),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'm05', 'flervalg', 'Hvem gir veiledning om diskriminering i Norge?', array['Forbrukertilsynet', 'Likestillings- og diskrimineringsombudet', 'Konkurransetilsynet', 'Datatilsynet']::text[], 1, 'Hjelper dem som opplever diskriminering.', false, true, 14),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'm06', 'flervalg', 'Hva gjør hjernen når den kategoriserer?', array['Forenkler verden for å spare energi', 'Lager alltid riktige bilder', 'Fjerner alle fordommer', 'Glemmer alt']::text[], 0, 'En årsak til stereotypier.', false, true, 15),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 'm07', 'flervalg', 'Hva kan du gjøre når noen utsettes for hets?', array['Dele hetsen videre', 'Late som ingenting', 'Si ifra og støtte den som rammes', 'Le med']::text[], 2, 'Hver enkelt kan gjøre en forskjell.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 's01', 'En person sier «alle fra gruppe X er late» og antar at en ukjent person fra gruppa er lat. Forklar hva som er stereotypien, og hva som er fordommen.', 'Påstanden om at alle fra gruppe X er late, er en stereotypi fordi den gir et forenklet bilde av en gruppe. Å ha en negativ holdning til den ukjente personen på grunn av gruppetilhørigheten er en fordom.', array['Forklarer stereotypi som et forenklet bilde eller en generalisering om en gruppe.', 'Forklarer fordom som en negativ holdning til personen på grunn av gruppetilhørighet, uten at personen er kjent.']::text[], 0),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 's02', 'Hvordan kan «vi og dem»-tenkning bidra til fordommer?', 'Når mennesker deler verden inn i en inng gruppe og en utgruppe, kan de begynne å se sin egen gruppe som bedre. Det kan føre til negative holdninger og generaliseringer om dem som tilhører utgruppa.', array['Forklarer at mennesker skiller mellom en inng gruppe og en utgruppe.', 'Knytter det å se egen gruppe som bedre til negative holdninger eller generaliseringer om andre grupper.']::text[], 1),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 's03', 'Hvordan kan sosialisering føre til at mennesker lærer fordommer?', 'Vi kan lære holdninger fra familie, venner og medier. Hvis vi møter fordomsfulle holdninger der, kan vi ta dem til oss uten å kjenne personene eller gruppene det gjelder.', array['Nevner at holdninger kan læres fra familie, venner eller medier.', 'Forklarer at slike lærte holdninger kan bli fordommer mot grupper eller personer.']::text[], 2),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 's04', 'En arbeidsgiver antar at personer med funksjonsnedsettelse ikke egner seg for en jobb, og avviser søkere av den grunn uten å vurdere evnene deres. Forklar hvordan situasjonen viser både en fordom og diskriminering.', 'Antakelsen om at personer med funksjonsnedsettelse ikke egner seg, er en fordom fordi den bygger på en negativ holdning til en gruppe. Avvisningen er diskriminering fordi søkerne blir behandlet dårligere på grunn av funksjonsnedsettelsen.', array['Forklarer antakelsen som en negativ holdning basert på gruppetilhørighet.', 'Forklarer avvisningen som dårligere behandling på grunn av funksjonsnedsettelse.']::text[], 3),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 's05', 'Sammenlign biologisk og strukturell rasisme. Hva bygger de på, og hvordan kommer de til uttrykk?', 'Biologisk rasisme bygger på påstanden om at menneskeraser finnes og har ulik verdi. Strukturell rasisme kommer til uttrykk når systemer eller regler rammer noen grupper, selv om ingen har ment at det skal skje.', array['Forklarer at biologisk rasisme bygger på en påstand om menneskeraser med ulik verdi.', 'Forklarer at strukturell rasisme handler om systemer eller regler som rammer grupper, også uten en slik hensikt.']::text[], 4),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 's06', 'En person blir hetset og nedvurdert fordi hen er same. Hvilket begrep beskriver dette, og hva kan en som er vitne til det, gjøre for å støtte personen?', 'Dette kan beskrives som antisamisk rasisme. Et vitne kan si ifra om hetsen og støtte personen som blir rammet.', array['Identifiserer hets eller nedvurdering av samer som antisamisk rasisme.', 'Nevner en relevant støttehandling, som å si ifra eller støtte den som rammes.']::text[], 5),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 's07', 'En elev utsettes for hatefulle ytringer på grunn av religion. Hvilken rolle har Straffeloven i en slik situasjon, og hva kan Likestillings- og diskrimineringsombudet bidra med?', 'Straffeloven forbyr hatefulle ytringer. Likestillings- og diskrimineringsombudet kan gi veiledning.', array['Knytter forbudet mot hatefulle ytringer til Straffeloven.', 'Forklarer at Likestillings- og diskrimineringsombudet kan gi veiledning.']::text[], 6),
  ('religion-og-etikk:fordommer-rasisme-og-diskriminering', 's08', 'I en krise får en minoritetsgruppe skylden for samfunnets problemer. Forklar hvilket begrep som beskriver gruppens rolle, og hvordan dette kan bidra til fordommer.', 'Gruppa blir gjort til en syndebukk. Når minoriteten får skylden for problemer, kan det forsterke negative holdninger og fordommer mot hele gruppa.', array['Forklarer at gruppa blir brukt som syndebukk ved å få skylden for problemer.', 'Knytter dette til at negative holdninger eller fordommer mot gruppa kan forsterkes.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'historie-og-filosofi-2', 'argumentasjon-og-kildearbeid', 'Filosofisk samtale, argumentasjon og kildearbeid', 'Hvordan du bruker filosofisk samtale til å utforske egne oppfatninger, analyserer argumenter og vurderer gyldighet og holdbarhet, gjenkjenner feilslutninger – og finner, leser og vurderer kilder av ulik art, også filosofiske og historiske originaltekster.', array[1, 2]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', '## Filosofisk samtale
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Filosofisk samtale', 'Felles utforsking av et åpent spørsmål for å forstå bedre.', 0),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Sokratisk metode', 'Å stille spørsmål for å avsløre motsigelser i tenkningen.', 1),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Premiss', 'En påstand som et argument bygger på.', 2),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Konklusjon', 'Det argumentet vil vise.', 3),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Gyldig argument', 'Konklusjonen følger logisk av premissene.', 4),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Holdbart argument', 'Gyldig og med sanne premisser.', 5),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Deduksjon', 'Fra det generelle til det spesielle – kan gi sikre konklusjoner.', 6),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Induksjon', 'Fra enkelttilfeller til en generell regel – gir sannsynlige konklusjoner.', 7),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Moteksempel', 'Et tilfelle som viser at en generell påstand ikke stemmer.', 8),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Sirkelargument', 'Konklusjonen står allerede i premissene.', 9),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Naturalistisk feilslutning', 'Å slutte fra hvordan noe er, til hvordan det bør være.', 10),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Appell til flertallet', 'Å mene noe er riktig fordi mange mener det.', 11),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Originaltekst', 'Teksten slik forfatteren skrev den, for eksempel Platons dialoger.', 12),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Nøkkelbegrep', 'Sentralt begrep som er avgjørende for å forstå en tekst.', 13),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'Tendens', 'At en kilde har interesse i å framstille noe på en bestemt måte.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q01', 'flervalg', 'Hva er målet med en filosofisk samtale?', array['Å vinne', 'Å forstå bedre og utvikle egne oppfatninger', 'Å bli enige raskt', 'Å bevise at læreren har rett']::text[], 1, 'Utforsking, ikke konkurranse.', true, true, 0),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q02', 'flervalg', 'Når er et argument gyldig?', array['Når konklusjonen følger logisk av premissene', 'Når premissene er sanne', 'Når mange er enige', 'Når det er kort']::text[], 0, 'Gyldighet handler om form.', true, true, 1),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q03', 'flervalg', '«Alle fugler kan fly. Pingviner er fugler. Altså kan pingviner fly.» Hva er galt?', array['Argumentet er ugyldig', 'Konklusjonen følger ikke', 'Argumentet er gyldig, men ikke holdbart fordi et premiss er usant', 'Ingenting']::text[], 2, 'Ikke alle fugler kan fly.', true, true, 2),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q04', 'flervalg', 'Hva kjennetegner induksjon?', array['Sikre konklusjoner', 'Fra det generelle til det spesielle', 'Ingen premisser', 'Fra enkelttilfeller til en generell regel']::text[], 3, 'Konklusjonen er bare sannsynlig.', true, true, 3),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q05', 'flervalg', 'Hva er naturalistisk feilslutning?', array['Å slutte fra hvordan noe er, til hvordan det bør være', 'Å angripe personen', 'Å gjenta konklusjonen', 'Å bruke to alternativer']::text[], 0, 'Naturlig betyr ikke riktig.', true, true, 4),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q06', 'flervalg', 'Hvem er den sokratiske metoden oppkalt etter?', array['Platon', 'Sokrates', 'Aristoteles', 'Kant']::text[], 1, 'Han stilte spørsmål i Athen.', true, true, 5),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q07', 'flervalg', 'Hva er et sirkelargument?', array['Et argument med mange premisser', 'Et induktivt argument', 'Et argument der konklusjonen allerede står i premissene', 'Et argument med moteksempel']::text[], 2, 'Det beviser ingenting nytt.', true, true, 6),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q08', 'flervalg', 'Hva er et godt første grep når du leser en originaltekst?', array['Å lese så fort som mulig', 'Å hoppe over vanskelige ord', 'Å bare lese konklusjonen', 'Å finne ut når, hvor og hvorfor teksten ble skrevet']::text[], 3, 'Konteksten hjelper forståelsen.', true, true, 7),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q09', 'flervalg', 'Hva er et moteksempel?', array['Et tilfelle som viser at en generell påstand ikke stemmer', 'Et eksempel som støtter påstanden', 'En konklusjon', 'En kilde']::text[], 0, 'Viktig verktøy i filosofisk samtale.', true, false, 8),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'q10', 'flervalg', '«Alle mener det, så det må være riktig.» Hvilken feilslutning er dette?', array['Stråmann', 'Appell til flertallet', 'Personangrep', 'Sirkelargument']::text[], 1, 'Flertallet kan ta feil.', true, false, 9),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'm01', 'sant-usant', 'Et gyldig argument kan ha usanne premisser.', array['Sant', 'Usant']::text[], 0, 'Da er det gyldig, men ikke holdbart.', false, true, 10),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'm02', 'sant-usant', 'Induktive argumenter gir alltid sikre konklusjoner.', array['Sant', 'Usant']::text[], 1, 'De gir sannsynlige konklusjoner.', false, true, 11),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'm03', 'sant-usant', 'I en filosofisk samtale er det en styrke å kunne endre mening.', array['Sant', 'Usant']::text[], 0, 'Målet er å forstå bedre.', false, true, 12),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'm04', 'sant-usant', 'Kilder som bekrefter det du allerede mener, trenger ikke vurderes kritisk.', array['Sant', 'Usant']::text[], 1, 'De bør vurderes særlig kritisk.', false, true, 13),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'm05', 'flervalg', 'Hva er en deduktiv slutning?', array['Fra enkelttilfeller til en regel', 'Fra det generelle til det spesielle', 'En gjetning', 'Et moteksempel']::text[], 1, 'Kan gi sikre konklusjoner.', false, true, 14),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'm06', 'flervalg', 'Hvilket spørsmål avklarer begreper?', array['«Hva mener du med frihet?»', '«Hvem vant?»', '«Hvor mye koster det?»', '«Når slutter timen?»']::text[], 0, 'Viktig i filosofisk samtale.', false, true, 15),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 'm07', 'flervalg', 'Hva bør du skille mellom når du leser en originaltekst?', array['Store og små bokstaver', 'Nye og gamle sider', 'Hva teksten sier og hva du selv mener', 'Forfatter og forlag']::text[], 2, 'Først forstå, så vurdere.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 's01', 'I et argument står det: «Alle X er Y. A er X. Derfor er A Y.» Hvilke utsagn er premissene, og hvilket utsagn er konklusjonen? Forklar kort hvilken rolle de har.', 'Premissene er «Alle X er Y» og «A er X». Konklusjonen er «A er Y», og den er det argumentet vil vise ved hjelp av premissene.', array['Identifiserer begge premissene.', 'Identifiserer konklusjonen.', 'Forklarer at premissene begrunner eller støtter konklusjonen.']::text[], 0),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 's02', 'Vurder argumentet: «Alle mennesker er dødelige. Sokrates er et menneske. Derfor er Sokrates dødelig.» Forklar hvorfor argumentet både er gyldig og holdbart.', 'Argumentet er gyldig fordi konklusjonen følger logisk av premissene. Det er holdbart fordi det også er gyldig, og premissene er sanne.', array['Forklarer at gyldigheten handler om at konklusjonen følger av premissene.', 'Forklarer at holdbarhet krever både gyldighet og sanne premisser.']::text[], 1),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 's03', 'Sammenlign deduksjon og induksjon. Forklar hvilken retning hver av dem går, og hva det betyr for hvor sikker konklusjonen kan være.', 'Deduksjon går fra det generelle til det spesielle og kan gi en sikker konklusjon. Induksjon går fra enkelttilfeller til en generell regel, så konklusjonen er sannsynlig, men ikke sikker.', array['Beskriver deduksjon som en slutning fra det generelle til det spesielle.', 'Beskriver induksjon som en slutning fra enkelttilfeller til en generell regel.', 'Skiller mellom sikker konklusjon ved deduksjon og sannsynlig konklusjon ved induksjon.']::text[], 2),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 's04', 'En elev sier: «Vi bør noen ganger stille spørsmål ved skolens regler.» En annen svarer: «Du mener altså at det ikke bør finnes noen regler.» Hvilken feilslutning bruker den andre eleven, og hva er galt med svaret?', 'Den andre eleven bruker en stråmann. Svaret forvrenger det første elevens syn ved å gjøre «stille spørsmål ved noen regler» om til at ingen regler bør finnes.', array['Identifiserer stråmann.', 'Forklarer at det første elevens syn blir forvrengt eller overdrevet.']::text[], 3),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 's05', 'To elever er uenige om det noen gang kan være riktig å bryte loven. Den ene gjentar bare standpunktet sitt. Beskriv to grep fra en filosofisk samtale som kan hjelpe dem til å forstå spørsmålet og hverandres syn bedre.', 'De kan be hverandre begrunne standpunktene og avklare hva de mener med «riktig». De kan også undersøke eksempler eller konsekvenser, slik at samtalen handler om å forstå spørsmålet bedre, ikke om å vinne.', array['Nevner minst to relevante grep, som å be om begrunnelser, avklare begreper, undersøke eksempler eller konsekvenser.', 'Knytter grepene til å forstå standpunktene eller spørsmålet bedre.']::text[], 4),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 's06', 'En elev leser en originaltekst med gammelt språk og en tankegang som er uvant. Forklar hvorfor teksten kan være krevende, og beskriv to måter eleven kan arbeide med innholdet på. Ikke bruk det å finne ut når, hvor og hvorfor teksten ble skrevet som et av grepene.', 'Teksten kan være krevende fordi språket er gammelt og tankegangen ukjent. Eleven kan notere nøkkelbegreper og formulere hovedpåstanden og argumentene med egne ord, samtidig som hen skiller mellom det teksten sier og egne meninger.', array['Forklarer at gammelt språk og/eller ukjent tankegang kan gjøre teksten vanskelig.', 'Nevner minst to relevante arbeidsmåter, som å notere nøkkelbegreper, formulere hovedpåstanden og argumentene med egne ord eller skille tekstens syn fra eget syn.']::text[], 5),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 's07', 'Du finner et anonymt innlegg på nett som støtter noe du allerede mener. Innlegget viser ikke til andre kilder. Beskriv to kildekritiske undersøkelser du bør gjøre, og forklar hva de kan hjelpe deg med å vurdere.', 'Jeg bør undersøke opphavet og formålet, blant annet om avsenderen kan ha en tendens til å framstille saken på en bestemt måte. Jeg bør også sammenligne innlegget med andre kilder for å vurdere hvor troverdig og relevant det er.', array['Nevner minst to relevante kildekritiske undersøkelser, som opphav, formål, troverdighet, relevans, tendens eller sammenligning med andre kilder.', 'Forklarer hvordan undersøkelsene kan bidra til å vurdere kilden eller påstandene.']::text[], 6),
  ('historie-og-filosofi-2:argumentasjon-og-kildearbeid', 's08', 'En elev sier først: «En regel må alltid følges.» Senere sier eleven: «Det kan være riktig å bryte en regel for å hindre skade.» Skriv et oppfølgingsspørsmål som kan undersøke om eleven ser en konflikt mellom påstandene, og forklar hva spørsmålet avklarer.', 'Du kan spørre: «Mener du at regelen må følges også når det hindrer skade?» Spørsmålet avklarer om eleven mener at den første påstanden gjelder uten unntak, eller om den andre situasjonen kan være et unntak.', array['Stiller et spørsmål som undersøker forholdet mellom de to påstandene.', 'Forklarer at spørsmålet avklarer om eleven mener den første påstanden gjelder uten unntak, eller om eleven godtar et unntak.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'historie-og-filosofi-2', 'vitenskap-og-pseudovitenskap', 'Vitenskap, pseudovitenskap, desinformasjon og konspirasjonsteorier', 'Hva som skiller vitenskap fra pseudovitenskap – demarkasjonsproblemet, Poppers falsifiserbarhetskriterium og kjennetegn ved god forskning – og hvorfor desinformasjon og konspirasjonsteorier sprer seg, og hvilke konsekvenser de kan få for enkeltmennesker og demokratiet.', array[3]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', '## Demarkasjonsproblemet
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Demarkasjonsproblemet', 'Spørsmålet om hva som skiller vitenskap fra pseudovitenskap.', 0),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Pseudovitenskap', 'Påstander som gir seg ut for å være vitenskap uten å følge vitenskapens krav.', 1),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Karl Popper', 'Filosof som mente vitenskapelige teorier må være falsifiserbare.', 2),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Falsifiserbarhet', 'At det må være mulig å tenke seg observasjoner som viser at teorien er feil.', 3),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Etterprøvbarhet', 'At andre kan gjenta undersøkelsen.', 4),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Fagfellevurdering', 'Andre forskere vurderer arbeidet før publisering.', 5),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Selvkorrigering', 'At vitenskapen endrer teorier når nye funn krever det.', 6),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Konsensus', 'Bred enighet i forskningen basert på mange studier.', 7),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Anekdote', 'Enkelthistorie som ikke gir systematisk bevis.', 8),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Feilinformasjon', 'Uriktig informasjon spredt uten vilje til å lure.', 9),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Desinformasjon', 'Bevisst falsk informasjon for å oppnå mål.', 10),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Konspirasjonsteori', 'Påstand om at hendelser styres av en hemmelig, mektig gruppe.', 11),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Syndebukk', 'Gruppe som får skylden for problemer.', 12),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Faktasjekk', 'Kontroll av om påstander er sanne.', 13),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'Polarisering', 'At grupper beveger seg lenger fra hverandre.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q01', 'flervalg', 'Hva er demarkasjonsproblemet?', array['Spørsmålet om hvor grensene mellom land går', 'Spørsmålet om hva som skiller vitenskap fra pseudovitenskap', 'Et matematisk problem', 'Et problem i kildekritikk alene']::text[], 1, 'Et sentralt spørsmål i vitenskapsfilosofien.', true, true, 0),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q02', 'flervalg', 'Hva mente Popper kjennetegner en vitenskapelig teori?', array['At den er falsifiserbar', 'At den kan forklare alt', 'At den er bevist for alltid', 'At mange tror på den']::text[], 0, 'Den må kunne vise seg å være feil.', true, true, 1),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q03', 'flervalg', 'Hvorfor er en teori som forklarer alt, ikke vitenskapelig ifølge Popper?', array['Fordi den er for enkel', 'Fordi den er for gammel', 'Fordi ingen observasjon kan motbevise den', 'Fordi den er matematisk']::text[], 2, 'Den kan ikke testes.', true, true, 2),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q04', 'flervalg', 'Hva er fagfellevurdering?', array['At journalister vurderer forskning', 'At publikum stemmer', 'At staten godkjenner forskning', 'At andre forskere vurderer arbeidet før publisering']::text[], 3, 'Et kvalitetskrav i vitenskapen.', true, true, 3),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q05', 'flervalg', 'Hva skiller desinformasjon fra feilinformasjon?', array['Desinformasjon er bevisst falsk', 'Desinformasjon er alltid sann', 'Det er ingen forskjell', 'Feilinformasjon er bevisst']::text[], 0, 'Hensikten er avgjørende.', true, true, 4),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q06', 'flervalg', 'Hva er et kjennetegn ved konspirasjonsteorier?', array['De bygger på fagfellevurdert forskning', 'Mangel på bevis tolkes som bevis på at noen skjuler noe', 'De endres etter nye funn', 'De sier at mye skjer tilfeldig']::text[], 1, 'Derfor er de vanskelige å motbevise.', true, true, 5),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q07', 'flervalg', 'Hva er et kjennetegn ved pseudovitenskap?', array['Etterprøvbarhet', 'Selvkorrigering', 'Avhengighet av anekdoter og motstand mot kritikk', 'Fagfellevurdering']::text[], 2, 'Bruker ofte vitenskapelige ord uten innhold.', true, true, 6),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q08', 'flervalg', 'Hvilken konsekvens kan konspirasjonsteorier om valgfusk få?', array['Høyere valgdeltakelse', 'Mer tillit', 'Bedre valg', 'Svekket tillit til valg og i verste fall vold']::text[], 3, 'En trussel mot demokratiet.', true, true, 7),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q09', 'flervalg', 'Kan vitenskapen bevise at en teori er endelig sann?', array['Nei, men teorier som har overlevd mange tester, er vel begrunnet', 'Ja, alltid', 'Ja, med én studie', 'Nei, vitenskap er meninger']::text[], 0, 'Ifølge Popper.', true, false, 8),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'q10', 'flervalg', 'Hvorfor kan konspirasjonsteorier virke tiltrekkende?', array['De er alltid sanne', 'De gir enkle forklaringer, kontroll og fellesskap', 'De er vitenskapelige', 'De er kjedelige']::text[], 1, 'Og spiller på mistillit.', true, false, 9),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'm01', 'sant-usant', 'Mange konspirasjonsteorier har vært antisemittiske.', array['Sant', 'Usant']::text[], 0, 'De gjør jøder til syndebukker.', false, true, 10),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'm02', 'sant-usant', 'Én enkelt studie er nok til å skape vitenskapelig konsensus.', array['Sant', 'Usant']::text[], 1, 'Konsensus bygger på mange studier.', false, true, 11),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'm03', 'sant-usant', 'Stater kan bruke desinformasjon for å påvirke valg i andre land.', array['Sant', 'Usant']::text[], 0, 'Og skape splid.', false, true, 12),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'm04', 'sant-usant', 'Vitenskapen endrer aldri teoriene sine.', array['Sant', 'Usant']::text[], 1, 'Selvkorrigering er et kjennetegn.', false, true, 13),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'm05', 'flervalg', 'Hva er et eksempel på pseudovitenskap?', array['Evolusjonsteorien', 'Astrologi', 'Gravitasjonsteorien', 'Celleteorien']::text[], 1, 'Påstandene kan ikke testes på en vitenskapelig måte.', false, true, 14),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'm06', 'flervalg', 'Hvilken helsekonsekvens kan myter om vaksiner få?', array['At færre vaksinerer seg og sykdommer kommer tilbake', 'At flere blir friske', 'At vaksiner blir billigere', 'Ingen konsekvenser']::text[], 0, 'Et konkret eksempel.', false, true, 15),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 'm07', 'flervalg', 'Hva kan hjelpe mot desinformasjon?', array['Å dele alt raskt', 'Å stole på anonyme kilder', 'Kildekritikk og faktasjekk', 'Å unngå all informasjon']::text[], 2, 'Og kunnskap om vitenskapelig metode.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 's01', 'En vitenskapelig teori blir utfordret av nye funn. Forklar hva selvkorrigering betyr i denne situasjonen.', 'Selvkorrigering betyr at vitenskapelige teorier endres når nye funn krever det. Forskere holder altså ikke fast ved en teori uavhengig av hva undersøkelsene viser.', array['Forklarer at teorier kan endres på grunn av nye funn.', 'Viser at vitenskapen tar hensyn til ny kunnskap i stedet for å fastholde teorien uansett.']::text[], 0),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 's02', 'En person forteller at homeopati hjalp mot plagene deres. Forklar hvorfor denne historien alene ikke er systematisk vitenskapelig belegg, og nevn hva som må til for at andre skal kunne undersøke påstanden.', 'En enkelt persons historie er en anekdote og viser ikke alene at behandlingen virker. Påstanden bør undersøkes systematisk på en måte som andre kan gjenta og etterprøve.', array['Identifiserer historien som en anekdote eller enkelthistorie, ikke systematisk belegg.', 'Nevner systematisk undersøkelse eller at andre må kunne gjenta undersøkelsen.']::text[], 1),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 's03', 'Forskere undersøker det samme spørsmålet i mange ulike studier. Forklar hvordan resultatene kan danne en vitenskapelig konsensus, og hvorfor én studie alene ikke er nok til å etablere den.', 'Konsensus er bred enighet som bygger på resultater fra mange studier. Én studie alene gir ikke et slikt grunnlag, fordi konsensus ikke bygger på ett enkelt resultat.', array['Forklarer at konsensus er bred enighet basert på mange studier.', 'Forklarer at én studie alene ikke gir grunnlag for konsensus.']::text[], 2),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 's04', 'En stat lager med vilje en falsk video og sprer den for å påvirke et valg i et annet land. Forklar hvordan dette bør klassifiseres, og hva formålet med spredningen er.', 'Dette er desinformasjon, fordi den falske videoen spres bevisst. Formålet er politisk: å påvirke valget i et annet land.', array['Klassifiserer det som desinformasjon fordi informasjonen er falsk og spres med vilje.', 'Knytter formålet til politisk påvirkning av valget.']::text[], 3),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 's05', 'Forklar hvordan sosiale medier og kunstig intelligens kan bidra til polarisering når falske videoer og nyheter spres.', 'Sosiale medier og kunstig intelligens gjør det lett å spre falske videoer og nyheter raskt. Det kan bidra til at folk lever i ulike virkeligheter og slutter å snakke sammen, altså polarisering.', array['Forklarer at sosiale medier og kunstig intelligens gjør rask spredning av falskt innhold lettere.', 'Knytter dette til at grupper får ulike virkelighetsbilder eller slutter å snakke sammen.']::text[], 4),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 's06', 'En teori hevder at en mektig gruppe skjuler sannheten fordi ingen bevis er funnet, og at kritikere derfor må være med på sammensvergelsen. Forklar hvordan teorien tolker mangelen på bevis og kritikken den møter.', 'Teorien tolker mangelen på bevis som tegn på at noen skjuler sannheten. Kritikere blir framstilt som del av sammensvergelsen, slik at kritikken ikke får svekke teorien.', array['Forklarer at mangel på bevis tolkes som bevis på skjuling.', 'Forklarer at kritikere blir sett på som del av sammensvergelsen.']::text[], 5),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 's07', 'En konspirasjonsteori gir en gruppe skylden for mange problemer. Forklar hva det betyr at gruppen blir gjort til en syndebukk, og nevn en mulig konsekvens av slike teorier.', 'Å gjøre gruppen til en syndebukk betyr at den får skylden for problemer. Konspirasjonsteorier kan bidra til hat og i verste fall rettferdiggjøre vold mot grupper.', array['Forklarer at en syndebukk er en gruppe som får skylden for problemer.', 'Nevner hat eller vold mot grupper som en mulig konsekvens.']::text[], 6),
  ('historie-og-filosofi-2:vitenskap-og-pseudovitenskap', 's08', 'En venn deler en oppsiktsvekkende påstand om at en hemmelig gruppe styrer viktige hendelser. Beskriv en måte du kan undersøke påstanden på og en måte du kan snakke med vennen om den på.', 'Jeg kan faktasjekke påstanden og undersøke om den bygger på vitenskapelig metode. Jeg kan også snakke åpent og respektfullt med vennen, i stedet for å avvise personen.', array['Foreslår en faglig relevant måte å undersøke påstanden på, for eksempel faktasjekk eller kunnskap om vitenskapelig metode.', 'Foreslår en åpen og respektfull samtale.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 'historie-og-filosofi-2', 'metode-perspektiv-og-erkjennelse', 'Metode, perspektiv og erkjennelse', 'Hvordan vi søker kunnskap gjennom valg av metoder, teorier, perspektiver og kilder – positivisme og hermeneutikk, teoriladede observasjoner, Kuhns paradigmer og feministiske og postkoloniale perspektiver – og hvordan valgene påvirker hva vi ser, leter etter og forstår.', array[4]::int[], 2, 'utkast', '{}'::text[], false, now())
