insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 's01', 'Sammenlign positivismen og hermeneutikken: Hva legger hver tradisjon mest vekt på når kunnskap utvikles?', 'Positivismen legger vekt på observerbare fakta, målinger og lover. Hermeneutikken legger vekt på å tolke tekster og handlinger ut fra sammenhenger og forforståelse.', array['Forklarer at positivismen vektlegger observerbare fakta eller målinger.', 'Forklarer at hermeneutikken vektlegger tolkning av mening eller sammenheng.']::text[], 0),
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 's02', 'En historiker tolker først enkelte setninger i en dagbok og danner seg så et inntrykk av dagboken som helhet. Når helheten endrer forståelsen av setningene, leser historikeren dem på nytt. Forklar hvordan dette viser den hermeneutiske sirkelen.', 'Den hermeneutiske sirkelen innebærer at delene forstås ut fra helheten, mens helheten forstås ut fra delene. Derfor kan historikerens forståelse av setningene og dagboken som helhet endres mens hun tolker.', array['Får fram vekslingen mellom forståelse av deler og helhet.', 'Forklarer at forståelsen kan endres gjennom denne vekslingen.']::text[], 1),
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 's03', 'Du skal undersøke både hvor utbredt en mening er, og hvordan mennesker opplever den. Sammenlign kvantitative og kvalitative metoder, og forklar hvilken type spørsmål hver metode passer best til.', 'Kvantitative metoder, som statistikk og målinger, kan gi oversikt over hvor utbredt en mening er og vise mønstre. Kvalitative metoder, som intervjuer, kan gi dybde i hvordan mennesker opplever meningen, men resultatene er vanskeligere å generalisere fra.', array['Knytter kvantitative metoder til oversikt, målinger eller mønstre.', 'Knytter kvalitative metoder til dybde eller opplevelser, og får fram at det kan være vanskelig å generalisere.']::text[], 2),
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 's04', 'Ifølge Kuhn arbeider forskere i normalvitenskap innenfor et etablert paradigme. Forklar hvordan avvik kan føre fra normalvitenskap til et paradigmeskifte.', 'I normalvitenskap løser forskerne oppgaver innenfor paradigmet. Hvis det samler seg for mange avvik som paradigmet ikke håndterer, kan det skje en vitenskapelig revolusjon der paradigmet erstattes av et nytt.', array['Forklarer at normalvitenskap foregår innenfor et etablert paradigme.', 'Får fram at mange avvik kan utløse en revolusjon og føre til at paradigmet erstattes.']::text[], 3),
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 's05', 'En utstilling om fortiden handler nesten bare om konger og statsmenn. Forklar hvordan et nedenfra-perspektiv kunne endret hva utstillingen viser.', 'Et nedenfra-perspektiv ville lagt mer vekt på vanlige mennesker og livene deres, ikke bare på makthavere. Det kunne gjort erfaringer og handlinger som ellers ble oversett, synlige i utstillingen.', array['Får fram at perspektivet retter oppmerksomheten mot vanlige mennesker.', 'Forklarer at dette gir plass til erfaringer eller handlinger som ikke kommer fram når fokuset bare er på makthavere.']::text[], 4),
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 's06', 'En historiker undersøker hvordan en politisk beslutning påvirket mennesker, men bruker bare offentlige dokumenter. Forklar en mulig svakhet ved dette kildevalget, og foreslå hvordan historikeren kan få fram flere stemmer.', 'Offentlige dokumenter alene kan gi et begrenset bilde av hvem som ble påvirket, og hvilke erfaringer som kommer fram. Historikeren kan søke etter andre kilder som gir plass til stemmene til mennesker som ikke er representert i dokumentene.', array['Forklarer at kildevalget kan gjøre at noen erfaringer eller stemmer mangler.', 'Foreslår å utvide kildegrunnlaget for å få fram flere perspektiver eller stemmer.']::text[], 5),
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 's07', 'En forsker legger fram en konklusjon, men sier ikke hvilke kilder eller metoder den bygger på. Forklar hvorfor dette gjør konklusjonen vanskeligere å vurdere, og nevn én måte forskeren kan styrke begrunnelsen på.', 'Uten åpenhet om kilder og metoder er det vanskelig å vurdere hvordan forskeren har kommet fram til konklusjonen. Forskeren kan gjøre valgene tydelige og prøve konklusjonen mot nye kilder eller andre perspektiver.', array['Forklarer at åpenhet om valg gjør det mulig å vurdere hvordan konklusjonen er begrunnet.', 'Nevner en relevant måte å prøve eller styrke konklusjonen på, for eksempel nye kilder eller andre perspektiver.']::text[], 6),
  ('historie-og-filosofi-2:metode-perspektiv-og-erkjennelse', 's08', 'En forsker ønsker å være objektiv. Forklar hva objektivitet betyr som ideal, og hvorfor forskeren likevel bør være bevisst på hvordan egne valg påvirker det som blir synlig.', 'Objektivitet er idealet om at forskeren skal være nøytral. Samtidig påvirker valg av spørsmål, metoder, teorier og perspektiv hva forskeren legger merke til, så forskeren bør være åpen om disse valgene.', array['Forklarer objektivitet som et ideal om nøytralitet.', 'Får fram at forskerens valg påvirker hva som blir synlig, og at valgene derfor bør gjøres bevisste eller åpne.']::text[], 7);
