insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q01', 'flervalg', 'Hva er autonomi?', array['Å være styrt av andre', 'Selvstyre – å styre eget liv ut fra egne vurderinger', 'Å ha mye penger', 'Å bo alene']::text[], 1, 'Sentralt hos Kant.', true, true, 0),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q02', 'flervalg', 'Hva er negativ frihet?', array['Frihet fra tvang', 'Frihet til å gjøre gode ting', 'Mangel på frihet', 'Frihet som er ulovlig']::text[], 0, 'Isaiah Berlins skille.', true, true, 1),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q03', 'flervalg', 'En person har lov til å studere, men har ikke råd. Hva mangler hen?', array['Negativ frihet', 'Autonomi alltid', 'Positiv frihet', 'Ansvar']::text[], 2, 'Reelle muligheter.', true, true, 2),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q04', 'flervalg', 'Hva mente Sartre med ond tro?', array['Å tro på Gud', 'Å være ond', 'Å stole på andre', 'Å late som man ikke har valg']::text[], 3, 'Vi må ta ansvar for valgene våre.', true, true, 3),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q05', 'flervalg', 'Hva mente Epikur var det gode liv?', array['Fravær av smerte og indre ro', 'Luksus og fester', 'Makt', 'Berømmelse']::text[], 0, 'Enkle gleder og vennskap.', true, true, 4),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q06', 'flervalg', 'Hva lærer stoikerne?', array['Å søke mest mulig nytelse', 'Å skille mellom det vi kan og ikke kan påvirke', 'Å unngå alle andre', 'Å samle rikdom']::text[], 1, 'Og møte livet med sinnsro.', true, true, 5),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q07', 'flervalg', 'Hva viser Nozicks erfaringsmaskin ifølge Nozick?', array['At nytelse er det eneste som teller', 'At maskiner er gode', 'At vi vil gjøre og være noe, ikke bare føle oss bra', 'At lykke er umulig']::text[], 2, 'Et argument mot hedonisme.', true, true, 6),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q08', 'flervalg', 'Hva finner lykkeforskningen betyr mest for tilfredshet?', array['Bare penger', 'Berømmelse', 'Makt', 'Relasjoner, helse, mening og mestring']::text[], 3, 'Når grunnleggende behov er dekket.', true, true, 7),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q09', 'flervalg', 'Hva er eudaimonia?', array['Aristoteles'' begrep om det gode liv', 'En gresk gud', 'En type nytelse', 'En stoisk øvelse']::text[], 0, 'Å realisere sine evner og leve dydig.', true, false, 8),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'q10', 'flervalg', 'Hva mente Mill med at det er bedre å være et misfornøyd menneske enn en fornøyd gris?', array['At griser er lykkeligere', 'At høyere nytelser er mer verdifulle enn lavere', 'At misnøye er målet', 'At dyr ikke har verdi']::text[], 1, 'Kvalitet, ikke bare mengde, teller.', true, false, 9),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'm01', 'sant-usant', 'Pasienter har rett til å nekte behandling på grunn av prinsippet om autonomi.', array['Sant', 'Usant']::text[], 0, 'Autonomi i helsevesenet.', false, true, 10),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'm02', 'sant-usant', 'Epikur mente at luksus og overflod gir det beste livet.', array['Sant', 'Usant']::text[], 1, 'Han vektla enkle gleder og indre ro.', false, true, 11),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'm03', 'sant-usant', 'Mange valgmuligheter kan også oppleves som et press.', array['Sant', 'Usant']::text[], 0, 'Valgets byrde.', false, true, 12),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'm04', 'sant-usant', 'Sartre mente vi kan skylde på samfunnet for alle våre valg.', array['Sant', 'Usant']::text[], 1, 'Han mente vi har fullt ansvar.', false, true, 13),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'm05', 'flervalg', 'Hvem skilte mellom negativ og positiv frihet?', array['Kant', 'Isaiah Berlin', 'Mill', 'Epikur']::text[], 1, 'I 1958.', false, true, 14),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'm06', 'flervalg', 'Hvilken politisk retning legger ofte vekt på positiv frihet?', array['Sosialdemokrati', 'Anarkisme', 'Enevelde', 'Fascisme']::text[], 0, 'Gjennom skole og velferd.', false, true, 15),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 'm07', 'flervalg', 'Hva betyr heteronom?', array['Selvstyrt', 'Fri', 'Styrt utenfra av lyster eller autoriteter', 'Lykkelig']::text[], 2, 'Motsatsen til autonom.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 's01', 'Kant mente at mennesker kan være autonome fordi de har fornuft. Forklar hvordan fornuft henger sammen med autonomi, og sammenlign dette med å være styrt av lyster eller autoriteter.', 'For Kant er et menneske autonomt når det bruker fornuften til å gi seg selv moralske lover. Den som bare følger lyster eller autoriteter, er heteronom fordi styringen kommer utenfra.', array['Forklarer at autonomi innebærer å styre seg selv ved hjelp av fornuft.', 'Skiller dette fra å være styrt av lyster eller autoriteter utenfra.']::text[], 0),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 's02', 'Isaiah Berlin skilte mellom negativ frihet, frihet fra tvang, og positiv frihet, reelle muligheter og evne til å styre eget liv. Forklar hvordan liberale og sosialdemokrater ofte vektlegger disse frihetsformene forskjellig.', 'Liberale vektlegger ofte negativ frihet, altså at andre ikke skal hindre individet. Sosialdemokrater legger også vekt på positiv frihet, for eksempel at skole og velferd kan gi mennesker reelle muligheter.', array['Knytter liberal vektlegging til negativ frihet eller frihet fra tvang.', 'Knytter sosialdemokratisk vektlegging til positiv frihet og reelle muligheter, gjerne gjennom skole eller velferd.']::text[], 1),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 's03', 'En pasient får informasjon om en behandling og velger å nekte den. Forklar hvordan pasientens valg henger sammen med autonomi i helsevesenet.', 'Valget uttrykker pasientens autonomi, fordi pasienten skal kunne styre eget liv ut fra egne vurderinger. I helsevesenet innebærer dette en rett til å samtykke til eller nekte behandling.', array['Forklarer at pasientens eget valg er et uttrykk for selvstyre eller egne vurderinger.', 'Nevner retten til å nekte behandling eller samtykke til behandling.']::text[], 2),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 's04', 'En person sier at oppveksten og miljøet gjorde valgene hans uunngåelige. Forklar hvordan Sartre ville utfordret denne forklaringen, og hvorfor arv, miljø og samfunn likevel kan ha betydning for hvor ansvarlig personen er.', 'Sartre ville ment at personen ikke kan skylde valgene sine på omgivelsene, fordi vi må ta ansvar for valgene våre; å late som vi ikke har valg er ond tro. Samtidig kan arv, miljø og samfunn begrense handlingsrommet, og det må tas med i vurderingen av ansvar.', array['Får fram at Sartre legger ansvar på mennesket for valgene det tar, og knytter det til ond tro eller det å late som man ikke har valg.', 'Forklarer at arv, miljø eller samfunn kan begrense handlingsrommet og dermed må tas med når ansvar vurderes.']::text[], 3),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 's05', 'En person søker luksus og sterke opplevelser for å få det godt. En annen foretrekker enkle gleder, vennskap og indre ro, og forsøker å konsentrere seg om det han kan påvirke. Sammenlign hvilken tilnærming som passer med Epikur, og hvilken som passer med stoikerne.', 'Den andre personens vekt på enkle gleder, vennskap og indre ro passer med Epikur, som så fravær av smerte og indre ro som viktig. Konsentrasjonen om det personen kan påvirke, passer med stoikerne, som skiller mellom det vi kan og ikke kan påvirke.', array['Knytter Epikur til enkle gleder, fravær av smerte eller indre ro, framfor luksus.', 'Knytter stoikerne til skillet mellom det man kan og ikke kan påvirke.']::text[], 4),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 's06', 'En elev utvikler evnene sine, øver på å handle dydig og samarbeider godt med andre. Bruk Aristoteles’ syn på det gode liv til å forklare hvorfor dette kan være et eksempel på eudaimonia.', 'For Aristoteles handler eudaimonia om å realisere evnene sine og leve dydig. Elevens utvikling av evner og gode handlinger sammen med andre passer derfor med hans syn på det gode liv.', array['Knytter eudaimonia til å realisere eller utvikle egne evner.', 'Får fram at et dydig liv i fellesskap med andre er viktig hos Aristoteles.']::text[], 5),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 's07', 'Mina mener at livet ikke har en ferdig mening som hun bare kan finne, og at hun må forme mening gjennom egne valg. Forklar hvordan dette synet henger sammen med eksistensialismen.', 'Eksistensialistene mener at meningen ikke er gitt på forhånd, men er noe vi må skape selv. Minas syn på at hun former mening gjennom egne valg, passer derfor med eksistensialismen.', array['Forklarer at eksistensialistene mener at mening må skapes av mennesket selv.', 'Knytter dette til Minas egne valg eller handlinger.']::text[], 6),
  ('historie-og-filosofi-2:frihet-autonomi-og-det-gode-liv', 's08', 'Mange unge opplever press om å velge riktig utdanning, jobb og livsstil, selv om de også verdsetter friheten til å velge. Forklar hvorfor dette kan kalles valgets byrde, og hvilken motsetning det viser i dagens samfunn.', 'Det kalles valgets byrde fordi mange valgmuligheter også kan føre til press om å velge riktig. Situasjonen viser en motsetning mellom frihet og selvrealisering på den ene siden og behovet for fellesskap, ansvar og ro på den andre.', array['Forklarer at mange valgmuligheter kan skape press eller forventning om å velge riktig.', 'Viser en spenning mellom frihet eller selvrealisering og fellesskap, ansvar eller ro.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('historie-og-filosofi-2:etiske-sporsmal-i-nyere-tid', 'historie-og-filosofi-2', 'etiske-sporsmal-i-nyere-tid', 'Etiske og eksistensielle spørsmål i nyere tid', 'Temaer fra nyere tid som illustrerer etiske og eksistensielle spørsmål – holocaust og Arendts «ondskapens banalitet», Milgrams lydighetsforsøk, atombomben, 22. juli, pandemien, klimakrisen, kunstig intelligens og debatten om aktiv dødshjelp.', array[8]::int[], 6, 'utkast', '{}'::text[], false, now())
