  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 's01', 'Forklar forskjellen på stoffmengde og masse. Ta med hva slags enhet som brukes for hver av dem.', 'Stoffmengde beskriver hvor mange mol det er av et stoff, mens masse beskriver hvor mye stoffet veier. Stoffmengde måles i mol og masse i gram.', array['Forklarer at stoffmengde er antall mol, mens masse er hvor mye stoffet veier.', 'Knytter mol til stoffmengde og gram til masse.']::text[], 0),
  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 's02', 'Du undersøker hvordan temperaturen påvirker reaksjonsfarten. Oppgi den uavhengige variabelen, den avhengige variabelen og én faktor du bør holde konstant.', 'Temperaturen er den uavhengige variabelen, og reaksjonsfarten er den avhengige variabelen. For eksempel bør konsentrasjonen holdes konstant.', array['Identifiserer temperaturen som uavhengig variabel og reaksjonsfarten som avhengig variabel.', 'Oppgir en relevant faktor som bør holdes konstant, for eksempel konsentrasjonen.']::text[], 1),
  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 's03', 'I et forsøk skal du bruke et flyktig kjemikalie. Beskriv hvor du bør arbeide, og forklar hvorfor.', 'Jeg bør arbeide i et avtrekkskap, som suger ut flyktige eller giftige gasser. Jeg bør også bruke verneutstyr når det trengs.', array['Sier at forsøket bør gjøres i avtrekkskap.', 'Forklarer at avtrekkskapet suger ut flyktige eller giftige gasser.']::text[], 2),
  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 's04', 'En atommodell viser atomene som kuler. Forklar hvorfor en slik modell ikke er en fullstendig beskrivelse av virkeligheten, og hva modellen likevel kan brukes til.', 'En modell er en forenkling og viser derfor ikke alle sider ved virkeligheten. Den kan likevel brukes som et bilde som hjelper oss å beskrive atomer.', array['Forklarer at modellen er forenklet og ikke gjengir hele virkeligheten.', 'Beskriver at modellen likevel kan hjelpe oss med å forstå eller beskrive atomer.']::text[], 3),
  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 's05', 'Forklar forskjellen på fagfellevurdering og å gjenta et forsøk som måter å kontrollere forskning på.', 'Ved fagfellevurdering vurderer andre forskere arbeidet før det publiseres. Når andre gjentar forsøket, undersøker de om resultatene holder.', array['Forklarer at fagfellevurdering innebærer at andre forskere vurderer arbeidet før publisering.', 'Forklarer at gjentakelse undersøker om resultatene kan gjenfinnes eller holder.']::text[], 4),
  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 's06', 'Tre målinger er 4,8 g, 5,0 g og 5,2 g. Regn ut gjennomsnittet. Vis det viktigste regnetrinnet.', 'Gjennomsnittet er (4,8 + 5,0 + 5,2) / 3 = 5,0 g.', array['Legger sammen målingene og deler summen på 3.', 'Oppgir gjennomsnittet 5,0 g.']::text[], 5),
  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 's07', 'En kjent verdi er 10,0 g, og målingen din er 9,5 g. Regn ut prosentvis avvik med formelen |måling − kjent verdi| / kjent verdi · 100 %. Vis det viktigste regnetrinnet.', 'Prosentvis avvik er |9,5 − 10,0| / 10,0 · 100 % = 5 %.', array['Bruker forskjellen mellom målingen og den kjente verdien, delt på den kjente verdien.', 'Regner ut og oppgir prosentvis avvik på 5 %.']::text[], 6),
  ('kjemi-2:forsok-modeller-og-kunnskapsutvikling', 's08', 'Du gjentar en måling flere ganger og får resultater som ligger tett samlet, men som alle er et stykke fra den kjente verdien. Hva sier dette om presisjonen og nøyaktigheten?', 'Resultatene har god presisjon fordi de ligger tett samlet. Nøyaktigheten er dårligere fordi resultatene er et stykke fra den kjente verdien.', array['Knytter tett samlet resultatene til god presisjon.', 'Knytter avstanden fra den kjente verdien til dårligere nøyaktighet.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('kjemi-2:redoks-og-elektrokjemi', 'kjemi-2', 'redoks-og-elektrokjemi', 'Redoksreaksjoner og elektrokjemi', 'Oksidasjon og reduksjon, oksidasjonstall og balansering av redoksligninger, galvaniske celler og standard reduksjonspotensial, cellespenning og energi, batterier og brenselceller, elektrolyse med Faradays lov og korrosjon.', array[4]::int[], 1, 'utkast', '{}'::text[], false, now())
