  ('kjemi-2:redoks-og-elektrokjemi', 'ΔG° = −zFE°', 'Sammenhengen mellom cellespenning og fri energi.', 11),
  ('kjemi-2:redoks-og-elektrokjemi', 'Faradays konstant', 'F = 96 485 C/mol – ladningen til ett mol elektroner.', 12),
