insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('kjemi-2:kromatografi', 'q01', 'flervalg', 'Hva er den mobile fasen i kromatografi?', array['Fasen som står stille', 'Fasen som beveger seg', 'Prøven', 'Platen']::text[], 1, 'En væske eller gass.', true, true, 0),
  ('kjemi-2:kromatografi', 'q02', 'flervalg', 'Et stoff har vandret 3,0 cm og løsemiddelfronten 6,0 cm. Hva er Rf?', array['0,50', '2,0', '3,0', '0,33']::text[], 0, '3,0 / 6,0.', true, true, 1),
  ('kjemi-2:kromatografi', 'q03', 'flervalg', 'Hvilke stoffer vandrer kortest på en polar silikaplate?', array['Upolare stoffer', 'Gasser', 'Polare stoffer', 'Alle vandrer like langt']::text[], 2, 'De bindes sterkt til silika.', true, true, 2),
  ('kjemi-2:kromatografi', 'q04', 'flervalg', 'Hva tyder det på at en prøve gir én flekk på TLC?', array['At det er mange stoffer', 'At forsøket mislyktes', 'At løsemiddelet var feil', 'At stoffet er rent']::text[], 3, 'Flere flekker tyder på urenheter.', true, true, 3),
  ('kjemi-2:kromatografi', 'q05', 'flervalg', 'Hvilken type kromatografi bruker gass som mobil fase?', array['Gasskromatografi', 'HPLC', 'Papirkromatografi', 'TLC']::text[], 0, 'Egnet for flyktige stoffer.', true, true, 4),
  ('kjemi-2:kromatografi', 'q06', 'flervalg', 'Hvordan kan du identifisere et stoff med TLC?', array['Ved å se på fargen alene', 'Ved å sammenligne Rf med kjente referansestoffer', 'Ved å veie platen', 'Ved å lukte']::text[], 1, 'Samme Rf under samme forhold.', true, true, 5),
  ('kjemi-2:kromatografi', 'q07', 'flervalg', 'Hva kjennetegner HPLC?', array['Gass som mobil fase', 'Papir som stasjonær fase', 'Væske presses under høyt trykk gjennom en kolonne', 'Ingen kolonne']::text[], 2, 'Svært nøyaktig.', true, true, 6),
  ('kjemi-2:kromatografi', 'q08', 'flervalg', 'Hvilken feilkilde kan ødelegge et TLC-forsøk?', array['At platen er tørr', 'At startlinjen er over løsemiddelet', 'At prøven er liten', 'At startlinjen ligger under løsemiddelnivået']::text[], 3, 'Prøven løses ut i karet.', true, true, 7),
  ('kjemi-2:kromatografi', 'q09', 'flervalg', 'Hva kan kolonnekromatografi brukes til?', array['Å rense større mengder stoff', 'Å måle temperatur', 'Å veie stoffer', 'Å lage gass']::text[], 0, 'Stoffene samles opp etter tur.', true, false, 8),
  ('kjemi-2:kromatografi', 'q10', 'flervalg', 'Hva er Rf-verdien alltid?', array['Større enn 1', 'Mellom 0 og 1', 'Negativ', 'Lik 1']::text[], 1, 'Stoffet kan ikke vandre lenger enn fronten.', true, false, 9),
  ('kjemi-2:kromatografi', 'm01', 'sant-usant', 'Ved å endre løsemiddel kan du styre separasjonen.', array['Sant', 'Usant']::text[], 0, 'Polariteten til den mobile fasen påvirker vandringen.', false, true, 10),
  ('kjemi-2:kromatografi', 'm02', 'sant-usant', 'Stoffer som binder seg sterkt til den stasjonære fasen, vandrer raskest.', array['Sant', 'Usant']::text[], 1, 'De vandrer langsomst.', false, true, 11),
  ('kjemi-2:kromatografi', 'm03', 'sant-usant', 'Flekker på TLC-plater kan gjøres synlige med UV-lys.', array['Sant', 'Usant']::text[], 0, 'Eller et fargereagens.', false, true, 12),
  ('kjemi-2:kromatografi', 'm04', 'sant-usant', 'Kromatografi brukes bare i skolelaboratorier.', array['Sant', 'Usant']::text[], 1, 'Den brukes i doping-, mat- og miljøanalyser.', false, true, 13),
  ('kjemi-2:kromatografi', 'm05', 'flervalg', 'Hva er papirkromatografi godt egnet til?', array['Flyktige gasser', 'Å skille fargestoffer i tusj', 'Store mengder stoff', 'Metaller']::text[], 1, 'Enkel og billig metode.', false, true, 14),
  ('kjemi-2:kromatografi', 'm06', 'flervalg', 'Hvilket instrument kobles ofte til GC og HPLC for å identifisere stoffer?', array['Massespektrometer', 'pH-meter', 'Vekt', 'Termometer']::text[], 0, 'Gir molekylenes masse og struktur.', false, true, 15),
  ('kjemi-2:kromatografi', 'm07', 'flervalg', 'Hvordan kan kromatografi brukes i en syntese?', array['Til å varme opp', 'Til å veie produktet', 'Til å følge med på om reaksjonen er ferdig', 'Til å lage katalysator']::text[], 2, 'Utgangsstoffet forsvinner, produktet dukker opp.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('kjemi-2:kromatografi', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('kjemi-2:kromatografi', 's01', 'I en kromatografisk blanding beveger noen stoffer seg raskere enn andre. Forklar hvordan stoffenes binding til den stasjonære fasen og løselighet i den mobile fasen påvirker hvor raskt de beveger seg.', 'Et stoff som binder seg sterkt til den stasjonære fasen, beveger seg langsomt. Et stoff som løser seg godt i den mobile fasen, beveger seg raskere.', array['Knytter sterk binding til den stasjonære fasen til langsommere vandring.', 'Knytter god løselighet i den mobile fasen til raskere vandring.']::text[], 0),
  ('kjemi-2:kromatografi', 's02', 'På en TLC-plate med polar silika kan løsemiddelet endres. Forklar hvorfor et bytte av løsemiddel kan endre hvor godt stoffene i en blanding blir skilt fra hverandre.', 'Når løsemiddelet endres, kan stoffene løse seg ulikt godt i den mobile fasen. Dermed endres hvordan de fordeler seg mellom fasene, og stoffene kan vandre forskjellig og bli skilt på en annen måte.', array['Forklarer at løsemiddelet påvirker hvor godt stoffene løser seg i den mobile fasen.', 'Knytter endret fordeling mellom fasene til endret vandring eller separasjon.']::text[], 1),
  ('kjemi-2:kromatografi', 's03', 'Sammenlign papirkromatografi og kolonnekromatografi med tanke på den stasjonære fasen og hva metodene kan brukes til.', 'I papirkromatografi er papir den stasjonære fasen, og metoden kan brukes til å skille fargestoffer i tusj. I kolonnekromatografi brukes en kolonne fylt med silika til å skille og rense større mengder, som kan samles opp etter hvert som stoffene kommer ut.', array['Oppgir papir som stasjonær fase i papirkromatografi og knytter metoden til separering av fargestoffer.', 'Oppgir silika i en kolonne og forklarer at kolonnekromatografi kan rense større mengder ved at stoffene samles opp etter tur.']::text[], 2),
  ('kjemi-2:kromatografi', 's04', 'En prøve inneholder flyktige stoffer, og laboratoriet vurderer gasskromatografi (GC) og HPLC. Sammenlign metodene ut fra mobil fase og hvilken av dem som passer best til prøven.', 'I GC er den mobile fasen en gass, og metoden er egnet for flyktige stoffer. I HPLC er den mobile fasen en væske som presses under høyt trykk gjennom en kolonne, så GC passer best til prøven.', array['Skiller mellom gass som mobil fase i GC og væske under høyt trykk i HPLC.', 'Velger GC fordi prøven inneholder flyktige stoffer.']::text[], 3),
  ('kjemi-2:kromatografi', 's05', 'På en TLC-plate har et stoff vandret 2,0 cm, og Rf-verdien er 0,40. Hvor langt har løsemiddelfronten vandret? Vis det viktigste regnestykket.', 'Rf = avstand stoffet har vandret / avstand løsemiddelfronten har vandret. Dermed er avstanden til løsemiddelfronten 2,0 / 0,40 = 5,0 cm.', array['Setter opp forholdet Rf = stoffets vandring / løsemiddelfrontens vandring.', 'Regner ut at løsemiddelfronten har vandret 5,0 cm.']::text[], 4),
  ('kjemi-2:kromatografi', 's06', 'I en TLC-analyse har løsemiddelfronten vandret 8,0 cm. Et stoff har Rf = 0,25. Hvor langt har stoffet vandret? Vis det viktigste regnestykket.', 'Stoffets vandring er Rf ganger løsemiddelfrontens vandring. 0,25 · 8,0 cm = 2,0 cm.', array['Bruker sammenhengen stoffets vandring = Rf · løsemiddelfrontens vandring.', 'Får svaret 2,0 cm.']::text[], 5),
  ('kjemi-2:kromatografi', 's07', 'En rettsmedisinsk undersøkelse skal analysere en prøve som kan inneholde giftstoffer. Forklar hvordan kromatografi kan brukes i denne situasjonen, og hvilken rolle et massespektrometer kan ha.', 'Kromatografi kan brukes i rettsmedisin til å analysere giftstoffer i en prøve. Et massespektrometer, som ofte kobles til kromatografi, kan brukes til å identifisere stoffene.', array['Knytter kromatografi til analyse av giftstoffer i rettsmedisin.', 'Forklarer at massespektrometeret brukes til å identifisere stoffer.']::text[], 6),
  ('kjemi-2:kromatografi', 's08', 'En elev setter startlinjen på en TLC-plate under nivået til løsemiddelet i karet. Forklar hva som kan skje med prøven, og hvorfor dette gjør forsøket upålitelig.', 'Prøven kan løses ut i løsemiddelet i karet i stedet for å vandre oppover platen. Da blir separasjonen på TLC-platen upålitelig.', array['Beskriver at prøven kan løses ut i løsemiddelet i karet.', 'Knytter dette til at prøven ikke vandrer normalt oppover platen, slik at separasjonen blir upålitelig.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('kjemi-2:biologiske-makromolekyler', 'kjemi-2', 'biologiske-makromolekyler', 'Biologiske makromolekyler', 'Oppbygningen av biologiske makromolekyler – karbohydrater, proteiner, lipider og nukleinsyrer – bindingene som holder dem sammen, proteiners struktur på fire nivåer, og hvordan ytre faktorer som temperatur, pH, salter og tungmetaller kan påvirke molekylenes struktur og egenskaper.', array[13]::int[], 11, 'utkast', '{}'::text[], false, now())
