  ('biologi-2:energistrom-og-stoffkretslop', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('biologi-2:energistrom-og-stoffkretslop', 's01', 'I en energipyramide blir det mindre energi tilgjengelig for hvert trofisk nivå oppover. Forklar hvorfor dette skjer, og hvordan det bidrar til at pyramiden blir smalere mot toppen.', 'Organismene bruker mye energi til celleånding og bevegelse, og energi forsvinner også som varme. Noe energi er i deler som ikke blir spist eller havner i avføring, så mindre energi blir tilgjengelig på nivået over.', array['Forklarer at energi brukes i organismene og går tapt som varme.', 'Forklarer at noe energi ikke blir spist eller havner i avføring, slik at mindre energi overføres videre.']::text[], 0),
  ('biologi-2:energistrom-og-stoffkretslop', 's02', 'Sammenlign bruttoproduksjon og nettoproduksjon hos produsenter. Hva skiller størrelsene, og hvilken av dem er tilgjengelig for konsumentene?', 'Bruttoproduksjon er all energien produsentene binder. Nettoproduksjon er det som er igjen etter produsentenes egen celleånding, og denne energien er tilgjengelig for konsumentene.', array['Beskriver bruttoproduksjon som all energien produsentene binder.', 'Beskriver nettoproduksjon som energien igjen etter celleånding, tilgjengelig for konsumentene.']::text[], 1),
  ('biologi-2:energistrom-og-stoffkretslop', 's03', 'I jorda omdanner bakterier ammonium til nitrat. Hva kalles denne prosessen, og hva skjer videre med nitratet i nitrogenkretsløpet?', 'Prosessen kalles nitrifikasjon. Plantene kan ta opp nitratet fra jorda.', array['Kaller omdanningen fra ammonium til nitrat nitrifikasjon.', 'Får fram at planter tar opp nitrat.']::text[], 2),
  ('biologi-2:energistrom-og-stoffkretslop', 's04', 'Et område med skog blir brent. Bruk kunnskap om karbonkretsløpet til å forklare hvordan karbonlagring og karbon i lufta påvirkes.', 'Skog er et karbonlager. Forbrenning frigjør karbon som har vært lagret, blant annet som CO₂.', array['Nevner at skog lagrer karbon.', 'Forklarer at forbrenning frigjør lagret karbon, for eksempel som CO₂.']::text[], 3),
  ('biologi-2:energistrom-og-stoffkretslop', 's05', 'Fosfor frigjøres sakte fra berggrunnen og kan etter hvert havne i havsedimenter. Forklar hvordan dette henger sammen med at fosfor kan være en begrensende faktor for vekst.', 'Fosfor frigjøres sakte fra berggrunnen, tas opp av planter og går gjennom næringskjeden. Når mye fosfor ender i havsedimenter, kan lite være tilgjengelig for vekst, slik at fosfor blir begrensende.', array['Forklarer at fosfor frigjøres sakte fra berggrunnen.', 'Knytter begrenset tilgjengelighet, blant annet ved at fosfor havner i sedimenter, til at fosfor kan begrense vekst.']::text[], 4),
  ('biologi-2:energistrom-og-stoffkretslop', 's06', 'Planter tar opp vann fra jorda, og vann fordamper fra plantene til lufta. Hva kalles denne prosessen, og hvordan inngår den i vannets kretsløp?', 'Prosessen kalles transpirasjon. Den bidrar til vannets kretsløp sammen med fordampning, nedbør og avrenning.', array['Kaller plantenes avgivelse av vann til lufta transpirasjon.', 'Plasserer transpirasjon som en del av vannets kretsløp.']::text[], 5),
  ('biologi-2:energistrom-og-stoffkretslop', 's07', 'Produsentene binder 10 000 kJ. Omtrent 10 % går videre til neste trofiske nivå. Hvor mye energi får primærkonsumentene? Vis det viktigste regnetrinnet.', '10 % av 10 000 kJ er 1 000 kJ. Primærkonsumentene får altså omtrent 1 000 kJ.', array['Viser at 10 % beregnes som 0,1 × 10 000 kJ eller tilsvarende.', 'Oppgir omtrent 1 000 kJ.']::text[], 6),
  ('biologi-2:energistrom-og-stoffkretslop', 's08', 'En næringskjede starter med produsenter som har 10 000 kJ. Omtrent 10 % går videre for hvert trofisk nivå. Hvor mye energi når tertiærkonsumentene? Vis det viktigste regnetrinnet.', 'Energien blir omtrent 1 000 kJ hos primærkonsumentene, 100 kJ hos sekundærkonsumentene og 10 kJ hos tertiærkonsumentene. Det tilsvarer å ta 10 % tre ganger: 10 000 → 1 000 → 100 → 10 kJ.', array['Bruker 10 %-regelen for hvert av de tre overføringstrinnene fra produsent til tertiærkonsument.', 'Oppgir omtrent 10 kJ hos tertiærkonsumentene.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('biologi-2:menneskelig-pavirkning-pa-kretslopene', 'biologi-2', 'menneskelig-pavirkning-pa-kretslopene', 'Menneskelig påvirkning på kretsløpene', 'Hvordan menneskelig aktivitet påvirker karbon-, nitrogen- og fosforkretsløpet – fossilt brensel, avskoging, drenering av myr, kunstgjødsel, overgjødsling, havforsuring og oksygensvinn – og hvilke tiltak som kan bidra til å ivareta kretsløpene.', array[5]::int[], 4, 'utkast', '{}'::text[], false, now())
