  ('biologi-2:genteknologi-og-etikk', 'Insulin fra bakterier', 'Legemiddel laget av genmodifiserte bakterier.', 2),
  ('biologi-2:genteknologi-og-etikk', 'mRNA-vaksine', 'Vaksine som gir cellene oppskrift på et protein.', 3),
  ('biologi-2:genteknologi-og-etikk', 'Persontilpasset medisin', 'Behandling tilpasset pasientens gener.', 4),
  ('biologi-2:genteknologi-og-etikk', 'Genterapi', 'Tilføring eller reparasjon av gener for å behandle sykdom.', 5),
  ('biologi-2:genteknologi-og-etikk', 'CAR-T-behandling', 'Pasientens immunceller genmodifiseres til å angripe kreft.', 6),
  ('biologi-2:genteknologi-og-etikk', 'Gyllen ris', 'Genmodifisert ris med vitamin A.', 7),
  ('biologi-2:genteknologi-og-etikk', 'Genteknologiloven', 'Norsk lov som regulerer bruk av GMO.', 8),
  ('biologi-2:genteknologi-og-etikk', 'Bioteknologiloven', 'Norsk lov om medisinsk bruk av bioteknologi på mennesker.', 9),
  ('biologi-2:genteknologi-og-etikk', 'Føre var-prinsippet', 'Forsiktighet når langsiktige virkninger er usikre.', 10),
  ('biologi-2:genteknologi-og-etikk', 'Patent på gener', 'Enerett som kan gjøre bønder avhengige av selskaper.', 11),
  ('biologi-2:genteknologi-og-etikk', 'Redigering av embryoer', 'Endringer som arves videre – forbudt i de fleste land.', 12),
  ('biologi-2:genteknologi-og-etikk', 'Genetisk personvern', 'Spørsmålet om hvem som skal ha tilgang til genetiske data.', 13),
  ('biologi-2:genteknologi-og-etikk', 'Merking av GMO', 'Krav om at GMO-mat skal merkes i Norge.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('biologi-2:genteknologi-og-etikk', 'q01', 'flervalg', 'Hva er forskjellen på GMO og genredigering?', array['Det er det samme', 'GMO har gener fra andre arter, genredigering endrer organismens egne gener', 'Genredigering bruker alltid fremmede gener', 'GMO finnes ikke i mat']::text[], 1, 'Genredigering bruker for eksempel CRISPR.', true, true, 0),
  ('biologi-2:genteknologi-og-etikk', 'q02', 'flervalg', 'Hva lages med genmodifiserte bakterier i medisin?', array['Insulin', 'Vitamin C fra frukt', 'Penicillin fra sopp alene', 'Blod']::text[], 0, 'Også veksthormon og antistoffer.', true, true, 1),
  ('biologi-2:genteknologi-og-etikk', 'q03', 'flervalg', 'Hva er gyllen ris?', array['Ris som tåler sprøytemidler', 'Vanlig ris med gyllen farge', 'Genmodifisert ris med vitamin A', 'Ris fra Norge']::text[], 2, 'Skal motvirke vitamin A-mangel.', true, true, 2),
  ('biologi-2:genteknologi-og-etikk', 'q04', 'flervalg', 'Hvorfor ble redigeringen av tvillingenes gener i 2018 fordømt?', array['Fordi den mislyktes', 'Fordi den var lovlig', 'Fordi den var billig', 'Fordi endringer i embryoer arves videre og er forbudt i de fleste land']::text[], 3, 'Et spørsmål om menneskeverd og sikkerhet.', true, true, 3),
  ('biologi-2:genteknologi-og-etikk', 'q05', 'flervalg', 'Hva er føre var-prinsippet?', array['Forsiktighet når langsiktige virkninger er usikre', 'Å alltid ta risiko', 'Å bruke mest mulig teknologi', 'Å forby all forskning']::text[], 0, 'Sentralt i norsk regelverk.', true, true, 4),
  ('biologi-2:genteknologi-og-etikk', 'q06', 'flervalg', 'Hvilket etisk problem kan patenter på frø skape?', array['Billigere frø', 'At bønder i fattige land blir avhengige av store selskaper', 'Mer biologisk mangfold', 'Ingen problemer']::text[], 1, 'Et spørsmål om rettferdighet.', true, true, 5),
  ('biologi-2:genteknologi-og-etikk', 'q07', 'flervalg', 'Hvilken lov regulerer bruk av GMO i Norge?', array['Bioteknologiloven', 'Markedsføringsloven', 'Genteknologiloven', 'Arbeidsmiljøloven']::text[], 2, 'Legger vekt på samfunnsnytte, bærekraft og etikk.', true, true, 6),
  ('biologi-2:genteknologi-og-etikk', 'q08', 'flervalg', 'Hva er CAR-T-behandling?', array['En vaksine', 'En type GMO-plante', 'En gentest', 'Genmodifisering av pasientens immunceller mot kreft']::text[], 3, 'En ny kreftbehandling.', true, true, 7),
  ('biologi-2:genteknologi-og-etikk', 'q09', 'flervalg', 'Hvilket spørsmål om personvern reiser gentester?', array['Hvem skal ha tilgang til genetiske data', 'Hvor mye testen koster', 'Hvor raskt svaret kommer', 'Hvilken farge prøveglasset har']::text[], 0, 'Data sier også noe om familien.', true, false, 8),
  ('biologi-2:genteknologi-og-etikk', 'q10', 'flervalg', 'Hva er et argument mot at genteknologi er «unaturlig»?', array['At naturen er farlig', 'At mennesker har foredlet planter og dyr i tusenvis av år', 'At genteknologi er gammel', 'At GMO ikke finnes']::text[], 1, 'Grensen for det naturlige er uklar.', true, false, 9),
  ('biologi-2:genteknologi-og-etikk', 'm01', 'sant-usant', 'Norge har et strengt regelverk for GMO.', array['Sant', 'Usant']::text[], 0, 'Med vekt på samfunnsnytte, bærekraft og etikk.', false, true, 10),
  ('biologi-2:genteknologi-og-etikk', 'm02', 'sant-usant', 'Genredigering av embryoer som arves videre, er tillatt i de fleste land.', array['Sant', 'Usant']::text[], 1, 'Det er forbudt i de fleste land.', false, true, 11),
  ('biologi-2:genteknologi-og-etikk', 'm03', 'sant-usant', 'Steril oppdrettslaks kan hindre krysning med villaks.', array['Sant', 'Usant']::text[], 0, 'Et forskningsfelt i havbruk.', false, true, 12),
  ('biologi-2:genteknologi-og-etikk', 'm04', 'sant-usant', 'Genetiske data sier bare noe om den som blir testet.', array['Sant', 'Usant']::text[], 1, 'De sier også noe om familien.', false, true, 13),
  ('biologi-2:genteknologi-og-etikk', 'm05', 'flervalg', 'Hva kan persontilpasset medisin gjøre?', array['Gi alle samme medisin', 'Velge medisiner som virker best ut fra pasientens gener', 'Erstatte leger', 'Fjerne alle sykdommer']::text[], 1, 'Basert på gentester.', false, true, 14),
  ('biologi-2:genteknologi-og-etikk', 'm06', 'flervalg', 'Hvilken bekymring gjelder genmodifiserte planter i naturen?', array['At gener kan spres til ville slektninger', 'At plantene blir for små', 'At de ikke kan dyrkes', 'At de mangler farge']::text[], 0, 'Føre var-prinsippet.', false, true, 15),
  ('biologi-2:genteknologi-og-etikk', 'm07', 'flervalg', 'Hvilket spørsmål bør du stille når du drøfter genteknologi?', array['Hvor gammel teknologien er', 'Hvem som oppfant den', 'Hvilken nytte og risiko den gir, og for hvem', 'Hvor mange som liker den']::text[], 2, 'Og hvilke verdier som står mot hverandre.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('biologi-2:genteknologi-og-etikk', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('biologi-2:genteknologi-og-etikk', 's01', 'En mRNA-vaksine gir cellene en oppskrift på et protein. Forklar hvordan vaksinen gir cellene denne oppskriften, og nevn én fordel ved utviklingen av mRNA-vaksiner.', 'mRNA-vaksinen gir cellene oppskriften på et protein. Slike vaksiner kan utvikles raskt.', array['Forklarer at vaksinen gir cellene en oppskrift på et protein.', 'Nevner at mRNA-vaksiner kan utvikles raskt.']::text[], 0),
  ('biologi-2:genteknologi-og-etikk', 's02', 'Sammenlign genteknologiloven og bioteknologiloven i Norge ved å forklare hva hver av lovene regulerer.', 'Genteknologiloven regulerer bruk av GMO. Bioteknologiloven regulerer medisinsk bruk av bioteknologi på mennesker.', array['Knytter genteknologiloven til regulering av GMO.', 'Knytter bioteknologiloven til medisinsk bruk av bioteknologi på mennesker.']::text[], 1),
  ('biologi-2:genteknologi-og-etikk', 's03', 'En pasient har arvelig blindhet. Hvilken type genteknologisk behandling kan være aktuell, og hvordan virker den i hovedtrekk?', 'Genterapi kan være aktuell, siden noen former for arvelig blindhet kan behandles slik. Genterapi tilfører eller retter opp gener.', array['Identifiserer genterapi som en aktuell behandling.', 'Forklarer at genterapi tilfører eller retter opp gener.']::text[], 2),
  ('biologi-2:genteknologi-og-etikk', 's04', 'Mais er genmodifisert slik at den produserer et stoff som dreper skadeinsekter. Beskriv den genetiske egenskapen maisen har fått, og hva den gjør.', 'Maisen har fått en egenskap som gjør at den produserer et stoff som dreper skadeinsekter.', array['Beskriver at maisen produserer et stoff.', 'Forklarer at stoffet dreper skadeinsekter.']::text[], 3),
  ('biologi-2:genteknologi-og-etikk', 's05', 'Et selskap har patent på frø som er utviklet med genteknologi. Forklar en mulig utfordring dette kan skape for bønder i fattige land, og nevn én mulig nytte genteknologi kan gi.', 'Patenter på frø kan gjøre bønder i fattige land avhengige av selskapene. Genteknologi kan samtidig bidra til mer mat eller billigere medisiner.', array['Forklarer at patenter kan gjøre bønder i fattige land avhengige av selskaper.', 'Nevner mer mat eller billigere medisiner som en mulig nytte.']::text[], 4),
  ('biologi-2:genteknologi-og-etikk', 's06', 'Genene til to tvillingjenter ble redigert i 2018. EU vedtok nye regler i 2026. Regn ut hvor mange år det er mellom de to årstallene, og vis regnestykket.', '2026 − 2018 = 8 år.', array['Viser en riktig utregning av forskjellen mellom årstallene.', 'Oppgir svaret 8 år.']::text[], 5),
  ('biologi-2:genteknologi-og-etikk', 's07', 'I en sak ble genene til to tvillingjenter redigert. Regn ut hvor mange tvillingpar de to jentene utgjør, og vis regnestykket.', '2 ÷ 2 = 1 tvillingpar.', array['Viser regnestykket 2 ÷ 2.', 'Oppgir at jentene utgjør 1 tvillingpar.']::text[], 6),
  ('biologi-2:genteknologi-og-etikk', 's08', 'En plante ønskes endret slik at den tåler tørke, uten at den får gener fra en annen art. Hvilken metode passer best, og hva er det ved metoden som gjør at den passer til målet?', 'Genredigering, for eksempel med CRISPR, passer best. Metoden endrer plantens egne gener uten å tilføre gener fra en annen art.', array['Velger genredigering som metode.', 'Forklarer at genredigering endrer organismens egne gener uten å tilføre fremmede gener.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('geofag-2:jordsystemenes-vekselvirkninger', 'geofag-2', 'jordsystemenes-vekselvirkninger', 'Vekselvirkninger mellom jordsystemene', 'Hvordan atmosfæren, hydrosfæren, kryosfæren, litosfæren og biosfæren påvirker hverandre – med vekt på hvordan vekselvirkningene påvirker havet, atmosfæren og kryosfæren, og hvordan positive og negative tilbakekoblinger kan forsterke eller dempe endringer.', array[1]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('geofag-2:jordsystemenes-vekselvirkninger', '## Fem jordsystemer
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Atmosfæren', 'Lufta rundt jorda.', 0),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Hydrosfæren', 'Hav, innsjøer, elver og grunnvann.', 1),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Kryosfæren', 'Is og snø: breer, innlandsis, havis og permafrost.', 2),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Litosfæren', 'Jordskorpa og øverste del av mantelen.', 3),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Biosfæren', 'Alt liv på jorda.', 4),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Albedo', 'Hvor mye av sollyset en overflate reflekterer.', 5),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Is–albedo-effekten', 'Smeltende is gir mørkere overflate og mer oppvarming.', 6),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Positiv tilbakekobling', 'Forsterker en endring.', 7),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Negativ tilbakekobling', 'Demper en endring.', 8),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Permafrost', 'Jord som er frossen hele året – kan slippe ut metan når den tiner.', 9),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Pinatubo 1991', 'Vulkanutbrudd som ga global avkjøling på omtrent en halv grad.', 10),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'El Niño', 'Samspill mellom hav og atmosfære i Stillehavet som påvirker været globalt.', 11),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Havforsuring', 'Havets pH synker når det tar opp CO₂.', 12),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Vanndamp som tilbakekobling', 'Varmere luft holder mer vanndamp, som er en drivhusgass.', 13),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'Vippepunkt', 'Terskel der endringen blir selvforsterkende.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q01', 'flervalg', 'Hvilket system omfatter isbreer, havis og permafrost?', array['Hydrosfæren', 'Kryosfæren', 'Litosfæren', 'Biosfæren']::text[], 1, 'Is og snø.', true, true, 0),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q02', 'flervalg', 'Hva er is–albedo-effekten?', array['Smeltende is gir mørkere overflate som tar opp mer varme', 'Is reflekterer mindre enn hav', 'Is smelter aldri', 'Is lager vind']::text[], 0, 'En positiv tilbakekobling.', true, true, 1),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q03', 'flervalg', 'Hva skjedde etter vulkanutbruddet på Pinatubo i 1991?', array['Global oppvarming', 'Havnivået sank', 'Global avkjøling på omtrent en halv grad', 'Ingenting']::text[], 2, 'Svovelpartikler reflekterte sollys.', true, true, 2),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q04', 'flervalg', 'Hvorfor er tining av permafrost en positiv tilbakekobling?', array['Den gir mer is', 'Den gir mer oksygen', 'Den gir mer skog', 'Den slipper ut metan og CO₂ som gir mer oppvarming']::text[], 3, 'Forsterker endringen.', true, true, 3),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q05', 'flervalg', 'Hva gjør havet med CO₂ og varme fra atmosfæren?', array['Tar opp mye av det og demper klimaendringene', 'Slipper ut alt', 'Påvirkes ikke', 'Lager mer CO₂']::text[], 0, 'Men gir havforsuring.', true, true, 4),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q06', 'flervalg', 'Hva er en negativ tilbakekobling?', array['En som forsterker endringen', 'En som demper endringen', 'En som er skadelig', 'En som stopper alt liv']::text[], 1, 'For eksempel økt varmestråling fra en varmere jord.', true, true, 5),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q07', 'flervalg', 'Hvordan kan smeltevann påvirke havstrømmer?', array['Det gjør havet saltere', 'Det har ingen virkning', 'Ferskvann er lettere enn saltvann og kan endre sirkulasjonen', 'Det gjør havet kaldere alltid']::text[], 2, 'Tetthetsforskjeller driver havstrømmer.', true, true, 6),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q08', 'flervalg', 'Hva er et vippepunkt?', array['Et punkt på et kart', 'En type vulkan', 'En værstasjon', 'En terskel der endringen blir selvforsterkende']::text[], 3, 'For eksempel nedsmelting av Grønlandsisen.', true, true, 7),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q09', 'flervalg', 'Hvordan påvirker forvitring klimaet over lang tid?', array['Den tar opp CO₂', 'Den slipper ut metan', 'Den lager is', 'Den øker albedo']::text[], 0, 'Over millioner av år.', true, false, 8),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'q10', 'flervalg', 'Hvorfor kan skyer virke begge veier på klimaet?', array['De består av is', 'De reflekterer sollys, men holder også på varme', 'De lager vind', 'De er alltid kalde']::text[], 1, 'Netto virkning avhenger av skytype og høyde.', true, false, 9),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'm01', 'sant-usant', 'Varmere luft kan holde mer vanndamp.', array['Sant', 'Usant']::text[], 0, 'Vanndamp er en drivhusgass.', false, true, 10),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'm02', 'sant-usant', 'Jordsystemene er uavhengige av hverandre.', array['Sant', 'Usant']::text[], 1, 'De utveksler energi, vann og stoffer.', false, true, 11),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'm03', 'sant-usant', 'Mennesket er i dag en viktig kraft som endrer jordsystemene.', array['Sant', 'Usant']::text[], 0, 'Gjennom utslipp og arealbruk.', false, true, 12),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'm04', 'sant-usant', 'Mørkt hav reflekterer mer sollys enn is.', array['Sant', 'Usant']::text[], 1, 'Is har høyere albedo.', false, true, 13),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'm05', 'flervalg', 'Hva driver havstrømmer i overflaten?', array['Månen alene', 'Vind', 'Vulkaner', 'Permafrost']::text[], 1, 'Også tetthetsforskjeller.', false, true, 14),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'm06', 'flervalg', 'Hva gir smelting av isbreer og innlandsis?', array['Havnivåstigning', 'Havnivåsenkning', 'Mer havis', 'Kaldere hav alltid']::text[], 0, 'Havis som smelter, gir lite havnivåendring.', false, true, 15),
  ('geofag-2:jordsystemenes-vekselvirkninger', 'm07', 'flervalg', 'Hvordan påvirker platetektonikk klimaet?', array['Raskt fra år til år', 'Ikke i det hele tatt', 'Ved å endre fordelingen av hav og land over geologisk tid', 'Bare gjennom jordskjelv']::text[], 2, 'Endrer havstrømmer og klima.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('geofag-2:jordsystemenes-vekselvirkninger', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('geofag-2:jordsystemenes-vekselvirkninger', 's01', 'Sammenlign hydrosfæren og kryosfæren. Hvilke deler av jorda omfatter hvert system?', 'Hydrosfæren omfatter vann i hav, innsjøer, elver og grunnvann. Kryosfæren omfatter is og snø, blant annet isbreer, havis og permafrost.', array['Skiller mellom vannsystemet og systemet for is og snø.', 'Gir minst ett riktig eksempel på hva hvert system omfatter.']::text[], 0),
  ('geofag-2:jordsystemenes-vekselvirkninger', 's02', 'Forklar hvordan vind kan påvirke både havet og været.', 'Vind driver havstrømmer og skaper bølger. Havstrømmene frakter varme, og det kan påvirke værmønstre.', array['Knytter vind til havstrømmer eller bølger.', 'Forklarer at havstrømmer frakter varme som påvirker værmønstre.']::text[], 1),
  ('geofag-2:jordsystemenes-vekselvirkninger', 's03', 'Et vulkanutbrudd sender svovelgasser høyt opp i atmosfæren. Forklar hvordan dette kan føre til avkjøling.', 'Svovelgassene danner små partikler i atmosfæren. Partiklene reflekterer sollys, slik at mindre energi varmer jorda og det kan bli avkjøling.', array['Nevner at gassene danner små partikler i atmosfæren.', 'Forklarer at partiklene reflekterer sollys og kan gi avkjøling.']::text[], 2),
  ('geofag-2:jordsystemenes-vekselvirkninger', 's04', 'El Niño er et samspill mellom hav og atmosfære i Stillehavet. Hvilken følge kan dette samspillet ha for været?', 'Samspillet mellom havet og atmosfæren under El Niño kan påvirke været over store deler av verden.', array['Identifiserer havet og atmosfæren som systemene som samspiller.', 'Nevner at været kan påvirkes over store deler av verden.']::text[], 3),
  ('geofag-2:jordsystemenes-vekselvirkninger', 's05', 'Varmere luft kan holde mer vanndamp, og vanndamp er en drivhusgass. Forklar hvordan dette kan forsterke en oppvarming.', 'Når lufta blir varmere, kan den holde mer vanndamp. Siden vanndamp er en drivhusgass, bidrar den til å holde på varme og forsterke oppvarmingen.', array['Knytter varmere luft til at mer vanndamp kan være i lufta.', 'Forklarer at vanndampens rolle som drivhusgass kan forsterke oppvarmingen.']::text[], 4),
  ('geofag-2:jordsystemenes-vekselvirkninger', 's06', 'Sammenlign hva som skjer med klimaet når havis smelter, med hva som skjer med havnivået når isbreer eller innlandsis smelter.', 'Når havis smelter, blir mørkt hav blottlagt. Havet tar da opp mer varme, som kan bidra til mer smelting. Når isbreer eller innlandsis smelter, stiger havnivået.', array['Forklarer at smelting av havis blottlegger mørkt hav som tar opp mer varme.', 'Nevner at smelting av isbreer eller innlandsis øker havnivået.']::text[], 5),
  ('geofag-2:jordsystemenes-vekselvirkninger', 's07', 'I en forenklet bokføring tilfører utslipp 15 enheter CO₂ til atmosfæren, mens fotosyntese tar opp 6 enheter. Hvor mange enheter CO₂ blir det netto tilført, og hvilket jordsystem tar opp CO₂-en?', 'Netto blir 15 − 6 = 9 enheter CO₂ tilført. Det er biosfæren som tar opp CO₂ gjennom fotosyntese.', array['Regner ut at netto tilførsel er 9 enheter CO₂.', 'Knytter opptaket gjennom fotosyntese til biosfæren.']::text[], 6),
  ('geofag-2:jordsystemenes-vekselvirkninger', 's08', 'I en enkel modell kan lufta holde 4 enheter vanndamp før oppvarming og 7 enheter etter oppvarming. Hvor mange flere enheter kan lufta holde, og hvordan kan dette påvirke oppvarmingen?', 'Lufta kan holde 7 − 4 = 3 flere enheter vanndamp. Siden vanndamp er en drivhusgass, kan økningen forsterke oppvarmingen.', array['Regner ut at økningen er 3 enheter.', 'Forklarer at mer vanndamp kan forsterke oppvarmingen fordi vanndamp er en drivhusgass.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('geofag-2:straling-og-global-sirkulasjon', 'geofag-2', 'straling-og-global-sirkulasjon', 'Strålingsbalanse og global sirkulasjon', 'Jordens strålingsbalanse med kortbølget og langbølget stråling, albedo og drivhuseffekt, ulik strålingsfordeling med breddegrad, strålingspådriv – og hvordan dette driver den globale sirkulasjonen med Hadley-, Ferrel- og polarceller, passatvinder, vestavindsbeltet og jetstrømmer.', array[2]::int[], 1, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('geofag-2:straling-og-global-sirkulasjon', '## Strålingsbalanse
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('geofag-2:straling-og-global-sirkulasjon', 'Kortbølget stråling', 'Stråling fra sola, mest synlig lys.', 0),
  ('geofag-2:straling-og-global-sirkulasjon', 'Langbølget stråling', 'Varmestråling fra jorda.', 1),
  ('geofag-2:straling-og-global-sirkulasjon', 'Albedo', 'Andelen sollys som reflekteres – omtrent 30 % for jorda.', 2),
  ('geofag-2:straling-og-global-sirkulasjon', 'Strålingsbalanse', 'Innstråling og utstråling er omtrent like store over tid.', 3),
  ('geofag-2:straling-og-global-sirkulasjon', 'Drivhuseffekt', 'Drivhusgasser tar opp langbølget stråling og varmer jorda.', 4),
  ('geofag-2:straling-og-global-sirkulasjon', 'Uten drivhuseffekt', 'Omtrent −18 °C i stedet for omtrent 15 °C.', 5),
  ('geofag-2:straling-og-global-sirkulasjon', 'Strålingsoverskudd', 'Ved ekvator, der sola står høyt.', 6),
  ('geofag-2:straling-og-global-sirkulasjon', 'Strålingspådriv', 'Endring i strålingsbalansen målt i W/m².', 7),
  ('geofag-2:straling-og-global-sirkulasjon', 'Aerosoler', 'Små partikler som ofte gir negativt pådriv.', 8),
  ('geofag-2:straling-og-global-sirkulasjon', 'Hadleycellen', 'Sirkulasjonscelle mellom ekvator og 30°.', 9),
  ('geofag-2:straling-og-global-sirkulasjon', 'Passatvinder', 'Vinder som blåser mot ekvator nær bakken.', 10),
  ('geofag-2:straling-og-global-sirkulasjon', 'Intertropisk konvergenssone', 'Området der passatvindene møtes, med mye regn.', 11),
  ('geofag-2:straling-og-global-sirkulasjon', 'Ferrelcellen', 'Sirkulasjonscelle mellom 30° og 60° med vestavinder.', 12),
  ('geofag-2:straling-og-global-sirkulasjon', 'Polarfronten', 'Grensen mellom kald polarluft og varmere luft.', 13),
  ('geofag-2:straling-og-global-sirkulasjon', 'Jetstrøm', 'Kraftig vestavind i 8–12 km høyde som styrer lavtrykkene.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('geofag-2:straling-og-global-sirkulasjon', 'q01', 'flervalg', 'Omtrent hvor stor er jordas albedo?', array['5 %', '30 %', '70 %', '90 %']::text[], 1, 'Skyer, is og lyse flater reflekterer.', true, true, 0),
  ('geofag-2:straling-og-global-sirkulasjon', 'q02', 'flervalg', 'Hva ville gjennomsnittstemperaturen vært uten den naturlige drivhuseffekten?', array['Omtrent −18 °C', 'Omtrent 15 °C', 'Omtrent 30 °C', 'Omtrent 0 °C']::text[], 0, 'Med drivhuseffekten er den omtrent 15 °C.', true, true, 1),
  ('geofag-2:straling-og-global-sirkulasjon', 'q03', 'flervalg', 'Hvorfor er det strålingsunderskudd ved polene?', array['Fordi sola aldri skinner', 'Fordi det er lite luft', 'Fordi strålingen kommer skrått inn og albedoen er høy', 'Fordi det er mye skog']::text[], 2, 'Energien fordeles over større areal.', true, true, 2),
  ('geofag-2:straling-og-global-sirkulasjon', 'q04', 'flervalg', 'Hva betyr et positivt strålingspådriv?', array['Avkjøling', 'Ingen endring', 'Mer is', 'Oppvarming']::text[], 3, 'For eksempel økt CO₂.', true, true, 3),
  ('geofag-2:straling-og-global-sirkulasjon', 'q05', 'flervalg', 'Hvor synker luften i Hadleycellen og gir ørkener?', array['Rundt 30° nord og sør', 'Ved ekvator', 'Ved polene', 'Ved 60°']::text[], 0, 'Høytrykk gir lite nedbør.', true, true, 4),
  ('geofag-2:straling-og-global-sirkulasjon', 'q06', 'flervalg', 'Hvilket vindbelte ligger Norge i?', array['Passatvindbeltet', 'Vestavindsbeltet', 'De polare østavindene', 'Den intertropiske konvergenssonen']::text[], 1, 'Mange lavtrykk og mye nedbør på Vestlandet.', true, true, 5),
  ('geofag-2:straling-og-global-sirkulasjon', 'q07', 'flervalg', 'Hva gjør jetstrømmene?', array['Lager havstrømmer', 'Smelter is', 'Styrer lavtrykkenes bane', 'Lager ørkener']::text[], 2, 'Kraftige vinder i 8–12 km høyde.', true, true, 6),
  ('geofag-2:straling-og-global-sirkulasjon', 'q08', 'flervalg', 'Hva gir aerosoler fra vulkaner ofte?', array['Positivt pådriv', 'Mer drivhuseffekt', 'Ingen virkning', 'Negativt pådriv og avkjøling']::text[], 3, 'De reflekterer sollys.', true, true, 7),
  ('geofag-2:straling-og-global-sirkulasjon', 'q09', 'flervalg', 'Hva er den intertropiske konvergenssonen?', array['Området der passatvindene møtes, med mye regn', 'En ørken', 'En havstrøm', 'Et høytrykk ved polene']::text[], 0, 'Nær ekvator.', true, false, 8),
  ('geofag-2:straling-og-global-sirkulasjon', 'q10', 'flervalg', 'Hva driver vind og havstrømmer på global skala?', array['Månen', 'Ulik oppvarming og varmetransport fra ekvator mot polene', 'Jordskjelv', 'Vulkaner']::text[], 1, 'Strålingsfordelingen.', true, false, 9),
  ('geofag-2:straling-og-global-sirkulasjon', 'm01', 'sant-usant', 'Atmosfæren og havet frakter varme fra ekvator mot polene.', array['Sant', 'Usant']::text[], 0, 'Det jevner ut forskjellene.', false, true, 10),
  ('geofag-2:straling-og-global-sirkulasjon', 'm02', 'sant-usant', 'Drivhusgasser stopper sollyset før det når bakken.', array['Sant', 'Usant']::text[], 1, 'De slipper sollyset gjennom, men tar opp varmestråling.', false, true, 11),
  ('geofag-2:straling-og-global-sirkulasjon', 'm03', 'sant-usant', 'En slyngete jetstrøm kan låse værtyper fast i lang tid.', array['Sant', 'Usant']::text[], 0, 'For eksempel langvarig tørke eller regn.', false, true, 12),
  ('geofag-2:straling-og-global-sirkulasjon', 'm04', 'sant-usant', 'Strålingspådriv måles i grader celsius.', array['Sant', 'Usant']::text[], 1, 'Det måles i W/m².', false, true, 13),
  ('geofag-2:straling-og-global-sirkulasjon', 'm05', 'flervalg', 'Hvilken retning blåser jetstrømmene?', array['Fra øst mot vest', 'Fra vest mot øst', 'Fra nord mot sør', 'Tilfeldig']::text[], 1, 'Vestlige vinder i høyden.', false, true, 14),
  ('geofag-2:straling-og-global-sirkulasjon', 'm06', 'flervalg', 'Hvilke vinder blåser i polarcellen nær bakken?', array['Polare østavinder', 'Passatvinder', 'Vestavinder', 'Monsunvinder']::text[], 0, 'Kald luft strømmer fra polene.', false, true, 15),
  ('geofag-2:straling-og-global-sirkulasjon', 'm07', 'flervalg', 'Hva skjer med innstråling og utstråling over tid når klimaet er stabilt?', array['Innstrålingen er alltid større', 'Utstrålingen er alltid større', 'De er omtrent like store', 'Begge er null']::text[], 2, 'Strålingsbalanse.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('geofag-2:straling-og-global-sirkulasjon', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('geofag-2:straling-og-global-sirkulasjon', 's01', 'Beskriv hva slags stråling jorda mottar fra sola og hva slags stråling jorda sender ut. Hva må gjelde mellom innstråling og utstråling over tid for at jorda ikke skal bli stadig varmere eller kaldere?', 'Jorda mottar kortbølget stråling fra sola og sender ut langbølget varmestråling. Over tid må innstrålingen og utstrålingen være omtrent like store for at jorda ikke skal bli stadig varmere eller kaldere.', array['Skiller mellom kortbølget stråling fra sola og langbølget stråling fra jorda.', 'Forklarer at innstråling og utstråling må være omtrent like store over tid.']::text[], 0),
  ('geofag-2:straling-og-global-sirkulasjon', 's02', 'Jordas albedo er omtrent 30 %. Hvor stor andel av solstrålingen som når jorda, blir ikke reflektert, men tatt opp? Vis det viktigste regnestykket.', 'Omtrent 70 % blir tatt opp. Regnestykket er 100 % − 30 % = 70 %.', array['Viser at andelen som tas opp, finnes ved å trekke albedoen fra 100 %.', 'Oppgir omtrent 70 % som svar.']::text[], 1),
  ('geofag-2:straling-og-global-sirkulasjon', 's03', 'Forklar hvordan drivhusgasser bidrar til å varme opp jordoverflaten.', 'Drivhusgasser slipper sollyset gjennom, men tar opp mye av den langbølgede varmestrålingen fra bakken. De sender stråling i alle retninger, også tilbake mot bakken, og varmer den dermed opp.', array['Forklarer at drivhusgasser tar opp langbølget stråling fra bakken.', 'Får fram at noe av strålingen sendes tilbake mot bakken og bidrar til oppvarming.']::text[], 2),
  ('geofag-2:straling-og-global-sirkulasjon', 's04', 'CO₂-mengden i atmosfæren øker. Forklar hvordan dette påvirker strålingspådrivet og jordas temperatur.', 'Økt CO₂ gir et positivt strålingspådriv. Det bidrar til oppvarming av jorda.', array['Knytter økt CO₂ til positivt strålingspådriv.', 'Forklarer at positivt pådriv bidrar til oppvarming.']::text[], 3),
  ('geofag-2:straling-og-global-sirkulasjon', 's05', 'Uten den naturlige drivhuseffekten ville gjennomsnittstemperaturen vært omtrent −18 °C, mot omtrent 15 °C med drivhuseffekten. Hvor stor er forskjellen mellom temperaturene? Vis regnestykket.', 'Forskjellen er omtrent 33 °C. Regnestykket er 15 − (−18) = 33.', array['Setter opp eller beskriver regnestykket som finner avstanden mellom 15 og −18.', 'Oppgir omtrent 33 °C.']::text[], 4),
  ('geofag-2:straling-og-global-sirkulasjon', 's06', 'Sammenlign Hadleycellen og Ferrelcellen ved å angi breddegradene de dekker og hvilken vindretning som kjennetegner hver celle nær bakken.', 'Hadleycellen går fra ekvator til 30° og har passatvinder nær bakken som blåser mot ekvator. Ferrelcellen går fra 30° til 60° og har vestavinder nær bakken.', array['Plasserer Hadleycellen mellom ekvator og 30° og knytter den til passatvinder mot ekvator.', 'Plasserer Ferrelcellen mellom 30° og 60° og knytter den til vestavinder.']::text[], 5),
  ('geofag-2:straling-og-global-sirkulasjon', 's07', 'Forklar sammenhengen mellom ulik oppvarming av jorda, trykkforskjeller og dannelsen av vindbelter.', 'Ulik oppvarming skaper trykkforskjeller i atmosfæren, og trykkforskjellene setter lufta i bevegelse som vind. Jordas rotasjon bøyer vindene av, og dette bidrar til de store vindbeltene.', array['Forklarer at ulik oppvarming fører til trykkforskjeller, som skaper vind.', 'Får fram at jordas rotasjon bøyer av vindene og bidrar til vindbeltene.']::text[], 6),
  ('geofag-2:straling-og-global-sirkulasjon', 's08', 'En jetstrøm slynger seg mye. Hvilken virkning kan dette få på været, og hvor lenge kan virkningen vare?', 'Når jetstrømmen slynger seg mye, kan ulike værtyper bli låst fast. Da kan værforholdene vare på samme sted i lang tid.', array['Forklarer at en sterkt slyngende jetstrøm kan låse værtyper fast.', 'Får fram at værforholdene da kan vare lenge.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('geofag-2:coriolis-trykk-og-havstrommer', 'geofag-2', 'coriolis-trykk-og-havstrommer', 'Jordrotasjon, trykk og tetthet i hav og atmosfære', 'Konsekvensene av jordens rotasjon, trykkforskjeller og tetthetsforskjeller – corioliseffekten, trykkgradientkraften, geostrofisk vind, lavtrykk og høytrykk, Ekman-transport og oppstrømning, termohalin sirkulasjon og Golfstrømmen – og hvordan de påvirker havet og atmosfæren.', array[3]::int[], 2, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('geofag-2:coriolis-trykk-og-havstrommer', '## Trykkforskjeller gir vind
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Lufttrykk', 'Vekten av lufta over et punkt.', 0),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Trykkgradientkraft', 'Kraften som får lufta til å strømme fra høyt mot lavt trykk.', 1),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Isobar', 'Linje som binder sammen steder med likt lufttrykk.', 2),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Corioliseffekten', 'Avbøyning mot høyre på nordlige og venstre på sørlige halvkule.', 3),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Geostrofisk vind', 'Vind parallelt med isobarene når trykkgradientkraft og coriolis er i balanse.', 4),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Lavtrykk på nordlige halvkule', 'Vinden blåser mot klokka og inn mot sentrum.', 5),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Høytrykk på nordlige halvkule', 'Vinden blåser med klokka og ut fra sentrum.', 6),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Ekman-transport', 'Netto vanntransport omtrent 90° til høyre for vinden på nordlige halvkule.', 7),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Oppstrømning', 'Kaldt, næringsrikt vann strømmer opp fra dypet.', 8),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Havstrømvirvel', 'Stort vinddrevet strømsystem i et hav.', 9),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Tetthet i havet', 'Avhenger av temperatur og saltholdighet.', 10),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Termohalin sirkulasjon', 'Global havsirkulasjon drevet av tetthetsforskjeller.', 11),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Dypvannsdannelse', 'Kaldt, salt vann synker i Nord-Atlanteren og rundt Antarktis.', 12),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Golfstrømmen', 'Varm havstrøm som gir Norge et mildt klima.', 13),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'Omveltningssirkulasjonen', 'Den atlantiske sirkulasjonen som kan svekkes av mer ferskvann.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q01', 'flervalg', 'Hvilken retning avbøyes vinden på den nordlige halvkule?', array['Mot venstre', 'Mot høyre', 'Rett fram', 'Oppover']::text[], 1, 'Corioliseffekten.', true, true, 0),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q02', 'flervalg', 'Hvordan blåser vinden rundt et lavtrykk på den nordlige halvkule?', array['Mot klokka og inn mot sentrum', 'Med klokka og ut fra sentrum', 'Rett inn', 'Rett ut']::text[], 0, 'Luften stiger og gir nedbør.', true, true, 1),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q03', 'flervalg', 'Hva betyr tette isobarer på et værkart?', array['Svak vind', 'Mye sol', 'Sterk vind', 'Høy temperatur']::text[], 2, 'Stor trykkgradient.', true, true, 2),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q04', 'flervalg', 'Hva er Ekman-transport?', array['Transport av skip', 'Tidevann', 'Vind i høyden', 'Netto vanntransport omtrent 90° til høyre for vinden på nordlige halvkule']::text[], 3, 'En følge av corioliseffekten.', true, true, 3),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q05', 'flervalg', 'Hvorfor er oppstrømningsområder rike fiskeområder?', array['Fordi kaldt, næringsrikt vann strømmer opp', 'Fordi vannet er varmt', 'Fordi det er lite strøm', 'Fordi det er lite lys']::text[], 0, 'Gir mye plankton.', true, true, 4),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q06', 'flervalg', 'Hvilket vann er tyngst?', array['Varmt og ferskt', 'Kaldt og salt', 'Varmt og salt', 'Kaldt og ferskt']::text[], 1, 'Synker og driver dypvannssirkulasjon.', true, true, 5),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q07', 'flervalg', 'Hva er geostrofisk vind?', array['Vind nær bakken', 'Vind mot lavtrykket alltid', 'Vind parallelt med isobarene i høyden', 'Sjøbris']::text[], 2, 'Balanse mellom trykkgradient og coriolis.', true, true, 6),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q08', 'flervalg', 'Hvorfor har Norge mildere klima enn andre steder på samme breddegrad?', array['Fordi Norge ligger nær ekvator', 'På grunn av fjellene', 'På grunn av permafrost', 'På grunn av Golfstrømmen og vestavindene']::text[], 3, 'Varmt vann og mild luft.', true, true, 7),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q09', 'flervalg', 'Hvor er corioliseffekten null?', array['Ved ekvator', 'Ved polene', 'Ved 45°', 'Overalt']::text[], 0, 'Størst ved polene.', true, false, 8),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'q10', 'flervalg', 'Hva kan mer smeltevann fra Grønland gjøre med havsirkulasjonen?', array['Styrke den', 'Svekke den fordi overflatevannet blir lettere', 'Ingenting', 'Stoppe tidevannet']::text[], 1, 'Mindre dypvannsdannelse.', true, false, 9),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'm01', 'sant-usant', 'Høytrykk gir ofte klart og stabilt vær.', array['Sant', 'Usant']::text[], 0, 'Synkende luft hindrer skydannelse.', false, true, 10),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'm02', 'sant-usant', 'Rundt et lavtrykk på den sørlige halvkule blåser vinden mot klokka.', array['Sant', 'Usant']::text[], 1, 'Retningen er motsatt – med klokka.', false, true, 11),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'm03', 'sant-usant', 'Den termohaline sirkulasjonen kan bruke rundt tusen år på én runde.', array['Sant', 'Usant']::text[], 0, 'Det globale transportbåndet.', false, true, 12),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'm04', 'sant-usant', 'Friksjon nær bakken får vinden til å blåse helt parallelt med isobarene.', array['Sant', 'Usant']::text[], 1, 'Nær bakken blåser den litt inn mot lavtrykket.', false, true, 13),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'm05', 'flervalg', 'Hvor dannes dypvann som driver den termohaline sirkulasjonen?', array['Ved ekvator', 'I Nord-Atlanteren og rundt Antarktis', 'I Middelhavet', 'I Stillehavet ved Peru']::text[], 1, 'Kaldt, salt vann synker.', false, true, 14),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'm06', 'flervalg', 'Hvorfor er kysten av Norge isfri om vinteren?', array['Golfstrømmen og Den nordatlantiske strømmen', 'Høyt saltinnhold alene', 'Tidevannet', 'Vulkaner']::text[], 0, 'Varmt vann fra sør.', false, true, 15),
  ('geofag-2:coriolis-trykk-og-havstrommer', 'm07', 'flervalg', 'Hvor finner vi et kjent oppstrømningsområde?', array['I Nordsjøen', 'I Østersjøen', 'Utenfor Peru', 'I Mjøsa']::text[], 2, 'Rike fiskeområder.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('geofag-2:coriolis-trykk-og-havstrommer', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('geofag-2:coriolis-trykk-og-havstrommer', 's01', 'Forklar hvordan trykkgradientkraften får luft til å bevege seg, og hvilken betydning lufttrykket har for dette.', 'Trykkgradientkraften får luft til å strømme fra områder med høyt trykk mot områder med lavt trykk. Lufttrykk er vekten av lufta over et punkt.', array['Forklarer at lufttrykk er vekten av lufta over et punkt.', 'Forklarer at trykkgradientkraften driver luft fra høyt mot lavt trykk.']::text[], 0),
  ('geofag-2:coriolis-trykk-og-havstrommer', 's02', 'En vind beveger seg over store avstander på den sørlige halvkule. Hvilken vei blir vinden avbøyd av corioliseffekten, og hva er årsaken?', 'Vinden blir avbøyd mot venstre. Det skyldes at jorda roterer.', array['Angir at avbøyningen er mot venstre på den sørlige halvkule.', 'Knytter avbøyningen til jordrotasjonen.']::text[], 1),
  ('geofag-2:coriolis-trykk-og-havstrommer', 's03', 'Sammenlign geostrofisk vind høyt over bakken med vind nær bakken. Ta med både retningen i forhold til isobarene og hvilken rolle friksjon spiller.', 'Høyt over bakken, der friksjonen er liten, blåser geostrofisk vind parallelt med isobarene fordi trykkgradientkraften og corioliseffekten er i balanse. Nær bakken bremser friksjonen vinden, som da blåser litt inn mot lavtrykket.', array['Forklarer at geostrofisk vind blåser parallelt med isobarene når kreftene er i balanse.', 'Forklarer at friksjon nær bakken bremser vinden, slik at den blåser inn mot lavtrykket.']::text[], 2),
  ('geofag-2:coriolis-trykk-og-havstrommer', 's04', 'En vind blåser rett mot nord på den nordlige halvkule. Ekman-transporten går omtrent 90° til høyre for vinden. Regn ut hvilken himmelretning vanntransporten går i.', 'Vanntransporten går omtrent mot øst. Når du står vendt mot nord, er øst 90° til høyre.', array['Regner ut at retningen 90° til høyre for nord er øst.', 'Bruker at Ekman-transporten går til høyre for vinden på den nordlige halvkule.']::text[], 3),
  ('geofag-2:coriolis-trykk-og-havstrommer', 's05', 'Den termohaline sirkulasjonen kan bruke rundt 1000 år på én runde. Omtrent hvor lang tid tar to runder dersom hver runde tar like lang tid? Vis det viktigste regnestykket.', 'To runder tar rundt 2000 år. Regnestykket er 2 × 1000 år = 2000 år.', array['Multipliserer tiden for én runde med to.', 'Oppgir et resultat på rundt 2000 år.']::text[], 4),
  ('geofag-2:coriolis-trykk-og-havstrommer', 's06', 'Ved en kyst fører Ekman-transport overflatevann bort fra land. Beskriv hva som da skjer med vannet fra dypet.', 'Når overflatevannet føres bort fra land, strømmer kaldt, næringsrikt vann opp fra dypet. Dette kalles oppstrømning.', array['Forklarer at vann fra dypet strømmer opp når overflatevannet føres bort fra land.', 'Beskriver dypvannet som kaldt og næringsrikt, eller bruker begrepet oppstrømning riktig.']::text[], 5),
  ('geofag-2:coriolis-trykk-og-havstrommer', 's07', 'Sammenlign tettheten til kaldt, salt havvann med ferskere overflatevann i Nord-Atlanteren. Hvilket synker lettest, og hvorfor?', 'Kaldt og salt vann er tyngre og har større tetthet, så det synker lettere. Ferskere overflatevann er lettere og synker derfor ikke like lett.', array['Forklarer at kaldt og salt vann har høy tetthet og synker.', 'Forklarer at ferskere overflatevann er lettere, eller knytter ferskere vann til mindre tilbøyelighet til å synke.']::text[], 6),
  ('geofag-2:coriolis-trykk-og-havstrommer', 's08', 'Beskriv hvordan lufta beveger seg i et lavtrykk og et høytrykk på den nordlige halvkule, og knytt bevegelsen til været som ofte følger med.', 'I et lavtrykk stiger lufta, avkjøles og gir skyer og nedbør. I et høytrykk synker lufta og gir ofte klart og stabilt vær.', array['Knytter stigende luft i lavtrykk til avkjøling, skyer eller nedbør.', 'Knytter synkende luft i høytrykk til klart eller stabilt vær.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('geofag-2:vaersystemer-og-vaerkart', 'geofag-2', 'vaersystemer-og-vaerkart', 'Værsystemer og værkart', 'Hvordan værsystemer oppstår og utvikler seg på global, regional og lokal skala – luftmasser og fronter, polarfrontteorien og ekstratropiske lavtrykk, tropiske sykloner og monsun, lokale vinder som sjøbris og fønvind – og hvordan du tolker værkart og værutvikling.', array[4]::int[], 3, 'utkast', '{}'::text[], false, now())
