insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('geofag-2:forhistorisk-klima', 'q01', 'flervalg', 'Hva er proksydata?', array['Direkte temperaturmålinger', 'Indirekte data om fortidens klima', 'Værvarsler', 'Satellittbilder']::text[], 1, 'For eksempel iskjerner og pollen.', true, true, 0),
  ('geofag-2:forhistorisk-klima', 'q02', 'flervalg', 'Hva inneholder luftbobler i iskjerner?', array['Atmosfære fra fortiden', 'Vann fra havet', 'Pollen', 'Sand']::text[], 0, 'Vi kan måle CO₂ og metan direkte.', true, true, 1),
  ('geofag-2:forhistorisk-klima', 'q03', 'flervalg', 'Hvor langt tilbake går iskjernene fra Antarktis?', array['Omtrent 1000 år', 'Omtrent 10 000 år', 'Omtrent 800 000 år', 'Omtrent 100 millioner år']::text[], 2, 'Lange klimaserier.', true, true, 2),
  ('geofag-2:forhistorisk-klima', 'q04', 'flervalg', 'Hva styrer vekslingen mellom istider og mellomistider?', array['Vulkaner alene', 'Menneskelige utslipp', 'El Niño', 'Milanković-syklusene']::text[], 3, 'Endringer i jordbanen.', true, true, 3),
  ('geofag-2:forhistorisk-klima', 'q05', 'flervalg', 'Når begynte holocen?', array['For omtrent 11 700 år siden', 'For 800 000 år siden', 'For 56 millioner år siden', 'I 1850']::text[], 0, 'Dagens mellomistid.', true, true, 4),
  ('geofag-2:forhistorisk-klima', 'q06', 'flervalg', 'Hvilken Milanković-syklus har en periode på omtrent 41 000 år?', array['Eksentrisitet', 'Aksehelning', 'Presesjon', 'Solsyklusen']::text[], 1, 'Helningen av jordaksen.', true, true, 5),
  ('geofag-2:forhistorisk-klima', 'q07', 'flervalg', 'Hva viser iskjernene om CO₂ og temperatur?', array['At de ikke henger sammen', 'At CO₂ alltid har vært konstant', 'At de har fulgt hverandre tett', 'At temperaturen alltid har vært lik']::text[], 2, 'CO₂ har forsterket endringene.', true, true, 6),
  ('geofag-2:forhistorisk-klima', 'q08', 'flervalg', 'Hvordan brukes paleoklima til å forbedre klimamodeller?', array['Ved å varsle været', 'Ved å måle vind', 'Ved å telle trær', 'Ved å teste om modellene gjenskaper tidligere klima']::text[], 3, 'Også for å anslå klimafølsomheten.', true, true, 7),
  ('geofag-2:forhistorisk-klima', 'q09', 'flervalg', 'Hva er klimafølsomhet?', array['Hvor mye temperaturen stiger ved en dobling av CO₂', 'Hvor raskt været endres', 'Hvor følsomme mennesker er for kulde', 'Hvor mye is som smelter per år']::text[], 0, 'Et nøkkeltall i klimaforskningen.', true, false, 8),
  ('geofag-2:forhistorisk-klima', 'q10', 'flervalg', 'Hvordan er dagens CO₂-nivå sammenlignet med de siste 800 000 årene?', array['Lavere enn noen gang', 'Høyere enn noen gang', 'Helt vanlig', 'Ukjent']::text[], 1, 'Og endringen skjer mye raskere.', true, false, 9),
  ('geofag-2:forhistorisk-klima', 'm01', 'sant-usant', 'Under siste istid var havnivået over 100 meter lavere enn i dag.', array['Sant', 'Usant']::text[], 0, 'Mye vann var bundet i is.', false, true, 10),
  ('geofag-2:forhistorisk-klima', 'm02', 'sant-usant', 'Regelmessige temperaturmålinger finnes fra de siste 10 000 årene.', array['Sant', 'Usant']::text[], 1, 'De finnes bare fra omtrent 1850.', false, true, 11),
  ('geofag-2:forhistorisk-klima', 'm03', 'sant-usant', 'Klimaet har noen ganger endret seg brått på tiår.', array['Sant', 'Usant']::text[], 0, 'For eksempel ved slutten av siste istid.', false, true, 12),
  ('geofag-2:forhistorisk-klima', 'm04', 'sant-usant', 'Den lille istid var like stor og global som dagens oppvarming.', array['Sant', 'Usant']::text[], 1, 'Den var mer regional og mindre.', false, true, 13),
  ('geofag-2:forhistorisk-klima', 'm05', 'flervalg', 'Hva viser pollen i sedimenter?', array['Havtemperatur direkte', 'Hvilke planter som vokste', 'CO₂-innhold', 'Vindstyrke']::text[], 1, 'Gir informasjon om temperatur og nedbør.', false, true, 14),
  ('geofag-2:forhistorisk-klima', 'm06', 'flervalg', 'Hva gir innsikt i hva som skjer ved raske karbonutslipp?', array['Den varme perioden for omtrent 56 millioner år siden', 'Den lille istid', 'Holocen', 'Middelalderen']::text[], 0, 'Kraftig oppvarming på kort geologisk tid.', false, true, 15),
  ('geofag-2:forhistorisk-klima', 'm07', 'flervalg', 'Hvordan dateres klimaarkiver?', array['Bare ved å gjette', 'Med værmeldinger', 'Ved å telle årlag eller med radioaktive metoder', 'Med kompass']::text[], 2, 'Nødvendig for tidsserier.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('geofag-2:forhistorisk-klima', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('geofag-2:forhistorisk-klima', 's01', 'Hva undersøker paleoklimatologien, og hvorfor bruker forskere klimaarkiver når de undersøker klima før regelmessige temperaturmålinger begynte omkring 1850?', 'Paleoklimatologi undersøker klimaet før vi hadde direkte målinger. Siden regelmessige temperaturmålinger bare finnes fra omtrent 1850, bruker forskere naturlige klimaarkiver for å finne spor etter eldre klima.', array['Forklarer at paleoklimatologi gjelder klimaet før direkte målinger.', 'Knytter behovet for klimaarkiver til at regelmessige målinger bare finnes fra omtrent 1850.']::text[], 0),
  ('geofag-2:forhistorisk-klima', 's02', 'Et sedimentlag inneholder pollen. Forklar hva pollen kan fortelle om fortidens klima, og hvordan forskere bruker det til å trekke slutninger.', 'Pollen viser hvilke planter som vokste da sedimentet ble dannet. Ut fra plantene kan forskerne trekke slutninger om temperatur og nedbør.', array['Nevner at pollen gir informasjon om hvilke planter som vokste.', 'Knytter plantene til slutninger om temperatur og/eller nedbør.']::text[], 1),
  ('geofag-2:forhistorisk-klima', 's03', 'Sammenlign hva oksygenisotoper og årringer kan fortelle om fortidens klima.', 'Forholdet mellom tunge og lette oksygenisotoper kan fortelle om temperatur og ismengde. Årringer viser vekstforholdene år for år.', array['Knytter oksygenisotoper til temperatur og ismengde.', 'Knytter årringer til vekstforhold fra år til år.']::text[], 2),
  ('geofag-2:forhistorisk-klima', 's04', 'Hvorfor må forskere datere klimaarkiver før de bruker dem til å undersøke fortidens klima? Nevn to metoder for datering.', 'Datering viser når sporene i klimaarkivet ble dannet, slik at klimaopplysningene kan plasseres i tid. Forskere kan for eksempel telle årlag eller bruke radioaktive metoder.', array['Forklarer at datering plasserer klimainformasjonen i tid.', 'Nevner både telling av årlag og radioaktive metoder.']::text[], 3),
  ('geofag-2:forhistorisk-klima', 's05', 'Sammenlign middelalderens varmeperiode og den lille istid med dagens globale oppvarming når det gjelder geografisk utbredelse og størrelse.', 'Middelalderens varmeperiode og den lille istid var mer regionale og mindre enn dagens globale oppvarming. Dagens oppvarming er dermed større og mer globalt omfattende.', array['Beskriver de to eldre periodene som mer regionale enn dagens oppvarming.', 'Beskriver dem som mindre enn dagens globale oppvarming.']::text[], 4),
  ('geofag-2:forhistorisk-klima', 's06', 'Eksentrisitet har en periode på omtrent 100 000 år, mens presesjon har en periode på omtrent 23 000 år. Hvor mye lengre er perioden for eksentrisitet? Vis det viktigste regnestykket.', 'Perioden for eksentrisitet er omtrent 77 000 år lengre. Regnestykket er 100 000 − 23 000 = 77 000 år.', array['Regner ut differansen 100 000 − 23 000.', 'Oppgir svaret som omtrent 77 000 år.']::text[], 5),
  ('geofag-2:forhistorisk-klima', 's07', 'Holocen begynte for omtrent 11 700 år siden, og regelmessige temperaturmålinger begynte omkring 1850. Omtrent hvor mange år gikk det fra starten av holocen til 1850? Vis det viktigste regnestykket.', 'Det gikk omtrent 9 850 år. Regnestykket er 11 700 − 1 850 = 9 850 år.', array['Trekker 1 850 fra 11 700.', 'Oppgir et svar på omtrent 9 850 år.']::text[], 6),
  ('geofag-2:forhistorisk-klima', 's08', 'For omtrent 56 millioner år siden steg temperaturen kraftig etter at store mengder karbon ble sluppet ut. Forklar hvordan denne perioden kan være relevant når forskere undersøker konsekvensene av raske karbonutslipp i dag.', 'Perioden viser at store karbonutslipp på kort geologisk tid kan være knyttet til en kraftig temperaturøkning. Den gir derfor innsikt i mulige konsekvenser av raske karbonutslipp.', array['Knytter store karbonutslipp i perioden til den kraftige temperaturøkningen.', 'Forklarer at perioden gir innsikt i konsekvenser av raske karbonutslipp.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('geofag-2:klimaendringer-reduksjon-og-tilpasning', 'geofag-2', 'klimaendringer-reduksjon-og-tilpasning', 'Konsekvenser av klimaendringer, utslippskutt og tilpasning', 'Hvilke konsekvenser klimaendringer får for enkeltmennesker, samfunn og økosystemer i Norge og i verden, og hvordan vi kan redusere utslippene og tilpasse oss – fra Parisavtalen og klimapolitikk til bærekraftige valg i hverdagen.', array[8]::int[], 7, 'utkast', '{}'::text[], false, now())
