insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q01', 'flervalg', 'Hva er grensekostnaden?', array['Den totale kostnaden', 'K′(x) – omtrent kostnaden for én enhet til', 'K(x)/x', 'Den faste kostnaden']::text[], 1, 'Kostnaden ved neste enhet.', true, true, 0),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q02', 'flervalg', 'Når er overskuddet størst?', array['Når I′(x) = K′(x)', 'Når K(x) = 0', 'Når I(x) = 0', 'Når x er størst mulig']::text[], 0, 'O′(x) = 0.', true, true, 1),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q03', 'flervalg', 'Hva er grenseinntekten ved fast pris 150 kr?', array['0', '150x', '150 kr', 'Umulig å si']::text[], 2, 'I(x) = 150x gir I′(x) = 150.', true, true, 2),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q04', 'flervalg', 'Med K′(x) = 0,04x + 50 og pris 150 kr, hvilken x gir størst overskudd?', array['1000', '5000', '150', '2500']::text[], 3, '150 = 0,04x + 50.', true, true, 3),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q05', 'flervalg', 'Hvordan regnes enhetskostnaden ut?', array['K(x)/x', 'K′(x)', 'I(x) − K(x)', 'K(x) · x']::text[], 0, 'Gjennomsnittskostnad per enhet.', true, true, 4),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q06', 'flervalg', 'Når er enhetskostnaden lavest?', array['Når K(x) = 0', 'Når A(x) = K′(x)', 'Når I′ = K′', 'Når x = 0']::text[], 1, 'Grensekostnad lik gjennomsnittet.', true, true, 5),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q07', 'flervalg', 'Hva betyr I′(x) > K′(x)?', array['Det lønner seg å redusere produksjonen', 'Bedriften går med tap', 'Det lønner seg å øke produksjonen', 'Prisen er for lav']::text[], 2, 'Neste enhet gir mer enn den koster.', true, true, 6),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q08', 'flervalg', 'Hva betyr K′(2000) = 130?', array['Totalkostnaden er 130 kr', 'Enhetskostnaden er 130 kr', 'Overskuddet er 130 kr', 'Enhet nummer 2001 koster omtrent 130 kr']::text[], 3, 'Grensekostnaden.', true, true, 7),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q09', 'flervalg', 'Hva er laveste enhetskostnad når K(x) = 0,02x² + 50x + 20 000?', array['90 kr', '50 kr', '70 kr', '110 kr']::text[], 0, 'A(1000) = 20 + 50 + 20.', true, false, 8),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'q10', 'flervalg', 'Hva gir ∫ₐᵇ K′(x) dx?', array['Overskuddet', 'Økningen i kostnad fra a til b enheter', 'Grenseinntekten', 'Enhetskostnaden']::text[], 1, 'Total endring.', true, false, 9),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'm01', 'sant-usant', 'Faste kostnader påvirker ikke grensekostnaden.', array['Sant', 'Usant']::text[], 0, 'Den deriverte av en konstant er 0.', false, true, 10),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'm02', 'sant-usant', 'Overskuddet er alltid størst når produksjonen er størst mulig.', array['Sant', 'Usant']::text[], 1, 'Det er størst når I′ = K′.', false, true, 11),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'm03', 'sant-usant', 'Er grensekostnaden lavere enn enhetskostnaden, synker enhetskostnaden når x øker.', array['Sant', 'Usant']::text[], 0, 'Neste enhet trekker gjennomsnittet ned.', false, true, 12),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'm04', 'sant-usant', 'Grenseinntekten øker alltid når prisen må settes ned for å selge mer.', array['Sant', 'Usant']::text[], 1, 'Den synker da.', false, true, 13),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'm05', 'flervalg', 'Hva er O(2500) når K(x) = 0,02x² + 50x + 20 000 og prisen er 150 kr?', array['375 000 kr', '105 000 kr', '270 000 kr', '125 000 kr']::text[], 1, '375 000 − 270 000.', false, true, 14),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'm06', 'flervalg', 'Hvorfor stiger ofte grensekostnaden ved høy produksjon?', array['Presset kapasitet, overtid og slitasje', 'Lavere lønninger', 'Færre kunder', 'Lavere husleie']::text[], 0, 'Flaskehalser.', false, true, 15),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 'm07', 'flervalg', 'Hva er I(x) når prisen er p(x) = 200 − 0,01x?', array['200 − 0,01x', '200x', '200x − 0,01x²', '0,01x²']::text[], 2, 'I(x) = p(x) · x.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 's01', 'En bedrifts kostnader består av faste og variable kostnader. Forklar forskjellen på disse, og hvordan de påvirkes når bedriften produserer flere enheter.', 'Faste kostnader, som husleie, avhenger ikke av hvor mange enheter bedriften produserer. Variable kostnader øker når produksjonen øker.', array['Forklarer at faste kostnader ikke avhenger av produksjonsmengden.', 'Forklarer at variable kostnader øker med produksjonsmengden.']::text[], 0),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 's02', 'Grensekostnaden kan først synke og senere stige når produksjonen øker. Forklar hvorfor begge deler kan skje.', 'Grensekostnaden kan synke fordi produksjonen blir mer effektiv. Senere kan den stige fordi kapasiteten presses, for eksempel gjennom overtid, slitasje eller flaskehalser.', array['Knytter først synkende grensekostnad til økt effektivitet.', 'Knytter senere stigende grensekostnad til presset kapasitet, med en relevant følge.']::text[], 1),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 's03', 'Forklar forskjellen på grensekostnad og enhetskostnad. Hva skjer med enhetskostnaden når grensekostnaden er lavere eller høyere enn gjennomsnittet?', 'Grensekostnaden er omtrent kostnaden for å produsere én enhet til, mens enhetskostnaden er gjennomsnittskostnaden per enhet. Er grensekostnaden lavere enn gjennomsnittet, trekkes enhetskostnaden ned; er den høyere, trekkes den opp.', array['Skiller mellom kostnaden for én ekstra enhet og gjennomsnittskostnaden per enhet.', 'Forklarer riktig hvordan grensekostnaden påvirker gjennomsnittet når den er lavere eller høyere.']::text[], 2),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 's04', 'Sammenlign grenseinntekten når bedriften selger til fast pris, med situasjonen der den må sette ned prisen for å selge mer. Hvordan utvikler grenseinntekten seg i de to tilfellene?', 'Ved fast pris er grenseinntekten lik prisen og dermed konstant. Hvis bedriften må sette ned prisen for å selge mer, synker grenseinntekten når mengden øker.', array['Beskriver grenseinntekten ved fast pris som lik prisen og konstant.', 'Beskriver at grenseinntekten synker når prisen må settes ned for å selge mer.']::text[], 3),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 's05', 'En bedrifts grensekostnad er K′(x) = 0,04x + 50 kroner. Hvor mye øker kostnaden når produksjonen øker fra 1000 til 2000 enheter? Bruk integralet av grensekostnaden.', 'Kostnadsøkningen er ∫₁₀₀₀²⁰⁰⁰ (0,04x + 50) dx = [0,02x² + 50x]₁₀₀₀²⁰⁰⁰ = 110 000 kroner.', array['Setter opp integralet av K′(x) fra 1000 til 2000.', 'Finner kostnadsøkningen 110 000 kroner ved å regne ut integralet.']::text[], 4),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 's06', 'En bedrifts kostnadsfunksjon er K(x) = 0,02x² + 50x + 20 000. Finn enhetskostnaden når bedriften produserer 500 enheter. Vis det viktigste regnetrinnet.', 'K(500) = 0,02 · 500² + 50 · 500 + 20 000 = 50 000 kroner. Enhetskostnaden er A(500) = 50 000/500 = 100 kroner per enhet.', array['Finner at K(500) = 50 000 kroner.', 'Deler kostnaden på 500 og finner enhetskostnaden 100 kroner per enhet.']::text[], 5),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 's07', 'Forklar hvorfor faste kostnader som husleie ikke endrer grensekostnaden for én ekstra produsert enhet.', 'Faste kostnader er de samme uansett hvor mange enheter som produseres. Derfor gir de ingen økning i kostnaden når bedriften produserer én enhet til.', array['Forklarer at faste kostnader ikke endres med produksjonsmengden.', 'Knytter dette til at grensekostnaden gjelder kostnadsøkningen for én ekstra enhet.']::text[], 6),
  ('matematikk-s2:grensekostnad-og-grenseinntekt', 's08', 'En modell beregner at overskuddet er størst ved produksjon av 2500 enheter. Hva bør bedriften undersøke før den bruker dette resultatet i praksis?', 'Bedriften bør undersøke om 2500 enheter er et realistisk antall innenfor kapasiteten, og om modellen gjelder for denne produksjonsmengden. I virkeligheten kan blant annet konkurrenter, sesongvariasjoner og kapasitet påvirke priser og kostnader.', array['Nevner at produksjonsmengden må være realistisk og innenfor kapasiteten.', 'Forklarer at modellen må være gyldig for den aktuelle mengden, eventuelt med en relevant påvirkning fra virkeligheten.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-s2:forventning-varians-og-standardavvik', 'matematikk-s2', 'forventning-varians-og-standardavvik', 'Forventningsverdi, varians og standardavvik', 'Stokastiske variabler og sannsynlighetsfordelinger, hvordan du regner ut og tolker forventningsverdi, varians og standardavvik, regneregler for summer og lineære endringer, og anvendelser i spill, forsikring og risikovurdering.', array[7]::int[], 7, 'utkast', '{}'::text[], false, now())
