  ('matematikk-s2:normalfordelingen', 'Kontinuerlig variabel', 'Kan ta alle verdier i et intervall.', 0),
  ('matematikk-s2:normalfordelingen', 'Sannsynlighetstetthet', 'Funksjon der arealet under grafen er sannsynlighet.', 1),
  ('matematikk-s2:normalfordelingen', 'P(a < X < b)', '∫ₐᵇ f(x) dx', 2),
  ('matematikk-s2:normalfordelingen', 'P(X = a) kontinuerlig', '0', 3),
  ('matematikk-s2:normalfordelingen', 'Normalfordeling', 'Symmetrisk klokkeform bestemt av μ og σ.', 4),
  ('matematikk-s2:normalfordelingen', 'μ ± σ', 'Omtrent 68 % av verdiene.', 5),
  ('matematikk-s2:normalfordelingen', 'μ ± 2σ', 'Omtrent 95 % av verdiene.', 6),
  ('matematikk-s2:normalfordelingen', 'μ ± 3σ', 'Omtrent 99,7 % av verdiene.', 7),
  ('matematikk-s2:normalfordelingen', 'Standardisering', 'Z = (X − μ)/σ', 8),
  ('matematikk-s2:normalfordelingen', 'Standardnormalfordeling', 'μ = 0 og σ = 1.', 9),
  ('matematikk-s2:normalfordelingen', 'Φ(z)', 'P(Z ≤ z) – finnes i tabell.', 10),
  ('matematikk-s2:normalfordelingen', 'z for 5 % nedre hale', 'Omtrent −1,645.', 11),
  ('matematikk-s2:normalfordelingen', 'InversNormal', 'GeoGebra-kommando som finner x fra en sannsynlighet.', 12),
  ('matematikk-s2:normalfordelingen', 'norm.cdf', 'Python-funksjon for P(X ≤ x).', 13),
  ('matematikk-s2:normalfordelingen', 'Skjevfordeling', 'Fordeling med lang hale – for eksempel inntekter.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-s2:normalfordelingen', 'q01', 'flervalg', 'Omtrent hvor stor andel ligger innenfor μ ± 2σ?', array['68 %', '95 %', '99,7 %', '50 %']::text[], 1, '68–95–99,7-regelen.', true, true, 0),
  ('matematikk-s2:normalfordelingen', 'q02', 'flervalg', 'Hva er Z når X = 730, μ = 750 og σ = 10?', array['−2', '2', '−20', '0,2']::text[], 0, '(730 − 750)/10.', true, true, 1),
  ('matematikk-s2:normalfordelingen', 'q03', 'flervalg', 'Hva er P(X = 750) når X er kontinuerlig?', array['0,5', '1', '0', '0,68']::text[], 2, 'Én enkelt verdi har areal 0.', true, true, 2),
  ('matematikk-s2:normalfordelingen', 'q04', 'flervalg', 'Hva bestemmer σ i en normalfordeling?', array['Hvor toppen ligger', 'Arealet under kurven', 'Om kurven er symmetrisk', 'Hvor bred kurven er']::text[], 3, 'μ bestemmer plasseringen.', true, true, 3),
  ('matematikk-s2:normalfordelingen', 'q05', 'flervalg', 'Hva er P(740 < X < 760) når μ = 750 og σ = 10?', array['Omtrent 0,68', 'Omtrent 0,95', 'Omtrent 0,5', 'Omtrent 0,34']::text[], 0, 'μ ± σ.', true, true, 4),
  ('matematikk-s2:normalfordelingen', 'q06', 'flervalg', 'Hvordan finnes sannsynligheten i en kontinuerlig fordeling?', array['Som høyden på grafen', 'Som arealet under grafen', 'Som stigningstallet', 'Som μ']::text[], 1, 'Et integral av tettheten.', true, true, 5),
  ('matematikk-s2:normalfordelingen', 'q07', 'flervalg', 'Hva er P(X > 190) når μ = 180 og σ = 7?', array['Omtrent 0,5', 'Omtrent 0,025', 'Omtrent 0,076', 'Omtrent 0,16']::text[], 2, 'z ≈ 1,43.', true, true, 6),
  ('matematikk-s2:normalfordelingen', 'q08', 'flervalg', 'Hvorfor er normalfordelingen så vanlig?', array['Fordi alle data er symmetriske', 'Fordi den er lett å tegne', 'Fordi den har bare én parameter', 'Fordi summer av mange små uavhengige bidrag blir tilnærmet normalfordelt']::text[], 3, 'Sentralgrensesetningen.', true, true, 7),
  ('matematikk-s2:normalfordelingen', 'q09', 'flervalg', 'Hvilken vekt har de 5 % letteste brødposene under når μ = 750 g og σ = 10 g?', array['Omtrent 733,6 g', '740 g', '730 g', 'Omtrent 766,4 g']::text[], 0, '750 − 1,645 · 10.', true, false, 8),
  ('matematikk-s2:normalfordelingen', 'q10', 'flervalg', 'Hvilken type data er ofte ikke normalfordelt?', array['Målefeil', 'Inntekter', 'Vekt av produserte varer', 'Høyde']::text[], 1, 'Skjevfordelt med lang hale.', true, false, 9),
  ('matematikk-s2:normalfordelingen', 'm01', 'sant-usant', 'Hele arealet under en sannsynlighetstetthet er 1.', array['Sant', 'Usant']::text[], 0, 'Summen av alle sannsynligheter.', false, true, 10),
  ('matematikk-s2:normalfordelingen', 'm02', 'sant-usant', 'Normalfordelingen er skjev med lang hale mot høyre.', array['Sant', 'Usant']::text[], 1, 'Den er symmetrisk.', false, true, 11),
  ('matematikk-s2:normalfordelingen', 'm03', 'sant-usant', 'Z forteller hvor mange standardavvik en verdi ligger fra forventningen.', array['Sant', 'Usant']::text[], 0, 'Z = (X − μ)/σ.', false, true, 12),
  ('matematikk-s2:normalfordelingen', 'm04', 'sant-usant', 'Normalfordelingens tetthet kan enkelt integreres med kjente funksjoner.', array['Sant', 'Usant']::text[], 1, 'Vi må bruke tabell eller verktøy.', false, true, 13),
  ('matematikk-s2:normalfordelingen', 'm05', 'flervalg', 'Omtrent hvor stor andel ligger mer enn 2σ over forventningen?', array['5 %', '2,5 %', '16 %', '0,15 %']::text[], 1, 'Halvparten av de 5 % utenfor μ ± 2σ.', false, true, 14),
  ('matematikk-s2:normalfordelingen', 'm06', 'flervalg', 'Hvilken Python-funksjon gir P(X ≤ x) i en normalfordeling?', array['norm.cdf', 'norm.ppf', 'random.randint', 'print']::text[], 0, 'norm.ppf gir x fra en sannsynlighet.', false, true, 15),
  ('matematikk-s2:normalfordelingen', 'm07', 'flervalg', 'Hvor ligger toppen på normalfordelingskurven?', array['Ved μ + σ', 'Ved 0 alltid', 'Ved μ', 'Ved μ − 2σ']::text[], 2, 'Kurven er symmetrisk om μ.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-s2:normalfordelingen', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-s2:normalfordelingen', 's01', 'Høyde regnes som en kontinuerlig variabel. Forklar hva det betyr for hvilke verdier høyden kan ha.', 'En kontinuerlig variabel kan ta alle verdier i et intervall. Høyden trenger derfor ikke være et helt antall centimeter.', array['Forklarer at variabelen kan ta alle verdier i et intervall.', 'Knytter forklaringen til at høyde kan ha verdier mellom hele centimeter.']::text[], 0),
  ('matematikk-s2:normalfordelingen', 's02', 'Sammenlign hvilken rolle μ og σ har i en normalfordeling. Hva skjer med kurven hvis μ endres, eller hvis σ endres?', 'μ bestemmer forventningen og hvor toppen av kurven ligger. σ bestemmer hvor bred kurven er, så en endring i σ påvirker bredden.', array['Forklarer at μ bestemmer sentrum/toppen av kurven.', 'Forklarer at σ bestemmer bredden på kurven.']::text[], 1),
  ('matematikk-s2:normalfordelingen', 's03', 'Vekten av brødposer er normalfordelt med μ = 750 g og σ = 10 g. Finn intervallet som inneholder omtrent 95 % av vektene ved hjelp av 68–95–99,7-regelen.', 'Omtrent 95 % ligger innenfor μ ± 2σ. Det gir 750 ± 2 · 10, altså fra 730 g til 770 g.', array['Bruker intervallet μ ± 2σ for omtrent 95 %.', 'Regner ut riktige grenser: 730 g og 770 g.']::text[], 2),
  ('matematikk-s2:normalfordelingen', 's04', 'I en normalfordeling, omtrent hvor stor andel av verdiene ligger mellom μ + σ og μ + 2σ? Bruk 68–95–99,7-regelen og kurvens symmetri.', 'Mellom μ − 2σ og μ + 2σ ligger omtrent 95 %, og innenfor μ ± σ ligger omtrent 68 %. Forskjellen er 27 %, som fordeles likt på begge sider, så andelen er omtrent 13,5 %.', array['Finner forskjellen 95 % − 68 % = 27 %.', 'Bruker symmetrien til å dele forskjellen på to og får omtrent 13,5 %.']::text[], 3),
  ('matematikk-s2:normalfordelingen', 's05', 'Forklar hva standardisering gjør, og hva Z-verdien forteller om en observasjon.', 'Standardisering regner om X til Z = (X − μ)/σ, slik at verdien måles i standardavvik fra forventningen. Z forteller hvor mange standardavvik observasjonen ligger fra μ.', array['Beskriver standardisering som en omregning til Z, gjerne med formelen.', 'Forklarer at Z angir avstanden fra forventningen målt i standardavvik.']::text[], 4),
  ('matematikk-s2:normalfordelingen', 's06', 'En tabell gir verdien Φ(z). Forklar hvilken sannsynlighet denne verdien viser, og hvilket område under standardnormalfordelingen den gjelder.', 'Φ(z) er sannsynligheten P(Z ≤ z). Den viser arealet under kurven til venstre for z.', array['Knytter Φ(z) til P(Z ≤ z).', 'Forklarer at sannsynligheten gjelder området til venstre for z.']::text[], 5),
  ('matematikk-s2:normalfordelingen', 's07', 'Sammenlign GeoGebra-kommandoene Normal(μ, σ, x) og InversNormal(μ, σ, p). Hva finner hver av dem?', 'Normal(μ, σ, x) finner sannsynligheten for at X er mindre enn eller lik x. InversNormal(μ, σ, p) finner verdien x som svarer til sannsynligheten p.', array['Forklarer at Normal finner en sannsynlighet ut fra en x-verdi.', 'Forklarer at InversNormal finner en x-verdi ut fra en sannsynlighet.']::text[], 6),
  ('matematikk-s2:normalfordelingen', 's08', 'Inntekter kan være skjevfordelte med en lang hale mot høye verdier. Forklar hvorfor det er lurt å undersøke et histogram før man bruker en normalfordeling på slike data.', 'En normalfordeling er symmetrisk, mens skjevfordelte inntekter har en lang hale mot høye verdier. Et histogram kan vise om dataene er skjeve og dermed om normalfordelingen passer dårlig.', array['Knytter normalfordelingen til en symmetrisk form og inntekter til en skjev fordeling med lang hale mot høye verdier.', 'Forklarer at histogrammet brukes til å vurdere om dataene passer med normalfordelingen.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-s2:sentralgrensesetningen', 'matematikk-s2', 'sentralgrensesetningen', 'Sentralgrensesetningen', 'Hva sentralgrensesetningen sier om summer og gjennomsnitt av mange uavhengige variabler, hvordan du kan argumentere for den med simulering, normaltilnærming til binomisk fordeling, og praktiske eksempler som terningsummer, bagasjevekt og kvalitetskontroll.', array[10]::int[], 10, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-s2:sentralgrensesetningen', '## Hva sier setningen?
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-s2:sentralgrensesetningen', 'Sentralgrensesetningen', 'Summer og gjennomsnitt av mange uavhengige variabler er tilnærmet normalfordelte.', 0),
  ('matematikk-s2:sentralgrensesetningen', 'Sum av n variabler', 'Forventning nμ, standardavvik σ√n.', 1),
  ('matematikk-s2:sentralgrensesetningen', 'Gjennomsnitt av n variabler', 'Forventning μ, standardavvik σ/√n.', 2),
  ('matematikk-s2:sentralgrensesetningen', 'Uansett fordeling', 'Setningen gjelder selv om hver variabel ikke er normalfordelt.', 3),
  ('matematikk-s2:sentralgrensesetningen', 'Tommelfingerregel for n', 'n ≥ 30 er ofte nok.', 4),
  ('matematikk-s2:sentralgrensesetningen', 'Én terning', 'Uniform – flat fordeling.', 5),
  ('matematikk-s2:sentralgrensesetningen', 'Sum av to terninger', 'Trekantformet med topp ved 7.', 6),
  ('matematikk-s2:sentralgrensesetningen', 'Sum av ti terninger', 'Tydelig klokkeformet.', 7),
  ('matematikk-s2:sentralgrensesetningen', 'Normaltilnærming binomisk', 'X ≈ N(np, √(np(1 − p)))', 8),
  ('matematikk-s2:sentralgrensesetningen', 'Vilkår for normaltilnærming', 'np og n(1 − p) minst 5 – tommelfingerregel.', 9),
  ('matematikk-s2:sentralgrensesetningen', 'Heltallskorreksjon', 'Justering med 0,5 fra diskret til kontinuerlig fordeling.', 10),
  ('matematikk-s2:sentralgrensesetningen', 'Uavhengighet', 'Nødvendig forutsetning for setningen.', 11),
  ('matematikk-s2:sentralgrensesetningen', 'Utjevning', 'Store avvik i én variabel jevnes ut av de andre.', 12),
  ('matematikk-s2:sentralgrensesetningen', 'Sum av 100 terninger', 'Forventning 350, standardavvik omtrent 17,1.', 13),
  ('matematikk-s2:sentralgrensesetningen', 'Betydning', 'Forklarer hvorfor normalfordelingen er så vanlig.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-s2:sentralgrensesetningen', 'q01', 'flervalg', 'Hva sier sentralgrensesetningen?', array['At alle variabler er normalfordelte', 'At summer og gjennomsnitt av mange uavhengige variabler blir tilnærmet normalfordelte', 'At gjennomsnittet alltid er 0', 'At variansen er 1']::text[], 1, 'Uansett fordelingen til hver variabel.', true, true, 0),
  ('matematikk-s2:sentralgrensesetningen', 'q02', 'flervalg', 'Hva er standardavviket til gjennomsnittet av n variabler med standardavvik σ?', array['σ/√n', 'σ√n', 'nσ', 'σ']::text[], 0, 'Gjennomsnittet blir mer presist.', true, true, 1),
  ('matematikk-s2:sentralgrensesetningen', 'q03', 'flervalg', 'Hvilken form har fordelingen til summen av to terningkast?', array['Flat', 'Klokkeform', 'Trekant med topp ved 7', 'Skjev mot høyre']::text[], 2, 'Flest kombinasjoner gir 7.', true, true, 2),
  ('matematikk-s2:sentralgrensesetningen', 'q04', 'flervalg', 'Hva er forventningen til summen av 100 terningkast?', array['100', '600', '35', '350']::text[], 3, '100 · 3,5.', true, true, 3),
  ('matematikk-s2:sentralgrensesetningen', 'q05', 'flervalg', 'Hvilken normalfordeling tilnærmer en binomisk fordeling med n og p?', array['N(np, √(np(1 − p)))', 'N(p, n)', 'N(0, 1) alltid', 'N(n, p)']::text[], 0, 'Forventning np og varians np(1 − p).', true, true, 4),
  ('matematikk-s2:sentralgrensesetningen', 'q06', 'flervalg', 'Hvilken forutsetning er nødvendig for sentralgrensesetningen?', array['At variablene er normalfordelte', 'At variablene er uavhengige', 'At n = 2', 'At σ = 1']::text[], 1, 'Avhengighet kan gi en annen fordeling.', true, true, 5),
  ('matematikk-s2:sentralgrensesetningen', 'q07', 'flervalg', 'Hvorfor bruker vi heltallskorreksjon?', array['For å gjøre utregningen raskere', 'For å øke standardavviket', 'Fordi vi tilnærmer en diskret fordeling med en kontinuerlig', 'Fordi n er liten']::text[], 2, 'Justerer med 0,5.', true, true, 6),
  ('matematikk-s2:sentralgrensesetningen', 'q08', 'flervalg', 'Hva er standardavviket til summen av 100 uavhengige variabler med σ = 2?', array['200', '2', '0,2', '20']::text[], 3, '2 · √100.', true, true, 7),
  ('matematikk-s2:sentralgrensesetningen', 'q09', 'flervalg', 'Hva er P(X ≥ 60) omtrent ved 100 myntkast?', array['Omtrent 0,03', 'Omtrent 0,5', 'Omtrent 0,16', 'Omtrent 0,6']::text[], 0, 'Eksakt 0,028.', true, false, 8),
  ('matematikk-s2:sentralgrensesetningen', 'q10', 'flervalg', 'Hvorfor er ekstreme summer sjeldne?', array['Fordi terningene er skjeve', 'Fordi nesten alle enkeltutfall må være ekstreme samtidig', 'Fordi summen alltid er 350', 'Fordi variansen er null']::text[], 1, 'Avvik jevnes ut.', true, false, 9),
  ('matematikk-s2:sentralgrensesetningen', 'm01', 'sant-usant', 'Sentralgrensesetningen gjelder selv om hver variabel er uniformt fordelt.', array['Sant', 'Usant']::text[], 0, 'Terningeksempelet viser det.', false, true, 10),
  ('matematikk-s2:sentralgrensesetningen', 'm02', 'sant-usant', 'Gjennomsnittet av mange målinger får større spredning jo flere målinger vi tar.', array['Sant', 'Usant']::text[], 1, 'Spredningen σ/√n blir mindre.', false, true, 11),
  ('matematikk-s2:sentralgrensesetningen', 'm03', 'sant-usant', 'En binomisk variabel er en sum av mange forsøk som gir 0 eller 1.', array['Sant', 'Usant']::text[], 0, 'Derfor gjelder sentralgrensesetningen.', false, true, 12),
  ('matematikk-s2:sentralgrensesetningen', 'm04', 'sant-usant', 'Normaltilnærmingen er alltid god, selv for n = 3.', array['Sant', 'Usant']::text[], 1, 'Den krever stor n.', false, true, 13),
  ('matematikk-s2:sentralgrensesetningen', 'm05', 'flervalg', 'Hva er standardavviket til den samlede bagasjevekten for 180 kofferter med σ = 5 kg?', array['900 kg', 'Omtrent 67 kg', '5 kg', 'Omtrent 13 kg']::text[], 1, '5 · √180.', false, true, 14),
  ('matematikk-s2:sentralgrensesetningen', 'm06', 'flervalg', 'Hvilken tommelfingerregel brukes ofte for når n er stor nok?', array['n ≥ 30', 'n ≥ 2', 'n = 1000 nøyaktig', 'n ≤ 10']::text[], 0, 'Avhenger av hvor skjev fordelingen er.', false, true, 15),
  ('matematikk-s2:sentralgrensesetningen', 'm07', 'flervalg', 'Hvorfor er den totale bagasjevekten på et fly ganske forutsigbar?', array['Fordi alle kofferter veier likt', 'Fordi flyet veier kofferter', 'Fordi variasjonen i enkeltkofferter jevnes ut i summen', 'Fordi σ er null']::text[], 2, 'Relativ spredning σ√n/(nμ) blir liten.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-s2:sentralgrensesetningen', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-s2:sentralgrensesetningen', 's01', 'En måling har en uniform fordeling, men en forsker samler inn et stort utvalg av uavhengige målinger med samme fordeling. Forklar hvorfor forskeren likevel kan bruke en normalfordeling som tilnærming for gjennomsnittet når hun lager et konfidensintervall.', 'Sentralgrensesetningen sier at gjennomsnittet av mange uavhengige variabler med samme fordeling blir tilnærmet normalfordelt, selv om hver enkelt måling ikke er normalfordelt. Derfor kan normalfordelingen brukes til konfidensintervaller for gjennomsnittet.', array['Knytter normaltilnærmingen til gjennomsnittet av mange uavhengige målinger.', 'Får fram at målingene ikke selv trenger å være normalfordelte.']::text[], 0),
  ('matematikk-s2:sentralgrensesetningen', 's02', 'Summen av 100 uavhengige terningkast har standardavviket til ett kast lik √(35/12). Bruk standardavviket for en sum til å finne standardavviket til summen, omtrent.', 'Standardavviket til summen er √(100 · 35/12) ≈ 17,1.', array['Setter inn n = 100 i uttrykket σ√n, eller tilsvarende i variansen før kvadratroten tas.', 'Oppgir omtrent 17,1.']::text[], 1),
  ('matematikk-s2:sentralgrensesetningen', 's03', 'Vekten av hver koffert har forventning 20 kg og standardavvik 5 kg. Det er 180 passasjerer, og koffertvektene er uavhengige. Finn forventningen og standardavviket til den samlede bagasjevekten.', 'Forventningen er 180 · 20 = 3600 kg. Standardavviket er 5√180 ≈ 67 kg.', array['Beregner forventningen som 180 · 20 = 3600 kg.', 'Beregner standardavviket som 5√180 ≈ 67 kg.']::text[], 2),
  ('matematikk-s2:sentralgrensesetningen', 's04', 'En binomisk variabel teller antall kronesider i 100 myntkast, der sannsynligheten for kroneside er 0,5. Kontroller om tommelfingerregelen for normaltilnærming er oppfylt.', 'Her er np = 100 · 0,5 = 50 og n(1 − p) = 100 · 0,5 = 50. Begge er minst 5, så tommelfingerregelen er oppfylt.', array['Finner både np = 50 og n(1 − p) = 50.', 'Konkluderer med at begge verdiene oppfyller grensen på minst 5.']::text[], 3),
  ('matematikk-s2:sentralgrensesetningen', 's05', 'Forklar hva sentralgrensesetningen innebærer for påliteligheten til gjennomsnittet når utvalgsstørrelsen øker.', 'Gjennomsnittet blir mer konsentrert rundt forventningen når utvalget blir større. Standardavviket til gjennomsnittet er σ/√n, så spredningen blir mindre når n øker.', array['Forklarer at gjennomsnittet får mindre spredning når utvalgsstørrelsen øker.', 'Knytter dette til at gjennomsnittet blir mer pålitelig eller konsentrert rundt forventningen.']::text[], 4),
  ('matematikk-s2:sentralgrensesetningen', 's06', 'En modell brukes til å summere hvor mange kunder som kommer til en butikk, men kundene påvirker hverandre slik at antall besøk ikke er uavhengige. Forklar hvorfor sentralgrensesetningen ikke uten videre kan brukes på summen.', 'Uavhengighet er en nødvendig forutsetning for sentralgrensesetningen. Når kundene påvirker hverandre, er denne forutsetningen brutt, og summen kan få en annen fordeling enn den tilnærmede normalfordelingen.', array['Peker på at variablene ikke er uavhengige fordi kundene påvirker hverandre.', 'Forklarer at normaltilnærmingen derfor ikke uten videre kan begrunnes med sentralgrensesetningen.']::text[], 5),
  ('matematikk-s2:sentralgrensesetningen', 's07', 'En elev vil bruke normaltilnærming for summen av et lite antall variabler, og hver variabel har en svært skjev fordeling. Hvilket forbehold bør eleven ta?', 'Normaltilnærmingen kan være dårlig når antallet variabler er lite og fordelingen er svært skjev. Tommelfingerregelen om at n ≥ 30 ofte er nok, er ikke en garanti for at enhver tilnærming blir god.', array['Nevner at liten n kombinert med sterk skjevhet kan gi en dårlig tilnærming.', 'Skiller en tommelfingerregel fra en garanti, eller nevner at n ≥ 30 ofte er nok.']::text[], 6),
  ('matematikk-s2:sentralgrensesetningen', 's08', 'Sammenlign summen og gjennomsnittet av n uavhengige variabler med forventning μ og standardavvik σ. Hva er forventningen og standardavviket til hver av dem?', 'Summen har forventning nμ og standardavvik σ√n. Gjennomsnittet har forventning μ og standardavvik σ/√n.', array['Oppgir forventningene nμ for summen og μ for gjennomsnittet.', 'Oppgir standardavvikene σ√n for summen og σ/√n for gjennomsnittet.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-s2:hypotesetesting', 'matematikk-s2', 'hypotesetesting', 'Hypotesetesting', 'Hvordan du gjennomfører en hypotesetest på reelle data – nullhypotese og alternativ hypotese, signifikansnivå, p-verdi, ensidige og tosidige tester, test av en andel med binomisk fordeling og normaltilnærming – og hvordan du tolker resultatet og feiltypene.', array[11]::int[], 11, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-s2:hypotesetesting', '## Idéen
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-s2:hypotesetesting', 'Hypotesetest', 'Undersøker om data gir grunnlag for å påstå noe.', 0),
  ('matematikk-s2:hypotesetesting', 'Nullhypotese H₀', '«Ingen endring» – antas sann i utgangspunktet.', 1),
  ('matematikk-s2:hypotesetesting', 'Alternativ hypotese H₁', 'Det vi vil undersøke.', 2),
  ('matematikk-s2:hypotesetesting', 'Ensidig test', 'H₁ gjelder bare én retning.', 3),
  ('matematikk-s2:hypotesetesting', 'Tosidig test', 'H₁: p ≠ p₀ – p-verdien dobles.', 4),
  ('matematikk-s2:hypotesetesting', 'Signifikansnivå α', 'Grensen for å forkaste H₀ – ofte 5 %.', 5),
  ('matematikk-s2:hypotesetesting', 'p-verdi', 'Sannsynligheten for et minst like ekstremt resultat dersom H₀ er sann.', 6),
  ('matematikk-s2:hypotesetesting', 'Forkaste H₀', 'Når p-verdien ≤ α.', 7),
  ('matematikk-s2:hypotesetesting', 'Teststørrelse', 'Tallet vi bruker i testen, for eksempel antall defekte.', 8),
  ('matematikk-s2:hypotesetesting', 'Z for andel', '(p̂ − p₀)/√(p₀(1 − p₀)/n)', 9),
  ('matematikk-s2:hypotesetesting', 'Type I-feil', 'Forkaste H₀ selv om den er sann.', 10),
  ('matematikk-s2:hypotesetesting', 'Type II-feil', 'Beholde H₀ selv om den er usann.', 11),
  ('matematikk-s2:hypotesetesting', 'Beholde H₀', 'Betyr ikke at H₀ er bevist.', 12),
  ('matematikk-s2:hypotesetesting', 'Statistisk signifikant', 'Ikke nødvendigvis viktig i praksis.', 13),
  ('matematikk-s2:hypotesetesting', 'Skjevt utvalg', 'Gir feil konklusjon uansett test.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-s2:hypotesetesting', 'q01', 'flervalg', 'Hva er p-verdien?', array['Sannsynligheten for at H₀ er sann', 'Sannsynligheten for et minst like ekstremt resultat dersom H₀ er sann', 'Signifikansnivået', 'Andelen defekte']::text[], 1, 'Beregnes under antakelsen om H₀.', true, true, 0),
  ('matematikk-s2:hypotesetesting', 'q02', 'flervalg', 'Når forkaster vi H₀?', array['Når p-verdien ≤ α', 'Når p-verdien > α', 'Alltid', 'Når n er stor']::text[], 0, 'Resultatet er for usannsynlig under H₀.', true, true, 1),
  ('matematikk-s2:hypotesetesting', 'q03', 'flervalg', 'Hva er en type I-feil?', array['Å beholde en usann H₀', 'Å regne feil', 'Å forkaste en sann H₀', 'Å velge feil fordeling']::text[], 2, 'Sannsynligheten er α.', true, true, 2),
  ('matematikk-s2:hypotesetesting', 'q04', 'flervalg', 'Hva gjør vi med p-verdien i en tosidig test?', array['Halverer den', 'Tar kvadratroten', 'Lar den være', 'Dobler den']::text[], 3, 'Ekstreme resultater i begge retninger teller.', true, true, 3),
  ('matematikk-s2:hypotesetesting', 'q05', 'flervalg', 'I eksempelet med 10 defekte av 100 er p-verdien 0,028. Hva blir konklusjonen ved 5 % nivå?', array['Forkast H₀', 'Behold H₀', 'Testen er ugyldig', 'Vi trenger ikke konkludere']::text[], 0, '0,028 < 0,05.', true, true, 4),
  ('matematikk-s2:hypotesetesting', 'q06', 'flervalg', 'Hva betyr det å beholde H₀?', array['At H₀ er bevist', 'At vi ikke har grunnlag for å forkaste H₀', 'At H₁ er bevist', 'At dataene er feil']::text[], 1, 'Ikke et bevis for H₀.', true, true, 5),
  ('matematikk-s2:hypotesetesting', 'q07', 'flervalg', '60 kron på 100 kast gir tosidig p-verdi 0,057. Hva er konklusjonen ved 5 % nivå?', array['Mynten er skjev', 'Mynten er bevist rettferdig', 'Vi beholder H₀', 'Vi forkaster H₀']::text[], 2, '0,057 > 0,05.', true, true, 6),
  ('matematikk-s2:hypotesetesting', 'q08', 'flervalg', 'Når velges signifikansnivået?', array['Etter at p-verdien er regnet ut', 'Når resultatet er kjent', 'Det velges aldri', 'Før vi ser på dataene']::text[], 3, 'Ellers kan vi jukse med konklusjonen.', true, true, 7),
  ('matematikk-s2:hypotesetesting', 'q09', 'flervalg', 'Hva er en type II-feil?', array['Å beholde H₀ selv om den er usann', 'Å forkaste en sann H₀', 'Å bruke feil α', 'Å doble p-verdien']::text[], 0, 'Reduseres med større utvalg.', true, false, 8),
  ('matematikk-s2:hypotesetesting', 'q10', 'flervalg', 'Hvorfor er ikke statistisk signifikant alltid viktig?', array['Fordi signifikans er tilfeldig', 'Fordi små, uviktige forskjeller kan bli signifikante i store utvalg', 'Fordi p-verdien alltid er feil', 'Fordi α er for stor']::text[], 1, 'Skill mellom statistisk og praktisk betydning.', true, false, 9),
  ('matematikk-s2:hypotesetesting', 'm01', 'sant-usant', 'Et større utvalg reduserer sannsynligheten for type II-feil.', array['Sant', 'Usant']::text[], 0, 'Testen får større styrke.', false, true, 10),
  ('matematikk-s2:hypotesetesting', 'm02', 'sant-usant', 'Å forkaste H₀ beviser at H₁ er sann.', array['Sant', 'Usant']::text[], 1, 'Det gir et statistisk grunnlag, ikke et bevis.', false, true, 11),
  ('matematikk-s2:hypotesetesting', 'm03', 'sant-usant', 'Tester vi mange hypoteser, vil noen bli signifikante ved en tilfeldighet.', array['Sant', 'Usant']::text[], 0, 'Med α = 5 % omtrent én av tjue.', false, true, 12),
  ('matematikk-s2:hypotesetesting', 'm04', 'sant-usant', 'Nullhypotesen er vanligvis det vi ønsker å vise.', array['Sant', 'Usant']::text[], 1, 'Det er vanligvis den alternative hypotesen.', false, true, 13),
  ('matematikk-s2:hypotesetesting', 'm05', 'flervalg', 'Hvilken hypotese er riktig H₁ når vi mistenker at andelen er større enn 5 %?', array['p = 0,05', 'p > 0,05', 'p < 0,05', 'p ≠ 0,5']::text[], 1, 'Ensidig test.', false, true, 14),
  ('matematikk-s2:hypotesetesting', 'm06', 'flervalg', 'Hva er sannsynligheten for type I-feil?', array['α', 'p-verdien alltid', '1 − α', '0']::text[], 0, 'Signifikansnivået.', false, true, 15),
  ('matematikk-s2:hypotesetesting', 'm07', 'flervalg', 'Hva er et problem med et skjevt utvalg?', array['Det gjør testen raskere', 'Det gir alltid lav p-verdi', 'Det kan gi feil konklusjon uansett test', 'Det har ingen betydning']::text[], 2, 'Datainnsamlingen er avgjørende.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-s2:hypotesetesting', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-s2:hypotesetesting', 's01', 'Forklar hvordan en hypotesetest bruker nullhypotesen til å vurdere om data gir grunnlag for en påstand.', 'Nullhypotesen antas å være sann i utgangspunktet. Vi vurderer om dataene er så usannsynlige dersom H₀ stemmer, at de gir grunnlag for å forkaste den.', array['Forklarer at H₀ er utgangspunktet og antas sann i testen.', 'Knytter vurderingen til hvor usannsynlige dataene er dersom H₀ stemmer.']::text[], 0),
  ('matematikk-s2:hypotesetesting', 's02', 'To tester tar utgangspunkt i H₀: p = 0,05. Den ene undersøker om p er større enn 0,05, og den andre om p er forskjellig fra 0,05. Skriv H₁ for hver test, og forklar hvilken test som er ensidig og hvilken som er tosidig.', 'For testen som undersøker om p er større, er H₁: p > 0,05, og testen er ensidig. For testen som undersøker om p er forskjellig, er H₁: p ≠ 0,05, og testen er tosidig.', array['Oppgir H₁: p > 0,05 for den første testen og H₁: p ≠ 0,05 for den andre.', 'Knytter ensidig test til én retning og tosidig test til begge retninger.']::text[], 1),
  ('matematikk-s2:hypotesetesting', 's03', 'Hvis H₀ sier at andelen defekte varer er 5 %, hvor mange defekte varer forventer vi blant 100 varer dersom H₀ stemmer? Vis det viktigste regnestykket, og forklar kort hva tallet betyr.', '100 · 0,05 = 5. Dersom H₀ stemmer, er forventet antall defekte varer 5.', array['Regner ut 100 · 0,05 = 5.', 'Forklarer at 5 er forventet antall dersom H₀ stemmer.']::text[], 2),
  ('matematikk-s2:hypotesetesting', 's04', 'I en andelstest er p₀ = 0,5, n = 100 og observert andel p̂ = 0,6. Bruk formelen Z = (p̂ − p₀)/√(p₀(1 − p₀)/n) til å regne ut Z. Vis det viktigste steget.', 'Nevneren blir √(0,5 · 0,5/100) = √0,0025 = 0,05. Dermed er Z = (0,6 − 0,5)/0,05 = 2.', array['Finner at nevneren er 0,05.', 'Regner ut Z = 2 ved å bruke differansen 0,6 − 0,5 = 0,1.']::text[], 3),
  ('matematikk-s2:hypotesetesting', 's05', 'Forklar sammenhengen mellom signifikansnivået α og type I- og type II-feil. Ta også med hva et større utvalg gjør med type II-feil.', 'Et lavere α gir færre type I-feil, men flere type II-feil. Et større utvalg reduserer sannsynligheten for type II-feil.', array['Knytter lavere α til færre type I-feil og flere type II-feil.', 'Nevner at et større utvalg reduserer type II-feil.']::text[], 4),
  ('matematikk-s2:hypotesetesting', 's06', 'En meningsmåling bruker et utvalg som ikke representerer dem målingen skal si noe om. Forklar hvorfor en korrekt utført hypotesetest likevel kan gi en feil konklusjon.', 'Et skjevt utvalg gir data som ikke gir et pålitelig bilde av gruppen målingen gjelder. Hypotesetesten kan ikke rette opp skjevheten i datainnsamlingen.', array['Forklarer at utvalget ikke representerer gruppen målingen gjelder.', 'Forklarer at testen ikke kan kompensere for et skjevt utvalg.']::text[], 5),
  ('matematikk-s2:hypotesetesting', 's07', 'En svært stor studie finner en statistisk signifikant forskjell, men forskjellen er liten. Forklar hvorfor funnet ikke nødvendigvis er viktig i praksis.', 'Statistisk signifikans betyr ikke automatisk at forskjellen er praktisk viktig. I store utvalg kan selv små forskjeller bli statistisk signifikante.', array['Skiller mellom statistisk signifikans og praktisk betydning.', 'Knytter små signifikante forskjeller til at utvalget kan være stort.']::text[], 6),
  ('matematikk-s2:hypotesetesting', 's08', 'En forsker tester mange hypoteser på de samme dataene. Forklar hvorfor noen av testene kan bli statistisk signifikante ved en tilfeldighet.', 'Når mange hypoteser testes, øker muligheten for at enkelte resultater blir signifikante selv om de skyldes tilfeldigheter. Derfor bør signifikante funn fra mange tester tolkes med varsomhet.', array['Forklarer at noen signifikante funn kan oppstå tilfeldig.', 'Knytter dette til at mange hypoteser testes.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'matematikk-s2', 'gjennomsnitt-og-konfidensintervall', 'Test av gjennomsnitt og konfidensintervall', 'Hvordan du tester en påstand om et gjennomsnitt med normalfordelingen, hva som endres når standardavviket er ukjent, hvordan du lager og tolker konfidensintervaller for gjennomsnitt og andeler, og sammenhengen mellom konfidensintervall og hypotesetest.', array[10, 11]::int[], 12, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', '## Gjennomsnitt i et utvalg
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Standardfeil', 'σ/√n – standardavviket til gjennomsnittet.', 0),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Z for gjennomsnitt', '(x̄ − μ₀)/(σ/√n)', 1),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Utvalgets standardavvik s', 'Brukes når σ er ukjent.', 2),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 't-fordelingen', 'Brukes med ukjent σ – tykkere haler enn normalfordelingen.', 3),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'ttest_1samp', 'Python-funksjon for t-test av ett gjennomsnitt.', 4),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', '95 % konfidensintervall for μ', 'x̄ ± 1,96 · σ/√n', 5),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', '95 % konfidensintervall for andel', 'p̂ ± 1,96 · √(p̂(1 − p̂)/n)', 6),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Tolking av konfidensintervall', 'Metoden fanger den sanne verdien i 95 % av tilfellene.', 7),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Feilmargin', 'Halve bredden av konfidensintervallet.', 8),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Halvere feilmarginen', 'Krever fire ganger så stort utvalg.', 9),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', '99 % konfidensintervall', 'Bruker 2,576 – bredere intervall.', 10),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Test og intervall', 'Tosidig test forkaster når μ₀ ligger utenfor intervallet.', 11),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Representativt utvalg', 'Speiler populasjonen – nødvendig for gyldige konklusjoner.', 12),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'Feilmargin i meningsmåling', 'Tar bare hensyn til tilfeldig variasjon.', 13),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', '1,96', 'z-verdien for 95 % tosidig.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q01', 'flervalg', 'Hva er standardfeilen når σ = 6 og n = 36?', array['6', '1', '0,17', '36']::text[], 1, '6/√36.', true, true, 0),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q02', 'flervalg', 'Hva er Z når x̄ = 497,5, μ₀ = 500, σ = 6 og n = 36?', array['−2,5', '2,5', '−0,4', '−15']::text[], 0, '−2,5/1.', true, true, 1),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q03', 'flervalg', 'Hva er et 95 % konfidensintervall for μ?', array['x̄ ± σ', 'μ ± 1,96', 'x̄ ± 1,96 · σ/√n', 'x̄ ± 2,576 · σ']::text[], 2, 'Bruker standardfeilen.', true, true, 2),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q04', 'flervalg', 'Hva er feilmarginen når 30 % av 1000 svarer ja?', array['30 prosentpoeng', '1 prosentpoeng', '10 prosentpoeng', 'Omtrent 2,8 prosentpoeng']::text[], 3, '1,96 · √(0,21/1000).', true, true, 3),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q05', 'flervalg', 'Hvor mye større utvalg trengs for å halvere feilmarginen?', array['Fire ganger så stort', 'Dobbelt så stort', 'Halvparten så stort', 'Ti ganger så stort']::text[], 0, 'Feilmarginen avtar med √n.', true, true, 4),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q06', 'flervalg', 'Hva brukes når σ er ukjent og utvalget er lite?', array['Poissonfordelingen', 't-fordelingen', 'Uniform fordeling', 'Ingen test er mulig']::text[], 1, 'Med utvalgets standardavvik s.', true, true, 5),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q07', 'flervalg', 'Hva skjer med intervallet når konfidensnivået økes fra 95 % til 99 %?', array['Det blir smalere', 'Det blir uendret', 'Det blir bredere', 'Det forsvinner']::text[], 2, '2,576 i stedet for 1,96.', true, true, 6),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q08', 'flervalg', 'Når forkaster en tosidig test på 5 % nivå H₀: μ = μ₀?', array['Når μ₀ ligger midt i intervallet', 'Når intervallet er bredt', 'Når x̄ = μ₀', 'Når μ₀ ligger utenfor 95 % konfidensintervallet']::text[], 3, 'Test og intervall henger sammen.', true, true, 7),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q09', 'flervalg', 'Hvordan tolkes et 95 % konfidensintervall?', array['Metoden gir intervaller som inneholder den sanne verdien i 95 % av tilfellene', '95 % av dataene ligger i intervallet', 'μ endres i 95 % av tilfellene', 'Det er 95 % sikkert at x̄ er riktig']::text[], 0, 'Det er metoden som treffer.', true, false, 8),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'q10', 'flervalg', 'Hva tar feilmarginen i en meningsmåling ikke hensyn til?', array['Tilfeldig variasjon', 'At noen lar være å svare eller svarer uærlig', 'Utvalgets størrelse', 'Andelen som svarer ja']::text[], 1, 'Bare tilfeldig variasjon.', true, false, 9),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'm01', 'sant-usant', 'For store utvalg blir t-fordelingen og normalfordelingen nesten like.', array['Sant', 'Usant']::text[], 0, 'Forskjellen er størst for små utvalg.', false, true, 10),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'm02', 'sant-usant', 'En nettavstemning der alle kan svare, gir et gyldig konfidensintervall.', array['Sant', 'Usant']::text[], 1, 'Utvalget er ikke tilfeldig.', false, true, 11),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'm03', 'sant-usant', 'Større spredning i dataene gir bredere konfidensintervall.', array['Sant', 'Usant']::text[], 0, 'σ står i telleren.', false, true, 12),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'm04', 'sant-usant', 'To partier som skiller seg med mindre enn feilmarginen, kan sikkert rangeres.', array['Sant', 'Usant']::text[], 1, 'Forskjellen kan skyldes tilfeldigheter.', false, true, 13),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'm05', 'flervalg', 'Hva er 95 % konfidensintervallet for pakkene med x̄ = 497,5 og standardfeil 1?', array['[496,5, 498,5]', 'Omtrent [495,5, 499,5]', '[490, 505]', '[497,5, 500]']::text[], 1, '497,5 ± 1,96.', false, true, 14),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'm06', 'flervalg', 'Hva er den tosidige p-verdien når Z = −2,5?', array['Omtrent 0,012', 'Omtrent 0,006', 'Omtrent 0,05', 'Omtrent 0,5']::text[], 0, '2 · 0,0062.', false, true, 15),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 'm07', 'flervalg', 'Hvilken z-verdi brukes for et 99 % konfidensintervall?', array['1,645', '1,96', '2,576', '3']::text[], 2, 'Bredere enn 95 %.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 's01', 'Hva forteller standardfeilen om gjennomsnittet i et utvalg, og hvordan påvirkes den når utvalgsstørrelsen n øker?', 'Standardfeilen er standardavviket til gjennomsnittet og beregnes som σ/√n. Når n øker, blir standardfeilen mindre.', array['Forklarer at standardfeilen beskriver spredningen til gjennomsnittet.', 'Knytter standardfeilen til σ/√n og sier at den blir mindre når n øker.']::text[], 0),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 's02', 'Sammenlign testen av et gjennomsnitt når populasjonens standardavvik σ er kjent, med testen når σ er ukjent.', 'Når σ er kjent, bruker vi Z-teststørrelsen med σ/√n i nevneren. Når σ er ukjent, bruker vi utvalgets standardavvik s og t-fordelingen, som har tykkere haler enn normalfordelingen, særlig viktig for små utvalg.', array['Knytter kjent σ til Z-teststørrelsen.', 'Knytter ukjent σ til utvalgets standardavvik s og t-fordelingen.', 'Får fram at t-fordelingen har tykkere haler, særlig relevant ved små utvalg.']::text[], 1),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 's03', 'En maskin fyller pakker med gjennomsnittsvekt x̄ = 497,5 g. For utvalget er n = 36, og maskinens standardavvik er σ = 6 g. Bruk 99 %-intervallet x̄ ± 2,576 · σ/√n til å regne ut intervallet.', 'Standardfeilen er 6/√36 = 1 g. Intervallet blir 497,5 ± 2,576, altså omtrent [494,9, 500,1] g.', array['Finner standardfeilen 1 g.', 'Bruker 2,576 som feilmarginfaktor og får et intervall omtrent fra 494,9 g til 500,1 g.']::text[], 2),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 's04', 'I en tosidig test er P(Z ≤ −2,5) = 0,0062. Regn ut p-verdien og avgjør om H₀ forkastes på 5 % nivå.', 'P-verdien er 2 · 0,0062 = 0,0124, omtrent 0,012. Siden den er mindre enn 0,05, forkaster vi H₀.', array['Dobler sannsynligheten og finner p-verdi omtrent 0,012.', 'Sammenligner med 0,05 og konkluderer med at H₀ forkastes.']::text[], 3),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 's05', 'En maskin skal fylle pakker med 500 g i gjennomsnitt. Skriv nullhypotesen og den alternative hypotesen hvis du vil undersøke om maskinen i gjennomsnitt fyller feil mengde, uansett om mengden er for høy eller for lav.', 'Nullhypotesen er H₀: μ = 500 g. Den alternative hypotesen er H₁: μ ≠ 500 g, så testen er tosidig.', array['Oppgir H₀: μ = 500 g.', 'Oppgir H₁: μ ≠ 500 g eller forklarer at testen er tosidig.']::text[], 4),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 's06', 'Hva er forskjellen på et konfidensintervall for et gjennomsnitt og et konfidensintervall for en andel? Nevn hvilken verdi fra utvalget som brukes i hvert tilfelle.', 'Et intervall for et gjennomsnitt anslår populasjonsgjennomsnittet μ og tar utgangspunkt i utvalgsgjennomsnittet x̄. Et intervall for en andel anslår populasjonsandelen og tar utgangspunkt i utvalgsandelen p̂.', array['Knytter intervallet for gjennomsnitt til μ og x̄.', 'Knytter intervallet for andel til populasjonsandelen og p̂.']::text[], 5),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 's07', 'En nettavstemning om partipreferanser lar alle som besøker nettsiden svare. Hvorfor kan resultatet ikke uten videre brukes til å lage et gyldig konfidensintervall for alle velgere?', 'De som svarer, utgjør ikke nødvendigvis et tilfeldig og representativt utvalg av alle velgere. Derfor kan resultatet være skjevt, og et konfidensintervall basert på det er ikke nødvendigvis gyldig.', array['Forklarer at selvvalgte deltakere ikke nødvendigvis er et tilfeldig eller representativt utvalg.', 'Knytter dette til at konfidensintervallet ikke gir et gyldig grunnlag for konklusjoner om alle velgere.']::text[], 6),
  ('matematikk-s2:gjennomsnitt-og-konfidensintervall', 's08', 'I en meningsmåling er forskjellen mellom to partiers oppslutning mindre enn feilmarginen. Hva kan du konkludere om hvilket parti som er størst, og hvorfor?', 'Du kan ikke si sikkert hvilket parti som er størst. Forskjellen er mindre enn feilmarginen, så den kan skyldes tilfeldig variasjon i målingen.', array['Konkluderer med at det ikke er mulig å si sikkert hvilket parti som er størst.', 'Begrunner det med at forskjellen er mindre enn feilmarginen og kan skyldes tilfeldig variasjon.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('rettslare-2:rett-og-rettferd', 'rettslare-2', 'rett-og-rettferd', 'Rett og rettferd i en rettsstat', 'Skillet mellom det som er gjeldende rett og det som oppleves som rettferdig – naturrett og rettspositivisme, formell og materiell rettferdighet, urettferdige lover i historien, sivil ulydighet og hvordan rettsstaten forsøker å bygge bro mellom rett og rettferd.', array[1]::int[], 0, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('rettslare-2:rett-og-rettferd', '## Rett og rettferd er ikke det samme
insert into public.flashcards (tema_id, begrep, forklaring, sortering) values
  ('rettslare-2:rett-og-rettferd', 'Rett', 'Reglene som faktisk gjelder.', 0),
  ('rettslare-2:rett-og-rettferd', 'Rettferd', 'Moralsk vurdering av hva som er riktig og fortjent.', 1),
  ('rettslare-2:rett-og-rettferd', 'Naturrett', 'Allmenngyldige moralske prinsipper står over menneskeskapte lover.', 2),
  ('rettslare-2:rett-og-rettferd', 'Rettspositivisme', 'Retten er det som er vedtatt på riktig måte – rett og moral holdes atskilt.', 3),
  ('rettslare-2:rett-og-rettferd', 'Nürnbergprosessen', 'Rettssakene mot nazistiske ledere etter andre verdenskrig.', 4),
  ('rettslare-2:rett-og-rettferd', 'Formell rettferdighet', 'Like tilfeller behandles likt og upartisk.', 5),
  ('rettslare-2:rett-og-rettferd', 'Materiell rettferdighet', 'Innholdet i reglene og resultatet er rettferdig.', 6),
  ('rettslare-2:rett-og-rettferd', 'Jødeparagrafen', 'Nektet jøder adgang til Norge fram til 1851.', 7),
  ('rettslare-2:rett-og-rettferd', 'Fornorskingspolitikken', 'Politikk overfor samer, kvener og skogfinner forankret i lover og regler.', 8),
  ('rettslare-2:rett-og-rettferd', 'Sivil ulydighet', 'Åpent, ikkevoldelig lovbrudd i protest, der man aksepterer straffen.', 9),
  ('rettslare-2:rett-og-rettferd', 'Alta-aksjonen', 'Protest mot utbygging av Alta-Kautokeino-vassdraget rundt 1980.', 10),
  ('rettslare-2:rett-og-rettferd', 'Legalitetsprinsippet', 'Inngrep i borgernes frihet krever hjemmel i lov.', 11),
  ('rettslare-2:rett-og-rettferd', 'Reelle hensyn', 'Rimelighet og rettferdighet i tolkingen av uklare regler.', 12),
  ('rettslare-2:rett-og-rettferd', 'De lege lata', 'Hva retten er.', 13),
  ('rettslare-2:rett-og-rettferd', 'De lege ferenda', 'Hva retten bør være.', 14);
insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('rettslare-2:rett-og-rettferd', 'q01', 'flervalg', 'Hva hevder naturretten?', array['At retten er det som er vedtatt', 'At det finnes moralske prinsipper over menneskeskapte lover', 'At domstolene lager all rett', 'At moral er uviktig']::text[], 1, 'Grove brudd gjør loven ugyldig etter dette synet.', true, true, 0),
  ('rettslare-2:rett-og-rettferd', 'q02', 'flervalg', 'Hva er formell rettferdighet?', array['At like tilfeller behandles likt og reglene følges upartisk', 'At resultatet alltid er rimelig', 'At alle får det de ønsker', 'At lovene er moralsk gode']::text[], 0, 'Sier ikke noe om innholdet i reglene.', true, true, 1),
  ('rettslare-2:rett-og-rettferd', 'q03', 'flervalg', 'Hva kjennetegner sivil ulydighet?', array['Hemmelig lovbrudd', 'Voldelig protest', 'Åpent, ikkevoldelig lovbrudd der man aksepterer straffen', 'Lovlig demonstrasjon']::text[], 2, 'For eksempel Alta-aksjonen.', true, true, 2),
  ('rettslare-2:rett-og-rettferd', 'q04', 'flervalg', 'Hva betyr de lege ferenda?', array['Hva retten er', 'En type dom', 'En klage', 'Hva retten bør være']::text[], 3, 'Brukes når man drøfter lovendring.', true, true, 3),
  ('rettslare-2:rett-og-rettferd', 'q05', 'flervalg', 'Hva hevder rettspositivismen?', array['At retten er det som er vedtatt på riktig måte', 'At moral står over loven', 'At bare Gud kan gi lover', 'At domstoler ikke trengs']::text[], 0, 'Rett og moral holdes atskilt.', true, true, 4),
  ('rettslare-2:rett-og-rettferd', 'q06', 'flervalg', 'Hva gjorde jødeparagrafen i Grunnloven av 1814?', array['Ga jøder stemmerett', 'Nektet jøder adgang til riket', 'Beskyttet religionsfrihet', 'Innførte kongedømme']::text[], 1, 'Opphevet i 1851.', true, true, 5),
  ('rettslare-2:rett-og-rettferd', 'q07', 'flervalg', 'Hvilket prinsipp krever lovhjemmel for inngrep i borgernes frihet?', array['Maktfordelingsprinsippet', 'Offentlighetsprinsippet', 'Legalitetsprinsippet', 'Likhetsprinsippet']::text[], 2, 'Et grunnleggende rettsstatsprinsipp.', true, true, 6),
  ('rettslare-2:rett-og-rettferd', 'q08', 'flervalg', 'Hvorfor fikk naturrettstanken ny kraft etter andre verdenskrig?', array['Fordi alle lover ble opphevet', 'Fordi FN forbød rettspositivisme', 'Fordi Norge fikk ny grunnlov', 'Fordi mange overgrep hadde vært formelt lovlige']::text[], 3, 'Nürnbergprosessen bygde på dette.', true, true, 7),
  ('rettslare-2:rett-og-rettferd', 'q09', 'flervalg', 'Hva er materiell rettferdighet?', array['At innholdet i reglene og resultatet er rettferdig', 'At reglene følges likt', 'At dommeren er upartisk', 'At saken går raskt']::text[], 0, 'Handler om innholdet.', true, false, 8),
  ('rettslare-2:rett-og-rettferd', 'q10', 'flervalg', 'Hvordan kan en rettsstat endre urettferdige lover?', array['Gjennom vold', 'Gjennom demokratiske prosesser', 'Ved at dommerne ignorerer dem', 'Det er ikke mulig']::text[], 1, 'Stortinget kan vedta endringer.', true, false, 9),
  ('rettslare-2:rett-og-rettferd', 'm01', 'sant-usant', 'En dom kan være juridisk riktig og likevel oppleves som urettferdig.', array['Sant', 'Usant']::text[], 0, 'Rett og rettferd sammenfaller ikke alltid.', false, true, 10),
  ('rettslare-2:rett-og-rettferd', 'm02', 'sant-usant', 'Alt som er lovlig, er også rettferdig.', array['Sant', 'Usant']::text[], 1, 'Historien har mange eksempler på urettferdige lover.', false, true, 11),
  ('rettslare-2:rett-og-rettferd', 'm03', 'sant-usant', 'Aksjonistene i Alta-saken ble straffet.', array['Sant', 'Usant']::text[], 0, 'Men saken fikk stor betydning for samiske rettigheter.', false, true, 12),
  ('rettslare-2:rett-og-rettferd', 'm04', 'sant-usant', 'Rettspositivister mener at en lov er ugyldig hvis den er umoralsk.', array['Sant', 'Usant']::text[], 1, 'Det er naturrettens syn.', false, true, 13),
  ('rettslare-2:rett-og-rettferd', 'm05', 'flervalg', 'Hvem er et kjent eksempel på sivil ulydighet i USA?', array['Abraham Lincoln', 'Rosa Parks', 'George Washington', 'Richard Nixon']::text[], 1, 'Nektet å gi fra seg setet på bussen.', false, true, 14),
  ('rettslare-2:rett-og-rettferd', 'm06', 'flervalg', 'Hva betyr de lege lata?', array['Hva retten er', 'Hva retten bør være', 'En type straff', 'En domstol']::text[], 0, 'Gjeldende rett.', false, true, 15),
  ('rettslare-2:rett-og-rettferd', 'm07', 'flervalg', 'Hvilket spørsmål hører med i en drøfting av rett og rettferd?', array['Hvor lang loven er', 'Hvem som skrev loven', 'Hvilke hensyn taler for og mot regelen', 'Hvilket år loven ble trykt']::text[], 2, 'Forutsigbarhet, likhet og rimelighet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('rettslare-2:rett-og-rettferd', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('rettslare-2:rett-og-rettferd', 's01', 'En domstol avslår erstatning fordi foreldelsesfristen har gått ut. Legg til grunn at domstolen har fulgt regelen som gjelder. Forklar hvordan avgjørelsen kan være juridisk riktig, men likevel oppleves som urettferdig.', 'Avgjørelsen kan være juridisk riktig fordi domstolen har fulgt gjeldende regler. Den kan likevel oppleves som urettferdig fordi den som ble skadet, ikke får erstatning.', array['Skiller mellom at dommen følger gjeldende rett og at den oppleves rettferdig.', 'Knytter opplevelsen av urettferdighet til at offeret ikke får erstatning.']::text[], 0),
  ('rettslare-2:rett-og-rettferd', 's02', 'Jødeparagrafen nektet jøder adgang til Norge fram til 1851. Fornorskingspolitikken overfor samer, kvener og skogfinner var blant annet forankret i regler om jordkjøp og skole. Hva viser disse historiske eksemplene om forholdet mellom lover og rettferdighet?', 'Eksemplene viser at lover og regler som gjelder, ikke automatisk er rettferdige. Lovgivning kan brukes til å utestenge eller ramme grupper.', array['Får fram at lover som gjelder, ikke nødvendigvis er rettferdige.', 'Knytter dette til at lovene kunne ramme eller utestenge bestemte grupper.']::text[], 1),
  ('rettslare-2:rett-og-rettferd', 's03', 'Tenk deg at et flertall vedtar en lov som begrenser en minoritets frihet. Forklar hvordan menneskerettigheter og uavhengige domstoler kan bidra til å beskytte minoriteten.', 'Menneskerettighetene setter grenser for hva flertallet kan vedta. Uavhengige domstoler er en del av rettsstaten og kan bidra til at reglene blir prøvd uten å være underlagt flertallet.', array['Forklarer at menneskerettighetene setter grenser for flertallets makt.', 'Forklarer hvilken rolle uavhengige domstoler har som en del av rettsstaten.']::text[], 2),
  ('rettslare-2:rett-og-rettferd', 's04', 'En regel følges likt og upartisk for alle, men innholdet i regelen stenger én gruppe ute. Bruk begrepene formell og materiell rettferdighet til å forklare hvorfor lik behandling ikke nødvendigvis betyr at regelen er rettferdig.', 'At regelen følges likt og upartisk, kan være formelt rettferdig. Men hvis innholdet stenger en gruppe ute, kan regelen være materielt urettferdig.', array['Knytter lik og upartisk behandling til formell rettferdighet.', 'Viser at regelens innhold eller resultat kan være urettferdig selv om den brukes likt.']::text[], 3),
  ('rettslare-2:rett-og-rettferd', 's05', 'En lovregel er uklar og kan forstås på to måter. Forklar hvordan en domstol kan bruke reelle hensyn når den skal tolke regelen.', 'Domstolen kan legge vekt på rimelighet og rettferdighet når den velger mellom mulige tolkninger av en uklar regel. Slike vurderinger kalles reelle hensyn.', array['Får fram at reelle hensyn gjelder rimelighet og rettferdighet.', 'Forklarer at hensynene kan brukes i tolkingen av en uklar regel.']::text[], 4),
  ('rettslare-2:rett-og-rettferd', 's06', 'Alta-aksjonen var en protest mot utbyggingen av Alta-Kautokeino-vassdraget rundt 1980. Aksjonistene ble straffet. Forklar hvilken betydning aksjonen likevel fikk.', 'Aksjonen fikk stor betydning for samiske rettigheter. At aksjonistene ble straffet, hindret ikke at protesten bidro til å sette saken og rettighetene på dagsordenen.', array['Nevner betydningen aksjonen fikk for samiske rettigheter.', 'Får fram at aksjonen hadde betydning utover at aksjonistene ble straffet.']::text[], 5),
  ('rettslare-2:rett-og-rettferd', 's07', 'Forklar hvordan maktfordeling og uavhengige domstoler bidrar til at et samfunn er en rettsstat.', 'Maktfordeling innebærer at makten ikke er samlet hos én del av staten. Uavhengige domstoler er en del av ordningen som skal støtte rettsstaten.', array['Får fram at maktfordeling innebærer at makten er fordelt.', 'Knytter uavhengige domstoler til rettsstatens oppbygning eller funksjon.']::text[], 6),
  ('rettslare-2:rett-og-rettferd', 's08', 'I en diskusjon sier én person hva retten krever i dag, mens en annen sier hvordan loven bør endres. Bruk begrepene de lege lata og de lege ferenda til å forklare forskjellen mellom de to synspunktene.', 'Synspunktet om hva retten krever i dag, er de lege lata. Synspunktet om hvordan loven bør være, er de lege ferenda.', array['Knytter de lege lata til hva retten er eller krever nå.', 'Knytter de lege ferenda til hva retten bør være eller hvordan den bør endres.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('rettslare-2:rettskilder-og-juridisk-drofting', 'rettslare-2', 'rettskilder-og-juridisk-drofting', 'Rettskilder og juridisk drøfting', 'Hvordan du bruker rettskildene til å løse juridiske problemstillinger – tolking av lovtekst, vekting av forarbeider, rettspraksis og reelle hensyn, prinsipper for motstrid – og hvordan du bygger opp en fullstendig juridisk drøfting fra parter og krav til konklusjon.', array[2, 3]::int[], 1, 'utkast', '{}'::text[], false, now())
