  ('rettslare-2:rettskilder-og-juridisk-drofting', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('rettslare-2:rettskilder-og-juridisk-drofting', 's01', 'En lovregel ser etter ordlyden ut til å omfatte mange tilfeller. En jurist tolker regelen slik at den bare gjelder færre av dem. Hva kalles denne typen tolking, og hva skjer med regelens rekkevidde?', 'Dette er innskrenkende tolking. Regelen gjelder færre tilfeller enn ordlyden tilsier.', array['Identifiserer innskrenkende tolking.', 'Forklarer at regelen får snevrere rekkevidde enn ordlyden tilsier.']::text[], 0),
  ('rettslare-2:rettskilder-og-juridisk-drofting', 's02', 'En regel nevner sykler, men ikke et annet kjøretøy. Forklar forskjellen på å bruke regelen analogisk på det andre kjøretøyet og å tolke regelen antitetisk.', 'Ved analogi brukes regelen på det andre kjøretøyet fordi det ligner på sykler, selv om det ikke er nevnt. Ved antitetisk tolking regnes det som ikke nevnt, og dermed som ikke omfattet av regelen.', array['Forklarer at analogi bruker regelen på et lignende, ikke nevnt tilfelle.', 'Forklarer at antitetisk tolking holder det som ikke er nevnt, utenfor regelen.']::text[], 1),
  ('rettslare-2:rettskilder-og-juridisk-drofting', 's03', 'To norske regler gir motstridende svar i samme sak. Den ene regelen er nyere enn den andre. Hvilket tolkningsprinsipp er relevant, og hvilken regel går foran?', 'Lex posterior er relevant. Etter dette prinsippet går den nyere regelen foran den eldre.', array['Identifiserer lex posterior.', 'Forklarer at den nyere regelen går foran den eldre ved motstrid.']::text[], 2),
  ('rettslare-2:rettskilder-og-juridisk-drofting', 's04', 'Sammenlign hva forarbeider og avgjørelser fra Høyesterett kan bidra med når en lovregel skal tolkes. Ta også med én situasjon der en av kildene får særlig vekt.', 'Forarbeider kan vise lovgivers formål, og de veier særlig tungt for nye lover. Høyesteretts avgjørelser er svært viktige, særlig avgjørelser fra storkammer eller plenum.', array['Forklarer at forarbeider kan belyse lovgivers formål, særlig ved nye lover.', 'Forklarer at Høyesteretts avgjørelser har stor vekt, og gjerne nevner storkammer eller plenum.']::text[], 3),
  ('rettslare-2:rettskilder-og-juridisk-drofting', 's05', 'En vare slutter å virke 18 måneder etter at den ble levert. Selgeren viser ikke at feilen oppsto etter leveringen. Hva følger av regelen om feil som viser seg innen to år?', 'Feilen antas å ha vært til stede ved leveringen, fordi den viste seg innen to år. Selgeren kan avkrefte denne antakelsen ved å vise noe annet.', array['Anvender toårsregelen og sier at feilen antas å ha vært til stede ved levering.', 'Får fram at selgeren kan vise at feilen oppsto senere.']::text[], 4),
  ('rettslare-2:rettskilder-og-juridisk-drofting', 's06', 'Nora krever retting av en vare fra butikken hun kjøpte den i, men butikken avviser kravet. Hvem er partene i saken, og hva er Noras krav?', 'Partene er Nora og butikken. Noras krav er at butikken retter varen.', array['Identifiserer Nora og butikken som partene.', 'Angir retting av varen som Noras krav.']::text[], 5),
  ('rettslare-2:rettskilder-og-juridisk-drofting', 's07', 'En kjøper mener at en vare har en mangel, mens selgeren er uenig. Kjøperen krever deretter retting. Forklar hva subsidiær drøfting innebærer for spørsmålet om retting dersom du først konkluderer med at det ikke foreligger en mangel.', 'Du kan likevel drøfte spørsmålet om retting subsidiært, for det tilfellet at det likevel skulle foreligge en mangel. Det betyr at du vurderer det neste spørsmålet selv om du først svarte nei på det første.', array['Forklarer at retting drøftes «for det tilfellet at» det likevel foreligger en mangel.', 'Viser at subsidiær drøfting lar deg gå videre til neste spørsmål selv om du først konkluderer med nei.']::text[], 6),
  ('rettslare-2:rettskilder-og-juridisk-drofting', 's08', 'Andre rettskilder gir ikke et klart svar mellom to mulige tolkninger av en regel. Forklar hvordan forutsigbarhet kan brukes som et reelt hensyn i vurderingen.', 'Man kan vurdere hvilken tolkning som gir mest forutsigbare utfall for dem regelen gjelder. Forutsigbarhet er et reelt hensyn som kan trekkes inn når de andre rettskildene ikke gir et klart svar.', array['Knytter forutsigbarhet til hvor forutsigbare regelens utfall blir.', 'Forklarer at reelle hensyn brukes når andre rettskilder ikke gir et klart svar.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('rettslare-2:aktuelle-rettssporsmal', 'rettslare-2', 'aktuelle-rettssporsmal', 'Dagsaktuelle juridiske problemstillinger', 'Hvordan du utforsker og drøfter dagsaktuelle rettsspørsmål – å finne saken, kildene og interessene, skille mellom gjeldende rett og hva retten bør være – med eksempler som kunstig intelligens og opphavsrett, ytringsfrihet på nett, barnevern og menneskerettigheter, og nye straffebestemmelser.', array[4]::int[], 2, 'utkast', '{}'::text[], false, now())
