insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('rettslare-2:aktuelle-rettssporsmal', 'q01', 'flervalg', 'Hva er første steg når du skal utforske et aktuelt rettsspørsmål?', array['Skrive konklusjonen', 'Finne ut hva saken handler om og hvem som er involvert', 'Velge side', 'Lese kommentarfelt']::text[], 1, 'Deretter kildene.', true, true, 0),
  ('rettslare-2:aktuelle-rettssporsmal', 'q02', 'flervalg', 'Hvilken artikkel i EMK verner retten til familieliv?', array['Artikkel 8', 'Artikkel 2', 'Artikkel 10', 'Artikkel 3']::text[], 0, 'Viktig i barnevernssaker.', true, true, 1),
  ('rettslare-2:aktuelle-rettssporsmal', 'q03', 'flervalg', 'Hvilket spørsmål reiser KI i opphavsretten?', array['Om KI kan stemme', 'Om KI kan straffes', 'Om det er lovlig å trene KI på beskyttet materiale', 'Om KI trenger pass']::text[], 2, 'Mange spørsmål er uavklarte.', true, true, 2),
  ('rettslare-2:aktuelle-rettssporsmal', 'q04', 'flervalg', 'Hva verner Grunnloven § 100?', array['Eiendomsretten', 'Religionsfriheten', 'Stemmeretten', 'Ytringsfriheten']::text[], 3, 'Med grenser i straffeloven.', true, true, 3),
  ('rettslare-2:aktuelle-rettssporsmal', 'q05', 'flervalg', 'Hva betyr at en regel er samtykkebasert?', array['At det avgjørende er om det forelå samtykke', 'At begge parter må signere', 'At politiet må samtykke', 'At dommeren må godkjenne']::text[], 0, 'Voldtektsbestemmelsen ble samtykkebasert i 2025.', true, true, 4),
  ('rettslare-2:aktuelle-rettssporsmal', 'q06', 'flervalg', 'Hvorfor er ikke en avisartikkel en rettskilde?', array['Fordi aviser er forbudt', 'Fordi den bare omtaler saken og kan være vinklet', 'Fordi den er for kort', 'Fordi den er gratis']::text[], 1, 'Gå til loven og dommen selv.', true, true, 5),
  ('rettslare-2:aktuelle-rettssporsmal', 'q07', 'flervalg', 'Hva er rettssikkerhet som argument?', array['At straffene er strenge', 'At saker går raskt', 'At reglene er klare og forutsigbare', 'At alle får erstatning']::text[], 2, 'Et sentralt hensyn i rettsstaten.', true, true, 6),
  ('rettslare-2:aktuelle-rettssporsmal', 'q08', 'flervalg', 'Hvorfor bør du oppgi dato når du skriver om aktuelle saker?', array['Fordi det er pent', 'Fordi lærerne krever det', 'Fordi lover aldri endres', 'Fordi aktuelle saker endrer seg raskt']::text[], 3, 'Nye dommer og lover kan komme.', true, true, 7),
  ('rettslare-2:aktuelle-rettssporsmal', 'q09', 'flervalg', 'Hva er forholdsmessighet?', array['At inngrepet står i rimelig forhold til målet', 'At straffen er lik for alle', 'At loven er lang', 'At saken er stor']::text[], 0, 'Viktig ved menneskerettighetsinngrep.', true, false, 8),
  ('rettslare-2:aktuelle-rettssporsmal', 'q10', 'flervalg', 'Hva bør et arbeid med et aktuelt rettsspørsmål ende med?', array['Et sitat', 'Et begrunnet standpunkt', 'En avisoverskrift', 'Et spørsmål']::text[], 1, 'Støttet av argumenter og kilder.', true, false, 9),
  ('rettslare-2:aktuelle-rettssporsmal', 'm01', 'sant-usant', 'EMD har i flere saker kommet fram til at Norge har krenket retten til familieliv i barnevernssaker.', array['Sant', 'Usant']::text[], 0, 'Det har ført til endringer i praksis.', false, true, 10),
  ('rettslare-2:aktuelle-rettssporsmal', 'm02', 'sant-usant', 'Alle spørsmål om KI og opphavsrett er ferdig avklart.', array['Sant', 'Usant']::text[], 1, 'Mange er fortsatt uavklarte.', false, true, 11),
  ('rettslare-2:aktuelle-rettssporsmal', 'm03', 'sant-usant', 'Ytringsfriheten har grenser, for eksempel mot trusler.', array['Sant', 'Usant']::text[], 0, 'Straffeloven setter grenser.', false, true, 12),
  ('rettslare-2:aktuelle-rettssporsmal', 'm04', 'sant-usant', 'Et innlegg i sosiale medier er en rettskilde.', array['Sant', 'Usant']::text[], 1, 'Det er ikke en rettskilde.', false, true, 13),
  ('rettslare-2:aktuelle-rettssporsmal', 'm05', 'flervalg', 'Hvilket spørsmål handler om de lege ferenda?', array['Hva sier loven i dag?', 'Bør loven endres?', 'Hva står i paragrafen?', 'Hva sa Høyesterett?']::text[], 1, 'Hva retten bør være.', false, true, 14),
  ('rettslare-2:aktuelle-rettssporsmal', 'm06', 'flervalg', 'Hvor kan du finne informasjon om lovforslag?', array['stortinget.no og regjeringen.no', 'Bare i aviser', 'På sosiale medier', 'Hos naboen']::text[], 0, 'Offisielle kilder.', false, true, 15),
  ('rettslare-2:aktuelle-rettssporsmal', 'm07', 'flervalg', 'Hvilket demokratisk spørsmål reiser mange rettsdebatter?', array['Hvem som skal betale skatt', 'Om loven er trykt', 'Om spørsmålet bør avgjøres av Stortinget eller domstolene', 'Om dommerne liker saken']::text[], 2, 'Maktfordeling.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('rettslare-2:aktuelle-rettssporsmal', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('rettslare-2:aktuelle-rettssporsmal', 's01', 'Sammenlign de lege lata og de lege ferenda. Hva slags spørsmål prøver du å besvare med hvert av begrepene?', 'De lege lata handler om hva gjeldende rett er. De lege ferenda handler om hva retten bør være, for eksempel om en lov bør endres.', array['Skiller mellom gjeldende rett og hva retten bør være.', 'Knytter begrepene til ulike spørsmål om rettstilstanden.']::text[], 0),
  ('rettslare-2:aktuelle-rettssporsmal', 's02', 'Du undersøker både hvilken lovregel som gjelder i en sak, og hvordan en domstol har vurdert et lignende spørsmål. Hvilke nettsteder kan du bruke til å finne lovtekst og dommer?', 'Lovdata kan brukes til å finne lover og dommer. Domstol.no er også en relevant kilde når du leter etter informasjon om dommer.', array['Nevner Lovdata som kilde til lovtekst.', 'Nevner en egnet kilde til dommer, for eksempel Lovdata eller domstol.no.']::text[], 1),
  ('rettslare-2:aktuelle-rettssporsmal', 's03', 'En avisartikkel omtaler en aktuell rettssak og blander opplysninger om saken med vurderinger av utfallet. Beskriv to kontroller du bør gjøre før du bruker artikkelen i en juridisk drøfting.', 'Jeg bør undersøke hvem som står bak artikkelen og hvilke interesser avsenderen kan ha. Jeg bør skille fakta fra meninger og kontrollere omtalen mot dommen eller loven.', array['Vurderer avsenderen eller mulige interesser bak artikkelen.', 'Skiller mellom fakta og meninger, eller kontrollerer opplysningene mot dommen eller loven.']::text[], 2),
  ('rettslare-2:aktuelle-rettssporsmal', 's04', 'En bruker legger ut en trussel på en plattform. Forklar hvilke to rettslige hensyn som kan komme i konflikt, og hvorfor det ikke er nok å vise til ytringsfriheten alene.', 'Grunnloven § 100 verner ytringsfriheten, men straffeloven forbyr blant annet trusler. Derfor må man også vurdere om innholdet rammes av straffeloven.', array['Viser til at ytringsfriheten er vernet av Grunnloven § 100.', 'Får fram at trusler er forbudt etter straffeloven, slik at ytringsfriheten ikke alene avgjør saken.']::text[], 3),
  ('rettslare-2:aktuelle-rettssporsmal', 's05', 'Et rettsspørsmål er om opphavsrettslig beskyttet materiale kan brukes til å trene KI uten samtykke. Bruk interessekartlegging til å forklare hvem som kan vinne eller tape på ulike løsninger.', 'Hvis slik trening tillates uten samtykke, kan de som trener KI få større mulighet til å bruke materialet, mens rettighetshaverne kan tape kontroll over bruken. Et krav om samtykke kan styrke rettighetshavernes kontroll, men begrense tilgangen til materiale for KI-trening.', array['Identifiserer både aktører som trener KI og rettighetshavere som berørte interesser.', 'Forklarer hvordan ulike løsninger kan gi fordeler eller ulemper for disse aktørene.']::text[], 4),
  ('rettslare-2:aktuelle-rettssporsmal', 's06', 'EMD har i flere barnevernssaker kommet fram til at Norge krenket retten til familieliv etter EMK artikkel 8. Forklar hvordan slike avgjørelser kan påvirke norsk praksis og debatten om barnevern.', 'Avgjørelsene har ført til endringer i norsk praksis. De har også bidratt til debatt om hvordan barnets beste skal balanseres mot foreldrenes rettigheter.', array['Knytter EMDs avgjørelser til endringer i norsk praksis.', 'Forklarer at de aktualiserer balansen mellom barnets beste og foreldrenes rettigheter.']::text[], 5),
  ('rettslare-2:aktuelle-rettssporsmal', 's07', 'I debatten før den samtykkebaserte voldtektsbestemmelsen trådte i kraft, sto ulike hensyn mot hverandre. Forklar hvordan rettssikkerhet, vern av ofre og bevisspørsmål kan inngå i denne debatten.', 'En drøfting kan vurdere om regelen er klar og forutsigbar for den tiltalte, samtidig som den gir vern til ofre. Den må også ta hensyn til hvordan det kan bevises om samtykke manglet.', array['Knytter rettssikkerhet til klarhet eller forutsigbarhet for den tiltalte.', 'Får fram både hensynet til vern av ofre og at bevis for manglende samtykke kan være et spørsmål.']::text[], 6),
  ('rettslare-2:aktuelle-rettssporsmal', 's08', 'I en aktuell rettsdebatt kan spørsmålet være om en løsning bør komme gjennom en lovendring fra Stortinget eller gjennom domstolenes behandling av saken. Forklar hvilket demokratihensyn dette reiser.', 'Spørsmålet gjelder hvem som bør avgjøre rettsutviklingen. Demokrati kan tale for at Stortinget, som vedtar lover, bør avgjøre om loven skal endres, mens domstolene behandler rettsspørsmål i konkrete saker.', array['Får fram at spørsmålet gjelder hvem som bør avgjøre rettsutviklingen.', 'Knytter hensynet til demokrati til Stortingets rolle i å vedta lover.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('rettslare-2:demokrati-og-menneskerettigheter', 'rettslare-2', 'demokrati-og-menneskerettigheter', 'Demokrati og menneskerettigheter', 'Hvordan demokratiet er forankret i Grunnloven, og hvilke grunnleggende menneskerettigheter som verner det – ytringsfrihet, forsamlings- og foreningsfrihet, stemmerett og retten til rettferdig rettergang – med menneskerettsloven, EMK og Den europeiske menneskerettsdomstolen.', array[5]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('rettslare-2:demokrati-og-menneskerettigheter', '## Demokratiet i Grunnloven
