insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('psykologi-2:teorier-og-forklaringer', 'q01', 'flervalg', 'Hvilket perspektiv forklarer angst med tankemønstre?', array['Biologisk', 'Kognitivt', 'Psykodynamisk', 'Humanistisk']::text[], 1, 'Overvurdering av fare.', true, true, 0),
  ('psykologi-2:teorier-og-forklaringer', 'q02', 'flervalg', 'Hvordan forklarer læringspsykologien at angst opprettholdes?', array['Gjennom unngåelse som gir lettelse og forsterkes', 'Gjennom gener alene', 'Gjennom ubevisste drifter', 'Gjennom selvaktualisering']::text[], 0, 'Negativ forsterkning.', true, true, 1),
  ('psykologi-2:teorier-og-forklaringer', 'q03', 'flervalg', 'Hva er reduksjonisme?', array['Å se helheten', 'Å redusere antall deltakere', 'Å forklare ved å bryte ned til enkle deler', 'Å avvise all forskning']::text[], 2, 'Presist, men kan overse helheten.', true, true, 2),
  ('psykologi-2:teorier-og-forklaringer', 'q04', 'flervalg', 'Hva viser epigenetikk?', array['At gener ikke betyr noe', 'At miljø ikke betyr noe', 'At alle er like', 'At miljøet kan påvirke hvordan gener uttrykkes']::text[], 3, 'Arv og miljø samspiller.', true, true, 3),
  ('psykologi-2:teorier-og-forklaringer', 'q05', 'flervalg', 'Hvilken metode brukes ofte i det psykodynamiske perspektivet?', array['Kasusstudier', 'fMRI', 'Reaksjonstidsforsøk', 'Dyreforsøk']::text[], 0, 'Grundige studier av enkeltpersoner.', true, true, 4),
  ('psykologi-2:teorier-og-forklaringer', 'q06', 'flervalg', 'Hvilket spørsmål er viktig når du vurderer en forklaring?', array['Om den er gammel', 'Om den er støttet av empirisk forskning', 'Om den er lang', 'Om den er populær']::text[], 1, 'Også testbarhet og nytte.', true, true, 5),
  ('psykologi-2:teorier-og-forklaringer', 'q07', 'flervalg', 'Hvilket perspektiv legger vekt på kultur og sosiale forhold?', array['Biologisk', 'Kognitivt', 'Sosiokulturelt', 'Læringspsykologisk']::text[], 2, 'For eksempel prestasjonspress.', true, true, 6),
  ('psykologi-2:teorier-og-forklaringer', 'q08', 'flervalg', 'Hva brukes tvillingstudier til?', array['Å teste hukommelse', 'Å måle reaksjonstid', 'Å studere drømmer', 'Å undersøke betydningen av arv']::text[], 3, 'Sammenligner eneggede og toeggede tvillinger.', true, true, 7),
  ('psykologi-2:teorier-og-forklaringer', 'q09', 'flervalg', 'Hvilken behandling for angst bygger på kognitive og læringspsykologiske forklaringer?', array['Kognitiv atferdsterapi', 'Lobotomi', 'Drømmetydning', 'Hypnose']::text[], 0, 'Har sterk forskningsstøtte.', true, false, 8),
  ('psykologi-2:teorier-og-forklaringer', 'q10', 'flervalg', 'Hvorfor er en helhetlig forklaring ofte best?', array['Fordi den er kortest', 'Fordi fenomener som angst har årsaker på flere nivåer', 'Fordi den bare bruker ett perspektiv', 'Fordi den ikke kan testes']::text[], 1, 'Biologisk, psykologisk og sosialt.', true, false, 9),
  ('psykologi-2:teorier-og-forklaringer', 'm01', 'sant-usant', 'Ulike perspektiver kan utfylle hverandre.', array['Sant', 'Usant']::text[], 0, 'De forklarer på ulike nivåer.', false, true, 10),
  ('psykologi-2:teorier-og-forklaringer', 'm02', 'sant-usant', 'Spørsmålet om arv og miljø har som regel svaret «bare arv».', array['Sant', 'Usant']::text[], 1, 'Svaret er nesten alltid begge deler.', false, true, 11),
  ('psykologi-2:teorier-og-forklaringer', 'm03', 'sant-usant', 'Psykodynamiske forklaringer er ofte vanskelige å teste.', array['Sant', 'Usant']::text[], 0, 'Ubevisste prosesser er vanskelige å måle.', false, true, 12),
  ('psykologi-2:teorier-og-forklaringer', 'm04', 'sant-usant', 'Holisme gjør det lettere å teste presise hypoteser.', array['Sant', 'Usant']::text[], 1, 'Reduksjonisme gir mer presise tester.', false, true, 13),
  ('psykologi-2:teorier-og-forklaringer', 'm05', 'flervalg', 'Hvilken hjernestruktur er sentral i biologiske forklaringer på angst?', array['Lillehjernen', 'Amygdala', 'Synsbarken', 'Ryggmargen']::text[], 1, 'Viktig for frykt.', false, true, 14),
  ('psykologi-2:teorier-og-forklaringer', 'm06', 'flervalg', 'Hva legger det humanistiske perspektivet vekt på?', array['Egne verdier, aksept og selvaktualisering', 'Gener og hormoner', 'Betinging', 'Ubevisste drifter']::text[], 0, 'Maslow og Rogers.', false, true, 15),
  ('psykologi-2:teorier-og-forklaringer', 'm07', 'flervalg', 'Hvilken metode passer det sosiokulturelle perspektivet?', array['Hjerneskanning', 'Hormonmålinger', 'Tverrkulturelle sammenligninger', 'Dyreforsøk']::text[], 2, 'Også feltstudier.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('psykologi-2:teorier-og-forklaringer', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('psykologi-2:teorier-og-forklaringer', 's01', 'Sammenlign reduksjonisme og holisme som måter å forklare et psykologisk fenomen på. Ta med én styrke og én begrensning ved hver tilnærming.', 'Reduksjonisme kan gi presise forklaringer ved å dele fenomenet opp, men kan overse helheten. Holisme viser hvordan flere forhold virker sammen, men forklaringer kan være vanskeligere å teste.', array['Forklarer at reduksjonisme bryter fenomenet ned i mindre deler, og nevner at det kan gjøre forskningen presis, men overse helheten.', 'Forklarer at holisme ser på helheten og samspillet, og nevner at det kan være vanskeligere å teste.']::text[], 0),
  ('psykologi-2:teorier-og-forklaringer', 's02', 'En person blir skremt i en bestemt situasjon og kjenner senere angst når situasjonen dukker opp igjen. Bruk klassisk betinging til å forklare hvordan angsten kan ha blitt lært.', 'Situasjonen kan først ha vært nøytral, men ble koblet til noe skremmende. Etter koblingen kan situasjonen i seg selv utløse angst.', array['Forklarer at en nøytral situasjon kobles sammen med noe skremmende.', 'Forklarer at situasjonen senere kan utløse angst på grunn av koblingen.']::text[], 1),
  ('psykologi-2:teorier-og-forklaringer', 's03', 'Sammenlign hvordan biologisk og kognitivt perspektiv kan forklare angst. Ta med et konkret forhold hvert perspektiv legger vekt på.', 'Det biologiske perspektivet kan knytte angst til aktivitet i amygdala, stresshormoner eller arv. Det kognitive perspektivet kan forklare angst med tankemønstre, som at faren overvurderes og egen mestring undervurderes.', array['Beskriver en biologisk forklaring på angst, for eksempel knyttet til amygdala, stresshormoner eller arv.', 'Beskriver en kognitiv forklaring med tankemønstre, for eksempel vurdering av fare eller egen mestring.']::text[], 2),
  ('psykologi-2:teorier-og-forklaringer', 's04', 'En forsker vil undersøke hvordan prestasjonspress og sosiale medier i elevenes miljø henger sammen med angst. Hvilket perspektiv passer best, og hvilken metode kan forskeren bruke? Begrunn svaret.', 'Det sosiokulturelle perspektivet passer fordi det undersøker hvordan sosiale forhold og samfunn påvirker angst. Forskeren kan bruke en feltstudie for å undersøke forholdene i elevenes miljø.', array['Knytter prestasjonspress eller sosiale medier til det sosiokulturelle perspektivet.', 'Foreslår feltstudier og knytter metoden til undersøkelse av forhold i elevenes miljø.']::text[], 3),
  ('psykologi-2:teorier-og-forklaringer', 's05', 'En biopsykososial forklaring på angst kombinerer flere forklaringsnivåer. Beskriv ett mulig forhold på biologisk, psykologisk og sosialt nivå.', 'Biologisk kan angst knyttes til stresshormoner, psykologisk til tankemønstre og sosialt til prestasjonspress. Den biopsykososiale modellen setter slike forhold fra ulike nivåer sammen.', array['Gir et relevant biologisk forhold, som gener, hjerne eller hormoner.', 'Gir et relevant psykologisk forhold, som tanker, følelser eller læring, og et sosialt forhold, som relasjoner, kultur eller samfunn.']::text[], 4),
  ('psykologi-2:teorier-og-forklaringer', 's06', 'Psykodynamiske forklaringer legger vekt på ubevisste prosesser. Forklar hva det vil si at en slik forklaring er testbar, og hvorfor det kan være vanskelig å teste den.', 'En forklaring er testbar hvis den i prinsippet kan undersøkes og motbevises. Det kan være vanskelig å teste forklaringer om ubevisste prosesser fordi de ikke er direkte synlige.', array['Forklarer at testbarhet innebærer at en forklaring kan undersøkes og i prinsippet motbevises.', 'Knytter utfordringen ved psykodynamiske forklaringer til at de handler om ubevisste prosesser.']::text[], 5),
  ('psykologi-2:teorier-og-forklaringer', 's07', 'En person kjenner angst fordi hun opplever at hun lever i strid med egne verdier og mangler aksept. Forklar situasjonen med det humanistiske perspektivet, og knytt forklaringen til selvaktualisering.', 'Det humanistiske perspektivet kan forstå angsten som knyttet til at personen ikke lever i tråd med egne verdier eller mangler aksept. Selvaktualisering handler om å utvikle seg i retning av det som er viktig for en selv.', array['Forklarer angsten med konflikt med egne verdier eller mangel på aksept.', 'Knytter selvaktualisering til å utvikle seg eller leve i tråd med det som er viktig for personen.']::text[], 6),
  ('psykologi-2:teorier-og-forklaringer', 's08', 'En forsker vil undersøke om tankemønstre påvirker hvordan personer med angst husker informasjon. Hvilket perspektiv passer best, og hvilken type metode kan forskeren bruke?', 'Det kognitive perspektivet passer fordi det handler om tanker og informasjonsbehandling. Forskeren kan bruke eksperimenter med hukommelse.', array['Knytter undersøkelsen av tankemønstre og hukommelse til det kognitive perspektivet.', 'Foreslår eksperimenter med hukommelse som en metode som passer.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('psykologi-2:sosial-pavirkning-og-grupper', 'psykologi-2', 'sosial-pavirkning-og-grupper', 'Sosial påvirkning og grupper', 'Hvordan sosial påvirkning og samspill i grupper påvirker holdninger, atferd og identitet – konformitet og Asch, lydighet og Milgram, normer og roller, gruppetenkning, sosial identitet og fordommer, holdninger og kognitiv dissonans – og hvordan dette spiller seg ut i sosiale medier.', array[4]::int[], 3, 'utkast', '{}'::text[], false, now())
insert into public.tema_innhold (tema_id, sammendrag, tankekart) values
  ('psykologi-2:sosial-pavirkning-og-grupper', '## Mennesket er sosialt
