insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q01', 'flervalg', 'Hva er støy i kommunikasjonsmodellen?', array['Bare høye lyder', 'Alt som forstyrrer kommunikasjonen', 'Tilbakemeldingen', 'Budskapet']::text[], 1, 'Også stress og ulike forventninger.', true, true, 0),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q02', 'flervalg', 'Hva er de fire trinnene i ikkevoldelig kommunikasjon?', array['Observasjon, følelse, behov, anmodning', 'Kritikk, forsvar, angrep, pause', 'Sender, kanal, mottaker, støy', 'Lytte, snakke, gå, komme']::text[], 0, 'Marshall Rosenberg.', true, true, 1),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q03', 'flervalg', 'Hvilken form for kommunikasjon gir flest signaler?', array['Tekstmelding', 'E-post', 'Ansikt til ansikt', 'Brev']::text[], 2, 'Kroppsspråk, tonefall og blikk.', true, true, 2),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q04', 'flervalg', 'Hva er sosial sammenligning?', array['Å samarbeide', 'Å dele bilder', 'Å hjelpe andre', 'Å vurdere seg selv opp mot andre']::text[], 3, 'Kan gi dårligere selvbilde.', true, true, 3),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q05', 'flervalg', 'Hvilken type sosiale medier-bruk ser ut til å være mest positiv?', array['Aktiv kommunikasjon med venner', 'Passiv scrolling', 'Bruk om natten', 'Bruk uten pauser']::text[], 0, 'Hvordan betyr mer enn hvor mye.', true, true, 4),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q06', 'flervalg', 'Hva er emosjonell støtte?', array['Konkret hjelp', 'Omsorg og trøst', 'Råd og kunnskap', 'Penger']::text[], 1, 'En av tre typer sosial støtte.', true, true, 5),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q07', 'flervalg', 'Hvorfor er relasjoner viktige for livskvalitet?', array['Fordi de gir penger', 'Fordi de erstatter søvn', 'Fordi gode relasjoner er blant de viktigste faktorene for helse og trivsel', 'Fordi de hindrer all sorg']::text[], 2, 'Kommunikasjon er verktøyet.', true, true, 6),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q08', 'flervalg', 'Hva betyr at sosial støtte virker som en buffer?', array['At den gir mer stress', 'At den erstatter behandling', 'At den bare gjelder barn', 'At den demper virkningen av stress']::text[], 3, 'Å vite at noen er der, hjelper.', true, true, 7),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q09', 'flervalg', 'Hva er FOMO?', array['Frykt for å gå glipp av noe', 'En app', 'En type mobbing', 'En kommunikasjonsmodell']::text[], 0, 'Fear of missing out.', true, false, 8),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'q10', 'flervalg', 'Hvorfor kan emojier skape misforståelser?', array['Fordi de er forbudt', 'Fordi de tolkes ulikt', 'Fordi de er for store', 'Fordi de alltid er negative']::text[], 1, 'Erstatter bare delvis kroppsspråk.', true, false, 9),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'm01', 'sant-usant', 'Mottakeren tolker budskapet ut fra egne erfaringer.', array['Sant', 'Usant']::text[], 0, 'Derfor kan samme ord forstås ulikt.', false, true, 10),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'm02', 'sant-usant', 'Forskningen viser entydig at alle sosiale medier gjør alle ungdommer deprimerte.', array['Sant', 'Usant']::text[], 1, 'Sammenhengene er ofte små og varierer mye.', false, true, 11),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'm03', 'sant-usant', 'Sosiale medier kan gi fellesskap for ungdom som føler seg annerledes.', array['Sant', 'Usant']::text[], 0, 'En viktig positiv side.', false, true, 12),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'm04', 'sant-usant', 'Anerkjennelse betyr at man alltid må være enig.', array['Sant', 'Usant']::text[], 1, 'Man kan anerkjenne følelser og være uenig.', false, true, 13),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'm05', 'flervalg', 'Hvilket utsagn er en observasjon uten vurdering?', array['Du er alltid sen', 'Du kom en time for sent', 'Du bryr deg ikke', 'Du er upålitelig']::text[], 1, 'Beskriver bare hva som skjedde.', false, true, 14),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'm06', 'flervalg', 'Hva er informativ støtte?', array['Råd og kunnskap', 'Trøst', 'Konkret hjelp', 'En gave']::text[], 0, 'En av tre typer.', false, true, 15),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 'm07', 'flervalg', 'Hvordan kan mye skjermbruk påvirke helsen indirekte?', array['Bedre søvn', 'Mer fysisk aktivitet', 'Mindre søvn og fysisk aktivitet', 'Ingen virkning']::text[], 2, 'Fortrenger andre aktiviteter.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('psykologi-2:kommunikasjon-og-livskvalitet', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('psykologi-2:kommunikasjon-og-livskvalitet', 's01', 'Hva betyr livskvalitet, og nevn to sider ved livet som inngår i opplevelsen av livskvalitet.', 'Livskvalitet handler om hvordan vi opplever livet. Det kan blant annet dreie seg om glede, mening, trygghet og tilhørighet.', array['Forklarer at livskvalitet handler om opplevelsen av livet.', 'Nevner minst to relevante sider, som glede, mening, trygghet eller tilhørighet.']::text[], 0),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 's02', 'Sara sender en melding til Amir: «Kan du ta med boka mi i morgen?» Amir svarer: «Ja, det kan jeg.» Bruk kommunikasjonsmodellen til å forklare hvem som er sender og mottaker, hva budskapet er, hvilken kanal som brukes, og hva som er tilbakemeldingen.', 'Sara er sender, og Amir er mottaker. Budskapet er spørsmålet om å ta med boka, kanalen er tekstmelding, og svaret fra Amir er tilbakemeldingen.', array['Identifiserer Sara som sender, Amir som mottaker og spørsmålet som budskap.', 'Identifiserer tekstmelding som kanal og Amirs svar som tilbakemelding.']::text[], 1),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 's03', 'To venner prøver å løse en uenighet først på tekstmelding og senere ansikt til ansikt. Forklar hvorfor det kan være lettere å oppklare misforståelser når de snakker ansikt til ansikt.', 'Ansikt til ansikt kan de bruke kroppsspråk, tonefall og blikk, og de kan få rask tilbakemelding. Tekstmeldinger mangler mange slike signaler, som kan gjøre budskapet vanskeligere å tolke.', array['Forklarer at ansikt til ansikt gir flere ikke-verbale signaler, som kroppsspråk, tonefall eller blikk.', 'Knytter rask tilbakemelding eller mangel på signaler i tekst til muligheten for å oppklare misforståelser.']::text[], 2),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 's04', 'En elev er stresset før en prøve. En venn trøster eleven, hjelper med å lage en leseplan og gir råd om hvordan stoffet kan øves på. Hvilken type sosial støtte viser hver handling?', 'Trøsten er emosjonell støtte, og hjelpen med leseplanen er praktisk støtte. Rådene om øving er informativ støtte.', array['Knytter trøst til emosjonell støtte og hjelp med leseplan til praktisk støtte.', 'Knytter rådene om øving til informativ støtte.']::text[], 3),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 's05', 'Mina forteller en venn at hun føler seg utenfor. Vennen er uenig i Minas tolkning av situasjonen. Hva kan vennen gjøre for å kommunisere anerkjennende, og hvordan kan det påvirke Mina?', 'Vennen kan lytte respektfullt og ta Minas følelser på alvor, selv om de er uenige. Når Mina føler seg sett og forstått, kan det styrke selvfølelsen hennes.', array['Beskriver respektfull lytting og at Minas følelser tas på alvor til tross for uenighet.', 'Forklarer at det å bli sett eller forstått kan styrke selvfølelsen.']::text[], 4),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 's06', 'Oskar ser ofte redigerte bilder av andres liv på sosiale medier og begynner å føle at hans eget liv ikke er bra nok. Forklar hvordan sosial sammenligning kan bidra til denne reaksjonen.', 'Oskar vurderer seg selv opp mot andres liv. Når bildene er redigerte, kan han sammenligne seg med et glansbilde og få et dårligere selvbilde.', array['Forklarer at sosial sammenligning innebærer å vurdere seg selv opp mot andre.', 'Knytter redigerte bilder til risiko for dårligere selvbilde.']::text[], 5),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 's07', 'En undersøkelse finner en liten gjennomsnittlig sammenheng mellom bruk av sosiale medier og livskvalitet. Forklar hvorfor dette ikke betyr at sosiale medier påvirker alle mennesker på samme måte.', 'En liten gjennomsnittlig sammenheng sier ikke at virkningen er lik for hver person. Det er store forskjeller mellom personer, og hvordan sosiale medier brukes, har betydning.', array['Forklarer at et gjennomsnitt ikke viser samme virkning for alle.', 'Nevner store forskjeller mellom personer eller at måten sosiale medier brukes på, har betydning.']::text[], 6),
  ('psykologi-2:kommunikasjon-og-livskvalitet', 's08', 'En ungdom som føler seg annerledes der hun bor, finner et fellesskap på sosiale medier, men opplever også hets der. Forklar én mulig positiv og én mulig negativ virkning dette kan ha på livskvaliteten hennes.', 'Fellesskapet kan gi henne kontakt og tilhørighet. Hets kan ramme hardt og dermed påvirke livskvaliteten negativt.', array['Forklarer hvordan kontakt eller fellesskap på sosiale medier kan gi tilhørighet eller støtte.', 'Forklarer at hets kan være skadelig og påvirke livskvaliteten negativt.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('psykologi-2:psykisk-helse-i-endring', 'psykologi-2', 'psykisk-helse-i-endring', 'Synet på psykisk helse gjennom tidene', 'Hvordan synet på psykisk helse og behandlingen av psykiske lidelser har endret seg – fra overnaturlige forklaringer og dårekister til asyler, moralsk behandling, psykoanalyse, lobotomi og psykofarmaka, avinstitusjonalisering og opptrappingsplan – og hvilke endringer som pågår i dag.', array[9]::int[], 8, 'utkast', '{}'::text[], false, now())
