insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('psykologi-2:forebygging-og-behandling', 'q01', 'flervalg', 'Hva er universell forebygging?', array['Tiltak for de som allerede er syke', 'Tiltak rettet mot alle', 'Tiltak bare for risikogrupper', 'Medisinering']::text[], 1, 'For eksempel livsmestring i skolen.', true, true, 0),
  ('psykologi-2:forebygging-og-behandling', 'q02', 'flervalg', 'Hva er BUP?', array['Barne- og ungdomspsykiatrisk poliklinikk', 'En kommunal skole', 'En medisin', 'En terapiform']::text[], 0, 'Del av spesialisthelsetjenesten.', true, true, 1),
  ('psykologi-2:forebygging-og-behandling', 'q03', 'flervalg', 'Hva er eksponering i behandling av angst?', array['Å unngå det man frykter', 'Å ta medisiner', 'Å gradvis møte det man frykter', 'Å snakke om barndommen']::text[], 2, 'En del av kognitiv atferdsterapi.', true, true, 2),
  ('psykologi-2:forebygging-og-behandling', 'q04', 'flervalg', 'Hva er terapeutisk allianse?', array['En avtale om betaling', 'En medisin', 'En diagnose', 'Relasjonen mellom terapeut og klient']::text[], 3, 'Har stor betydning for resultatet.', true, true, 3),
  ('psykologi-2:forebygging-og-behandling', 'q05', 'flervalg', 'Hva er evidensbasert praksis?', array['Å kombinere forskning, klinisk erfaring og pasientens ønsker', 'Å bare følge egen erfaring', 'Å bare bruke medisiner', 'Å gjøre som pasienten sier']::text[], 0, 'Tre kunnskapskilder.', true, true, 4),
  ('psykologi-2:forebygging-og-behandling', 'q06', 'flervalg', 'Hvem kan du vanligvis få henvisning fra til spesialisthelsetjenesten?', array['Læreren', 'Fastlegen', 'Rektor', 'Politiet']::text[], 1, 'Fastlegen henviser.', true, true, 5),
  ('psykologi-2:forebygging-og-behandling', 'q07', 'flervalg', 'Hva er selektiv forebygging?', array['Tiltak for alle', 'Tiltak for de med diagnose', 'Tiltak rettet mot risikogrupper', 'Tiltak bare på sykehus']::text[], 2, 'For eksempel barn av foreldre med rusproblemer.', true, true, 6),
  ('psykologi-2:forebygging-og-behandling', 'q08', 'flervalg', 'Hvilket nummer kan du ringe hele døgnet for å snakke med noen?', array['112', '110', '1881', '116 123']::text[], 3, 'Mental Helses hjelpetelefon.', true, true, 7),
  ('psykologi-2:forebygging-og-behandling', 'q09', 'flervalg', 'Hva er et sosialt behandlingstiltak?', array['Samarbeid med skole og NAV om tilrettelegging', 'SSRI', 'Søvnmedisin', 'Eksponering']::text[], 0, 'Behandling på flere nivåer.', true, false, 8),
  ('psykologi-2:forebygging-og-behandling', 'q10', 'flervalg', 'Hva anbefales ofte først ved lettere psykiske plager?', array['Innleggelse', 'Samtalebehandling', 'Sterke medisiner', 'Ingen hjelp']::text[], 1, 'Medisiner kan ha bivirkninger.', true, false, 9),
  ('psykologi-2:forebygging-og-behandling', 'm01', 'sant-usant', 'Kombinasjonen av medisiner og terapi gir ofte best effekt ved alvorlige lidelser.', array['Sant', 'Usant']::text[], 0, 'Virker på flere nivåer.', false, true, 10),
  ('psykologi-2:forebygging-og-behandling', 'm02', 'sant-usant', 'Helsefremming handler bare om å behandle sykdom.', array['Sant', 'Usant']::text[], 1, 'Den styrker det som gir god helse.', false, true, 11),
  ('psykologi-2:forebygging-og-behandling', 'm03', 'sant-usant', 'Ved akutt fare for liv og helse skal man ringe 113.', array['Sant', 'Usant']::text[], 0, 'Medisinsk nødhjelp.', false, true, 12),
  ('psykologi-2:forebygging-og-behandling', 'm04', 'sant-usant', 'Bare metoden avgjør om terapi virker, ikke relasjonen.', array['Sant', 'Usant']::text[], 1, 'Terapeutisk allianse har stor betydning.', false, true, 13),
  ('psykologi-2:forebygging-og-behandling', 'm05', 'flervalg', 'Hvilken terapiform involverer hele familien?', array['KAT', 'Familieterapi', 'Interpersonlig terapi', 'Eksponering']::text[], 1, 'Særlig ved barn og unge.', false, true, 14),
  ('psykologi-2:forebygging-og-behandling', 'm06', 'flervalg', 'Hva er et eksempel på indikert forebygging?', array['Kurs i å mestre nedstemthet for ungdom med symptomer', 'Livsmestring for alle elever', 'Gratis fritidsaktiviteter', 'Tiltak mot mobbing for alle']::text[], 0, 'Rettet mot tidlige symptomer.', false, true, 15),
  ('psykologi-2:forebygging-og-behandling', 'm07', 'flervalg', 'Hvor kan du få hjelp på skolen?', array['I kantinen', 'Hos vaktmesteren', 'Hos helsesykepleier i skolehelsetjenesten', 'Ingen steder']::text[], 2, 'Første linje.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('psykologi-2:forebygging-og-behandling', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('psykologi-2:forebygging-og-behandling', 's01', 'Forklar forskjellen mellom helsefremming og forebygging av psykiske vansker.', 'Helsefremming styrker forhold som gir god psykisk helse, som mestring, tilhørighet og mening. Forebygging skal hindre at psykiske problemer oppstår eller utvikler seg.', array['Forklarer at helsefremming styrker ressurser eller forhold som fremmer god psykisk helse.', 'Forklarer at forebygging skal hindre at problemer oppstår eller utvikler seg.']::text[], 0),
  ('psykologi-2:forebygging-og-behandling', 's02', 'En kommune tilbyr støtte til barn av foreldre med rusproblemer, og et kurs til ungdom som har tidlige tegn på nedstemthet. Hvilket forebyggingsnivå passer for hvert tilbud, og hvorfor?', 'Støtten til barn av foreldre med rusproblemer er selektiv forebygging fordi den retter seg mot en risikogruppe. Kurset for ungdom med tidlige tegn på nedstemthet er indikert forebygging fordi deltakerne har tidlige symptomer.', array['Knytter tilbudet til barn av foreldre med rusproblemer til selektiv forebygging og risikogruppe.', 'Knytter kurset til indikert forebygging og tidlige symptomer.']::text[], 1),
  ('psykologi-2:forebygging-og-behandling', 's03', 'En kommune vil forebygge psykiske vansker ut fra den biopsykososiale modellen. Foreslå ett tiltak rettet mot biologiske forhold og ett rettet mot sosiale forhold, og forklar kort hva tiltakene retter seg mot.', 'Et biologisk tiltak kan være å fremme søvn eller fysisk aktivitet, som retter seg mot kroppslige forhold. Et sosialt tiltak kan være å skape et tryggere skolemiljø, som retter seg mot forhold mellom mennesker og i omgivelsene.', array['Foreslår et relevant biologisk tiltak, for eksempel knyttet til søvn, fysisk aktivitet, kosthold eller rusdebut.', 'Foreslår et relevant sosialt tiltak, for eksempel knyttet til skolemiljø, fritidsaktiviteter, familie eller fattigdom.']::text[], 2),
  ('psykologi-2:forebygging-og-behandling', 's04', 'Sammenlign kognitiv atferdsterapi og psykodynamisk terapi ved å forklare hva hver terapiform retter oppmerksomheten mot.', 'Kognitiv atferdsterapi arbeider med sammenhengen mellom tanker, følelser og atferd. Psykodynamisk terapi utforsker ubevisste mønstre og erfaringer fra relasjoner.', array['Forklarer at kognitiv atferdsterapi arbeider med sammenhengen mellom tanker, følelser og atferd.', 'Forklarer at psykodynamisk terapi utforsker ubevisste mønstre og/eller relasjonserfaringer.']::text[], 3),
  ('psykologi-2:forebygging-og-behandling', 's05', 'En person har en psykoselidelse, og en annen har bipolar lidelse. Hvilke medikamentgrupper brukes ved de to lidelsene?', 'Antipsykotika brukes ved psykoselidelser. Stemningsstabiliserende medisiner brukes ved bipolar lidelse.', array['Knytter antipsykotika til psykoselidelser.', 'Knytter stemningsstabiliserende medisiner til bipolar lidelse.']::text[], 4),
  ('psykologi-2:forebygging-og-behandling', 's06', 'Forklar forskjellen mellom første linje og andre linje i hjelpeapparatet, og gi ett eksempel på en tjeneste fra hver linje.', 'Første linje er kommunale tjenester, som fastlege eller helsesykepleier. Andre linje er spesialisthelsetjenesten, som BUP, DPS eller sykehus.', array['Forklarer at første linje består av kommunale tjenester og gir et passende eksempel.', 'Forklarer at andre linje er spesialisthelsetjenesten og gir et passende eksempel.']::text[], 5),
  ('psykologi-2:forebygging-og-behandling', 's07', 'En pasient skal begynne i behandling, og behandleren vil legge til rette for brukermedvirkning. Beskriv hva pasienten skal få være med på å bestemme.', 'Pasienten skal få være med på å velge mål for behandlingen og hvilken behandling som skal brukes. Ønskene og verdiene til pasienten skal tas med i vurderingen.', array['Får fram at pasienten deltar i å velge mål for behandlingen.', 'Får fram at pasienten deltar i valg av behandling, med egne ønsker eller verdier tatt med.']::text[], 6),
  ('psykologi-2:forebygging-og-behandling', 's08', 'En person er i akutt fare for liv og helse. Hvilket nummer skal personen eller noen rundt ringe, og hva slags situasjon er nummeret beregnet for?', 'De skal ringe 113. Nummeret brukes ved akutt fare for liv og helse.', array['Oppgir 113.', 'Knytter nummeret til akutt fare for liv og helse.']::text[], 7);
