  ('sosialkunnskap:kilder-og-informasjon', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('sosialkunnskap:kilder-og-informasjon', 's01', 'Hva er forskjellen på en NOU og en stortingsmelding når du undersøker et samfunnsspørsmål?', 'En NOU er en grundig offentlig utredning som ofte kan ligge til grunn for nye lover og reformer. En stortingsmelding viser regjeringens politikk.', array['Forklarer at en NOU er en grundig utredning og ofte grunnlag for lover eller reformer.', 'Forklarer at en stortingsmelding viser regjeringens politikk.']::text[], 0),
  ('sosialkunnskap:kilder-og-informasjon', 's02', 'I en undersøkelse ser man at skolefravær og helseplager blant ungdom øker samtidig. Hvorfor er ikke dette nok til å slå fast at skolefravær forårsaker helseplagene?', 'At to forhold øker samtidig, viser en sammenheng, men ikke nødvendigvis at det ene forårsaker det andre. Det kan være andre forklaringer, og man trenger mer kunnskap for å fastslå årsak.', array['Skiller mellom at to forhold henger sammen og at det ene forårsaker det andre.', 'Viser at det kan finnes andre forklaringer, eller at mer kunnskap trengs for å fastslå årsak.']::text[], 1),
  ('sosialkunnskap:kilder-og-informasjon', 's03', 'To personer deler den samme uriktige påstanden: Den ene tror påstanden er sann, mens den andre vet at den er falsk. Hvem sprer desinformasjon, og hvem sprer feilinformasjon? Begrunn svaret.', 'Personen som vet at påstanden er falsk, sprer desinformasjon fordi informasjonen deles bevisst. Personen som tror påstanden er sann, sprer feilinformasjon fordi det skjer uten vilje til å villede.', array['Knytter desinformasjon til at personen bevisst sprer noe falskt eller villedende.', 'Knytter feilinformasjon til at feilen spres uten vilje til å villede.']::text[], 2),
  ('sosialkunnskap:kilder-og-informasjon', 's04', 'Du finner en rapport om ungdoms levekår som ble laget for en tid tilbake. Rapporten sier lite om hvordan kunnskapen ble samlet inn. Hvilke to forhold bør du undersøke før du bruker rapporten, og hvorfor?', 'Jeg bør undersøke når rapporten ble laget, fordi eldre kunnskap kan være mindre oppdatert. Jeg bør også finne ut hvordan undersøkelsen ble gjennomført og hvem som deltok, for å vurdere hva resultatene kan si noe om.', array['Tar opp når rapporten ble laget og knytter tidspunktet til hvor oppdatert kunnskapen er.', 'Tar opp metode eller hvem som deltok, og forklarer at dette har betydning for hvordan resultatene kan vurderes.']::text[], 3),
  ('sosialkunnskap:kilder-og-informasjon', 's05', 'En interesseorganisasjon publiserer informasjon om saken den arbeider for. Forklar hvordan informasjonen kan være nyttig, og hvorfor du bør sammenligne den med andre kilder.', 'Organisasjonen kan ha god kunnskap om saken den arbeider for. Samtidig har den bestemte interesser, så det er viktig å sammenligne informasjonen med andre kilder før man trekker konklusjoner.', array['Forklarer at interesseorganisasjonen kan ha relevant kunnskap om saken.', 'Knytter organisasjonens interesser til behovet for å kontrollere eller sammenligne informasjonen med andre kilder.']::text[], 4),
  ('sosialkunnskap:kilder-og-informasjon', 's06', 'Du skal undersøke en aktuell sak og finner både en reportasje i et redaktørstyrt medium og et innlegg om saken i sosiale medier. Forklar én viktig forskjell på hvordan disse kildene kvalitetssikres.', 'Redaktørstyrte medier følger Vær Varsom-plakaten, som blant annet krever at kilder kontrolleres, og at den som angripes, får svare. Sosiale medier har ikke de samme redaksjonelle rutinene.', array['Nevner minst én relevant rutine i redaktørstyrte medier, som kildekontroll eller retten til å svare.', 'Forklarer at slike redaksjonelle rutiner ikke finnes på samme måte i sosiale medier.']::text[], 5),
  ('sosialkunnskap:kilder-og-informasjon', 's07', 'En rapport fastslår at en gruppe har fått lavere inntekt. En kommentator sier at utviklingen er urettferdig. Hvilken påstand er en beskrivelse av fakta, og hvilken er en mening? Forklar forskjellen.', 'Påstanden om at gruppen har fått lavere inntekt, beskriver et forhold som kan undersøkes med fakta. At utviklingen er urettferdig, er en vurdering eller mening.', array['Identifiserer påstanden om lavere inntekt som en faktapåstand som kan undersøkes.', 'Identifiserer «urettferdig» som en vurdering eller mening, ikke et rent faktum.']::text[], 6),
  ('sosialkunnskap:kilder-og-informasjon', 's08', 'Du skal analysere inkludering i samfunnet. Beskriv hvordan du kan bruke kilder og fagkunnskap for å komme fram til en begrunnet konklusjon.', 'Jeg vil samle kilder med ulike perspektiver og vurdere kvaliteten på dem. Fakta og statistikk kan beskrive situasjonen, mens teori kan hjelpe med å forklare den; deretter drøfter jeg ulike syn, konkluderer begrunnet og oppgir kildene tydelig.', array['Beskriver bruk av flere perspektiver og vurdering av kildenes kvalitet.', 'Forklarer hvordan fakta eller statistikk kan beskrive situasjonen, og teori kan bidra til å forklare den.', 'Viser til drøfting av ulike syn, en begrunnet konklusjon eller tydelig kildeoppgivelse.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('sosialkunnskap:samfunnsvitenskapelig-metode-og-teori', 'sosialkunnskap', 'samfunnsvitenskapelig-metode-og-teori', 'Samfunnsvitenskapelige metoder og teorier', 'Kvantitative og kvalitative metoder i samfunnsvitenskapen – spørreskjema, intervju, observasjon og dokumentanalyse – og sentrale teorier og perspektiver som funksjonalisme, konfliktperspektivet, symbolsk interaksjonisme, aktør og struktur og Bourdieus kapitalformer, og hvordan du bruker dem i egne undersøkelser.', array[2]::int[], 1, 'utkast', '{}'::text[], false, now())
