insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('sosialkunnskap:sosialisering', 'q01', 'flervalg', 'Hvor skjer primær sosialisering først og fremst?', array['I skolen', 'I familien', 'På jobb', 'I sosiale medier']::text[], 1, 'I de første leveårene.', true, true, 0),
  ('sosialkunnskap:sosialisering', 'q02', 'flervalg', 'Hva er speilingsselvet?', array['At vi ser oss selv gjennom hvordan andre ser oss', 'At vi ser oss i speilet', 'At vi etterligner foreldre', 'At vi er like alle andre']::text[], 0, 'Cooley.', true, true, 1),
  ('sosialkunnskap:sosialisering', 'q03', 'flervalg', 'Hva mener konfliktperspektivet om sosialisering?', array['At den alltid gir likhet', 'At den bare skjer i familien', 'At den kan reprodusere ulikhet', 'At den ikke finnes']::text[], 2, 'For eksempel gjennom kulturell kapital.', true, true, 2),
  ('sosialkunnskap:sosialisering', 'q04', 'flervalg', 'Hva er den generaliserte andre?', array['En nær venn', 'En lærer', 'Foreldre', 'Samfunnets allmenne forventninger']::text[], 3, 'Mead.', true, true, 3),
  ('sosialkunnskap:sosialisering', 'q05', 'flervalg', 'Hva kjennetegner det senmoderne samfunnet ifølge Giddens?', array['At tradisjoner mister makt og identitet må skapes', 'At kirken bestemmer alt', 'At alle har samme yrke som foreldrene', 'At familien er uten betydning']::text[], 0, 'Refleksivitet.', true, true, 4),
  ('sosialkunnskap:sosialisering', 'q06', 'flervalg', 'Hva betyr aktiv sosialisering?', array['At barn er passive mottakere', 'At barn og unge velger, tolker og påvirker selv', 'At bare voksne sosialiseres', 'At sosialisering skjer ved trening']::text[], 1, 'Også foreldre påvirkes.', true, true, 5),
  ('sosialkunnskap:sosialisering', 'q07', 'flervalg', 'Hvilken endring har skjedd i sosialiseringen?', array['Færre sosialiseringsagenter', 'Mer makt til kirken', 'Flere agenter, blant annet digitale medier', 'Mindre tid i institusjoner']::text[], 2, 'Barn tilbringer mer tid i barnehage og skole.', true, true, 6),
  ('sosialkunnskap:sosialisering', 'q08', 'flervalg', 'Hva er en sosialiseringsagent?', array['En hemmelig agent', 'En lov', 'En type skole', 'En person eller institusjon som påvirker sosialiseringen']::text[], 3, 'Familie, skole, venner, medier.', true, true, 7),
  ('sosialkunnskap:sosialisering', 'q09', 'flervalg', 'Hva mener mange om familiens betydning i dag?', array['At den fortsatt er viktigst, men deler innflytelsen med flere', 'At den ikke betyr noe', 'At den har all makt', 'At skolen har overtatt helt']::text[], 0, 'Særlig for verdier og tilknytning.', true, false, 8),
  ('sosialkunnskap:sosialisering', 'q10', 'flervalg', 'Hva er forhandlingsfamilien?', array['En familie som selger varer', 'En familie med mer dialog og mindre autoritær oppdragelse', 'En familie uten regler', 'En storfamilie']::text[], 1, 'Barn får mer innflytelse.', true, false, 9),
  ('sosialkunnskap:sosialisering', 'm01', 'sant-usant', 'Sosialisering varer hele livet.', array['Sant', 'Usant']::text[], 0, 'Vi lærer nye roller hele tiden.', false, true, 10),
  ('sosialkunnskap:sosialisering', 'm02', 'sant-usant', 'I det tradisjonelle samfunnet var normene ofte uklare og svært ulike.', array['Sant', 'Usant']::text[], 1, 'Normene var ofte klare og felles.', false, true, 11),
  ('sosialkunnskap:sosialisering', 'm03', 'sant-usant', 'Påvirkere i sosiale medier kan fungere som sosialiseringsagenter.', array['Sant', 'Usant']::text[], 0, 'De formidler normer og idealer.', false, true, 12),
  ('sosialkunnskap:sosialisering', 'm04', 'sant-usant', 'Etter Bourdieu belønner skolen alle former for kulturell kapital likt.', array['Sant', 'Usant']::text[], 1, 'Den belønner ofte middelklassens kapital.', false, true, 13),
  ('sosialkunnskap:sosialisering', 'm05', 'flervalg', 'Hvem beskrev signifikante og generaliserte andre?', array['Giddens', 'Mead', 'Durkheim', 'Marx']::text[], 1, 'Gjennom lek og spill.', false, true, 14),
  ('sosialkunnskap:sosialisering', 'm06', 'flervalg', 'Hva kan være en utfordring i det senmoderne samfunnet?', array['Usikkerhet og press ved mange valg', 'For få valgmuligheter', 'Ingen utdanning', 'At alle har samme yrke']::text[], 0, 'Frihet gir også ansvar.', false, true, 15),
  ('sosialkunnskap:sosialisering', 'm07', 'flervalg', 'Hvilken endring har skjedd i familieformer?', array['Bare kjernefamilier', 'Færre skilsmisser', 'Flere familieformer som bonus- og regnbuefamilier', 'Ingen endring']::text[], 2, 'Mangfoldet har økt.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('sosialkunnskap:sosialisering', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('sosialkunnskap:sosialisering', 's01', 'Sammenlign primær og sekundær sosialisering. Når skjer de, og gjennom hvilke personer eller arenaer lærer barn og unge?', 'Primær sosialisering skjer i de første leveårene, særlig i familien. Sekundær sosialisering skjer blant annet gjennom barnehage, skole, venner, medier, fritidsaktiviteter og senere arbeidslivet.', array['Skiller mellom tidspunktet og den typiske arenaen for primær og sekundær sosialisering.', 'Nevner relevante arenaer eller personer for begge formene.']::text[], 0),
  ('sosialkunnskap:sosialisering', 's02', 'Skolen lærer elever punktlighet og samarbeid. Forklar hvordan et funksjonalistisk perspektiv kan knytte dette til stabilitet i samfunnet.', 'Fra et funksjonalistisk perspektiv overfører skolen felles normer og verdier til nye generasjoner. Når elever lærer punktlighet og samarbeid, kan det bidra til at samfunnet fungerer stabilt.', array['Knytter sosialisering til overføring av felles normer eller verdier.', 'Forklarer at dette kan bidra til stabilitet i samfunnet.']::text[], 1),
  ('sosialkunnskap:sosialisering', 's03', 'Barn fra ulike klasser kan ha ulik kulturell kapital hjemme, og skolen belønner ofte den kulturelle kapitalen middelklassen har. Forklar hvordan dette kan bidra til at ulikhet reproduseres.', 'Barn som allerede har den kulturelle kapitalen skolen belønner, kan få en fordel. Dermed kan sosialisering og skolens forventninger bidra til å videreføre forskjeller mellom klasser.', array['Forklarer at ulik kulturell kapital hjemme kan gi elever ulike forutsetninger i skolen.', 'Knytter skolens belønning av middelklassens kulturelle kapital til at ulikhet kan videreføres.']::text[], 2),
  ('sosialkunnskap:sosialisering', 's04', 'Mead mente at barn lærer gjennom lek og spill. Forklar hva barn lærer i slike situasjoner, og hvordan det kan utvikle forståelsen deres av andre.', 'Gjennom lek og spill øver barn på å ta andres perspektiv. De lærer å forstå roller og forventninger i samspill med andre.', array['Nevner at barn lærer å ta andres perspektiv.', 'Knytter læringen til samspill, roller eller forventninger.']::text[], 3),
  ('sosialkunnskap:sosialisering', 's05', 'En ungdom møter normer og idealer fra påvirkere på sosiale medier og spiller på nett med jevnaldrende. Forklar hvordan dette er digital sosialisering, og nevn én følge for foreldres eller skolens kontroll.', 'Sosiale medier og spill er sosialiseringsagenter der ungdom møter normer og idealer og påvirkes av jevnaldrende på nett. Foreldre og skole har mindre kontroll over hvilke verdier ungdom møter.', array['Forklarer at medier eller spill formidler normer og idealer eller at jevnaldrende påvirker hverandre på nett.', 'Nevner at foreldres og skolens kontroll over verdiene ungdom møter, er mindre.']::text[], 4),
  ('sosialkunnskap:sosialisering', 's06', 'En ungdom velger selv en fritidsaktivitet og får foreldrene til å endre mening om hva ungdom bør få bestemme. Forklar hvordan situasjonen viser aktiv sosialisering.', 'Ungdommen er aktiv fordi hen selv velger en aktivitet, i stedet for bare å ta imot påvirkning. Ungdommen påvirker også foreldrenes syn, slik at påvirkningen går begge veier.', array['Viser at ungdommen selv velger eller tolker, og ikke bare er mottaker av påvirkning.', 'Forklarer at ungdommen påvirker foreldrene eller andre voksne.']::text[], 5),
  ('sosialkunnskap:sosialisering', 's07', 'Et barn møter ulike normer hjemme og utenfor hjemmet i et flerkulturelt samfunn. Forklar hvilken side ved sosialiseringen situasjonen illustrerer.', 'Situasjonen illustrerer at barn i flerkulturelle samfunn kan møte ulike normer hjemme og ute. Barnet sosialiseres dermed i møte med forskjellige forventninger.', array['Knytter situasjonen til at samfunnet er flerkulturelt eller at barn møter ulike normer.', 'Forklarer at normene kan variere mellom hjemmet og arenaer utenfor hjemmet.']::text[], 6),
  ('sosialkunnskap:sosialisering', 's08', 'Et barn går i barnehage og SFO, og bor i en familie med steforeldre. Hvilke to endringer i sosialiseringen illustrerer situasjonen, og hvordan påvirker de hvem barnet møter i hverdagen?', 'Barnehage og SFO illustrerer at barn tilbringer mer tid i institusjoner. Steforeldrene illustrerer at det finnes flere familieformer, slik at både institusjoner og flere familiemedlemmer kan være del av barnets sosialisering.', array['Knytter barnehage og SFO til at barn tilbringer mer tid i institusjoner.', 'Knytter steforeldre til flere familieformer, som bonusfamilier.', 'Forklarer at både institusjoner og familie kan være arenaer eller påvirkningskilder i barnets hverdag.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('sosialkunnskap:kjonn-og-identitet', 'sosialkunnskap', 'kjonn-og-identitet', 'Kjønn og identitet', 'Ulike perspektiver på kjønn – biologisk, sosialt og juridisk kjønn, kjønnsroller i endring, kjønnsidentitet og kjønnsuttrykk, seksuell orientering, essensialisme og sosialkonstruktivisme, interseksjonalitet – og refleksjon over holdninger til egen og andres identitet.', array[6]::int[], 5, 'utkast', '{}'::text[], false, now())
