insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('sosialkunnskap:kjonn-og-identitet', 's01', 'Forklar forskjellen mellom sosialt kjønn og juridisk kjønn. Gi ett eksempel på hva hvert av dem handler om.', 'Sosialt kjønn handler om forventninger og roller samfunnet knytter til kjønn, for eksempel forventninger til hvem som skal ta ansvar for hjem og barn. Juridisk kjønn er kjønnet som er registrert i folkeregisteret.', array['Forklarer at sosialt kjønn handler om samfunnets forventninger eller roller.', 'Forklarer at juridisk kjønn handler om registreringen i folkeregisteret.']::text[], 0),
  ('sosialkunnskap:kjonn-og-identitet', 's02', 'Alex ble tildelt jente ved fødselen, opplever seg som mann, bruker klær som ofte forbindes med kvinner og blir forelsket i menn. Forklar hva dette sier om Alex sin kjønnsidentitet, kjønnsuttrykk og seksuelle orientering, og hvorfor én av disse opplysningene ikke avgjør de andre.', 'Alex er trans fordi kjønnsidentiteten ikke er i samsvar med kjønnet han ble tildelt ved fødselen. Klærne er en del av kjønnsuttrykket, og siden han er mann og blir forelsket i menn, er han homofil. Kjønnsidentitet, kjønnsuttrykk og seksuell orientering er ulike dimensjoner.', array['Knytter det å oppleve seg som mann når man ble tildelt jente ved fødselen, til trans.', 'Skiller mellom klær som kjønnsuttrykk og forelskelse i menn som seksuell orientering.', 'Får fram at disse dimensjonene ikke avgjør hverandre.']::text[], 1),
  ('sosialkunnskap:kjonn-og-identitet', 's03', 'I det tradisjonelle samfunnet hadde menn oftere rollen som forsørgere, mens kvinner hadde ansvar for hjem og barn. Forklar hvordan fedrekvoten kan bidra til å endre denne arbeidsdelingen.', 'Fedrekvoten gir far en del av foreldrepermisjonen som er forbeholdt ham. Når far får omsorgsansvar, kan ansvaret for barn i større grad deles, i stedet for å følge den tradisjonelle arbeidsdelingen.', array['Forklarer at fedrekvoten er en del av foreldrepermisjonen som er forbeholdt far.', 'Knytter fedrekvoten til at far får omsorgsansvar og at arbeidsdelingen kan bli mindre tradisjonell.']::text[], 2),
  ('sosialkunnskap:kjonn-og-identitet', 's04', 'Sammenlign essensialisme og sosialkonstruktivisme som forklaringer på forskjeller mellom kjønnene.', 'Essensialisme forklarer i hovedsak kjønnsforskjeller med medfødte biologiske forskjeller. Sosialkonstruktivisme legger vekt på at mye av det vi forbinder med kjønn, er skapt av kultur og forventninger og derfor kan endres.', array['Knytter essensialisme til medfødte biologiske forskjeller.', 'Knytter sosialkonstruktivisme til kultur eller forventninger, og får fram at slike forhold kan endres.']::text[], 3),
  ('sosialkunnskap:kjonn-og-identitet', 's05', 'Nora er kvinne og tilhører en etnisk minoritet. Forklar hvordan et interseksjonelt perspektiv kan brukes til å undersøke erfaringene hennes uten å anta at alle kvinner har de samme erfaringene.', 'Et interseksjonelt perspektiv ser på hvordan kjønn krysser andre kategorier, som etnisitet. Det kan derfor undersøke om Nora møter andre utfordringer enn en kvinne som tilhører majoriteten, uten å anta at erfaringene hennes er gitt på forhånd.', array['Forklarer at kjønn må ses i sammenheng med andre kategorier, her etnisitet.', 'Får fram at dette kan gi andre erfaringer eller utfordringer enn for kvinner i majoriteten.']::text[], 4),
  ('sosialkunnskap:kjonn-og-identitet', 's06', 'En ungdom får ikke lov av familien til å være sammen med en person hen er forelsket i, eller til å bestemme hvordan hen skal leve. Forklar hvorfor situasjonen kan være et eksempel på negativ sosial kontroll.', 'Dette kan være negativ sosial kontroll fordi familien begrenser hvem ungdommen kan være sammen med og hvordan hen kan leve. Slik kontroll handler om at familie eller miljø begrenser en persons liv.', array['Peker på at familien begrenser ungdommens valg eller mulighet til å leve slik hen ønsker.', 'Knytter begrensningen til hvem ungdommen kan være sammen med eller hvordan hen kan leve.']::text[], 5),
  ('sosialkunnskap:kjonn-og-identitet', 's07', 'En person beskriver seg selv både som omsorgsfull og som medlem av en bestemt vennegjeng. Forklar hvilken del av beskrivelsen som handler om personlig identitet, og hvilken som handler om sosial identitet. Ta også med hvordan identitet i det senmoderne samfunnet i større grad kan utvikles.', 'Å være omsorgsfull handler om en personlig egenskap og dermed om personlig identitet. Å tilhøre en vennegjeng handler om sosial identitet, fordi det viser til en gruppe personen tilhører. I det senmoderne samfunnet skaper og utforsker mennesker i større grad identiteten sin.', array['Skiller mellom personlige egenskaper eller erfaringer og gruppene man tilhører.', 'Får fram at identitet i det senmoderne samfunnet i større grad skapes eller utforskes.']::text[], 6),
  ('sosialkunnskap:kjonn-og-identitet', 's08', 'Det er forbudt å diskriminere på grunn av kjønn, samtidig som arbeidsmarkedet fortsatt kan være kjønnsdelt. Forklar hvordan dette kan være mulig, og bruk ett annet eksempel på en kjønnsforskjell som fortsatt finnes.', 'Et forbud mot diskriminering fastsetter hva som ikke er lov, men betyr ikke i seg selv at alle forskjeller i samfunnet forsvinner. Arbeidsmarkedet kan fortsatt være kjønnsdelt, og det finnes blant annet lønnsforskjeller, flere kvinner i deltidsarbeid og flere menn i toppledelse.', array['Skiller mellom et forbud mot diskriminering og at ulikheter fortsatt kan finnes i samfunnet.', 'Nevner et annet eksempel på en kjønnsforskjell, som lønnsforskjeller, flere kvinner i deltid eller flere menn i toppledelse.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('sosialkunnskap:velferdsforskjeller-og-sosiale-problemer', 'sosialkunnskap', 'velferdsforskjeller-og-sosiale-problemer', 'Velferdsforskjeller og sosiale problemer', 'Hvordan forskjeller i inntekt, utdanning, bolig og helse henger sammen med sosiale problemer som dårlig helse, rus, kriminalitet og frafall – den sosiale gradienten, barn i lavinntektsfamilier, opphopning av levekårsutfordringer – og hvilke konsekvenser det får for individ og samfunn.', array[7]::int[], 6, 'utkast', '{}'::text[], false, now())
