insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('sosialkunnskap:behov-i-barne-og-ungdomsarene', 's01', 'Hva betyr anerkjennelse som et behov for barn og unge? Gi et eksempel på hvordan en lærer kan vise anerkjennelse.', 'Anerkjennelse betyr å bli sett, verdsatt og tatt på alvor. En lærer kan for eksempel lytte til det eleven sier og vise at elevens synspunkter betyr noe.', array['Forklarer at anerkjennelse handler om å bli sett, verdsatt eller tatt på alvor.', 'Gir et eksempel som viser dette i praksis.']::text[], 0),
  ('sosialkunnskap:behov-i-barne-og-ungdomsarene', 's02', 'Sammenlign tilknytning og tilhørighet som behov. Hva slags relasjoner eller fellesskap handler de om?', 'Tilknytning handler om nære og stabile relasjoner til omsorgspersoner. Tilhørighet handler om å ha venner og være del av et fellesskap.', array['Knytter tilknytning til nære, stabile relasjoner til omsorgspersoner.', 'Skiller tilhørighet fra tilknytning ved å knytte det til venner eller fellesskap.']::text[], 1),
  ('sosialkunnskap:behov-i-barne-og-ungdomsarene', 's03', 'Sammenlign Maslows behovspyramide med selvbestemmelsesteorien. Hvordan ordner Maslow behovene, og hvilke behov legger selvbestemmelsesteorien vekt på?', 'Maslow ordner behovene i nivåer, fra fysiologiske behov nederst til selvrealisering øverst. Selvbestemmelsesteorien legger i stedet vekt på autonomi, kompetanse og tilhørighet som tre grunnleggende psykologiske behov.', array['Forklarer at Maslow ordner behovene i en pyramide fra grunnleggende til høyere behov.', 'Nevner autonomi, kompetanse og tilhørighet som behov i selvbestemmelsesteorien.']::text[], 2),
  ('sosialkunnskap:behov-i-barne-og-ungdomsarene', 's04', 'En ungdom får velge tema for et skoleprosjekt, arbeide med en oppgave som passer ferdighetene sine og samarbeide med venner. Forklar hvordan to sider ved situasjonen kan dekke psykologiske behov og påvirke ungdommens motivasjon.', 'Å få velge tema kan støtte autonomi, mens en oppgave som passer ferdighetene, kan gi opplevelse av kompetanse. Samarbeid med venner kan styrke tilhørigheten, og når slike behov dekkes, kan motivasjonen øke.', array['Knytter minst to sider ved situasjonen til riktige behov: autonomi, kompetanse eller tilhørighet.', 'Forklarer at dekning av slike behov kan øke motivasjonen.']::text[], 3),
  ('sosialkunnskap:behov-i-barne-og-ungdomsarene', 's05', 'Belastninger i barndommen kan henge sammen med problemer senere i livet. Forklar hva denne sammenhengen kan være, og hvorfor den ikke betyr at alle barn får problemer.', 'Belastninger som omsorgssvikt, vold, fattigdom eller mobbing henger sammen med økt risiko for problemer med helse, skole eller relasjoner senere. Det betyr ikke at alle får slike problemer, fordi beskyttende faktorer kan bidra til at barn klarer seg godt.', array['Forklarer at belastninger i barndommen henger sammen med økt risiko for problemer senere.', 'Får fram at økt risiko ikke betyr at utfallet er sikkert, for eksempel ved å vise til beskyttende faktorer.']::text[], 4),
  ('sosialkunnskap:behov-i-barne-og-ungdomsarene', 's06', 'Ungdom ønsker ofte mer selvstendighet, men trenger fortsatt trygge voksne. Forklar hvordan dette kan ses i sammenheng med hjernens utvikling i ungdomstiden.', 'Hjernen er fortsatt i utvikling i ungdomstiden, særlig områdene som har med impulskontroll og planlegging å gjøre. Trygge voksne kan derfor fortsatt være viktige samtidig som ungdom får øve på selvstendighet.', array['Nevner at hjernen, særlig områder for impulskontroll eller planlegging, fortsatt er i utvikling.', 'Knytter dette til at ungdom fortsatt trenger støtte fra trygge voksne, selv om behovet for selvstendighet øker.']::text[], 5),
  ('sosialkunnskap:behov-i-barne-og-ungdomsarene', 's07', 'En familie har lite penger, og barnet får ikke delta på en fritidsaktivitet. Nevn en velferdsordning som kan bidra, og forklar hvordan den kan støtte barnets behov for tilhørighet.', 'Fritidskort eller tilskudd til fritidsaktiviteter kan bidra til at barnet får delta. Det kan gi barnet mulighet til å være sammen med andre og oppleve tilhørighet.', array['Nevner fritidskort eller tilskudd til fritidsaktiviteter.', 'Forklarer hvordan deltakelse kan bidra til fellesskap eller tilhørighet.']::text[], 6),
  ('sosialkunnskap:behov-i-barne-og-ungdomsarene', 's08', 'Velferdsordninger kan bidra til å dekke barns behov, men kan ikke erstatte omsorg og relasjoner. Forklar forskjellen med et eksempel på en velferdsordning og et behov som må ivaretas gjennom nære relasjoner.', 'Barnetrygd kan bidra økonomisk til familiens utgifter, mens en nær og stabil relasjon til en omsorgsperson kan dekke behovet for tilknytning. Ordningen kan støtte familien, men kan ikke i seg selv gi barnet omsorg og nærhet.', array['Gir et riktig eksempel på en velferdsordning og hva den kan bidra med.', 'Skiller dette fra omsorg eller en nær relasjon som dekker behov for eksempelvis tilknytning og trygghet.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('sosialkunnskap:vold-og-trakassering', 'sosialkunnskap', 'vold-og-trakassering', 'Vold og trakassering', 'Ulike former for vold og trakassering – fysisk, psykisk, seksuell, materiell og digital vold, vold i nære relasjoner, negativ sosial kontroll og æresrelatert vold, seksuell trakassering, mobbing og netthets – og konsekvensene for individ og samfunn, med hjelpeinstanser og forebygging.', array[12]::int[], 11, 'utkast', '{}'::text[], false, now())
