insert into public.quiz_sporsmal (tema_id, nokkel, type, tekst, alternativer, riktig, forklaring, i_quiz, i_miniprove, sortering) values
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q01', 'flervalg', 'Hva er en visjon?', array['Et budsjett', 'Et langsiktig, inspirerende bilde av hva virksomheten vil bli', 'En reklamekampanje', 'Et delmål']::text[], 1, 'Gir retning og motivasjon.', true, true, 0),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q02', 'flervalg', 'Hvilke tre spørsmål svarer forretningsideen på?', array['Hva, hvem og hvordan', 'Når, hvor og hvorfor', 'Pris, plass og produkt', 'Styrker, svakheter og trusler']::text[], 0, 'Tilbud, målgruppe og ressurser.', true, true, 1),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q03', 'flervalg', 'Hva står M-en i SMART for?', array['Moderne', 'Motiverende', 'Målbar', 'Maksimal']::text[], 2, 'Man må kunne måle om målet er nådd.', true, true, 2),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q04', 'flervalg', 'Hva er et delmål?', array['En visjon', 'En verdi', 'En forretningsidé', 'Et mål for en avdeling eller periode som bidrar til hovedmålet']::text[], 3, 'Målhierarkiet.', true, true, 3),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q05', 'flervalg', 'Hvilke fire perspektiver har balansert målstyring?', array['Økonomi, kunder, interne prosesser og læring', 'Pris, produkt, plass og påvirkning', 'Styrker, svakheter, muligheter og trusler', 'Politikk, økonomi, sosialt og teknologi']::text[], 0, 'Ikke bare tall på kort sikt.', true, true, 4),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q06', 'flervalg', 'Hva kan skje hvis verdiene ikke etterleves?', array['Omdømmet styrkes', 'Omdømmet kan skades', 'Ingenting', 'Salget dobles']::text[], 1, 'Verdier må være troverdige.', true, true, 5),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q07', 'flervalg', 'Hva er et konkurransefortrinn?', array['Et lavt budsjett', 'Mange ansatte', 'Noe virksomheten gjør bedre enn konkurrentene', 'En visjon']::text[], 2, 'Bør være vanskelig å kopiere.', true, true, 6),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q08', 'flervalg', 'Hva er et eksempel på målkonflikt?', array['Høy trivsel og god kundeservice', 'Mange kunder og høy kjennskap', 'Lave kostnader og effektivitet', 'Kortsiktig lønnsomhet mot bærekraft']::text[], 3, 'Mål kan trekke i ulike retninger.', true, true, 7),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q09', 'flervalg', 'Hva beskriver virksomhetsideen?', array['Hvorfor virksomheten finnes og hvilket behov den dekker', 'Hvor mye den tjener', 'Hvem som er leder', 'Hvilke farger logoen har']::text[], 0, 'Også kalt misjon.', true, false, 8),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'q10', 'flervalg', 'Hvilket mål er SMART?', array['Bli best i verden', 'Øke markedsandelen fra 8 til 10 % innen utgangen av neste år', 'Få flere kunder', 'Bli mer kjent']::text[], 1, 'Spesifikt, målbart og tidsbestemt.', true, false, 9),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'm01', 'sant-usant', 'En visjon er ofte ikke direkte målbar.', array['Sant', 'Usant']::text[], 0, 'Den gir retning, mens målene kan måles.', false, true, 10),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'm02', 'sant-usant', 'Delmål trenger ikke henge sammen med hovedmålet.', array['Sant', 'Usant']::text[], 1, 'Delmålene skal bidra til hovedmålet.', false, true, 11),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'm03', 'sant-usant', 'En virksomhet kan måtte revidere visjonen når den endrer retning.', array['Sant', 'Usant']::text[], 0, 'For eksempel mot bærekraft.', false, true, 12),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'm04', 'sant-usant', 'Et mål som ingen ansatte aksepterer, er et godt SMART-mål.', array['Sant', 'Usant']::text[], 1, 'Målet må være akseptert.', false, true, 13),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'm05', 'flervalg', 'Hvilket mål er et markedsmål?', array['Redusere utslipp', 'Øke kjennskapen til merket', 'Øke trivselen', 'Redusere sykefraværet']::text[], 1, 'Markedsandel, kunder eller kjennskap.', false, true, 14),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'm06', 'flervalg', 'Hva kjennetegner en god forretningsidé?', array['Realistisk, tydelig målgruppe og konkurransefortrinn', 'Vag og generell', 'Uten målgruppe', 'Lett å kopiere']::text[], 0, 'Vanskelig å kopiere.', false, true, 15),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 'm07', 'flervalg', 'Hva viser handlingsplanen?', array['Visjonen', 'Verdiene', 'De konkrete tiltakene', 'Konkurrentene']::text[], 2, 'Nederst i målhierarkiet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 's01', 'Forklar forskjellen mellom en visjon og en forretningsidé. Hva beskriver hver av dem?', 'Visjonen er et langsiktig og inspirerende bilde av hva virksomheten vil bli eller oppnå, og gir retning. Forretningsideen beskriver mer konkret hvordan virksomheten skal tjene penger.', array['Skiller mellom visjonens langsiktige retning og forretningsideens konkrete beskrivelse.', 'Får fram at forretningsideen handler om hvordan virksomheten skal tjene penger.']::text[], 0),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 's02', 'En virksomhet sier at ærlighet er en verdi. En ansatt oppdager at et produkt ikke dekker kundens behov. Beskriv en handling som viser at den ansatte etterlever verdien, og forklar hvorfor det er viktig.', 'Den ansatte bør være ærlig om at produktet ikke dekker kundens behov, og ikke anbefale det som en passende løsning. Når ansatte handler i tråd med verdiene, blir de mer troverdige.', array['Foreslår en handling som viser ærlighet overfor kunden.', 'Forklarer at verdier må etterleves for at virksomheten skal være troverdig.']::text[], 1),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 's03', 'En virksomhet setter målet «Vi skal øke kundetilfredsheten snart». Forklar hvilke opplysninger som mangler for at målet skal bli lettere å følge opp som et SMART-mål.', 'Målet bør presisere hva som skal forbedres og hvordan kundetilfredsheten skal måles. Det bør også angi en tidsfrist, være realistisk og akseptert av dem som skal nå det.', array['Får fram at målet må konkretiseres og gjøres målbart.', 'Får fram at målet må ha en tidsfrist.', 'Nevner at målet også må være realistisk og akseptert.']::text[], 2),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 's04', 'En virksomhet har visjonen «å bli kjent for bærekraftige klær» og hovedmålet «å øke salget av bærekraftige klær på lang sikt». Markedsavdelingen får i oppgave å øke kundenes kjennskap til klærne, og handlingsplanen inneholder tiltak for å informere om dem. Forklar hvordan disse målene og tiltakene henger sammen.', 'Tiltakene i handlingsplanen skal bidra til delmålet om økt kjennskap. Delmålet støtter hovedmålet om økt salg, og hovedmålet bidrar til visjonen om å bli kjent for bærekraftige klær.', array['Knytter tiltakene til delmålet om økt kjennskap.', 'Forklarer hvordan delmålet støtter hovedmålet, og hvordan hovedmålet støtter visjonen.']::text[], 3),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 's05', 'En sykkelreparatør tilbyr reparasjon på kundens arbeidsplass, mens konkurrentene krever at kunden leverer sykkelen hos dem. Forklar hvilken kundefordel tilbudet gir, og hvorfor det kan være et konkurransefortrinn.', 'Kunden slipper å levere sykkelen hos reparatøren, noe som gjør tjenesten mer praktisk. Tilbudet kan være et konkurransefortrinn fordi virksomheten tilbyr noe den gjør bedre enn konkurrentene.', array['Beskriver nytten for kunden, for eksempel at reparasjonen blir mer praktisk.', 'Knytter konkurransefortrinnet til at virksomheten skiller seg positivt fra konkurrentene.']::text[], 4),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 's06', 'En leder vurderer virksomheten bare ut fra kortsiktig omsetning. Forklar hvorfor det kan gi et for smalt bilde av hvordan virksomheten gjør det, og bruk to andre perspektiver fra balansert målstyring i forklaringen.', 'Omsetning viser ikke alene hvordan virksomheten gjør det for kundene eller hvor gode de interne prosessene er. Balansert målstyring kan også følge med på for eksempel kunder og læring og utvikling.', array['Forklarer at økonomiske tall alene ikke gir et helhetlig bilde.', 'Bruker to andre perspektiver fra balansert målstyring og knytter dem til hva virksomheten kan følge med på.']::text[], 5),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 's07', 'En virksomhet setter tre mål: øke omsetningen, få flere kunder og redusere utslippene. Plasser hvert mål i riktig kategori: økonomisk mål, markedsmål eller sosialt/miljømessig mål.', 'Å øke omsetningen er et økonomisk mål. Å få flere kunder er et markedsmål, og å redusere utslippene er et miljømessig mål.', array['Plasserer økt omsetning som økonomisk mål.', 'Plasserer flere kunder som markedsmål.', 'Plasserer reduserte utslipp som miljømessig mål.']::text[], 6),
  ('markedsforing-og-ledelse-2:visjon-forretningside-og-mal', 's08', 'En virksomhet endrer retning og vil nå arbeide mer med bærekraft. Forklar hvorfor virksomheten kan måtte revidere visjonen eller forretningsideen, og hva den bør undersøke når den vurderer endringene.', 'Visjonen eller forretningsideen kan måtte endres hvis de ikke lenger passer med virksomhetens retning mot bærekraft. Virksomheten bør vurdere om de er tydelige og troverdige, og om de henger sammen med strategien og ressursene.', array['Knytter mulig revisjon til at retningen mot bærekraft kan gjøre eksisterende visjon eller forretningsidé mindre relevant.', 'Nevner at endringene bør vurderes opp mot tydelighet eller troverdighet og sammenheng med strategi eller ressurser.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('markedsforing-og-ledelse-2:malgruppevalg', 'markedsforing-og-ledelse-2', 'malgruppevalg', 'Segmentering og målgruppevalg', 'Faktorer som påvirker valg av målgruppe – segmenteringskriterier, krav til gode segmenter, markedsdekningsstrategier som udifferensiert, differensiert, konsentrert og individuell markedsføring – og hvordan ressurser, konkurranse, produktets livsfase, data og etikk påvirker valget.', array[3]::int[], 2, 'utkast', '{}'::text[], false, now())
