insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-2:malgruppevalg', 's01', 'En virksomhet deler først markedet inn i grupper med like behov, velger deretter hvilke grupper den vil satse på, og bestemmer til slutt hvordan tilbudet skal oppfattes. Forklar hva de tre stegene i STP-prosessen heter, og hva virksomheten gjør i hvert steg.', 'Stegene er segmentering, målgruppevalg (targeting) og posisjonering. Virksomheten grupperer kunder med like behov, velger hvilke segmenter den vil satse på, og bestemmer hvordan den vil oppfattes av målgruppen.', array['Knytter segmentering til å dele markedet i grupper med like behov.', 'Skiller mellom å velge segmenter i målgruppevalget og å bestemme ønsket oppfatning i posisjoneringen.']::text[], 0),
  ('markedsforing-og-ledelse-2:malgruppevalg', 's02', 'Et reiseselskap deler kundene inn etter hvilken landsdel de bor i, og etter alder og livsfase. Forklar hvilken type segmentering hvert av disse kjennetegnene viser, og hva som skiller typene.', 'Landsdel er et geografisk kjennetegn, mens alder og livsfase er demografiske kjennetegn. Geografisk segmentering deler etter hvor kundene bor, og demografisk segmentering deler etter personkjennetegn.', array['Klassifiserer bosted eller landsdel som geografisk segmentering.', 'Klassifiserer alder og livsfase som demografisk segmentering og forklarer forskjellen mellom kategoriene.']::text[], 1),
  ('markedsforing-og-ledelse-2:malgruppevalg', 's03', 'Sammenlign udifferensiert og differensiert markedsføring når det gjelder hvor mange segmenter virksomheten retter seg mot, og hvor tilpasset tilbudet er. Ta også med én forskjell i kostnader.', 'Udifferensiert markedsføring gir samme tilbud til hele markedet, mens differensiert markedsføring gir ulike tilbud til flere segmenter. Differensiering gir bedre tilpasning, men koster mer.', array['Forklarer at udifferensiert markedsføring retter samme tilbud mot hele markedet, mens differensiert markedsføring retter ulike tilbud mot flere segmenter.', 'Får fram at differensiert markedsføring gir bedre tilpasning, men høyere kostnader.']::text[], 2),
  ('markedsforing-og-ledelse-2:malgruppevalg', 's04', 'En virksomhet selger salt som standardvare og ønsker å nå hele markedet med samme tilbud. Hvilken markedsdekningsstrategi passer best? Begrunn valget med en fordel og en begrensning ved strategien.', 'Udifferensiert markedsføring passer best fordi virksomheten vil tilby en standardvare til hele markedet. Strategien kan gi lave kostnader, men tilbudet blir lite tilpasset ulike kundegrupper.', array['Velger udifferensiert markedsføring og knytter valget til standardvaren og hele markedet.', 'Nevner både en fordel, som lave kostnader, og en begrensning, som lite tilpasning.']::text[], 3),
  ('markedsforing-og-ledelse-2:malgruppevalg', 's05', 'Et segment kan måles og anslås å være stort nok til å lønne seg. Det skiller seg fra andre segmenter og er stabilt, men virksomheten har ingen måte å nå det med kommunikasjon eller distribusjon på. Hvilket krav til et godt segment er ikke oppfylt, og hvorfor er det et problem?', 'Kravet om tilgjengelighet er ikke oppfylt. Selv om segmentet kan være lønnsomt, får virksomheten ikke nådd kundene med kommunikasjon eller distribusjon.', array['Identifiserer at segmentet ikke er tilgjengelig.', 'Forklarer at virksomheten må kunne nå segmentet med kommunikasjon og distribusjon for å kunne satse på det.']::text[], 4),
  ('markedsforing-og-ledelse-2:malgruppevalg', 's06', 'En leverandør selger produkter til andre bedrifter og deler markedet etter kundenes bransje, størrelse og innkjøpsatferd. Forklar hvorfor dette er relevante kriterier for segmentering i bedriftsmarkedet.', 'Bransje, bedriftsstørrelse og innkjøpsatferd er kriterier som kan brukes til å dele bedriftsmarkedet i grupper. De kan skille mellom bedrifter med ulike kjennetegn og kjøpsmåter.', array['Knytter bransje, bedriftsstørrelse og innkjøpsatferd til segmentering i bedriftsmarkedet.', 'Forklarer at kriteriene brukes til å skille mellom ulike grupper av bedriftskunder.']::text[], 5),
  ('markedsforing-og-ledelse-2:malgruppevalg', 's07', 'En møbelleverandør selger skoleinnredning. Skoleledere står for kjøpene, mens lærere påvirker hvilke løsninger skolen velger. Hvem er primærmålgruppen og hvem er sekundærmålgruppen i denne situasjonen? Begrunn svaret.', 'Skolelederne er primærmålgruppen fordi de står for kjøpene og er de viktigste kundene. Lærerne er sekundærmålgruppen fordi de påvirker valget.', array['Identifiserer skolelederne som primærmålgruppe fordi de står for kjøpene.', 'Identifiserer lærerne som sekundærmålgruppe fordi de påvirker kjøpet.']::text[], 6),
  ('markedsforing-og-ledelse-2:malgruppevalg', 's08', 'En nettbutikk deler kundene inn etter hva de søker etter, klikker på og kjøper. Forklar hvorfor dette er datadrevet segmentering, og hvordan det kan gjøre tilbudene mer relevante for kundene.', 'Dette er datadrevet segmentering fordi virksomheten bruker digitale data om søk, klikk og kjøp til å gruppere kundene. Slik kan den tilpasse tilbudene mer presist til kundenes interesser og behov.', array['Forklarer at segmenteringen bygger på digitale data om søk, klikk eller kjøp.', 'Knytter bruken av data til mer presis tilpasning eller mer relevante tilbud.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('markedsforing-og-ledelse-2:situasjons-og-bransjeanalyse', 'markedsforing-og-ledelse-2', 'situasjons-og-bransjeanalyse', 'Situasjonsanalyse, bransjeanalyse og markedsstrategiske valg', 'Hvordan situasjonsanalyse og bransjeanalyse brukes som grunnlag for markedsstrategiske beslutninger – fra SWOT til strategier, Porters fem krefter, markedsformer, Porters generiske strategier, Ansoffs vekstmatrise og BCG-matrisen – og hvordan du vurderer strategiske valg.', array[4]::int[], 3, 'utkast', '{}'::text[], false, now())
