insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-2:merkevarestrategier-og-posisjonering', 's01', 'Forklar hva en merkevare er, og nevn én måte en sterk merkevare kan påvirke kundenes valg på.', 'En merkevare er summen av forestillingene, følelsene og erfaringene kundene har med produktet, ikke bare navnet og logoen. En sterk merkevare kan gjøre at kunder velger produktet igjen, betaler mer eller anbefaler det.', array['Forklarer at merkevaren består av kundenes forestillinger, følelser og erfaringer.', 'Nevner en relevant virkning, som gjenkjøp, høyere betalingsvilje eller anbefaling.']::text[], 0),
  ('markedsforing-og-ledelse-2:merkevarestrategier-og-posisjonering', 's02', 'En produsent selger et produkt under sitt eget merke, mens en dagligvarekjede selger et lignende produkt under et merke kjeden eier. Sammenlign disse merkeformene, og nevn én strategisk fordel kjeden kan få med sitt eget merke.', 'Produsentmerket eies av produsenten, mens kjedens egen merkevare (EMV) eies av kjeden. EMV kan gi kjeden høyere marginer og større makt overfor leverandørene.', array['Skiller riktig mellom hvem som eier produsentmerket og EMV.', 'Nevner en relevant fordel for kjeden: høyere marginer eller mer makt overfor leverandørene.']::text[], 1),
  ('markedsforing-og-ledelse-2:merkevarestrategier-og-posisjonering', 's03', 'Et yoghurtmerke lanserer en ny smak under samme merkenavn. Senere bruker virksomheten merkenavnet på et produkt i en helt annen kategori. Forklar hvilken type merkeutvidelse hvert av de to tilfellene er.', 'Den nye smaken er en linjeutvidelse fordi den er en ny variant i samme kategori. Bruk av merkenavnet på et produkt i en annen kategori er en merkeutvidelse.', array['Klassifiserer den nye smaken som linjeutvidelse og knytter det til samme kategori.', 'Klassifiserer bruk av merket i en annen kategori som merkeutvidelse.']::text[], 2),
  ('markedsforing-og-ledelse-2:merkevarestrategier-og-posisjonering', 's04', 'To ulike merkevarer utvikler og selger et produkt sammen. Hva kalles denne strategien, og hva kjennetegner den?', 'Strategien kalles co-branding eller samarbeidsmerker. Den kjennetegnes av at to merker samarbeider om ett produkt.', array['Identifiserer strategien som co-branding eller samarbeidsmerker.', 'Forklarer at to merker samarbeider om et produkt.']::text[], 3),
  ('markedsforing-og-ledelse-2:merkevarestrategier-og-posisjonering', 's05', 'På et posisjoneringskart viser den ene aksen pris og den andre helse. Et område øverst til høyre er tomt for merker. Hva kan virksomheten utlede av dette, og hvorfor bør den undersøke området før den velger det?', 'Kartet viser at ingen av merkene er plassert i området med høy pris og høy helse. Området kan være en ledig posisjon, men det kan også være tomt fordi kundene ikke ønsker den.', array['Tolker det tomme området ut fra de to dimensjonene i kartet.', 'Forklarer at en tom posisjon ikke nødvendigvis er attraktiv, fordi kundene kanskje ikke ønsker den.']::text[], 4),
  ('markedsforing-og-ledelse-2:merkevarestrategier-og-posisjonering', 's06', 'Et nytt merke i en produktkategori må ha en egenskap kundene forventer av alle produkter i kategorien. I tillegg har merket en egenskap som konkurrentene ikke tilbyr, og som gir kundene en grunn til å velge det. Forklar forskjellen på disse egenskapene ved hjelp av begrepene likhetspunkter og forskjellspunkter.', 'Egenskapen som merket må ha for å være med i kategorien, er et likhetspunkt. Egenskapen som skiller merket fra konkurrentene og gir kundene en grunn til å velge det, er et forskjellspunkt.', array['Knytter forventningen som kreves for å være med i kategorien, til likhetspunkter.', 'Knytter den unike egenskapen som gir en grunn til å velge merket, til forskjellspunkter.']::text[], 5),
  ('markedsforing-og-ledelse-2:merkevarestrategier-og-posisjonering', 's07', 'En virksomhet vil at målgruppen skal oppfatte merket som bærekraftig, men produktet støtter ikke dette løftet. Vurder om posisjoneringen er troverdig, og forklar hva virksomheten bør gjøre for at løftet skal henge sammen med merket.', 'Posisjoneringen er ikke troverdig når produktet ikke kan innfri løftet om bærekraft. Virksomheten må sørge for at produktet støtter løftet, og kommunisere på en måte som samsvarer med det.', array['Vurderer posisjoneringen som lite troverdig når produktet ikke kan innfri løftet.', 'Forklarer at produktet og kommunikasjonen må samsvare med posisjonen.']::text[], 6),
  ('markedsforing-og-ledelse-2:merkevarestrategier-og-posisjonering', 's08', 'Et merke har fått et image virksomheten ikke ønsker. Beskriv to ulike grep virksomheten kan bruke for å reposisjonere merket.', 'Virksomheten kan endre produktet og kommunisere konsekvent om den nye posisjonen. Reposisjonering handler om å endre hvordan målgruppen oppfatter merket.', array['Forklarer at målet er å endre målgruppens oppfatning av merket.', 'Nevner relevante grep, som endringer i produktet og konsistent kommunikasjon.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('markedsforing-og-ledelse-2:distribusjonsstrategier-og-makt', 'markedsforing-og-ledelse-2', 'distribusjonsstrategier-og-makt', 'Distribusjonsstrategier, makt og avhengighet', 'Hvordan virksomheter utvikler distribusjonsstrategier – direkte og indirekte kanaler, intensiv, selektiv og eksklusiv distribusjon, omnikanal og netthandel – og hvordan makt og avhengighet påvirker samarbeidet i en verdikjede, med dagligvarebransjen, vertikal integrasjon og push- og pull-strategier som eksempler.', array[6]::int[], 5, 'utkast', '{}'::text[], false, now())
