insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-2:kommunikasjonsstrategier-og-mediemiks', 's01', 'En virksomhet skal lage en kommunikasjonsstrategi. Hvilke fire hovedspørsmål må strategien besvare, og hvordan skal den støtte markedsstrategien og posisjoneringen?', 'Strategien må beskrive hva virksomheten vil oppnå, hvem den vil nå, hva den skal si, og hvor den skal kommunisere. Den skal støtte markedsstrategien og posisjoneringen.', array['Får fram målet, målgruppen, budskapet og kanalene som strategien skal avklare.', 'Forklarer at strategien skal støtte markedsstrategien og posisjoneringen.']::text[], 0),
  ('markedsforing-og-ledelse-2:kommunikasjonsstrategier-og-mediemiks', 's02', 'I en kampanje bruker virksomheten enten fakta og argumenter om et produkt eller humor for å skape glede. Forklar hvilken type appell hvert alternativ bruker, og hva som skiller dem.', 'Fakta og argumenter er en rasjonell appell, mens humor som spiller på glede er en emosjonell appell. Den rasjonelle appellen bygger på informasjon, mens den emosjonelle spiller på følelser.', array['Knytter fakta og argumenter til rasjonell appell.', 'Knytter humor og glede til emosjonell appell og får fram at den spiller på følelser.']::text[], 1),
  ('markedsforing-og-ledelse-2:kommunikasjonsstrategier-og-mediemiks', 's03', 'En virksomhet ønsker først at målgruppen skal bli kjent med et nytt tilbud. Hvilken type kommunikasjonsmål er dette, og hva ønsker virksomheten å oppnå?', 'Dette er et kognitivt mål. Virksomheten ønsker å skape kjennskap til tilbudet, eventuelt også kunnskap om det.', array['Identifiserer målet som kognitivt.', 'Forklarer at målet er å skape kjennskap eller kunnskap om tilbudet.']::text[], 2),
  ('markedsforing-og-ledelse-2:kommunikasjonsstrategier-og-mediemiks', 's04', 'En kampanje bruker en betalt annonse i sosiale medier, et nyhetsbrev fra virksomheten, en omtale i nyhetene og innhold som brukere deler og kommenterer i sosiale medier. Plasser hvert av disse i riktig kategori i PESO-modellen.', 'Annonsen er Paid, nyhetsbrevet er Owned, nyhetsomtalen er Earned, og brukernes deling og kommentarer er Shared.', array['Plasserer annonsen som Paid og nyhetsbrevet som Owned.', 'Plasserer nyhetsomtalen som Earned og brukernes deling og kommentarer som Shared.']::text[], 3),
  ('markedsforing-og-ledelse-2:kommunikasjonsstrategier-og-mediemiks', 's05', 'En virksomhet har et viktig budskap, men vil at målgruppen både skal legge merke til det og huske det. Forklar hvordan en sterk kreativ idé kan hjelpe.', 'En sterk kreativ idé kan gjøre budskapet mer iøynefallende og lettere å huske. Den bidrar dermed til at målgruppen legger merke til og husker det viktigste virksomheten vil formidle.', array['Forklarer at den kreative ideen kan gjøre budskapet mer synlig eller få det til å fange oppmerksomhet.', 'Knytter ideen til at målgruppen lettere husker budskapet.']::text[], 4),
  ('markedsforing-og-ledelse-2:kommunikasjonsstrategier-og-mediemiks', 's06', 'En virksomhet skal velge kanaler for en kampanje. Forklar hvorfor den bør vurdere både målgruppens mediebruk og budskapet når den velger kanaler.', 'Kanalene bør være steder målgruppen faktisk bruker, slik at kampanjen kan nå fram til den. De bør også passe til budskapet som virksomheten skal formidle.', array['Forklarer at kanalvalget må passe med hvordan målgruppen bruker medier.', 'Forklarer at kanalene må egne seg til budskapet.']::text[], 5),
  ('markedsforing-og-ledelse-2:kommunikasjonsstrategier-og-mediemiks', 's07', 'I en kampanje blir alternativ A vist til mange i målgruppen én gang, mens alternativ B blir vist flere ganger til en mindre del av målgruppen. Hvilket alternativ har høyest dekning, og hvilket har høyest frekvens? Begrunn svaret.', 'Alternativ A har høyest dekning fordi det når flere personer minst én gang. Alternativ B har høyest frekvens fordi personene i den mindre gruppen nås flere ganger.', array['Identifiserer alternativ A som høyest dekning og knytter det til hvor mange som nås.', 'Identifiserer alternativ B som høyest frekvens og knytter det til hvor mange ganger personene nås.']::text[], 6),
  ('markedsforing-og-ledelse-2:kommunikasjonsstrategier-og-mediemiks', 's08', 'En virksomhet lager en kampanje som retter seg mot barn og sårbare grupper, men gjør det uklart at budskapet er reklame. Hvilke etiske hensyn bør virksomheten ta?', 'Virksomheten bør gjøre det tydelig hva som er reklame og følge markedsføringsloven. Den må også ta særlig hensyn til barn og sårbare grupper og unngå å utnytte dem.', array['Får fram at reklame må være tydelig og at markedsføringsloven skal følges.', 'Får fram at virksomheten må ta hensyn til barn og sårbare grupper.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 'markedsforing-og-ledelse-2', 'lederens-rolle-og-internmarkedsforing', 'Lederens rolle i markedsstrategi og internmarkedsføring', 'Hvilken rolle og funksjon lederen har i utviklingen og gjennomføringen av markedsstrategien – ledernivåer, lederstiler, situasjonsbestemt og transformasjonsledelse, forankring og endringsledelse – og hvordan internmarkedsføring gjør de ansatte til ambassadører gjennom kommunikasjon, opplæring, motivasjon og kultur.', array[9]::int[], 8, 'utkast', '{}'::text[], false, now())
