insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 's01', 'Hvordan bidrar planlegging, organisering, ledelse og kontroll til at en leder kan nå virksomhetens mål gjennom andre mennesker?', 'Planlegging viser hva som skal gjøres, og organisering fordeler oppgaver og ressurser. Lederen motiverer og kommuniserer med medarbeiderne, og kontroll gjør det mulig å følge med på resultatene og justere arbeidet.', array['Forklarer hvordan minst tre av lederfunksjonene bidrar til arbeidet.', 'Knytter funksjonene til å nå mål gjennom medarbeiderne.']::text[], 0),
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 's02', 'Sammenlign mellomledere og førstelinjeledere: Hva har de ansvar for på hvert sitt nivå?', 'Mellomledere omsetter strategien til planer for avdelingene. Førstelinjeledere følger opp det daglige arbeidet.', array['Plasserer mellomledernes ansvar på taktisk nivå og knytter det til avdelingsplaner.', 'Plasserer førstelinjeledernes ansvar på operativt nivå og knytter det til daglig arbeid.']::text[], 1),
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 's03', 'Sammenlign autoritær og demokratisk lederstil. Ta med én mulig fordel eller ulempe ved hver stil.', 'En autoritær leder bestemmer alene, noe som kan være effektivt i en krise, men kan gi medarbeiderne lite motivasjon. En demokratisk leder involverer medarbeiderne i beslutninger, noe som kan gi eierskap, men også tar tid.', array['Forklarer forskjellen i hvem som tar beslutningene.', 'Nevner en relevant fordel eller ulempe ved hver stil.']::text[], 2),
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 's04', 'En nyansatt trenger støtte for å utføre oppgavene sine, mens en erfaren medarbeider kan arbeide selvstendig. Hvordan kan lederen tilpasse oppfølgingen av de to?', 'Lederen kan gi den nyansatte tydelige instrukser og følge arbeidet tettere. Den erfarne medarbeideren kan få større frihet og ansvar gjennom delegering.', array['Foreslår mer instruksjon eller tettere oppfølging for den nyansatte.', 'Foreslår delegering eller større frihet for den erfarne medarbeideren.']::text[], 3),
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 's05', 'En virksomhet lover kundene personlig rådgivning. Beskriv hvordan de tre delene av tjenestetrekanten kan bidra til at kunden faktisk får dette.', 'Ekstern markedsføring gir kundene løftet om personlig rådgivning. Intern markedsføring gjør de ansatte i stand til å levere den, og i møtet med kunden holder de ansatte løftet gjennom interaktiv markedsføring.', array['Knytter ekstern markedsføring til løftet som gis til kundene.', 'Forklarer hvordan intern markedsføring forbereder de ansatte, og interaktiv markedsføring skjer i kundemøtet.']::text[], 4),
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 's06', 'Hvorfor bør ansatte få informasjon om en kampanje før kundene ser den?', 'Da forstår de ansatte hva virksomheten lover kundene og kan svare på spørsmål. De kan også bidra til å levere det kampanjen lover.', array['Forklarer at ansatte trenger å kjenne til kampanjen eller løftet før kundene møter det.', 'Knytter informasjonen til at ansatte kan svare kundene eller levere løftet.']::text[], 5),
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 's07', 'En virksomhet innfører en ny strategi, men noen ansatte motsetter seg endringen. Hva bør lederen gjøre for å håndtere situasjonen?', 'Lederen bør forklare hvorfor endringen er nødvendig og involvere de ansatte. Det kan bidra til forståelse og støtte, samtidig som lederen får håndtert motstanden.', array['Forklarer at lederen bør gjøre grunnen til endringen tydelig.', 'Nevner involvering av ansatte som en måte å håndtere motstand på.']::text[], 6),
  ('markedsforing-og-ledelse-2:lederens-rolle-og-internmarkedsforing', 's08', 'En ansatt i en tjenesteytende virksomhet møter kunder direkte. Gi et eksempel på hvordan den ansatte kan påvirke kundeopplevelsen, og forklar hvorfor ansatte i slike virksomheter kalles deltidsmarkedsførere.', 'En ansatt som lytter til kundens behov og gir god service, kan bidra til en god kundeopplevelse. Ansatte kalles deltidsmarkedsførere fordi de møter kundene direkte og påvirker hvordan virksomhetens tilbud oppleves.', array['Gir et relevant eksempel på hvordan en ansatt påvirker kundens opplevelse.', 'Forklarer sammenhengen mellom direkte kundekontakt og rollen som deltidsmarkedsfører.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('markedsforing-og-ledelse-2:helhetlig-markedsstrategi-og-etikk', 'markedsforing-og-ledelse-2', 'helhetlig-markedsstrategi-og-etikk', 'Helhetlige markedsstrategier og etisk bruk av konkurransemidler', 'Hvordan virksomheter utvikler og begrunner helhetlige markedsstrategier gjennom markedsplanen – fra analyse og mål til STP, markedsmiks, budsjett og kontroll – og hvordan de drøfter etisk bruk av konkurransemidlene, med markedsføringsloven, etiske teorier og dilemmaer som kroppspress, grønnvasking og manipulerende design.', array[10]::int[], 9, 'utkast', '{}'::text[], false, now())
