insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-2:markedsmiks-og-effektmaling', 's01', 'Hva gjør en markedsmiks helhetlig? Forklar hvilke hensyn virksomheten må ta når den setter sammen konkurransemidlene.', 'En helhetlig markedsmiks er tilpasset målgruppen og behovene deres, passer med virksomhetens posisjonering og produktets livsfase, og er realistisk ut fra ressursene.', array['Forklarer at miksen må passe målgruppen og posisjoneringen.', 'Får fram at livsfase og ressurser også må tas hensyn til.']::text[], 0),
  ('markedsforing-og-ledelse-2:markedsmiks-og-effektmaling', 's02', 'Et produkt er i introduksjonsfasen. Hvilket mål bør markedsføringen særlig støtte, og hvordan er distribusjonen ofte lagt opp i denne fasen?', 'Markedsføringen bør særlig bygge kjennskap til produktet. Distribusjonen er ofte begrenset i introduksjonsfasen.', array['Nevner kjennskap som et sentralt mål.', 'Beskriver distribusjonen som ofte begrenset.']::text[], 1),
  ('markedsforing-og-ledelse-2:markedsmiks-og-effektmaling', 's03', 'Sammenlign markedsføringsprioriteringene i vekstfasen og nedgangsfasen.', 'I vekstfasen utvides gjerne distribusjonen og målgruppen, samtidig som virksomheten bygger preferanse. I nedgangsfasen kan virksomheten redusere kostnader, fornye produktet eller avvikle det.', array['Knytter vekstfasen til utvidet distribusjon eller målgruppe og bygging av preferanse.', 'Knytter nedgangsfasen til kostnadsreduksjon, fornyelse eller avvikling.']::text[], 2),
  ('markedsforing-og-ledelse-2:markedsmiks-og-effektmaling', 's04', 'En virksomhet vil forbedre kundenes holdning til merket. Hvilke typer målinger passer til dette målet, og hvorfor?', 'Holdningsundersøkelser og måling av preferanse passer til målet. De undersøker kundenes holdninger til merket og hvilke alternativer de foretrekker.', array['Nevner holdningsundersøkelser eller preferanse som relevant måling.', 'Forklarer at målingen handler om kundenes holdning eller hva de foretrekker.']::text[], 3),
  ('markedsforing-og-ledelse-2:markedsmiks-og-effektmaling', 's05', 'Forklar forskjellen på klikkrate (CTR) og kostnad per anskaffelse (CPA).', 'CTR viser andelen som klikker på en annonse. CPA viser kostnaden per anskaffelse.', array['Forklarer at CTR handler om andelen som klikker.', 'Forklarer at CPA handler om kostnaden per anskaffelse.']::text[], 4),
  ('markedsforing-og-ledelse-2:markedsmiks-og-effektmaling', 's06', 'En virksomhet vil undersøke om en kampanje har økt kjennskapen til merket. Beskriv hvordan den kan bruke før- og ettermåling til dette.', 'Virksomheten måler kjennskapen før kampanjen og måler den på nytt etterpå. Ved å sammenligne målingene kan den se om kjennskapen har endret seg.', array['Beskriver at kjennskapen måles både før og etter kampanjen.', 'Forklarer at resultatene sammenlignes for å se om kjennskapen har endret seg.']::text[], 5),
  ('markedsforing-og-ledelse-2:markedsmiks-og-effektmaling', 's07', 'En kunde ser en annonse i én kanal, møter senere virksomheten i en annen kanal og kjøper deretter et produkt. Forklar hvorfor det kan være vanskelig å måle hvilken kanal som bidro til kjøpet.', 'Kunden har møtt flere kanaler før kjøpet, så det kan være vanskelig å vite hvilken kanal som skal få æren for salget. Dette kalles attribusjon.', array['Forklarer at flere kanaler kan ha bidratt før kjøpet.', 'Knytter usikkerheten om hvilken kanal som får æren, til attribusjon.']::text[], 6),
  ('markedsforing-og-ledelse-2:markedsmiks-og-effektmaling', 's08', 'Sammenlign ROI og ROAS: Hva viser hvert nøkkeltall om markedsføringen?', 'ROI viser avkastningen sammenlignet med kostnaden. ROAS viser hvor mye inntekter virksomheten får per krone brukt på annonser.', array['Forklarer at ROI sammenligner avkastning med kostnad.', 'Forklarer at ROAS viser inntekter per krone brukt på annonser.']::text[], 7);
insert into public.temaer (id, fag_id, slug, navn, intro, kompetansemaal, sortering, status, merknader, publisert, oppdatert) values
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'markedsforing-og-ledelse-2', 'samfunnsansvar-og-omdomme', 'Samfunnsansvar og omdømme', 'Hvordan virksomheters samfunnsansvar kan drøftes ut fra et etisk, lovmessig og forretningsmessig perspektiv – Carrolls pyramide, interessenter, åpenhetsloven og aktsomhetsvurderinger, delt verdiskaping – og hvordan samfunnsansvar påvirker omdømmet, med omdømmebygging og krisehåndtering.', array[12]::int[], 11, 'utkast', '{}'::text[], false, now())
