  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q01', 'flervalg', 'Hva er de fire nivåene i Carrolls pyramide?', array['Pris, produkt, plass og påvirkning', 'Økonomisk, juridisk, etisk og filantropisk', 'Styrker, svakheter, muligheter og trusler', 'Planlegge, organisere, lede og kontrollere']::text[], 1, 'Fra lønnsomhet til frivillige bidrag.', true, true, 0),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q02', 'flervalg', 'Hva krever åpenhetsloven?', array['Aktsomhetsvurderinger av menneskerettigheter og arbeidsforhold i leverandørkjeden', 'At alle priser er offentlige', 'At bedrifter betaler mer skatt', 'At alle ansatte får bonus']::text[], 0, 'For større virksomheter.', true, true, 1),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q03', 'flervalg', 'Hva er delt verdiskaping?', array['Å dele overskuddet likt', 'Å gi bort produkter', 'Å skape økonomisk verdi ved å løse samfunnsproblemer', 'Å samarbeide med konkurrenter']::text[], 2, 'Porter og Kramer.', true, true, 2),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q04', 'flervalg', 'Hva er omdømme?', array['Virksomhetens logo', 'Hvordan virksomheten ser på seg selv', 'Hvordan virksomheten ønsker å bli sett', 'Summen av interessentenes oppfatninger over tid']::text[], 3, 'Bygges av handlinger.', true, true, 3),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q05', 'flervalg', 'Hva er et forretningsmessig argument for samfunnsansvar?', array['Bedre omdømme og lettere rekruttering', 'Høyere kostnader', 'Mindre kontroll', 'Færre kunder']::text[], 0, 'Også lavere risiko.', true, true, 4),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q06', 'flervalg', 'Hva er første steg i god krisehåndtering?', array['Å tie', 'Å reagere raskt', 'Å skylde på andre', 'Å slette kontoer']::text[], 1, 'Deretter ærlighet og ansvar.', true, true, 5),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q07', 'flervalg', 'Hvem er interessenter?', array['Bare eierne', 'Bare kundene', 'Grupper som påvirkes av eller kan påvirke virksomheten', 'Bare konkurrentene']::text[], 2, 'Ansatte, kunder, lokalsamfunn og flere.', true, true, 6),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q08', 'flervalg', 'Hva kan et gap mellom profil og faktisk atferd føre til?', array['Bedre omdømme', 'Høyere lønn', 'Flere ansatte', 'Omdømmetap']::text[], 3, 'Troverdigheten svekkes.', true, true, 7),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q09', 'flervalg', 'Hva er filantropisk ansvar?', array['Frivillige bidrag til samfunnet', 'Å følge loven', 'Å være lønnsom', 'Å betale skatt']::text[], 0, 'Toppen av pyramiden.', true, false, 8),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'q10', 'flervalg', 'Hva er en kritikk av samfunnsansvar?', array['At det er ulovlig', 'At det noen ganger bare er markedsføring', 'At det alltid er for dyrt', 'At kunder ikke bryr seg']::text[], 1, 'Tiltakene må være ekte.', true, false, 9),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'm01', 'sant-usant', 'Omdømme bygges av det virksomheten gjør, ikke bare det den sier.', array['Sant', 'Usant']::text[], 0, 'Handlinger teller mest.', false, true, 10),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'm02', 'sant-usant', 'Samfunnsansvar handler bare om å følge loven.', array['Sant', 'Usant']::text[], 1, 'Det handler også om etisk og frivillig ansvar.', false, true, 11),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'm03', 'sant-usant', 'Forbrukere kan be om informasjon etter åpenhetsloven.', array['Sant', 'Usant']::text[], 0, 'Om hvordan virksomheten håndterer risiko.', false, true, 12),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'm04', 'sant-usant', 'Et godt omdømme har ingen verdi i en krise.', array['Sant', 'Usant']::text[], 1, 'Det gir tillit og handlingsrom.', false, true, 13),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'm05', 'flervalg', 'Hva er et eksempel på en omdømmekrise?', array['En ny logo', 'Barnearbeid hos en leverandør', 'En sommerkampanje', 'En ny butikk']::text[], 1, 'Spres raskt i sosiale medier.', false, true, 14),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'm06', 'flervalg', 'Hva skiller ekte samfunnsansvar fra pynt?', array['At tiltakene er knyttet til kjernevirksomheten og følges opp', 'At det er mye reklame for det', 'At det er billig', 'At ingen vet om det']::text[], 0, 'Og rapporteres.', false, true, 15),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 'm07', 'flervalg', 'Hva er profil?', array['Summen av oppfatninger', 'Hvordan virksomheten ser seg selv', 'Hvordan virksomheten ønsker å bli sett', 'Regnskapet']::text[], 2, 'Identitet er selvbildet.', false, true, 16);
insert into public.miniprover (tema_id, minutter) values
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 15)
insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 's01', 'Forklar hva samfunnsansvar (CSR) innebærer, og hvordan det går utover det virksomheten er pålagt ved lov.', 'Samfunnsansvar handler om å ta hensyn til mennesker, samfunn og miljø i virksomhetens handlinger. Det omfatter også ansvar som går lenger enn det loven krever.', array['Får fram hensynet til mennesker, samfunn og miljø.', 'Får fram at ansvaret går utover lovkrav.']::text[], 0),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 's02', 'Sammenlign identitet og profil i en virksomhet. Hva beskriver hvert av begrepene?', 'Identitet er hvordan virksomheten ser på seg selv. Profil er hvordan virksomheten ønsker å bli sett av andre.', array['Beskriver identitet som virksomhetens syn på seg selv.', 'Beskriver profil som hvordan virksomheten ønsker å bli oppfattet.']::text[], 1),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 's03', 'En beslutning i en virksomhet påvirker både ansatte, kunder og lokalsamfunnet. Forklar hvorfor virksomheten bør ta hensyn til og balansere interessene deres.', 'Disse gruppene påvirkes av virksomheten og er derfor interessenter. De kan ha ulike interesser, så virksomheten bør ta hensyn til dem og forsøke å balansere dem.', array['Forklarer at gruppene er interessenter fordi de påvirkes av virksomheten.', 'Får fram at ulike interesser må tas hensyn til og balanseres.']::text[], 2),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 's04', 'En virksomhet følger alle lover, men vurderer et tiltak som kan skade mennesker eller miljø. Bruk det etiske og det lovmessige perspektivet til å forklare hva virksomheten bør ta hensyn til.', 'Det lovmessige perspektivet krever at virksomheten følger lovens minstekrav. Det etiske perspektivet innebærer også en plikt til å unngå skade på mennesker og miljø, selv når loven ikke krever det.', array['Får fram at loven setter minstekrav som virksomheten må følge.', 'Får fram at det etiske ansvaret kan gå lenger og innebærer å unngå skade.']::text[], 3),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 's05', 'En virksomhet undersøker risiko for brudd på menneskerettigheter og dårlige arbeidsforhold hos leverandørene sine. Forklar hva en slik aktsomhetsvurdering går ut på.', 'En aktsomhetsvurdering går ut på å kartlegge risiko for brudd på menneskerettigheter og anstendige arbeidsforhold i leverandørkjeden. Den hjelper virksomheten med å undersøke mulige problemer hos leverandørene.', array['Forklarer at vurderingen kartlegger risiko.', 'Nevner menneskerettigheter og arbeidsforhold i leverandørkjeden.']::text[], 4),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 's06', 'En virksomhet legger et samfunnsansvarstiltak inn i kjernevirksomheten og rapporterer hvordan det følges opp. Forklar hvorfor dette er relevant når man vurderer om tiltaket er reelt eller bare pynt.', 'At tiltaket er knyttet til kjernevirksomheten, tyder på at det handler om hvordan virksomheten faktisk drives, ikke bare om å skape et godt inntrykk. Rapportering av oppfølging gjør det mulig å se om virksomheten følger opp tiltaket over tid.', array['Forklarer hvorfor tilknytning til kjernevirksomheten taler for at tiltaket er reelt.', 'Får fram at rapportering og oppfølging viser om tiltaket blir gjennomført over tid.']::text[], 5),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 's07', 'En virksomhet har allerede reagert raskt på en krise. Beskriv to viktige ting den bør gjøre videre for å håndtere krisen godt.', 'Virksomheten bør være ærlig og åpen, ta ansvar og beklage. Den bør også fortelle hva den gjør for å rette opp situasjonen og følge opp over tid.', array['Nevner ærlighet og åpenhet og/eller at virksomheten tar ansvar og beklager.', 'Får fram at virksomheten må rette opp situasjonen og følge opp videre.']::text[], 6),
  ('markedsforing-og-ledelse-2:samfunnsansvar-og-omdomme', 's08', 'Forklar hva handlingsrom betyr for en virksomhet, og hvordan et godt omdømme kan gi virksomheten større handlingsrom i en vanskelig situasjon.', 'Handlingsrom er friheten virksomheten har til å handle i vanskelige situasjoner. Et godt omdømme kan gi større handlingsrom fordi interessentene har tillit til virksomheten.', array['Forklarer handlingsrom som frihet eller mulighet til å handle i en vanskelig situasjon.', 'Knytter større handlingsrom til tillit som følger av et godt omdømme.']::text[], 7);
