insert into public.skriveoppgaver (tema_id, nokkel, tekst, fasit, kriterier, sortering) values
  ('markedsforing-og-ledelse-2:barekraftige-valg', 's01', 'En virksomhet dekker kundenes behov i dag ved å bruke ressurser på en måte som svekker kommende generasjoners mulighet til å dekke sine behov. Forklar hvorfor dette ikke er bærekraftig utvikling.', 'Bærekraftig utvikling skal dekke dagens behov uten å ødelegge mulighetene for kommende generasjoner. Virksomhetens ressursbruk svekker disse mulighetene.', array['Forklarer at bærekraftig utvikling tar hensyn til både dagens behov og kommende generasjoner.', 'Knytter virksomhetens ressursbruk til at framtidige muligheter svekkes.']::text[], 0),
  ('markedsforing-og-ledelse-2:barekraftige-valg', 's02', 'En virksomhet har særlig stor påvirkning på arbeidsforholdene til menneskene som produserer varene den selger. Hvilket av FNs bærekraftsmål som er nevnt her, passer best for virksomheten å prioritere, og hvorfor?', 'Anstendig arbeid passer best fordi målet handler om arbeidsforhold. Virksomheten bør velge mål som henger sammen med områdene den har størst påvirkning på.', array['Velger anstendig arbeid som relevant bærekraftsmål.', 'Begrunner valget med virksomhetens påvirkning på arbeidsforhold.']::text[], 1),
  ('markedsforing-og-ledelse-2:barekraftige-valg', 's03', 'Forklar forskjellen på ombruk og materialgjenvinning av et brukt produkt.', 'Ved ombruk tas det brukte produktet i bruk igjen. Ved materialgjenvinning gjenvinnes materialene i produktet.', array['Forklarer at ombruk betyr at det brukte produktet brukes igjen.', 'Skiller dette fra materialgjenvinning, der materialene gjenvinnes.']::text[], 2),
  ('markedsforing-og-ledelse-2:barekraftige-valg', 's04', 'En livsløpsvurdering av et produkt viser at transport står for større miljøbelastning enn emballasjen. Virksomheten hadde planlagt å bare redusere emballasjen. Forklar hvordan vurderingen bør påvirke hva virksomheten prioriterer.', 'Virksomheten bør vurdere tiltak som reduserer belastningen fra transport, siden vurderingen viser at dette bidrar mest. Den bør se på hele produktets livsløp og ikke bare emballasjen.', array['Knytter prioriteringen til at transport står for den største belastningen i situasjonen.', 'Viser at tiltak bør vurderes ut fra produktets samlede livsløp.']::text[], 3),
  ('markedsforing-og-ledelse-2:barekraftige-valg', 's05', 'Sammenlign hva Svanemerket og Fairtrade særlig forteller om et produkt.', 'Svanemerket er et nordisk miljømerke. Fairtrade handler om rettferdig handel og bedre vilkår for produsenter.', array['Knytter Svanemerket til miljø.', 'Knytter Fairtrade til rettferdig handel eller bedre vilkår for produsenter.']::text[], 4),
  ('markedsforing-og-ledelse-2:barekraftige-valg', 's06', 'En virksomhet vil sette en pris som dekker produktets reelle kostnader, også miljø- og samfunnskostnader. Forklar hvorfor dette kan gjøre prisen høyere, og hvordan det henger sammen med bærekraftige valg.', 'Når prisen skal dekke miljø- og samfunnskostnader i tillegg til andre kostnader, kan den bli høyere. Da gjenspeiler prisen kostnadene bedre, selv om bærekraftige produkter kan være dyrere for kundene.', array['Forklarer at miljø- og samfunnskostnader kan bidra til en høyere pris.', 'Knytter prisen til at de reelle kostnadene skal dekkes.']::text[], 5),
  ('markedsforing-og-ledelse-2:barekraftige-valg', 's07', 'En virksomhet omtaler et produkt som «grønt» uten dokumentasjon og framhever én liten forbedring, selv om resten av virksomheten er uendret. Forklar hvorfor dette kan være villedende, og nevn én mulig konsekvens.', 'Påstanden kan gi inntrykk av at produktet eller virksomheten er mer miljøvennlig enn den er, uten at dette er dokumentert. Virksomheten kan risikere bøter eller omdømmetap.', array['Forklarer at påstanden gir et overdrevet eller udokumentert inntrykk av miljøvennlighet.', 'Nevner bøter eller omdømmetap som en mulig konsekvens.']::text[], 6),
  ('markedsforing-og-ledelse-2:barekraftige-valg', 's08', 'En virksomhet vurderer å legge ned en forurensende produksjon, men nedleggingen kan koste arbeidsplasser. Forklar hvilke hensyn som står mot hverandre, og hvorfor valget må vurderes bredt.', 'Miljøhensyn står mot hensynet til arbeidsplasser og mennesker. Valget må vurderes bredt fordi bærekraft handler om flere hensyn som ikke alltid trekker i samme retning.', array['Forklarer konflikten mellom å redusere forurensning og å bevare arbeidsplasser.', 'Viser at bærekraftige valg krever at flere hensyn vurderes samlet.']::text[], 7);
